INSERT OR REPLACE INTO tv_seasons (id, tv_show_id, season_number, name, overview, poster_key, air_date, created_at, updated_at) VALUES ('004abc4c-ce77-4df9-8c97-9f56ea8b37ce', '67dd0904-9aba-49bc-b1b1-d047b59106ce', 5, 'Season 5', 'Kipper launches a rocket, tracks a hedgehog, and more on the trail of adventure.', '/qheY3fHcBY9jV2hImKWhLcArr3U.jpg', '2000-01-20', '2026-04-03T17:10:49Z', '2026-04-03T17:10:49Z');
