INSERT OR REPLACE INTO tv_seasons (id, tv_show_id, season_number, name, overview, poster_key, air_date, created_at, updated_at) VALUES ('01916834-25ec-43d6-9a1b-8ea5d9630adc', '57f0e548-f9d1-412a-8b9b-dc3960a09b22', 6, 'Season 6', '', '/7I9PQPfc7uEhiI63IKyNcpDZi6B.jpg', '2025-05-26', '2026-04-03T17:39:33Z', '2026-04-03T17:39:33Z');
INSERT OR REPLACE INTO tv_seasons (id, tv_show_id, season_number, name, overview, poster_key, air_date, created_at, updated_at) VALUES ('01b3a1e3-d0e8-4f2b-a56d-9d55669ab5f2', '90d490fa-c5ec-40a5-aac3-c70e29b32b31', 13, 'Season 13', 'Kody talks to each of his wives about Christine''s desire to move to Utah and gets a resounding no from each of them. When he tries to talk Christine out of it, she can''t even have a conversation with him and walks out in tears. A difference of opinions about COVID protocols creates tension between Janelle''s family and Kody and Robyn. Despite the fact that Meri has no romantic relationship with Kody, she seems to be doing better and managing the drama within the family well. As the family prepares to start building on their property, they are splitting apart at the seams over the upcoming holidays. Both Janelle and Christine''s families refuse to follow Kody''s COVID rules. Is the family not getting back together, even for the holidays? With tensions boiling over, more than one wife is questioning the future.', '/xcVhepEkt5I058UuhwKRgHnm1ZG.jpg', '2021-11-21', '2026-04-03T16:34:32Z', '2026-04-03T16:34:32Z');
