INSERT OR REPLACE INTO tv_seasons (id, tv_show_id, season_number, name, overview, poster_key, air_date, created_at, updated_at) VALUES ('02cdc012-16d2-4444-b010-b45ad42283b9', '5cc5cb2f-38cf-4a64-8a10-9007e89133ed', 1, 'Miniseries', 'Four Edwardian children find a strange egg in their newly-arrived Persian carpet. It hatches into a Phoenix bird that grants wishes and also transforms the rug into a magic carpet, which takes them on a series of adventures all over the world and at home.', NULL, '1997-11-16', '2026-04-03T17:18:35Z', '2026-04-03T17:18:35Z');
