INSERT OR REPLACE INTO tv_seasons (id, tv_show_id, season_number, name, overview, poster_key, air_date, created_at, updated_at) VALUES ('0987f081-b3b7-4e3c-abb7-795e56c279d5', '87af6181-d36d-4591-87c2-33400a5f013c', 4, 'Season 4', 'While an unexpected turn of events might force Frankie to reevaluate her career at the car dealership, Mike''s made it his mission to ensure that Axl somehow earns a sports scholarship to college next year. Meanwhile, Sue''s not only navigating high school, but wants to navigate Indiana roads by getting her driver''s license. It''s no wonder that youngest son Brick keeps his nose in a book!', '/7WaBgPSBtS53IS44BvhY4wvCQyo.jpg', '2012-09-26', '2026-04-03T15:40:29Z', '2026-04-03T15:40:29Z');
INSERT OR REPLACE INTO tv_seasons (id, tv_show_id, season_number, name, overview, poster_key, air_date, created_at, updated_at) VALUES ('09db9eae-334c-4283-929a-f00ecb3fd845', '5763807e-668f-42f4-9f90-716799017463', 51, '2008', '', NULL, NULL, '2026-04-03T17:22:07Z', '2026-04-03T17:22:07Z');
INSERT OR REPLACE INTO tv_seasons (id, tv_show_id, season_number, name, overview, poster_key, air_date, created_at, updated_at) VALUES ('0a9aba05-559f-4db4-a6ca-8ac35cc378d1', '1f54a881-cf7d-4cce-9bc7-38768c2cf36e', 6, 'Season 6', 'Following the shocking developments at the conclusion of season five, survivors from all parts of Westeros and Essos regroup to press forward, inexorably, towards their uncertain individual fates. Familiar faces will forge new alliances to bolster their strategic chances at survival, while new characters will emerge to challenge the balance of power in the east, west, north and south.', '/p1udLh0gfqyZFmXBGa393gk8go5.jpg', '2016-04-24', '2026-04-03T15:40:37Z', '2026-04-03T15:40:37Z');
INSERT OR REPLACE INTO tv_seasons (id, tv_show_id, season_number, name, overview, poster_key, air_date, created_at, updated_at) VALUES ('0ab4dfb2-58c9-4e52-b5bf-49bba0bfc597', '822343ab-b688-40b9-b089-d0b3ddcdb256', 1, 'Season 1', 'High school chemistry teacher Walter White''s life is suddenly transformed by a dire medical diagnosis. Street-savvy former student Jesse Pinkman "teaches" Walter a new trade.', '/1BP4xYv9ZG4ZVHkL7ocOziBbSYH.jpg', '2008-01-20', '2026-04-03T15:40:32Z', '2026-04-03T15:40:32Z');
