INSERT OR REPLACE INTO tv_seasons (id, tv_show_id, season_number, name, overview, poster_key, air_date, created_at, updated_at) VALUES ('0bbd380c-5cb8-46a6-8838-b5d60223c073', 'abeeff5a-ac6a-44e0-910b-8bc866b1556d', 1, 'Season 1', '', '/jORRYTyiKcs5esdw9idC674kiLt.jpg', '1976-09-05', '2026-04-03T17:35:24Z', '2026-04-03T17:35:24Z');
INSERT OR REPLACE INTO tv_seasons (id, tv_show_id, season_number, name, overview, poster_key, air_date, created_at, updated_at) VALUES ('0d2293dd-dfca-4591-8f9a-0fbe023f8d1c', '3f51cdd3-08df-42f8-806f-78d3958c3166', 1, 'Season 1', 'The witcher Geralt, a mutated monster hunter, struggles to find his place in a world in which people often prove more wicked than beasts.', '/5BvFJfi3qBxTFaLKsft202YeqGl.jpg', '2019-12-20', '2026-04-03T15:40:45Z', '2026-04-03T15:40:45Z');
INSERT OR REPLACE INTO tv_seasons (id, tv_show_id, season_number, name, overview, poster_key, air_date, created_at, updated_at) VALUES ('0d24c742-83f2-4f37-8a5d-0b09c7df6a7f', '3f51cdd3-08df-42f8-806f-78d3958c3166', 4, 'Season 4', 'After the Continent-altering events of Season Three, Geralt, Yennefer, and Ciri find themselves separated by a raging war and countless enemies. As their paths diverge, and their goals sharpen, they stumble on unexpected allies eager to join their journeys. And if they can accept these found families, they just might have a chance at reuniting for good...', '/d74mHAWr5Q73O7lINSME4YBDhhh.jpg', '2025-10-30', '2026-04-03T15:40:46Z', '2026-04-03T15:40:46Z');
INSERT OR REPLACE INTO tv_seasons (id, tv_show_id, season_number, name, overview, poster_key, air_date, created_at, updated_at) VALUES ('0e284f5d-f37d-404f-9424-2eb1947723c9', '5763807e-668f-42f4-9f90-716799017463', 30, '1993-1994', '', NULL, NULL, '2026-04-03T17:22:00Z', '2026-04-03T17:22:00Z');
