INSERT OR REPLACE INTO tv_seasons (id, tv_show_id, season_number, name, overview, poster_key, air_date, created_at, updated_at) VALUES ('0ebba123-871d-4d2b-a054-eb85d2ad9450', 'f2f13547-c984-48e2-9c9d-8c3eb9824b65', 1, 'Original Series', '', '/NCQdGCorybrM7YjaxXIA6CEovi.jpg', '1993-12-22', '2026-04-03T17:39:39Z', '2026-04-03T17:39:39Z');
INSERT OR REPLACE INTO tv_seasons (id, tv_show_id, season_number, name, overview, poster_key, air_date, created_at, updated_at) VALUES ('0f64bf9f-8d05-4f5b-9a57-5d0c44ac3f40', '90d490fa-c5ec-40a5-aac3-c70e29b32b31', 6, 'Season 6', 'Kody and the sister wives - Meri, Janelle, Christine and Robyn - are at a crossroads in their relationship. While the divorce from Kody was supposed to be just a document shuffle, it has become nothing like what the family thought it would be. So much has changed and the whole family struggles to figure out how to move forward.

In addition to the shifting family structure, the Browns begin their journey to legally adopt Robyn''s children from a previous marriage. Kody also takes his youngest daughters to the beach in an attempt to bond more with them, and Robyn announces her pregnancy to the family, kicking off the countdown to her due date.', '/c9oqzbx6luCjuYVIDGFzsD1EnKk.jpg', '2015-09-13', '2026-04-03T16:34:29Z', '2026-04-03T16:34:29Z');
