INSERT OR REPLACE INTO tv_seasons (id, tv_show_id, season_number, name, overview, poster_key, air_date, created_at, updated_at) VALUES ('1a8f02c5-f727-4ce3-9bb2-5946d236e47c', '17fdbe5f-70b0-4c44-bfea-a7543bb6eabb', 5, 'Stranger Things 5', 'The fall of 1987. Hawkins is scarred by rifts. Vecna has vanished and the government has placed the town under military quarantine, forcing Eleven back into hiding. To end this nightmare, they''ll need everyone together, one last time.', '/5i5Fg549J27knMvhI5NRM2FT3Gn.jpg', '2025-11-26', '2026-04-03T15:40:40Z', '2026-04-03T15:40:40Z');
