INSERT OR REPLACE INTO tv_seasons (id, tv_show_id, season_number, name, overview, poster_key, air_date, created_at, updated_at) VALUES ('21384b9c-43fa-410c-b89d-102e7cf9129b', '90d490fa-c5ec-40a5-aac3-c70e29b32b31', 4, 'Season 4', 'After living in separate rental homes for the past two years, the Browns are one step closer to fulfilling their dream of being together under one roof, moving into four adjacent houses in the same neighborhood. But now they have four large mortgages and a struggling start-up jewelry business. Meanwhile, Meri finally decides on whether or not to accept Robyn''s offer to be her surrogate, but will Kody agree with her decision? And as more kids prepare to leave the nest, Kody and the wives have a surprise in store that will rebuild the closeness the family once shared back in Utah.', '/spQ3LzMIVbZnRmNFJlgOLpjnOO6.jpg', '2013-07-21', '2026-04-03T16:34:28Z', '2026-04-03T16:34:28Z');
