INSERT OR REPLACE INTO tv_seasons (id, tv_show_id, season_number, name, overview, poster_key, air_date, created_at, updated_at) VALUES ('52f9c16b-a60f-4eb7-b991-5c3bf70877bf', '7f6201f9-072d-4130-8be5-bd20b8d34b0d', 1, 'Season 1', 'The inaugural season comprises eight episodes, each delving into the personal and professional lives of the cast members. The series provides an intimate look at their daily routines, family dynamics, and social interactions within the exclusive community. Notably, Kimberly Bryant made a single-season appearance, while the other women continued to feature in subsequent seasons.', '/b6Gues9XCGxwvbldXQbQ7Yyw5sX.jpg', '2006-03-21', '2026-04-03T16:35:29Z', '2026-04-03T16:35:29Z');
INSERT OR REPLACE INTO tv_seasons (id, tv_show_id, season_number, name, overview, poster_key, air_date, created_at, updated_at) VALUES ('53587a7e-cd93-44f0-ad79-5fe586dccb8e', '67dd0904-9aba-49bc-b1b1-d047b59106ce', 1, 'Season 1', 'Kipper is on the trail of adventure and magical capers with his faithful and valued friends.', '/3Tjm1b5oIgEdTtREmwXI6cvg2wV.jpg', '1997-09-05', '2026-04-03T17:10:48Z', '2026-04-03T17:10:48Z');
INSERT OR REPLACE INTO tv_seasons (id, tv_show_id, season_number, name, overview, poster_key, air_date, created_at, updated_at) VALUES ('537d4f44-99ae-4a27-92b0-d0b5aa19ea3c', '5763807e-668f-42f4-9f90-716799017463', 50, '2007', '', NULL, NULL, '2026-04-03T17:22:06Z', '2026-04-03T17:22:06Z');
INSERT OR REPLACE INTO tv_seasons (id, tv_show_id, season_number, name, overview, poster_key, air_date, created_at, updated_at) VALUES ('53f9624f-fcf8-4f77-82f6-d2eb3f5376ee', '90d490fa-c5ec-40a5-aac3-c70e29b32b31', 16, 'Season 16', 'This season, the family faces the devastating passing of Janelle and Kody''s son, Garrison Brown. Through the heartbreaking pain, the family navigates this incredible tragedy and comes together to mourn and celebrate his life.

There has been much change over the past few years, where all the Browns are facing new pathways forward. While three of Kody''s wives have left, his fourth wife Robyn remains legally married to him. Now that the Browns have left polygamy behind, Robyn and Kody face challenges together as a monogamous couple and how to adapt to a lifestyle they never planned on living.', '/xLoDj8zcaUYyPN01jkkaT4Do037.jpg', '2024-09-15', '2026-04-03T16:34:33Z', '2026-04-03T16:34:33Z');
INSERT OR REPLACE INTO tv_seasons (id, tv_show_id, season_number, name, overview, poster_key, air_date, created_at, updated_at) VALUES ('543ec6dc-c6c7-447c-b5a7-4484d9618391', '4363c674-ad55-4e79-99dc-101bee2108c9', 1, 'Season 1', '', '/tZbxjMbxrXHN8vWg0x43EVqZXVo.jpg', '2010-08-05', '2026-04-03T16:35:01Z', '2026-04-03T16:35:01Z');
INSERT OR REPLACE INTO tv_seasons (id, tv_show_id, season_number, name, overview, poster_key, air_date, created_at, updated_at) VALUES ('54900370-8988-46b8-b7aa-61d2b88d7056', 'eea5207a-afb0-4a84-9824-b6c77e32e7c5', 6, 'Season 6', '', '/1tQ2wVVKoma672CxE2kfl9oxHR8.jpg', '2025-09-16', '2026-04-03T16:35:46Z', '2026-04-03T16:35:46Z');
INSERT OR REPLACE INTO tv_seasons (id, tv_show_id, season_number, name, overview, poster_key, air_date, created_at, updated_at) VALUES ('54c29014-2dbd-49ff-a23f-cf4c546e0b3a', 'bcde3737-b03b-4a75-b676-ba4495ceb9d8', 6, 'Season 6', 'Season six sees the return of Aviva Drescher, Sonja Morgan, Carole Radziwill, Ramona Singer, and Heather Thompson, who are joined by model and businesswoman Kristen Taekman as they navigate their hectic lifestyles of jam-packed social calendars, careers, relationships, children and the hustle and bustle of city living. Also returning in a recurring role this season is Countess LuAnn de Lesseps.', '/egMC4TND81m6MUQEbdplmoeWLD8.jpg', '2014-03-11', '2026-04-03T16:35:23Z', '2026-04-03T16:35:23Z');
INSERT OR REPLACE INTO tv_seasons (id, tv_show_id, season_number, name, overview, poster_key, air_date, created_at, updated_at) VALUES ('54facb0b-db59-41fe-9d64-c7c7221a3c81', 'bcde3737-b03b-4a75-b676-ba4495ceb9d8', 11, 'Season 11', '', '/5FdH6iVVNvdoudQUHZCfwMJMTr2.jpg', '2019-03-06', '2026-04-03T16:35:25Z', '2026-04-03T16:35:25Z');
INSERT OR REPLACE INTO tv_seasons (id, tv_show_id, season_number, name, overview, poster_key, air_date, created_at, updated_at) VALUES ('55930d10-8ec2-4a20-8c94-52d9b5329bae', '1f54a881-cf7d-4cce-9bc7-38768c2cf36e', 5, 'Season 5', 'The War of the Five Kings, once thought to be drawing to a close, is instead entering a new and more chaotic phase. Westeros is on the brink of collapse, and many are seizing what they can while the realm implodes, like a corpse making a feast for crows.', '/7Q1Hy1AHxAzA2lsmzEMBvuWTX0x.jpg', '2015-04-12', '2026-04-03T15:40:37Z', '2026-04-03T15:40:37Z');
