INSERT OR REPLACE INTO tv_seasons (id, tv_show_id, season_number, name, overview, poster_key, air_date, created_at, updated_at) VALUES ('6c71887a-d6e3-41f1-aa7c-f482abc104d2', '1df66cf3-3a18-440f-8acd-9a7ef9c6e204', 3, 'The Silver Chair', 'Shipped off to a miserable school, Eustace finds companionship in Jill Pole. Running from bullies, the two hide in a garden shed that magically transports them into the magical world of Narnia, where they''re entrusted with a task by Aslan: to rescue the king''s stolen son, Prince Rilian. Together, with Puddleglum the Marshwiggle, Eustace and Jill must travel north across the mountains, dodge giants, and journey down into the earth itself to rescue Rilian from the mysterious evil that holds him bound there.', '/Ai2kAEB8VYDm1PZCaV4h3v626Og.jpg', '1990-11-18', '2026-04-03T17:17:41Z', '2026-04-03T17:17:41Z');
