INSERT OR REPLACE INTO tv_seasons (id, tv_show_id, season_number, name, overview, poster_key, air_date, created_at, updated_at) VALUES ('7eef937c-4483-42bd-bafe-263a7d4e4573', 'ac75c382-1246-42cd-95b8-7e8ae011ffb6', 3, 'Season 3', '', '/da5qfAWluvAtVRD61Q2NaVY4txN.jpg', '1996-09-14', '2026-04-03T17:37:48Z', '2026-04-03T17:37:48Z');
INSERT OR REPLACE INTO tv_seasons (id, tv_show_id, season_number, name, overview, poster_key, air_date, created_at, updated_at) VALUES ('7f5ae98b-4913-40c2-a542-54bc3f1ec0a4', '74e16096-af9f-436e-a57f-923e0f6239e1', 6, 'Season 6', 'It’s season six and Rick and Morty are back! Pick up where we left them, worse for wear and down on their luck. Will they manage to bounce back for more adventures? Or will they get swept up in an ocean of piss! Who knows?! Piss! Family! Intrigue! A bunch of dinosaurs! More piss! Another can’t miss season of your favorite show.', '/cvhNj9eoRBe5SxjCbQTkh05UP5K.jpg', '2022-09-04', '2026-04-03T15:40:43Z', '2026-04-03T15:40:43Z');
