INSERT OR REPLACE INTO tv_seasons (id, tv_show_id, season_number, name, overview, poster_key, air_date, created_at, updated_at) VALUES ('a8db07e5-fba3-49a9-bd12-947c111b39be', 'bcde3737-b03b-4a75-b676-ba4495ceb9d8', 8, 'Season 8', 'In season eight, the name of the game is change as the ladies face betrayal, crumbling marriages, new love and endless wild nights.', '/y7kuiKEKieC3wC667lXSK0907DB.jpg', '2016-04-06', '2026-04-03T16:35:24Z', '2026-04-03T16:35:24Z');
INSERT OR REPLACE INTO tv_seasons (id, tv_show_id, season_number, name, overview, poster_key, air_date, created_at, updated_at) VALUES ('a8f3a681-7abc-41e0-9988-9b8804d74611', '90d490fa-c5ec-40a5-aac3-c70e29b32b31', 3, 'Season 3', 'The twenty one episode season mainly dealt with the family''s inability to be a cohesive unit while living in four separate homes. Meri explains more about the infertility problems she has experienced, while Christine discloses more on her jealousy of Robyn. The season returned from hiatus on November 18, 2012, to the Brown family still discussing their options into moving their family onto one property, and invest in a cul-de-sac where they can build four homes. It is more evident this season that living in separate homes is tearing the family apart. Towards the end of the season, the family plans a three-day trip to Nauvoo, Illinois, the birthplace of American polygamy. In the last episode on December 30, 2012, the family also deals with the upcoming departure to college of the eldest Brown child, Logan.', '/zy3Hx5xODeOLZ1ahGQ8549osS14.jpg', '2012-05-13', '2026-04-03T16:34:28Z', '2026-04-03T16:34:28Z');
