INSERT OR REPLACE INTO tv_seasons (id, tv_show_id, season_number, name, overview, poster_key, air_date, created_at, updated_at) VALUES ('abeb8d07-5c86-4f6a-a110-b11cba2a4138', '5648cd2a-194d-4ab9-a2ae-b2f9743f463c', 3, 'Book Three: Fire', 'Aang wakes up from his battle with Azula to discover that Ba Sing Se has fallen and the world thinks he''s dead. So he and his friends set off undercover across the Fire Nation to find Fire Lord Ozai before the Day of Black Sun. Prince Zuko returns home as the triumphant son, but soon finds the honor he so greatly craved from his father is worthless. New alliances are formed and Team Avatar forges a new plan to stop the Fire Lord. But will they find him in time?', '/roPE4jaHawj1Dm6uIXJHuLDpkNy.jpg', '2007-09-21', '2026-04-03T17:40:48Z', '2026-04-03T17:40:48Z');
