INSERT OR REPLACE INTO tv_seasons (id, tv_show_id, season_number, name, overview, poster_key, air_date, created_at, updated_at) VALUES ('c7ffc8df-4671-47e3-a11b-606828bcb508', '822343ab-b688-40b9-b089-d0b3ddcdb256', 4, 'Season 4', 'Walt and Jesse must cope with the fallout of their previous actions, both personally and professionally. Tension mounts as Walt faces a true standoff with his employer, Gus, with neither side willing or able to back down. Walt must also adjust to a new relationship with Skyler, whom while still reconciling her relationship with Walt, is committed to properly laundering Walt’s money and ensuring her sister Marie and an ailing Hank are financially stable.', '/5ewrnKp4TboU4hTLT5cWO350mHj.jpg', '2011-07-17', '2026-04-03T15:40:33Z', '2026-04-03T15:40:33Z');
