INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('01450a15-7ad6-4636-b1a8-889159a7220d', 'd8ccf6d3-e37a-430a-b67d-7fbf269bf0be', 2, 'Vacation Crashers', 'Lisa and Meredith meet up to talk out their issues. Meredith plans a trip to Palm Springs for the women but snubs one of the ladies. Monica reveals a secret about her past to Heather and worries about leaving her kids for the first time. Whitney takes matters into her own hands with Angie for the trip. In Palm Springs, Lisa loses something valuable and sentimental.', '2023-09-12', 55, '/6vhGtaCgXTyNbCv2P6R7QovF9z6.jpg', '2026-04-03T16:35:45Z', '2026-04-03T16:35:45Z');
