INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('01677d51-42c4-4b25-bf5d-fc58c59eaefa', '33e647e7-a3e8-4c3a-93e6-74e08399a790', 11, 'Quivering Heap', 'Pete gets to suck Fiona''s neck in Dracula, and Gribbs is jealous. Locked in the school toilets by the gang,  Pete meets a ghost who has to scare someone or stay in the dunny forever. But he doesn''t have that touch!', '1992-06-12', 24, '/fAYjvi05NI7fdP0bsISoFziogVq.jpg', '2026-04-03T17:40:41Z', '2026-04-03T17:40:41Z');
