INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('0294683b-f4f8-4fdd-bc95-8d61aad3581c', '4b2a19e0-2fae-492e-bc31-f78e63d88ebc', 9, 'Cowboys and Cannons', 'Light a fuse with Pawn Stars when a 19th century sun dial cannon explodes into the shop. Will Rick blast out the big bucks or will the deal fizzle out? Next, a signed helmet from one of Hollywood''s biggest flops, Heaven''s Gate, gallops in. Will Rick cowboy up an offer or ride off into the sunset? Then, sterling silver baby figurines gleam their way into the shop. Will Rick take a shine to them or will the deal get tarnished? And later, a 1964 Beatles board game plays its way in. Will Corey score a fab win, or lose his turn?', '2016-09-07', 21, '/ix7ZbB8w9Eb8ZQNOgMISDZpbKQT.jpg', '2026-04-03T16:34:20Z', '2026-04-03T16:34:20Z');
