INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('02c80fd6-f1f9-4fd2-9dd8-141b1574e920', '80775c3d-fa41-46f6-96ec-efc2e14efdcf', 10, 'Pop of Crazy', 'Dorinda''s birthday dinner takes a sour turn when Bethenny and Heather have a screaming showdown, capping a conflict-packed Berkshire weekend. Also: Ramona hopes to connect with Avery; and drama surrounds Bethenny at Ramona''s party at her new sports bar.', '2015-06-09', 44, NULL, '2026-04-03T16:35:24Z', '2026-04-03T16:35:24Z');
