INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('0336c503-7b34-4717-bc9d-bca292bb8ce5', '5fa796b4-eaa3-4d89-a746-0a8b86cb8432', 5, 'Sunken Treasure', 'A hurricane of the coast of Florida in 1662 caused the Atocha, a Spanish galleon to sink. This book describes the many-years-long search for the treasure believed to be on it. Also contains The Atocha, The Titanic and book reviews for The Titanic: Lost... and Found, A Day Underwater and What''s in the Deep? An Underwater Adventure.', '1990-09-14', 30, NULL, '2026-04-03T17:36:17Z', '2026-04-03T17:36:17Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('033afcf1-f16b-48aa-9ed1-1670464b17bb', '937ee587-e2eb-46aa-9a69-3d6bab04398f', 4, 'The Paper Crane', 'LeVar provides insight on Japanese culture. Keye Luke reads the story of a kind restaurant owner who is thanked by a customer with a magical crane made from a napkin, whose dancing spectacle soon brings in the guests to make the failing business prosperous again.', '1987-06-25', 30, NULL, '2026-04-03T17:36:16Z', '2026-04-03T17:36:16Z');
