INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('03576469-267b-40a0-8b15-b24debef58dd', '0bbd380c-5cb8-46a6-8838-b5d60223c073', 24, 'Vincent Price', 'In honor of guest star Vincent Price, the show is filled with monsters, ghosts, bats, vampires and spooky situations. A three-headed monster auditions for the show: "We sing!" "No, we dance!" "No, we tell jokes!"', '1977-04-23', 26, '/wavAIJzV2hidngoeGdrLMH3SCqk.jpg', '2026-04-03T17:35:24Z', '2026-04-03T17:35:24Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('03588522-22d2-496e-b55b-4a3edf99a1cf', 'e4023da2-33d7-4a2b-a04a-ca449bd23935', 13, 'Valentine’s Day VI', 'Valentine''s Day aims its sights on the Heck kids when a nervous Brick finds out that his quirky girlfriend Cindy wants him to kiss her on the special day, Darrin asks Frankie and Mike to help out with an exciting scavenger hunt he''s putting together for Sue, and Axl begins to question his girlfriend Devin''s request that he not give her anything for what she considers to be a lame tradition.', '2015-02-11', 22, '/jmrvSetoohqJZAGavJDpXvhunyN.jpg', '2026-04-03T15:40:30Z', '2026-04-03T15:40:30Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('035d0e28-d561-46bd-b3df-25dbb49aeba0', 'd3e13496-e3c8-4903-83b4-5a31fedee232', 15, 'Bato of the Water Tribe', 'Aang feels neglected as Katara and Sokka reunite with Bato, an old friend of their father’s from the South Pole. They begin to reminisce on their times in the past while they wait for a message to arrive from their father. Aang believes Katara and Sokka will abandon him and go out to find their father should the message arrive. However, when the messenger gives Aang the message to give to Bato, Aang betrays his friends in a way Katara or Sokka could never imagine. However, when Zuko recruits a bounty hunter named June to track Aang down, his friendship is put to the test as he must deal with the fact that he betrayed his friends while defending himself from yet another fight.', '2005-10-07', 25, '/sBSdSLVgW6JxpYKhEQiWGbVl1Q3.jpg', '2026-04-03T17:40:47Z', '2026-04-03T17:40:47Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('0363c6b5-1b4b-4c7d-b129-ee83d646c4b3', '4892e2af-46c1-4b4e-ac81-eac161b5a347', 2, 'Episode 2', 'STOP PRESS -BLUE PETER INDOOR RIDING SCHOOL OPENED BY PRINCESS ANNE  That was the welcome news that greeted handicapped riders in Tyne and Wear this summer. The Indoor School was provided by some of the old wool and cotton donated by viewers to the Clothes Horse Race Appeal.  Today PETER reports on the Official Opening and talks to some of the disabled children who are now able to ride whatever the weather.', '1977-09-15', NULL, NULL, '2026-04-03T17:21:53Z', '2026-04-03T17:21:53Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('0366c91a-1cc5-45b1-b306-2998a593ba4a', '5144de59-e67f-4fcf-919b-7106989ab797', 17, 'Going By the Book', 'The kids want to play Sleeping Beauty, but as four of them don’t fit the description of the protagonists, they research other princes and princesses that reflect their individual heritages.', '1995-02-07', 29, NULL, '2026-04-03T17:12:21Z', '2026-04-03T17:12:21Z');
