INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('03dcdbb4-ac85-4b6c-99c4-340e62e47c90', '2e6ee129-b32e-4417-9500-56f1cc9bc434', 2, 'The Furry News', 'As LeVar discusses his favorite parts of a newspaper and interviews other people for different viewpoints, other functions of a newspaper staff are explored. Cartoonist Ray Billingsley, who draws Curtis, shows how he illustrates a comic, and a high school newspaper staff is profiled making a weekly publication.', '1993-10-12', 30, NULL, '2026-04-03T17:36:18Z', '2026-04-03T17:36:18Z');
