INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('05133c34-bb92-4824-b434-349b828ccb92', '1d39506b-06b8-4f93-9136-0208069bd7e4', 2, 'Dueling Labor Day Parties', 'While in the Hamptons, LuAnn and her children receive a surprise visit from erstwhile housekeeper Rosie. The arrival of Labor Day results in laborious drama when both Ramona and LuAnn throw separate parties, forcing the other wives to choose bashes. Meanwhile, Jason asks Bethenny a crucial question over dinner; and dramas play out between LuAnn and Mario.', '2010-03-11', 43, '/cT9gNNAXHCfAnvHNpgL7N49OoSJ.jpg', '2026-04-03T16:35:22Z', '2026-04-03T16:35:22Z');
