INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('05799e74-deba-46cd-8390-084cba657694', '913796e9-c0ce-44dd-98bc-f6f520cb2444', 2, 'Uncle Jed''s Barber Shop', 'LeVar visits his favorite barbershop for a trim, and reads the featured book while waiting his turn. Regina Taylor tells the story of how Uncle Jed, who had a dream of owning his own barbershop and kept saving up despite several financial setbacks, including the bank crash at the start of the Great Depression, finally achieved his goal at the age of 79.', '1995-10-09', 30, NULL, '2026-04-03T17:36:19Z', '2026-04-03T17:36:19Z');
