INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('059546e4-8eb6-4efd-bdb2-01291aa7a595', '95ca8b6f-ccbc-431a-9d95-9b23367bbfed', 3, 'Sutton''s Gotta Give', 'As the Tahoe getaway continues, Sutton and Crystal’s colorful disagreement comes to a head — only to go off the rails again when Sutton feels alienated from the group. Garcelle''s bold opinion of a Hilton family member shocks Kyle and Kathy. Dorit gets down and dirty during a rare night out on the town, while Lisa and Erika prank a prankster.', '2021-06-02', 43, '/d0LJnSSMwx85AYs4BdTZCwTwP4v.jpg', '2026-04-03T16:34:58Z', '2026-04-03T16:34:58Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('05963bdd-7037-4845-b302-a05e04d83db4', 'a8f3a681-7abc-41e0-9988-9b8804d74611', 8, 'No Place Like Home', 'Logan, Mariah, Madison, and Hunter head back to Utah to visit their family and friends, but more importantly, to visit the happy home they left behind. How will they feel about being back and will they have any resentment or regrets since leaving?', '2012-06-10', 21, NULL, '2026-04-03T16:34:28Z', '2026-04-03T16:34:28Z');
