INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('05a5aff1-2696-49a9-8696-a73cc9e8aaa5', 'e48599f8-66ff-4c0f-9274-65b9ae1cda9e', 19, 'Episode 19', 'Lesley joins ''Missus'' and meets her baby - the first dolphin ever to be born and bred in Britain.', '1976-11-15', NULL, NULL, '2026-04-03T17:21:53Z', '2026-04-03T17:21:53Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('05a652ff-d7d1-442b-9f72-d794c6c6c574', 'f30bbf81-8770-4e74-b68b-280e7c85b52f', 3, 'The Jacket', 'Jerry buys a real expensive new suede jacket with a colorful inner lining. George has a song from Les Miserables that he just can''t get out of his mind. Kramer is supposed pickup a magician friend''s doves, and needs someone to help him for two minutes; Elaine takes on the job. Kramer promises she''ll get "a lift" to the hotel where Jerry and George are meeting her and her father, Alton Benes, an author cut from Hemingway cloth. Jerry and George suffer while waiting with Elaine''s father. When it begins to snow, Jerry turns his new jacket inside out, to protect it, but Alton Benes doesn''t want to be seen on the street with him.', '1991-02-06', 23, '/sjEg8xWgVH1IgNXla1pnHNLM2hN.jpg', '2026-04-03T16:34:09Z', '2026-04-03T16:34:09Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('05aa16b9-4eeb-4728-8e68-8a333ac14f67', '21745b85-d269-42fa-b4dd-701b2da5c085', 82, 'Episode 82', 'with John Noakes, Peter Purves, Lesley Judd.  Today you can discover where the Blue Peter team is off to for the summer expedition.', '1974-07-01', NULL, NULL, '2026-04-03T17:21:52Z', '2026-04-03T17:21:52Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('05b52ca9-c906-425c-a6d3-6a13e10d60e6', '7bc54df3-f32a-454e-aef6-a9436c35d53b', 31, 'Episode 31', 'Mr. McFeely delivers Lady Elaine an invitation to a boomerang contest. To show her gratitude, Lady Elaine shows "Funny Fast Films" of Mr. McFeely and Chef Brockett.', '1970-03-16', NULL, NULL, '2026-04-03T17:35:39Z', '2026-04-03T17:35:39Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('05b61413-0661-403a-aa26-2742a1403235', '1d556682-d9bb-47e1-993f-0b648a8daacd', 83, 'Episode 1268', '', '1979-03-21', NULL, NULL, '2026-04-03T17:36:33Z', '2026-04-03T17:36:33Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('05c1a149-df54-4b0d-b930-331dfa11e771', 'e3a58098-e0da-42f7-9709-96dc0a4866c8', 9, 'Everybody''s Special', 'Rogers shows some of the Neighborhood of Make-Believe puppets and introduces the puppeteer who created Prince Tuesday, Lenny Meledandri. In the Neighborhood of Make-Believe, several people have to console Prince Tuesday, who has removed his robe.', '1995-09-12', NULL, NULL, '2026-04-03T17:35:47Z', '2026-04-03T17:35:47Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('05c672fd-463d-440a-a9af-89a376cc4cb5', '05fa5e18-78d2-41fe-ae30-0c242c7ffb6a', 11, 'Fit For Nothing', 'The Fire-fighters are training hard to appear in the Wales Fittest Fire-fighters calendar. It''s a competition to see who is the fittest.', '2003-04-14', 10, '/8xCFnJwAcbslKCpMehlA5XNjq4t.jpg', '2026-04-03T17:14:38Z', '2026-04-03T17:14:38Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('05cbb603-749d-4a4a-9b45-fa925b7814c3', 'e48599f8-66ff-4c0f-9274-65b9ae1cda9e', 75, 'Episode 75', 'Rags to Riches  Two years ago Blue Peter viewers collected 800 tons of old wool and cotton to provide badly needed help for handicapped children and adults. Now Rags, the trainee pony for disabled riders, is nearing the end of her special schooling and today John, Peter and Lesley over the past 16 months to review her progress, under the expert guidance of top trainer Tessa Martin Bird.', '1977-06-09', NULL, NULL, '2026-04-03T17:21:53Z', '2026-04-03T17:21:53Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('05cd649e-1fa1-4151-9879-5b04a3ebad16', '63f9bf6d-39b3-44f4-b885-a56807277a80', 17, 'The Muppets Go To the Movies', 'The Muppets Go to the Movies aired on ABC on May 20, 1981 to help promote The Great Muppet Caper. The special was taped between March 9 and 17, 1981. 

In this one-hour special, Lily Tomlin and Dudley Moore join the Muppets in a tribute to film classics. 

Kermit the Frog hosts the program, which begins with an all-cast rendition of "Hey a Movie!" from The Great Muppet Caper.', '1981-05-20', 26, NULL, '2026-04-03T17:35:23Z', '2026-04-03T17:35:23Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('05ddaf7f-fafb-4c0c-88c8-eca0043cc67e', 'e3a58098-e0da-42f7-9709-96dc0a4866c8', 5, 'Fast and Slow', 'Rogers operates a toy crane in the sandbox. In the Neighborhood of Make-Believe, a much larger crane finally catches the Trolley and lifts it up, so the neighbors can figure out how it can slow down.', '1995-09-26', NULL, NULL, '2026-04-03T17:35:47Z', '2026-04-03T17:35:47Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('05e6c362-2886-452c-99fc-9eb09ef45a2d', 'c9adc698-be92-4dd7-94ad-d8f6759361ca', 13, 'Welcome New Friends Pt 3', 'Rogers hears a harmonica band at Negri''s Music Shop. In the Neighborhood of Make-Believe, Donkey Hodie realizes that Malcolm Apricot Dinko cannot help much with harvesting the vegetables.', '1973-03-07', NULL, NULL, '2026-04-03T17:35:40Z', '2026-04-03T17:35:40Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('05e7dbf7-153b-4025-b002-195042d058ff', '6c1ec19f-74df-4f35-9a61-17b98175d826', 12, 'Roman Rumors', 'After rumors about Denise begin to swirl, Lisa attempts to save the group''s Roman holiday from turning into a disaster; when Teddi questions Denise about talking behind their backs, the confrontation leads to shocking revelations.', '2020-07-29', 43, '/yFO3iPVQHxGI4nMVFhuAO6hwXcx.jpg', '2026-04-03T16:34:58Z', '2026-04-03T16:34:58Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('05f6dbb0-ebb4-49a7-8a73-6fe1c6178a09', 'e1ef357b-4edf-412a-a785-7060c0e33bd2', 7, 'Madeline''s Detective School', 'The girls want to get Miss Clavel a birthday present.', '1995-10-21', 30, NULL, '2026-04-03T16:34:02Z', '2026-04-03T16:34:02Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('05f77118-f3e7-4fa0-a9a7-151c63d0182a', '9193e795-da7c-40ec-b68f-f63aa7d5174f', 270, 'From Imagination to Reality: Inside the Art Department - Part 1', 'Part 1 of an extensive featurette detailing the astonishing work of Production Designer Deborah Riley and her art department, dissecting the process behind the creation of season 7''s incredible new sets, including Dragonstone, Casterly Rock, Highgarden, the Dragon Pit, and more.', '2017-12-12', 25, '/xT8oo8EC2tuOxktv4WOZ50FiR1v.jpg', '2026-04-03T15:40:35Z', '2026-04-03T15:40:35Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('05fa2f99-7062-496c-a808-6d7a81c3353d', '9193e795-da7c-40ec-b68f-f63aa7d5174f', 2, '15-Minute Preview', 'An approximately 15-minute preview of the first episode of Game of Thrones.', '2011-04-03', 15, '/7LUPfB5mrNfplDFfpZIjFL5J9fI.jpg', '2026-04-03T15:40:35Z', '2026-04-03T15:40:35Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('05fcef0f-ecf1-4434-ae51-245f07ff5b65', 'f21ca545-466c-448c-ada5-b8acc8b856dc', 6, 'The Time of Day', 'Bernard is staying with Grandad during the school holiday, but Grandad accidentally hurts his foot. Fortunately, plenty of people have time for him and Bernard.', '1999-10-29', 15, NULL, '2026-04-03T17:20:05Z', '2026-04-03T17:20:05Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('05fe07b3-b03a-4c33-99e4-81c279211191', '34674c90-410e-427c-be4d-2a6f6f865a80', 12, 'Like a Rock', 'Take a load off with the Pawn Stars when a 1955 Chevy Pickup rolls by the shop. A rare "first edition" model, will the guys offer a truck full of cash for this sweet ride, or will they haul a* out of there? Then, a guy pops in with a Smith and Wesson "top break" revolver. Favored by Police Departments in the late 1800''s, can Rick lay down the law and make a deal, or is he simply outgunned? And later, Rick and the Old Man are presented with a 1950''s admiral''s telephone from a U.S. Navy ship. Complete with a line for ordering nuclear strikes, will they navigate through this deal unscathed, or will the Old Man go down with the ship?', '2012-06-11', 21, NULL, '2026-04-03T16:34:17Z', '2026-04-03T16:34:17Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('05fec8a8-fa38-483a-8f97-d5059534fc12', 'f21ca545-466c-448c-ada5-b8acc8b856dc', 9, 'Visiting Time', 'Bernard''s demanding cousin Lucy is staying with him, and looking after her takes all the time the watch can give. However, Lucy soon changes her ways when Bernard does a particularly good deed for her.', '1999-11-19', 15, NULL, '2026-04-03T17:20:05Z', '2026-04-03T17:20:05Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('0604c6df-6b85-4504-8e8e-5ebd4f55ac4a', '0ebba123-871d-4d2b-a054-eb85d2ad9450', 117, 'Bob Lends a Helping Hand', 'not a part of this series; shouldn''t be here', NULL, 30, '/lNp4Ud7vQgHFbhp2S9AiVE9TDgP.jpg', '2026-04-03T17:39:39Z', '2026-04-03T17:39:39Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('06053ecb-88e6-47cd-a01e-248ebc823748', '204d86fb-d99c-4fd1-8dcd-9c1bcfd3c33f', 36, 'Hands Together', 'On Dragontines'' Day, the friends participate in a special dance recital to the song "Los Pollitos", but Ord can''t seem to get the moves right.', '2001-09-12', NULL, NULL, '2026-04-03T15:26:04Z', '2026-04-03T15:26:04Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('06067fb7-2409-46e1-9759-bb026bc8a935', 'e2aa3158-68e5-494f-951a-498ca0518dbb', 16, 'The Snapshot', 'Shaun is accidentally cut out of the Farmer''s family photo.', '2012-12-03', 7, '/yCtdqCdjtjw9C0BVLDhis5M62hn.jpg', '2026-04-03T17:39:32Z', '2026-04-03T17:39:32Z');
