INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('0608f29d-3024-46f1-961b-2398e2a725bd', '46d7a706-c7a8-4ebe-b96f-387c66e8bb8b', 122, 'Episode 1567', '', '1981-05-12', NULL, NULL, '2026-04-03T17:36:34Z', '2026-04-03T17:36:34Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('060c3f26-7b64-42f6-968d-cbb48ff17c90', '9c5608b2-5111-48bc-a907-7f93472c1e03', 5, 'Me Am What Me Am', 'Cookie Monster becomes known as the Veggie Monster after he eats several carrots.', '2012-09-28', 58, '/52zCbUTHsSLpI83kewmcYi1ucxT.jpg', '2026-04-03T17:36:47Z', '2026-04-03T17:36:47Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('060f2c8e-60ca-4a69-89d4-e5cfb21c8676', '7ccd5605-fe0b-4e00-ae7f-3e3daa252f8b', 11, 'Nothing Is as It Seems', 'Now that Tamra Barney''s marriage is feeling more stable, she decides to get Simon’s name tattooed on her ring finger. Simon is surprised when Tamra reveals the tattoo during a Harley ride to Balboa Island. Simon comments “that’s the first unselfish thing you’ve done in a long time.”

Vicki Gunvalson and her husband, Donn, weather a date night filled with typical Vicki mishaps including a bee in Donn’s drink and spilled red wine on Vicki’s top. However, it’s Donn’s romantic surprise that trumps every distraction and leaves Vicki completely overwhelmed.  

Lynne Curtin calls Alexis Bellino to apologize for her recent behavior at Alexis'' cooking party.  Lynne invites Alexis to a housewarming party she and her husband, Frank, are throwing in their new Laguna Beach home. 

After the debacle at Alexis’ cooking party, Gretchen Rossi and her boyfriend, Slade, discuss the state of her friendship with Lynne and whether or not they should attend the Curtin''s housewarming party. Gretchen decides to stand by her friend, and Slade reluctantly agrees.

The Curtins’ housewarming starts off on a good note, but that doesn’t last too long when a heated argument breaks out between Simon and Vicki. Tamra is once again stuck in the middle of a crazy triangle between her husband and best friend.

The next morning after the party, the Curtin''s are delivered devastating news in the form of an eviction notice.', '2010-02-04', 44, '/og5Y0XZd7X91tFToNnO8mIngekY.jpg', '2026-04-03T16:35:31Z', '2026-04-03T16:35:31Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('06118705-7a19-4117-98fb-76cbfbfb8ce9', 'f4c40307-9b5e-4263-a4e0-dfa138131e7f', 5, '123 Count With Me', 'Ernie sings a series of songs from the hotel', NULL, NULL, NULL, '2026-04-03T17:36:27Z', '2026-04-03T17:36:27Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('061701e7-69f7-4134-a36c-aca1e2f8cf6f', '196e5a10-ac25-4d58-8416-575d3a71fcef', 6, 'You''re a Good Man, Chumlee Russell', 'When a seller brings in a WWF prototype figurine, Chum looks to a higher authority to bless the deal. Will the Pawn Star be ready to rumble or will the seller have him in a chokehold?', '2024-08-21', 42, '/fu257P2CBmJWhPhfrsxs9KIGW43.jpg', '2026-04-03T16:34:24Z', '2026-04-03T16:34:24Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('061d1b1c-c0bb-45ff-8804-3ac00d6bfa9e', '5d57283d-079c-4f66-93c8-33a2feeada89', 10, 'Sleepless in Orson', 'Frankie and Mike start to worry when Brick begins developing irrational fears. Sue is conflicted about Derrick Glossner''s behavior. Axl and Sean shut down Darrin''s attempt to start a Boss Co spinoff.', '2014-01-08', 22, '/JvzTXufhYKPnAuYmxZCvpx1Iyo.jpg', '2026-04-03T15:40:30Z', '2026-04-03T15:40:30Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('061d26be-7824-4612-87fe-d73e6c4bcd8a', 'e40e6b63-9f84-449f-8e88-53209b0906c8', 10, 'Triangle Lover of the Day', 'Telly stares in awe at the Triangle Triple Crown, which will be worn for three weeks by the "Triangle Lover of the Day" at today''s Triangle Lovers'' Club meeting. He loves triangles more than anyone else, so he is sure that he will get crowned, and he invites Baby Bear to the special occasion. Baby Bear is not sure he will fit in with the other Triangle Lovers, since he doesn''t call himself one, but Telly reassures him that he''ll do fine.', '2007-08-31', NULL, '/d0BugA2RK1fL9ZIxKsqX4FYue8H.jpg', '2026-04-03T17:36:45Z', '2026-04-03T17:36:45Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('061e4f71-4e45-4d36-9ebd-b9bd03ecb1a0', '1d713ca6-4e17-4f84-949c-8cfd98514127', 12, 'Break Room Battle', 'Get the show on the road with the Pawn Stars when an antique circus calliope whistles into the shop. Will Rick become the Ringmaster of this musical relic, or is the seller just clowning around? Then, Rick rallies for a letter signed by JFK about the 1963 March on Washington. Will his dream of taking it home come true or will it find freedom somewhere else? And later, when Rick hangs a unique painting in the break room, it offends the guys. Will they force Rick to redecorate or will he win this artistic showdown?', '2014-08-14', 21, '/ohAs0F7EBdl9Xza35f8wt3PaCzh.jpg', '2026-04-03T16:34:19Z', '2026-04-03T16:34:19Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('061e7c17-90b4-4cd6-a893-b576e0b8eec2', '42253cb1-e961-4018-8dd9-8a69e6f70873', 11, 'Episode 2236', '', NULL, NULL, NULL, '2026-04-03T17:36:37Z', '2026-04-03T17:36:37Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('06213827-0867-4b00-9627-b3713b8e30f7', 'e789c40e-cfef-4f92-a6b8-a509f04f161e', 3, 'Kids'' Favorites', '', '2020-05-31', 64, '/7GmAJVN4EruDWUGpaM5GtSvCRtJ.jpg', '2026-04-03T15:26:05Z', '2026-04-03T15:26:05Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('0623c6fd-bf27-4ab2-9e54-cfbd09219a26', '51f03551-ba41-409d-85f4-e51bddfdf82e', 2, 'Hamptons Retreat... But No Surrender', 'Jill offers support to Bethenny, who sheds light on her romantic life. Meanwhile, Jill snoops for information about new housewife Kelly Killoren Bensimon, an act that creates tension with Ramona. In the Hamptons, Alex and Simon shop until they drop. And Jill''s parents pay a visit from Florida.', '2009-02-24', 60, '/xtjEEPvptCxQ4yXeIqdg9mFBYNF.jpg', '2026-04-03T16:35:22Z', '2026-04-03T16:35:22Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('0629abd7-65f0-4088-b1c1-981ef4ca21b0', '4d2cac0f-38fd-438b-8afa-acf43952e535', 94, 'Episode 94', 'A magazine programme for younger viewers with Christopher Trace and Leila Williams.  Including:  Life in the Royal Air Force: 3: Fighter Controller.  Introduced by Pilot Officer Pamela Rich. Film provided by the Royal Air Force and Animal Friends: 1: The Chimpanzee with Kenneth Exall.', '1960-08-05', NULL, NULL, '2026-04-03T17:21:47Z', '2026-04-03T17:21:47Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('0629ccb8-6d10-451e-9061-7fa774ab460a', '05c0e384-194c-4417-9f62-803eb615e409', 14, 'A visit with a chimp', 'Title number 0014. Opens with Mister Rogers arriving with an easel, supplies, and a record. Mister Rogers plays the 4th movement of Brahm''s Symphony No 1 and improvises on paper how music in a song makes him feel. Mr. McFeely treats Mister Rogers to a visit with Honey, a chimpanzee from the zoo. Professor Joseph Fitzpatrick is introduced to the Neighborhood of Make-Believe and he discusses Seurat.', '1968-03-07', 29, NULL, '2026-04-03T17:35:38Z', '2026-04-03T17:35:38Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('062ec4ec-c646-4d0a-b12b-0021f9e4c8cb', '4d2cac0f-38fd-438b-8afa-acf43952e535', 329, 'Episode 329', 'with Christopher Trace and Valerie Singleton.', '1965-01-21', NULL, NULL, '2026-04-03T17:21:47Z', '2026-04-03T17:21:47Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('062ed56a-6dcc-44bf-8b89-0b26b1ab511e', '05c0e384-194c-4417-9f62-803eb615e409', 28, 'Things that fit into other things', 'Title number 0028. Opens with Mister Rogers arriving with nesting boxes. At the television house, someone sends a rather unusual box. After he locks his pillow in a safe, Edgar Cooke expresses his different feelings. Lady Elaine Fairchilde finds her special toy, which is a boomerang.', '1968-03-27', 28, NULL, '2026-04-03T17:35:38Z', '2026-04-03T17:35:38Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('062f0053-27db-4426-b8c8-4f2d212b129b', '69b3befe-579a-43ad-a7d6-ec30ffe3adf7', 57, 'Episode 1112', '', NULL, NULL, NULL, '2026-04-03T17:36:32Z', '2026-04-03T17:36:32Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('06321157-c996-4040-a1c3-5bd7da6cd66a', 'f15647d3-c8bf-4e37-a6bc-589853787f3b', 8, 'Take Me Out of the Ball Game', 'Nick is on a baseball team, the Braves, coached by his father. It is important to them to win the game against their biggest rival, the Dodgers. And they think it is in the bag this year because of Thurman Miller, the teams biggest and best player.', '1989-07-23', 30, '/8LB26UPoODvZkFnPE6kuDw2oZFd.jpg', '2026-04-03T17:40:08Z', '2026-04-03T17:40:08Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('06363313-9418-4f0e-8224-a56250673043', 'd01919fb-98e0-42bf-b9d9-1cecf912f6e1', 3, 'The World''s Longest Hide and Seek Game (3788)', '', '1998-11-18', NULL, NULL, '2026-04-03T17:36:42Z', '2026-04-03T17:36:42Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('06370295-66ff-4e8a-a996-f11d76e7b116', '69b3befe-579a-43ad-a7d6-ec30ffe3adf7', 61, 'Episode 1116', '', NULL, NULL, NULL, '2026-04-03T17:36:32Z', '2026-04-03T17:36:32Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('063bdc5a-52ba-4eaa-b19b-242fdbdcd40d', '05c0e384-194c-4417-9f62-803eb615e409', 12, 'A visit with a toucan, a mime and a French horn', 'Title number 0012. Opens with Mister Rogers arriving with a toucan in a cage under a blanket. Jewel Walker visits the television house, where he transforms into Mime Walker. He heads to Make-Believe, where he helps X learn arithmetic with a musician who is playing a French horn for X.', '1968-03-05', 29, NULL, '2026-04-03T17:35:38Z', '2026-04-03T17:35:38Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('063caea5-5542-4d36-bb0d-e8712b1c8388', '9310a288-5af0-4746-a8d7-d7635ffb6beb', 1, 'Conflict', 'Mister Rogers arrives with a wooden puzzle where specific shapes must be matched to their corresponding holes. After playing with the puzzle for a moment, Mister Rogers sings You''ve Got to Do It.

Mr. McFeely stops by with a coin bank before he and Mister Rogers visit Negri''s Music Shop where a collection of toy banks is on display.

In the Neighborhood of Make-Believe, King Friday plans to purchase a record player for the Neighborhood school but he becomes distracted when a curious delivery is made to Corney''s factory.', '1983-11-07', NULL, NULL, '2026-04-03T17:35:43Z', '2026-04-03T17:35:43Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('063f2f00-defd-44d4-94a3-31877299a007', '8e5ed8a4-08e5-4006-9f36-c68c91ddfee4', 24, 'Episode 773', '', NULL, NULL, NULL, '2026-04-03T17:36:40Z', '2026-04-03T17:36:40Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('06412ac7-38de-4aef-83aa-201dceb71f81', 'bf0f7445-f58f-467f-a81b-fcc2bf6bca21', 12, 'The Doozer Contest', 'Flange and Modem Doozer get involved in a building competition (something the Doozers haven''t had for many years).', '1984-03-19', 24, '/98Ydf8TxODNyOKqMn8MRKUXLtPZ.jpg', '2026-04-03T17:35:00Z', '2026-04-03T17:35:00Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('06497f36-8d7b-46d2-a10e-0e6df8d3b479', 'bf3ffafd-7d45-4f2c-9f1b-28001bd082db', 6, 'Episode 6', 'Expedition - Thailand  John, Peter and Lesley visit a unique jungle school. Classes start at dawn with ''picking up small things’ and all the pupils are elephants.', '1974-09-26', NULL, NULL, '2026-04-03T17:21:52Z', '2026-04-03T17:21:52Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('064ad29d-0f48-4aec-90d8-7725b79cf177', '53587a7e-cd93-44f0-ad79-5fe586dccb8e', 4, 'Nothing Ever Happens', 'It''s a boring day, so Kipper complains that nothing ever really happens around his house. The tables are turned after a trip into the attic reveals magic just out of sight.', '1997-09-26', 9, '/iK2AuG98VJw4PCyfjZtftms2wzK.jpg', '2026-04-03T17:10:48Z', '2026-04-03T17:10:48Z');
