INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('06651999-366f-4043-8123-690cef728254', 'c6d5cf79-f2b0-40af-ad12-91aa4f1b1d21', 4, 'Blast from the Past', 'A customer walks in with a ''Tommy Boy'' poster signed by Chris Farley. Later, Rick and Corey check out a hand cannon from the 1600s.', '2022-05-14', 42, '/e81rofDHtrUdQqtIEmZfzeDI0Pq.jpg', '2026-04-03T16:34:23Z', '2026-04-03T16:34:23Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('0668dec8-9a25-4073-93cf-229226a15b43', '4da606e7-9d23-4682-8bd5-f535e1da706f', 5, 'Franklin the Spy', 'Franklin and Bear play secret agents and uses a hidden tape recorder on their friends.  But the recorder stopped taping just when the secret was about to be revealed and Franklin & Bear takes it one step to far.', '1998-09-21', 12, NULL, '2026-04-03T17:40:15Z', '2026-04-03T17:40:15Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('066cc9f6-4026-4f07-bedb-bd4f4ec28b00', '40700e8a-1dce-4895-bede-522a13a8bcad', 23, 'Ants and Eaters', 'When an anteater shows up, Zoboo worries that it will eat a colony of ants living in Animal Junction. He tries to broker a peace agreement between the creatures. Zoboo learns that even though anteaters need ants to survive, ants have many ways of protecting themselves from anteaters. Predation is part of life in the creature world and every creature has what she needs to survive.', '2001-05-25', 27, NULL, '2026-04-03T17:10:55Z', '2026-04-03T17:10:55Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('0675b5ce-4514-4566-b737-7f943db8a948', 'd920ebae-f00a-4e25-abfe-40492c74ded6', 7, 'May the Pawn Be With You', 'Rick flies across the pond to look at an epic Star Wars collection, including an iconic prop from the movie. Will the force be on his side, or will he leave solo? Meanwhile, a seller phones home with everyone’s favorite Ewok. Will Chum pick up the call or let it ring through? Finally, the Gold & Silver Pawn Shop gets a new employee. Can he work with Corey to make a deal on a Planters jar, or will they go nuts?', '2019-12-23', 42, '/cQY6F9GoVTnp5TSYrRiUrHmSVif.jpg', '2026-04-03T16:34:22Z', '2026-04-03T16:34:22Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('0675daf2-b1fc-4185-afe2-b93cd3795a3b', 'e48599f8-66ff-4c0f-9274-65b9ae1cda9e', 65, 'Episode 65', 'John visits Zeebrugge and reports on one of the most dangerous and daring exploits of the Great War.', '1977-05-02', NULL, NULL, '2026-04-03T17:21:53Z', '2026-04-03T17:21:53Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('067a92df-b9e5-4e56-b37f-0eff8d33ebd3', 'c21dbd22-5e2e-4414-bb67-750399aaf6f0', 14, 'Smells Like Pawn Spirit', 'The Pawn Stars see their spirits soar when a guy brings in a Charles Lindbergh doll from the 1920s. Will the appeal of this rare toy fly over Rick''s head, or will he take the pilot''s seat and make a deal? Then, the shop becomes a real freak show when a guy brings in an antique poster advertising a sword swallowing act. Will Rick cough up the cash for this piece of show biz history, or will the asking price be too hard to swallow? And later, a guy comes in with a harmonica that once belonged to Aerosmith front man Steven Tyler. Played by Tyler, can they make a deal with some "Sweet Emotion," or will they tell the customer to "Walk This Way" right out of the shop?', '2012-01-09', 21, NULL, '2026-04-03T16:34:17Z', '2026-04-03T16:34:17Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('067a9c27-5262-41ba-99c0-5918fbe9999c', '6b5caa66-f66f-4ed1-817f-a00bad08790e', 1, 'Thicker Than Water', 'The lives of five affluent housewives - Teresa, Jacqueline, Caroline, Dina and Danielle - in New Jersey reveals a surprising twist: three of the housewives are related. Meanwhile, Caroline, who owns two businesses, prepares for her son''s graduation party while mum-of-three Teresa plots her daughter Tia''s road to stardom after watching her dancing.', '2009-05-12', 43, '/xTJgpKLbvNbi3l7AlYaQmZUOOWl.jpg', '2026-04-03T16:35:14Z', '2026-04-03T16:35:14Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('0683ec1b-8974-4399-9a6a-7232d15c42cf', 'fb4ecc73-cb92-4c5c-821f-92179058b37b', 17, 'Episode 3672', '', '1997-12-09', NULL, NULL, '2026-04-03T17:36:41Z', '2026-04-03T17:36:41Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('068746ce-208a-4db1-8ff3-48829fc89676', 'd1863f2f-02ec-40ce-af64-db03fbe518a7', 5, 'Funny Farm', 'Elmo, Abby, and Alan help Grover think like a farm animal so he can throw the perfect party for farm animals. Also featuring Super Grover 2.0 (S.T.E.M.), and Elmo''s world-farm. Brought to you by the letter F and the number 3.', '2016-02-06', NULL, '/s5eUfkJ0kCYD1I6YY494fnQhUjm.jpg', '2026-04-03T17:36:48Z', '2026-04-03T17:36:48Z');
