INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('06adf25e-5c65-43e6-907d-280fd85d2028', '3af7ea64-fa13-4097-b8e4-40af07083054', 3, 'Making a Pizza [1328]', 'Rogers sees how pizza is made by observing two guests at Brockett''s Bakery. In the Neighborhood of Make-Believe, Miss Paulifficate''s pizza dough, thrown in the air, lands with an OCS lesson attached.', '1974-02-20', 28, NULL, '2026-04-03T17:35:40Z', '2026-04-03T17:35:40Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('06b08737-9c49-4473-89d0-afa399f1d1f3', '5ba20443-d99f-4820-81f6-6832d3f2bc4f', 13, 'Amphibians', 'Frogs, toads, salamanders, newts, and caecilians (worm-like animals that have backbones) are all amphibians, animals that spend part of their lives in water and part on land. Amphibians are slimy. Amphibians are cold-blooded that means their body temperature changes with the temperature outside. And as amphibians grow up, they go through metamorphosis.', '1996-01-30', 26, '/sX5LrSgbtWhiYoxPd8BOYpXAP2T.jpg', '2026-04-03T17:37:21Z', '2026-04-03T17:37:21Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('06b99459-2897-4c52-89e3-62a21c839be2', 'f9a8d8b3-d72e-437e-a9d5-7477f6d64df8', 2, 'Sesame Street Super Heroes', 'Elmo, Abby, and Rosita are playing superheroes! When Elmo and Abby suggest Rosita play Super Carga, who can turn on superpowers with a Spanish catchphrase, she shares that speaking Spanish isn’t the only thing that makes her special.', '2022-11-10', 26, '/3dR0RoeAO8tpp6IZAjhDI8VYhZq.jpg', '2026-04-03T17:36:51Z', '2026-04-03T17:36:51Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('06bc2fb1-3db5-431a-baef-9a6bde20a8ac', 'e606692a-47b7-411e-b54b-7c6bf61a67b7', 5, 'The Golden Meaty Awards', '', '2005-05-16', 30, '/gq8Wstr7Rw3CuVHHy30obuUvfEl.jpg', '2026-04-03T17:12:29Z', '2026-04-03T17:12:29Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('06bc4292-db35-4c61-b6b4-e83017487cfa', '78a02d50-e3dc-4549-844a-3cf357a32ef4', 9, 'Char-Lotta Drama', 'Kenya is invited to host Peter''s grand opening of Club One in Charlotte, but Cynthia is disappointed to discover she was not invited to join the celebration. Meanwhile, Kandi feels betrayed by a former employee as she gears up for her Bedroom Kandi convention. Shereé prepares to drop a fiery tell-all novel based on her life, while Porsha temporarily moves back in with her mom until she can find her dream home. Phaedra gets a visit from an unexpected guest and Peter''s highly anticipated grand opening gets derailed by a few surprise visitors.', '2017-01-08', 43, '/2C2FOH3M5xg2Xo4j6d7KMTJ649D.jpg', '2026-04-03T16:34:47Z', '2026-04-03T16:34:47Z');
