INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('06d5db12-a691-4bba-8f6e-965353523dac', '42e591e2-2a88-4434-ae9f-3d4b1d685613', 3, 'One Way Ticket', 'Rock and Roll all night with the Pawn Stars when a seller brings in a gold record signed by the band KISS. Can this rare piece of rock history convince the guys to join the KISS Army? Then, a Confederate pinfire revolver marches into the shop. Known for its sensitive firing mechanism, will negotiations blow up in Rick''s face? And later, when Corey pranks Chumlee with a fake lottery scratcher, is there any way this won''t end badly.', '2013-06-06', 21, NULL, '2026-04-03T16:34:18Z', '2026-04-03T16:34:18Z');
