INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('071d1e52-a4ac-4e99-ba26-cc663dcf2d87', '110e3467-3698-4e19-a35b-f6ebbaeb4d6b', 7, 'Grimm Party', 'Although not an actual Faerie Tale, this was very fun. It was a party with all the actors and actresses that made a contribution of their talents to lovely Shelley Duvall''s Faerie Tale Theatre. They talk about their experiences as some of the most beloved Faerie Tale characters. Jean Stapleton also talks about how she was in more episodes of Faerie Tale Theatre more than anybody else besides Shelley Duvall herself. Stapleton appeared as the fairy godmother in Cinderella and the Giant''s Wife in Jack and the Beanstalk. Unfortunately, this exclusive party was never released on video, but only time can tell...', '1985-07-17', 51, NULL, '2026-04-03T17:38:41Z', '2026-04-03T17:38:41Z');
