INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('0727831c-af4a-4493-ba19-5318b7b85b15', 'e1063f87-66c2-4e2d-a913-53362941aa19', 68, 'Episode 343', 'Kids are busy drawing with crayons outdoors. When a stiff breeze begins to blow the papers about, Tom suggests that the kids come into his store to play. Once inside, the kids decide to play catch. Tom suggests that the store isn''t the best place to play catch. The kids agree and go outside. Tom observes that there are some things that it''s better to do inside and some things it''s better to do outside.', '1972-02-09', NULL, NULL, '2026-04-03T17:36:29Z', '2026-04-03T17:36:29Z');
