INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('0735465f-c7bf-4a78-98f0-701f47bd8ec3', 'b86d15ea-4253-41a5-9f14-4a254ec601e0', 3, 'It''s My Party and I''ll Fight If I Want To', 'Teresa''s father goes to the ICU just as the family gears up for a birthday party. Elsewhere, tension grows between Kathy and Teresa; Caroline returns to an unkempt mansion; and a white lie infuriates Teresa.', '2013-06-16', 43, '/6HF8bLyLFMuLyLZNnvIGV4LxUDV.jpg', '2026-04-03T16:35:16Z', '2026-04-03T16:35:16Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('07368b1f-18a5-4bdd-84cd-d7a1e1f2b4a5', 'f29f456f-8e38-49af-8808-7943977100ec', 8, 'That''s My Grandma!', 'When Grandma Thora becomes the most popular babysitter in Elwood City, D.W. becomes upset.', '2016-10-13', 13, NULL, '2026-04-03T17:38:02Z', '2026-04-03T17:38:02Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('073a92b9-5630-46ef-a609-ddf8ed2606d7', 'c373abed-50ef-417e-9f34-4e9050611a1b', 1, 'Bullies and Babies', 'Vicki''s daughter gives birth to a baby boy. Tamra moves in with her new business partner and fiancée. Heather hosts a clambake and doesn''t invite Alexis, which leads to tension in the group.', '2013-04-01', 44, NULL, '2026-04-03T16:35:32Z', '2026-04-03T16:35:32Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('0742af51-7e42-43f5-ac4e-392fac3d206e', 'ea73e13c-6962-4804-8305-c303df65f89f', 20, 'Welcome the Platypus Family (5) - Digging in the Neighborhood of Make-Believe', 'Rogers brings in various shovels, one of which he uses to put down fertilizer. In the Neighborhood of Make-Believe, Henrietta has sewn curtains with a duckbill pattern. These go to the site for the new Platypus mound. Rogers also shares his homemade recipe for making Ice pops.', '1969-03-07', NULL, NULL, '2026-04-03T17:35:38Z', '2026-04-03T17:35:38Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('0744cba2-5a09-423a-ba93-356229d41f0a', '6f81c872-cdb9-42dd-8377-2c17cb6ed4d7', 18, 'Counting Hats (repeat)', 'Elmo and Zoe compete to see who can wear the most hats.', '2017-05-06', NULL, '/s8OuAbYOeib3B916QLYyzcnSyz.jpg', '2026-04-03T17:36:48Z', '2026-04-03T17:36:48Z');
