INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('074b1072-c771-493b-9d88-8d3a58e26ae0', 'f4c40307-9b5e-4263-a4e0-dfa138131e7f', 43, 'Sesame Beginings - Moving Together', '', NULL, NULL, NULL, '2026-04-03T17:36:27Z', '2026-04-03T17:36:27Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('074b51ff-50ba-41e3-b99b-5826cfadcb07', '34674c90-410e-427c-be4d-2a6f6f865a80', 2, 'Corey''s Big Burn', 'The Pawn Stars prepare to play rough when an original program from the very first NFL championship rushes into the shop. A 1932 game between the Chicago Bears and the Portsmouth Spartans, will the guys push this deal into overtime, or will damage cause them to pass? Then, Rick sees dollar signs when he''s presented with an exploding dye pack of $10 bills. Used by banks to catch thieves, can Rick steal the deal, or will it blow up in his face? And during the night shift, a 1960''s Schwinn tandem bike rolls into the shop. Will Chumlee and Olivia take this classic bike for a pawn-paired spin, or will the negotiation go flat?', '2012-04-09', 21, NULL, '2026-04-03T16:34:17Z', '2026-04-03T16:34:17Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('074c8dfe-9ff8-409a-8594-fc14ae39e7f1', 'c66c23b0-1456-451a-bb80-45c28b0309ec', 7, 'The Bear and the Maiden Fair', 'Dany exchanges gifts in Yunkai; Brienne faces a formidable foe in Harrenhal.', '2013-05-12', 58, '/nNuLiw1TnQMNJ8B3ijN2D6jyAfc.jpg', '2026-04-03T15:40:36Z', '2026-04-03T15:40:36Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('074d48ca-81b3-45f9-8d75-4f8466930bff', 'f13cb622-84e3-4654-a8f1-0ceab09a9ca6', 5, 'Franklin''s Pumpkin', 'Franklin and Bear have been growing a huge pumpkin in the hopes of entering it in the county fair and winning first prize. As they run an errand to help Mrs. Muskrat, they tell her of their pumpkin and learn about the amazing things she does with seemingly useless broken glass. When their pumpkin suffers an unfortunate accident, Mrs. Muskrat shows them how they too can make something great out of something seemingly useless.', '2002-05-13', 12, NULL, '2026-04-03T17:40:16Z', '2026-04-03T17:40:16Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('07639868-fe58-4e12-b6a3-37580adf29b1', 'bb919aec-0d5c-4c58-9a5a-fa2a0a5de2b6', 84, 'Episode 489', '', '1973-03-22', NULL, NULL, '2026-04-03T17:36:30Z', '2026-04-03T17:36:30Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('076893b6-5c5e-466f-80cc-4921cc885cc9', '4b4d327b-6c8b-459c-9e73-b1d4d84aed77', 17, 'Big Bear, Small Bear', 'Brother wants to grow up fast.', '2003-10-08', NULL, NULL, '2026-04-03T17:40:22Z', '2026-04-03T17:40:22Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('076a03e8-b8fb-49b8-9ba8-42236222b4ad', '9193e795-da7c-40ec-b68f-f63aa7d5174f', 214, 'The Fallen: A Roundtable', 'Writer Bryan Cogman sits down with a few main casts who face their deaths in season 4. The 30-minute feature shows what it''s like to live - or die - in the world of Game of Thrones, from the first announcement of the impending end to the execution of the final scene.', '2015-02-17', 30, '/1rb8gGU9SEQcv8gyVmXj8Jbbz5.jpg', '2026-04-03T15:40:35Z', '2026-04-03T15:40:35Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('076a50f2-d18d-4d9a-8ff2-7e590b23756c', '70d9e397-6813-4785-887d-27d034928bae', 10, 'Pingu And The Message In A Bottle', 'Pingo is fishing, and Pingu meets up with him by the water. Pingu spots a bottle bobbing up and down in the water, and throws snowballs into the water to float the bottle to the shore. He smashes the bottle, and finds a mysterious map inside. This shows a route from the water into the hills, with a big “X” at the end point. Pingu and Pingo follow the route, which is quite hazardous in parts, to a boarded up cave. Pingu goes into the cave and discovers a padlocked chest. He brings it out and breaks into it, but he and Pingo are both disappointed to find that the chest is empty except for a shell. They then have a difference of opinion over who gets what, as they both want the chest; Pingo eventually takes the chest and Pingu the shell. When Pingu gets home with the shell Pinga is quite keen to have it, but Pingu won’t give it to her. Mother comes over and he gives it to her, but Pinga tries to grab it and it falls to the floor, breaking open. They’re all surprised to see a pearl drop out and roll across the floor. Pinga rushes to get it and gives it to Pingu, and they’re all pleased at their good fortune.', '1995-08-17', 5, '/8duuFjaHc3jmojJf8MB3PMbAqRb.jpg', '2026-04-03T17:22:19Z', '2026-04-03T17:22:19Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('077726d9-cc21-4bce-b179-aabe23da5a46', '9193e795-da7c-40ec-b68f-f63aa7d5174f', 123, 'Histories & Lore: The Wall', 'Samwell Tarly explains the impressive construction and function of the Wall, including its natural defenses against wildling attempts to scale, breach, and circumnavigate it.', '2015-02-17', 4, '/3NlmULP5ZpYZCK0xYRmTHUn7VaI.jpg', '2026-04-03T15:40:35Z', '2026-04-03T15:40:35Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('07832ee7-f433-40c4-a11f-4452359cbd77', '0b9d7ae7-218e-45a0-8c3a-e69912f5a6ed', 6, 'Franklin and the Computer', 'Franklin spends too much time on Beaver''s computer game, Dam Builders. Beaver thinks that Franklin is more interested in the game than spending time with her, who comes to his senses and puts his friend before the game.', '1999-10-25', 12, NULL, '2026-04-03T17:40:15Z', '2026-04-03T17:40:15Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('0785cc2c-0601-4793-95e8-2c8846eeba97', '18da9943-1963-4e04-a7a0-ae63802bb1fa', 17, 'Friends and Enemas', 'Vicki is confronted by her son Michael for not letting him know about her most recent procedure; Tamra and Gina''s conflict continues at Emily''s Turkish coffee cup reader gathering; Kelly questions if Shannon may be manipulating the Tamra-Gina rift.', '2018-11-12', 44, NULL, '2026-04-03T16:35:34Z', '2026-04-03T16:35:34Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('07886336-eeb0-40fc-baf7-a82401400d32', '34674c90-410e-427c-be4d-2a6f6f865a80', 22, 'Bullitt Proof', 'Burn some rubber with the Pawn Stars when they check out a 1968 Ford Mustang GT fastback. Just like the car driven by Steve McQueen in "Bullitt," will Rick get into a high-speed chase for this classic muscle? Then, a guy moseys in with an 1858 Smith & Wesson Model 1. The same model used to kill Wild Bill Hickok, will this Old West pistol still pack a punch, or is the seller drawing dead? And later, a man dashes in with a WWII telegraph set. A wireless version often associated with spies, will the guys tap out a good price, or will the seller s bottom line force them to stop?', '2012-08-13', 21, NULL, '2026-04-03T16:34:17Z', '2026-04-03T16:34:17Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('078d59df-577b-4bd7-bd39-63cc43d8ef0c', '4d2cac0f-38fd-438b-8afa-acf43952e535', 39, 'Episode 39', 'A weekly programme for younger viewers.  Introduced by Christopher Trace.  Model Ships shown by J.B. Jenkinson and John Fisher.  The Chipmunk Song pictured by Tony Hart.  What the Brownies Do: 4 with Jean Francis.', '1959-07-16', NULL, NULL, '2026-04-03T17:21:47Z', '2026-04-03T17:21:47Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('079262dd-91f2-4fb6-851a-ec7918846ebc', '5d97d70c-fcec-41ce-8e0d-78ab624fe334', 7, 'Elmo''s Awesome Bike', '', '2026-03-09', 30, NULL, '2026-04-03T17:36:52Z', '2026-04-03T17:36:52Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('079b17ab-2053-4a7c-bc10-2a755a66f5e9', '3af7ea64-fa13-4097-b8e4-40af07083054', 62, 'Episode 62', 'Negri''s Music Shop has a display of television equipment. Rogers and Negri take turns working the camera and performing music on-screen. Before leaving the shop, Rogers encounters Terri and Chrissy Thompson, who are arranging a puppet show. MGR-TV still continues to emerge at the Neighborhood of Make-Believe, creating program ideas on the spot. To help tiring camera operator, Lady Aberlin, Handyman Negri provides a rolling camera attachment.', '1974-05-14', 28, NULL, '2026-04-03T17:35:40Z', '2026-04-03T17:35:40Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('079e01ee-eefa-428b-aec0-bc0c2cd0fb0d', 'a1b69730-d225-48f2-a7e7-1d314cf3b349', 75, 'Episode 75', 'with Valerie Singleton, John Noakes, Peter Purves', '1969-06-12', NULL, NULL, '2026-04-03T17:21:49Z', '2026-04-03T17:21:49Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('079ed13c-31a8-4232-8b9b-83f6bc302c0d', 'c5ae23d0-08df-4f18-af08-0ccc8fdef868', 2, 'Bugs & Beetle Bop', 'Can Cleo and the cubs cure Theo of his fear of caterpillars? And, get ready for the sensational singing group coming to the library: The Beetles!', NULL, 30, NULL, '2026-04-03T17:12:30Z', '2026-04-03T17:12:30Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('079fe42c-0035-4c28-a67d-6a6cc1c601cc', 'f4c40307-9b5e-4263-a4e0-dfa138131e7f', 95, 'Best of Sesame Street Spoofs! Volume 1', 'Sesame Street has always focused on ABCs and 123s, but what happens when the Muppets on the Street become TV game show hosts, police officers, or famous musicians? Hilarity ensues! Spoofs Volume 1 contains old school classics like "Hill Street Twos," "Hey Food," "Rebel L," "Twin Beaks" and "Monsterpiece Theater."', NULL, NULL, NULL, '2026-04-03T17:36:27Z', '2026-04-03T17:36:27Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('07a05d89-1b23-4dae-8e9d-551dfa8d5dd9', '225b0f03-984b-47f3-a1a3-d3e92175e39d', 1, 'Episode 1', 'with Christopher Trace, Valerie Singleton and John Noakes.', '1966-09-19', NULL, NULL, '2026-04-03T17:21:48Z', '2026-04-03T17:21:48Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('07a3e83a-c8a8-401c-8b15-0129d883e145', '151e88a1-9576-4bd1-b84a-c4d64c1c9fe8', 5, 'In Hot Water', 'Kyle and Garcelle attempt to get to the bottom of the alleged “dark comments” Sutton made a year ago, but Crystal refuses to divulge what was said. Lisa suffers a devastating loss. Diana sweetens the trip to Mexico by chartering a private jet, but the getaway may not be enough to ease Dorit’s ongoing anxiety. Erika and Lisa’s comments push Sutton to a breaking point.', '2022-06-08', NULL, '/uPiUYn32K6Do0XyxD2q4FdNiQE4.jpg', '2026-04-03T16:34:58Z', '2026-04-03T16:34:58Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('07a67d84-756a-49d1-b04b-df1dd40e3ce7', '42253cb1-e961-4018-8dd9-8a69e6f70873', 14, 'Episode 2239', '', NULL, NULL, NULL, '2026-04-03T17:36:37Z', '2026-04-03T17:36:37Z');
