INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('08476096-a8ef-4858-9d38-bc70ff76c007', '22beba7f-9b8e-4563-93da-46e76ecba427', 18, 'Happy Birthday Rocco!', 'Zoe is throwing a birthday party for her pet rock, Rocco, and everyone''s invited.', '2006-09-20', NULL, '/rK3pOznmxdM6IMG2m9W1gmqejL8.jpg', '2026-04-03T17:36:44Z', '2026-04-03T17:36:44Z');
