INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('08d2810f-82b6-4bdf-ac57-6539a8d0e64e', '38bf8c20-c17c-4071-9226-7887787cf1b1', 21, 'Rats', 'After someone calls Leona a nasty name on the playground, a friend of the Lions'', named Frank, tells a story about Rats, which shows that bad names can hurt just as much as sticks and stones.', '2001-04-30', 30, NULL, '2026-04-03T17:12:28Z', '2026-04-03T17:12:28Z');
