INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('09234dc1-ba54-42e9-8a66-0aa29152f8ac', 'ba33491a-8f19-4e61-ae9f-0a67db3c65b0', 9, 'Ambush in Paradise', 'Karen and Mia struggle to recover after an explosive confrontation; when Candiace is caught talking trash about the group to the public, Robyn confronts the issue with the help of a special guest; Ashley brings a rumour about Karen to the table.', '2022-12-04', 54, '/9bzzevkA42Q6F7QL0SLXcr7y0DG.jpg', '2026-04-03T16:35:40Z', '2026-04-03T16:35:40Z');
