INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('0930d3d0-8e13-4c40-b9fe-c2e99ce0a2c8', '5c16db9d-5e71-40eb-b44e-f559b2ddb8f3', 3, 'Pinocchio', 'James Coburn, Carl Reiner, Paul Reubens and Lainie Kazan star in this amazing version of the Carlo Collodi''s classic tale. A magical blue fairy brings a marionette named Pinocchio to life in order to grant a woodcutter''s wish. Now Pinocchio must prove himself kind and loving in order to become a real, live boy. But, if he is bad, which sometimes he is, his nose will grow and only until he realizes his mistake will it shrink back to a valid size. This is one of the best Faerie Tale Theatre episodes, and one of the best versions of this classic Faerie Tale!', '1984-05-14', 51, '/4f0IRTC7qxRubcj7mvEwYbgyJv0.jpg', '2026-04-03T17:38:41Z', '2026-04-03T17:38:41Z');
