INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('094019d5-bd11-4292-a248-cc6112b4f747', '5062ce29-8dbb-48ab-879b-0771221678d5', 10, 'A Very Useful Friend', 'As Badger and Fox help Percy tidy his shed, Mouse joins in the work, but her clumsiness isn''t helping. But when the trio become trapped, Mouse proves to be very useful to them.', '1999-11-14', 15, NULL, '2026-04-03T17:19:02Z', '2026-04-03T17:19:02Z');
