INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('09e84f8f-6faf-4d07-af20-34504636f2d0', '5a6d9a42-165b-4b56-9273-0a06874dfe10', 1, 'Madeline', '"In an old house in Paris all covered with vines lived twelve little girls in two straight lines..." Thus begins this musical adaptation of the classic 1930''s children''s book about Madeline, the smallest and bravest of the twelve little girls.', '1988-11-07', 23, NULL, '2026-04-03T16:34:01Z', '2026-04-03T16:34:01Z');
