INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('0a1e57c8-e35d-4140-9ccc-ebc7d592b8f6', '913f846d-85df-4694-8dd4-0d5909f78887', 8, 'Self-Discipline', 'Zach’s obsession with a new video game, rather than his scouting manual, leaves him embarrassingly unprepared during a troop camping trip, prompting a story from Plato about the need for self-discipline.', '2000-11-12', 30, NULL, '2026-04-03T17:38:35Z', '2026-04-03T17:38:35Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('0a1e8135-9858-4f72-8cd2-f4d39243110f', 'ea1650c2-e4f1-46c7-93ba-74b5d45d08e5', 18, 'Reunion (2)', 'Hosted by Bravo''s Andy Cohen, part II of the reunion has the ladies of Hotlanta, Cynthia Bailey, Kandi Burruss, NeNe Leakes, Phaedra Parks, Sheree Whitfield, Kim Zolciak get together to set the record straight on some of the most talked-about antics of the season and answer some of America''s most burning questions.', '2011-02-20', 43, '/yzHOCfUN60xIeQDSGSEnnZCpEBR.jpg', '2026-04-03T16:34:45Z', '2026-04-03T16:34:45Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('0a2366ec-a831-4b3d-92b9-46ae29bc3406', '68138de2-0900-460a-b58e-480688f1e081', 38, 'What''s The Story?', '', NULL, 25, NULL, '2026-04-03T17:35:31Z', '2026-04-03T17:35:31Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('0a239755-47e9-48ba-8720-dee6671293f3', '3087a3ed-e94e-4276-9d02-a78183dea1d3', 13, 'Make an A* Out of a Donkey', 'Kenya and Phaedra focus on their competing workout videos as their feud builds, with Porsha ultimately getting caught in the crossfire. Elsewhere, Cynthia tries to expand her agency, and NeNe learns hard lessons about success.', '2013-01-27', 43, NULL, '2026-04-03T16:34:46Z', '2026-04-03T16:34:46Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('0a24e5ac-9c50-426c-bc1e-6343c8b9b640', '941b8c65-4454-4336-be7c-1d0591c12f90', 24, 'Pingu Plays Tag', 'Pingu is having a game of tag with Pinga, and he is determined to avoid being "it" at all costs, rushing round the igloo, hiding in bed and hiding behind the ironing board, where Father is ironing. When Pingu bangs the ironing board, causing the ironing to fly into the air, Father tells them to go outside to play. Pingu gives Pinga the slip by climbing up on an ice arch. When she can’t find him she gives up looking and goes home. Pingu meanwhile has discovered that there is no easy way down from the top of the ice arch! Pinga tells Father that she can’t find Pingu and, as it’s getting late, Mother, Father and Pinga set off in the motorised sledge to look for him. As night falls, Pingu is still on the ice arch, getting colder and colder, and Mother, Father and Pinga are still searching. Eventually they find Pingu, and Father persuades Pingu to jump down into his arms, which he safely does. Later, Pingu is helping Father by folding the ironing when Pinga tags him, to his annoyance. Father consoles Pingu, then surprises him by tagging him himself and running off …', '2004-02-04', 5, '/nuTAEYS7dfhS7GcjknZrLV9cSIt.jpg', '2026-04-03T17:22:20Z', '2026-04-03T17:22:20Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('0a260930-28c2-49aa-a946-02df292143f7', '487fdbcd-ec5a-454e-8268-b50566eb8546', 3, 'Don''t Cross the Caro-line', 'Caroline Stanbury undergoes hypnotherapy to confront her past. Lesa tries to convince her mother to move to Dubai. Sara reluctantly goes on a double date with a new man. Michael says good riddance to Caroline Stanbury and Sergio with a farewell party, but someone is left off the guest list.', '2024-06-18', 43, '/l55zxyRQE4asUSJqHUIAJqC3Uqm.jpg', '2026-04-03T16:35:07Z', '2026-04-03T16:35:07Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('0a29f93f-0c67-42fa-8e96-d45818adaaa3', '3fc7c152-e4f6-426a-a899-36ec454c4403', 42, 'Treasure Hunt', 'The kids visit the secret Treasure Trove with their dragon friends, but forget Quetzal''s final instruction and end up lost. It is only by following directions and working together that they break free.', '2000-01-17', NULL, NULL, '2026-04-03T15:26:03Z', '2026-04-03T15:26:03Z');
