INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('0a325a29-834c-4dd0-9ae3-4df0ceb323fe', 'ea1650c2-e4f1-46c7-93ba-74b5d45d08e5', 6, 'Trashed Collection', 'With Bryson''s 90-day deadline to get a job or get out approaching, NeNe hopes introducing her late bloomer to Cynthia''s boyfriend and club owner Peter will inspire her son to find a career path. While visiting his daughter, Noelle, Cynthia''s ex-fiancé, actor Leon Robinson, discuss Cynthia reservations about marriage. Even while planning a high-end yard sale, Kim begins work on her new track with help from Kandi, but things get heated between the two when creative differences arise. Already puzzled with Phaedra''s ever-changing due date, the ladies are shocked to hear she’ll be inducing her baby "early." NeNe''s marriage troubles come to a boiling point when she reveals a dark relationship secret to Cynthia.', '2010-11-07', 43, '/8PhYwBtrwVCtaLchaRJI5rKOzmW.jpg', '2026-04-03T16:34:45Z', '2026-04-03T16:34:45Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('0a344f42-c252-4a8a-b9b0-811024014ca7', '24003c6d-d919-4616-a7dd-0d38bb7a0656', 16, 'Race', 'Pat comes across her real-life husband Laurence Hutchins who invites her to a café by the river. He offers to give her a lift in his car, but she declines. Rosie and Jim dislike his remark of the Ragdoll being slow and decide to race him in the boat.', '1996-08-02', 10, NULL, '2026-04-03T17:19:37Z', '2026-04-03T17:19:37Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('0a36487e-d320-4b28-820a-105945777f5e', '05c0e384-194c-4417-9f62-803eb615e409', 66, 'All about cars', 'Title number 0066. Opens with Mister Rogers arriving with a bag of toy cars. Mr. Rogers explains how all toys do what you want them to do. His son, John, also makes his first appearance on the show to play with model antique cars. Meanwhile, at the Neighborhood of Make-Believe, Corny''s newly rebuilt factory offers to help Mime Jewel Walker in his go-cart play-act.', '1968-05-20', 29, NULL, '2026-04-03T17:35:38Z', '2026-04-03T17:35:38Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('0a42553c-baa8-41d5-b2d5-4f5f26072a6f', '1d713ca6-4e17-4f84-949c-8cfd98514127', 4, 'Put Up Your Nukes', 'Go to DEFCON 1 with the Pawn Stars when a seller claims he has a cover for a thermonuclear warhead. Can Rick successfully defuse the negotiation or will it blow up in his face? Then, Corey swings into action when a mandolin from Bob Wills'' Texas Playboys comes into the shop. Will he pull some strings for the country classic or will it be out of tune? And later, Chumlee tries to find something he''s better at than Rick. Will he be able to beat the boss or will Rick prove once and for all don''t mess with the best?', '2014-07-17', 21, '/whJXD0CycdCsYhoGzaVFO2VBqka.jpg', '2026-04-03T16:34:19Z', '2026-04-03T16:34:19Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('0a4bf943-1927-418f-94ee-42c1a142e4c2', '01916834-25ec-43d6-9a1b-8ea5d9630adc', 12, 'Stuck in the Muck', 'Shaun tries to help when the tractor gets stuck, but he only gets deeper into bother.', '2025-06-10', 7, '/81tbnKNZcqlcCT8BqYWaETsKG38.jpg', '2026-04-03T17:39:33Z', '2026-04-03T17:39:33Z');
