INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('0a6f358a-2ccc-41d4-a299-76c4a564d341', 'ecb64ef3-4f80-45a7-b4a9-c04434b02e35', 32, 'Saddle Up', 'Cast your vote for the Pawn Stars when an Abraham Lincoln campaign poster comes up for grabs. Used in his 1864 re-election campaign during the Civil War, will it cost Rick a pretty penny or will he veto the negotiation? Then, Chumlee''s feeling like a kid again when a Turbo Man action figure flies into the shop. Can he cough up the dough to snag this fictional superhero or will it "jingle all the way" out the door? And later, Chumlee''s plan for a hike with the guys turns into a day on horseback, but it seems Vegas is a one-horse town.', '2014-04-17', 21, '/v58SOccl2nqP5OpHtu1ZwE7lbOC.jpg', '2026-04-03T16:34:19Z', '2026-04-03T16:34:19Z');
