INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('0ac08ada-f021-419e-bb38-811fa1ed2fce', 'ce91a034-5625-4fa6-b81b-db773be5502e', 2, 'The Pirate Part Deux', 'At the beach, the ladies discuss Sonja''s communication skills and revisit the infamous Scary Island; Luann hosts a seafood dinner where Sonja questions Kristen''s marriage; some handsome young men join the ladies for a house party.', '2023-12-14', 47, '/aB8qfZwKNYinPbyn82D807E9xPe.jpg', '2026-04-03T16:34:41Z', '2026-04-03T16:34:41Z');
