INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('0acf1cf8-748c-4630-8460-31acdedc76ec', 'd306a064-e835-417e-8548-0cf806295f31', 16, 'Melting Pot Meltdown', 'Lisa stands up for herself against her mother-in-law; Peter confides in his father about his mom; Nicole and her dad confront their issues; Guerdy hosts a melting pot party where Adriana pleads with Alexia and Marysol for forgiveness.', '2023-03-02', 44, '/ueb1RunuzLJDp3jD9K2aVTJBYvv.jpg', '2026-04-03T16:35:11Z', '2026-04-03T16:35:11Z');
