INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('0b28a0b8-7041-4efb-a20b-0622387efa81', '3087a3ed-e94e-4276-9d02-a78183dea1d3', 4, 'Unmoved', 'Kandi settles into her new home just as Kim must move out of her dream home. Elsewhere, Porsha continues to fume in the wake of her showdown with Kenya; Phaedra arranges an excessive party for her son; NeNe forwards bad news to Cynthia.', '2012-11-25', 43, NULL, '2026-04-03T16:34:46Z', '2026-04-03T16:34:46Z');
