INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('0b42b4ac-306a-4441-80d7-deaac10702fa', '227b8429-0dfd-47e4-b874-c37da20c403f', 24, 'Rick''s Bad Day', 'The Pawn Stars have an opportunity to buy a theater playbill from the night that Abraham Lincoln was assassinated. But first they''ll have to determine it''s authenticity. Then Corey and Chum meet a modern day renaissance man and buy his pair of Halbert spears. But before they can put their tights on, the Old Man suspects there may be more there than meets the eye. And later, Rick takes a gamble on an elegant, perpetual motion clock that he hopes will stand the test of time.', '2009-12-27', 21, '/hCc2gBpi5Bdef9v6rJYzntLls96.jpg', '2026-04-03T16:34:15Z', '2026-04-03T16:34:15Z');
