INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('0ba087ea-e14e-43d7-a59a-7f809e19ec8c', '1c9ea7d3-e254-4e7b-8a9f-33eea9c6c341', 10, 'Living on the Edge', 'After an icy welcome in Toronto, Nene lays out her standing with each of the girls. Nene and Eva sit face to face and revisit old wounds, while a group trust exercise forces the ladies to live on the edge in an unexpected way. Kenya, Porsha, and Kandi team up to find the snake that recorded Cynthia, but before they can get to it, there is a surprise that will shock everyone.', '2020-01-05', 43, NULL, '2026-04-03T16:34:49Z', '2026-04-03T16:34:49Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('0ba331b9-e2bf-42f8-8b0a-1d2260dbcf86', '34674c90-410e-427c-be4d-2a6f6f865a80', 21, 'Kick the Can', 'Take the field with the Pawn Stars when a World Series ring from the 1995 Atlanta Braves slides into the shop. Known as "the team of the 90s," will the guys try to push the negotiation into extra innings, or is this item out of their league? Then, Corey and the Old Man hear the sweet sound of cash when a Sho-Bud steel guitar comes in. A classic instrument in country music, can the Old Man get it for a song, or is the seller singing a different tune? And later, a guy brings in an oilcan used for fueling a 19th century lighthouse lamp. Will the Old Man guide this deal through treacherous waters?', '2012-07-09', 21, '/pp71O0HWed02OEyCnWuuOJnxtzT.jpg', '2026-04-03T16:34:17Z', '2026-04-03T16:34:17Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('0ba9f6ad-464a-4926-b468-700e681fc806', 'c0c0b0ba-e6e3-4a30-9567-1102881eddf3', 18, 'So Funny I Forgot to Laugh', 'Arthur''s teasing of Sue Ellen''s new sweater makes her feel bad.', '2013-05-10', 13, NULL, '2026-04-03T17:38:00Z', '2026-04-03T17:38:00Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('0bab1ac7-e4c5-4e9a-b5bc-a5a05af05f35', '9310a288-5af0-4746-a8d7-d7635ffb6beb', 8, 'Work', 'Mister Rogers arrives with a bucket and a rubber washer. Taking the washer to the kitchen, he finds that it is too large to be used to repair his kitchen faucet. After a phone call to Bob Trow, Mister Rogers visits Trow''s workshop to pick up a washer that fits.

At Trow''s workshop, Bob Trow is repairing a shovel with a broken handle. Once that task is completed, Mister Rogers is shown a collection of various washers and is able to find one just the right size. Mr. Trow then demonstrates an antique water pump he has recently repaired.', '1984-04-06', NULL, NULL, '2026-04-03T17:35:43Z', '2026-04-03T17:35:43Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('0bb4c628-f05f-4613-8542-4c0207c9125a', '5144de59-e67f-4fcf-919b-7106989ab797', 2, 'Train Driving Kids', 'The boys have a model train but refuse to share with the girls, insisting it’s a boys’ activity. Gradually everyone takes to other suggested activities, leaving only Leon and Kiki still wanting to play with the model train. Nuzzle struggles to play a toy xylophone.', '1995-01-17', 29, NULL, '2026-04-03T17:12:21Z', '2026-04-03T17:12:21Z');
