INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('0be321dc-7245-4976-a852-70b2de1941a9', 'efd2082e-32f5-4edd-9a7b-a4326d6992c9', 17, 'Fixing X', 'Big Bird and Snuffy are the hosts of "The Letter of the Day Show" on Sesame Street, and learn all about how the letter X can come at the end of a word.', '2019-03-09', NULL, '/ydYidr8fGiyVUXeiSTplP5n8HFD.jpg', '2026-04-03T17:36:49Z', '2026-04-03T17:36:49Z');
