INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('0c08910f-eddb-4e4e-ba8f-56f023744d4a', '596e6e8f-f651-47f2-83b8-d4cdee8e5927', 13, 'Episode 13', '', '2005-06-26', 25, NULL, '2026-04-03T17:21:20Z', '2026-04-03T17:21:20Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('0c11b449-f715-4731-a818-acaa1ee36f41', 'a4843a51-aeef-427c-902c-7fb3bd670cd4', 19, 'Magic in the Kitchen', 'Bear has just gone inside the Big Blue House for some relaxing swinging in the living room in the kitchen. Ojo, however, is soon there to remind Bear of a promise he made. She''s very hungry and Bear had promised to make her his "incredible banana berry whole-wheat pancakes with maplely syrup." So Bear heads to the kitchen to get cooking, and Ojo offers to help out. She goes to get Snow Bear and soon after, Pip and Pop join in the cooking. Tutter and Treelo appear soon after and Tutter''s a bit annoyed with Treelo for taking him flying through the trees. Still, they join in the preparation as well --- Bear has them set the table. Tutter disagrees with Treelo as to how to fold the napkins, but Bear gets them working together on a new way to do it. In the Shadow segment, Shadow sings the song "Muffin Man." In her version, however, the Muffin Man is a super treat that''s able to fly into your mouth (with a little help.) 

Songs 

Magic in the Kitchen 

Clean Up the House', '1997-11-14', 25, NULL, '2026-04-03T17:35:31Z', '2026-04-03T17:35:31Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('0c1623ed-8d60-41e3-8daa-95f0d9c4d78b', 'd5351b60-8a0c-482a-a6dd-4fb860cfe143', 23, 'Episode 1413', 'Mister Rogers arrives with a catalog of tents to share with viewers -- Tempered Tents For All Seasons.  In the Neighborhood of Make-Believe, Lady Aberlin is making a tent for Prince Tuesday when Mr. Allmine arrives in the Neighborhood.', '1975-03-19', NULL, NULL, '2026-04-03T17:35:41Z', '2026-04-03T17:35:41Z');
