INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('0c181bed-c35c-4d27-a878-f18f2c61ecbe', 'a79a245f-acab-4ebe-aee9-29867f9e52f6', 21, 'Game Night!', 'It''s game night at the Browns, and it''s about to get a little crazy. The family gets competitive as Mykelti and Gwendlyn host Sister Wives trivia. There''s lots of noise and chaos, and there''s punishments for the losers, so the stakes are high!', '2018-03-25', NULL, NULL, '2026-04-03T16:34:30Z', '2026-04-03T16:34:30Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('0c2633d0-ae81-407f-ad56-61b841b25644', '913796e9-c0ce-44dd-98bc-f6f520cb2444', 3, 'How to Make an Apple Pie and See the World', 'LeVar and a friend say following recipes and cooking foods are very much like science experiments. They work on recipes which include lasagna made with rice, a marinara sauce, and apple raisin muffins. Helen Mirren reads How to Make an Apple Pie and See the World, a tale of a lady who goes to elaborate lengths to get all the ingredients to make a pie after she finds her local grocery store closed.', '1995-10-10', 30, NULL, '2026-04-03T17:36:19Z', '2026-04-03T17:36:19Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('0c2b22e8-51a8-4296-ae49-06b3e3ea4de2', 'ebc99729-ccb7-4d64-82c1-42708cd7ba85', 37, 'Episode 37', '', '1981-01-15', NULL, NULL, '2026-04-03T17:21:55Z', '2026-04-03T17:21:55Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('0c2cf903-7398-4a8d-a15e-8bddbd45ff2e', '994c75e5-06fa-4be1-a142-ea7b2c892dd0', 5, 'Curiosity: A Visit with Violinist Hilary Hahn', 'Rogers reads his own book titled "Daniel Striped Tiger Gets Ready for Bed". He finds violinist Hilary Hahn at Negri''s Music Shop. Nighttime grips the Neighborhood of Make-Believe with worry over Little Panda and Prince Tuesday.', '2000-09-07', NULL, NULL, '2026-04-03T17:35:49Z', '2026-04-03T17:35:49Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('0c2ec11d-9a3b-45fe-adb1-23af2217468b', '0e419615-4c96-4dde-8ed2-715770ba77bb', 4, 'First Day At Mouse School', 'It''s finally Tutter''s very first day at Mouse School. He''s really excited and happily shows off his bookbag and other school supplies to the other kids in the Big Blue House. Meanwhile, Bear and Doc Hogg share a cry over how much he''s growing up. But when it comes time to go to school, Tutter is scared that he won''t fit in. Bear agrees to accompany him and to wait outside the school, until he''s comfortable with being there without him. 

Songs 

First Time for Everything', '2002-09-17', 25, '/9hHIwsu9jwOLqkbUdTtUaA0jFC1.jpg', '2026-04-03T17:35:32Z', '2026-04-03T17:35:32Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('0c32a761-1627-4dfb-8c97-c8d0bef11631', '8bae6aa3-4b55-4fa6-bc15-8f4317bd1f13', 45, 'Lady Elaine''s Purple Phase Pt 5', 'Lady Aberlin and Robert Troll must convince Lady Elaine of her rightful place in the Neighborhood of Make-Believe.', '1972-04-21', NULL, NULL, '2026-04-03T17:35:40Z', '2026-04-03T17:35:40Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('0c389443-0086-417b-834e-43b363528c81', '3415030f-f54d-42b9-a290-aaa05e246d86', 6, 'Maddie Gets Married', 'Madison Brown is getting married! This is the first wedding of all the Sister Wives’ children and it’s absolutely stunning.', '2016-12-18', NULL, NULL, '2026-04-03T16:34:30Z', '2026-04-03T16:34:30Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('0c396e0c-4fda-4b5c-9d9e-cf31d25736b4', 'ea73e13c-6962-4804-8305-c303df65f89f', 21, 'Magic Kite (1) - All about kites', 'While digging the Platypus family''s home, Digger Digorum and Handyman Negri discover a box containing a magic kite.', '1969-03-10', NULL, NULL, '2026-04-03T17:35:38Z', '2026-04-03T17:35:38Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('0c3bbc3a-94b0-43e6-a17e-8b3b3d5e716e', '3a96d6c6-3736-498a-926f-6c479cdfb73a', 4, 'Franklin''s Bad Day', 'Franklin is sad his best friend, Otter had moved away. Even though he refuses to admit it, he''s also angry and mad at everyone. He then realizes, no matter what, it''s no excuse for his behavior.', '1997-11-06', 12, NULL, '2026-04-03T17:40:14Z', '2026-04-03T17:40:14Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('0c3da90a-3b65-4f38-b2f0-730a0af57f62', 'c1df0e9b-e03e-48e5-a930-61ee5ef85840', 10, 'You Are Arthur...', 'D.W. and Tibbles help Arthur train for a 3K race against Brain.', '2000-10-02', 13, NULL, '2026-04-03T17:37:56Z', '2026-04-03T17:37:56Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('0c42bf46-eed6-4383-8c79-1adef0ee4ff4', 'b86d15ea-4253-41a5-9f14-4a254ec601e0', 2, 'A Manzo of Her Word', 'Melissa considers selling her house and moving. Meanwhile, Kathy is tested by her son and her husband; the Lauritas host a poker night; and Caroline and Teresa square off in a fiery exchange.', '2013-06-09', 43, '/A6aUlWYwaTBgR5dJCMdEf81iuxG.jpg', '2026-04-03T16:35:16Z', '2026-04-03T16:35:16Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('0c463332-a0e3-4b22-9dfc-1cdf0c80725f', '1996ddd8-20c9-4a30-96be-2b87fab8d17c', 18, 'To the Light (1)', 'Rob takes Jamal to see his friend Double T who he met at the homeless shelter. When they go, Double T has mysteriously vanished leaving no trace of where he is. The only clue is a broken broom and a torn diary. Rob fears that someone is out to get Double T.', '1993-01-24', NULL, '/sZi1IzgMI3inMfPSlxCVhdUn2nR.jpg', '2026-04-03T17:40:28Z', '2026-04-03T17:40:28Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('0c488881-b419-40d1-9d90-ca074bef5b27', '44624ee8-03f0-4261-8379-68daf4666b42', 10, 'Arthur and Los Vecínos', 'Mr. Sipple from next door is moving away and Arthur wonders-who will be the new neighbours. When Alberto Molina and his family settle in, Arthur makes a new friend and learns about a different culture.', '2001-10-22', 13, NULL, '2026-04-03T17:37:57Z', '2026-04-03T17:37:57Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('0c49d53d-a4fd-4715-9df4-0421c8b0a1ab', '9c5608b2-5111-48bc-a907-7f93472c1e03', 26, 'Great Vibrations', '', NULL, NULL, '/qIU7lDFThVj6rcDEPvFhM1Uj0GE.jpg', '2026-04-03T17:36:47Z', '2026-04-03T17:36:47Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('0c4abf58-5728-4248-906a-4b6174f70fc7', '842c6419-ab98-4d34-8845-1d9782291aad', 7, 'Patience', 'When Annie volunteers to help a younger schoolmate with his math, she grows increasingly impatient with the boy and loses her temper. Annie regrets offering to tutor the boy, until she hears several stories from her friends at Plato’s Peak about the virtue of patience.', '1998-03-29', 30, NULL, '2026-04-03T17:38:34Z', '2026-04-03T17:38:34Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('0c4c45f2-bf39-4346-889d-2f35759b5334', 'a2edcb57-63c1-4028-b87b-7faeae2c999b', 4, 'Testing Time', '', '2004-01-27', 15, NULL, '2026-04-03T17:20:06Z', '2026-04-03T17:20:06Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('0c4eb2a7-74fe-4bc8-8a8a-247ac6f34fff', '9b144910-398a-47d4-9ccd-823d25cc8b0a', 7, 'True Love True Lies', 'Caroline finds out what Teresa really thinks of her; Melissa debuts her new song with a party; Joe reaches out to his sister one last time.', '2012-06-10', 43, '/cdEWBOLez1rfsHBnGV2i1c0Xa8w.jpg', '2026-04-03T16:35:15Z', '2026-04-03T16:35:15Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('0c4f1986-ef78-4deb-9835-2016495de021', 'e93f04c2-7344-4b93-abba-8ba1b2f8eb35', 100, 'Episode 635', '', NULL, NULL, NULL, '2026-04-03T17:36:30Z', '2026-04-03T17:36:30Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('0c552635-21ee-46e3-8db7-d9023a60b282', '4d2cac0f-38fd-438b-8afa-acf43952e535', 22, 'Episode 22', 'A weekly programme for younger viewers.  Including ''The Story of San Marco'', a scale model serial and ''Ginger and Pickles'', a story by Beatrix Potter with the original pictures.  Introduced by Christopher Trace and Leila Williams.', '1959-03-12', NULL, NULL, '2026-04-03T17:21:47Z', '2026-04-03T17:21:47Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('0c579b5a-ca32-421e-a034-eca68706cd42', '6b5caa66-f66f-4ed1-817f-a00bad08790e', 6, 'Finale', 'Teresa''s plans for a civilised dinner with the housewives and their families are scuppered when the ladies discuss Danielle''s past. Danielle blames Dina for spreading rumours about her even when Caroline admits responsibility for gossiping about her, and an argument breaks out between the housewives and Teresa gets angry with her guests. Later, Teresa''s husband tried to placate the guests with champagne.', '2009-06-16', 43, '/9mXLgQ59inVrPf0IpBerkZ5PCpP.jpg', '2026-04-03T16:35:14Z', '2026-04-03T16:35:14Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('0c579d15-810b-4b23-ac21-846859ed7da8', 'bf874be3-7e2f-4a0e-b205-c76ac1ad69fc', 36, 'Inside Looks (on The Fix-Up)', 'Inside look from the season 3 episode "The Fix-Up."', NULL, 4, NULL, '2026-04-03T16:34:08Z', '2026-04-03T16:34:08Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('0c588113-78e2-4bf4-a410-9147f40f9ce9', '54facb0b-db59-41fe-9d64-c7c7221a3c81', 1, 'Divided, They Summer', 'It''s been one crazy summer for the New York City housewives. Bethenny struggles with the sudden passing of her boyfriend Dennis, while Luann is coming to terms with the fact that she relapsed and had to go back to rehab. Ramona is tackling her fear of the water by taking swim lessons, and Sonja is adjusting to her new apartment. Dorinda has made positive changes in her life, but she has yet to face the tension between her and Luann. They haven''t spoken since the incident at Luann''s cabaret five months ago.', '2019-03-06', 60, '/n3MMlfa82nFKf8Nq6NhizJyaLoE.jpg', '2026-04-03T16:35:25Z', '2026-04-03T16:35:25Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('0c7055bc-9df6-44be-afe9-4e19d8281783', '2e6ee129-b32e-4417-9500-56f1cc9bc434', 3, 'Mrs. Katz and Tush', 'LeVar pays a visit to a family friend, who is Jewish, to learn how to prepare special foods served during a Seder dinner, like Challah bread and potato latkes. Reizyl Bozyk and Rick English read the featured story of an elderly Jewish lady and how she befriends her neighbor''s young son after she is widowed and he gives her a pet cat to keep her company.', '1993-10-13', 30, NULL, '2026-04-03T17:36:18Z', '2026-04-03T17:36:18Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('0c840406-ab33-471b-9d24-a99e487cce14', 'e6ea1431-9e67-4637-83ae-a11073e8c7e0', 10, 'Backwards in Heels', 'A joint anniversary bash with a burlesque theme is planned by Kyle and Lisa Vanderpump, but dramas spike when it''s discovered Faye Resnick is on Kyle''s guest list. Also, Lisa Rinna continues to feel guilty about a past discussion.', '2016-02-02', 43, '/rTxyJUePtCEdOXGvxZ7vaJi51a2.jpg', '2026-04-03T16:34:56Z', '2026-04-03T16:34:56Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('0c939ec4-43c6-4fb7-bb1e-480aabd9feee', 'f63c3f61-0970-4e37-81cc-2b9045a9952c', 65, 'Hurricane - Part 5 - The Final Twig (3980)', '', '2001-03-30', NULL, NULL, '2026-04-03T17:36:42Z', '2026-04-03T17:36:42Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('0c9740d7-573f-430e-8131-9f53bdc69d47', '004abc4c-ce77-4df9-8c97-9f56ea8b37ce', 11, 'The Flying Machine', 'Kipper decides to make something out of old bits and pieces he finds lying around. He thinks he''s making a flying machine, but in fact it turns out to be something much more useful for a hot day.', '2000-03-30', 30, NULL, '2026-04-03T17:10:49Z', '2026-04-03T17:10:49Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('0c9e113f-99d8-4b22-a621-8a25ae2d7d85', '05c0e384-194c-4417-9f62-803eb615e409', 45, 'The Babysitter Opera', 'Title number 0045. Opens with Mister Rogers arriving with a box with a hat and cape inside. During Reardon''s opera, Lady Aberlin hires Henrietta to look after Donkey Hodie.', '1968-04-19', 29, NULL, '2026-04-03T17:35:38Z', '2026-04-03T17:35:38Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('0ca2aee0-4841-4af7-b2a8-b5cae4877ef3', '3415030f-f54d-42b9-a290-aaa05e246d86', 3, 'He Pops the Question', 'Madison lays out the plans for her wedding. Janelle and Meri''s therapist pushes them to take a terrifying next step in their struggling relationship, and the biggest news of all; and the Brown''s family may be growing again after a special proposal', '2016-12-04', NULL, NULL, '2026-04-03T16:34:30Z', '2026-04-03T16:34:30Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('0ca87c72-0458-4587-9178-71c3789fb21a', 'a1b69730-d225-48f2-a7e7-1d314cf3b349', 54, 'Episode 54', 'with Valerie Singleton, John Noakes, Peter Purves', '1969-03-31', NULL, NULL, '2026-04-03T17:21:49Z', '2026-04-03T17:21:49Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('0cb52e0b-2dae-4237-ae2f-5bba7b3d44eb', 'f593d90c-5339-42f5-9c88-5bfd48d04075', 16, 'Everything Must Go', 'Everything must go when the farmer sets up a stall by the side of the road and leaves Bitzer in charge. The lazy sheepdog soon tires of his role and gives Shaun the job. He proves to be a much better salesman than Bitzer and the flock are only too happy to get stuck in, selling pretty much all the farmer''s worldly possessions.', '2009-11-22', NULL, '/tu94Up52tzFwm0radaLcCEBTE15.jpg', '2026-04-03T17:39:31Z', '2026-04-03T17:39:31Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('0cbc0264-a5f9-4766-bfad-7238ee0f1e16', '9310a288-5af0-4746-a8d7-d7635ffb6beb', 4, 'Conflict', 'Mister Rogers brings with him a box full of colored blocks. He takes them to the kitchen were he uses them to build a bridge. He also has with him a handful of marbles which he shows before watching films on how people use and make marbles.

In the Neighborhood of Make-Believe, Lady Elaine and Lady Aberlin take Bob Dog with them to Southwood to find out what exactly is going on.

Upon their arrival, they learn that the parts Corney made have been used to build a bridge, not for building bombs.', '1983-11-10', NULL, NULL, '2026-04-03T17:35:43Z', '2026-04-03T17:35:43Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('0cbede8b-0479-4d19-804f-7d7728fabd71', '33825a15-37dc-4ff9-82bd-cc720498149a', 11, 'My Life on the Dee List', 'Kameron tries to impress her daughter with a bow and arrow, while Kary has her first photoshoot for her jewelry line. Stephanie throws husband Travis a mid-life crisis themed 50th birthday party. Things get crazy when Mama Dee appears to crash the party and one of the ladies refuses to attend. The ladies leave for Thailand, with LeeAnne hoping this trip will finally be a positive one for her.', '2019-11-13', NULL, '/uItA2zZrv7WwdKm9EGrLrTNuW4j.jpg', '2026-04-03T16:35:04Z', '2026-04-03T16:35:04Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('0cc01fd2-3a14-4ffa-bc98-556d6a37b785', '3a96d6c6-3736-498a-926f-6c479cdfb73a', 9, 'Franklin Rides a Bike', 'Franklin noticed all his friends are riding their bikes without training wheels.  At first, he was a little embarrased with his training wheels but with the help of his mother, he learned how to finally ride a bike without training wheels.', '1997-11-20', 12, '/6koXEJg2ZyTsxOt5THYCL4ECFE.jpg', '2026-04-03T17:40:14Z', '2026-04-03T17:40:14Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('0cc4b9f3-1ca8-4184-8915-cf0230a2b484', '6053b5c1-ce86-425c-8166-e0fcc3466061', 51, 'Episode 51', 'with Valerie Singleton, John Noakes, Peter Purves', '1970-03-12', NULL, NULL, '2026-04-03T17:21:50Z', '2026-04-03T17:21:50Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('0cc914ef-ee9e-4f94-9d14-ec0861b587e8', '3af7ea64-fa13-4097-b8e4-40af07083054', 51, 'Episode 51', 'Mr. McFeely gives Rogers a pullover shirt from Elsie Neal. Later Rogers hears a marimba and a xylophone at Negri''s Music Shop.', '1974-04-29', 28, NULL, '2026-04-03T17:35:40Z', '2026-04-03T17:35:40Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('0ccec05e-d874-4f5f-9446-355f1b809750', '84ce360a-90d1-4fc0-be06-33bdcbe8e60a', 10, 'The Big Freeze', 'Kipper helps some ducks when their pond freezes over in winter.', '1999-11-25', 30, NULL, '2026-04-03T17:10:49Z', '2026-04-03T17:10:49Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('0cd0a0d7-5eab-43a3-ac75-76a8914e8476', 'b3d2e6de-205c-47bd-94ce-282860aad053', 1, 'Chapter One: Suzie, Do You Copy?', 'Summer brings new jobs and budding romance. But the mood shifts when Dustin''s radio picks up a Russian broadcast, and Will senses something is wrong.', '2019-07-04', 51, '/97PVnrEQWEsdMnD08QDmMxLkV7h.jpg', '2026-04-03T15:40:39Z', '2026-04-03T15:40:39Z');
