INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('0cdcb5be-e974-4983-83df-39dbb6e9785d', 'ebc99729-ccb7-4d64-82c1-42708cd7ba85', 48, 'Episode 48', '', '1981-02-23', NULL, NULL, '2026-04-03T17:21:55Z', '2026-04-03T17:21:55Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('0ce0175b-01d6-4310-94fe-7997003f287b', '1a534647-384b-4c00-bb6c-a3371ad962eb', 13, 'Rocky Road', 'Come out fighting with the Pawn Stars when handprints signed by Sylvester Stallone pummels into the shop. Will Rick score a knockout deal, or go down a Rocky road? Then, Rick scouts out two signed Norman Rockwell lithographs. Titled "Puppy Love" and "Dressing Up", will they be picture perfect, or show their true colors? And later, Chumlee tries to prove he is more active than everyone thinks he is by entering an arm-wrestling competition. Will Chum muscle his way to a win or will he be strong armed out of the competition?', '2015-02-26', 21, '/aF0rF5L0WJTjiX1felD5ljSERVr.jpg', '2026-04-03T16:34:19Z', '2026-04-03T16:34:19Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('0ce07f6b-455b-4df7-9b71-990a631e539a', '3d4e0e45-1c67-475e-b37d-9e7e6b8b942a', 8, 'Barking at Buddha', 'Wishbone wants to be a hero and tries to rescue two misguided youngsters when they set out to impress the older kids. As ""Monkey,"" he yearns to be immortal and seeks a position of importance in Wu Ch''eng-en''s Chinese folktale.', '1997-03-10', 28, NULL, '2026-04-03T17:10:42Z', '2026-04-03T17:10:42Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('0ce4bb79-c998-4405-b293-3492f9231704', '98d80972-e53a-43dd-a03a-7703465e6f87', 2, 'Sturgis and Acquisitions', 'Start your hog and ride with the Pawn Stars as they head to the annual Sturgis Motorcycle Rally. Can Rick relax and enjoy the trip, or will he stop and hunt for deals along the way? And back in Las Vegas, the Old Man and Olivia are holding down the shop. Will school be in session as he teaches her the pawn biz, or will he just take a nap and make her do all the work? And later, the guys arrive in Sturgis, but Rick spots a sweet deal, a 1966 Honda CB160 motorcycle. Is he just window-shopping, or will he insist on mixing business with pleasure?', '2012-11-05', 21, NULL, '2026-04-03T16:34:18Z', '2026-04-03T16:34:18Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('0ce6e00d-6259-46de-8e89-b3097a676039', '8610109b-4fb9-4eae-be54-c549fae5ecc8', 9, 'Audio Commentary: Great American Melting Pot', '', NULL, 3, NULL, '2026-04-03T17:13:55Z', '2026-04-03T17:13:55Z');
