INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('0d39e658-509a-4e21-a9be-98edd2936272', '9dff2271-f91b-47c1-a20d-58973840b764', 13, 'The Big Rock', 'Gribbs reads the last poem in the Book of Love and unknowingly turns Fay into a frog. Unfortunately, this is only part one. Snorrison returns when all the adults are transported to the 8th Century AD and the kids take over.', '2000-03-16', 24, NULL, '2026-04-03T17:40:41Z', '2026-04-03T17:40:41Z');
