INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('0d40b8b5-dfc8-4053-b5d3-4f15d0c5d4f0', '6fedba82-52f3-4184-be77-6b26e556cd0e', 1, 'Please Look After This Bear', 'Mr and Mrs Brown are at Paddington Station, they meet a bear, decide to adopt him and name him after the station.', '1976-01-05', NULL, '/mZxTQoCfQVZoTFwFu2LifIbDE6r.jpg', '2026-04-03T17:22:52Z', '2026-04-03T17:22:52Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('0d454534-214f-401d-bd6f-1a57fec393fc', '7b8e3988-fbf3-4cfc-aeb2-782ae5a64e2d', 43, 'The Help-O-Bots', 'Chris reads Elmo, Telly, and Rosita the story of "Rico, the Very Helpful Robot." After hearing it, the three friends decide to become robots to help Chris at Hooper''s store.', '2010-01-05', NULL, '/srBxdCnskGEz6xBaS0KYwEHfgxz.jpg', '2026-04-03T17:36:46Z', '2026-04-03T17:36:46Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('0d478155-b0a7-477f-b381-207aebdae565', '98d80972-e53a-43dd-a03a-7703465e6f87', 12, 'Wouldn''t It Be Ice?', 'Hold steady and fire with Pawn Stars as Rick checks out a Japanese Knee Mortar. Used in WWII for fighting in the dense jungles of the Pacific, will Rick see the chance to make a deal, or does the seller not even have a leg to stand on? Then, Corey and Chumlee read the fine print when an original signed copy of Wayne Gretzky''s NHL contract skates into the shop. Will the guys pass, or take off the gloves and fight for it? And later, Corey continues to push for a partner’s stake in the pawn shop by betting Rick he can make bigger deals. Will the gamble pay off?', '2012-12-03', 21, NULL, '2026-04-03T16:34:18Z', '2026-04-03T16:34:18Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('0d484d65-2e35-4e41-9291-aef2d90b13be', '1d39506b-06b8-4f93-9136-0208069bd7e4', 8, 'Let''s See That Ring', 'Kelly joins Sonja and LuAnn in the Hamptons for gossipy dishing about romance, marriage and under-the-covers relations. In other diva plot arcs, all the ladies attend Kelly''s party, where Bethenny springs breaking news on them and dramas revolve around Jill.', '2010-04-22', 43, '/7YqEUxoBDXAsIiOFGtFYplATTat.jpg', '2026-04-03T16:35:22Z', '2026-04-03T16:35:22Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('0d536315-ee70-4652-a261-bed592cc7837', '41328fef-c185-4924-a8b0-791b5b84f8fd', 1, 'Dear Adil', 'Arthur is excited to have a new pen pal named Adil and fantasizes about what life would be like in Turkey.', '2003-09-15', 13, NULL, '2026-04-03T17:37:57Z', '2026-04-03T17:37:57Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('0d536672-cd77-4551-bbbf-5057cd6ac80e', '05044f49-5f9c-4e7f-a74d-b2ff19475d0e', 16, 'Reunion (1)', 'Host Andy Cohen interviews the housewives about the dramatic events that went down during season six; a conversation prompts Teresa Giudice to leave the couch; Dina opens up about where she stands with Caroline, Jacqueline and the others.', '2014-11-02', 43, '/yziamgCY9Ab2LE12HS76HVU0dhs.jpg', '2026-04-03T16:35:16Z', '2026-04-03T16:35:16Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('0d539ee8-5c52-4557-9ba4-aee71ca9e56f', '27d0351a-92f5-4d01-995c-6b5928957075', 9, 'Not a Yacht of Fun', 'Meredith convinces Jen to include Danna on the girl''s trip, but when Angie K. claims the primary bedroom, she becomes a target; Heather, Lisa and Whitney take sides, but when Angie K. retaliates with an accusation against Jen, it becomes a war.', '2022-11-30', 44, '/qR3jS46EEX3YBjiMEwYFyK4ooch.jpg', '2026-04-03T16:35:44Z', '2026-04-03T16:35:44Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('0d5785a2-9ee2-49d5-b197-a52512e58c52', '4fe93658-c463-4329-8e64-9d523869c2cb', 19, 'Pedal to the Metal', 'The Pawn Stars meet a man with a handwritten lost poem from rock legend Jimi Hendrix. Will the rare Hendrix verse provide new insight into the ''60s icon or will the cryptic words remain locked in a purple haze of mystery? Then, the guys are presented with a chessboard made with wood from one of the most famous ships in history, the Titanic. Will the shop navigate the icy waters to make a deal or will they be forced to stop engines and jump ship? And later, Rick and Chumlee check out a classic child''s pedal car from the 1950s. In need of major repair, will the gang take a chance on restoring this miniature beauty or will missing pieces keep them from trying?', '2011-01-24', 21, '/lownWP2BFdTbwEtqpaDdngWnflY.jpg', '2026-04-03T16:34:16Z', '2026-04-03T16:34:16Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('0d5970e7-0261-4b84-8090-d6ab57a7bd10', '9c5608b2-5111-48bc-a907-7f93472c1e03', 21, 'Lifting Snuffy', 'Snuffy is looking forward to being lifted into the air during a dance that was choreographed by Zoe, but he''s too heavy for his partner to lift.', '2013-03-21', 58, '/hdOAVRcpt6vHsvJtvUjCVLvebrv.jpg', '2026-04-03T17:36:47Z', '2026-04-03T17:36:47Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('0d59c10a-08b1-4bfa-97f0-3c64654121b8', '49a00924-9169-4b3f-b8f0-d7bd68794db9', 6, 'Margs & Marriage', 'Teresa invites Jackie over for a visit; an innocent conversation between Dolores and Paul takes a sour turn when his divorce becomes the focus; Margaret recruits her friends for a charity golf outing; Jen Fessler meets with Jennifer Aydin for lunch.', '2024-06-09', 42, NULL, '2026-04-03T16:35:19Z', '2026-04-03T16:35:19Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('0d5b6c6c-f434-4c7e-95b6-b66e3ac3d990', '55930d10-8ec2-4a20-8c94-52d9b5329bae', 5, 'Kill the Boy', 'Dany makes a difficult decision in Meereen. Jon recruits the help of an unexpected ally. Brienne searches for Sansa. Theon remains under Ramsay''s control.', '2015-05-10', 57, '/25HHLKWpNKiy6e7zBhaoysK9hzv.jpg', '2026-04-03T15:40:37Z', '2026-04-03T15:40:37Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('0d5c262a-6523-4115-b9ff-4829fc91c4f3', '432a6abd-dcca-44cc-82ce-fb39e33b8949', 9, 'Castle Waterfall Pt 4', 'Rogers needs a washer for a fountain he wants to assemble. Instead of taking one from Bob Trow''s workshop, he merely leaves him a note. In the Neighborhood of Make-Believe, the Castle fountain works only to a small extent. Lady Elaine has taken the windmill at Someplace Else apart for unknown reasons.', '1971-02-25', NULL, NULL, '2026-04-03T17:35:39Z', '2026-04-03T17:35:39Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('0d655a23-4099-4fa5-9822-06fc9b6672d6', 'aa3b2cc3-b0cb-4d01-8aa0-694981101aab', 3, 'Time Out', 'Bernard wants to go to the zoo, but his parents just don''t have the time. Bernard, however, has all the time in the world, and decides to clear his parents'' schedules a bit.', '1997-11-28', 15, NULL, '2026-04-03T17:20:04Z', '2026-04-03T17:20:04Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('0d6bba88-ca3f-4ed4-bdcd-5aac97c22493', '3d4d8f6a-9708-47e8-9c99-26ebafdb2609', 17, 'Episode 826', '', NULL, NULL, NULL, '2026-04-03T17:36:41Z', '2026-04-03T17:36:41Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('0d70a5a8-84ba-4326-922c-a04af450f65f', '1e085f65-4b69-4500-8ffc-654d2f638dbb', 13, 'A Home for Fido', 'Chris, Elmo and Abby help Fido feel proud that he''s a frog and find him the right habitat to live in.', '2024-02-01', 26, '/hot2NFjAHu4DAfCzlZjf2X2Nk9Z.jpg', '2026-04-03T17:36:51Z', '2026-04-03T17:36:51Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('0d7334ee-1d65-4717-ae01-125d9088d12f', '04e133fd-c4a3-4dfa-8369-c6dcfd1e3a5a', 116, 'The Grouch of the Year Award', 'Oscar and the Grouches gather to determine who deserves the prestigious Grouch of the Year Award. Various Grouches demonstrate their grouchiness and compete for the title. The competition shows off what makes each Grouch unique and special in their own way.

Sponsors: T, U, 7', '1985-04-29', NULL, NULL, '2026-04-03T17:36:36Z', '2026-04-03T17:36:36Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('0d751b21-5a69-4000-9965-a3b53fc76868', 'a860511c-b630-415e-99a1-a9e0922fbfd7', 16, 'The Butler Did...What?', 'Bailey disappears, and Muffy tries to find him. In doing so she discovers that she doesn''t really know much about her Butler.', '2012-05-25', 13, NULL, '2026-04-03T17:38:00Z', '2026-04-03T17:38:00Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('0d77e49f-95c5-4a32-8044-6a01ffe6be32', 'fd0f7dfb-28aa-4687-9ef8-8ff0088ce25a', 19, 'Judy and the Beast', 'Judy of "Judy and Beast" searches for a new fairy godmother.', '2014-01-23', 58, '/bFnWJVoCKYUBZN4hnhhfEkD9ItX.jpg', '2026-04-03T17:36:47Z', '2026-04-03T17:36:47Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('0d791731-5f65-4422-8ebc-fe2a27170daf', 'bf874be3-7e2f-4a0e-b205-c76ac1ad69fc', 39, 'Inside Looks (on The Letter)', 'Inside look from the season 3 episode "The Letter."', NULL, 2, NULL, '2026-04-03T16:34:08Z', '2026-04-03T16:34:08Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('0d7d3b84-8a25-4988-b16d-5713ba8e089e', 'ca19f895-1514-4988-a709-95e84eab7cee', 6, 'Raiders Of The Lost Pawn', 'There’s a British invasion when a pair of vintage rock t-shirts roll into the Gold & Silver. Do Rick and Chum have the moves like Jagger to seal the deal? Next, Corey and Chum take a drive down memory lane when “Gumby” and “Pokey” toys cruise into the shop. Will the duo stretch for a deal, or say “neigh.” Then, a seller brings in a poster by Israeli artist, Gad Ullman. Will Rick hand over the money, or will he exhibit no interest? And later, Corey and Chum look at unopened Atari games. Can they unlock a deal before it’s game over?', '2020-12-14', 42, '/1nGnANw6tvwBTF7GXfHWyjD86X2.jpg', '2026-04-03T16:34:22Z', '2026-04-03T16:34:22Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('0d7e3587-89a9-423b-b159-b1d2573319b2', '48a6d3b8-3842-41da-aaec-b49a9b65f17f', 5, 'Hiccups', 'Poor Kipper gets the hiccups one warm Summer''s day while having some quiet time in his inflatable paddling pool and his friends, first Pig, then Jake, and finally Tiger give him various suggestions on how to cure them, like standing upside-down and making music and drinking a glass of water from the wrong side, that is until an unexpected and musical surprise cures the hiccups forever.', '1998-10-22', 30, NULL, '2026-04-03T17:10:48Z', '2026-04-03T17:10:48Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('0d7ee273-7be1-49fd-9062-52178625e46a', 'e291df42-d44f-49e5-bf81-2df32ee4a30f', 11, 'Bear''s Secret Cave', 'Pip and Pop, along with Treelo, have decided to go fossil-hunting. They''ve gathered up all their gear in a backpack and are ready to go. This gets Bear thinking about discoveries and how much he enjoys discovering things himself. He then hears Ojo and Tutter calling him. They''ve been searching around the attic and came across an old, dusty box. It turns out to be a treasure chest filled with some of Bear''s old things. He remembers that the played with them all in a secret cave, but he can''t recall just where exactly the cave is. Ojo and Tutter decide to get the help of the rest of the kids to rediscover the secret cave. Once there, they find out some things they never knew about Bear and realize that he''s a lot like them. 

Songs 

I Love to Discover 

A Lot Like You 

Notes 

The kids discover drawings on the wall of Bear''s secret cave. These drawings are of two of Bear''s friends when he was a kid: Don Deer and Roger Badger.', NULL, 25, NULL, '2026-04-03T17:35:32Z', '2026-04-03T17:35:32Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('0d876937-f4cb-4d11-afe3-20e94da5f283', '49a00924-9169-4b3f-b8f0-d7bd68794db9', 13, 'When All Is Said and Done', 'Dolores visits Margaret and Jen Fessler; Tensions run high as Dolores explodes at Margaret after a disagreement; Danielle makes moves regarding her estranged relationship with her dad.', '2024-08-04', NULL, NULL, '2026-04-03T16:35:19Z', '2026-04-03T16:35:19Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('0d8c29dc-e9e1-457b-9c53-9c5a301cc052', '9c9d89df-5f6b-41d0-84c6-b8ca7bd2a2e6', 6, 'Doggie Job Search', 'Brandeis, a yellow Labrador Retriever, is looking for a job on Sesame Street, so Gina trains him for a career as a service dog!', '2021-12-16', NULL, '/8LbUTPVfsZREKwMA2dIEYZRU9oi.jpg', '2026-04-03T17:36:50Z', '2026-04-03T17:36:50Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('0d95ad1f-82ea-4936-9bcf-b01a15f6078a', 'd01919fb-98e0-42bf-b9d9-1cecf912f6e1', 43, 'Maria Babysits Natasha (3828)', '', '1999-02-24', NULL, NULL, '2026-04-03T17:36:42Z', '2026-04-03T17:36:42Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('0d983655-f7fe-43c0-b6ca-695b9a420a29', '32192008-7529-4677-933f-c55ea6146368', 16, 'Driving on Empty', 'As the Colorado trip comes to an end, the ladies are racing against the clock to make it to their final excursion, but things don’t go as planned after Angel takes a wrong turn. Stacey’s character is once again questioned, but this time by one of her closest allies.', '2026-01-25', 54, NULL, '2026-04-03T16:35:42Z', '2026-04-03T16:35:42Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('0d9ada7d-e05d-48d0-802a-74a817fca572', '4d2cac0f-38fd-438b-8afa-acf43952e535', 92, 'Episode 92', 'A magazine programme for younger viewers with Christopher Trace and Leila Williams.  Life in the Royal Air Force: 1: The Fighter Pilot  introduced by Squadron Leader Peter Latham A.F.C., Commander of 111 Squadron ''The Black Arrows''.  Film provided by the Royal Air Force.', '1960-07-22', NULL, NULL, '2026-04-03T17:21:47Z', '2026-04-03T17:21:47Z');
