INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('0d9e7233-fe3c-4cb2-ab9e-36c3a0c150ec', '1c9ea7d3-e254-4e7b-8a9f-33eea9c6c341', 8, 'Head Over Hills', 'Cynthia''s boyfriend, Mike, decides he''s ready to take their relationship to the next level; Cynthia tries to get to the bottom of "Snakegate;" with the opening of The Bailey Wine Cellar, NeNe extends an olive branch to Cynthia.', '2019-12-22', 43, NULL, '2026-04-03T16:34:49Z', '2026-04-03T16:34:49Z');
