INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('0dab518c-c96c-43c2-a445-53c17b9207f3', 'bb919aec-0d5c-4c58-9a5a-fa2a0a5de2b6', 40, 'Episode 445', '', '1973-01-19', NULL, NULL, '2026-04-03T17:36:29Z', '2026-04-03T17:36:29Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('0dac18b1-1ead-4cc7-b3c3-f4bc85e03149', '22beba7f-9b8e-4563-93da-46e76ecba427', 2, 'Show and Tell Elmo', 'Abby goes to the Storybook Community School for the first time, and Mrs. Goose and her class make her feel welcome. But when it''s time for Show and Tell, she doesn''t have anything to share, so she decides to use her magic wand to leave school and ask Elmo for help.', '2006-08-15', NULL, '/tEg9FW95AH2gJTgvXsgC1K1jgEw.jpg', '2026-04-03T17:36:44Z', '2026-04-03T17:36:44Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('0daf8c6a-1478-4349-94d5-4092ac0d0c1f', '5ba20443-d99f-4820-81f6-6832d3f2bc4f', 2, 'Nutrition', 'All food, whether it’s protein, fat, carbohydrates, vitamins, or minerals, is made of chemicals. When your body gets a hold of these chemicals, it recombines them and makes energy. Different types of food make different amounts of energy, which are measured in calories. How do scientists figure out the amount of calories in food? In this episode, Bill will reveal the secrets of the bomb calorimeter – an instrument of food science.', '1995-11-10', 26, '/p3q64EKJSsUHQ9uX1glupScHzMX.jpg', '2026-04-03T17:37:21Z', '2026-04-03T17:37:21Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('0dafae5d-da6c-4c5a-87df-02696adcfd12', '4d2cac0f-38fd-438b-8afa-acf43952e535', 89, 'Episode 89', 'A magazine programme for younger viewers introduced by Christopher Trace and Leila Williams.  Including:  H.M.S. Keppel: 5: The Buffer''s Yeoman.  Members of the ship''s company explain their jobs.  Film specially shot by cameramen of the Royal Navy.  Making Figures from Seashells - shown by Tony Key.  Kidnapped - An extract from the new Walt Disney film.', '1960-06-29', NULL, NULL, '2026-04-03T17:21:47Z', '2026-04-03T17:21:47Z');
