INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('0dbff920-1c89-42fb-80d9-d058255a9382', '61e0c9d9-337e-4fe4-a0fd-e567b29af115', 18, 'Reunion (2)', 'In part two of the reunion, the husbands talk about their role in their wives'' arguments. Tensions reach an all-time high as Meredith attempts to clear her name to Angie''s husband, Shawn, over the rumors that have circled the group for the past two years. Heather challenges Bronwyn''s shifting narrative on her infidelity story with Todd. Mary gives an emotional update on Robert Jr., and the ladies have an impactful and honest conversation.', '2025-01-29', 43, '/sNNrSJiCmBwmOhlamHbGChiuchK.jpg', '2026-04-03T16:35:45Z', '2026-04-03T16:35:45Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('0dc8ecec-2874-4d7f-a3cc-739486bdd4a0', 'e93f04c2-7344-4b93-abba-8ba1b2f8eb35', 31, 'Episode 566', '', '1973-12-31', NULL, NULL, '2026-04-03T17:36:30Z', '2026-04-03T17:36:30Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('0dca71a3-5016-4685-8827-e1c1bec7d0cd', 'f07b8794-5625-4682-aae1-e56966b4c7a8', 13, 'Beautiful Doll', 'Unbeknownst to Julie, Nuzzle has taken her favorite doll. Julie is understandably upset, so Leon decides to conduct an all-out search. Ben and Skye do not appear in this episode.', '1996-01-31', 29, NULL, '2026-04-03T17:12:21Z', '2026-04-03T17:12:21Z');
