INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('0ddf60cd-edb2-4b81-a631-b6dc0f5e1b65', 'a1b69730-d225-48f2-a7e7-1d314cf3b349', 31, 'Episode 31', 'with Valerie Singleton, John Noakes, Peter Purves', '1969-01-09', NULL, NULL, '2026-04-03T17:21:49Z', '2026-04-03T17:21:49Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('0de0ad4d-10a1-46b5-a885-e1c6b148dfc9', '98d80972-e53a-43dd-a03a-7703465e6f87', 28, 'Grand Theft Corey', 'Put the pedal to the metal with the Pawn Stars as the guys check out a completely customized 1932 Ford Roaster. With less than 500 miles on it, will a high asking price put a red light on negotiations? Then, Corey and Chum lee face off against a guy trying to sell a Marilyn Manson Clayton doll. Used in the making of "Celebrity Death match," will they make an offer or is this deal DOA? And later, Rick eyes a diploma from the 1912 Olympics. Awarded for a 2nd place finish in swimming, can Rick turn it into pawn shop gold?', '2013-02-18', 21, NULL, '2026-04-03T16:34:18Z', '2026-04-03T16:34:18Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('0de37e03-775b-4acc-84eb-5033bb8e04b5', '6fd9fd9d-e378-411b-94b1-76ba4bd518fe', 30, 'Episode 30', 'with Christopher Trace and Valerie Singleton.', '1966-01-03', NULL, NULL, '2026-04-03T17:21:48Z', '2026-04-03T17:21:48Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('0de53867-0d1a-4161-958d-60d78c8e2368', 'a1b69730-d225-48f2-a7e7-1d314cf3b349', 4, 'Episode 4', 'with Valerie Singleton, John Noakes, Peter Purves', '1968-10-03', NULL, NULL, '2026-04-03T17:21:49Z', '2026-04-03T17:21:49Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('0dea9d13-b97b-409c-8ff2-d5415047ad6b', '9c9d89df-5f6b-41d0-84c6-b8ca7bd2a2e6', 15, 'Let''s Grow Together', 'Welcome to the Sesame Street community garden! Tamir has an idea: open a garden stand to share what they grow. Alan shares his grandmother’s pickled daikon recipe. Alan''s proud of his heritage and happy to be sharing his family’s culture', '2022-02-17', 26, '/f3uvkbofN62fKnLLGmSuBPcd47L.jpg', '2026-04-03T17:36:50Z', '2026-04-03T17:36:50Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('0df39b44-d54f-46bb-b989-334b1477568e', 'f593d90c-5339-42f5-9c88-5bfd48d04075', 37, 'An Ill Wind', 'The Farmer receives a huge electricity bill and decides to build his own wind turbine to power the farmhouse.', '2010-09-12', NULL, '/cbiJynnZT0r4RBxP2xzwwBYR54G.jpg', '2026-04-03T17:39:31Z', '2026-04-03T17:39:31Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('0dfc166c-ada9-4af4-b284-944923d87561', '208e80de-61e3-4a2f-857f-c667ffc29134', 7, 'Linda Lavin', 'Miss Piggy announces that this show is Kermit''s birthday, and before he can react, she launches into the tribute she''s organized. They''ve planned a This Is Your Life-style show with birthday greetings, including one from Mr. Dawson, Kermit''s old acting coach from Leland, Mississippi. Wayne and Wanda, the singing duo from the first season, show up and give Kermit such a guilt trip that he rehires them. When they sing, Kermit remembers why he fired them in the first place.', '1979-12-07', 26, '/9lsJhWQvy8V1j0puWHf8HIG8rvh.jpg', '2026-04-03T17:35:25Z', '2026-04-03T17:35:25Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('0e00ccb8-1218-4890-b5f8-5bbc6395d179', '272db816-9822-485a-b231-6e060d0ccb1a', 7, 'The Fire Engine', 'Some fire engines will go absolutely anywhere, so long as they don''t get stuck. Then they must not be too proud to ask for help.', '1977-12-01', 5, NULL, '2026-04-03T17:24:25Z', '2026-04-03T17:24:25Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('0e02edd6-2fd1-42a3-954c-b8fdb2ed1658', '5a824218-5831-4c6d-aef3-8b5ba9147532', 26, 'Episode 1601', '', NULL, NULL, NULL, '2026-04-03T17:36:34Z', '2026-04-03T17:36:34Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('0e03fc29-def9-466b-a2d9-3952164b5532', '27a5a980-ec0d-4637-b5ba-df8324a6405a', 13, 'The Map', 'Aunty Ginny''s funeral is the catalyst for Frankie''s vow to begin celebrating all of the family''s major life achievements. Axl mistakenly eats Brick''s school map project and Sue finds out that a boy on the wrestling team has a crush on her.', '2012-01-11', 22, '/coyL5ohuo2sJZL5J8id1K1vDw1X.jpg', '2026-04-03T15:40:29Z', '2026-04-03T15:40:29Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('0e0830fa-46f1-4c30-ac64-aa852c13bf41', '63850e1d-d8ed-4fe4-a068-83cb879c170a', 18, 'The Raincoats (1)', 'Kramer plans to profit from raincoats created by Jerry''s dad; George sells his dad''s old "cruisewear."', '1994-04-28', 42, '/kFbfRlfaCQNvFQC8pSZgLDyEvOF.jpg', '2026-04-03T16:34:11Z', '2026-04-03T16:34:11Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('0e09aa59-8422-43a7-ad1c-0c2c85366b3b', 'ec8d3322-8ca2-4e8d-9d22-268aee320274', 3, 'Pawn Barons', 'When a customer walks into the shop with a camera that shot the first footage of Elvis, will Rick and Corey shake up a good deal, or will they return to sender? Then Chum tries to dig up some info on a mysterious fossil. Is it a dinosaur egg or will Chum end up with egg on his face? Then Rick tries to strike black gold with a Standard Oil stock certificate. Will he buy low and sell high or will the market crash? And finally, Corey chomps his teeth into some Holyfield/Tyson tickets.', '2025-02-05', 42, '/svck1Xjk7Z21jEa4GayRE4pX6Gv.jpg', '2026-04-03T16:34:24Z', '2026-04-03T16:34:24Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('0e0c2ead-f720-4d78-8832-acc91cb61aa4', '387da09c-95c3-49e8-a7ff-fcbb68362cc0', 1, 'Up & Down', 'Rogers and Mr. McFeely ride an elevator and an escalator in a mall, to compare the differences. Lady Elaine accepts the delivery of a hydraulic platform.', '1992-11-23', NULL, NULL, '2026-04-03T17:35:46Z', '2026-04-03T17:35:46Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('0e0d7630-81ff-478b-93c9-d8be81183cfb', '2f8dd629-82c3-4f8e-87c0-963473c49284', 2, 'You Can Run But You Can''t Ride', 'Erin and Sai pick up the pieces after Brynn’s explosive party. Erin opens up about issues in her marriage and Jenna bonds with her son. While Ubah struggles to let her guard down, the ladies take off for their girls’ trip to the Hamptons.', '2024-10-08', 43, '/6TfXYiVv3mHsVvUApA5uZBskdYN.jpg', '2026-04-03T16:35:26Z', '2026-04-03T16:35:26Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('0e130429-24a3-497d-a248-3fb5cd7b1c3f', 'f8b69754-3e41-45e5-832a-64d9c2809ad7', 9, 'Learn To Earn', 'Bernard wants a new skateboard and Pentup Primary decides to pay the students to clean the school. But with Nicolette stealing half the kids'' money, Bernard must do something to get some new wheels.', '2005-03-03', 15, NULL, '2026-04-03T17:20:06Z', '2026-04-03T17:20:06Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('0e18610e-113a-4eb7-8837-a0ea5af3c2c7', 'ecb64ef3-4f80-45a7-b4a9-c04434b02e35', 10, 'Sunday Funday', 'Get ready for the biggest game of the year with the Pawn Stars when a ball signed by NFL hall of famer Walter Payton spirals into the shop. Will Corey be able to keep his head in the game, or will a tough negotiation cause him to fumble? Then, when a program from the first Super Bowl rushes in, Corey is forced to make a game-time decision. Will he score before the clock runs out? And later, all bets are off when the Old Man gets to decide who has to work the day of the big game. Will the guys play by the rules or make an illegal substitution?', '2014-01-30', 21, '/s7xTqbRgol0AlkmhR5Cy9DjbiUt.jpg', '2026-04-03T16:34:19Z', '2026-04-03T16:34:19Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('0e1c9ec5-934d-4dc1-bf5d-6a87050f5660', 'c7ffc8df-4671-47e3-a11b-606828bcb508', 6, 'Cornered', 'Skyler makes an unsettling discovery. Walter, Jr. pushes his dad into a questionable purchase. Jesse offers Mike some unexpected help.', '2011-08-21', 48, '/3tuFJVKzlWRqstoAOxwWF6lPzJY.jpg', '2026-04-03T15:40:34Z', '2026-04-03T15:40:34Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('0e1ce00c-ceda-43d5-8638-6564dea72254', 'f2d25a2b-cdd5-46ba-91f4-e490e0b002e5', 2, 'You and Me and Caveman Makes Three', '', NULL, 29, NULL, '2026-04-03T17:12:15Z', '2026-04-03T17:12:15Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('0e1e0432-fe8f-45f9-9851-cf55134cc24b', 'bd8a516b-9872-472d-a838-7aff1070fea3', 30, 'Loretta Lynn', 'Sketches/Songs: ""You''re Looking at Country"", ""I''m All Alone"", ""Muppet Newsflash"", Fozzie''s Act, ""At the Dance"", ""Sentimental Journey"", ""Oh, Lonesome Me"", ""Veterinarian''s Hospital"", ""Muppet Newsflash"", ""The Rhyming Song"", ""One''s on the Way""', '1978-04-23', 26, '/tvhps4toi2Zl7nG4GCXiKZ42g9D.jpg', '2026-04-03T17:35:24Z', '2026-04-03T17:35:24Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('0e2255df-5845-4bef-a17c-c5798f9d8019', 'ebc99729-ccb7-4d64-82c1-42708cd7ba85', 7, 'Episode 7', 'Introducing ''Muhammad Ali'', Malaysia''s coconut-collecting baboon!', '1980-09-29', NULL, NULL, '2026-04-03T17:21:55Z', '2026-04-03T17:21:55Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('0e263275-11fe-477c-9ade-e5bf302c1018', 'e03d79bd-e01f-4414-b0b3-f3b5f26e97f4', 23, 'The Bridge', 'Frankie and Mike attempt to cure Brick of his irrational fear of crossing over bridges. Meanwhile, Axl is pitted against nemesis Sean Donahue when a lifeguard position opens up at the local public pool, and Frankie is ready to pull her hair out when she tries to help an indecisive and emotional Sue pick out a two-piece bathing suit to wear on the pool''s opening day.', '2011-08-05', 22, '/k3ztA0OTDJHMv882vQhnwsKUrnB.jpg', '2026-04-03T15:40:29Z', '2026-04-03T15:40:29Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('0e2fe717-2633-415d-98f4-1dbe8406480e', '20d7138e-eea8-46a8-8ada-2b0f0ee1f674', 55, 'Episode 55', 'Chocolate Surprise

Beat the prices in the shops this Easter with a home-made Chocolate Egg Cake. Chef Duncan reveals a secret ingredient that guarantees you will surprise and delight your family and friends!', '1983-03-24', NULL, NULL, '2026-04-03T17:21:56Z', '2026-04-03T17:21:56Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('0e368753-c026-437c-8c0c-cfdf3b3931f2', '7ccd5605-fe0b-4e00-ae7f-3e3daa252f8b', 13, 'Let''s Bow Our Heads and Pray', 'The ladies are finishing their lunch in San Francisco. What started out as a fight between Alexis Bellino and Vicki Gunvalson ends up with everyone taking the opportunity to tell Vicki just what they think of her. Back in Orange County, Lynne’s daughter, Raquel, tells her friends about the family’s eviction. Tamra Barney and Vicki try to figure out where their friendship stands. Alexis and her husband, Jim, invite their pastor and his wife to breakfast. They talk about the role of modern day Christians and how Alexis feels judged for her beauty and looks. Gretchen and her boyfriend, Slade Smiley, are off to Palm Springs for a weekend getaway with her parents. It’s Tamra’s 42nd birthday and her husband, Simon, takes her out for a romantic dinner.', '2010-02-18', 44, '/jqZfHWK2E7ZX3oPkBMxiO9MD6D5.jpg', '2026-04-03T16:35:31Z', '2026-04-03T16:35:31Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('0e39912c-5127-444f-bebc-94f89d652f37', '21745b85-d269-42fa-b4dd-701b2da5c085', 14, 'Episode 14', 'with John Noakes, Peter Purves, Lesley Judd', '1973-10-25', NULL, NULL, '2026-04-03T17:21:51Z', '2026-04-03T17:21:51Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('0e46253a-7d27-4b2d-8c3d-c273b7c03ce2', '7c756336-29db-4634-b976-e993e8f51da2', 3, 'Hold Your Horses', 'The ladies of Potomac get decked out in their best hats and are off to the races for one of Baltimore''s elite events, The Preakness Stakes. Charrisse continues to reinvent her life by gifting herself a new champagne room. Karen welcomes her daughter with open arms, when she returns home for the summer. Robyn struggles to answer questions about her relationship status with Juan. Meanwhile, Monique heads to the "Dirty South" to celebrate her husband''s induction into the Alabama Hall of Fame, where she also reunites with her "Monster-In-Law" for the first time in months.', '2017-04-16', 42, '/3Wn9PdBpLpHWccrKE4Qw5ylhuR9.jpg', '2026-04-03T16:35:38Z', '2026-04-03T16:35:38Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('0e474bac-5e94-4876-a9ba-685ba87619f0', '151e88a1-9576-4bd1-b84a-c4d64c1c9fe8', 3, 'There''s Sutton About Crystal', 'Kyle invites her friends to the desert for the launch of her new store. Sutton apologizes to Dorit for seeming unsympathetic following her traumatic home invasion. Garcelle urges the women to be up front with each other. While Erika and Diana point out that all their problems share a common denominator, Crystal winds up triggered by a past offense and Lisa feels they''re all missing the point.', '2022-05-25', NULL, '/eENOdnVnvgqn7awGnoKzdBK5DkD.jpg', '2026-04-03T16:34:58Z', '2026-04-03T16:34:58Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('0e47f7f8-ffdf-42db-b4b2-e1eecf7cbc95', 'db555b98-87d6-4cd2-b7b4-973f9206cb1e', 20, 'Whooping It Up for Wedding Bells', 'Shannon goes on a date with a man who she plans to invite to Vicki’s engagement party. Emily helps Gina pack up her Coto house. Braunwyn and her mom Dr. Deb meet for yoga while continuing to avoid their unresolved issues. Emily is surprised at a medical diagnosis. The ladies celebrate Vicki’s engagement with a “farmhouse chic” party, but Tamra melts down after seeing Kelly.', '2019-12-17', 44, '/us8O6RqzBjvYN5g4RxPKJ294Pcx.jpg', '2026-04-03T16:35:34Z', '2026-04-03T16:35:34Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('0e4df98d-410c-4515-b58f-828027d916a5', '3ee646e8-23ae-4dec-bbc6-c7e6a210d55b', 99, 'Peck at Birdland', 'Big Bird reads a large sign posted in the yard for Elmo and the Birdketeers, advertising a "Peck" this afternoon at Birdland. He demonstrates to Elmo how birds peck, and Susan can even do it too and plans to go. At Birdland, Hoots the Owl shows off the pieces of his new dance floor for the peck tonight.

Sponsors: G, L, 5', '1991-03-28', NULL, NULL, '2026-04-03T17:36:38Z', '2026-04-03T17:36:38Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('0e4faaed-5265-45ac-b272-481a8490b17e', '2b968a9c-5fc0-4e93-bcf9-31d3e4c7b210', 61, 'Episode 61', '', '1976-04-08', NULL, NULL, '2026-04-03T17:21:52Z', '2026-04-03T17:21:52Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('0e55e7e7-1d44-48bd-bf85-b07b7efc3c62', '190c6e49-8849-4404-87d4-eaef943a6024', 2, 'Oakie Doke And The Nut Mystery', 'Doke helps Rufus to find his missing nut stash and Rose to find Root using Manny''s water detector. They find Root fast asleep in a hollow tree along with the nut stash Dave and Denzil stole.', '1995-09-18', 10, NULL, '2026-04-03T17:19:24Z', '2026-04-03T17:19:24Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('0e5756cd-8634-430e-b01b-b3e9bfa96c9f', '9d74600d-7222-47c1-bd1b-635f5b41b7d1', 9, 'Germs Make Me Sick!', 'LeVar goes on a search for microorganisms, distinguishing the good ones from the bad. An animated satire of Hill Street Blues (which ran 1981-1987) shows white blood cells ready to fight germs. Molly Mandlin reads Germs Make Me Sick!, explaining how people can catch colds and diseases from exposure to germs.', '1986-07-03', 30, NULL, '2026-04-03T17:36:15Z', '2026-04-03T17:36:15Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('0e580ab1-b75c-493f-804e-415255fa91f7', 'f21ca545-466c-448c-ada5-b8acc8b856dc', 3, 'Time and Again', 'Bernard and his Dad go fishing which causes the magic watch to break, Bernard is very upset however the postman steps in and saves the day.', '1999-09-24', 15, NULL, '2026-04-03T17:20:05Z', '2026-04-03T17:20:05Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('0e5e0052-21b4-4e53-976b-bab4aba1879f', '3982796b-5451-4100-9042-46bedf6a20a5', 26, 'Pingu Builds a Snowman', 'Pingu and Pinga get up to find a nice fresh fall of snow outside. They go off in the sledge to have some fun, but hit a bump sliding down a hill and get thrown off. They decide to build a snowman and have made a start when Robby turns up and suggests it should be a big one. They all agree, and Robby helps to gather the snow to form the bottom half. They make a ball to put on top for the body, but have difficulty getting it up and making it stay on. Pingu then spots a nearby signpost, used by hikers to find their way, and has the idea of using this to support the snowman. Pingu and Robby roll the balls of snow across and build up the snowman around the signpost, covering up the signs with snow to form the arms of the snowman. They then have problems trying to get the head on, as it’s so tall. Pingu has another idea and goes off on the sledge, and Pinga and Robby work on finishing off the body of the snowman. While all this has been going on, a hiker has been wandering around nearby, clearly lost. He spots Pinga and Robby, and comes over to them. Pinga and Robby ask him for help with the snowman, and he kindly puts on the head and makes it appear that the snowman is on a hike by adding a rucksack and a pole on his shoulder with a bag. The hiker asks Pinga and Robby if they know the way, but they say that they don’t, so the hiker wanders off again. Pingu then arrives back on the sledge with a ladder, and a carrot in a bucket, and is surprised to see the finished snowman. He wonders how Pinga and Robby did it. The hiker then returns, having found a sheer cliff in his way, and asks them again if they know the way. As they’re about to reply the snow falls off one of the snowman’s arms revealing the sign, to the hikers surprise. The hiker brushes off the snow on the other arm, which to his relief tells him the way he needs to go.', '1994-12-20', 5, '/uZKBSloU28eyrGGBFy61HptAyMe.jpg', '2026-04-03T17:22:19Z', '2026-04-03T17:22:19Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('0e6066b6-3eaa-4ab1-887d-d82dd4cca60a', 'd5f0284f-0ee3-45bf-8539-d02a825d15b2', 6, 'Farmer of the Opera', 'Julia surprises Martina with an opera performance she will never forget; Guerdy puts Larsa on blast for broadcasting her cancer diagnosis; Lisa hosts the ladies in Palm Beach, where Julia begins to question her growing friendship with Alexia.', '2023-12-06', 44, '/cXBC3m3jZ3TAcKZWG2xaxmPfEnF.jpg', '2026-04-03T16:35:12Z', '2026-04-03T16:35:12Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('0e669151-1124-4fb7-a00e-775e27c2699a', '9e4790f4-3aab-459c-a5ed-7100b4e39a75', 16, 'Reunion (2)', 'Tensions escalate as Sai opens up about her relationship with her mom. Brynn breaks down when sharing more about her childhood.', '2023-10-29', NULL, '/sIbb2P0lWSj4ZUN6DLoiwx6k6Es.jpg', '2026-04-03T16:35:26Z', '2026-04-03T16:35:26Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('0e70541d-e37e-4a01-b833-c3d8789388d5', '31feb548-2e4c-45db-9c77-61f2bc7451f5', 5, 'Muffy''s House Guests', 'Muffy is terrified when peregrine falcons build a nest outside her bedroom window.', '2019-05-15', 13, '/oqptx0EsRcGC0Y3O6qNOj0rtuan.jpg', '2026-04-03T17:38:03Z', '2026-04-03T17:38:03Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('0e773687-06fa-4bb0-9764-1d9e9caa6310', '6e0be2a3-a234-453b-abb7-0ba535a93601', 17, 'Franklin''s Rival', 'Franklin feels challenged by the affections of another kid Granny is babysitting.', '2000-07-02', 12, NULL, '2026-04-03T17:40:15Z', '2026-04-03T17:40:15Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('0e78d48f-2dfa-4286-aac3-c6b7ca5562b8', 'dbd3583f-e9b2-46d1-a37e-309eb666e233', 8, 'New Tricks', 'With her townhouse bursting at the seams, Kim and her newly expanded family move into a mansion of their dreams. Shereé and Phaedra''s relationship gets rocky as they deal with the aftermath of their court battle against Sheree''s ex-husband. Meanwhile, Kandi decides to steer her music career in a surprising new direction. Cynthia throws a grand-opening bash at her modeling school, the Bailey Agency, where Kim and NeNe rub elbows for the first time since Cynthia''s wedding.', '2011-12-18', 43, '/tHGKcsCa5f9Fn1I55e2wyT3g0Rh.jpg', '2026-04-03T16:34:45Z', '2026-04-03T16:34:45Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('0e7c4c70-1d4c-4b36-8530-10bacc850a57', '136b81d3-964d-4b8f-a214-92f00d96d6b9', 54, 'The Daily Bird', 'Big Bird creates his own newspaper, "The Daily Bird," with reporters and photographer Telly. They cover mundane stories and attempt to photograph Snuffleupagus as proof.

Sponsors: E, F, 12', '1984-02-02', NULL, NULL, '2026-04-03T17:36:35Z', '2026-04-03T17:36:35Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('0e89a6a5-37ee-40e9-850f-d1fcb979bbfa', 'c373abed-50ef-417e-9f34-4e9050611a1b', 5, 'The Party Is Done', 'Tamra''s explosion at the party has widespread effects, leaving Vicki torn between Tamra and Alexis; Gretchen goes to New York to support Slade; Lydia encourages Alexis to make amends.', '2013-04-29', 44, NULL, '2026-04-03T16:35:32Z', '2026-04-03T16:35:32Z');
