INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('0ea400dc-f840-4eea-a22e-c68a99c0dd31', '42e591e2-2a88-4434-ae9f-3d4b1d685613', 12, 'Fool''s Gold', 'Prepare for liftoff with the Pawn Stars as the guys check out a toilet seat from the NASA Space Shuttle program. Will this deal leave them flush with cash? Then, Corey''s offered a signed copy of Fear and Loathing in Las Vegas. Including a personal inscription from author Hunter S. Thompson, will Corey try to pick it up, or is the seller trippin''? And later, the Old Man sends Chumlee on some fool''s errands. But who will have the last laugh?', '2013-07-11', 21, NULL, '2026-04-03T16:34:18Z', '2026-04-03T16:34:18Z');
