INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('0ee302da-0ad7-4b96-8229-eaa120f1348a', 'bd8a516b-9872-472d-a838-7aff1070fea3', 9, 'Dom DeLuise', 'Miss Piggy hires Scooter to pay off the audience to go wild for her. She also has him send her dozens of bouquets and write her piles of fan mail, all part of an attempt to get Kermit to notice her more. Piggy and Scooter stage a conversation for Kermit to overhear, in which she pretends to have an offer from another show, but Kermit isn''t fooled. After finding out from Scooter what''s really going on, he tells Piggy he''s heard about her offer and has decided to let her go. When she breaks down in tears, sobbing that she can''t leave him, Kermit agrees to take her back, but at a lower salary. After all, if she can afford to have Scooter pay off the audience for her... Miss Piggy gets hysterical and depressed, but is refreshed by Dom DeLuise.', '1977-11-25', 26, '/tzUqIAG9GyX5knIGetjEqFGITIL.jpg', '2026-04-03T17:35:24Z', '2026-04-03T17:35:24Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('0ee502b6-9659-40e2-9af7-ec373cfa75b4', '5c1b881f-ac58-4d72-b63f-209952d4f902', 59, 'Episode 59', 'Dr Who''s Spring Clean  The BBC''s travelling Dr Who exhibitions are constantly changing to keep pace with the latest monsters the Doctor tackles. Tina goes behind the scenes, to lend a hand with this very unusual spring clean.', '1980-04-03', NULL, NULL, '2026-04-03T17:21:54Z', '2026-04-03T17:21:54Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('0ee7e058-afab-4c35-8121-0656f0a26944', '151e88a1-9576-4bd1-b84a-c4d64c1c9fe8', 12, 'Beverly Hills Blackout', 'Diana apologizes to Garcelle for acting out at her birthday party. Lisa has a frank conversation with Erika about her recent behavior. Kathy’s prank annoys but doesn’t surprise Kyle. Dorit isn’t happy about PK’s brush with the law and makes her feelings clear. Sutton dips her toes into the dating pool and makes a memorable impression on her Bumble match.', '2022-07-27', NULL, '/9yW8L0jkkGaCaYG7F3HIwD6s5ZA.jpg', '2026-04-03T16:34:58Z', '2026-04-03T16:34:58Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('0eeb46c3-9df0-460a-b01c-5ad00477bc91', '1415ef1c-411a-4c26-814a-7c79c3628bc2', 6, 'Wishful Invitation', 'Carole attends the memorial service Dorinda has for her husband, Richard, who died five years ago. Bethenny considers upgrading to a larger apartment. Tensions between Sonja and Tinsley are on the rise as Sonja blames her for everything wrong in the townhouse, forcing Tinsley to think about moving into her own place. Dorinda and the other bridesmaids get a sneak peek at Luann’s wedding dress. Over group drinks, Ramona first questions Luann about not being invited to her wedding and then decides to confront Bethenny yet again.', '2017-05-10', 60, '/qAPHJFbaByNtBwqLqQCwW2URQzT.jpg', '2026-04-03T16:35:24Z', '2026-04-03T16:35:24Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('0eedf858-ac0b-4d6a-94bd-9b8bcd958256', 'f4c40307-9b5e-4263-a4e0-dfa138131e7f', 49, 'Bert and Ernies Great Adventures', '', NULL, NULL, NULL, '2026-04-03T17:36:27Z', '2026-04-03T17:36:27Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('0ef01950-b075-4a2f-8e25-51755e69f77d', '943b0c94-0cc5-40e8-a0e1-bd5660772cc3', 11, 'This Party is Toast', 'Carole throws a holiday bash, and Aviva''s libidinous father is among the partygoers. Elsewhere, Sonja arrives at her photo shoot an hour late, irking Heather; Carole completes her book and invites the ladies on an island getaway to celebrate.', '2012-08-13', 60, NULL, '2026-04-03T16:35:23Z', '2026-04-03T16:35:23Z');
