INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('0f0bf809-323a-46ad-9918-dcba75680a57', 'bfdf87ff-01dd-4b54-94bd-19b384f41bdb', 21, 'Reunion (3)', 'The reunion concludes with the ladies recounting their traumatic experience in Glamis. Old wounds are opened as Meghan finds herself on the defensive for her lack of sympathy towards Vicki after the accident. When the ugly drama of Ireland is discussed, emotions run high and Shannon is driven to her breaking point.', '2016-11-21', 44, '/iJyvGUTY0xcuqeoetUzFBl78BvI.jpg', '2026-04-03T16:35:33Z', '2026-04-03T16:35:33Z');
