INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('0f1e44c0-305e-47ee-8ade-4df0b65ca305', '4c79c0b6-21a4-4277-8967-be1e791efdbe', 16, 'Pingu Wraps Up', 'Mother is ironing, and Pingu is chasing Pinga around the kitchen. Pinga then crashes into a chair, hurting her foot, and Mother rushes to console her. Mother decides that the foot needs a bandage. Pingu gets the first aid box out and Mother wraps up the foot. She goes to get the scissors to cut the bandage, but while she’s gone, Pingu finishes off himself by wrapping Pinga’s other foot and her arm. He then goes outside with the first aid box wondering what to wrap next. He starts with the snowman’s head, and then wraps Fathers motorised sledge. He calls in on Grandfather, and Grandfather lets Pingu wrap him up. Pingu leaves without unwrapping him, to Grandfather’s dismay. Grandfather tries to eat his sandwich, without success, then struggles across to the phone to call for help from Father. Meanwhile Pingu has wrapped the sign outside the bakery, some skis he found outside another igloo, a stranger on a bench next to a sign, and the bench and sign. Father arrives on his skis to untie Grandfather, and then goes off to find Pingu by following the trail of wrapped items that Pingu has left behind him. Pingu and Father then return, unwrapping the items, including the stranger, on the way. Pingu is riding on the front of the skis when they crash into a block of ice and tumble off, breaking a ski. They wonder what to do, then Pingu uses his skill in wrapping to bind up the broken ski so that they can finish their journey.', '2005-12-01', 5, '/4DxQMR05bD64CLVpsrfZse3D4EE.jpg', '2026-04-03T17:22:20Z', '2026-04-03T17:22:20Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('0f1ee1a5-1336-485a-b12c-c96ea683ab61', '27d0351a-92f5-4d01-995c-6b5928957075', 12, 'White Lies and Black Eyes', 'While the ladies are still in San Diego, Calif., a dark cloud looms above as the group tries to get answers about Heather''s black eye; Lisa learns that Meredith has been spreading rumors about her businesses.', '2022-12-21', 44, '/uWh9uNr4oblZmapjnI1HVxAhUYZ.jpg', '2026-04-03T16:35:44Z', '2026-04-03T16:35:44Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('0f202f8e-1dd7-4eb6-be12-9888a40f3dd8', 'e2aa3158-68e5-494f-951a-498ca0518dbb', 14, 'The Skateboard', 'Shaun decides he wants to have a go at skateboarding and sets about building a skatepark.', '2012-12-08', 7, '/A1QVd4XdollqJBpPwszP1d1DEYy.jpg', '2026-04-03T17:39:32Z', '2026-04-03T17:39:32Z');
