INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('0f8ab96c-2e08-4816-8f20-64236be312b5', 'bff09904-103d-4ae2-9c13-c1febc903a46', 5, 'Work Song', 'This week''s episode is about performance. In "When Aunt Lena Did The Rumba" a little girl puts on her own musical to cheer up her sick Aunt Lena. The Boy''s Choir of Harlem shows us the beauty of music through voice. Comedian Peter Patovsky shows how he makes people laugh. Then travel to Broadway for a glimpse of the hit musical "CATS". Books featured this week are "My Mama Had a Dancing Heart", "The Dancing Man", and "The Old Man Who Loved To Sing".', '1998-10-09', 30, NULL, '2026-04-03T17:36:20Z', '2026-04-03T17:36:20Z');
