INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('104219ac-d1f2-47c8-9f9e-ad4ba7ec66c1', '94efc131-3a47-4bcb-a519-330e791ce905', 4, 'After the Storm', 'It is a bright Autumn day and all the animals are playing in the fallen leaves which Percy has been trying to sweep up!!! He tries to get them to tidy them up again, but they make even more mess. Eventually, though, they finish, but it begins to rain. Everyone says goodnight and hurries to their tree, except for Squirrel, who has moved out due to the noise Owl has been making.', '1998-01-01', 15, NULL, '2026-04-03T17:19:01Z', '2026-04-03T17:19:01Z');
