INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('10541ac3-22fb-4fb7-b8b1-58989f2f7ff9', 'ecb64ef3-4f80-45a7-b4a9-c04434b02e35', 26, 'Brew Master', 'Risk it all with the Pawn Stars when a medal believed to be a Polish White Eagle soars into the shop. With no time to call an expert, Rick must decide whether to go all in or sit this one out. Then, Corey and Chumlee race to check out a brick from the Indianapolis Motor Speedway. Will they go full throttle for this piece of racing history or will it pass them on the turn? And later, Chumlee gets knee deep in hops and yeast to make the perfect home brew. Chum knows he can lead Rick to beer, but can he make him drink?', '2014-03-27', 21, '/pts0x3Ihhy9vOMDEmi5DPxjGgXt.jpg', '2026-04-03T16:34:19Z', '2026-04-03T16:34:19Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('1062d978-aad1-4edf-9f99-1b48fb058a99', 'b86d15ea-4253-41a5-9f14-4a254ec601e0', 17, 'Hair We Go Again', 'Caroline''s boys open their new restaurant; Melissa goes to Orlando for a live radio performance; Teresa and Jacqueline face their enemies at the opening of their boutique.', '2013-09-22', 43, '/6EzQ6KwGmt1LWoXM3gxDQZ2V9lD.jpg', '2026-04-03T16:35:16Z', '2026-04-03T16:35:16Z');
