INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('106827fd-0857-4650-a804-42f10c914d92', 'e9352408-a84b-4c1a-905c-7aa862062f7f', 19, 'Bouncy Castles', 'Pat notices a bouncy castle and visits Gaz Inflatables which makes them.', '1995-05-19', 10, NULL, '2026-04-03T17:19:37Z', '2026-04-03T17:19:37Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('10696652-4c9f-49d7-923d-3caca32c4769', '87989283-6fea-40d7-8d91-22c4947db105', 7, 'Why Not One House?', 'Janelle moves (again!) to be closer to her Sister Wives. Kody won''t let go of his dream to live all under one roof but the wives can''t agree to do it. Robyn wonders if they have failed as polygamists if they can''t live together.', '2020-02-16', NULL, NULL, '2026-04-03T16:34:31Z', '2026-04-03T16:34:31Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('1075269f-47bb-40b8-b20b-0081e6faa196', '7c756336-29db-4634-b976-e993e8f51da2', 1, 'Don''t Let the Zip Code Fool Ya', 'Gizelle and Charrisse’s friendship hangs in the balance following Gizelle''s shocking accusation that Charrisse is cheating on her husband. When the two ladies finally get together to talk, all bets are off! Meanwhile, Ashley’s involvement in a new charity threatens her responsibilities to her and Michael’s restaurant, causing tension in their marriage. Also, Robyn and Juan adjust to their new lives outside of Potomac, while Karen and Ray butt heads as they hunt for a new home.', '2017-04-02', 42, '/uKCi4h7paImEiWGlSsKVctUpzxZ.jpg', '2026-04-03T16:35:38Z', '2026-04-03T16:35:38Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('107650c4-45f4-4287-b472-61501f0eab19', '5144de59-e67f-4fcf-919b-7106989ab797', 28, 'Owning It', 'Leon obtains a new watch but drives everyone else crazy with it, causing them to snap back at him. Kiki is preparing chili in the kitchen, and Sizzle and Nuzzle want to taste it so badly.', '1995-02-22', 29, NULL, '2026-04-03T17:12:21Z', '2026-04-03T17:12:21Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('1080e30c-dcf6-4527-8a84-9b2997724c83', '5a6d9a42-165b-4b56-9273-0a06874dfe10', 5, 'Madeline and the Gypsies', 'Pepito invites Madeline and the girls to a Gypsy carnival.', '1991-10-14', 23, NULL, '2026-04-03T16:34:01Z', '2026-04-03T16:34:01Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('10855c94-5e07-42e4-867f-71d122edc05c', '8b6bbac8-e5ef-49c7-a5c1-197cfb19f772', 17, 'Mister Rogers Talks to Parents About Competition', 'Rogers discusses with parents combative attitudes.', '1981-05-30', NULL, NULL, '2026-04-03T17:35:42Z', '2026-04-03T17:35:42Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('108eeed3-0b73-4aca-b576-aea95284594e', '3982796b-5451-4100-9042-46bedf6a20a5', 3, 'Pingu and the Seagull', 'It is a nice day and Pingu is out riding his brand new blue scooter. Circling overhead is a Seagull. It squawks, and Pingu hoots back and waves to it. The Seagull then poos on the scooter, rather annoying Pingu. Pingu goes indoors, cleans up the scooter and puts a cover over it. He then goes outside again. The Seagull is now sitting on top of the igloo, and squawks when it sees Pingu. Pingu makes a snowball and throws it at the Seagull. The snowball narrowly misses as the Seagull takes off. The Seagull retaliates by pooing on Pingu''s right foot. Pingu cleans himself off, and then spots that the Seagull has landed on the ice nearby. He tries to grab it, but it takes off and flies out of reach. The Seagull lands again, and Pingu has another attempt at grabbing it, but this try also fails. The Seagull lands for a third time, but this time Pingu sneaks up on it from behind and succeeds in getting hold of its legs. The Seagull tries to fly away, and eventually Pingu has to let go. The Seagull circles around, and poos on Pingu again, this time on his right shoulder. The Seagull then lands to have a drink from a nearby ice hole and is grabbed on the beak by a lobster, which won’t let go. After initially being amused, Pingu takes pity on the Seagull and tugs the lobster off. The lobster turns on Pingu and follows him into the igloo. Pingu eventually chases the lobster away and back into the pool by banging some pan lids. He pets the Seagull, and just when he thinks he’s made friends with it, it flies away and poos on him yet again, right on the top of his head. He goes inside and tells Mother all about it, and she washes his head clean.', '1992-01-05', 5, '/isIXUg1LVoPnnHxG5RUiPAlFbVv.jpg', '2026-04-03T17:22:19Z', '2026-04-03T17:22:19Z');
