INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('10b4fb1b-3980-49e8-884b-3c4a8708fa8b', '97a3d1f5-a8f1-47cd-8122-2e74a092836d', 26, 'What''s Up With Alex? (2)', 'Lenni finds out Spencer has something to do with how Delilah knew where to get her tape recorder.  Tina and Hector go on a stakeout by taping Big Ralph.  They find out that a kid is involved, but they don''t know who it is.  Big Ralph gets arrested in the meantime.  Also, another student, Jason, had a gold bracelet stolen from his locker.  A boy named Arnie is also acting suspicious about the fact he has Maria''s camera.   In the meantime, Alex is playing at a Dragons game.  After their victory, Kevin wants to celebrate by smoking pot, which Alex doesn''t want to do.  Alex turns him down.  Kevin doesn''t show up for school the next day, so Alex is now behind on a project he''s supposed to do with Kevin.  Kevin offers Alex pot again, but accidently leaves a joint behind, which Gaby finds.  Gaby writes Alex a heartfelt letter about why he shouldn''t smoke marijuana, which he takes with him on his way to Kevin''s house.', '1994-04-17', NULL, NULL, '2026-04-03T17:40:28Z', '2026-04-03T17:40:28Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('10bd715a-e32e-4484-93d6-d48ed0a11d34', 'bb919aec-0d5c-4c58-9a5a-fa2a0a5de2b6', 82, 'Episode 487', '', '1973-03-20', NULL, NULL, '2026-04-03T17:36:30Z', '2026-04-03T17:36:30Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('10c32910-8136-48f9-9745-2dbc571561a2', 'bd8a516b-9872-472d-a838-7aff1070fea3', 6, 'Rich Little', 'Gonzo auditions real chickens for his dancing chicken act. Due to a last-minute cancellation, he finally gets on stage, but his chicken Lolita hardly moves.', '1977-11-04', 26, '/3vzzbzkXPAgc82OP2MxdfTvr8zV.jpg', '2026-04-03T17:35:24Z', '2026-04-03T17:35:24Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('10c50873-fa7a-4ef4-bf61-95f005d37184', '22beba7f-9b8e-4563-93da-46e76ecba427', 6, 'Snow White & The 6 Dwarves', 'Snow White (Amy Sedaris) visits Sesame Street with her dwarves.  One by one, each dwarf leaves the group, and soon Snow White ends up with ZERO dwarves.  Can Elmo save the day for Snow White?  Also in this episode: Bert and Ernie sing about circles and Grover learns how to ride a bike.  This episode is brought to you by the letter O and the number 7', '2006-08-22', NULL, '/sjuvKOH8Snmb6QesGMzQmZhyEjZ.jpg', '2026-04-03T17:36:44Z', '2026-04-03T17:36:44Z');
