INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('10dd3652-bb24-4a82-aa93-53eabaa5db54', '2f5a4ffe-2548-4181-85ac-6145cb3e3bf7', 1, 'Meri, On Her Own...', 'Meri''s offer on the B&B is accepted! But she doesn''t have enough cash for the down payment and asks the family for help. Kody steps up, but later, he realizes he doesn''t have the money and reneges, leaving Meri to come up with the money on her own.', '2019-01-20', NULL, NULL, '2026-04-03T16:34:31Z', '2026-04-03T16:34:31Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('10e59b2b-9b28-4f79-80d6-a85a6ace076c', 'da06465b-9154-4feb-a455-374df7dab02f', 4, 'Birdseed Cookies For Granny (4086)', 'ig Bird’s granny is coming to Sesame Street, and with Alan’s help, Big Bird bakes“The World’s Greatest Birdseed Cookies” for her. Big Bird and Alan have gatheredall the ingredients they need- birdseed, applesauce, bananas, porridge and cinnamon. Then, Baby Bear comes in wanting his porridge, but tries a healthy fruit saladinstead of his usual since Big Bird and Alan need the last bit of porridge to makethe cookies. As Alan and Big Bird continue to mix the ingredients, The Count comesin to help them count and figure out how many cookies they will be able to makewith the dough.', '2005-04-07', NULL, NULL, '2026-04-03T17:36:44Z', '2026-04-03T17:36:44Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('10e83e5a-b3b2-48f4-b18d-af49271ea1e8', 'c4d795ae-6afa-47d6-9819-4dd057030a3c', 5, 'Tatted Tales', 'Kandi gets advice from the women about sharing details from Porsha''s boyfriend''s past; Eva''s mother pushes her daughter''s buttons regarding the wedding''s budget; Shamari reveals more details about her open relationship with her husband.', '2018-12-02', 43, NULL, '2026-04-03T16:34:48Z', '2026-04-03T16:34:48Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('10ecab5d-a7a3-4919-8f98-387e255ade75', 'e48599f8-66ff-4c0f-9274-65b9ae1cda9e', 34, 'Episode 34', 'Blue Peter film cameras take to the high seas when Lesley meets the crew of HMS Dance, alias ''HMS Hero'' of Warship fame.', '1977-01-10', NULL, NULL, '2026-04-03T17:21:53Z', '2026-04-03T17:21:53Z');
