INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('111ef26c-e48c-4753-bf72-cacbb8d1b72f', 'f6015d9a-ece4-414a-a00b-06cf689fe40b', 7, 'Winter Sports Special', 'To celebrate the Winter Olympics, Blue Peter brings you a snow sport special! Radzi takes on a very special skeleton bob challenge, Lindsey gives snowboarding a go, and the two go head to head In a speed skating race! Where better to bring you a show full of action on ice, than the Swiss Alps?', '2018-02-10', NULL, NULL, '2026-04-03T17:22:10Z', '2026-04-03T17:22:10Z');
