INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('113d270d-88b9-44de-b574-a6fd138562eb', 'ad4e4348-3334-4a08-8928-455d9ba524c1', 1, 'Roger Moore', 'Kermit calls the Secret Service to hire real spies for Roger''s closing number. (They''re listed in the Yellow Pages.) However, Roger wants to do a cute, cuddly version of "Talk to the Animals". The spies, anxious for a chance to rub out James Bond, pose as fluffy animals to infiltrate the number.', '1980-10-05', 26, '/g21w8HBqeJoBvnqsy1qu3hr0ioa.jpg', '2026-04-03T17:35:25Z', '2026-04-03T17:35:25Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('114152e5-0a5b-4eaa-90e5-42237efd3dd7', '190c6e49-8849-4404-87d4-eaef943a6024', 11, 'Oakie Doke And The Monster', 'Doke babysits the tadpoles for Grannie Annie and Shrimp for Mrs. Tickle. Meanwhile Snoot spots what she thinks is a monster, but it is actually Lizzie''s papier-mâché mask.', '1995-11-20', 10, NULL, '2026-04-03T17:19:24Z', '2026-04-03T17:19:24Z');
