INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('11480918-a509-4ede-b7c0-438703f45ab3', 'f4c40307-9b5e-4263-a4e0-dfa138131e7f', 124, 'Christmas Eve on Sesame Street', 'Christmas Eve is upon the entire Sesame Street gang in this funny and sweet one-hour television special. Oscar the Grouch has Big Bird worried about Santa Claus arriving and bringing everyone presents.', '1978-12-03', NULL, NULL, '2026-04-03T17:36:27Z', '2026-04-03T17:36:27Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('11482bdb-ddc9-4594-8cd9-a40654fbfe9d', '3b154d00-cb7b-49c4-a053-6ebbbe906eba', 17, 'Telly is afraid he''ll hurt Baby Bear (4047)', '', '2003-04-29', NULL, NULL, '2026-04-03T17:36:43Z', '2026-04-03T17:36:43Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('114a80f1-6701-45fb-91fb-e91f8d9ee29e', 'edc63a59-2fd4-442a-9343-f2872d776bdc', 9, 'Arthur''s First Day', 'It''s finally the first day of fourth grade and Arthur couldn''t be more excited -until he learns Buster is in another class! Meanwhile, D.W. is nervous for her first day of kindergarten. Will Arthur and D.W. be able to make new friends?', '2021-09-06', 55, NULL, '2026-04-03T17:37:54Z', '2026-04-03T17:37:54Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('1153997e-4f73-496d-a9c7-d9bf40738fb3', '65524b14-e29e-4b04-81d3-fbebe525e9ec', 15, 'Franklin''s Word', 'Harriet hears a hurtful word and starts using it at inappropriate times.', '2004-06-26', 12, NULL, '2026-04-03T17:40:16Z', '2026-04-03T17:40:16Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('1154a3dd-20bd-4b10-922d-b99f4ab56916', '63f9bf6d-39b3-44f4-b885-a56807277a80', 29, 'The Christmas Toy', 'When no people are around, the toys still play in the playroom. But since a toy will be frozen forever if a person catches it out of position, they have to be very careful. It''s Christmas Eve, and Rugby the Tiger remembers how he was the Christmas Toy last year, and thinks he''s going to be unwrapped again. And it''s up to Apple the Doll, who Rugby supplanted as the favorite toy, to tell him what''s in store. But Rugby won''t believe her, and tries to get into the Christmas package and lets Meteora, Queen of the Asteroids, loose. Unfortunately, she doesn''t know she''s a toy and thinks she''s landed among aliens. And it''s up to Apple, Mew (the Cat''s toy mouse), and the other toys to get Rugby out of the box and Meteora back in it before they''re found and frozen.', '1986-12-06', 50, NULL, '2026-04-03T17:35:23Z', '2026-04-03T17:35:23Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('11574006-1660-4072-8ee0-3b572b5cc122', 'ac068b8e-80f6-46bf-afb2-dcebcf76dc36', 8, 'Spooky', 'Skye and Ben exclude Kiki and Julie from their Count Spookula club because they don''t think girls like spooky stuff, but they learn that some girls do like scary stuff, and some boys don''t. Leon and Jody do not appear in this episode. Sizzle and Nuzzle only make cameo appearances.', '1998-10-29', 29, NULL, '2026-04-03T17:12:21Z', '2026-04-03T17:12:21Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('1158baff-c001-476a-bfb0-5ee111bf5ae9', '34bdccfa-3c14-4e1c-9148-85c29aadc0e1', 8, 'The Great Canadians', 'Out in the Great White North, the Kratt brothers carry a canoe throughout their search for Canadian wildlife.', '1996-06-12', 30, NULL, '2026-04-03T17:11:47Z', '2026-04-03T17:11:47Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('115c3ffe-cd7d-41b8-ba71-423022389a9f', '6c47406b-b3d6-40d8-b483-1ae1b3d30009', 4, 'Fire Of Pontypandy', 'When Fireman Sam performs a super-heroic rescue, he is awarded a special bravery medal and offered a new job in Newtown by visiting Chief Fire Officer Boyce. Meanwhile, a Pontypandy Pioneer Scouts camping trip, results in a forest fire that threatens to engulf Pontypandy, forcing everyone to prepare to evacuate ! Will Fireman Sam leave his beloved town, and will this be the end of Pontypandy ?', '2018-06-13', 10, NULL, '2026-04-03T17:14:36Z', '2026-04-03T17:14:36Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('1164af13-0fc8-4cf3-ac47-b21cf9a944fd', '5b5e8b2f-0a85-4488-b3dc-3d8b794e6582', 2, 'It''s Either My Way or the Feng Shui', 'Vicki prepares for her big office move while Shannon enlists the help of her feng shui expert to try and bring balance into her otherwise chaotic life. Lydia is busy launching her brand new magazine which features Peggy, an Armenian firecracker, whose life may look perfect but not everything that glitters is gold. Kelly struggles to make her marriage work while Meghan settles into life as a new mom. Tamra plans an over-the-top birthday party for her granddaughter, Ava, where tempers fly as Lydia and Shannon meet for the first time and don''t see eye to eye when it comes to Vicki.', '2017-07-17', 44, '/6vTKz7Z2cYfUFGbCQMEC9wE5wp.jpg', '2026-04-03T16:35:33Z', '2026-04-03T16:35:33Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('1167aed2-c1d2-433f-8648-57b56f84eb13', '90cc8678-a14f-4d05-bc1e-54a3117895d5', 4, 'New Enemies', 'Poachers enter the Park and kill some of the Deer. The Farthing Wood animals do what they can to help and set up a watch to act as an early warning system. Fox hatches a plan to rid the Park of the hunters but Scarface plots to turn his plan against him.', '1994-01-01', 25, '/bv0yLduIGA6IoHsLaCLh5jQ8UTV.jpg', '2026-04-03T17:18:49Z', '2026-04-03T17:18:49Z');
