INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('117e34af-bf99-486a-8c31-b126548600e6', '33440d76-e69f-47ad-ac25-862ccbc9dfa1', 6, 'Tequila, Tears, Texas', 'Everything''s bigger in Texas, including the drama. Ashley continues her mission to keep spirits high and Austin weird, but plans are derailed when Robyn is pushed to her breaking point.', '2023-12-10', 43, '/cPTz1hKvSn1RpOKL5qTZQcVX4K6.jpg', '2026-04-03T16:35:41Z', '2026-04-03T16:35:41Z');
