INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('11936112-401b-49d5-aad4-87ac9f76c292', '5ba20443-d99f-4820-81f6-6832d3f2bc4f', 14, 'Volcanoes', 'Volcanoes are mountains made from molten rock. The Earth’s crust is divided into big slabs, called plates, which are slowly moving all the time. The plates are floating on the Earth’s mantle, a layer of gooey hot rock that flows like maple syrup. Some places in the mantle, the rock gets very hot and nearly liquid. It’s called magma. Sometimes the magma reaches the Earth’s surface and forms a volcano.', '1996-01-31', 26, '/uYEckRJRRtdxDthkhxMzNc00fgq.jpg', '2026-04-03T17:37:21Z', '2026-04-03T17:37:21Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('11a1c07a-ede1-4922-8015-514dcab79693', 'd84bd187-f033-42dd-8873-e1099c61de07', 30, 'Episode 689', '', NULL, NULL, NULL, '2026-04-03T17:36:39Z', '2026-04-03T17:36:39Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('11a1c25a-9160-4ca4-bcca-162b53995df3', '27d0351a-92f5-4d01-995c-6b5928957075', 15, 'Reunion (1)', 'The housewives bring an icy chill to New York to confront one another after an unpredictable season; Meredith Marks and Lisa Barlow face off about their ongoing issues; Meredith phones a special friend to help clear her name about an unproven rumor.', '2023-01-25', 44, '/Aff7RPQTYLf49HrWVAW9H5nD5Fx.jpg', '2026-04-03T16:35:44Z', '2026-04-03T16:35:44Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('11a3e60f-ab05-4647-a68c-e4808b31614d', '95c86b7f-162e-4e74-812e-73cca314f182', 6, 'The Lion, the Witch and the Wardrobe (6)', 'Aslan is dead and Peter prepares to fight the army of the White Witch.', '1988-12-18', 30, '/gxRGQfGoc5Zvfbsd7DkVCgzfpgV.jpg', '2026-04-03T17:17:41Z', '2026-04-03T17:17:41Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('11ab7c3f-7d17-4aff-93ed-1addcdb799b8', '61e0c9d9-337e-4fe4-a0fd-e567b29af115', 9, 'Revenge Is Best Served in Coach', 'As the couple''s trip to Palm Springs continues, tensions mount between Bronwyn and Lisa. Todd''s frustration with the group''s fighting grows. At dinner, Meredith questions Shawn''s comments about her family while Whitney and Lisa finally find some common ground. The group enjoys a fun day at the racetrack, but things quickly go south when Lisa learns their mode of travel back home is less than luxurious.', '2024-11-13', 55, '/af2i1Ie4aRiO6R7CnPsodCtk6gb.jpg', '2026-04-03T16:35:45Z', '2026-04-03T16:35:45Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('11aec3fa-8d1d-4860-a73d-d3ee809797dd', '02c86ae3-8c3b-4cc0-8e1f-0b27d01dcd91', 4, 'Bring on the Bling', 'DeShawn is determined to make a big splash on the Atlanta social scene with her "Night of a Thousand Stars" gala event, and invites hundreds of people into her private estate for the lavish event. Kim and Shereé bond during a private spa day and enjoy an intimate dinner with their kids, which puts NeNe''s friendship with Kim in jeopardy. Lisa''s "Wu Girl" jewelry line is taking off and her trunk show is a hit. She inks a distribution deal with jewelry mogul, Steven Zale, and models her jewelry in a glamorous photo shoot for her new brand.', '2008-10-28', 43, NULL, '2026-04-03T16:34:44Z', '2026-04-03T16:34:44Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('11b54791-c953-4a30-b055-247266bde96e', '698a60df-8ed4-4ca9-bcb1-ebab343dacdd', 24, 'The Pilot (2)', 'The pilot is cast, taped and aired, but George doesn''t think he''ll live to see its success.', '1993-05-20', 22, '/9jM9QyASKtf8ZbZQTp2ShhKg745.jpg', '2026-04-03T16:34:10Z', '2026-04-03T16:34:10Z');
