INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('11cdd3b9-acfa-460a-b856-90f0f4b80266', 'c7ffc8df-4671-47e3-a11b-606828bcb508', 3, 'Open House', 'Events spiral out of control at Jesse''s place. Skyler reluctantly asks for Saul''s help. Marie returns to an old pastime and a friend asks Hank for help.', '2011-07-31', 47, '/Ac0wu93r4LaZk07wa7PiWpNOOru.jpg', '2026-04-03T15:40:33Z', '2026-04-03T15:40:33Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('11d703ae-dec2-4d7b-9ed6-b553b1688fcc', 'fb06e658-4b54-4682-8783-eaa88a99e61e', 3, 'The Case of the Girl With the Long Face', 'George is concerned about Fern when she falls into a state of sadness, but doesn''t know why. Wanting to get to the bottom of the mystery, he enlists Buster Baxter to investigate.', '2014-09-30', 13, NULL, '2026-04-03T17:38:01Z', '2026-04-03T17:38:01Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('11d71076-734a-48e0-ad30-62b5f108c427', '27a5a980-ec0d-4637-b5ba-df8324a6405a', 16, 'The Concert', 'Frankie pulls out all of the stops in an effort to get an over-excited Sue tickets to a Justin Bieber concert, Mike is thrilled over Brick''s enthusiasm to win the school''s spelling bee and coaches him for the event, and Axl and his friends attempt to break a road sign''s 15-mile-per-hour speed limit - on foot.', '2012-02-15', 22, '/w7WP9jsynQCKB4qxsihecsCVt5V.jpg', '2026-04-03T15:40:29Z', '2026-04-03T15:40:29Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('11d7f79a-34dc-4ce1-b27c-ee222d4566a2', 'f1325b56-44e0-4b6e-89bc-82cac30afea6', 2, 'Jupiter On The Loose', 'When the Pontypandy Pioneers go to the fire station to complete their fire safety badge, Norman wants to prove to his cousin Derek that he can drive a fire engine.', '2012-03-31', 10, '/qWdY3knChXO2xjjZyfIeh6KBbyR.jpg', '2026-04-03T17:14:39Z', '2026-04-03T17:14:39Z');
