INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('11e81aa3-c395-4e33-837a-6d3e7555299a', '89ba90ec-2c79-4a12-a11d-7465d1757683', 18, 'Rick and Morty The Non-Canonical Halloween Adventures', 'This follow up to the original run of the Non-Canonical Adventures brings new movie parodies featuring Rick and Morty. The movies featured are: Beetlejuice; The Blair Witch Project; Evil Dead 2; Hellraiser; Home Alone; Jaws; Predator; Reservoir Dogs; Terminator 2; and Videodrome.', '2019-10-31', 3, '/qxXtl0IktQPHWIUy3AGoFgtvd9j.jpg', '2026-04-03T15:40:41Z', '2026-04-03T15:40:41Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('11e882c4-714d-4e90-add0-d070d0a726c8', '9193e795-da7c-40ec-b68f-f63aa7d5174f', 213, 'Unused / extended scenes from season 3', 'Five unused and extended scenes.', '2014-02-18', 14, '/c4xCuru2cxaUd8xzGPsa3R90828.jpg', '2026-04-03T15:40:35Z', '2026-04-03T15:40:35Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('11eb653d-b1a6-49c9-b47d-943e142a9cf9', 'e291df42-d44f-49e5-bf81-2df32ee4a30f', 1, 'Friends At Play', 'Ojo is excited about a visit from her friend, Christine. The two quickly get involved in one of Ojo''s imaginative games --- a pillow castle. Tutter arrives and asks if they''d like to play checkers, but Ojo tells him she''s in the middle of her game with her "best friend," Christine. Tutter is hurt by the use of the term "best friend." He creates his own friend to play with, "Mr. Cheese," but Bear helps to mend his friendship with Ojo. He also finds Pip and Pop at odds with Treelo out at the Otter Pond. He keeps pretending to be a monster during their Deep-Sea Divers game and they don''t like it at all. Bear, however, introduces them to a game called The Treasure of Kalamazoo Bay. In the Shadow segment, Shadow retells the story of "Mary Had a Little Lamb." The lamb in this version drives a car, skies and scuba dives in its efforts to follow Mary everywhere she goes.', '1999-07-19', 25, NULL, '2026-04-03T17:35:32Z', '2026-04-03T17:35:32Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('11f0f332-86f4-43e9-96b2-48d3fa55478d', '36e5c604-fea9-4bcf-8343-71bfaf60ecd2', 4, 'Foduck The Vigilant', 'Foduck is soon to earn his ''v-word''. This means he will be allowed to travel in the open ocean.   However, he is having a spot of bother picking a name so he turns to his other tug friends for help.', NULL, NULL, NULL, '2026-04-03T17:10:11Z', '2026-04-03T17:10:11Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('11f26328-8146-494b-bdce-f338144d7343', 'ea73e13c-6962-4804-8305-c303df65f89f', 54, 'Toy Boat', 'Lady Aberlin gives the Trolley a waves costume for the opera, which also fools Corny making him want to have a part in the opera. The entire Neighborhood of Make-Believe will be the backdrop, simulating the sea.', '1969-04-24', NULL, NULL, '2026-04-03T17:35:38Z', '2026-04-03T17:35:38Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('11fb4eaf-4c2a-4252-8601-2c681460bb97', '8bdf0ad3-a798-4d5a-b304-c7501eae6867', 4, 'You Just Don''t Get It', 'While her fiancé is in the hospital, Gretchen Rossi lifts her spirits by hosting a burlesque party at her home. Vicki Gunvalson and her family tour a million dollar yacht that she hopes to buy despite her daughter Briana''s protest. Life without their father around pushes Jeana Keough''s kids, Colton and Kara, to grow up quickly and seek out other paternal figures. Meanwhile, Tamra Barney''s son, Ryan, has an abrupt change of career aspirations much to Tamra and Simon''s surprise. New housewife Lynne Curtin is introduced and we meet her husband and two precocious teenage daughters, Raquel and Alexa. The eldest, Raquel, pushes her parents into having a huge 18th birthday blowout bash at their house. Vicki, Jeana and Tamra try to have a girls night out but a discussion about marriage and ex-husbands turns into a contentious situation between Vicki and Jeana.', '2008-12-16', 44, '/5xdde6IJ6PsqXLeCZWhJY4RqGMu.jpg', '2026-04-03T16:35:30Z', '2026-04-03T16:35:30Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('11ff9c8c-971e-48a2-9ada-bd844632784e', 'f63c3f61-0970-4e37-81cc-2b9045a9952c', 47, 'Elmo Makes a Collage (3962)', '', '2001-03-06', NULL, NULL, '2026-04-03T17:36:42Z', '2026-04-03T17:36:42Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('1206f805-84b3-459d-99cd-bfff5a1c9bd7', 'd01919fb-98e0-42bf-b9d9-1cecf912f6e1', 7, 'Old MacDonald''s Duck Gets the Moos (3792)', '', '1998-11-24', NULL, NULL, '2026-04-03T17:36:42Z', '2026-04-03T17:36:42Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('120a716a-49ea-4568-bd39-b68719d6c95d', 'bb919aec-0d5c-4c58-9a5a-fa2a0a5de2b6', 10, 'Episode 415', '', NULL, NULL, NULL, '2026-04-03T17:36:29Z', '2026-04-03T17:36:29Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('121932ae-aef6-4782-a6a2-38130b017dcd', '1a534647-384b-4c00-bb6c-a3371ad962eb', 26, 'Locked and Loaded', 'Enter a duel with the Pawn Stars as a 1763 flintlock pistol fires into the shop. Will Corey bring out the big guns or will the deal end in a draw? Then, Rick scopes out a 1890s telescope cane. Will he set his sights on buying this antique or will he limp away empty handed? And later, Rick and Chumlee venture to a galaxy far, far away to see screen-used "Star Wars" props. Can Rick use the old Jedi mind trick to close the deal or will it head towards the dark side?', '2015-05-07', 21, '/AjHkcSXwgahMXx3FxYlqTrYnKYG.jpg', '2026-04-03T16:34:19Z', '2026-04-03T16:34:19Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('121b6c30-84f0-4edb-8679-8f901a7d7a87', '8c0f12e1-5379-4a27-aca2-b69401a33b0f', 1, 'Arthur Meets Mr. Rogers', 'Mr. Rogers from Mr. Rogers Neighborhood comes to the Read family for a visit.', '1997-10-20', 13, '/5Rl6NQnyvRvKS56Ck6s06HpvFgE.jpg', '2026-04-03T17:37:55Z', '2026-04-03T17:37:55Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('121fcd5a-6131-4751-b21d-b7984aecf145', '2f5a4ffe-2548-4181-85ac-6145cb3e3bf7', 3, 'Kody Wants Out', 'Mitch and Aspyn announce their engagement and the race is on to find a venue! Then, the whole family goes to Utah to help with the official opening of Meri''s Bed & Breakfast.  At the opening, Kody drops a hint of some major changes ahead.', '2019-02-10', NULL, NULL, '2026-04-03T16:34:31Z', '2026-04-03T16:34:31Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('122322a1-64b9-43d1-b3a8-ca42e191d71d', '8d61f484-12f0-41cb-8716-0b9899bfc39f', 5, 'Pete''s a Pizza - Pygmalion', 'A father turns his son into a pizza; hugs bring a statue to

 life.', '2006-05-15', 30, NULL, '2026-04-03T17:12:29Z', '2026-04-03T17:12:29Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('12296314-e90f-4d0e-9080-c66826e0b4aa', 'ac068b8e-80f6-46bf-afb2-dcebcf76dc36', 4, 'To Have and Have Not', 'Skye worries that the others won''t play with him because his parents refuse to buy an expensive new toy. Nuzzle fakes an injury to get sympathy.', '1998-10-26', 29, NULL, '2026-04-03T17:12:21Z', '2026-04-03T17:12:21Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('122aae0b-b6e0-4539-8dc9-253fea5479e3', 'bb919aec-0d5c-4c58-9a5a-fa2a0a5de2b6', 21, 'Episode 426', '', NULL, NULL, NULL, '2026-04-03T17:36:29Z', '2026-04-03T17:36:29Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('123134ee-2fb6-4eb2-b097-b68757e906d1', '50d6073b-d6ab-4b00-9b01-5d829d987267', 6, 'Chapter Six: The Monster', 'A frantic Jonathan looks for Nancy in the darkness, but Steve''s looking for her, too. Hopper and Joyce uncover the truth about the lab''s experiments.', '2016-07-15', 46, '/tOb9lLSrWBIQfl1ulMHsVVTGtkv.jpg', '2026-04-03T15:40:38Z', '2026-04-03T15:40:38Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('12332aa6-56ec-40e4-bbcc-dad62aac28d1', 'f812042d-eb85-432e-8047-3675886e0b1b', 24, 'Paw Prints of Thieves', 'When Joe gets under the crosshairs for what appears to be a good deed, Wishbone imagines himself as Robin Hood.', '1996-03-02', 28, NULL, '2026-04-03T17:10:42Z', '2026-04-03T17:10:42Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('123a0b71-4e25-4c8b-bceb-a2b13824a2de', '698a60df-8ed4-4ca9-bcb1-ebab343dacdd', 15, 'The Visa', 'A lawyer George dates could help Jerry''s pal, who''s facing deportation, thanks, in part, to Kramer''s trip to Florida.', '1993-01-27', 23, '/60QyGW6rYUEjbBewNB0mDHcG1t7.jpg', '2026-04-03T16:34:10Z', '2026-04-03T16:34:10Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('123ce03c-9c09-452c-b962-7fae67f6a093', '42e591e2-2a88-4434-ae9f-3d4b1d685613', 20, 'London Pawning', 'Pawn Stars goes international when Rick takes a trip to England and visits his buddy''s pawn shop. Will Rick feel outclassed when he discovers that Regal Pawn owns a piece of the Titanic? Then, back in Las Vegas someone wants to buy Rick''s favorite mini-bike, a Rupp Roadster. Will the guys have the guts to sell it while Rick is out of the country? And later, Rick finds some rare maps of Nevada and North America. But with non-negotiable prices, will he take his business elsewhere?', '2013-08-15', 21, NULL, '2026-04-03T16:34:18Z', '2026-04-03T16:34:18Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('12470991-bf5b-48d3-b344-544527b51811', 'e40e6b63-9f84-449f-8e88-53209b0906c8', 17, 'The Worm Cup Games', 'Alan invites Big Bird into Hooper''s Store to watch the Worm Cup games on his TV set. The audience consists of a few kids, and even some worms with their own miniature tables and vans. The worm audience is split into two groups: one from France, and one from the USA. Alan explains to Big Bird that the objective of the Worm Cup games is to kick a ball into a cup the most times. Worms from all over the world are competing for the cup, including Slimey.', '2007-09-20', NULL, '/mvHPcvwT2ID0QuDN2N48fXhpeSX.jpg', '2026-04-03T17:36:45Z', '2026-04-03T17:36:45Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('124727e6-a181-4745-b720-9266bfb15c02', '421c3366-4d98-4baf-b4ad-6ec5047df9f8', 4, 'Ladonna Compson: Party Animal', 'Apple picking, bake sales, craft classes... there''s so much to do in Elwood City in the fall! And Ladonna''s determined to do it all. But when you''re juggling so much at once, you''re bound to drop a ball... or five.', '2013-11-12', 13, NULL, '2026-04-03T17:38:01Z', '2026-04-03T17:38:01Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('124b08fc-2e03-4599-a967-04468257c538', '21745b85-d269-42fa-b4dd-701b2da5c085', 71, 'Episode 71', 'with John Noakes, Peter Purves, Lesley Judd', '1974-05-20', NULL, NULL, '2026-04-03T17:21:51Z', '2026-04-03T17:21:51Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('124d8992-8dac-4b14-94c2-94c8bb08015a', '20d7138e-eea8-46a8-8ada-2b0f0ee1f674', 31, 'Episode 31', 'Remember when Simon shared his cornflakes with a tiger, Sarah played bowls with Chelsea Pensioners and Peter flew like a bird at the world''s first Aerodium? Other highlights include guide dog Prince''s first meeting with his blind owner, Sarah''s dive on the Mary Rose and Simon''s climb up a 100ft spar tree. Special guests include HRH Prince Charles, David Bellamy, Sefton, Terry Wogan and Evil Edna.', '1982-12-30', NULL, NULL, '2026-04-03T17:21:56Z', '2026-04-03T17:21:56Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('124d99e7-af5f-4095-8936-a8beb61c2baa', '6d2b78d7-2612-4afb-81ca-dee774af9c2b', 8, 'Dance', 'Rogers first sees Sam Weber demonstrating his tap-dancing skills. Mr. McFeely shows a videotape on how shoes are made. Sam Weber also visits the Neighborhood of Make-Believe to disprove Lady Elaine''s belief that men don''t dance.', '1987-05-11', NULL, NULL, '2026-04-03T17:35:44Z', '2026-04-03T17:35:44Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('12543eda-f674-49c6-bacc-a055b9f2c35e', '5a771f52-fe96-4ea2-b567-a8dde899059e', 5, 'E Equals MC Pawn', 'The Pawn Stars make calculated moves when some handwritten math by Albert Einstein could multiply their profits. Chumlee tries to prove he isn''t dim when he pays big bucks to have an antique headlamp tester shining brightly once again. Corey and Chumlee take a stab at buying a prop from the classic horror movie "Child''s Play." Later, a pill case pops into the shop that may have once belonged to Hollywood legend Carole Lombard, but Rick does a second take to make sure it''s not a stand-in.', '2017-10-30', 21, '/6aVMR1qcgklwo13TMwOBpq8j556.jpg', '2026-04-03T16:34:21Z', '2026-04-03T16:34:21Z');
