INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('125d40d0-87db-49ae-8e1c-7ed0fbbabfed', '70c8cb46-2494-4dd4-98f6-6bfb9b3faf73', 17, 'Bow Legged', 'The Pawn Stars are presented with one of most unique items to ever hobble its way into the shop - a pirate''s peg leg. Will the gang gather up a sizable bounty for this rare piece of piracy lore, or will they be forced to walk the plank? Then Rick has a chance to buy a brand new, top of the line, archery bow. Can he find the target price with the fiber-optic sights, or will this black bow backfire? And later a man wheels up to the shop with a full size, hand carved, wooden motorcycle. Can the shop widdle down the price or will this deal get axed?', '2010-04-12', 21, '/i9GOoiFoCeGGhoz1o2AmFDzA57M.jpg', '2026-04-03T16:34:16Z', '2026-04-03T16:34:16Z');
