INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('1278f190-1dfc-46c1-ab26-8e3c2ed9eaee', '5db3ff78-e439-48e1-8f67-988ecbf85d17', 5, 'Monsieur Treville, Captain of the Musketeers', 'Dogtanian has gone to see Monsieur Treville to join the Musketeers. When he arrives Widimer and some guards are about to arrest Aramis and Athos for drawing their swords against some of the guards. Treville comes down and sorts the problem pointing out both sides drew their swords, making it a duel, so both parties should be arrested. Before leaving Widimer spots Dogtanian and orders the guards to arrest him, a farcical chase follows, ending with Dogtanian jumping on a coach that takes him back to the Musketeers headquarters...', '1981-11-06', 24, '/cQK8I1laiFAk98GNXRosH4Jitdr.jpg', '2026-04-03T17:18:43Z', '2026-04-03T17:18:43Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('127fe53a-e08a-4731-a0a5-79b8da379e52', 'b8c1b631-9850-45f3-9361-cdad5571a492', 12, 'Life After Polygamy', 'Christine and Kody have a final battle about a snowblower on her way out the door to move to Utah.', '2022-11-27', 41, '/rCyPDMW3jziT6vEYXnCOBCvuYj9.jpg', '2026-04-03T16:34:32Z', '2026-04-03T16:34:32Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('1286ce36-5126-4746-a30a-818021267009', '65d1cad8-0120-425e-ae9b-5020ce773b32', 12, 'Defense Is the Best Offense', 'The women return from two tense trips with most feeling the planned bonding failed to take hold. Tamra joins Sophia on a music-school tour. Jenn realizes her upcoming wedding is having a greater emotional impact on her kids than she anticipated. Everyone reunites when Gretchen hosts a tactical training event. The ladies learn self-defense, but a shocking rumor about Tamra leads to an explosive confrontation.', '2025-09-25', NULL, NULL, '2026-04-03T16:35:36Z', '2026-04-03T16:35:36Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('1288b7bf-e898-4b9b-a10b-5c0e6d7d95eb', '095258d0-d8db-4096-8ac7-6a42cd4cbdcf', 16, 'The Battle Of Leaking Roof', 'It''s about to rain, and Ma wants Pa to fix the hole in the roof before it starts to pour. At the same time, Boober and Mokey are out getting radishes, and when Ma accidentally picks Boober up, he loses his hat. Boober''s too afraid to go back out there, so Mokey goes out by herself to get the hat. Meanwhile, Ma''s having a terrible time getting Pa to fix the roof, because he''s too scared of heights. Will Pa get over his fear and fix the hole in the roof before the rainfall?', '1985-04-15', 24, '/2Bd3PI5E5G1gUZwrFyyUZVrFZqS.jpg', '2026-04-03T17:35:00Z', '2026-04-03T17:35:00Z');
