INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('13959f4b-3835-47ab-abc5-fb3b440fc739', '1e967562-cb82-4c1a-b523-a8212971da9e', 1, 'Celebrating the Arts: All About Trees', 'While tree-sitting for Mr. McFeely, Rogers draws a picture of a tiny oak tree. McFeely compliments the drawing, and later, he shows a video on how adult tricycles are made. Cousin Mary returns to the Neighborhood of Make-Believe to show her videotape of various trees.', '2001-09-07', NULL, NULL, '2026-04-03T17:35:49Z', '2026-04-03T17:35:49Z');
