INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('13a2f9e7-695b-496c-b245-44d7ed4a3546', '63f9bf6d-39b3-44f4-b885-a56807277a80', 26, 'The Muppets on Puppets', 'The Muppets on Puppets aired on NET in 1968, as part of the Adventure in the Arts anthology series. In this one-hour special, Jim Henson -- with the help of Muppet character Rowlf the Dog -- explains the art of puppetry, from building to performance. Henson describes the various kinds of puppets; demonstrates how to operate a hand puppet; and provides a brief history of puppet development and performance throughout the world, beginning with the influence of the character Punch from the Punch and Judy shows of the 1800s. Jerry Juhl and Frank Oz demonstrate how other kinds of puppets work, such as the string puppet or marionette, the Javan rod puppet, the finger puppet, and the Sicilian puppet.', '1968-01-01', 26, '/dwkHumJPMSjXNJjZXu8aBOM8Nz1.jpg', '2026-04-03T17:35:23Z', '2026-04-03T17:35:23Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('13a32141-3851-4950-9081-2fd0e4a3abf4', '16cbf3f2-fffd-4a78-bca3-96d05f5a2c6b', 5, 'Arthur''s Toy Trouble', 'Arthur gets a Mutant Muck Monster as a gift, which he later learns is worth two million dollars unboxed, but it has fallen into the D.W.''s hands.', '2016-01-20', 13, NULL, '2026-04-03T17:38:01Z', '2026-04-03T17:38:01Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('13a65dab-e49f-47b5-8cc2-4aa5b71464e3', '2aebfad4-3145-4bc1-9def-5f1d5bdfcfc8', 4, 'The Dog', 'Jerry''s gig as a dog sitter provides some time alone to George and Elaine, who find they have little to say.', '1991-10-09', 23, '/gAJgORJBKH6bCIxQ3Rfibv2mprs.jpg', '2026-04-03T16:34:10Z', '2026-04-03T16:34:10Z');
