INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('13b165f8-1756-49ec-aaa5-70ae875db3b5', '1a534647-384b-4c00-bb6c-a3371ad962eb', 3, 'RC/DC', 'Rock on with the Pawn Stars when a signed AC/DC album electrifies the shop. Will Chum get it "done dirt cheap" or will he wind up on the "Highway to Hell"? Then, Rick gets fired up over a Beals Model Remington revolver. Can he hit his target or will the deal end in a draw? And later, when Rick wants to find new ways to advertise the pawn shop, he thinks small to get big results. Will Rick be able to pick a winner or will his new plan run out of juice?', '2015-01-15', 21, '/sZMZip6tvgPN3CSzgIlL9NzLJbT.jpg', '2026-04-03T16:34:19Z', '2026-04-03T16:34:19Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('13b4b798-d513-4fa3-8f6f-acb5d4bdab69', '40700e8a-1dce-4895-bede-522a13a8bcad', 18, 'Families', 'When a baby African pygmy hedgehog comes to Animal Junction, Zoboo, tries to find the right family for her to live with. The Kratt Brothers explain that there are all different kinds of creature families, and they finally find the perfect family for the baby hedgehog.', '2001-04-20', 27, NULL, '2026-04-03T17:10:55Z', '2026-04-03T17:10:55Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('13b7bcde-216d-4734-b9b0-15d695e4904c', '4d2cac0f-38fd-438b-8afa-acf43952e535', 269, 'Episode 269', 'Christopher Trace and Valerie Singleton introduce a magazine programme for younger viewers.', '1964-02-24', NULL, NULL, '2026-04-03T17:21:47Z', '2026-04-03T17:21:47Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('13b90921-ac5e-47c4-8a3d-fd67d802be07', 'e48599f8-66ff-4c0f-9274-65b9ae1cda9e', 49, 'Episode 49', 'High Speed Train Wash!  A prototype of the first OO gauge model of the high-speed train makes a test run on the Blue Peter layout, and for railway enthusiasts who want to keep their locos clean, an easy to make model train wash.', '1977-03-03', NULL, NULL, '2026-04-03T17:21:53Z', '2026-04-03T17:21:53Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('13b93fba-5710-4ce0-ba2b-857461f04e14', '8bae6aa3-4b55-4fa6-bc15-8f4317bd1f13', 54, 'Episode 54', 'Rogers uses a pitch pipe at his television house and with François Clemmons. Mr. McFeely demonstrates one of his sitting-still exercises. The crisis in the Neighborhood of Make-Believe is stopped in conjecture, as Rogers tells viewers they will have to decide the outcome on their own.', '1972-05-04', NULL, NULL, '2026-04-03T17:35:40Z', '2026-04-03T17:35:40Z');
