INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('13bdf0a0-c1bf-4af9-a25a-81d793a29a86', 'e291df42-d44f-49e5-bf81-2df32ee4a30f', 5, 'Halloween Bear', 'It''s Halloween at the Big Blue House. The house is all decorated and everyone is getting ready. Bear helps his friends to find costumes and helps Tutter with carving a pumpkin. He always helps out Treelo when he''s scared by Ojo''s bat costume. Later, everyone gets together for some fun trick-or-treating. The kids have all picked out their Halloween costumes, but Bear hasn''t been able to find anything to dress up as. The kids go through Bear''s box of costumes and come up with an amusing idea. In the Shadow segment, Shadow performs the song "What Do Shadows Do for Halloween?"', '1999-10-21', 25, NULL, '2026-04-03T17:35:32Z', '2026-04-03T17:35:32Z');
