INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('13c7c53e-ae57-45fa-8b9f-8c5203d70191', '937ee587-e2eb-46aa-9a69-3d6bab04398f', 6, 'A Three Hat Day', 'A totally unreal hat store called "Hats... to Where?" sells hats that transport customers to all parts of the world. LeVar whisks himself to the horse racetrack at Turf Paradise, to a model train display in Three Bridges, New Jersey, and to the Nassau Coliseum, where he gets a goal tending lesson from Kelly Hurdey of the New York Islanders. Zelda Rubenstein reads A Three Hat Day, a story about a man who loves hats very much, and how he meets his soul mate when he goes shopping in a new hat store.', '1987-06-29', 30, NULL, '2026-04-03T17:36:16Z', '2026-04-03T17:36:16Z');
