INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('14034d26-2f92-4d84-a0b1-52de2c1cc31b', 'b1d55597-d9d2-4eee-ab95-46dbb163291a', 24, 'Pingu and his Friends Play too Loudly', 'Pingu and Pingg are playing hopscotch, not knowing they are doing it in a parking space. When a parking neighbor comes here to park in and they get into a fight. Then suddenly, Pingu and Pingg are forced to play somewhere else. They go over to another igloo, and start running and playing about very noisily. The grouchy neighbor starts yapping at them. Pingu, Pingg and Pingo who comes along tease her. She was about to hit them with a carpet beater but she missed. She leaves and accidentally closes the window on her hand! She cries like a wolf (in the early version of course she did this,) making Pingo, Pingg and Pingu laugh. They then start playing ball, and the ball accidentally goes onto the grouchy neighbor''s roof. She catches it and takes it inside. Pingo and Pingg protest to tell Pingu to go get it back so he begs for it back. With no avail, but then suddenly, the grouchy neighbor gets locked outside, and though hearing them, laughing at her. At first, Pingu decides to help her, by climbing through the window and unlocking the door. Then suddenly, she gives them their ball back, and they all play together. But the grouchy neighbor accidentally hits the window on her igloo making them all laugh again!', '1990-10-13', 5, '/eU30zzZPcP1Y030q3xDFnREZMbI.jpg', '2026-04-03T17:22:19Z', '2026-04-03T17:22:19Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('14065955-9969-4b01-996f-42b58c36f712', 'dec4a06d-731b-41e4-8b15-374f47d1f5c7', 7, 'Spa-Cation', 'After being on home confinement for over a month, Teresa says goodbye to her ankle bracelet and the ladies plan a trip to celebrate; Siggy returns to her religious roots; Melissa confronts Jacqueline about involving Joe Gorga in her fight.', '2016-08-28', 43, '/bZba7BlQhPn3ehOCZIyo89RwaVT.jpg', '2026-04-03T16:35:16Z', '2026-04-03T16:35:16Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('140a0eba-e37c-40dd-a531-928334eff94a', '4d2cac0f-38fd-438b-8afa-acf43952e535', 181, 'Episode 181', 'A magazine programme for younger viewers. Introduced by Christopher Trace.', '1962-04-30', NULL, NULL, '2026-04-03T17:21:47Z', '2026-04-03T17:21:47Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('140b1567-0768-4b1b-8b36-071f4671d8b7', '363a94f9-e0e5-441c-aa86-2be2e9832da1', 5, 'Wreck it Rick', 'Rick and Chum kick it with a rare pair of Pumas from 1968. But will a shocking sticker price leave them in the dust, or can they race their way to a deal? Next, Chum is blown away by a fan from the 1940s. Later, Rick reads into a collection of letters from historical figures, but it''s some lab notes by Marie Curie that really leave him glowing. And finally, a Post Malone guitar inspires a smashing adventure for the guys. Will it bring them closer together, or wreck their day out?', '2021-10-30', 42, '/eZ4WJRAK3SPhvINhvtvh65D1AGw.jpg', '2026-04-03T16:34:23Z', '2026-04-03T16:34:23Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('140b3e9f-00c4-4bba-a62b-b3d19b7f216e', '73ae1459-ba91-4185-a9da-bf6f2844af49', 13, 'Not Feeling Jovani', 'Dorinda hosts the women at Blue Stone Manor for a relaxing weekend in the Berkshires. Sonja confronts Luann about paying her less than she deserves to perform in her cabaret show, and Dorinda steps in to defend Sonja. Meanwhile, Elyse approaches Ramona about the current state of their friendship.', '2020-07-09', 60, '/kQChlr3Vy6VlEIPq59XkTCpqRvQ.jpg', '2026-04-03T16:35:25Z', '2026-04-03T16:35:25Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('140b69d6-ffbd-48a4-9d6c-61bfec61888d', '1a534647-384b-4c00-bb6c-a3371ad962eb', 31, 'Ticket to Pawn', 'Twist and shout with the Pawn Stars when a 1963 Beatles signed guitar strums into the shop. Will Rick "let it be" or yell for "help"? Take a ride with Corey as he gets revved up when he checks out a 1981 Suzuki motorcycle. Will he kick start a sale or will the negotiation skid out of control? Then, Rick tries to teach the guys some office etiquette.', '2015-05-25', 21, '/seD17DjWP5b7KSVJsPFTofhnWXB.jpg', '2026-04-03T16:34:19Z', '2026-04-03T16:34:19Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('140c5737-710b-4bdf-a1f2-b00d648bb2b7', 'd1863f2f-02ec-40ce-af64-db03fbe518a7', 25, 'BooBoo Busters', 'Abby and Elmo are the Boo-Boo Busters; finding friends on Sesame Street who need help making their boo-boos better. Also featuring Cookie Monster''s Smart Cookies, and Elmo''s World. Brought to you by the letter B and the number 13.', '2016-06-25', NULL, '/vJcU85fTzKP5Cc4IU3lT8cVn9O5.jpg', '2026-04-03T17:36:48Z', '2026-04-03T17:36:48Z');
