INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('1418ae19-2a5a-4b77-ab3b-34987ee67bb4', 'c01ddd2a-bdb1-4c97-8d04-58f791ef1c24', 39, 'Stinky', 'In the creature world, different smells mean different things. When a skunk visits the gang at Animal Junction, Zoboo, Martin and Chris discover the difference between a ''come-here'' smell and a ''go away'' smell. They also visit with a mink, a creature that scent-marks to let other creatures know that it has passed by. Chris decides to make a Chris scent so he can scent-mark Animal Junction. Jackie gives her friend''s dog a bath in tomato juice to get rid of a gift from a skunk that didn''t want to play with her.', '2000-04-26', 27, NULL, '2026-04-03T17:10:55Z', '2026-04-03T17:10:55Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('1418b86a-0f22-4e7e-bf70-b668a2a1aeee', '0442fb97-1460-4923-8558-b994078dc6b8', 22, 'Reunion (3)', 'A heated exchange ensues between Chris Samuels and Chris Bassett; Karen and Ray Huger talk about the status of their relationship; Ray makes a surprise announcement; Robyn shares her feelings about where she and Juan stand with their marriage plans.', '2020-12-27', 42, '/qAOgv6gLDYq40rb1zY0fpvjMSv5.jpg', '2026-04-03T16:35:40Z', '2026-04-03T16:35:40Z');
