INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('14292ce6-3bf9-43bd-b041-56d8d7145329', '2dadbc6b-684f-4884-a0b2-57bda7546dc2', 3, 'Wings of Time', 'Bernard has to keep reminding Lucy on how she can''t keep appearing from anywhere. Then Lucy appears in an old lady''s house while shes outside then sees her puppies and realises the house is on fire what will Lucy do?', '2000-09-29', 15, NULL, '2026-04-03T17:20:05Z', '2026-04-03T17:20:05Z');
