INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('14396280-3c12-48a0-aa23-5e063044a642', '5b2c9365-7bd9-4ca1-a3fb-15f1a024a56e', 6, 'Girls'' Night Out', 'LuAnn''s son objects to her busy social schedule when she and Bethenny go to dinner after having drinks at the house. Elsewhere, an aloof Jason is late to a dinner with Bethenny, Jill and Bobby; and Alex brings Simon to a girls-only night, a move that irks Ramona.', '2008-04-08', 60, '/69Uf6uOwXn2ZWLgyN0e5r5ydIu3.jpg', '2026-04-03T16:35:21Z', '2026-04-03T16:35:21Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('14405e74-4de1-444c-865e-33c92f2678bb', 'eb7e3bb4-5746-4577-81c6-f5b2dc2efc6e', 19, 'The Guru', 'Aang travels to the Eastern Air temple to receive guidance from Guru Pathik while Sokka is reunited with his long-lost father. Meanwhile, Azula has something diabolical in store for her enemies in the Earth Kingdom, including Zuko and Iroh.', '2006-12-01', 25, '/49ED3hLwNq6sibzazGv656CrLEW.jpg', '2026-04-03T17:40:48Z', '2026-04-03T17:40:48Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('144269bd-14a6-4136-bcb4-695265961318', 'c66c23b0-1456-451a-bb80-45c28b0309ec', 1, 'Valar Dohaeris', 'Jon is tested by the wildling king; Tyrion asks for his reward; Dany sails to Slaver''s Bay.', '2013-03-31', 55, '/3pyS7xz9mprX4OuOCfV261CnGfR.jpg', '2026-04-03T15:40:36Z', '2026-04-03T15:40:36Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('1448de17-0067-4a7f-9a44-629b3dc1cc55', 'df77dba2-bbda-4f38-9713-8d5c856f852e', 3, 'There Were Five In a Bed', 'The bed where all the toys sleep is getting rather crowded. When Old Bear falls out and bumps his head the toys decide it would be a good idea to try and find somewhere else to sleep. They try all sorts of strange sleeping places; drawers, baskets, bowls and hammocks but there always seems to be a problem. In the end Old Bear comes up with the perfect solution and, at last, there is plenty of room for them all to sleep.', '1993-10-17', 10, NULL, '2026-04-03T17:18:55Z', '2026-04-03T17:18:55Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('14497225-52f9-4239-8ccc-8e549f51ef4c', 'ebc99729-ccb7-4d64-82c1-42708cd7ba85', 29, 'Episode 29', '''Merry Christmas'' in Cornish, and today four brothers from Bodmin, Merv, Andy, Chris and Neil, otherwise known as Bucca, make their very first appearance on TV. They''ll be singing old favourites like ''Tom Bawcock''s Eve'' and playing some of their amazing collection of 40 instruments, including the bombarde.

And Sarah tells the story of the Unknown Armada, when Mousehole, Newlyn, Penzance and Paul were invaded by Spanish troops in 1595. Story Dorothy Smith', '1980-12-15', NULL, NULL, '2026-04-03T17:21:55Z', '2026-04-03T17:21:55Z');
