INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('146210e0-1e06-4324-8906-82dd5104523c', '34bdccfa-3c14-4e1c-9148-85c29aadc0e1', 5, 'In Search of the Tasmanian Tiger', 'A diary belonging to Allison''s grandfather and great-uncle sends the Kratt brothers halfway around the world to look for the elusive Tasmanian ""Tiger.""', '1996-06-07', 30, NULL, '2026-04-03T17:11:47Z', '2026-04-03T17:11:47Z');
