INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('14634a19-f6d9-4554-b232-b5f8f841f144', '4d2cac0f-38fd-438b-8afa-acf43952e535', 310, 'Episode 310', 'with Christopher Trace and Valerie Singleton.', '1964-11-12', NULL, NULL, '2026-04-03T17:21:47Z', '2026-04-03T17:21:47Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('146c9bd4-164e-496b-b96c-e4b678f121c3', '4a8e3db0-8068-4ff3-942f-91f45f665f20', 18, 'Hug, Hug, Hug!', 'A sculpter named Pygmalion carves a statue of a woman, falls in love with her, and gives her a hug - only she can''t hug him back. The Lions then try to help find ways for the statue to hug Pygmalion.', '2000-04-26', 30, NULL, '2026-04-03T17:12:27Z', '2026-04-03T17:12:27Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('146ceef0-e6c3-4ff3-a202-537991c7d547', '941b8c65-4454-4336-be7c-1d0591c12f90', 26, 'Pingu''s Bedtime Shadows', 'It is night, and Father keeps dozing off. Pingu and Pinga are playing outside, and Mother tells Father to get them in so they can get ready for bed. They come in and Mother takes them into the bathroom while Father dozes off in the chair again. After some typically naughty behaviour in the bathroom by Pingu, including squirting the toothpaste on the mirror and making a fiendish shape from the pattern, they eventually get to bed. Mother snuggles them down in bed. Pinga dozes off, but then wakes and is scared when she sees a shadow of a monster on the wall. Pingu is also initially scared by the shadow, but then realises that a mask and some other things have caused the shadow. They both sit on Pingu’s bed and Pingu makes some shadows on the wall that Pinga enjoys. She then wants Pingu to do Robby, but is not very impressed by Pingu’s attempt and does a better one herself. Pingu then does a sailing boat; Pinga does a schooner. After some thought Pingu does a shadow of Father and mimics him, which Pinga applauds. Pingu then thinks that Pinga is doing a lifelike shadow of Father, with appropriate sounds, and claps wildly, but doesn’t realise as Pinga has that it’s the real thing! Father tells them to go to bed, but when Mother comes in she finds all three of them asleep, snuggled together in Pingu’s bed which makes her laugh, and then puts a blanket over them.', '2004-02-06', 5, '/5gIyaCskulMYapKkRGhlR5CDSke.jpg', '2026-04-03T17:22:20Z', '2026-04-03T17:22:20Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('146d6a46-c191-4417-9060-c0c275a2605a', '671bd4da-3470-40f9-9a03-40fba34d2b8e', 1, 'Vive La Hecks', 'Axl returns home from his summer trip to Europe, sporting a man-bun and embracing a new, chill European outlook on life. Mike just wants him to clean up and look for a job, but Frankie thinks Axl will do this on his own and asks Mike to give him a little breathing room. Meanwhile, because Sue worked the entire summer at Spudsy’s and missed out on having any fun, she decides to cram in a whole summer of fun in two days before going back to college; Brick makes the decision to break up with Cindy because he doesn’t want to be tied down in a relationship when he’s about to embark on the revelry of his “big sophomore year”; and Frankie desperately tries to come up with an item for a time capsule that’s being buried under the Orson cow that will make the town remember the Hecks when it’s opened in 100 years.', '2017-10-03', 22, '/9YzlgkgtN1TzZqTMVfx9Bl0nMgb.jpg', '2026-04-03T15:40:31Z', '2026-04-03T15:40:31Z');
