INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('14d34c16-03ea-4781-8489-b1e86e7fd13c', 'a0fa5075-9ce1-48c1-9995-0c0fd866e549', 14, 'Hemlines and Headlines', 'As Mauricio’s dating life starts to make headlines, Kyle struggles to picture what her own life will be like moving forward. Erika’s fabulous home remodel is finished, but will it meet her mother’s high standards? Garcelle and Dorit have a long-awaited one-on-one, where someone’s rose-tinted glasses may prevent them from seeing eye-to-eye. The press is out for Sutton’s first fashion show, but a runway faux pas could make all the wrong headlines.', '2025-03-04', 43, '/pLt1WCOhZKaavQEUnuntpu2d0Yp.jpg', '2026-04-03T16:34:59Z', '2026-04-03T16:34:59Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('14d74421-03c2-4b93-bc09-8b31a22c79f1', '9c5608b2-5111-48bc-a907-7f93472c1e03', 16, 'Sesame Street-O-Saurus', '', NULL, NULL, '/8XidsYx2bN6P7qOdUnXCVpLhPHV.jpg', '2026-04-03T17:36:47Z', '2026-04-03T17:36:47Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('14da76f9-d9cb-4ead-878a-bdc5a84cb94a', '3269a890-bba9-4e6c-9278-f7eb38eb1720', 14, 'Spinning Things', 'A lot of things spin – bike wheels, footballs, hard disks in your computer, and even the Earth – they’re all twirling around. Spinning things have inertia, which means they keep spinning unless something slows them down. Bike tires keep spinning until you put on the brakes. A football spirals through the air until you catch it. The Earth keeps on spinning 24 hours a day, seven days a week. It’s been spinning for over four billion years.', '1995-09-15', 26, '/9vSWoxLYNCQrULCcYffgRR32VqZ.jpg', '2026-04-03T17:37:21Z', '2026-04-03T17:37:21Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('14db8f04-b9c3-495a-b653-51427206a9ac', '5a6d9a42-165b-4b56-9273-0a06874dfe10', 13, 'Madeline at Cooking School', 'Madeline, the girls, and Pepito prepare a disastrous meal for Lord Cucuface, who immediately enrolls them for cooking lessons at the famed Cordon Bleu. After various mishaps, the children finally get the hang of French cuisine, but Madeline fails to receive her diploma because she has given her creation to the hungry. In the end, Miss Clavel helps Madeline realize that the satisfaction of helping someone is more rewarding than any blue ribbon could ever be.', '1993-10-24', 21, NULL, '2026-04-03T16:34:01Z', '2026-04-03T16:34:01Z');
