INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('14f1d808-f8a5-4df2-b726-1808d7929be1', '98d80972-e53a-43dd-a03a-7703465e6f87', 15, 'It''s a Wonderful Pawn', 'Do time with the Pawn Stars when a Christmas dinner menu from Alcatraz Prison from 1912 comes into the shop. Will Rick sentence this piece to life in the pawn shop, or let it escape? Then, Rick and the Old Man check out a bomber jacket worn by a member of the famous WWII fighter squadron, The Hell Hawks. Can the guys make an offer, or is the asking price sky high? And later, Chumlee is put in charge of the annual Christmas party. Can Christmas be saved?', '2012-12-17', 21, NULL, '2026-04-03T16:34:18Z', '2026-04-03T16:34:18Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('14f33fc4-20e5-40bb-b99c-2a17e1b64094', '050d8ae1-6cc1-4018-933d-b3c3d13de856', 25, 'Episode 25', 'Cable Cliffhanger!

Simon''s mid-air report, dangling 170 metres above the Derbyshire countryside! Volunteer Groom tries out the emergency drill on board Britain''s first Alpine-style cable car system. If you have a head for the Heights of Abraham, your Blue Peter badge guarantees you a free ride-but check the opening times before you go into orbit!', '1984-12-03', NULL, NULL, '2026-04-03T17:21:57Z', '2026-04-03T17:21:57Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('14fb35db-e357-4779-9cce-e4caa8760895', '42684fca-0bc7-4f4c-bf7d-f41fd288a764', 8, 'Postman Pat and the Greendale Movie', 'Pat receives his own video camera and goes round making a video diary of Greendale''s events.', '2004-09-17', 15, '/uech9JrqxLAtqv2zKO2fiaMqFqY.jpg', '2026-04-03T17:14:30Z', '2026-04-03T17:14:30Z');
