INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('1500bf5e-5b73-417f-831a-4e3a6a556e9f', 'efd2082e-32f5-4edd-9a7b-a4326d6992c9', 12, 'Elmo''s Happy Little Train', 'Elmo, Rosita, and Zoe play train and pretend to be the driver, conductor and passenger. They make up an adventure so that Oscar can play, too.', '2019-02-02', NULL, '/gLj4W56LjScJGZuzPd8VgQ7CpUN.jpg', '2026-04-03T17:36:49Z', '2026-04-03T17:36:49Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('150454b8-83c7-4a82-a5c9-34414fb9e172', '5b5e8b2f-0a85-4488-b3dc-3d8b794e6582', 3, 'The Not So Quiet Woman', 'Trust issues plague Vicki as she organizes her new office. Also, Peggy deals with her looming surgery; Tamra is thrust back into a past role; and Shannon confronts her weight gain as well as her nemesis, Kelly Dodd, who crashes dinner.', '2017-07-24', 44, '/1NOuxekzFTJNYXbZ5ERvX3ocuY6.jpg', '2026-04-03T16:35:33Z', '2026-04-03T16:35:33Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('1506c8f4-6f1c-41c3-8f58-35ac96815c24', 'bc6d3e37-6e5e-472d-90aa-4c6df1f7def8', 2, 'Polygamists in a Shark Tank', 'Robyn and Meri hit a critical point in their relationship as the Browns pitched their latest business idea to investors.', '2014-06-15', 60, NULL, '2026-04-03T16:34:29Z', '2026-04-03T16:34:29Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('150b8bca-86af-44e7-96ff-22b2ea23de61', '45e64a15-8fc0-4e4b-a1ca-9e3f42f3634d', 7, 'Digestion', 'Take time to digest this show.   They say that your food is no more inside you than a pencil is inside a donut, when it''s poked through   the hole. Instead of the food going in you, food goes through you. But, all the energy you get to live and   grow comes from your food. All the chemicals that become your body and brain as you get bigger, come   from your food. You get these vital chemicals through a process called ""digestion."" Your body breaks   food down and grabs all the nutrients you need from it. Then, your body gets rid of what''s left over.   Digestion starts in your mouth. You begin breaking food down by breaking it into pieces with your teeth   and jaw muscles. Your saliva (your spit) is full of chemicals that react with the chemicals in food and   make them break apart. Then you swallow. Your food goes down a tube (your esophagus) to your stomach,   where powerful hydrochloric acid breaks it down further into a mushy mash we call chime (kime). From   there, the chime goes in', '1993-10-22', 26, '/bSBfTnmfAcweSND7cLFDnfOZ8qy.jpg', '2026-04-03T17:37:20Z', '2026-04-03T17:37:20Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('150e38a7-8140-4650-8daf-ade06d5d06cd', 'bf874be3-7e2f-4a0e-b205-c76ac1ad69fc', 156, 'Inside Looks (on The Bookstore)', 'Inside look from the season 9 episode "The Bookstore."', NULL, 22, NULL, '2026-04-03T16:34:09Z', '2026-04-03T16:34:09Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('15104bd2-1661-4682-b5de-25c72228d203', '87f84063-82b3-45a4-936c-3759e5d91ce3', 2, 'Icy Apology', 'Heather takes Jen to task for the disparaging comments she''s made behind her back. Whitney talks to Justin about improving their sex life, Mary makes plans to renovate her home and Meredith reveals new negative tweets Jen is liking about Brooks.', '2021-09-19', 44, '/62zTJPW7D1aBeqcaocnu3UIqYr5.jpg', '2026-04-03T16:35:44Z', '2026-04-03T16:35:44Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('151413b5-ef13-44d1-9734-84092753b186', '3fc7c152-e4f6-426a-a899-36ec454c4403', 7, 'Tails You Lose', 'Emmy dislikes losing, and while everyone plays freeze dance, she is always the first one to be eliminated from the game by being called out. Emmy decides to quit the game and heads home early, but Quetzal shows her that playing can be more fun than winning.', '1999-09-09', 30, '/1C4tiHwv0PlkEGMsQKJ7YgwCDGy.jpg', '2026-04-03T15:26:03Z', '2026-04-03T15:26:03Z');
