INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('1534777b-ce7a-4583-a199-485f24d54fbb', '04572e48-bbfd-476b-aebe-b6dc424f742d', 3, 'What Is Lost', 'Impatient with Geralt''s methods, Ciri braves major obstacles to prove her mettle. Scheming and suspicion amongst the Brotherhood make Yennefer a target.', '2021-12-17', 60, '/N7qYLPhDxFdFYga4pDaJw1cCaJ.jpg', '2026-04-03T15:40:45Z', '2026-04-03T15:40:45Z');
