INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('1538e285-14f8-448a-9fcf-5c333121ef9e', '1996ddd8-20c9-4a30-96be-2b87fab8d17c', 24, 'Who''s Who (2)', 'Tina gets worried when Lana doesn''t show up at the tailor shop. She finds her locked in her garage. Lana believes that it''s just an obsessed fan. Tina and the team go to Lana''s house to find out who might be after her. They find out that she had four husbands. One of her husbands was the one who made her a star, but she divorced him. Another member of her family is her long lost daughter who''s holding a grudge against her.', '1993-03-14', NULL, '/ypCoXiFnPS2cagUXMmZ4frkLidC.jpg', '2026-04-03T17:40:28Z', '2026-04-03T17:40:28Z');
