INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('1614dc87-af4e-4e8d-8139-d5fe93a552d5', '1a534647-384b-4c00-bb6c-a3371ad962eb', 11, 'Bucking Bronco', 'Play that funky music with the Pawn Stars when a signed Red Hot Chili Peppers album sizzles into the shop. Will Rick take this piece of Rock and Roll history to "Higher Ground", or will he "Give it Away"? Then, Corey saddles up when a Mobo Bronco toy gallops in. Will Corey horse around on the deal, or will he pony up? And later, when Chumlee gets in trouble for wearing a hat to work, he decides to bend the rules. Will Chum pull a hat trick, or will he get in over his head?', '2015-02-19', 21, '/fwOXiN6rvVPamPjM6w4hAfFSDnx.jpg', '2026-04-03T16:34:19Z', '2026-04-03T16:34:19Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('161bb584-96f9-4c95-b385-eab3c36fa192', '59fb7950-a3b5-4f5f-97f3-68268048a662', 10, 'Butterflies', '', '1997-03-18', NULL, NULL, '2026-04-03T17:19:31Z', '2026-04-03T17:19:31Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('161e896c-f441-4fa2-ae90-d2e958f3c3df', '6be74684-83e6-4d00-bd69-3e4fca97cabb', 8, 'Hollman Holiday', 'Stephanie struggles when Travis tries to hijack the planning of his own birthday party. Brandi and LeeAnne break bread to see if they can find common ground. Cary chastises Mark for overspending on extravagant gifts for three-year-old Zuri’s birthday. Tiffany and Stephanie watch LeeAnne take center stage as the keynote speaker for a charity event supporting women with HIV. And at Travis’ birthday, a drunken Brandi raises eyebrows by extending an invitation to everyone for a weekend getaway.', '2016-05-30', NULL, '/ybes6Ux2BNGQW3bverlYOyERYWi.jpg', '2026-04-03T16:35:03Z', '2026-04-03T16:35:03Z');
