INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('1650fb0a-e232-4f8a-a522-8433bc7cdf5f', 'f593d90c-5339-42f5-9c88-5bfd48d04075', 17, 'Party Animals', 'The farmer throws a fancy-dress house party for his birthday. When Bitzer loses all the invitations, however, Shaun saves the day again. Disguised in their own ingenious costumes, the sheep stand in as the guests and have a good old knees-up. But can they fool the farmer into believing he is surrounded by his friends?', '2010-02-14', NULL, '/kx6T5Rp51fTjan1GaHB031MTx4C.jpg', '2026-04-03T17:39:31Z', '2026-04-03T17:39:31Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('1651c650-af9b-44e4-815e-a54a6bf09699', '18da9943-1963-4e04-a7a0-ae63802bb1fa', 13, 'Heat Waves and Hot Flashes', 'In Jamaica, the heat gets to everyone; Shannon laughs it up in a salt scrub with Vicki and Kelly; Gina shares an emotional moment with the ladies; after some fun and games on bamboo rafts and rope swings, tension erupts between Shannon and Tamra.', '2018-10-15', 44, NULL, '2026-04-03T16:35:34Z', '2026-04-03T16:35:34Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('1653db84-e389-4fa1-be54-1fb1123cd320', 'bfdf87ff-01dd-4b54-94bd-19b384f41bdb', 10, 'Shock and Roll', 'Tamra, Vicki, Heather and Kelly travel to Glamis to celebrate Eddie''s birthday. While the trip is supposed to be down and dirty fun, Tamra and Heather are still wary of Kelly''s filthy mouth. After a long RV ride down, the ladies finally get some fresh air and see what the motor sports mecca has to offer. The next day, the ladies set out to explore the dunes, leading to a ride they will never forget. Meanwhile back in Orange County, lives are forever changed as Meghan receives the results from her pregnancy test and Shannon''s holistic home has finally sold, leaving the Beador''s two weeks to move out.', '2016-09-05', 44, '/79d5GzIyt3fwLw9slSbhUvhf9fR.jpg', '2026-04-03T16:35:33Z', '2026-04-03T16:35:33Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('16578dd7-a17a-4909-84d3-43e319c1772c', '4d2cac0f-38fd-438b-8afa-acf43952e535', 287, 'Episode 287', 'Christopher Trace and Valerie Singleton introduce a magazine programme for younger viewers.', '1964-07-13', NULL, NULL, '2026-04-03T17:21:47Z', '2026-04-03T17:21:47Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('1659806b-8252-45de-9222-218180d92007', '40700e8a-1dce-4895-bede-522a13a8bcad', 17, 'Don''t Fence Me In', 'Zoboo invites a wolverine to live with him in Animal Junction, only to realize that there''s not enough space for his new pal. Wild creatures need room to roam.', '2001-04-13', 27, NULL, '2026-04-03T17:10:55Z', '2026-04-03T17:10:55Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('165b0824-5078-43eb-944a-ddcb94cf7a57', '4900fc8d-5e7e-408e-972e-ce9269d203b3', 6, 'Straight Questions, Straight-ish Answers', 'Heather treats Jen and Emily to a spa day where Jen opens up about her marriage. Shannon heads for Nashville to visit her mom and is surprised when her daughter Sophie opens up about her new relationship.', '2022-01-12', 44, '/r3X9xORmTMAdC1RUlomxmzPPdXq.jpg', '2026-04-03T16:35:35Z', '2026-04-03T16:35:35Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('165fc25c-ad24-4a56-b5c8-693a365ace7a', 'e8b959c0-6865-4332-9be1-b8f720716aa8', 21, 'Coracle', 'John visits the Bewdley Museum to see how a coracle is made after seeing some on the River Severn.', '1992-03-02', 15, NULL, '2026-04-03T17:19:37Z', '2026-04-03T17:19:37Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('16656d8c-4069-4fcb-ab8e-9ca953aea54e', 'c01ddd2a-bdb1-4c97-8d04-58f791ef1c24', 33, 'Sand Creatures', 'Meerkats, scorpions and camels start arriving after a sandstorm buries Animal Junction.', '1999-09-07', 27, NULL, '2026-04-03T17:10:55Z', '2026-04-03T17:10:55Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('1665ca20-1d03-4d23-a82e-53e2d82a9e5f', 'e03d79bd-e01f-4414-b0b3-f3b5f26e97f4', 24, 'Back To Summer', 'With only three days left until summer vacation, Frankie is ecstatic that she''s made it through another school year with the family. But her happiness turns to panic when she and Mike learn that Brick needs to write a daily journal and turn it in to Ms. Rinsky or risk not moving up to the fourth grade; that Axl hasn''t fulfilled his required 30 days of community service; and that, because of an error, Sue must prove that she never took a sick day from school in order to receive a perfect attendance award at her middle school graduation ceremony.', '2011-08-05', 22, '/hcceYGvLGFtTl4hliw4bi2e1Xd1.jpg', '2026-04-03T15:40:29Z', '2026-04-03T15:40:29Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('166869a5-3034-45f0-9add-64f0502b7f05', '70cac5ca-fb7f-4cb7-8c9b-004d44124a1d', 8, 'Walking on Broken Glass', 'While at Siggy''s retreat, Margaret opens up about her relationship with her step-children, and Teresa talks about her resentment toward Joe. Melissa and Margaret plan a fun surprise, while Siggy and Dolores confront Teresa about a rumour.', '2017-11-29', 43, '/oNfW5wSDBYQbPWqBa0npU01psT2.jpg', '2026-04-03T16:35:17Z', '2026-04-03T16:35:17Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('166aee98-2f3d-4c0d-b6bc-4914a214948a', 'e93f04c2-7344-4b93-abba-8ba1b2f8eb35', 13, 'Episode 548', '', '1973-12-05', NULL, NULL, '2026-04-03T17:36:30Z', '2026-04-03T17:36:30Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('166c0f68-2711-4cf6-b1f7-e62907c1756d', 'e03d79bd-e01f-4414-b0b3-f3b5f26e97f4', 22, 'The Prom', 'After learning that Axl text-invited the wrong girl to prom and plans to solve the situation by standing her up, Frankie and Mike demand that he meet the girl face-to-face in a timely manner to gently break off the date - or face the music and take her to the big event. Meanwhile, Sue and her friend, Carly, try in earnest to fit in with the school''s "B" crowd during lunch, and after a successful first show, Brick begins to bore Frankie and Mike with his impromptu one-man plays.', '2011-07-29', 22, '/hYiiwsgXzyfQ24T3Zpyt309Wxq7.jpg', '2026-04-03T15:40:29Z', '2026-04-03T15:40:29Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('166f29e4-4014-4376-a89d-ad9a6749ffad', '941b8c65-4454-4336-be7c-1d0591c12f90', 7, 'Pinga''s Lost Rabbit', 'Pinga is cuddling her toy rabbit. Pingu offers her his teddy in exchange, but she doesn’t want it. Pingu sneaks up and takes the rabbit, and then teases Pinga by keeping it just out of reach. Pinga cries, and Pingu thinks it’s a huge joke, but he’s not so happy when Pinga starts jumping up and down on the teddy. He tosses the rabbit away, and it lands on the windowsill. Pinga screams, and Mother and Father come in to find out what is going on. Pingu denies any wrongdoing on his part, but is told to go and get the rabbit. As he’s going to the window he trips and knocks the rabbit out of the window. Pingu is told to go and get it back and, rather reluctantly, he goes outside to get it. He tosses it into the air and it lands on the sledge, but as Pingu goes to get it from the sledge he trips again and knocks the sledge away. The sledge doesn’t stop so Pingu goes after it, following the tracks it’s made in the snow. When at last he catches up he finds that Robby has now got the rabbit. Robby won’t give it back, and he does to Pingu what Pingu was doing to Pinga, keeping the rabbit just out of reach as Pingu tries to get it! When Robby finally flips it away Pingu follows it, but he can’t find it anywhere. He’s about to give up when he sees it drifting away on an ice floe. Fortunately there’s a fishing rod leaning against the wall of a nearby igloo, and he uses the rod to catch the rabbit as it drifts past. He returns triumphantly home, but Pinga is now happily playing with the teddy, which is on a chair being offered a pretend cup of tea. Pingu offers her the rabbit but she doesn’t want it, so Pingu sits it on a nearby chair and goes away.', '2003-09-12', 5, '/5WqK9fuqSIiQEhOUMKqvQ6Ka7Gc.jpg', '2026-04-03T17:22:20Z', '2026-04-03T17:22:20Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('16747a40-fd96-44cd-a26b-05fca14d4f90', '3fc7c152-e4f6-426a-a899-36ec454c4403', 15, 'A Picture''s Worth a Thousand Words', 'Ord wants to give his mother a very special birthday gift, so the Doodle Fairy draws a map to a meadow full of Giggle Flowers.', '1999-09-22', 30, '/mQcAIBJdrtqq6QkRabASTxaXFbR.jpg', '2026-04-03T15:26:03Z', '2026-04-03T15:26:03Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('167b38d2-3118-48b5-b6ff-139438fdb36b', '70d9e397-6813-4785-887d-27d034928bae', 6, 'Pingu the Painter', 'Pingu has a pad of paper, and goes over to the shed to look around. In an old wooden container he finds a box of paints, brushes, etc. which is just what he’s looking for. He loads them onto his sledge, finds an easel and artist’s cap in an old barrel, loads the easel on to the sledge, puts the cap on his head and sets off out. After a while he comes across an interesting ice formation but, after examining it carefully from an artists perspective, decides it’s not quite right and continues on his way. He finds a block of ice that will do, sets up his easel, measures up and starts painting. He has completed a painting when Robby appears from behind the ice, pulls up a convenient block and strikes a pose! Pingu paints Robby, and has just about finished when Robby starts messing about and not holding the pose. Robby then strikes a new pose and Pingu starts afresh, but it is not long before Robby starts messing about again, which gets Pingu rather annoyed. Robby poses yet again. Pingu paints a "sad" Robby, but as he admires his third Robby painting a blob of red paint lands on the paper, which makes the face on the picture move, and change from "sad" to "surprised", to Pingu''s astonishment; Robby has abandoned posing and has found the tubes of paint! Pingu then has a paint-fight with Robby, which ends with both of them laughing and a lot of paint on the ice. Pingu then packs up and they leave together. What they don’t realise is that the mess of paint left behind on the ice is a work of art in itself!', '1995-07-20', 5, '/yUaUEauoBxaC5F2WVRLTGmJ8keC.jpg', '2026-04-03T17:22:19Z', '2026-04-03T17:22:19Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('167c41f4-ae85-4763-b310-62efddc8a21b', 'a9657e86-4135-49ce-b1f9-c295113077e1', 13, 'Down the Drain', 'Captain Scallywag accidentally pulls the plug that holds the water in Dragoon Lagoon, and it''s up to him and the friends to get the water back.', '2005-03-10', 30, NULL, '2026-04-03T15:26:04Z', '2026-04-03T15:26:04Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('1680d761-1160-47f3-b794-c8521d5a46ca', '7b8e3988-fbf3-4cfc-aeb2-782ae5a64e2d', 36, 'Abby Thinks Oscar is a Prince', 'After hearing a story about a frog who is a prince, Abby thinks that Oscar is an enchanted prince.', '2010-11-12', NULL, '/hPOSBwe1WN1Rw65NJdjy8JopLfE.jpg', '2026-04-03T17:36:46Z', '2026-04-03T17:36:46Z');
