INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('171b94cd-e52e-43e1-a154-739a9c7071b6', 'c4717644-555d-4df1-aec0-c095b101e7c0', 6, 'The Lotus Seed', 'Young people who emigrated to the United States from Asian countries are interviewed and discuss having to learn a new language and fitting in with other children their age while dealing with language and cultural barriers. Rona Figueroa reads the story of The Lotus Seed, about a woman who flees her native country during wartime and manages to save only one memento, a lotus seed given to her by her mother from the garden she tended for the emperor.', '1994-10-10', 30, NULL, '2026-04-03T17:36:18Z', '2026-04-03T17:36:18Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('1720bad8-0732-41b3-b597-a376606b94ad', '51f03551-ba41-409d-85f4-e51bddfdf82e', 7, 'Kelly vs. Bethenny', 'In one corner: Kelly. In the other: Bethenny. The two housewives square off in a diva duel during a downtown bar meeting. In other unfolding dramas, all six wives assemble at a magazine party, where Kelly reflects on her fight with Bethenny. And there''s back-and-forth tension over an upcoming tennis match.', '2009-03-31', 60, '/aYQmZU7EcWPKONrnuhEjoCv1C2A.jpg', '2026-04-03T16:35:22Z', '2026-04-03T16:35:22Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('1729d513-512a-4d59-a06c-6c46adcf325f', '8b6bbac8-e5ef-49c7-a5c1-197cfb19f772', 5, 'Divorce', 'Rogers wears a false-face to show that he is still himself inside. The Royal Electric Plane-Car arrives via a clown courier. Behind the mask is Chuck Aber, who has been divorced and doesn''t see much of his children. Thus, Prince Tuesday can relate to Aber''s feelings. Corny reveals his secret: he is now making rocking-chair-shaped pretzels. Mister Rogers shows viewers the ins and outs of an airplane.', '1981-02-20', NULL, NULL, '2026-04-03T17:35:42Z', '2026-04-03T17:35:42Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('173076c0-74aa-4de1-9857-e8e1853a0afa', '53f9624f-fcf8-4f77-82f6-d2eb3f5376ee', 26, 'One on One (1)', 'The Brown family sit down individually to discuss their past and future. As Christine says she tried to make her relationship with Kody work, he says that the wives all had the same chances as Robyn.', '2025-05-25', NULL, '/bRNpJhh2fmUk6O8zoeHdJWwBlLz.jpg', '2026-04-03T16:34:33Z', '2026-04-03T16:34:33Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('17369592-922d-424b-81b6-dbe4ad9b6c7f', '097823b3-4b9f-460d-9ccf-923af9e525bb', 8, 'Making and Creating', '', '1986-05-20', NULL, NULL, '2026-04-03T17:35:44Z', '2026-04-03T17:35:44Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('1737b15d-1769-4bfa-b239-1ed6b7e80aec', '4060ad7f-4b8f-4393-8eb1-66a150b928b6', 16, 'The Glitter Jar', 'Nina is feeling frustrated as she tries to fix her scooter. Elmo and Grover wonder how they can help Nina calm down. What if they make her glitter jars? Let''s try!', '2021-02-25', 26, '/kObJhdjgahs2jd6NOms7JToeaN4.jpg', '2026-04-03T17:36:50Z', '2026-04-03T17:36:50Z');
