INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('174f9592-9e79-466b-8c52-e7aba50afeb8', '4900fc8d-5e7e-408e-972e-ce9269d203b3', 4, 'Judge & Jury', 'The ladies gather to celebrate Shane finally passing the California bar. Despite making amends with Gina, Shannon runs into another roadblock with Emily. Noella’s situation worsens as she struggles to find answers about her husband. Heather learns about Dr. Jen’s issues with Noella and soon finds herself in Noella’s crosshairs.', '2021-12-22', 44, '/ig8kn980co6m8o4Ks52h3XY3NkC.jpg', '2026-04-03T16:35:35Z', '2026-04-03T16:35:35Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('1751dc6b-a270-4524-bd01-bd85db88299e', 'edc63a59-2fd4-442a-9343-f2872d776bdc', 1, 'Arthur''s Perfect Christmas', 'Plans are under way in Elwood City for the best holidays ever! Arthur, D.W., their friends and family make preparations for perfect gifts, perfect parties, and perfect family traditions for Christmas, Hanukkah and Kwanzaa. But, just as in real life, perfection cannot last and things begin to fall apart. Arthur learns that the joy in Christmas isn''t found in an artificial vision of the perfect holiday season, but in the wonderfully messy, imperfect world he lives in.', '2000-11-23', 55, '/76AQgJrxXtqUAGtgPhpgXJ4qIm1.jpg', '2026-04-03T17:37:54Z', '2026-04-03T17:37:54Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('175a17aa-f33f-4fa9-a75b-93d764bd3f13', 'fed71eea-5d41-479c-b12a-beb733409c5c', 11, 'Peter Piper''s Purpose', 'Telly helps Alan pick pickled peppers for each customer.', '2014-11-19', NULL, '/pUTyHof06emdOWWVO0BThQgu24U.jpg', '2026-04-03T17:36:48Z', '2026-04-03T17:36:48Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('175f9962-ab90-42d6-90a0-574fa591b07f', 'dec4a06d-731b-41e4-8b15-374f47d1f5c7', 13, 'Picking Sides', 'The wives try to regroup following a turbulent Vermont trip. Also: Melissa receives bad news about her boutique; Jacqueline''s husband reveals shocking family news; Siggy has an important conversation; and Teresa prepares for her husband''s stay in prison.', '2016-10-09', 43, '/2Zjukl6xfU5lzwmGrHzGuSg4I3E.jpg', '2026-04-03T16:35:16Z', '2026-04-03T16:35:16Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('176147f8-f990-43ec-b22b-8ae69f21323b', 'db555b98-87d6-4cd2-b7b4-973f9206cb1e', 7, 'Dance Like No One Is Watching', 'Kelly invests in a new business and goes to a Wellness Expo to practice her pitch. While Gina meets with a new lawyer about her DUI, Braunwyn and Kelly head to Las Vegas to support Emily at her dance performance. Then, the ladies travel to a wellness resort in Miraval, Arizona. At a sound bath, Kelly bonks Shannon over the head which leads to an unexpected trip to Urgent Care.', '2019-09-17', 44, '/ufcfb5arNJBOjX6OY4rmivK6fUC.jpg', '2026-04-03T16:35:34Z', '2026-04-03T16:35:34Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('176a86ce-991f-49af-8b7c-9a08770d6ba3', 'e13f4aa4-dd8a-48d5-8cc1-1c258f43e44d', 109, 'Real Housewives Confess: A Watch What Happens Special', 'The housewives get together to discuss Season 2 and update us on the recent events from behind the scenes.', '2007-03-20', 44, NULL, '2026-04-03T16:35:29Z', '2026-04-03T16:35:29Z');
