INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('17709f51-356f-4c5e-b8d9-9ce5a37d0caa', '4060ad7f-4b8f-4393-8eb1-66a150b928b6', 9, 'Sneeze a Season', 'Grover wishes he didn''t have a cold in the Fall, so Rudy uses Abby''s wand to change the season. Now every time Grover sneezes, the seasons keep changing.', '2021-01-07', 26, '/oGqzrFemwUMlTktZG4tnk8wxD0o.jpg', '2026-04-03T17:36:50Z', '2026-04-03T17:36:50Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('1772fa87-906e-4438-a4ff-47d4db142246', '04207e76-d855-4f29-a066-1732feea34b5', 6, 'It''s Not Me, It''s You', 'After the outburst at The Brownstone, a battle breaks out on Facebook when Danielle accuses Jacqueline''s teenage daughter of threatening her life. Wanting to put an end to the drama, Jacqueline and Teresa confront Ashley about the alleged attacks. Dina decides to follow her energist''s advice and sets up a face-to-face meeting with Danielle to officially cut her out of her life.', '2010-06-07', 43, '/wZD5MiWJaBOSIB81TxADTWbKp6g.jpg', '2026-04-03T16:35:15Z', '2026-04-03T16:35:15Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('17730d99-8902-446f-ab29-90038906d257', 'bf0f7445-f58f-467f-a81b-fcc2bf6bca21', 19, 'Doomsday Soup', 'Boober accidentally creates a magical soup when he throws out old laundry water and a failed radish gumbo.', '1984-05-07', 24, '/fWEZfKIZXlgHTDXx6Mzw7OHDip4.jpg', '2026-04-03T17:35:00Z', '2026-04-03T17:35:00Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('1773b256-8934-49f8-bf98-559f3ce3af19', 'e93f04c2-7344-4b93-abba-8ba1b2f8eb35', 14, 'Episode 549', '', '1973-12-06', NULL, NULL, '2026-04-03T17:36:30Z', '2026-04-03T17:36:30Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('177f5812-eb28-442f-b225-308ea7a0d218', 'a8c6182e-05e1-4b68-91a5-5126cf6c94f0', 1, 'The Boston Tea Party', 'At the direction of Benjamin Franklin, Moses, James and Henri travel to Boston in search of Sarah, who has arrived from England on a tea-laden ship. When they get to the Harbor, they happen upon the disguised colonists and discover they are raiding the very ship Sarah is on.', '2002-09-02', 30, '/jcCtkiIMgU5OkvoP62JCXAcMsA3.jpg', '2026-04-03T17:38:28Z', '2026-04-03T17:38:28Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('17837584-01a8-4eb5-8902-33f679f2c647', '53f9624f-fcf8-4f77-82f6-d2eb3f5376ee', 5, 'The Year of Release', 'Meri asks the church for a release from her marriage to Kody. Gabe opens up to Janelle about his relationship with his father. Christine is excited for her second date with David. Mykelti reveals she ate her placenta. Robyn is left in tears on Christmas.', '2024-10-13', NULL, '/yYDN2Zh1gRxRwBMq6C0AExs3SVf.jpg', '2026-04-03T16:34:33Z', '2026-04-03T16:34:33Z');
