INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('1795175e-e8e0-4638-ba71-e2a8c94dcdbd', '1d556682-d9bb-47e1-993f-0b648a8daacd', 30, 'Episode 1215', '', '1979-01-05', NULL, NULL, '2026-04-03T17:36:33Z', '2026-04-03T17:36:33Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('179c1b45-f7ff-4d48-bb5e-e4b08d6ebe4f', '4f18ac4c-8757-456c-a49a-224f00e6a9f7', 7, 'Annual Triangle Toss', 'Baby Bear welcomes the viewer to Sesame Street, when Telly runs into him, and excitedly tells him (and the viewer) that today is the Triangle Lovers Club''s annual Triangle Toss (similar to ring toss). He displays his lucky triangle vest, which is what he claims helps him win every year. When he tries it on, however, he notices it''s smaller than it was last year. Baby Bear and Leela help him put it on Telly, and they notice it''s such a tight squeeze that he can''t move his arms, but that doesn''t worry him.', '2008-08-20', NULL, '/AlbpJCSi19nrGxlesW6ssK9qJOC.jpg', '2026-04-03T17:36:45Z', '2026-04-03T17:36:45Z');
