INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('17b58786-b057-42a7-aacd-54a9fa40dc76', '4060ad7f-4b8f-4393-8eb1-66a150b928b6', 18, 'The Rainy Day Play', 'Zoe and Rosita want to draw with chalk outside but it''s raining! They become scientists and try a couple ideas, and wonder if there''s something they can use that would keep them dry in the rain. What if they use art smocks that keep them dry when they paint? Zoe and Rosita didn''t give up and they used the art smocks to keep the sidewalk dry. Now Zoe and Rosita can draw outside with chalk!', '2021-03-11', 26, '/A8H3ra41T0zoafciQtd2XyndRpg.jpg', '2026-04-03T17:36:50Z', '2026-04-03T17:36:50Z');
