INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('17d6007b-5ece-4408-98f2-17c39fe9ee53', '150d1480-f3f1-43f9-9a22-d2527756fba2', 11, 'No Business Like Shade Business', 'Gizelle hits some speed bumps trying to teach her daughter Grace to drive; Ashley''s family isn''t happy with Michael''s proposed venture into the movie business; Karen and Wendy work on putting together their candle lines.', '2021-09-19', 42, '/rRZes20f0fBCQ81intj82Xd6OMt.jpg', '2026-04-03T16:35:40Z', '2026-04-03T16:35:40Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('17d9f76c-108e-42c3-b8f6-299d371f0752', '1a534647-384b-4c00-bb6c-a3371ad962eb', 41, 'On the Road', 'Hit the road with the Pawn Stars to revisit the best items ever seen outside of the shop: Rick''s international trip to London where he finds some rare American maps, a vintage piano used by the Rat Pack found within the home of eccentric collector Lonnie Hammergen, an exclusive tour of an L-39 Soviet Albatros Fighter Jet, and an ancient Samurai helmet that causes Rick to detour while traveling to the Sturgis Motorcycle Rally.', '2015-08-10', 21, '/btwPCzZJeq9a66ZbF2AaL8stJ30.jpg', '2026-04-03T16:34:20Z', '2026-04-03T16:34:20Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('17dbdbd3-e263-4ee8-8717-44fafdd486db', '262e8e7c-fa78-4578-a216-add6f184c4d2', 21, 'Sister Wives on the Strip', 'The Sister Wives get makeovers and head to the strip for a night on the town while Kody stays home to babysit all the kids. How will they react when they come face to face with all the "adult" entertainment Vegas has to offer?', '2011-11-20', NULL, NULL, '2026-04-03T16:34:27Z', '2026-04-03T16:34:27Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('17e1a160-3b55-45a5-80fe-56c101f2b241', 'f4d370ca-3c39-40a8-911d-e2b5e7c6b0d7', 3, 'The Castle', 'While Little Bear and Duck are sorting through their farm set they find an old piece of castle wall. This gives them an idea and with the help of the other toys they create a new castle complete with a moat and drawbridge. Old Bear explains what sort of games you can play with a castle and they find a clever way to divide themselves into teams to play. With Little Bear firing paper cannon balls from the battlements, it looks as though it will be hard for Bramwell’s team to invade the castle but he has a very clever plan.', '1996-09-18', 10, NULL, '2026-04-03T17:18:56Z', '2026-04-03T17:18:56Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('17e2f70c-20bb-4d07-990f-b29819e67fd4', 'bbfee3b4-9c95-48a6-beaa-791fa08b1f43', 15, 'Episode 15', 'They said it could not be done! For 72 miles through 12 tunnels and over 17 viaducts, the railway line from Settle to Carlisle climbs over some of the most spectacular countryside in Britain. This famous track was one of the last important lines to be laid - it was opened to traffic in 1876. Simon and Goldie follow the tracks of the pioneers who created one of the engineering master-pieces of the Victorian age.', '1983-10-31', NULL, NULL, '2026-04-03T17:21:56Z', '2026-04-03T17:21:56Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('17e3001e-c7f0-43a0-9c4f-ce04695aa865', 'd199804f-ccf5-4e36-8929-56c1e356b74d', 31, 'Episode 956', '', NULL, NULL, NULL, '2026-04-03T17:36:32Z', '2026-04-03T17:36:32Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('17e4a0d2-a722-4222-bee2-dee82f12ff1a', 'd589b670-2e75-4922-9f56-029b48e54927', 18, 'Look Back: How It''s Going', 'All but one of the Sister Wives have fallen out with their husband Kody, but how did we get here? The Browns look back at the huge ups and downs of the relationship rollercoaster this family has been on.', '2023-12-31', NULL, NULL, '2026-04-03T16:34:27Z', '2026-04-03T16:34:27Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('17e51a32-5ff6-43af-8ef2-7b585a43439d', '8730c55e-8443-44b0-afef-a369c478b14f', 56, 'Apples and Bananas 2', '', NULL, NULL, NULL, '2026-04-03T15:26:09Z', '2026-04-03T15:26:09Z');
