INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('182b3d87-fd52-4061-b7e5-16761cebfdbb', 'e3a28669-91b5-45f7-bb73-5006acc084e8', 23, 'Washday', 'The sheep use the farmer''s clotheshorse as a merry-go-round - the garments get dirty and have to be washed before the farmer returns.', '2007-09-04', 7, '/nycp3c730k7gmaTZ7NnBKkuy0i.jpg', '2026-04-03T17:39:31Z', '2026-04-03T17:39:31Z');
