INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('184d1790-f05d-43c3-8a8a-236c279cdb6d', 'd123fd65-efb7-4ebb-a23e-190c447791cf', 13, 'Reunion Part 1', 'The ladies reunite to discuss what happened during and after the season; Larsa gets grilled about her looks and OnlyFans; Julia reveals shocking details surrounding the death of her son; Nicole, Marysol and Alexia rehash their Hamptons drama.', '2022-03-03', 44, '/52GzLkH8TBtpCpB0T5tHwkIJHD.jpg', '2026-04-03T16:35:11Z', '2026-04-03T16:35:11Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('1854e976-d0dc-481f-8931-cdb4a93a52f4', 'ecb64ef3-4f80-45a7-b4a9-c04434b02e35', 7, 'Anytime, Any Mace', 'Prepare for battle with the Pawn Stars as Rick checks out a medieval mace. Will it be a fair fight for this primitive weapon or is he in for a low blow? Then, Rick and the Old Man check out a set of cap guns from the 1950s. Will nostalgia force them to pull the trigger? And later, the Old Man sends Corey and Chum on a simple errand that turns into a daylong adventure. Will they make it back in one piece?', '2014-01-23', 21, '/Ltdxn8pUaXA2x1gzqkMSLIVcmI.jpg', '2026-04-03T16:34:19Z', '2026-04-03T16:34:19Z');
