INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('186669a5-cc37-47fc-ad7f-fc6aa8137a5e', '7c542833-ed0a-4272-9c53-e822408ab434', 24, 'The Taste of Pontypandy', 'James has the idea of using the horse and cart to deliver his team''s forgotten cherry pop to a tasting competition. But when the pop gets shaken up and starts to pop open, scaring the horse, they are soon on a runaway horse.', '2024-11-08', 10, '/sOtKDcEmRvjZoKEEIQLYknkQmDv.jpg', '2026-04-03T17:14:42Z', '2026-04-03T17:14:42Z');
