INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('19232443-94b9-40b8-8d63-00c24e0b6921', '4d2cac0f-38fd-438b-8afa-acf43952e535', 245, 'Episode 245', 'Christopher Trace and Valerie Singleton introduce a magazine programme for younger viewers. Including Giant Modelling, an outsize dolls'' house kit. Little Watha: Part 4: The Rain by Oliver Postgate. The wicked Medicine Man banishes Little Watha from the Popangwawa Tribe, but the Eagle and the Beaver help their Brother. Told by Peter Hawkins and Patricia Hayes.', '1963-09-02', NULL, NULL, '2026-04-03T17:21:47Z', '2026-04-03T17:21:47Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('19240b63-7d55-4ccf-a493-0e1bdfe431f8', '8c0f12e1-5379-4a27-aca2-b69401a33b0f', 13, 'Arthur''s TV-Free Week', 'Everyone has all pledged not to watch TV for one whole week.', '1997-10-28', 13, NULL, '2026-04-03T17:37:55Z', '2026-04-03T17:37:55Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('192939d9-837f-4a77-bd0d-45d054af4abc', '4d2cac0f-38fd-438b-8afa-acf43952e535', 333, 'Episode 333', 'Valerie Singleton thrives on variety, which she finds in abundance on Blue Peter. Her assignments have taken her on whirlwind trips, from a day in Africa to a near-trip to Bangkok, and a quick jaunt to Boulogne, where she was described as "une jeune et jolie personne de 27 ans." "I can''t bear things to be the same every day," she explains, preferring the unexpectedness of the job to her previous role as an announcer. Since joining the show in September 1962, Valerie has become a favorite among children. She has found that her wide interests—including riding, yachting, and skiing—often feature in her reports. She also enjoys crafts and has a great fondness for animals, especially Jason and Petra. A former actress, Valerie attended RADA before moving into TV plays and commercials. The opportunity to become an announcer presented a difficult choice, and she admits she "hankered after" acting for a long time. However, she clearly loves Blue Peter, and its audience loves her in return.', '1965-02-04', NULL, NULL, '2026-04-03T17:21:47Z', '2026-04-03T17:21:47Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('193a08eb-edfa-47f5-a126-13fd5d0a098a', '8a5892f6-ccb7-4f02-9a5a-85b134b5f0cf', 3, 'Bluebell', 'A good donkey will always do what she is told, even though she has to run rather a long way to do it; luckily there are wheels for the return journey.', '1976-02-19', 5, NULL, '2026-04-03T17:24:25Z', '2026-04-03T17:24:25Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('193e9e0f-662d-4769-aafb-bea8d252335d', 'e48599f8-66ff-4c0f-9274-65b9ae1cda9e', 77, 'Episode 77', 'Narrow Escapes  JOHN, PETER and LESLEY relive some of their most heart-stopping moments during the past ten years. Hold your breath with them as John falls five miles, Lesley escapes death by inches and Peter crashes at 60 mph straight through a furniture van!', '1977-06-16', NULL, NULL, '2026-04-03T17:21:53Z', '2026-04-03T17:21:53Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('19487868-b3d7-42cf-81fd-966504fb953a', '7da1b693-04d1-4168-a0a0-9715407c04c6', 2, 'Sam''s Birthday', 'A broken birthday present for Sam goes haywire after James attempts to fix it.', '2016-05-07', 10, '/qg2I6tODRHFbvDg6T3f6eNUQUDz.jpg', '2026-04-03T17:14:40Z', '2026-04-03T17:14:40Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('1949dcc0-736d-4283-91e3-52b5d8fd22cb', 'dbd3583f-e9b2-46d1-a37e-309eb666e233', 4, 'Jewels Be Dangled', 'Phaedra does the proper Southern thing and apologizes to Kim for her husband''s behavior at Kim''s baby shower. Shereé takes Phaedra along to see her Chateau Shereé construction site, only to find no progress has been made. Kandi plans her 35th birthday bash despite a case of the biological clock blues. The party heats up when Phaedra presents a “Ridickulous” surprise that neither Kandi – nor her mom – will ever forget. Meanwhile, Cynthia’s attempt at making peace between her husband and sister backfires, leaving her torn between her new family and her old one. Kim tries to figure out how she will handle the birth of her new son.', '2011-11-27', 43, '/gxnua3fWBy3JtGKw4Z95QWLDrH6.jpg', '2026-04-03T16:34:45Z', '2026-04-03T16:34:45Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('194d1b9b-321d-4cde-b786-01ed405a4bd7', 'a8c6182e-05e1-4b68-91a5-5126cf6c94f0', 29, 'The Great Galvez', 'Sarah is in London with her mother and is having doubts about belonging there. In the end, she finally decides she is an American.    Meanwhile James and Henri are traveling a long ways to give a letter to Galvez, but on the way are Brittish soldiers, will they stop them and find the letter?', '2002-11-07', 30, '/om62w0QkPqc6L3d4wFmhsZ57gDm.jpg', '2026-04-03T17:38:28Z', '2026-04-03T17:38:28Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('194e306d-8142-40dc-9dbf-535b7c28138e', '7c542833-ed0a-4272-9c53-e822408ab434', 3, 'Star Spotter of the Year', 'When James tries to win the star globe in a star spotter competition, he ends up breaking the globe and falls into the water chasing it', '2024-10-02', 10, '/g2KxS1yy7YBDRobMQluj8rG1aRG.jpg', '2026-04-03T17:14:42Z', '2026-04-03T17:14:42Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('194ecc63-db0a-47d3-94f6-0b05048d7695', '871570b4-bf2f-4ba1-9940-65fb932cb009', 10, 'Homecomings and Confrontations', 'Mama Joyce confronts Phaedra, Porsha confronts her sister, and Kenya may finally confront her mom!', '2016-01-10', 43, NULL, '2026-04-03T16:34:47Z', '2026-04-03T16:34:47Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('195002e1-996b-4735-889c-782fc4bfe49f', 'a5f2554f-07b6-4471-ace0-46b97c492097', 3, 'The Demon Headmaster Strikes Again (Part Three)', 'Lloyd goes missing and the team try to find him. Rose continues her mission.', '1996-10-09', 25, NULL, '2026-04-03T17:40:35Z', '2026-04-03T17:40:35Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('19567dae-5ab8-4181-a880-5d1f4a7b3524', '6c1ec19f-74df-4f35-9a61-17b98175d826', 15, 'Sex, Lies, and Text Messages', 'Kyle and Dorit surprise Teddi with a baby shower, but Brandi reveals a few surprises of her own. Denise and Garcelle lament over how they think Lisa has changed – but Lisa has a very different take on things. Erika leaves LA and jets off to Broadway.', '2020-08-19', 43, '/xOHQVnQjakbKg0A4O0ftOqE492X.jpg', '2026-04-03T16:34:58Z', '2026-04-03T16:34:58Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('195baec8-9b85-4ec8-a057-c321f560f662', 'efd2082e-32f5-4edd-9a7b-a4326d6992c9', 7, 'New Year''s Eve on Sesame Street', 'It’s New Year’s Eve on Sesame Street! Rosita and Telly try to help Elmo stay awake until midnight so he can celebrate with his friends.', '2018-12-29', NULL, '/7D1t9l4XseipUtGjlULZdqWQNnW.jpg', '2026-04-03T17:36:49Z', '2026-04-03T17:36:49Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('195d49b5-337a-4fbb-bf23-fa7ed9233991', 'e1063f87-66c2-4e2d-a913-53362941aa19', 59, 'Episode 334', '', '1972-01-27', NULL, NULL, '2026-04-03T17:36:29Z', '2026-04-03T17:36:29Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('195e1a0d-faff-4c4a-bdec-610d19e722e2', '98d80972-e53a-43dd-a03a-7703465e6f87', 31, 'Book ''Em Rick', 'Read up on the Pawn Stars when one of the first books ever printed comes in the shop. An incunable from the 15th century, will the guys judge this worm-eaten work by its cover? Then, Corey and the Old Man hear the sweet sound of music when a sitar strums by the shop. An Indian instrument popularized by the Beatles, can it score a big hit? And later, the guys jump through flaming hoops for an ID card belonging to the late stuntman Evel Kneivel.', '2013-03-04', 21, NULL, '2026-04-03T16:34:18Z', '2026-04-03T16:34:18Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('195fa0a6-a0bb-4454-9826-7041a056fd51', 'a605edf8-69ba-46db-8c0c-523b1ef5447b', 65, 'Episode 65', 'with John Noakes, Peter Purves, Lesley Judd', '1973-04-30', NULL, NULL, '2026-04-03T17:21:51Z', '2026-04-03T17:21:51Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('1966161d-a261-4bba-822f-242f3eb84eed', '200eca8d-ccb8-4470-b0fa-868d95b41c33', 4, 'Oathkeeper', 'Dany balances justice and mercy; Jaime tasks Brienne with his honor; Jon readies his men.', '2014-04-27', 56, '/fg0ImcTfCinFq7iu21BahGD3fPr.jpg', '2026-04-03T15:40:36Z', '2026-04-03T15:40:36Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('196716a7-0098-4f2a-aca2-6b6e61cefa03', '1f34e241-4c1d-4586-921a-1c5aeb1fbbaa', 45, 'Oscar writes Grouch poems', 'Snuffleupagus wants to play football with Slimey, but Oscar thinks the size difference will make the game unfair to Slimey; he suggests hide and seek instead. Snuffy looks everywhere on Sesame Street and can''t find Slimey. Oscar shows Snuffy that Slimey has been hiding in Snuffy''s fur the whole Gordon comes across Oscar reading his book of Grouch Rhymes to Irvine.

Sponsors: T, Z, 10', '1986-01-17', NULL, NULL, '2026-04-03T17:36:36Z', '2026-04-03T17:36:36Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('1967ed71-d86b-4b89-9f94-7e623874711d', '5c1b881f-ac58-4d72-b63f-209952d4f902', 8, 'Episode 8', 'Expedition Egypt  The amazing child weavers of Herrania, whose tapestries are sought after by collectors all over the world.', '1979-10-04', NULL, NULL, '2026-04-03T17:21:54Z', '2026-04-03T17:21:54Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('197eb4ec-1ac6-4411-b516-e190ccb703d4', '8c0f12e1-5379-4a27-aca2-b69401a33b0f', 17, 'Lost!', 'Arthur gets on the wrong bus to his swimming lessons and gets lost.', '1997-10-30', 13, NULL, '2026-04-03T17:37:55Z', '2026-04-03T17:37:55Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('1981ce9f-69f5-4f9f-af86-fd415c70c9c8', '54c29014-2dbd-49ff-a23f-cf4c546e0b3a', 8, 'Unforgivable Debt', 'Ramona reveals Sonja''s financial secrets. Elsewhere, Kristen visits a new modeling agent; Sonja is stood up by her 23-year-old flame; and the heat is on at a spa when Kristen and Ramona have a dispute.', '2014-04-29', 60, NULL, '2026-04-03T16:35:23Z', '2026-04-03T16:35:23Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('198451b3-e9ea-4e7a-b3dd-77480c23bfa7', 'fd0f7dfb-28aa-4687-9ef8-8ff0088ce25a', 14, 'The Wild Brunch', 'Snuffy has to figure out how to remember everyone''s order when he helps out at Hooper''s Store.', '2013-11-21', NULL, '/kueQHoY66T42pOkyTb9YIZMeUcp.jpg', '2026-04-03T17:36:47Z', '2026-04-03T17:36:47Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('198b582d-59c1-4474-b0de-0cbfc71fec94', '3415030f-f54d-42b9-a290-aaa05e246d86', 11, 'Tell All: Part 1', 'In the latest two-part installment of Sister Wives Tell All, The Brown Family sits down to discuss this season''s celebrations, confessions, and jaw-dropping  moments. From weddings, to catfishing, and stories of coming out, nothing is off limits.', '2017-01-22', NULL, NULL, '2026-04-03T16:34:30Z', '2026-04-03T16:34:30Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('198b9909-2d7e-4946-a16c-83a7bb2d8a74', 'ea73e13c-6962-4804-8305-c303df65f89f', 32, 'Preparing for the carnival', 'Rogers uses a balance scale to compare weights. The Neighborhood of Make-Believe is beginning plans for their upcoming carnival. X and Lady Aberlin demonstrate the talents they will display there.', '1969-03-26', NULL, NULL, '2026-04-03T17:35:38Z', '2026-04-03T17:35:38Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('198cb8cf-3537-4cf7-a452-748dce29bdac', 'db555b98-87d6-4cd2-b7b4-973f9206cb1e', 11, 'Hot Mess Express', 'For Shannon’s birthday, the ladies celebrate with a trip on a train to Del Mar and where Shannon’s goal is to find a man to kiss. Still upset over the canceled double date, Gina avoids Emily, angered that the date may have been a bad set up from the start. Gina feels betrayed, but Emily insists she only had good intentions. Tamra and Braunwyn’s flirtation finally comes to a boil. Kelly has an issue communicating with Dr. Brian. Vicki and former housewife Meghan come along to the party.', '2019-10-15', 44, '/6Inuwhr7BvRr54AUpop7IyQ23Bd.jpg', '2026-04-03T16:35:34Z', '2026-04-03T16:35:34Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('1998a5bf-249d-4c97-af68-2d6eef9d7699', '7b8e3988-fbf3-4cfc-aeb2-782ae5a64e2d', 21, 'Sesame Street Fairy Tale Science Fair', 'Baby Bear and Telly are reporters at the Sesame Street Fairy Tale Science Fair! Everyone’s favorite fairy tale characters are solving problems with science. Little Red Riding Hood is the first fairy tale scientist and she can’t tell the difference between her granny and the Big Bad Wolf. She decides to solve her problem by observing and comparing. After she looks closely and carefully, she points out their similarities and differences and discovers who her real granny is! Cinderella, who just loves science, asks a question about whether a pumpkin will float or sink. They form a hypothesis and conduct an experiment to test it. Baby Bear and Telly think that it will sink, but the pumpkin actually floats! Next, the Three Little Pigs become worried about the Big Bad Wolf blowing down their house. They discuss what they already know: the wolf is coming and he can huff and puff and blow them away. They decide to build a house to protect them, but can’t agree upon which material is the best. Baby Bear helps them design an experiment to figure out which material is the sturdiest. They each make a hypothesis and use a fan to see which material won’t blow away- straw, sticks, or brick. The pigs conclude that brick is the best material. The Big Bad Wolf arrives, but to his disappointment, he can’t blow down the brick house. Science saved the day and solved lots of problems on Sesame Street!', '2010-12-16', NULL, '/lWb1CXkHu69zKWJo3tbc0fvP2Ty.jpg', '2026-04-03T17:36:46Z', '2026-04-03T17:36:46Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('199b05bf-e514-4811-b650-0c530751fa10', '10da3800-1902-4816-ab86-d911b2ed6ff2', 1, 'Rip Van Winkle', 'Rip Van Winkle is off in the Catskill mountains one day when he finds a gathering of ghosts. After drinking wine and socializing all day, he falls fast asleep. When he awakes, he discovers it is 20 years later! An interesting version of the Washington Irving Tale.', '1987-03-23', 51, '/p6ynY4xseABkPct4Y3Z2l9ln1yl.jpg', '2026-04-03T17:38:42Z', '2026-04-03T17:38:42Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('199e7933-9dfc-4907-bdf1-3615472ba972', '136b81d3-964d-4b8f-a214-92f00d96d6b9', 109, 'Inspector Bird and the balloons', 'Inspector Bird investigates the curious Case of the Missing Balloons and follows cryptic clues around Sesame Street. Through detective work, he discovers that the balloons escaped when someone carelessly left a store door open. Inspector Bird successfully reunites the wayward balloons with their delighted owner.

Sponsors: K, S, 10', '1984-04-19', NULL, NULL, '2026-04-03T17:36:35Z', '2026-04-03T17:36:35Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('19a4e06f-812f-4318-a2f9-6fc40f582651', '941b8c65-4454-4336-be7c-1d0591c12f90', 14, 'Pinga''s Balloon', 'Pinga is trying to blow up her balloon, but she’s not having any success. Pingu comes by and says he’ll do it, but can’t blow it up either. He then has an idea and goes off to the shed. Meanwhile Father comes by and also tries to blow up the balloon, but despite stretching it and blowing hard he can’t inflate it. Pingu comes back from the shed with the bicycle pump and tries with that. He successfully blows the balloon up, but it then comes off the pump and zooms around the room, finishing off by collecting Pinga and shooting her outside into a heap of snow. Pingu and Father rush to get her out. Father then again tries to inflate the balloon. This time he succeeds in getting some air into it and ties off the end, but manages to do it round his wrist. Pingu pulls it off and gives it to Pinga, but as she strokes it, it goes down. They go back inside, and see Mother livening up the fire in the stove with some bellows. This gives Pingu an idea, so the balloon is attached to the bellows and he and Father bounce Pinga up and down on the bellows. The balloon inflates and Pingu ties it off and gives it to Pinga, who cuddles it and gives Pingu a big kiss.', '2004-01-21', 5, '/3r68gRepeQJsmnCJzN1qa6Kc2pF.jpg', '2026-04-03T17:22:20Z', '2026-04-03T17:22:20Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('19bad09b-d712-42fb-b81d-37a491b30c9b', '4c79c0b6-21a4-4277-8967-be1e791efdbe', 7, 'Pinga in a Box', 'Pinga is playing in the kitchen, and bumps her head several times on the table. She sees her cuddly rabbit on top of the toy box and goes over to get it. Also on the top of the toy box is an empty box and, as Pinga gets her rabbit, the box falls upside-down over her. She wanders around bumping into things, but as she’s got the box over herself she doesn’t get hurt. She goes past Pingu, who is sitting on his bed reading, and he grabs hold of the box and lifts it off her. Pingu has an idea! He explains his idea to Pinga, then turns the box the right way up, puts Pinga inside, tells her to be quiet and puts on the lid. He calls Mother, who comes to see what he wants. Pingu tells Mother that the box is for her, and as she’s about to open it to see what it is Pinga jumps up in the box and startles her. Mother sees the funny side of it and gives Pinga a cuddle. Pingu and Pinga, who has her rabbit with her, then go out on the sledge, taking the box with them. They come to Grandfather’s house, and stop. Grandfather is inside, banging, so they put the box outside the door, Pinga hides inside, Pingu knocks on the door and then he hides. Grandfather opens the door, spots the box, looks it over carefully and then goes to open it. Pinga jumps up as she did before, startling Grandfather who almost has a heart attack with the shock. When he recovers he tells them off for playing such a prank and makes Pinga cry. Then he sees the amusing side and gives them a hug. Pingu and Pinga continue their journey and reach the post office. Nobody is about, so they set the prank up again, putting the box with Pinga inside next to some other boxes by the door. Pingu hears Father approaching on the motorised sledge and quickly hides. Father loads some of the boxes, including the one that Pinga is in, onto the sledge and drives off to deliver them. Pingu comes out of hiding, spots that Pinga has dropped her rabbit, picks it up and runs shouting after them. Father doesn’t hear, and stops only to deliver two of the boxes to one igloo and a third box to another, leaving Pinga’s box still on the sledge. Pingu is still rushing to catch up, but stops when he passes the second igloo as the owner is still outside with the box. He grabs the box and empties it on the ground to see if it’s Pinga’s box, but it isn’t, so he tosses the box aside and rushes on, leaving a puzzled recipient behind. He catches up just as Father is about to deliver Pinga’s box to a third igloo; Father has picked up the box and is carrying it round the sledge. Father stops when he sees Pingu, and Pinga pops up out of the box and startles Father, who then laughs. Father puts the box on the ground and Pingu reunites Pinga with her rabbit, and gives her a big hug.', '2005-01-11', 5, '/vAqu5J5RNEXzow4zPbLNNy1ERot.jpg', '2026-04-03T17:22:20Z', '2026-04-03T17:22:20Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('19be6b95-e1b0-42a2-b0ad-420dc2c5d876', '4bf3b194-81b8-4726-8850-62b05609eac8', 27, 'Operation W.R.A.P.', 'The young Wombles learn first aid.', '1975-10-21', NULL, NULL, '2026-04-03T17:23:20Z', '2026-04-03T17:23:20Z');
