INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('1a021b42-b767-441c-912b-1369454e7ca8', '78a02d50-e3dc-4549-844a-3cf357a32ef4', 14, 'Loose Lips Sink Ships', 'The ladies return to Atlanta after a dramatic end to their glamping getaway. Cynthia begins planning her Cargo Fashion Show, presenting momager Shereé with an opportunity for Kairo to participate. Porsha wonders if Todd is ready for a serious relationship and decides to confront him with an ultimatum. Phaedra hears major news concerning her divorce, while Kenya gives Cynthia a special gift to help jumpstart her dating life post-divorce. Kandi and Porsha meet for the first time since the shocking rumors surfaced to see if they can hash out their unresolved issues.', '2017-02-19', 43, '/yvreTqK3DVmNVeT1ko6XZobdJS.jpg', '2026-04-03T16:34:48Z', '2026-04-03T16:34:48Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('1a041a60-db48-4efe-acba-c506afec2265', '4d2cac0f-38fd-438b-8afa-acf43952e535', 100, 'Episode 100', 'A magazine programme for younger viewers introduced by Leila Williams. Baby Elephants in fact and fiction including Packi, a new story told and drawn by Tony Hart.', '1960-09-16', NULL, NULL, '2026-04-03T17:21:47Z', '2026-04-03T17:21:47Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('1a05bbd4-2e1a-47ef-9b8c-46211ceb338e', '262e8e7c-fa78-4578-a216-add6f184c4d2', 20, 'College-Bound Browns', 'The Brown family nervously accepts an invitation from a religious professor to talk to her students in Boston. Anxious about the question they will face, how will they respond? Meanwhile, the older teens tag along to visit some of Boston''s best colleges.', '2011-11-13', NULL, NULL, '2026-04-03T16:34:27Z', '2026-04-03T16:34:27Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('1a0a0266-37b5-4159-8203-47a8278b179e', 'c4d795ae-6afa-47d6-9819-4dd057030a3c', 22, 'Reunion (Part 2)', 'Kandi clues Porsha in about reports regarding her and Dennis'' relationship timeline; NeNe and Gregg talk about his cancer diagnosis and their marriage; tempers flare as the women discuss the Bye Wig party.', '2019-04-14', 43, NULL, '2026-04-03T16:34:48Z', '2026-04-03T16:34:48Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('1a0b944e-be47-4d1b-b62c-20fbdea5be24', 'b590e3d8-e4a6-4360-ba5d-3e2248899d2a', 14, 'Learning', 'The school at Someplace Else is ready to stage their field trip through the Neighborhood of Make-Believe. But a major stumbling block emerges when James Michael Jones shows off his learning machine on his head. Rogers talks to blind jazz saxophonist Eric Kloss at the neighborhood library.', '1992-01-31', NULL, NULL, '2026-04-03T17:35:46Z', '2026-04-03T17:35:46Z');
