INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('1a150f03-f847-450b-b3c9-9cc5920be78e', '95eff6e0-032d-45f2-8003-826d9c82b439', 2, 'The Stake Out', 'Jerry meets an attractive woman at a party but by the time she leaves, he has only learned where she works. Jerry stakes out the mystery woman''s office with George so that he can “casually” bump into her.', '1990-05-31', 23, '/zPMl6UTCwZVMQZvdXMBKAuYzLQa.jpg', '2026-04-03T16:34:09Z', '2026-04-03T16:34:09Z');
