INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('1a95aa87-616c-489e-9885-3db685c2d032', 'a6ed03e0-c05f-48f8-9f56-3f1da50e1792', 55, 'Episode 1370', '', '1980-02-08', NULL, NULL, '2026-04-03T17:36:33Z', '2026-04-03T17:36:33Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('1a98d7c3-24ae-4414-a1ca-d9847fa3559f', 'fc120008-c5c4-47d7-a3a9-91a401394c41', 22, 'Visit the Dentist', 'Sister Bear has a loose tooth. Brother scares Sister by telling her that the dentist will pull out her tooth with a pair of "yankers". Not only that, Brother has a toothache from eating too much candy. They both hide their dental problems until Mama finds out and takes them to the dentist. Brother gets a cavity filled and Sister''s tooth falls out at the dentist''s office.', '2003-02-04', NULL, '/5Cg7MN8STW5DfT0gxsLPtV1hibK.jpg', '2026-04-03T17:40:21Z', '2026-04-03T17:40:21Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('1aa0f392-6969-449c-9a92-d3439ce50fd5', 'f07b8794-5625-4682-aae1-e56966b4c7a8', 19, 'I Scream, You Scream', 'Jody and the kids learn that dealing with a difficult situation is easier when you’re able to talk about your feelings, especially with issues like divorce and remarriage. Sizzle and Nuzzle think of ways to organize the basement. Julie and Ben do not appear in this episode.', '1996-02-08', 29, NULL, '2026-04-03T17:12:21Z', '2026-04-03T17:12:21Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('1aa7b452-384c-4a85-999a-16a8cf98888a', 'ba99b779-cada-43a7-902a-2adb472c2e30', 5, 'Episode 5', 'The family have taken up refuge in an old boot that they have found in the forest. This is the base camp for Pod''s excursions out to try and find another family of borrowers, one that is supposed to live in a badger''s nest somewhere nearby. This episode introduces a new borrower, a young boy about Arrietty''s age that lives in the forest.', '1992-12-06', 30, NULL, '2026-04-03T17:17:47Z', '2026-04-03T17:17:47Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('1aa91a34-dd21-4ab6-848c-5db987370ad1', 'd64c5d0c-41a0-4404-88e7-55c405302d79', 10, 'Valar Morghulis', 'Tyrion wakes up in a new world; Dany goes to a strange place; Jon proves himself.', '2012-06-03', 64, '/u46jn12qEyaCOe1oqJBwPvL5d7R.jpg', '2026-04-03T15:40:36Z', '2026-04-03T15:40:36Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('1aaa1b26-d940-427b-9b3e-8bf6ee2a3115', '4d2cac0f-38fd-438b-8afa-acf43952e535', 346, 'Episode 346', 'with Christopher Trace and Valerie Singleton.', '1965-03-22', NULL, NULL, '2026-04-03T17:21:47Z', '2026-04-03T17:21:47Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('1aae80d6-71c4-4982-81dd-f6f648cf851b', '6f731e6b-d3c5-4de6-84e1-7a19cb650e86', 25, 'Legends of Rock', 'Go wild with the Pawn Stars when a hand-painted, signed guitar from Def Leppard''s Phil Collen rocks into the shop. Will Rick "Pour Some Sugar" on his offer or will he have to call in a special guest? Then, a pair of sneakers signed by NBA legend LeBron James hit the floor. Will it be an air-ball or a three-pointer for Chum? Next, Rick finds the time to check out a 19th century carriage clock. Will he get wound up over this French classic or will it turn into a ticking time bomb? And later, an original Mogen David wine ad displays itself. Will Rick like what he sees or end up with a bad taste in his mouth?', '2016-02-03', 21, '/lIV6Wr73JxnkkQL8Ld6otbe9ddA.jpg', '2026-04-03T16:34:20Z', '2026-04-03T16:34:20Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('1abb239f-e921-40dc-9fc0-566c51a693f7', '8bae6aa3-4b55-4fa6-bc15-8f4317bd1f13', 33, 'Episode 33', 'Lady Elaine is prepared to go to the Moon by any means. Later in the visit, Rogers goes to the Brown Marionette studio to work on a piece with Chef Brockett.', '1972-04-05', NULL, NULL, '2026-04-03T17:35:40Z', '2026-04-03T17:35:40Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('1ac700c8-972e-4169-b85e-e96c31360b33', 'f1959b84-1930-4f85-b2fd-9000b3abf48a', 15, 'Episode 794', '', NULL, NULL, NULL, '2026-04-03T17:36:40Z', '2026-04-03T17:36:40Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('1ad1d798-423c-4b4e-a81f-89f6b61cc6f5', '9ae29d08-7ce8-47f9-8584-2d3e861067a8', 7, 'One Minute', 'Hank''s increasing volatility forces a confrontation with Jesse and trouble at work. Skyler pressures Walt to make a deal. Gus'' actions have severe consequences.', '2010-05-02', 48, '/4yyVAkAQhzc5URhJJiy21biH3FJ.jpg', '2026-04-03T15:40:33Z', '2026-04-03T15:40:33Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('1adb3fda-9497-4627-8211-c16f646b3209', 'cefd1496-b649-4c62-aef9-35a22558ac08', 2, 'Haute Dogs of Dallas', 'Stephanie makes a play to put a crack in Brandi’s newfound friendship with LeeAnne, but it backfires turning Cary and LeeAnne against her. Meanwhile, Travis drops millions on a house in the city, but Stephanie is the last to know. D’Andra makes moves towards taking over her mother’s cosmetics business, but it won’t be easy. And fur flies when Brandi and Stephanie meet again at the Howl-O-Ween dog costume contest.', '2017-08-21', 60, '/joyaVtX1vSEiL6YeG94ZkondnZz.jpg', '2026-04-03T16:35:04Z', '2026-04-03T16:35:04Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('1add17b2-2f19-4fcf-9175-6c0a9ddcc625', '13ecb08f-a000-49f9-8d96-54c16c3ad653', 5, 'Breakage', 'Hank suffers from the aftermath of his encounter with Tuco. Meanwhile, Jesse hires a crew to get their product out on the streets.', '2009-04-05', 48, '/bPQxF63jhfT5eNYjhzuGEO7oMQg.jpg', '2026-04-03T15:40:33Z', '2026-04-03T15:40:33Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('1ade1806-4e9c-4978-a2f9-8032c60ac361', '73ae1459-ba91-4185-a9da-bf6f2844af49', 17, 'Back On The Hump', 'The chaos in Cancun continues; Luann confronts Dorinda about her anger, while Ramona tries to forgive Leah for her behavior; Dorinda organizes camel rides and lunch on the beach for some bonding before they celebrate Sonja''s birthday.', '2020-08-06', 44, '/qKlTpoO3xRv1N6HiEczCOxqvCXK.jpg', '2026-04-03T16:35:25Z', '2026-04-03T16:35:25Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('1ae41de1-12f3-46f5-94d6-7cc5191663da', '9c5608b2-5111-48bc-a907-7f93472c1e03', 24, 'Trashgiving Day', '', NULL, NULL, '/op1gekKvOiqR00mq1SW59lyff4I.jpg', '2026-04-03T17:36:47Z', '2026-04-03T17:36:47Z');
