INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('1aee4ed9-fb05-472b-9fee-19a104a6fd50', 'ad4e4348-3334-4a08-8928-455d9ba524c1', 9, 'Jean-Pierre Rampal', 'Miss Piggy is cornered by flautist Jean-Pierre, who wants to speak French with her. She claims to have laryngitis, whispering, "My vocal coach told me not to speak French. I''m not even supposed to eat French fries!"', '1980-11-30', 26, '/u0ZSNef8equYKFWJFIVyunvulLC.jpg', '2026-04-03T17:35:25Z', '2026-04-03T17:35:25Z');
