INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('1afacddd-d7fb-439f-8ade-d6a503ce5d21', '432a6abd-dcca-44cc-82ce-fb39e33b8949', 60, 'Episode 60', 'Morrie Turner, author of the Wee Pals comic strip, visits Rogers. In the Neighborhood of Make-Believe, X begins his printing business.', '1971-05-07', NULL, NULL, '2026-04-03T17:35:39Z', '2026-04-03T17:35:39Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('1afb4d7f-28d6-48b3-b63d-46317885d5d9', '272db816-9822-485a-b231-6e060d0ccb1a', 4, 'Juggernaut', 'When Ivor leaves to seek his fame and fortune, something threatens to take his place; it is worth a load of gold just for the pleasure of seeing it go.', '1977-11-25', 5, NULL, '2026-04-03T17:24:25Z', '2026-04-03T17:24:25Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('1afd01a9-91d1-4637-a17f-1dcd2b8c6d41', '4da606e7-9d23-4682-8bd5-f535e1da706f', 10, 'Franklin''s Valentines', 'Franklin made beautiful valentine cards for this schoolmates. During class time, Franklin could not find his cards anywhere. He found them on his way home, they were strewn all over and rain soaked. Since his schoolmates were so understanding, he found a new way to celebrate Valentine''s Day.', '1998-10-05', 12, NULL, '2026-04-03T17:40:15Z', '2026-04-03T17:40:15Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('1afd67c5-6383-4061-bfe4-62a491cd10b8', '4d2cac0f-38fd-438b-8afa-acf43952e535', 375, 'Episode 375', 'with Christopher Trace and Valerie Singleton.', '1965-07-08', NULL, NULL, '2026-04-03T17:21:47Z', '2026-04-03T17:21:47Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('1b014bca-785d-477a-b8ba-7a71233f39f6', '5a771f52-fe96-4ea2-b567-a8dde899059e', 16, 'Some Serious Coinage', 'The first American coin ever made has Rick thinking this is a sale that was mint to be - but it''ll cost him a serious chunk of change. Corey and Chum see a future for an antique "Jetsons" cartoon lunchbox that zooms across their counter. Can they draw on their negotiating skills and make a deal? A hood ornament from an Austrian automaker pulls into the shop, but will it drive Rick to make an offer? Later, Rick gets some self-help, medieval style, from an ancient Latin book.', '2018-01-29', 21, '/cZiifErO0Go7bvUNtgRt3RadhHs.jpg', '2026-04-03T16:34:21Z', '2026-04-03T16:34:21Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('1b0160b2-b949-474b-8570-d009760fa068', '1be79a20-de33-41d1-af17-079035b18d5c', 84, 'Rufus Opens a Lemonade Stand', '', '1970-03-05', NULL, NULL, '2026-04-03T17:36:28Z', '2026-04-03T17:36:28Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('1b043f81-ce9b-4224-86b4-d18ec899df5e', '68138de2-0900-460a-b58e-480688f1e081', 21, 'Dance Fever!', 'Bear is really excited about building the new birdhouse kit that he got in the mail, but Pip & PopTM and TutterTM are more excited about making something out of the box it came in. After gladly surrendering the box to his friends, Bear sets out it build the birdhouse on his back stoop, only to find that Jacques, an industrious local beaver, has bigger plans for Bear''s seemingly simple subject.', NULL, 25, NULL, '2026-04-03T17:35:31Z', '2026-04-03T17:35:31Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('1b06c56d-6f1f-4d65-977c-1c866477223b', '353f8b38-d837-4354-88bd-d51e98a3421a', 13, 'DELETE ME', '', NULL, 5, NULL, '2026-04-03T17:24:26Z', '2026-04-03T17:24:26Z');
