INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('1b103bb0-3373-4602-933c-5ea5130652e2', '7bc54df3-f32a-454e-aef6-a9436c35d53b', 20, 'Episode 20', 'Rogers has a recent chest x-ray, and explains what having an x-ray taken is about. In the Neighborhood of Make-Believe, Lady Elaine warns her neighbors that King Friday might be starting a wild animal zoo. That, she feels, is his big secret, although it isn''t.', '1970-02-27', NULL, NULL, '2026-04-03T17:35:39Z', '2026-04-03T17:35:39Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('1b10c186-eb48-49d5-a1b0-f23a638e7463', '18da9943-1963-4e04-a7a0-ae63802bb1fa', 2, 'One Apology, Another Betrayal', 'In the wake of Vicki repairing her friendship with Tamra, Vicki must face one last hurdle and apologize to Eddie. Tamra teaches an exercise class and introduces her new friend Gina, a recent transplant from Long Island, to the ladies. Emily and husband Shane celebrate their ninth anniversary. Shannon travels for the first time as a single mom to Mexico with her daughters. Kelly is stunned to learn that Vicki and Steve set up her ex-husband Michael and confronts Vicki over the betrayal.', '2018-07-23', 44, NULL, '2026-04-03T16:35:34Z', '2026-04-03T16:35:34Z');
