INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('1b1ca508-00d9-4394-8ae3-74f218fdb26d', '9193e795-da7c-40ec-b68f-f63aa7d5174f', 239, 'Deleted Scene: The Hound and the Little Bird', 'Deleted scene from Season 2', '2013-02-19', 2, '/b4KIBJbyBnrU3Pa8tzsxb4bCNtN.jpg', '2026-04-03T15:40:35Z', '2026-04-03T15:40:35Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('1b1f8c57-e2ec-4288-a7ea-c989d70d7726', '204d86fb-d99c-4fd1-8dcd-9c1bcfd3c33f', 24, 'Dragon Scouts', 'Cassie and Emmy join the Dragon Scouts. However, Cassie has to leave the Dragon Scouts to help her mother, leaving Emmy by herself.', '2001-09-04', 30, NULL, '2026-04-03T15:26:04Z', '2026-04-03T15:26:04Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('1b1ffc8c-1a24-40b7-b4fb-c8cb3ff06080', 'b7538712-04ce-43a6-9163-62280bbb084b', 2, 'Baby Bear and Telly Find a Kitten (3852)', '', '2000-01-04', NULL, NULL, '2026-04-03T17:36:42Z', '2026-04-03T17:36:42Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('1b2480bc-91b4-4523-9877-638a5af02c9f', '87989283-6fea-40d7-8d91-22c4947db105', 15, 'Two Moms, a Daughter, a Baby', 'Kody and Robyn are struggling with the bank as the mortgage process is not designed for plural marriage. Then in North Carolina, Maddie’s water breaks – at the mall. Evie K is born, but when she has problems breathing, an ambulance is called.', '2020-04-12', NULL, NULL, '2026-04-03T16:34:31Z', '2026-04-03T16:34:31Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('1b2cc2ed-27a2-4566-8ebd-997cd292a4fd', '1cafb2c3-bbcb-4172-b02d-441a5aaa155f', 9, 'You and I Together: A Visit with a Teen and his Service Dog', 'Rogers talks about how a variety of sticks is similar to a group of words: the more you have, the better you can work with them. Mr. McFeely shows a video of a service dog, named C.D., aiding a handicapped child. In the Neighborhood of Make-Believe, Dr. Bill Platypus tries to ensure Lady Elaine that the gorilla, called Kevin Wendell, is tame. Maggie Stewart Comes And Brings A Videotape On Mr Rogers Gets A Haircut', '1998-08-21', NULL, NULL, '2026-04-03T17:35:48Z', '2026-04-03T17:35:48Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('1b311c0f-aa6e-4a43-a547-a3fe7b91fd21', 'e2aa3158-68e5-494f-951a-498ca0518dbb', 15, 'The Piano', 'The Farmer plays the piano and tortures everyone with his musical inability.', '2012-11-30', 7, '/1MsopwfzPc85ZEHamVjNb7sAKYI.jpg', '2026-04-03T17:39:32Z', '2026-04-03T17:39:32Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('1b328df5-c5bc-499d-9910-67e7d57d1d8a', 'f4938e7d-11a8-4756-b405-98bedd7c9b28', 6, 'Pat''s Tractor Express', 'Pat has to deliver some eggs and a registered letter to some campers. The letter is too valuble to leave and the campers are at the waterfall. Pat''s van can''t travel the bumpy road so Miss Hubbard borrows a tractor and takes him on a rather bumpy ride to the waterfall. When Pat returns to his van, he sees that a hen has got in and laid an egg!', '1981-10-21', 14, '/8JVWL1UMkoD2QkMqI0DdNjYqrOO.jpg', '2026-04-03T17:14:29Z', '2026-04-03T17:14:29Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('1b32e327-68b2-478d-8188-f72d155f2d93', 'da06465b-9154-4feb-a455-374df7dab02f', 24, 'Bob''s Deaf Niece (4106)', 'Rosita and Telly want to play a game of tag but they can’t find anyone to play with them. They meet Bob’s niece Samara and wonder if she would like to play.  She can’t hear them because she is deaf.  Rosita and Telly are concerned because they don’t know how they will be able to all speak and play together. Samara explains that even though she can’t hear them, she can talk to them by using sign language.  They have a lot of fun learning, playing, and also signing and saying the alphabet together.  Everyone on Sesame Street gets so excited about sign language that they all can’t wait to learn more.', '2005-10-04', NULL, NULL, '2026-04-03T17:36:44Z', '2026-04-03T17:36:44Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('1b35fa6e-6afb-4e07-80c3-6432fc232139', '1be79a20-de33-41d1-af17-079035b18d5c', 71, 'Episode 71', '', '1970-02-16', NULL, NULL, '2026-04-03T17:36:28Z', '2026-04-03T17:36:28Z');
