INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('1b5130e9-2c07-49a2-8695-9b77cd6930c5', '0987f081-b3b7-4e3c-abb7-795e56c279d5', 19, 'The Bachelor', 'Disappointed with the finale of "The Bachelor," Frankie mopes for days; when Sue joins the school''s tennis team, Mike tries to toughen her up by complimenting her opponents during matches; Cassidy and Axl consider the future of their relationship.', '2013-04-03', 22, '/2LnSdgPUBpz8mh47ycvMjVdXOJc.jpg', '2026-04-03T15:40:30Z', '2026-04-03T15:40:30Z');
