INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('1b96e77a-c84b-4131-b4ab-7c0a20054438', '6f731e6b-d3c5-4de6-84e1-7a19cb650e86', 35, 'Pawning Pistols', 'Get your quack on with the Pawn Stars when a pair of Duck''s Foot pistols sends the guys off to the gun range. Will Chum prove he''s top gun or will he shoot himself in the foot? Then, a bar of Yellow Kid soap from an 1896 newspaper comic scrubs into the shop. Will it leave Rick shouting "Extra! Extra!" or will he fail to deliver? And later, a Victorian-era hand crank device gets geared up for a sale. Will Rick churn out a deal or turn it away?', '2016-05-18', 21, '/q6HLZQrsuMFwWbetlXXwZW40Dlk.jpg', '2026-04-03T16:34:20Z', '2026-04-03T16:34:20Z');
