INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('1ba14e77-0169-4cff-a216-184de0d19fa9', '95ca8b6f-ccbc-431a-9d95-9b23367bbfed', 18, 'Del Mar by the Shade', 'When the group caravans down the coast for a relaxing girls’ weekend, Kyle and Kathy find themselves in the luxurious presidential suite — while Sutton’s vacation takes a turn for the worse. New questions arise about Erika at a glamorous picnic on the beach, and she is later devastated by news about her family. Meanwhile, Dorit and Lisa push Garcelle to tears when they question her investment in their friendships.', '2021-09-22', 43, '/aOr1zIM0Xgi0OKtqujjFAk6zIyy.jpg', '2026-04-03T16:34:58Z', '2026-04-03T16:34:58Z');
