INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('1be8091c-a46f-44ec-b366-b59e2de44512', '02849455-d14b-476b-9603-eef5fb5d2ab3', 12, 'Can''t Hide From These Green Eyes', 'After seeking counsel from her uncle, Ashley must face the truth about why Michael is hesitant to have more children. Robyn confronts Karen about her lies in a public forum, while Charrisse is left questioning her friendship with Monique. The stress of wedding planning becomes too much for Candiace, testing her relationship with Chris.', '2018-06-17', 42, '/b04fKAzI9LJ6miIMbNnYMzIPjYW.jpg', '2026-04-03T16:35:39Z', '2026-04-03T16:35:39Z');
