INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('1beb941d-3ba2-4fc2-97ed-b078890d381c', '5c1b881f-ac58-4d72-b63f-209952d4f902', 30, 'Episode 30', 'Hurry, Hurry, Hurry! This week''s your last chance to join in with the Great Blue Peter Bring and Buy Sale before the Oxfam shops take down their posters this Saturday. Thanks to you, the lives of starving Cambodian babies, children and adults are being saved - watch out for the latest news on today''s programme.', '1979-12-20', NULL, NULL, '2026-04-03T17:21:54Z', '2026-04-03T17:21:54Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('1bf22b57-f95f-46c4-bd56-9c9b7b2bf54a', '1bb53927-76f6-4ed3-9c41-5414ad0865ce', 1, 'Slagar the Slaver', 'In the kitchens of Redwall Abbey, Mattimeo, son of Matthias and Cornflower, fights Vitch, a mean little rat. Mattimeo is punished by his father for discourtesy to a guest. But Mattimeo''s instincts about Vitch are validated when it transpires that Vitch is a spy for Slagar the fox - a slaver for the terrible underground Kingdom of Malkariss. Slagar gains entry to Redwall disguised as the leader of a troupe of magicians. At the great feast he is able to drug the drinks and capture Mattimeo and his friends: Tess, Tim, Sam Squirrel, and Cynthia Bankvole.

They join a group of slaves among whom is Auma, little daughter of Orlando the badger - who even now is hunting the fox. As the slaves are taken away, Slagar is revealed to be Chickenhound - the treacherous fox from season one - seeking revenge against Matthias the Warrior.', '2000-11-04', NULL, '/ylb84FevRvaOlX04OpwiDpMUmyw.jpg', '2026-04-03T17:12:08Z', '2026-04-03T17:12:08Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('1bfdb604-06e1-476b-8d6d-44e7aa8c5de7', '16cbf3f2-fffd-4a78-bca3-96d05f5a2c6b', 15, 'Dueling Detectives', 'When George''s giraffe puppet Wally goes missing, Fern and Binky war over who can find him.', '2016-05-26', 13, NULL, '2026-04-03T17:38:01Z', '2026-04-03T17:38:01Z');
