INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('1c243253-cd28-487a-939e-057a01ab5719', '095258d0-d8db-4096-8ac7-6a42cd4cbdcf', 18, 'Bored Stiff', 'Pa Gorg decides to rid his and Ma''s "Kissing Rock" of Fraggles once and for all with the Boredom Juice that Junior found, but things go horribly wrong.', '1985-04-29', 24, '/A7ETY01C5QGAPGNfVxYjVJVsfwL.jpg', '2026-04-03T17:35:00Z', '2026-04-03T17:35:00Z');
