INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('1c3aad04-270c-445e-ae7c-202296664b70', 'a61eda16-b572-4c5b-ba55-57df932417ec', 11, 'Wonder Mountain', 'Mokey is planning a trip to Wonder Mountain — alone. Red thinks Mokey is too dreamy and ethereal to be able to take care of herself, so she secretly follows Mokey in order to protect her from trouble. But it''s Red who needs protection.', '1986-03-17', 24, '/kbJr7DxZ2BpbyYg7QR0MDhIxtwc.jpg', '2026-04-03T17:35:01Z', '2026-04-03T17:35:01Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('1c425d39-f25f-42c2-8998-6c647c664dbc', 'a31fa1d7-d649-4846-a81f-4f34b6fb3331', 14, 'Paddington''s Puzzle', 'Paddington makes a puzzle from Mr Curry''s painting.', '1979-01-30', NULL, NULL, '2026-04-03T17:22:53Z', '2026-04-03T17:22:53Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('1c442e55-6fd4-4026-aaad-3020fe439e8d', '70d9e397-6813-4785-887d-27d034928bae', 5, 'Pingu Pretends to be Ill', 'Pingu wakes, gets up sleepily, goes to the toilet, and is about to go back to bed when he notices that Pinga is already up, and realises he should be too. He decides that he’ll go back to bed anyway, and snuggles down again. Mother calls to him to get up, but all he does is go completely under the blanket. Pinga leaves for the nursery with Father, and Mother calls again to Pingu to get up, as it’s getting late. When nothing seems to be happening she goes to see what Pingu is doing. When Mother asks Pingu why he hasn’t got up he says he’s not feeling very well. Mother feels his forehead, and goes to get the thermometer. Pingu chortles to himself. Mother brings back the thermometer and a hot drink, puts the thermometer into Pingu’s mouth, and goes away again. Pingu takes the thermometer out, puts it into the hot drink to get the temperature up and then puts it back into his mouth. Mother comes back, sees that Pingu apparently has a temperature and calls the doctor. The doctor rushes over, Mother shows him the thermometer and he examines Pingu. The doctor ponders for a moment, and then calls Mother out of the room to consult. Mother is worried, but the Doctor reassures her that there’s nothing much wrong! Pingu goes over to the door and looks through the keyhole to find out what is going on, and sees the doctor pull a large syringe out of his bag. Pingu is rather worried by what this might mean, and when Mother and the Doctor return to the bedroom Pingu is nowhere to be seen as he has hidden under the bed. Mother and the Doctor go to the bathroom to see if Pingu is there, and Pingu takes the opportunity to sneak out of the bedroom. Mother spots him, and the doctor explains that the syringe was just a way of getting him to admit that he''s fine, so they both let Pingu go. He grabs his satchel and rushes off to school, getting there just as the bell rings for the first lesson.', '1995-07-13', 5, '/rvdezjZD5I4b874m8iOnNh6EQ2p.jpg', '2026-04-03T17:22:19Z', '2026-04-03T17:22:19Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('1c449c2d-a481-416d-8d8a-a6616e0c1e50', 'f63c3f61-0970-4e37-81cc-2b9045a9952c', 23, 'Maria Watches Pets At The Fix-It Shop (Repeat) (3938)', '', '2001-01-31', NULL, NULL, '2026-04-03T17:36:42Z', '2026-04-03T17:36:42Z');
