INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('1c8af84e-d07b-47f7-a582-3e3e7f092d7b', '7eef937c-4483-42bd-bafe-263a7d4e4573', 11, 'In the Rainforest', 'The kids rent a rainforest cocoa tree as an Earth Day present for Ms. Frizzle. But when the harvest arrives, there’s only one shrivelled cocoa bean! Ms. Frizzle takes the class to the rainforest to meet the impeccable Inspector 47 who keeps a tidy, mud-free cocoa grove. What has he done to the rainforest''s intricate ecology web?', '1996-11-23', 25, '/lcRyJSe7Kd8i48ldyGBucCgOghX.jpg', '2026-04-03T17:37:49Z', '2026-04-03T17:37:49Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('1c9094fb-5162-4778-b7ca-2faf7542fefd', 'bc1b58b0-f2d6-4214-914b-231f27fb4d61', 17, 'Get to the Punta', 'The Garden State ladies embark on a paradise getaway to Punta Cana in the Dominican Republic. Activities include a private cruise, but Kathy and Teresa soon make waves when they clash on the beach.', '2011-09-18', 43, '/2WtEAFZiDVU43Rf93TVTk5V1cLk.jpg', '2026-04-03T16:35:15Z', '2026-04-03T16:35:15Z');
