INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('1c95533e-e1a4-4aa1-8031-9a234821b02a', '16cbf3f2-fffd-4a78-bca3-96d05f5a2c6b', 19, 'Little Miss Meanie', 'Muffy and Lydia join forces to topple a snobbish and unpleasant beauty queen.', '2015-06-03', 13, NULL, '2026-04-03T17:38:01Z', '2026-04-03T17:38:01Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('1c97a83f-aff6-44ff-a603-d6c589f75e99', '46d7a706-c7a8-4ebe-b96f-387c66e8bb8b', 60, 'Episode 1505', '', '1981-02-13', NULL, NULL, '2026-04-03T17:36:34Z', '2026-04-03T17:36:34Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('1ca4c447-a7ba-4c3c-bfdc-f4a68db4a990', '65d1cad8-0120-425e-ae9b-5020ce773b32', 5, 'The Big Uneasy', 'The heat builds up at Gina''s housewarming party when Jenn learns that Tamra has been showing unflattering photos of her from the past; the group visits New Orleans and embarks on a riverboat cruise.', '2025-08-07', NULL, '/pi7eOujYsVHG7kaQvDbzYBbZGAx.jpg', '2026-04-03T16:35:36Z', '2026-04-03T16:35:36Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('1ca61a2b-22a2-48ad-b4fd-5c743e880228', '9193e795-da7c-40ec-b68f-f63aa7d5174f', 197, 'The night''s watch', 'A detailed look at the special troop of men dedicated to the protection and supervision of the wall, a 200 meter high construction that separates the seven kingdoms from the darkness behind.', '2012-03-05', 8, '/u8nIVmMhR0irnsjNDLuP1aKZ3xo.jpg', '2026-04-03T15:40:35Z', '2026-04-03T15:40:35Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('1cac5246-6362-4c5d-ba07-c1ded906389c', '9dff2271-f91b-47c1-a20d-58973840b764', 11, 'The Icecream Man Cometh', 'Mr. Gribble fires Linda from his icecream parlour so she moves to Paulo''s. But Paulo''s secret is Giorgio, a freak who makes icecream from his nose and who has lived his whole life in the van.  Linda decides to rescue him but he may not be ready for the world that lies beyond.', '2000-03-14', 24, NULL, '2026-04-03T17:40:41Z', '2026-04-03T17:40:41Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('1cafadc7-457b-443d-9d91-8423ce1d9750', '8c3cfac1-d882-4904-b38c-d1981628d00e', 44, 'Episode 44', '', '1979-02-12', NULL, NULL, '2026-04-03T17:21:54Z', '2026-04-03T17:21:54Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('1cb25544-6196-440a-92d2-157c654275bf', '98d80972-e53a-43dd-a03a-7703465e6f87', 33, 'Close, But No Cigar', 'Ask not what your Pawn Stars can do for you, when the guys get a chance to own JFK''s personal cigar box. A piece that sat in the Oval Office, will the guys light up at the opportunity or will negotiations go up in flames? Then, a guy pops in with one of the most powerful handguns ever made, a Colt Walker. A model used by the Texas Rangers, can Rick get the seller to surrender this rare gun? And later, an Olympic gold medal makes it''s way into the shop. From the 1988 games in Seoul, will Corey stretch out for the win?', '2013-03-11', 21, NULL, '2026-04-03T16:34:18Z', '2026-04-03T16:34:18Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('1cb36c4e-99c2-4e22-896e-3b6f40cfc731', '1a8f02c5-f727-4ce3-9bb2-5946d236e47c', 8, 'Chapter Eight: The Rightside Up', 'As Vecna prepares to destroy the world as we know it, the party must put everything on the line to defeat him once and for all.', '2025-12-31', 129, '/kP23RWbUWM6vGhT9PxFyP5VT3y4.jpg', '2026-04-03T15:40:40Z', '2026-04-03T15:40:40Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('1cb39bc1-37de-4306-973c-ed6a20a44f78', '73ae1459-ba91-4185-a9da-bf6f2844af49', 7, 'How Ya Like Them Apples?', 'Tinsley vents to Leah’s boxing coach about her issues with Dorinda, while across town Dorinda confirms to Sonja that she and John are officially on a break. Luann opens up to Leah about her relationship with drinking. The ladies take a day trip to a local orchard, where things get hostile between the group.', '2020-05-14', 60, '/q6SznodW8WFi9KZv4ELVnsA8FkL.jpg', '2026-04-03T16:35:25Z', '2026-04-03T16:35:25Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('1cb87c26-afb8-4b21-ada9-8b710c2b5d7a', 'f0f8b366-cb33-40b3-a50f-a1ca7780916f', 8, 'Mokey, Then and Now', 'Mokey, Wembley and Boober get transported back in time, to an era when Fraggles are bald, have leaders, and never laugh.', '1987-02-23', 24, '/lVbMrvRpEtxmMapmNVdhVr4R3PM.jpg', '2026-04-03T17:35:01Z', '2026-04-03T17:35:01Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('1cb9b29f-8aec-4098-9503-ce3cabf75ce1', '05fa5e18-78d2-41fe-ae30-0c242c7ffb6a', 1, 'Danger Falling Sheep', 'When naughty Norman tries to conquer Pontypandy Mountain he finds himself stranded on a ledge with a fallen lamb.', '2003-03-31', 10, '/672Ol7ncGjCXWzoxoESTsieqncb.jpg', '2026-04-03T17:14:38Z', '2026-04-03T17:14:38Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('1cbe728b-27e3-4793-b4e3-692ff0d1542d', 'ca3f764e-b330-4980-bd7a-2908a73b77b6', 22, 'Reunion (2)', 'The Beverly Hills bombshells sit down with Andy Cohen to re-live and re-hash the seasons most controversial and talked about moments.', '2012-02-06', 43, '/f1VD9Z4rKVaoP9XLdYF2KwONXmd.jpg', '2026-04-03T16:34:55Z', '2026-04-03T16:34:55Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('1cc48e88-55a7-4bcc-94c8-7068835edd4a', 'f4c40307-9b5e-4263-a4e0-dfa138131e7f', 15, 'Abby in Wonderland', 'After wishing she had her own fairy tale, Abby Cadabby falls asleep while reading "Alice in Wonderland" with Elmo, and ends up in a world just like the book!

Also includes the thrilling adventure, "Texas Telly and the Golden Triangle of Destiny!"

Note: This entry refers to the special as aired on television, and not the direct-to-DVD version.

Episode image is courtesy of MuppetWiki and used here under the GNU Free Documentation License (GFDB).', '2008-11-28', NULL, NULL, '2026-04-03T17:36:27Z', '2026-04-03T17:36:27Z');
