INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('1cd15635-2b44-463f-addf-64ebdcee889a', '8bae6aa3-4b55-4fa6-bc15-8f4317bd1f13', 35, 'Episode 35', 'Al Worden shows more equipment that he took to the Moon, and he discusses the one side of the Moon that is never seen on Earth. In the Neighborhood of Make-Believe, King Friday gives Worden a model Solar System.', '1972-04-07', NULL, NULL, '2026-04-03T17:35:40Z', '2026-04-03T17:35:40Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('1cd418ef-8ee1-44a6-9499-45edd186d500', '54900370-8988-46b8-b7aa-61d2b88d7056', 16, 'Sisters of Salt, a Greek Tragedy', 'On their final day in Santorini, the ladies visit with Angie’s cousin at a winery and learn more about her culture and family history. After meeting with a local playwright, the group attends a special performance of traditional Greek theater about them. The play receives mixed reviews from the women, leading them to square off against each other.', '2026-01-06', 54, '/q3hSpsmqRqBImgj6Bjq7AF6fmlq.jpg', '2026-04-03T16:35:46Z', '2026-04-03T16:35:46Z');
