INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('1d19b3b8-e87c-4458-8e4e-6cfba1951923', 'dfe2c51c-8d2c-4c92-a010-7dbb71c3e48b', 13, 'Skeleton', 'Why is the human spine shaped like an S? Which animals'' skeletons can join together to form islands? SKELETON takes you beneath the surface to reveal the hidden secrets of an incredible variety of skeletal structures, none more complex than our own. A symbol of our deepest fears, a miracle of engineering - see the skeleton as never before.', '1995-06-26', 29, '/lNt3qVbBb0YZxehao7HGbrboH7X.jpg', '2026-04-03T17:39:04Z', '2026-04-03T17:39:04Z');
