INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('1db19dc5-01ce-47ea-b2e9-c3695142689f', '1e085f65-4b69-4500-8ffc-654d2f638dbb', 3, 'Proud of My Name', 'Elmo, Gabrielle and Rosita join a basketball team; Elmo and Gabrielle encourage Rosita to tell the coach to call her by her actual name; Rosita is proud of her name because names are a big part of one''s identity.', '2023-11-23', 26, '/gYPEx4v5c2DwdqA33kg7KkRnUpk.jpg', '2026-04-03T17:36:51Z', '2026-04-03T17:36:51Z');
