INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('1db97c3e-d88b-479b-975f-bd0470547e24', '4892e2af-46c1-4b4e-ac81-eac161b5a347', 27, 'Episode 27', 'Today JOHN lights the first candle on the Advent Crown, PETER goes north to Beamish and rides on a Sheffield tram, and Britain''s top pet cats compete for the title Blue Peter Champion Top Cat 1977 and the silver trophy '' live'' in the studio.', '1977-12-12', NULL, NULL, '2026-04-03T17:21:53Z', '2026-04-03T17:21:53Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('1dbb22be-f8f1-4dfc-b1ad-cddbbae2cfbc', '05c0e384-194c-4417-9f62-803eb615e409', 114, 'Staying well', 'Lady Elaine wants to turn King Friday upside-down with her Boomerang, but it backfires and the whole Neighborhood turns upside-down.', '1968-07-25', NULL, NULL, '2026-04-03T17:35:38Z', '2026-04-03T17:35:38Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('1dbf9eba-00d1-4aa4-ac5b-fd772c3d8f7a', 'e291df42-d44f-49e5-bf81-2df32ee4a30f', 23, 'Read My Book', 'Bear is holding his weekly book club. He''s excited that the mail has come because he ordered a new book and sure enough, there''s a package waiting for him. However, when he opens the package, he finds that the book is called 1001 Ways to Cook Slop. This definitely isn''t the book he ordered. A quick phone call to Jeremiah Tortoise reveals the mixup --- Bear must have received Doc Hogg''s cookbook by mistake, while Doc Hogg got the book intended for Bear. He says that he''ll get the problem taken care of as fast as he can. This leaves Bear with a bit of a dilemma, as he still needs a book to read for his club, but it could take a while for Jeremiah to bring the right book. Bear decides to search the Big Blue House for another book to read. As he goes about his search, he finds that everybody in the Big Blue House has ideas on books that he could read. 

Notes 

The books that Bear finds in the kitchen are titled "The Brothers Bearmazov" and "Jane Bear." 

Bear mentions that when he was little cub, he read a book called "Buck Antler: Deer in Space." This is a reference to Buck Rogers. 

Earl has an appearance in the book "Mouse the Great".', NULL, 25, NULL, '2026-04-03T17:35:32Z', '2026-04-03T17:35:32Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('1dc357a1-4b8a-4bd3-8603-929d0227dfbd', 'ea73e13c-6962-4804-8305-c303df65f89f', 5, 'Ducklings', 'Rogers brings ducklings into the Television house. For their benefit, he fills a wading pool and both he and François Clemmons feed the ducklings. Lady Aberlin and Lady Elaine discuss the difference between being alive and being a model. Robert Troll tells King Friday that Sara Saturday will soon be arriving from Westwood.', '1969-02-14', NULL, NULL, '2026-04-03T17:35:38Z', '2026-04-03T17:35:38Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('1dc55c4a-6024-4d05-93e4-594715a0ed64', '5c16db9d-5e71-40eb-b44e-f559b2ddb8f3', 1, 'Goldilocks And The Three Bears', 'It''s probably the most famous story of trespassing in fiction. In this version, its unquestionably the most entertaining. Tatum O''Neal stars as the mischievous but lovable heroine in this story of a child who invades the lives of 3 bears. The amusing threesome is headed by Alex Karras. Carole king and John Lithgow and Hoyt Axton are included in the talented supporting cast.', '1984-01-09', 51, '/pLDzOPmahwHA9OQkw09CFJmeFrB.jpg', '2026-04-03T17:38:41Z', '2026-04-03T17:38:41Z');
