INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('1de5fdfe-4427-46c2-acb0-b5e804d851a3', 'ea1650c2-e4f1-46c7-93ba-74b5d45d08e5', 16, 'The Bride and the Doom', 'Back from the Miami trip, Cynthia''s rocky road to the altar is nearing the end, but as she struggles with last minute wedding jitters, her mom and her sister urge her to reconsider getting married altogether. Phaedra has a surprisingly emotion reaction to heading back to work after her maternity leave. Sheree''s acting chops are challenged at her very first movie audition, and Kandi finally confronts Kim about their financial arrangement regarding their new song, "The Ring Didn''t Mean a Thing."', '2011-01-30', 64, '/74qYX4ZotuZDjsxGrZqLlxr8S7l.jpg', '2026-04-03T16:34:45Z', '2026-04-03T16:34:45Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('1de64786-8fdf-497e-95fb-82e4b1a8fd78', '787dfa0b-c827-4dad-a82d-0548a6534d88', 14, 'A Storm Is Coming', 'The day after Tamra''s sex party, the ladies are still in disbelief over Vicki''s attack on Meghan. Meanwhile, Shannon''s kids cook up a plan to improve their parent''s troubled relationship. Tamra and Eddie''s date night turns sour when she comes clean about financially helping out her son. Plus, Vicki leaves the OC for a visit with Briana in Oklahoma, but underlying tensions about Brooks brings the trip to an explosive end.', '2015-09-07', 44, '/sb9UGaad341bH3AMXW8mCja1EiD.jpg', '2026-04-03T16:35:32Z', '2026-04-03T16:35:32Z');
