INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('1dee558b-a144-4f21-ae6f-b0ccde7e739d', 'f593d90c-5339-42f5-9c88-5bfd48d04075', 25, 'Chip Off The Old Block', 'The Farmer has taken up sculpting, but unintentionally drops a huge slab of stone on top of Timmy''s teddy. Shaun and the flock must struggle and strain to lift the heavy block and retrieve the precious toy.', '2010-04-25', NULL, '/yelofRcpp6lLxswPhGMXtNFC0My.jpg', '2026-04-03T17:39:31Z', '2026-04-03T17:39:31Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('1df4687f-84a2-4e46-a594-d9923a8865d7', 'ab509c47-ec64-4fb3-8560-03873dd0c37e', 20, 'The Doodle', 'Jerry''s family lives it up at the Plaza for free, thanks to Elaine; the fumigation of Jerry''s apartment disables Kramer''s taste buds.', '1995-04-06', 23, '/w5vsXaEn1z04kTcqU4TtgBKat8y.jpg', '2026-04-03T16:34:11Z', '2026-04-03T16:34:11Z');
