INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('1e19167d-0110-4693-8a8f-74cf79c81ee0', 'ecb64ef3-4f80-45a7-b4a9-c04434b02e35', 42, 'Breaking the Bank', 'The Pawn Stars take it to the hoop when one of NBA legend Dr. J''s supposed game-worn sneakers steps into the shop. Will the guys score a slam dunk on this item or will it be an air ball? Then, a rare Half Eagle coin from the Civil War flies in. Can the guys land this Eagle or will it fly away? And later, when everyone borrows from Rick''s coin jar, will he see it''s time to change or will the guys break his bank?', '2014-05-22', 21, '/pZr9SU7rg6WsCMeHNwKCmCNSTQJ.jpg', '2026-04-03T16:34:19Z', '2026-04-03T16:34:19Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('1e20302f-3d72-4885-964c-99a91a68a01a', 'f63c3f61-0970-4e37-81cc-2b9045a9952c', 14, 'Elmo Pretends That He''s in the Wild West (3929)', '', '2001-01-18', NULL, NULL, '2026-04-03T17:36:42Z', '2026-04-03T17:36:42Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('1e216003-1281-4bb1-921e-1453930b9e30', '68138de2-0900-460a-b58e-480688f1e081', 4, 'Clear As A Bell', 'Bear gets a new Spanish-language tape in the mail, but just as he''s about to try it, he''s waylaid by Tutter, who, it seems, has a touch of laryngitis. He cant talk at all. A concerned Bear gives him a small bell to call him when he needs some-thing, and Tutter keeps bear running back and forth his Spanish lessons with Pip&Pop to a misunderstanding between Ojo and Treelo. During the course of Bear''s busy day, we discover how to communicate with words and without them.', NULL, 25, NULL, '2026-04-03T17:35:31Z', '2026-04-03T17:35:31Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('1e225085-3255-43b0-bfdb-fd7b75002269', '1d39506b-06b8-4f93-9136-0208069bd7e4', 17, 'Reunion (3)', 'Kelly continues to claim she was bullied by the other women in St. John''s; Jill''s motives in regards to her surprise trip to the island are debated; Luann talks about her romantic life since her divorce and her singing career; Kelly''s contradictory statements on the show are discussed. Bethenny''s and Jill''s future is still uncertain.', '2010-06-17', 43, '/qhoZKce70Kn3VudvBSUUGOEWkzX.jpg', '2026-04-03T16:35:22Z', '2026-04-03T16:35:22Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('1e296685-7022-4374-a2bc-33cf3a09c78f', 'e13f4aa4-dd8a-48d5-8cc1-1c258f43e44d', 915, 'How They Got Here 2018', '', '2018-06-11', NULL, NULL, '2026-04-03T16:35:29Z', '2026-04-03T16:35:29Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('1e2bbdb7-5d94-41f2-ba91-934df1a7158e', 'a9657e86-4135-49ce-b1f9-c295113077e1', 15, 'Hello, Ms. Tipps', 'The class in the School-in-the-Sky has a substitute teacher, Ms. Tipps. The others have a fun day, but Lorca misses Quetzal''s way of doing things. The others must figure something out to help convince him to change his mind.', '2005-03-29', 30, NULL, '2026-04-03T15:26:04Z', '2026-04-03T15:26:04Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('1e30e9dd-df97-4e35-ae33-d851439d2a04', '9193e795-da7c-40ec-b68f-f63aa7d5174f', 81, 'Histories & Lore: The Greyjoy Rebellion (Theon Greyjoy)', 'Theon Greyjoy reflects on his father''s failed rebellion and the penalties his family suffered as a result of it.', '2013-02-19', 3, '/qeK2Qa4wIpABDqnhnceztgffdBt.jpg', '2026-04-03T15:40:35Z', '2026-04-03T15:40:35Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('1e3107ad-4213-4973-8143-499e6fa06c78', '004abc4c-ce77-4df9-8c97-9f56ea8b37ce', 2, 'Tiger''s Rocket', 'Tiger''s very excited when his new rocket arrives. He''s not so excited when it refuses to take off. With a bit of help from Kipper and Sock Thing, everything works out fine.', '2000-01-27', 30, NULL, '2026-04-03T17:10:49Z', '2026-04-03T17:10:49Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('1e395600-ffcd-4071-8df0-b9b756a41ee0', 'e8b959c0-6865-4332-9be1-b8f720716aa8', 22, 'Puppet Show', 'John visits the Swan Theatre in Stratford-upon-Avon to see a puppet show performed by Major Mustard.', '1992-03-09', 15, NULL, '2026-04-03T17:19:37Z', '2026-04-03T17:19:37Z');
