INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('1e3cad4d-fda2-4f5a-9619-895e732a2442', '2e6ee129-b32e-4417-9500-56f1cc9bc434', 8, 'Is This a House for Hermit Crab?', 'LeVar sets out to build a bird house, prompting an examination of animal habitats. Eartha Kitt reads the story of a growing hermit crab, who is now too large for his current shell, and all the difficulties he has trying to find a new place to live, all the while trying to avoid predators who want to eat him.', '1993-10-20', 30, NULL, '2026-04-03T17:36:18Z', '2026-04-03T17:36:18Z');
