INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('1e61f699-6b8b-4bef-b485-f42c35060b74', 'bbfee3b4-9c95-48a6-beaa-791fa08b1f43', 13, 'Episode 13', 'The remarkable story of Judy, the only dog ever to become an official prisoner of war. Captured by the Japanese after the fall of Singapore, Judy survived the gruelling conditions of a forced labour camp and on her return to Britain she was awarded the Dicken Medal. The citation read '' for magnificent courage and endurance in Japanese prison camps, thus helping to maintain morale among her fellow prisoners, and for saving many lives by her intelligence and watchfulness''.', '1983-10-24', NULL, NULL, '2026-04-03T17:21:56Z', '2026-04-03T17:21:56Z');
