INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('1e744888-aa17-4534-9b8d-465babc5d919', '05c0e384-194c-4417-9f62-803eb615e409', 17, 'Donkey Hodie comes to the Neighborhood of Make-Believe', 'Title number 0017. Opens with Mister Rogers arriving with papers in his hand. A young donkey named Jenny is visiting Mister Rogers on the porch. Back in the house, he, Lady Aberlin, and Mr. McFeely play a game of Pin the Tail on the Donkey. In the Neighborhood of Make Believe, Donkey Hodie has just arrived and is looking for a place to live. He assures Lady Aberlin and Henrietta Pussycat that he no longer bites.', '1968-03-12', 28, NULL, '2026-04-03T17:35:38Z', '2026-04-03T17:35:38Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('1e762607-5534-46fd-99be-935afc387073', 'bddd6427-4f85-402c-b58c-5c18ab159704', 93, 'Episode 888', '', '1976-04-07', NULL, NULL, '2026-04-03T17:36:31Z', '2026-04-03T17:36:31Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('1e77ab76-c578-4049-b00f-84e28ea69f71', 'f4c40307-9b5e-4263-a4e0-dfa138131e7f', 63, 'Elmo''s World: Food, Water & Exercise', 'Join Elmo as he explores why food, water, and exercise are essential parts of your life! An apple talks about his family tree, Elmo scuba dives to depths unknown, and you can even join in the exercise by groovin’ to the Bunny Hop! Learn with Elmo about foods from around the world, dip into the deep water and stay healthy and strong with exercise!', NULL, NULL, NULL, '2026-04-03T17:36:27Z', '2026-04-03T17:36:27Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('1e7b2d7a-f2e0-41cc-963b-17762c9ee50c', '5144de59-e67f-4fcf-919b-7106989ab797', 12, 'I Love Kiki', 'Kiki is at a loss as to what to do when she unwittingly “breaks” Julie’s toy horse, and can''t bring herself to tell her. Sizzle looks after the sneaker that Nuzzle likes to chew on, but when the Piece Police throw it out as she naps, she panics. Ben does not appear in this episode.', '1995-01-31', 29, NULL, '2026-04-03T17:12:21Z', '2026-04-03T17:12:21Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('1e7f56b1-5ae3-479c-8e02-4623ea64f0ab', '9193e795-da7c-40ec-b68f-f63aa7d5174f', 153, 'Histories & Lore: The Dothraki', 'Jorah Mormont details the history of the first major migration of the Dothraki after the Doom of Valyria towards Central Essos, and how the newly invaded invaders destroyed the civilizations of what would later become the Dothraki Sea.', '2016-11-15', 5, '/8WiJ6QMpFFnoZvCNDCM2czO89Li.jpg', '2026-04-03T15:40:35Z', '2026-04-03T15:40:35Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('1e881ae9-778c-4a84-afb4-e6d7e6fed761', '2aebfad4-3145-4bc1-9def-5f1d5bdfcfc8', 3, 'The Pen', 'Elaine regrets accompanying Jerry on a visit to his parents, where local gossip includes how Jerry acquired a pen that writes upside down.', '1991-10-02', 23, '/eLZeYFfxDblM6ynFP9byqUGhVO0.jpg', '2026-04-03T16:34:10Z', '2026-04-03T16:34:10Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('1e917bfe-d347-4521-aee3-c4a381bc3648', 'bfdf87ff-01dd-4b54-94bd-19b384f41bdb', 3, 'Lies in the Air, Sand in My Hair', 'Vicki and Briana take a road trip from Oklahoma to Orange County when Vicki finally gets her wish, her daughter is moving back.  But Briana''s homecoming is not all that Vicki hoped. Meghan faces her fear of needles head-on when she begins her IVF shots without Jimmy, as Heather struggles with her children''s expectations about how much they see their father. Kelly throws a beach party to get to know all the women better and Vicki and Tamra pull their heads out of the sand to try and resolve the issues that have plagued them for the past year.', '2016-07-11', 44, '/5ZxIAw5lErd7UZJyJTXel7Rsz9s.jpg', '2026-04-03T16:35:33Z', '2026-04-03T16:35:33Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('1e91ff51-7407-41ee-88f0-25197e1cffef', '8e5ed8a4-08e5-4006-9f36-c68c91ddfee4', 8, 'Betty Lou''s Dolly loses her head', '', '1994-11-30', NULL, NULL, '2026-04-03T17:36:40Z', '2026-04-03T17:36:40Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('1e97a7a0-77c4-4d96-aa99-9640e202fd85', 'a61eda16-b572-4c5b-ba55-57df932417ec', 8, 'A Brush with Jealousy', 'When a new artist shows up in Fraggle Rock, Mokey is determined to prove that she is better. She even goes as far as to acquire a magic paintbrush — one that brings danger to anyone who uses it.', '1986-02-24', 24, '/r3mFA3sk0QItDSPwtkfFP37NjzJ.jpg', '2026-04-03T17:35:01Z', '2026-04-03T17:35:01Z');
