INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('1ed054bf-fe73-48c2-9ada-cdf14e19e015', 'b8c1b631-9850-45f3-9361-cdad5571a492', 14, 'Which Wife Is Next?', 'While Christine settles into her new life in Utah, the remaining wives and Kody have another tense conversation at Robyn''s. Janelle feels Kody is making her choose between him and her kids, and they reach a breaking point.', '2022-12-11', 41, '/r7nEEvlRTF2aSEB7ws1Y5gsLt7O.jpg', '2026-04-03T16:34:32Z', '2026-04-03T16:34:32Z');
