INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('1ed5fa0d-946e-4db4-b8c2-8766548d7375', '6c47406b-b3d6-40d8-b483-1ae1b3d30009', 8, 'Fireman Sam: The Great Fire of Pontypandy', 'Fireman Sam: The Great Fire of Pontypandy, known in Scotland as Fireman Sam: The Great Fire of London, is a 2010 animated film, based on the Welsh stop-motion television series, Fireman Sam. Norman, Derek, Sarah & James and Dilys go pioneering with Trevor Evans in the forest. Norman Price and his cousin Derek want a campfire to cook sausages and try to light a fire by rubbing sticks together. The trouble is, Dilys calls them away and the fire gets going without them realising it and the great fire of Pontypandy starts!', NULL, 10, '/rcC4chijhaTr2l50tqjsYsx8eNL.jpg', '2026-04-03T17:14:36Z', '2026-04-03T17:14:36Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('1ee150cc-7f16-43fb-b0dc-f493b09542dd', '79c64e0a-3488-41bc-9b5c-2243ff15b373', 14, 'Unmasking the Truth', 'The ladies of Beverly Hills hit the streets of Florence for some Italian high-end retail therapy. Rachel debates cutting her trip short to be with her boys while Kyle argues on someone else’s behalf. The group meets for a poolside pizza party where Sutton defends herself during Dorit’s latest dinner table tirade. Natalie finds herself stuck in the middle as tensions rise between Bozoma and Amanda.', '2026-03-19', NULL, '/91mlAVkRRZ6aaXwsx5fMoyhlwCM.jpg', '2026-04-03T16:34:59Z', '2026-04-03T16:34:59Z');
