INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('1f45cb66-4b00-4f57-b505-c1d76a1527a6', '204d86fb-d99c-4fd1-8dcd-9c1bcfd3c33f', 1, 'Lucky Stone', 'Ord loses his lucky heart-shaped stone and explains that he needs it to do three loop-de-loops, four aerial zigzags, and a round springback handoff after Max confesses that he threw it in the river when he and Emmy were skipping rocks when they arrive in Dragon Land. However, when Ord does his tricks without it, he learns that he really didn''t need the stone to be lucky at all. Just by believing in himself.', '2001-06-04', 30, '/7tbfV7po4hGEUekPKN82wMyLYN6.jpg', '2026-04-03T15:26:04Z', '2026-04-03T15:26:04Z');
