INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('1f8b84e6-dda7-4f1a-8ce3-4d1531f88e5f', 'b1d55597-d9d2-4eee-ab95-46dbb163291a', 22, 'Pingu''s Grandfather Is Sick', 'Pingu is painting a painting while his mom is ironing clothes, but then the telephone rings and Pinga answers the phone, Pingu''s mom rushes Pinga off the phone - it is Grandpa who''s suffering measles. Pingu tells Pinga not to mess up his painting but Pinga throws red on it. Pingu gets really angry at Pinga and she runs away from Pingu. They go to Grandpa''s house, but Pinga blocks the door so Pingu can''t get out. Pingu backs up and rushes the door, but Pinga has moved away and he falls flat on the ground. They all go to Grandpa’s house and while Mother tries treatments, Pingu and Pinga run around babbling and dancing, possibly to entertain Grandpa, but end up annoying him. Mother lectures them and tells them to be quiet, but they pretend to cook something in a pot and the lid falls off. Mom tells them to stop messing about and again tells them to be quiet, but they play dress-up while Pingu is on a sled and they crash into the drawer. Pingu''s mom, exasperated, makes them go outside, where Pingu finds a board and puts it above a giant wad of snow to play seesaw. Mother, exasperated again, tells them to stop. Pingu then kicks snowballs into the door and kicks one into Mother. She finally has had enough of their behavior and tells them to go home. They then use markers to make fake spots and then call Mother. She comes home, lifts the bed sheets and finds them all spotty, like the measles. When Mother rubs their heads she finds out they have used crayon and they try it on Mother. When she jumps on the bed in the ending, she breaks it (much to Pingu''s surprise). They then laugh.', '1990-05-26', 5, '/hAQqK9aQzh02DIc1u3SMI5pAtNG.jpg', '2026-04-03T17:22:19Z', '2026-04-03T17:22:19Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('1f91a81b-bd7c-47ef-bd0b-1bc1382f3660', '69b3befe-579a-43ad-a7d6-ec30ffe3adf7', 64, 'Episode 1119', 'Luis trades junk with Oscar.', NULL, NULL, NULL, '2026-04-03T17:36:32Z', '2026-04-03T17:36:32Z');
