INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('1fb28878-0530-459f-aec3-2685f3b90c6a', '23c93536-610c-41c5-ac6b-a6b243423258', 8, 'Healing, Thriving and Surviving', 'Wendy preps for her 40th birthday bash and tries to bring her extended family together. Karen''s big day in court arrives. Ashley performs her new single at a GnA event. Mia confides to the ladies about rising tensions between Gordon and Inc. Gizelle and Mia''s confrontation causes issues within the group.', '2024-11-24', 43, NULL, '2026-04-03T16:35:41Z', '2026-04-03T16:35:41Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('1fb2f303-b366-4a4b-9deb-a28533ece0ae', 'f13cb622-84e3-4654-a8f1-0ceab09a9ca6', 9, 'Franklin Stays Up', 'Franklin is having a campout in his backyard and he and Rabbit hatch a plan to stay up all night. Originally, all members of the sleepover are on board, but then they fall asleep one-by-one until finally Franklin and Rabbit are the only ones who make it until morning to see the sunrise, but not without a few setbacks.', '2002-05-27', 12, NULL, '2026-04-03T17:40:16Z', '2026-04-03T17:40:16Z');
