INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('1fb4e96d-f412-4a31-93f7-53f771002822', 'e56be195-5389-42bc-8aa9-2d9e9b0d974f', 1, 'Vote For Froglet', 'An election special. The narrator explains the democratic process, and demonstrates it by asking the Clangers to vote between the Soup Dragon and a Froglet. The Soup Dragon wins the election on a policy of "No Soup for Froglets", but the Clangers are dissatisfied with the result.

This special was believed to be a lost episode for many years, but it was released in full for free by the British Film Institute to coincide with the 2017 UK General Election.', '1974-10-10', 11, NULL, '2026-04-03T17:23:52Z', '2026-04-03T17:23:52Z');
