INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('1fbca0fa-5140-4f44-9026-6767c16f092c', 'c1df0e9b-e03e-48e5-a930-61ee5ef85840', 7, 'The World Record', 'Arthur tells his friends about the World Records that have been broken, and they try to break some of the records. Buster, walking backwards, Francine trying to kick a soccer ball in the air the most times, Muffy not talking, and Binky building the largest popsicle stick bridge. All these were very hard tasks, so Arthur decides to make the largest pizza in the world by getting help from the whole city.', '2000-09-25', 13, NULL, '2026-04-03T17:37:56Z', '2026-04-03T17:37:56Z');
