INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('1fbfa848-7255-4544-93a7-d83df335909e', '97a3d1f5-a8f1-47cd-8122-2e74a092836d', 18, 'Who is Max Mouse? (2)', 'Max Mouse continues to wreak havoc in Hurston. Jamal Lenni, and a lot of other kids grades get changed, false alarms go off and a child is nearly killed in a fire because the fire department is responding to a false alarm. Ms. Kelly has had enough. The kids have never seen her so upset. Then there''s a new message on the computer but this one looks serious.  The team''s three suspects are Calvin, Erica and Janice.', '1993-01-03', NULL, NULL, '2026-04-03T17:40:28Z', '2026-04-03T17:40:28Z');
