INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('1fc2d46d-86e0-4311-939b-c6aceea1ad75', 'd46f25ad-9612-4516-91df-d1ace11fec38', 3, 'Creepy or Cute with Kyle Thomas and Beard of Bees Challenge', 'Animal lover and social media superstar Kyle Thomas wants to prove that creepy crawlies can be cute, and Joel is challenged to wear thousands of bees on his face. Meanwhile, Shini meets one of the UK’s cutest birds, and Henry gets a bath!', '2025-09-19', 25, NULL, '2026-04-03T17:22:12Z', '2026-04-03T17:22:12Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('1fca8052-f0d7-4fa1-ae80-a76682798242', 'ffc2a75e-0ffa-4b26-b121-9b91b277594a', 13, 'The Countdown Begins', 'Kandi tries to overcome bad news about her tour. Elsewhere, Kenya has high hopes about returning to her acting and producing career; NeNe tries to patch up differences at a work event; and Apollo''s prison date approaches.', '2015-02-08', 43, NULL, '2026-04-03T16:34:47Z', '2026-04-03T16:34:47Z');
