INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('1fcfd556-4845-44a6-9fea-f8eb2379bddd', '21384b9c-43fa-410c-b89d-102e7cf9129b', 8, 'A Wife Decides', 'To move forward with their new life, the Brown’s burn the bag Kody used daily to go between each house. Janelle hits a plateau with her weight loss. Kody and Meri make a decision on Robyn''s surrogacy offer.', '2013-09-08', NULL, NULL, '2026-04-03T16:34:28Z', '2026-04-03T16:34:28Z');
