INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('1fda7c22-464a-446d-beaf-17e33b4d3d3a', '4861ce46-9045-43c7-963f-27b4ea539804', 134, 'Episode 264', '', '1971-05-13', NULL, NULL, '2026-04-03T17:36:29Z', '2026-04-03T17:36:29Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('1fdd99ab-7c46-4408-abe9-89d8411f0bd0', '45e64a15-8fc0-4e4b-a1ca-9e3f42f3634d', 18, 'Electricity', 'It''s time for Bill Nye to shed a little light on electricity.   Electricity might seem mysterious, but once you understand the science the light goes on (so to speak).   You flip a switch, and the lights turn on. You push the play button, and your personal stereo starts playing   music. When you flip the switch or push play, you start a flow of electrons. Electricity is the flow of   electrons, and electrons are very tiny charged particles. Electrons are found in atoms, the tiny pieces that   all stuff is made from. We can make electrons flow in two ways. Batteries make electricity by mixing up   chemicals -- making a chemical reaction that forces electrons to move in a path from the battery to the   personal stereo and back to the battery. Electricity that turns on lights in your home is made by power   plants. Most power plants use big machines called generators to make electrons by twirling wire in a   magnet. The magnet makes electrons in the wire move around, creating electricity.', '1994-01-28', 26, '/vqlmjIOrFgXGa3165j5D659kD6h.jpg', '2026-04-03T17:37:20Z', '2026-04-03T17:37:20Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('1fe8db09-bb0f-4d59-90f1-601bfd8e1942', '89ba90ec-2c79-4a12-a11d-7465d1757683', 7, 'Rick and Morty The Non-Canonical Adventures: Blade Runner', 'A claymation recreation of a classic scene from ‘Blade Runner’.', '2017-07-11', 1, '/c6WEy6P5qDTIKLtkaQfoM4qL18U.jpg', '2026-04-03T15:40:41Z', '2026-04-03T15:40:41Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('1fe9f0d5-079f-4a1e-8bcd-cd913c378ef7', '3af7ea64-fa13-4097-b8e4-40af07083054', 61, 'Episode 61', 'Rogers first shows his driver''s license. As a favor for Mr. McFeely, he gives a delivery to Trow''s workshop. Robert Trow is giving a lesson on silkscreening to a professional artist. The Neighborhood of Make-Believe has waited a weekend for the license for MGR-TV. A few hurdles still have to be cleared. X and Mr. McFeely have delivered to an empty studio. But Lady Elaine and King Friday arrive in haste, eager to get MGR-TV back on the air.', '1974-05-13', 28, NULL, '2026-04-03T17:35:40Z', '2026-04-03T17:35:40Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('1fee3c60-e234-4d91-8e49-2194bf69c689', 'b761c069-8326-445a-8a55-4adf19467af4', 7, 'Pizza with Pizzazz / I Didn''t Break the Lamp / Toboggan', '', '1994-03-10', NULL, NULL, '2026-04-03T17:11:21Z', '2026-04-03T17:11:21Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('1ff1aac2-2860-4f5b-bfa4-c1e8b1301ab6', '97616d6e-5c17-449f-a376-55f1da83d6c3', 4, 'Mister Rogers Talks About DISCIPLINE', 'Mister Rogers arrives with a towel and a pair of swim trunks and makes good on his promise from the previous day to show viewers where he swims. He talks about how he made a promise to himself to swim a certain length every day and has done so almost every day for ten years. Mister Rogers then shows film footage of his daily swimming. Following the film, Mister Rogers talks about how he doesn''t always feel like swimming but he does it anyway because he made a promise to himself to do so.', '1982-03-03', NULL, NULL, '2026-04-03T17:35:42Z', '2026-04-03T17:35:42Z');
