INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('202b31d6-e733-463f-8733-4d54f5a78c5b', '70c8cb46-2494-4dd4-98f6-6bfb9b3faf73', 33, 'Moon Walking', 'The Pawn Stars are blasted into orbit when someone brings in a flag from one of NASA''s final missions to the Moon. Autographed by the crew of Apollo 16, will the gang take one giant leap and buy this rare piece of history or will they take steps to abort the mission? Then, Rick is presented with an 1861 Civil War Colt musket that was won in a poker game. Mysteriously perfect in every detail, will Rick risk going all-in on an offer or will he second guess his hand and fold? And later, Corey and Chumlee meet a guy selling his collection of NFL pins from the first 20 Super Bowls. Will they draw up the perfect play and celebrate the win or will they fumble the deal and lose yardage?', '2010-07-12', 21, '/oddqYDsj3SY4HBFaDeWIQraxa6C.jpg', '2026-04-03T16:34:16Z', '2026-04-03T16:34:16Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('202c454f-3033-48a0-a814-9b8f6147bb40', '04e133fd-c4a3-4dfa-8369-c6dcfd1e3a5a', 85, 'Telly becomes a firefighter', 'Oscar gathers all his "friends" for a club photo, cramming them closer and closer together for the shot. Luis explains the parts of a toy fire engine to Telly, who immediately dreams of becoming a firefighter. After putting on a helmet and getting a small extinguisher, Telly discovers he must wait for people to call for help rather than solicit for work, and learns that real firefighters require training and education.

