INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('2086d1a8-fc33-4ab8-9e6c-929bf8d3f2e3', 'dbd3583f-e9b2-46d1-a37e-309eb666e233', 19, 'All Pomp but No Circumstance', 'With her apprenticeship at Willie Watkins'' funeral home almost complete, Phaedra helps a "real" family through the grieving process. NeNe travels to LA to meet with the creators of the hit TV show Glee and entertains the idea of moving to the west coast permanently. Kandi continues to juggle her businesses by working on designs for a new Bedroom Kandi sex toy line, while Kroy visits Kim''s father to have a very important man-to-man talk. Later, all the women come out to support Phaedra at a big event at City Hall where she makes an unexpected announcement.', '2012-04-01', 43, '/rgA7cohf01sBmCxF7tj4qMlahgU.jpg', '2026-04-03T16:34:45Z', '2026-04-03T16:34:45Z');
