INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('2097697c-29c9-44ee-a1ac-100b09e719d3', '23af85bf-93be-48cd-913c-09c2f60403da', 10, 'Close Rick-Counters of the Rick Kind', 'Rick and Morty have a falling out when Rick is approached by some familiar associates.', '2014-04-07', 23, '/8gOouaPQhfB8cC01sYyFLYgTcRq.jpg', '2026-04-03T15:40:41Z', '2026-04-03T15:40:41Z');
