INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('20c5f63f-d80a-4920-b543-d3c5dbb18219', '73ae1459-ba91-4185-a9da-bf6f2844af49', 12, 'Eat, Drink, and Be Scary', 'Looking for love again, Ramona meets with a matchmaker. Meanwhile, Dorinda and her daughter Hannah discuss Dorinda’s recent life struggles. And to mark the end of Halloween week, Luann hosts a voo-doo themed dinner party where Ramona becomes the subject of everyone’s witchy ire.', '2020-07-02', 60, '/mEzEmnyk2bgpBMnSbtohPfZqOTJ.jpg', '2026-04-03T16:35:25Z', '2026-04-03T16:35:25Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('20c77f8e-0fff-4141-98f9-07359d45ca76', 'ebc99729-ccb7-4d64-82c1-42708cd7ba85', 35, 'Episode 35', 'High Diver!

Peter joins British diving champions LINDSEY FRASER and ANDREW JEFFS at Crystal Palace pool and picks up a few tips on perfecting Olympic dives like the double somersault, the pike and the half twist.', '1981-01-08', NULL, NULL, '2026-04-03T17:21:55Z', '2026-04-03T17:21:55Z');
