INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('20d4bdd7-2727-4bc7-85e2-bec7ed247c88', '1f34e241-4c1d-4586-921a-1c5aeb1fbbaa', 103, 'Episode 2198', 'Maria has just finished making a small table to give to Linda for her birthday. Telly comes by with a potted plant and asks Maria to build him a table to put it on. Buster the Horse greets Oscar and remarks that he looks rather slovenly, a word Oscar has never heard before. Buster explains it and gives various synonyms which are new to Oscar as well.

Sponsors: O, T, 8', '1986-04-09', NULL, NULL, '2026-04-03T17:36:36Z', '2026-04-03T17:36:36Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('20d572e9-21d1-4c7c-9d2f-f744ae5f75ee', '3fc7c152-e4f6-426a-a899-36ec454c4403', 50, 'Frog Prints', 'Everyone goes on a boat ride through Dragoon Lagoon where Max makes friends with a Unifrog named Hoppy, who can say his name, despite Quetzal''s objections that he can’t take him home because he would feel homesick and miss his family.', '2000-01-21', NULL, NULL, '2026-04-03T15:26:03Z', '2026-04-03T15:26:03Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('20da57db-7a3f-4fdc-947e-2aefd99e2b95', '4f18ac4c-8757-456c-a49a-224f00e6a9f7', 5, 'Firefly Show', 'At dusk, Chris welcomes the viewer to Sesame Street as he closes Hooper''s Store, and listens to all the nighttime sounds. Telly and Baby Bear pass by him with a net and a jar, and tell him that they''re trying to catch fireflies. Chris goes home, and Telly and Baby Bear tell the viewer to help them out by pointing out any fireflies they see. One flies above their head, and they scramble to catch it as they follow it near and far.', '2008-08-15', NULL, '/4OnXjgBbdzKkaqIxemgTaTRLKx9.jpg', '2026-04-03T17:36:45Z', '2026-04-03T17:36:45Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('20dd4d78-e45c-4a01-9cdd-16df28383919', 'b7538712-04ce-43a6-9163-62280bbb084b', 22, 'Zoe Creates a Zoeology Book (3872)', '', '2000-02-01', NULL, NULL, '2026-04-03T17:36:42Z', '2026-04-03T17:36:42Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('20e498e0-ce11-443d-9171-9427c7267151', '8bae6aa3-4b55-4fa6-bc15-8f4317bd1f13', 23, 'Arts Foundation Pt 3', 'Rogers explains the size of things by having a tailor alter a suit jacket. Those in the Neighborhood of Make-Believe donate things to the Appel family.', '1972-03-22', NULL, NULL, '2026-04-03T17:35:40Z', '2026-04-03T17:35:40Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('20e60612-af8d-4c00-b024-5601e2a1e8cd', 'f29f456f-8e38-49af-8808-7943977100ec', 2, 'Arthur and the Whole Truth', 'While Arthur is practicing for a piano recital, he learns that Buster has been telling him white lies just to not hurt his feelings. Arthur and Buster agree to not tell any more white lies.', '2016-10-10', 13, NULL, '2026-04-03T17:38:02Z', '2026-04-03T17:38:02Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('20e9e5bb-0f52-4020-a7a6-b9b6cf0527f4', '4d2cac0f-38fd-438b-8afa-acf43952e535', 69, 'Episode 69', 'A magazine programme for younger viewers.  Introduced by Christopher Trace.', '1960-02-12', NULL, NULL, '2026-04-03T17:21:47Z', '2026-04-03T17:21:47Z');
