INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('20f102ed-5ba3-46e3-9084-ecba50a3f03a', '46d7a706-c7a8-4ebe-b96f-387c66e8bb8b', 93, 'Episode 1538', '', '1981-04-01', NULL, NULL, '2026-04-03T17:36:34Z', '2026-04-03T17:36:34Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('20f875f6-a785-4640-b252-917d82f60f32', '941b8c65-4454-4336-be7c-1d0591c12f90', 8, 'Pingu''s Moon Adventure', 'Pingu’s and Grandfather are outside looking at the moon, and Grandfather explains to Pingu how to get there in a rocket. Pingu decides he wants to visit the moon, so when he gets home he goes into the shed and gets out the toolbox. Pinga comes and asks what he’s doing. Pingu tells her that he’s going to build a rocket to go to the moon, and she wants to help. They go into the shed and come out with a miscellaneous collection of objects that, together with an old barrel, they use to build the rocket. Grandfather arrives just as they finish with a present for Pingu - an old diving helmet for him to use as a space helmet. Grandfather shows Pingu how to do a moonwalk like in the war while Pinga is getting her potty to use as a helmet, and both Pingu and Pinga go into the rocket. Grandfather tells them not to land on the grass if they land on another planet. Inside, they make their space uniforms using tinfoil. Pingu sits in the pilots seat and pulls the lever to take off, but they’re then both scared when the rocket starts rocking and shaking. They then see a strange alien face, that''s peering in at the window and making weird noises. Pingu looks out of the window to find out what’s going on, and realises that Grandfather is responsible. Pingu and Pinga get out of the rocket, hide, and then watch Grandfather performing! They creep up behind him and yell, giving him quite a shock. They all laugh about it, and together moonwalk off to plant a commemorative flag.', '2003-09-19', 5, '/jFTez5k7dYrwvxZ1LqNWBVZ1J6K.jpg', '2026-04-03T17:22:20Z', '2026-04-03T17:22:20Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('2105f74b-f16f-490e-98d7-fdcc9906b344', '6053b5c1-ce86-425c-8166-e0fcc3466061', 50, 'Episode 50', 'with Valerie Singleton, John Noakes, Peter Purves', '1970-03-09', NULL, NULL, '2026-04-03T17:21:50Z', '2026-04-03T17:21:50Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('210a8df9-db43-4ce3-8a98-9516051f9a61', '54facb0b-db59-41fe-9d64-c7c7221a3c81', 19, 'Reunion (2)', 'The women confront Ramona over her lies and insults; Dorinda, Bethenny, and Sonja challenge Tinsley to tell the truth about her relationship; Luann is in the hot seat as Andy and the ladies discuss her sobriety slip and probation violation.', '2019-07-18', 60, '/g40LxkHp90pJsyTrZTUl9EGFouY.jpg', '2026-04-03T16:35:25Z', '2026-04-03T16:35:25Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('211e0b9d-328d-4c77-93ee-275a0c1548d2', '05fa5e18-78d2-41fe-ae30-0c242c7ffb6a', 24, 'Fields of Fire', 'Sam receives new equipment for fighting fires. It proves to be useful when careless campers fail to put out their fires in the fields.', '2003-05-01', 10, '/xPoeoII4VZbOfWDiF5j5rSJy1Ny.jpg', '2026-04-03T17:14:38Z', '2026-04-03T17:14:38Z');
