INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('21376a07-91b5-4997-b920-27d662a80bcb', 'df895a8e-db4c-48d1-bf84-9a6a650583dc', 15, 'Arthur Unravels', 'Arthur''s Grandmother teaches him how to knit. However, embarrassed by his new skill, he tries to hide it from everyone else.', '2011-04-26', 13, NULL, '2026-04-03T17:38:00Z', '2026-04-03T17:38:00Z');
