INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('2139e018-e6cb-4026-9cf2-c6afc1dde9c6', '79916e0e-881c-43a7-b4ee-00e5052a94be', 2, 'The Cold Snap', 'The Dispatcher can''t hear properly due to a bad cold, this situation unfortunately leads to some confusion because he is not entirely sure what everyone else is saying exactly.', NULL, NULL, NULL, '2026-04-03T17:10:11Z', '2026-04-03T17:10:11Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('213daf17-46e4-4cad-931c-0af72c79dd6d', 'da06465b-9154-4feb-a455-374df7dab02f', 22, 'Grouch Apprentice (4104)', 'Donald Grump, the grouch with the most trash in the world, is looking for a new apprentice. Oscar, Grundgetta, and the other grouches can''t wait to meet him because if they get chosen, they will get to keep some of Grump''s trash. Elmo decides that he wants to be Grump''s helper too, but just because he likes to help others. Grump puts them through counting and sorting tasks that Elmo does great at. Oscar and Grundgetta are too busy arguing and the other grouches have already been fired. Grump decides that even though Elmo succeeded at all the tasks, he is too good at being a helper to help a grouch. Elmo doesn''tmind. He gets to leave with the one thing he wanted anyway- Grump''s hairpiece. Grundgetta and Oscar are both hired, but they decide that Grump''s trash isn''t worth it if they have to help him to get it. He leaves Oscar and Grundgetta no choice but to tell him, "You''re fired!"', '2005-09-28', NULL, NULL, '2026-04-03T17:36:44Z', '2026-04-03T17:36:44Z');
