INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('217c788b-6b27-4ffd-bbe5-39883b946535', 'e40e6b63-9f84-449f-8e88-53209b0906c8', 25, 'Rosita Gets Upset at Zoe & Abby', 'Rosita and Zoe are both excited about their play date together. As they start to play hide-and-seek, Abby Cadabby poofs up out of nowhere. Rosita is about to show Abby how they play hide-and-seek, but Abby mentions another game, "jumping rhymes," which piques Zoe''s interests. Zoe and Abby are good at the game, but Rosita has trouble thinking of words that rhyme with "chair," and can only think of made-up words (which are acceptable).', '2007-10-12', NULL, '/7ERLOEgQuTHjHLGFZMCkeMTPXfW.jpg', '2026-04-03T17:36:45Z', '2026-04-03T17:36:45Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('217dff72-7122-4503-ae0e-44746cfbc789', '50d6073b-d6ab-4b00-9b01-5d829d987267', 4, 'Chapter Four: The Body', 'Refusing to believe Will is dead, Joyce tries to connect with her son. The boys give Eleven a makeover. Nancy and Jonathan form an unlikely alliance.', '2016-07-15', 50, '/60wmC1e20HV8gu688GAhsWxqxPx.jpg', '2026-04-03T15:40:38Z', '2026-04-03T15:40:38Z');
