INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('218c962c-1d67-48cb-aea2-30e6f129ec79', '36ea3814-66b4-4986-b6ee-44559d3562c1', 10, 'A Trip Down Memory Lane', 'Porsha feels that it''s time to move out of her mother''s residence. Cynthia''s sister comes over and plans to stay longer than expected. Kandi tries again to fix Mama Joyce''s problems with Todd. Phaedra and NeNe receive an invitation to dinner by Mynique''s husband.', '2014-01-05', 43, NULL, '2026-04-03T16:34:46Z', '2026-04-03T16:34:46Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('218d2013-8f91-4ef8-a947-96fd7a6cf3d2', 'a84aa42d-e738-4081-8da9-1faec0209ee9', 23, 'Signals', 'Frankie points out to Mike that his social ineptness has been passed on to Brick, leading Mike to decide that both he and Brick need to be more social, and the Heck family BBQ is the perfect time to try. Meanwhile, Axl volunteers to clean the family pool in an attempt to get girls to stop by and swim and Sue tries to raise money for a local parish because her new friend, Reverend TimTom might be leaving in order to keep costs down', '2010-05-12', 22, '/6sKkB0bxQDsNJFpxAt8MvXuQyc3.jpg', '2026-04-03T15:40:28Z', '2026-04-03T15:40:28Z');
