INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('219922ef-92a2-4e7e-b880-b7725f0971e4', '32192008-7529-4677-933f-c55ea6146368', 1, 'Second Bloom', 'Gizelle brings the group together to process Karen''s trial and sentencing, but the conversation shifts toward relationships; Keiarna and Stacey circle the block on love; Ashley hosts her first big outing as newly divorced woman.', '2025-10-05', 54, '/tehNoP03kRHZvI7Z6LuqX78AZhm.jpg', '2026-04-03T16:35:41Z', '2026-04-03T16:35:41Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('2199bb86-1a77-4143-99b4-ce76da985511', '80775c3d-fa41-46f6-96ec-efc2e14efdcf', 2, 'New House, Old Grudges', 'The ladies go to the Hamptons, and LuAnn shows off her new home at an informal party. Meanwhile, Dorinda and Sonja finally meet one another at Ramona''s house; Ramona reaches out to LuAnn to address the past; and Carole flirts with LuAnn''s personal chef.', '2015-04-14', 44, NULL, '2026-04-03T16:35:23Z', '2026-04-03T16:35:23Z');
