INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('21aac5ab-f8c6-42d8-8deb-db63351bbfb7', '301fb913-4e76-408f-b84b-05bf979766fe', 1, 'The Engagement', 'Jerry reneges on his pact with George to be more like "grown-up men"; Newman takes care of a barking dog that keeps Elaine awake.', '1995-09-21', 23, '/mn2LSAhEzn4I0S9kHtakr624ndV.jpg', '2026-04-03T16:34:11Z', '2026-04-03T16:34:11Z');
