INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('21d30f62-5c6c-4616-81d9-2bf94e56bdef', '4d2cac0f-38fd-438b-8afa-acf43952e535', 363, 'Episode 363', 'with Christopher Trace and Valerie Singleton.', '1965-05-24', NULL, NULL, '2026-04-03T17:21:47Z', '2026-04-03T17:21:47Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('21d35c9a-6bc7-4da5-9755-304cfd9236c9', '4d2cac0f-38fd-438b-8afa-acf43952e535', 243, 'Episode 243', 'Christopher Trace and Valerie Singleton introduce a magazine programme for younger viewers. Including: Little Watha: 2: The Headdress by Oliver Postgate. Where will the boy of the Popangawa find his headdress of eagle''s feathers so that he can be a brave and bring the rain to give them their corn? Told by Peter Hawkins and Patricia Hayes. Owning A Pony - Ross Salmon takes Elizabeth for her first ride on Moorland King. Petra Takes a Bath - Do''s and don''ts in bathing your dog.', '1963-08-19', NULL, NULL, '2026-04-03T17:21:47Z', '2026-04-03T17:21:47Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('21d78cfc-57db-467b-9c65-2684d7f6beb9', 'd1d267dd-e27f-4543-acb8-0d28f676512a', 50, 'Episode 50', 'with Valerie Singleton, John Noakes, Peter Purves.', '1968-02-26', NULL, NULL, '2026-04-03T17:21:49Z', '2026-04-03T17:21:49Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('21d9cf38-4de6-4e9b-9832-fa1983e2b9e8', '6a2d2839-7106-4c3b-8906-c9b3e4bfcc8b', 11, 'Making Woo-Hoo-Py!', 'A banished Shannon journeys to join Vicki and Brooks in Puerto Vallarta. Meanwhile, Lizzie struggles to juggle work and family; Heather hires a personal chef; and Tamra''s effort to teach Eddie a lesson in fatherhood backfires.', '2014-06-30', 44, NULL, '2026-04-03T16:35:32Z', '2026-04-03T16:35:32Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('21db2b23-253d-4f94-8103-e04a9bd76529', '25fe20d1-6fc6-4236-93f6-73178498cdfa', 7, 'Four Wives and Counting...', 'The big day is finally here! Follow Kody and his wives as they make Robyn officially wife number four. See this extraordinary family as they celebrate the newest additions to their family and prepare to embark on a new chapter in their lives.', '2010-10-17', NULL, NULL, '2026-04-03T16:34:27Z', '2026-04-03T16:34:27Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('21e0e1a4-4163-4082-ba5c-2eedcf783167', 'c9d2b3fb-7845-4f3c-9847-ce1f7717257a', 6, 'Pawn of the Seas', 'An 18th-century sea map from the legendary Captain Cook has Rick exploring a big deal; Chumlee haggles for a hilarious "Saturday Night Live" prop; an autographed piece of memorabilia from WWE star Roddy Piper; an antique bicycle.', '2019-03-04', 42, NULL, '2026-04-03T16:34:21Z', '2026-04-03T16:34:21Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('21e3f276-0a42-443a-ab57-ed72c580ee1d', '20d7138e-eea8-46a8-8ada-2b0f0ee1f674', 23, 'Episode 23', 'Twelve-year-old Juliette Smith from Barrow-in-Furness wants to be a train-driver when she leaves school. Today she has a taste of the old days of steam as she rides with Simon on the footplate of the 532 Blue Peter.', '1982-11-29', NULL, NULL, '2026-04-03T17:21:56Z', '2026-04-03T17:21:56Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('21e4b601-638f-47d5-879b-c4fda55113aa', '4b2a19e0-2fae-492e-bc31-f78e63d88ebc', 25, 'Wound Up Rick', 'Make some noise with the Pawn Stars when an autographed Led Zeppelin album looks to break records in the shop. Will Rick give a whole lotta love and make a deal, or will it ramble on out the door? Then, an antique whistle collection announces itself. Will Rick be whistling a happy tune or will a deal blow away? Next, Corey gets political when a Doonesbury cartoon pencils itself in. Will he draw up a deal or will his offer get erased? And later, the minutes are ticking down when Rick explores a self-winding clock. Will he make the time for a deal or wind up with nothing?', '2017-01-23', 21, '/26aDoZ5Y6c8bU24FEoPNRmWkLBS.jpg', '2026-04-03T16:34:20Z', '2026-04-03T16:34:20Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('21f00de3-6176-452a-b1c8-ae2c4f66562c', '8bdf0ad3-a798-4d5a-b304-c7501eae6867', 3, 'Love Tanks', 'Tamra and Simon Barney celebrate their ten-year wedding anniversary with a weekend getaway in Napa, and they invite Vicki and Donn Gunvalson to join them. While Tamra and Simon enjoy a romantic weekend of wine tasting, grape-stomping and gourmet dining, Vicki struggles just to be civil to Donn. Envious of Tamra and Simon''s relationship, Vicki concludes that her "love tank" is empty and she''s uncertain if Donn can fill it. Although her husband, Matt, is still in her house, Jeana Keough is making an effort to re-build her life post-separation with the encouragement of her family and her trainer, John Ellis. Gretchen Rossi and Jeff attend the Indianapolis 500. With his history in the automotive and racing car industry, Jeff''s status provides access and privilege that very few people have at the races. Gretchen rubs elbows, exchanges a few kisses, and rides along with the Indy 500 royalty. Meanwhile, a horrible turn of events threatens Lauri Peterson''s fairytale life with her husband, George.', '2008-12-09', 44, '/cZHsP2SCO7684NZvlEIMHlTumaP.jpg', '2026-04-03T16:35:30Z', '2026-04-03T16:35:30Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('21f2f011-11c7-42a7-8131-bf935e133878', '5062ce29-8dbb-48ab-879b-0771221678d5', 3, 'One Warm Fox', 'It is winter, and very, very cold. So cold, in fact, that Fox borrowed some of Percy''s clothes with the help of a scarecrow in the cold winter night. Percy doesn''t notice though, because Fox puts them back in the morning.', '1999-10-03', 15, NULL, '2026-04-03T17:19:02Z', '2026-04-03T17:19:02Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('21f7eca3-16a8-45ce-a367-cfb4049b0524', '0d24c742-83f2-4f37-8a5d-0b09c7df6a7f', 4, 'A Sermon of Survival', 'Yennefer''s conviction starts to waver. Ciri opens up to Mistle about her true identity. Geralt finds himself at the mercy of Dijkstra.', '2025-10-30', 55, '/yTKE8PmQy4lm1gHgobnoxIGq3WK.jpg', '2026-04-03T15:40:46Z', '2026-04-03T15:40:46Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('21fca2c9-b0ce-406c-b8ce-be312e429120', '27a5a980-ec0d-4637-b5ba-df8324a6405a', 6, 'Bad Choices', 'As the Heck home begins to literally fall apart, Frankie and Mike consider leaving homeownership behind and moving the family to an apartment. Meanwhile, Axl tries to fake Frankie out by pretending that he''s sick in order to get out of taking a school test - and must later convince her that he''s well enough to attend a party that evening; Sue and her ex-sort-of-boyfriend, Brad, volunteer to prepare a school skit about showing the dangers of texting and drinking while driving; and Brick tries to offer a little bit of levity by spouting off Shakespearian quotes.', '2011-10-19', 22, '/yNbIgrHMeIwIM0qBfTzum6Vmksj.jpg', '2026-04-03T15:40:29Z', '2026-04-03T15:40:29Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('22068425-328c-416a-96a6-ac6374036d41', '4d2cac0f-38fd-438b-8afa-acf43952e535', 188, 'Episode 188', 'All Aboard with Christopher Trace and Anita West in a magazine programme for younger viewers.', '1962-06-25', NULL, NULL, '2026-04-03T17:21:47Z', '2026-04-03T17:21:47Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('2206f9d6-2e03-413e-a52b-fc80689f84aa', '573fa62f-55a9-4f17-97cc-d1a005a83cc8', 27, 'Ruff Ruff Doggie Robot', 'Elmo, Tamir, and Alan are building a robot dog, but the tail isn''t "waggedy." What if they wrap a wooden paintbrush with shiny foil? Let''s try!', '2025-07-17', 26, '/uuAAMm3mfHPFQjeJSSZalHWQlUU.jpg', '2026-04-03T17:36:52Z', '2026-04-03T17:36:52Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('2211a85e-2ca4-4d75-8544-73577fd08251', 'f4d370ca-3c39-40a8-911d-e2b5e7c6b0d7', 5, 'Little Bear''s Snowmen', 'It’s winter and snow has covered everything in the garden. The toys have fun playing on a sledge and building a wonderful snowman. Little Bear is worried that the birds must be very hungry as their food is hidden under the snow. At lunchtime the toys all go inside to make bread snowmen to go with Old Bear’s delicious soup. While they are waiting for them to cook, they tell each other food stories and become more and more hungry. At last the bread is ready but Little Bear has not forgotten that the birds need feeding too and he has a really good idea.', '1996-10-02', 10, NULL, '2026-04-03T17:18:56Z', '2026-04-03T17:18:56Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('2215f965-fd92-463c-adb3-b5819c59ce68', 'f4c40307-9b5e-4263-a4e0-dfa138131e7f', 3, 'Let''s Make Music', 'Telly learns that music can be made from many different things, as the members of Stomp! make music all along Sesame Street with different every day objects.', NULL, NULL, NULL, '2026-04-03T17:36:27Z', '2026-04-03T17:36:27Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('221b325e-d8fe-47f3-b2cb-d706ff668361', '10e64538-c78a-4cb0-82f9-17d14256dbac', 23, 'Find My Hecks', 'Frankie figures out a way to secretly track Sue and Axl after they refuse to abide by their curfew while they''re home for the summer. Meanwhile, Brick''s determined to discover who else could be class valedictorian as middle-school graduation approaches.', '2016-05-11', 22, '/upnx2eaEFGHJpO6Vo5Ya6iqrbYe.jpg', '2026-04-03T15:40:31Z', '2026-04-03T15:40:31Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('22244c5a-eabd-47ca-9a50-e20d6efdac3c', '39505290-458d-46b9-8bdf-69ee037230e2', 4, 'Giving Thanks: A Native American Good Morning Message', 'LeVar discusses how people show gratitude for kind acts and how we can repay each other in acts of kindness to spread good will in the world. Nicholson Earl Billey reads the featured story, a poem of greeting that Native Americans say each day to bless the earth and pray for all the gifts they have been given by respecting the planet.', '1997-04-10', 30, NULL, '2026-04-03T17:36:20Z', '2026-04-03T17:36:20Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('22248b8a-f4b7-46fa-b92d-a5995d51a966', 'e38e9d87-1432-4a1a-a7d0-64a559bf7570', 13, 'So Near And Yet So Far', '', '1993-03-28', 24, '/qAVAo3V3Ua4CTMbQ1FfAW9mjM5B.jpg', '2026-04-03T17:18:49Z', '2026-04-03T17:18:49Z');
