INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('22baf545-807d-4c8b-a610-1f56bc3a39b8', '9193e795-da7c-40ec-b68f-f63aa7d5174f', 115, 'Histories & Lore: House Martell', 'Oberyn Martell discusses the history and reputation of House Martell, the strong-willed ruling family of Dorne that refused to join the Seven Kingdoms for centuries.', '2015-02-17', 4, '/8Zotw4gqUYuvSqmkuuCa8Zn6aNt.jpg', '2026-04-03T15:40:35Z', '2026-04-03T15:40:35Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('22be2c12-f2e9-49e2-8169-ddc0e0207b06', 'cd7ade48-bcf3-49c4-acf2-cde19ca45cf5', 6, 'The Demon Headmaster Takes Over (Part Six)', 'Dinah makes the final push to save the world and her mother.', '1998-01-22', 25, NULL, '2026-04-03T17:40:35Z', '2026-04-03T17:40:35Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('22be94cc-392b-4d2f-8324-9f08bb4a933e', 'bb919aec-0d5c-4c58-9a5a-fa2a0a5de2b6', 48, 'Episode 453', '', '1973-01-31', NULL, NULL, '2026-04-03T17:36:29Z', '2026-04-03T17:36:29Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('22c01d53-8e7d-4e99-b21b-8d95c9a2f319', '5c1b881f-ac58-4d72-b63f-209952d4f902', 5, 'Episode 5', 'The Gardening Family  Are there michaelmas daisies at the bottom of your garden? Do you grow lilac, gladioli, tradescantia, Virginia creeper, or tulip, plane and acacia trees? All these plants and trees were brought to this country by one family, the famous Tradescants. Chris traces their extraordinary story that ends in a Lambeth churchyard.', '1979-09-24', NULL, NULL, '2026-04-03T17:21:54Z', '2026-04-03T17:21:54Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('22c5371c-3012-416d-a49e-ee989098af3a', 'd01919fb-98e0-42bf-b9d9-1cecf912f6e1', 48, 'Telly Sees a Mysterious X (3833)', '', '1999-03-24', NULL, NULL, '2026-04-03T17:36:42Z', '2026-04-03T17:36:42Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('22c5cc8f-fb28-4e84-a2f2-192e08243706', '004abc4c-ce77-4df9-8c97-9f56ea8b37ce', 9, 'Skates', 'Tiger and Kipper go to the park to try out Tiger''s new roller blades. Tiger crashes and hurts his thumb. He tells Pig he''s so badly injured he can''t use roller blades anymore and Pig can borrow them. But Pig is quite happy on Kipper''s roller skates and does a ballet dance to show them.', '2000-03-16', 30, NULL, '2026-04-03T17:10:49Z', '2026-04-03T17:10:49Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('22c6c272-4216-4c09-b771-561e2aa5186d', 'd1d267dd-e27f-4543-acb8-0d28f676512a', 78, 'Episode 78', 'with Valerie Singleton, John Noakes, Peter Purves.', '1968-06-06', NULL, NULL, '2026-04-03T17:21:49Z', '2026-04-03T17:21:49Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('22c8bc2f-fc64-4601-8816-33c130b43004', 'a3a2c2fb-8276-412c-9d86-5175167be1d7', 2, 'Episode 2', 'with Valerie Singleton, John Noakes, Peter Purves', '1971-09-16', NULL, NULL, '2026-04-03T17:21:51Z', '2026-04-03T17:21:51Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('22cbba90-cb29-4115-841f-8180601db96b', '6f323ed7-50f3-4902-a8b2-2072c5d0489b', 2, 'The Demon Headmaster (Part Two)', 'Dinah struggles to get on with Lloyd and Harvey, as snow falls. A snowball fight breaks out and Dinah, Lloyd and Harvey are forced to clear up the snow on the school yard into snowballs. Dinah joins an exclusive group.', '1996-01-04', 25, NULL, '2026-04-03T17:40:34Z', '2026-04-03T17:40:34Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('22ce2e9a-803e-4a93-9d15-8219b82517c9', '6ef86c27-33e7-47e5-a053-483059dfd16d', 41, 'Episode 41', '', '1982-02-04', NULL, NULL, '2026-04-03T17:21:55Z', '2026-04-03T17:21:55Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('22cfb73f-8a7e-4196-bb7f-8ca505ad396f', '1415ef1c-411a-4c26-814a-7c79c3628bc2', 21, 'Reunion (2)', 'In part II of the reunion, new housewife Tinsley opens up about her rocky re-entry into NYC life and reveals some big news. Carole reflects on the turbulent election and the status of her relationship with Adam, while Sonja discusses her personal love triangle, which elicits a shocking accusation about her French lover. Additionally, Bethenny gets emotional talking about her personal life and how she is planning to move forward.', '2017-08-23', 60, '/pplLvMqUCZ8Yaa3dshg033lWUYh.jpg', '2026-04-03T16:35:24Z', '2026-04-03T16:35:24Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('22d48e1b-d647-45b5-8336-4e448f6efea1', '991e78f1-03a5-4d26-8f75-75e11db4243c', 3, 'Noisy and Quiet: How Do Different Percussion Instruments Sound?', 'Rogers visits drum performer Tim Adams. In the Neighborhood of Make-Believe, X and Henrietta have rigged their tree so that, at the first sign of anything unnatural, everyone will hear constant drumming.', '1999-03-01', NULL, NULL, '2026-04-03T17:35:48Z', '2026-04-03T17:35:48Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('22d4d0da-148d-4459-9773-3e3fbb2f0ce6', '4a8e3db0-8068-4ff3-942f-91f45f665f20', 28, 'The Fox and the Crow', 'When ""The Fox and the Crow"" fable is read in the library, Walter and Clay get angry over the way the crow was depicted as a ""bird brain"", and then protest to have the story banned! The Lions come up with a less extreme approach, and suggest that they re-write the story to make the crow the one who comes out on top.', '2000-05-10', 30, NULL, '2026-04-03T17:12:27Z', '2026-04-03T17:12:27Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('22d6d54f-9b03-4f94-b323-4a8b77e52292', '56184a09-a2e5-4d61-b4d5-66a16df3036b', 3, 'Dudley and the King', '', NULL, 29, NULL, '2026-04-03T17:12:14Z', '2026-04-03T17:12:14Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('22dbff0d-3fde-45a8-8406-1c14ea25a910', 'e6254ae4-7d72-493b-8b37-b677d8b76c46', 43, 'Episode 708', '', '1975-01-01', NULL, NULL, '2026-04-03T17:36:31Z', '2026-04-03T17:36:31Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('22e1be11-168e-4c4c-ab17-32b245364d42', '363a94f9-e0e5-441c-aa86-2be2e9832da1', 1, 'Pawn Jam', 'When a very special cowboy hat owned by President Ronald Reagan moseys into the shop, can Rick wrangle an offer? Next, Chum lights up when a glowing Pearl Jam painting rocks across the counter. Will a deal make him come alive, or will the seller look for a better man to buy it? Next, Rick and Corey rehash the past when a seller brings a Sammy Sosa signed baseball into the shop. Who will win the race to bring home a deal? And finally, inspired by a signed copy of photographer, Peter Lik''s book, Chum sets out to capture an unforgettable muse.', '2021-10-02', 42, '/9tLHRHkrLDfDL5GHNHrgqMo3YGh.jpg', '2026-04-03T16:34:23Z', '2026-04-03T16:34:23Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('22e40f7a-c1c5-428c-9cc9-8c895ca7339f', '22beba7f-9b8e-4563-93da-46e76ecba427', 19, 'Oscar Loves Cranky', 'Oscar gets a new dog: a Rottendoodle named Cranky. Because he has heard that Rottendoodles are grouches that never do what you tell them to, never help anyone, and never kiss, he is astonished when Cranky starts doing all those things.', '2006-09-21', NULL, '/tRNONnlbtNyVfLMw4S1fnunAruG.jpg', '2026-04-03T17:36:44Z', '2026-04-03T17:36:44Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('22e9ef33-bbfd-4cc6-9109-bce1a9912e3f', '16cbf3f2-fffd-4a78-bca3-96d05f5a2c6b', 12, 'Mr. Ratburn''s Secret Identity', 'Arthur and his friends believe that Mr. Ratburn has a secret identity.', '2016-05-25', 13, NULL, '2026-04-03T17:38:01Z', '2026-04-03T17:38:01Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('22f21618-f9bb-420a-9044-565371373ce3', 'e1063f87-66c2-4e2d-a913-53362941aa19', 126, 'Episode 401', '', NULL, NULL, NULL, '2026-04-03T17:36:29Z', '2026-04-03T17:36:29Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('22f37667-49de-43e9-9848-0041046152d0', '05fa5e18-78d2-41fe-ae30-0c242c7ffb6a', 4, 'Bug Eyed Boy From Venus', 'When Trevor Evans tells the children that there''s no such thing as little green men from outer space, Norman is determined to prove him wrong.', '2003-04-03', 10, '/9y1uSo6JZZKD9Yz4YM0lwiFpr2U.jpg', '2026-04-03T17:14:38Z', '2026-04-03T17:14:38Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('22f4e767-1856-4fea-bb15-7654f8fe47bb', '4d2cac0f-38fd-438b-8afa-acf43952e535', 91, 'Episode 91', 'A magazine programme for younger viewers.  Introduced by Leila Williams.  Including: How Other Children Live: 4: A day in the life of a French boy, a film produced by the French Television Service.', '1960-07-15', NULL, NULL, '2026-04-03T17:21:47Z', '2026-04-03T17:21:47Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('22f54d56-3ca6-480f-b149-b96540412444', '6f731e6b-d3c5-4de6-84e1-7a19cb650e86', 34, 'Rick the Emperor', 'All hail the Pawn Stars when a 44 BC Roman coin with Julius Caesar''s portrait presides over the shop. Will Rick command a high price or will the deal be assassinated? Next, a rare 1960s leather jacket zips in. Will Corey have a cow over the rockin'' style or will he think it''s a bad fit? Then, Corey and Chum hit a streak when plaster casts of Joe DiMaggio''s feet steal a base in the shop. Will the guys mold together a deal or will the sale crumble? And later, Rick is quarantined when a scarlet fever sign infects the shop. Will a deal be his cure or will it just make him sick?', '2016-05-11', 21, '/r7fhIPswpodgu9zj9Q1rbPyT5a2.jpg', '2026-04-03T16:34:20Z', '2026-04-03T16:34:20Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('22f574b8-43af-48a6-b8a3-c39b39dbca22', '5a4e38a1-8e54-4974-8097-d7a7b48630a2', 25, 'Episode 25', 'with Valerie Singleton, John Noakes, Peter Purves', '1970-12-11', NULL, NULL, '2026-04-03T17:21:50Z', '2026-04-03T17:21:50Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('22fb03b6-a5ef-4360-b6c6-c6d7928b6870', 'b7538712-04ce-43a6-9163-62280bbb084b', 27, 'Elizabeth Is Visited By A Fairy Bubbleperson (3877)', '', '2000-02-08', NULL, NULL, '2026-04-03T17:36:42Z', '2026-04-03T17:36:42Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('22fbab14-d55e-41cc-83b4-04c861d3fa84', 'ba99b779-cada-43a7-902a-2adb472c2e30', 6, 'Episode 6', 'Things take a turn for the worse as the boot that the family is sleeping in is picked up by the rat catcher and taken back to his caravan. The young borrower from the forest and the young boy from the house have to join forces to attempt a rescue.', '1992-12-13', 30, NULL, '2026-04-03T17:17:47Z', '2026-04-03T17:17:47Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('22fde499-27fd-4b9a-a63d-c2aacd92ae53', '2b968a9c-5fc0-4e93-bcf9-31d3e4c7b210', 3, 'Episode 3', 'Expedition Turkey  Sunken Cistern: JOHN, PETER and LESLEY boat through the mysterious Roman reservoir that lies beneath the pavements of Istanbul and discover the spot where the world''s first bird-man leapt into space.', '1975-09-15', NULL, NULL, '2026-04-03T17:21:52Z', '2026-04-03T17:21:52Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('23053d79-98ff-416e-a579-f0debecf551c', 'c01ddd2a-bdb1-4c97-8d04-58f791ef1c24', 25, 'Great Singers', 'Animal "music"  spills into Animal Junction, performed by camels, wolves, and elk, far better than a sound effects machine.', '1999-06-24', 27, NULL, '2026-04-03T17:10:55Z', '2026-04-03T17:10:55Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('230583a1-056a-473f-82a7-dd821e298519', '5a4e38a1-8e54-4974-8097-d7a7b48630a2', 6, 'Episode 6', 'with Valerie Singleton, John Noakes, Peter Purves', '1970-10-06', NULL, NULL, '2026-04-03T17:21:50Z', '2026-04-03T17:21:50Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('23070a8f-1295-4aa7-9f5a-1bdc33c212d4', '20d7138e-eea8-46a8-8ada-2b0f0ee1f674', 58, 'Episode 58', 'Simon Groom gets up at the crack of dawn to spend a day with the Household Cavalry, beginning in the stables', '1983-04-07', NULL, NULL, '2026-04-03T17:21:56Z', '2026-04-03T17:21:56Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('230b171b-c43e-444e-a3a2-1ccc44daf2f6', '331fc1df-6d70-4d79-b585-bf28024a4124', 24, 'Towering Inferno', 'Norman Price, Mandy Flood and the twins play hide and seek, but Norman tries to hide in the fire station training tower while the firefighters are running a drill. Fireman Sam comes to the rescue.', '2008-12-12', 10, NULL, '2026-04-03T17:14:39Z', '2026-04-03T17:14:39Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('2310a1b0-d3b4-4b4a-8b17-d309457332fc', '119c16d5-1047-45ec-8242-c72a8eed423b', 7, 'D.W.''s Imaginary Friend', 'D.W. has an imaginary friend, Nadine, says she has to come everywhere, but Arthur is sick of it.', '1996-10-10', 13, '/5jILwQcgeyRFHL5ePbpZoFWH67b.jpg', '2026-04-03T17:37:55Z', '2026-04-03T17:37:55Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('231c0501-d3e0-4d0b-aade-be864a3cd79f', '0fb5ce65-0258-4423-be8a-f7ba9c37bb6b', 4, 'Floating Away', 'Norman and Mandy go off to retrieve their wildlife journal.', '2023-10-24', 9, '/1vTG2u17gz8JxJNb3eoWpt0zyuH.jpg', '2026-04-03T17:14:42Z', '2026-04-03T17:14:42Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('2321734f-292c-4aee-83ba-c135c1d8cdf2', '1d713ca6-4e17-4f84-949c-8cfd98514127', 37, 'Chum''s Secret Stash', 'Strike it rich with the Pawn Stars when a 1907 Saint-Gaudens high-relief coin makes its way onto the counters. Will Rick pay a pretty penny for this rare piece of currency or will he refuse to empty his pockets? Then, Rick gets blindsided when a vintage pair of Ray-Ban sunglasses potentially owned by President George Bush, Sr. gets brought in. Will he be able to see right through them or will his judgment be clouded? And later, when Rick finds Chum''s secret stash in the back, Rick explains to him the concept of layaway. Can Rick make Chum pay or will Chum get his own form of payback?', '2014-12-11', 21, '/yeveG85I7UHIDpzO4u7zdXSWXfQ.jpg', '2026-04-03T16:34:19Z', '2026-04-03T16:34:19Z');
