INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('23274b36-9863-4047-80d2-30e4b4a1761a', '05c0e384-194c-4417-9f62-803eb615e409', 13, 'Ask for permission to borrow things', 'Title number 0013. Mister Rogers sits on the porch swing listening to the symphony rehearse, and afterwards plays with two different kinds of dominoes. In Make-Believe, Marion Petrov dances for King Friday and Lady Elaine steals King Friday''s painting of the Bluebird of Happiness.', '1968-03-06', 28, NULL, '2026-04-03T17:35:38Z', '2026-04-03T17:35:38Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('2327bb60-cfa6-4a50-9e0a-aa549000d8be', 'bc1b58b0-f2d6-4214-914b-231f27fb4d61', 11, 'A Very Jersey Christmas', 'It''s Christmas morning and housewives are stirring. Caroline receives a long-overdue present and Melissa considers herself the luckiest woman in Jersey. But there aren''t many ho-ho-ho''s for Teresa, whose holidays take a not-so-merry turn.', '2011-07-31', 43, '/aMcS7ePeDupYoHju2O0hOIIfIj2.jpg', '2026-04-03T16:35:15Z', '2026-04-03T16:35:15Z');
