INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('233d8334-2fcb-4b33-9b76-a383d35954ba', '46d7a706-c7a8-4ebe-b96f-387c66e8bb8b', 99, 'Episode 1544', '', '1981-04-09', NULL, NULL, '2026-04-03T17:36:34Z', '2026-04-03T17:36:34Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('23423b82-8d36-434f-b29f-4e2b0a325466', '4f18ac4c-8757-456c-a49a-224f00e6a9f7', 14, 'Big Bird''s Nest Sale', 'Big Bird hangs up a sign for his nest sale and welcomes the viewer. He’s selling toys that he doesn’t play with anymore, and says that all the toys in the nest are for sale, while everything out of the nest isn’t, including Radar. Snuffy arrives at his nest, and Big Bird makes him his “Assistant Nest Sale Snuffleupagus”. Snuffy''s only task is to remember what toys are for sale and which are not, especially Radar. Big Bird briefly leaves to get more of his toys from Maria and Luis’s apartment and puts Snuffy in charge, but unbeknownst to him and Snuffy, Big Bird’s tail knocks Radar into the nest when he leaves.', '2008-10-02', NULL, '/8Csx7SOXtWflDJHj4tlBZg2LBwB.jpg', '2026-04-03T17:36:45Z', '2026-04-03T17:36:45Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('23426a72-414a-4642-b225-476f0c6135f4', '2b968a9c-5fc0-4e93-bcf9-31d3e4c7b210', 13, 'Episode 13', 'Who Can Ever be Tired of Bath?  When Jane Austen wrote these words in 1801 Bath was the centre of fashionable society. To celebrate Jane Austen''s bicentenary Valerie revisits the city and takes the waters.', '1975-10-20', NULL, NULL, '2026-04-03T17:21:52Z', '2026-04-03T17:21:52Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('23439cc1-5b21-4b16-9345-ed8832113235', '3ea743ef-0a22-47cf-b1d2-62f37e939253', 33, 'Snuffy''s Grandmother Visits', '', '2002-03-20', NULL, NULL, '2026-04-03T17:36:43Z', '2026-04-03T17:36:43Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('234a0c57-2273-4b78-9db3-26a62fa94991', '4da606e7-9d23-4682-8bd5-f535e1da706f', 21, 'Franklin''s Garden', 'Franklin was proud of his little garden until he noticed a caterpillar kept eating his petunias.  He tried everything to keep the caterpillar out but Mr. Mole explained the significance of a caterpillar and gave Franklin a whole new outlook about his garden, including other living things.', '1998-11-16', 12, NULL, '2026-04-03T17:40:15Z', '2026-04-03T17:40:15Z');
