INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('23ee4088-f337-483f-9547-c888bf0c7780', '4060ad7f-4b8f-4393-8eb1-66a150b928b6', 5, 'Cardboard Castle', 'Issa Rae is a Queen who doesn’t have enough bricks to build a play castle for her daughter. This is a problem! Elmo, Cookie Monster, and Rosita wonder: can they use something else to build the castle? What about cardboard boxes and tubes? The three friends give it a try—and it works. Because they didn’t give up, they built a cardboard castle fit for a Princess!', '2020-12-10', 26, '/5QPzsxku7wgrQPjTz2ycNo1rEmK.jpg', '2026-04-03T17:36:50Z', '2026-04-03T17:36:50Z');
