INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('248b925c-9028-4270-b3f0-bc5779cc9f61', '050d8ae1-6cc1-4018-933d-b3c3d13de856', 70, 'Episode 70', 'Gravel Pit Ski-ing

Michael, the demon of the slopes, is back on his skis again! He''s continuing his freestyle acrobatic ski training in deepest Berkshire. There''s not much snow there in May so he and the British Freestyle Ski-ing team take to the water instead!', '1985-05-20', NULL, NULL, '2026-04-03T17:21:57Z', '2026-04-03T17:21:57Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('248f4231-9ee7-431b-a96c-e4d2118b9483', '7c542833-ed0a-4272-9c53-e822408ab434', 14, 'Kite Catastrophe', 'When Hannah shows off a homemade kite, her stunts cause a barbequing accident, sparking multiple fires!', '2024-10-21', 10, '/er4V6jG8X86stfZ1XkH7DmL3DE0.jpg', '2026-04-03T17:14:42Z', '2026-04-03T17:14:42Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('24908f39-0715-4a8d-9e00-9a463f42e115', '95ca8b6f-ccbc-431a-9d95-9b23367bbfed', 13, 'Season’s Grillings', 'Shockwaves from an unexpected news article continue to spread as the ladies try to piece together the truth. Meanwhile, Garcelle serves up a very Haitian holiday meal for her family. When Kyle gathers the ladies for Christmas dinner, holiday cheer turns to jeer as the women press for answers, and Erika realizes that not everyone has her best interests at heart.', '2021-08-18', 43, '/tsESNfxVltBeXDNroy2cFJoJ3BQ.jpg', '2026-04-03T16:34:58Z', '2026-04-03T16:34:58Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('2492720e-f9f0-48b2-b11b-1805a93b528b', '99b71026-3919-4813-a330-eb09e0e43d74', 5, 'Show Way', 'As LeVar helps his wife and daughter construct his family tree, Diahann Carroll narrates Show Way, in which the author chronicles her family back to her Great, Great, Great, Great Grandmother, who was a slave in the South. Through traditions passed down to each generation, her family learned to sew "Show Way" quilts that were secretly maps designed to help slaves escape to the north to freedom, and how her relatives taught her to keep up with the love of quilting to retain family history.', '2006-11-10', 30, NULL, '2026-04-03T17:36:22Z', '2026-04-03T17:36:22Z');
