INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('24db341c-7fa9-4527-8b57-527a1710a32e', 'd5351b60-8a0c-482a-a6dd-4fb860cfe143', 22, 'Episode 1412', 'Mister Rogers takes viewers outside where he has a tent set up in the grass. After showing the real tent, he goes back inside and shows how a tent can be made inside using two chairs and a blanket.  In the Neighborhood of Make-Believe, everyone is confused by a tent which appeared overnight.', '1975-03-18', NULL, NULL, '2026-04-03T17:35:41Z', '2026-04-03T17:35:41Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('24dd0083-38d5-4024-a0f3-d7e520c9ad49', '87f84063-82b3-45a4-936c-3759e5d91ce3', 7, 'Slippery Slope', 'A fun day of snow tubing leaves Mary and Lisa at odds, Jennie and Mary at war and Meredith and Jen nowhere to be found when it comes to having Lisa’s back. Meanwhile, Heather throws a party for Beauty Lab, Meredith and Seth plan for the future and Jennie still reeling from her conversation with Duy looks towards other solutions for their marital their problems.', '2021-10-24', 44, '/hKPNkaKGxyCSQt7oOvHO3xMPhEo.jpg', '2026-04-03T16:35:44Z', '2026-04-03T16:35:44Z');
