INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('258f837c-8df1-49f7-8372-68a0a997d64b', '5c1b881f-ac58-4d72-b63f-209952d4f902', 78, 'Episode 78', 'Twelve years ago schoolboy Ray Gluckman grew a crystal in an eggcup. See it today in a dustbin - tipping the scale at 40 lbs and still growing!', '1980-06-16', NULL, NULL, '2026-04-03T17:21:54Z', '2026-04-03T17:21:54Z');
