INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('2591e803-c43c-45a6-a5e3-660be2c02c34', '42e591e2-2a88-4434-ae9f-3d4b1d685613', 24, 'You''re Out', 'Burn rubber with the Pawn Stars as Rick and Chumlee check out a 1969 Camaro Z28. In nearly mint condition, will Rick punch this deal into overdrive? Then, a first edition baseball scorebook from 1878 slides into the shop. Published by "Father of Professional Baseball" Harry Wright, can the guys score this one for the home team? And later, Corey''s wild spending habits earn him a visit with a financial adviser. Will he have to sell one of his toys?', '2013-08-29', 21, NULL, '2026-04-03T16:34:18Z', '2026-04-03T16:34:18Z');
