INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('25b59c8e-662d-4988-9d53-d4793eb50c47', '05c0e384-194c-4417-9f62-803eb615e409', 47, 'Fur, feathers, and hair', 'Title number 0047. Opens with Mister Rogers arriving with a book of Fur, Feathers, and Hair. Mr Rogers reads a book that depicts Henrietta and X the Owl. They are flattered when Lady Aberlin shows them. Nicholas and Marion Petrov visit the Neighborhood of Make-Believe dressed up as  X the Owl and Henrietta Pussycat. They dance in both costumes and in leotards.', '1968-04-23', 29, NULL, '2026-04-03T17:35:38Z', '2026-04-03T17:35:38Z');
