INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('25bd38b3-e778-4fed-bfab-c8046a8966be', 'abfe14ee-db42-4dde-a96a-601ff3c53ecc', 6, 'High Standards', 'Cluny attempts to starve the abbey into submission as within Redwall pressure mounts as tempers flare. When Basil and Jess Squirrel seem to desert, Matthias wonders if surrender is close. He decided to try and rescue the stolen tapestry from Cluny in order to give courage to the citizens of Redwall - and discovers that Basil and Jess are attempting the same thing! They outwit Cluny, retrieve the precious tapestry of Martin, and renew the spirit of Redwall.', '1999-09-19', NULL, '/xyZEEqKvFvCTWkRcN69eLRETtkD.jpg', '2026-04-03T17:12:08Z', '2026-04-03T17:12:08Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('25bd9ee1-744d-40ad-be83-3e24b39768d2', 'a8c6182e-05e1-4b68-91a5-5126cf6c94f0', 30, 'In Praise of Ben', 'The title kinda gives it away, the episode begins with Sarah coming ''home'' to Philidelphia, she''s greeted by Moses, and eventually, a slightly bitter James. The rest is ''in praise of Ben'' Benjamin Franklin. It''s about is education, his inventions, and many other things.', '2002-11-08', 30, '/7KT08ePmVRTBsfVi0F2xRYbs9G0.jpg', '2026-04-03T17:38:28Z', '2026-04-03T17:38:28Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('25c1e1b2-072e-4dd5-9cf5-16e8dd8beade', '96dd06ee-d44a-47f3-9372-e29e8eaa77f5', 4, 'Chemistry Set', 'Norman''s dream of making the pongiest stink bomb in the world backfires when Dilys walks into the laboratory.', '1988-09-22', 10, '/gQ81TWZwagMjSZYNBYxvmDsnoZA.jpg', '2026-04-03T17:14:37Z', '2026-04-03T17:14:37Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('25c73172-b13c-43db-8f67-de8deecb1d3c', '204d86fb-d99c-4fd1-8dcd-9c1bcfd3c33f', 20, 'A Snowman for All Seasons', 'The friends go to Snowy Summit to play with Chilly and Nippy (from “My Way Or The Snow Way”) until they realize the weather is warming up. So they go to Polly Nimbus'' cloud factory to bring the snow back.', '2001-06-22', 30, NULL, '2026-04-03T15:26:04Z', '2026-04-03T15:26:04Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('25ccaa74-1f61-48d0-94a1-f265cafbd0fe', '10e64538-c78a-4cb0-82f9-17d14256dbac', 8, 'Thanksgiving VII', 'Frankie clashes with a coworker at her Thanksgiving job, Sue offers to work to see a guy she likes, Axl has an embarrassing moment at the bar, and Mike and Brick are bored at home after a blackout.', '2015-11-18', 22, '/fXWfL2FhuegfpoPiFtPUTvkZlPk.jpg', '2026-04-03T15:40:31Z', '2026-04-03T15:40:31Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('25cdb2d6-56d7-4b4a-b6d8-8cd1eb6148e9', '5062ce29-8dbb-48ab-879b-0771221678d5', 13, 'The Lost Acorns', 'Percy plants some bulbs under the ground. Unfortunately... Squirrel has lost all her acorns and mistakes the planted bulbs for possible acorn storages. Mole finds his secret storage by accident and the squirrel replants the bulbs.', '1999-12-12', 15, NULL, '2026-04-03T17:19:02Z', '2026-04-03T17:19:02Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('25d03287-beee-49fd-8cb0-b9ac5df8ee55', '8e5ed8a4-08e5-4006-9f36-c68c91ddfee4', 23, 'Episode 772', '', NULL, NULL, NULL, '2026-04-03T17:36:40Z', '2026-04-03T17:36:40Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('25d4e99e-3ab4-4c7a-9c4f-5e61d6a30005', '6f731e6b-d3c5-4de6-84e1-7a19cb650e86', 30, 'Gangsters, Guns, & Guitars', 'Get mobbed with the Pawn Stars and revisit some of the best guns, guitars and gangster memorabilia ever to enter the shop: a limited edition guitar hand-painted and played by Def Leppard''s Phil Collen, a signet ring possibly once owned by Lucky Luciano, a rare 1800''s octagon barrel .22 caliber Winchester, a 1969 Les Paul Professional guitar, an ornately engraved 1894 Marlin rifle, and a check signed by Carlo Gambino that prompts Rick to give its owner an offer he can''t refuse.', '2016-04-06', 21, '/l4HizKDDxKPwj2gAcCd1Exy0iyf.jpg', '2026-04-03T16:34:20Z', '2026-04-03T16:34:20Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('25d7c79d-69a8-40b0-b19e-b8c3376e5ab7', '87f84063-82b3-45a4-936c-3759e5d91ce3', 23, 'Reunion (2)', 'The reunion continues with an update on the Real Housekids of Salt Lake City; the women discuss the allegations and rumors about Mary; Lisa breaks down after Heather and Whitney hold her accountable for her attempt at an apology.', '2022-03-06', 44, '/eCMiFlIAzTgJDHwTdagk6l8zjU5.jpg', '2026-04-03T16:35:44Z', '2026-04-03T16:35:44Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('25db7278-a51f-4d36-8093-7dfd20819da2', '0bbd380c-5cb8-46a6-8838-b5d60223c073', 9, 'Lena Horne', 'Kermit cuts Miss Piggy''s scheduled song so she won''t look foolish following Lena Horne. He tells her that "there are singers and there are singers," making her think that he doesn''t want her to show up Lena.', '1976-10-31', 26, '/g2ohZ4kAK9EmMhIJRIh5JqqYH2R.jpg', '2026-04-03T17:35:24Z', '2026-04-03T17:35:24Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('25e56999-64f1-4a17-9542-6295cbf19795', '04e133fd-c4a3-4dfa-8369-c6dcfd1e3a5a', 101, 'Episode 2066', 'A standard episode featuring various street scenes and educational segments with the regular cast. Daily activities and lessons are taught through character interactions. The residents help each other and learn together.

Sponsors: T, U, 11', '1985-04-08', NULL, NULL, '2026-04-03T17:36:36Z', '2026-04-03T17:36:36Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('25e56f19-b62b-453d-bfbe-d80b73778bde', '4d2cac0f-38fd-438b-8afa-acf43952e535', 217, 'Episode 217', 'Christopher Trace and Valerie Singleton introduce a magazine programme for younger viewers. Including Making Puppets with Gordon Murray, uilding a Model Farm: The animals and vehicles and the Blue Peter Vet with ''Petra''.', '1963-01-28', NULL, NULL, '2026-04-03T17:21:47Z', '2026-04-03T17:21:47Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('25ea49a3-5425-40fb-adb7-ece997e3891f', '876145f4-b55e-4070-b35b-893a67f88bac', 16, 'Family Reunion', 'Margaret and Teresa''s friendship faces the ultimate test. Shockingly, Joe Giudice leaves ICE for Italy and Teresa and the girls arrive to see Joe. Teresa and Joe decide the future of their relationship.', '2020-02-26', 43, '/jsROSqARg3vzzvrKtWCbxHbVhEz.jpg', '2026-04-03T16:35:18Z', '2026-04-03T16:35:18Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('25f011cc-7076-41d1-8734-a20edefb2b8c', 'e93f04c2-7344-4b93-abba-8ba1b2f8eb35', 69, 'Episode 604', '', NULL, NULL, NULL, '2026-04-03T17:36:30Z', '2026-04-03T17:36:30Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('25f0e9e8-0606-46ce-b20d-364a602b4541', 'a4843a51-aeef-427c-902c-7fb3bd670cd4', 17, 'A Winter''s Nap', 'On a cold winter day, Bear puts on his nightcap and decides to take a nice winter''s nap. However, it would seem that others in the Big Blue House have other plans for Bear. Ojo comes to Bear in alarm --- concerned about the sudden disappearance of her duck friends from the Otter Pond. Bear makes her a cup of cocoa and tells her about migration. Treelo takes Bear outside, telling him there''s feathers falling from the sky. Bear introduces him to the delights of snow. Bear finally settles down for the nap, but is woken up by Pip and Pop. They take him outside, where all the kids have a special surprise for him. Tutter''s been trying to take a nap too, but with all the noise, he finds himself just as awake as Bear. In the Shadow segment, Shadow tries to help Bear get to sleep. She sings "Rockabye Baby."', '1997-11-12', 25, NULL, '2026-04-03T17:35:31Z', '2026-04-03T17:35:31Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('25fed94e-91ff-4636-b9a6-f168438778d3', '136b81d3-964d-4b8f-a214-92f00d96d6b9', 22, 'Rhyming for Reasons', 'Big Bird and friends explore rhyming words and their creative uses in stories, songs, and games throughout the episode.

Sponsors: A, E, 12', '1983-12-20', NULL, NULL, '2026-04-03T17:36:35Z', '2026-04-03T17:36:35Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('26097495-dcbc-4191-afe7-2c2896542ea6', '04e133fd-c4a3-4dfa-8369-c6dcfd1e3a5a', 49, 'Uncle Wally''s Snortleoutagus gag', 'Uncle Wally visits and tricks Big Bird by impersonating Snuffleupagus. The prank teaches about trust and the importance of being truthful with friends.

Sponsors: F, G, 8', '1985-01-24', NULL, NULL, '2026-04-03T17:36:36Z', '2026-04-03T17:36:36Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('260af400-5e42-4568-94b9-2ec21724f5f8', '573a556e-ed20-4222-a12d-b1b7779e1b18', 7, 'Faces in the Forest', 'Falling in love with the orangutans of Sumatra, Steve assists them in their rehabilitation process.', '1999-09-10', 44, NULL, '2026-04-03T17:39:11Z', '2026-04-03T17:39:11Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('261a11a4-6f56-4ca1-92a7-2f9838fde9f9', '871570b4-bf2f-4ba1-9940-65fb932cb009', 3, 'Party in a Sweatbox', 'Kenya tries to make amends with Sheree following fiery conflict at Cynthia''s launch party. Meanwhile, Phaedra and Kandi have differing views on their friendship; Kim Fields meets the remaining ladies; and Kenya hosts a bash to launch her hair-care line.', '2015-11-22', 43, NULL, '2026-04-03T16:34:47Z', '2026-04-03T16:34:47Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('261a43e9-5155-4b37-8e63-b2831826d3f1', '5db3ff78-e439-48e1-8f67-988ecbf85d17', 21, 'The Shipwreck', 'The Blue Falcon, after escaping, is continuing his reign of terror on the high seas. Dogtanian, still tired from his last attempt to catch the Falcon, and the 3 Musketeers are told to catch him on the Mediterranean and bring him back to France. Cardinal Richelieu is discussing the Musketeers plan with Count Rochefort, Rochefort suggests that he also takes a sea voyage to find the Falcon first.At the waterfront Juliette gives Dogtanian a gift, unseen by anyone Milady is watching, promising I will have my revenge Dogtanian, neither you nor your friends will ever see France again...', '1982-02-19', 24, '/uEnVTtVtbZFaZpew1d7UHZ9Z2id.jpg', '2026-04-03T17:18:43Z', '2026-04-03T17:18:43Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('261c6663-f6f2-4078-be4f-5d513010d26d', 'df77dba2-bbda-4f38-9713-8d5c856f852e', 5, 'Little Bear''s Trousers', 'Little Bear wakes up to find he has lost his trousers. After visiting his friends, one by one, he discovers they have all been using the trousers in very untrousery ways; as a sail for a boat, as a skiing hat, to carry bricks and as a flag. Little Bear is quite upset when he finally finds Bramwell Brown using the red trousers as an icing bag! But the cake Bramwell has made saves the day when it becomes a ‘Trousers Day’ cake and Little Bear finally gets his beloved trousers back.', '1993-10-31', 10, NULL, '2026-04-03T17:18:55Z', '2026-04-03T17:18:55Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('2621c67d-0bfb-4092-8f2d-3afca808e7a9', '2005d71d-54eb-49f8-ae9c-039eae4089b3', 7, 'Jumble Duck', 'Neil joins in a jumble sale with clutter from the boat and Duck accidentally gets sold.', '2000-02-15', 10, NULL, '2026-04-03T17:19:39Z', '2026-04-03T17:19:39Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('2623e41d-2845-4bdb-98d1-70396f517c15', 'ea1650c2-e4f1-46c7-93ba-74b5d45d08e5', 7, 'She Can Dance?', 'Sheree is determined to prove she can dance, and signs up to participate in Dancing Stars of Atlanta, a local charity event. Meanwhile, Cynthia is caught off guard when Peter surprises her with a sneaky proposal, and Phaedra packs her finest lingerie in preparation for the birth of her baby. Kandi is fed up with Kim''s disrespectful attitude towards the new song she wrote for her, while Kim’s preoccupied with her latest crush -- NFL player Kroy Biermann.', '2010-11-14', 43, '/8jiwtqb20po9rQ6JvJP47rcrjRL.jpg', '2026-04-03T16:34:45Z', '2026-04-03T16:34:45Z');
