INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('26a28db3-2936-48c6-b595-957166fdbd05', '937ee587-e2eb-46aa-9a69-3d6bab04398f', 5, 'The Runaway Duck', 'In a small boat on the Chesapeake Bay, LeVar is on the lookout for ducks who are spending the winter. During the trip, he gets a chance to see a duck up close and show how a couple turns a block of wood into a duck. Orson Bean reads The Runaway Duck, a story of a toy duck named Egbert who gets tied to a car by accident and how he then travels all over the world when the car drives off.', '1987-06-28', 30, NULL, '2026-04-03T17:36:16Z', '2026-04-03T17:36:16Z');
