INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('26ba4928-921a-4b80-a09f-8f4ca3ef636b', 'ecb64ef3-4f80-45a7-b4a9-c04434b02e35', 6, 'Can''t Buy Me Love', 'Hold hands with the Pawn Stars when the original contract between The Beatles and their manager Brian Epstein invades the shop. Considered one of the most important documents in the history of rock and roll, can they come together on a deal? Then, a Cold War-era high altitude suit blasts into the shop. Will the Soviet design leave the guys seeing red? And later, Chumlee''s been making great strides to lose weight, but can he inspire another pawn shop employee to change his ways?', '2014-01-16', 21, '/6p8mytok8PVwhU7JUNjQzMt7uHe.jpg', '2026-04-03T16:34:19Z', '2026-04-03T16:34:19Z');
