INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('26c67c5a-25c2-47e7-a35f-2a7a1a1cf5f6', '22beba7f-9b8e-4563-93da-46e76ecba427', 17, 'The Alphabet Road Show', 'Host David Letterguy and The Alphabet Road Show are coming to Sesame Street to look for unusual people saying the alphabet in unusual ways. Telly and Baby Bear know exactly how they are going to say the alphabet, but Elmo is still unsure.', '2006-09-18', NULL, '/r7ueTspg3xKBsAGNjdQMcDINw3l.jpg', '2026-04-03T17:36:44Z', '2026-04-03T17:36:44Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('26c94066-2f5f-4f0b-8e01-5656f6941ea1', 'bf874be3-7e2f-4a0e-b205-c76ac1ad69fc', 38, 'Inside Looks (on The Good Samaritan)', 'Inside look from the season 3 episode "The Good Samaritan."', NULL, 2, NULL, '2026-04-03T16:34:08Z', '2026-04-03T16:34:08Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('26cb2996-8e4d-4357-8834-3176c94e5f00', '2b968a9c-5fc0-4e93-bcf9-31d3e4c7b210', 22, 'Episode 22', 'Christmas Money Savers  Today: Home-made Christmas Cards and Gift Tags', '1975-11-20', NULL, NULL, '2026-04-03T17:21:52Z', '2026-04-03T17:21:52Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('26cb7bd6-a3ac-4796-acf8-96bb7ad96fed', '18da9943-1963-4e04-a7a0-ae63802bb1fa', 3, 'Tres Amigas', 'Kelly’s argument with Vicki continues; Tamra and Vicki fly to Mexico for a girls weekend to help break Shannon out of her shell; a night of dancing on the bars ends with a real injury and the trio opening up about their real vulnerabilities.', '2018-07-30', 44, NULL, '2026-04-03T16:35:34Z', '2026-04-03T16:35:34Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('26cbb444-d036-48cd-9435-28995635a2b2', '3087a3ed-e94e-4276-9d02-a78183dea1d3', 18, 'He''s Stalking, I''m Walking', 'After being teased by the women in Vegas about whether or not she''s pregnant, Porsha waits to take the test until she''s home in Atlanta with Kordell. NeNe travels to NYC for a whirlwind press tour to promote her sitcom, while Kandi''s stretched to the breaking point with renovations of both her business and her home. Kenya thought she had extracted Walter from her life, but the men keep inviting him around; the talk soon turns ugly and rumors begin to fly.', '2013-03-17', 43, NULL, '2026-04-03T16:34:46Z', '2026-04-03T16:34:46Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('26cf38d2-2b57-4122-ab69-9a52b00df2d3', 'bf3ffafd-7d45-4f2c-9f1b-28001bd082db', 29, 'Episode 29', 'with John Noakes, Peter Purves, Lesley Judd', '1974-12-16', NULL, NULL, '2026-04-03T17:21:52Z', '2026-04-03T17:21:52Z');
