INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('26e06015-ee2c-4f6d-80e4-d48a437ff649', '7da1b693-04d1-4168-a0a0-9715407c04c6', 21, 'Big Top Norman', 'Norman creates his own big top circus, but a trick involving some sheep goes awry when they escape into town.', '2016-07-16', 10, '/3qd0Xm76WFC6MflzcGThAyQNUFg.jpg', '2026-04-03T17:14:40Z', '2026-04-03T17:14:40Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('26e20845-ddf6-43b2-9281-fa649e655215', 'bbfee3b4-9c95-48a6-beaa-791fa08b1f43', 10, 'Episode 10', 'More than half the population of Sri Lanka follow the teachings of the Lord Buddha, which began nearly 600 years before Christ was born. The monks start their training when they are very young, as Peter discovered when he met The Rev Wimela - aged 10. Like most children Wimela has lessons and homework - but not many 10-year-olds have their heads shaved every three months -Buddha teaches that long hair leads to vanity!', '1983-10-13', NULL, NULL, '2026-04-03T17:21:56Z', '2026-04-03T17:21:56Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('26ebbda6-f623-4072-8d6b-34496159bbef', '04e133fd-c4a3-4dfa-8369-c6dcfd1e3a5a', 38, 'Ferlinghetti bugs David', 'Ferlinghetti the bug constantly pesters David with jokes and pranks that annoy but secretly amuse him. Their unusual friendship shows how different personalities can connect.

Sponsors: K, L, 6', '1985-01-09', NULL, NULL, '2026-04-03T17:36:35Z', '2026-04-03T17:36:35Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('26ebc3cc-047e-4cad-ad7b-a2652f0f30a1', '68138de2-0900-460a-b58e-480688f1e081', 7, 'Back To Nature', 'Bear gets a new Spanish-language tape in the mail, but just as he''s about to try it, he''s waylaid by Tutter, who, it seems, has a touch of laryngitis. He cant talk at all. A concerned Bear gives him a small bell to call him when he needs some-thing, and Tutter keeps bear running back and forth his Spanish lessons with Pip&Pop to a misunderstanding between Ojo and Treelo. During the course of Bear''s busy day, we discover how to communicate with words and without them.', NULL, 25, NULL, '2026-04-03T17:35:31Z', '2026-04-03T17:35:31Z');
