INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('26f031b0-fa79-426a-848b-2e77d286e44e', 'ad4e4348-3334-4a08-8928-455d9ba524c1', 22, 'Chris Langham', 'A messenger brings a message from the scheduled guest star -- Benny Brillstein, the Yiddish yodeler. Benny refuses to be on the show, so Kermit asks Chris, the messenger boy, to be the guest. Chris knows a joke, so Kermit introduces him as a comedian.', '1981-03-01', 26, '/bOad4881Hq3pCphSwyAuARe9q36.jpg', '2026-04-03T17:35:25Z', '2026-04-03T17:35:25Z');
