INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('26fe7641-6682-4464-9b23-af0089f3fa04', '98d80972-e53a-43dd-a03a-7703465e6f87', 5, 'Lord of the Ring', 'The Pawn Stars say their prayers when a guy brings in a ring believed to have been owned by a Catholic Cardinal. A symbol of status and power in the Church, does Rick see a chance for cathedral-sized profits, or lose faith in the item''s worth? Then, a woman pops in with a collection of four antique pistols from the 1800''s. Will the guys load up a giant offer, or is this deal shooting blanks? And later, Corey and Chumlee remember their own high school days when they check out John Wayne''s yearbook. Can this deal be voted most likely to succeed, or will the seller look like the class clown?', '2012-11-13', 21, NULL, '2026-04-03T16:34:18Z', '2026-04-03T16:34:18Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('270e0f6e-1337-4b24-b7cf-d7587796b19b', '42253cb1-e961-4018-8dd9-8a69e6f70873', 18, 'Episode 2243', '', NULL, NULL, NULL, '2026-04-03T17:36:37Z', '2026-04-03T17:36:37Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('271183f2-b2ae-45ae-807e-95bccac48d82', '27a5a980-ec0d-4637-b5ba-df8324a6405a', 20, 'Get Your Business Done', 'Frankie is inspired by the pastor''s sermon at the new church the family is attending. She decides to make it her mission that every family member completes their life''s destiny before they die. As Mike, Sue, Brick and Axl come up with ideas as to their destiny, Frankie has a hard time figuring out what exactly she should be doing.', '2012-04-11', 22, '/rtdcKjpujy5hwjc7svLGbx7TRhN.jpg', '2026-04-03T15:40:29Z', '2026-04-03T15:40:29Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('27170d94-2a5b-48fe-b2d7-69b04200eb2c', '42253cb1-e961-4018-8dd9-8a69e6f70873', 30, 'Episode 2255', '', NULL, NULL, NULL, '2026-04-03T17:36:37Z', '2026-04-03T17:36:37Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('271803e0-b703-483e-ac99-ec10cbfe8961', '04572e48-bbfd-476b-aebe-b6dc424f742d', 1, 'A Grain of Truth', 'Geralt sets off with Ciri on a journey that leads him to an old friend. After the Battle of Sodden, Tissaia shows no mercy in her search for information.', '2021-12-17', 64, '/lRYwDG1Mu576iRJJ3sfzmm9rJTz.jpg', '2026-04-03T15:40:45Z', '2026-04-03T15:40:45Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('27192ee9-9530-4a80-bc97-723b8d34755d', 'f593d90c-5339-42f5-9c88-5bfd48d04075', 4, 'Spring Lamb', 'A reluctant Timmy tries to avoid bath time and in trying to escape he gets a spring attached to his tail. It''s up to the flock to catch the bouncing baby sheep and return him to the tub before he destroys the farm.', '2009-10-19', NULL, '/csFo2aA8220U5MqrNHSrGar6uYk.jpg', '2026-04-03T17:39:31Z', '2026-04-03T17:39:31Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('271be3be-61e9-4920-93e2-cdf513e3a124', '740a96a0-a075-4be2-be92-a178d0939384', 2, 'Cinderella''s Slippery Slippers', 'Cinderella would rather play than open her new shoe store and be a princess; Rosita tells Cinderella she can solve both of her problems if she gets a pair of sneakers like hers from the new store.', '2017-11-25', NULL, '/sO9QuI1og0eYLhjsvKyTgBkr9k3.jpg', '2026-04-03T17:36:49Z', '2026-04-03T17:36:49Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('271ea8ec-740e-4ff9-a90d-aabdb2c6b8f3', '3e571866-318e-49df-8b7e-6119d7f3b442', 6, 'Shake It with Shaun', 'Bust some funky moves with Shaun the Sheep in his baaaa-rilliant dance routine.', '2017-09-16', NULL, '/dP9rrmtO1UA2sZUACWCoKMj94Y1.jpg', '2026-04-03T17:39:30Z', '2026-04-03T17:39:30Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('27227615-0a84-4efa-bd4e-514cab45825c', 'e4023da2-33d7-4a2b-a04a-ca449bd23935', 8, 'The College Tour', 'Mike accompanies Sue on a college tour weekend. Frankie leaves Brick with babysitters and a school project while she goes to watch Axl play in his first college football game.', '2014-12-03', 22, '/kVyS3sGDrww5yGP37czWXeRzM2z.jpg', '2026-04-03T15:40:30Z', '2026-04-03T15:40:30Z');
