INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('273c5691-793c-48f7-95cf-0e51b955fe3f', 'c01ddd2a-bdb1-4c97-8d04-58f791ef1c24', 26, 'Playtime', 'You know what they say about all work and no play.  Thus the Kratts take a break at Animal Junction, playing with lion cubs, serval kittens, ducklings and, yes, children.', '1999-06-25', 27, NULL, '2026-04-03T17:10:55Z', '2026-04-03T17:10:55Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('273d66db-1854-46c4-b8be-93bd320dfe9c', 'dbd3583f-e9b2-46d1-a37e-309eb666e233', 14, 'No Bones About It', 'Fresh off of their emotional trip to the orphanage, the ladies find themselves in a place of peace and harmony with one another. They get a taste of authentic African culture, visiting a local museum and a not-so-traditional herbalist. Later, they bond over sex talk at NeNe and Marlo''s cozy pajama party. But the good vibes are short-lived. Cynthia and Kandi make comments about Kim that bother Sheree so much that she decides to report back to Kim about this "betrayal."', '2012-02-19', 43, '/iiDbghI1HRX5fxapaza7kbs8idU.jpg', '2026-04-03T16:34:45Z', '2026-04-03T16:34:45Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('274071e7-3291-48e7-9fac-02783a797a22', '83d1c2fb-7cd9-4977-9a5d-98d36cfb59d3', 11, 'Episode 580', 'Grammy Award winner Bobby McFerrin sings ABCs with Hoots the Owl.  The Two-Headed Monster learns to blow bubbles.  Maria and Luis try to reminisce about their wedding.  Betty Lou sings the "Amigo" song.  "Sesame Street News" correspondent Kermit the Frog reports on London Fog.  Ernie and Bert leaky faucet skit.  Cookie Monster sings about subtraction.  Placido Flamingo performs a "Lost Toy Opera" with Big Bird.', '1988-12-05', NULL, NULL, '2026-04-03T17:36:37Z', '2026-04-03T17:36:37Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('2740d33e-de41-440f-a7a6-5364ebc98368', 'b054aff3-548c-4f56-b372-b1ea26613abb', 4, 'Mister Rogers Talks About FRIENDS', 'Mister Rogers arrives with a fife which he has borrowed from Joe Negri. Expressing how difficult it is to play the fife, Mister Rogers takes viewers to the kitchen where he has a row of bottles set up. Using these bottles, filled with various amounts of water, Mister Rogers is able to play Tree Tree Tree.

Joe Negri stops by to pick up his fife and invites Mister Roges to join him on a visit to Betty Aberlin''s Little Theater. At the theater, a group of musicians demonstrates the fife and plays it along with their drums.', '1982-11-18', NULL, NULL, '2026-04-03T17:35:43Z', '2026-04-03T17:35:43Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('2741d4b6-f07f-485a-8cd8-0cc7436b1d4e', '1cafb2c3-bbcb-4172-b02d-441a5aaa155f', 11, 'Little and Big: We All Have Talents - Little and Big', 'Prince Tuesday is a natural at working a yo-yo, much to King Friday''s chagrin. To everyone''s dismay, Friday disallows any yo-yos in the neighborhood.', '1998-08-03', NULL, NULL, '2026-04-03T17:35:48Z', '2026-04-03T17:35:48Z');
