INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('28340564-3314-4bb7-8c76-8495a55a9fa8', '79c64e0a-3488-41bc-9b5c-2243ff15b373', 3, 'A Match Made in Beverly Hills', 'Boz takes the group’s single status into her own hands and hosts a speed-dating party. While Dorit shows off her charm, Erika gets stage fright in front of the bachelors. Kyle opens up about finding love after her separation. Rachel encourages Sutton to embrace her old self post-annulment. Dorit gets financial advice from “Money Queen” Amanda.', '2025-12-18', NULL, '/v2mgE6aZ3NWp58tWzW4q5bZHwGj.jpg', '2026-04-03T16:34:59Z', '2026-04-03T16:34:59Z');
