INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('283c73ba-a578-468f-ba2c-04d72b58f2b3', 'b6baa6ec-0908-4a47-9001-7e7158985002', 6, 'Wet All Over', 'Arnold and Wanda are due to give a report on the town waterworks. But Ms. Frizzle thinks it''s field DRIP time! She turns the bus and class into water drops and the kids evaporate, condense, become rain and rush by river into the ocean. After several trips through the water cycle, they''re ready to turn back into regular kids. But the magic key that will get them out of the cycle is locked in the school bathroom! Trying to work their watery way into the bathroom, the kids go through the town waterworks and see how water is purified. Can they get to school through bathroom pipes? Or are they stuck in the water cycle forever?', '1995-10-14', 25, '/zW5qKlnyk0ifaXcdAkBXCBFweZm.jpg', '2026-04-03T17:37:48Z', '2026-04-03T17:37:48Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('2846a17c-ddfc-4474-aa5c-d284555eb250', 'b5ab3a72-bc79-4e9b-a531-96739afd7aea', 13, 'Uncle Feedle', 'Emily brings in a piece of cloth, which Charlie Mouse identifies as a house for a rag doll, leading to a several rag jokes from the mice! They fold up the cloth so that Bagpuss can use it as a thinking cap, and create the story of Uncle Feedle, which Gabriel and Madeleine sing along to.', '1974-05-07', 15, NULL, '2026-04-03T17:23:58Z', '2026-04-03T17:23:58Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('284fa255-52b0-4f6a-85ec-0554e5e9bd71', '5a4e38a1-8e54-4974-8097-d7a7b48630a2', 32, 'Episode 32', 'with Valerie Singleton, John Noakes, Peter Purves', '1971-01-08', NULL, NULL, '2026-04-03T17:21:50Z', '2026-04-03T17:21:50Z');
