INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('2857dde0-6aeb-4a8d-bd13-f874a3f10c52', 'f1325b56-44e0-4b6e-89bc-82cac30afea6', 7, 'The Great Guinea Pig Rescue', 'Sarah and James have got a pet guinea pig and name him Norris, Station Officer Steele''s real name, but then the guinea pig''s taste for cables soon leads to a fire.', '2012-04-16', 10, '/m1qDmO3sHdCHSbt7f4jLOTrzofA.jpg', '2026-04-03T17:14:39Z', '2026-04-03T17:14:39Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('2859e467-33ca-42e8-978d-2585a447edc9', 'c7ffc8df-4671-47e3-a11b-606828bcb508', 10, 'Salud', 'Walt''s family worries when he doesn''t turn up for Walter, Jr.''s 16th birthday. Jesse is forced to put his lab skills to the test without Mr. White''s help.', '2011-09-18', 48, '/dBrs0Npmn76g81yel2mjK7mTaOj.jpg', '2026-04-03T15:40:34Z', '2026-04-03T15:40:34Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('285e835c-7b15-4984-901a-6db2611ef142', 'da06465b-9154-4feb-a455-374df7dab02f', 12, 'Telly Learns The Grouchketeer Cheer (4094)', 'The Big Bad Wolf feels so exhausted from having to chase pigs and dress up like a Grandma all the time that he decides to take a vacation.  In the meantime, Zoe, Elmo, and Telly audition to be the temporary wolf.  The three of them first have to blow down a straw house, then chase pigs, and lastly, pretend to be Grandma.  All three of them creatively think of different strategies to pass the test.  They all then begin arguing over who could best play the role of the Big Bad Wolf.  Gordon talks to them and helps them to realize that it’s more important to stay friends than to be the wolf.  When it’s time for the Big Bad Wolf to decide, he gives the role to Gordon since he did such a great job showing Telly, Zoe, and Elmo how to do everything that a Big Bad Wolf should do!', '2005-04-19', NULL, NULL, '2026-04-03T17:36:44Z', '2026-04-03T17:36:44Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('2861f08e-f8f8-407f-a7c7-a57fdb095282', 'bcab920a-51a5-4cbb-aa59-41578a0eb005', 12, 'Feeding a Need', 'After a tear-filled Mexico trip, Lisa Rinna confronts Eden over the “near death” accusations. Lisa Vanderpump buys her son Max a condo, and the scripted show inspired by Kyle''s childhood becomes even more of a reality. Lisa Rinna is honored with an award from her favorite charity, but Dorit has increasing suspicions about what she sees as erratic behavior from Rinna.', '2017-02-21', 43, '/8eGwyHk4RgcUqCSCqWvw9nChjbz.jpg', '2026-04-03T16:34:56Z', '2026-04-03T16:34:56Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('28655221-f87f-4eac-a31b-142a60f0906e', 'd1863f2f-02ec-40ce-af64-db03fbe518a7', 13, 'The Princess Story', 'Rosita helps Abby and Zoe think outside the ''fairy tale'' box as they imagine and make up a story together. Also featuring Cookie Monster''s Star Smores parody, and Elmo the Musical-prince. Brought to you by the letter P and the number 4.', '2016-04-02', NULL, '/qrFJ9lUOnZzMiEWnaTTdXpHpdzU.jpg', '2026-04-03T17:36:48Z', '2026-04-03T17:36:48Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('286f5344-80fd-45eb-9281-2593c9ce1b4c', 'f13cb622-84e3-4654-a8f1-0ceab09a9ca6', 21, 'Franklin''s Canoe Trip', 'Mr. Turtle misses the call of the loons from camping in the wilderness, so he takes Franklin and Bear on a camping trip, encouraging them to be "voyageurs." Although enthusiastic about the trip, they begin to think for a while that it''s less fun than they thought it would be.', '2002-07-08', 12, NULL, '2026-04-03T17:40:16Z', '2026-04-03T17:40:16Z');
