INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('28a0fd6f-b5e4-487d-a646-7d17893f6471', '208e80de-61e3-4a2f-857f-c667ffc29134', 5, 'Shields & Yarnell', 'Inspired by mimes Shields & Yarnell, Fozzie Bear works on a mime act, including "Bear walking against the wind". Kermit suggests that Fozzie find a more original act, so Fozzie tries out "Bear feeding spaghetti to an elephant" and "Bear going to a drive-in movie with a porcupine".', '1979-11-23', 26, '/jOPKEtMzwic1qRQqBDtV9m9p0Ne.jpg', '2026-04-03T17:35:25Z', '2026-04-03T17:35:25Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('28a2c41f-3b77-41bb-91e0-3301f7d6b6c7', '319bd5d6-ff58-426f-b9da-a0bb2cb87b02', 12, 'Caves', 'Caves come in all different shapes and sizes depending on how they were formed. Spelunkers (people who explore caves) have plenty of descriptive names for caves and the natural rocky features that form within them – soda straws, fried eggs, popcorn and draperies are just a few. Caves can be as simple as one straight passage with a few stalactites overhead, or as complex as a labyrinth, with many stalagmite-carpeted rooms.', '1998-04-25', 26, '/wbKGPtG5ADg50dkR2FbTXQHInBv.jpg', '2026-04-03T17:37:22Z', '2026-04-03T17:37:22Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('28a72717-1f08-4048-b9e1-c31c6836565e', 'a7421c26-c9a2-437a-be12-2cabed2b5a96', 4, 'Katie''s New Life / Snow Art / Tag Wrestling', '', '2001-09-26', NULL, NULL, '2026-04-03T17:11:22Z', '2026-04-03T17:11:22Z');
