INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('28bbbfbc-f67c-49f8-9782-5e0b36c970af', '7bc54df3-f32a-454e-aef6-a9436c35d53b', 32, 'Episode 32', 'Rogers plays rhyming games and flash cards with Bob Trow. Lady Elaine and several others participate in the boomerang contest.', '1970-03-17', NULL, NULL, '2026-04-03T17:35:39Z', '2026-04-03T17:35:39Z');
