INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('28c78953-7c14-446e-8e65-61ba30c57dba', '4b2a19e0-2fae-492e-bc31-f78e63d88ebc', 27, 'Pawn Patent', 'Space out with Pawn Stars when an autograph of astronomer Edwin Hubble takes a starring role. Will Rick hitch his wagon to this star or keep his feet on the ground? Next, an 1850s patent model self-lighting and extinguishing lantern flashes into the shop. Will Rick light up an offer or will the deal go dark? Then, a Starrett Food Chopper slices in. Will Corey dice up an offer or will he get cut? And later, an 1871 British Martini-Henry Short Lever Rifle bores into the shop. Will Rick shoot off a deal or will he misfire?', '2017-01-30', 21, '/pZO0OtQ9u5P4JiYJXBR136LCq7E.jpg', '2026-04-03T16:34:20Z', '2026-04-03T16:34:20Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('28ca2801-050d-474d-8062-c89de2c2c31c', 'b7538712-04ce-43a6-9163-62280bbb084b', 43, 'Baby Bear''s grandmother visits Sesame Street (3893)', '', '2000-03-01', NULL, NULL, '2026-04-03T17:36:42Z', '2026-04-03T17:36:42Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('28cb3895-c19e-4f7e-b8a7-cb0c991d8248', '3fdccc2c-e563-42fb-8874-c93879cd4141', 6, 'Babysitter Bitzer', 'The flock are off for a girls'' night, leaving Bitzer to babysit Timmy. It''s not long before the youngster makes clear who''s in charge.', '2016-09-12', NULL, '/hODOkS0ZggnKaPQ86NAlZJEhPKM.jpg', '2026-04-03T17:39:32Z', '2026-04-03T17:39:32Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('28d5d8e8-7562-4685-aabd-878fad53853f', '42e591e2-2a88-4434-ae9f-3d4b1d685613', 17, 'The Chum-Sake', 'Print money with the Pawn Stars as the guys check out an entire sheet of test notes. Made when the U.S. Mint was testing a new printing press, will they see dollar signs, or is this funny money too hot to touch? Then, Corey and Chumlee have to duck and cover when some poleaxes swing into the shop. Used in Medieval times to dismount horse-riding soldiers, can they land a deal? And later, the guys try to give Chumlee a new nickname, but can they make it stick?', '2013-08-08', 21, NULL, '2026-04-03T16:34:18Z', '2026-04-03T16:34:18Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('28d82bde-2f2c-4841-b77b-57bdba39c4f4', '95ca8b6f-ccbc-431a-9d95-9b23367bbfed', 17, 'A Tale of Two Accidents', 'At Kathy''s spa day, Erika reveals a shocking story about her family, leaving the group with questions. Meanwhile, Crystal works on her big-ticket basement renovation and Garcelle moves one step closer to finding Mr. Right. Dorit’s wedding dress launch is anything but happily ever after, as Sutton and Erika come face-to-face and Garcelle has to answer for a provocative comment.', '2021-09-15', 43, '/ukZSY4VumoGKNq5DCkt6qk04n75.jpg', '2026-04-03T16:34:58Z', '2026-04-03T16:34:58Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('28d9366a-905e-47ae-856e-e885be63d881', 'bf874be3-7e2f-4a0e-b205-c76ac1ad69fc', 53, 'Inside Looks (on The Pick)', 'Inside look from the season 4 episode "The Pick."', NULL, 3, NULL, '2026-04-03T16:34:09Z', '2026-04-03T16:34:09Z');
