INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('28f1deec-ee95-4be1-a5e1-395c89d4d2ad', '332249fa-796b-4f92-b7f8-421d523b0bdc', 13, 'A Rum Punch to the Gut', 'Sanya attempts to redeem herself from Sheree’s birthday party backlash with a fun couples trip to Jamaica. Just as she and Kenya forge a new bond, however, Marlo and Kandi’s friendship appears to pass the point of no return.', '2022-08-07', NULL, '/vJfuPjacpIjUIWr7Y4D31PTv8eu.jpg', '2026-04-03T16:34:49Z', '2026-04-03T16:34:49Z');
