INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('29d66458-dbc2-4586-9ce4-fa167124ec64', '65524b14-e29e-4b04-81d3-fbebe525e9ec', 5, 'Franklin''s Badge', 'Franklin joins the Woodland Trailblazer troop, a sort of combination Boy / Girl Scouts, and tries to earn some merit badges. He finds that there is much more to it than simply earning badges.', '2004-06-06', 12, NULL, '2026-04-03T17:40:16Z', '2026-04-03T17:40:16Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('29ddeb39-038e-4a08-b9fa-b9d143a97219', 'abfe14ee-db42-4dde-a96a-601ff3c53ecc', 13, 'The Final Conflict', 'Cluny seizes the family of a dormouse and threatens to kill them unless their father, Plumpen, betrays Redwall and opens the gate to the now huge army of rats. The plan works and Redwall is finally captured. But Matthias challenges Cluny and in a final confrontation, he kills him. Cornflower and Matthias are at last married and Redwall returns to its idyllic lifestyle. Matthias has become like a hero he admired in his childhood.', '1999-10-08', NULL, '/u6gcFpAm05qMxByS5XYx4WCfKdg.jpg', '2026-04-03T17:12:08Z', '2026-04-03T17:12:08Z');
