INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('2a2e7b17-3285-4509-8e06-61a9367ac097', '3ee646e8-23ae-4dec-bbc6-c7e6a210d55b', 108, 'Telly and Oscar write', 'Oscar is weary of hearing the "Sesame Street Theme" every day and wishes they''d come up with something better. Telly happens to have a composition ready and sings a song all about saying "Hi." Oscar reads Telly a book he''s written to combat all the nice stories they always hear.

Sponsors: C, W, 11', '1991-04-10', NULL, NULL, '2026-04-03T17:36:38Z', '2026-04-03T17:36:38Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('2a2f95df-4cc9-4897-ba55-667a1395683d', '5c1b881f-ac58-4d72-b63f-209952d4f902', 2, 'Episode 2', 'Fit for a Queen  A teddy made of chrysanthemums, a koala bear with a plum for a nose and an owl sitting under a banana moon were just three of the hundreds of stunning floral displays admired by Her Majesty The Queen when she made her first-ever visit to Westminster Cathedral for the International Year of the Child Flower Festival. Blue Peter film cameras were there to record this historic event and so were nine Blue Peter viewers aged from five to 16 -winners of the Flower Picture competition.

For Cristian, Kate, Una, James, Christine, Rebecca, Lesley, Jenny and Sarah, who were all presented to Her Majesty, this particular Friday the 13th was one they''ll remember for the rest of their lives!', '1979-09-13', NULL, NULL, '2026-04-03T17:21:54Z', '2026-04-03T17:21:54Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('2a301ac8-f069-4b71-a74e-437db226b4d9', '4d2cac0f-38fd-438b-8afa-acf43952e535', 158, 'Episode 158', 'A magazine programme for younger viewers. Introduced by Christopher Trace. Including Blue Peter Alphabet: E for Engineering. The Fly Who Wanted a Tail, a traditional Russian folk-story told by Elena Snow. How to Build Your Own Model Theatre.', '1961-11-06', NULL, NULL, '2026-04-03T17:21:47Z', '2026-04-03T17:21:47Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('2a3d6c0c-37ce-486d-a33f-8ea6c3375135', '136b81d3-964d-4b8f-a214-92f00d96d6b9', 68, 'Episode 1903', 'Telly frantically tries to retrieve a kite stuck in a tree, eventually learning from Luis how to solve the problem with a ladder. Oscar reveals he spent the morning deliberately getting the kite stuck, causing mischief as usual. The group learns about teamwork while preparing soup, and Big Bird helps Telly count place settings for his monster birthday party using a clever trick.

Sponsors: J, P, 2', '1984-02-22', NULL, NULL, '2026-04-03T17:36:35Z', '2026-04-03T17:36:35Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('2a3f4df6-7383-4dda-b191-7e5ba32af726', 'bb919aec-0d5c-4c58-9a5a-fa2a0a5de2b6', 41, 'Episode 446', '', '1973-01-22', NULL, NULL, '2026-04-03T17:36:29Z', '2026-04-03T17:36:29Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('2a4390fc-8639-4f68-97c6-861589d14b65', '18da9943-1963-4e04-a7a0-ae63802bb1fa', 8, 'Seeing Red', 'Vicki’s golf party concludes as Tamra hounds Steve to propose to Vicki; with cracks continuing to appear in Tamra and Shannon’s friendship, the ladies finally sit down for an emotional heart-to-heart; Gina makes a confession about her marriage; Tamra throws Eddie a 45th birthday party; and at the party, Kelly’s plan to confront Steve goes awry and she ends up arguing with Emily’s husband, Shane.', '2018-09-10', 44, NULL, '2026-04-03T16:35:34Z', '2026-04-03T16:35:34Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('2a44def9-41d4-4079-a8d6-2af532f51ca5', 'f13cb622-84e3-4654-a8f1-0ceab09a9ca6', 19, 'Franklin''s Spring First', 'Everyone in Woodland has been looking forward to spring, but a late snowfall make it seem like it''s taking forever. Franklin decides to celebrate the first day of spring by creating a holiday based around it, with special traditions such as having waffles for breakfast. On the day of the big celebration, melting snow and heavy rains cause an unfortunate flood, but Franklin and his family still find reason to celebrate after receiving help from a certain animal familiy who''s well-equipped to deal with the problem.', '2002-07-01', 12, NULL, '2026-04-03T17:40:16Z', '2026-04-03T17:40:16Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('2a4aa3fb-cd12-41c4-b595-df9c219ba244', '225b0f03-984b-47f3-a1a3-d3e92175e39d', 34, 'Episode 34', 'with Christopher Trace, Valerie Singleton and John Noakes.', '1967-01-23', NULL, NULL, '2026-04-03T17:21:48Z', '2026-04-03T17:21:48Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('2a4ada94-82fd-4c0c-a431-549c6625a842', '7b8e3988-fbf3-4cfc-aeb2-782ae5a64e2d', 19, 'Twins Day on Sesame Street', 'Twins are celebrated with their own special day. Chris introduces his twin sister Christy; Abby and Zoe decide they want to be each other''s twin.', '2010-12-10', NULL, '/wtQx9nUI3Nqpy85MZGL5fn4Vp6H.jpg', '2026-04-03T17:36:46Z', '2026-04-03T17:36:46Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('2a4bf24d-2660-4a5e-bfa0-d312c68fbe40', '79916e0e-881c-43a7-b4ee-00e5052a94be', 3, 'Hank and the Hug', 'No one wants to play with Hank or even let him help. He at first feels very angry but a little later he feels very depressed. The other tugs soon join together to formulate a plan on how to apologize to Hank and make him feel better.', NULL, NULL, NULL, '2026-04-03T17:10:11Z', '2026-04-03T17:10:11Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('2a4f2586-34d7-4869-a4c1-01620800fb3b', '3087a3ed-e94e-4276-9d02-a78183dea1d3', 24, 'Secrets Revealed', 'Following the three-part reunion, Bravo gives viewers an inside peek at never-before-seen footage.', '2013-04-28', 43, NULL, '2026-04-03T16:34:46Z', '2026-04-03T16:34:46Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('2a5262e1-6a7a-40b5-9385-1505ae0352a8', 'b590e3d8-e4a6-4360-ba5d-3e2248899d2a', 8, 'Imaginary Friends', '', '1991-12-20', NULL, NULL, '2026-04-03T17:35:46Z', '2026-04-03T17:35:46Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('2a5557bd-4e26-434e-94a1-c5274e5d0ade', '23c93536-610c-41c5-ac6b-a6b243423258', 5, 'Blast from Everyone''s Past', 'Mia reveals what she allegedly overheard on the phone with Karen years ago, leaving the table speechless. The ladies ring in Wendy''s 40th birthday. Gizelle heads back to Maryland to attend Angel and Adore''s cap-and-gown ceremony. Chaos erupts over breakfast when Mia and Ashley''s friendship takes an unusual turn.', '2024-11-03', 43, NULL, '2026-04-03T16:35:41Z', '2026-04-03T16:35:41Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('2a57843e-4aae-499a-bfe5-77bc70015c7b', 'e48599f8-66ff-4c0f-9274-65b9ae1cda9e', 56, 'Episode 56', 'Lebanon postcards with deltiologist Ronnie Barker.', '1977-03-28', NULL, NULL, '2026-04-03T17:21:53Z', '2026-04-03T17:21:53Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('2a584679-1442-42a4-bf70-e2b4c6111b48', '8b07363e-5f54-45d6-b036-b43793f7af74', 13, 'Buster''s Amish Mismatch', 'During a field trip to Amish country, Buster becomes enamoured with the simple lifestyle and vows to forgo all modern conveniences back home.', '2002-11-26', 13, NULL, '2026-04-03T17:37:57Z', '2026-04-03T17:37:57Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('2a5ae49b-9965-4599-aeb8-d23881236600', '301fb913-4e76-408f-b84b-05bf979766fe', 11, 'The Rye', 'George''s parents meet Susan''s; Elaine fears her enthusiasm may have scared off the musician she''s dating; Kramer drives a hansom cab, but feeds his steed bad fuel.', '1996-01-04', 22, '/bRiPyJgvg6c9XBQjkF3ig7CkH4B.jpg', '2026-04-03T16:34:11Z', '2026-04-03T16:34:11Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('2a5e00e6-b643-441a-8e6c-0d202958e9c2', '05c0e384-194c-4417-9f62-803eb615e409', 65, 'Rebuilding the factory', 'Title number 0065. Opens with Mister Rogers arriving with a bag of wood logs. Lady Aberlin, Handyman Negri, and X rebuild all of Corny''s factory. Everyone donates something to help, including King Friday.', '1968-05-17', 29, NULL, '2026-04-03T17:35:38Z', '2026-04-03T17:35:38Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('2a5e278d-08ca-4ec2-b5b8-18d86434912e', '4060ad7f-4b8f-4393-8eb1-66a150b928b6', 3, 'Measuring Big Bird', 'Nina is using a smiley face growth chart to measure how tall Elmo and Rosita are. Big Bird wants to see how tall he is too, but Nina is all out of smiley faces. What else can they use to measure their tall friend? After trying a few ideas, inspiration strikes. What if they make their own smiley faces? It works! Because they didn’t give up, all the friends—including Big Bird—could be measured.', '2020-11-26', 26, '/jIQmc6559PDqKSrhbfY09KWebhg.jpg', '2026-04-03T17:36:50Z', '2026-04-03T17:36:50Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('2a664f32-7a98-4c8d-86c6-d4218d72a732', 'c67a8787-4971-4961-b536-1ff01924e2a9', 15, 'Francine''s Pilfered Paper', 'When Mr. Ratburn assigns everyone in his class an individual topic about Thanksgiving to write a five-page report on, Francine feels that she''s "doomed." She has no idea how she''s going to come up with five pages on the Pilgrims'' eating habits, until Brain shows her how to use a search engine to find information about the subject on the Internet. She copies the contents of an entire article and hands it in as her report, looking forward to a relaxing holiday. She then learns from her sister that what she''s done is plagiarism and could get her suspended from school.', '2007-09-05', 13, NULL, '2026-04-03T17:37:59Z', '2026-04-03T17:37:59Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('2a69c3ba-e3a8-4c8a-897f-4ae94ddd83dc', '87989283-6fea-40d7-8d91-22c4947db105', 5, 'A Not So Merry Christmas', 'It''s Christmas and the family is divided over Kody''s idea to live in one house. There''s a big surprise when a pregnancy is revealed. Then the family confronts the fact that their houses in Vegas aren''t selling. Their finances are at a breaking point.', '2020-01-26', NULL, NULL, '2026-04-03T16:34:31Z', '2026-04-03T16:34:31Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('2a7462da-a375-4014-b793-4ad9a2a1bbb1', '4d2cac0f-38fd-438b-8afa-acf43952e535', 5, 'Episode 5', 'Toys, model railways, games, stories, cartoons. A weekly programme for younger viewers with Christopher Trace and Leila Williams.', '1958-11-13', 15, NULL, '2026-04-03T17:21:47Z', '2026-04-03T17:21:47Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('2a7609ff-ded6-4707-93eb-12deec5b9f22', '3ea743ef-0a22-47cf-b1d2-62f37e939253', 3, 'Three Monster Girls Who Love to Sing', '', '2002-02-06', NULL, NULL, '2026-04-03T17:36:43Z', '2026-04-03T17:36:43Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('2a7706ea-8bc8-4152-a584-30fad04015a6', '842c6419-ab98-4d34-8845-1d9782291aad', 12, 'Moderation', 'When Annie’s obsession with baseball playing results in a drop in her grades, Plato relates two tales that demonstrate the value of moderation in all things.', '1998-05-03', 30, NULL, '2026-04-03T17:38:34Z', '2026-04-03T17:38:34Z');
