INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('2a818a0c-e0a9-4b2c-b094-531e41561b49', '18da9943-1963-4e04-a7a0-ae63802bb1fa', 1, 'The Next Chapter', 'In the Season 13 premiere, after the surprising reconciliation between Vicki, Tamra and Shannon at last season’s reunion, the ladies are working to rebuild their friendship and regain each other’s trust. Tamra has moved into a new home, and as part of their divorces, both Shannon and Kelly have downsized, while also adjusting to life as single mothers. Vicki, who has marriage on the brain, is now cohabitating with her boyfriend Steve, though he is in no rush to pop the question.', '2018-07-16', 44, NULL, '2026-04-03T16:35:34Z', '2026-04-03T16:35:34Z');
