INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('2a95d3d4-5656-4812-a429-64b673c44e49', 'a84aa42d-e738-4081-8da9-1faec0209ee9', 4, 'The Trip', 'Frankie urges Sue to fight for her right to attend a class trip after making the grade by selling thousands of dollars worth of sausage and cheese; Brick gets his first girlfriend.', '2009-10-21', 22, '/2F0fJ0dBMDzqzhxCR2VP1XBrN6p.jpg', '2026-04-03T15:40:28Z', '2026-04-03T15:40:28Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('2a98491d-48f4-4589-9deb-5bdb8e386800', '06030129-ff2d-4490-b66c-9f41bbe7aabd', 13, 'Bread', 'John sets out to a wheat field to find out how bread is made. He then sees a windmill, and is shown how wheat is turned into bread. Rosie and Jim get up to their old tricks and fool around with John when he isn''t looking.', '1990-11-26', 15, NULL, '2026-04-03T17:19:36Z', '2026-04-03T17:19:36Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('2a98bf2c-b8af-4b20-bd01-0be1c3e7c484', '98d80972-e53a-43dd-a03a-7703465e6f87', 8, 'The Last Samurai', 'In an attempt to prove he should get an ownership stake in the Gold & Silver, Corey buys a sword without getting a second opinion. Rick and the Old Man think he got ripped off, but Corey''s convinced he got a deal. They call in a local expert to determine who''s right. And a one of a kind item from the beaches of D-Day creates a lot of noise in the shop.', '2012-11-19', 21, NULL, '2026-04-03T16:34:18Z', '2026-04-03T16:34:18Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('2aa91100-2f7f-4844-a344-0d4c797a7e23', '5c1b881f-ac58-4d72-b63f-209952d4f902', 41, 'Episode 41', 'Join Simon on a trip back in time on the Severn Valley Railway and discover how you can win a ride on the footplate of a famous old loco.', '1980-01-31', NULL, NULL, '2026-04-03T17:21:54Z', '2026-04-03T17:21:54Z');
