INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('2afbd0d4-b84b-4bf5-b19a-1137a29c0c30', '9d74600d-7222-47c1-bd1b-635f5b41b7d1', 1, 'Animal Cafe', 'LeVar goes to a 24-hour diner to look into night jobs, and profiles people who have occupations in the evening and early morning hours, like radio DJ''s, bakers, cab drivers, and police officers. In a separate story, a man ventures into a cave to see bats and other nocturnal animals. Martin Short narrates the story of "Animal Cafe," about a cat and dog who operate a third shift restaurant for all the animals in their neighborhood while keeping it a secret from their human owner.', '1986-06-23', 30, NULL, '2026-04-03T17:36:15Z', '2026-04-03T17:36:15Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('2afbd6f3-70a6-4096-8638-4de0b8f1ab55', 'f07b8794-5625-4682-aae1-e56966b4c7a8', 11, 'Hello, Maggie', 'Kiki’s cousin Maggie visits from Mexico. Even though she only speaks Spanish, the other kids learn that friendship and communication can develop through gestures and a few simple words. Nuzzle gets trapped in a dollhouse. Leon and Jody do not appear in this episode.', '1996-01-29', 29, NULL, '2026-04-03T17:12:21Z', '2026-04-03T17:12:21Z');
