INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('2b5199a9-ae5f-4e5d-ab09-a886c171b038', '02849655-bd95-4d8d-af3b-03321918eeee', 23, 'Madeline and the Tea Party', 'The girls are planning a spring tea in honor of Lord Cucuface and the trustees when Sugar Dimples, the child movie star, drops in to visit and takes over, turning their simple party into a major "Hollywood" production, with over-the-top results. It is up to Madeline to bring the party down to earth and remind Sugar Dimples that it is the company that counts, not the lavishness.', '2001-02-07', 30, NULL, '2026-04-03T16:34:02Z', '2026-04-03T16:34:02Z');
