INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('2b59c217-e159-4794-8a8b-b8b41920b085', 'f30bbf81-8770-4e74-b68b-280e7c85b52f', 6, 'The Statue', 'Jerry has a box of stuff his grandfather left him. Inside is an interesting looking statue that could replace one George''s parents had years ago, but he broke. George plans to pick the statue up later but in the meantime he tells his parents about the replacement statue. Meanwhile the boyfriend of a bitter Finnish author (whose latest work Elaine is going to edit) is going to clean Jerry''s apartment. When Jerry returns to his apartment it is cleaned beyond reason. Later when Jerry and Elaine are at the author''s apartment, they see the statue on her mantelpiece. Getting it back may jeopardize Elaine''s chance at being an editor, but save George from his parent''s wrath.', '1991-04-11', 23, '/y9bT1IQX4DUfizADWxGVvl39z4h.jpg', '2026-04-03T16:34:09Z', '2026-04-03T16:34:09Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('2b5a91ba-2383-4075-bdb4-e14d400e9bda', 'f12380a9-93e5-47bb-9e2f-cf1eed11eee4', 10, 'Extending an Olive Branch', 'Janelle celebrates the sale of Coyote Pass by partying with friends in New Orleans. Meri ventures out of her comfort zone and attends a dating event in Las Vegas. Kody owns up to his bad behavior and decides to apologize to each of his ex-wives.', '2025-11-30', NULL, '/bUCSjZNrZeBwYUtwBJGwpIQtJch.jpg', '2026-04-03T16:34:33Z', '2026-04-03T16:34:33Z');
