INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('2becc86d-41f3-4e28-a249-32af655a6c67', 'ecdefd77-a7ac-4344-bea1-fb1df2fd0ac9', 4, 'Every Time', 'Bernard uses his watch to help people with their injuries. But when his teacher Mrs. Spindell sees him with his watch, she tells him not to bring it to school because it is valuable, but when he brings it anyway, she sends him to the headteacher.', '2001-11-29', 15, NULL, '2026-04-03T17:20:05Z', '2026-04-03T17:20:05Z');
