INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('2c8abf9a-a696-4f31-b87c-acd908bef755', 'd0e5568d-939d-4d89-ab4e-c291a90691cf', 9, 'The Robot', 'Kipper is waiting for Pig and Arnold at the duck pond when a small friendly robot clanks out of the water. At Kipper''s house it tries a piece of bread, a milk shake and some chocolate cookies but when Kipper introduces Hippo, to his horror, the robot eats him too! Happily Kipper and Hippo are reunited at the duck pond.', '2000-11-23', 30, NULL, '2026-04-03T17:10:49Z', '2026-04-03T17:10:49Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('2c8d0c87-1590-46ac-bff4-1665289b3b24', '0fa92002-82ae-4609-85e3-3982baa99ae1', 15, 'Postman Pat the Secret Superhero', 'Charlie and Bill are eager to see a superhero in Greendale but can''t find one. Then, the post falls out of his van and Pat goes to extraordinary lengths to retrieve it!', '2005-03-16', 15, '/930CcAKVeBHSO7CcC4udOU1c87n.jpg', '2026-04-03T17:14:30Z', '2026-04-03T17:14:30Z');
