INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('2c97442a-57cd-4e2e-9716-a7b685298a5a', '6f81c872-cdb9-42dd-8377-2c17cb6ed4d7', 11, 'Baby Bear Learns About Bees (repeat)', 'Baby Bear is scared of bees until Abby shows him and Chris just how amazing the insects really are.', '2017-03-18', NULL, '/xnx6GVEeqbtBJhOysHLp7ZO34Cz.jpg', '2026-04-03T17:36:48Z', '2026-04-03T17:36:48Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('2c97c255-913a-4a6e-a64b-179e2e8bf5f6', '119c16d5-1047-45ec-8242-c72a8eed423b', 17, 'Arthur Babysits', 'Arthur has plenty of gripes about his past babysitters, but soon finds himself trying his hand at some babysitting of his own. He ends up having the Tibble Twins'' Grandma ask him to babysit the infamous Tibble Twins and he agrees to the job. Despite the warnings from both his friends and D.W., he takes on the task and quickly finds himself overwhelmed. After some quick thinking, and a willingness to keep at things, he comes up with a plan.', '1996-10-17', 13, '/jbsz1PEQP1w4jt5HXoq7uYik7ty.jpg', '2026-04-03T17:37:55Z', '2026-04-03T17:37:55Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('2c9b00a2-b190-4c84-b3b8-41a628c6426f', 'abeb8d07-5c86-4f6a-a110-b11cba2a4138', 6, 'The Avatar and the Firelord', 'The tale of Avatar Roku and Fire Lord Sozin is revealed to Aang and Zuko by different sources.  Both learn about themselves and are shown the origins of the war.', '2007-10-26', 24, '/sFZ1uE6Kl50PRt2yGaGdKTay4gA.jpg', '2026-04-03T17:40:48Z', '2026-04-03T17:40:48Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('2c9bd782-3dec-44fc-b6f1-6ef0f39eab69', '06030129-ff2d-4490-b66c-9f41bbe7aabd', 18, 'Sailing', 'John travels to Tewkesbury Marina to see some sailing boats and get some ideas for a story about Rosie and Jim', '1991-01-14', 15, NULL, '2026-04-03T17:19:36Z', '2026-04-03T17:19:36Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('2c9dbd8a-87e4-4851-a5ae-8315819f4562', 'c7994637-b7c7-42c7-aaee-1bff4144fe23', 13, 'Tapas and Tattletales', 'Adios Beverly Hills, hola España! Sutton takes the ladies on a fabulous getaway to Barcelona where Garcelle fears supernatural houseguests. Kyle''s bold fashion choices leave Dorit questioning this new Kyle. Annemarie puts Crystal in the hot seat for talking behind the group''s back.', '2024-01-24', 44, '/ct6UsE0iCz0NMgrf3gjkRodKzNt.jpg', '2026-04-03T16:34:59Z', '2026-04-03T16:34:59Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('2ca32cd7-f49a-404e-99f4-9702c6e72ea3', '52135215-5160-4d42-9d0f-db242b1abcaa', 4, 'The Sign Painter''s Dream', 'LeVar is back in New York (as he always seems to be), this time on Broadway. It''s a sign mecca, and part of this program shows the making of a huge advertisement. Jamie Farr tells the story about a cranky sign painter who has a revelation about his job when he''s asked to commission a sign for free as a good gesture.', '1995-10-05', 30, NULL, '2026-04-03T17:36:19Z', '2026-04-03T17:36:19Z');
