INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('2ccc7cb7-4f66-4cba-909b-53599025e5eb', 'bbfee3b4-9c95-48a6-beaa-791fa08b1f43', 71, 'Episode 71', 'Lee Boo , the Stranger in Rotherhithe The extraordinary story of the 19-year-old prince who left his Pacific Ocean island in 1784 to go to school in London. For five months he was a familiar figure in Rotherhithe until he died of smallpox.', '1984-05-24', NULL, NULL, '2026-04-03T17:21:56Z', '2026-04-03T17:21:56Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('2ccf0be5-9189-4858-b6fc-437825adfce1', '78a02d50-e3dc-4549-844a-3cf357a32ef4', 18, 'Baby Nups and Breakups', 'The ladies are back home and ready to get down to business. Cynthia shows the Atlanta fashionistas that she''s more than a pretty face, even as Shereé tries to interfere. Kandi starts planning an OLG Restaurant preview, while Phaedra helps Kandi''s former employee seek financial resolution. Porsha decides she''s ready to take her relationship with Todd to the next level. Matt resurfaces, forcing Kenya to make a decision about their future.', '2017-03-26', 43, '/9F3aFIcOVcWRbnU2CNLjbjcueLy.jpg', '2026-04-03T16:34:48Z', '2026-04-03T16:34:48Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('2ccfee30-93f1-42b1-aaa7-bfffdccac69f', '0bbd380c-5cb8-46a6-8838-b5d60223c073', 8, 'Peter Ustinov', 'Kermit becomes jealous when Miss Piggy, Fozzie, Hilda and Scooter rave about Peter Ustinov. At the end, Peter admits that he''s jealous of Kermit; he''s always wanted to be a frog.', '1976-10-24', 26, '/dTGGgUpppH1zC1SOPKGUx4LEM92.jpg', '2026-04-03T17:35:24Z', '2026-04-03T17:35:24Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('2cdcdd7d-8b6f-4e45-af3a-f555bc7f1aa8', 'e93f04c2-7344-4b93-abba-8ba1b2f8eb35', 55, 'Episode 590', '', NULL, NULL, NULL, '2026-04-03T17:36:30Z', '2026-04-03T17:36:30Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('2cdee02a-5e25-4f4c-9933-75fdf193e4ec', '941b8c65-4454-4336-be7c-1d0591c12f90', 4, 'Pingi''s Valentine Card', 'It is Valentine''s day, and Pingu gets a valentine card from Pingi. He shows it to Pinga and Mother, and decides he’ll make one for Pingi. Mother gets him the box of card making materials out of the cupboard and he settles down to making the card. He chooses the paper for the card, and then tries to put glue on it to attach a heart shape. Unfortunately the glue won’t come out at first, and then comes out in a big blob. He attempts to stick a heart to a card, but each stays stuck to the hand he’s holding it in. He eventually gets them stuck together, or so he thinks, but after a few seconds it falls off! He then tries to make a card using glitter as well as the heart. He gets the glitter and heart stuck to the card, but then can’t put the card down as it keeps sticking to him - if it isn’t stuck to one hand it’s stuck to the other, or to his head. He eventually gets it off, but meanwhile Pinga has sat up to the table and is rude to Pingu. Pingu is rude back and mother intervenes, but the card then sticks to the newspaper she is reading. It comes off when she has to intervene again, and it ends up stuck to Pingu as before. After another struggle getting it off himself, Pingu stomps into the bedroom to sulk. There he discovers he’s got another piece of card stuck to his bottom. Meanwhile Pinga is making something from some card without using glue and goes to show it to Pingu, who at first refuses to look. Eventually Pinga unveils her masterpiece – a set of linked figures cut out from folded paper. This gives Pingu an idea, and he goes back to the table and makes some cut out hearts. He takes them over to Pingi’s home and gives them to her. She is delighted.', '2003-08-22', 5, '/zfM97YqNHcD0JI9Yln96C9mEAJX.jpg', '2026-04-03T17:22:20Z', '2026-04-03T17:22:20Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('2ce6a946-29ff-495c-8c10-d9f63235e203', 'e3a58098-e0da-42f7-9709-96dc0a4866c8', 1, 'Fast and Slow', 'Rogers wants to take his time playing a game with a ball and a few tubes. The same can''t be said for the Trolley, which whizzes through the Neighborhood of Make-Believe.', '1995-09-26', NULL, NULL, '2026-04-03T17:35:47Z', '2026-04-03T17:35:47Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('2ce7abed-2398-430a-9e2f-73a4f5e043ca', 'b1d55597-d9d2-4eee-ab95-46dbb163291a', 12, 'Pinga Is Left Out', 'Pingu brings Pinga along with him to play with Pingo. When they meet up, Pingu and Pingo start playing leap-frog and Pinga really wants to join in. But Pingu, however, forbids her to play with them because she''s too little. While he and Pingo are rampaging about, she sadly runs away from them. Pingu and Pingo look everywhere for her, and finally find footprints and her scarf at the edge of a deep pit. Assuming she has fallen in, Pingu and Pingo go home in tears and tells mother what happened. But Mother explains to them that she was at home all along. Pinga starts tormenting Pingu, who gets very angry and starts to hit Pinga with her scarf, but Mother stops him and tells them to make up, to no avail. While Mother and Pingo watch on, Pinga refuses to speak to Pingu, but he soon discovers that patting Pinga''s hand comforts her and they both make up. Pingu then happily feeds Pinga.', '1989-12-17', 5, '/2q6jgRzIYexd9kGfZdkjrrFWZj.jpg', '2026-04-03T17:22:18Z', '2026-04-03T17:22:18Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('2cf7bd19-1430-492e-8363-8a521df64133', '1d39506b-06b8-4f93-9136-0208069bd7e4', 9, 'Stay on Message', 'Jill hires new housewife Jennifer Gilbert to plan her holiday bash. Elsewhere, a stunned Bethenny discovers that her pregnancy was leaked on the blogosphere; drama sharpens between Alex and Jill; Sonja visits a nip-tuck doctor and a psychic.', '2010-04-29', 43, '/uY0rcGG4zz8qElyMqHb1ZzKT9gv.jpg', '2026-04-03T16:35:22Z', '2026-04-03T16:35:22Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('2cf97c88-d5fe-4356-8afb-ad2bfdfbf2ef', 'f1bffb39-ecc9-4322-a528-c335d8048732', 3, 'CoComelon Sing-Alongs:kids''Favorites', 'Clap your hands and tap your toes alongside J.J. and his pals to popular children''s songs like "Old MacDonald,""itsy Bitsy Spider" and "Baby shark"', NULL, NULL, NULL, '2026-04-03T15:26:05Z', '2026-04-03T15:26:05Z');
