INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('2cfb3d97-011e-4df5-9aab-51b6b9f5d001', '0ebba123-871d-4d2b-a054-eb85d2ad9450', 23, 'Duke and the Great Pie War', 'A lesson in loving your family.', '2005-05-05', 30, '/nuCFyisiXfUp1oFUM47Xhr4jwQe.jpg', '2026-04-03T17:39:39Z', '2026-04-03T17:39:39Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('2cfea32a-5ff3-4d65-b368-dad1a2019694', '517e7594-ee8e-4564-a52d-4588850bbbdf', 5, 'Unforgiven', 'Meri gets a present for Kody to make amends for the catfishing catastrophe. Meanwhile, Madison goes shopping for a wedding dress; and Mariah displays her independent side.', '2016-05-29', NULL, NULL, '2026-04-03T16:34:29Z', '2026-04-03T16:34:29Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('2cffb9d8-2d29-4875-8f5c-d307bcb6b49e', '9193e795-da7c-40ec-b68f-f63aa7d5174f', 255, 'The Free Companies of Essos', 'Author George R.R. Martin talks about the free companions of Essos.', '2014-02-18', 2, NULL, '2026-04-03T15:40:35Z', '2026-04-03T15:40:35Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('2d00fd1b-a36f-4096-a4a0-294193cea85c', '4eb9b495-7962-41d9-ba8a-3bed48d9bcc6', 10, 'Treats!', 'An advertising Dream Team - creators of the Lions'' favorite ""Wheaty Meat Treats"" spot - is hired to create a commercial for the library. But it seems the team needs a little help. Guest Starring Vanessa Williams, Oliver Platt, and Jon Stewart.', '2002-11-18', 30, '/iJ1nSj9dQNY8KVtBKBcNjuqCdpB.jpg', '2026-04-03T17:12:28Z', '2026-04-03T17:12:28Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('2d0122d6-b045-4ee5-943c-4473b903bd99', 'f9a8d8b3-d72e-437e-a9d5-7477f6d64df8', 3, 'Kind Rudy', 'Elmo and Rudy are helping Abby out in the garden because she hurt her wrist, and Rudy wonders how else he can help, too. What if he holds the door for Chris, who is holding the bag of soil, waters the flowers, cleans up paint left out at the community center, and makes a get-well card for Abby''s wrist? Just because some things are done doesn''t mean you can''t help. There are so many ways to be kind!', '2022-11-17', 26, '/itOtHUYFLvO2Fmo6jORxM72amp5.jpg', '2026-04-03T17:36:51Z', '2026-04-03T17:36:51Z');
