INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('2d4dfc58-7289-42e6-80e8-75e210549812', 'e6359e6d-9bdb-4aba-9cba-6f7ddd6328f9', 4, 'Lights Out!', 'Lisa Rinna and Erika jet off to Tokyo to support Amelia and Delilah''s latest modeling gig, but "momager” Lisa comes to the realization that the girls might not need her there as much as she thought. Dorit agrees to model for Lisa Vanderpump''s magazine, but the photo shoot is not what she expected. When the power goes out at Kyle''s dinner party, the darkness brings out the worst in one housewife, leading to an explosive outburst.', '2018-01-09', 43, '/5dHEgXQwa9XPmTzrqKsMd2Vsapb.jpg', '2026-04-03T16:34:57Z', '2026-04-03T16:34:57Z');
