INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('2db52f38-aacb-4334-bd1d-6a03c974a07e', '7b8e3988-fbf3-4cfc-aeb2-782ae5a64e2d', 12, 'There’s An App For That', 'Baby Bear is ordering a bowl of porridge at Hooper’s Store when Telly comes in bouncing on his pogo stick. As he’s practicing the boingarooni, the hardest pogo trick, Mack, the pogo salesman, bounces in and tries to sell Telly and Baby Bear an iPogo stick. With an iPogo, not only can you boing without ever falling off, you can do almost anything- make a phone call, take a picture, and cool off hot porridge! Telly agrees to exchange his old, beloved pogo stick for a brand new iPogo. When he tries it, the iPogo seems to do everything but boing. Baby Bear uses the manual to figure out that they need to press a hexagon icon to get the iPogo to boing, but when he tries that, it ejects Telly right off! Then, they try a triangle icon, but that shakes Telly like a milkshake. Telly finally does the perfect boingarooni, but is disappointed because the iPogo did it for him. Telly asks the salesman for his old pogo stick back and everyone celebrates as Telly does the boingarooni all by himself!', '2010-11-03', NULL, '/dRXqLgpGa3TUTZHxAMM5i9Judug.jpg', '2026-04-03T17:36:46Z', '2026-04-03T17:36:46Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('2db54da9-3f7f-4e31-a5dd-acbaefc69f78', '3ee646e8-23ae-4dec-bbc6-c7e6a210d55b', 53, 'The Count counts stars', 'Telly passes by the Count, who invites Telly to join him in a special activity, but they must wait until it''s dark out. Gordon suspects that Big Bird doesn''t want to go to sleep when he requests a fourth bedtime story.

Sponsors: I, K, 10', '1991-01-23', NULL, NULL, '2026-04-03T17:36:38Z', '2026-04-03T17:36:38Z');
