INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('2dc22479-b1ae-4942-a1cb-0ef4488fd146', 'f4d370ca-3c39-40a8-911d-e2b5e7c6b0d7', 13, 'The Treasure Hunt', 'It is a lovely warm day and the toys are out in the garden. Duck is weeding, Bramwell is planting seeds and Jolly Tall is watering. The only ones who aren’t helping are Little Bear and Ruff who are much too busy playing. But Bramwell has an idea; he sends them on a treasure hunt which, to their surprise, ends up with them helping in the garden too!', '1996-11-27', 10, NULL, '2026-04-03T17:18:56Z', '2026-04-03T17:18:56Z');
