INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('2df5a472-04aa-42dd-9c9a-05b6f0f0aaff', '5046642d-462d-4eb0-8194-0bbd7962af0f', 9, 'Bully Trouble', 'Junior is a young boy who is discouraged when a big bully named Mount Gordon claims the playground as his own and threatens to pound anyone who trespasses. Back in his tree house, Junior starts daydreaming about being very heroic with Gordon always being the antagonist of his dreams. When he declares that he is not afraid, Dad comes and gives him advice on how to overcome his fears. Later, the kids return to the playground. Gordon appears and threatens to pound Junior every day. But soon, the other kids gain courage to stand up to Gordon as well. Gordon leaves and everyone cheers.', '2006-10-04', 30, NULL, '2026-04-03T17:39:38Z', '2026-04-03T17:39:38Z');
