INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('2e1f86e6-ea58-4453-ab45-bfce74daa82d', '936491e2-ab83-4e1f-b5c7-2c03f6461d86', 3, 'Summer Story', 'During the harvest season, Lord Woodmouse and Primrose go picking blackberries, while Wilfred looks for adventure by trying to find a creature called The Weasel. Primrose and Wilfred get lost as they explore the wilderness, so all the other mice send out a search party. The search party finds Primrose and Wilfred, so they all return home.', '1997-08-25', 25, NULL, '2026-04-03T16:14:06Z', '2026-04-03T16:14:06Z');
