INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('2e2a8424-d51e-4f49-8adb-2805a4542b2a', 'b6a0f228-7ddc-409c-b808-681b777a6704', 14, 'Mister Rogers Makes an Opera', 'Rogers finds a bubble-making machine and a knitting machine at Bob Trow''s workshop. Mr. McFeely shows a video of how people make sweaters in a factory. Reardon also visits the Neighborhood of Make-Believe. Lady Aberlin decides she will be a sweater-maker for an upcoming opera.', '1980-05-29', NULL, NULL, '2026-04-03T17:35:42Z', '2026-04-03T17:35:42Z');
