INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('2e3711c6-aa99-4ef6-87d8-8aafc20f9b14', '4c79c0b6-21a4-4277-8967-be1e791efdbe', 20, 'Pingu and the Rubberband Plane', 'Pingu is on his way to school with his toy truck when Pongi catches him up. Pongi is carrying a box that contains a model plane powered by a rubber band. Pingu goes to touch the plane but Pongi quickly shuts the box and walks on. Then Pingg goes past, carrying a long thin box, and Pingo also goes past, bouncing on his pogo stick. After seeing these toys Pingu is quite envious. At school, they’re all playing. Pingu is playing a game of “catch the fish” with Pingi, Pingo is bouncing about on his pogo stick, Pingg is playing swing-ball and Pongi is flying his plane. The schoolmaster has a try at “catch the fish” and gets one. Just then the plane flies low over his head and lands. Pingu goes over to where it has landed and picks it up, but Pongi rushes over and grabs it back. He then relents and lets Pingu hold it. The schoolmaster comes across to look at the plane and breaks the rubber band, so he goes to his box and gets a new one. He then gets distracted, so Pingu tries out the plane with the new rubber band. It doesn’t go very far, so Pingu gets a bigger one from the rubber band box and tries the plane again. It still doesn’t fly very well. Pingu then finds a very big band in the box and wants to try it, but Pongi doesn’t want to. The schoolmaster then tells them all to sit down, and starts the lesson that is on how to draw a circle. Pingu isn’t doing very well, but then he has an idea and pretends he wants to go to the loo. When the schoolmaster says yes, he sneakily collects the plane on the way, fits the very big rubber band and tries it out. The plane zooms round the classroom, disrupting the lesson, then zooms off, with Pongi and Pingu in pursuit. It then buzzes around Father, who is out on his motorised sledge to make a delivery, and twice he nearly crashes into the fish stall trying to avoid it. When the plane finally lands Pongi grabs it. Pingu catches up, and Father sees them. Pingu explains what he’s done, and Father takes them both back to school. At school the schoolmaster is still trying to teach how to draw a circle, but he’s not having much success. When Pingu and Pongi arrive, the schoolmaster tells them off and confiscates the plane. Then Pingu has another idea. He attaches the plane to Pingg’s swing-ball and sets it going, and it flies round in a perfect circle. The class then use the method to draw their own circles.', '2006-02-23', 5, '/xClBG592XaQn9WvzZhROtr2lBi.jpg', '2026-04-03T17:22:21Z', '2026-04-03T17:22:21Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('2e3be49c-fbf2-451f-976a-e3db5792f02f', '151e88a1-9576-4bd1-b84a-c4d64c1c9fe8', 17, 'The Girl With the Diamond Earrings', 'The ladies hit the slopes in Aspen, where Dorit proves to be shaky on her skis. Sutton goes snowmobiling but is really revved up about Diana. Garcelle broaches a very touchy subject with Erika at dinner. Back at the house, Rinna wants everyone to chill out, but things get heated when Kyle and Crystal confront Erika about her perceived lack of empathy.', '2022-09-07', NULL, '/zqALNzRtYz9ebQgAEU5qs3vGEo4.jpg', '2026-04-03T16:34:58Z', '2026-04-03T16:34:58Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('2e3ccf65-383e-4ff4-be13-c6511151aa4f', 'dec4a06d-731b-41e4-8b15-374f47d1f5c7', 18, 'Reunion (2)', 'The group is divided during ongoing reunion dramas. Joe Gorga and Chris Laurita enter the fray to address Teresa''s stern accusation; Jacqueline bids adieu to a relationship; and Siggy''s wish for the group comes true in a shocking conclusion.', '2016-11-13', 43, '/cqA7Cm3FDkrlFBsnhBdnQFPb2S.jpg', '2026-04-03T16:35:16Z', '2026-04-03T16:35:16Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('2e3ff6fc-7a86-4561-bdf3-87e2823b5549', 'bf722849-cddb-452b-9c0f-7f0d96e94c26', 1, 'Work', 'When a violent thunderstorm wrecks Plato’s Peak, everyone works together to clean up the debris, except Sock, who finds no virtue in work.', '1996-09-02', 30, NULL, '2026-04-03T17:38:34Z', '2026-04-03T17:38:34Z');
