INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('2e8b6dcf-2473-49ad-ab34-fa7f8194ca3a', 'bfdf87ff-01dd-4b54-94bd-19b384f41bdb', 8, 'Shannon Gets Her Groove Back', 'After an explosive night at the sushi dinner, Heather and Tamra discuss Kelly''s volatile behavior as Kelly regretfully turns to her friend Meghan and receives some tough love. Meanwhile, Meghan takes the next crucial step in her IVF process. Later, Shannon celebrates a night full of surprises with all her friends and family. Back in the OC, Vicki and Kelly have a party of their own and bond over being the odd women out.', '2016-08-22', 44, '/ng0qJFsiF6PWYtG4KtP7XAPwC41.jpg', '2026-04-03T16:35:33Z', '2026-04-03T16:35:33Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('2e8bb30b-0d77-43c1-a2cd-12b993a1f3d2', '4d2cac0f-38fd-438b-8afa-acf43952e535', 228, 'Episode 228', 'Christopher Trace and Valerie Singleton introduce a magazine programme for younger viewers. Including "Bengo at the Circus" by Tim. Told by Tim Gudgin, "Two Bagatelles" by Norman McLaren and "The Sea Commander": The final stages.', '1963-04-22', NULL, NULL, '2026-04-03T17:21:47Z', '2026-04-03T17:21:47Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('2e8cf2b2-ab85-4c6c-b974-88b8c4efa0bb', '5c4e51c6-e207-46ad-875c-72988eb1e13e', 20, 'Kings and McQueens', 'The Pawn Stars are blown away when a seller limps in with a 19th century shotgun disguised as a cane. Will Rick take a shot at buying this legendary concealed firearm or will his offer miss the mark? Then, Rick and Chumlee race to check out a 1940 Indian Motorcycle once owned by the King of Cool, Steve McQueen. Will this negotiation take off like a Bullitt or will Rick let this one make a Great Escape? And later, the guys are presented with a book printed by founding father Benjamin Franklin. Will Rick shell out some of his own Benjamins for this rare piece or will he find it''s not worth the paper it''s printed on?', '2011-07-18', 21, NULL, '2026-04-03T16:34:16Z', '2026-04-03T16:34:16Z');
