INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('2e9ebd6b-44fb-4851-9895-1fe2010296cc', '4b2a19e0-2fae-492e-bc31-f78e63d88ebc', 20, 'A Pawn of Lies', 'Bend your mind with the Pawn Stars when two original lithographs by graphic artist M.C. Escher are brought in. Will Rick make a surreal sale or will he find the deal impossible to construct? Next, things get transparent when a censored recording made on a Soviet X-ray is exposed in the shop. Will Rick throw the seller a bone or will the deal cause a stress fracture? Then, Corey calls shotgun when a Wells Fargo model stagecoach rides in. Will he jump on the bandwagon and make an offer or will he be walking home? And later, a 1950s toy lie detector puts Chum in the hot seat. Will he make an honest offer or will he fail the test?', '2017-01-01', 21, '/40X8Bp9EOUcrx0q5Gm0K4yGrrN4.jpg', '2026-04-03T16:34:20Z', '2026-04-03T16:34:20Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('2ea52ea1-305f-4c7c-81ab-54da14ff1737', '6c1ec19f-74df-4f35-9a61-17b98175d826', 6, 'Read Between the Signs', 'Erika is left seeing stars at her astrology party when old resentments flare up between Kyle, Teddi and Dorit; Denise''s simmering frustration boils over in front of a speechless Lisa Rinna; Garcelle questions a new friend''s priorities.', '2020-05-20', 43, '/xMZ0x7aeiDF2lXVul47PrxscxRh.jpg', '2026-04-03T16:34:58Z', '2026-04-03T16:34:58Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('2eb04ef4-d4e0-43c1-8597-e599e092758d', '3fc7c152-e4f6-426a-a899-36ec454c4403', 56, 'True Blue Friend', 'The gang inadvertently uses permanent paint and turn themselves into different colors. They must follow Quetzal''s instructions in order to remove the paint from their bodies.', '2000-01-26', NULL, NULL, '2026-04-03T15:26:03Z', '2026-04-03T15:26:03Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('2eb3d25f-2e0b-48b3-9870-76d8b69d554a', '8bae6aa3-4b55-4fa6-bc15-8f4317bd1f13', 40, 'Lady Elaine Flies into Space Pt 5', 'Lady Elaine radios back to the Neighborhood of Make-Believe, saying she will stay in space because she has made the most extraordinary discovery.', '1972-04-14', NULL, NULL, '2026-04-03T17:35:40Z', '2026-04-03T17:35:40Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('2ebb1911-9067-4859-b1d8-49277c3b1aff', 'dbd3583f-e9b2-46d1-a37e-309eb666e233', 12, 'South Africa: Just Like Home', 'The ladies arrive in Cape Town, South Africa for a 10-day adventure where it’s officially the “Smalls” (Phaedra, Shereé and Kandi) versus the “Talls” (NeNe, Cynthia and Marlo). However, Africa works its magic on them - even NeNe and Shereé put aside their differences for the first time in months. On a yacht ride in the harbor, they open up to each other about their differences and attempt to start anew. But the love-fest is only a few hours old when NeNe''s new bestie, Marlo, confronts Shereé about not inviting her to a dinner party. A huge fight erupts, with NeNe playing the unlikely role of peacemaker. Back in Atlanta, with Kroy away at football camp, Kim’s feeling the pressure of being a single mother of three.', '2012-01-29', 43, '/vfaPqWhuby2J76WPJF901XdAZwl.jpg', '2026-04-03T16:34:45Z', '2026-04-03T16:34:45Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('2ebbdba9-b3c6-4b71-9588-c570e7cf716a', 'b2317fc3-1cfc-4f19-b181-effa23959c6d', 8, 'Forest of Fury', 'Dolores discovers David''s true feelings about her, while Margaret and Jennifer sit down to hash out their issues. On the other hand, Traci''s well intentioned team building event turns toxic when Teresa unleashes her anger on the group.', '2022-03-22', 43, '/1wblRhIHCgm20NLBWoJSLxhUPOS.jpg', '2026-04-03T16:35:18Z', '2026-04-03T16:35:18Z');
