INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('2ed81531-d949-48dd-a309-f6056630ae56', 'f4d370ca-3c39-40a8-911d-e2b5e7c6b0d7', 9, 'Rabbit and the Visitor', 'Rabbit’s rather rude cousin turns up unexpectedly and decides to stay with the toys for a few days. After a large picnic tea, where she eats most of the food, the toys get ready for bed. She puts on her pyjamas and climbs into the bed, leaving no room for Rabbit. The next morning the toys decide having a guest is not as much fun as they thought and Old Bear thinks of a plan that might persuade her to go home.', '1996-10-30', 10, NULL, '2026-04-03T17:18:56Z', '2026-04-03T17:18:56Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('2ed94525-b1c6-48e1-ac5d-68de5840c633', '10e64538-c78a-4cb0-82f9-17d14256dbac', 9, 'The Convention', 'Frankie invites Mike to join her on a trip to Des Moines, Iowa for a convention about her dentist office''s transition to a new owner; and Axl informs a disapproving Sue that he''s moving into her dorm room. Meanwhile, Mike''s dad agrees to watch Brick while the parents are out of town.', '2015-12-02', 22, '/2Se1JjLEiroTE28hGpD2OCtbjbE.jpg', '2026-04-03T15:40:31Z', '2026-04-03T15:40:31Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('2ed9f873-d44c-4ce1-a295-4273b289b5ad', 'b761c069-8326-445a-8a55-4adf19467af4', 2, 'Yee Ping / 6 Cents Don''t Go That Far / Mrs. Parette''s Picture', '', '1993-05-18', NULL, NULL, '2026-04-03T17:11:21Z', '2026-04-03T17:11:21Z');
