INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('2ef2698f-aef3-43b6-8243-a7b9768b1a1e', '4d0fd8a5-5200-4dfc-b96c-ae436dc8803c', 3, 'Sam The Sea Cow', 'LeVar goes to Florida to help take care of manatee with a crew of marine biology experts. He gets to feed a baby manatee, and assists in returning a rehabilitated manatee back to the ocean. Jason Robards reads the feature story of a true tale about a young manatee named Sam whose curiosity caused him to get stuck in drain pipe, and how he was rescued and returned to the sea.', '1992-10-07', 30, NULL, '2026-04-03T17:36:18Z', '2026-04-03T17:36:18Z');
