Sponsors: P, T, 8', '1983-11-29', NULL, NULL, '2026-04-03T17:36:35Z', '2026-04-03T17:36:35Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('2ef832ac-78d5-4801-9be2-f459d81399f2', 'de8ec769-16bb-436b-be43-aedc7e18a7d7', 31, 'Rudy Blows His First Bubble', 'Rudy feels frustrated that he can''t blow a bubble. With help from Elmo, Alan, and Rosita, Rudy realizes that he needs to breathe out instead of breathing in when blowing a bubble.', '2020-06-13', NULL, '/xzDDeHdOpVnqfmUSFW8Nbu5EuEB.jpg', '2026-04-03T17:36:50Z', '2026-04-03T17:36:50Z');
