INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('2f003273-167a-44da-83d3-ecb1eff75ab1', '42e591e2-2a88-4434-ae9f-3d4b1d685613', 23, 'What Happens in Vegas', 'Prepare to squirm with the Pawn Stars as the guys check out a collection of sex education records from 1948. Will Rick discuss the birds and the bees in front of the Old Man? Then, Corey and Chumlee check out a "blue book" from the Las Vegas Sheriff''s Department. A who''s who of Las Vegas criminals in the 1960s, can the guys collar this rare crime fighting tool? And later, the shop gets a new intern, but will Chumlee see the new hire as his personal assistant?', '2013-08-29', 21, NULL, '2026-04-03T16:34:18Z', '2026-04-03T16:34:18Z');
