INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('2f1f12be-b1cc-4938-84c7-82ed59a90805', '050d8ae1-6cc1-4018-933d-b3c3d13de856', 52, 'Episode 52', 'Tile Detective!

Monkeys, camels and elephants, nursey rhyme characters and royal princesses are just a few of the valuable tile pictures that used to cheer up patients in the children''s wards of hospitals.

Now as old buildings are demolished the tiles are in danger. The search is on to save them, and you can help. Find out how today, and see some of the treasures that have survived.', '1985-03-11', NULL, NULL, '2026-04-03T17:21:57Z', '2026-04-03T17:21:57Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('2f1f2224-a642-4d39-8da4-c56e7c675f4c', 'f9a8d8b3-d72e-437e-a9d5-7477f6d64df8', 14, 'Family Album', 'Gabrielle and Tamir are making a family photo album for Grandma Nell. They learn about melanin and that sometimes people in a family can look alike, and sometimes they can look different, but are still the same family.', '2023-02-02', 26, '/a6krBdOtjh073cCP8s1mY9I1Gol.jpg', '2026-04-03T17:36:51Z', '2026-04-03T17:36:51Z');
