INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('2f2c834f-a1fb-41e5-a047-c5bca08dd3d0', '5c4e51c6-e207-46ad-875c-72988eb1e13e', 2, 'Pablo Pawncasso', 'Get revved up with the Pawn Stars as they check out a rare REO Flying Cloud hot rod from the 1930s. Will Rick muster the strength to crank up an offer for this classic ride or will the deal take a detour and sputter out? Then, Rick and Corey are presented with a well-known Picasso etching called "Poor Roby." Will the guys draw themselves a masterpiece of a deal or will critic reviews call it "Poor Rick?" And later, Rick and Chumlee meet a man trying to sell his pair of pants - miniature gold plated pants awarded to Ohio State football players when they beat Michigan. Will the guys cautiously step into this deal one leg at a time or jump right in with both feet?', '2011-04-04', 21, NULL, '2026-04-03T16:34:16Z', '2026-04-03T16:34:16Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('2f2fb08f-7cb2-4030-95a2-8f5476ebad74', '42684fca-0bc7-4f4c-bf7d-f41fd288a764', 20, 'Postman Pat and the Great Dinosaur Hunt', 'Pat, Ted and the villagers are working hard on a very special surprise for the children. Meanwhile, the children are looking for dinosaurs, and it''s not long before they find one...', '2004-10-06', 15, '/r3BRVoGuOsUiM4muKLk25aAowdV.jpg', '2026-04-03T17:14:30Z', '2026-04-03T17:14:30Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('2f42e61b-8236-46f5-bf6a-eaec681528d4', 'e8b959c0-6865-4332-9be1-b8f720716aa8', 14, 'Library', 'John visits The Children''s Library in Sutton Coldfield.', '1992-01-13', 15, NULL, '2026-04-03T17:19:37Z', '2026-04-03T17:19:37Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('2f459f8d-99f6-40b9-85ea-5b98f04b2e4d', '699572f8-2bff-4515-8df3-6e7d1a21f346', 6, 'Goes Cellular', 'It’s the night of the rock lovers’ annual Granite Awards, and Arnold is about to become the first kid to win the Rocky Award. He’s so excited, all he’s been able to eat for weeks are “Seaweedies.” When he arrives for the big event, he’s totally nervous and totally... orange!', '1997-10-18', 25, '/q5O4RbXlyDodV9F9Plc8x9QdcMH.jpg', '2026-04-03T17:37:49Z', '2026-04-03T17:37:49Z');
