INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('2f4b3e30-d559-4d40-8d9c-17c9339da46d', 'db958af4-9a9a-4533-af9b-f0ff590d1dd9', 9, 'Coffee Talk', 'Paul tells Dolores she needs to establish boundaries with Frank; Melissa and Teresa have differing opinions of Louie''s involvement in their family issues; Dolores and Jennifer attempt to mend their friendship over lunch.', '2023-04-04', 44, '/3BAMaM3dSAqzN3Pd4qnTWYBwHUJ.jpg', '2026-04-03T16:35:19Z', '2026-04-03T16:35:19Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('2f528aad-c666-442a-af11-225ce8d32654', '8bae6aa3-4b55-4fa6-bc15-8f4317bd1f13', 64, 'Episode 64', 'The McFeelys bring two African lion cubs to Rogers'' television house. In the Neighborhood of Make-Believe, Lady Aberlin helps Handyman Negri with his tasks.', '1972-05-18', NULL, NULL, '2026-04-03T17:35:40Z', '2026-04-03T17:35:40Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('2f53f981-7cea-4a45-8dbd-44852102f87a', '6f731e6b-d3c5-4de6-84e1-7a19cb650e86', 1, 'Pawn of Fire', 'Walk the line with the Pawn Stars when a model train once owned by Johnny Cash chugs into the shop. Will Rick make a bid for the Man in Black or will he be singing the prison blues? Then, Chum gets scrambled when a 1920''s chicken incubator clucks on in. Will Chum hatch a deal or will it get poached? Next, Rick becomes enlightened while checking out a 17th century Tibetan Buddha. Will he be reborn as a buyer or take a vow of silence? And later, Rick and Corey take a trip down memory lane in a 1972 Cadillac Eldorado. Will the guys take home the luxury Caddy or will it turn out to be a clunker?', '2015-10-22', 21, '/5hsPAhaBFlE94I72iOcsBo5NUpB.jpg', '2026-04-03T16:34:20Z', '2026-04-03T16:34:20Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('2f543a81-b6bf-4fb1-84ef-a92d5b391dce', 'ecb64ef3-4f80-45a7-b4a9-c04434b02e35', 16, 'Chords, Swords and Rewards', 'Rick and Corey check out a sword belonging to the Freemasons. Will the guys be able to sneak in an offer or will negotiations get chopped? Then, Corey and Chumlee play with the idea of scoring a Gibson Master Museum guitar. Stamped with the serial number 1, how far will they go to pluck out this rare instrument? And later, Chumlee tries to prove he deserves a raise, but will his weaknesses outweigh his strengths?', '2014-02-20', 21, '/5cRsrQtJXv2DcWVronRvSaz7BtY.jpg', '2026-04-03T16:34:19Z', '2026-04-03T16:34:19Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('2f5b792f-2acf-4b40-b42a-e9596074c1e8', 'd4b26e75-318a-457b-ae14-c30bfec3d76e', 6, 'Wood', '', '1993-10-28', NULL, NULL, '2026-04-03T17:19:30Z', '2026-04-03T17:19:30Z');
