INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('2f7fe62e-8901-4b2b-bd56-0a6c85fe77ca', '6f81c872-cdb9-42dd-8377-2c17cb6ed4d7', 6, 'Elmo''s Sweet Ride', 'Elmo shares his scooter with Zoe and learns how to be patient and wait for his turn, while she practices and learns how to ride.', '2017-02-11', NULL, '/4UOeHCo4TELYy34cOfpRrF5XJhL.jpg', '2026-04-03T17:36:48Z', '2026-04-03T17:36:48Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('2f837a13-17bb-46c6-8b2d-b7966a09fbb9', '3ade5e1f-8441-4c2c-acf6-fb933a61dcfa', 17, 'Unanswered Questions', 'The women scramble to find Katie, and are shocked to discover her true whereabouts. Gizelle battles mother nature, while Karen teaches the ladies a unique technique. The fun comes to screeching halt when Karen and Ashley get into an unexpected conflict – catching everyone off guard.', '2019-09-01', 42, '/fkNVSUUKmQKNb5BELHMr60qFKoU.jpg', '2026-04-03T16:35:39Z', '2026-04-03T16:35:39Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('2f87e09f-e113-4ec3-aa0d-9ca1f3723afe', '5144de59-e67f-4fcf-919b-7106989ab797', 22, 'Maiden Voyages', 'While the others turn the basement into a moonwalk with many balloons, Kiki and Julie enjoy moon cakes, but a humorous misunderstanding may mean Julie will marry Leon.', '1995-02-14', 29, NULL, '2026-04-03T17:12:21Z', '2026-04-03T17:12:21Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('2f88c0a3-f377-407f-b8fe-656ac209381a', '33440d76-e69f-47ad-ac25-862ccbc9dfa1', 4, 'In a Pickle', 'Karen invites all of the couples to a fun day of pickleball, but things get heated on and off the court. Candiace comes face to face with Robyn and Gizelle. Everyone is surprised when a certain husband makes an appearance. Nneka confronts Wendy with some shocking allegations.', '2023-11-26', 43, '/jLKrerMdJjS7yk3rG5f3qZPckm4.jpg', '2026-04-03T16:35:41Z', '2026-04-03T16:35:41Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('2f903690-9eeb-435a-98f8-8cc4e66e8920', '6053b5c1-ce86-425c-8166-e0fcc3466061', 25, 'Episode 25', 'with Valerie Singleton, John Noakes, Peter Purves', '1969-12-08', NULL, NULL, '2026-04-03T17:21:50Z', '2026-04-03T17:21:50Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('2f98d39b-54c8-455d-b26e-85a081f78e70', 'c01ddd2a-bdb1-4c97-8d04-58f791ef1c24', 38, 'The Four F''s', 'Creature coats are the key to keeping animals warm in cold weather. Zoboo, Chris and Martin realize that animals beat the cold with the four F''s: fur, feathers and fat and in the case of otters fun. But what happens when the weather warms up? Ernie the camel comes to Animal Junction looking for a good scratching post to help him shed his winter coat for summer since he won''t need it when it''s hot outside. Jackie brushes her dog, Goldy, to help her take off her heavy winter coat. Dogs and cats love being brushed and it feels good to lose that extra hair. Jackie knits a small sweater from the hair she brushed out of Goldy.', '2000-04-25', 27, NULL, '2026-04-03T17:10:55Z', '2026-04-03T17:10:55Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('2f9ac1eb-4c4a-419d-b15d-599dc8cfec04', '671bd4da-3470-40f9-9a03-40fba34d2b8e', 14, 'Guess Who''s Coming to Frozen Dinner', 'Mike''s wayward brother, Rusty, comes to town and presents Sue with an extravagant gift, which Mike thinks is stolen goods. Meanwhile, with Sue now older and living the college life, Mike feels like he''s not as close to her as he used to be and tries to figure out a way to reconnect; Axl blows the money from his first paycheck on a big screen TV and blames his spending spree on years of learning from Frankie''s lack of financial wisdom; and Brick is stumped, but delighted to discover mysterious, unmarked gifts being left at the front door of the house.', '2018-02-06', 22, '/3uy0PChQUC6QEIqImUajCveRqAT.jpg', '2026-04-03T15:40:31Z', '2026-04-03T15:40:31Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('2f9cf18f-5373-4cd2-a4a2-0c6ae23eb933', 'e38e9d87-1432-4a1a-a7d0-64a559bf7570', 11, 'A Deathly Calm', '', '1993-03-14', 24, '/vBINJ2jMwoaVxMvpOc2pur9P0md.jpg', '2026-04-03T17:18:49Z', '2026-04-03T17:18:49Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('2f9d87f7-46d1-4054-91e9-b93b8905bbc1', 'd199804f-ccf5-4e36-8929-56c1e356b74d', 21, 'Episode 946', '', NULL, NULL, NULL, '2026-04-03T17:36:32Z', '2026-04-03T17:36:32Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('2fa1b88d-c598-48f3-acf4-92a647edd552', '331fc1df-6d70-4d79-b585-bf28024a4124', 2, 'Hot & Cold Running Sniffer Dog', 'Mike doesn''t believe that Radar is a rescue dog, but he is soon proved wrong after he falls and breaks his arm in the Whole Fish Cafe cellar.', '2008-11-12', 10, '/tEgDYG73zRNMs03bBQXBLDjSF8E.jpg', '2026-04-03T17:14:39Z', '2026-04-03T17:14:39Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('2fa3894e-02e5-49f7-8d24-061687e46c71', '9193e795-da7c-40ec-b68f-f63aa7d5174f', 68, 'Histories & Lore: Mad King Aerys (Tywin Lannister)', 'Tywin Lannister reminisces on the collapse of his alliance with Aerys as the latter descended further and further into madness.', '2012-03-05', 3, '/dvghaT5H91Iwr2UGFet1fxa25F9.jpg', '2026-04-03T15:40:35Z', '2026-04-03T15:40:35Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('2fa61404-c607-4e07-a1fb-6e61f2a70215', '190c6e49-8849-4404-87d4-eaef943a6024', 6, 'Oakie Doke And The Hat Hunt', 'Granny Annie accidentally loses her hat at the bottom of the pond, so everyone participates in a competition to fish the hat out for a grand prize.', '1995-10-16', 10, NULL, '2026-04-03T17:19:24Z', '2026-04-03T17:19:24Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('2fa6433c-5ca9-46e8-8340-1f1db55acb04', '5a6d9a42-165b-4b56-9273-0a06874dfe10', 16, 'Madeline''s Winter Vacation', 'Madeline, Pepito and the girls visit Miss Clavel''s aunt and nephew in their Alpine chalet.', '1993-11-14', 30, NULL, '2026-04-03T16:34:01Z', '2026-04-03T16:34:01Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('2fa7c224-244d-461b-9423-525504f36d74', '6acfefc0-1904-4f93-9c06-a1a09856150a', 5, 'Willow Whispers / Pink! / The Pond Prince', '', '2002-12-23', NULL, NULL, '2026-04-03T17:11:23Z', '2026-04-03T17:11:23Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('2fad29f6-d545-460a-8c92-366b87638b75', '9d74600d-7222-47c1-bd1b-635f5b41b7d1', 10, 'Abiyoyo', 'In one of the rare times Reading Rainbow uses a studio set, LeVar tells about storytelling through music. The then-new art of music videos is first up, with clips of Who''s Johnny (among others). Pete Seeger appears on the set to perform his version of Abiyoyo. Also unique to htis episode: all the book reviewers share the stage with LeVar.', '1986-07-04', 30, NULL, '2026-04-03T17:36:15Z', '2026-04-03T17:36:15Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('2faf49b7-1e0f-49b8-b490-c4244f981a4f', '45e64a15-8fc0-4e4b-a1ca-9e3f42f3634d', 9, 'Biodiversity', 'Ecosystems are areas where things live. Ecosystems that are biodiverse are home to a variety of   plants and animals. A healthy ecosystem is one with a lot of biodiversity.   Imagine if humans could only eat one kind of food, say corn. We''d be in big trouble if all the corn   disappeared. Besides not having anything to munch on at the movies, we''d have nothing to eat at all.   Luckily, our ecosystem covers a big part of the Earth, and there are lots of different plants to eat. Ecosystems   are not as simple as one living thing eating another, as the corn example. The lives of animals and plants   are intertwined - what happens to one animal can have an impact on all sorts of living things.   As humans, we have a big effect on the other living things around us. We are the only animals to leave   lots of stuff around, such as houses, cars, and malls. It''s important for us to think about the choices we   make and how they will affect the other living things around us. Remember: The Earth', '1993-11-05', 26, '/cKk14w7eEpXc7KPzLhzCvpRNptB.jpg', '2026-04-03T17:37:20Z', '2026-04-03T17:37:20Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('2fb00923-6094-4443-981f-792e4c5f3627', '4861ce46-9045-43c7-963f-27b4ea539804', 105, 'Episode 235', '', '1971-04-02', NULL, NULL, '2026-04-03T17:36:28Z', '2026-04-03T17:36:28Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('2fb4d371-1422-4c70-90b8-8ebd46ba3f5e', 'ad180412-a5d6-4e4a-8b49-590334f2fc69', 9, 'A Bigger Oink', 'The animals in White Deer Park are still trying to deal with the army of rats and try to make the Warden aware of the problem. Meanwhile the weasels and the piglet come across a copse with a grumpy Wild Boar living there. Bully forms a task force to hunt down and kill the snakes. They find Sinuous, thinking it''s Adder and kill him. Hurkel and Shadow try to comfort Adder as Bully slinks away unnoticed.', '1995-11-23', 25, '/oVwqtCPP3NNvPNknWNLJYM5BEzd.jpg', '2026-04-03T17:18:49Z', '2026-04-03T17:18:49Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('2fb52c4f-5572-4afa-bad3-0b4f314b8f12', 'de8ec769-16bb-436b-be43-aedc7e18a7d7', 9, 'Humpty Dumpty''s Football Dream', 'When Humpty Dumpty decides to join the King''s Horses & Men in their annual football game, Telly tries to come up with the right protective gear to keep Humpty from cracking.', '2020-01-11', NULL, '/zvYm6L8Ypb5Y23weneQN2Ijkrl.jpg', '2026-04-03T17:36:50Z', '2026-04-03T17:36:50Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('2fb8a704-2aaf-4cb0-a13a-410daf1f5b60', '225b0f03-984b-47f3-a1a3-d3e92175e39d', 23, 'Episode 23', 'with Christopher Trace, Valerie Singleton and John Noakes.', '1966-12-12', NULL, NULL, '2026-04-03T17:21:48Z', '2026-04-03T17:21:48Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('2fba35ea-4591-4ff9-8c66-af3d3619c40f', '0987f081-b3b7-4e3c-abb7-795e56c279d5', 9, 'Christmas Help', 'Mike helps his brother Rusty move some furniture into the Heck family''s garage, only to realize the furniture is stolen; Frankie hopes to land a part-time job in a department store so she can get a discount on Christmas presents.', '2012-12-05', 22, '/efS7qg73IbsfSBCsGdgZK5hzdxe.jpg', '2026-04-03T15:40:30Z', '2026-04-03T15:40:30Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('2fbfc87a-7e58-4e6f-a8ec-048231d7f2d9', '421c3366-4d98-4baf-b4ad-6ec5047df9f8', 14, 'Go Fly a Kite', 'Muffy, Binky, and Ladonna find Carl''s lost kite and they argue over who should take possession of it.', '2014-04-22', 13, NULL, '2026-04-03T17:38:01Z', '2026-04-03T17:38:01Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('2fc0cb40-cde0-464b-820c-efe273afe82b', 'ad4e4348-3334-4a08-8928-455d9ba524c1', 2, 'Loretta Swit', 'How well can Loretta fit into Miss Piggy''s roles?  It all comes to a dramatic climax with the ""Pigs in Space"" installment.', '1980-10-12', 26, '/zKnIqVwUStWjFuT1ylWJ2X7HLz5.jpg', '2026-04-03T17:35:25Z', '2026-04-03T17:35:25Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('2fc4bc8d-08fd-4ec8-96bf-f0195e9aed67', '8c3cfac1-d882-4904-b38c-d1981628d00e', 28, 'Episode 28', 'A behind-the-scenes look at the filming for this year''s All Star Record Breakers - in Blue Peter''s Italian sunken garden!', '1978-12-14', NULL, NULL, '2026-04-03T17:21:54Z', '2026-04-03T17:21:54Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('2fc681c5-b5c7-4ce2-9bac-2edb5434e28a', '45e64a15-8fc0-4e4b-a1ca-9e3f42f3634d', 16, 'Light & Color', 'Lighten up. It''s the ""Light and Color"" episode.   Without light, we wouldn''t be able to see. It would be like living in a room with no windows, doors, or   lamps. There''s an old saying, ""We don''t see things; we see light bouncing off of things."" We see things,   and colors, when light bounces off things and into our eyes. White light, like the light from the Sun, is   made up of all the different colors of light blended together. When white light hits something white, almost   all of the light bounces into our eyes, and we see the color white.   Things are different colors because some light bounces off and other light gets absorbed.   An orange is orange because it absorbs all different colors of light except orange light.   Grass is green because it absorbs all different colors of light except green light.   Bill Nye''s lab coat is blue because it absorbs all different colors of light except blue light. All colors,   including black, are made in the same way. It''s just a matter of ref', '1993-12-24', 26, '/jvN7fQz61QphvBG1nXT2RTZLw71.jpg', '2026-04-03T17:37:20Z', '2026-04-03T17:37:20Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('2fc6c165-7367-49a7-9665-8aeba1fa6a08', '4b2a19e0-2fae-492e-bc31-f78e63d88ebc', 10, 'Great Negotiations', 'Drive a hard bargain with the Pawn Stars and relive some of the fiercest negotiations in the show’s history: a pair of boots worn by Elton John, a James Bond Aston Martin toy car, an ancient 44 B.C. Julius Caesar Roman coin, an assortment of vintage Pez dispensers, a 16th century book that belonged to Sir Isaac Newton, an extremely rare collection of Viking copper and gold and an aphorism signed by Mark Twain has Katie Couric haggling it out with Rick for the best deal.', '2016-09-07', 21, '/hcEpJqyFlsqmwXrGNRtYZHP49I2.jpg', '2026-04-03T16:34:20Z', '2026-04-03T16:34:20Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('2fcac989-335f-4e14-a69e-f4ca2b465657', 'f593d90c-5339-42f5-9c88-5bfd48d04075', 28, 'Zebra Ducks Of The Serengeti', 'After getting covered in soot, two hapless ducks are mistaken for a pair of rare African Zebra Ducks. Seeing a way to make money, the farmer transforms Shaun''s field into an exotic duck enclosure, which he gleefully opens to the public. Shaun doesn''t appreciate losing his field and sets about exposing the fraud.', '2010-12-03', NULL, '/aaBJ4JDzdjfWZBtQPzB4NXSh3Va.jpg', '2026-04-03T17:39:31Z', '2026-04-03T17:39:31Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('2fd0e42f-f550-491b-a199-0f2ef68b648b', 'f6015d9a-ece4-414a-a00b-06cf689fe40b', 21, 'Goes Microscopic!', 'You won''t believe your eyes when we set fire to water using miniscule science. There''s live music from Una Healy. Also, George is back to kick-start the Blue Peter garden.', '2018-05-17', NULL, NULL, '2026-04-03T17:22:10Z', '2026-04-03T17:22:10Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('2fd28b8d-5c65-4296-a6f9-e917fc1f82e6', '87f84063-82b3-45a4-936c-3759e5d91ce3', 6, 'Sex, Lies and Sister Wives', 'When Jennie is unwilling to expand their family, a heartbroken Duy seeks desperate measures; Jen plans a surprise for the ladies, while Heather has "the talk" with Ashley and Mary worries for her marriage once Robert Jr. leaves the nest.', '2021-10-17', 44, '/g5mhujkoVUBV0FmD8lgLX1Qb9Eu.jpg', '2026-04-03T16:35:44Z', '2026-04-03T16:35:44Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('2fd656fb-16f7-423e-b99a-6171e09c493f', '6c47406b-b3d6-40d8-b483-1ae1b3d30009', 9, 'Heroes of the Storm', 'Fireman Sam and the team are on a mission to save Pontypandy! Just as the brand new fire station opens and two new recruits arrive, an approaching hurricane threatens Pontypandy! The crew jump into action to prepare the town.', '2014-11-04', 60, NULL, '2026-04-03T17:14:36Z', '2026-04-03T17:14:36Z');
