INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('2ff9509f-c546-4fc7-832e-78dc2b652925', 'c7994637-b7c7-42c7-aaee-1bff4144fe23', 17, 'Soirees and Separations', 'After a tough year, Sutton celebrates her success with an over-the-top shopping day. PK’s continued absence leaves Dorit questioning her progress … and their marriage. The White Party is back and bigger than ever as Garcelle, Crystal and Annemarie get ready to watch Erika hit the stage at SoFi Stadium. A shocking headline forces Kyle to reckon with her marriage and leaves all of Beverly Hills questioning her truth.', '2024-02-21', 44, '/3zF2khiPUW5h5s1T2f9G0UgVG7T.jpg', '2026-04-03T16:34:59Z', '2026-04-03T16:34:59Z');
