INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('30119662-36c8-43de-b1ad-d69a9b98768b', 'fe19a277-aed8-44df-a4ac-fc1c4e9941b4', 2, 'Kim-Tervention', 'NeNe calls Kim to meet up for that long overdue “glass of wine,” in an attempt to make amends. Shereé dishes about the recent blow-up she had with a party planner. Meanwhile, Lisa and Ed have their first fertility visit. NeNe approaches Shereé about squashing their problems with Kim, and they set up a meeting to talk it out. Also, Kandi goes to the studio to work on her solo album.', '2009-08-06', 43, NULL, '2026-04-03T16:34:45Z', '2026-04-03T16:34:45Z');
