INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('301cfe9f-9505-40ed-863b-07bb54abb39a', 'd3e13496-e3c8-4903-83b4-5a31fedee232', 19, 'The Siege of the North (1)', 'Zhao begins to launch his attack against the Northern Water Tribe. As the walls of the prestiged city begin to fall, the Avatar taps into the spirit world and seeks the help of one of the oldest spirits, in hopes of saving one of the most prominent areas of the world.', '2005-12-02', 25, '/9jGillcXki194qzZm1LYfXNlVhz.jpg', '2026-04-03T17:40:47Z', '2026-04-03T17:40:47Z');
