INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('301ebf1e-0b11-477c-bb04-031d789333ed', '5a6d9a42-165b-4b56-9273-0a06874dfe10', 19, 'Madeline''s Birthday at the Zoo', 'It''s Madeline''s birthday & Pepito & his father take her to the zoo while Miss Clavel & the girls get the house ready for a surprise birthday party.', '1993-12-05', 30, NULL, '2026-04-03T16:34:01Z', '2026-04-03T16:34:01Z');
