INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('3026c11c-241b-4e40-bab9-0af346b90dcb', '4d2cac0f-38fd-438b-8afa-acf43952e535', 210, 'Episode 210', 'All Aboard! with Christopher Trace and Valerie Singleton in a magazine programme for younger viewers.', '1962-12-03', NULL, NULL, '2026-04-03T17:21:47Z', '2026-04-03T17:21:47Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('302af11c-155d-477f-a6b9-6f36dca17959', 'd920ebae-f00a-4e25-abfe-40492c74ded6', 20, 'Saints and Winners', 'When a customer comes in with items from Tony Soprano’s wardrobe, can Rick make him an offer he can’t refuse, or will he fuggedaboutit’ Then, a pair of papal artifacts inspires Rick and Chum to mix business with pleasure as they set off to Italy for a Roman holiday. Will the holy relics be the blessing they’re hoping for’ Meanwhile, back at the shop, Corey is puzzled by a rare toy. Can he line up a deal, or does he have the wrong combination’ Next, Rick’s on a mission to track down a rare book written by an iconic philosopher. Can he get on the same page with the seller before the deal goes up in flames’ And later, the guys take a test ride on a pair of Vespas. Will Rick and Chum join the Vespa club, or will they be left in the dust’', '2020-05-18', 42, '/oJ97KHqKnnEZvNFjcyXXAeDPKyz.jpg', '2026-04-03T16:34:22Z', '2026-04-03T16:34:22Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('303bc772-b55c-4f44-9d35-e4d1dfd401a3', '45e01c04-6ac6-41e1-87d8-f749ee230385', 48, 'Episode 48', '', NULL, NULL, NULL, '2026-04-03T17:14:38Z', '2026-04-03T17:14:38Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('303e1f7b-bdf4-4905-b916-1bb8fa4a420a', '34674c90-410e-427c-be4d-2a6f6f865a80', 23, 'Cool as Ike', 'The Pawn Stars prepare to invade when Rick is offered a memoir written and signed by Dwight D. Eisenhower. Detailing his command during WWII, is Rick willing to pay big bucks for this rare book, or will the negotiation force him to retreat? Then, a shop regular piques Rick s interest with a Remington New Model Army. Considered the second most popular pistol of the Civil War, will Rick make an offer, or has popularity diminished its value? And later, Corey and Chum orbit a set of food bags made for Apollo 11. Are the guys hungry to make a deal, or are the seller s expectations out of this world?', '2012-08-20', 21, NULL, '2026-04-03T16:34:17Z', '2026-04-03T16:34:17Z');
