INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('30aa4749-2b55-4cac-bfc1-13708f3c45e2', '319bd5d6-ff58-426f-b9da-a0bb2cb87b02', 15, 'Comets & Meteors', 'Outer space is full of stuff. We’re not just talking about planets and moons. There are some bits and pieces, too small to be noticed most of the time that float around and occasionally run into all those planets and moons. Comets and meteors are the big bits of dirt, rock and ice that inhabit our Universe. More than just high-speed space chunks, comets and meteors carry important information about the history of our Universe.', '1998-05-16', 26, '/iqwPAPpzOLvc0kl1De916JRD5gU.jpg', '2026-04-03T17:37:22Z', '2026-04-03T17:37:22Z');
