INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('30af7e4c-8edc-4b68-bfcd-162ca06787bc', '363a94f9-e0e5-441c-aa86-2be2e9832da1', 14, 'Big Apple Rick', 'Rick''s in the big apple to see if he can compute a deal on a rare piece of tech. Can this sweet piece, tempt Rick, or will he shut it down? Then, a seller flies into the shop with a special edition Stan Lee Funko Pop figure. Will Corey make a super deal? Meanwhile, Chumlee has a blast with an original flintlock wall gun. Will he hit his target, or be off the mark? And later, Corey checks out a vintage camera. Can he focus in on a perfect deal, or will the negotiations end in a flash?', '2021-12-18', 42, '/d2n7mupdtyk9fXtLgC1d6LhtdoM.jpg', '2026-04-03T16:34:23Z', '2026-04-03T16:34:23Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('30b14db8-0da5-4a95-b266-5e293cc27fdf', '228172b6-fed0-4226-acdf-820049d2c72e', 11, 'Everything''s Upside Down', 'The pandemic is pulling the Brown family apart, and tensions rise. Kody refuses to travel with Christine for Ysabel''s surgery. Then, Christine gathers the wives for a pitch to move back to Utah, which ends in tears as she questions her marriage to Kody.', '2021-04-18', NULL, NULL, '2026-04-03T16:34:31Z', '2026-04-03T16:34:31Z');
