INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('30beca05-fc28-4daf-bf1f-b93b136b755b', '699572f8-2bff-4515-8df3-6e7d1a21f346', 5, 'Gets Swamped', 'Should Walkerville get rid of the swamp and replace it with a great new shopping mall or build the mall somewhere else? The class learns that the swamp is an important habitat and natural water filter, but the town council’s not convinced until... FLOOD!', '1997-10-11', 25, '/vtoKzmvcpnQwfCKpOgMzcZ02way.jpg', '2026-04-03T17:37:49Z', '2026-04-03T17:37:49Z');
