INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('313d15dd-6d7d-4f48-87cc-2612eabae9d8', '5a6d9a42-165b-4b56-9273-0a06874dfe10', 26, 'Madeline in New York', 'While on holiday in New York, the girls and Pepito attend a Yankee game, and Madeline catches the first home run ball of the season.', '1994-01-23', 30, NULL, '2026-04-03T16:34:01Z', '2026-04-03T16:34:01Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('313e8e10-c3da-499b-a284-25ce83d49f8a', 'bf874be3-7e2f-4a0e-b205-c76ac1ad69fc', 162, 'Reunion Special', '', NULL, 22, NULL, '2026-04-03T16:34:09Z', '2026-04-03T16:34:09Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('313f4112-dece-45fb-abaa-4828cf9d7dd4', '63f9bf6d-39b3-44f4-b885-a56807277a80', 13, 'The Muppets Celebrate Jim Henson', 'Jim Henson''s classic Muppets put on a tribute to their creator, but also ponder the question: Who was he? To help them figure that out are some of Jim''s human friends, as well as some rare clips from the Henson legacy.', '1990-11-21', 26, NULL, '2026-04-03T17:35:23Z', '2026-04-03T17:35:23Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('313f548c-a213-48ea-8ada-5d696aee90dd', '4d2cac0f-38fd-438b-8afa-acf43952e535', 276, 'Episode 276', 'Christopher Trace and Valerie Singleton introduce a magazine programme for younger viewers.', '1964-04-20', NULL, NULL, '2026-04-03T17:21:47Z', '2026-04-03T17:21:47Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('31402463-c325-484e-a9a5-567fcc61d840', '0bbd380c-5cb8-46a6-8838-b5d60223c073', 15, 'Avery Schreiber', 'To make Kermit jealous, Miss Piggy instructs Scooter to tell him that Avery is in love with her. Kermit finds out that it''s all a trick, and Piggy karate-chops everybody.', '1976-12-12', 26, '/4eWL61bXoXXydRFIm2ubNesq00j.jpg', '2026-04-03T17:35:24Z', '2026-04-03T17:35:24Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('3148ae7c-1a71-4bbf-890d-1693e1640b71', '24003c6d-d919-4616-a7dd-0d38bb7a0656', 12, 'Window Dressing', 'Pat visits Oxford to help take a mannequin to a shop and dress it.', '1996-07-05', 10, NULL, '2026-04-03T17:19:37Z', '2026-04-03T17:19:37Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('3157e450-799b-4b3c-a40e-1bc151b86cd2', '8c3cfac1-d882-4904-b38c-d1981628d00e', 27, 'Episode 27', 'How does a puppet come to life? All will be revealed today when the visual effects experts from the new "Pinocchio" series stage a special demonstration in the Blue Peter studio.', '1978-12-11', NULL, NULL, '2026-04-03T17:21:54Z', '2026-04-03T17:21:54Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('315f46ea-e1bc-4e03-a46b-6550eafc39be', '4d2cac0f-38fd-438b-8afa-acf43952e535', 126, 'Episode 126', 'Introduced by Leila Williams. Packi''s Balloon Adventures: 5: England, written and drawn by Tony Hart. How to Mend a Puncture and an extract from the film Diesel Train Ride.', '1961-03-13', NULL, NULL, '2026-04-03T17:21:47Z', '2026-04-03T17:21:47Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('315fbf23-8581-4da9-862c-92aa4dcdc2b5', '42253cb1-e961-4018-8dd9-8a69e6f70873', 19, 'Episode 2244', '', NULL, NULL, NULL, '2026-04-03T17:36:37Z', '2026-04-03T17:36:37Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('31619c85-5bbd-4062-9518-d494da19b5f1', '2e6ee129-b32e-4417-9500-56f1cc9bc434', 9, 'And Still the Turtle Watched', 'LeVar discusses how people can help to preserve animals and plants in nature that are in danger of extinction. Stories profiled include scientists working to improve the bald eagle population by raising chicks and re-releasing them into the mountains, and an elementary school class that decides to plant trees in their neighborhood. Michael Ansara narrates an unusual story, told from the viewpoint of a turtle sculpture carved in a rock, and how he wishes to preserve the history of Manatoo native Americans, despite being vandalized and thought to be ignored by later generations after he was carved.', '1993-10-21', 30, NULL, '2026-04-03T17:36:18Z', '2026-04-03T17:36:18Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('3164deb0-9963-4d07-97a7-6bc9ff38bee2', '01b3a1e3-d0e8-4f2b-a56d-9d55669ab5f2', 7, 'Choosing Kids Over Kody', 'Janelle''s kids blow up and call Kody''s COVID rules "stupid." Later, at a family meeting to plan the holidays, Kody tries to persuade some of his wives to stay in town and follow his rules. Janelle walks out on him, angry and cursing.', '2022-01-02', 60, '/zumIhroHQebk4WMeWIqiBmyhd4K.jpg', '2026-04-03T16:34:32Z', '2026-04-03T16:34:32Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('31652dbb-b9ca-42bb-bbc4-341cb192e9f9', 'bbfee3b4-9c95-48a6-beaa-791fa08b1f43', 45, 'Episode 45', '', '1984-02-16', NULL, NULL, '2026-04-03T17:21:56Z', '2026-04-03T17:21:56Z');
