INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('316e9950-d0cc-48df-aba4-d561914715ec', '97a3d1f5-a8f1-47cd-8122-2e74a092836d', 23, 'Don''t Stop the Music (3)', 'Casey is accused of being the saboteur. Lenni continues to get gifts from Marlon. Lenni asks Marlon if he even knows David but he claims that he doesn''t. Lenni suspects that he and David are lying. Hector learns that Avatar is the one leaving the anonymous notes for Jade. Gaby and Tina learn that Casey isn''t the saboteur after all. A spotlight falls and nearly kills Lenni and another note is attached but this one is different from the others left by Avatar.', '1994-02-06', NULL, NULL, '2026-04-03T17:40:28Z', '2026-04-03T17:40:28Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('31739caa-bb23-496d-ad91-66b02ae78338', 'cc472916-0b8b-4498-8a9a-c5c1e7e66097', 16, 'The Real Housewives of Paris, Part Deux', 'Kyle and Lisa have a heated discussion about their friendship on top of the Eiffel Tower.', '2013-03-04', 43, '/hJklkLJpdRM0n1znQjodx43DGis.jpg', '2026-04-03T16:34:55Z', '2026-04-03T16:34:55Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('31739e31-09b0-4fbc-b3cc-5672783462e7', '991e78f1-03a5-4d26-8f75-75e11db4243c', 4, 'Noisy and Quiet: What You Can Do When Someone Wants Quiet Time', 'Rogers recounts his snorkeling adventure with Sylvia Earle, back from 1990. Sylvia Earle visits the television house, and screens a videotape on the sounds of fish. In the Neighborhood of Make-Believe, everyone is upset at the constant bell-ringing and drumming at Henrietta and X''s tree. No one can convince him to stop, especially since fewer and fewer neighbors remain uncostumed.', '1999-03-08', NULL, NULL, '2026-04-03T17:35:48Z', '2026-04-03T17:35:48Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('317770d7-df56-4524-adb8-e937fe5835df', 'd7ff9136-a833-4c43-a37c-a985a34f45a9', 19, 'Christine and David Part 1', 'Christine Brown has met the love of her life, and they are getting married!', '2024-01-07', NULL, '/ffVHKAjZ1sE0xbfnxhO3BjbXx7D.jpg', '2026-04-03T16:34:32Z', '2026-04-03T16:34:32Z');
