INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('31d6dede-db26-4fd3-a1dc-422043aab703', '48a6d3b8-3842-41da-aaec-b49a9b65f17f', 11, 'The Magic Lamp', 'Kipper finds an old bike headlight that grants every wish that he and Tiger make. They find a door behind Tiger''s wallpaper, go up a very high staircase and also go on a roller coaster that takes them to a planet where a very scary dragon lives.', '1998-12-03', 30, NULL, '2026-04-03T17:10:48Z', '2026-04-03T17:10:48Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('31d9418c-a1e1-4386-a96e-d07ac4c5f066', '787dfa0b-c827-4dad-a82d-0548a6534d88', 23, 'Brooks Tells All', 'The half-hour special delves deep and showcases never-before-seen footage from Andy''s sit down interview with Brooks Ayers, originally seen in the reunion, where Brooks addresses the ladies'' allegations regarding his health. Andy confronts Brooks on the season''s burning questions including why he avoided seeing Shannon''s doctor, why he and Vicki told different stories about his treatment, and the claim that announcing his cancer diagnosis may have been an attempt to control his damaged public image. Brooks also reveals his true feelings about each of the ladies, including Vicki''s daughter Briana, and explains why he finally ended his relationship with OC matriarch Vicki.', '2015-11-12', 44, '/ccXwMO5M9UzrobzBIhdWCgJleMv.jpg', '2026-04-03T16:35:32Z', '2026-04-03T16:35:32Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('31de044f-d52d-42fa-bf41-b38508914c3e', '05c0e384-194c-4417-9f62-803eb615e409', 5, 'The end of the first week', 'Title number 0005. Opens with Mister Rogers playing with a feather on the porch. After Mr. Rogers plays with them, Betty Aberlin takes some helium balloons to the Neighborhood of Make-Believe. Tagging them with a message of peace, she floats them above the castle. When King Friday reads the message, he ceases his efforts to stop change. The wall is taken down. Mister Rogers sings his special family bedtime song called, "Good Night, God" for the first time.', '1968-02-23', 29, NULL, '2026-04-03T17:35:38Z', '2026-04-03T17:35:38Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('31e02250-9fb3-4e9d-8309-a1bc7759cb3e', '16cbf3f2-fffd-4a78-bca3-96d05f5a2c6b', 6, 'Spar for the Course', 'After Binky wrecks the 18th hole at a miniature golf course, Muffy, Buster and Binky attempt to create a new 18th hole.', '2016-01-20', 13, NULL, '2026-04-03T17:38:01Z', '2026-04-03T17:38:01Z');
