INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('31fd8b42-6fda-4327-a12d-d8d86c7de6ed', '8b6bbac8-e5ef-49c7-a5c1-197cfb19f772', 7, 'Competition', 'Mister Rogers visits an art museum to look carefully at the various genres of paintings that are on display. In the Neighborhood of Make-Believe, Henrietta is upset when she hears that Big Bird (from Sesame Street) will visit X.', '1981-06-02', 30, NULL, '2026-04-03T17:35:42Z', '2026-04-03T17:35:42Z');
