INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('320a9ac7-3aad-4ea7-89ca-9b6d2d8078b1', '941b8c65-4454-4336-be7c-1d0591c12f90', 1, 'Pingu''s Bouncy Fun', 'Pingu is jumping up and down on his bed, which causes dishes to fall down and break from a shelf. Mother comes in and tells him to stop and makes him sit on a chair. Pingu then jumps up and down on the chair, nearly frightening Pinga, and is for the second time told not to bounce. Pingu then jumps on a cushion and then on Pinga''s rabbit! Mother takes the rabbit away from Pingu and passes it to Pinga. Father arrives and settles down to read the newspaper. He and Pingu build a makeshift trampoline, and they bounce on it. When Mother comes home, Pingu falls head first on the chair. Then they take the trampoline outside and Mother puts on crash helmets. Pingu and Father do bouncing on it.', '2003-08-01', 5, '/k2T2XssmrXYBsKbOkotOkbAYyEn.jpg', '2026-04-03T17:22:20Z', '2026-04-03T17:22:20Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('320b5cb2-7a2f-4750-8f3a-5691e9546078', 'b86d15ea-4253-41a5-9f14-4a254ec601e0', 21, 'The Real Housewives Tell All (1)', 'Never-before-seen footage, from extravagant events to bizarre antics.', '2013-10-20', 43, '/crfKdzOcCyMcxz2d8YQhKhq4Psa.jpg', '2026-04-03T16:35:16Z', '2026-04-03T16:35:16Z');
