INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('32166853-aacb-4391-81f5-018638f6e75b', '1c9ea7d3-e254-4e7b-8a9f-33eea9c6c341', 22, 'A Star Is Born', 'On the day of Kandi''s baby shower, Mama Joyce and Todd''s old feud reignites; NeNe gets the scoop on some bad press circulating about her, meanwhile Porsha has newfound issues with Kenya.', '2020-04-19', 43, NULL, '2026-04-03T16:34:49Z', '2026-04-03T16:34:49Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('32183897-0663-4a19-90c5-8bf3d12965d9', '3ee646e8-23ae-4dec-bbc6-c7e6a210d55b', 87, 'Elmo takes tap lessons', 'Elmo greets the viewer as he waits for Savion''s dance class to begin. He''s fully prepared, already wearing his tap shoes, when Savion and Jelani happen by. They inform Elmo that the lesson will be this afternoon, and they have to go to school right now.

Sponsors: R, Z, 9', '1991-03-12', NULL, NULL, '2026-04-03T17:36:38Z', '2026-04-03T17:36:38Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('3219fda5-aa9c-4319-ac03-e2e764d4d817', '6b5caa66-f66f-4ed1-817f-a00bad08790e', 8, 'Reunion: Watch What Happens (1)', 'Featuring a further look at previously unseen and explosive scenes from Teresa''s dinner party. Battle lines are drawn and friendships on the line.', '2009-06-23', 43, '/xXLHzmtTPm7psrqZw14rOmwz1a0.jpg', '2026-04-03T16:35:14Z', '2026-04-03T16:35:14Z');
