INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('322c32bb-61b7-4881-8527-7f03d7cfe2df', '5a824218-5831-4c6d-aef3-8b5ba9147532', 17, 'Episode 1592', '', NULL, NULL, NULL, '2026-04-03T17:36:34Z', '2026-04-03T17:36:34Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('324004d4-0a6c-4aaa-895c-876af280882a', 'f4d370ca-3c39-40a8-911d-e2b5e7c6b0d7', 14, 'Little Bear and the Christmas Star', 'It’s Christmas Eve and the toys have been busy decorating the Christmas tree. Everything is looking ready for Christmas but, sadly, there is no star on the top of the tree. Old Bear thinks it might be in the attic and Rabbit and Little Bear climb the tree to look. They find all sorts of things up there, but no star. After a wonderful Christmas party and Rabbit’s special magic show, they all get ready for bed. But in the night Little Bear wakes and remembers the Christmas star. He bravely decides to go and look for it. After a thrilling, snowy, night-time adventure will Little Bear get back in time for Father Christmas and will there be a star on the tree on Christmas Day?', '1997-12-24', 10, NULL, '2026-04-03T17:18:56Z', '2026-04-03T17:18:56Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('32465136-e2c2-47cc-b3da-035f349dfe86', '97616d6e-5c17-449f-a376-55f1da83d6c3', 14, 'Mister Rogers Talks About MAKE-BELIEVE', 'Mister Rogers arrives with a several different kinds of spoons which he takes to the kitchen to show. As he waits on a visit from a friend, Mister Rogers shows a film about how spoons are made. After the film Mister Rogers learns that his friend will not be arriving until a little later so he sings Let''s Think of Somthing to Do.

In the Neighborhood of Make-Believe, Lady Aberlin and Robert Troll are having a pretent tea party and King Friday provides them with some spoons. As they sip their pretend tea, King Friday recalls a time he had tea on the side of a mountain and commands Lady Aberlin and Robert Troll to create a mountain beside the castle.

Frustrated by this outlandish expectation, Lady Aberlin and Robert Troll sing Troll Talk as they seek out the assistance of some of their Neighborhood friends. In doing so, they encounter Jeffrey Shade, a baton twirler who is looking for King Friday.', '1982-06-28', NULL, NULL, '2026-04-03T17:35:42Z', '2026-04-03T17:35:42Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('324880e8-4336-4828-93ab-1d7afc4bab71', '1f34e241-4c1d-4586-921a-1c5aeb1fbbaa', 13, 'Telly doesn''t get angry', 'Oscar acts like a pirate in preparation for a bout of sailing with his pet elephants. Their ship, the S. Discontented, floats in the pool and the mast sticks out from the top of the can.

Sponsors: G, M, 6', '1985-12-04', NULL, NULL, '2026-04-03T17:36:36Z', '2026-04-03T17:36:36Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('32532356-6cb6-44eb-b89b-3c9ca17e02db', '17e6cc8e-dcf3-4ce6-97db-5a9fc8e31eb5', 3, 'High Notes and Cheap Shots', 'Kelli plans her first luxury shopping event, but Shamea and Angela''s clash feels like 1999; Drew awaits the judge''s decision on her divorce records.', '2025-03-23', 42, '/sINpadqVmjIOeh91d3nzXlMRb2s.jpg', '2026-04-03T16:34:50Z', '2026-04-03T16:34:50Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('3253bf7a-d630-4366-80d6-6e267bdbbd4a', 'ca70502b-d862-4cdd-8071-468d6644d517', 2, 'Chapter Two: Vecna''s Curse', 'A plane brings Mike to California — and a dead body brings Hawkins to a halt. Nancy goes looking for leads. A shaken Eddie tells the gang what he saw.', '2022-05-27', 78, '/lSSWqv7XrO51uY2uc4lql9Hub3f.jpg', '2026-04-03T15:40:40Z', '2026-04-03T15:40:40Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('325e41b0-6189-446b-830a-f0d76377b30f', 'f5c042dc-0657-42e8-a37d-247414140632', 17, 'Reunion (1)', 'A COVID scare keeps two of the housewives from appearing in-person; Kary drops a bomb about her marriage; Kameron brings a suitcase of evidence to try to prove that Tiffany is three-faced after going to war with her on social media.', '2021-05-04', 44, '/nZ3zRC5vCsI9bdmXUTUnAx03Knw.jpg', '2026-04-03T16:35:05Z', '2026-04-03T16:35:05Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('3261f9d4-2d75-49dc-9d01-35992875f027', '65f5abc8-0c59-497b-86e5-8c6165ee480c', 14, 'Growers and Show-ers', 'The trip to Copenhagen, Denmark, continues; Brandi confronts LeeAnne about the alcoholic accusations; D''Andra apologizes to Kameron; the ladies hit the town by land and by sea; Stephanie brokers a truce between D''Andra and LeeAnne.', '2018-11-14', NULL, '/kgBxUlDLzGEDRn61H06gVQQBm5h.jpg', '2026-04-03T16:35:04Z', '2026-04-03T16:35:04Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('3264f43b-0be5-46ef-820f-7ea8d223e109', 'ecb64ef3-4f80-45a7-b4a9-c04434b02e35', 36, 'Fiesta Loco', 'Paint the town red with the Pawn Stars when a Monet landscape brushes into the shop. Will the artwork make a bad impression on Rick or will this picture be worth a million dollars? Then, Corey feels the heat when a customer brings in an old firefighter station. Can he douse this customer''s expectations or will he get burned? And later, when Rick''s history lesson on Cinco de Mayo drives the guys loco, Rick may be uninvited to his own fiesta.', '2014-05-01', 21, '/78ptrAJwTCqqMd70naWjyjmZZoB.jpg', '2026-04-03T16:34:19Z', '2026-04-03T16:34:19Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('326a8f12-ffab-40f6-948b-6674f7ca55b7', '9193e795-da7c-40ec-b68f-f63aa7d5174f', 140, 'Histories & Lore: The Fighting Pits of Meereen', 'Daario Naharis describes the history of the fighting pits of Meereen, the different types of fights that occur there, and the lives that the more-skilled fighters lead.', '2016-03-15', 3, '/lXWX6VrOyhWct69zv3mfwHFcWVQ.jpg', '2026-04-03T15:40:35Z', '2026-04-03T15:40:35Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('326d7150-5924-4662-90cb-5e511350c076', '4b2a19e0-2fae-492e-bc31-f78e63d88ebc', 4, 'Civil War Treasures', 'Brush up on American history with the Pawn Stars and revisit some of the greatest Civil War items to ever enter the shop: a Civil War veteran''s rifle, a campaign ribbon from Lincoln''s first election in 1860, a sterling-silver flask used in the Civil War, a lap desk made by the physician who treated John Wilkes Booth - Dr. Samuel Mudd, a soldier''s engraved pocket watch, an 1864 Lincoln/Johnson campaign poster and a Confederate-era schoolbook containing mathematical problems that leave Rick puzzled.', '2016-08-17', 21, '/jvNinyam2q4Okl1NFUQgFobFfzY.jpg', '2026-04-03T16:34:20Z', '2026-04-03T16:34:20Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('326f167a-b956-4563-ac7c-77af325fcb49', '21745b85-d269-42fa-b4dd-701b2da5c085', 38, 'Episode 38', 'with John Noakes, Peter Purves, Lesley Judd', '1974-01-21', NULL, NULL, '2026-04-03T17:21:51Z', '2026-04-03T17:21:51Z');
