INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('32bbe89a-a02f-4914-bf73-5f9631e97f8f', '5a6d9a42-165b-4b56-9273-0a06874dfe10', 10, 'Madeline and the New House', 'The Old House, sorely in need of repair, is condemned and the girls are forced to move to a small apartment where their snooty neighbors hate kids and dogs. But just before the wrecking ball destroys their beloved abode, Madeline enlists the aid of the ladies of the Historical Society, who help get the Old House renovated to perfection.', '1993-10-03', 30, NULL, '2026-04-03T16:34:01Z', '2026-04-03T16:34:01Z');
