INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('32cf78ec-349b-4b72-9d62-ab3e5f9385f9', 'de8ec769-16bb-436b-be43-aedc7e18a7d7', 32, 'Big Bird''s Fairy Tale', 'Big Bird makes up a fairy tale about a bird named Birdie who helps a Beast learn how to be a good friend.', '2020-06-20', NULL, '/zvrbBMNXITVS61sbOx7zksP1CBc.jpg', '2026-04-03T17:36:50Z', '2026-04-03T17:36:50Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('32d21204-51fa-4101-93d6-c28093b8e476', '70c8cb46-2494-4dd4-98f6-6bfb9b3faf73', 25, 'Gold Diggers', 'The Pawn Stars have an opportunity to buy a huge gold bar believed to be from a 1500s shipwreck. Will the gang dig in and strike it rich or will they end up on a fool''s errand? Then Rick has a chance to shoot for the moon with a celestial navigation dome from a World War II B29 bomber. Will his offer take flight or come crashing down? And later, a woman brings a mint condition collection of golden era American League baseball field passes. Can Rick hit the deal out of the ballpark, or will he strike out looking?', '2010-06-14', 21, '/y7yKiy3tyhIBqWHYIoFT3yVBiZJ.jpg', '2026-04-03T16:34:16Z', '2026-04-03T16:34:16Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('32d5eb46-8b57-4500-ac72-5bd388fff190', '01b3a1e3-d0e8-4f2b-a56d-9d55669ab5f2', 11, 'One on One: Part 1', 'The Browns sit down individually to talk about their most contentious season yet. Kody, Christine and Meri answer burning questions about the current state of their relationships, and the rest of the family discusses the challenges brought on by COVID.', '2022-01-30', NULL, '/baB1z4lu18td4ZIPaOfgHbscCbs.jpg', '2026-04-03T16:34:32Z', '2026-04-03T16:34:32Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('32d70339-fbca-4994-bd7c-504b941e0d1e', '56428e5e-7daa-468d-8bd2-076956507aa8', 20, 'Respiration', 'How breathing supplies the body with the oxygen it needs', '1995-01-07', 26, '/uABweYf9C136DqgP8gnJCtrA9h8.jpg', '2026-04-03T17:37:21Z', '2026-04-03T17:37:21Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('32d8a2f1-e393-43a2-a7ac-f11ddcdc8604', '5144de59-e67f-4fcf-919b-7106989ab797', 20, 'Dancing Dragon', 'Skye and Kiki unwittingly invade Julie’s privacy by opening a package meant for her. Nuzzle and Sizzle cause some mischief with it.', '1995-02-10', 29, NULL, '2026-04-03T17:12:21Z', '2026-04-03T17:12:21Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('32d91ef9-5e7e-446b-857e-1458055ad9bf', '87989283-6fea-40d7-8d91-22c4947db105', 9, 'This Land Is Your Land... Or Hers?', 'Robyn, Meri and Kody have a huge fight over who will get which piece of land. Janelle worries the whole family won''t get access to the pond. Tempers flare and everyone is lashing out at everyone else in the worst fight the family has ever had.', '2020-03-01', NULL, NULL, '2026-04-03T16:34:31Z', '2026-04-03T16:34:31Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('32d974f2-2354-4831-b88b-1336b5187dd5', '4861ce46-9045-43c7-963f-27b4ea539804', 8, 'Episode 138', '', '1969-12-31', NULL, NULL, '2026-04-03T17:36:28Z', '2026-04-03T17:36:28Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('32dcb0b4-0d10-4c9b-9d1f-c37e313405fe', '73ae1459-ba91-4185-a9da-bf6f2844af49', 19, '21st Century Sonja', 'On the ladies’ last night in Cancun, Ramona addresses Dorinda’s anger issues in a group text; in New York City, Leah works to improve her relationship with her mother; Ramona sees a therapist; Luann preps for a cabaret workshop; Sonja hosts a party.', '2020-08-20', 60, '/empynKJScATt9P3eyALMl4pDDTR.jpg', '2026-04-03T16:35:25Z', '2026-04-03T16:35:25Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('32dce6ca-3dad-4ef0-af2e-4af1f3786d57', '5c4e51c6-e207-46ad-875c-72988eb1e13e', 26, 'Weird Science', 'The Pawn Stars travel to Utah for a rare shot at a 19th century Hotchkiss Revolving Cannon. A rapid-fire weapon used decisively in the Spanish American War, will Rick overwhelm the seller with an explosive offer, or will negotiations hit a turn for the worse and blow up in his face? Then, Corey and Chumlee try to get the party started, when an antique Wurlitzer jukebox grooves its way into the shop. Will the guys be able to stay in tune long enough to make a deal or will they be left singing the blues? And later, a woman comes in hoping to sell her antique medical quackery device. An electric zapping machine called a "Master Violet Ray," will this piece of weird science heal all of the shop''s problems or cause them to seek a second opinion?', '2011-08-08', 21, NULL, '2026-04-03T16:34:17Z', '2026-04-03T16:34:17Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('32e94874-6914-4d4f-a902-0d2b3daeea3f', 'ffc2a75e-0ffa-4b26-b121-9b91b277594a', 21, 'Chasing Nay-Nay', 'The ladies return to Atlanta from the Philippines and immediately get back to work. Kenya is in the midst of shooting her pilot, Life Twirls On, as Cynthia strives to perfect her accent for the role as a Jamaican salon owner. Meanwhile, Kandi and Todd attempt to go on a romantic date, but Todd drops a bomb that leaves Kandi torn. Phaedra continues to feel the rippling effect of Apollo’s absence and is inspired to throw a charity event. Things take a turn when NeNe makes a cameo from New York and exchanges words with Claudia.', '2015-04-12', 43, NULL, '2026-04-03T16:34:47Z', '2026-04-03T16:34:47Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('32f80713-902a-46b7-94c3-ea8d071574ff', '05fa5e18-78d2-41fe-ae30-0c242c7ffb6a', 25, 'Let it Snow', 'Naughty Norman has his heart set on a Christmas tree.', '2003-05-02', 10, '/skHSVe5N3x31DBLJsZyH8o8d3gV.jpg', '2026-04-03T17:14:38Z', '2026-04-03T17:14:38Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('32f88e79-e045-4b94-b3a2-2afc7a98e827', 'e8981e01-407b-4ef7-b809-3b5f30b5248d', 2, 'Mortyplicity', 'Who''s even real, broh? Are you real? Broh?', '2021-06-27', 22, '/wzKkvUbWMso3bceAwJRXDDdMzNI.jpg', '2026-04-03T15:40:42Z', '2026-04-03T15:40:42Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('32fd9a63-f928-4403-949d-ce978bdaa89c', 'a6ed03e0-c05f-48f8-9f56-3f1da50e1792', 3, 'Episode 1318', '', '1979-11-28', NULL, NULL, '2026-04-03T17:36:33Z', '2026-04-03T17:36:33Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('330aef44-ec64-4a5b-b357-d240b56f4d5a', '136b81d3-964d-4b8f-a214-92f00d96d6b9', 80, 'A day at the library with Don Music', 'Don Music grows increasingly frustrated at the library as he struggles to complete a song, each attempt ending in failure and disappointment. Big Bird and the helpful librarian offer encouragement and remind him to relax. With their support and a fresh perspective, Don Music finally overcomes his writer''s block and finishes his beautiful composition.

Sponsors: E, S, 4', '1984-03-09', NULL, NULL, '2026-04-03T17:36:35Z', '2026-04-03T17:36:35Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('330d0c1b-2113-4c38-979f-6bae5dcb8c11', '1f34e241-4c1d-4586-921a-1c5aeb1fbbaa', 49, 'Big Bird practices magic', 'Maria and Luis welcome the viewer in Spanish, then Big Bird - or rather, "The Amazing Birdford," greets them. Big Bird has borrowed the Amazing Mumford''s magic kit and is learning how to become a magician. Susan sets three new plants on her window sill.

Sponsors: P, R, 3', '1986-01-23', NULL, NULL, '2026-04-03T17:36:36Z', '2026-04-03T17:36:36Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('330d69b3-dad6-4899-82c0-ef7e89a00e6c', '208e80de-61e3-4a2f-857f-c667ffc29134', 21, 'Doug Henning', 'Fozzie Bear tries out a magic act, pulling a rabbit from a hat. Instead, he gets a rabbi, and then a robot. He taps the hat too hard, and gets dozens of rabbits, who follow him around and call him "Daddy."', '1980-03-14', 26, '/2BE3lTewbyPaCK9R45XGSX9PdcH.jpg', '2026-04-03T17:35:25Z', '2026-04-03T17:35:25Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('330e116e-aee2-499a-aca7-6c0f05b712ab', 'ec8d3322-8ca2-4e8d-9d22-268aee320274', 5, 'Everything From Pawn to Nuts', 'A seller comes into the shop with some chef whites signed by the actor who played the iconic Soup Nazi on Seinfeld. Will Rick and Chum say `No deal'' for you or will they reach an agreement on price?', '2025-02-26', 42, '/eaTYYAMRipSHqOOxXWtw8xiGZ4p.jpg', '2026-04-03T16:34:24Z', '2026-04-03T16:34:24Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('331dfc3b-2ab1-4d9a-8f7c-e04bb34cfc2f', '05c0e384-194c-4417-9f62-803eb615e409', 103, 'Roller skates', 'Rogers talks of playing with toys and reads the poem of The Land of Counterpane by Robert Louis Stevenson. In the Neighborhood of Make-Believe, Tadpole Frogg and Lady Aberlin pretend to roller skate. Lady Aberlin finds out that King Friday and Sara Saturday are in the R Room of the Castle.', '1968-07-10', NULL, NULL, '2026-04-03T17:35:38Z', '2026-04-03T17:35:38Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('33212414-9c07-4f47-aee4-bfcb462a0b40', '5a4e38a1-8e54-4974-8097-d7a7b48630a2', 76, 'Episode 76', 'with Valerie Singleton, John Noakes, Peter Purves', '1971-06-18', NULL, NULL, '2026-04-03T17:21:50Z', '2026-04-03T17:21:50Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('332bb171-85b3-4d3b-8808-3f791b844c53', '98d80972-e53a-43dd-a03a-7703465e6f87', 26, 'Just Shoe It', 'Get your kicks with the Pawn Stars as Rick and Chumlee check out a massive collection of Nike shoes. With an asking price of $1 million, is this deal a slam dunk or an air ball? Then, an Arnold & Son longitude watch finds its way into the shop. Used for navigation on ships since the 1700''s, will Rick offer a boatload for this rare timepiece? And later, Corey and Chumlee eye a vintage handcuff collection. Featuring some of the most painful, and illegal, restraint devices ever made, do the guys try to lock this deal up, or does something rub them the wrong way.', '2013-02-11', 21, NULL, '2026-04-03T16:34:18Z', '2026-04-03T16:34:18Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('332dd56c-3233-4493-9ecd-e09e82a35c67', '1a534647-384b-4c00-bb6c-a3371ad962eb', 19, 'Son of a Gun', 'Get fired up with the Pawn Stars when a 1800s Wilkinson turret rifle shoots into the shop. Will Rick go in guns blazing or will he fail to pull the trigger? Then, Chum buckles up when celebrity engraved matchboxes from the private jet, "The Starship One" flies in. Will he be able to land these collectibles or will the price be plane crazy? And later, Chumlee volunteers to help the guys write descriptive cards for the shop. Will he get his facts straight or will he need a history lesson?', '2015-03-19', 21, '/nJ6WaG8j9B0HzYPMXMoJbzPuzvk.jpg', '2026-04-03T16:34:19Z', '2026-04-03T16:34:19Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('332de7a7-4aff-46f9-baae-318ca60900ea', 'f1959b84-1930-4f85-b2fd-9000b3abf48a', 6, 'Episode 785', '', NULL, NULL, NULL, '2026-04-03T17:36:40Z', '2026-04-03T17:36:40Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('333348a5-4d07-46dd-b796-7b85e5793019', 'dec4a06d-731b-41e4-8b15-374f47d1f5c7', 2, 'A Very Hairy Christmas', 'Melissa hosts a Christmas Eve dinner, during which she reunites with Teresa; Jacqueline gets a surprise call from Teresa as Dolores attempts to reconcile the two former friends; Joe Giudice and Gia are at odds over her New Year''s Eve plans.', '2016-07-17', 43, '/1PIkM8uEoLmw0i90K3pmRQCXHWJ.jpg', '2026-04-03T16:35:16Z', '2026-04-03T16:35:16Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('33349ef4-521d-4ec6-840e-d4173a1327d9', '97a3d1f5-a8f1-47cd-8122-2e74a092836d', 9, 'Just in Time (1)', 'Ghostwriter travels back in time to the 1920''s before the Ghostwriter team existed. There he learns of a young boy named Frank who''s living with a foster family named the Camilans. Frank is accused of stealing a priceless tea set. Nobody believes Frank except his best friend Catherine.', '1993-10-31', NULL, NULL, '2026-04-03T17:40:28Z', '2026-04-03T17:40:28Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('33372443-0a2b-4ce6-8591-cde46fc61257', '119c16d5-1047-45ec-8242-c72a8eed423b', 45, 'Bully for Binky', 'Binky is the toughest kid in school and everyone is afraid of him.', '1996-11-06', 13, NULL, '2026-04-03T17:37:55Z', '2026-04-03T17:37:55Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('333ddd8b-62dd-47b6-a1e9-9459d3369be3', '7b8e3988-fbf3-4cfc-aeb2-782ae5a64e2d', 9, 'Bert’s Pigeon Search', 'Leela fixes Elmo and Abby''s rocket and they begin playing spaceship, making "brr brr" sounds for their rocket. Bert rushes in, thinking he''s heard a blue-bar pigeon. He shows them his Pigeon Life List, featuring seven different varieties of pigeons. He has a check for each one, except a blue-bar. Upset, he leaves for home. The two decide to help Bert out by finding the pigeon for him. Abby magically whips up some safari gear and they use their binoculars to look for a bird. They see one in the distance and go to him.', '2010-10-12', NULL, '/vW2OlTna7B0U61xnlwn2guQxkJl.jpg', '2026-04-03T17:36:46Z', '2026-04-03T17:36:46Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('334100e9-620e-4488-a035-efc7d8c65e53', '46d7a706-c7a8-4ebe-b96f-387c66e8bb8b', 6, 'Episode 1451', '', '1980-12-01', NULL, NULL, '2026-04-03T17:36:34Z', '2026-04-03T17:36:34Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('3342f947-5a73-4b9b-b5b6-d5ca22933496', '1415ef1c-411a-4c26-814a-7c79c3628bc2', 19, 'Thank You and Good Night', 'After moving out of Sonja’s townhouse, Tinsley has Carole over to see her new digs. Luann and Tom challenge each other during a game of tennis. Bethenny deals with the stresses of renovating a new apartment, but finds distraction with a hot, new fling. Dorinda has John over for a romantic dinner, while Sonja and Frenchie talk about their upcoming trip to France together. The ladies all come together when Tinsley throws a thank you party for Sonja.', '2017-08-09', 60, '/xValwsSz9TKX0fQjNjGzW9RRnxI.jpg', '2026-04-03T16:35:24Z', '2026-04-03T16:35:24Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('3344c1a2-f7c5-4d7e-96c3-f91af64dd7d4', '150d1480-f3f1-43f9-9a22-d2527756fba2', 4, 'Going Ham at the Pajammy Jam', 'Mia and Gordon wonder if she can repair the broken relationship with her mother; Gizelle works on showing compassion when her oldest daughter goes through a life obstacle; Michael surprises his very pregnant wife, Ashley, with a new venture.', '2021-08-01', 42, '/sT9ussrFMiCZ2Qvs8eJVFokWdZU.jpg', '2026-04-03T16:35:40Z', '2026-04-03T16:35:40Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('3349e00c-acbe-4401-a3aa-c0cc8a6195fc', 'cc140989-c480-4586-b460-8872b416a0b7', 2, 'Stay Away from the Junkyard!', 'LeVar decides it''s time to clean out the things cluttering up his house. What he finds is only memories of his entire life. None of this is junk, as it turns out. Michelle Mariano reads the story of a young girl visiting relatives who befriends the local junkyard manager, even though the rest of the town avoids him and spreads rumors.', '1989-07-04', 30, NULL, '2026-04-03T17:36:17Z', '2026-04-03T17:36:17Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('33598729-5fd7-44ee-817e-c7072a29acd5', 'a8facd21-e786-4fff-b89f-7eb83eba2231', 16, 'Episode 555', '', NULL, NULL, NULL, '2026-04-03T17:36:37Z', '2026-04-03T17:36:37Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('335a4e8b-0c86-486d-88ee-9fa1aca0c8cd', '20d7138e-eea8-46a8-8ada-2b0f0ee1f674', 19, 'Episode 19', 'Today Simon, Sarah and Peter make their most important announcement of the year-so have paper and pencil handy for details of the 1982 Appeal and find out what Blue Peter is collecting this year and how you can help.', '1982-11-15', NULL, NULL, '2026-04-03T17:21:56Z', '2026-04-03T17:21:56Z');
