INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('3362babb-b46a-45e7-bc26-56a02281d671', 'acac417e-2aa3-42e7-9e08-ed0d6071a3ee', 12, 'Every Mayflower Has Its Thorn', 'Luann gets out of rehab and the ladies whisk her away for a spa weekend in Connecticut; the relaxation doesn''t last long as Luann discovers that Ramona tried to get an invite to Tom''s New Year''s Eve party; Dorinda and Sonja clash over a family crest.', '2018-06-20', 44, '/h8o8BxHUD8AzWOV2DuuyVfN9BHD.jpg', '2026-04-03T16:35:25Z', '2026-04-03T16:35:25Z');
