INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('336fa970-404b-4ce3-ad23-720174380075', '5db3ff78-e439-48e1-8f67-988ecbf85d17', 7, 'Dogtanian Meets the King', 'All the guns in a man''s shop are stolen by le Faucon Bleu, the worst & most notorious thief and pirate in Europe. He leaves a message "Watch out tonight danger is near, for I have come to Paris", a musketeer rides through the streets telling people to lock their doors. That night only the Police, Guards and Musketeers dare to go out, even Dogtanian has locked up the house. Outside the city the Blue Falcon and his gang of thieves are scheming, the Blue Falcon scales the city''s wall to put his plan into action...', '1981-11-20', 24, '/zVe8rL9Cb836ZNHjljFayGOEik5.jpg', '2026-04-03T17:18:43Z', '2026-04-03T17:18:43Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('33761156-102d-4768-91a6-147bbe1fd43e', '02849655-bd95-4d8d-af3b-03321918eeee', 3, 'Madeline and the Can Can Cliques', 'While she and the other girls learn to dance the Can Can, eleven little girls form two cliques, and Madeline is caught in the middle, much to her dismay.', '2000-09-22', 30, NULL, '2026-04-03T16:34:02Z', '2026-04-03T16:34:02Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('3384dfa2-e2ff-4016-911d-85beae193fb8', '61e0c9d9-337e-4fe4-a0fd-e567b29af115', 13, 'Rooms for Improvement', 'There is trouble in paradise as the ladies embark on their trip to Puerto Vallarta. Angie feels slighted after Meredith''s bat mitzvah. Bronwyn and Lisa have a falling out over room assignments. Mary chooses to stay in Salt Lake City as issues with Robert Jr. come to a head. Britani makes a new announcement. Bronwyn comes to terms with Gwen''s decision about her grandparents.', '2024-12-11', 43, '/awyDgTsJ1XLIWMiLhKq58DupMLA.jpg', '2026-04-03T16:35:45Z', '2026-04-03T16:35:45Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('33869d02-05b1-4414-8020-9236a5873d93', 'f4c40307-9b5e-4263-a4e0-dfa138131e7f', 14, 'Kids'' Favorite Songs', 'Kids'' Favorite Songs kicks off with a cackle-worthy parody of Bob Dylan doing "Old McDonald," and from there the groovy gags keep comin'' ''round the mountain. Everywhere Elmo turns on Sesame Street monsters spontaneously burst into song, and all because they want him to feature their favorite tunes on his forthcoming radio countdown. For Telly, winnowing the hits to one is akin to Cookie Monster choosing between a macaroon and a figgie bar: at first he''s sure that "Twinkle Twinkle Little Star" lights his fire, but then he says bye-bye to a black sheep. The street heaves a collective sigh pavementward when word comes down that the countdown is strictly a numbers gig, no music involved. Only Sesame Street could weave well-loved musical numbers around a simple numbers lesson with such wacky pizzazz, making this a countdown that''s no letdown for high-spirited parent-preschooler combos.', NULL, NULL, NULL, '2026-04-03T17:36:27Z', '2026-04-03T17:36:27Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('338f20cf-bcaf-41b8-be8c-d5d59b3ddd68', 'f812042d-eb85-432e-8047-3675886e0b1b', 13, 'Sniffing the Gauntlet', 'Keeping oneself in the right frame of mind, Wishbone draws into Rebecca''s world in Ivanhoe.', '1995-04-06', 28, '/zjj4VBdoRUOfw9FPhSzZK2dBUYI.jpg', '2026-04-03T17:10:42Z', '2026-04-03T17:10:42Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('338f9e33-1b07-45b2-b884-4f428c5aed05', '19e027c7-8626-44a9-96ba-d36b323b3a74', 6, 'The Preachification of Convincing John', 'Mokey decides that eating Doozer constructions hurts their feelings, so she gets Convincing John to help her get the Fraggles to stop.', '1983-02-14', 24, '/yi5HbYJzjMwwtA1AVOQcPdToyxB.jpg', '2026-04-03T17:34:59Z', '2026-04-03T17:34:59Z');
