INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('33e0cae8-1b7e-4fa1-a014-99849071e488', '3af7ea64-fa13-4097-b8e4-40af07083054', 5, 'The Circus coming to Make Believe [1330]', 'Elsie Neal brings a decoration she made from horse chestnuts. Later Ezra Jack Keats, returned from Japan, visits Rogers. The Neighborhood of Make-Believe invites the circus from Westwood.', '1974-02-22', 28, NULL, '2026-04-03T17:35:40Z', '2026-04-03T17:35:40Z');
