INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('33ee2dfe-cf0e-4e75-bda5-074d9490723e', '208e80de-61e3-4a2f-857f-c667ffc29134', 1, 'Dudley Moore', 'Dudley has a surprise for Kermit, a robot that can do the work of the entire band and of course the Electric Mayhem feel threatened by this fact.', '1979-10-24', 26, '/7wZQjPoJnJCKK7tP2LAyCE5ceCW.jpg', '2026-04-03T17:35:25Z', '2026-04-03T17:35:25Z');
