INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('34d11ff1-140f-4990-b551-5a2497678de9', 'e4023da2-33d7-4a2b-a04a-ca449bd23935', 20, 'Food Courting', 'A case of disrespect hits the Heck boys when Axl -- who is celebrating his milestone 21st birthday -- refuses to come home and help Mike move an old freezer, and Brick begins turning into a mini-Axl by dissing Frankie with a bad attitude. Meanwhile, Sue is torn over what to do when the manager of Chop Suey USA tries to woo her away from her job at Spudsy''s.', '2015-04-15', 22, '/rP1wlhWqMh1hrxN3T7wI5uipgq6.jpg', '2026-04-03T15:40:30Z', '2026-04-03T15:40:30Z');
