INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('350e204e-c3da-4219-bf80-14ac5580234f', 'fe19a277-aed8-44df-a4ac-fc1c4e9941b4', 7, 'Throwing Shade', 'It’s showtime for Lisa! With the debut of her clothing line Closet Freak, she is all business, trying to get everything done in time. Meanwhile, Sheree finds out that her She By Sheree fashion line debut will have to wait , yet again. NeNe gets tough on her college dropout son Brice, and Kandi calls in a favor to flip "Tardy for the Party" into a song for Kim and NeNe to record. Kim gets serious about launching her wig line, and does a little research by throwing a wig party.', '2009-09-10', 43, NULL, '2026-04-03T16:34:45Z', '2026-04-03T16:34:45Z');
