INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('354ba0d0-00fa-4471-9404-746edd05b3e7', '5b5e8b2f-0a85-4488-b3dc-3d8b794e6582', 14, 'Armenian Rhapsody', 'Vicki and Tamra finally come face-to-face to see if there is any hope of redeeming their broken friendship. Lydia discovers the joys of when the rich get richer. Kelly''s dad comes to town and she discovers the parallels between her parent''s dysfunctional relationship and her own. Peggy and Diko celebrate their 22nd wedding anniversary with the ultimate Armenian inspired party while Shannon faces the consequences of her prying husband''s actions.', '2017-10-09', 44, '/5BbIFOWQAqqAmWHKzD2y00PTqJ3.jpg', '2026-04-03T16:35:33Z', '2026-04-03T16:35:33Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('3555136d-e036-46a6-a6d6-e51b09d07bee', '35ebddbb-977f-4aac-8aa4-55560de6d4b8', 5, 'Episode 5', '', '2006-05-01', 25, NULL, '2026-04-03T17:21:20Z', '2026-04-03T17:21:20Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('35584ee1-6b2e-4d85-a3db-5689d0175c4c', 'ea1650c2-e4f1-46c7-93ba-74b5d45d08e5', 3, 'White Hot', 'Kandi travels to Palm Springs to offer advice and support to Kim, who’s been invited to perform at one of the biggest gay circuit parties –- the White Party. With only one song on her playlist is Kim ready for her first concert appearance? NeNe has an honest talk with Brentt about Brice''s brush with the law. After Sheree takes the high road with Dwight and his claims to have paid for the She By Sheree fashion show last year she reunites with her oldest daughter, Tierra who has moved back to Atlanta after being away at college. New housewife Cynthia struggles with her feelings about marriage, while Phaedra and Apollo don’t see eye to eye when it comes to parenting.', '2010-10-18', 43, '/2iTfdIFzn9Yz0aXmdWHNf0owrtS.jpg', '2026-04-03T16:34:45Z', '2026-04-03T16:34:45Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('355900c2-38a7-416d-ba0b-c4b5a259be2c', 'bf722849-cddb-452b-9c0f-7f0d96e94c26', 7, 'Friendship', 'When Annie’s "new best friend" breaks her promise and chooses someone else to be her partner on a canoe trip, Annie’s feelings are hurt, provoking a discussion about the meaning of true friendship.', '1997-02-09', 30, NULL, '2026-04-03T17:38:34Z', '2026-04-03T17:38:34Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('3562754e-8205-4c63-bf5c-f92d1e9cf28b', 'edc63a59-2fd4-442a-9343-f2872d776bdc', 7, 'The Rhythm and Roots of Arthur', 'Pack your bags, buckle your seatbelts, and get ready for an ARTHUR road trip to the family farm! Arthur''s Great-Grand Uncle Theo is celebrating his 85th birthday, so the Reads (and Buster) are off to Ohio to join in the festivities. While D.W. and Arthur learn that farm life is a little different than life in Elwood City, Buster worries he may be getting in the way at this family reunion. With the help of Cousin Miles, some llamas, and a little bit of music, they all discover what it truly means to be family.', '2020-01-20', 55, NULL, '2026-04-03T17:37:54Z', '2026-04-03T17:37:54Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('3565a328-c8d3-47a3-aa38-38a5230baa5a', '9e30a416-edbd-490b-bb0f-18d5c45f0bdf', 9, 'Guess Who''s Coming to Dinner?', 'When Lisa hosts a dinner at SUR to mend things with Joyce, things go worse than her last meal with "The Dream Team."', '2013-12-30', 42, '/aIvCelTIEF4lExUbWXcpbA9caLM.jpg', '2026-04-03T16:34:55Z', '2026-04-03T16:34:55Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('356ba977-fcaa-420d-9cd0-68dd6f060752', '42684fca-0bc7-4f4c-bf7d-f41fd288a764', 5, 'Postman Pat and the Jumble Sale', 'It is National Recycling Week and Nisha is organizing a jumble sale.', '2004-09-14', 15, '/bo1ovsWJzbHr189EQGnD3ZeCPvf.jpg', '2026-04-03T17:14:30Z', '2026-04-03T17:14:30Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('356f314c-1713-40ab-937e-26a2a228935f', '7bc54df3-f32a-454e-aef6-a9436c35d53b', 34, 'Episode 34', 'King Friday hears about the baby platypus that will emerge soon. He tries to make the Platypus family leave the Neighborhood of Make-Believe so that his new baby will be the first born there.', '1970-03-19', NULL, NULL, '2026-04-03T17:35:39Z', '2026-04-03T17:35:39Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('35717463-41ca-4af8-83e9-85ffa757c690', '871570b4-bf2f-4ba1-9940-65fb932cb009', 5, 'Where Is the Love Boat', 'A booze cruise turns dramatic when an argument between Cynthia and Porsha escalates. Back on land, the group continues to clash over the events. Meanwhile, Kandi visits the doctor and faces troubling news, and the ladies try to unite.', '2015-12-06', 43, NULL, '2026-04-03T16:34:47Z', '2026-04-03T16:34:47Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('3571ca11-b33a-409e-972f-7b3440524906', '02c86ae3-8c3b-4cc0-8e1f-0b27d01dcd91', 3, 'Who''s Your Poppa?', 'The ladies take a trip to the countryside to meet with Kim''s psychic advisor. After an eerie prediction of personal strife ahead, NeNe gets a letter from a family member revealing that the man who she thought was her father might not be. She must decide whether or not to pursue the paternity issue and risk opening Pandora''s box. Meanwhile, Kim has always wanted to be a country singer and decides now is the perfect time to pursue her dream. DeShawn must pull off planning a black tie gala for the DeShawn Snow Foundation in just two weeks. NeNe decides to help her and together they try to raise a million dollars for charity during the gala.', '2008-10-21', 43, NULL, '2026-04-03T16:34:44Z', '2026-04-03T16:34:44Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('3573ab23-c335-4adb-bea7-49e0b0524f9a', 'de8ec769-16bb-436b-be43-aedc7e18a7d7', 26, 'Back to Nature', 'Abby and Rudy want to bring nature inside Hooper''s so Chris can feel like he’s outside. Abby uses her mom’s magic wand but makes a mistake and fills Hooper’s with too many animals and plants. Abby apologizes for using her mom’s wand without permission and together, with her mom, she learns how to fix her mistake without using magic.', '2020-05-09', NULL, '/4DyhPfABHXsO5Xfzs0VZbJk0brJ.jpg', '2026-04-03T17:36:50Z', '2026-04-03T17:36:50Z');
