INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('35d5cbb6-ce8f-4c03-a753-bb2c8d5e4943', '227b8429-0dfd-47e4-b874-c37da20c403f', 22, 'Pawn Shop Pinot', 'When Rick and the Old Man buy an antique 19th Century wine-maker, Chumlee wants to put it into action. Will he succeed and brew a magnificent "Pawn Shop Pinot"? The Pawn Stars also consider buying a 16th Century replica signal cannon used to call ships as Rick looks at the priciest pawn ever to enter the shop - a semi truck.', '2009-12-21', 21, '/qNunJlOJe4dfBefdLDo1NB1cQFx.jpg', '2026-04-03T16:34:15Z', '2026-04-03T16:34:15Z');
