INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('36992808-2048-4281-a093-055390affe2a', '01b3a1e3-d0e8-4f2b-a56d-9d55669ab5f2', 3, 'Not Social but Very Distant', 'The wives come to a major decision about the property lots. Christine is leaving to take Ysabel to New Jersey for surgery, but Kody''s refusal to go leaves Christine angry. Then, a member of the family has a big announcement.', '2021-12-05', 61, '/fpNEeng3FzSsM8teyZWDP90846D.jpg', '2026-04-03T16:34:32Z', '2026-04-03T16:34:32Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('369a7040-960b-4e2a-bbde-9eab0a86944c', '40700e8a-1dce-4895-bede-522a13a8bcad', 24, 'World of Legs', 'Zoboo spies a larva and wonders what kind of legs this animal will have once it grows. Will it have strong legs like a tiger, hundreds of legs like a millipede or long ones like a kangaroo? When the larva finally transforms into a salamander, its legs are like nothing Zoboo imagined they would be!', '2001-06-01', 27, NULL, '2026-04-03T17:10:55Z', '2026-04-03T17:10:55Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('369ee46a-d4fe-4242-beac-d6d368805192', '740a96a0-a075-4be2-be92-a178d0939384', 22, 'The Helpful Cloud', 'Elmo and Grover help Floatie the Cloud try to find a job on Sesame Street; Chris helps Floatie realize that she already has an important job by bringing rain to help plants and flowers grow and giving shade to keep everyone cool on hot, sunny days.', '2018-04-14', NULL, '/fIN3jjwiddRoCB4uDEilqOofPWP.jpg', '2026-04-03T17:36:49Z', '2026-04-03T17:36:49Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('369f3f98-e39e-4d4d-9a58-6746037c0043', '244b0a34-284b-4ec1-b3a7-0e5abff6d0d1', 10, 'When Carl met George', 'George is excited about spending time with his new friend Carl, who seems to know all kind of cool facts about trains and about... well lots of things! Then George learns that Carl has Asperger''s Syndrome - a form of autism that makes Carl see the world differently than most people.', '2010-04-05', 13, NULL, '2026-04-03T17:37:59Z', '2026-04-03T17:37:59Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('36a8aa2b-9933-41f3-ab8b-4bdd668345ac', '0bbd380c-5cb8-46a6-8838-b5d60223c073', 17, 'Valerie Harper', 'This is one of only a few Muppet Show episodes that open the show after the theme song with some kind of offstage scene. There''s also a couple of scenes with the guest star in her dressing room conversing with Muppets instead of onstage in the Talk Spot. In last week''s "At The Dance", Boppity danced in drag with another monster. This week Boppity appears as normal but his partner is in drag. In both instances, he ends up headless.', '1977-01-02', 26, '/x0sfeFUyVRuGopIB1MBvJRYSCpC.jpg', '2026-04-03T17:35:24Z', '2026-04-03T17:35:24Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('36aa4e69-1eee-43ac-b714-3793ea432521', '54facb0b-db59-41fe-9d64-c7c7221a3c81', 18, 'Reunion (1)', 'The ladies discuss how Bethenny dealt with the death of her boyfriend; the women give updates on their new living situations; Bethenny argues with Luann; Dorinda and Luann finally address their issues, leveling accusations and shedding tears.', '2019-07-10', 60, '/Amf2c1NKygrgPvsd1CEI21NoKtJ.jpg', '2026-04-03T16:35:25Z', '2026-04-03T16:35:25Z');
