INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('36b0bccc-f375-4942-b3e4-4a00c03d27c4', 'e6254ae4-7d72-493b-8b37-b677d8b76c46', 74, 'Episode 739', '', '1975-02-13', NULL, NULL, '2026-04-03T17:36:31Z', '2026-04-03T17:36:31Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('36b17e24-d6a3-43a9-8b40-e59e1d4b39ec', '98d80972-e53a-43dd-a03a-7703465e6f87', 20, 'Spare the Rodman', 'The Pawn Stars get a fast break when the ex-wife of NBA star Dennis Rodman drops by. Trying to sell a collection of Rodman''s signed jerseys, will the guys jump at the chance to own a piece of sports history, or will heightened emotions cause them to foul out? Then, Rick and Chumlee prepare to flee when they''re presented with a jury questionnaire from the O.J. Simpson trial. Do they vote unanimously to buy, or is the jury still out? And later, a BMC pedal tractor from the 1950s plows into the shop. Will the guys make hay while the sun shines, or put this relic out to pasture?', '2013-01-21', 21, NULL, '2026-04-03T16:34:18Z', '2026-04-03T16:34:18Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('36b1911c-d586-4639-906b-0d5c3fdd98e6', 'bb9a568b-5bcf-4cb2-846e-3a7a46a8ed55', 7, 'Space Sandwich', '', '2020-10-30', 10, '/reXIhV5h3F3y7U0vEH0K1G2YmKk.jpg', '2026-04-03T17:14:41Z', '2026-04-03T17:14:41Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('36b2b44e-53e5-4db4-bea7-d01297b2024e', '6ef86c27-33e7-47e5-a053-483059dfd16d', 49, 'Episode 49', 'Scruffy or sharp? Tatty or trendy? What''s your verdict on Peter''s clothes? No one seems to agree on what suits him best, so now''s your chance to design the ideal outfit!', '1982-03-04', NULL, NULL, '2026-04-03T17:21:55Z', '2026-04-03T17:21:55Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('36b9d19d-7324-4053-b8ac-16ba605644ed', 'bcab920a-51a5-4cbb-aa59-41578a0eb005', 21, 'Reunion (3)', 'As the reunion comes to a close, all the harsh feelings force the women to evaluate the bonds they have forged over the years. Lisa Vanderpump gets surprisingly emotional when discussing her son and her crusade to save dogs. Lisa Rinna and Kim Richards attempt to see eye-to-eye, while Kyle decides to dive into the fray.', '2017-04-25', 43, '/t4uR23ERgqv75W1LauBB2kUKyVZ.jpg', '2026-04-03T16:34:56Z', '2026-04-03T16:34:56Z');
