INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('36c0bd6d-03c2-4637-aa3c-55a8d2c9e88b', 'f30bbf81-8770-4e74-b68b-280e7c85b52f', 7, 'The Revenge', 'George quits his job in a huff after he is demoted to using the regular bathroom. Newman tells Kramer that he plans to jump off the building. Jerry suggests that George just go back into work next Monday morning and pretend like nothing happened; however, that doesn''t work. Newman jumps, from the second floor. George plots revenge, and with Elaine''s help, tries to slip his boss "a Mickey." Jerry suspects that his launderer is a larcenist after he discovers that $1500 he had stashed in his laundry bag is missing. Kramer helps Jerry get revenge by bringing a bag of concrete in to put into one of the wash machines.', '1991-04-18', 23, '/pQZDgs2VmFxBIBLQlrm02kft6hV.jpg', '2026-04-03T16:34:09Z', '2026-04-03T16:34:09Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('36c2a261-a013-4b4b-b9fd-78a4215bf380', 'd123fd65-efb7-4ebb-a23e-190c447791cf', 12, 'No Wedding and a Funeral', 'Alexia''s Bachelorette party ends with a guest leaving the table in a huff; Larsa finally signs her divorce papers, as her mothers health takes a turn for the worse. Alexia''s dream wedding day begins to crumble.', '2022-02-24', 44, '/12rG71TPIs31J1TKR47vPDAnepF.jpg', '2026-04-03T16:35:11Z', '2026-04-03T16:35:11Z');
