INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('36d3d28b-c77d-4280-a161-68e6248fc0e1', '5a771f52-fe96-4ea2-b567-a8dde899059e', 12, 'The Devil Went Down to Vegas', 'The Pawn Stars dive right in with a folding bike used by paratroopers during WWII. Will they stick the landing or collapse under pressure? An antique German clock winds up in front of Corey. Will he chime in with a good offer? A fiddle signed by "The Devil Went Down to Georgia" singer Charlie Daniels puts Rick in a bind, ''cause he''s way behind - is he willing to make a deal? Later, Rick tries to dig himself out of a hole when an old miner''s self-rescuer falls into the store.', '2017-11-20', 21, '/wVQb3fMY3xZ1Od12xdlGgoK922T.jpg', '2026-04-03T16:34:21Z', '2026-04-03T16:34:21Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('36d46d0a-2409-4a05-952b-44b87e079c83', '6a2d2839-7106-4c3b-8906-c9b3e4bfcc8b', 16, 'Bali Highs & Lows', 'Balinese bliss becomes a rumble in the jungle when the ladies set out on a trip to Bali. Heather and Shannon hope for peace and relaxation, but things escalate when Shannon gets some shocking news. Meanwhile, Vicki hears about a scandalous statement allegedly made at the Valentine''s Day dinner and Lizzie reveals her true thoughts about Tamra.', '2014-08-11', 44, NULL, '2026-04-03T16:35:32Z', '2026-04-03T16:35:32Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('36e08c35-ccdb-4f7e-870c-1fb81f147a06', 'bb919aec-0d5c-4c58-9a5a-fa2a0a5de2b6', 22, 'Episode 427', '', NULL, NULL, NULL, '2026-04-03T17:36:29Z', '2026-04-03T17:36:29Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('36e45057-7c53-4d79-b2de-dd96f855e059', '79c64e0a-3488-41bc-9b5c-2243ff15b373', 4, 'A Housewives Heatwave', 'Sutton plans a trip to Sedona, where she hopes to show the group how much she’s changed. Rachel opens up about life as a boy mom. Kathy hosts a summertime dinner where Amanda talks her way into the hot seat. Dorit looks to Kyle for support while navigating her separation, but both women decide there’s a better man for the job. Boz takes another shot at her fertility journey. Erika reveals she has a new love interest.', '2026-01-08', NULL, '/fupHfszrapSGH96kYuLUAXgcmuW.jpg', '2026-04-03T16:34:59Z', '2026-04-03T16:34:59Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('36e70a9a-090f-4a57-8c70-869c1e4fbe1c', '6e314631-d72b-4ebd-bf39-d123d19108fc', 10, 'Pets', '', NULL, NULL, NULL, '2026-04-03T17:20:13Z', '2026-04-03T17:20:13Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('36e876c5-2f0a-42f8-a67b-1c45d86091c0', 'ecdefd77-a7ac-4344-bea1-fb1df2fd0ac9', 10, 'What''s Time For?', 'The Postman needs Bernard''s help to handle a mischievous young watch-holder, Harry Claymore, who keeps causing problems for everyone.', '2001-12-07', 15, NULL, '2026-04-03T17:20:05Z', '2026-04-03T17:20:05Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('36f61806-cb05-4993-965a-9038f71f69a5', '18da9943-1963-4e04-a7a0-ae63802bb1fa', 16, 'Twin Tweaks', 'Vicki and Shannon proceed with dueling plastic surgeries; Emily and Shane attend couples therapy and face a painful memory; Gina gets herself in hot water with Tamra after she confesses to Shannon about what the ladies were saying behind her back.', '2018-11-05', 44, NULL, '2026-04-03T16:35:34Z', '2026-04-03T16:35:34Z');
