INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('3706e4bb-d456-4044-932f-0c1851b41b56', '6fedba82-52f3-4184-be77-6b26e556cd0e', 23, 'Paddington Makes a Clean Sweep', 'The misadventures of Paddington as he cleans a chimney.', '1976-05-11', NULL, NULL, '2026-04-03T17:22:52Z', '2026-04-03T17:22:52Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('370a044d-47c8-4881-889a-3434fefba529', '58adb9ab-3f1b-4a11-87b6-9b0b2dbb6aaf', 9, 'Pawning Reagan', 'Get stumped with the Pawn Stars when a rare double lock musket comes into the shop. Will Rick and Corey take it lock, stock and barrel or will it leave them gun shy? Then, Rick is offered an autographed photo of Laurel & Hardy. Will he make an offer or will a small detail leave him seeing double? And later, when Corey comes face to face with a Ronald Reagan foam head, will he find himself making an offer on the "Gipper"?', '2017-05-15', 21, '/clp2WoQmBC3Vz1qspRMMRPjztz6.jpg', '2026-04-03T16:34:21Z', '2026-04-03T16:34:21Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('370f2ebe-a7d1-4aab-a123-c859ca6a4e6d', 'a75dc15e-67df-4db2-9e0f-8b9901dbab51', 2, 'Rumpelstiltskin', 'Boasting about one''s daughter is one thing, Telling the king she can spin straw into gold is quite another- especially when the penalty for failure is death!What will the millers daughter do? call on the assistance of a strange little man who in exchange for spinning straw into gold -- wants her first born child! The only way to save herself from a terrible fate is to guess the little man''s name.', '1982-10-16', 51, '/rv9IzyjOrt3mIPak0Z1TGz4C5vp.jpg', '2026-04-03T17:38:40Z', '2026-04-03T17:38:40Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('37147c1f-4cd3-47aa-86b5-a353d2fd1a37', 'd01919fb-98e0-42bf-b9d9-1cecf912f6e1', 60, 'Maria Reads "They Built a Garden" On Sesame Street (3845)', '', '1999-04-09', NULL, NULL, '2026-04-03T17:36:42Z', '2026-04-03T17:36:42Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('371cd791-6609-4b59-b87c-71688ca1c5ff', 'd920ebae-f00a-4e25-abfe-40492c74ded6', 13, 'A Bombsight For Sore Eyes', 'Things get heated at the shop when a seller brings in a trophy awarded to basketball legend Julius "Dr. J" Erving. Will this trophy be a slam dunk or an air ball'' Meanwhile, Rick targets a bombsight from WWII. Will he hit the bullseye or miss the mark'' Then, a seller brings in some antique quack medicine bottles. Will Chum buy into the old fads or will the pill be too hard to swallow'' Next, Rick says hello to a little coin nicknamed the "Scarface." Will it be worth the pretty penny the seller''s hoping for'' And later, the shop gets artsy when Corey and Chum thumb through a book of etchings by Henri Matisse. Will it prove to be the masterpiece they''re hoping for''', '2020-03-09', 42, '/q0kCVArqfz5jZ7taiESxkaxwcEH.jpg', '2026-04-03T16:34:22Z', '2026-04-03T16:34:22Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('371cd8aa-80df-4529-ac83-d253efdd4d2f', '7bc54df3-f32a-454e-aef6-a9436c35d53b', 63, 'Episode 63', 'Rogers makes modeling clay, a perfect spot for son Jamie to discuss clay figurines. Dancer Ethel Winter is toured around the Neighborhood of Make-Believe and Someplace Else.', '1970-04-29', NULL, NULL, '2026-04-03T17:35:39Z', '2026-04-03T17:35:39Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('37251bac-c45d-4e37-ad07-4845a779fea8', '5a771f52-fe96-4ea2-b567-a8dde899059e', 24, 'Pawned and Confused', 'A seller drums up excitement for his Led Zeppelin vinyl albums that’s music to Rick and Chum''s ears. Will they think these records rock enough to roll out some cash? An elaborate 19th century office desk is a formidable piece of furniture. Will Rick move to file it under "must-haves", or will he remain stationary? Next up to bat is a game-used base from the 2016 World Series. Will Rick and Corey think it''s a steal, or will they walk? Later, Rick takes a trip to see "The Object," an obelisk-shaped item featured on the cover of Led Zeppelin''s "Presence" album, but will the seller have objections to selling such a rare find?', '2018-03-05', 21, '/A9vhv2peITWj3TMX7goEyOynOT3.jpg', '2026-04-03T16:34:21Z', '2026-04-03T16:34:21Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('3726cd66-971a-4383-a5e4-761254b9aa0d', '787dfa0b-c827-4dad-a82d-0548a6534d88', 9, 'Swimming With Sharks', 'It''s not all fun in the Tahitian sun as the women of the OC travel to the island of Moorea. When they go swimming with sharks, Meghan discovers that the real danger isn''t in the water. Later, the group splits up for dinner leaving Shannon, Vicki and Tamra to not only take numerous shots at the bar, but also a few shots at Heather and Meghan''s friendship.', '2015-08-03', 44, '/aa72saznzhrTYYw7CQJDNf60h1l.jpg', '2026-04-03T16:35:32Z', '2026-04-03T16:35:32Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('372bc096-5ffe-4e77-a0fb-6a63264d2ad1', '4d2cac0f-38fd-438b-8afa-acf43952e535', 288, 'Episode 288', 'Christopher Trace and Valerie Singleton introduce a magazine programme for younger viewers.', '1964-07-20', NULL, NULL, '2026-04-03T17:21:47Z', '2026-04-03T17:21:47Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('372c6198-886e-43c5-9b6d-536ca4231c08', 'de8ec769-16bb-436b-be43-aedc7e18a7d7', 3, 'Pigs for Another Day', 'After the three little pigs catch a cold, Grover, Rosita and Cookie Monster become "Pigs for a Day." They make a couple of mistakes, but they keep trying until they build the right-sized doghouse for Chris’ friend.', '2019-11-30', NULL, '/7xtk26BQotpWcjEy0UEUBKlZQkJ.jpg', '2026-04-03T17:36:50Z', '2026-04-03T17:36:50Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('373261e4-3b33-4b0f-a030-adf9e795fb85', '1cfdff3a-d531-4a9e-afc9-8010a979dd27', 2, 'Prince Caspian (2)', 'The siblings rush to help Caspian in the Narnian civil war.', '1989-11-26', 30, '/mvYffJ4OAvHfeC5UTmzkgmYWXEo.jpg', '2026-04-03T17:17:41Z', '2026-04-03T17:17:41Z');
