INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('37417606-728e-4ac5-a965-ff040b49de66', '33825a15-37dc-4ff9-82bd-cc720498149a', 17, 'Reunion (2)', 'In the supersized second part of the reunion, the women discuss the highs and lows of their trip to Thailand, including LeeAnne''s L''Infinity dress debacle and the controversial visit to the Red-Light District. Emotions run high when questions about LeeAnne''s shocking remarks towards Kary turn into a heated argument between LeeAnne and the whole group.', '2020-01-08', 44, '/1eT6kyD8qwVXo3VMzjlA8rQgNyS.jpg', '2026-04-03T16:35:04Z', '2026-04-03T16:35:04Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('37468e9f-1523-4ec7-9a63-a786ae01ec25', '2b968a9c-5fc0-4e93-bcf9-31d3e4c7b210', 39, 'Episode 39', 'Fish and Chips!  JOHN and LESLEY become cook and waitress at the world''s largest and most luxurious fish and chip shop -where the lights are glass chandeliers and the ingredients of the batter one of Britain''s top secrets.', '1976-01-22', NULL, NULL, '2026-04-03T17:21:52Z', '2026-04-03T17:21:52Z');
