INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('3761c31a-07c0-445f-a90e-3bb75f373dce', '7bc54df3-f32a-454e-aef6-a9436c35d53b', 7, 'The Pie Restaurant Pt 2 - Money', 'Mr. McFeely finds a puppy, which Rogers looks after until someone finds its home.', '1970-02-10', NULL, NULL, '2026-04-03T17:35:39Z', '2026-04-03T17:35:39Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('3769f633-dc49-458c-8fbf-a58aa397f0b2', 'd199804f-ccf5-4e36-8929-56c1e356b74d', 18, 'Episode 943', '', NULL, NULL, NULL, '2026-04-03T17:36:32Z', '2026-04-03T17:36:32Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('376a99a2-887c-48d1-8020-76d3197c5278', '3fc7c152-e4f6-426a-a899-36ec454c4403', 62, 'Max and the Magic Carpet', 'Ord plans a picnic at Rainbow Canyon and invites Emmy, Cassie, and Max. When Quetzal is doing some spring cleaning, Max is excited to find that his old magic carpet can still fly. He has so much fun riding on it, but doesn''t know he is ignoring Ord until he falls in a Huggly-Snuggly Flower and Ord squeezes him out. Max apologizes to Ord for ignoring him and to thank him and prove that they''re still friends, they ride on the carpet together.', '2000-04-17', NULL, NULL, '2026-04-03T15:26:03Z', '2026-04-03T15:26:03Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('376bc822-aeb5-43d7-aa0f-750d1b11faa4', '225b0f03-984b-47f3-a1a3-d3e92175e39d', 38, 'Episode 38', 'with Christopher Trace, Valerie Singleton and John Noakes.', '1967-02-06', NULL, NULL, '2026-04-03T17:21:48Z', '2026-04-03T17:21:48Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('376c28a4-8e35-4c6c-b973-173f5ff3296b', '3af7ea64-fa13-4097-b8e4-40af07083054', 56, 'Episode 56', 'Rogers goes to the McFeelys to work a player piano, even though Mrs. Mcfeely had not been told about it. In the Neighborhood of Make-Believe, Lady Elaine thinks Joey Hollingsworth will be the best man for her apparent wedding with Corny.', '1974-05-06', 28, NULL, '2026-04-03T17:35:40Z', '2026-04-03T17:35:40Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('3774e932-ce83-4ae2-b355-e03467ff3e9a', '15b8dcae-871d-41ca-a88e-beb4ec6530f7', 8, 'The Bike Path / The Neighborhood Picnic / Cleaning Out the Basement', '', '2001-05-23', NULL, NULL, '2026-04-03T17:11:22Z', '2026-04-03T17:11:22Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('3781d476-942b-48cf-b6b8-8e724414aef1', '57139af1-0331-40fb-a5fb-2b05db33accb', 3, 'Part 3', 'Tom discovers that his nightly visits to the garden are not necessarily journeys into a bright summer day when he finds the garden threatened by a storm.', '1989-01-18', 26, NULL, '2026-04-03T17:17:52Z', '2026-04-03T17:17:52Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('3783b9e5-252d-4029-a87b-5ce78ed2527e', 'a3a2c2fb-8276-412c-9d86-5175167be1d7', 44, 'Episode 44', 'with Valerie Singleton, John Noakes, Peter Purves', '1972-02-14', NULL, NULL, '2026-04-03T17:21:51Z', '2026-04-03T17:21:51Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('3785a469-2bfd-4a2b-986a-06996feb7b10', 'edc63a59-2fd4-442a-9343-f2872d776bdc', 5, 'D.W. and the Beastly Birthday', 'In this all-new Arthur movie event, D.W.’s fifth birthday doesn’t go the way she had always imagined it would and she chose to escape to the magical island of Ukubonga. Meanwhile, Arthur has skipped her birthday party to go on a school trip to the planetarium – but instead of transporting him into outer space, it transports him four years in the future!', '2017-05-29', 55, NULL, '2026-04-03T17:37:54Z', '2026-04-03T17:37:54Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('378fa5fe-94c5-4883-9bf4-f3d46ade8a6e', '1a534647-384b-4c00-bb6c-a3371ad962eb', 23, 'Mail Mayhem', 'Follow the yellow brick road with the Pawn Stars when a signed first edition of "The Wonderful Wizard of Oz" skips into the shop. Will Rick make a deal with his brain or will he not have the courage? Then, Corey races to check out a one-of-a-kind Turbo Drive II arcade game. Will he able to race to victory or will he spin off the track? And later, Rick is on the hunt for a package that was supposedly delivered to him. With the Old Man claiming ownership too, will this piece of mail make it into the right Richard''s hands or will Rick have an identity crisis?', '2015-04-09', 21, '/6EW2qothCB2ebYwTvP0541IZNlO.jpg', '2026-04-03T16:34:19Z', '2026-04-03T16:34:19Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('379442d8-184f-46ba-94eb-75c7357625aa', '27a5a980-ec0d-4637-b5ba-df8324a6405a', 3, 'Hecking Order', 'Mike learns that Brick has been skipping gym class, and goes to meet with his fourth grade teacher. Meanwhile, Axl plans a prank on Sue, who is now in high school with him.', '2011-09-28', 22, '/itNnnw3JLlEtCuwKuDAPlV6o4EX.jpg', '2026-04-03T15:40:29Z', '2026-04-03T15:40:29Z');
