INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('37978224-305e-4266-82df-f7bfe421d8b0', '9193e795-da7c-40ec-b68f-f63aa7d5174f', 10, 'The Politics of Power: A Look Back at Season 3', 'Relive every thrilling, dramatic and tragic highlight from Season 3 of "Game of Thrones" in this comprehensive featurette. From Daenerys building a slave army to the infamous Red Wedding, not a detail is missed as recalled by the stars of the hit HBO series.', '2014-03-12', 25, '/nTAGjLkDuhn69Ni18UdfYcJ7nnj.jpg', '2026-04-03T15:40:35Z', '2026-04-03T15:40:35Z');
