INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('37a92874-a355-48b5-b994-a47ea31fac4d', 'efd2082e-32f5-4edd-9a7b-a4326d6992c9', 14, 'Sesame Friendship', 'Big Bird is building a tall block castle, but it accidentally gets knocked down. Big Bird thinks Snuffy did it and doesn''t let him explain. Alan and Nina help them learn to stand up for themselves, listen to each other and apologize.', '2019-02-16', NULL, '/l0P2jdu94gNy6f7GBbUMOzwLFez.jpg', '2026-04-03T17:36:49Z', '2026-04-03T17:36:49Z');
