INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('37b1fd53-386b-4200-8d97-15f147939e71', 'a8f3a681-7abc-41e0-9988-9b8804d74611', 5, 'Infertility & Nesting', 'The Browns apply for separate mortgages as they dream of getting their family into adjacent homes. Meanwhile, Janelle is still determined to open a gym, but will Kody support her plan? Later, Meri discloses the details of her past fertility problems.', '2012-06-03', 44, NULL, '2026-04-03T16:34:28Z', '2026-04-03T16:34:28Z');
