INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('37b2716f-849b-49fb-86bc-ff64ffdbffa5', '10e64538-c78a-4cb0-82f9-17d14256dbac', 16, 'The Man Hunt', 'After Brick attends a Bar Mitzvah and questions when he''ll officially become a man, Mike attempts to help him become more responsible in his quest to manhood. Meanwhile, Sue exudes a little too much enthusiasm as she tries to flirt and find herself a boyfriend, and Axl and Hutch find themselves a new home in the form of a Winnebago.', '2016-02-24', 22, '/yS21x60C3wLr68cOJQmZ6u4m3Cn.jpg', '2026-04-03T15:40:31Z', '2026-04-03T15:40:31Z');
