INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('37b93945-aa6c-4803-bb0c-f57a53336dd9', 'e03d79bd-e01f-4414-b0b3-f3b5f26e97f4', 21, 'Mother''s Day II', 'Things don''t go as planned when Mike and the kids give Frankie a day without the family as a Mother''s Day gift.', '2011-07-29', 22, '/zqtE3VhOZAZnJ1MIBvrYoIwOgny.jpg', '2026-04-03T15:40:29Z', '2026-04-03T15:40:29Z');
