INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('37c711ba-8b01-4cc2-aa58-38488001a29f', '4900fc8d-5e7e-408e-972e-ce9269d203b3', 9, 'Runaway Husband', 'During the ladies'' final night in Cabo, tensions rise and Emily takes a fall. Back in the OC, Gina starts to question her friendship with Noella, meanwhile Shannon hopes to strengthen her friendships with Heather and Emily. Emily throws a game night, and Dr. Jen and Ryne come to a crossroads in their marriage.', '2022-02-09', 44, '/x9YKzbESpEkStUwZAtEFH3mjV5T.jpg', '2026-04-03T16:35:35Z', '2026-04-03T16:35:35Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('37c8020b-528b-4500-854a-83de5eb4cbfb', 'dfa60f31-6ef1-4bee-a9ad-554b68a5448b', 4, 'Journey to the Red Center', 'Steve and Terri journey to the Red Desert at the heart of Australia. They examine venomous snakes, lizards and endangered mammals as they make their way to the world famous Uluru, also known as Ayers Rock.', '2000-12-17', 44, NULL, '2026-04-03T17:39:11Z', '2026-04-03T17:39:11Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('37c8fbb8-a4b6-4423-9c8f-3d933c78e9ac', '5db3ff78-e439-48e1-8f67-988ecbf85d17', 19, 'Dogtanian Is Put to the Test', 'Dogtanian continues pursuing The Black Moustache, on the way out of the Musketeers headquarters he runs into Athos who''s showing off his new baldric. Dogtanian tries to see the back and makes Athos look a fool when he finds out the baldric doesn''t have a back. Athos challenges him to a duel, Dogtanian agrees and arranges it half an hour after his duel with Porthos. Dogtanian resumes the chase and runs into Aramis, as he''s approaching he accidently kicks a stone at Aramis'' girlfriend, leading to another duel again half an hour after the duel with Athos...', '1982-02-05', 24, '/jjvqt0H2wjPYeymtfLlKip7ryzf.jpg', '2026-04-03T17:18:43Z', '2026-04-03T17:18:43Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('37d228f8-664b-49a6-af26-11849419138a', 'a6ed03e0-c05f-48f8-9f56-3f1da50e1792', 28, 'Episode 1343', '', '1980-01-02', NULL, NULL, '2026-04-03T17:36:33Z', '2026-04-03T17:36:33Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('37d41321-811d-4766-97b8-690b2b956ec9', 'b6a0f228-7ddc-409c-b808-681b777a6704', 13, 'Mister Rogers Makes an Opera', 'Guest Jay O''Callahan tells a story about a king trapped in an enormous soap bubble. When King Friday asks for a bubble that lasts, no one can help, until Reardon calls.', '1980-05-19', NULL, '/h6Fl6QLLg2Tdn7ogwKrBQF7EUyC.jpg', '2026-04-03T17:35:42Z', '2026-04-03T17:35:42Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('37d8a1f1-15ba-481a-8113-6432a70dc850', 'bfdf87ff-01dd-4b54-94bd-19b384f41bdb', 2, 'Making Friends But Not Amends', 'While Heather travels to Turks and Caicos to help Terry reconnect with their kids, Tamra tries to save Ryan and Sarah''s relationship. Meanwhile, Kelly decides to befriend Vicki against Meghan''s warnings. As Shannon continues to rebuild her relationship with David, Vicki does the same with her business. Later, Meghan invites the ladies over to her new house to demolish her kitchen; however it''s Kelly who seems to smash her chances of friendship with the girls when she reveals she has befriended Vicki.', '2016-06-27', 44, '/25w8ltQVaChvt20bWYewDBANPmm.jpg', '2026-04-03T16:35:33Z', '2026-04-03T16:35:33Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('37dbba27-2e42-4116-b59a-e87bf721bc7a', '4d2cac0f-38fd-438b-8afa-acf43952e535', 342, 'Episode 342', 'with Christopher Trace and Valerie Singleton.', '1965-03-08', NULL, NULL, '2026-04-03T17:21:47Z', '2026-04-03T17:21:47Z');
