INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('37f12255-1622-49c5-b238-a28e8e487c58', '56428e5e-7daa-468d-8bd2-076956507aa8', 16, 'Communication', 'In this program, Bill points out the different ways in which humans and animals exchange information. He also talks about the ability of humans to store data in computers, books, and on videotapes.', '1994-11-12', 26, '/cTf5gwIaIbCYW6KM1ecpatF7kWW.jpg', '2026-04-03T17:37:21Z', '2026-04-03T17:37:21Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('37f1f8cd-e9f9-4a11-9f6e-b96da648c939', '5062ce29-8dbb-48ab-879b-0771221678d5', 5, 'Sledge Ride', 'Percy is taking the day off and builds a sledge. However Fox and Squirrel borrow Percy''s materials to make their own sledge. Then they offer Percy a ride in it.', '1999-10-17', 15, NULL, '2026-04-03T17:19:02Z', '2026-04-03T17:19:02Z');
