INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('3886490c-2e6b-43b0-9ea3-e396fce281f6', 'bfdf87ff-01dd-4b54-94bd-19b384f41bdb', 17, 'Puppet Strings and Tamra''s Wings', 'The Ireland trip ends with the conclusion of the bus ride from hell. Back in Orange County, the women try to make sense of their war on foreign soil, while Meghan escapes to St. Louis to get away from the drama. After months of strict diet and exercise, Tamra is finally ready to flaunt her body on stage at her long awaited fitness competition and the ladies gather to cheer her on.', '2016-10-24', 44, '/sGczUQNQOxOllsKrudpAln5TSjf.jpg', '2026-04-03T16:35:33Z', '2026-04-03T16:35:33Z');
