INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('3890b29e-54ae-4a0b-806e-aed00c41835e', 'a0fa5075-9ce1-48c1-9995-0c0fd866e549', 16, 'Sutton on Trial at Sea', 'As Boz’s trip to Saint Lucia heats up, Sutton apologizes to Dorit for her poor use of words at Jennifer’s dinner party, but Dorit finds the apology a day late and a dollar short. Kyle faces the music about her private life. Garcelle begins to see a different side to her bestie, leading to a surprising spat. During a yacht getaway, Erika makes a splash with a damning observation that leaves some women wanting to jump overboard.', '2025-03-18', 43, '/8AVYw8RxQq0XBDKBOset7yEy03L.jpg', '2026-04-03T16:34:59Z', '2026-04-03T16:34:59Z');
