INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('395f8ef7-928a-457d-8509-7947a3dd3d46', 'a31fa1d7-d649-4846-a81f-4f34b6fb3331', 10, 'Trouble at the Beach', 'Paddington''s sandcastle making goes wrong, as does his whole day out.', '1979-01-02', NULL, '/w3nHdPF44UbAUISXBeFKO5NkRZg.jpg', '2026-04-03T17:22:52Z', '2026-04-03T17:22:52Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('39604ebb-62cf-490b-a7b2-d90f4d39d168', '5c1b881f-ac58-4d72-b63f-209952d4f902', 68, 'Episode 68', '', '1980-05-08', NULL, NULL, '2026-04-03T17:21:54Z', '2026-04-03T17:21:54Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('396367a2-78a8-4e91-a6aa-42efb27320bf', 'ecb64ef3-4f80-45a7-b4a9-c04434b02e35', 51, 'Get in the Ring', 'Grab a ringside seat when the Pawn Stars square off for memorabilia from undefeated boxing champ Rocky Marciano. Can Corey land a knockout blow or will he end up down for the count? Then, Rick checks out a one-of-a-kind, battery-operated, glow-in-the-dark car. Will he take charge and make an electric deal or end up in the dark? And later, Chumlee uses modern technology to "tele-presence" into work. Can he get the job done or will Rick pull the plug?', '2014-06-26', 21, '/mX6xNoT9Q5kDvmmpuNemH0FA7UN.jpg', '2026-04-03T16:34:19Z', '2026-04-03T16:34:19Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('3963ff23-b33b-4bd9-a18a-00bc2405f811', '15b8dcae-871d-41ca-a88e-beb4ec6530f7', 11, 'Tom''s Pool Party / Dancing Fairies / Orbie and the Skunk', '', '2001-06-13', NULL, NULL, '2026-04-03T17:11:22Z', '2026-04-03T17:11:22Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('39686d0c-9ce8-4cbc-beaa-a0e0bd03e100', '9193e795-da7c-40ec-b68f-f63aa7d5174f', 128, 'Histories & Lore: The Death of Kings', 'Varys tracks the lives and all too common deaths of the Kings of Westeros over the years, proving that the Iron Throne is truly an uncomfortable seat to hold.', '2015-02-17', 3, '/bnlqPzEOxM36Lrw5WIjIINuka0T.jpg', '2026-04-03T15:40:35Z', '2026-04-03T15:40:35Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('396e42e1-91ec-4ae6-a57e-a3681337315e', 'dbde6570-a68d-4fd7-a1b0-a6037a266a18', 18, 'Will He or Wont He', 'Alexis reports on-location for the news; Gretchen discovers Slade''s plan to propose leading to a confrontation; Eddie surprises Tamra with a surprise romantic getaway.', '2012-06-12', 44, NULL, '2026-04-03T16:35:31Z', '2026-04-03T16:35:31Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('396f25c2-19fc-4ba5-8fa7-e4d5f39f94ab', '04e133fd-c4a3-4dfa-8369-c6dcfd1e3a5a', 37, 'Luis breaks his arm — Luis gets a check-up', 'Luis visits his doctor for a check-up and receives encouraging news about his arm''s progress. The medical milestone gives him hope for complete recovery soon.

Sponsors: J, K, 5', '1985-01-08', NULL, NULL, '2026-04-03T17:36:35Z', '2026-04-03T17:36:35Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('39737cb5-2d35-4f6f-86fe-ec2d85b44f99', '1415ef1c-411a-4c26-814a-7c79c3628bc2', 5, 'The Politics of Friendship', 'Carole and her mom go canvassing in Pennsylvania in the last moments before the presidential election, and later Carole and her friends watch the results come in while at her party. Sonja is conflicted between “Frenchie” and Rocco. Dorinda conspires to get Ramona to a surprise party she’s throwing for her, but Ramona unknowingly throws a wrench in the plans.', '2017-05-03', 60, '/o7JTs2ZijGnZuBW3EgJ1VnCM3jU.jpg', '2026-04-03T16:35:24Z', '2026-04-03T16:35:24Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('39794f26-49ce-4b76-9156-e487920db383', 'cc472916-0b8b-4498-8a9a-c5c1e7e66097', 17, 'No Business Like Clothes Business', 'The ladies wrap up their trip to Paris and back in L.A. Kyle throws a party for the opening of her store.', '2013-03-11', 43, '/sarn7RNk5cWP56pu2ECh7FmtSTd.jpg', '2026-04-03T16:34:55Z', '2026-04-03T16:34:55Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('397a7f99-222d-4204-bcec-060ed77244d6', 'd8ccf6d3-e37a-430a-b67d-7fbf269bf0be', 17, 'Reunion (1)', 'The ladies reunite in New York to discuss the season''s highs and lows. New housewife Monica sets the record straight about her past – from her affair, history with the Mormon church and how she became an informant in her ex-friend''s criminal case. Angie confronts Monica and Meredith about the rumors regarding her husband and the Greek Mafia.', '2024-01-09', 44, '/fXGKcCitDCMqATuSwWjDsLfQlYg.jpg', '2026-04-03T16:35:45Z', '2026-04-03T16:35:45Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('397fe5c9-0d8c-47c2-bf71-08d6ed35295a', '6fedba82-52f3-4184-be77-6b26e556cd0e', 7, 'A Family Group', 'Paddington attempts to take a photo of the Browns using an old camera.', '1976-01-13', NULL, '/dYe9hAMPjagSQbqEwOS7aRsUECB.jpg', '2026-04-03T17:22:52Z', '2026-04-03T17:22:52Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('3984ba14-497d-431f-a991-5c2aa1c35e3e', '70d9e397-6813-4785-887d-27d034928bae', 19, 'Pingu Hides a Letter', 'Pingu comes in from playing with his ball and sees a letter on the table. The letter is sealed, and has nothing written on the envelope. He wonders what it might be about but leaves it and has a snack. He is about to go out again when curiosity gets the better of him, so he returns to the letter, opens it and is about to look at the contents when he hears someone coming. He quickly hides the letter, just before Pinga and Mother enter. Mother notices the letter is no longer on the table, and asks Pingu if he knows where it is. Pingu says he doesn’t, so Mother and Pinga search everywhere for it. Mother then asks Pingu again if he knows about it, and this time he owns up to having opened it and gives it to Mother. It was for Pingu all along, and is an invitation to a party. Pinga shows Pingu her own invitation that she’d already opened. Pingu then notices that the party is today, and it’s now the time that it’s almost time to start, so they have to rush to get there, and they make it just in time before it started.', '1996-07-18', 5, '/zGZkTKkV5pGpTPmwD8RbfaKueWS.jpg', '2026-04-03T17:22:19Z', '2026-04-03T17:22:19Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('398a500b-119f-4442-9968-bed9367178ed', 'a8c6182e-05e1-4b68-91a5-5126cf6c94f0', 20, 'An American in Paris', 'While visiting Abigail Adams, Sarah gets exposed to smallpox. Meanwhile Alexander Hamilton joins George Washington in the battle.', '2002-09-27', 30, '/hM3052fq9xYFPPzUfpdWoTwHzNW.jpg', '2026-04-03T17:38:28Z', '2026-04-03T17:38:28Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('398a6793-6b6e-479e-b9e6-187a9adf6324', 'd9973960-273b-4a92-a7da-62efe8860d09', 4, 'Roaring Emotions', 'At the conclusion of Whitney’s 20s Party, Jen’s explosive temper reaches a boiling point and Meredith and Mary are the targets. Meredith finally reveals the truth about her marriage to Lisa, while Jen shares the details with Heather, who then tells Whitney. Mary takes the high road and invites Jen to her luncheon hoping to squash their issues for good, but when Jen tries to open up to the group things take a sudden turn for the worst.', '2020-12-02', 42, '/2Q7vjLmGnm2vpJy8AyhlMvreRsX.jpg', '2026-04-03T16:35:44Z', '2026-04-03T16:35:44Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('398af12f-5d8b-48b5-9e79-f64d73c37b34', 'f63c3f61-0970-4e37-81cc-2b9045a9952c', 11, 'Elmo, Baby Bear and Telly Put On a Play (3926)', '', '2001-01-15', NULL, NULL, '2026-04-03T17:36:42Z', '2026-04-03T17:36:42Z');
