INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('3a126596-ee13-44ac-9e94-a3ae8f5cfe2d', 'abeb8d07-5c86-4f6a-a110-b11cba2a4138', 14, 'The Boiling Rock (1)', 'Sokka wants to break his father out of jail and asks Zuko for information on Fire Nation prisons. Sokka and Zuko head for the Boiling Rock, a prison located in the middle of a volcano, to rescue Sokka''s father.', '2008-07-16', 24, '/keivJ7wk45aLbg03AqEb9WgrYSz.jpg', '2026-04-03T17:40:48Z', '2026-04-03T17:40:48Z');
