INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('3a1b8145-beaf-416d-88e3-721904631b50', '7b19039a-31ac-425c-8fb1-b51cf2447821', 14, 'Making Waves', 'The ladies get together for the first time in months when Emily throws an elegant beach party. But with a lot of unfinished business in the group, the gloves quickly come off. Gina is shocked to learn Shannon is holding a grudge against her and Braunwyn struggles with evolving feelings in her relationships. Later, Elizabeth takes steps to heal the wounds from her past, and Kelly confronts Braunwyn about her authenticity.', '2021-01-13', 44, '/5BWd1IcaDOWbB9uVivPapOmyIcv.jpg', '2026-04-03T16:35:34Z', '2026-04-03T16:35:34Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('3a258175-8b24-4710-9230-68ab72339052', '8c3cfac1-d882-4904-b38c-d1981628d00e', 38, 'Episode 38', 'On 17 January. 1912 Captain Scott''s Antarctic expedition reached the South Pole - only to find a Norwegian flag planted there! Chris investigates the dramatic story of Roald Amundsen - the first man at the South Pole.', '1979-01-22', NULL, NULL, '2026-04-03T17:21:54Z', '2026-04-03T17:21:54Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('3a264cbf-3d3a-4b6d-b023-10abdf46be97', '0fa92002-82ae-4609-85e3-3982baa99ae1', 13, 'Postman Pat and the Tricky Transport Day', 'When Pat''s van breaks down one snowy day, he has to use a lot of different vehicles to finish his round.', '2005-03-14', 15, '/e8ouzHFoFFBqX6r5zQhKGVZr247.jpg', '2026-04-03T17:14:30Z', '2026-04-03T17:14:30Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('3a26af81-41bb-402a-b161-7947cd04543c', '56428e5e-7daa-468d-8bd2-076956507aa8', 7, 'Light Optics', 'Don''t stay in the dark - Bill Nye will help you absorb the science of light optics. Light is energy that normally moves in a straight line, but often something gets in the way. When light runs into something, three things can happen - the light can bounce off, it can go through, or it can be absorbed. Often all three things happen at the same time. Light bounces off mirrors. You see yourself in a mirror when light bounces off your face, into the mirror, and then into your eyes. Light goes through glass. If the glass is bent or curved, the light gets bent on its way out of the glass. The glass in a magnifying glass or a pair of eyeglasses is curved so that it bends light, making things look bigger. More light is absorbed by dark-colored things than by light-colored things. Colors are made when some light is absorbed while other light is bounced back. Black things look black because when light hits them, they absorb almost all of the light.', '1994-09-10', 26, '/28TyqRpbzdGgPE98HQzbXcm7LGH.jpg', '2026-04-03T17:37:21Z', '2026-04-03T17:37:21Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('3a2d0940-b211-4553-97b3-47f20a994aee', 'b7538712-04ce-43a6-9163-62280bbb084b', 41, 'Felix cleans Oscar''s trash can (3891)', '', '2000-02-28', NULL, NULL, '2026-04-03T17:36:42Z', '2026-04-03T17:36:42Z');
