INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('3b068559-dab7-486d-a46c-937e98cc030d', '698a60df-8ed4-4ca9-bcb1-ebab343dacdd', 22, 'The Handicap Spot', 'There are many repercussions after the gang parks in a handicap space.', '1993-05-13', 23, '/vLeQ7eHc8aJM1K9j5mIU3k2xq15.jpg', '2026-04-03T16:34:10Z', '2026-04-03T16:34:10Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('3b0b1904-c9a5-4746-ab7f-72f6fe24e003', 'ea1650c2-e4f1-46c7-93ba-74b5d45d08e5', 1, 'New Attitude', 'Gossip spreads fast when Kim reveals her lesbian affair in the tabloids, and NeNe rekindles her roller coaster relationship with Kim just in time to get the inside scoop. NeNe’s got drama of her own -- her marriage is on the rocks and her old friend Dwight has been spreading rumors behind her back. Shereé pursues her long-time dream of becoming an actress and Kandi starts getting back into the dating scene. NeNe, Kim and Sheree hit up a couture shoe event and run into new housewife Phaedra Parks – the pregnant, classy, but sassy attorney-to-the-stars, who arrives with her old pal Dwight.', '2010-10-04', 43, '/9l5Xyc7j4z1w6pPQ0MB1NDIe9lb.jpg', '2026-04-03T16:34:45Z', '2026-04-03T16:34:45Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('3b0c5083-f656-43ed-88f5-a643dd6ac58b', '5db3ff78-e439-48e1-8f67-988ecbf85d17', 23, 'Marco''s Mission', 'The Jewels were given to the former King of France by the King of Spain, Louis decides to return them as a sign of friendship, The Three Musketeers and Dogtanian have be given the honour of carrying out the mission, Treville proudly strokes his mustache. Richelieu and Rochefort have plans to stop them reaching the Spanish Court. Pip is at a show satirising Cardinal Richelieu staring a mouse called Marco. Widimer and the Cardinal''s guards have been ordered to stop the show. Marco knocks Widimer off his horse, Pip joins in the fighting but doesn''t help and Marco and the Ringmaster are arrested. Richelieu and Rochefort tell Marco there is a conspiracy to start a war between France and Spain and ask him to help stop it...', '1982-03-05', 24, '/iDZHksFsoMCZ53qaFA8epQPwu7H.jpg', '2026-04-03T17:18:43Z', '2026-04-03T17:18:43Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('3b0dfdcc-a96a-436c-a943-d7add76dc804', '740a96a0-a075-4be2-be92-a178d0939384', 12, 'Hair Training', 'Prairie and her friend Gabrielle are practicing a dance, but their hair doesn’t move the same way. Nina helps them realize that the dance is even more fun when they each let their hair do what it wants to do! Elmo and Big Bird join in and let their fur and feathers fly free.', '2018-02-03', NULL, '/dfb2yjWPzinZcccuZyhkutWaahw.jpg', '2026-04-03T17:36:49Z', '2026-04-03T17:36:49Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('3b1772d2-1a26-46aa-8266-854e8b3dec18', 'f13cb622-84e3-4654-a8f1-0ceab09a9ca6', 16, 'Franklin''s Party Plans', 'When Franklin finds Skunk crying and learns that she''s moving, he tells some of his friends about it and they decide to put together a surprise party to cheer her up. They create a number of items for her to remember them by, but when it comes time for the surprise party, it turns out to be Skunk who surprises them.', '2002-06-17', 12, NULL, '2026-04-03T17:40:16Z', '2026-04-03T17:40:16Z');
