INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('3b65947c-b150-4e42-b562-c8cdb674cbde', 'd6092173-d23b-4449-baff-e0e16fe56c9a', 12, 'Front Page News', 'Marlo invites the ladies to saddle up for a hayride, but the fun is interrupted by news that unearths trust issues within the group. As the countdown to Cynthia and Mike’s wedding approaches, Cynthia is met with minor setbacks.', '2021-03-07', 43, '/hp99V5yKKBpnxKOk2iqsqxyer7E.jpg', '2026-04-03T16:34:49Z', '2026-04-03T16:34:49Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('3b65a21b-8865-45f8-92e8-cf6ca7565ca5', '2e6ee129-b32e-4417-9500-56f1cc9bc434', 6, 'Follow the Drinking Gourd', 'LeVar reflects on a time when Africans were brought to America as slaves. He talks about how African-Americans risked their lives for freedom, and discusses how the music from slavery times effected the African culture. Keith David reads the featured story, which explains that the African-American folk song, "Follow the Drinking Gourd," was in fact a coded message to slaves giving them instructions on how to take the Underground Railroad north to states that abolished slavery.', '1993-10-18', 30, NULL, '2026-04-03T17:36:18Z', '2026-04-03T17:36:18Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('3b73354c-77f1-4358-93b6-0711cec8fe02', '0ebba123-871d-4d2b-a054-eb85d2ad9450', 49, 'Beauty and the Beet', 'Mirabelle and her traveling family band, the Veggie Tones, are determined to make their next gig at Vegetable Square Garden. On their journey, a fierce winter snowstorm hits, and the family gets stuck at a run-down resort! Mr. Beet, the grumpy manager, makes them sing - and clean - for their supper. Why is Mr. Beet such a beast? And can Mirabelle''s kindness change him? Find out in this hilarious and heartwarming tale of unconditional love!', '2014-10-14', 30, '/zYC04JoeBFToILcpuRf4wjMzhKj.jpg', '2026-04-03T17:39:39Z', '2026-04-03T17:39:39Z');
