INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('3b8aebe0-a0d7-46b9-9557-6f4ba31cdcfd', '190c6e49-8849-4404-87d4-eaef943a6024', 3, 'Oakie Doke And The Party', 'Rose is not able to cook pizzas for the Oakie Hollows Hoedown due to her broken oven. Manny finds out that Snoot stuffed Grannie Annie''s hat down the pipe. After Marcus, Root and Oakie have fixed the oven, Oakie and all the family come to the Oakie Hollows Hoedown with the pizzas.', '1995-09-25', 10, NULL, '2026-04-03T17:19:24Z', '2026-04-03T17:19:24Z');
