INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('3b9288d4-62e3-457c-b3d5-455b9d244783', '1996ddd8-20c9-4a30-96be-2b87fab8d17c', 3, 'Ghost Story (3)', 'Alex learns about Ghostwriter. Jamal and Alex figure out that the THABTOS, are who have been stealing backpacks (including Gaby''s) and learn that these are the same kids Jamal saw at the park. Gaby, Alex''s sister encounters the mysterious being.', '1992-10-18', NULL, '/xwJj9q3NTKYM92h6KnTZgRIdctb.jpg', '2026-04-03T17:40:28Z', '2026-04-03T17:40:28Z');
