INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('3b9e6765-d75d-4314-950e-f1aadffa562f', '06030129-ff2d-4490-b66c-9f41bbe7aabd', 9, 'Coal', 'It is quite cold on the Ragdoll, and John is running out of coal for his furnace to keep him and Rosie and Jim warm, so he and Rosie and Jim set out to a coal mine to see where exactly coal comes from.', '1990-10-29', 15, NULL, '2026-04-03T17:19:36Z', '2026-04-03T17:19:36Z');
