INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('3ba5af36-746f-4bba-a564-c6923df66718', '6ef86c27-33e7-47e5-a053-483059dfd16d', 11, 'Episode 11', 'William Adams was shipwrecked on Black Island off the coast of Japan in 1600. Sarah traces the true story of the Englishman who became samurai to the Shogun.', '1981-10-19', NULL, NULL, '2026-04-03T17:21:55Z', '2026-04-03T17:21:55Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('3ba684d7-555e-4ae4-81c6-2c2ad855a07e', 'c9adc698-be92-4dd7-94ad-d8f6759361ca', 39, 'Episode 39', 'Rogers shows different kinds of potatoes and shows what happens if they are put in water for a while. He makes up a potato song. Mr. McFeely delivers an ocarina. At the Negri''s Music Shop, a blue grass band is rehearsing and explains why their music is bluegrass. Chef Brockett plays an ocarina and decides to be a potato bug in the opera. John Reardon and Lady Aberlin are still planning the opera and need a king and a pilot. King Friday decides he can''t be in the opera. François Clemmons will make a good king, and Miss Ito can be a pilot.', '1973-04-12', NULL, NULL, '2026-04-03T17:35:40Z', '2026-04-03T17:35:40Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('3baa107a-0491-4a19-8721-5dd621a9c05e', '6f81c872-cdb9-42dd-8377-2c17cb6ed4d7', 10, 'Elmo Comes Clean', 'Elmo keeps hiding from Nina because he wants more time to play before his bath, but Ernie helps him realize that he can play in the bathtub, too.', '2017-03-11', NULL, '/jrbRAmmrO9qkAqxwAVsl6qlC3Kl.jpg', '2026-04-03T17:36:48Z', '2026-04-03T17:36:48Z');
