INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('3bb713e5-4157-45f1-8b80-4666de8dfd9d', 'd306a064-e835-417e-8548-0cf806295f31', 4, 'Hot Mic in Miami', 'Larsa hosts a paw-ty for her dog''s birthday; Nicole receives upsetting and possibly threatening news from her father; Julia worries that Martina may leave her; Lisa hosts a pool party for the ladies where Lenny''s true intentions are revealed.', '2022-12-08', 54, '/bcfxGBF8uyQtW8cPI2opVYuBcqB.jpg', '2026-04-03T16:35:11Z', '2026-04-03T16:35:11Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('3bb731fb-63d3-4e33-9321-0981581aa699', '70d9e397-6813-4785-887d-27d034928bae', 20, 'Pingu is Not Allowed to Join in the Games', 'Pingu is on a walk when he comes across Pingo and Robby playing badminton. He wants to join in, but they won’t let him. He mopes off to a nearby block of ice, where he finds a basket of fish. He’s about to look closer but Pingo tells him to leave it alone. Then Pingo hits the shuttlecock very high, and it lands on top of the ice block. Pingu goes up to the top of the block to get the shuttlecock but won’t return it except in exchange for their basket of fish. Pingo and Robby decide to play a trick on Pingu, so Robby gets a crab that they put under the fish before letting Pingu have the basket. Pingu puts his hand in the basket and is bitten by the crab, which holds on. Pingu is so startled he falls off the block of ice, and the crab makes good its escape. Robby is sympathetic about Pingu’s hurt hand, but then goes onto the top of the ice-block with Pingo and he and Pingo eat all of the fish except one. They then feel sorry for Pingu and take him the last fish, which he eats. Robby then gives Pingu his racket to use, and all three of them then play together happily.', '1996-07-25', 5, '/hBXFDt4ZotGI8TQM2qNMMA1ovU5.jpg', '2026-04-03T17:22:19Z', '2026-04-03T17:22:19Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('3bb9debb-9aee-4d93-930d-d76e1af859a5', '3eee3180-acb7-429d-95af-f575bb4ab932', 1, 'Paul Bunyan', 'Lavar visits a lumberjack camp in the forest. Today''s featured book is based on the legend of Paul Bunyan, the giant woodsman.', '1985-07-01', 30, NULL, '2026-04-03T17:36:15Z', '2026-04-03T17:36:15Z');
