INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('3bc319f8-c407-4795-a443-4a41b687f4bb', '4fe93658-c463-4329-8e64-9d523869c2cb', 22, 'Put Up Your Dukes', 'The Pawn Stars have a chance to buy a 450 year-old book once owned by Sir Isaac Newton, but when hand-written notes and formulas are discovered in the margins the gravity of the situation becomes clear. Can they postulate a proper price or will this deal require an equal and opposite reaction? Then, a man walks in with his grandfather''s Army jacket from the Spanish American War. Will Rick and Corey offer up the shirts off their backs or will one loose thread cause the whole deal to unravel? And later, Rick and Chumlee check out a collection of John Wayne memorabilia. Will they sound a charge to secure pieces of the western legend or will Rick be forced to retreat?', '2011-01-31', 21, '/i6FkMWjo16LBuLCkP6QJn5ofkFi.jpg', '2026-04-03T16:34:16Z', '2026-04-03T16:34:16Z');
