INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('3bd72ee9-44d6-480f-a5ce-6766225340ae', 'df77dba2-bbda-4f38-9713-8d5c856f852e', 6, 'The Circus', 'There has been a party in the playroom and the toys can see that there is lots of food left on the table, but it is just out of reach. Little Bear explores underneath the tablecloth and discovers that it looks just like a circus tent; a starting point for a wonderful new game. Many of the toys want to perform in the circus and others come to watch. It is Rabbit who turns out to be the star of the show and he, accidentally, solves the problem of the out-of-reach food.', '1993-11-07', 10, NULL, '2026-04-03T17:18:55Z', '2026-04-03T17:18:55Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('3bd87c72-615f-4152-927c-7a8dbce963d7', 'd84bd187-f033-42dd-8873-e1099c61de07', 16, 'Episode 675', '', NULL, NULL, NULL, '2026-04-03T17:36:39Z', '2026-04-03T17:36:39Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('3bdde687-d330-4ff6-9e73-0a29f9fa6f85', 'd3e13496-e3c8-4903-83b4-5a31fedee232', 3, 'The Southern Air Temple', 'Aang is excited about going home for the first time in one hundred years, but he is shocked to find out that the temple is deserted. Aang tells Sokka and Katara about his childhood as they explore the temple, but they soon discover something that Aang never expected. Meanwhile, Zuko must make repairs to his ship and the only way he can do it is to dock his ship at his rival''s naval base.', '2005-02-25', 25, '/bFBUv2VDtyBuilulFynsNGPINnw.jpg', '2026-04-03T17:40:47Z', '2026-04-03T17:40:47Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('3bdf3095-9a0e-4fac-874d-d0d4d8095027', '787dfa0b-c827-4dad-a82d-0548a6534d88', 12, 'Racing to the Truth', 'Meghan, Heather, Tamra, and Shannon head to NASCAR while Vicki enjoys a birthday getaway with Brooks. Later, Shannon tries to put on a happy face during her birthday dinner with David and her girls. Heather throws a luncheon at her unfinished home, where Meghan confronts the OG of the OC.', '2015-08-24', 44, '/iNm2SzVg29aSReDhZVmcpeuhegI.jpg', '2026-04-03T16:35:32Z', '2026-04-03T16:35:32Z');
