INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('3be37a6d-73ca-41de-93b3-17355816d1a0', '4da606e7-9d23-4682-8bd5-f535e1da706f', 18, 'Franklin''s Collection', 'Franklin did not know what to bring to school for show and tell. Everyone had a collection of some sort except for Franklin. Franklin sets out to find a collection but didn''t think it was anything spectular until Mr. Owl pointed out what a great collection Franklin has.', '1998-11-02', 12, NULL, '2026-04-03T17:40:15Z', '2026-04-03T17:40:15Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('3befbdb5-6944-4ef1-9a32-bff9748eeb71', '7b19039a-31ac-425c-8fb1-b51cf2447821', 2, 'Tequila Truth Serum', 'Kelly is focused on her future with fiancé Rick, but wonders how long her recently brokered peace with Shannon will last. Elizabeth and Jimmy bond over their shared Mexican heritage. Braunwyn struggles with her identity and worries that her friends won’t stick around now that she’s not “fun” anymore. Gina reveals that she heard Braunwyn made fun of her “small house” but it turns out she isn’t the only one making disparaging remarks. Gina also brings up the awkward text messages she had with Sean last year. When Emily calls Braunwyn to clarify, she refuses to discuss over the phone. Later, when rumors start to spread, Braunwyn is forced to reveal a secret to Shannon.', '2020-10-14', 44, '/r29LcSzSr5HQCrErGRwzr2hMh8J.jpg', '2026-04-03T16:35:34Z', '2026-04-03T16:35:34Z');
