INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('3bf9a2dc-f825-4ec2-a57a-b08e13695269', '3ee646e8-23ae-4dec-bbc6-c7e6a210d55b', 37, 'Telly Monster follows Gordon to school for a "Wide World of Sesame Street" report', 'Telly hosts "The Wide World of Sesame Street," a program which shows a day in the life of someone on Sesame Street. "Wide World of Sesame Street" continues as Telly hides in the bushes and watches Gordon at the bus stop, waiting for the bus with a group of people (including Mike and Lisa).

Sponsors: D, H, 10', '1991-01-01', NULL, NULL, '2026-04-03T17:36:38Z', '2026-04-03T17:36:38Z');
