INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('3c091986-61dd-46fd-9c0e-e200f6575b59', '19e027c7-8626-44a9-96ba-d36b323b3a74', 18, 'The Minstrels', 'The Fraggles meet the band of traveling musicians known as The Minstrels, led by the mysterious and wise Cantus. Everyone must find their own song, but Red is having a lot of trouble with hers.', '1983-05-09', 24, '/fzgnS42cSY9K4V6tc2a8JYHrQqT.jpg', '2026-04-03T17:34:59Z', '2026-04-03T17:34:59Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('3c0ae563-1dd2-46a2-abe7-f217625a6590', '943b0c94-0cc5-40e8-a0e1-bd5660772cc3', 9, 'Dirty Ol'' Dad', 'The ladies have a dinner get-together in Miami with Sonja and her date—who happens to be Aviva''s lusty father. Later, Aviva seeks advice on how to deal with Ramona, and Carole calls out LuAnn about a past misdeed.', '2012-07-30', 60, NULL, '2026-04-03T16:35:23Z', '2026-04-03T16:35:23Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('3c14bfcb-9f5b-4c01-b7da-71a9b06db5e2', '119c16d5-1047-45ec-8242-c72a8eed423b', 22, 'D.W.''s Baby', 'D.W. was excited to have a new little sister, but when she doesn''t get to help much and the baby moves into her room, things don''t seem so great. Kate stinks and makes a lot of noise. D.W. hatches a plan to get rid of her, but finds that maybe being a big sister isn''t so bad after all.', '1996-10-21', 13, '/ndmmklmlqDfLFVAhCQti1IMEto.jpg', '2026-04-03T17:37:55Z', '2026-04-03T17:37:55Z');
