INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('3c2f7f48-a7e8-44c9-b20d-cc11fe3cbb0f', 'a4843a51-aeef-427c-902c-7fb3bd670cd4', 23, 'Need a Little Help Today', 'Bear has caught a cold and his nose is so stuffed up that he just has to take it as assumed that the viewers smell good today. Tutter suggests he get a little rest on the couch and then the kids all decide that they''ll do their best to help Bear feel better. Tutter recalls that when he needed some water, Bear helped him to reach the faucet. Ojo brings Bear her favorite toy, Snow Bear, to help cheer him up. She recalls the time when he helped her to feel better when she fell down while trying to fly. Pip and Pop deliver Bear a package containing a clam with the message "Get Well Soon." They recall the time when Bear let them be postal delivery otters. Treelo gives Bear a hug and recalls the time that he was afraid of going down the drain in the bathtub. And Tutter recalls a time when he wasn''t feeling all that well himself.', '1997-11-19', 25, NULL, '2026-04-03T17:35:31Z', '2026-04-03T17:35:31Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('3c3266f2-d2af-44e0-a62c-46ed562a22c2', '573fa62f-55a9-4f17-97cc-d1a005a83cc8', 6, 'Rudy''s Doctor Dilemma', 'Rudy is afraid of getting a shot at the doctor''s office, so Nina and Abby play pretend to show what the visit will be like so he can feel less scared.', '2025-02-20', 26, '/eG7koSU8Rk9tBLkIjnxwLobRsMo.jpg', '2026-04-03T17:36:52Z', '2026-04-03T17:36:52Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('3c34a2c1-eccb-4f3a-b4fa-6868c44a05ac', '1e085f65-4b69-4500-8ffc-654d2f638dbb', 18, 'Tamir''s Water Works', 'Tamir needs to figure out how to keep the community garden watered while he''s away at camp. With his friends'' help, Tamir makes an irrigation system.', '2024-03-07', 26, '/jXIVMOUjgOeLHJ6ZddTI5sC5olA.jpg', '2026-04-03T17:36:51Z', '2026-04-03T17:36:51Z');
