INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('3c469e0a-7284-4838-af23-61fffea0c019', '842c6419-ab98-4d34-8845-1d9782291aad', 4, 'Gratitude', 'Zach plans to invite a lot of classmates to his birthday party -- more guests means more gifts! -- until his parents tell him that they can only afford a small party for Zach’s closest friends. Disappointed, Zach retreats to Plato’s Peak where he hears several tales which demonstrate the importance of gratitude.', '1998-03-08', 30, NULL, '2026-04-03T17:38:34Z', '2026-04-03T17:38:34Z');
