INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('3c5690b0-9608-4364-9ac3-746887d930d2', 'f6015d9a-ece4-414a-a00b-06cf689fe40b', 20, 'We Love Eurovision!', 'We''re having a Eurovision party, as UK entry SuRie performs her song Storm in the studio. We also catch up with Scott Mills and Rylan Clark-Neal in Lisbon for the latest Eurovision update. Also, there''ll be more of you receiving your diamond badges and there''s another chance to enter our Flying High competition, and be in with a chance of winning a once-in-a-lifetime prize.', '2018-10-16', 160, NULL, '2026-04-03T17:22:10Z', '2026-04-03T17:22:10Z');
