INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('3c6cd24e-a29a-4899-8919-d60bd7916619', 'f5474771-8930-41eb-b0d4-db442233acee', 4, 'Steve Irwin''s Ghosts of War: Chapter I', 'In this epic two-part mini-series, Steve revisits some of the notorious and legendary battle grounds of the Pacific conflict between the Allied forces and Japan.', '2002-08-07', NULL, NULL, '2026-04-03T17:39:10Z', '2026-04-03T17:39:10Z');
