INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('3dae525a-79fe-4269-a13f-781b3aac60ea', '45e64a15-8fc0-4e4b-a1ca-9e3f42f3634d', 20, 'Eyeball', 'Look no further ... Bill Nye is on the ball - the eyeball.   For their small size, your eyes do an important job. By working with your brain, your eyes can tell the   difference between thousands of different colors. They can follow a fast-moving hockey puck across the   ice. They are even sending messages to your brain about what you''re reading right now. Eyes work a lot   like a camera. They take in light, focus light, and make images. With help from the brain, your eyes help   understand the world around you.   Light bouncing into your eye passes through an opening called the pupil. If you look in the mirror, your   pupil is the black area in the middle of your eye. The pupil can open or close, depending on the brightness   of the light. After passing the pupil, the light is focused onto the back of your eye by the lens, a thin layer   of cells. On the back of your eye are special cells called rods and cones that are sensitive to light. These   cells send electrical messages to your', '1994-02-11', 26, '/liet78quyNwphWl8GLLgJZ30oeH.jpg', '2026-04-03T17:37:20Z', '2026-04-03T17:37:20Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('3dafcec6-5ec7-4d5f-8de9-657b6e83698b', '6fd9fd9d-e378-411b-94b1-76ba4bd518fe', 38, 'Episode 38', 'with Christopher Trace, Valerie Singleton and John Noakes.', '1966-01-31', NULL, NULL, '2026-04-03T17:21:48Z', '2026-04-03T17:21:48Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('3db09625-a385-4f3b-aca8-c44cc3206a07', 'bd5f5a3f-07fa-4689-b67b-02be5d65f1b2', 16, 'Postman Pat and the Double Disguise', 'Tom and Katy want to be grown-ups so they can help out, but they soon discover that being small has its advantages.', '2006-03-02', 15, '/vkeKJtdUcqmWc1GQlwl5beHsAZ4.jpg', '2026-04-03T17:14:31Z', '2026-04-03T17:14:31Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('3db53038-9a34-44d3-a122-984204bfb664', 'bc1b58b0-f2d6-4214-914b-231f27fb4d61', 12, 'Auld Lang Syne for an Eye', 'The wives get set to ring in the new year by trying fresh approaches to life: Teresa works on her new cookbooks; Melissa tries to live out her dream; and Caroline''s daughter vows to shed pounds. The gang then celebrates New Year''s Eve at the Brownstone, but backstabbing and finger-pointing prevail.', '2011-08-07', 43, '/mBBVAPTnDYDj6dr5hI2XmNibDvP.jpg', '2026-04-03T16:35:15Z', '2026-04-03T16:35:15Z');
