INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('3dc89185-01dc-43f3-bc2a-1ec9be450680', 'ec8d3322-8ca2-4e8d-9d22-268aee320274', 4, 'No More Mr. Nice Buys', 'When an outfit supposedly worn by Alice Cooper hits the counter, it''ll be "No More Mr. Nice Guy" as Rick tries to land a deal. Then, Chum gets mercenary when he makes an offer on a 7-foot tall Deadpool PEZ dispenser. Will the seller accept, or is it all a joke to them? After, Rick and Chum trade looks at sheets of MetaZoo cards with an old adversary--will Rick get burned on a deal again? And later, Rick and Corey go for the gold on a sale of a 1988 Winter Olympics torch. But will they cross the finish line?', '2025-02-12', 42, '/vWkcq7n5HDPzK3hhibrux8Q9srY.jpg', '2026-04-03T16:34:24Z', '2026-04-03T16:34:24Z');
