INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('3dd5709e-fe30-462f-8992-f4deaafc94ee', '51f03551-ba41-409d-85f4-e51bddfdf82e', 12, 'Charity Wives', 'In the Season 2 finale, fiery feuds and catty conflicts erupt when the housewives try to work together to organize Jill''s charity event. Meanwhile, LuAnn tutors Bethenny in the fine art of modeling, after which Bethenny struts her stuff on the catwalk at a Moroccan fashion show.', '2009-05-05', 60, '/seXL8liNbzZ5Cydk4ZpI9Jv3LnP.jpg', '2026-04-03T16:35:22Z', '2026-04-03T16:35:22Z');
