INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('3df58094-cbd0-4add-8a11-c8b22947cfbf', 'd7ff9136-a833-4c43-a37c-a985a34f45a9', 3, 'Throwing Stones in Glass Houses', 'Kody vents to friends about his anger over his divorce; Janelle''s sons are still not talking to Kody, and the family may celebrate another holiday separately; a discussion about Christmas blows up into the worst fight Janelle and Kody have ever had.', '2023-09-03', 43, '/j81KvhMRNURxin0hlqcwdGCGiV.jpg', '2026-04-03T16:34:32Z', '2026-04-03T16:34:32Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('3df6c938-2b15-46ff-8700-b3f113091023', '40700e8a-1dce-4895-bede-522a13a8bcad', 7, 'Pop Goes the Tiger', 'Two Siberian tiger cubs arrive in Animal Junction and pounce and pop on every ball in sight as they practice their hunting skills. An effort to make an indestructible superball sends Zoboo and the Kratt Brothers to a place where tigers live-India.', '2001-01-08', 27, NULL, '2026-04-03T17:10:55Z', '2026-04-03T17:10:55Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('3dfb8865-9479-4da1-8388-3fcb9012340f', 'fb4ecc73-cb92-4c5c-821f-92179058b37b', 81, 'Episode 3736', '', '1998-03-09', NULL, NULL, '2026-04-03T17:36:41Z', '2026-04-03T17:36:41Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('3e027a3f-6a81-4715-8b08-d7dec427c301', '66a11a09-aee2-4a7b-8543-ab080a9d1be4', 23, 'Secrets Revealed', 'Previously unseen clips of the ladies are revealed. Eileen mulls over winning an Emmy, Kyle''s daughter wants to pursue an acting career, the women snoop into Yolanda''s past and Kim confronts Lisa Rinna.', '2015-04-21', 41, '/wzoekGrbMemSwcgrGADB5GIXMCo.jpg', '2026-04-03T16:34:56Z', '2026-04-03T16:34:56Z');
