INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('3e06b1a8-632d-4bee-b2df-0e2e1778a818', '19e027c7-8626-44a9-96ba-d36b323b3a74', 9, 'The Lost Treasure of the Fraggles', 'Gobo and Red find a map that leads to the Ancient Treasure of the Fraggles.', '1983-03-07', 24, '/v7vayNpKC2zkMOJZqnhtYY30PSr.jpg', '2026-04-03T17:34:59Z', '2026-04-03T17:34:59Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('3e0d77d5-7957-404e-bfa9-a095226e193e', 'd1d267dd-e27f-4543-acb8-0d28f676512a', 2, 'Episode 2', 'with Valerie Singleton and John Noakes', '1967-09-28', NULL, NULL, '2026-04-03T17:21:49Z', '2026-04-03T17:21:49Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('3e11bcb7-a07e-43ea-b8b2-99bc8f7bf4a8', '4900fc8d-5e7e-408e-972e-ce9269d203b3', 2, 'Loose Lips and Lawsuits', 'Gina and Emily investigate a juicy rumour about Shannon and Heather''s old friend, Nicole; Gina feels compelled to reveal the truth, resulting in an explosive string of arguments that shuts down Heather''s party.', '2021-12-08', 44, '/1pqwBq5GsVOme4kPI5NgL71ULlL.jpg', '2026-04-03T16:35:35Z', '2026-04-03T16:35:35Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('3e1812b6-5f1d-4af8-81d5-e8ded617a43e', 'f4c40307-9b5e-4263-a4e0-dfa138131e7f', 36, 'Fiesta!', 'Fiesta means party in Spanish, and Sesame Street is pulsating with activity in this upbeat preschool program featuring Latino songs. Jim Henson''s Muppets join the fun while everyone''s favorite, Elmo, learns the Conga-Wiggle dance. Maria, Rosita, and Gabi create floats and costumes; even Oscar reluctantly partakes in the festivities. The dialogue is sparse in order to devote most of the 30-minute show to singing and dancing during eight Spanish/English tunes, featuring special performances by Linda Ronstadt and Celia Cruz. Most of the music will be familiar, such as "Conga Counting Song," "Amigo," and "It Sure Is Hot." Kids will also learn greetings, familiar words, and numbers in Spanish. While some might wish for the addition of live-action scenes of Mexico or a more complex story line, the bilingual focus is solid and the ever supportive cast of Sesame Street grownups, kids, and Muppets make it a neighborhood worth visiting.', NULL, NULL, NULL, '2026-04-03T17:36:27Z', '2026-04-03T17:36:27Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('3e1e69e3-9a88-41fb-858d-91a64ef099cb', '3982796b-5451-4100-9042-46bedf6a20a5', 2, 'Pingu''s Admirer', 'Pingu goes to school. On the way he meets Pingg, Pingo and Pongi playing limbo, and joins in, but then the schoolmaster rings the bell. The schoolmaster has just started the lesson when a new student arrives. The new student is a girl named Pingi. The schoolmaster greets Pingi, and he finds a place for her to sit. Unlike his friends, Pingu does not want anything to do with her. He spreads out his things all over his desk and puts his legs wide apart to make it seem as though there is no room at his desk, and is infuriated when the schoolmaster picks his seat anyway. Pingo offers Pingi a lollipop, which she takes and offers to Pingu. He refuses, so she gives it back to Pingo. She then draws a heart and offers that to Pingu, and he snaps at her, earning himself a reprimand from the schoolmaster, who firmly orders him to be nice to her. On the way home after school Pingi follows Pingu and, when Pingu lets her have a piece of his mind, she cries. Pingu walks away, and Pingi throws a snowball at him. He throws one back in retaliation, but it goes through the window of a nearby igloo. He and Pingi both hide in a barrel to escape the wrath of the igloo''s irate owner, and they end up liking each other. They walk together the rest of the way and Pingu actually cries a bit when they have to part.', '1991-11-04', 5, '/aZSmGX3LaYjjHrH7wNfVkvAylyG.jpg', '2026-04-03T17:22:19Z', '2026-04-03T17:22:19Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('3e26417b-00af-4cf9-9c69-fa929b07f813', '33825a15-37dc-4ff9-82bd-cc720498149a', 1, 'Of Friends and Frenemies', 'LeeAnne is overwhelmed by the planning of her wedding; D''Andra inherits the family business which isn''t doing as well as she thought. Stephanie hosts a “Friendtervention” in an attempt to help mend fences between former besties LeeAnne and D''Andra.', '2019-09-04', NULL, '/4LvFsAw7PRwwR0k20EsXvdcvJYe.jpg', '2026-04-03T16:35:04Z', '2026-04-03T16:35:04Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('3e2cad8d-282e-4cd3-b967-e1a81bf832dd', '4892e2af-46c1-4b4e-ac81-eac161b5a347', 22, 'Episode 22', 'Rags, the "Blue Peter" pony, has finished her training and passed all her tests. Today, "Blue Peter" film cameras follow her progress as she starts work as a fully-qualified pony for Handicapped Riders.', '1977-11-24', NULL, NULL, '2026-04-03T17:21:53Z', '2026-04-03T17:21:53Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('3e317086-e3b4-4654-91ed-030aafe9902d', 'e48599f8-66ff-4c0f-9274-65b9ae1cda9e', 5, 'Episode 5', 'Rags at Ascot  Blue Peter''s trainee pony for handicapped riders goes to the races and joins the VIPs in Tattersalls at Britain''s premier race-course.', '1976-09-27', NULL, NULL, '2026-04-03T17:21:53Z', '2026-04-03T17:21:53Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('3e3b291d-1ea3-4b02-bef7-4e75c794f33a', '97a3d1f5-a8f1-47cd-8122-2e74a092836d', 5, 'Get the Message (1)', 'Tina is videotaping Max setting up his instruments when he is nearly killed in a car accident caused by Mr. Fernandez. Fernandez says that he swerved to avoid hitting someone that ran in front of his car, but Max thinks he did it deliberately. Lenni begins accuse Fernandez of being a reckless driver and Alex angrily begins stalking Lenni. Gaby breaks up her friendship with Tina when Tina writes an unpleasant story in the paper.', '1993-10-03', NULL, NULL, '2026-04-03T17:40:28Z', '2026-04-03T17:40:28Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('3e452d9f-c09c-4afd-ae48-b7acb5022541', '543ec6dc-c6c7-447c-b5a7-4484d9618391', 1, 'Welcome to the District', 'In the series premiere, Michaele hosts a Polo event with some high members of society, including the Ambassador of India, Michelle Jones and Republican Lobbyist, Edwina Rogers. Lynda is reluctant to go due to old rivalries, Mary is tied up with the guest list for her birthday party and Cat gets a lesson in public relations at Stacie''s dinner party.', '2010-08-05', NULL, NULL, '2026-04-03T16:35:01Z', '2026-04-03T16:35:01Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('3e5171f2-3d3d-40c4-8ddc-b66c5334f2a0', '4d0fd8a5-5200-4dfc-b96c-ae436dc8803c', 2, 'The Wall', 'LeVar visits the Vietnam Veterans Memorial in Washington DC, and discusses its historical significance to helping people learn about the service men and woman who died in the war. Artist Mia Lin, who designed the black granite wall, is profiled as she describes the reasons she chose the materials and design style for the monument. Jason Ruggiero reads the featured story of a boy who accompanies his father to the monument to search for his paternal grandfather''s name on the wall, and his observations of other visitors.', '1992-10-06', 30, NULL, '2026-04-03T17:36:18Z', '2026-04-03T17:36:18Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('3e57c898-fb94-4cd7-bcd3-23a8fed5a908', 'fd0f7dfb-28aa-4687-9ef8-8ff0088ce25a', 9, 'Leela''s Cell Phone Addiction', 'Zoe and Abby are frustrated that Leela constantly texts.', '2013-10-17', NULL, '/zGQoKeLI3jd1G7bC2OcxW8R2CiV.jpg', '2026-04-03T17:36:47Z', '2026-04-03T17:36:47Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('3e62bac2-0f63-4f4a-8be6-05201bc884e6', '5c4e51c6-e207-46ad-875c-72988eb1e13e', 37, 'Rick or Treat', 'The Pawn Stars are ready for Halloween when a 19th century vampire killing kit stakes out the shop. Complete with a gun and silver bullets, will Rick try to hunt down these terrifying tools or will an eternal negotiation spook the deal? Then, a couple appears in the store with a set of equipment used for paranormal investigations. Everything for recording evidence of spirits, will this ghostly gear capture Rick''s attention, or will lack of proof leave him feeling skeptical? And later, Rick tries to get the guys into the holiday spirit when he holds a costume contest in the shop. Will they dress to impress, or will this haunted holiday become a bust?', '2011-10-24', 21, NULL, '2026-04-03T16:34:17Z', '2026-04-03T16:34:17Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('3e6b43fb-7b6a-424a-93ec-d7a712ba0a44', '3fdccc2c-e563-42fb-8874-c93879cd4141', 4, 'Baa-d Hair Day', 'The flock don''t recognise Shaun when he loses one his most distinctive features. His old pal Bitzer helps him track down the lost thatch, but not before Shaun becomes very attached to one of the chickens.', '2016-09-08', NULL, '/R1A91YpIDYX7RIrujYZYxSYAlG.jpg', '2026-04-03T17:39:32Z', '2026-04-03T17:39:32Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('3e6bd41d-c4bc-4cae-8b63-c90580d8cb12', '447296c1-2426-4e98-827a-13f4a36afcdd', 1, 'Is That Kosher?', 'Francine''s convinced that she can fast on Yom Kippur just like her older sister. But then Arthur wins a free pizza party for all his friends for that very same day! Will Francine be able to resist?', '2008-10-06', 13, NULL, '2026-04-03T17:37:59Z', '2026-04-03T17:37:59Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('3e6ebcd1-0b28-4a69-a72d-cb4eb5496dce', '119c16d5-1047-45ec-8242-c72a8eed423b', 14, 'Buster Makes the Grade', 'Buster''s grades aren''t as good as his jokes, and now he is on the verge of repeating his third grade year. If he does not receive at least a B on his next test, he fails...', '1996-10-15', 13, '/dxB9CQ2aJKBOppmKiGSepBE9hvx.jpg', '2026-04-03T17:37:55Z', '2026-04-03T17:37:55Z');
