INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('3e8cc7b9-7ecf-41a8-9acd-e7e7788ea048', '3af7ea64-fa13-4097-b8e4-40af07083054', 65, 'Episode 65', 'In preparation for Chrissy and Terri''s puppet show, Mister Rogers has made an "icebox cake" from chocolate wafers and whipped cream. Before the play, the Neighborhood of Make-Believe finds Lady Aberlin in search of the world''s smallest talking witch.', '1974-05-17', 28, NULL, '2026-04-03T17:35:40Z', '2026-04-03T17:35:40Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('3e8dcfc1-0c89-4f2a-b659-1438e22fd9bd', '6f731e6b-d3c5-4de6-84e1-7a19cb650e86', 22, 'Racing Revolution', 'Rev your engines with the Pawn Stars when a limited edition 2014 Hertz Penske GT Mustang races around the Las Vegas Motor Speedway. Will Rick ride into victory lane with a deal or will he be forced to make a pit stop? Next, a 1600s lobster tail helmet from Oliver Cromwell''s army battles its way into the shop. Will Rick join the revolution or will he be defeated? Then, an old fashion apple peeler gets Corey cranking. Will he feel it in his core and make an offer or will the deal go bad?', '2016-01-13', 21, '/2yqGbpeyhhsNdIH9XsCUz0ExvuC.jpg', '2026-04-03T16:34:20Z', '2026-04-03T16:34:20Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('3e8f80ee-bf32-4951-b4fd-f9be976e05c0', '0ebba123-871d-4d2b-a054-eb85d2ad9450', 47, 'Veggies in Space: The Fennel Frontier', 'Captain Cuke (Larry the Cucumber), First Officer, Mr. Spork (Bob the Tomato), and the rest of the crew of the USS Applepies are sent to stop the evil space pirate, Luntar the Looter (Mr. Lunt). Its theme is the power of sharing.', '2014-03-11', 30, '/e4nPZ0NPLCJ13FLjQse3Pye0AiO.jpg', '2026-04-03T17:39:39Z', '2026-04-03T17:39:39Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('3e8fb386-bc84-4dbe-a9d6-35b0dfaefbed', '0987f081-b3b7-4e3c-abb7-795e56c279d5', 12, 'One Kid at a Time', 'When Frankie and Mike dedicate a day to each of their children, Axl takes them to a paintball range, Sue has them do 17 separate activities and Brick wants to go to a sci-fi convention.', '2013-01-16', 22, '/kcrdtYhc6PSaHH4FmxZDJgqNzg3.jpg', '2026-04-03T15:40:30Z', '2026-04-03T15:40:30Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('3e96212d-a030-457c-84bd-917d87f81836', 'd5351b60-8a0c-482a-a6dd-4fb860cfe143', 24, 'Episode 1414', 'Mister Rogers arrives with two party favors and shows how it uncurls when he blows into it.  In the Neighborhood of Make-Believe, Queen Sara shows concern over the whereabouts of Lady Aberlin and Daniel Striped Tiger.', '1975-03-20', NULL, NULL, '2026-04-03T17:35:41Z', '2026-04-03T17:35:41Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('3e98a087-b69b-4534-92c1-eb5a7138bab9', '331fc1df-6d70-4d79-b585-bf28024a4124', 22, 'Alarm On The Beach', 'When James and Mandy find a crate on the beach, they try to open it, but end up trapping James'' legs under the crate.', '2008-12-10', 10, NULL, '2026-04-03T17:14:39Z', '2026-04-03T17:14:39Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('3e9f6549-0e38-42f6-97d6-49daa5e1855e', 'ffc2a75e-0ffa-4b26-b121-9b91b277594a', 8, 'Tea With a Side of Squashed Beef', 'Kandi can''t seem to keep the peace with her family while Phaedra looks ahead toward life as a single parent. Claudia''s mom and grandma touch down in Atlanta to have some fun. Kenya accepts an invitation to sit down with NeNe, Cynthia and Porsha--which ends with a surprising conclusion. ', '2014-12-28', 43, NULL, '2026-04-03T16:34:47Z', '2026-04-03T16:34:47Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('3ea14137-73c5-4d06-a773-f7a1b3274f11', '1d455f60-41e8-4800-9359-4445e4df2b77', 7, 'Environment', '', '1990-06-01', 30, NULL, '2026-04-03T17:35:45Z', '2026-04-03T17:35:45Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('3eb03acc-6244-4cca-b60d-1fa1fb0bd331', '3d4e0e45-1c67-475e-b37d-9e7e6b8b942a', 7, 'Moonbone', 'Would you believe a missing Super Bowl ring could be traced to Wishbone?  Hard for him to notice, as he imagines himself as Franklin Blake in Wilkie Collins''s The Moonstone.', '1997-03-09', 28, NULL, '2026-04-03T17:10:42Z', '2026-04-03T17:10:42Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('3eb343f7-c8a2-4731-8d9c-c97b46b7e4dc', '5c4e51c6-e207-46ad-875c-72988eb1e13e', 17, 'Over the Top', 'Run for cover with the Pawn Stars when a World War I helmet blasts into the shop. The first metal helmet used by U.S. forces, will the guys butt heads to buy this piece or will they dig in for a long negotiation? Then, Corey and Rick are presented with a gun holster used on the long running TV show Gunsmoke. Will they round up a posse and go after this prop with guns blazing or are they just blowing smoke? And later, Rick decides the guys could use some exercise and hires them a personal trainer. Can he convince these couch potatoes to "feel the burn" or will they decide there''s no gain to pain?', '2011-06-13', 21, NULL, '2026-04-03T16:34:16Z', '2026-04-03T16:34:16Z');
