INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('3f1b1b9a-b362-4868-90fe-34484c418e2c', 'e48599f8-66ff-4c0f-9274-65b9ae1cda9e', 25, 'Episode 25', 'Lifeline Lebanon  As the result of the Civil War hundreds and thousands of children and babies-many of them orphans-are in a desperate condition. Some are badly burned, others have been injured by shells and gunfire, all are suffering from malnutrition and are in need of urgent medical care. Britain has provided the only mercy mission to be allowed into the war zone, but to keep this lifeline going and enable the doctors and nurses to extend their stay, Blue Peter is asking for your old postage stamps and postcards. 300 old stamps or 10 postcards can be sent for the minimum postage rate of 61p. Even the smallest donation will help to save a life so send it off to: [address removed]', '1976-12-06', NULL, NULL, '2026-04-03T17:21:53Z', '2026-04-03T17:21:53Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('3f1b8263-024a-467e-8bdc-3005901dbbbc', '5a771f52-fe96-4ea2-b567-a8dde899059e', 14, 'Series Rings and Rap Kings', 'The Gold & Silver is brushed with a stroke of luck when an original Marc Chagall painting draws Rick''s attention. Will he master this piece, or will he gloss over it? Later, Rick takes a swing at buying a Boston Red Sox World Series ring. Can he strike a deal, or will he strike out? Corey goes crazy for a first edition of Ken Kesey''s novel, "One Flew Over the Cuckoo''s Nest." When the BMW that legendary rapper Tupac was shot in rolls up, all eyes are on Rick and Chum. Will they drive this deal home, or decide to steer clear?', '2018-01-22', 21, '/naDZSOwvuXrimnZQQKAMMvYKzq5.jpg', '2026-04-03T16:34:21Z', '2026-04-03T16:34:21Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('3f1e30f0-84a3-4028-b3da-7a65bdd0c78e', '1d556682-d9bb-47e1-993f-0b648a8daacd', 118, 'Episode 1303', '', '1979-05-09', NULL, NULL, '2026-04-03T17:36:33Z', '2026-04-03T17:36:33Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('3f220738-8ff2-4c47-a16a-3a8d579686da', '3a96d6c6-3736-498a-926f-6c479cdfb73a', 8, 'Franklin''s Halloween', 'It''s Halloween and everyone''s buzzing about. They all can''t wait for the Halloween party. When strange noises and ghosts appear, Franklin thought it was Bear until he heard he was home with the flu.', '1997-11-13', 12, NULL, '2026-04-03T17:40:14Z', '2026-04-03T17:40:14Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('3f32b71c-5357-435b-9b95-26328a9e4c07', '54900370-8988-46b8-b7aa-61d2b88d7056', 1, 'Hot Dogs and Hearsay', 'Angie arranges a surprise RV trip for the women, but with Lisa gone for work, Bronwyn brings up some rumors she’s heard about Lisa’s business. Tensions brew as Britani calls out Whitney. Heather and Bronwyn go head-to-head. Angie makes a bold claim about one of the women. A ghost of Salt Lake City past creates a haunting evening for the ladies.', '2025-09-16', 54, '/hxUhPDgG4mFkHxjQJAdEs3GqERx.jpg', '2026-04-03T16:35:46Z', '2026-04-03T16:35:46Z');
