INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('3f363807-3f7e-4788-8309-1213b676f3cd', 'f9a8d8b3-d72e-437e-a9d5-7477f6d64df8', 29, 'Wash Day', 'It’s Wash Day today, and Gabrielle gets to spend time with her Auntie, Kayla. Auntie Kayla combs, shampoos, conditions, and detangles Gabrielle’s hair. During bath time, Gabrielle’s hair is twisted up in a shower cap and at the end, Gabrielle gets to pick out a new style for her hair. Wash Day is really special to Gabrielle and her family.', '2023-05-18', 26, '/imaH8o07fZOwPpdyFzMeQxFHpvx.jpg', '2026-04-03T17:36:51Z', '2026-04-03T17:36:51Z');
