INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('3fc1d618-e918-4926-9c7d-5cbe01e1d8d3', 'c01ddd2a-bdb1-4c97-8d04-58f791ef1c24', 6, 'Swimming', 'The arrival of a couple of river otters prompts a swimming party, with black jaguars, soft-shelled turtles, penguins, and capybaras jumping in. Jackie and her dog Goldie join in with a swim in MudPuppy Pond, where they meet even more water creatures.', '1999-02-01', 27, NULL, '2026-04-03T17:10:55Z', '2026-04-03T17:10:55Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('3fc66eff-84e8-42ab-a48b-000442d682f6', '1415ef1c-411a-4c26-814a-7c79c3628bc2', 1, 'Talk of the Town', 'Luann catches Dorinda up on how her wedding plans are unfolding. Dorinda complains about Sonja''s persistent bad mouthing of her. Bethenny and her realtor friend Fredrik get to work to sell the apartment she got back in the divorce. Carole has made some changes to her living situation. Luann confronts Ramona about Tom.', '2017-04-05', 60, '/pRy4MvN3s6vkIaiW2pRquCAuT73.jpg', '2026-04-03T16:35:24Z', '2026-04-03T16:35:24Z');
