INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('3fc96c0d-fdfd-4149-a173-42eeed2f5e5e', 'de8ec769-16bb-436b-be43-aedc7e18a7d7', 11, 'The Great Fruit Strike', 'When the pineapples, bananas, and other fruits get tired of being passed over at snack time, they decide to leave Sesame Street. The gang gets together to sing songs about how much they appreciate fruit to get them to stay.', '2020-01-25', NULL, '/tK4tyaFN4fkHrXPn5ZLqtiJ9ofa.jpg', '2026-04-03T17:36:50Z', '2026-04-03T17:36:50Z');
