INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('3fe517d9-6ee6-445c-9df7-5a8634dac2d4', '6b5caa66-f66f-4ed1-817f-a00bad08790e', 5, 'Casinos and C-Cups', 'Dina, Caroline and Teresa head to Atlantic City for a weekend of shopping, gambling and spa treatments. Teresa has an argument with her husband about plastic surgery after going bikini shopping, while Danielle is down in the dumps after splitting up with her boyfriend and turns to her children for support. Later, she pops out for a friendly birthday lunch with Jacqueline.', '2009-06-09', 43, '/i2BBLaiFmRKcTj5Dsr7mEocxGkD.jpg', '2026-04-03T16:35:14Z', '2026-04-03T16:35:14Z');
