INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('3ff1d900-e674-476b-b734-68f68352474d', '1a534647-384b-4c00-bb6c-a3371ad962eb', 18, 'Hot Dam', 'The crowd goes wild with the Pawn Stars when concert posters signed by Johnny Cash and Stevie Ray Vaughn rock and unroll the shop. Will Corey get them for a song, or will they be out of tune? Then, Rick feels the rush when checking out original blueprints of the Hoover Dam. Will he flood the seller with offers or will the deal hit a wall? And later, when Chum breaks Rick''s new expensive sunglasses, will he come clean or replace them on the cheap?', '2015-03-19', 21, '/doI5pJqMr03hkRW7T5PrpzG73uM.jpg', '2026-04-03T16:34:19Z', '2026-04-03T16:34:19Z');
