INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('4040d897-7535-47bb-8965-eb36e12e4abe', '5144de59-e67f-4fcf-919b-7106989ab797', 32, 'You Say Potato', 'The kids bring in items for a picnic but can’t seem to agree on where to have it. While Leon and Jody are content to go anywhere, Skye and Julie prefer the mountains and Ben and Kiki prefer the park. Even the two duos can’t agree on the specifics. Sizzle and Nuzzle are excited to go on the picnic themselves, especially for bird-watching.', '1995-02-28', 29, NULL, '2026-04-03T17:12:21Z', '2026-04-03T17:12:21Z');
