INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('404e6185-204c-4e57-b170-eafad48434d1', '04fb713d-9c59-45f7-8de0-acd7582daa53', 16, 'Reunion Part 1', 'Margaret and Jennifer exchange heated words while addressing their ongoing conflict; Teresa accuses Jackie of having ulterior motives for joining the show, and she makes it clear that she will never forgive what Jackie said about her husband.', '2019-02-20', 43, '/iZLD1CfTmJJK7UKD6zsAJZlfmTN.jpg', '2026-04-03T16:35:17Z', '2026-04-03T16:35:17Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('404fe307-02e1-4111-a8b4-1cc06a60ad06', 'fed71eea-5d41-479c-b12a-beb733409c5c', 16, 'Oscar''s Clean Tuxedo', 'Leela and Elmo remember and recreate three of the yuckiest stains on Oscar''s tuxedo.', '2015-01-14', NULL, '/bX4GNfuqyRhbIxeEUwMSj8wpVlj.jpg', '2026-04-03T17:36:48Z', '2026-04-03T17:36:48Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('406f003d-1202-46cc-b0af-6f28165375a8', 'f812042d-eb85-432e-8047-3675886e0b1b', 23, 'Bark to the Future', 'Joe learns that his own intellect can never be replaced by modern technology. Meanwhile, Wishbone, as The Time Traveler, finds that in the year 802,701 the lazy Eloi have allowed their intellect to be replaced by technology in H.G. Wells'' The Time Machine.', '1995-11-06', 28, NULL, '2026-04-03T17:10:42Z', '2026-04-03T17:10:42Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('40713bbc-2b25-4faa-be86-b092a79340fb', '3269a890-bba9-4e6c-9278-f7eb38eb1720', 20, 'Animal Locomotion', 'Some animals have wings that let them fly and hover. Other animals have legs, from two to more than 200, to get them walking, galloping, or running. Some animals’ legs are really pumped-up for powerful jumps. Animals also strut, stroll, slither, swim, slime, sprint and squeeze their way around.', '1995-10-27', 26, '/9dB5nkV6J542S67Wi6LEYCa0ydZ.jpg', '2026-04-03T17:37:21Z', '2026-04-03T17:37:21Z');
