INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('40af0bde-8109-4851-b42b-84ab6cc7d7fe', '573fa62f-55a9-4f17-97cc-d1a005a83cc8', 23, 'Garden Explorers', 'To find Gabrielle''s lost charm bracelet, Elmo, Abby, and Gabrielle play garden explorers and use their five senses in the Community Garden.', '2025-06-19', 26, '/hhMZIEhwhfe6Orls0i34pjUSk4y.jpg', '2026-04-03T17:36:52Z', '2026-04-03T17:36:52Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('40b96726-b518-46eb-b489-987821f693fc', 'c6d5cf79-f2b0-40af-ad12-91aa4f1b1d21', 3, 'Pawned Lightnin''', 'Rick and Corey race to San Diego to take a spin in the classic car Hell''s Chariot, from the movie Grease. Is the flaming hotrod the one that they want, or will they "drop out" of the deal? Then, Chum takes a whack at a Punch-A-Bag game once played by Jack Dempsey. Will he score big, or will he get KO''d? Meanwhile, will Rick see red when he hears the asking price for a set of University of Alabama school rings? And later, will a set of Three Stooges trading cards have Chum laughing all the way to the bank, or will his offer be a slapstick in the face?', '2022-05-07', 42, '/eFKSnaEALuzirhCUjOx9L92iz8C.jpg', '2026-04-03T16:34:23Z', '2026-04-03T16:34:23Z');
