INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('40c95c45-5a40-4a4b-bf5f-747e2cd7457c', '42e591e2-2a88-4434-ae9f-3d4b1d685613', 30, 'Comfortably Chum', 'Get ready for a bumpy ride with the Pawn Stars when a big-time car dealer drops by the shop. Interested in buying their 1924 Dodge, will Rick have the negotiation skills to battle this car pro? Then, Rick and Corey check out some uniforms owned by a 3-star general in the Soviet Army. Dating back to the height of the Cold War, will the guys be seeing green or red? And later, while his house is being bug bombed Chumlee needs a place to crash. Will the Old Man''s couch be a dream come true or a nightmare?', '2013-10-24', 21, '/fzECHPRk8BxcSDebotXKu4gevXO.jpg', '2026-04-03T16:34:18Z', '2026-04-03T16:34:18Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('40cdeebd-c4ac-46d8-b8e2-35bfb86e37c1', 'e2909bec-d580-4388-acdc-22ade5168644', 15, 'Music', 'Rogers visits a man with a wide assortment of musical instruments. In the Neighborhood of Make-Believe, everyone hurries over to Westwood, where the Bass Violin Festival is held.', '1985-05-17', 30, NULL, '2026-04-03T17:35:43Z', '2026-04-03T17:35:43Z');
