INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('4132365e-d288-4a20-ae57-de829074a49e', 'fe19a277-aed8-44df-a4ac-fc1c4e9941b4', 5, 'Home Is Where the Heartbreak Is', 'Lisa and NeNe go shopping to prepare for their trip to L.A., and NeNe meets with photographer Derek Blanks to discuss her “Alter Ego” photo shoot. Shereé meets with an event promoter to discuss Mercedes Benz sponsoring her “She By Sheree” fashion show. Meanwhile, Lisa brings NeNe for a visit with her family and a celebration of her grandmother’s 92nd birthday. Back on the East Coast, Kim visits Kandi in the recording studio. As they bond, Kim asks Kandi to produce "Tardy for the Party" for Kim and NeNe to record.', '2009-08-27', 43, NULL, '2026-04-03T16:34:45Z', '2026-04-03T16:34:45Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('41331c6e-a34b-42ac-ad71-688e82db6475', '1cfdff3a-d531-4a9e-afc9-8010a979dd27', 3, 'The Voyage of the Dawn Treader (1)', 'Nasty cousin Eustace accompanies Lucy and Edmund on a new adventure in Narnia.', '1989-12-03', 30, '/nkRHZum6jiWXViI4o8rEmdgqaEK.jpg', '2026-04-03T17:17:41Z', '2026-04-03T17:17:41Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('413d7342-5a8b-46f5-bee7-1d2beef34024', '5b5e8b2f-0a85-4488-b3dc-3d8b794e6582', 8, 'Run for Your Wife', 'Vicki turns green with envy after learning that Kelly is celebrating St. Patrick''s Day with Shannon and Meghan; Lydia wonders if her son''s prophecy will come true as she competes in a race; Meghan, Shannon and Kelly indulge in whiskey and whimsy.', '2017-08-28', 44, '/wQ3866mo7hdBchA4qxG1EnrPkAn.jpg', '2026-04-03T16:35:33Z', '2026-04-03T16:35:33Z');
