INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('41421034-5424-40b1-85fd-4514a8070e5c', '4bf3b194-81b8-4726-8850-62b05609eac8', 17, 'Porridge For Breakfast', 'MacWomble sends the young Wombles out to gather bracken to make porridge.', '1975-10-07', NULL, NULL, '2026-04-03T17:23:20Z', '2026-04-03T17:23:20Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('41436710-b7a4-4550-83ac-355acff6edef', '5c1b881f-ac58-4d72-b63f-209952d4f902', 10, 'Episode 10', '1066 and All That....  It''s 913 years since Britain was successfully invaded and next Sunday marks the anniversary of the famous battle that took place at Hastings. Christopher has taken Blue Peter film cameras to Caen and Bayeux in France and Battle and Hastings in England to follow in the footsteps of King Harold and William the Conqueror.', '1979-10-11', NULL, NULL, '2026-04-03T17:21:54Z', '2026-04-03T17:21:54Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('41437a45-88fc-4a42-b5c3-0cf13587cc7d', 'fa6f43f4-b944-4c33-ac69-dddbf54c0c16', 5, 'Little Red Riding Hood', 'Mary Steenburgen encounters a surprise on the trip to grandmas -- he has big eyes - big ears and a set of sparkling Razor sharp teeth. He has decided to take an extra liking to "Miss Hood" as he accompanies her on her trip through the forest. He hasn''t counted on the cunning and ever-sweet Granny nor has he thought about what danger he might be in from Miss hoods admirer -- all in all the vain wolf learns that humans are just as cunning.', '1983-11-10', 51, '/637nz7MofZxtTQgy6ZoopCEyRd6.jpg', '2026-04-03T17:38:40Z', '2026-04-03T17:38:40Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('414d5f34-3d2c-4f13-861f-5ddd05587ace', '190c6e49-8849-4404-87d4-eaef943a6024', 9, 'Oakie Doke And The Orchestra', 'Doke delivers some bottles to Granny Annie''s house for her lemonade, which accidentally gets ruined by Neptune, who puts baking powder in the lemonade instead of sugar. While Granny Annie cleans up, Oakie stops by the Corncrackers'' house to teach the animals to make music and they all form an orchestra.', '1995-11-06', 10, NULL, '2026-04-03T17:19:24Z', '2026-04-03T17:19:24Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('415564d9-8d4a-42c5-a3d5-d5beae61d8cb', 'c9adc698-be92-4dd7-94ad-d8f6759361ca', 5, 'Episode 5', 'Rogers and several other neighbors attend the opening of the new soda fountain at Brockett''s Bakery. Eric Kloss visits the Neighborhood of Make-Believe, telling King Friday how the other senses tell a blind person about the world.', '1973-02-23', NULL, NULL, '2026-04-03T17:35:40Z', '2026-04-03T17:35:40Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('415a6a20-5b60-4aac-8e1c-f35ab1a45280', '5a4e38a1-8e54-4974-8097-d7a7b48630a2', 57, 'Episode 57', 'with Valerie Singleton, John Noakes, Peter Purves', '1971-04-09', NULL, NULL, '2026-04-03T17:21:50Z', '2026-04-03T17:21:50Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('41641afe-b7ea-4f9f-9764-dda572b7f6da', '9193e795-da7c-40ec-b68f-f63aa7d5174f', 110, 'Histories & Lore: The Reach', 'Margaery Tyrell discusses the history, customs, and noble houses of the Reach, the fertile region known for chivalry, knightly tournaments, farms, and vineyards.', '2014-02-18', 5, '/mjJQ8VPcboRoaKe7MkqzzP87JBT.jpg', '2026-04-03T15:40:35Z', '2026-04-03T15:40:35Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('4164eb6d-70f3-4a5d-84a8-7c3728eb66eb', 'da06465b-9154-4feb-a455-374df7dab02f', 21, 'Telly''s and Baby Bear''s Story (4103)', 'Baby Bear and Telly decide to use their imaginations to write a story together, but have a hard time deciding on whether their story should be about a magic bowl of porridge or a magic triangle. With Maria''s help, they realize that best friends should be able to work together and compromise by deciding to write a story about both! Their story takes place in the Kingdom of Dum Diddley Dum Diddley Do. In this Kingdom, there is a magical triangular bowl of porridge. The bowl has three sides and three angles, and is filled with an unlimited amount of delicious porridge that King Baby Bear absolutely loves. Baby Bear and Telly realize that they make a great team and decide to write another story together!', '2005-09-26', NULL, NULL, '2026-04-03T17:36:44Z', '2026-04-03T17:36:44Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('416a053d-8682-40d8-a386-0a6f4e01f170', '842c6419-ab98-4d34-8845-1d9782291aad', 8, 'Charity', 'When a cold front moves through Spring Valley, making life miserable for the poor, Zach and Annie decide to collect clothes donations from their neighbors. When Annie includes her favorite leather jacket, and later regrets it, she must come to terms with the true meaning of ‘charity.’', '1998-04-05', 30, NULL, '2026-04-03T17:38:34Z', '2026-04-03T17:38:34Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('416be483-9620-4d67-99de-5bf0473f162d', 'bc6d3e37-6e5e-472d-90aa-4c6df1f7def8', 6, 'Four Wives in Two RVs', 'The Browns take a road trip for Spring Break on Route 66 to Missouri to visit a non-Mormon polygamist clan, but cramped quarters in two RVs create tension among the traveling companions.', '2014-07-06', NULL, NULL, '2026-04-03T16:34:29Z', '2026-04-03T16:34:29Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('416f636a-99f7-4669-afe5-4b2881318a6d', 'c9adc698-be92-4dd7-94ad-d8f6759361ca', 10, 'Episode 10', 'Rogers'' telephone isn''t working, so the telephone repairman makes a visit.', '1973-03-02', NULL, NULL, '2026-04-03T17:35:40Z', '2026-04-03T17:35:40Z');
