INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('4197f54b-117c-47db-b39b-5fcf92d5f0f7', 'ac068b8e-80f6-46bf-afb2-dcebcf76dc36', 7, 'A Star Is Burned', 'Skye is directing the kids'' production of Rapunzel. Julie gets mad when he praises costar Ben so she hits him to get a peace of her mind. Kiki and Jody do not appear in this episode.', '1998-10-29', 29, NULL, '2026-04-03T17:12:21Z', '2026-04-03T17:12:21Z');
