INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('41a1f41a-2137-4c44-8efe-8270e0ae30db', '3fc7c152-e4f6-426a-a899-36ec454c4403', 57, 'Zak Takes a Dive', 'Zak is nervous on going swimming as he and Wheezie have never been swimming before, but he later realizes that trying new activities can end up being fun.', '2000-01-27', NULL, NULL, '2026-04-03T15:26:03Z', '2026-04-03T15:26:03Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('41aad78f-38b6-4d34-af61-19dd43198ae8', '4a8e3db0-8068-4ff3-942f-91f45f665f20', 5, 'Shooting Stars', 'The lions try to stay awake at night, in order to see a meteor shower. Of course, this is not as easy as it sounds, as Theo says, ""Lions need a solid 22 hours of sleep a day!""', '2000-04-07', 30, NULL, '2026-04-03T17:12:27Z', '2026-04-03T17:12:27Z');
