INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('41b057c8-d640-4d2a-a874-a84f74e7f65f', 'a6ed03e0-c05f-48f8-9f56-3f1da50e1792', 94, 'Episode 1409', '', '1980-04-03', NULL, NULL, '2026-04-03T17:36:33Z', '2026-04-03T17:36:33Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('41b62aac-a90d-403e-b017-a392420268fe', 'bf874be3-7e2f-4a0e-b205-c76ac1ad69fc', 118, 'Queen of the Castle: The Elaine Benes Story', 'When Seinfeld needed a girl, Julia Louis-Dreyfus fit the bill, bringing luster and laughter to the show.', NULL, 22, '/dqghFBEQRkiWax3kpNoxfwqPnqo.jpg', '2026-04-03T16:34:09Z', '2026-04-03T16:34:09Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('41b8cf1a-54a5-4e34-b136-08ae133eb540', 'd5383b3d-5636-4d71-b99c-b84774b4b3c6', 4, 'Pingu and the Big Fish', 'Mother is rolling out dough in the kitchen. Pinga is playing nearby. Pingu comes over and sees Pinga’s trumpet on the floor. He picks it up and blows it. Pinga tries to get her trumpet back from Pingu, but he won’t let go. When Pinga lets go, Pingu tosses the trumpet into the air over his shoulder, and it lands in Mother’s bowl of flour. Mother comforts Pinga, then tells Pingu off and tells him to go away. Pingu trudges outside and sees one of his neighbours telling another about his successful fishing trip. Pingu sees the bucket of fish that has been caught and has an idea. He rushes indoors and gets his fishing rod. On his way out Mother stops him, points to the clock and tells him not to be late back for supper. Pingu goes to a nearby pool and starts to fish. Pingo arrives and watches. Pingu has a bite, but hooks nothing, and Pingo laughs. Pingu is annoyed and shoves the rod at Pingo, telling him to try and do better. Pingo soon has a bite, but when he lifts the rod there’s a lobster hanging onto the bait, clacking its claws. The lobster drops back into the water, taking the fishhook with him. Then a big fish jumps from the water and splashes back in. They wonder how they can catch the fish, as the hook has gone. Then Pingu has a brainwave. He takes the handle from the bait bucket and uses it to make a large hook, which he ties onto the line. Pingu baits the hook and Pingo starts fishing again. There are lots of bubbles around the float but no bites. Later, as it’s getting dark, Father arrives home from work. He goes indoors and greets Mother and Pinga; Mother tells him that Pingu went out earlier but hasn’t yet returned. Father goes out on the sled to look for him, eventually finding him fishing at the pool with Pingo in attendance. While Father tells Pingu he should have been back home earlier, Pingu gets a bite, and it takes all three of them pulling together to land the large fish that Pingu has hooked. They proudly take the fish home, Mother cooks it and Pingu’s family and Pingo all enjoy a fish supper.', '1998-01-08', 5, '/nzyQkLDV6SR4nZ0J4FZY6GAXJ5z.jpg', '2026-04-03T17:22:20Z', '2026-04-03T17:22:20Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('41bf3751-7ebc-4088-8709-67759889b235', '387da09c-95c3-49e8-a7ff-fcbb68362cc0', 9, 'Love', '', '1993-03-19', NULL, NULL, '2026-04-03T17:35:46Z', '2026-04-03T17:35:46Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('41c90057-c636-4d9a-9d9b-595949281a18', '119c16d5-1047-45ec-8242-c72a8eed423b', 46, 'Misfortune Teller', '', '1996-11-06', 13, NULL, '2026-04-03T17:37:55Z', '2026-04-03T17:37:55Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('41d2c728-dfd9-46ad-b74c-21d06d759089', '5ba20443-d99f-4820-81f6-6832d3f2bc4f', 10, 'Flowers', 'Flowers are an important part of many plants. Plants use flowers to make other plants – to reproduce. Flowers have special parts, called stamens and pistils. When pollen from the stamen finds its way down through the pistil, the flower is pollinated, and seeds start to grow. The seeds eventually find their way to the ground, the seeds sprout, and more plants are born.', '1996-01-27', 26, '/72XaGmWtSRaeiVvWt0doULPQCyu.jpg', '2026-04-03T17:37:21Z', '2026-04-03T17:37:21Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('41d75d27-1f4d-49a2-aa65-2adf41ed65aa', '6f731e6b-d3c5-4de6-84e1-7a19cb650e86', 8, 'Riders on the Pawn', 'Run in slow motion with the Pawn Stars when a David Hasselhoff signed rescue buoy from the set of "Baywatch" floats in. Will Rick and Chum hassle the Hoff for a deal or will it get cancelled? Then, sparks fly when two flintlock blunderbuss pistols barrel in. Will Rick aim for a deal or will it be a blunder-bust? Next, Rick and Corey get energized while checking out a six person solar bike. Will they amp up the offer or will the seller charge too much? And later, Rick breaks on through to the other side when a yearbook featuring Jim Morrison is brought to the shop. Will he make a deal for the Lizard King or will he graduate without an offer?', '2015-11-12', 21, '/cY8wbsDcHpppb5D2RGg6d5msuPF.jpg', '2026-04-03T16:34:20Z', '2026-04-03T16:34:20Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('41df0309-e6da-4d6a-9fb6-9787d9a9252f', '4c79c0b6-21a4-4277-8967-be1e791efdbe', 6, 'Poor Pingu', 'Pingu wakes up, and tries to wake Pinga. She doesn’t wake. Pingu then sees she’s got red spots on her head, and suspects she’s put them on herself with the crayon he finds nearby. Then more spots appear and Pingu pulls back the blanket. Pinga is covered in spots. She has measles! She yells, and Pingu calls his parents in. While his parents comfort Pinga, Pingu is asked to call the doctor, get a wet cloth, get some milk, get a woollen hat, get some biscuits and open the door for the doctor. The doctor examines Pinga, and everyone ignores Pingu, so Pingu starts to examine the contents of the doctor’s bag. He finds a badge, but this is grabbed from him and given to Pinga who by now is starting to feel a bit happier. Pingu is fed up with the attention Pinga is getting and of being ignored himself, so he fakes that he has a cough, then a temperature and then a sore foot. All of this is ignored. Father then asks Pingu to empty Pinga’s potty, which he unhappily does. On his way back out of the bathroom he spots Mother’s lipstick, and uses it to make some spots on his head like those of Pinga. He goes back into the bedroom and pretends that he’s poorly, and he’s put straight into bed. Mother wipes Pingu’s brow with the wet cloth, and the spots start to come off! Pingu is told off, and Mother wipes away the rest of Pingu’s lipstick spots. Some proper spots then appear on Pingu’s head, and he’s now really got a temperature and the measles as well. Pingu is given his own badge by the doctor, and is now the centre of attention rather than Pinga. Pinga is dismayed, so she gets out of her bed and climbs into Pingu’s bed next to him. The doctor gives each of them a lollipop, and they quickly cheer up.', '2005-01-10', 5, '/hRQseRjLBk32OxpEhVuKU6noUSW.jpg', '2026-04-03T17:22:20Z', '2026-04-03T17:22:20Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('41e300df-38cd-4f68-b10e-e5e19924fb4f', '9193e795-da7c-40ec-b68f-f63aa7d5174f', 6, 'You Win or You Die', 'A prequel to Game of Thrones Season 2 which recaps on the first season and gives insight into what''s to come.', '2012-03-24', 22, '/6M8HOqp1AnaabsMnBDczrxMPPVS.jpg', '2026-04-03T15:40:35Z', '2026-04-03T15:40:35Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('41e396f3-e163-4e24-aa6d-2fba266c4514', '5ba20443-d99f-4820-81f6-6832d3f2bc4f', 1, 'Rivers & Streams', 'Water is massive; rivers are powerful. As rivers flow downhill, they wear away rock and soil to form canyons or winding curves in the land, called meanders. Sometimes rivers fill and overflow their banks. Rivers with too much water create floods that can carry away plants, trees, buildings and boulders. Rivers and streams support most of the ecosystems on land.', '1995-11-03', 26, '/o2AkrlCEjk1zeJTOMm6caFG8IbC.jpg', '2026-04-03T17:37:21Z', '2026-04-03T17:37:21Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('41e53722-a2ee-4f26-be19-e902f4095ccb', 'd306a064-e835-417e-8548-0cf806295f31', 18, 'Reunion Part 2', 'Larsa opens up about her new boyfriend, Marcus Jordan, and defends her fighting tactics; Julia gives an update on Martina''s multiple battles with cancer; Kiki joins the ladies and drops a bomb on Lisa.', '2023-03-16', 44, '/xyZGU5KNBqQ6522trbVvlDEPMBo.jpg', '2026-04-03T16:35:11Z', '2026-04-03T16:35:11Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('41ef8f0e-968e-4703-89c4-653ec2909039', '004abc4c-ce77-4df9-8c97-9f56ea8b37ce', 12, 'Arnold''s Drum', 'Arnold gets a new drum. He plays it non-stop at Kipper''s, Tiger''s and Pig''s picnic, throwing the big day into chaos.', '2000-04-06', 30, NULL, '2026-04-03T17:10:49Z', '2026-04-03T17:10:49Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('41f056c9-e772-4a0b-b06d-58411cc0c2d7', '751012d3-7df1-4084-8e96-0efd6559cf06', 6, 'Visiting Friends', 'Tiny Clanger builds a helicopter to visit the Iron Chicken.', '1970-01-01', 9, '/9rpzJB1YP1QQZAhYXyOCGm7iD9n.jpg', '2026-04-03T17:23:53Z', '2026-04-03T17:23:53Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('41f32361-04cc-4647-acda-cfed34fff5d1', 'e6254ae4-7d72-493b-8b37-b677d8b76c46', 21, 'Episode 686', '', NULL, NULL, NULL, '2026-04-03T17:36:30Z', '2026-04-03T17:36:30Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('41f7f74d-74c9-4108-9d08-8b3731d4e2dd', '97d7ff20-e6ff-4dbb-bcdd-fd87a1d0fa4e', 8, 'May the Miniforce Be With You', 'Corey finds out if the force is with him, when a seller comes in with two Star Wars Lego minifigures. Can he "C" his way to a deal, or will he run into a brick wall? Then, Rick and Chum mosey on down to Texas where WWE Champion Booker T helps them authenticate a pair of wrestling boots. Will they tag team a deal, or tap out? And finally, Rick tries not to pop with excitement when he checks out a Jeff Koons Balloon Dog statue.', '2023-05-03', 41, '/mHPJ8KOpS79NShwEI1CAhW9ogYm.jpg', '2026-04-03T16:34:23Z', '2026-04-03T16:34:23Z');
