INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('42061d5c-c124-4d9f-bb8b-5b270a98d9fd', '20d7138e-eea8-46a8-8ada-2b0f0ee1f674', 73, 'Episode 73', 'Tribute to Blake''s Seven!

