INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('420cf6ac-2e05-4d66-9cbd-ae45543c9e1e', 'a9657e86-4135-49ce-b1f9-c295113077e1', 9, 'Itching for a Cure', 'The friends try to build a house of cards, but the houses fall down when an earthquake shakes them. The shaking turns out to be Mungus the Giant, who has a terrible rash on his back.', '2005-02-25', 30, NULL, '2026-04-03T15:26:04Z', '2026-04-03T15:26:04Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('4210d283-d144-4583-bdf2-a2d0830e6745', 'efdf1e4f-8476-4382-a9d7-2b9da4188be0', 16, 'Brave and Strong', 'The Neighborhood of Make-Believe has witnessed cereal falling like snow over a couple of areas. It stops snowing cereal over at the Platypus Mound, but not at Daniel''s Clock.', '1996-07-30', NULL, NULL, '2026-04-03T17:35:47Z', '2026-04-03T17:35:47Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('421784ee-da5e-4d00-ad20-5bdfa3af0b3a', '1d713ca6-4e17-4f84-949c-8cfd98514127', 27, 'Rick''s a Riot', 'Rock out with the Pawn Stars when a 1969 Gibson Les Paul jams into the shop. Will the asking price be music to Rick''s ears, or is the deal too far out of tune? Then, Chum tries to score with a Los Angeles Lakers backpack signed by members of the 2004 team. Will the deal be a slam dunk, or will it be an air ball? And later, Corey calls Rick out on his most annoying habit. Will Rick change his ways or will he laugh it off?', '2014-10-30', 21, '/aBqutNmZdaGuRrigHAx7sB7Y6kh.jpg', '2026-04-03T16:34:19Z', '2026-04-03T16:34:19Z');
