INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('422c86b1-0a55-4fd7-b641-dd727e404dff', '095258d0-d8db-4096-8ac7-6a42cd4cbdcf', 17, 'Playing Till It Hurts', 'It''s time for Rock Hockey, and Red''s especially excited because her idol, Rock Hockey Hannah, is coming to watch her play. Her excitement''s cut short, however, when she injures herself. She''s still determined to play, and she escapes from her room to try it again, only to get even more hurt. But Red is becoming more and more stubborn; she doesn''t want Hannah to think she''s a wimp. So she decides to fool Feeny Fraggle and takes his place as goalie. But is playing the game to impress her hero worth the risk?', '1985-04-22', 24, '/pbNzHeZq67Jy7rYdfeCqYZXu1JC.jpg', '2026-04-03T17:35:00Z', '2026-04-03T17:35:00Z');
