INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('42bfbccb-aa98-4236-b937-11c14c731c9f', '487fdbcd-ec5a-454e-8268-b50566eb8546', 7, 'The Beauty and the Beggar', 'Ayan launches her beauty collection; Caroline Brooks and Taleen appear to make amends until Taleen hears some disparaging comments; Lesa struggles with work-life balance; Caroline Stanbury hosts a housewarming dinner that takes a turn for the worse.', '2024-07-16', 43, '/4bSaaSgrZoMRPEtDxxD978QjAJq.jpg', '2026-04-03T16:35:07Z', '2026-04-03T16:35:07Z');
