INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('43165a81-9ab9-4017-ac9c-02632c864211', '5a824218-5831-4c6d-aef3-8b5ba9147532', 18, 'Episode 1593', '', NULL, NULL, NULL, '2026-04-03T17:36:34Z', '2026-04-03T17:36:34Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('4316c799-b5bf-4399-84cd-bf2cb738600f', '4d2cac0f-38fd-438b-8afa-acf43952e535', 27, 'Episode 27', 'A weekly programme for younger viewers, including The Story of San Marco, a scale model serial and Jean and Frank: 1: Frank and his Dog, stories of some American children.  Introduced by Christopher Trace and Leila Williams.', '1959-04-23', NULL, NULL, '2026-04-03T17:21:47Z', '2026-04-03T17:21:47Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('431745f7-b6f9-403d-800c-e467172d6fe4', 'd6092173-d23b-4449-baff-e0e16fe56c9a', 13, '10.10.20', 'Cynthia and Mike''s big day is here; leaks about the South Carolina weekend spread in the press, and the women to speculate about the source; Shamea hopes to shelter the nieces from the judgmental aunties; Porsha and Dennis discuss their relationship.', '2021-03-14', 43, '/rPh2hSUNawUIQU7W7Av03fJuKH6.jpg', '2026-04-03T16:34:49Z', '2026-04-03T16:34:49Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('4318cde9-a64e-4525-9a91-8d71ce1afa18', '34bdccfa-3c14-4e1c-9148-85c29aadc0e1', 50, 'Around Africa in Eight Hours', 'Allison has lost her computer records on Africa.  Chris and Martin have only eight hours to try and revisit all the places they had been to during the series.', '1996-08-09', 30, NULL, '2026-04-03T17:11:47Z', '2026-04-03T17:11:47Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('431a5732-68fd-4788-af9e-2df4a3243f0a', '3ee646e8-23ae-4dec-bbc6-c7e6a210d55b', 75, 'Miles'' grandparents visit', 'At Gordon and Susan''s apartment, Preston Rabbit is excited because Susan''s mother and father (Dorothy and Lee) are coming over for a visit. He assumes that being grandparents, they''re going to give presents to Miles; as a present-giver himself, watching others give presents is the next best thing. As Susan’s parents try to chat with Gordon and Susan, Preston eagerly picks at the shopping bag Dorothy and Lee brought, and Lee thinks it''s time to reveal what''s inside.

Sponsors: J, M, 17', '1991-02-22', NULL, NULL, '2026-04-03T17:36:38Z', '2026-04-03T17:36:38Z');
