INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('43538dda-d242-47d4-82e5-3c3111ca60c4', '01916834-25ec-43d6-9a1b-8ea5d9630adc', 9, 'Whistle-Stop', 'Shaun finds musical whistles that make the flock move involuntarily, creating chaos.', '2025-06-05', 7, '/t4IJzH2hN9dlUSR4qbZ1KiYrRg8.jpg', '2026-04-03T17:39:33Z', '2026-04-03T17:39:33Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('43541cfe-0c99-487a-a72b-6eaf8b971a8b', '5c16db9d-5e71-40eb-b44e-f559b2ddb8f3', 7, 'The Boy Who Left Home to Find Out About the Shivers', 'Overcoming fear is a problem for most people, but there once was a boy whose problem was his complete lack of fear! Peter MacNicol stars as that boy in this amusing production narrated by Vincent Price. The king played by Christopher Lee promises the boy treasure and a beautiful princess if he can defeat an evil sorcerer who has haunted the kings castle. The boy meets an ominous mute hunchback, a headless man and ghosts galore and finally the sorcerer himself (in a duel to the death fight). Yet, he still has no fear, until the surprise conclusion.', '1984-09-17', 51, '/iMiUSLitczrJvWU0TAUZL9xsRmj.jpg', '2026-04-03T17:38:41Z', '2026-04-03T17:38:41Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('435b1666-16a8-45e7-9844-8245097a4a3d', 'f4c40307-9b5e-4263-a4e0-dfa138131e7f', 9, 'Sing, Hoot & Howl', 'Who better than Big Bird to host this "Sesame Street" musical salute to our furred and feathered friends? Join a Muppet menagerie as they sing songs like "Cluck Around the Clock" and others.', '2004-04-06', NULL, NULL, '2026-04-03T17:36:27Z', '2026-04-03T17:36:27Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('435c8d92-0baf-4063-8264-d62e84ee54b4', 'fb4ecc73-cb92-4c5c-821f-92179058b37b', 6, 'Frazzle''s favorite book (3661)', '', '1997-11-24', NULL, NULL, '2026-04-03T17:36:41Z', '2026-04-03T17:36:41Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('4363a69a-62e4-47f6-bbad-1b411b57b6f1', '7eef937c-4483-42bd-bafe-263a7d4e4573', 10, 'Gets Planted', 'Phoebe tries to grow a vine for the school play, Jack and the Beanstalk. But her plant is more like a beansprout than a beanstalk! With the opening curtain only moments away, Ms. Frizzle turns Phoebe into a bean plant so she’ll grow into the star of the show!', '1996-11-16', 25, '/uDQQ3d8jWvcZ7H0K3OBWiQ93AsX.jpg', '2026-04-03T17:37:49Z', '2026-04-03T17:37:49Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('43661631-c73e-4c7f-bb83-c9f74d754b2e', 'b892884d-7b56-4255-a4c6-08f5d0122273', 7, 'Prehistoric Life', '', '1996-10-14', 29, '/xdEm4WU71TS2obVitCLZNMYuZYC.jpg', '2026-04-03T17:39:04Z', '2026-04-03T17:39:04Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('4369745f-9c40-4d96-a264-228111c90c2b', 'f4d370ca-3c39-40a8-911d-e2b5e7c6b0d7', 8, 'The Jolly Dragon', 'Old Bear is reading Little Bear a very exciting book about a dragon. When Old Bear explains that there aren’t any real dragons, Little Bear decides to pretend to be a real dragon living in a cave, just like the one in the book. But it isn’t until the other toys arrive that he discovers how realistic his dragon mask is. It takes Old Bear to sort out the problem of just too many dragons.', '1996-10-23', 10, NULL, '2026-04-03T17:18:56Z', '2026-04-03T17:18:56Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('436f3f95-86d8-4f22-9869-9d9a5d45efa4', '8730c55e-8443-44b0-afef-a369c478b14f', 27, 'Johny Johny Yes Papa (Parents Version)', '', NULL, NULL, NULL, '2026-04-03T15:26:09Z', '2026-04-03T15:26:09Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('43708d07-50de-4f46-9e7c-2f84bce6ce22', '8bae6aa3-4b55-4fa6-bc15-8f4317bd1f13', 60, 'Episode 60', 'Lady Elaine decides to turn the Neighborhood of Make-Believe purple with her Boomerang. It does not sit well with the neighbors.', '1972-05-12', NULL, NULL, '2026-04-03T17:35:40Z', '2026-04-03T17:35:40Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('4371f0ea-1a15-4661-a07d-7d490cbc5271', 'bbfee3b4-9c95-48a6-beaa-791fa08b1f43', 58, 'Episode 58', '', '1984-04-02', NULL, NULL, '2026-04-03T17:21:56Z', '2026-04-03T17:21:56Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('4373bb02-3ef1-47ef-a2e8-30d5ef59ed5a', 'f812042d-eb85-432e-8047-3675886e0b1b', 9, 'Digging Up the Past', 'Wishbone and Joe meet a charming elderly Oakdale resident who has returned after a long absense, and together they search for a ""time capsule"" in Joe''s backyard.  Meanwhile, Wishbone imagines himself as Rip van Winkle, who falls asleep in the forest and wakes up twenty years later to discover that a whole new nation (the USA) has been born.', '1995-04-02', 28, '/tnplStnQDp8il0LFS1a4UM3PM05.jpg', '2026-04-03T17:10:42Z', '2026-04-03T17:10:42Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('43744cfc-644d-449a-b9bf-499a0edbbb15', '208e80de-61e3-4a2f-857f-c667ffc29134', 13, 'Lola Falana', 'After years of failure Gonzo is actually appriciated for the actor he is and decides to quit the Muppet Show and move on to movies. Piggy, more jealous than sad, asks Gonzo to refer her to the director. This is one of the episodes that teeters on the edge of being very sad.', '1980-01-18', 26, '/dKoTYpRzGScOXhffhZt4EnOG6ks.jpg', '2026-04-03T17:35:25Z', '2026-04-03T17:35:25Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('4380af2c-f966-4d4d-8bfc-8b47c54fc379', '5d97d70c-fcec-41ce-8e0d-78ab624fe334', 4, 'Grover''s Super Suitycase', 'Elmo''s sad his daddy has to go on a work trip, and Grover''s on a mission to cheer him up — but it isn''t working. Sounds like a job for the Help Fairies!', '2025-11-10', 30, '/tLe01PNJkRi8joi2U31G3g17AKL.jpg', '2026-04-03T17:36:52Z', '2026-04-03T17:36:52Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('4381367a-5d50-4f4f-b6c1-f904cdc7ea7c', '05c0e384-194c-4417-9f62-803eb615e409', 29, 'Weaving', 'Title number 0029. Opens with Mister Rogers arriving with a small loom. Mister Rogers demonstrates the use of a small loom and takes a trip to see the large ones being operated by Nantucket Weavers. In Make-Believe, a four string quartet plays for King Friday. In closing, Mr Rogers sings and plays "Good Night, God" on his piano.', '1968-03-28', 29, NULL, '2026-04-03T17:35:38Z', '2026-04-03T17:35:38Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('4389504d-cc25-46d3-a34b-ec967a5c0813', '54900370-8988-46b8-b7aa-61d2b88d7056', 8, 'Loose Lips Sink Friend Ships', 'Heather''s yacht trip takes a stormy turn when Bronwyn learns Lisa has been spreading rumors. Meredith grows increasingly uneasy with Britani''s behavior. Lisa vents to Mary about Meredith, sparking a fiery confrontation.', '2025-11-04', 42, '/8UYWeMkEMbCPktOE1j9STchmdsW.jpg', '2026-04-03T16:35:46Z', '2026-04-03T16:35:46Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('438e32d4-6d58-42e8-95ee-dee2b8516861', 'a6ed03e0-c05f-48f8-9f56-3f1da50e1792', 100, 'Episode 1415', '', '1980-04-11', NULL, NULL, '2026-04-03T17:36:33Z', '2026-04-03T17:36:33Z');
