INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('439d1132-513b-4c9e-9d77-44ec82885ac5', '1996ddd8-20c9-4a30-96be-2b87fab8d17c', 6, 'Who Burned Mr. Brinker''s Store? (1)', 'A mysterious man delivers a letter to Brinker. Whatever it says makes Brinker so mad he takes his anger out on Jamal and his friends. Jamal writes a letter to calm Brinker down and delivers it to him on the same night a fire is set.', '1992-11-01', NULL, '/zGVcnnvilOknAgMvHD9I6Inhdrv.jpg', '2026-04-03T17:40:28Z', '2026-04-03T17:40:28Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('43a27390-6297-4119-b2e2-c8bca7d01485', 'fed71eea-5d41-479c-b12a-beb733409c5c', 7, 'A Bicycle Built by Two', 'Luis and Telly follow a diagram of a bicycle and build the perfect sized bicycle for Little Chicken.', '2014-10-08', NULL, '/xHgKyLiw8XLmkGCuDzhu1u6Dcj9.jpg', '2026-04-03T17:36:48Z', '2026-04-03T17:36:48Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('43a2befb-8e82-4478-a712-871d0f648a04', '9193e795-da7c-40ec-b68f-f63aa7d5174f', 147, 'Histories & Lore: The Kingsmoot', 'Euron Greyjoy discusses the origins of the tradition of the Kingsmoot, and he names the most famous and bloodthirsty kings named under this tradition.', '2016-11-15', 4, '/7fC8k9xfoo6MAffxjay7ilThkt2.jpg', '2026-04-03T15:40:35Z', '2026-04-03T15:40:35Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('43a51a57-96ff-45ad-82bb-15f1d918bffa', '671bd4da-3470-40f9-9a03-40fba34d2b8e', 9, 'The 200th', 'Frankie remembers she has to come up with something to place in the time capsule; Bill Norwood informs Mike that he and Paula are separating; Brick tries to win Cindy back; Axl volunteers Sue to be his personal assistant.', '2017-12-05', 22, '/gfj5Em3zdS3gyiFFAbGR2Wo7WoP.jpg', '2026-04-03T15:40:31Z', '2026-04-03T15:40:31Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('43b6fad8-a7cf-444f-8e68-1bd4b0f3db59', 'bf874be3-7e2f-4a0e-b205-c76ac1ad69fc', 161, 'The Roundtable: The Cast of Seinfeld and Larry David (2)', 'Part two of an hour-long featurette wherein the cast got together to discuss the show in all its splendor on the ninth anniversary of the series finale and is also considered the official Seinfeld Reunion.', NULL, 28, NULL, '2026-04-03T16:34:09Z', '2026-04-03T16:34:09Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('43b80242-9e94-483b-b63a-4f94fc6d6d5c', '0bbd380c-5cb8-46a6-8838-b5d60223c073', 11, 'Candice Bergen', 'Fozzie brings a series of deliveries to Kermit, pestering the frog with lousy gags.', '1976-11-14', 26, '/tL6OJh8L4iFRNqsBEiwCRXiPGAK.jpg', '2026-04-03T17:35:24Z', '2026-04-03T17:35:24Z');
