INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('43c340ed-fe54-45f5-9524-323bd594ef01', '0fa92002-82ae-4609-85e3-3982baa99ae1', 4, 'Postman Pat and the Spring Dance', 'Everyone is practicing different dances for Greendale''s spring dance, but Pat is not very good at dancing. Ted helps Pat out by teaching him how to dance. Later, Pat is able to surprise Sara by whisking her onto the dance floor.', '2005-03-02', 15, '/l6omXmqL4xeknAXVbTxqzx6aIL8.jpg', '2026-04-03T17:14:30Z', '2026-04-03T17:14:30Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('43c63052-687c-4631-acd7-248eb0b0aebb', '0f64bf9f-8d05-4f5b-9a57-5d0c44ac3f40', 1, 'A Secret Marriage', 'In the season premiere, Kody and Meri''s divorce takes the family into uncharted territory. Also: Kody, his wives and their kids answer viewer questions.', '2015-09-13', NULL, NULL, '2026-04-03T16:34:29Z', '2026-04-03T16:34:29Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('43c726b8-7585-47f2-8380-424e48c4456c', 'bf3ffafd-7d45-4f2c-9f1b-28001bd082db', 1, 'Episode 1', 'Expedition - Thailand  John, Peter and Lesley discover Bangkok’s Giant Swing, ride the klongs in a long-tailed boat and meet Mr Larry, the lightning tailor.', '1974-09-09', NULL, NULL, '2026-04-03T17:21:52Z', '2026-04-03T17:21:52Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('43c7622f-2516-4b52-936f-eff985a578bb', '9c5608b2-5111-48bc-a907-7f93472c1e03', 20, 'Fairy Tale Science Fair (repeat)', 'Baby Bear and Telly report from the Sesame Street Fairy Tale Science Fair, which features fairy tale characters solving problems with science. Little Red Riding Hood, for instance, observes and compares her grandmother and the Big Bad Wolf, who''s dressed like her grandma, in order to tell one from the other; and Cinderella, with help from Baby Bear and Telly, conducts an experiment to see if pumpkins can float.', '2013-02-28', 58, '/mM76we9crb3t8x5ipI9CxNihQM5.jpg', '2026-04-03T17:36:47Z', '2026-04-03T17:36:47Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('43d25502-ece0-4681-bdfb-b38b6a71170f', 'f5266c49-eb29-4594-b5d9-f927edfee336', 4, 'The Genie', 'Shaun dreams of a life in the fast-lane.', '2014-02-06', NULL, '/ydhWH2g5ja1rRt6XNnAfrrWgRq4.jpg', '2026-04-03T17:39:32Z', '2026-04-03T17:39:32Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('43db9e2b-72e7-4033-b4d1-2d85f7ffafbd', '3b154d00-cb7b-49c4-a053-6ebbbe906eba', 13, 'Elmo and Zoe Search for Rocco (4043)', '', '2003-04-23', NULL, NULL, '2026-04-03T17:36:43Z', '2026-04-03T17:36:43Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('43deaff0-bfe0-4219-93b1-a515a4e55187', '050d8ae1-6cc1-4018-933d-b3c3d13de856', 34, 'Episode 34', 'Rising Star!

At 15 America''s Kathy Healy is already a star of stage, screen and the ice-rink! After figure-skating in John Curry ''s famous Superskate Show, aged 6, Kathy acted with Dudley Moore and Mary Tyler Moore and danced in Germany, Italy, Paris, and New York. Today she makes a whirlwind visit to the Blue Peter studio between performances as Clara in the London Festival Ballet''s Nutcracker.', '1985-01-07', NULL, NULL, '2026-04-03T17:21:57Z', '2026-04-03T17:21:57Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('43e1e9b5-9eb3-4b68-b771-ec0c131c95c4', '80775c3d-fa41-46f6-96ec-efc2e14efdcf', 20, 'Reunion (1)', 'The women provide conflicting accounts of how they reacted to the return of Bethenny; tensions resurface as the women remember their trip to Atlantic City, N.J.; from boyfriends to "girl codes," Luann and Carole continue to bicker.', '2015-08-18', 44, NULL, '2026-04-03T16:35:24Z', '2026-04-03T16:35:24Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('43e402eb-354e-4715-bc27-482bd0a42f50', '20d7138e-eea8-46a8-8ada-2b0f0ee1f674', 4, 'Episode 4', '', '1982-09-23', NULL, NULL, '2026-04-03T17:21:56Z', '2026-04-03T17:21:56Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('43eabdde-d80d-4663-ae24-f2b0a8d758b6', 'ad4e4348-3334-4a08-8928-455d9ba524c1', 17, 'Debbie Harry', 'Robin''s Frog Scout troop visits the show, getting in everyone''s way backstage. They ask Debbie for help earning their punk merit badges, and she teaches them how to do the pogo. When Gonzo cancels his act, the Frog Scouts get their chance to do a performance of close-order drills.', '1981-01-25', 26, '/kcRR8yJW1Nh4Yz3IueeuH5AMzRq.jpg', '2026-04-03T17:35:25Z', '2026-04-03T17:35:25Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('43f86221-f9f1-49b9-9653-1a5c28f9ce97', '319bd5d6-ff58-426f-b9da-a0bb2cb87b02', 1, 'Forensics', 'Forensic scientists try to find out the who, what, when, where, and why of events in the past – crimes. Most forensic scientists work in police labs. They collect evidence from the scene of a crime and analyze the evidence in a lab. Forensic scientists look for clues that will help them solve a crime. Fingerprints, footprints, hair, blood, and traces of gunpowder can be helpful evidence. Forensic scientists use all sorts of scientific instruments to analyze even the smallest bit of hair or the tiniest chip of paint. By scientifically testing evidence from the crime scene, and by knowing about evidence from past cases, forensic scientists can piece together what happened, to figure out who did what, and to help police catch a criminal.', '1997-09-19', 26, '/yjVkHw6JReCit9oIdcVd7IZb0hZ.jpg', '2026-04-03T17:37:22Z', '2026-04-03T17:37:22Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('43f9092d-b431-440b-b632-9106a0339698', 'a8facd21-e786-4fff-b89f-7eb83eba2231', 44, '2399 - Ronald Grump builds the Grump Tower', 'Ronald Grump, the Grouch building tycoon, approaches Oscar with a new idea - a two-story can-dominium called "Grump Tower." In exchange for Oscar giving up his property to build the tower, Grump gives him a spot in the tower, as well as three bags of trash. Maria thinks it''s a rotten deal, which only encourages Oscar further.', '1988-01-14', 58, NULL, '2026-04-03T17:36:37Z', '2026-04-03T17:36:37Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('43fb136e-5cca-4945-b2fc-0f98ca87d1f9', '45e01c04-6ac6-41e1-87d8-f749ee230385', 38, 'Episode 38', '', NULL, NULL, NULL, '2026-04-03T17:14:38Z', '2026-04-03T17:14:38Z');
