INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('44637756-ddc6-494a-b0a2-33761c2a53ac', '54900370-8988-46b8-b7aa-61d2b88d7056', 7, 'Above Neck and Below the Belt', 'In a can''t-miss crossover event with "Below Deck Down Under," the women take off for Heather''s Caribbean adventure, but one housewife is noticeably missing. Once on deck, Britani flirts with Capt. Jason and the deck crew. Angie tries to find her sea legs. Bronwyn and Whitney question whether one of the women has been leaking stories to the press.', '2025-10-28', 54, '/f2mIUK6ar7kOmX8tdrL4zFa0cGJ.jpg', '2026-04-03T16:35:46Z', '2026-04-03T16:35:46Z');
