INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('4466ef96-923a-444c-b6bb-5e1261d9c85d', '36ea3814-66b4-4986-b6ee-44559d3562c1', 5, 'Save the Drama for Mama', 'In order to prepare for her mortuary exam, Phaedra flies to Alabama to practice what she''s learned. Apollo receives advice from Peter on how to handle his marital issues. Noelle has started to date, and Cynthia is forced to face the reality of her daughter growing up.', '2013-12-01', 43, NULL, '2026-04-03T16:34:46Z', '2026-04-03T16:34:46Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('446e0fbd-810a-48af-8f8d-c5453d515f75', '2f5a4ffe-2548-4181-85ac-6145cb3e3bf7', 4, 'Kody''s Shocking Move', 'Aspyn goes wedding dress shopping, but after the fun, Kody drops a huge bombshell; with a weird whiteboard presentation, he tells his wives they need to sell their houses and move; Janelle digs in her heels and refuses to do this to her kids.', '2019-02-17', NULL, NULL, '2026-04-03T16:34:31Z', '2026-04-03T16:34:31Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('446ef0ad-6312-4bc4-a648-721f49aac8eb', 'ca09391a-de6a-4b2b-aefc-c2efbc80a106', 1, 'Alistair''s Time Machine', 'LeVar goes to a totally-fictitious spot to find inventors from all eras. True to form, these inventors come from the distant past, Reading Rainbow''s near-present, and the future. Arnold Stang narrates Alistair''s Time Machine, the story of a boy who invents a machine that takes him centuries back in time.', '1991-09-16', 30, NULL, '2026-04-03T17:36:17Z', '2026-04-03T17:36:17Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('44703523-28a0-46c2-9325-6988de999005', 'ed2cc20d-0c20-4001-b59c-457b515c462d', 6, 'Episode 6', '', '1996-02-08', 25, NULL, '2026-04-03T17:21:17Z', '2026-04-03T17:21:17Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('44715ed5-b802-4964-8ab8-8707ed79da96', '7b8e3988-fbf3-4cfc-aeb2-782ae5a64e2d', 10, 'Up In The Air', 'Big Bird and Snuffy are having a playdate and jumping in the arbor to see who can stay in the air the longest. They quickly realize that they come right back down after jumping in the air. Gordon comes by and explains that they can’t stay up in the air because of gravity. They might not be able to see it, but gravity pulls everything, big and small, down to the ground. Big Bird and Snuffy watch as Gordon shows them examples of gravity by experimenting with different items such as a book, a writing pad, a ruler, and a pencil. Shortly after Gordon leaves, Big Bird and Snuffy see Abby and tell her what they have just learned. They can’t help but think how fun it would be if there wasn’t any gravity and they could float in the air. With some help from Abby’s magic, they do just that! Floating is so much fun until they try to play catch, and the ball doesn’t come down. Then, they try to play with their race car, but it floats away too. Even their sandwich floats away! Suddenly, Gordon floats toward them and calls Abby to bring back gravity so things can return to normal. With a spell and the wave of her wand, gravity returns. Big Bird and Snuffy happily return to the ground and continue their playdate!', '2010-10-14', NULL, '/leQI2fqyvcD0rjPsNchtteDByCP.jpg', '2026-04-03T17:36:46Z', '2026-04-03T17:36:46Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('4475ac52-bce0-4178-8c2f-4a3d9f08a4bb', '4a8e3db0-8068-4ff3-942f-91f45f665f20', 27, 'Piggyback, Piggyback', 'After reading a book about a king who rode on his friend''s back (because he didn''t want to get his feet dirty), Leona wants to do the same. So she hops on her dad''s back, and doesn''t want to let go!', '2000-05-09', 30, NULL, '2026-04-03T17:12:27Z', '2026-04-03T17:12:27Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('447613f0-abba-467b-883c-b26fdaa1ba24', 'a8c6182e-05e1-4b68-91a5-5126cf6c94f0', 33, 'Conflict in the South', 'James and Henri follow General Nathanael Green; Sarah is upset to discover Thomas Jefferson has slaves.', '2003-01-21', 30, '/4bpmZz6Ih62OhcKm1S01piauggL.jpg', '2026-04-03T17:38:28Z', '2026-04-03T17:38:28Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('4476a7b5-c2e7-4fff-80db-6e0caa0625f5', '871570b4-bf2f-4ba1-9940-65fb932cb009', 1, 'The Shades of It All', 'Kandi and Todd receive exciting news in the Season 8 premiere. Also: A viral video causes drama for Cynthia; Porsha''s boyfriend visits; Phaedra adjusts to life as a single mother; and Cynthia throws an event to celebrate her eyewear line.', '2015-11-08', 43, NULL, '2026-04-03T16:34:47Z', '2026-04-03T16:34:47Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('4476d848-ade0-4ece-8810-bf450a3f003e', 'e48599f8-66ff-4c0f-9274-65b9ae1cda9e', 47, 'Episode 47', 'Olympic gold medallist Jim Fox and news of the latest scheme to win more British Olympic medals.', '1977-02-24', NULL, NULL, '2026-04-03T17:21:53Z', '2026-04-03T17:21:53Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('447dedcf-2247-4cd5-ab4f-c2808d42d818', '1f34e241-4c1d-4586-921a-1c5aeb1fbbaa', 55, 'Big Bird and Snuffy pretend to explore Sesame Street', 'Big Bird and Snuffy pretend to explore Sesame Street, imagining it''s their first time seeing it. They observe an "umpadumpus tree," meet some friendly native "Sesame Streetians" speaking "Sesamese" and attempt to communicate with them and learn their customs, and encounter a wild animal (Barkley). Oscar kicks off the annual Grouchketeer Dirty Face Contest.

Sponsors: E, X, 9', '1986-01-31', NULL, NULL, '2026-04-03T17:36:36Z', '2026-04-03T17:36:36Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('447ee62b-dc88-4382-974d-e0b5b0d6e943', '40700e8a-1dce-4895-bede-522a13a8bcad', 2, 'Brain Power', 'The Kratt Brothers and Zoboo put their heads together with Braniac the really intelligent chimpanzee and build an ""Invisibility Machine."" They meet some other animals with great brains including elephants and crows and discover that all creatures are smart in their own ways.', '2000-10-09', 27, NULL, '2026-04-03T17:10:55Z', '2026-04-03T17:10:55Z');
