INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('45a701ec-05da-4517-9926-3da62ccad7fc', 'db555b98-87d6-4cd2-b7b4-973f9206cb1e', 21, 'Reunion (1)', 'Part one kicks off by discussing the return of “Fun Shannon” and Shannon gives an update on her love life. Emily and Gina’s complicated friendship is dissected as they discuss their roller coaster season including Gina’s DUI, Emily’s marital struggles and Gina’s relationships in the wake of her separation. Meanwhile, Vicki grows agitated backstage waiting to join the ladies onstage. Once reunited, the ladies hear about Vicki’s love tank, and hash it out over the unforgettable trip to Miraval including the gong heard around the world.', '2019-12-18', 44, '/dXnTlmzHHtcf9WGK59OTet2sI1g.jpg', '2026-04-03T16:35:34Z', '2026-04-03T16:35:34Z');
