INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('45bf6b58-b86d-49eb-a4ac-205f79047739', '262e8e7c-fa78-4578-a216-add6f184c4d2', 8, 'Sister Wives in Holiday Crisis', 'The Sister Wives struggle to accept that this will be their last Christmas in Utah; a massive change to the family dynamic.', '2011-05-08', NULL, NULL, '2026-04-03T16:34:27Z', '2026-04-03T16:34:27Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('45c0837e-f135-4026-85fd-6b37a8f90dce', '5a771f52-fe96-4ea2-b567-a8dde899059e', 19, 'President''s Day Sale', 'Rick tries to snap up an autographed card of President Abraham Lincoln that he can''t picture himself without. Corey and Chum think about offering big bills for a golf driver shaft designed for President Bill Clinton, until they''re fore-warned he may not have used it. Rick checks out a personal check signed by President James Madison that bounces into the shop, but will it clear his reservations? Later, a patent model for an American flag press has Rick seeing stars and stripes, but will he pledge to buy it?', '2018-02-19', 21, '/er6wLp5EiqEuUf83n1mP6qeov0a.jpg', '2026-04-03T16:34:21Z', '2026-04-03T16:34:21Z');
