INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('460ac106-45c3-4ab1-ad45-3a0d76fc3d7a', '21745b85-d269-42fa-b4dd-701b2da5c085', 19, 'Episode 19', 'Today Valerie and John go behind-the-scenes at Westminster Abbey to see the preparations being made for this week’s Royal Wedding. More than 500-million people in five continents are expected to be viewing on Wednesday, and the Wedding will be televised '' live '' to 16 different countries. The BBC will be using 50 cameras and 14 mobile control rooms to cover the event, and in today’s Blue Peter you can see where the cameras are hidden in the Abbey.', '1973-11-12', NULL, NULL, '2026-04-03T17:21:51Z', '2026-04-03T17:21:51Z');
