INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('4626d994-048a-4d57-99f3-4b4c5bbbb47f', '852a07b0-f228-4197-9147-7aeed79390bf', 2, 'Burning Up', 'To celebrate being reunited after a long quarantine, Ramona invites the ladies to the Hamptons; Luann overshares details about her new man with Sonja; Leah hosts a Burning Man party, where the group learns devastating news during a healing session.', '2021-05-11', 60, '/fRoNxObyhz7t2VdM3KClCiCy9bW.jpg', '2026-04-03T16:35:26Z', '2026-04-03T16:35:26Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('4628b2bd-8dfd-438a-847b-a0515440d107', 'ad4e4348-3334-4a08-8928-455d9ba524c1', 15, 'Hal Linden', 'Statler and Waldorf get their chance to do a better show than Kermit--they play host, while Kermit and Fozzie heckle from the balcony. Unfortunately, Statler and Waldorf''s acts don''t turn out exactly as they plan.

The Berlin National Opera Company cancels and are replaced by the Salzburg Sauerkraut Singers. Hal''s Fourth of July number is invaded by Gonzo on a sleigh singing Christmas songs. Finally, Statler and Waldorf admit that the show is harder to put together than it looks and happily go back to complaining from the balcony.', '1981-01-11', 26, '/80ropCu4QgUA2ECX4aOh2Vx2dri.jpg', '2026-04-03T17:35:25Z', '2026-04-03T17:35:25Z');
