INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('46322a25-6921-494b-afa1-53eb08c33ba6', '95ca8b6f-ccbc-431a-9d95-9b23367bbfed', 6, 'The Liberation of Erika Jayne', 'Erika reunites with the ladies for the first time since filing for divorce and explains how she came to such a tough decision. Crystal invites everyone over to make Chinese dumplings, but she and Sutton must first confront their lingering issues from Lake Tahoe. Kyle and Dorit reach a truce, while Garcelle meets with a dating coach to dream up Mr. Right.', '2021-06-23', 43, '/qKVox6PhF9ZdP7mYQW52zCXAGtZ.jpg', '2026-04-03T16:34:58Z', '2026-04-03T16:34:58Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('4633c87c-7489-4a7a-8ddb-63e8d9744ef0', 'd3e13496-e3c8-4903-83b4-5a31fedee232', 20, 'The Siege of the North (2)', 'Aang returns from the spirit world to a big surprise. Meanwhile, Zhao and his forces continue to press deeper into the Northern Water Tribe. Iroh makes a powerful stand and Zuko struggles to keep his plan intact.', '2005-12-02', 26, '/5Y074fdoE8Xc1HhjyACMszucOPO.jpg', '2026-04-03T17:40:47Z', '2026-04-03T17:40:47Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('46366d09-641d-4894-9e89-ca69a0211cfc', '5c1b881f-ac58-4d72-b63f-209952d4f902', 23, 'Episode 23', 'Flying Cats Jack and Jill take to the skies and jet their way to Dunfermline for a guest appearance at the Edinburgh and East Scotland Cat Show. Blue Peter cameras follow their flight from Gatwick to Edinburgh.', '1979-11-26', NULL, NULL, '2026-04-03T17:21:54Z', '2026-04-03T17:21:54Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('46388464-77ef-4f34-883d-a640a3545f56', '40700e8a-1dce-4895-bede-522a13a8bcad', 6, 'Zoboo the Super Lemur', 'Inspired by a comic book hero, Zoboo becomes a Super Lemur with a little assistance from Muscles and Muscley, two black bear cubs. After Zoboo rescues some kittens, the Kratt Brothers travel to India to find other heroes in the creature world.', '2000-11-06', 27, NULL, '2026-04-03T17:10:55Z', '2026-04-03T17:10:55Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('4639fbb2-5e47-4e59-92f0-41887ba80271', 'f13cb622-84e3-4654-a8f1-0ceab09a9ca6', 17, 'Gee Whiz Franklin', 'When Rabbit tells Franklin and his friends about the "Gee Whiz Challenge," a contest to do something fun for 24 hours and get in a magazine, everyone jumps at the chance to become famous. They soon find that not only is it harder than they think, but there are other things that are more important.', '2002-06-24', 12, NULL, '2026-04-03T17:40:16Z', '2026-04-03T17:40:16Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('463fc985-5a93-4b13-8a38-d0c04f3cea26', 'bb919aec-0d5c-4c58-9a5a-fa2a0a5de2b6', 29, 'Episode 434', '', NULL, NULL, NULL, '2026-04-03T17:36:29Z', '2026-04-03T17:36:29Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('46406e94-bd7b-4362-97a6-0ac30fe551b1', '04572e48-bbfd-476b-aebe-b6dc424f742d', 2, 'Kaer Morhen', 'Seeking a safe place for Ciri, Geralt heads for home, but danger lurks everywhere — even Kaer Morhen. Yennefer''s dreams could be the key to her freedom.', '2021-12-17', 59, '/bD0fkV9hxxxjmQXWfjB1LZQ154s.jpg', '2026-04-03T15:40:45Z', '2026-04-03T15:40:45Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('4642ca33-856f-4bd1-9ddd-b6d9eafb0f8d', '99b71026-3919-4813-a330-eb09e0e43d74', 4, 'Game Day', 'James Avery reads a story written by identical twin brothers Tiki and Ronde Barber, who became professional football players, and how they learned the importance of teamwork when they played together in junior high.', '2006-11-09', 30, NULL, '2026-04-03T17:36:22Z', '2026-04-03T17:36:22Z');
