INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('4647b16d-98a0-422d-a224-8cb7eb03409c', 'f6015d9a-ece4-414a-a00b-06cf689fe40b', 13, 'Sport Relief Spectacular!', 'Find out how Lindsey and Radzi got on with their Sport Relief Challenge. How many steps will they be able to add to the Mega Mileathon Totaliser? There''s a sneak peek behind the scenes of Sport Relief. Plus Dako Flying Angels showcase their fantastic gymnastic display skills!', '2018-03-22', NULL, NULL, '2026-04-03T17:22:10Z', '2026-04-03T17:22:10Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('464ddfd8-e923-4b73-870a-88660bfd59ac', '73ae1459-ba91-4185-a9da-bf6f2844af49', 21, 'Viva la Dysfunction', 'In the season finale, the women look to the future but can''t escape the past. Luann records a new song that she hopes to feature in her upcoming cabaret. Leah continues to rebuild her relationship with her mother. Sonja clashes with Ramona on how to prepare the townhouse for sale. An invasive surgery has Dorinda looking back at her tumultuous year. And when the ladies come together for Sonja’s Drag Queen Bingo party, the evening goes from fabulous to ferocious when an old wound is ripped back open.', '2020-09-03', 60, '/evRUmxvSgYpT6Ii5KRa7oqb1vmF.jpg', '2026-04-03T16:35:25Z', '2026-04-03T16:35:25Z');
