INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('465c3732-9c1c-460f-b426-da3eddda1b62', 'bc1b58b0-f2d6-4214-914b-231f27fb4d61', 5, 'Stick It', 'Teresa encounters her brother for the first time since the tumultuous christening. Elsewhere, Melissa tries to fulfill her dream of being a pop star; Caroline plans to offer matronly advice on the radio; and Jacqueline''s daughter plots to get a car.', '2011-06-12', 43, '/MT02I2gAmBy9B9I1nAU8uo76vO.jpg', '2026-04-03T16:35:15Z', '2026-04-03T16:35:15Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('4661e2a6-f710-41dd-a68f-ecf0017a2331', '4a8e3db0-8068-4ff3-942f-91f45f665f20', 25, 'A King and His Hawk', 'Lionel and Leona read a very sad story about a King and his friend, the Hawk. After, Leona wants to take and hide the book where no will be able to find it, so they can''t read it and be sad like she was. Also, Theo sings about the greatness of reading sad, sad books.', '2000-05-05', 30, NULL, '2026-04-03T17:12:27Z', '2026-04-03T17:12:27Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('4664ea6c-dfd4-4b70-a015-370a3b5a71db', 'f4c40307-9b5e-4263-a4e0-dfa138131e7f', 100, 'When Families Grieve', 'This bilingual multimedia outreach program is designed to give families tools to support children coping with the death of a parent, while also providing reassurance that together with their families they can learn ways of being there for each other and move forward.

In a "street story," Elmo and his family cope with the death of his Uncle Jack. In wraparound segments, host Katie Couric talks about coping with Elmo and his cousin Jesse, and the monsters interact with real kids and families. Appearing in the "story" segments only are Jack''s wife Jill and Elmo''s parents Louie and Mae.', '2010-04-14', NULL, NULL, '2026-04-03T17:36:27Z', '2026-04-03T17:36:27Z');
