INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('4672b98b-e7cf-4297-b27e-10ae7bd495e7', '432a6abd-dcca-44cc-82ce-fb39e33b8949', 58, 'Babies Pt 2', 'Mr. McFeely delivers the book "Fur, Feathers, and Hair" to Rogers. Later McFeely brings in an English sheepdog. In between, King Friday is upset that baby Prince Tuesday will not smile at him.', '1971-05-05', NULL, NULL, '2026-04-03T17:35:39Z', '2026-04-03T17:35:39Z');
