INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('4680083a-4b51-4df3-b5cf-175510c1e1b9', '5c1b881f-ac58-4d72-b63f-209952d4f902', 62, 'Episode 62', 'Chris goes behind-the-scenes with the Mines Rescue Service - the emergency teams on 24-hour call to cope with pit disasters.', '1980-04-17', NULL, NULL, '2026-04-03T17:21:54Z', '2026-04-03T17:21:54Z');
