INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('469f0bf1-ba93-42a6-bf19-bc19b5a9efcc', '4d2cac0f-38fd-438b-8afa-acf43952e535', 36, 'Episode 36', 'A weekly programme for younger viewers.  Introduced by Christopher Trace and Leila Williams.  Working with Wood shown by Owen Williams.  The Tale of Jemima Puddle-Duck: Part 2, a story by Beatrix Potter with the original pictures.  What the Brownies Do: 1 - Jean Francis introduces the first of a new series.', '1959-06-25', NULL, NULL, '2026-04-03T17:21:47Z', '2026-04-03T17:21:47Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('46a4f695-74f3-465b-9e3d-d9650859e3a8', '6c1ec19f-74df-4f35-9a61-17b98175d826', 9, 'Until We Leave Again', 'Denise and Aaron’s hasty departure from Kyle''s barbecue leaves the other ladies confused and unsettled. Kyle helps Kim through a delicate medical procedure, while Lisa and Erika have a distinctively Beverly Hills “procedure” of their own. Garcelle moves into her new house. Aaron awkwardly comes face to face with Erika and Teddi at Sutton''s trunk show.', '2020-07-08', 43, '/mKnuUEcHjITTfAc1vNsQM6pcKbm.jpg', '2026-04-03T16:34:58Z', '2026-04-03T16:34:58Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('46b33887-af24-4531-97f3-4db39b928c1f', 'b5ab3a72-bc79-4e9b-a531-96739afd7aea', 12, 'Flying', 'Yaffle comes down from his bookend to find a basket, containing items.  The mice search it and find a twig broom, which leads Madeleine and Gabriel to sing a song about a woman who brushes the cobwebs out of the sky.', '1974-04-30', 15, NULL, '2026-04-03T17:23:58Z', '2026-04-03T17:23:58Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('46bd490c-7d0d-497b-a4cc-987be90ec9c4', 'b86d15ea-4253-41a5-9f14-4a254ec601e0', 20, 'Reunion (part 2)', 'Teresa and Joe speak about the charges they''re faced with; Rosie shares her experience; the ladies discuss the season.', '2013-10-13', 43, '/57nTlQu8BOsWwmzqe8LSJwCz27k.jpg', '2026-04-03T16:35:16Z', '2026-04-03T16:35:16Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('46c1c0dd-87e1-4308-822d-37325404230c', '1f34e241-4c1d-4586-921a-1c5aeb1fbbaa', 47, 'Jiffy the turtle / Barkley the cow', 'At Hooper''s Store David greets Jiffy the turtle, who comes in for breakfast. Jiffy speaks very slowly, so David makes sure Gordon and Linda have everything they need - this could take a long time. Jiffy doesn''t know whether he wants eggs or pancakes, and eventually decides to have corn flakes with f It''s lunch time, but Jiffy is still eating his breakfast.

Sponsors: I, K, 11', '1986-01-21', NULL, NULL, '2026-04-03T17:36:36Z', '2026-04-03T17:36:36Z');
