INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('47730d85-7268-4039-94c8-b243a1095e8b', '40700e8a-1dce-4895-bede-522a13a8bcad', 9, 'Talk to Me', 'With the help of the Kratt Brothers and Toothbrush the elephant, Zoboo learns how animals communicate with each other. While Zoboo does his best to answer all of the letters sent in by kids, Martin and Chris go to India to find out how animals talk to each other in the wild.', '2001-01-22', 27, NULL, '2026-04-03T17:10:55Z', '2026-04-03T17:10:55Z');
