INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('482b4f95-efd7-40b3-b8d3-286a87d2bec3', '70c8cb46-2494-4dd4-98f6-6bfb9b3faf73', 28, 'Chumlee''s Dummies', 'The sky is the limit for the Pawn Stars as they consider buying a 1939 Allied Forces World War II plane. Will the gang soar to new heights and make the deal or will it stall out and take a nose dive? Then the Old Man has a chance to buy a munitions receipt from the War of 1812, signed by future President Andrew Jackson. Will this correspondence from the Commander in Chief be reimbursed for cold hard cash or is this historic invoice a cheap imitation? And later, a man saunters in with a pair of life-size western cowboy mannequins. Will Chumlee boss around a couple of new companions or will these hombres pack up and hit the trail?', '2010-06-28', 21, '/uXfJWzDEdKuENUejJvo6sOmOx00.jpg', '2026-04-03T16:34:16Z', '2026-04-03T16:34:16Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('482dacb9-3b91-48e3-9d52-6418523277c5', '487fdbcd-ec5a-454e-8268-b50566eb8546', 14, 'Reunion Part 1', 'Ayan and Caroline Stanbury are still celebrating; Taleen and Caroline Brooks confront each other; Caroline Stanbury clears the air about her "sugar daddy;" Taleen makes a revelation about Caroline Brooks'' ex.', '2024-09-10', NULL, '/7qZV6BYUUEsx03aXgO96OEzTUNS.jpg', '2026-04-03T16:35:07Z', '2026-04-03T16:35:07Z');
