INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('484984d8-4676-4b3c-9379-4b40a83b38b8', '51f03551-ba41-409d-85f4-e51bddfdf82e', 8, 'Game, Set, Feud', 'Jill gets set to play her doubles tennis match against Ramona and Mario, but it could be a histrionic racket when her pro tennis partner opts out and Jill invites Simon to play with her. It''s game, set, drama when the other wives attend the match. Meanwhile, Jill shows her home redesign to Bethenny; and Bethenny seeks help with her product-logo design.', '2009-04-07', 60, '/6jTJekac98AWhPPf9K7oNpGxkFj.jpg', '2026-04-03T16:35:22Z', '2026-04-03T16:35:22Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('484b75eb-532b-4488-a90b-34a476bf646e', '58adb9ab-3f1b-4a11-87b6-9b0b2dbb6aaf', 8, 'Gilded Pawn Age', 'All aboard with the Pawn Stars when Rick checks out a Gilded Age train. Will he be able to hook up a buyer for this thing, or is Rick holding a one-way ticket to No Sale? Then, a classic Nintendo race car game from the 1960s rolls its way into the shop. Will Corey and Chum hit the brakes on a sale or will they cross the finish line? Also, Is it a bird? Is it a plane? No, it''s an amazing Superman and Batman print. Will it save the day and become a sale or will the heroes be defeated?', '2017-05-08', 21, '/7uyl7t7WN8W7qebOhkBmYnn4Erx.jpg', '2026-04-03T16:34:21Z', '2026-04-03T16:34:21Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('484dbf8d-99c6-4649-ac36-b7a53299d143', 'e1063f87-66c2-4e2d-a913-53362941aa19', 29, 'Episode 304', '', NULL, NULL, NULL, '2026-04-03T17:36:29Z', '2026-04-03T17:36:29Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('484f17a4-8f93-4cb2-8fa5-80e0c6f9e288', '42e591e2-2a88-4434-ae9f-3d4b1d685613', 28, 'The Enigma', 'It''s a first for the Pawn Stars when a WWII Enigma machine comes in the shop. Used by the Germans to send top-secret messages, can they crack the code to owning this incredibly rare artifact? Then, Corey and the Old Man check out a photo of Old West gunfighter Doc Holiday. The only known photograph showing Holiday as a dentist, will this negotiation be like pulling teeth? And later, Corey''s big-spending ways have him strapped for cash. Can a financial adviser set him straight?', '2013-10-17', 21, NULL, '2026-04-03T16:34:18Z', '2026-04-03T16:34:18Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('4858a8c4-a442-418b-aeea-7726ad27cbf6', 'a6ed03e0-c05f-48f8-9f56-3f1da50e1792', 79, 'Episode 1394', '', '1980-03-13', NULL, NULL, '2026-04-03T17:36:33Z', '2026-04-03T17:36:33Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('485d0ade-798b-4ead-bcaa-a3a7f54c5e13', '42e591e2-2a88-4434-ae9f-3d4b1d685613', 34, 'The Merchant of Vegas', 'Drop in on the Pawn Stars when the guys check out a Cushman scooter allegedly used by paratroopers during WWII. Will this negotiation have a soft landing, or spin out of control? Then, Rick and Corey look at a rubber bullet and shell casing from the Bloody Sunday massacre. Can Rick and the seller be as one, or has the battle just begun? And later, the guys send Chumlee to the mint to design a new commemorative coin for the shop.', '2013-11-07', 21, '/ndnhploAXo9BUaOcpIDOImVZ25X.jpg', '2026-04-03T16:34:18Z', '2026-04-03T16:34:18Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('485e3978-aeb8-45f5-a215-c27f5c6fc06c', '101549f4-6ed1-45fa-b543-d08723f65306', 14, 'Episode 733', '', NULL, NULL, NULL, '2026-04-03T17:36:39Z', '2026-04-03T17:36:39Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('48611b14-c16d-4f93-ae2b-75c3ecfad208', 'b91685b5-c0d4-4040-b72e-620169541bfc', 6, 'Studio, Jewelry, and Babies', 'Jo has her first studio taping and needs something strong to get her through... Lauri get a surprise herself when she comes out of a photo shot and will her new business fail after all...Vicki is jealous and girl''s night out is a little more than cooking...Tammy leave town for the weekend and her daughter has party but what does it take to pull it off and oh does mom find out?...And will anyone ever buy a horse for Tammy''s girls again?', '2007-02-20', 44, '/kFz4xEmMKswAffI7q1rWLmLFmfh.jpg', '2026-04-03T16:35:30Z', '2026-04-03T16:35:30Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('4872dee1-32aa-42b4-9e2e-06ef8309cffa', '4f149920-ca76-4c31-a71b-d5b65a380905', 4, 'Greatest Haggles', 'Relive some of the toughest negotiations in the history of Pawn Stars including: a first edition "20,000 Leagues Under The Sea" book, a 1932 Ford Roadster, and a $95,000 Les Paul guitar owned by Mary Ford.', '2014-12-01', 22, '/99bmkqpi8X00vQ4hwfzgIUIfK3H.jpg', '2026-04-03T16:34:15Z', '2026-04-03T16:34:15Z');
