INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('48d29da9-1038-4631-b00e-b16a80067578', '45e01c04-6ac6-41e1-87d8-f749ee230385', 2, 'Pontypandy Extreme', 'Norman is upset when Trevor accidentally runs over his skateboard. Not prepared to wait until his birthday for a new board, Norman decides to retrieve coins from the bottom of a wishing well and buy one himself. When Norman becomes trapped, Sam must use the abseiling skills he has just learned from Tom to rescue him.', '2008-02-12', 10, '/pkRoPrXwNbCcu1JEZLQqgbQsTom.jpg', '2026-04-03T17:14:38Z', '2026-04-03T17:14:38Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('48d3ce0d-3b69-41a1-b2ed-6acdcbde592d', '3ade5e1f-8441-4c2c-acf6-fb933a61dcfa', 1, 'That''s The Way The Cookie Crumbles', 'Gizelle attempts to rekindle her friendship with Karen by delivering her homemade treats, but is shocked by what greets her at the door. Recovering from their miscarriage, Ashley and Michael are back in full baby making mode, meanwhile Robyn takes her romantic relationship with Juan to new heights. And with her wedding only days away, Candiace reveals that she''s invited her half-brother to the nuptials, causing her mother to launch a verbal attack that threatens to derail the festivities.', '2019-05-05', 42, '/4KA71PHqVnh4xmDBCtyhweXWOu1.jpg', '2026-04-03T16:35:39Z', '2026-04-03T16:35:39Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('48d6060e-f5c1-46c1-afcc-4115851ffd49', '650bac93-7b59-41fc-b277-dc6f8bdcd7bb', 9, 'A Very Marry Christmas', 'As Christmas approaches, Sue keeps a holiday secret from the family. After agreeing to watch the neighbor’s three kids, Brick finds himself trying to hide from them as they had such a good time that they keep wanting to come over and play. Mike doesn’t know how to react when Bill Norwood gives him a Christmas gift for the first time ever,', '2016-12-13', 22, '/mpH73qm3itMpcFGMAsNwdQUKUrV.jpg', '2026-04-03T15:40:31Z', '2026-04-03T15:40:31Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('48d92e4d-154f-4aec-a95e-a273ecae24c5', '22beba7f-9b8e-4563-93da-46e76ecba427', 13, 'Fantastic Freddy!', '"Teacher" Zoe arranges a field trip for Rocco and all her dolls, but there''s no room on the bus for Telly''s doll, Freddy. So Telly and Baby Bear give Freddy a day all his own, including a new game called Fantastic Freddy.', '2006-09-07', NULL, '/ldMLP4FFUEMXdnREv39WMO5cOmS.jpg', '2026-04-03T17:36:44Z', '2026-04-03T17:36:44Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('48da96c0-80b5-4761-b87a-c1ac763f9d21', 'aa3b2cc3-b0cb-4d01-8aa0-694981101aab', 2, 'A Bit More Time', 'As Bernard gets used to using his magic watch, he finds it comes in very handy at school.', '1997-11-21', 15, NULL, '2026-04-03T17:20:04Z', '2026-04-03T17:20:04Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('48dae6cb-50e5-4fb1-80f9-1b63f147f151', '97d7ff20-e6ff-4dbb-bcdd-fd87a1d0fa4e', 15, 'A Surreally Good Deal', 'Rick makes a surreally good deal for a painting supposedly created by artist, Rene Magritte. In order to have the apple of his eye authenticated, he and Chum must head to Belgium. Corey tries to score on a Tom Brady Pro Bowl jersey and Seiko watch.', '2023-06-28', 42, NULL, '2026-04-03T16:34:23Z', '2026-04-03T16:34:23Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('48dd4e0f-a7e1-4363-8c43-85b49cd88c5c', '1d455f60-41e8-4800-9359-4445e4df2b77', 12, 'Fathers and Music', '', '1990-05-04', NULL, NULL, '2026-04-03T17:35:45Z', '2026-04-03T17:35:45Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('48e3e2d4-96e6-4bb3-9294-800d7b6e986d', '9d74600d-7222-47c1-bd1b-635f5b41b7d1', 5, 'Mama Don''t Allow', 'When Miles gets a saxophone for his birthday, neither his parents nor his neighborhood can stand the racket! No one guesses what''s in store for them, when Miles and his Swamp Band receive and invitation to play at the Alligator Ball. Also includes Alligator Farm, Meet Fred Newman, Visit the Creole Queen, and The Saxophone Player and book reviews for Miranda, Apt. 3 and Alligator Shoes.', '1986-06-27', 30, NULL, '2026-04-03T17:36:15Z', '2026-04-03T17:36:15Z');
