INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('48f044bf-3195-450a-96f4-43806dadb544', 'f593d90c-5339-42f5-9c88-5bfd48d04075', 19, 'Two''s Company', 'Shaun is smitten when a bedraggled new sheep lands among the flock. After a wash in the sheep dip, the newcomer turns out to be quite attractive and Shaun immediately falls head over hoof for her. While Bitzer goes on a journey to find her rightful owner, the flock are kept amused by Shaun''s romantic antics.', '2010-02-21', NULL, '/f1RGBst6pfMOOW3SXLKa1FwkNAv.jpg', '2026-04-03T17:39:31Z', '2026-04-03T17:39:31Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('48f1061b-5bba-4e9b-88b4-0c9a6bd91052', '19e027c7-8626-44a9-96ba-d36b323b3a74', 7, 'I Want to Be You', 'Everyone loves Mokey, so Red decides to be just like her.', '1983-02-21', 24, '/inycUI8hhiFE99aBl4SRTAwwhsp.jpg', '2026-04-03T17:34:59Z', '2026-04-03T17:34:59Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('48f1814e-3b41-4216-9f7b-93816dbf6b65', 'db555b98-87d6-4cd2-b7b4-973f9206cb1e', 3, 'All Aboard the Rumor Train', 'As Tamra’s housewarming party continues, Kelly’s tear-filled exit prompts the other women to air their grievances. Gina confesses a painful secret to Emily. Shannon and Braunwyn cement their friendship and bond over challenges they face parenting. And while Kelly is in Aspen with Jolie, a new shocking rumor comes to light.', '2019-08-20', 44, '/mbamdQtuei2bK188jXuZIpYPAsU.jpg', '2026-04-03T16:35:34Z', '2026-04-03T16:35:34Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('48f371cc-85ea-4c68-bdf2-c714802c8b51', 'd1727ab0-c860-40ec-af59-b76f25c2e0ad', 6, 'Save the Ocean', 'Make a commotion and save the ocean.', '2009-07-10', 3, NULL, '2026-04-03T17:13:57Z', '2026-04-03T17:13:57Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('49018e42-ff5e-4034-9e55-1e5e102f128b', 'db81ad42-93a7-4926-89e5-d4cefa257b83', 7, 'Hair Brain', 'Linda and Gribbs are oppositions in the election for School Council. But when a haircut goes wrong,  Linda can hear people''s thoughts and decides to use her power for the election, despite the smelly consequences.', '2001-03-14', 24, NULL, '2026-04-03T17:40:41Z', '2026-04-03T17:40:41Z');
