INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('49077c90-2be5-4179-9ae5-aeecf30f8ca2', 'df895a8e-db4c-48d1-bf84-9a6a650583dc', 1, 'The Wheel Deal', 'Brain learns how to play basketball while in a wheelchair from a girl named Lydia.', '2010-10-11', 13, NULL, '2026-04-03T17:38:00Z', '2026-04-03T17:38:00Z');
