INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('4942508f-7bb3-4bc5-b273-c007edc790f4', 'abfe14ee-db42-4dde-a96a-601ff3c53ecc', 11, 'Asmodeus', 'Matthias sets off to find Asmodeus and recapture Martin''s sword. Helped by the shrews of Mossflower he finally meets his foe in the deep caverns where he guards the warrior''s sword - the object of Matthias'' quest. In a terrible battle Matthias kills Asmodeus. At last the serpent is dead and the sword is his. Now he can truly be a protector of Redwall. But news of Cluny''s assault reaches him and he realizes he is trapped deep underground.', '1999-10-02', NULL, '/1sFGSJ62tTLX9wDaWWdMJrQ723W.jpg', '2026-04-03T17:12:08Z', '2026-04-03T17:12:08Z');
