INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('49769285-0457-4aaa-b4b6-f2abfe7b8162', '465e5a6d-74b6-4ffb-b54f-51103f8329b3', 4, 'Fourth Wall Down', 'The ladies start to let their guards down as they take in the breathtaking sights of Turks and Caicos; Kenya gets a triggering message that sends her into a spiral; Melissa begins her high school sleepover-inspired night at the villa.', '2021-11-18', 45, '/nLSXI97Jb9lSqY91ljzp6vw0dq5.jpg', '2026-04-03T16:34:40Z', '2026-04-03T16:34:40Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('49796182-f9bb-44f4-98fc-1a1379c6b006', 'efdf1e4f-8476-4382-a9d7-2b9da4188be0', 10, 'Transformations', 'Rogers shows a wooden egg that contains a speckled egg. He then returns to the McFeely''s house, where plants are transplanted and ducklings are delivered. In the Neighborhood of Make-Believe, Lady Elaine Fairchilde retrieves the package for Purple Panda. Much to everyone''s surprise, the package opens itself. Maggie Stewart Stops Instead Of Mr McFeely A Videotape On How People Make Towels', '1996-08-16', NULL, NULL, '2026-04-03T17:35:47Z', '2026-04-03T17:35:47Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('497a93f3-e57e-4a55-a3e3-0f5fc297ee1c', '34674c90-410e-427c-be4d-2a6f6f865a80', 13, 'Dirty Sox', 'Pop goes the Pawn Stars when four original paintings by Andy Warhol brush by. Do the guys give these rare works 15 minutes of fame, or just send them back to the factory? Then, a baseball signed by members of the infamous 1919 Chicago Black Sox has Rick and Corey seeing green. Will the guys signal for a steal, or does a tough negotiation knock the price out of the park? And later, a pair of 10k gold sunglasses comes in on the night shift. Can Chumlee and Olivia eye a good deal on these vintage specs, or will the seller have it made in the shade?', '2012-06-11', 21, NULL, '2026-04-03T16:34:17Z', '2026-04-03T16:34:17Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('497f6d9c-b7e3-488d-9408-7e22a82d05af', 'd1863f2f-02ec-40ce-af64-db03fbe518a7', 28, 'Mi Amigita Rosita', 'Rosita is bothered by a story that doesn''t resonate with her culture, so she writes her own book about things she loves: dancing, Mexican wrestling and playing with her friends. Also featuring celeb vocab in espanol with Gina Rodrigues, and Elmo the Musical. Brought to you by the ABC''s and the number 9.', '2016-07-16', 30, '/8qhlVyqgBXGlHjAEywzfS2C0vY2.jpg', '2026-04-03T17:36:48Z', '2026-04-03T17:36:48Z');
