INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('49834956-5618-48a6-a455-ded523ed9850', '6c1ec19f-74df-4f35-9a61-17b98175d826', 8, 'Mind Your P''s and BBQ''s', 'Garcelle is honored for her work with a local charity, but her acceptance speech isn’t charitable to one guest. The ladies feel mom-shamed when Denise shows up to Kyle''s kid-friendly barbecue without her kids. Lisa, Erika and Teddi are annoyed when Aaron mansplains to them – a situation Dorit knows firsthand is problematic for husbands in this group.', '2020-06-03', 43, '/fslHhX8mGivoQCqG9am5hKGdMkL.jpg', '2026-04-03T16:34:58Z', '2026-04-03T16:34:58Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('49843bc0-9b6c-42f9-a71e-f3493aec28eb', '9c9d89df-5f6b-41d0-84c6-b8ca7bd2a2e6', 5, 'Bug Scouts', 'Bug Scouts Elmo, Abby, and Cookie Monster want to help Artie the Ant carry a heavy crumb. They try pushing the crumb, but it’s too heavy to move. What if they break the crumb into smaller pieces? Let’s try!', '2021-12-09', 20, '/zMldaJvP7qKtyDFI4VWiVwzuVE1.jpg', '2026-04-03T17:36:50Z', '2026-04-03T17:36:50Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('49873ae5-1f21-418e-a8cb-ecbbe29d41a5', 'ae8f64d9-4b83-4147-a44c-bfe720381f8e', 13, 'Abby Has the Sparkle Fairy Freckles', 'Elmo and Abby are playing tag. Suddenly, Abby’s freckles start sparkling! Abby calls the Fairy Doctor who looks at Abby’s freckles. Abby has a case of the Sparkle Speckle Fairy Freckles! This is where freckles sparkle and glow, and eventually fall off. The Fairy Doctor tells Abby the magic words to get the freckles back, “Fricka-Fracka, Freckle Back-A”.

All of a sudden, Abby’s freckles jump off of her face, glowing and bouncing all around!  Abby, with the help of Alan, chases one freckle as it bounces into Hooper’s store. Chris spots it on a cereal box. Abby says the magic words and poof! The freckle returns to Abby’s face. Abby has five more to find! Rosita notices the dot on the center of her flower drawing is sparkling and so is the dot on the “i” in her name “Rosita.” Abby says the magic words two times and the freckles reappear on Abby’s face.

Only three more to go! Abby notices that all the freckles seem to be hiding on little circles and realizes she should look for circles! Abby sees two more freckles go bouncing into the laundromat. Mama Bear notices a sparkling freckle on Baby Bear’s polka dotted underpants and Elmo notices a freckle on Leela’s nose ring. Magic word time! Abby leaves the Laundromat and notices a freckle on Cookie Monster’s cookie. He’s about to take a bite! Luckily, Abby stops him just in time to say the magic words and get the last and final freckle back on her face. Cookie Monster happily eats the cookie, while Abby admires the six freckles on her face!', '2009-12-02', NULL, '/zxLnIUTO8qtWk5m4p2ZZ7b4jyDl.jpg', '2026-04-03T17:36:46Z', '2026-04-03T17:36:46Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('49897cda-4764-436e-8a7d-a369f68a9495', 'a8db07e5-fba3-49a9-bd12-947c111b39be', 22, 'Reunion (2)', 'A reunion continues with the Big Apple ladies. Here, Bethenny gets emotional about her life situation, Dorinda addresses her inclination to meddle, and the group zeros in on the saga revolving around Tom.', '2016-09-07', 44, NULL, '2026-04-03T16:35:24Z', '2026-04-03T16:35:24Z');
