INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('49a0d4b1-4e37-4220-9575-7fc019aedac5', '015cceb3-0a47-4f26-a683-81a4696951f0', 9, 'Postman Pat''s Magic Christmas', 'Pat has so many parcels and letters to deliver that he does not know how he will get his rounds done in time for the village Christmas party and make a surprise visit as Santa Claus. But help is at hand from a very cheerful stranger with a big white beard and shiny black boots – who could it be?', '2003-12-25', 25, NULL, '2026-04-03T17:14:29Z', '2026-04-03T17:14:29Z');
