INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('49e8ff4d-b350-4629-87ef-d9826c733d7b', 'da06465b-9154-4feb-a455-374df7dab02f', 1, 'Telly Learns How to Catch a Ball (4083)', 'Everyone on Sesame Street is outside having fun and playing catch! Well, everyone except Telly, who admits to BabyBear he doesn’t know how to catch a ball. Baby Bear, Rosita and Maria each try to help Telly. But no matter how hardhe tries, the ball slips through his fingers! Just when Telly decides he’s ready to quit, Baby Bear introduces a surpriseguest, New York Yankees manager, Joe Torre! Joe assures Telly he’s doing everything right, and reminds him thatsometimes learning something new takes a lot of practice. As he leaves, Joe tosses the ball to Telly—and he catchesit! Now Telly wants to practice even more', '2005-04-04', NULL, NULL, '2026-04-03T17:36:44Z', '2026-04-03T17:36:44Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('49ee1cf3-fd5c-47b4-bc04-328758eeda5a', 'b598da2e-89fd-4e98-8d0d-4bce6bbd4ac9', 11, 'Liberace', 'Sketches/Songs: ""Never on Sunday"", ""Swedish Chef"", ""Veterinarian''s Hospital"", ""Muppet Newsflash"", ""She Wants to Sing in Opera"", ""Liberace bird concert""', '1979-01-19', 26, '/331idxMwlvNk2fp4bLFWUmKvt5a.jpg', '2026-04-03T17:35:24Z', '2026-04-03T17:35:24Z');
