INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('4a21d410-d72b-4b41-b007-6ca34753fc9b', '4f8c16f6-9b92-4be9-9b6b-837f26ad3720', 6, 'Show Time', 'On Bernard''s birthday, Grandad performs a conjuring show for his party. However, the show looks like coming a cropper thanks to a rude party guest. Then Bernard performs a few tricks of his own, and soon the tables are turned.', '1998-11-06', 15, NULL, '2026-04-03T17:20:04Z', '2026-04-03T17:20:04Z');
