INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('4a5684a0-c266-41be-a7ba-7b194211b93d', '23af85bf-93be-48cd-913c-09c2f60403da', 7, 'Raising Gazorpazorp', 'Morty convinces Rick to buy him a sexy robot.  Later Rick and Summer spend some quality time together.', '2014-03-10', 22, '/j7qn7TIOSQOHZBgVi4NKnTpIcgM.jpg', '2026-04-03T15:40:41Z', '2026-04-03T15:40:41Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('4a5a2573-ebf3-4ed7-866f-7759598f9f5c', 'd5351b60-8a0c-482a-a6dd-4fb860cfe143', 14, 'Episode 1404', 'Mister Rogers arrives with two pieces of construction paper which he takes to the kitchen and uses to make a peek-a-boo game. As he plays, he sings Look and Listen before sharing an animation about a moving dot.

At Brockett''s Bakery, Mister Rogers watches as Chef Brockett and Maggie Stewart make noodle pudding. They pantomime each ingredient before adding it to the recipe.

In the Neighborhood of Make-Believe, Edgar Cooke is playing peek-a-boo as he awaits the return of the royal family. His play, however, is bothersome to Miss Paulificate who is trying to work.', '1975-03-06', NULL, NULL, '2026-04-03T17:35:41Z', '2026-04-03T17:35:41Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('4a5c45af-1554-4e37-ad6d-7ad20e2fa09a', 'ae373811-cd7f-4e4c-bf5f-6e5eef167f8d', 1, 'No More Kings', 'The story of the American Independence movement.', '1975-09-27', 3, '/7eGHtctYGJDbOINhMosn5g4pMVS.jpg', '2026-04-03T17:13:56Z', '2026-04-03T17:13:56Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('4a61b5a5-de7c-4ba0-9589-078bf6b73d32', '573fa62f-55a9-4f17-97cc-d1a005a83cc8', 9, 'A Trip to the Moon', 'After looking through Yasmine''s telescope, Tamir, Elmo, and Zoe pretend to be astronauts and learn about the moon.', '2025-03-13', 26, '/zwtllKe09cJx8Y6kYf9ViEwhZo.jpg', '2026-04-03T17:36:52Z', '2026-04-03T17:36:52Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('4a6a432d-1886-432a-8f7b-a67a86217597', '8bae6aa3-4b55-4fa6-bc15-8f4317bd1f13', 8, 'Episode 8', 'Rogers shows steam from a tea kettle. Mr. McFeely shows him the use of a steam engine. Robert Troll plays ball with Lady Aberlin, Handyman Negri and Daniel.', '1972-03-01', NULL, NULL, '2026-04-03T17:35:40Z', '2026-04-03T17:35:40Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('4a6f7c6d-b6c4-47d1-bc6f-368f794543c9', '3ee646e8-23ae-4dec-bbc6-c7e6a210d55b', 24, 'Hatching an egg', 'Gordon, Susan, Gina, and Uncle Wally convene outside Oscar''s trash can to surprise him on his birthday. Telly happens over to the Fix-It Shop, where Luis is painting a sign.

Sponsors: G, M, 19', '1990-12-13', NULL, NULL, '2026-04-03T17:36:38Z', '2026-04-03T17:36:38Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('4a7e8c5f-c690-4965-bdb2-180ad1426b1e', '42e591e2-2a88-4434-ae9f-3d4b1d685613', 5, 'Ready to Rumble', 'Let''s get ready to rumble with the Pawn Stars as the guys check out a pair of punching bags owned by Rocky Marciano. The only champion to go undefeated in his career, can they land a knockout in negotiations? Then, Rick checks out a Swiss Doxa pocket watch from the 1800s. Will he give it the time of day? And later, when Corey installs a punching bag in the warehouse, the Old Man is inspired to show off his boxing skills.', '2013-06-13', 21, NULL, '2026-04-03T16:34:18Z', '2026-04-03T16:34:18Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('4a82497c-cde1-440a-b8e7-6ff1f145ebca', '684af21e-0459-4832-b094-db0997e354c5', 16, 'Reunion Part 1', 'Hosted by Bravo''s Andy Cohen, Part 1 brings Lea Black, Marysol Patton, Adriana De Moura, Ana Quincoces, Joanna Krupa, Karent Sierra, and Lisa Hochstein to rehash this season''s drama.', '2012-12-27', 44, '/5X7VFVujrY5i1ZJXVxd3wDC70WM.jpg', '2026-04-03T16:35:10Z', '2026-04-03T16:35:10Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('4a83733a-4731-4ec9-a855-cda0c9ceb22f', '2afe02c5-499e-4d46-ad93-0504a321941f', 7, 'The Great Escapes', 'Martin and his friends are captured by Slo Worms and are dragged into the lizard''s lair.', '2002-01-14', NULL, '/oNIkt1OgqmNFNhXIJc0vqmx4LON.jpg', '2026-04-03T17:12:08Z', '2026-04-03T17:12:08Z');
