INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('4a98b145-9966-410e-a101-336826bc6998', '8bae6aa3-4b55-4fa6-bc15-8f4317bd1f13', 34, 'Episode 34', 'Rogers and Al Worden recall the question-and-answer period they conducted with children about going to the Moon. Worden shows the envelope of questions he took with him on his mission. Lady Elaine turns him upside-down with her boomerang.', '1972-04-06', NULL, NULL, '2026-04-03T17:35:40Z', '2026-04-03T17:35:40Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('4a9c416e-6836-4222-9b38-5c1850e22f10', '97a3d1f5-a8f1-47cd-8122-2e74a092836d', 6, 'Get the Message (2)', 'Jamal goes straight to the art gallery that Ghostwriter read on one of the shirts of the two men that ran in front of the camera. He learns that one of their paintings was stolen. The security guard chased the thief and it was the same place where the accident occurred. The team''s feuding causes Ghostwriter to begin fading away.', '1993-10-10', NULL, NULL, '2026-04-03T17:40:28Z', '2026-04-03T17:40:28Z');
