INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('4aa645eb-aeae-40b3-9f08-9d0049c9425c', '8bae6aa3-4b55-4fa6-bc15-8f4317bd1f13', 57, 'Episode 57', 'Ezra Jack Keats visits the Neighborhood of Make-Believe and tells a story about a bad king. Keats must report his story to King Friday.', '1972-05-09', NULL, NULL, '2026-04-03T17:35:40Z', '2026-04-03T17:35:40Z');
