INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('4ab0c738-f611-4f2f-9094-83891f24208a', '19e027c7-8626-44a9-96ba-d36b323b3a74', 1, 'Beginnings', 'Gobo''s Uncle Matt discovers the opening to Outer Space and sets off to explore it, leaving Gobo behind to explore Fraggle Rock and pick up the postcards Matt will send.', '1983-01-10', 24, '/rLAQJ493gJ9IVN2gNQ7uotpTNH0.jpg', '2026-04-03T17:34:59Z', '2026-04-03T17:34:59Z');
