INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('4ab67f33-0a65-43a7-ad75-1b245f75d0af', '04e133fd-c4a3-4dfa-8369-c6dcfd1e3a5a', 47, 'Linda''s friend Ed visits', 'Linda''s deaf friend Ed visits Sesame Street and communicates through sign language with Linda and the community. The episode celebrates different forms of communication and the power of friendship.

Sponsors: G, H, 9', '1985-01-22', NULL, NULL, '2026-04-03T17:36:36Z', '2026-04-03T17:36:36Z');
