INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('4ac86d01-98a5-4383-96d0-4e13ee92768c', '7ccd5605-fe0b-4e00-ae7f-3e3daa252f8b', 12, 'You Can Dish It But You Can''t Take It', 'Lynne Curtin’s daughters, Raquel and Alexa, are home alone when a stranger knocks on the door and hands Raquel an eviction notice. Vicki Gunvalson hears terrifying health news about her daughter, Brianna. Alexis Bellino and Gretchen Rossi meet for dinner and discuss Lynne’s housewarming party the night before. The ladies head to San Francisco for a girls weekend away. At dinner that night, everyone is annoyed by Alexis’ non-stop phone calls and texting with Jim at the table. The ladies begin the next day with a round of shopping followed by a beautiful water front lunch. Vicki takes a business call at the lunch table and this rubs Alexis the wrong way and she confronts Vicki about her comments over the previous night’s calls to Jim.', '2010-02-11', 44, '/pE5dgWeEHXyKBEcEwQlQxoT69Iq.jpg', '2026-04-03T16:35:31Z', '2026-04-03T16:35:31Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('4ad4786f-464a-4ac2-b0d8-0ec93d892875', '7bc54df3-f32a-454e-aef6-a9436c35d53b', 41, 'The NOM Models Pt 7', 'Bob Trow has made his own model of the Neighborhood Trolley and its tracks for Rogers. In the Neighborhood of Make-Believe, King Friday is tired of waiting for the baby to be born. Several neighbors decide to hold a play based on what King Friday puts in a suitcase.', '1970-03-30', NULL, NULL, '2026-04-03T17:35:39Z', '2026-04-03T17:35:39Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('4ad60f72-24aa-43ae-9646-0cec13e4c539', '1f34e241-4c1d-4586-921a-1c5aeb1fbbaa', 53, 'The Count’s suitcases', 'Biff supervises as Sully drills the sidewalk outside 123 Sesame Street. Gordon comes to the window, begging them to stop, as baby Miles is going to be taking his nap. Sully can''t seem to drill any quieter, so Biff suggests they take their lunch break earlier.

