INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('4ae0551e-1037-4453-931a-c00bfcc30984', '63f9bf6d-39b3-44f4-b885-a56807277a80', 102, 'The Muppets On Muppets', 'Feature filmed in the late 1990s for Muppet Show reruns airing on the Odyssey Network, but not seen by the public until it was included as a bonus feature on Muppet Show: Season Two DVD box set. Kermit, Gonzo, Rizzo, Animal and some special guest pals sit down for these personal, revealing interviews. Notable for including multiple characters who were created for Muppets Tonight and had never appeared on The Muppet Show.', '2007-08-07', 13, '/f3a11y57y4f9gmxWByIFe9POMfl.jpg', '2026-04-03T17:35:23Z', '2026-04-03T17:35:23Z');
