INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('4b1d2a5c-fbbc-4df4-93d4-7c2a2a02b452', 'ebc99729-ccb7-4d64-82c1-42708cd7ba85', 64, 'Episode 64', 'Top Ten Birds: Will the starling stay at the top? Britain''s second garden bird survey is launched on Saturday and your help is vital! Have a pencil and paper handy for the details.', '1981-04-23', NULL, NULL, '2026-04-03T17:21:55Z', '2026-04-03T17:21:55Z');
