INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('4b23741e-5c11-44c1-9244-b626d6316fc4', '65d1cad8-0120-425e-ae9b-5020ce773b32', 17, 'A Source of Discontent', 'The ladies partake in several local activities in Amsterdam; Emily receives a distressing call from Shane; Heather finds comfort in visiting her parents'' former home before spreading her father''s ashes; Gina struggles with a scandalous rumor.', '2025-10-30', NULL, NULL, '2026-04-03T16:35:36Z', '2026-04-03T16:35:36Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('4b23b607-50bc-4146-ba64-f0fbe1bbd6ff', 'f29f456f-8e38-49af-8808-7943977100ec', 5, 'He Said, He Said', 'Arthur, Buster, and George are excited to watch a special Bionic Bunny episode, but the TV blacks out. Meanwhile, D.W. and Bud are building a huge Tower of Cows, which Carl also starts doing.', '2016-10-12', 13, NULL, '2026-04-03T17:38:02Z', '2026-04-03T17:38:02Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('4b2739c9-3397-4955-985a-b86f3ba710a0', '6d2b78d7-2612-4afb-81ca-dee774af9c2b', 10, 'Episode 10', 'Rogers visits an expert weaver and helps in making a scarf. Lady Elaine invites the Junior Tamburitzans to her studio.', '1987-05-11', NULL, NULL, '2026-04-03T17:35:44Z', '2026-04-03T17:35:44Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('4b299ff4-2817-4bb9-bd6b-618b48aa03ac', '70c8cb46-2494-4dd4-98f6-6bfb9b3faf73', 2, 'Wheels', 'The Pawn Stars have a chance to buy an incredibly rare 1970s Indian mini-motorcycle. Will they purchase the little hog and restore it to its former glory, or will they all be taken for a long bumpy ride and find out it''s a fake? Then Rick and the Old Man consider buying a ship''s bell believed to have been salvaged from a 1600s shipwreck. With suspicion that the bell was never submerged in salt water, the Pawn Stars will need to decide if the deal will ring true or crack under pressure. And later, a man takes a chance at selling his classic 1900s roulette wheel. Will Rick take a gamble with luck on his side, or will the deal spin out of control and put him in the red?', '2010-01-18', 21, '/5SwCvzDc3OEtqhhKq4j8bEEzgrS.jpg', '2026-04-03T16:34:16Z', '2026-04-03T16:34:16Z');
