INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('4bd092d9-e8f0-4225-88af-3a25a04935dc', '45e64a15-8fc0-4e4b-a1ca-9e3f42f3634d', 4, 'Skin', 'Learning about skin science is no sweat.   It''s gigantic. It''s gargantuan. It''s your skin. It''s your body''s biggest organ. If you could lay your skin out   flat, it would cover about one and a half square meters. Your skin stops you from drying out, protects you   from the weather, and keeps bacteria and viruses from getting inside your body.   Your skin is also your personal air conditioner and heater all in one. Sweating cools you off. When you''re   hot, glands in your skin push a mixture of water and other chemicals onto the surface of your skin. When   the water evaporates, it takes some of the heat with it, and you''re cooler. When you''re too cold, your skin   muscles start twitching. Shivering makes your body warm up.   Without skin, you wouldn''t be able to feel the difference between a sheet of paper and a wool blanket.   There are thousands of touch receptors inside skin. When you touch the remote control, the receptors   send information about the remote''s temperature, thicknes', '1993-10-01', 26, '/5bMTXdmgDT2W4p7hQyRhscEDt3r.jpg', '2026-04-03T17:37:20Z', '2026-04-03T17:37:20Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('4bdaabd4-bcc9-43bb-827d-60500f52a94f', '9b95011e-93db-4e56-a45d-8aa956c15997', 11, 'Lights, Camera, Avalanche!', 'It''s snowy and Norman is directing his very first movie up in the mountains, starring Mandy and Sarah. Sam and Elvis are also up in the mountains, on their way to a skiing lesson with Penny.', '2014-10-14', 10, '/ixYMrOHESeg2iC3VqjDuld5ipG6.jpg', '2026-04-03T17:14:40Z', '2026-04-03T17:14:40Z');
