INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('4bea30ac-7c88-4142-808c-5aa663a0d729', 'b8c1b631-9850-45f3-9361-cdad5571a492', 5, 'The Last Family Gathering', 'Kody worries about tight quarters after touring Janelle''s new RV, and Meri feels hurt when Kody suggests she move away to run the bed and breakfast full time. Then, the family reunites for Ysabel''s graduation party with a bittersweet celebration.', '2022-10-09', 43, '/wKdzLgOLKUvW7B6Hpo7QZd1GSpX.jpg', '2026-04-03T16:34:32Z', '2026-04-03T16:34:32Z');
