INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('4c0f61ee-1b3a-41a7-b9ec-54f87c486fc6', '78a02d50-e3dc-4549-844a-3cf357a32ef4', 25, 'Secrets Revealed', 'Phaedra and Porsha explore the world of edible hotel decor, while Kenya looks into maximum security for Moore Manor. Kandi''s baby mogul Ace has his first photo shoot for his baby product empire, while Noelle confronts Cynthia about how she handled the news of her divorce. As Kairo heads off to college, Shereé gets ready for her book launch. While Kenya and Cynthia try to persuade Phaedra to warm up to Kandi before their beef heats up to a full boil, Shereé and Porsha share a moment that sheds light on one of the biggest conflicts of the season. Porsha and Peter finally get to the root of their longstanding feud with a shocking admission from Porsha.', '2017-05-14', 43, '/5mvNfFSNYL7WSsikoqawgix0uNl.jpg', '2026-04-03T16:34:48Z', '2026-04-03T16:34:48Z');
