INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('4c289a0d-d972-4624-8ecd-41fe36d6e916', '70c8cb46-2494-4dd4-98f6-6bfb9b3faf73', 24, 'Whale of a Time', 'The Pawn Stars are presented with an engraved whale''s tooth believed to be authentic 1800''s scrimshaw. Can the gang make a whale of an offer or will it be a fluke? Then, the Old Man sets his sights on a pair of mysterious Civil War era rifles. Will he take aim and hit the mark or end up dodging a bullet? And later, a man brings in a pristine edition of Playboy''s very first issue - featuring Hollywood legend Marilyn Monroe. Will Rick sneak a peek or just read the articles?', '2010-06-14', 21, '/6GFOpWNeu8u0FUak4Z5gkUuOaC7.jpg', '2026-04-03T16:34:16Z', '2026-04-03T16:34:16Z');
