INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('4c4f00a9-0ae6-499e-90d3-861afd10e4ac', '05c0e384-194c-4417-9f62-803eb615e409', 19, 'Looking for a place for a windmill', 'Title number 0019. Opens with Mister Rogers arriving with a toy raft made out of straws. He plays with it and other floating toys in a tub of water. In the Neighborhood of Make-Believe, Scientist Alder is checking the wind velocity for Donkey Hodie, who is looking for a place with a good wind to build his windmill. He decides the best place would be in the hills behind the Castle, but King Friday objects because he wants his privacy. Back at the house, Mister Rogers shows different kinds of fans.', '1968-03-14', 28, NULL, '2026-04-03T17:35:38Z', '2026-04-03T17:35:38Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('4c54ab02-e06d-4123-9673-a58f031ff00c', '9df0f8c1-723f-4061-8692-e8c51a6a7223', 2, 'Episode 2', '', '2026-05-31', NULL, NULL, '2026-04-03T15:40:44Z', '2026-04-03T15:40:44Z');
