INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('4c5b05d3-fd30-4132-be6a-4475c439a64e', '4fe93658-c463-4329-8e64-9d523869c2cb', 26, 'Wise Guys', 'The Pawn Stars take a mission briefing when presented with a fully functional 1941 M3 Armored Scout Truck from World War II. Will the gang head to battle for this bulletproof piece of military history or will an auto ambush force them to retreat? Then, Rick and Corey meet a man hoping to sell a check signed by notorious mobster Carlo Gambino. Will Rick make him an offer he can''t refuse or will this deal sleep with the fishes? And later, Rick and Chumlee check out a 1987 Apple II GS Computer. Will they boot up some cash for this classic piece of technology or is the deal bound to crash?', '2011-02-14', 21, '/yPT54dWgBaFG3gc7TCM3SKqgtKl.jpg', '2026-04-03T16:34:16Z', '2026-04-03T16:34:16Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('4c5d5a6b-843a-45b8-9325-308b353d7da3', 'e93f04c2-7344-4b93-abba-8ba1b2f8eb35', 107, 'Episode 642', '', NULL, NULL, NULL, '2026-04-03T17:36:30Z', '2026-04-03T17:36:30Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('4c608398-5950-4326-974e-20b08cb68b9d', '05c0e384-194c-4417-9f62-803eb615e409', 1, 'Change: The First Program', 'Title number 0001. Opens with Mr. Rogers talks about tying his shoes. Mrs. Russellite sends an invitation to Mr. Rogers to see her lampshade collection. Lady Elaine''s changes to the geography of the Neighborhood of Make-Believe worry King Friday, who begins to impose new rules and restrictions in Make-Believe, and builds a wall.', '1968-02-19', 28, NULL, '2026-04-03T17:35:38Z', '2026-04-03T17:35:38Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('4c60ef64-7a31-490f-8731-daea14c5733f', 'acac417e-2aa3-42e7-9e08-ed0d6071a3ee', 7, 'On an Island', 'Bethenny and Dorinda hit the ground in Puerto Rico and get to work. Ramona attempts to mend fences with Sonja. Carole works on a revealing story with a magazine, while Luann starts to plan a special performance. Bethenny lets Dorinda in on an incident involving Carole’s ex, Adam. Carole confronts Bethenny about an accusation she’s made that puts Ramona in the middle of their friendship.', '2018-05-16', 60, '/vArdIfVL87y13cB1Ifpi3SY2zD4.jpg', '2026-04-03T16:35:25Z', '2026-04-03T16:35:25Z');
