INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('4c731fb5-45d4-4475-a55a-45303ce796cf', 'f4d370ca-3c39-40a8-911d-e2b5e7c6b0d7', 11, 'Ruff and the Big Wheel', 'When Little Bear accidentally breaks a wheel on Zebra’s cart, Old Bear finds a box of shiny, round lids to mend it. There are enough lids left over to make a lovely go-cart. When it is finished it turns out that Ruff is too big and needs a bigger cart of his own. But there are only two wheels left. Old Bear hunts in the cupboard under the stairs and finds a wheel that is much bigger than all the others. You can’t make a go-cart with only one wheel but what Old Bear does make is even more fun.', '1996-11-13', 10, NULL, '2026-04-03T17:18:56Z', '2026-04-03T17:18:56Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('4c783345-f643-4a16-9013-c072fd359966', '54c29014-2dbd-49ff-a23f-cf4c546e0b3a', 6, 'Unhappy Anniversary', 'Ramona returns from Africa with renewed inner peace and tries to bring the feuding Heather and Aviva together; Kristen and Carole meet up with Beverly Hills housewives Brandi Glanville and Yolanda H. Foster; and Heather hosts an anniversary party.', '2014-04-15', 60, NULL, '2026-04-03T16:35:23Z', '2026-04-03T16:35:23Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('4c82bdfd-f94f-4c77-813d-b89603393bbf', '4060ad7f-4b8f-4393-8eb1-66a150b928b6', 20, 'Potluck Pickle', 'Elmo, Abby, Cookie Monster and Gover want to bring vegetable lasagna to Sesame Street''s potluck party, but they don''t have the right ingredients and their oven is broken.', '2021-03-25', 26, '/sZERraNHqZnOkKUXju4YcaqKxoA.jpg', '2026-04-03T17:36:50Z', '2026-04-03T17:36:50Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('4c835df7-7b90-4f77-803f-8528dfeb010e', 'ceb4c48c-6260-40df-a265-c9fbfa7885f9', 6, 'Muffy Misses Out', 'Muffy goes to an opera but is also worrying that the members of Mrs. McGrady''s bake sale will need her help.', '2018-02-12', 13, NULL, '2026-04-03T17:38:02Z', '2026-04-03T17:38:02Z');
