INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('4c911396-8f66-4e4f-ba81-1a2dd6d82f57', 'dd4554c2-6e74-499a-808a-7dad5f2be50f', 8, 'Gliding Over All', 'Walt takes care of loose ends; Walt makes a dangerous decision.', '2012-09-02', 48, '/uTAPBgAah14jQbV98Sw7iqJD4W7.jpg', '2026-04-03T15:40:34Z', '2026-04-03T15:40:34Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('4c924e1a-5612-4f16-937e-491ad5ceddeb', '5b5e8b2f-0a85-4488-b3dc-3d8b794e6582', 5, 'Moving In, Moving On And Moving Fast', 'Tamra and Shannon have their first face-to-face with Meghan''s new baby and learn they''ll soon have to face Vicki. Lydia''s family takes a luxurious Hawaiian vacation full of uncomfortable conversations, while Kelly tackles her fears about her mother''s mortality and her desire to move on with Tamra and Shannon. Vicki tries to settle into her new office and meddle in her son''s love life while Peggy invites her friends to the unveiling of her custom-designed Lamborghini.', '2017-08-07', 44, '/rmLyAgwWHhGJAR29DeTr2sCpKMy.jpg', '2026-04-03T16:35:33Z', '2026-04-03T16:35:33Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('4c959a60-20de-4678-9c40-abdfc1af9bc1', '852a07b0-f228-4197-9147-7aeed79390bf', 9, 'The Salem B**** Trials', 'Eboni takes Sonja to Philadelphia to meet a matchmaker. Leah hosts the ladies on an excursion to the witch capital of the world: Salem, Massachusetts. At Leah''s latex and leather dinner, the aftermath of the election leads Eboni to question some of the ladies'' allegiances.', '2021-07-06', 60, '/bQnifmGkGe7GCy1ifsQlbh9ekvI.jpg', '2026-04-03T16:35:26Z', '2026-04-03T16:35:26Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('4c983f18-e958-4ee3-806c-a73319da96c6', '7c756336-29db-4634-b976-e993e8f51da2', 12, 'Home Is Where The Truth Is', 'The ladies question Karen''s quick move out of Potomac after she reveals the location of her new home. Robyn finally confronts her ex-husband Juan about their relationship and is surprised by his confession. Monique shows off her new Potomac home, while Gizelle searches for the courage to break it off with her boyfriend Kevin. The women attend an "exotic" anniversary party at Karen''s new home and are shocked to discover her new life outside of Potomac.', '2017-07-02', 42, '/c0vA3no8QnmXw73PozP5eWlwY4U.jpg', '2026-04-03T16:35:39Z', '2026-04-03T16:35:39Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('4c99c780-9e9a-42d7-8091-024a7cb1f60b', 'c01ddd2a-bdb1-4c97-8d04-58f791ef1c24', 13, 'Puppies', 'The discovery of a litter of eight puppies turns Chris, Martin, and Zoboo into puppysitters. When one of the puppies and a calf both wander off from their mothers, everyone at Animal Junction learns how important it is to keep a close watch on babies.', '1999-02-10', 27, NULL, '2026-04-03T17:10:55Z', '2026-04-03T17:10:55Z');
