INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('4ca2da7e-942e-423c-94e7-bbdd558c125f', 'f63c3f61-0970-4e37-81cc-2b9045a9952c', 37, 'Monster Sing-A-Long On Sesame Street (3952)', '', '2001-02-20', NULL, NULL, '2026-04-03T17:36:42Z', '2026-04-03T17:36:42Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('4ca43a8a-01b4-4273-a644-ab046cdcf2b0', 'ecb64ef3-4f80-45a7-b4a9-c04434b02e35', 15, 'Rock Bottom', 'Hit rough terrain with the Pawn Stars when Rick bumps into a vehicle known as a rock crawler. Will he steer this off-roading dream machine home or will negotiations hit rock bottom? Then, Corey does a touchdown dance when a game worn jersey from Bob Hayes gets carried in. Will his victory be short-lived? And later, when the guys realize they''re getting negative reviews online they attempt to solve the problem, but will they change for the better or worse?', '2014-02-20', 21, '/oDysoeLVvUaZHvPPCPiFX1jilMJ.jpg', '2026-04-03T16:34:19Z', '2026-04-03T16:34:19Z');
