INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('4caaf5b5-f208-4db8-9355-8050887c75cf', 'd01919fb-98e0-42bf-b9d9-1cecf912f6e1', 32, 'Exploring the Land of Lulu-Puddy (3817)', '', '1999-01-19', NULL, NULL, '2026-04-03T17:36:42Z', '2026-04-03T17:36:42Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('4cac1579-66cf-4b6a-9c2b-c68341d0b2d6', 'c21dbd22-5e2e-4414-bb67-750399aaf6f0', 23, 'Bear-ly There', 'Get fired up with the Pawn Stars as they set their sights on a rare 1870 Volcanic pistol. Can Rick and Corey make a deal on this forefather of the Winchester repeating rifle or will an unseen problem cause the deal to backfire? Then, the guys are breathless when a World War II gas mask made for the U.S. Navy floats up to the counter. Will Rick and Chum sniff out a good deal for this piece, or will the negotiations start to stink? And later, the Old Man finally wakes up from hibernation when an early 1900s life-sized Steiff bear prowls into the shop. Can he work up the grizzly courage to buy this rare toy, or will he only offer the bear minimum?', '2012-02-13', 21, NULL, '2026-04-03T16:34:17Z', '2026-04-03T16:34:17Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('4caf7492-97c0-4996-824c-4c098461a6bc', '9e30a416-edbd-490b-bb0f-18d5c45f0bdf', 23, 'Secrets Revealed', 'Watch never-before-seen moments, including Kim giving Brandi acting lessons, and Lisa and Joyce bonding.', '2014-04-07', 42, '/8x4NoP5I26kqYokx7HbZ5sdpPGI.jpg', '2026-04-03T16:34:55Z', '2026-04-03T16:34:55Z');
