INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('4cb1b4be-0fa8-4819-8467-0a303f110577', 'ad4e4348-3334-4a08-8928-455d9ba524c1', 23, 'Mac Davis', 'Beaker tests Muppet Labs'' new copier machine, ultimately falling into it and making seven copies of himself. The multiple Beakers gang up on Bunsen, and the doctor is forced to wear a disguise and hide from his assistants.', '1981-03-08', 26, '/kAaKAuejFSMyVn31dPzx03ao3Tv.jpg', '2026-04-03T17:35:25Z', '2026-04-03T17:35:25Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('4cb21977-99eb-4734-9ad7-1fd2d3e0c6e5', '4aa00613-08c0-402b-85c7-6805658d02a1', 5, 'Two Old Potatoes and Me', 'Jordan Puryear reads "Two Old Potatoes and Me," about a girl who works with her father to recycle two rotted potatoes by replanting them using the sprouts to grow a whole new crop of potatoes. LeVar, working with his daughter, is inspired to make potato dishes from recipes in the book.', '2005-01-21', 30, NULL, '2026-04-03T17:36:21Z', '2026-04-03T17:36:21Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('4cb24770-38be-4617-a6ad-0652776ee4ed', '42e591e2-2a88-4434-ae9f-3d4b1d685613', 42, 'The Amazing Chumlee', 'Spin a web with the Pawn Stars as Corey and Chumlee check out a copy of Amazing Fantasy #15, featuring the very first appearance of Spider-Man. Will the comic set off Chum''s "Spidey senses?" Then, Rick''s buddy Davey Deals drops by with a samurai sword from the 1500''s. Will they cut a cash deal, or would Rick consider a trade? And later, when Chumlee wants a promotion, he has to take a management test.', '2013-12-12', 21, '/kzLpktyxhIVNZbDDjqTCNujsZJn.jpg', '2026-04-03T16:34:18Z', '2026-04-03T16:34:18Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('4cb3bffe-fdb6-4e4c-857c-0e5cb0d8c8c8', 'e3a28669-91b5-45f7-bb73-5006acc084e8', 40, 'Shaun Encounters', 'Two alien kids land at the farm one night and run riot. Shaun and Bitzer attempt to stop the aliens before The Farmer finds out.', '2007-09-13', 7, '/jgnM6kSJ3VW0PAqOA9zApZNs5eB.jpg', '2026-04-03T17:39:31Z', '2026-04-03T17:39:31Z');
