INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('4cdb257f-7eff-4061-a721-2f737865fa5a', '4d2cac0f-38fd-438b-8afa-acf43952e535', 110, 'Episode 110', 'A magazine programme for younger viewers.  Introduced by Leila Williams.  The last of three stories about  The House Under the Hill: 3: The Hillman and the Housewife and Six by Four: 1: The Baseboard.  A series in which Michael Humphries shows you how to make a better lay-out for your model railway.', '1960-11-21', NULL, NULL, '2026-04-03T17:21:47Z', '2026-04-03T17:21:47Z');
