INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('4ce0c545-64f6-4a11-a1f4-529be152ff4d', '1a534647-384b-4c00-bb6c-a3371ad962eb', 35, 'Expert Examinations', 'Take a look back at some of the finest expert examinations in the history of Pawn Stars: a rare edition Book of Mormon authenticated by Rebecca, a straitjacket possibly worn by Harry Houdini investigated by Murray, a signed Babe Ruth bat and glove inspected by Jeremy, and strategic plans from the Battle of Iwo Jima examined by the "Beard of Knowledge", Mark Hall-Patton.', '2015-06-04', 21, '/mkxfj6QFIWzndepvoZGlqdtuHYs.jpg', '2026-04-03T16:34:19Z', '2026-04-03T16:34:19Z');
