INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('4d2546ee-053c-485b-ada6-c94bac617045', '4091b13b-4db6-4857-ad22-20b5658c6b89', 5, 'Kiss My Peach', 'Dolores and David address their relationship while Jennifer''s relationship with her mother worsens. Melissa and Joe confront Michelle and Jon about the rumor they are spreading, and Teresa throws a wild pool party that ends badly.', '2021-03-17', 43, '/xbiQAAr5eutRw1ezuYyIlyfX7Zs.jpg', '2026-04-03T16:35:18Z', '2026-04-03T16:35:18Z');
