INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('4d6d9ea4-0b1c-451a-a0e7-afca722ad011', '353f8b38-d837-4354-88bd-d51e98a3421a', 2, 'DELETE ME', '', NULL, 5, NULL, '2026-04-03T17:24:26Z', '2026-04-03T17:24:26Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('4d7246f6-f4da-40b1-a445-81e9225416b8', '45e64a15-8fc0-4e4b-a1ca-9e3f42f3634d', 14, 'Structures', 'Are you tense? Need some structure to your life? Then tune in to Bill Nye the Science Guy as he   explains the science of structures.   All structures give support or create a shape. You can find structures everywhere. Bridges, buildings,   chairs, shoes, plants, spiderwebs, tables, and even your own body are all structures. A structure''s shape,   size, and what it''s made of depend on what the structure does and how strong it needs to be.   When structures give support, they either experience a pull (tension) or a push (compression). Structures   in tension, such as ropes, cables, or blimps are made from stuff that is good at pulling. The materials in   tension are usually thin. Structures under compression, such as elephant legs and courthouse columns,   are made from hard stiff stuff. Compared to structures under tension, structures under compression are   much thicker. When it comes to structures, form (the size and shape) depends on function (what it does).   Build support for Bill', '1993-12-10', 26, '/mlrSQ7yEP2IH5uSRWPWrUd5QXrm.jpg', '2026-04-03T17:37:20Z', '2026-04-03T17:37:20Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('4d7246f7-1431-42a0-b74a-447c8826465d', 'de052e8e-7dbd-454a-a6d8-b9afba6e9bfa', 10, 'Orinoco Sees The Light', 'Wellington has planted some daffodil seeds and he is "awfully disappinted" when they don''t grow. Orinoco suggests he plants light bulbs instead.', '1973-02-20', NULL, '/5fBALNIPtvgvEHE4440wvp9K2oz.jpg', '2026-04-03T17:23:19Z', '2026-04-03T17:23:19Z');
