INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('4da12299-5209-4afe-af56-d01ccc79b207', '53f9624f-fcf8-4f77-82f6-d2eb3f5376ee', 2, 'Let There Be Light', 'Janelle considers leaving Flagstaff for good as she and Maddie look at land in Montana. Kody learns that Meri is asking their church for a "release," their religion''s word for a divorce. Christine and Aspyn throw Ysabel a welcome home party.', '2024-09-22', 43, '/2sZKrG4NH4yTAIvA66v18Jwy2uO.jpg', '2026-04-03T16:34:33Z', '2026-04-03T16:34:33Z');
