INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('4e0b182b-f83c-4152-9cfd-df9e61979416', '9193e795-da7c-40ec-b68f-f63aa7d5174f', 287, 'Behind the Scenes: The Final Step', 'Discussing the Season 5 post-production', '2020-11-09', 26, NULL, '2026-04-03T15:40:35Z', '2026-04-03T15:40:35Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('4e101657-7502-4fd7-a4bc-2294e1e1f2ec', '3fc7c152-e4f6-426a-a899-36ec454c4403', 47, 'The Greatest Show in Dragon Land', 'The friends are excited to go to a new theme park called Wonder World, but they have to go through many obstacles to get there, despite Zak and Wheezie''s broken wing. However, when they finally reach Wonder World, everyone thinks this place isn’t Wonder World at all, since they think the obstacle rides were much more fun than the rides there.', '2000-01-20', NULL, NULL, '2026-04-03T15:26:03Z', '2026-04-03T15:26:03Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('4e130718-3319-436b-8ba3-957a8c7d6d3e', 'a4843a51-aeef-427c-902c-7fb3bd670cd4', 13, 'Music to My Ears', 'Ojo has formed an orchestra and has invited everyone in the Big Blue House to participate. Viewers are invited to participate too as Bear and the kids hold a concert out at the Otter Pond. Ojo is the orchestra "constructor," and Pip and Pop are using pot and pan lids for cymbals. As Bear searches for his kazoo, he comes across Treelo and asks for his help. When Treelo spots a radio, he turns it on and starts singing and dancing to music. He then goes off to create his own instrument. Bear finds his kazoo and also finds that Tutter wants to play the clarinet, but it''s too big for him. Bear helps Tutter to come up with another way to participate in the orchestra. In the Shadow segment, Shadow presents the tale of the cat and the fiddle. 

Songs 

Everywhere There''s Music 

Hey, We Can Play

Notes 

Tutter says that he received his clarinet from the Klutter Tutters. This performing musical trio consisted of his Auntie Klutter Tutter, cousin Skitter Tutter and Uncle Nutter Tutter.', '1997-11-05', 25, NULL, '2026-04-03T17:35:31Z', '2026-04-03T17:35:31Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('4e16fc5a-b656-4da0-817b-28b0cfb25a64', 'e606692a-47b7-411e-b54b-7c6bf61a67b7', 4, 'A Shower of Stars/Two Moons and One Lagoon', 'It''s nighttime at the library roof garden as Theo gives an energetic Leona a reread from the episode Shooting Stars. Then, under a full moon, Cleo gives Lionel and Leona a story from the episode Touching the Moon.', '2005-05-09', 30, '/5UonhiksNoxQaCOCxS6TS8bu459.jpg', '2026-04-03T17:12:29Z', '2026-04-03T17:12:29Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('4e186842-3dff-427a-ad01-285ecb6c3491', '32192008-7529-4677-933f-c55ea6146368', 4, 'Tropic Like It''s Hot', 'The ladies jet off to Nevis; Angel struggles to find her place in the group while Gizelle questions her and Stacey; Keiarna deals with the fallout of her feuds with Wendy and Jassi; Stacey claps back at Gizelle with swirling rumors of a tryst.', '2025-10-26', 54, '/mAaYfyVxuW59WYwnwGPz8AcNUOL.jpg', '2026-04-03T16:35:42Z', '2026-04-03T16:35:42Z');
