INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('4e5c5169-d351-455a-8edf-84e1ebc7ad7e', '1a534647-384b-4c00-bb6c-a3371ad962eb', 12, 'All Hail Rick', 'It''s a royal affair with the Pawn Stars when Revolutionary War documents signed by King George III reign into the shop. Will the documents be fit for a king, or a royal faux par? Then, Chum feels the need for speed when checking out a pair of Cushman Scooters. Will he drive a hard bargain, or be taken for a ride? And later, after checking out a BB gun in the shop, the guys all take part in a competitive shoot-out. Who will call the shots, and who will miss the mark?', '2015-02-26', 21, '/drHjiVzivKnb4xzcalwEKksR7Hd.jpg', '2026-04-03T16:34:19Z', '2026-04-03T16:34:19Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('4e634b15-9930-4950-a988-f26a134aedd6', '8bdf0ad3-a798-4d5a-b304-c7501eae6867', 2, 'Hold On To Your Daddies', 'Tamra Barney''s husband, Simon, has quit his job at the Mercedes dealership and is now working on his own business start up....from home. The couple''s McMansion is closing in on this housebound couple, so Tamra goes on a sexy shopping spree to spice things up. Meanwhile, Gretchen Rossi talks her fiancé, Jeff, into going motorcycle shopping at Harley Davidson. Even though the real estate market is in the dumps in Orange County, Jeana Keough still manages to make money by selling off the distressed properties of her friends. Lauri Peterson checks in on her daughter, Ashley, and learns all about the new skincare business that she is trying to launch. Vicki and Donn Gunvalson take time out from their busy lives to have a date night, but an evening of romance and reconnection turns into a bitter sparring match over their marriage. The ladies are unpleasant to new girl Gretchen during a day trip to Beverly Hills and the Sonya Dakar spa. Lauri ducks out early and starts to distance herself from the group.', '2008-12-02', 44, '/5qDPQpg3q6OMZ0eA9952xj2Dqoy.jpg', '2026-04-03T16:35:30Z', '2026-04-03T16:35:30Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('4e6396ec-18c5-4db1-b5eb-3cdc09f7bee2', 'bb360d44-75ef-4ac3-9d24-461c5c182502', 7, 'Walt''s Confession', 'The video confession recorded by Walt.', NULL, NULL, '/bLZHmsQfrLSsQTO7nCq0fjf7osq.jpg', '2026-04-03T15:40:32Z', '2026-04-03T15:40:32Z');
