INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('4ea8ad7f-1e44-45c4-acbc-abdddca1fc38', 'f4c40307-9b5e-4263-a4e0-dfa138131e7f', 22, 'Elmo''s World: Happy Holidays', 'In the first-ever "Elmo''s World" holiday special, Elmo is gearing up to celebrate Christmas. But what present will he give Dorothy, his beloved goldfish? As he searches for an answer, Elmo learns about holidays around the world and discovers the many things that Christmas, Chanukah and Kwanzaa have in common. Finally, Elmo goes to the North Pole, where Santa has some expert advice about the true spirit of Chirstmas - and the perfect gift for Dorothy!', '2002-09-24', NULL, NULL, '2026-04-03T17:36:27Z', '2026-04-03T17:36:27Z');
