INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('4f50dda5-0ce4-4121-9441-77cd9a7c8c00', '432a6abd-dcca-44cc-82ce-fb39e33b8949', 1, 'Episode 1 (#1131)', 'Episode 1131- The show opens with Mr. Rogers walking in, carrying several pieces of construction paper. Mary Sweenie and her daughter Meghan stop by and invite Mr. Rogers to come see them tomorrow. King Friday feels that babies are getting too much attention and on Prince Tuesday, he tries to limit such attention to one hour a day. Picture Picture shows us how construction paper is made.', '1971-02-15', 29, NULL, '2026-04-03T17:35:39Z', '2026-04-03T17:35:39Z');
