INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('4f5e2afd-eddb-4f9a-b512-83acc970fe02', '8012f05a-66a3-4254-885f-0a679393f3dd', 12, 'Attack of the Slime Monster (4)', 'The team trys to come up with a conclusion.  Tina and Casey discover the Slime Monster''s weakness, cold.  Just before the discover their plan, He attacks Lenni and the rest of the team!  Luckily, Tina escapes and Jamal and Tina melt the Slime Monster with vegtable oil.', '1995-02-12', NULL, NULL, '2026-04-03T17:40:28Z', '2026-04-03T17:40:28Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('4f62463f-ce2a-4f0d-aa95-02114dd261c7', '01b3a1e3-d0e8-4f2b-a56d-9d55669ab5f2', 9, 'The Teflon Queen', 'Kody faces off with his sons Gabe and Garrison, and they trade blame over COVID restrictions. Then, Janelle suffers a huge loss as Christmas is approaching. The family hopes they will all test negative and finally be together.', '2022-01-16', NULL, '/h8wdyI47AE6g9iWcYWB5H8yoIaM.jpg', '2026-04-03T16:34:32Z', '2026-04-03T16:34:32Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('4f68d7e3-ca19-4728-8562-e913c6d93a7c', 'f07b8794-5625-4682-aae1-e56966b4c7a8', 6, 'Yellow Belt', 'When Ben teases Jody that girls can’t learn martial arts, she quickly teaches him a lesson.', '1996-01-22', 29, NULL, '2026-04-03T17:12:21Z', '2026-04-03T17:12:21Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('4f6c64e9-70fe-42bd-b6e3-05b29165dff2', 'dbd3583f-e9b2-46d1-a37e-309eb666e233', 13, 'Make It Rain Down in Africa', 'The ladies'' South African vacation continues with the "Talls" and "Smalls" moving beyond Sheree and Marlo''s intense showdown. After blowing off some steam at a Cape Town nightclub, the women travel to the luxurious Shamwari game reserve. On safari, NeNe finds herself caught between the competing attention of Marlo and Cynthia, while Sheree, Phaedra, and Kandi learn about the pharmaceutical benefits of elephant dung. Later, the entire group has an opportunity to visit a South African orphanage, where they are touched by the children and leave with the sense that this trip has been a life-changing experience.', '2012-02-12', 43, '/pVGNudDR6fmvXFpqMrWccIw3bTO.jpg', '2026-04-03T16:34:45Z', '2026-04-03T16:34:45Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('4f7d5063-d81e-49c7-8c6c-ecc03c02f32c', 'dbd3583f-e9b2-46d1-a37e-309eb666e233', 9, 'Unlikely Duos', 'Phaedra’s ready to make her family funeral business a reality, but it’s going to take some convincing of Apollo that working with the dead isn’t as creepy as it sounds. Driven to write a hit song in every music genre, Kandi goes country and travels to Nashville to work with country music star Jo Dee Messina. Kim struggles with her oldest daughter Brielle, who begins acting up as she adjusts to life after Kim’s new baby. Seeking to put rumors to rest about her alleged tryst with a fellow Atlanta socialite’s boyfriend, NeNe meets with Marlo Hampton, and learns a lot more about her than she had expected.', '2012-01-08', 43, '/vXkRYqVFdYFDcmMwCqxjYcgmqx5.jpg', '2026-04-03T16:34:45Z', '2026-04-03T16:34:45Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('4f7fb228-93eb-4e21-9dca-71119c71d918', '151e88a1-9576-4bd1-b84a-c4d64c1c9fe8', 19, 'We Need To Talk About Kathy', 'When Kathy skips the flight home from Aspen, whispers surface about a meltdown directed at Kyle that took place the night before. Back in Beverly Hills, Erika tells Dorit she’s hurt that Garcelle talked behind her back and vows to say it to her face. Sutton and the others don flapper dresses for Crystal’s swank Roaring 20s birthday party. However, when Kathy arrives as if nothing is amiss, Lisa heads for the exit, and Erika decides to share what she heard.', '2022-09-21', NULL, '/824u09dMuTsu3iWltNSbadiyETQ.jpg', '2026-04-03T16:34:58Z', '2026-04-03T16:34:58Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('4f83c3ae-5ca5-4f96-9802-c776a96d7361', 'cb8a0322-be77-485b-b339-bdd572bca349', 9, 'The Chips Are Down', 'D.W. eats a big green potato chip and to get her off his back Arthur tells her that it''s fatal and she could die. So D.W. spends this day as her last day until she finds out the truth.', '1998-11-20', 13, NULL, '2026-04-03T17:37:56Z', '2026-04-03T17:37:56Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('4f86f21b-875f-4f09-821a-75973ac64b45', '9e4790f4-3aab-459c-a5ed-7100b4e39a75', 14, 'Connecticut-ing the Dots', 'Brynn celebrates her birthday and the masks come off as friendships and state lines are crossed.', '2023-10-15', NULL, '/foY2EYRlgcV4zQJ9gGSyX1EbDw5.jpg', '2026-04-03T16:35:26Z', '2026-04-03T16:35:26Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('4f8d8df2-16a5-401f-aa26-2a245a71cc56', 'd123fd65-efb7-4ebb-a23e-190c447791cf', 14, 'Reunion Part 2', 'As the reunion concludes, Alexia revisits all of her traumatizing trials and tribulations throughout the season; Lisa comes to terms with her marriage; Adriana and Larsa go head-to-head over a certain someone''s penis.', '2022-03-10', 44, '/pvy3kZtaLMY0hVMDsNUTGxAN8XG.jpg', '2026-04-03T16:35:11Z', '2026-04-03T16:35:11Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('4f939da9-683a-4891-9d1f-24c103507115', '3190d082-877d-4951-bf7c-ed07ef560040', 2, 'Bugs', 'With microorganisms under his belt, LeVar now goes on the lookout for insects.', '1988-08-16', 30, NULL, '2026-04-03T17:36:16Z', '2026-04-03T17:36:16Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('4f965f6e-8d6c-4207-bc5c-cf7541c6b926', '6fd9fd9d-e378-411b-94b1-76ba4bd518fe', 71, 'Episode 71', 'with Christopher Trace, Valerie Singleton and John Noakes.', '1966-05-26', NULL, NULL, '2026-04-03T17:21:48Z', '2026-04-03T17:21:48Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('4f979f7d-6f4a-4461-88ca-865c263b87fd', '97a3d1f5-a8f1-47cd-8122-2e74a092836d', 15, 'Lost in Brooklyn (3)', 'Malenga finds one of the paintings and realizes that Safria is in New York. Jamal runs into his best friend Rob. Rob arrives at Lenni''s house but he has some terrible news. His mom just got a new job in Australia and he just returned to get ready to go. Malenga contacts the team. Malenga and Tina arrive at the hotel. Tina prays for Safria to be all right.', '1993-12-12', NULL, NULL, '2026-04-03T17:40:28Z', '2026-04-03T17:40:28Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('4f97c5c6-ed1e-4a10-9414-54777bd308e1', 'db958af4-9a9a-4533-af9b-f0ff590d1dd9', 4, 'Housewarming History Lesson', 'After the guys night blowout, the divide between Teresa, Joe and Melissa is at a standstill; Frankie hits Dolores with hard questions about their shifting family dynamic; Rachel and Jen Fessler spill the tea on Jennifer Aydin.', '2023-02-28', 44, '/oRj8WDhI9QAHdq0kQur3jGIVxtl.jpg', '2026-04-03T16:35:19Z', '2026-04-03T16:35:19Z');
