INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('4ffbfba0-8621-474b-b0bd-4b3daf18955a', '3fc7c152-e4f6-426a-a899-36ec454c4403', 17, 'Emmy''s Dream House', 'A Purple Goo Cloud is going to rain all over Dragon Land, so everyone builds a tree house to shelter. However, Emmy becomes bossy and wants everything to be done her own way, until she learns how to share with her friends and give them what they want.', '1999-09-23', 30, '/vGIBEiVVdLRPVe8qS81E5ATEqsR.jpg', '2026-04-03T15:26:03Z', '2026-04-03T15:26:03Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('4ffe088b-a903-4a80-8ecf-56147694ca3e', 'a2edcb57-63c1-4028-b87b-7faeae2c999b', 6, 'First Place', 'Bernard tries to use his watch to win sports day but is his family worth the risk?', '2004-02-10', 15, NULL, '2026-04-03T17:20:06Z', '2026-04-03T17:20:06Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('50001f44-fe9f-41bb-bc08-10d8a5c29824', 'd6092173-d23b-4449-baff-e0e16fe56c9a', 3, 'Ten Ten, Twenty Twenty', 'Porsha returns home from her second arrest in Kentucky and also reveals that she and Dennis have called it quits. Kenya offers Cynthia marital advice and juggles her fast track friendship with LaToya. Drew and Ralph agree to go to marriage counseling, while Cynthia and Mike disagree over when to host their dream wedding.', '2020-12-20', 43, '/gzCOccENsLDxyJXLK3HdVV54QQT.jpg', '2026-04-03T16:34:49Z', '2026-04-03T16:34:49Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('5006198c-61a4-4890-af09-9070e61ad69d', '5c4e51c6-e207-46ad-875c-72988eb1e13e', 1, 'Evel Genius', 'Batter up with the Pawn Stars when an autographed photo of Babe Ruth slides into the shop. Will Rick go into extra innings for this rare piece of baseball memorabilia or will a tough negotiation cause him to swing and miss? Then, the guys take a peek at a collection of 400 antique prosthetic glass eyeballs. Made from hand-blown glass, will they see eye-to-eye on this deal or will this collection have to stare down a new buyer? And later, Corey and Chumlee are presented with a classic 1970''s Evel Knievel pinball machine. Broken and beat up, will Corey rev up a death-defying leap to restore this cool rider collectable or will one look have him say "Game Over"?', '2011-04-04', 21, '/ccIbTcybZYh2QedX6EHiJ8DGNAE.jpg', '2026-04-03T16:34:16Z', '2026-04-03T16:34:16Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('5009aa52-eebd-41a1-b1d8-286f4f1b164d', '4d2cac0f-38fd-438b-8afa-acf43952e535', 255, 'Episode 255', 'Christopher Trace and Valerie Singleton introduce a magazine programme for younger viewers. Including Bengo Paints a Picture by Tim, told by Tim Gudgin.', '1963-11-11', NULL, NULL, '2026-04-03T17:21:47Z', '2026-04-03T17:21:47Z');
