INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('500ff490-12bb-4433-8a77-e8dc13946437', 'cc140989-c480-4586-b460-8872b416a0b7', 9, 'Bored-Nothing to Do!', 'Focusing on planes in this episode, LeVar takes a flying lesson and flies a plane himself. Also included: the activities of a top-notch airline in flight, as well as a look at the people who made the dream of flying come true, like Amelia Earhart and Charles Lindburgh. Alex Borg and David Hyman read the story of two boys who decide to build their own airplane, using household items, after their mother sends them outside to play when they complain of being bored.', '1990-03-29', 30, NULL, '2026-04-03T17:36:17Z', '2026-04-03T17:36:17Z');
