INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('501ce749-8858-413b-bcea-6573ae950fc3', '4fe93658-c463-4329-8e64-9d523869c2cb', 13, 'Never Surrender', 'The Pawn Stars are presented with a letter signed by one of the 20th century''s greatest leaders, Winston Churchill. Will the guys stand up and fight for a deal or will unverified signature force them to surrender? Then, Rick and the Old Man meet a guy hoping to sell a Holy Relic from the first American Saint Elizabeth Seton. Will this precious religious item bring the guys good fortune or will the Old Man remain the only relic in the shop? And later, a man brings in a gas fueled remote controlled toy Hummer with some mechanical problems. Will they take a chance at rewiring this RC truck to make a buck or will this deal run out of batteries?', '2010-11-01', 21, '/fELnnVu0zUVB5ppG1cyZsCZhJrJ.jpg', '2026-04-03T16:34:16Z', '2026-04-03T16:34:16Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('501deb3e-381e-4c7e-bf0d-00c23aa302f8', '83d04769-45b3-4d29-af02-590315104997', 7, 'Phuket Me Not', 'As the women near the end of their less-than-relaxing vacation, Gizelle makes a final push to find the tequila thief; too much time together pushes the Miami dynamic duo to their breaking point.', '2023-04-20', 52, '/1F2W9s83pd9YelcKuIaVgISXCtz.jpg', '2026-04-03T16:34:41Z', '2026-04-03T16:34:41Z');
