INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('5055fda3-830b-4e9a-adce-a7005747f6bc', '3ade5e1f-8441-4c2c-acf6-fb933a61dcfa', 21, 'Reunion (3)', 'The husbands take center stage for the dramatic conclusion to the Season 4 three-part reunion. The couples reveal their secrets in the bedroom, but the fun and games end there when the topic shifts to the charges against Michael. The women reveal secrets about Michael from seasons past. Chris Bassett and Ray chime in with new information that steers the conversation onto an unexpected course.', '2019-09-29', 42, '/8rY4ttc1aAGcq8rhI4HlTfenYwp.jpg', '2026-04-03T16:35:39Z', '2026-04-03T16:35:39Z');
