INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('506b3772-81d5-4d92-93a4-5034aaf779c0', '20d7138e-eea8-46a8-8ada-2b0f0ee1f674', 68, 'Episode 68', 'Janet''s fifth Blue Peter programme sees her transform a shoe box into a four-poster bed. Simon and Peter fight wizards and ores in the dungeons of a Cheshire castle.', '1983-05-16', NULL, NULL, '2026-04-03T17:21:56Z', '2026-04-03T17:21:56Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('506bbcf8-abaa-40f0-9837-6c7fa3536f2b', '095258d0-d8db-4096-8ac7-6a42cd4cbdcf', 3, 'Boober And The Glob', 'It''s Joke Day in Fraggle Rock, and Boober''s trying to get out before his friends find him and make him participate in the holiday he hates. But before he leaves, a huge purplish-pink glob rolls into the Great Hall. Boober ends up meeting Cotterpin Doozer as well, and the Doozers are on their way to start building near the Blob. However, the Glob starts to eat the Doozers, one by one, and soon enough, Cotterpin''s inside the Glob too. Even though a part of Boober really just wants to run away and pretend it isn''t happening, he''s forced into action and must find a way to set the Doozers free.', '1985-01-14', 24, '/wOzVOWhfv90r9XphcVp4Fyocx9m.jpg', '2026-04-03T17:35:00Z', '2026-04-03T17:35:00Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('506d4fa6-4ef5-421a-b16a-79d7256b0a72', 'ebc99729-ccb7-4d64-82c1-42708cd7ba85', 69, 'Episode 69', '', '1981-05-14', NULL, NULL, '2026-04-03T17:21:55Z', '2026-04-03T17:21:55Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('506fce88-6f9e-4faf-99ed-b678c291a942', '208e80de-61e3-4a2f-857f-c667ffc29134', 23, 'Carol Channing', 'Miss Piggy buys a cute new pair of shoes, but they''re too small, and she can''t walk in them. She wants to take them back, but Kermit compliments them, so she has to keep wearing them. She complains to Carol, who says she should have them stretched, and gives them to the gigantic Timmy Monster, who runs around the block in them.', '1980-03-28', 26, '/uEisEgcu4UDaZw5u7ak6PJNFMdX.jpg', '2026-04-03T17:35:25Z', '2026-04-03T17:35:25Z');
