INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('507ab77c-72c0-4660-8877-412efb4d4279', '5b2c9365-7bd9-4ca1-a3fb-15f1a024a56e', 2, 'The Hamptons', 'As Jill and Allyson journey to a plush health center on Martha''s Vineyard, Ramona gears up for a Hamptons-based fashion show and LuAnn''s daughter participates in an elite equestrian competition. Meanwhile, Ramona serves up a cooking party, but things turn testy when one housewife isn''t invited.', '2008-03-11', 60, '/bWxiQEVBMWemzfrIShMZObIMZU9.jpg', '2026-04-03T16:35:21Z', '2026-04-03T16:35:21Z');
