INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('508bc4dc-539a-48bc-b740-aa9cab5f4c98', '7bc54df3-f32a-454e-aef6-a9436c35d53b', 65, 'Episode 65', 'Rogers and Chef Brockett play games in which one doesn''t see, but hears or feels.', '1970-05-01', NULL, NULL, '2026-04-03T17:35:39Z', '2026-04-03T17:35:39Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('508fb0e6-c47d-4eb9-90fd-6f52f5882b0a', 'ca19f895-1514-4988-a709-95e84eab7cee', 17, 'Atomic Pawn', 'Chum goes for a hole-in-one when a signed Jack Nicklaus golf glove swings into the shop. Meanwhile, Corey targets a G.I. Joe Tomahawk helicopter toy. Will he get to be a real American hero, or will this deal go AWOL? Next, an antique Fender amp rocks Chum''s world. Will the price be music to his ear, or off key? And later, Rick and Spencer go on a picking adventure in Huntington Beach, California. When they find a treasure trove of military items, does Rick have enough ammunition to close the deal?', '2021-05-10', 42, '/yHVggrETWBHduPyT0ZdjbEux7L0.jpg', '2026-04-03T16:34:22Z', '2026-04-03T16:34:22Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('5095173f-9ace-47d9-9de5-df788dc2d3ce', '89ba90ec-2c79-4a12-a11d-7465d1757683', 16, 'Rick and Morty The Non-Canonical Adventures: Ghostbusters', 'A claymation recreation of a classic scene from ‘Ghostbusters’.', '2017-07-30', 1, '/pr7TFyO81lS1wP3diPbmCPbhqDF.jpg', '2026-04-03T15:40:41Z', '2026-04-03T15:40:41Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('509640fe-db5f-4c87-84e0-dad192024645', '5ff41814-d526-460e-9bf2-4945df6efab2', 8, 'The Hobbit, part 8 - Fire and Water', '', '1979-10-10', 15, NULL, '2026-04-03T17:20:12Z', '2026-04-03T17:20:12Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('5097f247-503b-4744-8d33-3750275f6b5d', 'd9973960-273b-4a92-a7da-62efe8860d09', 13, 'Chilly Reception', 'Heather works hard to finish her new Beauty Lab location for her launch party, but worries that she hasn’t connected with Jen since Vegas. Mary goes to her place of peace, her church choir, while Lisa spends time with her family doing what she truly loves – making business plans. Meredith and Seth realize that their marriage is a hot topic for their friends while Sharrieff surprises Jen with a date night she won’t forget. And at the At theBeauty Lab Launch Party, Jen tries to make amends with her friends but it doesn’t go as well as she planned.', '2021-02-03', 63, '/qPbM1x4fDbHkCIvlBYLMdamrbJJ.jpg', '2026-04-03T16:35:44Z', '2026-04-03T16:35:44Z');
