INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('5137c4e5-8487-4773-aac7-4b9f2328140f', '5a771f52-fe96-4ea2-b567-a8dde899059e', 18, 'The Happiest Place to Pawn', 'Rick and Corey are inspired by an anti-war speech signed by Dr. Martin Luther King. Will they "sit in" or sit this one out? A remote-controlled miniature version of a boat from Disney''s Jungle Cruise ride has Rick and Chum navigating a tough deal. Rick pins his hopes on a German "Blue Max" medal from WWI, but can he honor the seller''s high asking price? Later, in an interesting development, an antique Nikon camera from the 1950s makes a flashy appearance. Will Chum snap it up or shutter himself off?', '2018-02-05', 21, '/vWnd2ILKNWnA11hmOayLyksLjEu.jpg', '2026-04-03T16:34:21Z', '2026-04-03T16:34:21Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('513871bc-b487-4fdc-a90e-79a237fa42d9', 'ceb4c48c-6260-40df-a265-c9fbfa7885f9', 10, 'The Lost Dinosaur', 'Bud loses his imaginary friend Rapty, a dinosaur, and becomes worried what he''ll do without him.', '2018-02-14', 13, NULL, '2026-04-03T17:38:02Z', '2026-04-03T17:38:02Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('513a6c4e-2a8f-4da1-b99e-3e83e3c7e179', '3a8f72dc-7df9-4f84-957f-bf4a0a1f9594', 1, 'Episode 1', '', '1988-01-05', 25, NULL, '2026-04-03T17:21:15Z', '2026-04-03T17:21:15Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('513d578e-0347-465f-bc36-b52d151b8378', 'c7994637-b7c7-42c7-aaee-1bff4144fe23', 7, 'Dazed and Accused', 'As the weed dinner continues, Kyle and Sutton’s friendship seems to go up in smoke. Garcelle and Crystal struggle to make sense of Denise’s showdown with Erika. Dorit schools PK on their children’s future. Feeling let down by her friends, Kyle turns to sister Kim for support and advice about her family.', '2023-12-06', NULL, '/a0TN2tm1h3STJ4ExHrFI9CEBC7M.jpg', '2026-04-03T16:34:59Z', '2026-04-03T16:34:59Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('51418f2e-b746-4caa-8c3e-6e4babc82a95', 'a4843a51-aeef-427c-902c-7fb3bd670cd4', 24, 'Lost Thing', 'Bear hears a shout coming from the kitchen and finds Ojo begging Tutter to let her peek inside his mousehole. When he won''t let her, saying that she''s too big, she cries. It turns out that she''s lost her favorite toy, Snowbear. Not wanting to see her cry, Tutter agrees to help her find it --- mice are great at finding things. Pip and Pop soon join the hunt, but Bear''s bedroom gets rather messed up in the process. Ojo begins to despair, but Bear helps ro raise her spirits by encouraging her to keep up the hunt. Treelo then comes up with a great idea that could help her to find Snowbear. 

In the Shadow segment, Shadow tells the story of the "Three Little Kittens" --- the ones that lost their mittens. 

Songs 

Lost Thing 

Snow Bear Where Can You Be 

Notes 

This episode was adapted in storybook form as Lost and Found.', '1997-11-20', 25, NULL, '2026-04-03T17:35:31Z', '2026-04-03T17:35:31Z');
