INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('51639978-f68a-42b4-a8e3-209dcf1e1cf0', '06030129-ff2d-4490-b66c-9f41bbe7aabd', 14, 'Shopping', 'John sets out to the shops to buy some food and drink for a picnic. Rosie and Jim are hungry and want to have a picnic too, so they add their own items to John''s shopping list without him knowing. Bearing in mind that John doesn''t even like the items that Rosie and Jim added, they''re afraid that John is going to be upset. However, John isn''t overly upset after all, as he sees a family having a barbecue and gives them Rosie and Jim''s items.', '1990-12-03', 15, NULL, '2026-04-03T17:19:36Z', '2026-04-03T17:19:36Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('516a6538-34ad-42e9-b2e3-63c8414d39c0', 'efdf1e4f-8476-4382-a9d7-2b9da4188be0', 17, 'Brave and Strong', 'Rogers'' friend Brad Brewer, a knitter and puppeteer, talks of the puppets and puppet shows he has performed in. In the Neighborhood of Make-Believe, Elsie Jean Platypus explains that the cereal stopped falling on the Platypus Mound when she wasn''t afraid of it. But Daniel is afraid of the cereal snowfall on his Clock. And Then Maggie Stewart Shows A Videotape On How People Make Grits', '1996-08-02', NULL, NULL, '2026-04-03T17:35:47Z', '2026-04-03T17:35:47Z');
