INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('518b0d16-7bd8-4475-aba0-ee7401436297', 'd0b78f22-678e-4e46-9d61-aac40ba206b8', 16, 'Meet Rinna Jayne', 'Lisa Rinna, Kyle, Teddi, and Dorit discover an article that exposes Camille''s duplicity; while planning a Halloween bash, Kyle faces her worst fear; Dorit and Teddi battle the urge to confront Camille; Lisa Rinna makes a move that shocks everyone.', '2019-05-28', 44, '/tdf94RcUnnCDeGxr50raXsyBWdR.jpg', '2026-04-03T16:34:57Z', '2026-04-03T16:34:57Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('518ce058-daea-47cf-8f5e-68a14f970e06', '1a8f02c5-f727-4ce3-9bb2-5946d236e47c', 6, 'Chapter Six: Escape from Camazotz', 'As Holly and Max fight to escape Vecna''s mind, El must find a way into Will''s. Joyce wrestles with guilt. Jonathan and Nancy face a turning point.', '2025-12-25', 76, '/zwJuStMjSOT1jaPUkX3dweIciRs.jpg', '2026-04-03T15:40:40Z', '2026-04-03T15:40:40Z');
