INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('51922a1f-7f47-4197-9867-5683439da53c', '33319c06-a2b0-43bf-8694-b3e8e37e49e9', 23, 'Tailor', '', '1997-03-21', 10, NULL, '2026-04-03T17:19:38Z', '2026-04-03T17:19:38Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('519701ae-1414-4376-9eb6-603447031e6b', 'ae8f64d9-4b83-4147-a44c-bfe720381f8e', 25, 'Jacks Grows His Own Beanstalk', 'Jack from Jack and the Beanstalk comes to Sesame Street and tells Leela and Telly he has a problem. He only has a cow, but he needs a beanstalk! He knows he’s supposed to trade the cow for something but doesn’t know what. Leela gives him a clue—he needs to find something that grows in the ground.

Jack quickly returns with a duck. But ducks don’t grow in the ground! Leela gives Jack another clue—to find something that rhymes with “jeans.” Jack comes back with a tambourine in each hand. “Tambourine” rhymes with “jeans” but tambourines don’t grow in the ground. They’re musical instruments. Jack becomes discouraged and is convinced he is never going to be able to grow a beanstalk.

Leela gives him one more clue—he needs to look for something little. He trades the cow in and comes back with a handful of beans. They match all the clues—beans grow in the ground, rhyme with jeans, and they are little. Hooray! Jack found something that turns into a beanstalk. Leela shows Jack how to plant the beans in the garden. She covers the beans with soil, waters the beans, and lets the sun shine down. Suddenly, a huge beanstalk shoots up out of the ground. Telly, Leela, and Jack sing about the greatest green beanstalk that ever grew!', '2010-02-16', NULL, '/nNZrZqn9tCUJhk1AvuIHiaW3gmV.jpg', '2026-04-03T17:36:46Z', '2026-04-03T17:36:46Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('519747c0-52a1-4215-ba0b-926977a9def3', '1cafb2c3-bbcb-4172-b02d-441a5aaa155f', 15, 'Little and Big: A Visit with Architect Maya Lin', 'Rogers visits the studio apartment of an innovative architect. She explains how an appreciation of the earth inspired her to design certain tables, seats, and couches. Cornflake S. Pecially improves King Friday''s mood with a "Royal Automated Yo-Yo". Further reason to repeal the "no yo-yos" rule comes from a videotape of Yo-Yo Ma.', '1998-08-17', NULL, NULL, '2026-04-03T17:35:48Z', '2026-04-03T17:35:48Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('51996fb9-800e-435c-a987-12f8d0125701', '495d4222-b33a-46fa-8351-3265798e558b', 12, 'Without My Pants', 'Ben Byron died trying to save his drowning dog, Shovel. It''s when the ghost of Shovel zaps Pete that the hilarious trouble begins. Pete can''t say anything with out finishing his sentance with ""without my pants"" which causes him quite a bit of trouble.', '1990-06-29', 24, '/phDvOf7GHnxKZMgiGEH85N8pDMW.jpg', '2026-04-03T17:40:40Z', '2026-04-03T17:40:40Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('519bc956-9bf8-48b4-89c9-e52cf664831b', '2f8dd629-82c3-4f8e-87c0-963473c49284', 13, 'Dinner Disasters and Breakfast Breakdowns', 'Brynn and Erin confront Jessel about the way she''s changed; an argument between Ubah and Brynn ends dinner on a dramatic note; a comment from Ubah causes Erin to break down in tears; a trip to the beach leads to harsh critiques.', '2025-01-07', 43, NULL, '2026-04-03T16:35:26Z', '2026-04-03T16:35:26Z');
