INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('51c64785-089f-4a5f-8941-557a404d865f', '40700e8a-1dce-4895-bede-522a13a8bcad', 5, 'Humans', 'Zoboo is curious about what it''s like to be human and a whole class of kindergarten kids arrives in Animal Junction to help him out. There are a few differences, but Zoboo discovers that children and lemurs are a lot alike.', '2000-10-30', 27, NULL, '2026-04-03T17:10:55Z', '2026-04-03T17:10:55Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('51c86ae3-3651-4d02-9586-922eed38cde3', '2f5a4ffe-2548-4181-85ac-6145cb3e3bf7', 9, 'Kody''s Secret Plan', 'The Sister Wives announce to the kids that they''ve bought land in Flagstaff, AZ, and they plan to move there within a month. Aspyn asks what void are they trying to fill by moving? And Kody secretly has plans drawn up for one giant polygamist house.', '2019-03-24', NULL, NULL, '2026-04-03T16:34:31Z', '2026-04-03T16:34:31Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('51c9a36a-3400-4824-ad85-61ce067808b4', '84ce360a-90d1-4fc0-be06-33bdcbe8e60a', 5, 'Looking After Arnold', 'Kipper is looking after Arnold, who pig has assured him is very tired and won''t be any trouble at all. Kipper makes Arnold a house under the table, reads to him and turns a cardboard box into a railway engine. By the time Pig returns it''s Kipper who can''t keep his eyes open.', '1999-10-21', 8, NULL, '2026-04-03T17:10:49Z', '2026-04-03T17:10:49Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('51cd0e08-41d9-42f1-ba4a-05c029b2253d', 'ea73e13c-6962-4804-8305-c303df65f89f', 65, 'Cooling off in a pool', 'Queen Sara gives a lesson to Lady Aberlin and King Friday about understanding Robert Troll''s troll talk.', '1969-05-09', NULL, NULL, '2026-04-03T17:35:38Z', '2026-04-03T17:35:38Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('51d1ef39-40c7-49b8-b8a9-89de6b97bd13', '543ec6dc-c6c7-447c-b5a7-4484d9618391', 4, 'The Grape Stomp of Wrath', 'Cat feels that there''s more than everyone else sees with Michaele and Tareq. Lynda handles with the stress of relocation from her Georgetown condo to a huge suburban mansion to fit the needs of her grown children. Michaele wants to make things right with the rest of the ladies, so she invites them over to her winery for a grape stomp session.', '2010-08-26', NULL, NULL, '2026-04-03T16:35:01Z', '2026-04-03T16:35:01Z');
