INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('51d45e51-b37e-4d1b-9ed3-d1645ce088ba', '9193e795-da7c-40ec-b68f-f63aa7d5174f', 280, 'The Last Season: Duty is the Death of Love', 'Look at how the team behind Game of Thrones brought the Emmy-winning series to its conclusion in the series finale, "The Iron Throne."  Interviews include show runners David Benioff and D.B. Weiss, along with all of the major stars, including Kit Harington, Peter Dinklage, Emilia Clarke and more.', '2019-12-09', 32, '/zvJyDhtzwvbRkP3X95z9errxn7X.jpg', '2026-04-03T15:40:35Z', '2026-04-03T15:40:35Z');
