INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('5261d5b0-db0f-4119-be2e-8c6226d42503', '4d504e48-9b03-47a1-98ce-be9ad8bcb6c8', 7, 'Man I Feel Like a Pawn Star!', 'Chum goes bananas when a seller brings in vintage toys from the Planet of the Apes franchise. Will Chum “ape”-reciate the seller’s offer, or will he monkey around for a better deal?', '2026-02-25', 41, NULL, '2026-04-03T16:34:25Z', '2026-04-03T16:34:25Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('526413cc-6cd2-480f-9fdf-6022bad2b223', '6920e4b0-8f6c-46f2-86e0-48cdee5f6089', 9, 'Pride', 'Small Clanger finds a mirror, and vanity almost costs him his supper.', '1971-06-13', 9, '/cxjOeX3JWDlfXcZjcKdreDeYjoI.jpg', '2026-04-03T17:23:53Z', '2026-04-03T17:23:53Z');
