INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('52dcd9f5-5646-4f59-842e-ba0ff22d6851', '05c0e384-194c-4417-9f62-803eb615e409', 92, 'A production of “Rumpelstiltskin”', 'Rogers and Mr. McFeely take care of two ducks that have wandered onto the porch before seeing the Vagabond Marionettes'' production of Rumpelstiltskin.', '1968-06-25', NULL, NULL, '2026-04-03T17:35:38Z', '2026-04-03T17:35:38Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('52f4c2ee-5600-43f3-82bf-351921f85da9', '42253cb1-e961-4018-8dd9-8a69e6f70873', 29, 'Episode 2254', '', NULL, NULL, NULL, '2026-04-03T17:36:37Z', '2026-04-03T17:36:37Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('52f6e178-989a-42d0-a069-7bf69468cba5', '227b8429-0dfd-47e4-b874-c37da20c403f', 19, 'Hot Air Buffoon', 'The pawn shop heats up after Corey spends big bucks buying a huge 12 passenger hot air balloon - and at the same time breaking one of Rick''s golden rules. Will Corey rise to the occasion and patch up the deal or will his dicey decision deflate the shop''s profits? Then, when a man tries to sell his classic 1960 Gibson Les Paul guitar, Rick has some concerns: will the deal rock on or rock on out? And later, a man brings in a bottle of medicinal whiskey from Prohibition and the Old Man is forced to decide: Buy it, deny it, or drink it?', '2009-12-14', 21, '/cGdMDJHNYwLc0GTinpMAgk73ZP2.jpg', '2026-04-03T16:34:15Z', '2026-04-03T16:34:15Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('52fdcab6-a51f-4f42-ae32-bd26e25a213a', '8012f05a-66a3-4254-885f-0a679393f3dd', 7, 'Four Days of the Cockatoo (3)', 'Hector and Lenni are able to warn Alex and Gaby about the smugglers the retreat back to Lenni''s apartment. Jamal and Tina learn that Palm Cockatoos are endangered species,so the team tries to contact the police but it doesn''t work so they contact the fish and wild life service, an animal rights society. They tell Mr. Fernandez that they won''t give the bird to anyone except the fish and wild life people. Hawke, disguised as a pregnant woman overhears them and has a new idea. Just then two agents from the wild life society arrive at the bodega but Gaby reads a message from Ghostwriter and realizes that they are imposters, but when she goes to save Calypso the van takes off with her inside.', '1994-11-13', NULL, NULL, '2026-04-03T17:40:28Z', '2026-04-03T17:40:28Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('52fe05c0-4391-4c76-8d95-e2df424ba13c', '68138de2-0900-460a-b58e-480688f1e081', 10, 'It''s All In Your Head', 'Ojo gets the idea to put on some Olympics games out by the pond. Everyone''s excited, especially Tutter, who predicts that he¡¦s going to win every event. He doesn''t, he realizes that you don''t have to be good at everything to be a winner, but when the limbo competition rolls around K it turns out nobody can get lover than a mouse!', NULL, 25, NULL, '2026-04-03T17:35:31Z', '2026-04-03T17:35:31Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('53006ee4-ff82-4bdc-be67-1cfd699189c8', 'd405f973-4c7e-4cb6-b7c0-d09a884c9b35', 2, 'March Madness', 'The ladies participate in a marriage-equality march over the Brooklyn Bridge, yet there''s drama with these mamas when tension heats up between Sonja and Alex. Elsewhere, an offensive remark delivered by Ramona spreads back to Cindy.', '2011-04-14', 42, '/PNnhzGNOfUcee5RmuA0FooqRC8.jpg', '2026-04-03T16:35:22Z', '2026-04-03T16:35:22Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('53078caf-6837-4584-9596-886aa7ffd57d', '4da606e7-9d23-4682-8bd5-f535e1da706f', 11, 'Franklin''s Family Treasure', 'Mr. Turtle gives Franklin a whistle.  Without realizing it''s value, Franklin traded it away until his Granny told him where the whistle originates from.  Franklin and his Granny desperately tracks down who has the whistle.', '1998-10-12', 12, NULL, '2026-04-03T17:40:15Z', '2026-04-03T17:40:15Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('530bbb3d-14d2-4225-a1b8-c0b0befbf913', '6fd9fd9d-e378-411b-94b1-76ba4bd518fe', 41, 'Episode 41', 'with Christopher Trace, Valerie Singleton and John Noakes.', '1966-02-10', NULL, NULL, '2026-04-03T17:21:48Z', '2026-04-03T17:21:48Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('5311fce8-95d1-4dc3-9ae9-64a95577b922', '23c93536-610c-41c5-ac6b-a6b243423258', 4, 'Bunking Beds and Butting Heads', 'The ladies arrive in Lake Norman, N.C., to turn up, but some aren''t ready for the heat that''s unleashed. Jacqueline''s relationship with Mia is questioned. Stacey and Keiarna both have bones to pick with Ashley. Mia reveals a long-held alleged secret about Karen, leaving everyone shocked.', '2024-10-27', 43, NULL, '2026-04-03T16:35:41Z', '2026-04-03T16:35:41Z');
