INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('5375e85a-57bd-4f95-a4c9-c0db01b894f0', '70c8cb46-2494-4dd4-98f6-6bfb9b3faf73', 23, 'Top Secret', 'The Pawn Stars look to purchase top-secret maps and battle plans for Iwo Jima. Will the gang storm the beach for this strategic piece of World War II history or will they be out-gunned and forced to retreat? Then the Old Man and Chumlee look to buy a 1967 Ford F-100 truck. Will they fire up all cylinders and hit the deal full throttle or will it run out of gas? And later, Corey and Chumlee have a chance to buy an 1860''s ore cart from the mines of Goldfield, Nevada. Will they strike it rich or fall off the tracks?', '2010-06-07', 21, '/ynJgGqwAiD1FapBnjUtUaAgDjm.jpg', '2026-04-03T16:34:16Z', '2026-04-03T16:34:16Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('537cb02c-5923-47df-8d83-4ba924125170', '4da606e7-9d23-4682-8bd5-f535e1da706f', 6, 'Franklin''s Library Book', 'Franklin receives his first library card and takes out his first library book. He was so excited with this new responbility. Unfortunately, he left his library book out in the rain and tries to hide the damaged book.', '1998-09-21', 12, NULL, '2026-04-03T17:40:15Z', '2026-04-03T17:40:15Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('537de790-e900-4939-9a78-c772f20b80fa', 'ae373811-cd7f-4e4c-bf5f-6e5eef167f8d', 6, 'The Great American Melting Pot', 'A look at the Democratic recipe that built America.', '1976-04-17', 3, '/lJu2g8gtY1bpRIf2OF5TXCmdkEI.jpg', '2026-04-03T17:13:56Z', '2026-04-03T17:13:56Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('538299bb-5496-4c8c-b527-ee6b88e0442a', 'f4c40307-9b5e-4263-a4e0-dfa138131e7f', 21, 'Learning About Letters', 'Big Bird and Telly Monster lead young viewers through the alphabet, letter by letter, in a magical and imaginative half-hour discovery of letters and their sounds. The perfect tape for young Sesame Street fans who are just beginning to get the hang of what letters are all about, it includes short skits, songs, and other bits of business--some original, some culled from the Sesame Street show--featuring a variety of Muppet characters as well as the human residents of that famously educational thoroughfare.', NULL, NULL, NULL, '2026-04-03T17:36:27Z', '2026-04-03T17:36:27Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('538aa6eb-70ae-4f76-9810-9ea84928d66f', 'bddd6427-4f85-402c-b58c-5c18ab159704', 86, 'Episode 881', '', '1976-03-29', NULL, NULL, '2026-04-03T17:36:31Z', '2026-04-03T17:36:31Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('5395a996-a729-4192-9398-e7f77f042131', 'f07b8794-5625-4682-aae1-e56966b4c7a8', 5, 'Helping Hands', 'Kiki decides to prune a big tree by herself and becomes exasperated when she discovers that the job is too much for her to do alone. She learns that it’s okay to ask for help when you need it. Nuzzle obtains a motorcycle and Sizzle so badly wants to try it herself. Julie, Ben, and Leon do not appear in this episode.', '1996-01-19', 29, NULL, '2026-04-03T17:12:21Z', '2026-04-03T17:12:21Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('5395eb47-928b-4637-b2a4-9951577dc24f', '0987f081-b3b7-4e3c-abb7-795e56c279d5', 17, 'Wheel of Pain', 'When Axl, Sue and Brick accidentally break the family room window, they decide to blame the Glossner children -- the bad seeds of the neighborhood; Frankie tries to land a prime dental rotation spot.', '2013-02-27', 22, '/c5CuE45aZxww0mUyciP99KupLUK.jpg', '2026-04-03T15:40:30Z', '2026-04-03T15:40:30Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('53964e2c-f496-4efb-96f6-cdae57da5e7f', '0ab4dfb2-58c9-4e52-b5bf-49bba0bfc597', 6, 'Crazy Handful of Nothin''', 'The side effects of chemo begin to plague Walt. Meanwhile, the DEA rounds up suspected dealers.', '2008-03-02', 49, '/rCCLuycNPL30W3BtuB8HafxEMYz.jpg', '2026-04-03T15:40:32Z', '2026-04-03T15:40:32Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('5396ea28-682f-41df-9bfb-b73550df8df3', '70c8cb46-2494-4dd4-98f6-6bfb9b3faf73', 7, 'Pinball Wizards', 'The Pawn Stars have an opportunity to buy a classic 1973 pinball machine in need of some serious repair. Will they rack up a high score and make the deal? Then Corey and Chum meet a guy interested in selling his personal transporter - better known as a Segway. Will Corey shell out a nice stack of cash for a new ride? And later, a woman hopes to sell Rick a 1924 St. Gaudens Double Eagle gold coin - often called the most beautiful coin ever produced by the U.S. Mint. The only question is: is it real?', '2010-02-08', 21, '/p6Llu2U8wRexZg1v3LPisEFpen2.jpg', '2026-04-03T16:34:16Z', '2026-04-03T16:34:16Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('53975995-2df3-4bbf-93f4-83b216d3bbbf', 'd7ff9136-a833-4c43-a37c-a985a34f45a9', 11, 'Airing the Dirty Laundry', 'Christine is ecstatic when Mykelti tells her she''s having twins. Then, Meri reveals that while out for their anniversary, Kody finally admitted he no longer wants a relationship with her, and she is forced to consider ending her marriage for good.', '2023-10-29', 43, '/9OtSjIGKBstznxQKsb9uHJb4wCV.jpg', '2026-04-03T16:34:32Z', '2026-04-03T16:34:32Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('539ba352-600e-4e52-b37d-72ba73b62f88', 'e3a28669-91b5-45f7-bb73-5006acc084e8', 12, 'Little Sheep of Horrors', 'Little lambs shouldn''t watch scary movies, as Timmy finds out to his cost.', '2007-03-12', 7, '/2nXfSF3Id0B8mwH6y7vwuWauHgN.jpg', '2026-04-03T17:39:31Z', '2026-04-03T17:39:31Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('539ce004-6543-446d-9dd0-999c8d1aff7e', 'e8b959c0-6865-4332-9be1-b8f720716aa8', 8, 'Hats', 'John visits The Rag Market in Birmingham.', '1991-11-18', 15, NULL, '2026-04-03T17:19:37Z', '2026-04-03T17:19:37Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('53a1ec56-e239-4dad-af77-4bc6df5c02b2', '1f34e241-4c1d-4586-921a-1c5aeb1fbbaa', 21, 'A noisy day in the library', 'Luis gives Telly Monster a plan on how to get Oscar the Grouch to help show one of today''s letters - R. Telly loudly begins his talk to get Oscar''s attention and asks Oscar not to help at all. The reverse psychology works.

Sponsors: R, X, 4', '1985-12-16', NULL, NULL, '2026-04-03T17:36:36Z', '2026-04-03T17:36:36Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('53a3fa1e-03ee-4d5c-9f0e-9f3e43b1f4fa', '5d57283d-079c-4f66-93c8-33a2feeada89', 23, 'Orlando', 'Sue looks forward to the trip to Walt Disney World; Brick begs his parents to take him to meet his online girlfriend; Axl waits to learn his final grades.', '2014-05-21', 22, '/5Ag4rfXfwi88C57i4drkqyIRepm.jpg', '2026-04-03T15:40:30Z', '2026-04-03T15:40:30Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('53abd960-1967-4f86-8deb-8f50cbc4f1b8', '70d9e397-6813-4785-887d-27d034928bae', 24, 'Pingu Makes a Discovery', 'Pingu and Robby are sledging when they come across what appears to be the tail of a large fish sticking out of the ice, and anticipate a good meal. Pingu tries to pull it out of the ice, and gets annoyed when it won’t budge. Eventually they dig it out, still encased in ice, and take it home. Pingu stokes up the fire in the stove to melt the ice on their fish, while Robby gets the frying pan. The frying pan is put on top of the stove to warm up, and together Pingu and Robby lay the table in anticipation of a feast. A little while later all the ice has melted, and then they realise that what they’ve found is not a fish and, disappointingly, it’s not edible. Grandfather then comes to visit, and decides to call the curator of the museum to come and take a look at it. It turns out to be the missing figurehead of a boat on display at the museum, and the curator is very pleased that they’ve found it. Pingu, Robby and Grandfather accompany the curator when he takes the figurehead back to the museum, where a reception party is waiting, and Pingu and Robby have their photograph taken.', '1996-08-22', 5, '/lzdDVhqrvlF2oLmiBPkt7ALEaMN.jpg', '2026-04-03T17:22:19Z', '2026-04-03T17:22:19Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('53ae9975-ee87-4b28-83ad-e7b492a5f921', '05c0e384-194c-4417-9f62-803eb615e409', 110, 'Mr. McFeely’s Birthday', 'Rogers'' television house is the site of Mr. McFeely''s birthday party. King Friday and Sara Saturday offer a gift.', '1968-07-19', NULL, NULL, '2026-04-03T17:35:38Z', '2026-04-03T17:35:38Z');
