INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('53edfc6d-4668-47dd-a7a7-a3c83d44c7cd', 'ffc2a75e-0ffa-4b26-b121-9b91b277594a', 16, 'Southern Discomfort', 'Kandi and Todd confront their issues in marriage counseling; the women continue to reel from the story about text messages exchanged between Phaedra and Mr. Chocolate; NeNe proposes a way to heal broken relationships.', '2015-03-08', 43, NULL, '2026-04-03T16:34:47Z', '2026-04-03T16:34:47Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('53eebd4f-7237-42c0-a7c2-ce104fab6836', '42e591e2-2a88-4434-ae9f-3d4b1d685613', 29, 'No Shoes, No Shirt, No Service', 'Bond with the Pawn Stars when they spy a 1961 Fender Stratocaster used on the 007 theme song. Brought in by famed guitarist Vic Flick, will the guys let him lead the negotiation? Then, Corey and Chumlee check out a fully customized 2006 Dodge Magnum. Complete with suicide doors, is this a deal or dead weight? And later, Chumlee designs a new uniform shirt for shop employees. Will he have the skills to please a tough crowd?', '2013-10-24', 21, '/fZ2hAlJaF3Ly1D804eMmVVaZKFG.jpg', '2026-04-03T16:34:18Z', '2026-04-03T16:34:18Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('53f26326-0038-40db-80ae-2fe8d444e9f5', '573a556e-ed20-4222-a12d-b1b7779e1b18', 13, 'Jungle in the Clouds', 'Steve journeys through the wilderness of New Guinea, moving through the mangroves of the coast, jungles on the lowland plains, valleys, and mountains toward his destination: a rare equatorial glacier. He examines wildlife large and small all along his route.', '2000-06-21', NULL, NULL, '2026-04-03T17:39:11Z', '2026-04-03T17:39:11Z');
