INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('53f4285f-9bd5-4994-93c8-af91c5be9281', 'd0b78f22-678e-4e46-9d61-aac40ba206b8', 6, 'Fifty Shades of Shade', 'Erika pushes Dorit to take her sex appeal to the next level during a magazine photo shoot. Denise lets it all hang out at dinner with Lisa Vanderpump and Kyle, and reveals some big details -- literally -- about Aaron. Lisa Rinna helps Camille plan her 50th birthday bash, but tensions run high at the celebration when Teddi and Lisa Vanderpump go head to head.', '2019-03-19', 43, '/ArcA2aIKW2prjrbt7f1vyatJWea.jpg', '2026-04-03T16:34:57Z', '2026-04-03T16:34:57Z');
