INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('53fe2bbd-9fff-4ee7-ae27-ac7dc21af7f5', '852a07b0-f228-4197-9147-7aeed79390bf', 13, 'Ho Ho Holidays', 'The morning after Ramona and Sonja''s birthday bash, LuAnn and Ramona learn about Sonja''s late-night escapades with one of the party guests. Leah reconnects with her siblings for the first time since their grandmother''s funeral.', '2021-08-03', 60, '/4fyN18QUlaXZF0GPTZRGDR71qYC.jpg', '2026-04-03T16:35:26Z', '2026-04-03T16:35:26Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('5400fae3-01ac-441c-aff8-38bca3be9c7b', 'c6d5cf79-f2b0-40af-ad12-91aa4f1b1d21', 2, 'Put a Cork in It', 'When a seller comes in with a poster by Henri de Toulouse-Lautrec, will it make an impression on Rick, or will he bid adieu? Meanwhile, Chum unboxes some 1912 Yale baseball uniforms. Is it a home run, or a strike out? Then, Rick takes a look at a ukulele from 1919. Is this deal music to his ears, or is the seller just stringing him along? And later, Chum, Rick and Jake head to the track to test out a restored Track Rabbit go-kart. Will it run smoothly, or be a bumpy ride?', '2022-04-30', 42, '/2C7q8aD3AzBjxIGNq6NTjWj2T3Q.jpg', '2026-04-03T16:34:23Z', '2026-04-03T16:34:23Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('54025314-a8be-41e6-8aa8-bd090a591f36', 'd920ebae-f00a-4e25-abfe-40492c74ded6', 21, 'Slice and Dice', 'When a seller brings in an antique key gun, can the Pawn Stars unlock the mystery behind it? Meanwhile, Rick strikes gold…records, when a Pink Floyd album spins into the shop. Next, a rare 1600s blade slices its way into the hands of the guys. Can Corey’s negotiation cut through? Then, Chum and Corey give peace a chance in a vintage bus. Will they ride off into the sunset, or will the wheels fall off this deal? Finally, can Rick score a Jackie Robinson card collection that’s the best thing since sliced bread?', '2020-06-01', 42, '/eNACDEqwUpHcarWASx3ILr8hJzw.jpg', '2026-04-03T16:34:22Z', '2026-04-03T16:34:22Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('5406168b-1457-4be2-8f96-8f288fe80460', '3e571866-318e-49df-8b7e-6119d7f3b442', 8, 'Shirleyverse', 'Shaun makes a wish that changes everything, with unexpected consequences.', '2025-05-24', NULL, NULL, '2026-04-03T17:39:31Z', '2026-04-03T17:39:31Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('540b4ac4-e109-4930-826f-011608259af0', 'e3a28669-91b5-45f7-bb73-5006acc084e8', 28, 'Hiccups', 'Shirley drinks Bitzer''s lemonade too fast and gets the hiccups. Shaun tries to help with all the usual tricks, and the usual results.', '2007-09-06', 7, '/AkoH9zOAKMLo5ChSMUMxBxLq2BT.jpg', '2026-04-03T17:39:31Z', '2026-04-03T17:39:31Z');
