INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('540e0362-1130-4d88-b067-5de3f2d7d656', 'c67a8787-4971-4961-b536-1ff01924e2a9', 17, 'D.W. on Ice', 'When Emily announces a skating party to celebrate mid-winter, D.W. brags about being a great skater. She feels she''s so good that she even offers lessons to James, who is worried about his skating skills. D.W., however, is overconfident, having only gone ice-skating three times in her life. She begins to learn that sometimes it takes practice to be good at something.', '2007-09-06', 13, NULL, '2026-04-03T17:37:59Z', '2026-04-03T17:37:59Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('540f0a8b-dd69-42ab-99fd-ad35b6f0f82c', '8b35accc-64c5-42b9-bd91-7dbc7f28ce38', 4, 'Flat Tyre', 'After going to a boot-sale, Trevor''s  tyre goes flat and invades Pontypandy and loads of delays, luckilly Fireman Sam goes to the rescue.', '1987-11-26', 10, '/gW8I8go038TA9F1A9ym3J3cUGcI.jpg', '2026-04-03T17:14:37Z', '2026-04-03T17:14:37Z');
