INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('544659bc-ba34-43b9-85cb-4a2ebebfdfe9', '33440d76-e69f-47ad-ac25-862ccbc9dfa1', 18, 'An Iconic Ending', 'Mia hosts a reveal party for the ladies'' "Icons" photoshoot, but things are tense following the GnA show. Ashley''s friendships are called into question. Charrisse confronts Candiace about her involvement. News of a couple''s shocking separation breaks.', '2024-03-24', 43, '/a6WbIoYM2jbEAGMUZP9iyHjZEVJ.jpg', '2026-04-03T16:35:41Z', '2026-04-03T16:35:41Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('54491c8e-f59b-4538-a7fe-3c5b56268049', '04572e48-bbfd-476b-aebe-b6dc424f742d', 6, 'Dear Friend...', 'A close friend is lost — and another found — as Geralt helps Ciri learn more about her power. Cahir warns Fringilla to focus on their primary mission.', '2021-12-17', 58, '/p0WVue8TDH4BCkgwUVpk93LKI4z.jpg', '2026-04-03T15:40:45Z', '2026-04-03T15:40:45Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('544abf21-44ee-427f-b538-8c8a1f904213', 'e6ea1431-9e67-4637-83ae-a11073e8c7e0', 13, 'Spinning a Web', 'The ladies take a spin class to raise funds for charity, but flying allegations mark the follow-up lunch. Here, Yolanda targets Kyle for spreading gossip and then confronts Lisa Vanderpump. Meanwhile, Kathryn tries to gain Erika''s trust.', '2016-02-23', 43, '/6iJZVdqCf2OoDUvaNvDnKEhehLp.jpg', '2026-04-03T16:34:56Z', '2026-04-03T16:34:56Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('5455a5cb-2774-4f74-8c82-e7eac1d8e891', '79916e0e-881c-43a7-b4ee-00e5052a94be', 18, 'Theodore and the Ice Ship', 'Theodore, George and Hank find an enormous ice sculpture floating in the water but can''t tell what the object inside it is.', NULL, NULL, NULL, '2026-04-03T17:10:11Z', '2026-04-03T17:10:11Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('54598c56-1801-4a7f-bb09-de2e7bc9bdc7', '517e7594-ee8e-4564-a52d-4588850bbbdf', 3, 'Confessions', 'Meri is not at all over the trauma of the recent catfishing incident and yet decides to attempt a therapy session with Janelle, hoping to work through conflicts from long ago. Janelle is very nervous that the therapy might open up old wounds.', '2016-05-15', NULL, NULL, '2026-04-03T16:34:29Z', '2026-04-03T16:34:29Z');
