INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('5466850f-9e58-4c83-a11a-904da0e5ff18', '5db3ff78-e439-48e1-8f67-988ecbf85d17', 16, 'Daggers and Diamonds', 'Dogtanian and Pip are returning to Paris but decide to stop enjoy the view and relax before returning. After Pip has made some remarks about Dogtanian''s feelings about Juliette Dogtanian chases him and they run into a beautiful lady. After asking about the Dagger Dogtanian received from the Duke of Buckingham Dogtanian escorts her down to the river. "Little do Pip and Dogtanian realise that this beautiful and seductive female is none other than Milady, Cardinal Richelieu''s cunning and ruthless spy."', '1982-01-15', 24, '/xM0MB4s2dqlCZuslAHR2Z7OzPRN.jpg', '2026-04-03T17:18:43Z', '2026-04-03T17:18:43Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('54781baa-5360-47bb-9891-83b60465076d', '4900fc8d-5e7e-408e-972e-ce9269d203b3', 16, 'Mountain of Lies', 'Noella makes strides with her divorce but struggles to control her emotions. Emily and Shannon make peace and band together to give the other ladies a scare. Noella pushes Gina to her limits, causing a chain reaction that makes Heather question her friendships.', '2022-04-06', 44, '/2LJY8UVkFBKwKlIK5r6pCbAGWMu.jpg', '2026-04-03T16:35:35Z', '2026-04-03T16:35:35Z');
