INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('54bfbef1-1eb7-461a-88ac-ade43341aec0', '04fb713d-9c59-45f7-8de0-acd7582daa53', 11, 'Whine Country', 'Jackie hosts a trip to a vineyard for some much-needed bonding time; Jennifer attacks Jackie for writing an article about her family. Margaret calls Jennifer''s brother''s fiancé a “mail-order bride;” Teresa throws a song release party for Milania.', '2019-01-16', 43, '/4txExaM71CxOewxOu4V6bF8gXv9.jpg', '2026-04-03T16:35:17Z', '2026-04-03T16:35:17Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('54c142d5-47b0-4d25-b739-ec464a89e29b', '262e8e7c-fa78-4578-a216-add6f184c4d2', 3, 'The Price of Polygamy', 'Kody and Janelle plan a private camping trip that results in a discussion about family finances. Meanwhile, Robyn opens up about her insecurities of not wanting to be a burden on the family financially.', '2011-03-27', NULL, NULL, '2026-04-03T16:34:27Z', '2026-04-03T16:34:27Z');
