INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('54e64632-6926-4b34-8f3d-c43a1279e992', 'efd2082e-32f5-4edd-9a7b-a4326d6992c9', 9, 'Bath Time for Blanky', 'Abby brings Rudy to the laundromat to wash his stinky blanket, but new attendant Grover doesn''t know how to use the machines; luckily, Chris brings in his dirty clothes too, and shows everyone how to use a washing machine and dryer.', '2019-01-12', NULL, '/yL2IQExtV64SHum0ToJZ0t5yAAs.jpg', '2026-04-03T17:36:49Z', '2026-04-03T17:36:49Z');
