INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('54eb9f72-ca37-4789-9c7c-672b5fc65c95', 'e8981e01-407b-4ef7-b809-3b5f30b5248d', 3, 'A Rickconvenient Mort', 'Reduce, reuse, broh. Might be too late.', '2021-07-04', 23, '/nUP1i4LregRWkwMZTITmI26NgZA.jpg', '2026-04-03T15:40:42Z', '2026-04-03T15:40:42Z');
