INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('55ca0a09-e6b2-419a-ade1-81c248e0d04a', '5b5e8b2f-0a85-4488-b3dc-3d8b794e6582', 10, 'Loose Lips Sink Friendships', 'Meghan is still reeling from Kelly’s attack at Drag King Bingo. Lydia tries to play mediator but is unable to stay impartial. Tamra gets an unexpected phone call that leaves her wondering if there is still hope for her and Vicki. Peggy prepares to send her daughters off to college. Shannon celebrates her birthday but is faced with the harsh reality that this year there will definitely not be a renewing of her and David''s vows. Vicki throws a blowout party for her birthday and an old friend reveals some juicy details about Eddie’s past.', '2017-09-11', 44, '/iatJqLSMk01tGT7eFiyVWc5l39t.jpg', '2026-04-03T16:35:33Z', '2026-04-03T16:35:33Z');
