INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('55d3ec59-a5ce-435a-abd2-dee6f67382bf', 'f12380a9-93e5-47bb-9e2f-cf1eed11eee4', 6, 'We''re Not Brother Husbands', 'The Sister Wives are moving on: Meri starts dating; Janelle starts a farm in North Carolina, but an attempt to sell the Coyote Pass land goes bad when Kody considers going behind Meri''s back; to make amends, Kody visits each of his exes to apologize.', '2025-11-02', NULL, '/nK9oQMHcJ9a9j1152VVBYUhSR1z.jpg', '2026-04-03T16:34:33Z', '2026-04-03T16:34:33Z');
