INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('55dd008c-a96c-4dc3-bb8a-01d9620219be', '0fa92002-82ae-4609-85e3-3982baa99ae1', 26, 'Postman Pat and the Flying Post', 'It''s Nikhil''s birthday. Ted ties helium filled balloons to Pat''s postbag, which flies up into the air. Pat and PC Selby give chase. Ted uses his one man hover-backpack to reach the bag and pop the balloons.', '2005-04-01', 15, '/2dnqlsdZLd7zcr5Cdyfu9mnOKRi.jpg', '2026-04-03T17:14:30Z', '2026-04-03T17:14:30Z');
