INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('562bcbdb-141c-4fbe-9355-20f9757816e1', '8c0f12e1-5379-4a27-aca2-b69401a33b0f', 4, 'Arthur''s Lucky Pencil', 'Arthur uses a pencil that seems to be lucky and then lends it to his friends. But it gets shorter and shorter, so Arthur decides to use it for emergencies only.', '1997-10-21', 13, NULL, '2026-04-03T17:37:55Z', '2026-04-03T17:37:55Z');
