INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('563ba59f-a68d-48b7-9f10-4fd8fc0ca8be', 'f4c40307-9b5e-4263-a4e0-dfa138131e7f', 103, 'Elmo''s World: Dancing, Music and Books!', 'Come look at the world through the eyes of everyone''s favorite 3-year-old! Join Elmo in three self-contained segments as he explores his special world through dancing, music, and books. Each segment gives children a chance to experience their world on the TV screen and offers adults the opportunity to experience everyday things through a three-year-old''s eyes. Meet Dorothy, Elmo''s pet goldfish and Mr. Noodle, his new friend.', '2000-10-30', NULL, NULL, '2026-04-03T17:36:27Z', '2026-04-03T17:36:27Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('563cb853-4b52-4430-8051-964d125aaab6', 'bb5a8843-6181-4a6d-bfdf-33ef2c6be7b8', 10, 'Storming Out', 'Porsha organizes a trip to Houston to help Hurricane Harvey victims, but one of the ladies steals her thunder with a competing charity event. Meanwhile, Shereé struggles to get to the bottom of NeNe’s issues with her prison boo. Riley turns 15 and learns to drive, while Kandi tries to help her repair her relationship with her father. Tensions rise when Kenya has a tough time taking constructive criticism, setting off a storm of her own.', '2018-01-21', 43, '/qyGtvUOgFGVrkFDjUsKwVVUIVlG.jpg', '2026-04-03T16:34:48Z', '2026-04-03T16:34:48Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('563f7256-e8ba-45fc-8b04-62a900530470', '56428e5e-7daa-468d-8bd2-076956507aa8', 9, 'Oceanography', 'Surf''s up! Get the current information as Bill Nye explains why oceans are salty and explores the ocean currents. Go with the flow of ocean currents with Bill Nye the Science Guy. Most of the Earth is covered with water - we''re talking 71% of the entire Earth, and most of that water is in oceans. It depends how you count, but you can say that there are five oceans on Earth - the Atlantic, the Pacific, the Indian, the Arctic, and the Antarctic. They are all connected into one World Ocean by the flow of ocean currents. Ocean water is moving around all the time. Some of the moving water forms rivers in the ocean. Oceanographers, scientists who study oceans, call these rivers of ocean water "currents". Currents help sea animals move around, they bring up deep ocean water with lots of nutrients for small animals to eat, and they push warm and cold water around, creating different climates in the oceans. As the sea surface gets warmed by the Sun, water evaporates, but salt stays in the sea.', '1994-09-24', 26, '/gvzG3cBDMDS2DHiCFHrZJWUyg0q.jpg', '2026-04-03T17:37:21Z', '2026-04-03T17:37:21Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('5640360a-f8c4-467b-8114-55a1a9e983e5', '8dd9292d-bcb1-4864-8297-4f6c3313f8c6', 3, 'Red Flags and Flag Football', 'With tensions lingering between Gina and Jenn, the ladies get their aggressions out in a flag football match; Shannon grapples with the fact that Alexis seems to be taking over everything that was once hers; Gina follows through on a tough decision.', '2024-07-25', NULL, '/sUdHLKL3c7SJYHVBlIKst0NNhB.jpg', '2026-04-03T16:35:35Z', '2026-04-03T16:35:35Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('5642974f-43ec-41b3-ad65-a1ee44af1076', '4d2cac0f-38fd-438b-8afa-acf43952e535', 275, 'Episode 275', 'Christopher Trace and Valerie Singleton introduce a magazine programme for younger viewers.', '1964-04-13', NULL, NULL, '2026-04-03T17:21:47Z', '2026-04-03T17:21:47Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('564a6bfc-b70f-4c59-844f-57b095eb197a', '6fd9fd9d-e378-411b-94b1-76ba4bd518fe', 21, 'Episode 21', 'with Christopher Trace and Valerie Singleton.', '1965-12-02', NULL, NULL, '2026-04-03T17:21:48Z', '2026-04-03T17:21:48Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('564bddf8-4134-44ce-ac4b-324e01c9b41c', 'ca3f764e-b330-4980-bd7a-2908a73b77b6', 7, 'Game Night Gone Wild!', 'The ladies'' innocent game night ends with a jaw-dropping fight, and while Kim and Kyle are on the same side for once, Brandi is left with no one in her corner. The tension continues when the ladies attend Camille’s charity luncheon.', '2011-10-17', 43, '/lK9M7snA5VlkysQy5rdl0BpSIaE.jpg', '2026-04-03T16:34:54Z', '2026-04-03T16:34:54Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('56569f3f-1df2-4a57-8c8c-51f5eb48b9d7', '1996ddd8-20c9-4a30-96be-2b87fab8d17c', 30, 'Over a Barrel (4)', 'The team writes a petition for reporter Fannie Mae Banner who does reports on people caught doing something wrong. They decide to picket while Alex and Gaby video tape Miller destroying the evidence.', '1993-04-25', NULL, '/2rhCe3jv4IRdClVHKE5ZG8sci4g.jpg', '2026-04-03T17:40:28Z', '2026-04-03T17:40:28Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('565b6162-482f-4a04-8c33-a87b563585dc', 'f07b8794-5625-4682-aae1-e56966b4c7a8', 23, 'Leon Grows Up', 'Leon wants to be a grownup because he thinks grownups can do whatever they want. When he realizes that there are lots of things grownups have to do that kids don’t have to worry about, he decides he can wait. Sizzle wears a new sweater that makes her sneeze, and Nuzzle thinks he can be a doctor to her. Julie and Skye do not appear in this episode.', '1996-02-14', 29, NULL, '2026-04-03T17:12:21Z', '2026-04-03T17:12:21Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('565f6d62-99cc-4a85-be69-e54b39740176', '32192008-7529-4677-933f-c55ea6146368', 7, 'Guess Who''s Back?', 'Stacey unveils her new line of gummies, but the brand name gives the ladies cause for pause; Wendy gets candid about her father; Keiarna and Greg discuss the state of their relationship; Angel and Tia connect with their families.', '2025-11-16', 42, '/vJTKyXzidbdYViNQ9IE1LvHN6rE.jpg', '2026-04-03T16:35:42Z', '2026-04-03T16:35:42Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('5664ef6f-0ba6-4d26-8dd9-cb4634ecac91', '9193e795-da7c-40ec-b68f-f63aa7d5174f', 277, 'Red Wedding Option 2: Interviews', 'Show creators provide additional insight into the Red Wedding.', '2014-02-18', 12, '/o0lVHQ7d9j4pTlHAq5FpuZgFPWc.jpg', '2026-04-03T15:40:35Z', '2026-04-03T15:40:35Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('5665452e-643a-405d-9849-e142d5c48310', '58adb9ab-3f1b-4a11-87b6-9b0b2dbb6aaf', 16, 'Declaration of Dopeness', 'Brew up a hot cup of joe with the Pawn Stars when a Civil War era carbine shows up with a "coffee grinder" in the shoulder stock. Will Rick bite the bullet and make a sale, or misfire on making a deal? Later, a vintage skateboard deck shows up in the shop. Will Chum skate off into the sunset or lose his footing and land flat on a no sale?', '2017-06-26', 21, '/zXYs22wtBthQFwf0ncw0WZnWtFi.jpg', '2026-04-03T16:34:21Z', '2026-04-03T16:34:21Z');
