INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('5678df84-6881-4adb-bc4c-e77d3721d2b5', '45e01c04-6ac6-41e1-87d8-f749ee230385', 18, 'Sailor Steele', 'Fireman Sam and the rest of the team are training Mike Flood and Charlie Jones to be reserve firemen, and Station Officer Steele is very pleased with their progress. Both Charlie and Mike are itching to fight a fire but the training has prevented Charlie from going out in his fishing boat and there is no fish for the Wholefish Cafe. Charlie and Station Officer Steele they go out in the fishing boat, but are cast adrift after an engine fire leaves their boat stranded.', '2008-03-05', 10, '/5AaLSf8UitbJ8bTAj7y6t7Fa8z0.jpg', '2026-04-03T17:14:38Z', '2026-04-03T17:14:38Z');
