INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('56859552-9424-4ec2-83ba-ccbe8419c543', 'eb7e3bb4-5746-4577-81c6-f5b2dc2efc6e', 11, 'The Desert', 'Aang searches for Appa while Katara struggles to keep everyone together to survive in the vast desert. Meanwhile, Iroh and Zuko seek help from an ancient secret society.', '2006-07-14', 25, '/w2zbcRX7ZE6L4QQWo1xlgsrrwLy.jpg', '2026-04-03T17:40:48Z', '2026-04-03T17:40:48Z');
