INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('569ed1ac-3da4-42a7-970c-70b12716bcdb', '27947392-39ba-45a6-b67b-fc609eb26e51', 3, 'The Fastest Food', 'Mandy goes out of control when trying to become the fastest delivery person.', '2022-11-03', 9, '/j5JTzxnLLcOGtScRsZQl7fconWz.jpg', '2026-04-03T17:14:41Z', '2026-04-03T17:14:41Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('56a07ec4-c4e1-46ee-931a-a4b7dff0ce2a', '7ccd5605-fe0b-4e00-ae7f-3e3daa252f8b', 14, 'This Is How We Do It in the O.C.', 'After the tongue-lashing Vicki Gunvalson felt she endured from the other girls during their San Francisco trip, she seeks comfort from her old, tattered friendship with Jeana Keough. Lynne Curtin is staying with her mother while she figures things out in regards to her marriage with Frank. Gretchen Rossi''s long time makeup artist and current business partner, Ronn Ann, discuss preparations for the upcoming Women''s Empowerment Expo where Gretchen will unveil her new makeup line.', '2010-02-25', 44, '/hritWW8bk9wkPuPJMqUluDzgEmo.jpg', '2026-04-03T16:35:31Z', '2026-04-03T16:35:31Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('56ab1c0e-9404-4e00-8018-8ab665385571', 'e48599f8-66ff-4c0f-9274-65b9ae1cda9e', 42, 'Episode 42', 'An important day for Buttons, Blue Peter''s third guide dog, as she joins her new owner.', '1977-02-07', NULL, NULL, '2026-04-03T17:21:53Z', '2026-04-03T17:21:53Z');
