INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('5738bd84-5cff-4141-85a0-6ebbdcef467f', '1a534647-384b-4c00-bb6c-a3371ad962eb', 39, 'Wheelin'' and Dealin''', 'Wheel and deal with the Pawn Stars as they rediscover some of the coolest vehicles to ever drive into the shop: a one-of-a-kind rock crawler, an impressive collection of restored Indian motorcycles, a custom dragster capable of reaching 192 mph and a John Deere ice cream machine that leaves Chumlee drooling.', '2015-07-27', 21, '/5Nh0WyumYvUR4Aan6bkEw50NBHB.jpg', '2026-04-03T16:34:19Z', '2026-04-03T16:34:19Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('573b17f4-b62b-49a5-976c-3a8d3f77d19f', 'ba99b779-cada-43a7-902a-2adb472c2e30', 2, 'Episode 2', 'While on a trip out Arrietty is seen. Thankfully this is by a young boy that is living in the house and he does not have the usual adult reaction to the borrowers. Unfortunately, his naivety later leads to problems but initially Arrietty asks him to deliver a letter to a place she hopes might hold another family of borrowers.', '1992-11-15', 30, NULL, '2026-04-03T17:17:47Z', '2026-04-03T17:17:47Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('573c26bf-3147-439f-8fc3-62189a7973fe', 'bd5f5a3f-07fa-4689-b67b-02be5d65f1b2', 21, 'Postman Pat and the Cranky Cows', 'With another strange package to deliver to Ted, Pat sets off across the village, eager to find out what''s inside.', '2006-03-09', 15, '/Ah9UKMENYRxoTHNVyNM6xOBYfQs.jpg', '2026-04-03T17:14:31Z', '2026-04-03T17:14:31Z');
