INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('574ebe15-574d-477e-a2d5-576f4d1745ad', 'ae8f64d9-4b83-4147-a44c-bfe720381f8e', 4, 'Wild Nature Survivor Guy', 'Wild Nature Survivor Guy finds himself on Sesame Street. He is accustomed to surviving in the wilds of nature and thinks he needs to “survive” out on Sesame Street. Elmo and Rosita are confused. He is not alone and he’s not in the middle of nature, but he is convinced nature is all around them! First, Wild Nature Survivor Guy finds a tomato plant and bites into a ripe tomato. Not only do tomatoes come from nature, but so do all the fruits and vegetables on display outside Hooper’s store. 

Next, Wild Nature Survivor Guy looks for water to quench his thirst. He finds leaves with drops of water and puts the water together to drink. Wild Nature Survival Guy becomes concerned about nighttime approaching, and looks for ways to keep warm. He picks up feathers and puts them inside his shirt. Oh my! They tickle! Elmo offers him a coat, but Wild Nature Survivor Guy explains that feathers are what make most coats warm. The sun begins to set, and Wild Nature Survivor Guy finds perfect shelter, Big Bird’s nest! It has lots of branches, and lots of animals use trees and braches as shelter. Even houses are made of wood. Wild Nature Survivor Guy sings a song about nature as Elmo and Rosita realize that nature is all around them!', '2009-11-13', NULL, '/ts4Da4C7JPy8eCPa0MMaCFagI9P.jpg', '2026-04-03T17:36:46Z', '2026-04-03T17:36:46Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('575373e3-24e6-46d7-9db1-0c09cd433278', '225b0f03-984b-47f3-a1a3-d3e92175e39d', 54, 'Episode 54', 'with Christopher Trace, Valerie Singleton and John Noakes.', '1967-04-06', NULL, NULL, '2026-04-03T17:21:48Z', '2026-04-03T17:21:48Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('575447b9-196f-4920-805d-5dcebdcfe810', 'd1863f2f-02ec-40ce-af64-db03fbe518a7', 16, 'Rocco''s Playdate', 'Elmo and Zoe use arts and crafts to help make a ''friend'' for Zoe''s pet rock, Rocco, to play with. Also featuring Murray had a lttle lamb, and Elmo''s World-drawing. Brought to you by the letter C and the number 7.', '2016-04-23', NULL, '/nlSK3otOxFFoQBKRxNzYzvOr2Z5.jpg', '2026-04-03T17:36:48Z', '2026-04-03T17:36:48Z');
