INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('5776d7d7-c5dd-47b0-bdf0-d91a4b62b10d', 'a8db07e5-fba3-49a9-bd12-947c111b39be', 5, 'Birthday Bashing', 'Jules airs her grievances about Bethenny''s abrasiveness during a Hamptons getaway. In other events, Ramona at last tells Sonja why she has avoided her, and Ramona hosts a birthday lunch that is marked by a re-gifting blunder and a confrontation.', '2016-05-04', 44, NULL, '2026-04-03T16:35:24Z', '2026-04-03T16:35:24Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('577afc6d-a04e-4bbf-8912-54a9bd16345a', 'e38e9d87-1432-4a1a-a7d0-64a559bf7570', 4, 'False Haven', 'With most of the animals too tired to care where they rest they shelter in an empty barn. But Fox is wary about being near humans and sets up a watch to alert them of danger. However when Mrs Pheasant takes the place of her sleeping husband she wanders out of the barn and is killed by the farmer''s gun. With the sound of the gun the animals try to escape but they are locked inside the barn with a dog patrolling outside. Some of the animals manage to gnaw and dig an escape route allowing them all to escape into a nearby wood. However it is when they are all safe and the panic over that Fox realises that one of them is missing.', '1993-01-24', 24, '/d40dRgUmbfxNo2gDJqrw0XHnDw5.jpg', '2026-04-03T17:18:49Z', '2026-04-03T17:18:49Z');
