INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('57a78929-b2c2-4035-9719-bfc61859148c', 'da06465b-9154-4feb-a455-374df7dab02f', 15, 'Rock sitter for Rocco (4097)', 'Zoe needs a rock-sitter to read, sing, and play with Rocco while she is away in swimming class.  Telly agrees to take care of Rocco in the meantime. Since Rocco likes rock stories, Telly, with Elmo’s help, first tells her the story of “Goldirock and the Three Bears.”  Since Rocco also likes rock music, Telly, Alan, and Bob sing, “Rock Around the Rock” to her.  When Zoe returns from her swimming class, Telly tells her about all the fun they had while she was away, and offers to help her take care of Rocco anytime!', '2005-09-09', NULL, NULL, '2026-04-03T17:36:44Z', '2026-04-03T17:36:44Z');
