INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('57bb8601-c5a1-410f-9b86-fe46c4573ae5', '7c756336-29db-4634-b976-e993e8f51da2', 2, 'All Tea, All Shade', 'Gizelle finds a new love interest in an old friend, while Ashley and Michael''s inability to mix business with pleasure continues to create tension in their marriage. The women (finally) attend Katie''s Casino Royale event, where they are less than impressed. Meanwhile, Karen organizes a high-class high afternoon tea in hopes of avoiding any low-class antics, but Gizelle gets her claws into Charrisse''s new friend Monique -while Karen questions Robyn''s loyalty--causing things to get a little improper.', '2017-04-09', 42, '/dwpwy40eW1IyvRzHnzKYgvQQnZc.jpg', '2026-04-03T16:35:38Z', '2026-04-03T16:35:38Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('57bf50fb-0874-48f5-95e0-de4c51c4a640', 'd2f2ce63-96af-4899-92a8-3da5ea3913ce', 1, 'Gets Lost in Space', 'Arnold''s know-it-all cousin Janet drives the kids crazy when she joins Ms. Frizzle''s class on a field trip and gets them lost in outer space!', '1994-09-10', 26, '/oHEaWYXRgdZkLgFsWHAQFHDqomn.jpg', '2026-04-03T17:37:48Z', '2026-04-03T17:37:48Z');
