INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('57d3e2b7-768e-4fb4-b284-fc224d0ae2d3', '050d8ae1-6cc1-4018-933d-b3c3d13de856', 51, 'Episode 51', 'The Lamberts of Croydon

One hundred and sixty years ago, two boys and a small girl riding on a donkey were painted by the famous artist John Constable.

''They are very well-behaved and amiable children, and the donkey is a fine, rough, good-natured animal'' he wrote to his wife.

Today may be your last chance to see this painting - when this great family treasure is auctioned at Sotheby''s next week, it could well leave the country forever.', '1985-03-07', NULL, NULL, '2026-04-03T17:21:57Z', '2026-04-03T17:21:57Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('57e208cf-0661-4a30-a94a-d19dca5b9cf3', 'a7421c26-c9a2-437a-be12-2cabed2b5a96', 7, 'A Scary Story / John the Music Man / Orbie the Grouch', '', '2001-10-17', NULL, NULL, '2026-04-03T17:11:22Z', '2026-04-03T17:11:22Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('57e75461-7a2d-4d5d-80c7-c9d89e6b1320', '53f9624f-fcf8-4f77-82f6-d2eb3f5376ee', 21, 'The Land of Milk and Honey?', 'With Christine''s help, Janelle moves her life from Flagstaff to North Carolina and sees the land that she purchased sight unseen. Meri questions her entire relationship with Robyn. Kody prepares to baptize Aurora into a new church.', '2025-04-20', 43, '/m6pkKVrDoUrM9g1CMf92wbQy3QZ.jpg', '2026-04-03T16:34:33Z', '2026-04-03T16:34:33Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('57f00d46-438a-4886-86a0-c517745671d2', '66a11a09-aee2-4a7b-8543-ab080a9d1be4', 1, 'Guess Who''s Coming to the White Party?', 'Lisa Vanderpump is still wary of her former friends but begins to reconnect with Yolanda and Kyle; all of the women come face to face at Kyle''s extravagant White Party; the annual event brings together the original Beverly Hills housewives.', '2014-11-18', 42, '/45TOTSmugmr4T2vQ81QOjObfiCD.jpg', '2026-04-03T16:34:56Z', '2026-04-03T16:34:56Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('57fa927a-c2c1-4a16-a054-2fc0466a8849', '9b95011e-93db-4e56-a45d-8aa956c15997', 21, 'Hide and Seek', 'Norman, Mandy, Sarah and James decide to play hide and seek while the sausages are cooking, but disaster strikes. Meanwhile, Elvis and Mike try to fit in the new pole after Penny accidentally damages it, but Sam has a better idea.', '2014-08-23', 10, '/eejcXyGXyYxc3NjsW13UKYVzHvY.jpg', '2026-04-03T17:14:40Z', '2026-04-03T17:14:40Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('57fda0d9-fb28-4e67-8b35-1c15cbbc6e07', 'ceab3d79-abbe-47fb-b8b3-3073fccb1ec7', 10, 'Fear No Mort', 'A jaded Rick and Morty seek spooky thrills.', '2023-12-17', 24, '/4kKiVFbRxAPxcPDi7rPrUJjyMf6.jpg', '2026-04-03T15:40:43Z', '2026-04-03T15:40:43Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('58045e46-e475-45a3-8800-982a17859526', 'd123fd65-efb7-4ebb-a23e-190c447791cf', 11, 'Versace and Venom', 'Larsa moves forward with selling her family house; Alexia finalizes her wedding plans; the ladies get together for Alexia''s bachelorette party, but the fun quickly gets nasty after old feuds are reignited.', '2022-02-17', 44, '/8H7Ee7MZD7JX4d8J7GEtn0Lqf5y.jpg', '2026-04-03T16:35:11Z', '2026-04-03T16:35:11Z');
