INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('580ba222-ecf4-47aa-9380-c7deb96627fc', '3ee646e8-23ae-4dec-bbc6-c7e6a210d55b', 89, 'Open stage night at Birdland', 'Before Birdland opens, Hoots the Owl explains that tonight is "Open Stage Night," where anyone can get their chance to perform on the Birdland stage. A man named Forest Wimbeldon (Branford Marsalis) enters looking for Hoots, wishing to play jazz tonight. Hoots sees how un-jazzy his saxophone playing.

Sponsors: E, I, 4', '1991-03-14', NULL, NULL, '2026-04-03T17:36:38Z', '2026-04-03T17:36:38Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('580d8759-a1b1-4a7e-9af8-5b96ce3d5093', 'bbfee3b4-9c95-48a6-beaa-791fa08b1f43', 36, 'Episode 36', 'Ski Monday!

Peter reports from the French Alps where 232 12 to 18-year-olds have been competing in the 1984 British Junior Ski Championships.

Who will be the Ingemar Stenmark ot the future?', '1984-01-16', NULL, NULL, '2026-04-03T17:21:56Z', '2026-04-03T17:21:56Z');
