INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('58842872-3203-465c-a548-3cf64ea286cd', '58adb9ab-3f1b-4a11-87b6-9b0b2dbb6aaf', 5, 'Spider Pawn', 'Get fired up with the Pawn Stars when Rick investigates the authenticity of a rare 1936 Zippo lighter prototype. Will Rick light the fire on a sale or extinguish the deal when the truth comes out? Then, Corey tries to call in a fair price for an antique rotary phone, but will the seller hang up if it''s a wrong number? Later, it''s a meeting of the Lees when Chumlee meets legendary Marvel Comics creator and writer Stan Lee. Will Stan tell Chum his signed comic is a villainous sham or will he write Chum a superhero''s ending?', '2017-04-24', 21, '/mbtRu0Wlaac7kfwpYOItKCetsea.jpg', '2026-04-03T16:34:21Z', '2026-04-03T16:34:21Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('5884530f-83ee-4727-9cc0-98aa33ed4692', '99a96781-44cb-4a5c-9100-71e2a55b6b1a', 11, 'Here Comes The Bride', 'Season 3''s finale brought new beginnings and some endings to the OC, the biggest of which being the celebration of Lauri and George''s wedding. Lauri continued to work things out with her son, Josh, with the help of a mediator, and Josh made it to his mom''s special day. Viewers finally met "Roxie," Quinn''s alter ego, but it wasn''t enough to save Quinn''s relationship with Billy, which ended. And finally, Jo returned to make an appearance at one of Jeana''s many outdoor get-togethers, updating the ladies on the status of her musical career.', '2008-01-22', 44, '/nv2OGPDqRwb7pOoXjBfyK0OjyOq.jpg', '2026-04-03T16:35:30Z', '2026-04-03T16:35:30Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('58864ab2-1547-43cf-91e6-97e51a8de5b2', '4aa00613-08c0-402b-85c7-6805658d02a1', 1, 'Visiting Day', 'The series tackles a delicate subject of how some children must deal with a parent in prison. Alfre Woodard reads Visiting Day, a tale about a young girl preparing to visit her father in jail on his birthday, and how she and her grandmother get ready for the trip to the prison. Afterwards, LeVar visits a real family planning to see their father and husband in jail as he finishes his prison term for shooting at a man during an argument, and how they have to cope with the social stigma of having to explain an ex-convict.', '2004-12-15', 30, NULL, '2026-04-03T17:36:21Z', '2026-04-03T17:36:21Z');
