INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('58f966d0-2228-4490-b2af-29ff1e8c32d2', 'e40e6b63-9f84-449f-8e88-53209b0906c8', 2, 'Chris Arrives on Sesame Street', 'Gordon and Susan''s nephew, Chris, just moved to Sesame Street. He is looking for a job in the Help Wanted section of the newspaper because he needs money to buy books for school. Chris thinks the first ad might be for a job as a gym teacher because it reads, "Must love to exercise." He sings a new verse of "The People in Your Neighborhood."', '2007-08-14', NULL, '/iXK7zPzlepQvMBJSKf4XYYTpSHP.jpg', '2026-04-03T17:36:45Z', '2026-04-03T17:36:45Z');
