INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('59140d69-356a-4ba9-a45e-f51d8b9cb17b', '02849455-d14b-476b-9603-eef5fb5d2ab3', 1, 'You Gotta Make Millions to Owe Millions', 'Finally residents of 20854, Monique and Chris adjust to their new Potomac neighborhood. After months of living apart from Michael, Ashley decides it’s time to give her marriage another shot, influenced by sage advice from newly-in-love Gizelle. Karen and Ray become the talk of Potomac after a shocking headline in The Washington Post.  And things get heated between Karen and Robyn after a huge breach of trust.', '2018-04-01', 42, '/7EX3dqoxzMHnHPNThE2rOEVmXh5.jpg', '2026-04-03T16:35:39Z', '2026-04-03T16:35:39Z');
