INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('5917e29d-2ac1-44d2-9c3a-49f73a907712', '87989283-6fea-40d7-8d91-22c4947db105', 13, 'The Heat Is On', 'A forest fire is bearing down on Meri''s house and she''s prepaing to evacuate. Robyn is just days away from losing her rental and tensions are high with Kody. Lastly, Madison is having contractions and thinks the baby is coming tonight!', '2020-03-29', 56, NULL, '2026-04-03T16:34:31Z', '2026-04-03T16:34:31Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('591e8e7b-3ef7-429d-af87-0b48cbf1ef11', '3af7ea64-fa13-4097-b8e4-40af07083054', 42, 'Episode 42', 'Rogers hears Don Riggs play a washboard at Negri''s Music Shop. He also visits the McFeelys'' house to see an old-fashioned washing machine. In the Neighborhood of Make-Believe, X suggests a role he can play in the opera.', '1974-04-16', 28, NULL, '2026-04-03T17:35:40Z', '2026-04-03T17:35:40Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('591fc15f-0f57-4313-9f98-89630fab13e6', '5c1b881f-ac58-4d72-b63f-209952d4f902', 37, 'Episode 37', 'Shampoo and Set  Tina shows how to make a dolls'' hairdressing salon, complete with basins, showers and driers.', '1980-01-17', NULL, NULL, '2026-04-03T17:21:54Z', '2026-04-03T17:21:54Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('59208a93-a3b1-4b63-8159-6a401e8301f1', 'bc1b58b0-f2d6-4214-914b-231f27fb4d61', 16, 'Singing in the Pain', 'The wives are up and running when they participate in a charity race, with Teresa''s competitive nature on full display. Meanwhile, Melissa premieres her song to an unforgiving crowd in Hoboken. And Teresa throws a birthday bash for one of her daughters, highlighted by a jaw-dropping gift.', '2011-09-11', 43, '/skxrlGEmYZAtFHZBZPEq7NHa9eB.jpg', '2026-04-03T16:35:15Z', '2026-04-03T16:35:15Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('592c0fb5-bf0c-44aa-92fa-2e2edfaeda98', '1d713ca6-4e17-4f84-949c-8cfd98514127', 24, 'Chummified', 'Walk like an Egyptian with the Pawn Stars when a mummified falcon creeps into the shop. Is this ancient bird destined to spend eternity with Rick, or will it fly out the door? Then, Rick and Chumlee call a timeout when an autographed Harlem Globetrotters basketball from 1978 bounces in. Will the deal be a slam-dunk or an air ball? And later, when a metal detector comes in from the nightshift, the Old Man and Chumlee borrow it to go treasure hunting against Rick''s wishes. Will they strike gold before Rick strikes back?', '2014-10-16', 21, '/ab8ILK8NvHsePVLy8oSu3SoPWSQ.jpg', '2026-04-03T16:34:19Z', '2026-04-03T16:34:19Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('592c1bcf-4a9d-4ad2-8818-57d167678c9c', '04e133fd-c4a3-4dfa-8369-c6dcfd1e3a5a', 124, 'How Oscar came to Sesame Street', 'Oscar recalls the story of how he first arrived on Sesame Street and came to live in his trash can home. He remembers meeting the other residents and settling into the community. The flashback reveals Oscar''s history and how he became part of the neighborhood.

Sponsors: O, V, 3', '1985-05-09', NULL, NULL, '2026-04-03T17:36:36Z', '2026-04-03T17:36:36Z');
