INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('59c0ac96-6e9f-4c58-89fe-36f094b9ad49', '53587a7e-cd93-44f0-ad79-5fe586dccb8e', 6, 'The Rainbow Puddle', 'When Kipper finds a magic frog in a puddle at the end of a rainbow, he''s granted wishes. But when the frog has a wish of his own, Kipper must find a way to give his wish away and help his new friend.', '1997-10-10', 9, NULL, '2026-04-03T17:10:48Z', '2026-04-03T17:10:48Z');
