INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('59c4231d-d2c0-4384-8ec0-fb5bd771f45d', '02849655-bd95-4d8d-af3b-03321918eeee', 22, 'Madeline at the Eiffel Tower', 'After Madeline performs a successful science experiment dropping an egg off the balcony of the old house without breaking it, Pepito dares her to drop her egg off the top of the Eiffel Tower, and the two end up getting stuck in an elevator there, and being forced spending the night. Pepito and Madeline share their knowledge. Pepito shows her Morse code, and Madeleine shows,... well... her hunger.', '2001-01-31', 30, NULL, '2026-04-03T16:34:02Z', '2026-04-03T16:34:02Z');
