INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('59dfbfe8-933a-4b4a-b51f-659a3b14c083', 'bbfee3b4-9c95-48a6-beaa-791fa08b1f43', 31, 'Episode 31', '1983 was the year Blue Peter took off! Remember when Simon went spinning upside-down in a jet at 40,000 feet, Peter flew through the air on a flying trapeze, and Janet risked life and limb on her first parachute jump? The year''s special guests included Pele, Bonnie Langford, Elton John, the Prime Minister through the voice of 16-year-old Linda Kemery and Torvill and Dean.', '1983-12-29', NULL, NULL, '2026-04-03T17:21:56Z', '2026-04-03T17:21:56Z');
