INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('59f7e864-4c85-4812-a03b-651d539c6f45', '2a1c12a9-3fc2-44c9-8d37-010d16f56c77', 2, 'Happy Days', 'JJ and all his pals make music about trucks, show-and-tell and the holidays to the tune of familiar songs.', '2023-02-15', 55, NULL, '2026-04-03T15:26:07Z', '2026-04-03T15:26:07Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('59fc2ef9-8d92-4a86-adb8-ae4feb70c1a2', 'da06465b-9154-4feb-a455-374df7dab02f', 16, 'Goldilocks Takes Over Nursery Rhymes (4098)', 'Being completely oblivious to their feelings, Goldilocks takes Little Miss Muffet’s curds and whey, and then sticks her finger into Little Jack Horner’s pie.  She takes both of their nursery rhymes and makes them her own!  Little Miss Muffet and Little Jack Horner are so upset that they start crying and run off to Baby Bear and Big Bird who offer to help them.  They encourage Little Miss Muffet and Little Jack Horner to be assertive and stand up for themselves.  Little Miss Muffet and Little Jack Horner gain the confidence to approach Goldilocks, who is at Hooper’s Store with Alan.  Alan notices that Little Miss Muffet and Little Jack Horner are very upset, so he encourages them to share their feelings with Goldilocks.  After they express how badly she made them feel, Goldilocks realizes that she wouldn’t like it if they did the same thing to her and apologizes, saying that she really didn’t mean to make them feel sad.', '2005-09-12', NULL, NULL, '2026-04-03T17:36:44Z', '2026-04-03T17:36:44Z');
