INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('5a40eab9-6118-4ee4-a3dd-7e4907ccd828', 'bd8a516b-9872-472d-a838-7aff1070fea3', 5, 'Nancy Walker', 'Kermit is at home sick so Fozzie has to run the show and proves how bad he could be by having Crazy Harry of all people have an opening skit "Target Practice", then getting "Vets'' Hospital" and "At The Dance" on the same stage at the same time, causing a lot of trouble for the bear and his costars.', '1977-10-28', 26, '/273XwegXIzts1ZV9hllexbB6DRo.jpg', '2026-04-03T17:35:24Z', '2026-04-03T17:35:24Z');
