INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('5a5895ac-9746-4fc5-897e-759224aad31d', '6ef86c27-33e7-47e5-a053-483059dfd16d', 68, 'Episode 68', 'Each year more than 30,000 new recruits join hospitals all over Britain at the start of their nursing careers. Sarah spends the day at one of the most famous of the great teaching hospitals - St Thomas''s, London.

On Seymour Ward for children, a trainee nurse is expected to cope with anything from babies who don''t want to be bathed, to cheering-up new and nervous patients.', '1982-05-17', NULL, NULL, '2026-04-03T17:21:55Z', '2026-04-03T17:21:55Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('5a5a3f44-f32c-476a-bd27-8682ccaef8bc', '17e6cc8e-dcf3-4ce6-97db-5a9fc8e31eb5', 7, 'Nashville Hold Em', 'The ladies travel to Nashville to get away for Porsha''s birthday, but tension soon follows; Drew encounters startling news in court; as Brit picks up the pieces from recent allegations, she receives support from an unexpected housewife.', '2025-04-20', 42, '/rSE2VK6exVh1HmC4XwZ98n3X09x.jpg', '2026-04-03T16:34:50Z', '2026-04-03T16:34:50Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('5a5af86c-fe90-4e70-ac12-9bffdc07f516', '50ee8f6c-645c-4d48-bab9-53b9f8f7ff2f', 13, 'Siblings', 'Baby Bear''s a little aggravated with Curly Bear as they''re coloring—he doesn''t want to share the crayons. Sometimes it''s hard to share with a sibling, Chris and Christy explain. They should know—they''re twins.', '2011-11-09', NULL, '/rEOsgit2YtELqkYZ0Cb05Ukzrft.jpg', '2026-04-03T17:36:46Z', '2026-04-03T17:36:46Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('5a6137d9-bdee-41b5-a01c-0942bb968b5f', '17e6cc8e-dcf3-4ce6-97db-5a9fc8e31eb5', 16, 'Chicken and Waffles', 'Kelli and Charles Oakley face off cooking chicken and waffles; a man with a word for Angela throws a wrench in the fire that may affect her; Phaedra throws an event for one of her many businesses; things come to a head between Kelli and Brit.', '2025-06-22', 42, NULL, '2026-04-03T16:34:50Z', '2026-04-03T16:34:50Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('5a616af2-1ea2-4cd8-b3f2-2dba06a7ce91', '54c29014-2dbd-49ff-a23f-cf4c546e0b3a', 5, 'Everybody Thinks We''re Drag Queens', 'Battles continue at LuAnn''s barbecue. Elsewhere, Sonja tries to clear the bitter air by hosting a brunch; Carole receives an honor at a Coney Island parade, spurring the other ladies to strut the boardwalk dressed as seagoing drag queens; and Aviva faces her greatest fear.', '2014-04-08', 60, NULL, '2026-04-03T16:35:23Z', '2026-04-03T16:35:23Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('5a692eea-8c91-4713-aece-f4d17193016f', 'f4c40307-9b5e-4263-a4e0-dfa138131e7f', 118, 'The Alphabet Game', 'Sonny Friendly is the host of "Alphabet Treasure Hunt", a game show where contestants bring in items that start with certain letters of the alphabet. His contestants are Gary Grouch, Dimples the Dog and Big Bird. A video board picks a letter of the alphabet at random, and the contestants must find an item that begins with that letter. When they succeed, a piece of a cookie will light up, and when all three pieces light up, the contestant wins. At random times the board will also pick a number of letters, which then present Sesame Street segments involving those letters.', '1998-10-19', NULL, NULL, '2026-04-03T17:36:27Z', '2026-04-03T17:36:27Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('5a6a79c4-7465-4cf0-9069-df28b4b3872d', '432a6abd-dcca-44cc-82ce-fb39e33b8949', 28, 'Episode 28', 'Rogers plays an audio cassette that hints to a package containing a magnifying glass. In the Neighborhood of Make-Believe, King Friday gets the impression that a magnifying glass will make Prince Tuesday grow.', '1971-03-24', NULL, NULL, '2026-04-03T17:35:39Z', '2026-04-03T17:35:39Z');
