INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('5ae9fe1c-eb9a-4370-9741-175ae8fef30d', '9bd388de-f7fb-4a70-8458-3db458a2abf0', 2, 'Sharing', 'Rogers displays a horse Leonard Streckfus constructed from found objects. He also visits Streckfus at his workshop, where other found-objects sculptures are on display. In the Neighborhood of Make-Believe, Mayor Maggie learns the Westwood town sign is missing. It appears Lady Elaine has taken it for her "found" objects exhibit.', '1997-09-05', NULL, NULL, '2026-04-03T17:35:48Z', '2026-04-03T17:35:48Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('5aee69e2-b5cc-4c88-bae8-488493a9a840', 'e6359e6d-9bdb-4aba-9cba-6f7ddd6328f9', 11, 'Thank You, Thuck You', 'With front row seats to New York Fashion Week, Dorit tries to get back into Lisa Vanderpump''s good graces, while Kyle wants an apology from Lisa but doesn''t think she''ll get one. Erika comes face to face with Kyle''s old friend, Bethenny Frankel, who was critical of Erika''s music the last time they met. Lisa Rinna''s daughter is already feeling homesick. Teddi persuades Lisa Vanderpump to do the unthinkable.', '2018-02-27', 43, '/sSqYxOVnDQ8Rqz9247gFu66fgWx.jpg', '2026-04-03T16:34:57Z', '2026-04-03T16:34:57Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('5af21eb4-2f5e-4755-9a2b-85eb2703d5b0', '8dd9292d-bcb1-4864-8297-4f6c3313f8c6', 4, 'Not My Cup of Tea', 'After Katie shares controversial information about Heather, the two come head-to-head at Katie''s golf event; Jenn is upset with Emily for her comments about her financial woes.', '2024-08-01', NULL, '/nkNYtEPCuhJ6EuyMXgWkBtFeQAq.jpg', '2026-04-03T16:35:35Z', '2026-04-03T16:35:35Z');
