INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('5afdab21-556f-4d0d-a2e3-d92ac96511ca', '32192008-7529-4677-933f-c55ea6146368', 14, 'High and Dry', 'The ladies continue their trip to Colorado with a welcome mixer at Angel’s picturesque home. Monique draws unique parallels between her life and Angel’s. Chaos ensues when the guest house girls encounter a problem with their accommodations, leaving them feeling like they’ve been left high and dry by their host.', '2026-01-11', 42, NULL, '2026-04-03T16:35:42Z', '2026-04-03T16:35:42Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('5afe7f22-593f-4757-820b-52d7caaac513', '6fedba82-52f3-4184-be77-6b26e556cd0e', 14, 'A Visit to the Dentist', 'Paddington goes to the dentist.', '1976-01-23', NULL, NULL, '2026-04-03T17:22:52Z', '2026-04-03T17:22:52Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('5aff873d-27a0-4fac-bac8-962160595a8c', '5b5e8b2f-0a85-4488-b3dc-3d8b794e6582', 13, 'Don''t Rock the Boat', 'Lydia throws Doug a party aboard a yacht to say farewell to his fertility and invites all the ladies despite her hurt feelings over being left out of Shannon''s dinner. At the party, Peggy is infuriated when David questions Diko about her health. Meanwhile, Easter arrives in the OC and Shannon looks to her mom for advice about her marriage with David. Meanwhile, Vicki decides to call Tamra to finally meet and end their feud once and for all.', '2017-10-02', 44, '/ye1KEXo5Hc1CrpRiGBEf2CyGm4Z.jpg', '2026-04-03T16:35:33Z', '2026-04-03T16:35:33Z');
