INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('5b4c69fc-68c6-4528-a3f8-299caeed5699', '3af7ea64-fa13-4097-b8e4-40af07083054', 18, 'McFeelys’ anniversary (Pt 3) [1343]', 'Audrey Roth wants to put a mirror in an old frame and present it as an anniversary gift for the McFeelys. In the Neighborhood of Make-Believe, Prince Tuesday sees himself, for the first time, in a mirror while touring the Museum-Go-Round.', '1974-03-13', 28, NULL, '2026-04-03T17:35:40Z', '2026-04-03T17:35:40Z');
