INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('5b5b12ed-95b5-494e-858a-7936dfbb3413', 'd8ccf6d3-e37a-430a-b67d-7fbf269bf0be', 18, 'Reunion (2)', 'In Part II of the reunion, Monica breaks down while reflecting on her relationship with her mother. The rift between Angie and Monica grows as they disagree about the unseen events from Greek Easter. The group is joined by Mary, who comes to Monica''s defense and sheds light on where she currently stands with the rest of the women.', '2024-01-16', 44, '/k1wZt4vtFvBzZG4dXc6jPypt90Z.jpg', '2026-04-03T16:35:45Z', '2026-04-03T16:35:45Z');
