INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('5b655c26-542f-4f7c-9eb5-8d4047143cb7', '38bf8c20-c17c-4071-9226-7887787cf1b1', 6, 'Clickety-Clack, Clickety-Clack!', 'Theo ""borrows"" the typewriter from the book ""Click-Clack Moo!"", and has a hard time letting it go when the cows want it back.', '2001-04-09', 30, NULL, '2026-04-03T17:12:28Z', '2026-04-03T17:12:28Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('5b682cdc-213e-4b7a-a4d4-54236044424d', '543ec6dc-c6c7-447c-b5a7-4484d9618391', 3, 'Foreign Relations', 'Michaele and Tareq decide to join Stacie and her husband in Europe, and the two couples start to create a bond. Cat is working hard on her book and creating her cover, when disappointment suddenly strikes. The housewives come together at Mary''s fashion dinner to welcome a celebrity hairstylist, but previous drama comes into the light again and the night doesn''t go as planned.', '2010-08-19', NULL, NULL, '2026-04-03T16:35:01Z', '2026-04-03T16:35:01Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('5b6a2124-6e26-480e-afc6-575963d3c5c3', 'bd8a516b-9872-472d-a838-7aff1070fea3', 1, 'George Burns', 'Kermit is hassled by Daily Scandal reporter Fleet Scribbler, who blackmails his way backstage at The Muppet Show and is determined to spin everything he hears in a negative light. He even offers Miss Piggy a picture spread if she''ll give him the real dirt on the Muppets. Soon, even the Swedish Chef is talking to Fleet, who answers in mock-Swedish.', '1977-09-30', 26, '/zvCrPLoZJBseVorPvgl1HgmUY7p.jpg', '2026-04-03T17:35:24Z', '2026-04-03T17:35:24Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('5b6e4742-491d-42eb-957f-936cb3097780', '432a6abd-dcca-44cc-82ce-fb39e33b8949', 20, 'Episode 20', 'Queen Sara asks Bob Dog to send a note asking if Henrietta Pussycat can babysit for Prince Tuesday. Bob Dog is distracted with a new rocking chair, but he finds a way to help the Royal Family.', '1971-03-12', NULL, NULL, '2026-04-03T17:35:39Z', '2026-04-03T17:35:39Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('5b7e93bc-11bd-49d5-803d-9ef58339d778', 'df77dba2-bbda-4f38-9713-8d5c856f852e', 7, 'The Rainy Day', 'It is a wet afternoon and the rain is coming in the playroom window and dripping through a hole in the dolls’ house roof. The poor Doll family don’t know what to do; all their things are getting wet. The toys dream up lots of ingenious ways of mending the hole, but nothing really works until Little Bear finds a solution quite by chance. While standing on the roof, clutching his umbrella, he accidentally falls through the leaky hole and the Doll family are delighted with the surprising repair.', '1993-11-14', 10, NULL, '2026-04-03T17:18:55Z', '2026-04-03T17:18:55Z');
