INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('5baa899f-8b01-45e0-a1d9-b32df68b0fbc', '3190d082-877d-4951-bf7c-ed07ef560040', 9, 'Mummies Made in Egypt', 'A camel is out of place in Boston, but LeVar rides one in preparation for a show that takes a close look at mummies. Corrine Orr narrates "Mummies Made in Egypt", a book that gives all the facts about what mummies are, how the ancient Egyptians were mummified, and what they resembled three thousand years ago.', '1988-08-30', 30, NULL, '2026-04-03T17:36:16Z', '2026-04-03T17:36:16Z');
