INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('5bb16255-03bb-4f59-999b-5e174261dbec', '151e88a1-9576-4bd1-b84a-c4d64c1c9fe8', 14, 'Shameless Not Ruthless', 'Dorit throws a charity dinner to benefit the homeless, but there is little goodwill between Lisa and Sutton. When Lisa’s anger turns to tears, her friends rally to her side in her time of need. Crystal opens up about her health, expecting support from the women, but is stunned to face questions instead. Erika’s patience is stretched thin when Kyle reveals Garcelle criticized her drinking. After a turbulent year, Diana and Asher plan for a more harmonious future.', '2022-08-10', NULL, '/h6xhPosZ5L2K28RYXqEwlbxORFd.jpg', '2026-04-03T16:34:58Z', '2026-04-03T16:34:58Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('5bb35463-3979-4528-bf0f-582cfd42c8a2', 'abfe14ee-db42-4dde-a96a-601ff3c53ecc', 10, 'A Favour Returned', 'Matthias'' wild sparrow friend, Warbeak, attempts to reconnoiter Cluny''s camp as he prepares yet another attack on the abbey. She is captured and Matthias has to attempt to rescue her before Cluny feeds her to Asmodeus the snake. Posing as Cluny, Basil helps rescue Warbeak and Matthias sees Asmodeus once more and resolves to find a way to kill him. he stands between Matthias and Martin''s sword and battle is inevitable.', '1999-10-01', NULL, '/A3c40sgS0cr5mryrPbIKmYGOWTw.jpg', '2026-04-03T17:12:08Z', '2026-04-03T17:12:08Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('5bb8126a-df03-4798-9e68-0d07065390b9', '3982796b-5451-4100-9042-46bedf6a20a5', 19, 'Pingu and the Disabled Penguin', 'Pingu decides he’s going to play a practical joke, and meets up with Pingo. Pingu leads the way to a nearby ice-shelf, opens a bag he’s been carrying and takes out a fish and a piece of rope. He puts the fish on the ground, ties the rope to the fish’s tail, takes the other end of the rope to the ice-shelf and then covers the rope in snow so that all that can be seen by a passer-by is the fish on the ground. He and Pingo then hide on the ice-shelf and wait. Soon a penguin comes past with her shopping and sees the fish on the ground. She’s just about to pick it up when Pingu tugs on the rope to pull the fish away, and the shopping goes flying. Pingu and Pingo find this hilarious, the female penguin doesn’t! She picks up the shopping and goes off muttering. The next penguin to come by is in a wheelchair. He sees the fish and is delighted, but can’t find an easy way of getting the fish. Pingu doesn’t think that they should trick him but Pingo does and, despite Pingu’s attempts to prevent it, pulls the fish away. The disabled penguin follows the fish, the wheelchair hits a jutting piece of ice and the disabled penguin falls flat on his face on the ground with the wheelchair upside down beside him. Pingu and Pingo help him back into his chair, and explain what they did. Fortunately he sees the joke, and decides to join in, so when Pingu and Pingo hide for the next victim, the disabled penguin also hides. The next passer-by sees the fish, takes a close look at it and spots the covered rope. He gives it a tug and Pingu, who is holding the other end, falls off the ice-shelf and hurts his foot. While Pingo and the disabled penguin see to Pingu, the passer-by has a chuckle, eats the fish and walks away. Pingu gets home with the help of the disabled penguin; the disabled penguin is in the wheelchair, Pingu is balancing on top and Pingo is pushing. When he gets home Pingu thanks the disabled penguin, and Mother bandages Pingu’s foot. The disabled penguin then amuses them by doing “wheelies” in the wheelchair.', '1994-08-10', 5, '/1NKp0ZlVICqz5JSWj7brCL1QF00.jpg', '2026-04-03T17:22:19Z', '2026-04-03T17:22:19Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('5bbcaad8-cfaf-4939-bc71-ce26d156cbdd', 'fb4ecc73-cb92-4c5c-821f-92179058b37b', 90, 'Episode 3745', '', '1998-03-20', NULL, NULL, '2026-04-03T17:36:41Z', '2026-04-03T17:36:41Z');
