INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('5bf888dd-2653-48ac-b004-d1ba1b96c8ae', 'abeb8d07-5c86-4f6a-a110-b11cba2a4138', 1, 'The Awakening', 'Aang awakens to find himself aboard a captured Fire Nation ship with a full head of hair and sustaining serious injuries from the previous battle for Ba Sing Se. At his side are Katara, Sokka, and their father Hakoda who recount the events that led the four to the ship and contemplate their next move. Aang struggles to fight his own desire to face the Fire Lord before he is ready. Meanwhile, Zuko deals with his own issues as he makes his long-awaited journey home, with the fear of his father''s rejection hanging over his head.', '2007-09-21', 25, '/4bucff7ht2AkY6mAVgYMsJPVxo7.jpg', '2026-04-03T17:40:48Z', '2026-04-03T17:40:48Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('5c083902-eca8-4c02-b69f-733285ea6069', '10da3800-1902-4816-ab86-d911b2ed6ff2', 2, 'The Little Mermaid', 'Pam Dawber makes a deal with a sea witch after rescuing a human from drowning -- she wants to become human. The witch agrees to give her legs, but the prince must fall in love with her or she is doomed to be sea foam forever on the sea. The Witch also takes away her voice and warns her that every step she takes will feel like she is walking on knives. Even with all odds against her, the little mermaid follows her heart, no matter where it may lead!', '1987-04-06', 51, '/8RnY4eDkZy98PU5eNMppp7nHQj1.jpg', '2026-04-03T17:38:42Z', '2026-04-03T17:38:42Z');
