INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('5c2c0459-701c-4011-9011-b927770980db', 'bfdf87ff-01dd-4b54-94bd-19b384f41bdb', 18, 'Vicious Lies and Broken Ties', 'In the season finale, the ladies gather together at Shannon''s new house for a carb-loaded affair to celebrate Tamra''s victory at the fitness competition. However, with the residual anger surrounding Vicki''s loose-lipped gossip, Tamra, Heather and Shannon decide it''s time to shut down the rumor mill. After an evening of avoidance, they finally confront Vicki about her vicious rumors.', '2016-10-31', 44, '/iEut251Opf0W7QmEC6GLlQlOr1j.jpg', '2026-04-03T16:35:33Z', '2026-04-03T16:35:33Z');
