INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('5c67058c-d88d-4678-a081-1a91fdbab0eb', '63f9bf6d-39b3-44f4-b885-a56807277a80', 28, 'A Company of Players', 'The documentary includes previously unseen interviews with Martin Baker, Bill Barretta, Kevin Clash, Bonnie Erickson, Karen Falk, Michael K. Frith, Amy Van Gilder, Dave Goelz, Jane Gootnick, Jerry Juhl, Brian Henson, Kathryn Mullen, and Steve Whitmire. They talk about the cooperation between the puppeteers on The Muppet Show, and how a few of the core characters were developed.', '2008-05-20', 10, '/xai181tZizYCucp1lllAiqAFYRV.jpg', '2026-04-03T17:35:23Z', '2026-04-03T17:35:23Z');
