INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('5c67faf0-de22-44fe-9e60-72cbaf03f9fd', '04e133fd-c4a3-4dfa-8369-c6dcfd1e3a5a', 92, 'Episode 2057', 'Gordon and Bob discuss letters of recommendation while Bob worries he''s not qualified to write one. Big Bird finds three things in his nest that start with the letter H and presents them to the viewers. Oscar shares his Grouch wisdom about avoiding doing dishes by using paper plates, while Maria and Luis play a guessing game identifying pictures of objects.

Sponsors: D, H, 2', '1985-03-26', NULL, NULL, '2026-04-03T17:36:36Z', '2026-04-03T17:36:36Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('5c6e4f77-968f-4472-8bc6-e1246be6015e', 'da06465b-9154-4feb-a455-374df7dab02f', 7, 'American Fruit Stand (4089)', 'Alan is busy receiving a big delivery at Hooper’s Store so Miles helps him out by watching the fruit stand.  Elmo and Zoe walk by talking about cookies and ice cream. All of sudden, Sesame Street is transformed into a 50’s musical show “American Fruit Stand.”  Miles sings “I Love Fruit” (to the tune of “I Feel Good”), a song about how good fruit tastes and how good it is for the body. Elmo and Zoe get so excited about fruit that they now want an apple and an orange!  Gina comes to the fruit stand and asks Miles for some peaches and pears.  Sesame Street is transformed once again and Miles sings, “Peaches and Pears” (to the tune of “Twist and Shout”).  Maria needs some broccoli.  It happens to be her lucky day because broccoli is a special guest star on “American Fruit Stand” and Miles sings “Broccoli is Good” (to the tune of “Johnny B. Goode”).  All of the fans and groupies become so excited about fruits and vegetables.  Alan’s business has never been so good.', '2005-04-12', NULL, NULL, '2026-04-03T17:36:44Z', '2026-04-03T17:36:44Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('5c724131-f118-4c0f-b134-6def62db0e65', 'd01919fb-98e0-42bf-b9d9-1cecf912f6e1', 26, 'Gordon Give Irvine a Bath (3811)', '', '1999-01-11', NULL, NULL, '2026-04-03T17:36:42Z', '2026-04-03T17:36:42Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('5c76afc2-7db6-4fba-9e46-b4d64b6d80f0', '51f03551-ba41-409d-85f4-e51bddfdf82e', 1, 'There''s a New Girl in Town', 'Season 2 lifts off with tension surrounding Jill, whose published interview incites a feud with Alex and Simon. Meanwhile, social butterfly Bethenny spends the summer in the Hamptons with Jill. And new housewife Kelly Killoren Bensimon is introduced.', '2009-02-17', 60, '/6pUwHvwKMEm4BZjlZDtYT5SkSji.jpg', '2026-04-03T16:35:22Z', '2026-04-03T16:35:22Z');
