INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('5c813610-6ff4-4cbb-84de-436f120b28cd', 'd1863f2f-02ec-40ce-af64-db03fbe518a7', 10, 'Say Thank You to Your Face Day', 'Elmo helps Abby, Grover, and Telly figure out how to say thank you to our nose, eyes, and mouth all at the same time. Also featuring Cookie Monster''s Smart Cookies, and Elmo''s World-noses. Brought to you by the letter F and the number 9.', '2016-03-12', NULL, '/qA2SVeBbM4HyyrG2DE1o2MfSkUD.jpg', '2026-04-03T17:36:48Z', '2026-04-03T17:36:48Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('5c8594de-7c8c-49c1-a843-f70fa3960b60', 'f0f8b366-cb33-40b3-a50f-a1ca7780916f', 13, 'Change of Address', 'Doc finally knows of the Fraggles, when he and Sprocket have to move. Will Gobo be able to relay the Trash Heap''s message ""You cannot leave the magic"" in time?', '1987-03-30', 24, '/qEu3WfmdrcXbgqtwyeG8dil2c0Y.jpg', '2026-04-03T17:35:01Z', '2026-04-03T17:35:01Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('5c86feba-9125-4550-8318-83d6fdad3903', '50ee8f6c-645c-4d48-bab9-53b9f8f7ff2f', 15, 'Cast Iron Cooks', 'Alan, Chris and Elmo are challenged to make stew with things that start with the letter "P".', '2011-11-18', NULL, '/436e7YZru4DO4VBfMjsTbV7Fqc5.jpg', '2026-04-03T17:36:46Z', '2026-04-03T17:36:46Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('5c89aa94-34e7-4193-9d27-2cd50fd1a3b6', '842c6419-ab98-4d34-8845-1d9782291aad', 5, 'Selflessness', 'Annie is looking forward to spring vacation until her mother asks her to help baby-sit her four-year-old twin cousins part of the time. At first, Annie balks at being selfless and sharing her time, until she learns the value of giving up something in the present to achieve a greater future good.', '1998-03-15', 30, NULL, '2026-04-03T17:38:34Z', '2026-04-03T17:38:34Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('5c9155c1-d625-4423-b4f4-0886a361331b', '204d86fb-d99c-4fd1-8dcd-9c1bcfd3c33f', 26, 'Head Over Heels', 'Quetzal tells the friends to deliver gazpacho (ice cold soup) to a sick Fernando, but they must pass a grumpy tollbooth troll named Trumpy who tells people that the only way to get over his bridge is to cartwheel. However, Emmy has trouble doing cartwheels, so Max and the dragons help her get better at them.', '2001-09-05', NULL, NULL, '2026-04-03T15:26:04Z', '2026-04-03T15:26:04Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('5c92c19b-ca0b-4abb-b001-43483b631136', '3fc7c152-e4f6-426a-a899-36ec454c4403', 25, 'Not Separated at Birth', 'Zak and Wheezie have had enough of always having to do what the other wants to do and wish they became separated from each other, so Quetzal gives them crystals that separates them. However, when they build a musical playground, they discover that they actually need each other more than previously thought.', '1999-10-06', 30, '/estcsZBFZzINddsDftO7ZRC1Oxo.jpg', '2026-04-03T15:26:03Z', '2026-04-03T15:26:03Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('5c942eeb-24eb-494e-b332-5f04094c902d', 'a84aa42d-e738-4081-8da9-1faec0209ee9', 5, 'The Block Party', 'After Brick’s teachers tell his parents that he’s “socially challenged,” Mike tries to help Brick make friends; while Frankie needs her son’s coveted football jersey.', '2009-10-28', 21, '/8pwAIhtockzqpDE2GNtxCN4dDRp.jpg', '2026-04-03T15:40:28Z', '2026-04-03T15:40:28Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('5c9a23c4-452c-45f2-b97f-9788155487cf', '3af7ea64-fa13-4097-b8e4-40af07083054', 26, 'Water Flowing and Stopping Pt 1', 'Rogers shows a film of his visit to New York to see François Clemmons. Later Rogers visits an oboist at Negri''s Music shop. Some in the Neighborhood of Make-Believe look for X''s OCS lesson. King Friday shows concern that his waterfall remain off most of the time.', '1974-03-25', 28, NULL, '2026-04-03T17:35:40Z', '2026-04-03T17:35:40Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('5c9b6af6-e2cc-420e-9296-0060a1e2346e', 'e03d79bd-e01f-4414-b0b3-f3b5f26e97f4', 2, 'Homecoming', 'Mike and Frankie must decide whether to attend Axl''s football game or Sue''s first cross-country meet; after raking the yard, Brick wants to set the leaves free in the forest.', '2010-09-29', 22, NULL, '2026-04-03T15:40:29Z', '2026-04-03T15:40:29Z');
