INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('5cb09b0d-25c3-4b78-b514-4487de80c2f2', 'd6092173-d23b-4449-baff-e0e16fe56c9a', 6, 'The Giving Peach', 'Cynthia grapples with the decision of whether to invite her father to the wedding, knowing that her mother will disapprove. Kandi organizes a food drive to help provide groceries to local families in need. Porsha feels uncomfortable with the news that Dennis may be in attendance at Cynthia’s wedding. In the aftermath of Ralph’s father’s passing, Drew is even more determined to fight for her marriage. Kenya decides it’s time for the group to take a much needed break.', '2021-01-17', 43, '/rTTjMgNf0FF43FdwOGrS4kfEtv0.jpg', '2026-04-03T16:34:49Z', '2026-04-03T16:34:49Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('5cbbbdc1-698c-4635-a205-3d078c810016', '3ee646e8-23ae-4dec-bbc6-c7e6a210d55b', 39, 'Snuffle puppet show', 'Big Bird welcomes the viewer to the latest Snufflepuppet show that Snuffy is putting on. The Snufflepuppet show continues, where Bob is about to conduct his band while Gus (now positioned on Snuffy''s snuffle) sings "The Alphabet Song.

Sponsors: G, P, 12', '1991-01-03', NULL, NULL, '2026-04-03T17:36:38Z', '2026-04-03T17:36:38Z');
