INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('5cd9f967-526d-4be4-92c8-28812a44e762', 'd0e5568d-939d-4d89-ab4e-c291a90691cf', 2, 'The Big Race', 'Kipper, Tiger and Pig decide to have a race. The prize is one of Pig''s chocolate cakes. Tiger goes on his tricycle and ends up in the duck pond but Kipper keeps running. Arnold gets a lift with Jake on his scooter. Guess who gets the chocolate cake?', '2000-10-05', 8, NULL, '2026-04-03T17:10:49Z', '2026-04-03T17:10:49Z');
