INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('5cdbdee0-9f46-4d73-bf75-fb7d85283584', '19e027c7-8626-44a9-96ba-d36b323b3a74', 10, 'Don''t Cry Over Spilt Milk', 'Gobo gets trapped in Outer Space when Doc boards up the hole in the wall.', '1983-03-14', 24, '/jNvgYr0Iw4jkEnPJcDwOmMeXO3z.jpg', '2026-04-03T17:34:59Z', '2026-04-03T17:34:59Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('5cdfb371-4376-4eaa-996b-6a405f273a21', 'c6d5cf79-f2b0-40af-ad12-91aa4f1b1d21', 8, 'Rick''s Big Check', 'The shop travels back in time when a map comes in from the late 1800s. Will Rick be able to navigate these negotiations, or will the seller take a hike? Then, Corey spots a killer Mustang for sale. Will he pony up the cash, or drive off without a deal? Next, Rick takes a ride to check out a collection of transistor radios. Can he tune into the right price? And finally, when Chum and Rick get their hands on some Magic the Gathering prototype cards, will they be able to enchant the seller?', '2022-06-25', 42, '/1m1b5axbKhJVZechTfi0XcXMQeT.jpg', '2026-04-03T16:34:23Z', '2026-04-03T16:34:23Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('5ce5e6fa-b0fb-46cd-8a82-a4138bb213b3', 'f6015d9a-ece4-414a-a00b-06cf689fe40b', 17, 'Has Got it All!', 'This episode of Blue Peter has got it all. It''s jam-packed. In fact there is so much in it, we''ll struggle to tell you about it all right here. Especially when we spend so much time talking about how much is on the show. Oh, we''ve run out of space now. Watch it!', '2018-04-19', NULL, NULL, '2026-04-03T17:22:10Z', '2026-04-03T17:22:10Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('5ce971ff-d975-4774-a20c-ffb716223574', 'a8c6182e-05e1-4b68-91a5-5126cf6c94f0', 6, 'The Shot Heard Round the World', 'James, reporting on the Minutemen, and Sarah, falling in with the British forces, report from both sides on the ""shot heard â€˜round the world"" at Lexington. They each leave the scene fearful of what the future will bring though James is caught up with the romanticism of fighting for liberty.', '2002-09-09', 30, '/dH7yrHfJnWH6IwpDYkfwwm8ziRS.jpg', '2026-04-03T17:38:28Z', '2026-04-03T17:38:28Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('5cea63b5-b05a-478d-8077-7643f584177b', '05044f49-5f9c-4e7f-a74d-b2ff19475d0e', 21, 'Teresa Checks In, Part 2: Mr. Mom For Shore', 'The family goes on a trip to the Jersey Shore to visit their previous home, possibly for the last time. Joe talks to a friend who has been to a prison. The Giudice family celebrates Independence Day with the Gorgas.', '2015-10-18', 43, '/lpbax6rf415jKrHKSDOvzMLPQCy.jpg', '2026-04-03T16:35:16Z', '2026-04-03T16:35:16Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('5cece5c6-577d-4c2a-ba59-df219d1e2cdd', 'dbde6570-a68d-4fd7-a1b0-a6037a266a18', 17, 'Monkey Business', 'The tension in Costa Rica continues, forcing Alexis to leave early after the group gang up on her and the remaining ladies go white water rafting, with the experience resulting in Vicki having an emotional breakdown.', '2012-06-05', 44, NULL, '2026-04-03T16:35:31Z', '2026-04-03T16:35:31Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('5ced5c2a-21ed-4a9b-a023-5ba04f2c9667', 'ea73e13c-6962-4804-8305-c303df65f89f', 41, 'A visit from Mabel Mercer', 'Mabel Mercer arrives in the Neighborhood of Make-Believe with a costume changer for Lady Aberlin.', '1969-04-07', NULL, NULL, '2026-04-03T17:35:38Z', '2026-04-03T17:35:38Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('5cf09802-cc2c-4a4a-827c-3b991dc319a8', '0fb5ce65-0258-4423-be8a-f7ba9c37bb6b', 1, 'The Hot Potato', 'The kids learn how to cook potatoes outdoors, but their hunger gets the better of them. Meanwhile, fire team is introduced to the new Jupiter.', '2023-10-21', 9, '/d79hTdWkAdb4EjZcRF52D6tKSMH.jpg', '2026-04-03T17:14:42Z', '2026-04-03T17:14:42Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('5cf662a3-3db0-4047-a1a1-9e5c6634a160', '05c0e384-194c-4417-9f62-803eb615e409', 79, 'Calling Sara Saturday', 'Title number 0079. Opens with Mister Rogers arriving with an empty box from which he pretends to make a phone. King Friday gets advice on how to contact Sara Saturday. Once she is reached, Sara invites him to visit her at her home.', '1968-06-06', 28, NULL, '2026-04-03T17:35:38Z', '2026-04-03T17:35:38Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('5cf87b57-60d8-498f-99ff-4b09f2983060', '3fc7c152-e4f6-426a-a899-36ec454c4403', 6, 'Ord''s Unhappy Birthday', 'It’s Ord’s birthday, but his friends don''t have time to play with him. Feeling sad, Ord seeks out Quetzal who tells him to share his feelings with his friends. Afterwards, everybody gives him the best birthday ever, and little did he know that his friends were planning to make a surprise party for him.', '1999-09-08', 30, '/pdRbDgKQkiIiMP8uTAxBjbbgYAf.jpg', '2026-04-03T15:26:03Z', '2026-04-03T15:26:03Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('5cfcc7ee-ead5-4c77-8fb8-6b84bc0948d6', '91f66da7-56a2-423a-b855-f09d582805b2', 10, 'Making Bread & Cheesybreadville', 'Theo Lion tried to make bread; another bread-baking disaster results in a tasty treat.', '2007-11-19', 30, '/npTTB9QyvCTRyH2NjSzVdJT7vsN.jpg', '2026-04-03T17:12:29Z', '2026-04-03T17:12:29Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('5d01e755-c8c3-44ce-8608-e4730f9a0e48', '4d2cac0f-38fd-438b-8afa-acf43952e535', 366, 'Episode 366', 'with Christopher Trace and Valerie Singleton.', '1965-06-03', NULL, NULL, '2026-04-03T17:21:47Z', '2026-04-03T17:21:47Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('5d025a4c-5e38-49db-b624-4bd7913b5fc5', '7b8e3988-fbf3-4cfc-aeb2-782ae5a64e2d', 39, 'Three Cheers for Us', 'Elmo tries to bounce his ball three times, and Zoe the cheerleader cheers him on.', '2010-12-13', NULL, '/180W6eVsssIHtIqVvn1wxfEc6Id.jpg', '2026-04-03T17:36:46Z', '2026-04-03T17:36:46Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('5d03528b-5931-4639-bc01-9c04a11bd1f8', '9193e795-da7c-40ec-b68f-f63aa7d5174f', 17, 'The Game Revealed: Season 6 Episode 3 & 4', 'The Game Revealed: Season 6 Episode 3 & 4', '2016-08-01', 60, '/9xvP14MhH9OVL8SE5In4ggvZ3b4.jpg', '2026-04-03T15:40:35Z', '2026-04-03T15:40:35Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('5d05a9e3-362d-4e7b-a8f0-99d86dccfe32', '3982796b-5451-4100-9042-46bedf6a20a5', 10, 'Pingu''s Outing', 'It’s early in the morning and Mother is putting things in a pack for Pingu. She goes to wake him, and tells him to be quiet so as not to wake Pinga. Pingu goes to the bathroom, while Mother makes him breakfast. When Pingu comes out of the bathroom he lets the door slam behind him, which wakes Pinga up. Pinga cries, and is comforted by Father. Pingu eats his breakfast and leaves, carrying his pack. The family wave him goodbye. On his journey Pingu asks the way from an artist, who is out painting the sunrise, and the baker, where he’s given a free pastry. A delivery man on a motorised sledge passes him, and a package drops off the sledge. Pingu calls out, and the delivery man comes back for the package, and then gives Pingu a lift. He’s dropped off at a signpost where he has to go one way and the delivery man another. When he reaches his aunt’s home she greets him at the door, and he eats nearly all of the large meal she’s prepared for him. He’s nearly asleep on his feet, so his aunt suggests he go to bed, but he’s feeling homesick. His aunt offers him a doll to take to bed with him but he doesn’t want it, so she phones Mother. When he speaks to Mother Pingu immediately cheers up, as Mother has put his teddy bear in the pack he brought with him. He goes to bed, and falls asleep during the story his aunt is reading to him, cuddling his teddy.', '1993-03-02', 5, '/vGWSBfoEdvEvTZ56pjnJAeQRSlW.jpg', '2026-04-03T17:22:19Z', '2026-04-03T17:22:19Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('5d0f560a-146a-4687-856d-941635791fcd', '4bf3b194-81b8-4726-8850-62b05609eac8', 21, 'Hiccups', 'Tomsk and Bungo get hiccups after eating hot buttercup crumpets.', '1975-10-13', NULL, NULL, '2026-04-03T17:23:20Z', '2026-04-03T17:23:20Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('5d143782-81f2-4de2-9701-70a17569bec5', 'ca19f895-1514-4988-a709-95e84eab7cee', 22, 'Rick''s Big Triumph', 'When a chandelier made out of KFC buckets lights up the shop, does Corey''s future look bright, or will he get fried? Then, Rick gets revved up over a very special motorcycle. But will he come out of the negotiations triumphant? Next, Chum tries to talk his way into buying a vintage Teddy Ruxpin doll. But will a lowball offer even bear considering? And finally, Corey loses his head over an eerie artifact that has a strange resemblance to Chum.', '2021-08-28', 42, '/rfOfO2axskRRNiInNo3ZaoL7DVi.jpg', '2026-04-03T16:34:22Z', '2026-04-03T16:34:22Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('5d154e36-02d3-41d4-a097-5fc421ea6edc', '136b81d3-964d-4b8f-a214-92f00d96d6b9', 88, 'Episode 1923', 'Big Bird and Telly search the entire neighborhood for Snuffleupagus''s missing toy, asking every resident they encounter for help. The friends work together cooperatively and ultimately locate the lost item. Snuffy expresses his gratitude for their kindness and their unwavering friendship.

Sponsors: B, G, 3', '1984-03-21', NULL, NULL, '2026-04-03T17:36:35Z', '2026-04-03T17:36:35Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('5d18f40d-4726-4a85-be9b-90a6899f2805', '842c6419-ab98-4d34-8845-1d9782291aad', 1, 'Trustworthiness', 'When Zach discovers that his college football idol is coming to his school, he eagerly volunteers to help with the preparations. But when he’s asked to clean up the auditorium, Zach wants to back out, prompting stories from Aurora and Plato about what it means to be trustworthy.', '1998-02-15', 30, NULL, '2026-04-03T17:38:34Z', '2026-04-03T17:38:34Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('5d1fef33-9bd5-4343-9681-0d3d4d46e03a', '54c29014-2dbd-49ff-a23f-cf4c546e0b3a', 17, 'Bury the Hatchet', 'Heather and Kristen continue to clash, forcing some of the women to take sides. Elsewhere, the ladies take in a rodeo show and a final outdoor Montana dinner.', '2014-07-01', 60, NULL, '2026-04-03T16:35:23Z', '2026-04-03T16:35:23Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('5d227c29-9122-46be-98b9-248127ebf1bb', 'ceb4c48c-6260-40df-a265-c9fbfa7885f9', 2, 'Brain and the Time Capsule', 'Brain creates a time capsule but soon he gets frustrated when everyone wants to put something in.', '2017-10-24', 13, NULL, '2026-04-03T17:38:02Z', '2026-04-03T17:38:02Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('5d227f30-1b2b-4902-8e25-0bc36b9f8015', '3ade5e1f-8441-4c2c-acf6-fb933a61dcfa', 18, 'Mom''s the Word', 'Robyn and Juan make a grand gesture to solidify their relationship. Candiace begins making financial strides without her mother’s help. Karen finally reveals her La Dame perfume with an extravagant soirée, but the ladies leave with more questions than answers. After taking a pregnancy test, a fearful Ashley visits her doctor.', '2019-09-08', 42, '/3CzIzO604erdkgiT95UuhPXRjbL.jpg', '2026-04-03T16:35:39Z', '2026-04-03T16:35:39Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('5d267200-e276-4951-bef0-cd49d4d59f32', '4f18ac4c-8757-456c-a49a-224f00e6a9f7', 26, 'Baby Bear''s New Baby Sitter', 'Baby Bear is very excited because Grandmama Bear is coming to baby-sit. They have so much fun together! Just as Baby Bear is telling Gina this, Papa Bear breaks the news that Grandmama is sick and won’t be able to come. Baby Bear’s spirit is crushed. Gina suggests that they ask Gabi to baby-sit. It turns out that Gabi would love to do it. Even though Curly Bear is very excited and doesn’t seem upset at all, Baby Bear feels that his sister might be nervous with a new baby-sitter.', '2008-11-07', NULL, '/wLUTi2ObkllCKyte6sKXkHwlioq.jpg', '2026-04-03T17:36:45Z', '2026-04-03T17:36:45Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('5d295431-928b-45e3-ba10-5b5af6e209f4', 'e6359e6d-9bdb-4aba-9cba-6f7ddd6328f9', 2, 'Diva Las Vegas', 'Teddi''s job as an accountability coach leads to questions amongst the group. Lisa Vanderpump takes Erika to task for not responding whenever she reaches out. Kyle and Dorit confront Lisa Rinna while on a Ferris wheel overlooking the Las Vegas strip.', '2017-12-26', 43, '/wmeGnavtcxOR9KR7Uu6F6RQw04O.jpg', '2026-04-03T16:34:57Z', '2026-04-03T16:34:57Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('5d298040-a94a-45e3-a6f6-eccb186fa46a', 'eb7e3bb4-5746-4577-81c6-f5b2dc2efc6e', 2, 'The Cave of Two Lovers', 'On their way to Omashu, Aang, Katara, and Sokka meet a group of nomads who show them a shortcut through the "Cave of Two Lovers". But when the group becomes trapped in the cave, it''s up to Aang and Katara to save the group by trusting in love, possibly questioning their relationship. Meanwhile, Iroh gets a lethal rash so Zuko and Iroh head to a small Earth Kingdom town for help, hoping their real identities will not be discovered.', '2006-03-24', 25, '/nnXvDDSFUylD6SS7bpm1PXaNUbe.jpg', '2026-04-03T17:40:48Z', '2026-04-03T17:40:48Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('5d29a296-4206-40a0-ae1a-f247d1406f9b', '8730c55e-8443-44b0-afef-a369c478b14f', 51, 'The Boo Boo Song', '', NULL, NULL, NULL, '2026-04-03T15:26:09Z', '2026-04-03T15:26:09Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('5d2b3df3-74a7-4c17-8e5a-1d5ac1567fdb', 'abeb8d07-5c86-4f6a-a110-b11cba2a4138', 7, 'The Runaway', 'When Katara expresses her disapproval of Toph''s new way to make quick cash, the group finds her too motherly and tension grows between Katara and Toph. When Katara finally decides to participate in this scam to disprove Toph''s accusations, they are left vulnerable and are forced to face the dire consequences.', '2007-11-02', 24, '/8gymKiOEJNYZPVScLRVUhNuYgCj.jpg', '2026-04-03T17:40:48Z', '2026-04-03T17:40:48Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('5d2f8193-9eee-4bd5-8bb2-aecd23070600', '1be79a20-de33-41d1-af17-079035b18d5c', 103, 'Episode 103', '', '1970-04-01', NULL, NULL, '2026-04-03T17:36:28Z', '2026-04-03T17:36:28Z');
