INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('5d3240e6-a768-44bb-838b-14ef314cf8bd', '573fa62f-55a9-4f17-97cc-d1a005a83cc8', 18, 'A Bulldozer''s Unlucky Day', 'When Lucky gets upset about making mistakes on his first day as a bulldozer, Big Bird and Nina teach him that it''s okay to make mistakes.', '2025-05-15', 26, '/t0viwoWhld100g4HKOVCLrvxiva.jpg', '2026-04-03T17:36:52Z', '2026-04-03T17:36:52Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('5d329635-7a6c-4e03-a119-2105da7b7e45', 'bf0f7445-f58f-467f-a81b-fcc2bf6bca21', 7, 'Mokey and the Minstrels', 'Mokey decides that she wants to be a minstrel.', '1984-02-13', 24, '/diUuNW830uvWzjLQDssVuUuNNBq.jpg', '2026-04-03T17:35:00Z', '2026-04-03T17:35:00Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('5d3c57b2-eb37-4b45-8fcf-5fbc37962e95', '9d74600d-7222-47c1-bd1b-635f5b41b7d1', 2, 'Alistair in Outer Space', 'Alistair is on his way to return library books when he is captured in a spaceship by two creatures called Goots. Also includes Library of Congress, Maps and Globes, Conan the Librarian, Book Care and Repair and book reviews for Check it Out! The Book about Libraries, Commander Toad and Maps and Toads.', '1986-06-24', 30, NULL, '2026-04-03T17:36:15Z', '2026-04-03T17:36:15Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('5d4176c2-a32b-437b-aa3b-7c79351912bc', '1e085f65-4b69-4500-8ffc-654d2f638dbb', 19, 'Bert and Ernie''s Opposite Day', 'On Opposite Day, everyone is doing things that are as different as they can be. Bert and Ernie realize they like so many opposite things too!', '2024-03-14', 26, '/ofZzGSfthsHNdv5btzc4CzoogW.jpg', '2026-04-03T17:36:51Z', '2026-04-03T17:36:51Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('5d426197-3417-46d1-9c49-7c95463901d1', '04fb713d-9c59-45f7-8de0-acd7582daa53', 13, 'Camels, Cabo & Catfights', 'As the Cabo trip continues, Teresa reveals her true feelings about Joe returning home; the ladies are forced to take sides after Margaret throws out shocking accusations about Jennifer. Danielle tries to get Teresa on her good side.', '2019-01-30', 43, '/lbpBVU6cz7FrCtZQX7JavbMiBF9.jpg', '2026-04-03T16:35:17Z', '2026-04-03T16:35:17Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('5d4569c7-3d76-4f9c-bd60-cc79a046bec8', '1d39506b-06b8-4f93-9136-0208069bd7e4', 16, 'Reunion (2)', 'The women speak on the various fights during fashion week; Sonja joins the rest of the cast where she discusses her time on the show; Kelly attempts to defend herself against allegations that she had a mental breakdown in St. John''s.', '2010-06-14', 43, '/pMon1efP3le0rXOpuP9PREi8GAw.jpg', '2026-04-03T16:35:22Z', '2026-04-03T16:35:22Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('5d47a4dd-afba-4c42-b04d-8842fe53d8e8', '04e133fd-c4a3-4dfa-8369-c6dcfd1e3a5a', 71, 'Elmo plays hide-and-seek with Oscar', 'The library opens fresh and clean after Linda and Micki arrive early to tidy up from the night before, revealing their shared appreciation for the orderly space. When Oscar grows tired of Elmo''s constant pestering, he suggests a game of hide-and-seek to get some peace. As Oscar realizes he''s actually worried about Elmo being lost, he''s surprised to find that Elmo returns to help him search instead.

Sponsors: D, H, 6', '1985-02-25', NULL, NULL, '2026-04-03T17:36:36Z', '2026-04-03T17:36:36Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('5d4bc740-35f0-4bd0-8e5d-3be9c1d17f3d', '7a83ec7f-6f29-4aad-80a1-49cd578555b8', 2, 'How Orbie Helped the Easter Bunny / Stone Cold Soup / Orbie''s Wish', '', '1995-05-05', NULL, NULL, '2026-04-03T17:11:21Z', '2026-04-03T17:11:21Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('5d4d227b-7239-4058-976b-374398a2a551', '05044f49-5f9c-4e7f-a74d-b2ff19475d0e', 20, 'Teresa Checks In, Part 1: Tre of Life', 'The family celebrates its important events for the first time without Teresa. Joe and the girls get help and support from their relatives, including Melissa Gorga and Rosie Pierri. Teresa calls her family and sends daily e-mails.', '2015-10-11', 43, '/76E4HxLjEdX56AU528sxRE1Dv1B.jpg', '2026-04-03T16:35:16Z', '2026-04-03T16:35:16Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('5d571999-400a-4b05-bfd1-2686800bde8b', 'c9d2b3fb-7845-4f3c-9847-ce1f7717257a', 12, 'Sign of the Times', 'Rick partners up with Rick Dale to prove to Corey that he struck oil with an old Gulf sign; an old 1930s collectible from the Indy 500 sends Chumlee racing; Corey snoops out what might be a Charles Schulz original illustration of Charlie Brown.', '2019-06-10', 42, NULL, '2026-04-03T16:34:21Z', '2026-04-03T16:34:21Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('5d6057d6-aa19-414e-971c-9ec7d883988e', '1d556682-d9bb-47e1-993f-0b648a8daacd', 98, 'Episode 1283', '', '1979-04-11', NULL, NULL, '2026-04-03T17:36:33Z', '2026-04-03T17:36:33Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('5d62dff8-6dd1-4249-9738-0365af9d3fe3', '6053b5c1-ce86-425c-8166-e0fcc3466061', 41, 'Episode 41', 'with Valerie Singleton, John Noakes, Peter Purves', '1970-02-05', NULL, NULL, '2026-04-03T17:21:50Z', '2026-04-03T17:21:50Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('5d637c53-b96c-4f84-8b98-c4233a701ee1', '941b8c65-4454-4336-be7c-1d0591c12f90', 23, 'Pingu and the Doorbell', 'Pingu and Pingo are playing with a ball outside Pingu''s house. Pingu kicks it into the doorbell, which rings. As Mother comes out Pingu hits the bell again. She tells Pingu not to hit the doorbell with the ball, but instead just press it. They continue playing, and the ball hits the doorbell again, this time breaking it. Pingo runs off with the ball, leaving Pingu behind to take the blame. Mother, Father and Pinga come out, and Pingu tries to hide the damage to the doorbell, but Mother is not fooled and tells him to get it fixed. The rest of the family go off, and Pingu tries to fix the bell by pushing it together, but it comes apart again. He tries to fix it with sticky tape, but this also doesn’t work. Pingu angrily takes the broken bell off, and goes to the shop to get a new one. He finds all sorts of doorbell at the shop and settles for a trumpeting, yodelling one, and installs it when he gets back home. When his family return and go inside he keeps pressing the new doorbell, causing a lot of vibration, noise and disturbance. Father comes out to find the culprit. Pingu takes the new doorbell off and returns to the shop with it and the old one. He trades the noisy new one for a replacement button for the old one. When he gets back, he installs the repaired doorbell, and his family are pleased to have it fixed. Pingo, who heard the noise earlier, then returns and throws the ball into the doorbell. Mother tells him off and he contritely sits on the ball, but it promptly bursts under him.', '2004-02-03', 5, '/a73SwsigBXSADpAKrwPW1ayDeoU.jpg', '2026-04-03T17:22:20Z', '2026-04-03T17:22:20Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('5d67ce53-b23d-40f2-8103-1881c426599f', '5046642d-462d-4eb0-8194-0bbd7962af0f', 11, 'BabySitter In DeNile', 'Laura Carrot portrays Miriam, who wonders why people in the village refuse to acknowledge that her new baby brother Moses is a boy. She is forced to look after the baby because her parents and elder brother Aaron are working in the brickyards. She finds babysitting tougher than she thought and complains about her plight. But when Aaron is almost run down by a chariot, she learns the value of family. Once she learns that the Egyptians are taking away all the Hebrew baby boys, Miriam decides to hide Baby Moses in the Nile River. After he is plucked out of the river by Pharaoh''s daughter (Miss Achmetha), Miriam offers to have her family care for the new prince.', '2006-11-10', 30, '/sLicZDWFifaFYmBECMx7ez3JmO2.jpg', '2026-04-03T17:39:38Z', '2026-04-03T17:39:38Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('5d6b9817-bc2d-4e71-8595-c2ba3186753c', 'ceab3d79-abbe-47fb-b8b3-3073fccb1ec7', 2, 'The Jerrick Trap', 'Rick teaches Jerry that he works smarter, not harder.', '2023-10-22', 23, '/nPcoJ8K1TPhFwCDTZRIKBPv8IyH.jpg', '2026-04-03T15:40:43Z', '2026-04-03T15:40:43Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('5d7b1bcc-2a02-472f-98ef-c6db9066129a', '3fdccc2c-e563-42fb-8874-c93879cd4141', 17, 'Checklist', 'Bitzer over-officious management style becomes too much for the sheep who decide it''s time for him to chill out. Bitzer''s tasks for the day take on a new purpose, for everyone to have some fun!', '2016-11-15', NULL, '/zJ5VPCRpdYQpvUJbqKKBFTz8peq.jpg', '2026-04-03T17:39:32Z', '2026-04-03T17:39:32Z');
