INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('5ebb94ed-772c-49f0-90dd-377c3038cf3d', 'a84aa42d-e738-4081-8da9-1faec0209ee9', 11, 'The Jeans', 'A hormonally charged Sue wants a cool pair of jeans in order to fit in with her peers, resulting in Frankie and Mike enduring the unpredictability of teenagers, while Axl wants a car to impress a girl. Meanwhile, attempting to teach Brick about responsibility, Frankie and Mike reluctantly allow him to take care of Aunt Edie and Aunt Ginny''s dog Doris for a few days.', '2010-01-06', 22, '/s6Fe5NeAxicpSIn4YOe7S4SNkCx.jpg', '2026-04-03T15:40:28Z', '2026-04-03T15:40:28Z');
