INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('5ed1a742-7623-4f21-b711-89df1efba39e', 'cb8a0322-be77-485b-b339-bdd572bca349', 11, 'Binky Rules', 'Someone has been writing "Binky Rules" all over Lakewood Elementary and Mr. Morris thinks it is Binky.  Binky says he didn''t do it, so Fern and Buster are trying to find out.', '1998-11-23', 13, NULL, '2026-04-03T17:37:56Z', '2026-04-03T17:37:56Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('5edcef4e-8752-4b6e-8553-bfd3de39bea1', '0442fb97-1460-4923-8558-b994078dc6b8', 8, 'Serving up Betrayals', 'Ashley confronts Michael about the blog rumors; Gizelle gathers the ladies together for a wine tasting to celebrate her literary award, but the celebration is quickly halted when tension escalates to an alarming level.', '2020-09-20', 42, '/hTXfdKfQS9usiLIpE77zqPoVRAg.jpg', '2026-04-03T16:35:40Z', '2026-04-03T16:35:40Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('5eded463-ee04-418a-8d9b-d8dce0e63d18', 'd1d267dd-e27f-4543-acb8-0d28f676512a', 5, 'Episode 5', 'with Valerie Singleton and John Noakes', '1967-10-12', NULL, NULL, '2026-04-03T17:21:49Z', '2026-04-03T17:21:49Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('5ef000c0-6720-46c7-b410-e00643557d76', 'acac417e-2aa3-42e7-9e08-ed0d6071a3ee', 10, 'You Broke the Penal Code', 'Two weeks after Luann''s surprising arrest, she is still the talk of the town. While she''s in rehab in Palm Beach, the ladies try to piece together what happened. Bethenny throws a launch party for her new jeans line, and later meets Carole for lunch to try and resolve their dispute. Sonja flees her construction site and spends a night with Tinsley. Dorinda takes the initiative to check-in on Luann in rehab.', '2018-06-06', 60, '/4YwJzTpmS0sNwaF7sDeuaWGAAOo.jpg', '2026-04-03T16:35:25Z', '2026-04-03T16:35:25Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('5ef092a1-2ea2-4171-8ff7-7b30eafdb1f5', '6fd9fd9d-e378-411b-94b1-76ba4bd518fe', 75, 'Episode 75', 'with Christopher Trace, Valerie Singleton and John Noakes.', '1966-06-13', NULL, NULL, '2026-04-03T17:21:48Z', '2026-04-03T17:21:48Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('5ef2e257-beca-4c50-a934-72ccabe4cdd1', '0f64bf9f-8d05-4f5b-9a57-5d0c44ac3f40', 10, 'Chaos in the Cul-de-Sac', 'The Browns set out to celebrate the judge’s decision to allow Kody to adopt Robyn’s first three kids. What starts as a simple party for family and friends turns into a huge event for 60 people.This is the famous "Brown chaos" at its worst...and best.', '2015-11-01', NULL, NULL, '2026-04-03T16:34:29Z', '2026-04-03T16:34:29Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('5ef326b4-c58b-4952-9208-e2547b81c45b', '6f323ed7-50f3-4902-a8b2-2072c5d0489b', 5, 'The Demon Headmaster (Part Five)', 'Dinah arrives at Vulcan Towers, where the final of Octopus Dares is to be played. Lloyd and Harvey worry about Dinah''s safety and look to save her.', '1996-01-16', 25, NULL, '2026-04-03T17:40:34Z', '2026-04-03T17:40:34Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('5ef6267a-729b-41b6-b42b-1e3838b00e65', '227b8429-0dfd-47e4-b874-c37da20c403f', 9, 'Rope a Dope', 'The Pawn Stars look to buy a 1929 Chopped Ford Coupe but if they can''t agree on a price, will the deal end up rusting in the bone yard? Then, a cowboy wants to sell his mechanical calf-roping machine. Can Corey rein it in without Chumlee spooking the sale? And when the prettiest pawn shop employee continues to be tardy, Rick and the Old Man dish out a fitting punishment. But is it enough to teach her a lesson?', '2009-08-23', 21, '/hk7oY07QoG1iw1C6xXGNhJmaYNd.jpg', '2026-04-03T16:34:15Z', '2026-04-03T16:34:15Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('5ef717c5-50bf-4a07-bec6-8b06bd5b6597', '04fb713d-9c59-45f7-8de0-acd7582daa53', 17, 'Reunion Part 2', 'Jackie and Teresa''s argument boils over; Joe and Melissa defend themselves against Teresa''s accusations; Jennifer defends her parenting and her marriage; Teresa shocks Andy and the ladies when she reveals her true feelings about Joe''s deportation.', '2019-02-27', 43, '/81JYq0ghHIIdJoemGtjcD5MZNrl.jpg', '2026-04-03T16:35:17Z', '2026-04-03T16:35:17Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('5efc586e-a53f-4995-9d35-3e3f60cb8fc7', '79c831cf-2837-48fe-9e27-059281dc30de', 18, 'One Man Band', 'A one-man-band busker loses his drum when it falls into the canal so Rosie and Jim secretly help him get it back.', '1998-03-06', 10, NULL, '2026-04-03T17:19:38Z', '2026-04-03T17:19:38Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('5f013064-0a63-4dfe-b67e-e0f132eb77a4', '5704fb3f-fbbc-4177-88b0-9226373a9d4e', 45, 'Episode 45', '', '1966-02-11', NULL, NULL, '2026-04-03T17:20:12Z', '2026-04-03T17:20:12Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('5f07a384-e273-4013-a6f1-dfe1781d7372', '0e419615-4c96-4dde-8ed2-715770ba77bb', 6, 'When Harry Met Hallie', 'Harry visits the Big Blue House with big news --- his Mama has laid an egg and it''s going to be hatching really soon! Everyone in the Big Blue House is excited about the hatching. They pay Mama Duck a visit, but then return to the Big Blue House to give her some peace. Harry is excited at first to be a big brother, but doubt begins to creep in when the kids at the Big Blue House tell him some of the things they''ve heard about babies. It starts to seem like there isn''t going to be any time for him. He recalls their predictions as Doc Hogg unconsciously talks him out of his favorite toy and Treelo draws a picture -- not for him, but for the baby. 

Songs 

Lucky Day, Ducky Today 

Someone to Look Up to You 

Notes 

Harry''s little sister, Hallie, is born in this episode. Mama names her this after her babushka, Halinska. 

Allusions 

The title of this episode references the film When Harry Met Sally 

Harry''s favorite toy, Swanny, performs a tune with lyrics that are a riff off of the Irish folk tune "Danny Boy."', '2002-11-04', 25, NULL, '2026-04-03T17:35:32Z', '2026-04-03T17:35:32Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('5f09e396-7677-46e1-8b1b-f93a1ae71437', '319bd5d6-ff58-426f-b9da-a0bb2cb87b02', 9, 'Ocean Exploration', 'Ocean exploration is a tricky, risky business since humans can’t naturally survive under the ocean. Ocean explorers are constantly inventing new tools to help them dive deep into the sea. Over the last few hundred years or so, and especially in the last few decades, we humans have come up with all kinds of new ways to study the ocean. Even so, the ocean remains largely unexplored. It’s huge, cold, salty, and deep. Ocean exploration helps us understand our planet, and may help us solve the mystery of how life started on Earth.', '1997-12-05', 26, '/jBZn17Ai8K2uqu42qmo7G3wWVBP.jpg', '2026-04-03T17:37:22Z', '2026-04-03T17:37:22Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('5f0db30f-c4f5-4d8a-8c41-214d09bf487b', '9193e795-da7c-40ec-b68f-f63aa7d5174f', 53, 'The Game Revealed: Season 8 Episode 5', 'The Game Revealed: Season 8 Episode 5', '2019-05-13', 35, '/e6yQWYyccFQumNxPT88xI04wIGI.jpg', '2026-04-03T15:40:35Z', '2026-04-03T15:40:35Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('5f0eaa99-21ef-4f07-ae02-a123df0343a6', 'f9a8d8b3-d72e-437e-a9d5-7477f6d64df8', 27, 'Recycling Fairy to the Rescue', 'Redusa the Recycling Fairy helps everyone on Sesame Street recycle their old trash to help keep the earth clean and beautiful.', '2023-05-04', 26, NULL, '2026-04-03T17:36:51Z', '2026-04-03T17:36:51Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('5f0fc33c-cee0-4704-a6ad-5b03a12fa888', '7bc54df3-f32a-454e-aef6-a9436c35d53b', 40, 'Episode 40', 'Handyman Negri is among those with a gift for the baby Platypus. It''s a song to fit her Latin name, Ornithorhynchus anatinus.', '1970-03-27', NULL, NULL, '2026-04-03T17:35:39Z', '2026-04-03T17:35:39Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('5f108653-6e7d-442c-a1e9-1c435c89d7ad', '1a8f02c5-f727-4ce3-9bb2-5946d236e47c', 5, 'Chapter Five: Shock Jock', 'The gang hatches an electrifying plan to reconnect Will to the hive mind. Tensions flare during a search of the Upside Down''s Hawkins Lab.', '2025-12-25', 69, '/A9gML0mmuyE2m3hGK0eZZA2tRPg.jpg', '2026-04-03T15:40:40Z', '2026-04-03T15:40:40Z');
