INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('5f15c248-b937-427e-aaa1-c69bf9501015', '9e30a416-edbd-490b-bb0f-18d5c45f0bdf', 22, 'Reunion (3)', 'The women continue to try to hash things out with Lisa, while the husbands join the fray, as Ken defends his wife.', '2014-03-31', 42, '/7q22WW64vH1JMSKszLDqiXNewYa.jpg', '2026-04-03T16:34:55Z', '2026-04-03T16:34:55Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('5f1f8421-24b4-45c0-9b9d-9817c734c31b', '4d2cac0f-38fd-438b-8afa-acf43952e535', 336, 'Episode 336', 'with Christopher Trace and Valerie Singleton.', '1965-02-15', NULL, NULL, '2026-04-03T17:21:47Z', '2026-04-03T17:21:47Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('5f1fa699-8de8-4ae2-99a7-03d4477beebf', 'd5f0284f-0ee3-45bf-8539-d02a825d15b2', 5, 'A Night at the Opera', 'Adriana receives a therapy treatment and has an emotional out-of-body experience. Guerdy discovers that Larsa betrayed her trust. Julia hosts a F Cancer party in honor of Martina''s recovery, but Lisa is held up by the police.', '2023-11-29', 44, '/gv7J9l4CLgVZ1V5rdTdrEDJXRO1.jpg', '2026-04-03T16:35:12Z', '2026-04-03T16:35:12Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('5f295a78-03e6-43a6-8c9b-a194999a82a5', '1d39506b-06b8-4f93-9136-0208069bd7e4', 14, 'Rebuked, Reunited, Renewed', 'Jill and Bethenny at long last trying to end their feud. Meanwhile, LuAnn performs her single at a record-release party---but the wives are more interested in her new French boyfriend. Finally, the gang gathers to witness Ramona renewing her vows with Mario.', '2010-06-03', 43, '/vQwiQJ6gg2PFIDEpHh5C7u9PuKc.jpg', '2026-04-03T16:35:22Z', '2026-04-03T16:35:22Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('5f2be6b4-921d-4f29-8fa4-8ee0be77c9a5', 'd5383b3d-5636-4d71-b99c-b84774b4b3c6', 8, 'Pingu the Archer', 'Mother is cleaning and Pingu is playing when the phone rings. Mother asks Pingu to answer it; it’s Grandfather, who has found a bow and arrows outside his igloo. Pingu rushes over, and Grandfather gives him the bow and arrows. Pingu excitedly fires one into the air. Grandfather makes a target to aim at and suggests Pingu shoots at that. Pingu shoots and misses. He shoots another arrow and misses again. Grandfather tells Pingu to practice and goes inside for a cup of tea. He sits down to enjoy it, but he hasn’t seen Pingu’s mischievous look! Suddenly an arrow hits an apple in the fruit bowl, which is on the table in front of him. Then another arrow breaks a window. Grandfather is not amused and turns to go outside; a third arrow hits him on his behind. He phones Mother, angrily tells her what Pingu has done and sends Pingu home. When Pingu arrives home Mother is waiting, and takes the bow and arrows away from Pingu. Thinking to try and cheer him up, Mother asks Pingu to tidy up the firewood that is lying scattered around next to the igloo. She takes the bow and arrows and goes inside, leaving Pingu to get on with it. Pingu unhappily goes across to the wood to start, and then has an idea! He takes the broom, which is being held by the snowman, and uses it to quickly sweep all the wood into a neat pile. He then flicks the broom into the air and balances it on his beak, and starts to dance around. Mother comes out to see how Pingu is getting on, and is surprised to see the job done and Pingu dancing. Pingu finishes his dance, and flicks the broom back to the snowman. Mother claps, and gives Pingu a hug.', '1998-01-14', 5, '/wkQDphYCQ18FSXDdiWvvtjZHQ9X.jpg', '2026-04-03T17:22:20Z', '2026-04-03T17:22:20Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('5f2f5b5d-555e-4112-9cf0-1cfac5f34d72', 'e13f4aa4-dd8a-48d5-8cc1-1c258f43e44d', 112, 'Season 5 Reunion Part 1', 'The O.C. housewives come together to discuss the events of the fifth season of the show that started the "Real Housewives" franchise.', '2010-03-10', 44, NULL, '2026-04-03T16:35:29Z', '2026-04-03T16:35:29Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('5f30b59d-bf8b-4a00-a323-c11a2ac75100', '200eca8d-ccb8-4470-b0fa-868d95b41c33', 7, 'Mockingbird', 'Tyrion enlists an unlikely ally. Daario entreats Dany to allow him to do what he does best. Jon''s warnings fall on deaf ears.', '2014-05-18', 52, '/loEv49LmoG5SVHmf2BegG8nJGG0.jpg', '2026-04-03T15:40:36Z', '2026-04-03T15:40:36Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('5f33003c-ecf1-441d-b789-9dfa0d09daae', '1d556682-d9bb-47e1-993f-0b648a8daacd', 41, 'Episode 1226', '', '1979-01-22', NULL, NULL, '2026-04-03T17:36:33Z', '2026-04-03T17:36:33Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('5f3652e7-7300-4e1c-b373-3567ef59f5e0', '5c4e51c6-e207-46ad-875c-72988eb1e13e', 14, 'Sharpe Shooters', 'The Pawn Stars hit the road to check out the forefather of modern machine guns, a Gatling Gun. Introduced during the Civil War, will Rick use all his firepower to secure a deal or will he be outgunned? Then, Corey and the Old Man try to hail down a piece of automotive history, a 1915 Ford Model T taxi. Completely restored from top to bottom, will the guys run up the meter on this negotiation or will they find they''re being taken for a ride? And later, Rick gets his hands on the gun that helped win the Civil War, an 1863 Sharps rifle. Decisive in the Union''s victory at Gettysburg, will Rick rally up the troops and charge or will a counterattack force him to retreat?', '2011-06-01', 21, NULL, '2026-04-03T16:34:16Z', '2026-04-03T16:34:16Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('5f36fdb1-ce70-4c6e-b4eb-fe3ffa71971d', 'ffc2a75e-0ffa-4b26-b121-9b91b277594a', 2, 'No Moore Apollogies', 'Kandi tries to please her mother by buying her a house. Meanwhile, tension between Phaedra and Apollo continues; NeNe gears up for opening night in Las Vegas; and Cynthia hosts a party, where Apollo breaks stunning news.', '2014-11-16', 43, NULL, '2026-04-03T16:34:47Z', '2026-04-03T16:34:47Z');
