INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('5f6d5ae5-a5bd-4251-bf84-693c2f9845d7', '272db816-9822-485a-b231-6e060d0ccb1a', 6, 'Snowdrifts', 'It''s winter in the top left-hand corner of Wales and Ivor''s railway is not running because of deep snow. Llaniog needs supplies soon, though, as Eli the Baker is nearly out of flour. What Ivor needs is a snowplough.', '1977-11-30', 5, NULL, '2026-04-03T17:24:25Z', '2026-04-03T17:24:25Z');
