INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('5f856b6c-f5fd-4f4e-8f0a-66aed373b891', '4fe93658-c463-4329-8e64-9d523869c2cb', 28, 'Ah, Shoot!', 'The Pawn Stars zoom in on a long lost picture by America''s most famous photographer Ansel Adams. Will the gang snap up this scarce print or will a lack of focus keep this negotiation out of frame? Then, Rick and the Old Man meet a guy hoping to sell his Jaguar XJ6. Will they shift into overdrive for this luxury automobile or will this exclusive kitten put up a fight? And later, Corey is thrown a 1942 Chicago Bears football autographed by the entire legendary team. Will he make a move for this prized pigskin or will a tough defense force a fumble?', '2011-03-21', 21, '/pyQ0YDB87hIxn4zBQSVjz2ykEXx.jpg', '2026-04-03T16:34:16Z', '2026-04-03T16:34:16Z');
