INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('5fbd6983-7f26-4b98-8d42-a614b24149a6', '73ae1459-ba91-4185-a9da-bf6f2844af49', 14, 'Remember Your Blue Stone Manners', 'After a rosé fueled night, the ladies wake up to find that Luann has left Blue Stone Manor. The women head to town for some much-needed retail therapy and group healing. To celebrate their last night in the Berkshires, Dorinda throws an elegant dinner party and the mayhem continues.', '2020-07-16', 60, '/aQZ5e5kiQVWiW2ZD2jQ3RD7Ns93.jpg', '2026-04-03T16:35:25Z', '2026-04-03T16:35:25Z');
