INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('5fe2b7a7-7047-4538-8825-4fa0646fefb6', 'd1863f2f-02ec-40ce-af64-db03fbe518a7', 17, 'Camping Show', 'Elmo and Chris go camping in the woods near Sesame Street to relax and meet some new friends. Also featuring Murray had a little lamb, and Elmo''s World-plants. Brought to you by the letter N and the number 16.', '2016-04-30', NULL, '/kav8fN2CNwNcKLGOWgPehnxAsgv.jpg', '2026-04-03T17:36:48Z', '2026-04-03T17:36:48Z');
