INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('5fe3cb49-c253-404e-8c72-b8c51352593d', '33825a15-37dc-4ff9-82bd-cc720498149a', 12, 'Babes in Thailand', 'The Dallas ladies’ first day of the trip is jam-packed as they explore all Thailand has to offer. But it’s not all fun and leisure, LeeAnne and Kary remain at odds, and when D’Andra shows up to dinner wearing LeeAnne’s L’Infinity Dress as a joke, LeeAnne thinks it’s no laughing matter.', '2019-11-20', NULL, '/7k00IUKpv8a1QEQgPQqgQCfL1Ld.jpg', '2026-04-03T16:35:04Z', '2026-04-03T16:35:04Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('5fe8df7d-74b8-421d-982f-6feb55bcffed', '3982796b-5451-4100-9042-46bedf6a20a5', 7, 'Pingu as an Icicle Player', 'Pingu has gone out, and meets up with Robby and Pingo. They play a game where one person has to find the others and, once found, get back “home” before they do. Pingu starts as finder and counts while Robby and Pingo hide. When Pingu starts looking, Pingo creeps up and gets home before Pingu notices. Pingu then spots Robby’s tail sticking out of some ice blocks, and throws a snowball at him that lands on his tail. Robby comes out, and Pingu wins the race home. Robby then counts, and the other two hide, but Pingo doesn’t realise he’s leaving a trail of footprints behind him. Robby goes to look for them, comes across the footprints and finds Pingo. Robby just wins the race for home. Then they both go off to call in Pingu, but they can’t find him anywhere. Then Pingo hears some clanging sounds and finds Pingu, who is making the sounds by hitting an icicle with a broken off piece of icicle he’s using as a striker. Pingu shows Pingo the cavern he has found, which is full of icicles of all shapes and sizes. Pingo gets a striker and makes his own sounds. Then they both hear some deeper sounds; Robby has found them and is making his own sounds with the icicles. Pingu then plays a tune on the icicles and Pingo and Robby both applaud him.', '1992-02-02', 5, '/jKo0yOOJZiUzLa46W6WwNlpL7JL.jpg', '2026-04-03T17:22:19Z', '2026-04-03T17:22:19Z');
