INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('6159c847-9c76-4e55-b202-6f1b499fd82b', '095258d0-d8db-4096-8ac7-6a42cd4cbdcf', 11, 'The Beanbarrow, The Burden And The Bright Bouquet', 'It''s time for the annual Beanbarrow Race, and it''s Gobo and Wembley vs. Red and Mokey. But when Mokey gets delayed, Red ends up having to do the race with Lanford, Mokey''s annoying plant. As they''re racing, Red and Lanford get lost at Table Rock Cavern which is where the Clinging Creepers live. When the Clinging Creepers start to attack them, Red and Lanford must work together in order to escape.', '1985-03-11', 24, '/rMbrYFtmWBgCfYQVk7x6Wpq78sG.jpg', '2026-04-03T17:35:00Z', '2026-04-03T17:35:00Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('615a9790-150d-4689-8a9c-85b57bbd31c4', '16cbf3f2-fffd-4a78-bca3-96d05f5a2c6b', 4, 'Wish You Were Here', 'Sue Ellen meets her pen pal but he is more interested in fashion than world culture.', '2016-01-19', 13, NULL, '2026-04-03T17:38:01Z', '2026-04-03T17:38:01Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('61649d81-cc99-49ca-8386-7daaf6010dc1', 'f12380a9-93e5-47bb-9e2f-cf1eed11eee4', 13, 'Benevolence, Bitch', 'Kody''s apology to Christine starts well but gets tense when David brings up Kody''s relationships with his kids. Janelle seeks guidance from Meri on getting her spiritual release. Meri''s shocked friends try to talk her out of meeting up with Kody.', '2025-12-21', 61, NULL, '2026-04-03T16:34:33Z', '2026-04-03T16:34:33Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('616b97e8-5dd8-4543-915c-aefacabb2dae', 'efdf1e4f-8476-4382-a9d7-2b9da4188be0', 1, 'Mad Feelings', 'Rogers visits Red Grooms'' studio, where he is currently working on a painting of the trolley. The Neighborhood of Make-Believe sees Lady Elaine in fits because she can''t seem to draw the Eiffel Tower well.', '1996-08-16', NULL, NULL, '2026-04-03T17:35:47Z', '2026-04-03T17:35:47Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('616c1a88-19ac-4638-b8e0-7fcbcc41e0fd', '04e133fd-c4a3-4dfa-8369-c6dcfd1e3a5a', 69, 'Maria looks for things beginning with the letter I', 'Maria and Telly search frantically through the Fix-It Shop for something beginning with the letter I while Barkley creates chaos by howling and scratching. They pull out drawers, rummage through the store, and interrupt their lunch plans in the quest, but struggle to find anything suitable. Crystal explains the importance of breathing to help demonstrate the letter and its sounds.

Sponsors: I, T, 4', '1985-02-21', NULL, NULL, '2026-04-03T17:36:36Z', '2026-04-03T17:36:36Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('616d21c2-4ff5-4995-8732-4df7fae881d9', '1be79a20-de33-41d1-af17-079035b18d5c', 69, 'Episode 69', '', '1970-02-12', NULL, NULL, '2026-04-03T17:36:28Z', '2026-04-03T17:36:28Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('616e3b40-1f1f-46ba-bd5d-6d400051a693', '05c0e384-194c-4417-9f62-803eb615e409', 18, 'Practicing and playing the clarinet', 'Title number 0018. Opens with Mister Rogers arriving with clarinet in a case. Mister Rogers puts together a clarinet and plays a few notes. He talks about his childhood clarinet lessons and remembers that he did not practice enough. In the Neighborhood of Make-Believe, clarinetist Loius Paul performs for King Friday and talks about the importance of practice. Mrs. Russellite, played by Barbara Russell brings a pinwheel to Henrietta and is introduced to Donkey Hodie, who is staying in the Tree until he finds a place to live. The pinwheel gives Donkey Hodie the idea to live in a windmill.', '1968-03-13', 29, NULL, '2026-04-03T17:35:38Z', '2026-04-03T17:35:38Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('61707aec-31ac-4019-a5a0-8c9cc1d3b755', '68138de2-0900-460a-b58e-480688f1e081', 5, 'Good Times', 'Everyone has slept over at the Big Blue House, and with the rising of the Sun (who shares some words with Bear), they''re soon waking up and starting a new day. Before they can go out on their adventures, Bear helps them with some healthy morning rituals, from breakfast to brushing teeth. Children will relate to the various experiences on display, from coming to terms with a wild but believable dream to having to immediately take a bathroom break.', NULL, 25, NULL, '2026-04-03T17:35:31Z', '2026-04-03T17:35:31Z');
