INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('619df65e-ca3b-4787-8d18-4d76b79d144d', 'da06465b-9154-4feb-a455-374df7dab02f', 11, 'Baby Bear''s First Day of School (4093)', 'Telly Monster tells Gordon that he feels miserable because in order to go on Oscar’s Annual Grouch Picnic and Field Day, he has to learn the Official Grouch Cheer and he’s the only one who can’t do it right.  Gordon talks to Oscar and convinces him to let Telly try learning to do it right.  Telly is so discouraged at this point that he keeps saying that he can’t do the cheer.  Gordon motivates Telly by practicing the cheer with him and by telling him that he can do it!  Through Gordon’s encouragement, constant practice, and believing in himself, Telly finally learns to do the cheer!  Telly shows Oscar that he can do the cheer beautifully, and boards the bus to go on the field trip with all the other Grouchketeers!', '2005-04-18', NULL, NULL, '2026-04-03T17:36:44Z', '2026-04-03T17:36:44Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('61a20359-3ce6-4a17-8a52-cac183c515fc', '63f9bf6d-39b3-44f4-b885-a56807277a80', 30, 'Mr. Willowby''s Christmas Tree', 'The special begins with the song “The Perfect Tree,” which features both Mr. Willowby (Robert Downey Jr.) singing about his desire to find the perfect Christmas tree and, within Willowby’s house, a father mouse singing that he will go out to get a tree for his family (his two children, Beverly and Ned, decide to come with him). After the song is finished, Willowby asks his butler, Baxter (Leslie Nielsen), where his tree is.', '1995-12-06', 30, NULL, '2026-04-03T17:35:23Z', '2026-04-03T17:35:23Z');
