INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('61c1d6e3-fdba-4606-ac59-46e49a75a6c9', '1d713ca6-4e17-4f84-949c-8cfd98514127', 3, 'Chumdae', 'Rev your engines with the Pawn Stars when a legendary 1967 Shelby GT350 speeds into the shop. Will Rick be able to cruise through the negotiation or will it be gone in 60 seconds? Then, Corey and Chumlee play with the idea of buying one of the first video game consoles, a Magnavox Odyssey 200. Can they figure out how to beat the system or will it be game over? And later, Chumlee seeks the go ahead from Rick to test out the shop''s new ice cream maker. Will the guys all scream for ice cream or will Rick give Chumlee the cold shoulder?', '2014-07-17', 21, '/pCSsfApqp4aM4wKWlaFZ4cvbODE.jpg', '2026-04-03T16:34:19Z', '2026-04-03T16:34:19Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('61c9d8ca-f086-424a-8c5e-e89177e191c4', '6e0be2a3-a234-453b-abb7-0ba535a93601', 25, 'My Franklin', 'Franklin and Bear want to play in the park, but Bear''s younger sister keeps calling out to them. Franklin keeps retiring until, which makes Bear jealous, but they realize the she was actually calling out to Franklin because Bear was too busy.', '2000-07-30', 12, NULL, '2026-04-03T17:40:15Z', '2026-04-03T17:40:15Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('61cdb695-0c32-4b41-84f9-ec67b36a13c6', 'ca19f895-1514-4988-a709-95e84eab7cee', 11, 'Rick''s Big Shot', 'When a seller comes in with an overcoat once owned by suspected JFK assassin, Lee Harvey Oswald, will the deal be a stroll on a grassy knoll, or will Rick lose his shot at owning a piece of history? Next, Corey checks out a 30-year-old Gibson guitar with a factory mistake. Can he pick up a sale, or will he get shredded? Then, a rare Mike Tyson Nintendo game punches into the shop. Can Chum knock out an offer, or will the seller put up a fight? And finally, Rick and Corey head out of the shop and into the desert to check out a restored WWII half-track. Will the father and son duo be able to target a deal, or will it blow up in their faces?', '2021-03-22', 42, '/g4YnyTpA9pSrbzS8Tb4vzLPxdGV.jpg', '2026-04-03T16:34:22Z', '2026-04-03T16:34:22Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('61ce8fdc-4721-4cf6-b40b-f90be6dee4ea', '081f12e2-9239-4946-90a1-47763b935db2', 4, 'Episode 4', '', '1986-02-11', 25, NULL, '2026-04-03T17:21:14Z', '2026-04-03T17:21:14Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('61d64ba4-e924-41df-af93-0dc83d7b5fb1', 'd920ebae-f00a-4e25-abfe-40492c74ded6', 8, 'Pawning for Treble', 'Rick is in Chicago where he has a run-in with a wrestling legend and a chance to clinch a Michael Jordan championship jersey. Back at the shop, Chum looks to score big on a 300-year-old violin. Later, a vintage Batman playhouse places Corey and Chum in a betting mood.', '2019-12-30', 42, '/rNqwTIDC8cTV9NTLysWG8EyMiIz.jpg', '2026-04-03T16:34:22Z', '2026-04-03T16:34:22Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('61d81ce1-70d1-4f1f-b1b9-1ae2b271bbcf', '225b0f03-984b-47f3-a1a3-d3e92175e39d', 72, 'Episode 72', 'with Christopher Trace, Valerie Singleton and John Noakes.', '1967-06-12', NULL, NULL, '2026-04-03T17:21:48Z', '2026-04-03T17:21:48Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('61dab023-442b-424c-bdd3-b7d0893fdb72', 'd405f973-4c7e-4cb6-b7c0-d09a884c9b35', 11, 'Debt Becomes Her', 'The ladies wake to their final hours in Morocco. Packing is the order of the day, but Jill and Ramona find time to try to patch up their hot mess of a relationship. Before long, however, anger toward Ramona comes from someone else. Calmer heads prevail, and the ladies reminisce about their exotic getaway while anticipating a return home.', '2011-06-16', 42, '/i2hXQYQwt2aLWVUcMlexcgx9dZh.jpg', '2026-04-03T16:35:22Z', '2026-04-03T16:35:22Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('61daf758-4977-40c8-83c4-9a25e2ddc968', '01b3a1e3-d0e8-4f2b-a56d-9d55669ab5f2', 5, 'Sad Sorry Lonely Little People', 'Kody''s absence during Ysabel''s surgery and recovery upsets Christine.', '2021-12-19', NULL, '/oIAP3WMx6rm5owPa6DvlTt3qtz7.jpg', '2026-04-03T16:34:32Z', '2026-04-03T16:34:32Z');
