INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('61dccd68-bb8d-4902-a4d9-504cd031247a', 'cefd1496-b649-4c62-aef9-35a22558ac08', 8, 'A Mouthful in Mexico', 'The forecast for Playa Del Carmen, Mexico says plenty of sun and tequila, until Brandi pushes Kameron overboard with an “impressive” novelty.  LeeAnne shares exhilarating news about her relationship with Rich.  And at an exotic underground cave dinner, Cary confronts LeeAnne about her dangerous threat, unleashing crossfire of accusations and denials between the wives.', '2017-10-02', NULL, '/sJ6hCfVrLB6DxS5hx7HowehqYGS.jpg', '2026-04-03T16:35:04Z', '2026-04-03T16:35:04Z');
