INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('61f5430a-85a4-48e5-a1e4-c5e87593d5b8', 'abfe14ee-db42-4dde-a96a-601ff3c53ecc', 3, 'Treachery', 'Cluny uses two treacherous foxes, Sela the vixen and her son Chickenhound, to plant a false attack plan in Redwall, while Matthias and his mousemaid friend Cornflower unravel the mysterious motto, "I am that is." It is an anagram for "I Matthias" written years before he was born, another clue for the quest for Martin''s sword. Cluny''s real underground attack is inventively repulsed by hot porridge and Matthias sees the fearful snake Asmodeus for the first time and realizes that somehow their fates are horribly intertwined.', '1999-09-12', NULL, '/3EpLJVg5KOJdBFaf5VShCWTRrWM.jpg', '2026-04-03T17:12:08Z', '2026-04-03T17:12:08Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('61f8dc11-6b71-48a3-a9d9-6ade63132428', '6053b5c1-ce86-425c-8166-e0fcc3466061', 66, 'Episode 66', 'with Valerie Singleton, John Noakes, Peter Purves', '1970-05-07', NULL, NULL, '2026-04-03T17:21:50Z', '2026-04-03T17:21:50Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('61fa3946-6849-42e8-9ba0-a87ba8d9e957', '1996ddd8-20c9-4a30-96be-2b87fab8d17c', 5, 'Ghost Story (5)', 'The team, with the help of the robbed kids, set a trap for the backpack thieves at the video arcade.  After the theives are caught, the four decide to become the ""Ghostwriter Team"" and vow to try and solve mysteries.', '1992-11-01', NULL, '/mmppAFPNTAisM4CySkUTZ5ENNKU.jpg', '2026-04-03T17:40:28Z', '2026-04-03T17:40:28Z');
