INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('6229e6f9-c3de-4789-9cd6-1f0e1a83ce5f', '8c3cfac1-d882-4904-b38c-d1981628d00e', 33, 'Episode 33', 'Did you get a diary for Christmas? More than 300 years ago a young man started a ten-year diary written in secret code. Lesley and Christopher tell the story of Samuel Pepys and the diary that became one of the most important books in the English language.', '1979-01-04', NULL, NULL, '2026-04-03T17:21:54Z', '2026-04-03T17:21:54Z');
