INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('624adc78-5586-414d-8c0f-ffc071bf9d3b', '06030129-ff2d-4490-b66c-9f41bbe7aabd', 21, 'Breakdown', 'It''s time for John to take out the rubbish from the boat, so he attempts to catch up with the bin-man and takes the rubbish to the tip so it can be broken down and recycled.', '1991-02-04', 15, NULL, '2026-04-03T17:19:36Z', '2026-04-03T17:19:36Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('624e82f0-1140-4997-9d70-a6a20976368d', 'ca19f895-1514-4988-a709-95e84eab7cee', 23, 'Rick vs. the Globe of Death', 'Rick and Chum get a relatively genius package containing letters signed by Albert Einstein. But can they figure out the equation to work out a deal? Then, Chum and Corey marvel at replicas of Thor’s helmet and hammer. Will they nail the negotiation, or be deemed unworthy? Next, an antique game shuffles into the shop. Will Corey try to bet the house, or will he strike out? And finally, Rick heads out to meet Spencer for a death-defying picking adventure of global proportions.', '2021-09-04', 42, '/sqtE9nKLORQV9QrNHgMoO0PQR90.jpg', '2026-04-03T16:34:22Z', '2026-04-03T16:34:22Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('62512361-c70a-429d-80b7-d9a4aad63835', '3dc690a7-6dd8-4754-979a-02a9bf5d18db', 2, 'Paddington Goes to School', 'Paddington is told by the authorities that he must enroll in school, which of course is the start of trouble.', '1986-01-03', 30, NULL, '2026-04-03T17:22:52Z', '2026-04-03T17:22:52Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('62554f9f-6ff2-4faa-af0b-75cb9fdb6dfc', 'e4023da2-33d7-4a2b-a04a-ca449bd23935', 10, 'Pam Freakin'' Staggs', 'Frankie acts like a teenager when she hangs out with Pam Staggs, a former classmate who was popular in high school. Meanwhile, Brick surprises Mike by winning an athletic award; Sue pursues some odd hobbies; and Axl seeks a date with Devin Levin.', '2015-01-07', 22, '/atO1dYoLFmIAxQZaZ7F2ZDm4j2Z.jpg', '2026-04-03T15:40:30Z', '2026-04-03T15:40:30Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('6258d83d-e3fc-4061-a7f4-154967f2f807', '7c422193-b078-49d8-81ef-f2b9f94f059d', 39, 'Telly becomes afraid of bread', 'Episode #3044', '1992-12-31', 55, NULL, '2026-04-03T17:36:39Z', '2026-04-03T17:36:39Z');
