INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('62604a42-51d5-4827-89e2-910b9c073fe3', 'f07b8794-5625-4682-aae1-e56966b4c7a8', 16, 'That''s Weird', 'The children think Ben’s Norwegian dancing and traditional costumes are weird. They soon learn that things that are new to them just might be interesting, not weird. Sizzle, likewise, finds Nuzzle chewing on a toy car weird. Skye and Jody do not appear in this episode.', '1996-02-05', 29, NULL, '2026-04-03T17:12:21Z', '2026-04-03T17:12:21Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('62604ac4-d8f3-4220-b99a-28cb9670c932', 'd3e13496-e3c8-4903-83b4-5a31fedee232', 14, 'The Fortuneteller', 'When the group tries to help a man who is being attacked by a platypus-bear, they discover that the local town has a fortuneteller named Aunt Wu in it, who has been forecasting the town''s fate for years. But when Sokka and Aang discover one of the fortuneteller''s most vital predictions is dead wrong, they have to develop a plan to convince the stubborn townspeople that their beloved Aunt Wu was wrong.', '2005-09-23', 25, '/leJKRM1LLF64in8IGs6NbRAyEmx.jpg', '2026-04-03T17:40:47Z', '2026-04-03T17:40:47Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('62658044-6a5b-471b-bb7a-40702d1de135', '3fc7c152-e4f6-426a-a899-36ec454c4403', 45, 'Backwards to Forwards', 'During a game of Leap-Dragon, Zak and Wheezie accidentally hit a rock, sending it to one of the Backwards-Forwards Signs, and causing the entire Dragon Land to go backwards. When the mix-up becomes frustrating after a while, the gang must find a way to turn things around for them to go forwards again.', '2000-01-19', NULL, NULL, '2026-04-03T15:26:03Z', '2026-04-03T15:26:03Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('62682204-a197-41c2-b16a-39983ac2f36c', '46d7a706-c7a8-4ebe-b96f-387c66e8bb8b', 96, 'Episode 1541', '', '1981-04-06', NULL, NULL, '2026-04-03T17:36:34Z', '2026-04-03T17:36:34Z');
