INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('626e127c-50ff-4cee-9f99-98726f2cde76', '3fc7c152-e4f6-426a-a899-36ec454c4403', 64, 'Baby Troubles', 'Cassie''s baby sister, refuses to take her nap and gets very upset when Ord accidentally flattens her squishy. So the gang works together, taking care of her. It''s also up to Ord to help find a new squishy for Kiki to finally get her to take her nap.', '2000-04-18', NULL, NULL, '2026-04-03T15:26:03Z', '2026-04-03T15:26:03Z');
