INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('62ea41fb-8d82-46ee-aec6-7c98b4c552f5', '0f64bf9f-8d05-4f5b-9a57-5d0c44ac3f40', 9, 'A Judge Decides', 'Today is the day the Brown’s have been working towards this entire year. Finally, this is the court hearing where Kody will learn if he can adopt Robyn’s oldest kids. And Janelle’s oldest daughter, Madison, has a stunning announcement for the family.', '2015-10-25', NULL, NULL, '2026-04-03T16:34:29Z', '2026-04-03T16:34:29Z');
