INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('63416766-1067-4da1-a86f-4d469b8e6f0a', '05c0e384-194c-4417-9f62-803eb615e409', 41, 'Rain in the Neighborhood of Make-Believe', 'Title number 0041. Opens with Mister Rogers arriving in a rain coat twirling a bag. Mister Rogers talks about sewing, and shows a needlepoint creation of the Neighborhood of Make-Believe. Corny, X and Henrietta have various reactions to the rain in the Neighborhood of Make-Believe. Lady Aberlin and X sing "Creation Duet".', '1968-04-15', 29, NULL, '2026-04-03T17:35:38Z', '2026-04-03T17:35:38Z');
