INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('6366ef18-dd82-443e-b5b3-5eac50f23660', 'f5c042dc-0657-42e8-a37d-247414140632', 6, 'Another One Bites the Crust', 'Tiffany throws an intimate pizza party in an attempt to get closer to the other women, but her obsession with rules and an ill-timed prank only push them further away. Stephanie goes over-budget on her first charity project, Kameron''s dog trainer stops by for an "accountability meeting," and D''Andra consults her shaman about the best way to deal with Kary.', '2021-02-09', NULL, '/nujOaysTUXBxkmu8lTSKBnBmDsF.jpg', '2026-04-03T16:35:05Z', '2026-04-03T16:35:05Z');
