INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('637a6800-a28f-4caf-b669-79cb511098d0', '04e133fd-c4a3-4dfa-8369-c6dcfd1e3a5a', 74, 'Episode 2039', 'Big Bird fantasizes about Maria and Gordon vanishing through impossible means—Maria swimming the Atlantic and Gordon catching a rocket to Mars—in order to teach subtraction. When reality returns and they''re actually gone, Bob becomes confused by Big Bird''s mysterious talk of his imaginative scenario. Maria later receives a handmade flower from Big Bird that lifts her spirits after a long day fixing a grandfather clock.

