INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('637c651b-a0c0-473c-be58-2bae63350aa7', 'eb7e3bb4-5746-4577-81c6-f5b2dc2efc6e', 9, 'Bitter Work', 'Toph''s instructing abilities come into question when Aang cannot seem to overcome a block that keeps him from earthbending. Sokka gets himself in a jam, while befriending what was, moments before, his next meal, and Iroh and Zuko begin training utilizing new philosophies and methods that originate from the other elements.', '2006-06-02', 25, '/ilnwRuY533ZGv3JapxbZQGfxgyo.jpg', '2026-04-03T17:40:48Z', '2026-04-03T17:40:48Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('637f4fa7-8e46-474b-a85c-45d35fb4bdaf', 'f5474771-8930-41eb-b0d4-db442233acee', 1, 'Crocs Down Under', 'The Australian Saltwater crocodile is the world’s largest terrestrial carnivore. Intrepid natural historian, Steve Irwin, journeys to Australia’s far northeastern corner to try and capture a nuisance crocodile and teach him a lesson before releasing him back into the wild. Set against the colorful backdrop of Australia’s Top End, the special shows that these often ferocious man-eaters have a gentler side that make them caring lovers and devoted parents.', '1997-01-01', 44, NULL, '2026-04-03T17:39:10Z', '2026-04-03T17:39:10Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('638250bf-4eb1-4912-957d-6e8ccdf206c3', 'e93f04c2-7344-4b93-abba-8ba1b2f8eb35', 118, 'Episode 653', '', NULL, NULL, NULL, '2026-04-03T17:36:30Z', '2026-04-03T17:36:30Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('63880194-502d-4090-a3de-ee003843f3ea', '650bac93-7b59-41fc-b277-dc6f8bdcd7bb', 17, 'Exes and Ohhhs', 'Axl is startled to run into nearly all of his former flames at a St. Patrick''s Day party leaving him to wonder if it is a sign about his love life; Brick buys an old microfiche machine at a library sale, leaving Frankie and Mike less than thrilled.', '2017-03-14', 22, '/3YTDaCU4F5CWoDZUxUdqwpt6B1o.jpg', '2026-04-03T15:40:31Z', '2026-04-03T15:40:31Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('638c8aaa-8d6c-41f7-9d6c-b10d98f7eea7', 'ffc2a75e-0ffa-4b26-b121-9b91b277594a', 17, 'Fix It Therapy', 'Claudia seeks a new purpose in life and decides to pursue stand-up comedy. Meanwhile, Kandi and Phaedra have an emotional meeting about their wilting relationship; and NeNe brings the ladies together for therapy with Dr. Jeff, but the session sours and NeNe storms away.', '2015-03-15', 43, NULL, '2026-04-03T16:34:47Z', '2026-04-03T16:34:47Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('638dfaf2-f1cb-495b-b16d-e3177d324bbf', '70cac5ca-fb7f-4cb7-8c9b-004d44124a1d', 4, 'The Public Shaming of Melissa', 'As the restaurant opening approaches, tensions mount between Melissa and Teresa; Siggy throws a cocktail party, but her anger comes back to haunt Melissa; Danielle shares a secret with Teresa that could destroy Teresa''s friendship with Dolores.', '2017-10-25', 43, '/zEbMwuY7uH644VhnU0eUDVtP2J7.jpg', '2026-04-03T16:35:17Z', '2026-04-03T16:35:17Z');
