INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('63971fe6-61c6-47b7-b98f-08173a803ecc', 'cefd1496-b649-4c62-aef9-35a22558ac08', 5, 'Walking in Memphis', 'Kameron presents a bright pink business idea to her very skeptical husband, while Cary and Stephanie embark on Brandi’s family trip to Memphis. LeeAnne is left behind and crushed to find she’s not as close to Brandi as she thought. Unexpected news from D’Andra’s stepson Keatin leaves her angry and confused. And Brandi begins to feel she’s taking a daring emotional chance, hoping Grandma will open the door after being estranged for so long.', '2017-09-11', NULL, '/6Lljzrs1wwi6xmCupr4SsraWX6r.jpg', '2026-04-03T16:35:04Z', '2026-04-03T16:35:04Z');
