INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('63990109-c61c-43c6-9237-1610fa0920b2', '991e78f1-03a5-4d26-8f75-75e11db4243c', 8, 'Go-Stop-Go: A Visit with ''Arthur'' Creator, Marc Brown', 'Mr. Rogers visits Marc Brown, creator of the Arthur book series and shows him how he draws Arthur. After explaining how the TV show is made, they watch a clip of the episode "Arthur Meets Mister Rogers", which Rogers himself guest-starred on, and meet Michael Yarmush, who does the voice of Arthur and Arthur himself shows up in the Neighborhood of Make-Believe, greeting several neighbors — including Lady Elaine. Rogers views a video on how traffic lights are assembled.', '1999-04-05', NULL, NULL, '2026-04-03T17:35:48Z', '2026-04-03T17:35:48Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('639a1612-9cf5-4bf1-9b5f-f70c5cc888a7', '7c0e1f66-8835-4e8a-8ad9-0eee57155b4c', 7, 'Escape From the Spirit World', 'After being shot by Azula''s lethal lightning attack, Aang falls into a deep slumber. Escape from the Spirit World explains that while Aang''s mind and body were immobile, his soul was trapped in the Spirit World. He encounters Princess Yue, the Moon Spirit, who informs him that if he does not reconnect with his past four lives, the Avatar Cycle will end.', '2007-09-11', 14, '/bzlmne0LEBfdScAKLmU7aJLyzhz.jpg', '2026-04-03T17:40:47Z', '2026-04-03T17:40:47Z');
