INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('639ebcf7-5c19-45c3-98f6-09417d6b66e5', '6f731e6b-d3c5-4de6-84e1-7a19cb650e86', 33, 'Every Rose Has Its Pawn', 'Raise the American flag with the Pawn Stars when an original sketch of the Marine Corps War Memorial sculpts its way into the shop. Will Rick claim victory with his offer or will it become his enemy? Next, a Poison platinum disc signed by Bret Michaels rocks in. Will Rick make a glam metal deal or will it be a thorn in his side? Then, a Roman oil lamp from the first century lights its way in. Will Chum ignite a deal or will the flame burn out? And later, a military certificate from the Vietnam War shows up. Will Corey cash in or will it be worthless?', '2016-05-04', 21, '/H5pDfmzuwpSJfvgYbj1ZaOmtpX.jpg', '2026-04-03T16:34:20Z', '2026-04-03T16:34:20Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('63a2c45d-b66f-437d-aab6-378d7dac85e8', '0442fb97-1460-4923-8558-b994078dc6b8', 21, 'Reunion (2)', 'Candiace and Monique go head-to-head; the ladies confront Karen about where her loyalty lies; Gizelle and Robyn lay everything out on what fuelled the alleged trainer plot; Ashley clears the air about Michael, and she makes a shocking revelation.', '2020-12-20', 42, '/qK2BPx3eF88tCmEFIvt06yG0oBS.jpg', '2026-04-03T16:35:40Z', '2026-04-03T16:35:40Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('63a77160-2abe-45a7-94fe-117295224be5', 'b6baa6ec-0908-4a47-9001-7e7158985002', 4, 'Going Batty', 'When Ms. Frizzle invites the class’ parents in to see that their kids are learning about bats, Ralphie and the gang are convinced The Friz is a vampire! With Tyne Daly as Ralphie’s mom; Eartha Kitt as Keesha’s grandmother; Elliot Gould as Arnold’s dad; Dana Elcar as Phoebe’s dad; and Edward James Olmos as Carlos’s dad.', '1995-09-30', 25, '/lKpdSN346EScyTtUxDpRv8MxOaq.jpg', '2026-04-03T17:37:48Z', '2026-04-03T17:37:48Z');
