INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('63beb776-95df-43cb-9b1d-4b57aaec0172', 'a0fa5075-9ce1-48c1-9995-0c0fd866e549', 4, 'Twisted Sisterhood', 'The girls’ Oceanside getaway gets derailed when a tense exchange between Dorit and Kyle leaves the two at an impasse. On a boat trip, Garcelle feels adrift over her soon-to-be empty nest. Sutton helps Dorit navigate rough waters in her separation. At the final dinner, Boz and Erika are left questioning the future of the group, but Sutton tries to bind the woman together through sisterhood.', '2024-12-10', 43, '/q1KCRZTSM0LQozH2CKCq2dAaQ8b.jpg', '2026-04-03T16:34:59Z', '2026-04-03T16:34:59Z');
