INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('63e092a9-a456-4025-b161-13cdb078c4d0', 'bfdf87ff-01dd-4b54-94bd-19b384f41bdb', 14, 'Secrets, Lies and Vicki''s New Guy', 'Meghan throws a party to celebrate the grand opening of her candle store. Tensions ignite as Vicki threatens to expose a secret about Shannon that leaves all the ladies confused. As Kelly and Michael try to navigate their tumultuous marriage, Meghan and Jimmy try to get a handle on her highs and lows of pregnancy. Meanwhile, Heather throws a fancy party filled with mixed emotions and cocktails to celebrate the release of her book; where Vicki and Shannon finally confront one another and Meghan proposes a trip to Ireland to investigate her heritage.', '2016-10-03', 44, '/u9fR4P7UnpQtcAAO551FffZZwRg.jpg', '2026-04-03T16:35:33Z', '2026-04-03T16:35:33Z');
