INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('63f41501-aa47-44da-8c88-8facff8ad690', '03485b5e-a5b7-423e-b21e-c00e62216a35', 5, 'Bears For All Seasons', 'The cubs find something else to do in unseasonable weather.', '2004-09-08', NULL, NULL, '2026-04-03T17:40:22Z', '2026-04-03T17:40:22Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('63f6d43b-b682-4675-b90a-1d36d68e58ed', '3982796b-5451-4100-9042-46bedf6a20a5', 18, 'Pingu Cannot Lose', 'Pingu and Pinga are bowling. Pinga takes the first throw, and doesn’t score, but then rolls up herself and knocks all the skittles down. Pingu is not very amused; he is very surprised! Then Pingo comes by and has a go; he knocks down two skittles. Pingu throws and hits four. Pingo’s next throw gets one, and Pingu gets four again. Then Pingo gets two, and Pingu gets three, but this time his ball takes an odd path before reaching the skittles. A passer-by has a go and gets six. Pingu’s next ball goes straight, and he knocks over a skittle, but it stands up again. The passer-by gets another six and Pingu gets a one. The passer-by then gets seven, and Pingu walks away unhappily. Then the passer-by gets an eight. Robby, who has just arrived, gets one but his ball also takes an odd path before hitting the skittle. Robby thinks this is very funny. The passer-by then gets all nine skittles, and the others applaud. Robby’s next throw misses completely, as does Pingo’s. This time they all think this is funny. Pingu then has another try, but to throw he faces backwards and rolls the ball between his legs. Again his ball takes an odd route, misses, and ends up in front of the group of skittles. He has another throw. The ball hits the ball that’s already there, and both balls go round the outside of the group of skittles. They all find this extremely funny.', '1993-08-03', 5, '/z2FXzmDgzVdqyIqbv3QXeFD59kA.jpg', '2026-04-03T17:22:19Z', '2026-04-03T17:22:19Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('63f7d2a5-5003-41ea-b934-9cef8f5e6994', 'f63c3f61-0970-4e37-81cc-2b9045a9952c', 4, 'Maria''s Mother Visits (3919)', '', '2001-01-04', NULL, NULL, '2026-04-03T17:36:42Z', '2026-04-03T17:36:42Z');
