INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('640e86a6-07b4-4cdc-b602-fef632fba80d', 'f13cb622-84e3-4654-a8f1-0ceab09a9ca6', 3, 'Franklin Loses a Book', 'Harriet has a favorite book called The Happy Green Frog and she wants Franklin to read it to her over and over. Franklin is okay with reading it at first, but when she keeps asking to hear it and ignoring all of her other books, he grows tired of it and hides it under a pile of newspapers. Later, the newspapers are taken out to the recycling... and the book exits with them! Franklin and Bear launch on a wild hunt throughout Woodland in the hope of finding another copy of the book to read to Harriet, but end up with a very creative solution to the problem.', '2002-05-06', 12, NULL, '2026-04-03T17:40:16Z', '2026-04-03T17:40:16Z');
