INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('64562319-132f-4ee0-aed1-38bd19bb8d0b', '5ba20443-d99f-4820-81f6-6832d3f2bc4f', 8, 'Probability', 'Probability is a way to measure how likely it is that something will happen. Probabilities are predictions. They’re often just very careful guesses. When a scientist wants to calculate a probability, she or he gathers data and then uses the data to make her or his guess. Probabilities are between 100% (it’s definitely going to happen) and 0% (forget about it, pal, it’s not going to happen). Most things have a probability somewhere in between.', '1996-01-19', 26, '/vehWGKlFFZ1tDwbn9HVK8fSqOLA.jpg', '2026-04-03T17:37:21Z', '2026-04-03T17:37:21Z');
