INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('64a709c5-df7a-4f9b-a19d-161908812344', 'c01ddd2a-bdb1-4c97-8d04-58f791ef1c24', 14, 'Tracks', 'Martin and Chris follow the tracks of a lynx through the snow, and Jackie works on protecting her bird feeder from marauding squirrels.', '1999-02-11', 27, NULL, '2026-04-03T17:10:55Z', '2026-04-03T17:10:55Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('64ab66c9-2b4d-4100-b2e0-0499d33ca149', 'bf3ffafd-7d45-4f2c-9f1b-28001bd082db', 73, 'Episode 73', 'with John Noakes, Peter Purves, Lesley Judd', '1975-05-26', NULL, NULL, '2026-04-03T17:21:52Z', '2026-04-03T17:21:52Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('64ace8db-45d4-471e-b148-54815103d513', '1a534647-384b-4c00-bb6c-a3371ad962eb', 21, 'Crossing Chum', 'Get rewarded with the Pawn Stars when a 1965 Panama Canal service medal is presented to the shop. Will Rick keep his eyes on the prize or will he fail to complete his mission? Then, Corey sets his sights on a renaissance era crossbow. Will Corey hit a bulls eye or miss his target entirely? And later, Chumlee finds himself in hot water after he fails to call in an expert. Will his wacky sale turn a profit or will the joke be on him?', '2015-03-26', 21, '/aJz35oOLuP4va05jb4mPRoyAqb9.jpg', '2026-04-03T16:34:19Z', '2026-04-03T16:34:19Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('64ad95b1-6806-4f30-8dbd-23f174d65f42', 'f63c3f61-0970-4e37-81cc-2b9045a9952c', 15, 'Telly The Masked Tuba Player (3930)', '', '2001-01-19', NULL, NULL, '2026-04-03T17:36:42Z', '2026-04-03T17:36:42Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('64ae0761-ef3d-413a-9b34-11f3df4ed301', '0ab4dfb2-58c9-4e52-b5bf-49bba0bfc597', 4, 'Cancer Man', 'Walter finally tells his family that he has been stricken with cancer. Meanwhile, the DEA believes Albuquerque has a new, big time player to worry about. Meanwhile, a worthy recipient is the target of a depressed Walter''s anger, and Jesse makes a surprise visit to his parents home.', '2008-02-17', 49, '/2UbRgW6apE4XPzhHPA726wUFyaR.jpg', '2026-04-03T15:40:32Z', '2026-04-03T15:40:32Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('64ae4227-53a8-419f-9e2d-7b2ea01801f6', '3f27dc9b-9bbe-4aff-8cd9-90be629a885e', 6, 'Episode 6', '', '1997-02-06', 25, NULL, '2026-04-03T17:21:17Z', '2026-04-03T17:21:17Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('64af2140-2176-44fb-8c82-6b422291a7eb', 'd6092173-d23b-4449-baff-e0e16fe56c9a', 9, 'The Hostess With The Least-est', 'As the Isle of Palms girls’ trip continues, the drama between Marlo and Kenya reaches new heights. Porsha’s heart is still focused on how she can continue her activism as she struggles to cope with the verdict in the Breonna Taylor murder case. Kandi makes sure Cynthia’s last days of singledom are celebrated with a dungeon style stripper party… including a very special surprise package.', '2021-02-14', 43, '/wFotX4Rtze7Jw49a9xmtFw4uIex.jpg', '2026-04-03T16:34:49Z', '2026-04-03T16:34:49Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('64b3b980-2578-4408-b8f2-f68781b6d36b', '3fc7c152-e4f6-426a-a899-36ec454c4403', 53, 'Quetzal''s Magic Pop-Up Book', 'When the gang uses Quetzal''s magic pop-up book to make up stories, they all talk at once, but nobody listens. They soon realize that by taking turns, everyone''s story gets to be heard.', '2000-01-25', NULL, NULL, '2026-04-03T15:26:03Z', '2026-04-03T15:26:03Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('64bf7c48-1318-47f6-a3fa-a9d958787f38', '6c1ec19f-74df-4f35-9a61-17b98175d826', 17, 'Reunion (1)', 'The ladies come together for a virtual sit-down to rehash a season of incredible highs and shocking lows, as they confront their issues and tackle viewers’ burning questions. Kyle and Garcelle waste no time airing their grievances, and their unresolved tension finally reaches its boiling point when Kyle drops a shocking accusation. Dorit and Sutton recount their awkward exchange at Lisa’s daughters’ clothing line launch event, but Dorit’s apology falls on deaf ears as Sutton challenges the motivations behind her comment. Frustrations come to a head when Erika and Lisa bring Denise to task for refusing to have an honest conversation and accuse her of manipulating the truth.', '2020-09-02', 43, '/67NFMMdzFLcLGNGln30BlT38I3h.jpg', '2026-04-03T16:34:58Z', '2026-04-03T16:34:58Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('64c1d36e-74a7-44e7-ba4c-14edf42f2ce6', '6fedba82-52f3-4184-be77-6b26e556cd0e', 3, 'Paddington Goes Underground', 'Paddington travels on the underground with Mrs. Brown.', '1976-01-07', NULL, '/mwFFOehh5GwtHCuopb2jsKU1cz6.jpg', '2026-04-03T17:22:52Z', '2026-04-03T17:22:52Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('64c25350-e2e0-4326-a999-90743c5d61be', '1bb53927-76f6-4ed3-9c41-5414ad0865ce', 9, 'The Abyss', 'Slagar reaches the abyss and forces the slaves across a rope bridge, cutting it away behind him. There is now no way for Matthias to pursue him. A full day and night behind the pursuers arrive at the abyss and are stopped dead, until Sir Harry comes their rescue by retrieving enough rope to cross the bottomless gorge.

At Redwall Abbey the hostages are exchanged, but Ironbeak treacherously uses the diversion to take over a section of the abbey. The citizens of Redwall are trapped without water and are saved when Foremole digs a tunnel. The celebration is short when it is discovered that Ironbeak is attacking the Martin the Warrior Tapestry. Rushing to its rescue the citizens of Redwall are trapped; it was a baited ruse. Ahead of Mattimeo and the slaves are the Badger Head and Bell Rocks in a lifeless wasteland, which scares even Slagar and his rats. The terrible journey is approaching its climax.', '2000-12-24', NULL, '/zQLTxJLDaMkra5zjrNt96VvdiZ0.jpg', '2026-04-03T17:12:08Z', '2026-04-03T17:12:08Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('64cb8b3d-f1ba-40b1-bbb5-e536388af104', 'bf3ffafd-7d45-4f2c-9f1b-28001bd082db', 59, 'Episode 59', 'with John Noakes, Peter Purves, Lesley Judd', '1975-04-07', NULL, NULL, '2026-04-03T17:21:52Z', '2026-04-03T17:21:52Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('64cfee03-0cc4-491a-bf62-a6d6ad36e2e4', '45e01c04-6ac6-41e1-87d8-f749ee230385', 27, 'Steuermann Norman', '', NULL, 10, NULL, '2026-04-03T17:14:38Z', '2026-04-03T17:14:38Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('64d0b7b5-38e2-46d6-b80f-01d466cf290d', '421c3366-4d98-4baf-b4ad-6ec5047df9f8', 18, 'Framed!', 'Buster has just won the best young artist award at the Elwood City Arts Festival. Sensing his work might be worth something someday, Muffy hires Buster to paint her portrait.', '2014-05-13', 13, NULL, '2026-04-03T17:38:01Z', '2026-04-03T17:38:01Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('64d20722-29de-4293-8c0f-b922225abe05', '671bd4da-3470-40f9-9a03-40fba34d2b8e', 24, 'A Heck of a Ride: Part Two', 'The series concludes as the family escorts Axl to Colorado. Meanwhile the long affair of the snow globe and its relation to Sean and Sue''s relationship comes to a head.', '2018-05-22', 22, '/zo5x22mJyNLvZA6EF2dk1PSkrM4.jpg', '2026-04-03T15:40:31Z', '2026-04-03T15:40:31Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('64d23d54-146c-472e-823c-a1e84ffba194', 'b1d55597-d9d2-4eee-ab95-46dbb163291a', 9, 'Pingu Plays Fish Tennis', 'It is time for Pingu and Pinga to go to bed but they have other ideas. First they play with their blocks and fakely fight over them, and then mum tells Pingu to brush his teeth and he goes by shuffling with the block boxes on his feet. Pingu brushes the bathtub instead of his teeth, then knocks Pinga''s potty, and mum finally manages to get them to go to the bedroom. At first they tried to leave when she wasn''t looking. They keep demanding things such as a teddy, pacifier, fish, or bottles. When she stops coming to their demands (though Pinga made one), they go out to find their exasperated mother asleep. They move her into the bedroom and finally go to sleep all together', '1988-10-29', 5, '/di7PLSt5aLtsnUmrMbSJcajiI4V.jpg', '2026-04-03T17:22:18Z', '2026-04-03T17:22:18Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('64dc9096-6bbe-45ed-aff4-039707c10c0c', '8e5ed8a4-08e5-4006-9f36-c68c91ddfee4', 1, 'Episode 750', '', '1994-11-21', NULL, NULL, '2026-04-03T17:36:40Z', '2026-04-03T17:36:40Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('64e494ef-89c5-4a78-aafc-3378752b82e2', '671bd4da-3470-40f9-9a03-40fba34d2b8e', 6, 'The Setup', 'Frankie''s mom stays with her after becoming ill; Sue suggests to Sean that they should set each other up on dates; Axl and Brick ponder what Mike actually does at the quarry.', '2017-11-07', 22, '/yqpanCQO4axA2wh59hZMFCJkq7f.jpg', '2026-04-03T15:40:31Z', '2026-04-03T15:40:31Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('64e4f2dc-78f3-4b3d-b0c9-edf24ef232da', '9193e795-da7c-40ec-b68f-f63aa7d5174f', 275, 'VFX: Creating the Wall', 'The visual effects team discuss how they visually created the Wall.', '2014-02-18', 1, NULL, '2026-04-03T15:40:35Z', '2026-04-03T15:40:35Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('64e57f56-2835-42bf-bdb9-ef64ef18a685', 'f0f8b366-cb33-40b3-a50f-a1ca7780916f', 9, 'Ring Around the Rock', 'It''s Ma and Pa Gorg''s 513th anniversary, and they must get married again. But where''s the ring?', '1987-03-02', 24, '/xtROimI3f9dbw1B3lH5OL9tYsSU.jpg', '2026-04-03T17:35:01Z', '2026-04-03T17:35:01Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('64ea50c2-95f1-4167-a6e2-38dbe4bfda18', 'fe19a277-aed8-44df-a4ac-fc1c4e9941b4', 12, 'Baby Momma & Daddy Drama', 'Kim and Shereé return to the "scene of the crime" at FAB to make amends and to plan a surprise engagement party for Kandi and AJ. Meanwhile, Kandi, AJ and Kandi''s mom visit a marriage counselor to help ease the tension. Shereé’s finished samples for her She by Sheree line finally arrive, and she unveils them to Dwight for the first time. NeNe and her Uncle Mel travel back to her roots in Athens to give her book writer a glimpse into her life growing up. While in Athens, NeNe finds herself face-to-face with the man who claims to be her biological father.', '2009-10-15', 43, NULL, '2026-04-03T16:34:45Z', '2026-04-03T16:34:45Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('64f6482b-ec80-4171-9246-6982c666c851', '331fc1df-6d70-4d79-b585-bf28024a4124', 13, 'The Wrong Smell', 'Helen Flood and Firefighter Penny Morris go on a mountain hike while Firefighter Cridlington tries to teach Radar the Rescue Dog how to roll over. When the fog rolls in and Firefighter Penny Morris hurts her ankle, she and Helen Flood become lost. Fireman Sam, Radar the Rescue Dog and Tom Thomas come to the rescue.', '2008-11-27', 10, NULL, '2026-04-03T17:14:39Z', '2026-04-03T17:14:39Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('6500334f-a1f6-4f90-a307-c0f67e559b71', '79916e0e-881c-43a7-b4ee-00e5052a94be', 14, 'Foduck and the Rainbow', 'A string of unexpected, sudden changes to Foduck''s routine deeply upset him because he liked the way his original routine was.', NULL, NULL, NULL, '2026-04-03T17:10:11Z', '2026-04-03T17:10:11Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('65011dff-11d6-4490-914e-d7aef4509f08', '4d2cac0f-38fd-438b-8afa-acf43952e535', 368, 'Episode 368', 'with Christopher Trace and Valerie Singleton.', '1965-06-14', NULL, NULL, '2026-04-03T17:21:47Z', '2026-04-03T17:21:47Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('65033d34-05bb-4ab1-9d4e-aeb21b8ca228', 'bb919aec-0d5c-4c58-9a5a-fa2a0a5de2b6', 52, 'Episode 457', '', '1973-02-06', NULL, NULL, '2026-04-03T17:36:29Z', '2026-04-03T17:36:29Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('6504ce04-64ed-4e11-a5ce-ca0fa455e1fe', 'f593d90c-5339-42f5-9c88-5bfd48d04075', 29, 'Whistleblower', 'Bitzer loses his precious whistle and tests out a trumpet as a replacement. Before long, the power of the trumpet goes to his head and his fanfares and jazz styled bugling drives the flock around the bend.', '2010-07-18', NULL, '/xuvXymVTG2lhOWMd8dA2E4NsBE3.jpg', '2026-04-03T17:39:31Z', '2026-04-03T17:39:31Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('6505c4ee-c022-4344-89f2-28db23e26be9', '5a6d9a42-165b-4b56-9273-0a06874dfe10', 4, 'Madeline''s Rescue', 'As we know well by now, no one knows better "how to frighten Miss Clavel" than Madeline.', '1991-06-06', 23, NULL, '2026-04-03T16:34:01Z', '2026-04-03T16:34:01Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('650bc26c-c644-4008-99f3-e9dd2fe6071e', 'bb360d44-75ef-4ac3-9d24-461c5c182502', 1, 'Good Cop / Bad Cop', 'Season 1 Minisode 1: Hank and Marie celebrate Valentine''s Day.', '2009-02-17', 3, '/t729tFVXPetnJlJ2VsUZQz0rX6v.jpg', '2026-04-03T15:40:32Z', '2026-04-03T15:40:32Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('650dcbc3-d1a6-4f98-8339-cb40b2bbcd85', 'bf874be3-7e2f-4a0e-b205-c76ac1ad69fc', 84, 'Inside Looks (on The Chaperone)', 'Inside look from the season 6 episode "The Chaperone."', NULL, 22, NULL, '2026-04-03T16:34:09Z', '2026-04-03T16:34:09Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('6522a9c0-326e-4c96-ab31-28f49e136f4f', 'd306a064-e835-417e-8548-0cf806295f31', 10, 'Diamond Rings and Rumors', 'Larsa receives an unexpected package; Guerdy puts work aside to make time for family game night; Julia starts spreading the news about her adoption plans; at her engagement party, Nicole avoids her dad and defends her reputation against a rumor.', '2023-01-19', 44, '/rU8j3aBgMxqYkhWnT5zABaZjJjv.jpg', '2026-04-03T16:35:11Z', '2026-04-03T16:35:11Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('652722c1-4b2a-4c21-81c9-a8c86b68202e', 'c9adc698-be92-4dd7-94ad-d8f6759361ca', 37, 'Episode 37', 'Rogers visits the dentist. In the Neighborhood of Make-Believe, John Reardon agrees to give Pilot Ito opera lessons. King Friday commissions an opera for Friday.', '1973-04-10', NULL, NULL, '2026-04-03T17:35:40Z', '2026-04-03T17:35:40Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('653c7b9d-cebe-4636-a417-bbf81d906c9d', '90cc8678-a14f-4d05-bc1e-54a3117895d5', 8, 'Like Father, Like Son', 'Bold has left White Deer Park and is enjoying his new independent life. He first meets Crow then a friendly female Badger called Shadow when he unintentionally enters her den. He catches a pheasant for her and they become friends. She warns him about the gamekeeper, which explains the abundance of pheasants and a lack of foxes. Shadow gets caught in a trap meant for him and stays to release her when the human is on his way. However as he chews through the wire it springs back, releasing her but catches him in the eye. Later when hunting for pheasants, unable to see out of his injured eye he does not notice the farmer until it is too late and Bold is shot.   Meanwhile back in White Deer Park, Charmer the remaining female cub of Fox and Vixen meets and befriends Ranger, Scarface''s son. Scarface kills Mrs Hare and so Mr Hare moves his family back onto Farthing land. The animals plot to kill Scarface by stealth the way he probably did to kill Dreamer. They elect Adder but make the mistake', '1994-02-25', 25, '/tLZVfphCKOlnhavzfFxAUnfQzIr.jpg', '2026-04-03T17:18:49Z', '2026-04-03T17:18:49Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('65455172-9bf9-4f59-a63e-29a6da8c77ad', 'd9973960-273b-4a92-a7da-62efe8860d09', 2, 'A Snow Mountain of Trouble', 'Meredith''s birthday party comes to a cold ending when Jen and Mary get into a heated argument about Mary''s insensitivity towards Jen''s aunt. Whitney confronts Lisa about an incident at Whitney''s vow renewal. Meredith battles marriage problems.', '2020-11-18', 42, '/zjSO3um54aJfIbVTP1koFLRYC9L.jpg', '2026-04-03T16:35:44Z', '2026-04-03T16:35:44Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('6548823d-580e-497d-b241-5a59268190f5', '9c5608b2-5111-48bc-a907-7f93472c1e03', 2, 'The Good Sport', 'After losing to Abby in several games of hot potato, Elmo turns to Telly for help in becoming better. He becomes so good that, the next time he plays Abby, he repeatedly wins; and then his newfound skill goes to his head, causing him to show off.', '2012-09-25', 58, '/csVHXtIaW9ilR5DUlAp17UV0DyJ.jpg', '2026-04-03T17:36:47Z', '2026-04-03T17:36:47Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('65498de5-eb4e-4693-af80-b87a4a43e72f', '2aebfad4-3145-4bc1-9def-5f1d5bdfcfc8', 18, 'The Boyfriend (2)', 'Jerry and Elaine compete for the attention of baseball''s Keith Hernandez, while Kramer and Newman investigate a spitting incident involving Hernandez.', '1992-02-12', 24, '/wEf06gmg5jb8anj0dpTiwvFNbFQ.jpg', '2026-04-03T16:34:10Z', '2026-04-03T16:34:10Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('654d3252-5d0c-4b22-bf7b-778123f21bc5', '90cc8678-a14f-4d05-bc1e-54a3117895d5', 10, 'Shadows', 'Bold arrives in the town with Crow and they continue to keep their bargain of feeding one another. While wandering the town for food Bold comes across a female fox but she doesn''t seem interested. The following night he sees her again and they hunt together and she, Whisper invites him back to her earth. However he can''t break his agreement with Crow so goes back to him. Crow frees him from his agreement so that Bold can be free to see Whisper and says that if they need each other, to leave food under the bush. Bold goes back with Whisper to her earth in the Church grounds and tells her his story when she thinks that he is old. She is honoured to know him, the son of the famous, heroic Farthing fox.   Meanwhile Friendly finds out that his sister Charmer is seeing Ranger and informs his parents. Fox is not happy about it and agrees to meet him. Ranger says that in a fight between the Blue foxes and the Farthing Wood animals he won''t fight for any side. A sad event leaves the animals gri', '1994-03-11', 25, '/jCocbimUBUrkLrGdVaWDlfxh0LH.jpg', '2026-04-03T17:18:49Z', '2026-04-03T17:18:49Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('655354a1-ef8a-4e67-854b-8f7b443967f5', '87161406-2fce-4cd5-a716-ab2c19f08860', 1, 'Three More Little Pigs;The Ants And The Grasshopper', 'Lionel, Leona, and the Wolf each try their hand at writing a sequel to The Three Little Pigs, and Leona finds a way to work and play. Educational Goals: Highlights the joys of reading and introduces key literacy skills. Focuses on short u, the sound represented by the letter m, and synonyms for small (miniscule, little, petite, microscopic, tiny, teeny, diminutive, weeny).', '2010-09-20', 30, NULL, '2026-04-03T17:12:30Z', '2026-04-03T17:12:30Z');
