INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('6563ca90-d093-4bad-86b6-8d79ed9512c8', '52135215-5160-4d42-9d0f-db242b1abcaa', 2, 'Martha Speaks', 'A telephone call has distracted LeVar just as he was about to show the viewers a book about cats. While LeVar''s away, his dog, Luke, has the ability to talk and take over her hosting duties. Jo Hayden narrates the story of a dog who has the ability to talk after eating all that alphabet soup. Featuring Charles Fleischer as the voice of Luke.', '1995-10-03', 30, NULL, '2026-04-03T17:36:19Z', '2026-04-03T17:36:19Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('6570c1f3-051a-43ea-8e32-1e36702d7f38', 'a8c6182e-05e1-4b68-91a5-5126cf6c94f0', 17, 'Captain Molly', 'With General Washington losing battle after battle, James'' confidence wavers. He and Sarah go to Washington''s camp to report from the front lines. However, because she is a girl, Sarah is sent to Fort Tryon with the other women and children. There, she befriends Molly, a spunky patriot whose husband was killed fighting the British. But then James finds out that the British are going to attack Fort Tryon!  Meanwhile, back in Philadelphia, Moses starts teaching Henri how to read.', '2002-09-24', 30, '/mdVVWbIMrXmNQcO5y1hmEtaCItb.jpg', '2026-04-03T17:38:28Z', '2026-04-03T17:38:28Z');
