INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('65978d38-ea5f-4ab5-b48c-0553d18d4045', '740a96a0-a075-4be2-be92-a178d0939384', 20, 'Elmo''s Butterfly Friend', 'Elmo and Telly learn how a caterpillar turns into a butterfly through metamorphosis.', '2018-03-31', NULL, '/aUAXEkjzWHvhYZnbv063FJImN9O.jpg', '2026-04-03T17:36:49Z', '2026-04-03T17:36:49Z');
