INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('65bff205-ae30-4e23-99e0-b2ad673495b6', '208e80de-61e3-4a2f-857f-c667ffc29134', 8, 'John Denver', 'John and Kermit have a surprise for the cast; they''re all going to Kermits'' home the swamp! But even Gonzo, even with his love of the nasty and strange, thinks it''s a bad idea and no one is willing to take him up on the offer even when Kermit offers them to go.', '1979-12-14', 26, '/5eaxWmK3h7tiSt8ZuR0VKyjyulZ.jpg', '2026-04-03T17:35:25Z', '2026-04-03T17:35:25Z');
