INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('66dafaef-76bb-48f7-b4d7-0925947c51e9', '20d7138e-eea8-46a8-8ada-2b0f0ee1f674', 9, 'Episode 9', 'Meet Captain Webb-Foote and Vaniiuht Fannv Jones - not forget-tine Fiona and her amazing. ballet performed upside down with her head in a bucket.', '1982-10-11', NULL, NULL, '2026-04-03T17:21:56Z', '2026-04-03T17:21:56Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('66e17a6d-8e34-4a13-88a7-1ff94db57cc8', '3ee646e8-23ae-4dec-bbc6-c7e6a210d55b', 3, 'Little Bird looks for a home', 'Telly talks to the viewer about all the things on Sesame Street he can be sure about every day: Oscar will always pop out of his can, Bob will get out of his apartment, Gordon will always come out of 123 Sesame Street, and Big Bird will always come out of his nest area.

Sponsors: D, H, 18', '1990-11-14', NULL, NULL, '2026-04-03T17:36:38Z', '2026-04-03T17:36:38Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('66e535ff-fc40-408c-881d-c996204b3da7', '4892e2af-46c1-4b4e-ac81-eac161b5a347', 28, 'Episode 28', 'Today JOHN lights the first candle on the Advent Crown, PETER goes north to Beamish and rides on a Sheffield tram, and Britain''s top pet cats compete for the title Blue Peter Champion Top Cat 1977 and the silver trophy '' live'' in the studio.', '1977-12-15', NULL, NULL, '2026-04-03T17:21:53Z', '2026-04-03T17:21:53Z');
