INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('67343a73-b4de-4492-a8f7-1b652848fbe0', '04207e76-d855-4f29-a066-1732feea34b5', 4, 'Babies, Bubbles and Bubbies', 'Teresa and Joe welcome their fourth child into the world. Meanwhile, Chris Manzo scores big when he gets an inside look into his dream business, Jacqueline gets a peek into her husband''s secret safe, and Danielle gets an invitation she can''t refuse but makes sure to get back-up from an old friend before she replies.', '2010-05-24', 43, '/pVJtW2cVk0mjKZinCahfr3d3AR6.jpg', '2026-04-03T16:35:15Z', '2026-04-03T16:35:15Z');
