INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('67489f96-cd83-4ca8-8454-4851a1b18fb7', '5db3ff78-e439-48e1-8f67-988ecbf85d17', 20, 'Dogtanian and the Blue Falcon', 'After foiling Richelieu''s plan to destroy the reputation of Queen Anne Dogtanian is training to become a musketeer. This involves running up, and falling off, a tree as well as slicing leaves. While resting on the grass Dogtanian explains to Pip that he can''t join the musketeers until a musketeer leaves the corps, coincidentally Aramis arrives seconds later to tell Dogtanian there''s now a vacant post. But Dogtanian will have to pass some tests: sword-fighting, horse riding, swimming and a trek through the forest in the middle of the night to find a hat...', '1982-02-12', 24, '/hYUxJjUQhLJJhgGOSm2K9T2eMVg.jpg', '2026-04-03T17:18:43Z', '2026-04-03T17:18:43Z');
