INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('67636874-4945-417c-b68f-f0e764f60cc5', '4f149920-ca76-4c31-a71b-d5b65a380905', 1, 'A Christmas Special', 'Celebrate the holidays Pawn Stars style as the Old Man surprises the gang with a special holiday treat. But nothing goes according to plan as the guys take a look back at their best and worst moments of the year and learn what happened to some of their most memorable items. After the trip down memory lane, will the Old Man be rewarding with the gift of gold or grinch it up with a gift of coal?', '2009-12-21', 42, '/20dtgmkx5bPvfvDbHWyR8jcvDES.jpg', '2026-04-03T16:34:15Z', '2026-04-03T16:34:15Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('6765f191-6499-40fa-b6bb-cac90e4e6556', 'ad4e4348-3334-4a08-8928-455d9ba524c1', 3, 'James Coburn', 'Animal hits it off with tough guy James Coburn -- but James decides that Animal isn''t centered enough, and introduces him to meditation and Zen. Animal doesn''t take well to Zen.', '1980-10-19', 26, '/a13M9mBwOdgJeG1MWwhBVhYZ7Uf.jpg', '2026-04-03T17:35:25Z', '2026-04-03T17:35:25Z');
