INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('6793880a-9ee6-4813-80cb-ca928608abf7', 'd9973960-273b-4a92-a7da-62efe8860d09', 5, 'Ladies Who Lunch', 'Mary’s luncheon ends in disaster when Jen accuses Mary of being racist and Mary accuses Heather of being two-faced. While Whitney deals with her daddy issues, Meredith’s marriage problems escalate and Lisa reflects on her own marriage. Heather, caught between two friends, attempts to smooth things over with Mary who is still hurting over the things Jen said about her.', '2020-12-09', 41, '/f1p24KmLTUMWiShTPbyhMQsj8iN.jpg', '2026-04-03T16:35:44Z', '2026-04-03T16:35:44Z');
