INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('67d53903-7c9d-4df5-a0b5-c87cdf270739', 'da06465b-9154-4feb-a455-374df7dab02f', 3, 'Health Food Game Show (4085)', 'Healthy Food   Spanish Word - gato   Location - Paris France   Number of the Day - 6. The letter "G" and the number 6; nutrition. Elmo plays the Healthy Foods Name Game, in which he has to find nutritious foods of various colors. Jeopardy! champ Ken Jennings joins Grover for a Health Moment, and reggae artist Wyclef Jean sings about healthy food with Cookie Monster.', '2005-04-06', NULL, NULL, '2026-04-03T17:36:44Z', '2026-04-03T17:36:44Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('67dd144f-f625-4557-b541-7691031ef8ee', 'c1df0e9b-e03e-48e5-a930-61ee5ef85840', 6, 'The Shore Thing', 'Arthur and D.W. are obsessed with going to Aqualand. They beg their father to go with them, but David tells them that going to Ocean Zone would be more fun.', '2000-09-18', 13, NULL, '2026-04-03T17:37:56Z', '2026-04-03T17:37:56Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('67dea660-9477-490a-b48c-eb07f226e1f6', '68138de2-0900-460a-b58e-480688f1e081', 32, 'Boys Will Be Boys', 'When Bear receives a photo of Ursa in the mail, Ojo is off and running, discovering her "girlness." But as she and everyone else in the Big Blue House learn, it''s not being a boy or a girl that matters. It''s just being yourself.', NULL, 25, NULL, '2026-04-03T17:35:31Z', '2026-04-03T17:35:31Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('67e3fff2-5f0b-4243-8080-66bd8d03d794', '543ec6dc-c6c7-447c-b5a7-4484d9618391', 11, 'Reunion (2)', 'The ladies of D.C. reunite in the second part of the reunion, and bring closure to the events that unraveled during the season.', '2010-10-21', NULL, NULL, '2026-04-03T16:35:01Z', '2026-04-03T16:35:01Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('67e67e3a-2e6a-4d8b-b3c6-c73170ca0086', 'ca19f895-1514-4988-a709-95e84eab7cee', 7, 'Dueling and Dealing', 'A seller shoots for the moon, when he comes in with some Apollo 11 documents. Can Rick bring him down to earth before we have a problem? Then, a Harley Davidson 1962 Topper scoots into the shop. Can Chum get the bottom price on this bike? Next, Rick checks out a Renoir etching. Will it make a real impression, or is it too abstract? Finally, the stakes are high when the guys leave the shop for a little friendly competition. Will things get hairy for Rick, or scary for Corey?', '2020-12-21', 42, '/sNBxpLbNpWBrOO2FcXVeHjtThqx.jpg', '2026-04-03T16:34:22Z', '2026-04-03T16:34:22Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('67e8ac46-fb66-4b13-82ff-ba064d7330cd', 'f4c40307-9b5e-4263-a4e0-dfa138131e7f', 50, 'Counting With Elmo', '', NULL, NULL, NULL, '2026-04-03T17:36:27Z', '2026-04-03T17:36:27Z');
