INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('67ed395e-1d17-4514-8c1e-541952903529', '9193e795-da7c-40ec-b68f-f63aa7d5174f', 271, 'From Imagination to Reality: Inside the Art Department - Part 2', 'Part 2 of an extensive featurette detailing the astonishing work of Production Designer Deborah Riley and her art department, dissecting the process behind the creation of season 7''s incredible sets, including Winterfell, Euron''s ship Silence, the loot train and the frozen lake.', '2017-12-12', 22, '/xFkr7TQ2pfkMGLwK5Zlqp5RGGKZ.jpg', '2026-04-03T15:40:35Z', '2026-04-03T15:40:35Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('67eede61-dea7-40f8-b05a-d886034c2368', 'ab509c47-ec64-4fb3-8560-03873dd0c37e', 4, 'The Chinese Woman', 'Jerry makes a blind date; Kramer makes a change to increase his sperm count.', '1994-10-13', 22, '/r1n6cs053TI8hBIPjuUhZHZJht4.jpg', '2026-04-03T16:34:11Z', '2026-04-03T16:34:11Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('67f9c9ab-4cca-43c2-9816-852435369b67', 'd920ebae-f00a-4e25-abfe-40492c74ded6', 12, 'Pawnanza', 'Saddle up with the Pawn Stars as they check out some vintage horse equipment. Will Corey say yay or neigh to the McClellan Saddle’ Next, a rare Pee-wee Herman scooter rides into the shop. Will the word of the day be “sold''” Then, a seller comes in looking for an offer on his signed poster from the TV show, “Bonanza”. Will Rick strike gold or will this deal be a “lode” of crap’ And later, a first edition of the classic book “To Kill a Mockingbird” flies in. Can Rick make a deal, or will he have to set this bird free’.', '2020-03-02', 42, '/iacnXEduSbF6A5fTL3bpM29JbCJ.jpg', '2026-04-03T16:34:22Z', '2026-04-03T16:34:22Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('67fd98fe-c2fb-44e1-a1f5-bd4a1d9bcd44', '1be79a20-de33-41d1-af17-079035b18d5c', 36, 'Mr. Glopper Sets Up His Hot Dog Cart on the Street', 'Sponsors: L, U, Y, 4, 5', '1969-12-29', NULL, NULL, '2026-04-03T17:36:28Z', '2026-04-03T17:36:28Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('67fe57a0-f17e-4df3-b72f-4e85e051aa04', 'a860511c-b630-415e-99a1-a9e0922fbfd7', 17, 'The Trouble with Trophies', '', '2012-05-25', 13, NULL, '2026-04-03T17:38:00Z', '2026-04-03T17:38:00Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('67ffca4c-1446-4f60-a993-a2db62142db9', '913f846d-85df-4694-8dd4-0d5909f78887', 9, 'Moderation', 'Zach is excited about the launch of a new cable network called The Kids Movie Channel. Although he promises his parents that his movie watching won’t interfere with his studies and chores, Zach overdoes it, causing concern ... and a story up at Plato’s Peak about the importance of moderation.', '2000-11-19', 30, NULL, '2026-04-03T17:38:35Z', '2026-04-03T17:38:35Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('67ffdd76-d4a3-42c4-bcf8-d3e247b25e89', '5144de59-e67f-4fcf-919b-7106989ab797', 35, 'Everything In Its Place', 'Kiki makes plans to clean the place, but it doesn’t go as planned.', '1995-03-03', 29, NULL, '2026-04-03T17:12:21Z', '2026-04-03T17:12:21Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('68092648-d435-45a9-b636-df6d60f2573e', '7c542833-ed0a-4272-9c53-e822408ab434', 9, 'Back to the Stone Age', 'Competition between Norman and Derek to make the best stone age shelter goes too far and causes a fire on Pontypandy Island.', '2024-10-10', 10, '/tWN4i8GWG39rYPQa6tI4Yar6kzv.jpg', '2026-04-03T17:14:42Z', '2026-04-03T17:14:42Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('680ca9b8-7019-4405-aeb1-f642436c0c4a', 'd5f0284f-0ee3-45bf-8539-d02a825d15b2', 8, 'Palm Beach Pandemonium', 'The ladies play croquet in Palm Beach. Lisa is interrogated at dinner about her financial, parenting, and relationship choices. Nicole''s family expands in a way that she could have never imagined. Lenny files a motion citing Lisa as an unfit mother.', '2023-12-20', 44, '/dmShRheUxC2Szgq8QdKglAK4GF8.jpg', '2026-04-03T16:35:12Z', '2026-04-03T16:35:12Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('6810504b-75d4-4cd8-a084-d115412b8fda', '42e591e2-2a88-4434-ae9f-3d4b1d685613', 1, 'Rick ''n'' Roll', 'Turn it up to 11 with the Pawn Stars when Rick attends Rock and Roll Fantasy Camp. Performing with rock legend Roger Daltrey of "The Who," will Rick hit all the right notes? Then, Chumlee and the Old Man check out a collection of tin toys from the early 1900s. Can they turn this play date into a payday? And later, a tonsillotome finds its way into the shop.', '2013-05-30', 21, NULL, '2026-04-03T16:34:18Z', '2026-04-03T16:34:18Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('68116b9e-0bb8-45e2-9546-b7defa082093', '4060ad7f-4b8f-4393-8eb1-66a150b928b6', 35, 'Move and Groove on Sesame Street', '', '2021-07-01', 26, '/qD29xYtNnyxOOoMyt8bgPdFDN7T.jpg', '2026-04-03T17:36:50Z', '2026-04-03T17:36:50Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('681b1d17-2e89-4fb1-a4b5-2f1d9848c936', 'a3a2c2fb-8276-412c-9d86-5175167be1d7', 52, 'Episode 52', 'with Valerie Singleton, John Noakes, Peter Purves', '1972-03-13', NULL, NULL, '2026-04-03T17:21:51Z', '2026-04-03T17:21:51Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('681d5b90-c59d-4b28-9262-862b966655ed', '787dfa0b-c827-4dad-a82d-0548a6534d88', 22, 'Reunion (3)', 'The reunion concludes as the women and Briana confront Vicki head on with their doubts about Brooks'' cancer. Shannon provides shocking details regarding the validity of the PET/CT Scan, Tamra and Heather confront Vicki about the possibility of being blackmailed, and all of the ladies have strong reactions to Andy''s taped interview with Brooks. Then, Vicki makes a stunning revelation that has everyone doubting what they''ve heard.', '2015-11-01', 44, '/1CCJCOLvwX4ICmzBREkGuXiNDj2.jpg', '2026-04-03T16:35:32Z', '2026-04-03T16:35:32Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('681df173-a283-44d5-b106-5cffd970507f', '3ee646e8-23ae-4dec-bbc6-c7e6a210d55b', 74, 'Oscar and the word man', 'Elmo tells the viewer that because he''s so small, he can identify everyone by their knees, including Alex, Big Bird, and Linda. He also likes how knees allow big people to get closer to their smaller friends. A uniformed man knocks on Oscar''s trash can and declares himself as the "Telephone Man." Oscar asserts that his phone isn''t broken, nor does he need to be sold a new one.

Sponsors: E, Y, 12', '1991-02-21', NULL, NULL, '2026-04-03T17:36:38Z', '2026-04-03T17:36:38Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('6822c52e-13a3-4b8d-a5b3-b74b70273dc9', '3ee646e8-23ae-4dec-bbc6-c7e6a210d55b', 7, 'Elmo and Gordon make cookies/Snuffy does magic', 'Elmo joins Gordon in his kitchen, trying to guess what Gordon will be preparing. Elmo observes the newly-baked cookies and explains Gordon has stepped out to get some ice cream to eat along with them.

Sponsors: D, U, 10', '1990-11-20', NULL, NULL, '2026-04-03T17:36:38Z', '2026-04-03T17:36:38Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('6824a705-9a1d-40b2-bb7a-bfe02d94c5b6', '38bf8c20-c17c-4071-9226-7887787cf1b1', 12, 'Oh, Yes, It Can!', 'A storyteller visits the library one day, and tells an old story about a Yammering Yam and how it led to a whole series of unbelievable (but true) events for a farmer, a fisherman, and king.', '2001-04-17', 30, '/ogRmpV2YkT9AggI809PpUQEB5eu.jpg', '2026-04-03T17:12:28Z', '2026-04-03T17:12:28Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('682887fb-1926-46fb-8a87-00cd32693ab4', '53f9624f-fcf8-4f77-82f6-d2eb3f5376ee', 13, 'Give Up the Ghost', 'Christine goes shopping for her dream wedding dress while Meri meets with two of her friends and struggles to come to grips with her new reality.', '2024-12-08', NULL, '/uKZgPuKt5XJaap4KqREwD00alu3.jpg', '2026-04-03T16:34:33Z', '2026-04-03T16:34:33Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('682b202b-be17-4aaa-8865-61e0c2b119fc', '5ba20443-d99f-4820-81f6-6832d3f2bc4f', 15, 'Invertebrates', 'Worms, squid, clams, and flies are spineless creatures. They’re not afraid, they’re invertebrates – animals that don’t have backbones. Invertebrates are everywhere. You can find invertebrates in the sea, in freshwater, and on land. There are about 30 times more invertebrates than vertebrates on Earth.', '1996-02-07', 26, '/zmMcGK5ijYTY7wR8oY62j27fVLF.jpg', '2026-04-03T17:37:21Z', '2026-04-03T17:37:21Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('682ee4bf-7bb9-4514-92dc-2582ecb1a394', '04e133fd-c4a3-4dfa-8369-c6dcfd1e3a5a', 107, 'A blackout on Sesame Street', 'When the power goes out on Sesame Street, the residents must cope with darkness and find ways to entertain themselves. They gather together and tell stories, sing, and enjoy each other''s company. The episode shows how community bonds strengthen when everyone works together during challenging times.

Sponsors: P, R, 8', '1985-04-16', NULL, NULL, '2026-04-03T17:36:36Z', '2026-04-03T17:36:36Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('68345b16-bdd4-4d11-85df-fcc4998ea51b', '34674c90-410e-427c-be4d-2a6f6f865a80', 14, 'That Sinking Feeling', 'The tension is sky-high for the Pawn Stars, when a book signed by Charles Lindbergh flies into focus. Chronicling his historic flight, can they stay alert during a grueling negotiation, or nod off and lose control? Then, a medal commemorating the sinking of the Lusitania torpedoes into the shop. Issued by Germany to celebrate their infamous attack, do they navigate dangerous waters for this rare piece, or let it sink without a trace? And later, a guy tries to throw Rick off balance when he brings in a rare 17th century Dutch money scale. Will the deal tip in Rick''s favor?', '2012-06-18', 21, NULL, '2026-04-03T16:34:17Z', '2026-04-03T16:34:17Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('68346d72-4c88-45ea-9fa5-9001731c5260', '0ebba123-871d-4d2b-a054-eb85d2ad9450', 10, 'Madame Blueberry', 'A lesson in thankfulness.', '1998-07-21', 30, '/nVgKxvLNsDkMQ92sy6sprxHWV9E.jpg', '2026-04-03T17:39:39Z', '2026-04-03T17:39:39Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('683728e0-49b0-43ac-b609-f681d8153c97', '5d57283d-079c-4f66-93c8-33a2feeada89', 6, 'The Jump', 'Frankie rescues a lost dog and takes solace in the unconditional love she receives; Sue surprises her parents when she makes the volleyball team; Axl asks Brick for help with school.', '2013-11-13', 22, '/pzjVA5YwQ2aBPuCbdiMhoLlFUa4.jpg', '2026-04-03T15:40:30Z', '2026-04-03T15:40:30Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('683bf4ca-222b-4791-8f88-f1c8a5517a1f', '18da9943-1963-4e04-a7a0-ae63802bb1fa', 9, 'A Peace Treaty, A Blind Date, and a Divorce No One Undertands', 'Tamra''s birthday party for Eddie ends in shambles after an explosive comment is made; Shannon gets set up by a matchmaker and goes on her first date in over twenty years; Vicki fights back about the rumors about her relationship with Steve; and while the women react to Gina''s marital news, Emily and Kelly try to work out their issues.', '2018-09-17', 44, NULL, '2026-04-03T16:35:34Z', '2026-04-03T16:35:34Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('683c0b03-9215-48f4-8eca-3d5cc098a61a', '5c4e51c6-e207-46ad-875c-72988eb1e13e', 24, 'Cannons and Klingons', 'The Pawn Stars fire off to the shooting range to check out an antique signal cannon from the 1980''s TV series Magnum P.I. Will the guys bring out the big guns to make an offer or will they decide this deal doesn''t have enough bang for their buck? Then, the guys feel the heat when a lighter and photos from a top-secret 1950''s atomic bomb testing program come into the shop. Will these items ignite Rick''s interest or will a charged negotiation blow up in his face? And later, a guy beams by the shop with a carload of is signed Star Trek memorabilia. Will Corey and Chumlee boldly go where no deal has gone before or will they send this guy away at warp speed?', '2011-08-01', 21, NULL, '2026-04-03T16:34:17Z', '2026-04-03T16:34:17Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('6840d1ac-a8c8-4e82-b3c0-28e4c357fca9', '40700e8a-1dce-4895-bede-522a13a8bcad', 4, 'Snakebellies', 'Zoboo and the Kratt Brothers find a snakeskin but it doesn''t fit the anaconda in the pool, the rattlesnake sunning itself by the window or even the Burmese python. Finally, Zoboo discovers the owner-a trans-pecos rat snake!', '2000-10-23', 27, NULL, '2026-04-03T17:10:55Z', '2026-04-03T17:10:55Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('6840d527-43d6-4a9e-8c5b-9b33e2b726b7', 'a605edf8-69ba-46db-8c0c-523b1ef5447b', 1, 'Episode 1', 'with Valerie Singleton, John Noakes, Peter Purves, Lesley Judd', '1972-09-11', NULL, NULL, '2026-04-03T17:21:51Z', '2026-04-03T17:21:51Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('68434d80-265d-4019-817f-89207c28e491', 'e48599f8-66ff-4c0f-9274-65b9ae1cda9e', 37, 'Episode 37', '', '1977-01-20', NULL, NULL, '2026-04-03T17:21:53Z', '2026-04-03T17:21:53Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('684b853c-4a08-45e9-badd-85dee6c98359', '136b81d3-964d-4b8f-a214-92f00d96d6b9', 130, 'Sally Ride talks about being an astronaut', 'Astronaut Sally Ride visits Sesame Street to talk about her incredible experiences in space and what it''s truly like to be an astronaut. She explains her training regimen and emphasizes the importance of science and education. The kids are inspired by her achievements and courage.

