INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('68e015e0-033a-4eff-8065-4c2f0dfb9682', 'ea1650c2-e4f1-46c7-93ba-74b5d45d08e5', 12, 'Not So Fine Print', 'With her tour quickly approaching, Kandi has only a week to finish her new album and make sure that Kim is stage ready as her opening act. Cynthia tries to reconcile with NeNe and make up for the awkwardness of her "friendship contract," but NeNe''s got bigger problems when she''s put on the spot to deliver a big celebrity interview for her local entertainment segment. Mother definitely knows best when Sheree and daughter Tierra go furniture shopping, and Phaedra, fresh out of the maternity ward, is in full protective mommy-mode and confronts Kim about all the bad-mouthing she has been doing about her due date.', '2010-12-19', 43, '/3oheYuhqyveE0J6gbcFTAelDvAw.jpg', '2026-04-03T16:34:45Z', '2026-04-03T16:34:45Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('68e1f05f-4775-4b49-a2c7-1a6eef2078d0', 'ebc99729-ccb7-4d64-82c1-42708cd7ba85', 67, 'Episode 67', 'Appeal Auction: Last Tuesday all the collectors'' items donated to the Bring and Buy Sale for Disabled People were auctioned at Phillips. Find out whether the proceeds have raised the appeal total to £1 million.', '1981-05-07', NULL, NULL, '2026-04-03T17:21:55Z', '2026-04-03T17:21:55Z');
