INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('68f808e1-ebd6-4215-bec8-e4020d0e254c', 'ad4e4348-3334-4a08-8928-455d9ba524c1', 14, 'Gene Kelly', 'Gene is under the impression that he''s a "guest" -- that is, he''s going to sit and watch, but not perform onstage. Frantic, Kermit tricks him into performing by asking him to give him a dance lesson on-stage. Kermit plans a surprise closing number, "Singin'' in the Rain," Gene refuses, saying that he doesn''t think he''ll ever sing the song as good as he did in the movie, but he does eventually sing it backstage. Meanwhile, Scooter uses his Tarot cards to predict that the world is coming to an end. Beauregard believes him, and tries to convince the rest of the cast the apocalypse is near.', '1981-01-04', 26, '/oJBkuxMx2IsfFXAlfr7MsqAm5IH.jpg', '2026-04-03T17:35:25Z', '2026-04-03T17:35:25Z');
