INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('698b99a8-518f-465d-ab3a-4467edee30bd', '58adb9ab-3f1b-4a11-87b6-9b0b2dbb6aaf', 15, 'Lock Stock and Two Nickel Barrels', 'Hit "The Big Trail" with the Pawn Stars when Rick gets offered a rare movie poster for John Wayne''s first film. Will the asking price scare Rick off, or will he saddle up anyway? Then, a vintage RC helicopter strikes Rick''s fancy. Will their negotiation take flight, or will this deal stay grounded? And later, Chum takes a shot at a couple of nickel plated pistols supposedly made by the most famous gunmaker of the victorian era. Will he meet the seller''s high asking price, or stick to his guns and prepare for a negotiating duel?', '2017-06-12', 21, '/nWjpcLvYmcd4HfHgfkfByb8jOMp.jpg', '2026-04-03T16:34:21Z', '2026-04-03T16:34:21Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('698bd75c-9b4d-462b-ae05-d5c34ff47243', '80775c3d-fa41-46f6-96ec-efc2e14efdcf', 7, 'Family Matters', 'Ramona''s birthday festivities continue after a return from Atlantic City. Meanwhile, the women attend a boxing match; Bethenny journeys to Miami to meet a friend and connect with her estranged stepfather; and LuAnn also lands in Miami for her daughter''s appearance at an art festival.', '2015-05-19', 44, NULL, '2026-04-03T16:35:24Z', '2026-04-03T16:35:24Z');
