INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('69ade019-bd05-42d4-92ca-463412654f2d', 'd5351b60-8a0c-482a-a6dd-4fb860cfe143', 30, 'Episode 1420', 'Mister Rogers arrives with a St. Bernard named Rondo. Mr. McFeely had been walking the dog and Mister Rogers asked to borrow him to show to his television friends.  In the Neighborhood of Make-Believe, the power has been restored and MGR-TV is back on the air.', '1975-03-28', NULL, NULL, '2026-04-03T17:35:41Z', '2026-04-03T17:35:41Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('69aeb767-0e7e-4b85-91ea-63f834174b6d', 'd9973960-273b-4a92-a7da-62efe8860d09', 6, 'Sundance City', 'When Sundance arrives to Utah, it’s nonstop parties and celebrations for the ladies. When Whitney throws her husband, Justin, a 52nd birthday party, Jen and Mary finally call truce. Meredith helps her son Brooks prep for Salt Lake City’s very first fashion week while Heather is on the prowl for a one-night stand, with the help of Vanderpump Rules’ Utah natives Lala and Katie to assist. And while everyone is partying, Lisa is too busy planning Sundance parties for everyone else in Park City.', '2020-12-16', 42, '/vGH1LXpeW8g7tywTleQ1XvIQOdr.jpg', '2026-04-03T16:35:44Z', '2026-04-03T16:35:44Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('69b467e2-bb45-4b10-bdd1-2932681539fc', '97d7ff20-e6ff-4dbb-bcdd-fd87a1d0fa4e', 5, 'Chum Goes to Hollywood', 'Rick tackles a football helmet signed by 28 Heisman Trophy winners - but can he manage to get the seller''s price a touch down? Then, Corey gears up to buy a devastatingly cool "Transformers" toy for the shop. Can he build a good deal, or will it all fall to pieces? Meanwhile, Rick tries not to go psycho over an Alfred Hitchcock poster that makes a cameo in the shop. And later, Chum travels to LA to iron out a deal for some vintage garb. Will he be able to thread the needle, or will his trip be oh sew pointless?', '2023-04-12', 41, '/9AAlGhMu7nvQy6dWEgeRn80tdTM.jpg', '2026-04-03T16:34:23Z', '2026-04-03T16:34:23Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('69b5c4cf-b6af-4ca6-8373-72df70cfee00', '7da1b693-04d1-4168-a0a0-9715407c04c6', 9, 'The Great Party Panic', 'Sarah and James throw a spooky party at the Whole Fish Cafe, but when their ornate centerpiece catches fire, all the guests are trapped inside.', '2016-06-04', 10, '/vmUF3iJJEMj0ja5To5SmFzF5hod.jpg', '2026-04-03T17:14:40Z', '2026-04-03T17:14:40Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('69b8a096-8409-4370-8916-e6731524b23b', '7b8e3988-fbf3-4cfc-aeb2-782ae5a64e2d', 5, 'What’s That Noise', 'Elmo is sleeping over at Maria and Luis'' apartment. When Elmo tries to sleep, he hears a strange noise. He calls them in, but the sounds stop when they listen.', '2010-10-01', NULL, '/kypRKo0BZx10eRFIFi29Qpjui2H.jpg', '2026-04-03T17:36:46Z', '2026-04-03T17:36:46Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('69ba9f00-91d9-4072-b86a-0a7fab09312c', '3982796b-5451-4100-9042-46bedf6a20a5', 14, 'Pingu the Apprentice Magician', 'Pingu is proudly presenting his magic tricks to Pinga and Pingi. He baffles them with the scarf and tube trick, he amazes them by disappearing from behind a sheet leaving only his hat and the sheet behind, and then reappearing in his trunk, and puzzles them with his hat trick. He then changes Pinga into a snowman, the snowman is given several different heads, such as Robby’s and Pingo’s, and finally appears headless; Pinga then reappears. Pinga is then made to disappear from inside a box put over her. Pingi is very puzzled until she sees how Pinga gets back inside the box. Pingu then shows his levitation trick, but unfortunately for him Pingi already knows how this is done and gets Pinga to cut the strings that support the sheet with scissors, much to Pingu''s annoyance. Pinga and Pingi laugh! Pingu finishes by folding up the sheet he used for the levitation trick and throwing it into the air, where it shimmers and then disappears. Pingu takes a bow, and Pingi and Pinga applaud.', '1993-06-29', 5, '/wwZogZAD6ZWe4UntBdFHAPrAMly.jpg', '2026-04-03T17:22:19Z', '2026-04-03T17:22:19Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('69bcef6a-1a78-4a95-bd40-7e1e1dfe30a6', '3087a3ed-e94e-4276-9d02-a78183dea1d3', 3, 'Call Me Miss USA', 'New housewives Kenya Moore and Porsha Stewart socialize at a high-class charity event, but their relationship has a rocky beginning. Meanwhile, NeNe visits New York City for meetings; Phaedra focuses on releasing a workout video; Kim considers moving back to her old home.', '2012-11-18', 43, NULL, '2026-04-03T16:34:46Z', '2026-04-03T16:34:46Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('69c031ba-842e-4455-aa2f-6882ed96ecba', '50ee8f6c-645c-4d48-bab9-53b9f8f7ff2f', 7, 'Humpty Dumpty''s Big Break', 'Telly is very worried about Humpty Dumpty falling off the wall, but Humpty explains that he is there to watch a football game', '2011-10-07', NULL, '/2Tbjy49EC0gawvA3mhxi4Szwjhz.jpg', '2026-04-03T17:36:46Z', '2026-04-03T17:36:46Z');
