INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('6a05ec6b-7b12-4ab4-a691-1b1d39ece640', '5a771f52-fe96-4ea2-b567-a8dde899059e', 23, 'In the Presence of Greatness', 'Rick and Chum grapple with a Batman utility belt toy from the 1960s. Will they be hooked into buying it? A gorgeous Mosrite electric guitar shocks everyone at the shop, but will Corey and the seller be in tune when it comes to making a deal? Rick continues his hunt for "The Object," an item featured in the album art for Led Zeppelin''s album "Presence." When one that''s for sale ends up on his counter, can he be objective about this object of his desire? Later, an autograph book signed by 41 comic book artists draws Corey''s attention. Will he sign on the dotted line after drawn out negotiations?', '2018-03-05', 21, '/wJj2PaOkrKp4wajZWMYm5Q6Ssuk.jpg', '2026-04-03T16:34:21Z', '2026-04-03T16:34:21Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('6a06d7a8-451a-433a-84f9-c301cc24cac3', '84a24124-2290-4b86-aa88-5514da7bd0b6', 2, 'Things to Wear', 'Rogers inevitably fools Marilyn Barnett by donning the Bob Dog costume. Mr. McFeely shows a videotape on how blue jeans are made. Lady Elaine Fairchilde provides the only resistance to King Friday''s insistence that everyone and everything in the Neighborhood of Make-Believe should wear the three-cornered hat from the 18th century.', '1994-03-01', NULL, NULL, '2026-04-03T17:35:47Z', '2026-04-03T17:35:47Z');
