INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('6b33d73e-62a0-41b2-99cf-552939e52596', 'e38e9d87-1432-4a1a-a7d0-64a559bf7570', 1, 'The Wood In Danger', 'With the animals'' homes being destroyed by man, all of the animals of Farthing Wood meet in Badger''s earth to try to find a way to survive. The latecomer Toad, suggests that they all journey to a nature reserve called White Deer Park, where he had passed by on his journey home. The animals eventually all agree to make the journey to this new haven once they take the ancient Wood Oath, of Mutual Protection. This Oath meant that everyone promised not to eat or frighten each other. Fox is assigned as their leader and it is agreed that they will meet by the Great Oak at midnight to begin their long journey.', '1993-01-03', 24, '/lRYIWJC2mNt96HgdRtwpUKYtG0G.jpg', '2026-04-03T17:18:49Z', '2026-04-03T17:18:49Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('6b360ff8-bb26-4285-8cf6-0b96a51d7515', '73ae1459-ba91-4185-a9da-bf6f2844af49', 8, 'If You Can''t Take the Heat, Get Out of the Russian Bath House', 'Stressed out by the tension between the group, Leah arranges a spa day at a Russian bath house. Dorinda and Tinsley call a truce, while Ramona confronts Dorinda about her anger issues. Later on, Ramona hosts a cocktail party, where she and Dorinda’s disagreement reaches a boiling point.', '2020-05-21', 60, '/6wBMGseg38dvTDWb9VDy5x338q9.jpg', '2026-04-03T16:35:25Z', '2026-04-03T16:35:25Z');
