INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('6bc4922e-f0f3-4d94-b342-a859beb9098b', '21384b9c-43fa-410c-b89d-102e7cf9129b', 13, 'Polygamist Flash Mob', 'The Browns throw a party to celebrate Mariah and Aspyn''s graduation from high school, but Meri has a hard time thinking about Mariah leaving for college. Meanwhile, a fortune teller sees a fifth wife in Kody''s future.', '2014-01-12', NULL, NULL, '2026-04-03T16:34:28Z', '2026-04-03T16:34:28Z');
