INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('6bcbcbb4-5d0a-44fc-8afc-99b49b3cff86', '8012f05a-66a3-4254-885f-0a679393f3dd', 8, 'Four Days of the Cockatoo (4)', 'Gaby is taken to the smugglers hide their she encounters two wanted criminals Adoment Poulet and Honey Hawke who have been smuggling endangered birds into the country and skinning them alive. Gaby leaves a message for the team but before she can finish she is captured and put in a giant bird cage. The team learns of Gaby''s whereabouts and meet up with the real agents from the animal rights society. They discover where Gaby is and heads straight for the kidnappers lair. Poulet and Hawke are captured and Gaby gives the bird to the agents so they can help restore its species.', '1994-11-20', NULL, NULL, '2026-04-03T17:40:28Z', '2026-04-03T17:40:28Z');
