INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('6bdbbd9e-36f8-4b4f-9f12-dc82071361cc', '262e8e7c-fa78-4578-a216-add6f184c4d2', 22, 'Kody Climbs Into the Ring', 'Kody heads for the Vegas strip for a guy''s night out on the town, testing his wrestling skills against a mixed martial arts fighter and answering his friends'' questions about his lifestyle. Meanwhile, the wives help setup Robyn''s new nursery.', '2011-11-20', NULL, NULL, '2026-04-03T16:34:27Z', '2026-04-03T16:34:27Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('6be6414a-defd-4647-826c-2061d30342ab', '4fe93658-c463-4329-8e64-9d523869c2cb', 30, 'Chummobile', 'The Pawn Stars have an opportunity to buy one of the most recognizable cars of all time: The Batmobile. Will they use every gadget on their tool-belt for this legendary set of wheels or will they decide crime fighting doesn''t pay? Then, Rick and Chumlee are presented with a mysterious 19th century letter signed by Founding Fathers Thomas Jefferson and James Madison. Can Rick read between the lines and decode the decrepit document or will it fall to pieces in their hands, sealing it''s secrets for all time? And later, a small antique writing desk comes into the shop packing more than just stationary. Will this locked and loaded spy-desk trigger their interest or will the deal end up shooting blanks?', '2011-03-28', 21, '/lls6vJUXaBqUaLSx6sV2VwLiK8h.jpg', '2026-04-03T16:34:16Z', '2026-04-03T16:34:16Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('6bef3c56-cf27-4dd0-88a9-0f21a8a1e31d', '573fa62f-55a9-4f17-97cc-d1a005a83cc8', 24, 'Elmo and Rudy Make a Fort', 'Elmo and Rudy are making a fort at their sleepover but don''t have a pillow big enough for the roof. This is a problem!', '2025-06-26', 26, '/RfHjsrqwvtz0aZMxiBXbMlGn9a.jpg', '2026-04-03T17:36:52Z', '2026-04-03T17:36:52Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('6bf5141f-3a13-45d5-8580-e216a0d80a6e', 'a8c6182e-05e1-4b68-91a5-5126cf6c94f0', 31, 'Bostonians', 'James views the acts of the Iroquois and colonists; Sarah reunites with Abigail Adams.', '2002-11-11', 30, '/lFxZknhQeaK04BRH1YSIXCj9qEc.jpg', '2026-04-03T17:38:28Z', '2026-04-03T17:38:28Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('6bff329a-3fc4-46af-a4fe-4a5c015dbd0a', '3ea743ef-0a22-47cf-b1d2-62f37e939253', 13, 'The Bouncing Box', '', '2002-02-20', NULL, NULL, '2026-04-03T17:36:43Z', '2026-04-03T17:36:43Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('6bff68e4-341f-45fa-a6f6-5fbcd883af04', 'c21dbd22-5e2e-4414-bb67-750399aaf6f0', 17, 'Over the Moon', 'The Pawn Stars prepare for blast off when a piece of heat shield from Apollo 11 rockets into the shop. Will this relic of NASA''s most famous flight have the guys seeing stars or will it turn out to be a waste of space? Then, Rick is presented with a book written by FBI founder J. Edgar Hoover. Allegedly signed by Hoover himself, will Rick''s investigation turn up any positive proof? And later, a man brings in a WWII pilot''s jacket. Flown over the Himalayas on a route known as "The Hump," will the Old Man deliver up a tempting offer or will he eject for crashing down?', '2012-01-23', 21, NULL, '2026-04-03T16:34:17Z', '2026-04-03T16:34:17Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('6c01e71a-b8d2-4960-b136-07dd07d70bf2', '301fb913-4e76-408f-b84b-05bf979766fe', 4, 'The Wink', 'George''s involuntary winking is misinterpreted by many, and prompts Kramer to seek a favor from Yankee Paul O''Neill; Jerry tries to hide his distaste for meat from Elaine''s cousin.', '1995-10-12', 22, '/xG14eZA8qz4mbDZtYzuqYOUzoLq.jpg', '2026-04-03T16:34:11Z', '2026-04-03T16:34:11Z');
