INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('6d003791-a934-41b8-baf3-eb070ad9931e', '4f18ac4c-8757-456c-a49a-224f00e6a9f7', 11, 'Big Bird and Snuffy Talent Show', 'Big Bird and Snuffy welcome the viewer to Sesame Street, and to the Big Bird and Snuffy Talent Show! They realize that they don''t know what a talent show is, so they ask Leela to fill them in. Big Bird and Snuffy agree to have Leela be the first guest on their talent show, but she needs to get to work at the laundromat. Thinking quickly, she decides to juggle an apple and an orange, and Big Bird has her sing the alphabet song while doing so.', '2008-09-26', NULL, '/pzET0igHgwwVp9Ec82JR1907GSy.jpg', '2026-04-03T17:36:45Z', '2026-04-03T17:36:45Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('6d04c779-704d-4bf2-9c14-96a0cdeef6f8', 'a8c6182e-05e1-4b68-91a5-5126cf6c94f0', 3, 'United We Stand', 'Moses lets James report on Congress and after a British sailor is ""tarred and feathered,"" James learns about the ugliness of mob rule, when emotions get in the way of compassion. Sarah and Henri meet Abigail Adams and travel with her to bring supplies and pamphlets to the occupied city of Boston. Sarah immediately finds in Abigail a strong female role model to look up to.', '2002-09-04', 30, '/rvQVeHkkQrDBAqkuY2oezwrGxj2.jpg', '2026-04-03T17:38:28Z', '2026-04-03T17:38:28Z');
