INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('6d2c5740-5a37-4ad2-aa8f-90eba72c222f', '6a2d2839-7106-4c3b-8906-c9b3e4bfcc8b', 20, 'Reunion (2)', 'There are laughs, tears and tirades in part two of the reunion as Shannon explains her holistic ways as only Shannon can do. The ladies argue over whether Lizzie is more drama queen than beauty queen, and the gloves are off when Tamra faces her accusers on whether or not she''s to blame for much of this season''s conflicts.', '2014-09-01', 44, NULL, '2026-04-03T16:35:32Z', '2026-04-03T16:35:32Z');
