INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('6e59c357-ed93-4614-9099-d10b9db3e0ec', '4a8e3db0-8068-4ff3-942f-91f45f665f20', 30, 'Be Bop', 'The jazzy, rhythmic sounds of Be Bop make their way into the library one day, and soon everyone is singing nonsensical Be Bop tunes -- everyone except Barnaby B. Busterfield III, who claims he just doesn''t get this Be Bop thing!', '2000-05-12', 30, NULL, '2026-04-03T17:12:27Z', '2026-04-03T17:12:27Z');
