INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('6e68258a-f3aa-4ea4-862c-45e654aeb58d', 'b2317fc3-1cfc-4f19-b181-effa23959c6d', 2, 'House of Hypocrisy', 'The Gorga/Giudice feud moves to the next generation as Gia goes to battle with her uncle; Jackie learns Jennifer has been digging for dirt on Evan, while Dolores'' housewarming party ends in tears when she takes Margaret''s side over Jennifer''s.', '2022-02-08', 43, '/bmnFnCF2J3kCZxqxFOQsHoKegQl.jpg', '2026-04-03T16:35:18Z', '2026-04-03T16:35:18Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('6e6cec00-9fd0-4065-adb4-43859d6fbf55', '3ee646e8-23ae-4dec-bbc6-c7e6a210d55b', 109, 'Playing football / Meet Merry Monster', 'Elmo excitedly shows Oscar the globe he was just given by his daddy. He wants to travel the world and has Oscar spin the globe and point to a location he can go. Elmo lands on Tonga and Oscar is glad to see him leave, only Elmo returns moments later and leaps onto the globe.

Sponsors: E, U, 7', '1991-04-11', NULL, NULL, '2026-04-03T17:36:38Z', '2026-04-03T17:36:38Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('6e7409da-e2a2-4bad-b7c7-a217bf2b46d3', '2b968a9c-5fc0-4e93-bcf9-31d3e4c7b210', 31, 'Episode 31', 'See Lesley shrink as she becomes Alice - and watch her adventures in Blue Peterland.

Join in with carols round the tree, with the children of The John Scurr Junior School, Warlingham County Secondary School, and The Band of the Chalk Farm Branch of the Salvation Army, and hear the latest news of the Blue Peter Clothes-Horse Race.', '1975-12-22', NULL, NULL, '2026-04-03T17:21:52Z', '2026-04-03T17:21:52Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('6e78d784-7316-4bcf-9660-e3713e60c295', 'f4938e7d-11a8-4756-b405-98bedd7c9b28', 4, 'Pat''s Rainy Day', 'It has been raining very heavily in Greendale. Even the letters are wet when Pat goes to the Post Office to collect them. Later Pat is stopped when a road has to be cleared of a blockage of mud. Bill brings his model plane and Pat ties an SOS message to it and flies it over to Peter, giving him the message to clear the blockage with his tractor and bulldozer plough.', '1981-10-07', 15, '/gJHHnu8A2Fqvrl6Ir7UZB012KfE.jpg', '2026-04-03T17:14:29Z', '2026-04-03T17:14:29Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('6e80044d-c0e1-4309-ab77-7fcfcab3ee2d', '13ecb08f-a000-49f9-8d96-54c16c3ad653', 4, 'Down', 'Walt attempts to reconnect with his family, while Jesse struggles to rebuild his life.', '2009-03-29', 48, '/9xi18yhtCLrrJ2plZjXgfGqeTjU.jpg', '2026-04-03T15:40:33Z', '2026-04-03T15:40:33Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('6e85fd47-1245-4c74-a539-5e43c2dd5923', '9c9d89df-5f6b-41d0-84c6-b8ca7bd2a2e6', 9, 'Hike Pirates', 'Abby, Rudy, and Freddy are going on a hike. Rudy says he’s tired and wants to go home. To make their hike more fun, Freddy shows Abby and Rudy a map they can follow to find the hidden treasure left by hike pirates.', '2022-01-06', NULL, '/uheknXAmLgebMBaZC76tWK61OES.jpg', '2026-04-03T17:36:50Z', '2026-04-03T17:36:50Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('6e891a45-2414-4d62-ad6d-52c2b15b257f', 'a84aa42d-e738-4081-8da9-1faec0209ee9', 6, 'The Front Door', 'Mike insists that only Axl fix the front door after he knocks it down; Frankie must sell a car within a week; and its school picture time for a photographically challenged Sue.', '2009-11-04', 22, '/1ZGqYMv2a88kZ9XaJX9GyFZyxwT.jpg', '2026-04-03T15:40:28Z', '2026-04-03T15:40:28Z');
