INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('6e97379a-3936-43a6-8ac8-2c463c6c5a18', 'a860511c-b630-415e-99a1-a9e0922fbfd7', 1, 'Fifteen', 'Arthur has fifteen minutes to get back home get his report and get back to school before class starts.', '2011-10-10', 26, NULL, '2026-04-03T17:38:00Z', '2026-04-03T17:38:00Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('6ea455f0-b9ec-41b0-9bef-df3002ba9fca', '5a6d9a42-165b-4b56-9273-0a06874dfe10', 12, 'Madeline and the Toy Factory', 'When Madeline and the girls visit a toy factory, Madeline is accidentally boxed as a "doll" and sold to a handicapped girl. The ailing child considers Madeline her only friend and is devastated when Madeline reveals her true identity and has to go home. But things turn around the next day when the little girl discovers she now has twelve real live friends.', '1993-10-17', 30, NULL, '2026-04-03T16:34:01Z', '2026-04-03T16:34:01Z');
