INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('6ea8ae0a-4e6d-4cb4-aba6-476c8de7563b', 'aa3b2cc3-b0cb-4d01-8aa0-694981101aab', 1, 'Still Time', 'Bernard receives a watch from the postman because he is always late for everything including his friend Karen''s birthday party.', '1997-11-14', 15, NULL, '2026-04-03T17:20:04Z', '2026-04-03T17:20:04Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('6eabd0d3-2344-4d18-9e22-84f47eb8852d', 'a84aa42d-e738-4081-8da9-1faec0209ee9', 18, 'The Fun House', 'Frankie fears for her job when a motivational consultant comes to get the sale team into shape. While Frankie is putting in many extra hours, Mike has to deal with the children and their issues, including making the house more fun for Axl and his friends, giving advice to Sue''s ex-boyfriend and helping Brick with a school project.', '2010-03-24', 22, '/oa9VLgv57uPmbHRQwxbQEjn5DNe.jpg', '2026-04-03T15:40:28Z', '2026-04-03T15:40:28Z');
