INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('6eb15d2d-81df-49bf-8664-6e9022dcc0aa', 'eb7e3bb4-5746-4577-81c6-f5b2dc2efc6e', 6, 'The Blind Bandit', 'In search for an earthbending teacher for Aang, the kids go to an underground earthbending tournament called Earth Rumble 6, where they encounter Toph, a blind but powerful earthbending girl. After seeing her unique style of earthbending, Aang wants Toph to become his teacher, but there are complications with Toph''s family.', '2006-05-05', 25, '/ouMgUBM6duJ4cS3jXm2rUomz5X.jpg', '2026-04-03T17:40:48Z', '2026-04-03T17:40:48Z');
