INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('6ebd6471-b257-4449-8aa4-81a9c7cfe796', '10e64538-c78a-4cb0-82f9-17d14256dbac', 17, 'The Wisdom Teeth', 'Frankie''s excited to take care of Sue and Axl after they both have their wisdom teeth removed; and Brick lays down new house rules for his siblings while they''re back home. Meanwhile, Mike learns the diaper business was Rusty''s ex-wife''s idea and becomes furious when he finds out she may be entitled to all their profits.', '2016-03-16', 22, '/3LMIsJDB4mbKuoutFTO0wb7eqQU.jpg', '2026-04-03T15:40:31Z', '2026-04-03T15:40:31Z');
