INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('6ed069e5-4949-475d-982f-e215e4a0b26c', '244b0a34-284b-4ec1-b3a7-0e5abff6d0d1', 8, 'The Good, the Bad, and the Binky', 'As Emily''s new babysitter, Binky introduces his charge to the world of pro-wrestling, and teaches her some fierce moves. But when Emily starts ruffling the feathers of other pre-schoolers on the playground, Binky worries that he has not been the best role model.', '2009-10-15', 13, NULL, '2026-04-03T17:37:59Z', '2026-04-03T17:37:59Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('6ed431db-00bf-4648-aba8-80913bebf77f', '0ebba123-871d-4d2b-a054-eb85d2ad9450', 36, 'Sweetpea Beauty: A Girl After God''s Own Heart', 'A VeggieTales twist on the story of Sleeping Beauty and Snow White. The second story is "Snooderella", a twist of Cinderella. Its theme is true beauty.', '2010-07-31', 30, '/fim42g0EvoJmqsRrs72ZVbBK64b.jpg', '2026-04-03T17:39:39Z', '2026-04-03T17:39:39Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('6ed6b585-5d51-40f6-b7f9-f1ad311ad5fe', '319bd5d6-ff58-426f-b9da-a0bb2cb87b02', 13, 'Fluids', 'Fluids are cool; they ooze and swoosh. Whatever container you put a fluid in, that fluid will take the same shape. Milk poured into a pitcher forms to the shape of the pitcher. If you pour it into a glass, it takes the shape of the glass. You just can’t do that with a boulder. But with the right container, you could pour liquid rock from below the Earth’s crust. Fluids still act like fluids, even halfway to the center of the Earth.', '1998-05-02', 26, '/4duybQ3DaiZhPylOiBwABJquaYG.jpg', '2026-04-03T17:37:22Z', '2026-04-03T17:37:22Z');
