INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('6edd0570-cca7-4920-ac9e-ef1c9e15ad6a', 'dbd3583f-e9b2-46d1-a37e-309eb666e233', 20, 'Happiness and Joy', 'Cynthia hosts a model call at the Bailey Agency hoping to find Atlanta''s next "it" girl. NeNe makes a major decision about her marriage, and later meets with her "business partner" John, who surprises her with another gift. Kim is also in the giving spirit and surprises her new fiance with an extravagant birthday present. Meanwhile, Kandi launches her sex-toy line in a big way, but realizes it''ll take more than masseurs and vibrators to bring "happiness and joy" to the ladies.', '2012-04-08', 43, '/nclA2mwTAjFXP6TP0HsuaTD3LfI.jpg', '2026-04-03T16:34:45Z', '2026-04-03T16:34:45Z');
