INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('6f6521cc-5fa2-460e-85ea-b8e888a8ed5c', '02849455-d14b-476b-9603-eef5fb5d2ab3', 2, 'Meet the Press', 'With their relationship back on track, Robyn and Juan upgrade their lives by moving to a new condo with an interesting address. Trying to keep her man happy, Gizelle takes her new boyfriend Sherman on a romantic picnic, while Monique and Ashley hang out with a fabulous young friend who has a bubbly personality and a crown to go with it. Feeling hurt and betrayed by her friends, Karen decides to hold a "Press Conference" to answer all their questions regarding her financial situation.', '2018-04-08', 42, '/a010JrqHozOcIadFHSYjsDOkNs8.jpg', '2026-04-03T16:35:39Z', '2026-04-03T16:35:39Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('6f6e1d5c-6439-4f05-8336-de93a00f1522', '38bf8c20-c17c-4071-9226-7887787cf1b1', 14, 'Bug Beard', 'In the story ""Bug Beard"", a woodcutter brings home a grubby, buggy old man he finds in the woods. His wife is not amused by the buggy old man, and so she sets about trying to clean him up. When the buggy man is finally all cleaned up, it turns out he just isn''t his happy, dancing, singing old self. Can the Lions help?', '2001-04-19', 30, NULL, '2026-04-03T17:12:28Z', '2026-04-03T17:12:28Z');
