INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('6f8b374e-d0c0-44e9-b28d-ff22faf94d47', 'a61eda16-b572-4c5b-ba55-57df932417ec', 9, 'Wembley''s Flight', 'Wembley, feeling unhappy because he never gets to show off in front of his friends, meets a magical creature that gives him the power to fly. But his friends refuse to believe he has this magical gift and restrain him from flying. Other Fraggles believe him but want to exploit his gift. Wembley finally learns to fly for the right reasons.', '1986-03-03', 24, '/etzAovsv76dfQfxpCrWZQNoNhjC.jpg', '2026-04-03T17:35:01Z', '2026-04-03T17:35:01Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('6f8f2eb4-e3b2-4350-a64a-14032ccb5c2b', '5d57283d-079c-4f66-93c8-33a2feeada89', 14, 'The Award', 'Frankie tries to persuade Mike to attend a dinner honoring his dedicated service at the quarry; Sue forms a plan to build connections between students; Axl hopes to track down a girl who left a message on his phone.', '2014-02-26', 22, '/6DdKbM2XGUq4V2x8cbJoxsfL2EE.jpg', '2026-04-03T15:40:30Z', '2026-04-03T15:40:30Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('6f91a73c-df67-4bac-b51b-9960337b7a68', '0bbd380c-5cb8-46a6-8838-b5d60223c073', 22, 'Ethel Merman', 'Fozzie''s agent, Irving Bizarre, negotiates Fozzie''s contract with Kermit. Kermit ends up offering Fozzie ten times as much money; unfortunately, Fozzie made nothing before. "Yeah, and don''t forget," Irving says, "I get ten percent of that."', '1977-04-09', 26, '/41bAr3bHgedIUWAkZuhkVwE4eXW.jpg', '2026-04-03T17:35:24Z', '2026-04-03T17:35:24Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('6f927920-cc24-4f25-9842-39e76b1579c8', '4fe93658-c463-4329-8e64-9d523869c2cb', 23, 'Pawn Illustrated', 'The Pawn Stars take aim at an incredibly rare 18th century half-size musket. Designed for a child, will the gang hit a miniature bull''s-eye or will a pint-sized problem cause them to shoot themselves in the foot? Then, Rick and the Old Man are presented with a WWII pilot''s jacket flown in the legendary P-38 Lightning. Will the guys dive into a dogfight for this leather bomber or will this deal fall from the sky? And later, a man brings in the first three years of Sports Illustrated magazine. Will Corey and Chumlee go the distance for this iconic collection or will one brutal round cause them to throw in the towel?', '2011-02-07', 21, '/5g6GIsnu7WhO42vQKMLDOXPN3a7.jpg', '2026-04-03T16:34:16Z', '2026-04-03T16:34:16Z');
