INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('6fca458e-e2ec-4a1e-bf1c-76865f2b3581', '06030129-ff2d-4490-b66c-9f41bbe7aabd', 10, 'Clipping', 'As John sails down the canal, he notices lots of different things being cut, so he takes a walk and goes to a farm to see some sheep having their wool sheared off. Later on, John does some trimming of his own by giving his beard a snip. Rosie and Jim join in by taking some sheep wool and begin pretending to shear it off themselves.', '1990-11-05', 15, NULL, '2026-04-03T17:19:36Z', '2026-04-03T17:19:36Z');
