INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('701d011d-10a9-48fd-99b5-55ebc00175b6', '939d270c-ea8e-4cc8-a5a5-e59df2c8062c', 2, 'The G.O.A.T', 'Friends turn into foes during a time of giving thanks; as a blossoming friendship forms between Nina and Caroline Stanbury, Ayan questions Nina''s loyalty; Nina and Lesa bring Thanksgiving to Dubai with their own special flair.', '2022-06-08', 43, '/sADuN14IqR7XECd2J559eBarfX.jpg', '2026-04-03T16:35:07Z', '2026-04-03T16:35:07Z');
