INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('7024b2b1-4a78-4483-a13c-b6f8ddb5a3a6', '90cc8678-a14f-4d05-bc1e-54a3117895d5', 12, 'Blood Is Thicker Than Water', 'Infuriated by Lady Blue''s wounds following her fight with Vixen, Scarface leads an attack on the Farthing Wood animals. Fortunately, Hare manages to warn Fox and gather the animals in time. Ranger meanwhile attempts to aid the Farthing Wood animals but, in doing so unintentionally leads Scarface to their whereabouts. The attack culminates in a huge battle between Fox and Scarface which is ended when the Warden turns up, but not before Scarface is severely injured. Elsewhere, Adder decides its time to exact her plan of vengeance upon Scarface.', '1994-03-25', 25, '/9lBG671yhzOuTLmZCd1edlVpSjN.jpg', '2026-04-03T17:18:49Z', '2026-04-03T17:18:49Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('7024c302-7254-4219-918a-8e32c1dd09e4', 'a7421c26-c9a2-437a-be12-2cabed2b5a96', 11, 'Shannon / Grandma / Birds!', '', '2001-11-14', NULL, NULL, '2026-04-03T17:11:22Z', '2026-04-03T17:11:22Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('702b0d64-8851-40bd-a14e-fa7b9b394772', '52a47058-98e0-4ccb-aba0-b1481fbc2a96', 7, 'Watch What Happens Live: Miami Housewives Reunion', 'The ladies of Miami get together to set the record straight, solving some of the biggest controversies of the season.', '2011-04-05', 44, '/54vaj3K5h4WO1eZGyJpFUeSm5Zj.jpg', '2026-04-03T16:35:10Z', '2026-04-03T16:35:10Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('702c2cd5-7e31-4f11-b458-46153a88beef', '5a6d9a42-165b-4b56-9273-0a06874dfe10', 6, 'Madeline in London', '"Not a single eye was dry" the day the Spanish Ambassador moved to London, taking Madeline''s dear friend Pepito with him.', '1991-11-28', 23, NULL, '2026-04-03T16:34:01Z', '2026-04-03T16:34:01Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('702c4fe4-8b3e-4b5f-8693-3c2f4dcbee28', '79916e0e-881c-43a7-b4ee-00e5052a94be', 21, 'Theodore Hugs the Coast', 'The Dispatcher sends Theodore out on a job where it is vital that he hugs the coast. Unfortunately he becomes distracted and disobeys orders.', NULL, NULL, NULL, '2026-04-03T17:10:11Z', '2026-04-03T17:10:11Z');
