INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('70735fe1-2fb8-4d80-9d85-3b6aca978fee', 'e93f04c2-7344-4b93-abba-8ba1b2f8eb35', 33, 'Episode 568', '', '1974-01-02', NULL, NULL, '2026-04-03T17:36:30Z', '2026-04-03T17:36:30Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('70753b57-90b1-48ae-9e69-0cf6765ceb10', '1d713ca6-4e17-4f84-949c-8cfd98514127', 1, 'Press One for Chum', 'Play hardball with the Pawn Stars when an autograph of baseball legend Honus Wagner lands in the shop. Will Corey and Chum hit a home run or will this signature be going, going, gone? Then, Rick crushes on a rare, first edition of Nabokov''s controversial novel, "Lolita." Will he be seduced and give in to his love of literature or will it end up being a closed book? And later, Chumlee helps set up the shop''s new phone system. Will he get called out for doing a good job or will Rick hold the phone on his not-so-traditional ideas?', '2014-07-10', 21, '/VFx7ZDziwr98PdVZf3yAx7yN8U.jpg', '2026-04-03T16:34:19Z', '2026-04-03T16:34:19Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('7078dec3-c88a-4717-ad1d-a1912cadb98d', '7ccd5605-fe0b-4e00-ae7f-3e3daa252f8b', 5, 'Friends, Facelifts and Florida', 'Vicki Gunvalson is focused on repairing her marriage to Donn and schemes a big surprise to celebrate their upcoming 15th wedding anniversary. Alexis Bellino is raising her twin, 20-month old girls to know the importance of keeping up their good looks" and decides they are old enough to have their first mani/pedi at a nail salon. It’s plastic surgery day for the Curtins when Lynne undergoes a face-lift, while her oldest daughter Raquel has a bump removed from her nose. Meanwhile, Tamra Barney jumps back into the real estate game by showing her first house in several years. Also, Vicki travels to Florida for an insurance convention and invites all the Housewives to join her for a ladies-only getaway. But, Alexis tells Gretchen that if she goes on Vickis Florida girl trip, Jim will definitely be accompanying her. Gretchen begins to wonder about everyone''s confining relationships.', '2009-12-10', 44, '/ndRFXtQL2urPYdoVCTgrSxZiMGg.jpg', '2026-04-03T16:35:31Z', '2026-04-03T16:35:31Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('70798d7d-bb76-45db-a1a4-9ecf81b69791', '42e591e2-2a88-4434-ae9f-3d4b1d685613', 22, 'Goldfish and Silver', 'Go off-road with the Pawn Stars as the guys check out a Honda Pilot ATV. Will they see a chance to make a profit, or will negotiations get stuck in the mud? Then, Rick and Chumlee give a seller shelter when he brings in a signed photo of the Rolling Stones. A rare early image including the late Brian Jones, could wild horses tear Rick away from this piece? And later, when Chumlee brings his pet goldfish into the shop, the Old Man is determined to get rid of it.', '2013-08-22', 21, NULL, '2026-04-03T16:34:18Z', '2026-04-03T16:34:18Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('707d9316-6983-407c-9ab9-cca68af18f76', '5dade172-c4f3-4488-a399-b73f3aca0db5', 3, 'Chapter Three: The Pollywog', 'Dustin adopts a strange new pet, and Eleven grows increasingly impatient. A well-meaning Bob urges Will to stand up to his fears.', '2017-10-27', 51, '/792NQjFydcr5ucb1sga55LS6Vt3.jpg', '2026-04-03T15:40:39Z', '2026-04-03T15:40:39Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('7080d0c4-278c-44ac-aac0-b167969e04bb', '937ee587-e2eb-46aa-9a69-3d6bab04398f', 7, 'Rumplestiltskin', 'This looks like an extension of the previous episode, but it is a separate venture. LeVar appears in proper attire for an English Renaissance festival. Ralph Waite reads the fairy tale of Rumpelstiltskin, about a poor miller''s daughter who is stuck between a greedy king and a conniving elf to get out of a difficult situation.', '1987-06-30', 30, NULL, '2026-04-03T17:36:16Z', '2026-04-03T17:36:16Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('70852531-f711-460b-9017-f9c1ad81fae5', '5db3ff78-e439-48e1-8f67-988ecbf85d17', 10, 'The Great Getaway', 'Juliette''s Uncle is kidnapped by the people who kidnapped Juliette, who''s still being held in the house by Rochefort''s squire. Dogtanian plans to find them both and enlists The Three Musketeers to find Juliette''s Uncle while he goes to find Juliette. Juliette manages to escape outsmarting the squire who follows her with Rochefort. After Juliette falls in the river Rochefort lets her think she''s escaped so she will lead him to the Duke of Buckingham...', '1981-12-11', 24, '/wBqp8MzIbGzLBFI63ZO0tTvH37D.jpg', '2026-04-03T17:18:43Z', '2026-04-03T17:18:43Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('708d4d72-6203-491d-a807-318cd4e4fa55', 'f6015d9a-ece4-414a-a00b-06cf689fe40b', 14, 'Greg James and a Diamond Delivery', 'Get set for Easter with Blue Peter. We''ll show you how to reuse your Easter egg boxes to build a cool automaton. Radio 1''s Greg James and Chris Smith pop in to talk superheroes, and Lindsey delivers the very first diamond badges.', '2018-03-29', NULL, NULL, '2026-04-03T17:22:10Z', '2026-04-03T17:22:10Z');
