INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('7093db33-0026-4fc2-821f-3cae2ce044c0', 'ea73e13c-6962-4804-8305-c303df65f89f', 4, 'Moving day', 'The Frogg family moves to their new home in Westwood. Tadpole Frogg expresses his feelings about the move. Lady Elaine Fairchilde, the Museum-Go-Round''s new curator, is also pleased with the move.', '1969-02-13', NULL, NULL, '2026-04-03T17:35:38Z', '2026-04-03T17:35:38Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('709750bd-57f8-4ec9-9328-e19171b0dfd3', 'c7994637-b7c7-42c7-aaee-1bff4144fe23', 6, 'Ring Around the Rumor', 'Kyle seeks insight into Sutton''s confusing behavior. Dorit pours out a strong opinion of her own. Erika presses forward with reviving her public image. Garcelle is stunned when her son makes an admission about her divorce. After leaving her mark on country singer Morgan Wade, Kyle is confronted by Sutton about the state of her marriage.', '2023-11-29', NULL, '/ayIzccdrxj7vp8VJirSDYbQS21N.jpg', '2026-04-03T16:34:59Z', '2026-04-03T16:34:59Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('70988f4b-692f-46db-8da1-bd55102d7b5c', 'd5351b60-8a0c-482a-a6dd-4fb860cfe143', 20, 'Episode 1410', 'Mister Rogers arrives with a large box and does not change into his usual sweater. Instead, he changes into his sneakers and takes a red jacket from the box. Mister Rogers and Mr. McFeely have been asked to take tickets and hand out programs at the Brown''s marionette play of Little Red Riding Hood.

The marionette play gets underway as the audience enjoys a fun performance of Little Red Riding Hood.', '1975-03-14', NULL, NULL, '2026-04-03T17:35:41Z', '2026-04-03T17:35:41Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('70990898-357c-4ec1-987e-aaa30490a821', '7bc54df3-f32a-454e-aef6-a9436c35d53b', 30, 'Episode 30', 'Rogers makes a window out of construction paper. Later he picks up a record album at Negri''s Music Shop. In between, Chef Brockett goes to the Neighborhood of Make-Believe with a cake for Grand-père and Lady Elaine. Handyman Negri helps Lady Elaine fix the King Friday''s broken window.', '1970-03-13', NULL, NULL, '2026-04-03T17:35:39Z', '2026-04-03T17:35:39Z');
