INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('70aec90d-a35f-454a-a62b-030310d811d3', '3ade5e1f-8441-4c2c-acf6-fb933a61dcfa', 15, 'Cayman We Get Along?', 'The ladies head to the Cayman Islands, but things get off to a bumpy start when Karen and Gizelle engage in a showdown in the hotel lobby. Meanwhile, Ashley confronts Katie about the gossip she''s been spreading about her husband.', '2019-08-18', 42, '/o37MI9nFx8VyFzaMQz58butzwIL.jpg', '2026-04-03T16:35:39Z', '2026-04-03T16:35:39Z');
