INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('70b8beef-e60c-45ea-9169-56137f5b7198', 'd589b670-2e75-4922-9f56-029b48e54927', 16, 'Look Back: How It Started', 'All but one of Kody Brown''s polygamist marriages have completely fallen apart. Now it''s time to look back at how the Browns got to this point as they reflect on those early days after each of the four wives entered the family.', '2023-12-24', NULL, NULL, '2026-04-03T16:34:27Z', '2026-04-03T16:34:27Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('70bb8f12-58b6-4c56-9ca3-df15c6f170ef', '8bdf0ad3-a798-4d5a-b304-c7501eae6867', 6, 'Cut!', 'Gretchen asks Jeff''s children to come out from Michigan and rotate visits to their father''s bedside. Gretchen takes advantage of the kids'' visit to spend a day in Hollywood and engage in the success of her friend Jo De la Rosa.

Vicki accompanies Briana to the Red Cross to donate blood even though she is terrified of needles.

Feeling the financial pinch of being a college student, Kara gets a summer job at a local boutique...and redefines "manual labor."

Lynne frantically anticipates "the perfect" 18th birthday for her demanding daughter, Raquel. Things get off to a rocky start when a jealous squabble over their outfits threatens to dash Lynne''s hopes for the perfect party.

Lynne meets the other housewives for the first time at Orange County''s hip new restaurant. Within minutes of arriving, Lynne makes a misstep that leads to some very awkward exchanges. Before the night is over, Tamra and Gretchen square off over Gretchen''s treatment of her ailing fiancé. This incident completely derails their budding friendship.', '2008-12-30', 44, '/8ZdTeypoVAcYPwmhKzi1S1SoQal.jpg', '2026-04-03T16:35:30Z', '2026-04-03T16:35:30Z');
