INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('71124449-2b1a-4c64-9918-f7de6d7f1f43', '78a02d50-e3dc-4549-844a-3cf357a32ef4', 7, 'Model Behavior', 'Phaedra calls Kandi to clear the air, but the conversation takes a turn as Kandi divulges long-held secrets. Shereé acts as momager to son Kairo, as he explores a modeling career. Porsha finally introduces her boyfriend Todd to the family and he reveals something Porsha wasn''t expecting, putting their new relationship to the test. Cynthia anxiously awaits news of whether her offer on her dream home was accepted. In the aftermath of Kenya''s argument with Matt, she calls upon her dad for fatherly advice -- but nothing can prepare her for her next encounter with Matt.', '2016-12-18', 43, '/9q4J74vZwzSNOrQ8jEGwOmzpmAA.jpg', '2026-04-03T16:34:47Z', '2026-04-03T16:34:47Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('7114a088-cae0-4b42-9da4-885563585708', 'b598da2e-89fd-4e98-8d0d-4bce6bbd4ac9', 17, 'Spike Milligan', 'Sketches/Songs: ""Oklahoma"", ""An Editorial by Sam The Eagle"", ""The Music of Scotland"", ""Muppet Newsflash"", ""Dog Walk"", ""America"", ""The Intergalactic Brotherhood of Man, Including Things"", ""It''s a Small World""', '1979-03-02', 26, '/dW880bl9FpIivtQyCoYmK4oF7A5.jpg', '2026-04-03T17:35:25Z', '2026-04-03T17:35:25Z');
