INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('71225626-00fb-49be-a53c-0c94f233827e', 'bb919aec-0d5c-4c58-9a5a-fa2a0a5de2b6', 110, 'Episode 515', '', '1973-04-27', NULL, NULL, '2026-04-03T17:36:30Z', '2026-04-03T17:36:30Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('7123cc1e-59f5-4440-bad8-716e436c3371', '97a3d1f5-a8f1-47cd-8122-2e74a092836d', 13, 'Lost in Brooklyn (1)', 'An African exchange student arrives in Hurston and Tina befriends her. Safria explains to Tina that years ago her brother wanted to become an artist. Her father disapproved, they had a fight and Malenga accidentally hit him. Ever since that day Safria''s father hasn''t forgiven him and won''t allow his name to be mentioned. Safria tells Tina that Malenga has been writing  anonymous letters to her. She and Tina decide to go on a city search for Malenga.', '1993-11-28', NULL, NULL, '2026-04-03T17:40:28Z', '2026-04-03T17:40:28Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('712c1423-9c3e-4d4f-8009-360b8dafa0eb', '4da606e7-9d23-4682-8bd5-f535e1da706f', 15, 'Franklin''s Birthday Party', 'Franklin''s parents couldn''t afford to take Franklin and all his friends to Tamarack Point so they built their own little amusement park for Franklin''s birthday party.', '1998-10-26', 12, NULL, '2026-04-03T17:40:15Z', '2026-04-03T17:40:15Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('712c9089-3497-4591-8cd4-f84de64dd2ae', '1c9ea7d3-e254-4e7b-8a9f-33eea9c6c341', 25, 'Reunion (2)', 'Kenya and Porsha discuss where their friendship went wrong, which leads to a spicy exchange between Kenya and Nene. The ladies open up about their past relationship struggles and Eva breaks down while talking about her journey with her daughter. Porsha and Eva have a heated exchange when Porsha calls Eva out for being a shady friend. Nene goes missing, leaving Andy and the ladies to wonder if she’ll return to defend herself.', '2020-05-17', 43, NULL, '2026-04-03T16:34:49Z', '2026-04-03T16:34:49Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('712fe4a3-9351-404d-bc7d-5c48bd5d6405', 'a1b69730-d225-48f2-a7e7-1d314cf3b349', 69, 'Episode 69', 'with Valerie Singleton, John Noakes, Peter Purves', '1969-05-22', NULL, NULL, '2026-04-03T17:21:49Z', '2026-04-03T17:21:49Z');
