INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('7134c89e-9a3b-486a-8431-19674be6fa5e', '421c3366-4d98-4baf-b4ad-6ec5047df9f8', 19, 'Binky''s Music Madness', 'Everyone loves the Bang on a Can All-Stars, a funky experimental music group that''s touring around Elwood City. Everyone that is, except Binky. A musical purist, Binky thinks their nontraditional sound is just a bunch of noise and sets out to prove it.', '2014-05-14', 13, NULL, '2026-04-03T17:38:01Z', '2026-04-03T17:38:01Z');
