INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('714bd08d-c01a-443b-8289-1cc6af08eaa0', '90cc8678-a14f-4d05-bc1e-54a3117895d5', 11, 'A Time Of Reckoning', 'Now sharing a den, Bold and Whisper continue to grow closer. With the help of Whisper, Crow - and a St. Bernards dog Rollo whom he befriends, Bold is now finding the struggle for survival less and less of a challenge. But his pride has taken a blow - he can''t stand having to rely on others all the time, and when Whisper reveals that she is with cub, and wants him to guide her back to White Deer Park, Bold''s self-confidence takes another blow: she only chose him for a mate due to his lineage. Whisper denies this, but the journey takes its toll on Bold and he grows steadily weaker. Meanwhile, back in White Deer Park, the feud comes to a head when Vixen and Lady Blue become involved in a vicious fight.', '1994-03-18', 25, '/aTn1VL0cvYhc2mxBJpsV5mVcWfj.jpg', '2026-04-03T17:18:49Z', '2026-04-03T17:18:49Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('715a196f-cfb0-456b-af63-6b1ee877811e', 'efdf1e4f-8476-4382-a9d7-2b9da4188be0', 2, 'Mad Feelings', 'Maggie Stewart brings a water-and-oil motion sculpture to the television house. Jay Styperk, a wheelchair basketball specialist, gives Rogers a few exercises. The Neighborhood of Make-Believe is startled to see Lady Elaine has turned the Eiffel Tower upside down.', '1996-08-16', NULL, NULL, '2026-04-03T17:35:47Z', '2026-04-03T17:35:47Z');
