INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('715fdf92-221c-4057-b5d0-e1b9532fb821', '1f34e241-4c1d-4586-921a-1c5aeb1fbbaa', 110, 'Wynton Marsalis visits', 'At nighttime, Hoots the Owl meets up with fellow jazz musician Wynton Marsalis. Wynton says that "N" begins the word "note," and Hoots names the different kind of musical notes there are as demonstrated by Wynton and his trumpets.

Sponsors: N, Y, 4', '1986-04-18', NULL, NULL, '2026-04-03T17:36:36Z', '2026-04-03T17:36:36Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('7160f184-b64e-485c-bf04-a5cd1bb0d0c8', '7c0e1f66-8835-4e8a-8ad9-0eee57155b4c', 8, 'Creating the Legend: Waterbending', 'In the Avatar''s World, the powers of the four nations are based on four different forms of Chinese Martial Arts. Sifu Kisu discusses Waterbending.', '2010-08-20', 1, NULL, '2026-04-03T17:40:47Z', '2026-04-03T17:40:47Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('716734b8-bd53-430d-9008-d4c611ab778f', '42e591e2-2a88-4434-ae9f-3d4b1d685613', 4, 'Unprankable', 'The Pawn Stars prepare for a duel when a check signed by Aaron Burr comes in the shop. Will Rick try to turn this check into cash, or will a tough negotiation make the seller bounce? Then, Rick and Corey check out a 1960 Chevy Corvair. Will the guys have the guts to take this car, once considered "Unsafe at Any Speed," out for a spin? And later, Corey is determined to pay Chumlee back for a prank gone awry. Can he pull one over on the self-proclaimed "Prank Master?"', '2013-06-06', 21, NULL, '2026-04-03T16:34:18Z', '2026-04-03T16:34:18Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('716b14fe-23fd-4dab-8948-c131100385b5', 'e291df42-d44f-49e5-bf81-2df32ee4a30f', 26, 'A Berry Bear Christmas (2)', 'Continuing from part one of the Berry Bear Christmas special, the entire gang (now with Jack) goes out caroling.  As the kids settle down to try to figure out what to do about a Christmas present for Bear, Bear turns his attention to the finding of the winter berry. Jack overhears the kids'' conversation and suggests making something.  In the Shadow segment, Shadow sings a song about a Hanukah dreidel. She then wants to give Bear a present, but says there isn''t much a shadow can give a bear. So she has him kneel down and she gives him a kiss.  Everyone enjoys their presents, but they worry that they''ve left out Jack. Jack helps them to see that they''ve already given him a gift -- a peaceful, happy holiday in a warm house with good friends. Later, the search for the winter berry proves fruitful for all.', '1999-12-06', 25, NULL, '2026-04-03T17:35:32Z', '2026-04-03T17:35:32Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('7175cc5c-4438-42aa-a380-4720a013f681', 'bb919aec-0d5c-4c58-9a5a-fa2a0a5de2b6', 117, 'Episode 522', '', '1973-05-08', NULL, NULL, '2026-04-03T17:36:30Z', '2026-04-03T17:36:30Z');
