INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('717bd209-0af1-41a1-a6d9-4dbf9255db74', 'a84aa42d-e738-4081-8da9-1faec0209ee9', 14, 'The Yelling', 'Frankie makes a deal with her kids, that if they do their homework and keep chores she won''t nag them. Meanwhile, Mike takes a job as a night driver with Bob.', '2010-02-03', 22, '/zjWQg4q3jiUhieGhIL5xQ9dzVyx.jpg', '2026-04-03T15:40:28Z', '2026-04-03T15:40:28Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('71802f86-41a7-4565-8874-8f6bb89a06b9', '931b0f0a-097a-42be-a05d-d759fc5dfcae', 4, 'Number Cruncher', 'Scooter Computer And Mr Chips - Mr. Chips helps Scooter with his baseball game by crunching his numeric stats.', '1985-01-01', 3, '/b9ZauitZ3PDpUBOMXXnYkLctFy6.jpg', '2026-04-03T17:13:56Z', '2026-04-03T17:13:56Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('71829a66-a905-4f1d-a116-4cccd8e46ea5', '8c3cfac1-d882-4904-b38c-d1981628d00e', 31, 'Episode 31', 'Review of the Year  Re-live Blue Peter''s highlights of 1978 as Simon rides the Tower Bridge Death Slide, Christopher takes to the skies-on water-skis, and Lesley has a cuddle with Frankenstein''s monster! Join ANNI-FRID, BJORN, AGNETHA and BENNY in the Blue Peter studio, float in space with Skylab Astronaut Owen Garriot and flex your lips with the Fuoptimists as they give their unique ''trim-phone'' seminar.', '1978-12-28', NULL, NULL, '2026-04-03T17:21:54Z', '2026-04-03T17:21:54Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('718dc729-0bf7-437a-ab06-6c85ae3527d6', '3fc7c152-e4f6-426a-a899-36ec454c4403', 9, 'Pigment of Your Imagination', 'The group runs out of paint as they are finishing their I-Love-My-Mommy Day gifts. They set off for Rainbow Canyon to find more colors. However, when their map breaks, they must work as a team to put the pieces back together.', '1999-09-10', 30, '/r866iZYOLPcK3IGZRwhjfiovvHK.jpg', '2026-04-03T15:26:03Z', '2026-04-03T15:26:03Z');
