INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('719f1eff-9ba5-4941-ac9a-f7ea2eb53b37', 'ec8d3322-8ca2-4e8d-9d22-268aee320274', 10, 'The Champ Pays a Call', 'Chum gets a taste of a Julia Child cookbook, but will he find a recipe for success, or will he end up with egg on his face? Then, Rick kickflips for a vintage skateboard collection. Will he land his ollie, or is it all just a trick? Later, Corey tries to score a Steph Curry jersey. Will he hit a three pointer, or will he shoot a brick? And finally, Rick comes out swinging for a punching bag signed by an Academy Award-winning actor, who may even show up for a knock-out appearance.', '2025-04-02', 42, '/rLFyiplajAAdFE81WvyUeg4fRvd.jpg', '2026-04-03T16:34:24Z', '2026-04-03T16:34:24Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('719ff172-ac82-4eab-8495-8a68818d156e', 'a6ed03e0-c05f-48f8-9f56-3f1da50e1792', 40, 'Episode 1355', '', '1980-01-18', NULL, NULL, '2026-04-03T17:36:33Z', '2026-04-03T17:36:33Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('71a2757b-305e-4c94-b121-a3c1d52324d5', '34674c90-410e-427c-be4d-2a6f6f865a80', 6, 'Trigger Happy', 'The Pawn Stars get fired up when a rare three-trigger Stevens shotgun barrels into the shop. Will the third trigger be the charm, or is this gun a three-time loser? Then, Corey and Rick are presented with a movie camera used by the U.S. military during WWII. Built to operate on the battlefield, can it draw Rick''s focus or will he shoot it down? And later, an Abraham Lincoln campaign token comes in on the Night Shift. Handed out during Lincoln''s 1864 re-election campaign, will Olivia elect to bring in a second opinion or will run solo on this deal?', '2012-04-23', 21, NULL, '2026-04-03T16:34:17Z', '2026-04-03T16:34:17Z');
