INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('71ba37d7-e0b6-4647-b449-15bd89aeb905', '42684fca-0bc7-4f4c-bf7d-f41fd288a764', 26, 'Postman Pat''s Perfect Painting', 'Pat delivers a new supply of arts materials to the school. There, the children are making pictures of their favourite adventure from the past year. Everyone except Sara Gilbertson, who cannot think of anything.', '2004-10-14', 15, NULL, '2026-04-03T17:14:30Z', '2026-04-03T17:14:30Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('71bf82da-99b1-422b-9df1-58c8791d7c89', '6f731e6b-d3c5-4de6-84e1-7a19cb650e86', 37, 'Pawntucky Derby', 'Ante up with the Pawn Stars when they head out to see a 1980s Sigma Derby horse-racing game. Will Rick jockey for a deal or will he be left running in circles? Next, a 1940''s Moby Dick Classic Comic sails into the shop. Will Chum cast an offer or will he go down with the ship? Then, a dollar signed by Walt Disney and Ronald Reagan gets its closeup. Will Corey cash in or go broke? And later, a 1910 envelope sealer presses through the doors. Will Rick seal the deal or get stamped out?', '2016-06-08', 21, '/8eJfo7Nif4IREny2dLoxun5Giw2.jpg', '2026-04-03T16:34:20Z', '2026-04-03T16:34:20Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('71bfa8f4-e3b8-428b-8e69-c032caa8bc48', '0fb5ce65-0258-4423-be8a-f7ba9c37bb6b', 2, 'Boar Breakout', 'When one of Farmer Annie''s boars escapes, she tries to rescue it, and now they''re both drifting away into the river!', '2023-10-22', 9, '/qWGkzLSLehwVBvl22mFfP9KqXc6.jpg', '2026-04-03T17:14:42Z', '2026-04-03T17:14:42Z');
