INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('71e8712b-6a42-44ba-8420-91f207334906', '4a8e3db0-8068-4ff3-942f-91f45f665f20', 21, 'Sausage Nose', 'The Lions watch a video of a foreign film called ""Sausage Nose"", in which a poor couple receives three wishes from a wise old woman. Somehow, a sausage gets wished onto the wife''s nose, and from there, the characters from the film come to the library looking for advice on what to spend their last wish on.', '2000-05-01', 30, NULL, '2026-04-03T17:12:27Z', '2026-04-03T17:12:27Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('71f4621f-1287-4a07-9d0f-5728daf971e8', '225b0f03-984b-47f3-a1a3-d3e92175e39d', 18, 'Episode 18', 'with Christopher Trace, Valerie Singleton and John Noakes.', '1966-11-24', NULL, NULL, '2026-04-03T17:21:48Z', '2026-04-03T17:21:48Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('71f4b7b7-4afc-437f-8a74-8b336f242a1f', '2dcbd122-86d8-46e8-bbe5-9143875abd34', 1, 'D.W.''s Library Card', 'D.W. discovers that she can get her own library card and feel the power as Arthur has, but she can not write her own name. When she does and waits a week for a book to come in, she borrows it but never reads it because she thought she might destroy it.', '1999-10-04', 13, NULL, '2026-04-03T17:37:56Z', '2026-04-03T17:37:56Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('71f65d31-4542-413b-9a64-e282e1476ff7', 'e40e6b63-9f84-449f-8e88-53209b0906c8', 20, 'The Amazing Alphabet Race', 'Australian TV personality Amazing Al spots Elmo singing his ABCs, and chooses him to be a contestant on "The Amazing Alphabet Race." The objective of the game is to find all the letters of the alphabet before a clucking chicken tap dances her way to a gong!', '2007-09-28', NULL, '/6IWfnpPJe8xWM2METQuefWSeUHZ.jpg', '2026-04-03T17:36:45Z', '2026-04-03T17:36:45Z');
