INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('71fe3d0d-6690-491f-8885-22e1331cc2c2', '34bdccfa-3c14-4e1c-9148-85c29aadc0e1', 26, 'Arribala 1: The Sea Turtle Invasion', 'The Kratts are on the coast of Costa Rica, waiting for thousands of sea turtles to swim ashore and lay eggs on the beach. But distractions await the Kratts at virtually every stage.', '1996-07-08', 30, NULL, '2026-04-03T17:11:47Z', '2026-04-03T17:11:47Z');
