INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('72009100-9231-4e9f-b430-9d333bf541a7', '33440d76-e69f-47ad-ac25-862ccbc9dfa1', 9, 'Hard Conversations', 'Mia invites the Dixons to a cooking experience and can''t help but stir the pot. Gizelle takes Grace to a self-defense class as she prepares to send her off to college. The ladies come together to support Karen''s PAVE event and rally behind an important cause.', '2024-01-14', 43, '/gIIho6MeAku395cortGi6N2u5aF.jpg', '2026-04-03T16:35:41Z', '2026-04-03T16:35:41Z');
