INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('72131e0f-fe5c-4749-8286-347da92f9e7e', '7eef937c-4483-42bd-bafe-263a7d4e4573', 5, 'Gets a Bright Idea', 'The light show at Walkerville’s old theater is illuminating, but Arnold’s bossy cousin Janet claims she could put on a much better show—if there wasn’t a ghost living in the theater!', '1996-10-12', 25, '/34UE46yGMWoCTEHXdLsw7iTdJjm.jpg', '2026-04-03T17:37:49Z', '2026-04-03T17:37:49Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('7215518b-04b7-4c95-8071-dac3680b951a', '1c9ea7d3-e254-4e7b-8a9f-33eea9c6c341', 18, 'A Greek Tragedy in 6 Acts', 'After a misunderstanding with Nene, Kenya is ready to put the drama behind her but finds herself in hot water with Cynthia when she asks some inappropriate questions. An intense conversation rehashing old wounds brings Porsha and Nene to tears. When Nene confronts Kenya over her behavior, tempers erupt leaving the vacation almost in ruins.', '2020-03-15', 43, NULL, '2026-04-03T16:34:49Z', '2026-04-03T16:34:49Z');
