INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('72260bc3-a841-4630-9df3-d4219a3af30f', '852a07b0-f228-4197-9147-7aeed79390bf', 7, 'Electile Dysfunction', 'After the ladies compete in Luann''s 70''s inspired Halloween pageant, Leah receives devastating news about her grandma. Back in the city, Ramona reviews her real estate skills, while Leah and Eboni help Sonja learn to land a punch. Eboni hosts an election party.', '2021-06-15', 60, '/5VwZOOCVw186M1IaLlozqgTjd7N.jpg', '2026-04-03T16:35:26Z', '2026-04-03T16:35:26Z');
