INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('722f3755-1a0d-4bac-979e-a7c9b6aebe1f', '56428e5e-7daa-468d-8bd2-076956507aa8', 14, 'Brain', 'Bill Nye looks at how the brain controls the body and stores information', '1994-10-29', 26, '/A6YD8B96MPoAZK2geT7IW4nOi2m.jpg', '2026-04-03T17:37:21Z', '2026-04-03T17:37:21Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('72382059-54d0-4ac2-ba19-fd18706f46e8', 'f29f456f-8e38-49af-8808-7943977100ec', 12, 'Mutiny on the Pitch', 'Francine decides to leave her soccer position to Buster when the Lakewood Elementary soccer team claims she is too bossy.', '2017-05-31', 13, NULL, '2026-04-03T17:38:02Z', '2026-04-03T17:38:02Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('723ad7cd-9447-436e-816c-459e03358dcd', '4fe93658-c463-4329-8e64-9d523869c2cb', 25, 'Harrison for President', 'The Pawn Stars are presented with a piece of fabric believed to be from William Henry Harrison''s presidential campaign. Will the Harrison name get the vote, or will a loose thread unravel the deal? Then, Corey and Chumlee meet a man hoping to sell his fully functional antique arcade claw machine. Can they clasp the deal, or will it slip through their fingers? And later, Chumlee and the Old Man have an opportunity to buy a box of unopened, pre-embargo Cuban cigars. Will they fire up some cash for these 60-year-old stogies or will this deal go up in smoke?', '2011-02-14', 21, '/vix2VXlKlT7goTqtwEhuvvpLbU8.jpg', '2026-04-03T16:34:16Z', '2026-04-03T16:34:16Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('723f2e1f-6046-4a41-aa65-1fe0b6e350a9', 'b1d55597-d9d2-4eee-ab95-46dbb163291a', 19, 'Pingu At School', 'Pingu walks to school with his backpack, and on the way, calls for Robby. Robby slides down a slant on a snowy mountain. Pingu does the same sliding on his backpack, rather further than Robbie. Pingu slides his backpack to Robby. Robbie dons the backpack, Pingu is amused. Pingu and Robby find two rows of desks, a blackboard and an igloo. The teacher walks out of the igloo. As the teacher turns around to close the door, Robby quickly jumps into a water hole. The teacher rings the school bell. Pingo and Pingg arrive at the school. Before a lesson, Pingu tells Robbie to hide down the water hole. The teacher, Pingo, and Pingu walk over to the water hole. Pingo jumps into the water hole, much to Pingu''s surprise. Pingo jumps back out. Pingo goes to the blackboard and draws a fish. Pingg jumps into the water hole. Pingg jumps back out. Pingg is sent to blackboard and draws a fish skeleton along with a tail fin and head. Pingu laughs in amusement. Pingg points to the blackboard telling him why it isn''t funny. Pingu acts out Robby''s actions (first trying by mimicking the noise Robby makes, then, when this fails, moves like Robby). Pingg, Pingo and the teacher do not know who he is. Pingu goes to the blackboard and draws his friend Robby. Pingu takes a fish out of his desk and holds it over the water hole to attract Robby. Robbie jumps from the water hole and eats the fish''s body leaving the skeleton, head and tail fin. The teacher, Pingo and Pingg are astonished. Pingu calls for Robby. He leaps from the water hole and Pingu introduces him. The teacher is much satisfied. Robby brings a fish out of the water while the teacher erases the chalk drawings. They pass the fish down to the teacher and plaster it onto the blackboard. Robby gets an eel and repeats the process with a flounder and a lobster. Pingg and Pingo are asked what the creatures are. Pingu tries to raise his hand in order to answer. Pingu is finally brought up to answer the question of what the lobster is. Robby writes what it is. Pingu answers the question. The teacher pats Pingu''s head happily. All this leaves a happy Pingu, teacher and cheering Robby.', '1990-04-28', 5, '/4NBzjFVcmQtfnBkqXwIK2jsFAXQ.jpg', '2026-04-03T17:22:19Z', '2026-04-03T17:22:19Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('7240a857-4a36-43c0-a4bb-72a84425c063', '99a96781-44cb-4a5c-9100-71e2a55b6b1a', 3, 'Girls Gone Wild', 'For her graduation present, George’s daughter McKenzie hits the sun and fun of South Beach, Miami along with Tammy’s daughters, Lindsey and Megan, and Lauri''s daughter, Ashley. Money woes put a damper on the Knickerbocker girls’ good time and a trip to a famous tattoo parlor gets McKenzie in hot water with dad George.

Vicki invites Jeana, Colton, Tammy and Frankie to spend the weekend with her and Donn at their Lake Havasu vacation home. The alcohol flows like the river on which they party, but tensions between Vicki and Donn threaten to ruin the trip. Things turn dangerous when Colton takes a shocking death defying jump.

Laurie furthers her wedding plans by choosing a photographer and wedding invitations, while newly single Kara contemplates an offer from mother Jeana to take part in a mother/daughter pictorial for Playboy magazine.

Tamra throws a big birthday bash for son, Spencer, who just turned seven. The party atmosphere can''t tame the tension between her oldest son, Ryan, and her husband, Simon. Later at a family dinner, jobless Ryan bickers with step dad Simon, putting Tamra in the middle again.', '2007-11-20', 44, '/5DJck647GwngDpJXLQkp6HoiK8V.jpg', '2026-04-03T16:35:30Z', '2026-04-03T16:35:30Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('7240e0a7-38db-495f-87d8-1e5bb78be4a6', 'd0b78f22-678e-4e46-9d61-aac40ba206b8', 7, 'Eat, Drink, and Be Married', 'Kyle, Dorit, and Teddi shop for a wedding gift for Denise, who scrambles to pull off her big day in record time. Lisa Rinna comes face-to-face with an old flame, who dated both her and Denise at the same time. After their disastrous run-in at Camille’s birthday party, Lisa Vanderpump dreads seeing Teddi at the wedding. Erika prepares for the launch of her new tour.', '2019-03-26', 43, '/vNlAGEmVlPHlRiXfhYHicNZhs8M.jpg', '2026-04-03T16:34:57Z', '2026-04-03T16:34:57Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('72430b86-e3f0-41bb-b949-5161f856333d', '4060ad7f-4b8f-4393-8eb1-66a150b928b6', 29, 'A Windy Mystery', '', '2021-05-20', 26, '/rpsEqKwyf6YZ79gnzShwN0ofj2L.jpg', '2026-04-03T17:36:50Z', '2026-04-03T17:36:50Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('7247c9e5-d9dc-4629-bf45-17a1041eeaf8', '42e591e2-2a88-4434-ae9f-3d4b1d685613', 35, 'The Bachelor', 'Celebrate Rick Harrison''s last days of freedom, as the Pawn Stars throw him a bachelor party. Can he survive what they have planned? Then, a rare salesman''s copy of "The Adventures of Tom Sawyer" comes in the shop. A prospectus used for selling the book door to door, will the guys be sold? And later, the Old Man schools Lili the intern on Vegas history when some vintage casino chips come into the shop. Is this deal worth going all in.', '2013-11-14', 21, '/qr4m8EYtqBjogJevTvww755B3jb.jpg', '2026-04-03T16:34:18Z', '2026-04-03T16:34:18Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('72492931-bf99-4185-bf42-e00f3e8c147a', '42e591e2-2a88-4434-ae9f-3d4b1d685613', 16, 'Chum-parazzi', 'Flip the switch with the Pawn Stars as they check out a poem written and signed by inventor Nikola Tesla. Famous for his work with electricity, will this piece leave Rick in a state of shock? Then, a pair of wooly chaps rides into the shop. Made for cold weather cowboys, will the deal make the guys feel warm and fuzzy? And later, Chumlee goes on a quest for a famous musician''s autograph. Can he use his ninja skills to track them down?', '2013-08-01', 21, NULL, '2026-04-03T16:34:18Z', '2026-04-03T16:34:18Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('724ea1de-8d9e-4db7-bd00-f5da1a630dd5', 'bcab920a-51a5-4cbb-aa59-41578a0eb005', 1, 'Stronger Than Ever', 'Lisa Vanderpump introduces the group to her friend Dorit, whose permanent houseguest is Boy George. Erika celebrates her 45th birthday in style with a 1970s-inspired Studio 54 party and receives more than one birthday surprise. Lisa Rinna and Eileen awkwardly come face to face with Lisa Vanderpump for the first time in months.', '2016-12-06', 43, '/v5dqIUzEUodlCtpkfCQMHwIIwwe.jpg', '2026-04-03T16:34:56Z', '2026-04-03T16:34:56Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('725034ff-3d7d-46a1-9f63-a51c95eba32f', 'fc120008-c5c4-47d7-a3a9-91a401394c41', 23, 'House of Mirrors', 'Sister visits a house of mirrors in a carnival.', '2003-02-05', NULL, NULL, '2026-04-03T17:40:21Z', '2026-04-03T17:40:21Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('72522d2c-44c2-4cbb-b1fd-7832de5e9082', '9f448cb8-07f8-4040-840b-c8690371ec41', 5, 'The Package', 'Elaine regrets peeking at her medical chart; George takes dating advice from Kramer, who also hatches a scheme to improve Jerry''s stereo.', '1996-10-17', 22, '/ts2HTJvIw5lMD2STqx6yaV0CtH9.jpg', '2026-04-03T16:34:12Z', '2026-04-03T16:34:12Z');
