INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('7255a864-3b6a-40b9-8756-71c080806605', '8c3cfac1-d882-4904-b38c-d1981628d00e', 41, 'Episode 41', 'Fifteen years after discovering the South Pole, Norwegian explorer ROALD AMUNDSEN attempted the world''s first airship flight over the North Pole. Christopher tells the story of this hazardous flight which includes rarely-seen archive film of Amundsen in action in his dirigible, the Norge.', '1979-02-01', NULL, NULL, '2026-04-03T17:21:54Z', '2026-04-03T17:21:54Z');
