INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('7258e75b-cf76-48f6-a484-5b64cdfeea65', '3269a890-bba9-4e6c-9278-f7eb38eb1720', 16, 'Human Transportation', 'Transportation is all about moving people and their things. You can transport yourself around using your feet, a bike, a car, a train – anything that gets you going from one place to another. Humans have been moving around from place to place ever since they’ve been on Earth. That’s how we get our food and our materials like lumber, concrete and computers from one place to another.', '1995-09-29', 26, '/gcbXLSVvv69szkuZELH9Xmzsz91.jpg', '2026-04-03T17:37:21Z', '2026-04-03T17:37:21Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('725f458c-8221-4b7c-ade2-03360c827685', 'ecb64ef3-4f80-45a7-b4a9-c04434b02e35', 13, 'Rough and Tumble', 'Tame the beast with the Pawn Stars when Rick checks out some items signed by "Grizzly Adams" actor Dan Haggerty. Can this TV icon bear a bargain, or will the asking price be too wild? Then, a piece of flag carried by Teddy Roosevelt''s Rough Riders flies into the shop. Will Corey and Rick let this piece of presidential history pass them by, or are they facing an uphill battle? And later, Chumlee buys an old foot oscillator and can’t help but try it out. Will he get away with a mid-shift foot massage?', '2014-02-13', 21, '/lLhoPorH0ZBKS5RuTdpzZ6jerPN.jpg', '2026-04-03T16:34:19Z', '2026-04-03T16:34:19Z');
