INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('72c35af3-c5c5-4b5a-811a-54a714e5ccd4', '5062ce29-8dbb-48ab-879b-0771221678d5', 8, 'Badger''s Bath', 'Badger spends a long time digging, getting himself dirty. Percy tries to give the badger a bath, but he doesn''t want one. As Percy has the bath to himself, Badger falls out of his hiding place into the bath tub.', '1999-11-07', 15, NULL, '2026-04-03T17:19:02Z', '2026-04-03T17:19:02Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('72cc58e0-7377-4686-811b-992ec3131826', 'ae8f64d9-4b83-4147-a44c-bfe720381f8e', 26, 'Princess Show', 'Abby, Rosita and a penguin are going to play princesses. First, they decide to dance. Rosita leaps high into the air. Abby leaps even higher. The penguin takes a running start and leaps so high she lands on a balcony and can’t get down! Uh-oh! Suddenly, a prince enters and offers to rescue the penguin. He calls for her to let down her hair like the prince does in “Rapunzel,” but penguins don’t have any hair!  Abby flies up and brings the penguin safely to the ground.

Next, Abby, Rosita and the penguin go princess-roller skating, but the penguin can’t find her second skate. Never fear! The prince comes along to help. He pulls out a glass slipper, just as the prince does in “Cinderella”, but the penguin can’t skate with a glass slipper!  Abby suggests they just look for the other skate. They find it and continue skating.

Abby skates fast. Rosita skates even faster. The penguin skates the fastest and loses control. She crashes into a mailbox and gets stuck! The prince comes along to rescue her and give her a kiss, just like in “Sleeping Beauty” and “Snow White”, but a kiss won’t help the penguin get out of the mailbox. Rosita has a better idea! What if they cooperate and work together to help pull her out? It works! But the prince is upset. He wasn’t able to rescue a princess even once today. Abby explains that just because they are dressed as princesses, doesn’t mean they have to be saved. The prince agrees and they happily play a game of football together.', '2010-02-18', NULL, '/g2POcZ2NLHqC6NHyCSktsVamhAA.jpg', '2026-04-03T17:36:46Z', '2026-04-03T17:36:46Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('72cd783e-7f50-49e0-8b3b-8d7ffd07302a', '4861ce46-9045-43c7-963f-27b4ea539804', 43, 'Episode 173', '', '1971-01-06', NULL, NULL, '2026-04-03T17:36:28Z', '2026-04-03T17:36:28Z');
