INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('72f10384-e6e6-4d64-b114-c66087d916e0', '3a96d6c6-3736-498a-926f-6c479cdfb73a', 22, 'Franklin Takes the Blame', 'Mr. Mole asks Franklin to take care of his flower garden while he goes on vacation. However, Franklin gets sidetracked and kept forgetting to water Mr. Mole''s garden. When he discovered his error, he tries to correct the problem, only it couldn''t be fixed.', '1998-01-12', 12, NULL, '2026-04-03T17:40:14Z', '2026-04-03T17:40:14Z');
