INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('72fe85e9-0007-482e-9109-d0d2b45802ed', '91c151d9-8497-4056-a4ee-753cdcb08cea', 3, 'Episode 1458', 'Mister Rogers arrives with a large black cape which he has borrowed from Margaret Hamilton. Taking the cape to the garage, he talks about acting and pretends to be Mr. McFeely. While he waits on a visit from Joe Negri, Mister Rogers shows the video camera he has set up before he sings Pretending.', '1976-02-18', NULL, NULL, '2026-04-03T17:35:41Z', '2026-04-03T17:35:41Z');
