INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('73009f45-e78b-408a-8f4a-917880f610c2', '2005d71d-54eb-49f8-ae9c-039eae4089b3', 4, 'Mother''s Day', 'Neil''s mother, portrayed by Eileen Armstrong, is coming to lunch aboard the Ragdoll and Rosie and Jim try to help prepare. However, they end up making a mess.', '2000-01-25', 10, NULL, '2026-04-03T17:19:39Z', '2026-04-03T17:19:39Z');
