INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('7320c486-a995-42b1-9554-4dc0fabc8df9', '54facb0b-db59-41fe-9d64-c7c7221a3c81', 13, 'It’s Not You, It’s Miami', 'After Sonja crashes Lu’s rehearsal, Luann asks the women if they think Lady Morgan might be taking something to make her act this way. The ladies then head to Miami for fun, sun, and the revelation that Ramona made out with Harry Dubin. It’s all too much for Sonja to handle, and after a few drinks she lashes out at Luann and Ramona.', '2019-05-29', 60, '/kTNbQhlOkO7sRcFhkEI9QDVpsa5.jpg', '2026-04-03T16:35:25Z', '2026-04-03T16:35:25Z');
