INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('7325a5c3-23ca-44ef-b388-22c8245d4a2b', 'f5266c49-eb29-4594-b5d9-f927edfee336', 26, 'Picture Perfect', 'After completing all his tasks, Bitzer is shocked to find the state of the barn and decides to help by tidying up. He has lots of difficulty trying to rehang a wonky picture, till the flock come up with their own solution.', '2014-09-24', NULL, '/j2cHUAOQYas9Rm8Ph4gSuy9OHBd.jpg', '2026-04-03T17:39:32Z', '2026-04-03T17:39:32Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('73284476-c046-4075-b6dd-fe207e489106', 'dbd3583f-e9b2-46d1-a37e-309eb666e233', 2, 'Surprisingly Rich', 'Fresh off her verbal smack down with Sheree, NeNe decides to take a break from Atlanta by rounding up Cynthia and Kandi for a girl’s getaway weekend of fun, sun and Lesbian Pride in Miami. Phaedra''s fascination with the dead goes a step further as she explores opening her own family funeral business, but Apollo''s creeped out by Phaedra''s new passion. Sheree and Kim have some of their own girl time to discuss Kim and Kroy''s future plans. Meanwhile, Kroy and Sweetie conspire to throw an intimate surprise bash for a very pregnant Kim''s 33rd birthday, complete with expensive jewels.', '2011-11-13', 43, '/f0Dx9sdHAspmegibILwLTF2tZA3.jpg', '2026-04-03T16:34:45Z', '2026-04-03T16:34:45Z');
