INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('732c3229-7b36-43c5-a453-f0d9243d3fc5', '38bf8c20-c17c-4071-9226-7887787cf1b1', 1, 'The Sad Dad', 'Bruno Kirby plays a Dad whose house is overrun by kids: ""There''s hardly enough room to put on pants!"" he complains. Fed up with all this overcrowding, he decides to seek the advice of an old wise woman in town - who only adds to the problem!', '2001-04-02', 30, '/2QzoHYpm9wZBnpwIroIvilBS9vT.jpg', '2026-04-03T17:12:28Z', '2026-04-03T17:12:28Z');
