INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('735ab676-866f-4d2c-b984-8580bae4877c', '98d80972-e53a-43dd-a03a-7703465e6f87', 24, 'Off the Hook', 'Court is in session for the Pawn Stars when the guys check out a collection of sketches from the 1954 Sam Sheppard trial. The man who inspired "The Fugitive," is Rick willing to deliver a verdict on these rare drawings? Then, a baseball signed by the entire 1962 American League All Star team slides into the shop. With signatures from Yogi Berra and Mickey Mantle, do the guys play hardball, or strike out looking? And later, when Chumlee calls in sick, the guys are on the case to see if he s faking it. Will his story check out?', '2013-02-04', 21, NULL, '2026-04-03T16:34:18Z', '2026-04-03T16:34:18Z');
