INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('737cdad7-0591-4490-b090-560b2a463a10', '787dfa0b-c827-4dad-a82d-0548a6534d88', 18, 'Satan Loves Confusion', 'Vicki''s daughter Briana visits the OC and meets Tamra for lunch with some shocking new information about Brooks. Shannon''s rekindled relationship with Heather and Tamra allows her to confide in the ladies in a way she never thought possible. The ladies prep for Tamra''s baptism in some unconventional ways.', '2015-10-05', 44, '/rNyXpYGgJhLPkGyEQjln31FtwbA.jpg', '2026-04-03T16:35:32Z', '2026-04-03T16:35:32Z');
