INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('73865fba-807a-47a5-af63-e58daad9c141', '227b8429-0dfd-47e4-b874-c37da20c403f', 16, 'Sharks and Cobras', 'Rick and the Old Man look to buy a 1965 Shelby Cobra classic car - one of the most expensive American race cars. Will they burn rubber and make a deal or will they slam on the brakes for a fake? Then the Pawn Stars have a chance to buy a ship''s clock from a 1942 WWII Ship that''s worth money only if it ticks.', '2009-11-30', 21, '/dAqnmBBQ4gxrq9bJ9ItMB6WPFeJ.jpg', '2026-04-03T16:34:15Z', '2026-04-03T16:34:15Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('738a1981-baf1-49e4-b5cb-75a216980b6e', '42e591e2-2a88-4434-ae9f-3d4b1d685613', 13, 'World Series of Pawn', 'Take me out to the Pawn Stars when the guys look at a Los Angeles Dodgers World Series Pennant signed by Frank Sinatra. Will the connection to ol'' blue eyes send the price to the moon? Then, a replica of the Delorean from "Back to the Future" flies into the shop. Can they accelerate this deal to 88 miles an hour? And later, when Chumlee keeps losing the shop''s keys, Rick has to get creative to break him of the habit.', '2013-07-18', 21, NULL, '2026-04-03T16:34:18Z', '2026-04-03T16:34:18Z');
