INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('73a25797-f133-473e-b4ba-2502cc2c63ae', '7eef937c-4483-42bd-bafe-263a7d4e4573', 8, 'Goes Upstream', 'Ralphie wants to serve salmon at the annual school picnic, but he can’t find any at his favorite fishing spot. But when the kids are “Frizzled” inside a salmon-bus they have an uncontrollable urge to head upriver.', '1996-11-02', 25, '/9C83T1ktOx2CRHH61SFp2XhjZX2.jpg', '2026-04-03T17:37:49Z', '2026-04-03T17:37:49Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('73a5a4a5-2fcd-4014-8f38-f8c7bdde561f', '2f8dd629-82c3-4f8e-87c0-963473c49284', 17, 'Reunion (2)', 'In the dramatic conclusion of the Season 15 reunion, Jenna scolds Brynn for not taking enough accountability. Rebecca defends her beliefs. Brynn addresses the allegations she made on the last night in Puerto Rico.', '2025-02-04', 55, NULL, '2026-04-03T16:35:26Z', '2026-04-03T16:35:26Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('73aa9f31-631b-442e-8340-ee7538527117', 'b1d55597-d9d2-4eee-ab95-46dbb163291a', 2, 'Pingu Helps to Deliver the Mail', 'Pingu is helping his dad deliver the mail. His dad lets him wear his postman''s hat, and they go to the post office to pick up the mail and then deliver it to the town''s various eccentric residents; including an old, kid-hating granny penguin, a tall, loud-beaked (bird style for loud-mouthed) penguin, a short, zippy and strange penguin in suspenders (this is Punki, who also slams the door right in Pingu''s face as he opens it!), Pingu''s friend Pingo, a sad penguin with bad news, a woman with three children, and others, before returning home again to his mum''s arms.', '1986-06-04', 5, '/qGNCiD4pfkhGttgWgxqyHjqXK2Y.jpg', '2026-04-03T17:22:18Z', '2026-04-03T17:22:18Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('73ab7d04-110a-424c-a2b7-1337fe74e916', '03485b5e-a5b7-423e-b21e-c00e62216a35', 10, 'Grow It', 'Sister has been having difficulty growing things, even herself.', '2004-04-06', NULL, NULL, '2026-04-03T17:40:22Z', '2026-04-03T17:40:22Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('73aba76d-85b9-48b9-bfe3-cf952a376d40', '1415ef1c-411a-4c26-814a-7c79c3628bc2', 11, 'A Countess No More', 'Bethenny hosts her annual holiday party, but Ramona’s not invited. Ramona gets advice on her situation with Bethenny from her daughter Avery and Avery’s friends. Luann and Tom get married in Palm Beach on New Year’s Eve. Tinsley learns that "Frenchie" has moved into Sonja’s townhouse. Newlyweds Luann and Tom host a NYC reception for the friends not invited to the wedding.', '2017-06-14', 60, '/f5k7foFllhioV4Dp71t86n3Nq8Z.jpg', '2026-04-03T16:35:24Z', '2026-04-03T16:35:24Z');
