INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('73e64e7d-78a2-4a75-90fa-5be4957233ca', '6c71887a-d6e3-41f1-aa7c-f482abc104d2', 3, 'The Silver Chair (3)', 'Journeying on, Eustace, Jill and Puddleglum meet a lady in green who gives them directions to the castle of Harfang with the promise of food and shelter. But will their eagerness to get there distract them from their mission and make them miss another of Aslan''s signs?', '1990-12-02', 29, '/1iqiACZDGVvIlFeHRECH9lpga7d.jpg', '2026-04-03T17:17:41Z', '2026-04-03T17:17:41Z');
