INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('73f21f25-f3fa-48e6-b28f-5c62820027e9', '70c8cb46-2494-4dd4-98f6-6bfb9b3faf73', 29, 'Strike, Spare, BOOM', 'The Pawn Stars are blown away when they meet a guy selling his homemade mortar that fires a very unique brand of ammunition - bowling balls. Will the gang line up their aim and strike a deal or will a misfire send the deal into the gutter? Then Rick is handed an extremely rare World War II gas mask believed to have been designed for baby. Will Rick try to buy this unusual artifact, or will he throw the baby out with the bathwater? And later, the Old Man has a chance to buy an original unused ticket to the 1965 classic bout between Muhammad Ali and Floyd Patterson. Will the Pawn Stars go the distance for this piece of boxing memorabilia or will a surprise uppercut sting like a bee?', '2010-06-28', 21, '/hxnhnkRmEkinS5SRmB59EhXA5v5.jpg', '2026-04-03T16:34:16Z', '2026-04-03T16:34:16Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('73f3cd99-53dd-4a99-a79f-b1c3e561dc34', 'a8db07e5-fba3-49a9-bd12-947c111b39be', 8, 'All the Countess''s Men', 'Bethenny hosts a gift-exchange party, where the hot topic is a trip to the Berkshires. Also: Dorinda relays disappointing news to Sonja; LuAnn introduces her boyfriend; and, in the Berkshires, it''s discovered that Ramona shares a past with LuAnn''s man.', '2016-05-25', 44, NULL, '2026-04-03T16:35:24Z', '2026-04-03T16:35:24Z');
