INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('7402ed4d-a26b-4bbc-98d1-1202bd93a11c', '852a07b0-f228-4197-9147-7aeed79390bf', 12, 'Baby, It''s Cold Inside', 'In the city after their trip to Salem, Eboni and Sonja get back in the boxing ring with Martin. While Luann and Leah plan a joint birthday party for Ramona and Sonja, Eboni continues her search for answers about her family history. The women join Luann to record her new holiday song for charity, but Leah has questions about legalities and the proceeds. Then the group celebrates Ramonja''s birthdays with a grab bag of local eye candy.', '2021-07-27', 60, '/acUaJXcrzCQ81wHIfYBY6ECLbQq.jpg', '2026-04-03T16:35:26Z', '2026-04-03T16:35:26Z');
