INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('740e6cb6-5e71-4c62-90c8-fb4580183291', '120dbabe-a178-4607-be15-76335687f9f1', 6, 'Badger''s Parting Gifts', 'LeVar discusses cathartic ways to adjust to losing a loved one in this episode. He and fellow viewers talk about family members that are now gone that they miss, and how they try to remember the good times rather than dwell on the pain. Ruby Dee reads the featured story about an aging Badger, who knows he doesn''t have much longer to live and tries to prepare his friends for his passing.', '2001-04-20', 30, NULL, '2026-04-03T17:36:21Z', '2026-04-03T17:36:21Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('740ee2d9-deca-4a63-bdf6-40d5bfa0e931', 'c7994637-b7c7-42c7-aaee-1bff4144fe23', 1, 'The Eaglewoman Has Landed', 'Following a tumultuous year, Dorit hosts the ladies at a retreat, hoping to get an eagle-eyed perspective on their issues. While Erika seeks to rebuild her life following her husband''s indictment, she''s forced to deal with the consequences her behavior has had on her friendships. Garcelle tries to navigate her relationships with her teenage boys. Kyle''s new focus on fitness and self-care offers a sobering look at her home life.', '2023-10-25', NULL, '/gzklVzPm2nfjueww8d4TEqLbeXO.jpg', '2026-04-03T16:34:59Z', '2026-04-03T16:34:59Z');
