INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('7418d1ff-e9a7-4c2a-8bae-d16adcde7039', '6c1ec19f-74df-4f35-9a61-17b98175d826', 10, 'Black Ties and White Lies', 'Garcelle finds herself in a tough spot during a business meeting. Lisa questions Denise’s motives when Denise’s behavior is filled with shades of grey. With Dorit’s help, Kyle throws a black and white charity gala full of familiar faces from years past. Erika tries to avoid being “mansplained" to again, while Camille’s road to reconciliation is bumpier than she expected.', '2020-07-15', 43, '/98sFHNOw9xp2xYTIqEAIOMeoa15.jpg', '2026-04-03T16:34:58Z', '2026-04-03T16:34:58Z');
