INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('742a0566-51a4-468d-bea6-f0fcfb301a59', '4c79c0b6-21a4-4277-8967-be1e791efdbe', 22, 'Pingu''s Big Catch', 'Pingu is going fishing. Mother and Pinga come out to say goodbye, and Pingu says he’ll catch a big fish. On his way to the pool Pingu comes across Father, who is fixing his motorised sledge, which has broken down. Pingu hoots in his ear, which makes Father jump and drop the screwdriver. Pingu tells Father that he’s going to catch a big fish. When Pingu reaches the pool, Pingg is already there fishing. Pingu tells Pingg that he’s going to catch a big fish and starts fishing in a pool nearby. Pingg soon lands a small fish. Pingu then has a bite and catches a top hat. Pingg finds this very amusing. Pingg then catches another fish; Pingu catches a spring. The spring bounces around, and into Pingu, knocking him down. This again amuses Pingg. Pingu is annoyed, and insists on changing places with Pingg, who reluctantly agrees. They settle down to fish again, and Pingu catches a bicycle wheel. Pingg then catches another fish, and Pingu a lavatory seat. They swap pools again. Pingg catches another fish, Pingu catches a broken kettle, and then an old boot. Pingg is rolling about with laughter. Again they swap pools and, as Pingg lands yet more fish, Pingu gets a rusty pram. Pingu sits down, very dejected, while Pingg counts all the fish he’s caught, and then holds up a fish in each hand and makes fun of Pingu. Just then a rag and bone penguin comes by, sees all the junk that Pingu has caught, and offers him a big fish for it. Pingu is delighted to accept, while Pingg bemoans the fact that the fish he’s got are only small.', '2006-02-27', 5, '/Wb6pUybWl7UVMNDhNaRrGkmtqW.jpg', '2026-04-03T17:22:21Z', '2026-04-03T17:22:21Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('742c3325-105e-402b-b8b0-46f1a5b03940', 'a2edcb57-63c1-4028-b87b-7faeae2c999b', 8, 'Dare You', 'Nicolette has some concert tickets but daring Bernard to eat a fish, will Bernard eat the school pet?', '2004-02-24', 15, NULL, '2026-04-03T17:20:06Z', '2026-04-03T17:20:06Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('742e0419-3acc-43fc-bbb0-40be2663ecb6', '495d4222-b33a-46fa-8351-3265798e558b', 2, 'Birdsdo', 'The Gribble family - Port Niranda''s most notorious residents - are trying to get rid of Old Nell, so they can buy her house. The kids must prove Nell is fine but to do this, they must go up against birds who have real problems with their bowel movement.', '1990-04-13', 24, '/2gPRglycwooTD124jjwXfakxlzI.jpg', '2026-04-03T17:40:40Z', '2026-04-03T17:40:40Z');
