INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('74334dec-8801-4248-a4b2-68c9168b3a99', '3fc7c152-e4f6-426a-a899-36ec454c4403', 35, 'Quibbling Siblings', 'Zak wants the rare Jugglebug for show and tell, but Wheezie is so noisy, she scares it away. With Max and Emmy''s help the dragons find that working together gets the job done.', '1999-10-20', 30, '/vz7qQp5aLzpI5n0eSeEvnErLzQd.jpg', '2026-04-03T15:26:03Z', '2026-04-03T15:26:03Z');
