INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('746f2a22-d583-4386-860b-d4a24e2ee307', '9dff2271-f91b-47c1-a20d-58973840b764', 12, 'If These Walls Could Talk', 'Bronson is sick and tired of not being told anything but now every piece of furniture can talk!  Bronson decides to rescue Fay from Mr. Snapper by retrieving the Book of Love.', '2000-03-15', 24, NULL, '2026-04-03T17:40:41Z', '2026-04-03T17:40:41Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('746f3ee7-9862-452f-a45b-2bd354e5c6c5', '5ba20443-d99f-4820-81f6-6832d3f2bc4f', 19, 'Fossils', 'Most dead animals and plants break up, get decomposed, and become part of the soil, but some turn into fossils. A fossil forms when a plant or animal dies, and gets buried. If conditions are right, water gets into the fossil bed, and chemical reactions preserve the impressions for thousands or millions of years. There are different types of fossils — imprints of animals, black carbon outlines, hardened bones, or actual animals and plants that have been trapped in ice or hardened tree sap.', '1997-09-05', 26, '/saQZFcJ0AzStTCgri4mrzghP6ie.jpg', '2026-04-03T17:37:21Z', '2026-04-03T17:37:21Z');
