INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('7499f053-f175-4785-80e7-89fcf8b878eb', '4f18ac4c-8757-456c-a49a-224f00e6a9f7', 17, 'Abby''s First Sleepover', 'Abby Cadabby sleeps over at Big Bird''s nest. Which delays Luis and Maria from dancing.', '2008-10-10', NULL, '/kK11Xgab4cIER3nr2yexYhnHz94.jpg', '2026-04-03T17:36:45Z', '2026-04-03T17:36:45Z');
