INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('749d52c1-4b40-4006-8317-02d72fffee01', '6f81c872-cdb9-42dd-8377-2c17cb6ed4d7', 4, 'Super Sitters', 'Grover and Cookie Monster help Chris baby-sit and learn how to take care of a baby.', '2017-01-28', NULL, '/6iK17GBb3D0ODrRz5b5YLrvctNi.jpg', '2026-04-03T17:36:48Z', '2026-04-03T17:36:48Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('749f8cfa-c014-48c3-8660-2f839ff13925', '56428e5e-7daa-468d-8bd2-076956507aa8', 13, 'The Sun', 'The Sun is huge. It''s bigger than huge. It''s so big that 1.3 million Earths would fit inside a hollowed-out Sun. It''s really far away, too - about 150 million kilometers (93 million miles) Even at that distance the Sun affects everything on Earth. All the energy we have comes, or once came from, the Sun. That includes energy to light a lamp, energy to kick a soccer ball, and energy in batteries that play your personal stereo. We''re talking about nearly all of the energy. There''s a little bit of energy that comes from nuclear reactions deep in the Earth''s core. But that energy pales compared with the nuclear fusion fueling the Sun. Without the Sun, the Earth would be a big hunk of rock with nearly nothing on it. The Sun is made of gas. It has so much gravity that it''s atoms are smashed into hot gas. In the sun, atoms of gas are constantly crashing into each other. When they collide, they form new atoms and release energy. Scientists call this atom smashing "nuclear fus', '1994-10-22', 26, '/wb5Qf18Rop2vJWIhOsZMKWlzBIw.jpg', '2026-04-03T17:37:21Z', '2026-04-03T17:37:21Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('74a4ccbe-9103-4e6f-b9a1-231bf655e128', '3fc7c152-e4f6-426a-a899-36ec454c4403', 23, 'Zak and the Beanstalk', 'The Do-Re-Mi birds (from “Zak’s Song) have been kidnapped, and it is up to Emmy, Max, Zak & Wheezie to come to their rescue. When they learn that a giant named Mungus took the birds because he loves their songs, they teach him how to make his own music.', '1999-10-05', 30, '/2f4EONSg5hIJkMuejoo2V05ygZO.jpg', '2026-04-03T15:26:03Z', '2026-04-03T15:26:03Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('74ab8266-612f-4012-882f-0d07913def63', '04207e76-d855-4f29-a066-1732feea34b5', 8, 'Bubbies Gone Bad', 'Danielle goes under the knife to fix one of her biggest issues. Meanwhile, Teresa rolls out the red carpet for her long awaited housewarming party and Caroline deals with family issues.', '2010-06-21', 43, '/kfAl2FoM9U0PLbWW7jlDWnWIhS.jpg', '2026-04-03T16:35:15Z', '2026-04-03T16:35:15Z');
