INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('74b37232-97cd-4c09-8610-0dcdc60e0806', '8bae6aa3-4b55-4fa6-bc15-8f4317bd1f13', 4, 'Episode 4', 'While seeing the breads at Brockett''s Bakery, Rogers learns how a bread slicer works. The Neighborhood of Make-Believe discovers a floating loaf of bread from the Owl Correspondence School. X registers himself for a course.', '1972-02-24', NULL, NULL, '2026-04-03T17:35:39Z', '2026-04-03T17:35:39Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('74b3775e-f132-4351-bee7-4fafcf819528', '79c64e0a-3488-41bc-9b5c-2243ff15b373', 12, 'Arrivederci Beverly Hills', 'After smooth sailing in the Hamptons, tensions rise when Dorit discovers Kyle has been talking behind her back. Rachel sits her boys down to discuss her divorce. Amanda throws herself into planning her extravagant wedding. Boz invites the girls to join her on a trip to Italy at a bellissimo Tuscan villa where Sutton learns that no good deed goes unpunished.', '2026-03-05', NULL, '/AaZzmvCUAHKK9YDEouYxHIT8Gk5.jpg', '2026-04-03T16:34:59Z', '2026-04-03T16:34:59Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('74b45c2b-2978-454a-90b7-2f397c2cacae', '204d86fb-d99c-4fd1-8dcd-9c1bcfd3c33f', 10, 'Breaking Up is Hard to Do', 'Max and Ord are both proud of the art project they created, but they have arguments since they have a hard time agreeing on who gets it to take it home first, since they both want to take it home at the same time. Quetzal later shows them how to take pride in sharing.', '2001-06-08', 30, NULL, '2026-04-03T15:26:04Z', '2026-04-03T15:26:04Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('74b68e93-d4cb-4743-a6cb-91dfebdcfbfa', '0987f081-b3b7-4e3c-abb7-795e56c279d5', 13, 'The Friend', 'Frankie tries to get Mike to spend time with a new neighbor who shares his interests; Sue demands a cheer-off between the Wrestlerettes and the cheerleaders.', '2013-01-23', 22, '/cqFAyoaCLoH4T5MPpm7mDZy64qx.jpg', '2026-04-03T15:40:30Z', '2026-04-03T15:40:30Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('74b878d4-cdd0-4143-b442-bc20c61422d9', 'e13f4aa4-dd8a-48d5-8cc1-1c258f43e44d', 800, '100th Episode Special', '', '2013-06-24', 44, NULL, '2026-04-03T16:35:29Z', '2026-04-03T16:35:29Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('74bc95d1-faca-4aa6-a289-307c848e6639', 'fd0f7dfb-28aa-4687-9ef8-8ff0088ce25a', 21, 'Three Cheers for Us', 'Zoe, Elmo, Telly and Slimey want to be cheerleaders, but they need to find someone to cheer for.', '2014-02-03', 58, '/f9QYYfs2XLilthg9KeCyLU8xLz7.jpg', '2026-04-03T17:36:47Z', '2026-04-03T17:36:47Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('74bcf29c-ad1a-4399-ad6a-a926f99550b0', '04e133fd-c4a3-4dfa-8369-c6dcfd1e3a5a', 80, 'Episode 2045', 'Uncle Wally arrives wearing rabbit ears borrowed from a country friend to experience how jackrabbits hear the world. Big Bird and Uncle Wally sit quietly thinking about subtraction, which Gordon counts in voiceover. Uncle Wally demonstrates the letter G for "giggle" by making everyone burst into laughter, and performs "Here Are Some Things" with threes before producing an elephant from his suitcase.

Sponsors: G, P, 3', '1985-03-08', NULL, NULL, '2026-04-03T17:36:36Z', '2026-04-03T17:36:36Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('74c13102-ae28-450a-b8e8-533a858af1c4', '9c9d89df-5f6b-41d0-84c6-b8ca7bd2a2e6', 7, 'The Grouch Band', 'Oscar is getting ready for a virtual Grouch concert with the noisiest and most annoying instruments. Elmo’s Shaky Shake instrument isn’t noisy enough for the concert. What if he adds more rocks and blocks to his jar? Let’s try!', '2021-12-23', NULL, '/l5UK3VUvaa4HihYLzsBybcUP3tk.jpg', '2026-04-03T17:36:50Z', '2026-04-03T17:36:50Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('74c1f978-d7c2-450d-9c98-31f3437b254d', '8e5ed8a4-08e5-4006-9f36-c68c91ddfee4', 7, 'Episode 756', '', NULL, NULL, NULL, '2026-04-03T17:36:40Z', '2026-04-03T17:36:40Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('74c6bda8-1fa6-406d-9770-8b586e2343eb', 'd7ff9136-a833-4c43-a37c-a985a34f45a9', 9, 'Battle Lines Are Drawn', 'Janelle, Christine and their older kids gather for dinner, and things get intense as they express their frustrations about Kody and Robyn.', '2023-10-15', NULL, '/x4UJHksn1b13lWjXK54ljKmJvwU.jpg', '2026-04-03T16:34:32Z', '2026-04-03T16:34:32Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('74ca5784-1960-4e19-a743-631a87f808a3', 'bf874be3-7e2f-4a0e-b205-c76ac1ad69fc', 18, 'Inside Looks: The Bet', 'Inside look from the season 2 episode "The Bet." This episode was never created due to its controversial subject.', NULL, 3, NULL, '2026-04-03T16:34:08Z', '2026-04-03T16:34:08Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('74d09298-82b9-4ee8-a570-77e8e3522bec', '082d18af-d82e-4db8-8746-1f7473706dae', 12, 'Three by the Sea', 'Three by the Sea', '1983-06-21', 30, NULL, '2026-04-03T17:36:14Z', '2026-04-03T17:36:14Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('74d6070b-6cc0-444c-8d5f-b0aa833e6f0f', 'f12380a9-93e5-47bb-9e2f-cf1eed11eee4', 8, 'Making Out Like Teenagers', 'Coyote Pass has finally sold and it''s the final chapter in the family''s breakup. Kody, Robyn, Janelle, and Meri anxiously prepare to meet on the land to close out the deal. In North Carolina, Maddie has her baby girl.', '2025-11-16', NULL, '/y1To6PCZv2IXlmm3xpBbrK2Tk8O.jpg', '2026-04-03T16:34:33Z', '2026-04-03T16:34:33Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('74d74436-70ce-4059-bf3e-96d72df42f74', 'a9657e86-4135-49ce-b1f9-c295113077e1', 17, 'Express Yourself', 'Enrique gives Cassie a nickname she doesn''t like, since it reminds her of a new dragon in school who used to bully her, but Cassie is too shy to express her feelings to him.', '2005-03-04', 30, '/uYZlOQ1E7YTNoYLEdqOGnCPJNVJ.jpg', '2026-04-03T15:26:04Z', '2026-04-03T15:26:04Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('74d82625-b221-44b3-9835-cdc9e580a76f', '63f9bf6d-39b3-44f4-b885-a56807277a80', 15, 'The Muppets at Walt Disney World', 'A special which aired as part of The Magical World of Disney, this show was designed to promote a planned merger between The Walt Disney Company and The Jim Henson Company that would ultimately fall through upon Henson''s untimely death.  In the show, Kermit and Robin take the Muppet gang to the  Florida swamps for the annual Bug Fry and a frog family reunion. However, the other Muppets, unexcited  by a stinking bog, become excited when they learn they can see the fireworks from nearby Walt Disney World. Kermit agrees to let the gang "take a short peek" and be right back. As the Muppets accidentally break into the park, security tries to round them all up as they visit  the Magic Kingdom, EPCOT Center, and Disney/MGM Studios. Finally, after being rounded up, Kermit meets Mickey Mouse, and the show ends with a huge musical number.', '1990-05-06', 60, NULL, '2026-04-03T17:35:23Z', '2026-04-03T17:35:23Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('74d950cf-7172-44d4-ad7a-09839fdd5029', 'a9657e86-4135-49ce-b1f9-c295113077e1', 7, 'Sky Soccer', 'Ord''s friends help him get better at soccer by holding drills.', '2005-02-24', 30, NULL, '2026-04-03T15:26:04Z', '2026-04-03T15:26:04Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('74dc7b3b-9b22-46df-92de-b6bb0fb0984d', '204d86fb-d99c-4fd1-8dcd-9c1bcfd3c33f', 39, 'Just for Laughs', 'The friends team up to search for eggs in the Custard Egg Hunt, but they have their hands full looking after Kiki and Finn.', '2001-09-14', NULL, NULL, '2026-04-03T15:26:04Z', '2026-04-03T15:26:04Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('74de2cc9-dfb0-4ed2-9441-c5373b51223e', '3ea743ef-0a22-47cf-b1d2-62f37e939253', 50, 'Oscar''s Road Trip', '', '2002-04-12', NULL, NULL, '2026-04-03T17:36:43Z', '2026-04-03T17:36:43Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('74e4adbc-8369-4b48-a86a-888d21467bda', '5c1b881f-ac58-4d72-b63f-209952d4f902', 31, 'Episode 31', 'Christmas is Coming!  And today you can see the results of the Great Blue Peter Bring and Buy Sale Auction and find out how Blue Peter viewers all over Britain have given help and hope to thousands of suffering Cambodian babies, children and adults.

Join in, too, with carols round the tree with the children of Allfarthings School, Warlingham County Secondary School and the Band of the Chalk Farm branch of the Salvation Army.', '1979-12-24', NULL, NULL, '2026-04-03T17:21:54Z', '2026-04-03T17:21:54Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('74e51578-75b4-45ec-a3d4-d85775d556b1', 'b5ab3a72-bc79-4e9b-a531-96739afd7aea', 10, 'Old Man''s Beard', 'Emily brings in a plant called Old Man''s Beard. The friends try to figure out why it is has this name, and Bagpuss tells the story of a king who used his silvery beard to make carpets. Madeline sings a song about a master weaver.', '1974-04-16', 15, NULL, '2026-04-03T17:23:58Z', '2026-04-03T17:23:58Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('74e8903e-0054-45ac-95dd-f89a65fdd4c1', 'ac068b8e-80f6-46bf-afb2-dcebcf76dc36', 6, 'Between You and Me', 'Skye refuses to let Leon wear his Apache necklace, and Leon gets upset. When the kids hide Nuzzle and Sizzle’s favorite toys, they search everywhere to find them.', '1998-10-28', 29, NULL, '2026-04-03T17:12:21Z', '2026-04-03T17:12:21Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('74e8e3dd-9e03-4b50-b693-899dc0bbd1aa', '4d2cac0f-38fd-438b-8afa-acf43952e535', 23, 'Episode 23', 'A weekly programme for younger viewers.  Including: "The Story of San Marco", a scale model serial.  With Christopher Trace and Leila Williams.', '1959-03-19', NULL, NULL, '2026-04-03T17:21:47Z', '2026-04-03T17:21:47Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('74ea7705-6cc8-4569-b8c6-e91a1a6f4523', '5c4e51c6-e207-46ad-875c-72988eb1e13e', 21, 'Face the Music', 'The Pawn Stars seek counsel when the business card of the infamous Old Western outlaw turned-lawyer John Wesley Hardin moseys into the shop. Will the guys afford the ransom or will this deal meet its end at high noon? Then, Chumlee has a chance to buy a pristine Gibson mandolin. Can he hit a high note with his solo performance or will he be out of tune and get booed? And later, Rick and the Old Man tool around with a 1950''s Shopsmith woodworking machine. Will the seller get crafty and convince them to nail down a deal or will Rick grind negotiations to a halt?', '2011-07-25', 21, NULL, '2026-04-03T16:34:17Z', '2026-04-03T16:34:17Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('750110cc-aeb7-4866-843f-3b4cd678e6b2', '6acfefc0-1904-4f93-9c06-a1a09856150a', 8, 'Garden Fairies / Ice Dance / Stones', '', '2003-03-03', NULL, NULL, '2026-04-03T17:11:23Z', '2026-04-03T17:11:23Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('750ad5d7-c9b7-4264-9b55-ae2d30a12bc8', '38bf8c20-c17c-4071-9226-7887787cf1b1', 20, 'Dreaming Shakespeare', 'It''s Shakespeare Day at the Library.  Fanfares, flowery language and period costumes are the order of the day (Cleo is dressed as the female star of Antony and Cleopatra).  A method actor is unable to play Romeo and Juliet because Juliet is sick.  Maybe an exasperated hen can fill in.', '2001-04-27', 30, NULL, '2026-04-03T17:12:28Z', '2026-04-03T17:12:28Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('750d1629-d711-47c7-85a1-e0d46d8e44b5', 'd199804f-ccf5-4e36-8929-56c1e356b74d', 13, 'Episode 938', '', NULL, NULL, NULL, '2026-04-03T17:36:32Z', '2026-04-03T17:36:32Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('750d8f74-198f-4ea7-9eff-cb87daee667b', 'ffc2a75e-0ffa-4b26-b121-9b91b277594a', 23, 'Reunion (1)', 'The Atlanta ladies reunite to address the dramas of Season 7. NeNe and Kandi clash; Phaedra reflects on her emotional season and stuns the group with a revelation; and Claudia and Porsha face off once again.', '2015-04-26', 43, NULL, '2026-04-03T16:34:47Z', '2026-04-03T16:34:47Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('750e6399-9104-4980-9641-2062ab5db303', '4b2a19e0-2fae-492e-bc31-f78e63d88ebc', 18, 'Pawn Another Day', 'Strike a pose with the Pawn Stars when Madonna''s 1988 day planner vogues into the shop. Will it make Corey a material guy or will he fail to get into the groove? Next, a 1910 phrenology head analyzes its way in. Will it get a good read on Chum or will the deal hit some bumps? Then, an 1800s locket with preacher Henry Ward Beecher closes in. Will Rick give it his blessing or condemn it? And later, a 1980s egg chair used for hearing tests cranks up the volume. Will Corey hear money or think it’s an unsound buy?', '2016-12-26', 21, '/dH7JLRxWio2Il5qJvne8hNzNbUo.jpg', '2026-04-03T16:34:20Z', '2026-04-03T16:34:20Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('75111520-e718-4c93-ad3e-4347476b4c42', '0442fb97-1460-4923-8558-b994078dc6b8', 15, 'Portu-Girl-Bye', 'The ladies head to Madeira, Portugal for some fun and sun, but the distance proves to be too much for Ashley. Karen questions Gizelle''s relationship with Jamal, causing a heated discussion on whether or not Gizelle’s relationship is even real. Things get interesting when Robyn sides with Karen against her fellow green-eyed bandit — causing the two besties to be at odds.', '2020-11-08', 42, '/d7RWmlhR1Ag7iQKAMK3aAAz17SU.jpg', '2026-04-03T16:35:40Z', '2026-04-03T16:35:40Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('751e36ae-ee9f-48e2-8231-a52f58a59983', 'cb8a0322-be77-485b-b339-bdd572bca349', 25, 'Arthur''s Dummy Disaster', 'When George brings his dummy Wally to school, everyone loves him.  But after awhile, they get tired of Wally.', '1998-12-30', 13, '/8XsaIsYkhl4rRcCeGoCzME7e4is.jpg', '2026-04-03T17:37:56Z', '2026-04-03T17:37:56Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('751fdae3-8738-4c3c-a35a-29cd68977736', 'c7ffc8df-4671-47e3-a11b-606828bcb508', 5, 'Shotgun', 'When Jesse goes missing, Walt fears the worst. Skyler has an unlikely reunion. Hank shares some bad news with Detective Tim Roberts.', '2011-08-14', 48, '/cIpk1YHRcySKOET8qUfs2JC3QAy.jpg', '2026-04-03T15:40:34Z', '2026-04-03T15:40:34Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('7524dabb-95c5-4175-8b5e-5ba0f5028cc9', 'c7994637-b7c7-42c7-aaee-1bff4144fe23', 15, 'Ashing It Out', 'Sutton holds a healing ceremony for the group to let go of the past, but a shocking admission stirs up old grudges. The ladies say adios to Spain with a Flamenco dinner where Annemarie asks tough questions. Back in Beverly Hills, Kyle opens up to Dorit about the cracks in her once rock-solid relationship.', '2024-02-07', 44, '/f9S6qhEYCF3zMxzKJETXLxqLET6.jpg', '2026-04-03T16:34:59Z', '2026-04-03T16:34:59Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('7527c067-d9ed-48e8-a541-97fc9160fcc9', 'e9352408-a84b-4c1a-905c-7aa862062f7f', 9, 'Ten Pin Bowling', 'Pat visits a bowling alley in Coventry.', '1995-03-03', 10, NULL, '2026-04-03T17:19:37Z', '2026-04-03T17:19:37Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('75286a6e-3d8f-4b44-8fcb-01110991b7d6', 'd01919fb-98e0-42bf-b9d9-1cecf912f6e1', 53, 'Oscar on Talk Radio (3838)', '', '1999-03-31', NULL, NULL, '2026-04-03T17:36:42Z', '2026-04-03T17:36:42Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('752ba7fc-1e18-4373-8da1-96dd2d0b1181', 'b054aff3-548c-4f56-b372-b1ea26613abb', 5, 'Mister Rogers Talks About FRIENDS', 'Mister Rogers arrives with many empty food containers which uses for pretending. Later, Robert Trow gives a demonstration of pulleys at his workshop. The Neighborhood of Make-Believe tells a separate story with a rainy outcome.', '1982-11-19', 27, NULL, '2026-04-03T17:35:43Z', '2026-04-03T17:35:43Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('752c896e-cb5b-49de-bf89-05df88cf8b1d', 'e1063f87-66c2-4e2d-a913-53362941aa19', 52, 'Episode 327', '', '1972-01-18', NULL, NULL, '2026-04-03T17:36:29Z', '2026-04-03T17:36:29Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('752e5aab-2a32-4e56-8599-8bee05790a07', '0ab4dfb2-58c9-4e52-b5bf-49bba0bfc597', 5, 'Gray Matter', 'Walter and Skyler attend a former colleague''s party. Jesse tries to free himself from the drugs, while Skyler organizes an intervention.', '2008-02-24', 49, '/82G3wZgEvZLKcte6yoZJahUWBtx.jpg', '2026-04-03T15:40:32Z', '2026-04-03T15:40:32Z');
