INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('7575f077-d83f-4965-ad7e-eb569434a6cf', '58adb9ab-3f1b-4a11-87b6-9b0b2dbb6aaf', 28, 'If the Pawn Don''t Fit', 'Take a ride with the Pawn Stars as Rick test-drives the infamous O.J. Bronco. Will Rick pony up the big bucks for this million-dollar item, or will the verdict read no sale? Then, Rick sits down to dinner with a rare silverware set. Will he RSVP a yes to the sale, or lose his appetite after hearing the asking price? Also, in a pawn shop far, far, away ... Can Chum use his Jedi mind tricks to buy a 1978 "Star Wars" comic? Or will he be tempted by the powers of Darth No Sale?', '2017-08-14', 21, '/e82eqFRPxfreNsPDsAIQCPqkARB.jpg', '2026-04-03T16:34:21Z', '2026-04-03T16:34:21Z');
