INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('75fbd99c-0fc9-4974-b814-bc8d0a24b86d', '4da606e7-9d23-4682-8bd5-f535e1da706f', 4, 'Franklin Growing Up Fast', 'Franklin watches an old home movie of his dad. Franklin couldn''t believe his dad was once his size. He sets to do grownup things knowing he''ll be a grownup some day but yet he still wants to be a kid too.', '1998-09-14', 12, NULL, '2026-04-03T17:40:14Z', '2026-04-03T17:40:14Z');
