INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('7620944a-6c02-49f0-a1b9-e7661cb57373', 'de052e8e-7dbd-454a-a6d8-b9afba6e9bfa', 6, 'Peep-Peep-Peep', 'Great Uncle Bulgaria wants the Wombles to keep in touch with each other while they''re working, so Wellington invents, in the words of Orinoco, a "talking tin can"!', '1973-02-13', NULL, '/ctv5LuqUqhnyPDfUFFqMtTZZHDA.jpg', '2026-04-03T17:23:19Z', '2026-04-03T17:23:19Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('7628bbb2-38d8-4fd2-836f-5325f36c7da5', '1d713ca6-4e17-4f84-949c-8cfd98514127', 6, 'Colts and Vikings', 'Go great guns with the Pawn Stars when a Colt Army Model 1860 shoots into the shop. Will Corey hit the bullseye and claim this Civil War revolver, or will he end up off the mark? Then, Rick sets his sights on a Viking coin. Will he end up the conqueror of this ancient change or will he he be forced to retreat? And later, Chum tries using subliminal messages to get Rick to give him a raise, but will Rick even notice?', '2014-07-24', 21, '/9mONXASLddMhvpKTa9lThiRjMF8.jpg', '2026-04-03T16:34:19Z', '2026-04-03T16:34:19Z');
