INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('76b7baba-f4bc-4ec3-bdff-65e12cdaec6c', 'f79f69a8-e591-41d0-9d4a-3d9683defbbb', 3, 'We Cut It Close(ed)', 'Tamra regrets her behavior toward Shannon, and Jenn urges her to apologize and invite Shannon to the closing party; with her twins'' college departure looming, Heather contemplates the next chapter of her life.', '2023-06-21', 44, '/lIZwanedcyJhK5PJiIhbUOVG21B.jpg', '2026-04-03T16:35:35Z', '2026-04-03T16:35:35Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('76bd4d16-5565-4eed-a5b2-bce64f7ee562', 'a6efe883-0113-4477-bf06-57b42a3770ee', 15, 'The Wizard', 'Jerry buys his father an electric organizer; Kramer retires and moves next door to Jerry''s parents in Florida; Susan''s parents catch George in a lie; Elaine can''t tell if she''s part of an interracial couple.', '1998-02-26', 23, '/x8ufcNcNXjLijD1g1YnZPPhLoLr.jpg', '2026-04-03T16:34:12Z', '2026-04-03T16:34:12Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('76c0f77c-7452-4512-9e2b-6bda42a02b6e', '831e3a6b-c1a7-48b7-a5ac-b18ed67beb10', 9, 'Fifty Sense', 'Whether or not her husband, Eddie, shows up for the big party, Charrisse is determined to celebrate her 50th birthday to the tune of $80,000 of his money. The future of Robyn and Juan''s relationship hangs in the balance as they finally get the news about a possible job out of state. Ashley and Karen''s friendship may have reached the point of no return.', '2016-03-27', 42, '/iAiY4uoip4jNK5zq4ifIthXUFGK.jpg', '2026-04-03T16:35:38Z', '2026-04-03T16:35:38Z');
