INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('76d880b3-0180-43e2-bd31-575eec129fd9', '2aebfad4-3145-4bc1-9def-5f1d5bdfcfc8', 11, 'The Alternate Side', 'Jerry gets his car stolen; Kramer gets a line in a Woody Allen film; George gets a job; and Elaine gets tired of her boyfriend.', '1991-12-04', 23, '/p7eW8RnmvkJoA72jfFHqlnfxojv.jpg', '2026-04-03T16:34:10Z', '2026-04-03T16:34:10Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('76e6c109-16bf-44b0-8956-05bfcf0d8105', '63f9bf6d-39b3-44f4-b885-a56807277a80', 8, 'Tales From Muppetland: The Frog Prince', 'Enchanted by an evil witch, a beautiful princess is forced to speak only in nonsense phrases. One day, she finds a small frog who can understand what she says. The frog claims to really be a prince, also enchanted by an evil witch. Together they must try to break their spells.', '1971-05-12', 26, '/dESzpJmkTRpTUijbefAYUS0EcEQ.jpg', '2026-04-03T17:35:23Z', '2026-04-03T17:35:23Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('76e7a0c7-1517-4c3a-af2b-f4224c8081b1', '69b3befe-579a-43ad-a7d6-ec30ffe3adf7', 40, 'Hawaii Day 6 (1095)', 'The gang''s last day in Hawaii.  Image and description courtesy of MuppetWiki and used with permission under the GNU Free Documentation License (GFDL).', '1978-01-20', NULL, NULL, '2026-04-03T17:36:32Z', '2026-04-03T17:36:32Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('76ec7e43-5ad7-4aaf-b3bc-fdf80e61a5e1', 'cc140989-c480-4586-b460-8872b416a0b7', 1, 'Humphrey the Lost Whale: A True Story', 'LeVar is sailing on the Atlantic coast whale watching. He and a team of scientists learn about how whales eat and how they live in their habitats in the ocean. Jane Pauley narrates the true story of Humphrey, the Lost Whale, all about a humpback whale who gets separated from his pod and gets stuck under a bridge over the Sacramento River.', '1989-07-03', 30, NULL, '2026-04-03T17:36:17Z', '2026-04-03T17:36:17Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('76eeac43-bb45-406b-a080-0123bbfbb32d', '6f731e6b-d3c5-4de6-84e1-7a19cb650e86', 15, '90''s Pawn', 'The Pawn Stars have seen some pretty dope stuff from the 1990s and they''re looking back at a few items that are all that and a bag of chips: a jacket from Pulp Fiction, a guitar pedal supposedly used by Kurt Cobain, a juror questionnaire from the O.J. Simpson trial, an early Matt Groening lithograph, a couple of Dennis Rodman jerseys brought in by his ex-wife, some Michael Jackson photos, and a few "Wayne''s World" items that leave Rick feeling not worthy.', '2015-12-06', 21, '/dGkwWwkSqp6Z5N791eJmuKBgsfZ.jpg', '2026-04-03T16:34:20Z', '2026-04-03T16:34:20Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('76f4446b-6908-4d92-a2d5-6e397be002f0', '4d0fd8a5-5200-4dfc-b96c-ae436dc8803c', 6, 'Come a Tide', 'LeVar discusses the weather: how it is traced, tracked, and covered in the media. Kids our shown how they can make a "soda bottle tornado", how a barometer works, and read the book, "Come a Tide". All this is prelude to the dramatic footage of Hurricane Hugo as it wrought havoc on South Carolina in 1989.', '1992-10-12', 30, NULL, '2026-04-03T17:36:18Z', '2026-04-03T17:36:18Z');
