INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('7707d62b-94f6-4c34-976f-2874203adbb9', 'a8db07e5-fba3-49a9-bd12-947c111b39be', 18, 'Body of Evidence', 'The women celebrate Luann''s engagement with mixed feelings and mixed cocktails; Jules struggles with long-distance parenting; tensions between Luann and Ramona boil over, while Sonja''s feelings about Luann''s engagement finally comes to light.', '2016-08-03', 44, NULL, '2026-04-03T16:35:24Z', '2026-04-03T16:35:24Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('77084ad4-ecc2-4d0b-86ea-137a79163f12', '9bd388de-f7fb-4a70-8458-3db458a2abf0', 6, 'Be Yourself', 'Rogers visits a theater to see a juggling act called the Flying Karamazov Brothers. In the Neighborhood of Make-Believe, X is preparing to give flying lessons.', '1997-09-05', NULL, NULL, '2026-04-03T17:35:48Z', '2026-04-03T17:35:48Z');
