INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('771bf67b-d322-4ea0-b887-27583991fc39', 'df77dba2-bbda-4f38-9713-8d5c856f852e', 12, 'Jolly Snow', 'Jolly Tall has never seen snow and he wishes it would snow today. The other toys try to find ways to show him what snow is like. They all have fun making pretend snow out of flour, paper decorations, bubbles and feathers. Bramwell even makes snowflake biscuits. They are so busy enjoying themselves they almost forget to look out of the window. What a surprise they have when they do.', '1993-12-19', 10, NULL, '2026-04-03T17:18:55Z', '2026-04-03T17:18:55Z');
