INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('774dd100-a233-4b42-8bc2-630342dd72fc', '1cafb2c3-bbcb-4172-b02d-441a5aaa155f', 6, 'You and I Together: Installing a Wheelchair Lift', 'Rogers sees people operating a lifting device that elevates a wheelchair into a van. In the Neighborhood of Make-Believe, King Friday commands Mayor Maggie, who had arrived in a wheelchair, to visit Dr. Bill Platypus for a clean bill of health.', '1998-08-21', NULL, NULL, '2026-04-03T17:35:48Z', '2026-04-03T17:35:48Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('774f5883-b575-4088-abd0-57fae41849c7', 'c9adc698-be92-4dd7-94ad-d8f6759361ca', 62, 'Episode 62', 'Rogers tries on leg braces and works crutches before he visits Chrissie Thompson and Mrs. McFeely. In the Neighborhood of Make-Believe, Mr. McFeely helps Donkey Hodie put the finishing touches on his invention.', '1973-05-15', NULL, NULL, '2026-04-03T17:35:40Z', '2026-04-03T17:35:40Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('775249dc-4b5c-41b8-bb34-3fd5d48c0e74', '8610109b-4fb9-4eae-be54-c549fae5ecc8', 3, 'Scooter Computer and Mr. Chips- Number Cruncher', 'The last of the original series were four segments about the then-novel personal computer technology. The shorts featured two characters by the name of Scooter Computer and Mister Chips, and so these were the only episodes in the series to feature any recurring characters.', '1983-11-26', 3, NULL, '2026-04-03T17:13:55Z', '2026-04-03T17:13:55Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('7761c955-0b54-4675-a499-c029f0f0a748', 'c21dbd22-5e2e-4414-bb67-750399aaf6f0', 12, 'Help Wanted', 'The Pawn Stars lock and load as a triple barreled firearm made by famous European gunsmiths blasts its way into the shop. Will the guys hold their fire on this combination rifle and shot gun, or will they pull the trigger and make a deal for the rare weapon? Then, a man drops in with a collection of antique children''s toy piggy banks made of cast iron. A favorite among collectors, will these tot toys cost Rick a pretty penny, or will he save his money for a rainy day? Later, the shop is looking to hire a new broker to help cover the night shift, and Rick puts Corey and Chumlee in charge of recruiting. Will the guys be able to attract some major league talent, or will they get stuck in the minors?', '2012-01-02', 21, NULL, '2026-04-03T16:34:17Z', '2026-04-03T16:34:17Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('7761fe1f-56bf-4d3e-818f-ce3c0c740fab', 'e48599f8-66ff-4c0f-9274-65b9ae1cda9e', 11, 'Episode 11', 'George Stephenson''s ''Locomotion'' thundered along the track between Stockton and Darlington 151 years ago. Today JOHN and PETER go back in time and drive a full-size replica.', '1976-10-18', NULL, NULL, '2026-04-03T17:21:53Z', '2026-04-03T17:21:53Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('7764d6ea-f674-40db-bf69-4650d867f6d8', 'e03d79bd-e01f-4414-b0b3-f3b5f26e97f4', 15, 'Friends, Lies And Videotape', 'Frankie looks for a friend for Brick; Sue sneaks into an R-rated movie against Mike''s wishes; and Axl and his band need a hot female for their music video and try to get stealth footage of their sexy biology teacher.', '2011-07-08', 22, '/5efw5ZVdAVvldp46eF5WuEc28hG.jpg', '2026-04-03T15:40:29Z', '2026-04-03T15:40:29Z');
