INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('77781870-05d5-4ebb-b081-c15641656fd3', 'ffc2a75e-0ffa-4b26-b121-9b91b277594a', 4, 'Bury The Ratchet', 'Todd tells the staff off at the Kandi factory, meaning Kandi has to choose between her husband and staff members. Apollo has come clean, so Kenya hopes to mend fences, but Nene suggests a shocking twist.', '2014-11-30', 43, NULL, '2026-04-03T16:34:47Z', '2026-04-03T16:34:47Z');
