INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('777e1ecd-c0fe-4854-a023-bceae954302a', 'bf0f7445-f58f-467f-a81b-fcc2bf6bca21', 14, 'The Secret of Convincing John', 'Wembley can never make up his mind, until he gets Convincing John to help him.', '1984-04-02', 24, '/w6i1p7TosV8EEYvSSxiCJS4Z17j.jpg', '2026-04-03T17:35:00Z', '2026-04-03T17:35:00Z');
