INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('77a5e596-e4f4-4a54-9be9-da6e10f0e82e', 'a84aa42d-e738-4081-8da9-1faec0209ee9', 16, 'The Bee', 'When Mike discovers that Brick is a spelling whiz and won the school spelling bee, he puts all his efforts into training him to win the regional bee, which could ultimately lead to competing in the Scripps Spelling Bee. But as the family gets set for their road trip to Chicago for the regional bee, Frankie and Mike are horrified when they realize they forgot one thing -- Sue''s birthday.', '2010-03-03', 22, '/85I0QpODYfOZKS63SMHsqRmQYMi.jpg', '2026-04-03T15:40:28Z', '2026-04-03T15:40:28Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('77a61707-0946-4e6a-9d4d-75e5a3ec5445', 'e9352408-a84b-4c1a-905c-7aa862062f7f', 5, 'Gingerbread Man', 'Pat visits Coggans Bakery in Nuneaton to see how gingerbread men are made.', '1995-02-03', 10, NULL, '2026-04-03T17:19:37Z', '2026-04-03T17:19:37Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('77b1c02c-7b2d-41dc-9554-946be985d6d6', '3fc7c152-e4f6-426a-a899-36ec454c4403', 70, 'Whole Lotta Maracas Goin'' On', 'Quetzal''s maracas are broken and the gang decides to make him a new set. Now, they must work as a team to find all the materials they need – which turns out to be a challenging new adventure all its own.', '2000-04-21', NULL, NULL, '2026-04-03T15:26:03Z', '2026-04-03T15:26:03Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('77b287c7-7ac6-43e9-b7c0-bf8c3675a848', '208e80de-61e3-4a2f-857f-c667ffc29134', 4, 'Beverly Sills', 'The pigs are excited that guest star Beverly Sills plans to perform the opera "Pigoletto" as the closing number.', '1979-11-16', 26, '/uptBu0y60jsUPntZbup64qDs7lD.jpg', '2026-04-03T17:35:25Z', '2026-04-03T17:35:25Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('77b46ac3-7729-4f8c-a1a2-e8fbe83f5a02', 'b054aff3-548c-4f56-b372-b1ea26613abb', 8, 'Mister Rogers Talks About GAMES', 'Mister Rogers arrives with a device which plugs into an electrical outlet and turns things on with the clap of the hands. Demonstrating the device with a lamp, Mister Rogers sings You''ve Got To Do It.

Mr. McFeely stops by with a small remote-controlled robot and invites Mister Rogers to join him on a visit to where people make robots.

At the robot factory, Tom Zaken provides a detailed demonstration of how some of his robots work. He then takes Mister Rogers and Mr. McFeely to the assembly area to see how the robots are put together.', '1983-02-09', NULL, NULL, '2026-04-03T17:35:43Z', '2026-04-03T17:35:43Z');
