INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('77c4b487-3154-4b43-8582-ca338b3bdf59', '2e8b61b6-6179-4204-9d2b-c12300836fc8', 5, 'Oakie Doke and the Talking Stone', 'In the middle of the Oakie Hollows Painting Contest, Dave and Denzil, the judges, give a painted stone a monstrous expression, scaring the village children. Doke finds out about this and gives Dave and Denzil such a fright that they won''t want to do it again.', '1997-08-05', 10, NULL, '2026-04-03T17:19:25Z', '2026-04-03T17:19:25Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('77cc3b97-f005-4154-87de-c2a17813ce0c', 'd0b78f22-678e-4e46-9d61-aac40ba206b8', 8, 'Showdown at Villa Rosa', 'Denise and Aaron begin their life together by nesting at home; Dorit deals with the repercussions of the dog fiasco; a monster argument breaks out between Kyle and Lisa Vanderpump culminating in Lisa and Ken demanding that Kyle leave their house.', '2019-04-02', 43, '/86JbrbFb2ewW9Cwavf6ADkbHEho.jpg', '2026-04-03T16:34:57Z', '2026-04-03T16:34:57Z');
