INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('77f02192-de89-4f64-a9cd-b492bdd1efe9', '1be79a20-de33-41d1-af17-079035b18d5c', 97, 'Episode 97', '', '1970-03-24', NULL, NULL, '2026-04-03T17:36:28Z', '2026-04-03T17:36:28Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('77fc9a26-dfe8-44df-bcc6-d5fff675e70b', 'd5383b3d-5636-4d71-b99c-b84774b4b3c6', 9, 'Pingu Gets a Warning', 'Mother is in the kitchen mixing a cake. Pingu walks past carrying his kite, and tells her he’s going out to fly it. Mother pats him on the head, and he goes out. Outside, he pauses briefly to twirl the head round on the snowman, and then continues. Meanwhile, Pingo has been flying his kite nearby outside Pingu’s grouchy neighbor''s igloo, but the kite suddenly crashes to the ground next to some washing on a line. The grouchy neighbor comes out of her igloo in a grouchy way, tells Pingo to go away and takes away his kite. He unhappily goes off and hides behind a nearby block of ice. Pingu goes past, blissfully unaware, and stops by the washing. He tests the wind, decides it’s ok and launches his kite. Pingo rushes back and tells Pingu what happened to him, but Pingu laughs it off and waves Pingo away. Pingo is watching worriedly from nearby when the grouchy neighbor suddenly rushes out from her igloo, brandishing a carpet beater, and tells them to go away in a grouchy way. Pingo runs away. The wind then falters. Pingu’s kite goes into a spin and then crashes on to the washing line, knocking off a towel. Pingu''s idea is dismayed, and the grouchy neighbor gets very, grouchy. She throws the carpet beater to the ground, takes Pingu’s kite and stomps back towards her igloo. Pingo is quivering nearby as Pingu asks the grouchy neighbor to let him have his kite back. She refuses and marches into her igloo, slamming the door behind her. Pingo comes across, and he and Pingu talk about what to do next. The grouchy neighbor opens her igloo window and tells them to go away in a grouchy way. Pingu and Pingo then have a bright idea and go towards the igloo, watched worriedly through the window by the grouchy neighbor, who is wondering what they’re up to. Pingu replaces the fallen towel on the line, and they both then tidy up the mess surrounding the igloo. The grouchy neighbor comes out from her igloo in a grouchy way, causing Pingu to drop a bucket he’s been balancing on his head, and both Pingo and he run off. They stop and ask the grouchy neighbor if they can have their kites back but she says she never is going to give them back, and they trudge away to Pingu’s igloo. When they get there they see a ball lying outside the igloo, and gleefully play with this instead.', '1998-01-17', 5, '/paz4Y5V2MVRPlLTmhfW33DfBodH.jpg', '2026-04-03T17:22:20Z', '2026-04-03T17:22:20Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('78026ff7-e181-4f0d-9c95-e0d31dee1da1', '3b154d00-cb7b-49c4-a053-6ebbbe906eba', 25, 'Curly Bear is born (4055)', '', '2003-05-09', NULL, NULL, '2026-04-03T17:36:43Z', '2026-04-03T17:36:43Z');
