INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('780ecdfc-7626-49ec-a5df-ea302db8b01e', 'ce91a034-5625-4fa6-b81b-db773be5502e', 5, 'RHONY Relics', 'Surfing lessons turn serious when a medic is called to the beach; the ladies compete in a scavenger hunt around the villa; at dinner, swapping proposal stories has the ladies falling out of their seats.', '2023-12-28', 45, '/kOL2XJPuVcjwnv9i9q0GnAZZWoY.jpg', '2026-04-03T16:34:41Z', '2026-04-03T16:34:41Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('78127afe-c649-4d1f-882f-3b73c684c97d', '52f9c16b-a60f-4eb7-b991-5c3bf70877bf', 1, 'Meet the Wives', 'In the first episode of Bravo''s "The Real Housewives of Orange County," Jeana''s son Shane faces the stress of high school graduation and the baseball draft, where he feels pressure to become the third generation Keough to play pro baseball. Shane''s sister Kara is feeling the sting of sibling rivalry and things get ugly when she demands a new car

Meanwhile, Kimberly discusses her breast implants — a gift for her husband''s 40th birthday — and takes her daughter, Bianca, for professional make-up for a junior high dance. She then decides its time to enjoy afternoon cocktails with friends and meets Jo in a chance encounter.

Twenty-something Jo struggles with her new life as the fiancée of a wealthy thirty-something man. Jo and her fiancée, Slade, argue over her desire to continue partying. Jo ventures out and meets Kimberly, her first gated housewife friend.

Vicki spares no expense to celebrate her daughter Briana''s prom and graduation party, but dreads her ex-husband''s arrival for the festivities.

Lauri deals with the aftermath of her divorce and lower status life outside the gates. Things get even more complicated when her adult daughter comes home for a surprise visit.', '2006-03-21', 44, '/vuI2cWBpPEAtiK9LktXH1mEMj3H.jpg', '2026-04-03T16:35:29Z', '2026-04-03T16:35:29Z');
