INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('7876048b-64c5-4efe-87c7-e3d6f0ebd750', '6f731e6b-d3c5-4de6-84e1-7a19cb650e86', 45, 'Hollywood Goods', 'Take a trip to Tinseltown and revisit the coolest Hollywood items ever to appear on Pawn Stars: a letter terminating Marilyn Monroe from her 20th Century Fox contract, a life-size replica of the classic "Creature from the Black Lagoon," the ''51 Chevy convertible driven by Hollywood icon Steve McQueen in his final film, a rare collection of unpublished photos of Paul Newman, a prop shield used in the 1963 masterpiece "Cleopatra" and a whip supposedly from the Indiana Jones film franchise that has Chum snapping to attention.', '2016-07-20', 21, '/Ax6a6Xu2Aqx6MGGrnRKyX5nZkl.jpg', '2026-04-03T16:34:20Z', '2026-04-03T16:34:20Z');
