INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('78bee4f8-fdf3-4879-8184-335fd53bca2a', 'ca19f895-1514-4988-a709-95e84eab7cee', 5, 'Mo'' Monet, Mo'' Problems', 'Chum becomes the chosen one when a seller brings in Buffy figurines. Can he slay the deal before the stakes are raised? Next, an artist''s letter makes quite an impression on Rick. Will Rick show him the Monet? Then, Chum''s got a sweet tooth for an old vending machine. Will his investment be a candy rush, or candy crush? Finally, a 1949 fire truck light races into the shop. Is the price too alarming to make Rick stop, drop and buy?', '2020-12-07', 42, '/cqCbhlFd5K15o1NEw4HTYFaj6NA.jpg', '2026-04-03T16:34:22Z', '2026-04-03T16:34:22Z');
