INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('78d56db6-c35f-4539-87ac-e31417b7e871', '1d713ca6-4e17-4f84-949c-8cfd98514127', 7, 'Mr. Cool', 'Take your best shot with the Pawn Stars when Rick frames up a signed print of Ansel Adams'' famous photograph "Monolith, The Face of Half Dome". Can he successfully capture this rare picture or will he lose his focus? Then, Rick tries to cash in when a 1791 one-cent coin is brought into the shop. Will Rick pay a pretty penny or will he come to his senses? And later, Corey notices that Rick keeps taking his things. Will Corey let it go or will he take back what''s his?', '2014-07-31', 21, '/oFDMXP8x1IusOXvO3B1vHeEwvKQ.jpg', '2026-04-03T16:34:19Z', '2026-04-03T16:34:19Z');
