INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('79b89712-3a67-4714-bdfb-f3013afd3b84', '9e30a416-edbd-490b-bb0f-18d5c45f0bdf', 6, 'Palm Springs Breakers', 'The Wives head out on vacation, but Brandi might have been overserved during the antics and lashes out at Joyce.', '2013-12-09', 42, '/30OyzVaAhPonTTfJZXtNrMznvBm.jpg', '2026-04-03T16:34:55Z', '2026-04-03T16:34:55Z');
