INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('79c09c9f-8970-4f26-9132-fdf4b7aea7fc', 'e6254ae4-7d72-493b-8b37-b677d8b76c46', 60, 'Episode 725', '', '1975-01-24', NULL, NULL, '2026-04-03T17:36:31Z', '2026-04-03T17:36:31Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('79c20634-a691-412d-8c3b-9a8fe9aabf99', 'dd4554c2-6e74-499a-808a-7dad5f2be50f', 10, 'Buried', 'While Skyler''s past catches up with her, Walt covers his tracks. Jesse continues to struggle with his guilt.', '2013-08-18', 48, '/b0aRvTXslQgJpCmmcmoYqS9MsIB.jpg', '2026-04-03T15:40:34Z', '2026-04-03T15:40:34Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('79c21425-0ff6-4b0f-a143-e537f07b2694', '63f9bf6d-39b3-44f4-b885-a56807277a80', 21, 'Studio DC: Almost Live! - The First Show', 'Hosted by Dylan Sprouse, Cole Sprouse, and Miley Cyrus. With songs, dancing, and backstage antics, The Muppets and Disney Channel''s biggest stars team up for another fun variety show.', '2008-10-05', 26, NULL, '2026-04-03T17:35:23Z', '2026-04-03T17:35:23Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('79ca2973-bfd6-40a5-a460-ac6a3d5c3b03', '36ea3814-66b4-4986-b6ee-44559d3562c1', 9, 'Midnight in the Garden of Tea and Shade', 'Cynthia and NeNe disagree over certain parenting skills. Cynthia reveals that she is worried about Noelle. Porsha and Kenya bond over both wanting children. Porsha receives some wisdom from NeNe. Kenya attempts to make peace with Phaedra', '2013-12-29', 43, NULL, '2026-04-03T16:34:46Z', '2026-04-03T16:34:46Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('79cd64ac-90d6-4d22-a57c-daab6d1ccc2b', '6f731e6b-d3c5-4de6-84e1-7a19cb650e86', 18, 'The Pawn Before Christmas', 'Go dashing through the snow with the Pawn Stars when an 1800s one-horse-open sleigh rides in. Will Rick and Corey jingle out an offer or will they get snowed in? Next, a J.H. Rector rifle aims for a deal. Will Rick take a shot or will the numbers be off target? Then, things get jolly when unpublished Christmas art from Mad magazine comes down the chimney. Will Corey say "ho ho ho" for a sale or will he be a scrooge? And later, a Christmas tin from WWI unwraps itself. Will Rick be singing carols or will he shout "bah humbug"?', '2015-12-17', 21, '/bTjcSthnkvnvijnkBLtA0DDtEIi.jpg', '2026-04-03T16:34:20Z', '2026-04-03T16:34:20Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('79d8c80c-494a-49e1-a3e2-2b55a01d6f10', 'fd0f7dfb-28aa-4687-9ef8-8ff0088ce25a', 18, 'The Princess Story', 'Abby and Zoe ask Leela to help them write a princess story; imagination.', '2014-01-16', 58, '/3vxulXZ6XvDJK2yIMaxc2eM15ha.jpg', '2026-04-03T17:36:47Z', '2026-04-03T17:36:47Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('79d9236f-f02d-41ee-b07e-d33b21e9d819', 'd3e13496-e3c8-4903-83b4-5a31fedee232', 16, 'The Deserter', 'Aang and his friends go to a Fire Nation town so that Aang can witness some firebending, but their plan soon goes awry when it’s discovered that he is the Avatar. Fortunately, he''s rescued by an individual who serves a firebending master named Jeong Jeong who has abandoned the Fire Nation, so Aang decides to use this time to attempt to learn firebending. The firebending master, however, seems reluctant to teach Aang.', '2005-10-21', 25, '/rgdsLIpTCHPrq1DvOXtHh65qEp2.jpg', '2026-04-03T17:40:47Z', '2026-04-03T17:40:47Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('79dbcba6-528c-478f-8861-87fb8881a88b', '02849655-bd95-4d8d-af3b-03321918eeee', 14, 'Madeline and the Marionettes', 'Madeline and the girls help to reform an unhappy puppeteer in the Jardin de Luxembourg, who, because he never had the talent to be an opera singer, puts on marionette shows that twist the plots of classic fairy tales and disappoint children in the audience.', '2000-12-08', 30, NULL, '2026-04-03T16:34:02Z', '2026-04-03T16:34:02Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('79dd0452-f5db-4315-8c39-c82e7de26f73', 'df77dba2-bbda-4f38-9713-8d5c856f852e', 4, 'Jolly Tall', 'A mysterious box arrives in the playroom. After approaching it cautiously the toys discover it contains a new friend; Jolly Tall the giraffe. With Jolly still inside, everyone sets to work to turn his box into a cosy house for him. There is a problem though; Jolly is too tall to get out of the door! Using a toy crane, the friends finally manage to rescue Jolly and Jolly, in return, performs a rescue of his own. In the end the toys find that something Bramwell has been knitting all week turns out to be the perfect present for their new playmate.', '1993-10-24', 10, NULL, '2026-04-03T17:18:55Z', '2026-04-03T17:18:55Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('79e19b02-aa01-49ce-b5c5-a75c515b4dcf', 'da06465b-9154-4feb-a455-374df7dab02f', 6, 'How many balloons to raise Snuffy? (4088)', 'Snuffy wants to be a cloud in the sky.  He wonders how he is going to get up there, and then realizes that he could use a balloon to lift him up.  He wishes for a balloon and the Fairy Balloon Person (Richard Kind) comes to grant his wish.  Since it’s going to take more than one balloon to lift him up, the Fairy Balloon Person keeps adding 5 more balloons each time until they reach 40 balloons.  He starts to fly up to the sky going higher and higher.  While Snuffy is happy to be seeing birds and other clouds, he starts to get cold and lonely being all by himself.  Snuffy wishes to go back down, and his wish is granted.  He realizes that everyone he loves is down on Sesame Street and that he would rather be a snuffleupagus than a cloud any day.', '2005-04-11', NULL, NULL, '2026-04-03T17:36:44Z', '2026-04-03T17:36:44Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('79e43b6c-d955-4c59-991f-7fc14ebb46a8', 'e2aa3158-68e5-494f-951a-498ca0518dbb', 6, 'The Crow', 'A crow in the barn prevents Shaun and the flock from sleeping.', '2012-12-01', 7, '/6nzcS6TOpTjYn9iJfUmQPfTAzzq.jpg', '2026-04-03T17:39:32Z', '2026-04-03T17:39:32Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('79e68ba6-18a2-4225-88fd-18c287b09bd9', 'bb919aec-0d5c-4c58-9a5a-fa2a0a5de2b6', 88, 'Episode 493', '', '1973-03-28', NULL, NULL, '2026-04-03T17:36:30Z', '2026-04-03T17:36:30Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('79e897c5-5d03-4ed7-8a83-7760c03b87a0', 'bbfee3b4-9c95-48a6-beaa-791fa08b1f43', 50, 'Episode 50', '', '1984-03-05', NULL, NULL, '2026-04-03T17:21:56Z', '2026-04-03T17:21:56Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('79e9a21a-54d6-463b-8222-55e67538d942', 'bcab920a-51a5-4cbb-aa59-41578a0eb005', 16, 'Big Buddha Brawl', 'Tensions between Dorit and Erika continue to rock the boat in Hong Kong. Lisa Rinna and Eileen pick a side while Lisa Vanderpump and Kyle watch in shock. Will visiting the second largest Buddha in the world cure the madness or just serve as an intermission? That question is answered at an even more shocking dinner.', '2017-03-21', 43, '/kiik51TgQeXXCGMf9N92CnXyIdy.jpg', '2026-04-03T16:34:56Z', '2026-04-03T16:34:56Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('79e9dffa-2244-43e1-a85d-7a4c98f403ec', '98453a19-e5ae-465a-8505-9129bda66a86', 3, 'Pickle Rick', 'It''s family therapy time in this one broh. Classic stuff. Pickle Rick too.', '2017-08-06', 24, '/lzNb4JsebI3JXQ6k73rWddrKkuV.jpg', '2026-04-03T15:40:42Z', '2026-04-03T15:40:42Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('79ea41b0-9582-4b2b-9857-04331403f15e', 'a3a2c2fb-8276-412c-9d86-5175167be1d7', 66, 'Episode 66', 'with Valerie Singleton, John Noakes, Peter Purves', '1972-05-01', NULL, NULL, '2026-04-03T17:21:51Z', '2026-04-03T17:21:51Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('79ec5af8-24bb-4d07-b9a2-0a19c2fec5ee', '98d80972-e53a-43dd-a03a-7703465e6f87', 16, 'Santa Chum', 'Gather ''round the tree with the Pawn Stars as the guys get ready for their annual Christmas Party. With Chumlee in charge of the planning, can he keep it under budget and earn his Christmas bonus? Then, Rick and Corey check out a collection of military promotion documents signed by six different U.S. Presidents. Covering a single soldier s rise through the ranks starting in the Civil War, will this collection have the guys eager to enlist in negotiations? And later, Corey is offered an Italian movie poster for "Bullitt" starring Steve McQueen. Knowing Rick s love of everything McQueen, will Corey race at the chance to buy the poster, or will the deal crash and burn?', '2012-12-17', 21, NULL, '2026-04-03T16:34:18Z', '2026-04-03T16:34:18Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('79ee1049-fc89-4676-8c60-56fdcf7fb1c6', '7c422193-b078-49d8-81ef-f2b9f94f059d', 33, 'Chicago feels sad; Pineapple dentist', 'Episode #3038', '1992-12-23', 55, NULL, '2026-04-03T17:36:39Z', '2026-04-03T17:36:39Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('79ef68c0-5b71-43e5-bff6-cfdc67357b1d', 'a2edcb57-63c1-4028-b87b-7faeae2c999b', 1, 'Own Goal', 'It''s football time at Pentup Primary School and Bernard and his team mates are against the girls, will they win or will they lose?', '2004-01-06', 15, NULL, '2026-04-03T17:20:06Z', '2026-04-03T17:20:06Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('79efaaf5-8bb3-418a-9986-dfdea973fcad', 'd405f973-4c7e-4cb6-b7c0-d09a884c9b35', 7, 'Travel Reservations', 'LuAnn plans a big exotic trip for the ladies, hoping the getaway will help quell all the petty clashing. Some of the ladies prepare for the vacation by checking in at a spa, while others save face by visiting a plastic surgeon. Elsewhere, Jill hosts an anti-bullying event---even inviting Ramona to the affair.', '2011-05-19', 43, '/f1Ie1FFJU8MXs0DLx2UDcWdiube.jpg', '2026-04-03T16:35:22Z', '2026-04-03T16:35:22Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('79f34ac6-2ebd-4fca-93f1-9d902b2ea8d6', '6ef86c27-33e7-47e5-a053-483059dfd16d', 45, 'Episode 45', '', '1982-02-18', NULL, NULL, '2026-04-03T17:21:55Z', '2026-04-03T17:21:55Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('79f48cbc-d184-4811-bb5d-dd0adbee49fd', '02849455-d14b-476b-9603-eef5fb5d2ab3', 7, 'Blue Skies and Blue Eyes', 'The ladies continue their weekend escape in the woods, but it''s not quite as relaxing as Ashley had hoped. After a few glasses of champagne, Karen starts hurling insults at Robyn, leaving all the ladies confused. Tensions come to a halt for an afternoon of fishing, but things escalate once again when allegations swirl over Monique''s denials and Karen''s possible secrets.', '2018-05-13', 42, '/y1fH1m0o1sDjCEyy2oeF37ZrP3X.jpg', '2026-04-03T16:35:39Z', '2026-04-03T16:35:39Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('79f608b7-0b36-4c03-90a2-87d877c80597', 'bf0f7445-f58f-467f-a81b-fcc2bf6bca21', 8, 'All Work and All Play', 'Cotterpin Doozer doesn''t want to get her helmet and become a full-fledged Doozer worker. She wants to be a Fraggle!', '1984-02-20', 24, '/2W3ROsrPzLVyjALHWsbJtiABLor.jpg', '2026-04-03T17:35:00Z', '2026-04-03T17:35:00Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('79fa80de-78ca-447b-811d-022df519056c', '02849655-bd95-4d8d-af3b-03321918eeee', 2, 'Madeline and the Spider Lady', 'The girls'' pretend radio show accidentally gets broadcasted to the entire city.', '2000-09-15', 30, NULL, '2026-04-03T16:34:02Z', '2026-04-03T16:34:02Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('79fb62b1-4c13-4537-a50b-9adc8f2f53c4', 'a0fa5075-9ce1-48c1-9995-0c0fd866e549', 3, 'Life''s a Beach', 'Calling all beach babes! Kathy’s Oceanside, Calif., getaway promises to be a luxurious escape, but it’s far from smooth sailing. PK’s sudden silence causes Dorit to open up to Bozoma, but Garcelle and Sutton are left questioning this new friendship. Fun beach games bring the laughs, but the tension between Kyle and Dorit spills over at dinner, leaving everyone with a bad taste in their mouth', '2024-12-03', 43, '/uSfZpjz2XzR3aS9xUUwqF3Blly6.jpg', '2026-04-03T16:34:59Z', '2026-04-03T16:34:59Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('79fc6680-f1b6-469c-8e7e-8313fb79a37b', '17e6cc8e-dcf3-4ce6-97db-5a9fc8e31eb5', 15, 'Chapter 3: Rebirth', 'Grenada has bought the peaches closer, yet some can''t help but notice that something ain''t clean in the water; Kelli connects with her divorce lawyer and prepares for the worst; the women attend the Jab Jab, a memory they will never forget.', '2025-06-15', 42, '/tB1L18afebcuvLMWMXil3F9M8d.jpg', '2026-04-03T16:34:50Z', '2026-04-03T16:34:50Z');
