INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('7a0cae64-afa9-492e-9385-6f78f214418d', 'd306a064-e835-417e-8548-0cf806295f31', 8, 'Sing and Shout', 'Adriana films a music video for her new single, "Fyah," on a yacht; Alexia and Guerdy rock the boat when they come to final blows; Julia hosts a housewarming party; Larsa confronts Julia about kissing a man.', '2023-01-05', 44, '/rZlkMs3GFQnUTKMtpS4skf0af4w.jpg', '2026-04-03T16:35:11Z', '2026-04-03T16:35:11Z');
