INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('7a13738b-cc69-4cb8-ac2c-20a0e823bbb7', 'abeb8d07-5c86-4f6a-a110-b11cba2a4138', 19, 'Sozin''s Comet: The Old Masters (2)', 'While on the island, Aang seeks guidance from his past lives, but is not pleased with what he is told. The island, in fact, turns out to be a lion turtle from which Aang is given the guidance he had been seeking. Meanwhile, after the tracker is unable to track Aang, the rest of the group decide they must find Iroh. While tracking him down, the group meets up with The Order of the White Lotus, a group that transcends the division of the four nations.', '2008-07-19', 23, '/51ceqvaljO0hqBjdDtmUzliHwVp.jpg', '2026-04-03T17:40:48Z', '2026-04-03T17:40:48Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('7a177851-e0c7-4a1d-8192-d32ff737b1f8', '3190d082-877d-4951-bf7c-ed07ef560040', 7, 'Duncan and Dolores', 'There''s more to the cat than meets the eye. It culminates with one of the stars of what was then believed to be Broadway''s permanence: CATS. Jane Curtain narrates the featured book about a girl who wants a cat. In the story, Duncan and Dolores learn how to be themselves and earn each other''s friendship.', '1988-08-28', 30, NULL, '2026-04-03T17:36:16Z', '2026-04-03T17:36:16Z');
