INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('7a221247-2189-42cf-99ec-009a71ad7730', '3fdccc2c-e563-42fb-8874-c93879cd4141', 12, 'A Prickly Problem', 'Timmy decides to helps the hedghogs find a resting place for the night. His efforts, however, lead his weary friends into a series a scrapes rather than giving them a good night''s sleep.', '2016-11-08', NULL, '/xFjjsWlmHDX4VqLTN7Qh7XyPyFH.jpg', '2026-04-03T17:39:32Z', '2026-04-03T17:39:32Z');
