INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('7a33c8d7-7e9f-4a31-b480-4fede7044f1d', '5c4e51c6-e207-46ad-875c-72988eb1e13e', 6, 'Take a Seat', 'Take a seat with the Pawn Stars as a chair from the U.S. Senate floor rolls through their doors. Will a motion to buy this chair result in a resounding "Yay" or will the Old Man veto the deal? Then, Corey and Chumlee have their heads in the clouds when a guy brings in a signed photo of NASA''s Gemini launch. With over a dozen astronautical autographs, will the guys take one giant leap to buy this piece of space history or will they forced to abort the mission? And later, a man races into the shop with a NASCAR driver''s suit that once belonged to Ryan "The Rocket Man" Newman. Will the guys set a new lap record to make a deal or will negotiations crash before reaching the finish line?', '2011-04-18', 21, NULL, '2026-04-03T16:34:16Z', '2026-04-03T16:34:16Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('7a429d23-decf-4de3-9e2c-40ae0d939743', '913f846d-85df-4694-8dd4-0d5909f78887', 13, 'Compassion (2)', 'After she wakes up she learns the true meaning of the Christmas spirit.', '2000-12-17', 30, NULL, '2026-04-03T17:38:35Z', '2026-04-03T17:38:35Z');
