INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('7ae78def-b773-4dc5-b90d-29076c56bd94', '9c9d89df-5f6b-41d0-84c6-b8ca7bd2a2e6', 3, 'Lunchtime Engineers', 'When Chris sprains his ankle, Zoe, Gabrielle, and Rosita use a rope and pulley to bring him his lunch, but the rope slips off the lunch bag. What if they put the lunch bag in a basket and tie the rope to the basket handle? Let’s try!', '2021-11-25', NULL, '/hCaVmv5rrUzXvkw0NM2oUqZcz46.jpg', '2026-04-03T17:36:50Z', '2026-04-03T17:36:50Z');
