INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('7aea3dca-1bad-442e-bccf-a893a56d7c31', '4b2a19e0-2fae-492e-bc31-f78e63d88ebc', 26, 'Cutting Edge Pawn', 'Drink and be merry with the Pawn Stars when a Pre-Revolutionary American pewter tankard clanks into the shop. Will Rick cheers to an offer or will he put a lid on the deal? Next, original postcards by Jean-Michel Basquiat paint their way in. Will Rick tag them as legendary art or will he vandalize the sale? Then, Corey hits the road to check out a 1960''s Hydro-Cycle Barracuda watercraft. Will he splash up a deal or will the boat be a bust? And later, an early 1900''s blueprint copy machine engineers interest from Rick. Will he submit plans for an offer or will the foundation collapse?', '2017-01-23', 21, '/1bSpCO7LVGhXBT9e22UPFpx4TKS.jpg', '2026-04-03T16:34:20Z', '2026-04-03T16:34:20Z');
