INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('7b4e6b4d-5e79-462f-9f04-1e55a7da6c84', 'e03d79bd-e01f-4414-b0b3-f3b5f26e97f4', 3, 'The Diaper Incident', 'While shopping for baby diapers for Sue, who has run out of them on a baby-sitting job, Frankie is completely humiliated when a clerk assumes she''s shopping for adult diapers. Meanwhile, after getting on Mike''s case to get a physical exam because she thinks men tend to fall apart faster than women as they age, Frankie proceeds to throw out her back and hides it from Mike, who tells her he received a clean bill of health from the doctor; a clueless Sue falls for Axl''s friend, Sean, who barely notices her existence; and Brick begins to test all of the age-old urban legends parents tell their kids - such as not to swallow a watermelon seed for fear one will grow in their belly - after discovering Frankie has used these white lies on him in the past.', '2010-10-06', 22, '/1zusev8YZq4unD86ZPiR3lNzSlw.jpg', '2026-04-03T15:40:29Z', '2026-04-03T15:40:29Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('7b5173f9-6c56-4903-a26c-664ad6f6d470', 'cc140989-c480-4586-b460-8872b416a0b7', 8, 'Tooth-Gnasher Superflash', 'LeVar, the jack of all trades, becomes a garage mechanic for this episode. Much of it fantasizes about dream cars. Then comes a real dream car, which a man has decorated, followed by stock footage of an assembly line and a piece on a solar-powered car named the Sunraycer. Victoria Jackson narrates Tooth-Gnasher Superflash, the story of a family that buys a car that is not like any other.', '1990-03-28', 30, NULL, '2026-04-03T17:36:17Z', '2026-04-03T17:36:17Z');
