INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('7b920ca7-d93d-4c82-900d-030269033c56', 'a2edcb57-63c1-4028-b87b-7faeae2c999b', 12, 'Late Again', 'Bernard is on the verge of being expelled, with help he makes it on time but not if Nicolette has anything to say about it.', '2004-03-23', 15, NULL, '2026-04-03T17:20:06Z', '2026-04-03T17:20:06Z');
