INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('7bdeae34-efd1-4207-8b60-1313825aa7ae', 'a8f3a681-7abc-41e0-9988-9b8804d74611', 16, 'Mourning the Loss', 'Tensions rise as the Sister Wives fight for the bonus features they want for each house. Who stays in budget and who goes way over? Later, the Brown family digs deep when the family pet is ailing. A compromise leaves them all in tears.', '2012-12-16', NULL, NULL, '2026-04-03T16:34:28Z', '2026-04-03T16:34:28Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('7be5f8d3-ef21-4729-8dc8-e9849a845462', '7c542833-ed0a-4272-9c53-e822408ab434', 16, 'Sketching the Wildlife', 'On a wildlife sketching trip, Norman wants to find the most spectacular creature to sketch, but this gets a bit tricky when Lily Chen tags along.', '2024-11-04', NULL, '/3N72fN7VA50CQtFQ7nwleXB0GOc.jpg', '2026-04-03T17:14:42Z', '2026-04-03T17:14:42Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('7be61ca0-2b8e-4788-b972-34ecfe1a4809', '98d80972-e53a-43dd-a03a-7703465e6f87', 4, 'Stick To Your Guns', 'Pledge allegiance to the Pawn Stars when the guys check out a flag cut straight from a WWI fighter plane. Flown in the same famous squadron as Teddy Roosevelt s son Quentin, will the guys engage in a dogfight for these stars and stripes or will this deal cry mayday? Then, Rick checks out a gun that belonged to Old West lawman Fred Coates. Used to fend off cattle thieves during the Wyoming Range Wars, will Rick be quick to draw his cash, or will this deal be put out to pasture? And later, when Chumlee gets caught faking his timecard, Corey has to fix the problem. Will he find a way to beat the clock?', '2012-11-12', 21, NULL, '2026-04-03T16:34:18Z', '2026-04-03T16:34:18Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('7be8e948-aaa0-4d85-837e-1e54d60a7dcb', 'e1063f87-66c2-4e2d-a913-53362941aa19', 61, 'Episode 336', '', '1972-01-31', NULL, NULL, '2026-04-03T17:36:29Z', '2026-04-03T17:36:29Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('7be9e265-1fc2-4eda-a33e-7194d70ff7fe', '4c79c0b6-21a4-4277-8967-be1e791efdbe', 18, 'Pingu Boogaloo', 'Pingu is playing indoors when Mother comes by, turns on the radio, sits down and starts knitting. Pingu stops playing, and starts dancing to the swing music that is playing on the radio. The phone rings, and Mother turns off the radio and answers it. Pingu gets ready to turn the radio on again but is annoyed when he sees that Mother is clearly in for a long chat as she’s now got her knitting and is still on the phone. He has an idea, and gets the headphones from the cupboard. He plugs them into the radio, turns it on and starts to dance again. Father then comes in and consults the paper. He takes out the headphones and switches stations on the radio to listen to the world cup final, ignoring Pingu’s protests. Pingu goes outside and past the ice rink where, amongst various activities(including the hockey match father was listening to), a penguin is playing music on a special record player on runners that he’s pushing round the rink. Unfortunately, as it come past him Pingu can hear the music and can dance, but he can’t hear it when it’s the other side of the rink so he has to stop dancing. Pingu leaves the rink and goes past an igloo from which music is coming, so he knocks on the door. A penguin, singing opera, bursts out and Pingu hurries away. Then he comes across Pingo listening to the radio on headphones outside his igloo. Pingo lets Pingu share the headphones so they can both listen, but it’s not long before they have a tug-of-war that ends up with broken headphones. Pingu goes home, gets his headphones and gives them to Pingo, and goes back indoors. Mother is playing with Pinga, so Pingu sits down dejectedly on the sofa. Realising what is wrong Mother has a quiet word with Father, who gets out a record and starts playing swing on the record player. Pingu immediately cheers up and starts dancing. Pinga, and Mother and Father, soon join in.', '2006-02-21', 5, '/ifXFAhQV8qnOD1Dhh29u9rmuMB8.jpg', '2026-04-03T17:22:21Z', '2026-04-03T17:22:21Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('7bebd013-c81b-480d-880d-d54292dbcf84', 'd1d267dd-e27f-4543-acb8-0d28f676512a', 17, 'Episode 17', 'with Valerie Singleton and John Noakes', '1967-11-23', NULL, NULL, '2026-04-03T17:21:49Z', '2026-04-03T17:21:49Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('7bfb1b51-6a51-43ab-8608-295dd889a3ef', '5ba20443-d99f-4820-81f6-6832d3f2bc4f', 17, 'Inventions', 'Almost everything around you, from paper clips to computers, was thought of, designed, and built by humans. An invention can be a totally new idea, or an improved variation on something that already exists. Inventors invent to solve problems and make life easier. Anyone can be an inventor, even you. All you need is an idea, and sometimes you don’t even need that. Silly Putty, sticky notes, X-rays, pretzels and nylon were all accidents that became great inventions after more research, experimentation, and design.', '1996-02-21', 26, '/algp01d3p3O7sO9q9qf1nD7XCf.jpg', '2026-04-03T17:37:21Z', '2026-04-03T17:37:21Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('7c1095d9-0f61-4b43-81a9-487df1d1f30f', '7acb58c5-320f-419d-a96f-26ad3cfe2e82', 6, 'Everybody Has a Plan ''til They Get Punched in the Face', 'Betrayal and bloodshed rock the conclave when the hunt for Ciri comes to a head. As sides are chosen and enemies unmasked, nothing will ever be the same.', '2023-07-27', 49, '/jPc4g8j7zv70FQXbMEMsFaGyeLX.jpg', '2026-04-03T15:40:45Z', '2026-04-03T15:40:45Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('7c171620-9dc8-430a-b6f7-6f1be4c83897', 'e2aa3158-68e5-494f-951a-498ca0518dbb', 13, 'Fossils', 'Shaun and the Flock help Bitzer discover hidden treasure.', '2012-12-04', 7, '/uRsase9OvqQ2J43pnTXSHgQ91jz.jpg', '2026-04-03T17:39:32Z', '2026-04-03T17:39:32Z');
