INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('7c20fb35-2792-4899-b2cd-f4e29cd18e0c', '3ee646e8-23ae-4dec-bbc6-c7e6a210d55b', 97, 'Telly and the balloon', 'Monster on the Spot reporter Telly interviews twins Shawnee and Chai about how they are the same and different. He finds that they look the same and both wear their hair in pigtails, but the girls rattle off a seemingly endless list of the ways they''re different. Telly is holding onto Uncle Wally''s balloon, which Big Bird was doing before until he went to play catch with Miles.

