INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('7c260c86-c5a6-486b-adfc-ebbfba300c51', 'f12380a9-93e5-47bb-9e2f-cf1eed11eee4', 7, 'You''re Like a Stripper, I''m Like the Pole', 'Meri digs through boxes of her wedding memorabilia that bring up painful memories. Christine and David have their biggest disagreement yet. Kody and Robyn try to improve their rhythm with a dance lesson, and Janelle helps Maddie prepare for labor.', '2025-11-09', NULL, '/r9aGRlG0oO8K97RyK8DaUMhETRh.jpg', '2026-04-03T16:34:33Z', '2026-04-03T16:34:33Z');
