INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('7c2e761f-3205-4b0d-a815-40e6f08ecd67', '51f03551-ba41-409d-85f4-e51bddfdf82e', 10, 'Unfashionably Late', 'A sultry photo shoot involves Kelly, who goes before the cameras to pose for the photo invitation to her Halloween bash, which the other wives ultimately attend. Meanwhile, a shopping spree results when LuAnn''s daughter arrives from boarding school. And Jill, in a radio interview, chats about the suffering American economy and its impact on the rich.', '2009-04-21', 60, '/dlYQiVziSQzTLTR3QL2KpXAjDlY.jpg', '2026-04-03T16:35:22Z', '2026-04-03T16:35:22Z');
