INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('7c3fd029-de52-4645-a300-6b44d5be05ef', 'e2aa3158-68e5-494f-951a-498ca0518dbb', 17, 'Prickly Heat', 'It''s a scorching hot day on the farm and the Flock need to cool off. When Bitzer discovers the Sheep Dip is out of action the Flock have to come up with another plan. Meanwhile, the Farmer has his own ideas for cooling off, which don''t impress Bitzer at all.', '2012-12-07', 7, '/34hvDzRMgUSpA0HMVG11ueUW9Up.jpg', '2026-04-03T17:39:32Z', '2026-04-03T17:39:32Z');
