INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('7c45cd19-3e6e-4063-82f1-9fb0e84c73fb', '8c0f12e1-5379-4a27-aca2-b69401a33b0f', 34, 'Arthur the Loser', '', '1998-04-14', 13, NULL, '2026-04-03T17:37:55Z', '2026-04-03T17:37:55Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('7c465e70-842a-4aee-9252-4661c9b4c5ae', '05c0e384-194c-4417-9f62-803eb615e409', 42, 'Airplanes', 'Title number 0042. Opens with Mister Rogers arriving with a book about paper airplanes and sits on the porch to sing. Lady Aberlin gives X the scarf that she had promised for him after she visits with Daniel Striped Tiger and they sing "I Like You As You Are". In turn, X gives her a walnut, and she takes it to the new trading tower that Grand-père has established.', '1968-04-16', 29, NULL, '2026-04-03T17:35:38Z', '2026-04-03T17:35:38Z');
