INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('7ce31e88-a61a-4017-80ee-ac0c78db3089', '1cfdff3a-d531-4a9e-afc9-8010a979dd27', 1, 'Prince Caspian (1)', 'Troubled times have returned to the magical land of Narnia. Prince Caspian vows to free the persecuted animals and dwarfs and calls for help to save his kingdom.', '1989-11-19', 30, '/q8X7dRFYB8OCDFcoVmiu1X55Yl4.jpg', '2026-04-03T17:17:41Z', '2026-04-03T17:17:41Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('7cf02228-7204-41b0-83c0-c9620418bcf3', '8b07363e-5f54-45d6-b036-b43793f7af74', 11, 'Jenna''s Bedtime Blues', 'An invitation to Muffy''s exclusive slumber party terrifies Jenna, an occasional bed-wetter.', '2002-11-25', 13, NULL, '2026-04-03T17:37:57Z', '2026-04-03T17:37:57Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('7cf035f7-0961-4685-905d-1b33a65a1baf', 'efdf1e4f-8476-4382-a9d7-2b9da4188be0', 5, 'Mad Feelings', 'Rogers attends the rehearsals for Stomp. The Neighborhood of Make-Believe comforts a harried Lady Elaine, who rights the Eiffel Tower and learns that Mr. McFeely was not turned into a doll after all. And Then Maggie Stewart Picks Up The Mr McFeely Doll And Shows A Videotape Of Maggie Stewart and Chuck Aber Riding On The Racer At Kennywood', '1996-08-16', 30, NULL, '2026-04-03T17:35:47Z', '2026-04-03T17:35:47Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('7cf890d6-fccc-4411-ba58-a23ac61f1631', '4060ad7f-4b8f-4393-8eb1-66a150b928b6', 13, 'Elmo and the Healthy Heroes', 'The healthy Super Food Super Heroes help Elmo and his friends find and try new, colorful healthy snacks and learn that breakfast is the most important meal, giving them the energy they need for the day.', '2021-02-04', 26, '/fFhZlyZd8HMh9vuF2alb0PAKGFP.jpg', '2026-04-03T17:36:50Z', '2026-04-03T17:36:50Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('7cf8ea1c-abf5-4f8a-94d0-929a3fc98bee', 'bbfee3b4-9c95-48a6-beaa-791fa08b1f43', 29, 'Episode 29', 'Lift-off for Simon: Today''s the great day for 14-year-old Simon Holtom, the winner of Blue Peter''s Intelpost Greetings Card Competition. His glorious view of balloons over the London skyline has been turned into a greetings card and will be seen in public for the first time.', '1983-12-19', NULL, NULL, '2026-04-03T17:21:56Z', '2026-04-03T17:21:56Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('7cf97961-c3da-4bdd-88a6-048ac66c63e6', 'a6ed03e0-c05f-48f8-9f56-3f1da50e1792', 91, 'Episode 1406', '', '1980-03-31', NULL, NULL, '2026-04-03T17:36:33Z', '2026-04-03T17:36:33Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('7cfc57d6-8cc9-40ad-b251-cd117842eb21', '6ef86c27-33e7-47e5-a053-483059dfd16d', 35, 'Episode 35', '''Aunt Jane was the delight of all her nephews and nieces - but, as Sarah discovers, Aunt Jane had a secret!', '1982-01-14', NULL, NULL, '2026-04-03T17:21:55Z', '2026-04-03T17:21:55Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('7cfcc6a9-67bb-4860-8ddd-0bcd281e7a8c', '495d4222-b33a-46fa-8351-3265798e558b', 8, 'Wunderpants', 'Pete becomes blessed with magic powers after he uses a microwave to dry his undies. Unfortunately, a frog race and a shrinkage problem leave Pete all alone and a bit undressed...', '1990-05-25', 24, '/srVG0gNv0kDTbcord05vpWUL3lS.jpg', '2026-04-03T17:40:40Z', '2026-04-03T17:40:40Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('7cfefce9-899b-4ab7-8e9a-40ba4d6876f8', '02849455-d14b-476b-9603-eef5fb5d2ab3', 4, 'First Ladies and Second Chances', 'Ready to close the chapter on her days of being the "First Lady" of the Black Church, Gizelle decides to write a controversial book loosely based on her life. Monique and Robyn try to get to the root of their issues, while Candiace hopes to step out from her mother''s shadow. Ashley seeks the advice of a therapist to help solve her marital problems and as a result, tries to make the impossible choice between her husband and her mother.', '2018-04-22', 42, '/479ZSidZkqwcEzRrjqMCO5c1AmC.jpg', '2026-04-03T16:35:39Z', '2026-04-03T16:35:39Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('7d030bd8-6c5c-4a59-b961-25c9cd069b40', '34674c90-410e-427c-be4d-2a6f6f865a80', 25, 'Some Like It Not', 'Take the Pawn Stars hostage, when a $20 bill from infamous hijacker "DB Cooper" skydives into the shop. The only unsolved airplane hijacking in U.S. history, do the guys pay a king s ransom, or will negotiations get lost to the wind? Then, a guy marches in with a sword from the Civil War. Made for the foot artillery, does Rick see a sharp profit to be made or will he lose his edge? And later, Rick and Corey check out a collection of paintings by actor Tony Curtis. Will these works give them a whiff of the sweet smell of success?', '2012-08-27', 21, NULL, '2026-04-03T16:34:17Z', '2026-04-03T16:34:17Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('7d050eb5-4083-4ae9-94f7-2bc09bac8249', 'fd0f7dfb-28aa-4687-9ef8-8ff0088ce25a', 13, 'Big Bird''s Nest Sale', 'Snuffy accidentally sells Big Bird''s teddy bear while helping him with his nest sale.', '2013-11-14', NULL, '/1r2dwoBuzKgROd0UP3Wu8CGi1Op.jpg', '2026-04-03T17:36:47Z', '2026-04-03T17:36:47Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('7d075576-4e5b-4d9e-8662-d4f882ada449', '1415ef1c-411a-4c26-814a-7c79c3628bc2', 3, 'A New Low', 'The ladies head to the Hamptons for a weekend of fun and an early birthday dinner at Ramona’s. Carole is staying at Bethenny’s and the only thing she can talk about is the election. Splitting her weekend between Luann’s and Ramona’s homes, Dorinda prepares to see Sonja for the first time since learning about the gossip she has been spreading about her for months . Ramona takes the wrong approach with Bethenny when asking about her film role from 20 years ago.', '2017-04-19', 60, '/gYXhLCow5o4eX0kH3Eamq9DuRld.jpg', '2026-04-03T16:35:24Z', '2026-04-03T16:35:24Z');
