INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('7d770c92-060f-43d8-bcd3-d8212f07c6c1', '4892e2af-46c1-4b4e-ac81-eac161b5a347', 32, 'Episode 32', 'Has the Key-Note Appeal hit the jackpot? Will the keys and cars pouring into the collecting depot reach the two million target on the totaliser?  If so, "Blue Peter" viewers will have provided four mobile classrooms for deaf children in Wales, the Highlands of Scotland, Norfolk and Cornwall.  To start the new year "Blue Peter" travels back in time to the days of old when knights were bold! Peter goes to Knight School and learns the skill of jousting under the expert eye of Max Diamond.  And 52 gnomes invade the studio for a ''live'' phone-in with Noel Edmonds.', '1978-01-02', NULL, NULL, '2026-04-03T17:21:53Z', '2026-04-03T17:21:53Z');
