INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('7dce05df-7493-45d6-b5f1-d23787cbe95f', '871570b4-bf2f-4ba1-9940-65fb932cb009', 7, 'Miami Spice', 'In Miami, a houseguest takes the drama to new heights, causing tensions to rise; two of the women decide to return to Atlanta; Porsha goes on a steamy date with a new suitor.', '2015-12-20', 43, NULL, '2026-04-03T16:34:47Z', '2026-04-03T16:34:47Z');
