INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('7dd8b19e-660d-45aa-bac8-1429c0a16304', '432a6abd-dcca-44cc-82ce-fb39e33b8949', 34, 'Episode 34', 'Ezra Jack Keats visits Rogers to read his book "Hi, Cat!". In the Neighborhood of Make-Believe, a book editor visits Grand-père at the Eiffel Tower.', '1971-04-01', NULL, NULL, '2026-04-03T17:35:39Z', '2026-04-03T17:35:39Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('7ddec1d6-7f88-4c81-a3bb-37b6d54aed93', '5144de59-e67f-4fcf-919b-7106989ab797', 25, 'Ben''s Bad Hair Day', 'Ben attempts to change his “boring” hairstyle with disastrous results, before learning that his hair was fine the way it was.', '1995-02-17', 29, NULL, '2026-04-03T17:12:21Z', '2026-04-03T17:12:21Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('7de39304-89fe-4747-ada0-4ab1bd2ac24e', 'd5383b3d-5636-4d71-b99c-b84774b4b3c6', 7, 'Pingu Has a Day Off', 'Pingu is at school, and the class are given the rest of the day off. As they set off home, Pingu asks if they’d like to play, but they’re all going to go home. When Pingu arrives home Mother is busy cleaning the floor, and suggests that Pingu might like to help. Pingu’s not too keen, so Mother suggests he could help with the washing, or chopping firewood. Pingu is not keen on these either, and he goes out on his sledge. He passes a signpost, and tosses a snowball at it, so that snow covers the directions. He passes Pingg’s house; Pingg is busy helping his father with the firewood and can’t come with Pingu. He then passes the fish stall, where Pingo is helping his grandfather. Pingo is also too busy to come with Pingu. He meets Pingi helping her mother push a sledge loaded with vegetables; she also can’t come with him. He reaches a pool, tosses in a stone and when nothing much happens lies down for a rest. He hears cawing, and sees the Mother Bird taking a fish to her chicks. This gets him thinking; about Mother cleaning the floor, about Pingg with the firewood, Pingo at the fish stall and Pingi pushing the sledge. He then sees the Mother Bird fly off with the fish bone, and sets off back home. On the way he goes straight past his friends, and rattles the signpost so that the snow is cleared from the directions, all without stopping. When he arrives home, Mother is still cleaning the floor. To her surprise he gets her to her feet and settles her in the chair with the paper, and starts cleaning the floor himself. Mother is delighted by Pingu’s change of heart.', '1998-01-13', 5, '/dpaosnYQhABRSefRiTxvNY5h62X.jpg', '2026-04-03T17:22:20Z', '2026-04-03T17:22:20Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('7de707e0-e82b-49a9-aa03-e99536e58dd9', 'ebc99729-ccb7-4d64-82c1-42708cd7ba85', 73, 'Episode 73', 'Feeling hot and bothered? Cool down with a mouth-watering pudding that needs absolutely no cooking. Have a paper and pencil handy for the recipe.', '1981-06-01', NULL, NULL, '2026-04-03T17:21:55Z', '2026-04-03T17:21:55Z');
