INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('7dfe5f7b-9f3d-4de9-a695-9bcd38bcd10c', 'ac068b8e-80f6-46bf-afb2-dcebcf76dc36', 10, 'I''m Talking to You', 'Skye is ignored when he asks to use a video game so he assumes the girl is being mean. Then he discovers that she didn''t hear him because she is deaf. After he learns some sign language, he realizes he has found a new friend. Nuzzle gets interrupted from his nap by Sizzle trying to catch a butterfly. Julie, Ben, and Jody do not appear in this episode.', '1998-12-04', 29, NULL, '2026-04-03T17:12:21Z', '2026-04-03T17:12:21Z');
