INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('7e0d1809-c89a-4b6b-ba77-38bedc7a022c', '4060ad7f-4b8f-4393-8eb1-66a150b928b6', 2, 'Camp Out', 'Abby, Rudy, Elmo, and Charlie are camping out on Sesame Street. They’re just about to toast marshmallows when the sweet treats suddenly disappear! Together, the friends look and listen for clues to find out where their marshmallows have gone.', '2020-11-19', 26, '/yTioC9WbgDNxTr9B8IFoAx0phP7.jpg', '2026-04-03T17:36:50Z', '2026-04-03T17:36:50Z');
