INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('7e1604fa-de68-426b-a7ff-88cf1a88a59f', '5dade172-c4f3-4488-a399-b73f3aca0db5', 8, 'Chapter Eight: The Mind Flayer', 'An unlikely hero steps forward when a deadly development puts the Hawkins Lab on lockdown, trapping Will and several others inside.', '2017-10-27', 48, '/vuLea0DA9rYc9Y4M2Ic28CXL4Al.jpg', '2026-04-03T15:40:39Z', '2026-04-03T15:40:39Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('7e174461-48f3-4435-93e1-9f26b69158e9', '110e3467-3698-4e19-a35b-f6ebbaeb4d6b', 2, 'The Snow Queen', 'Kay and Gerda are best friends. A wicked goblin who likes to cause trouble casts a spell on Kay to separate the friends. The Snow Queen snatches Kay away to her castle. Gerda must go find him. Will she ever find Kay? Is the Snow Queen helping Kay or is she freezing his heart forever?', '1985-03-11', 51, '/9XovOcFk3fSrUaFX5uxms8kzIeK.jpg', '2026-04-03T17:38:41Z', '2026-04-03T17:38:41Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('7e1aab28-5db3-40dd-83ff-6dc8c60b344e', 'da06465b-9154-4feb-a455-374df7dab02f', 18, 'What Happens Next? Show (4100)', 'Elmo is excited to play a messy scientific game show called, "What Happens Next?" with Oscar as the host! With the help of his adult friends on "Sesame Street", Elmo learns lots of new things about what would happen next if, for example, Slimey jumps into a little mud pool from a low diving board, and then from a high board. Would there be a little splash or a big splash? Elmo uses fun science words such as hypothesis when making guesses about what would happen next. Elmo has a great time learning to observe, making guesses, and checking to see if his hypothesis is correct!', '2005-06-20', NULL, NULL, '2026-04-03T17:36:44Z', '2026-04-03T17:36:44Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('7e1c21d3-3ccb-4401-9366-00439cc9b9f7', '0b9d7ae7-218e-45a0-8c3a-e69912f5a6ed', 5, 'Franklin''s Masterpiece', 'Franklin wins a contest with a painting that he, Bear, Beaver, and Fox painted.', '1999-10-25', 12, NULL, '2026-04-03T17:40:15Z', '2026-04-03T17:40:15Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('7e246aa7-91e6-4b05-a675-3723c6116ddb', 'a6ed03e0-c05f-48f8-9f56-3f1da50e1792', 9, 'Episode 1324', '', '1979-12-06', NULL, NULL, '2026-04-03T17:36:33Z', '2026-04-03T17:36:33Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('7e2abe3d-24f0-4f02-acca-a7d53fa51c9c', '3087a3ed-e94e-4276-9d02-a78183dea1d3', 7, 'I Do... But, I Won''t', 'A wife makes a big decision during a Caribbean trip. Meanwhile, Kenya fumes when NeNe questions her behavior, and Porsha infuriates one of the ladies, leading to an all-out showdown.', '2012-12-16', 43, NULL, '2026-04-03T16:34:46Z', '2026-04-03T16:34:46Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('7e2cf73c-4e3e-4428-9547-76017597c1a0', '5c4e51c6-e207-46ad-875c-72988eb1e13e', 25, 'Silent and Deadly', 'The Pawn Stars are on hallowed ground when a piece of marble from Abraham Lincoln''s tomb enters the shop. Without any documentation to authenticate the item, can Rick trust the seller to be honest like Abe or will the negotiation die a quick death? Then, a seller comes in with an antique African sword apparently used for beheadings. Will the guys lose their minds over this piece and buy it, or will they not be sharp enough to execute a deal? And later, Chumlee and the Old Man are speechless when a nearly hundred-year-old Charlie Chaplin wind-up doll tramps into the shop. Will they manage to make a blockbuster buy, or will this negotiation turn into a comedy of errors?', '2011-08-08', 21, NULL, '2026-04-03T16:34:17Z', '2026-04-03T16:34:17Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('7e2d3a3b-5a6b-4c66-a2ea-178fc706533b', 'ca70502b-d862-4cdd-8071-468d6644d517', 9, 'Chapter Nine: The Piggyback', 'With selfless hearts and a clash of metal, heroes fight from every corner of the battlefield to save Hawkins — and the world itself.', '2022-07-01', 143, '/fvoa0Hosu4yK7TUiHglV8TvjMUB.jpg', '2026-04-03T15:40:40Z', '2026-04-03T15:40:40Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('7e2d7cb5-0fde-4d2e-929f-75da0eae8931', '941b8c65-4454-4336-be7c-1d0591c12f90', 10, 'Robby the Snowboarder', 'Pingu goes snowboarding with Robby. At the snowboarding slope they start on a gentle run, passing Pingi on the way, and all get down safely. They go on to the next slope, which is steeper and which has a jump at the bottom. Pingi goes first, does a somersault off the jump, and lands safely. Pingu goes next and makes a hash of the jump, landing painfully on his rear end. Robby goes last and plays safe, going round the jump. Pingi sticks plasters on Pingu’s rear end, and gives him a safety cushion for protection. On the next jump Pingu crashes again, but this time doesn’t get hurt because he’s wearing the cushion. With some tuition from Pingi, and after being knocked off the ski tow by Pingg, who is skiing nearby, and sliding back to the bottom on his stomach, Pingu eventually manages a successful run without crashing. They then all go up on the tow and try the “big one”. Pingi and Pingu get down safely, but this time, despite previous successful jumps, Robby crashes onto his bottom. We then see Pingu, Robby and Pingi snowboarding again, but this time they’re all wearing safety cushions!', '2004-01-15', 5, '/kOmcKKMRdY3jPeAH1o3IMR8WkaR.jpg', '2026-04-03T17:22:20Z', '2026-04-03T17:22:20Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('7e2f17be-ceb4-4aa3-987f-c57ee663fdca', '6fd9fd9d-e378-411b-94b1-76ba4bd518fe', 4, 'Episode 4', 'with Christopher Trace and Valerie Singleton.', '1965-09-30', NULL, NULL, '2026-04-03T17:21:48Z', '2026-04-03T17:21:48Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('7e2f8a5c-e9b0-4898-a573-4c5517f148ee', 'b6a0f228-7ddc-409c-b808-681b777a6704', 4, 'Mister Rogers Goes to School', 'Mister Rogers gets a beginner''s drum lesson at Negri''s Music Shop. He also discovers Mr. McFeely is learning to type, prompting an unusual quartet version of Everybody''s Fancy. In the Neighborhood of Make-Believe, Daniel tells Lady Aberlin his fears about starting school.', '1980-05-22', NULL, NULL, '2026-04-03T17:35:42Z', '2026-04-03T17:35:42Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('7e3437d7-71b1-41e7-bedd-a6f6ce096ea8', 'bf874be3-7e2f-4a0e-b205-c76ac1ad69fc', 163, 'Seinfeld ''Show Night''', 'Documentary about taping ''Seinfeld''.', NULL, 12, NULL, '2026-04-03T16:34:09Z', '2026-04-03T16:34:09Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('7e376a03-920d-43b1-bc5e-f50081d82ab1', '89ba90ec-2c79-4a12-a11d-7465d1757683', 37, 'Rick and Morty MEGASPHERE', 'Congrats on owning the new Rick and Morty console.', '2026-03-05', 3, NULL, '2026-04-03T15:40:41Z', '2026-04-03T15:40:41Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('7e399529-0e6f-45d1-8f32-a14a973d9cee', 'b892884d-7b56-4255-a4c6-08f5d0122273', 5, 'Mammal', 'What incredible talent do dolphins and bats share? How can you tell the oldest elephant in a herd? MAMMAL reveals the most amazing facts and folklore about our favorite furry animals. Towering or tiny, ferocious or friendly, mammals trot, hop, swim, and soar. Meet the creatures that make up this huge and varied family.', '1996-09-30', 29, '/drO9kvsXkK7yIH81B6Ao6eNcJZu.jpg', '2026-04-03T17:39:04Z', '2026-04-03T17:39:04Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('7e4c2940-d62b-466f-b910-e743168e4994', 'ab509c47-ec64-4fb3-8560-03873dd0c37e', 5, 'The Couch', 'Freedom-of-choice issues disrupt Elaine''s new relationship and Kramer''s business; George watches a video instead of reading his book-club book.', '1994-10-27', 22, '/ajPb7dY5vki58mE4q5s5NluP8O1.jpg', '2026-04-03T16:34:11Z', '2026-04-03T16:34:11Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('7e4edb91-8993-478d-84c3-1e02104bb236', '4900fc8d-5e7e-408e-972e-ce9269d203b3', 10, 'Edible Derangements', 'When Shannon invites the ladies over to her home for a luncheon, Dr. Jen reveals her marriage is struggling and looks to the women for advice. Emily and Noella clash unexpectedly when Emily questions some details about her divorce. Heather spends quality time with her family, while Gina notices that not everyone is supporting her brand new venture.', '2022-02-16', 44, '/fXQ2ZzFaIXFtCfxsmhyKTIjmCRg.jpg', '2026-04-03T16:35:35Z', '2026-04-03T16:35:35Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('7e5150e5-2cc0-4387-9072-b8811966399a', 'dbd3583f-e9b2-46d1-a37e-309eb666e233', 7, 'Law By Shereé', 'When Shereé is served with legal papers, she turns to Phaedra for representation. The two Housewives confidently face Sheree’s ex in court, but to their dismay, he has a trick up his sleeve. Kim and Kroy bring baby KJ home and chaos erupts in the house when everyone, including the dog, realizes how big of an adjustment this will be. On an all-new episode of "Kandi Koated Nights," Kandi chats with guests Marlo Hampton and baller boyfriend Charles Grant. One of Kandi''s co-hosts asks Charles what it was like to date NeNe and it doesn’t take long for the gossip to spread.', '2011-12-13', 43, '/mg7CBpnuuBWM8f3XZiv08ZZX3mR.jpg', '2026-04-03T16:34:45Z', '2026-04-03T16:34:45Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('7e531099-2c8e-40fe-b6a1-bad785413744', 'b1d55597-d9d2-4eee-ab95-46dbb163291a', 14, 'Pingu Runs Away From Home', 'Pingu and his parents are enjoying a quiet dinner, but Pingu isn''t happy due to him refusing to eat his disgusting dinner. Mother and Father decide to share their food. Father give Mother fish, Mother gives Father greens and Mother tries to give Pingu a brown potato, but he refuses and splatters it all over Mother. Father becomes enraged and tells him off. Pingu then rocks his chair and ends up pulling everything off the table. His parents becomes furious and Pingu ends up getting a spanking. He tries to make amends, but gets neglected instead and runs away, feeling that his parents don''t love him anymore. Pingu''s parents enjoy some quiet time, but they''re not really enjoying it because they are worried about Pingu because of what time it is and what they have done. Meanwhile, Pingu becomes hopelessly lost. He nearly gets crushed by falling ice, and then comes face to face with three ugly, menacing monster-faces in the snowdrifts. They look like a human skull, a grumpy dwarf and a dragon. Terrified, he runs and hides in an ice cave. His parents, realizing how late it is, feel pretty bad of how they treated Pingu, so they come out and find him, with Father using his post truck to find him. Pingu notices his parents finding him and shows himself. Happy to see their son, Mother and Father both apologize to him and they take him back home. After Pingu is fed hot soup by Mother, they all go to bed together happily.', '1990-01-14', 5, '/83OZuGgLqOHNYKlRBqnT7HVoqQf.jpg', '2026-04-03T17:22:18Z', '2026-04-03T17:22:18Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('7e5d967d-c5ff-4af6-9ef3-55bfff4e4d99', '9c5608b2-5111-48bc-a907-7f93472c1e03', 25, 'Porridge Art', 'Baby Bear enters a porridge art contest that''s being held by his favorite porridge brand.', '2013-04-18', 58, '/zn0lPnxAyDu9i9becmU0oTKqe24.jpg', '2026-04-03T17:36:47Z', '2026-04-03T17:36:47Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('7e5f6600-b5ae-4e7c-94e6-aa9fcede2bd2', '936491e2-ab83-4e1f-b5c7-2c03f6461d86', 4, 'Autumn Story', 'Wilfred is looking forward to the deep snow to ride on his tobaggan. Better still when the snow covers the third notch comes the Snow Ball celebration at the Oak Palace. Soon Basil, Wilfred and Primrose get trapped in one the snow tunnels. Primrose finds a way out and summons the other mice to help. After that everyone celebrates.', '1997-10-26', 25, NULL, '2026-04-03T16:14:06Z', '2026-04-03T16:14:06Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('7e6556b1-4bfb-4f81-9917-a96b9d4a87da', '16cbf3f2-fffd-4a78-bca3-96d05f5a2c6b', 11, 'Postcards from Binky', 'Binky''s grandparents miss his big soccer game, and so he attempts a reenactment of the event making video postcards just as Buster did when he left with his dad.', '2016-05-24', 13, NULL, '2026-04-03T17:38:01Z', '2026-04-03T17:38:01Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('7e655b52-f177-4fea-91bf-64955d900332', 'e40e6b63-9f84-449f-8e88-53209b0906c8', 3, 'Word ''Dog'' Escapes Abby''s Book', 'Baby Bear and Telly Monster welcome the viewer to Sesame Street, and look forward to reading a book with Abby Cadabby. Abby arrives and introduces her magical book: The Wild Adventures of Action Dog. The others hear a barking sound, which turns out to come from none other than the book itself.', '2007-08-15', NULL, '/84bCjWK3Gh1cwfIWxXdujevbzeg.jpg', '2026-04-03T17:36:45Z', '2026-04-03T17:36:45Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('7e6aec9f-a650-41fb-b224-b86f7cb3274e', '9b144910-398a-47d4-9ccd-823d25cc8b0a', 17, 'Hot Tub of Sour Grapes', 'Friendships may be beyond repair when Teresa and Caroline have one last blowout after Caroline overhears a conversation between Teresa and Kathy.', '2012-08-26', 43, '/8fo8mlahQIHj2YQappGTuooRmb7.jpg', '2026-04-03T16:35:15Z', '2026-04-03T16:35:15Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('7e6dce1e-b0f4-4d5a-bf76-8611d0715aa2', '1d713ca6-4e17-4f84-949c-8cfd98514127', 43, 'Motorcycle Mayhem', 'Rev your engines with the Pawn Stars when a 1957 Harley-Davidson Sportster roars into the shop. Will Corey be able to hammer down on the deal or will it burnout? Then, things get political when Rick checks out a painting of Communist leader Ho Chi Minh. Will he make a revolutionary deal, or will it be a tough loss? And later, when Chum starts helping himself to things around the shop, the guys try to tell him that taking is not the same as sharing. Will Chum teach them a lesson, or learn the hard way?', '2014-12-22', 21, '/o8c8ozBK6mRfDChx7ZxlZ1OXMCe.jpg', '2026-04-03T16:34:19Z', '2026-04-03T16:34:19Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('7e78e583-89e1-4d53-8c05-91a7fd9d3ab2', '9193e795-da7c-40ec-b68f-f63aa7d5174f', 24, 'The Story So Far (2017)', 'Ahead of the season seven premiere, get up to speed on all the action in Game of Thrones with this re-cap of the story so far.', '2017-07-13', 60, NULL, '2026-04-03T15:40:35Z', '2026-04-03T15:40:35Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('7e8afc5e-81a5-49d5-bff4-acfd3e972e09', '3ee646e8-23ae-4dec-bbc6-c7e6a210d55b', 112, 'Episode 2857', 'Bob watches over Barkley while Linda paints her kitchen. Barkley is feeling very sad, though. The Amazing Mumford happens by and has a trick that can help improve Barkley''s spirit.

Sponsors: K, U, 10', '1991-04-16', NULL, NULL, '2026-04-03T17:36:38Z', '2026-04-03T17:36:38Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('7e8bda70-807f-47a6-be68-c11127c98528', '4d2cac0f-38fd-438b-8afa-acf43952e535', 8, 'Episode 8', 'Toys, model railways, games, stories, cartoons. A weekly programme for younger viewers with Christopher Trace and Leila Williams.', '1958-12-04', 15, NULL, '2026-04-03T17:21:47Z', '2026-04-03T17:21:47Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('7e8c4350-5d56-478c-adef-e06b72713e01', '573fa62f-55a9-4f17-97cc-d1a005a83cc8', 2, 'Martin Luther King Jr. Day on Sesame Street', 'Elmo and his friends are making a Peace Tree to show how they will carry on Dr. Martin Luther King''s wish to treat people fairly and kindly every day!', '2025-01-23', 26, '/3H71WqVT3Fs61XizNCaD0KQGHlB.jpg', '2026-04-03T17:36:52Z', '2026-04-03T17:36:52Z');
