INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('7e922838-22e8-456e-8785-efec29db6030', '1d556682-d9bb-47e1-993f-0b648a8daacd', 119, 'Episode 1304', '', '1979-05-10', NULL, NULL, '2026-04-03T17:36:33Z', '2026-04-03T17:36:33Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('7e9b0b55-f31a-4666-8a99-1af3328b03b8', 'c9d2b3fb-7845-4f3c-9847-ce1f7717257a', 15, 'A Demon of a Deal', 'All engines rev when Corey flips a limited-edition Dodge Demon; a vintage suit worn by the legendary Dale Earnhardt Sr. sends Corey and Chumlee racing.', '2019-07-01', 42, NULL, '2026-04-03T16:34:21Z', '2026-04-03T16:34:21Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('7e9ee0c6-45ad-47b3-a636-9a18edbdacf1', '9b95011e-93db-4e56-a45d-8aa956c15997', 10, 'Up, Up and Away', 'Whilst doing some kite flying with the other kids, Mandy is inspired to want to fly over Pontypandy Mountain. Hannah tells her that her dad, Joe Sparkes, has just the thing...which turns out to be a hot air balloon!', '2014-06-07', 10, '/930wNB1gBYZDX9wf69XDForUN1w.jpg', '2026-04-03T17:14:40Z', '2026-04-03T17:14:40Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('7ea0e091-4963-4d84-8066-0023bf8c05af', 'dfa60f31-6ef1-4bee-a9ad-554b68a5448b', 13, 'Dangerous Africans', 'Steve encounters charging elephants on an African safari. He observes snakes, scorpions, buffalo, spiders and lions, and avoids a pursuing hippo.', '2001-06-22', NULL, NULL, '2026-04-03T17:39:11Z', '2026-04-03T17:39:11Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('7ea3c64c-1c66-4eed-a031-e7a6c6555322', 'bbfee3b4-9c95-48a6-beaa-791fa08b1f43', 35, 'Episode 35', 'Winged Waitress!

Janet discovers there''s more to being an air stewardess than meets the eye, as she fights a fire in the galley and escapes down an inflatable chute-part of the routine training by airline crews all over the world.', '1984-01-12', NULL, NULL, '2026-04-03T17:21:56Z', '2026-04-03T17:21:56Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('7eaf6f5a-fe32-4399-adde-db158846b7fc', '34674c90-410e-427c-be4d-2a6f6f865a80', 24, 'Free Willie', 'Hail a ride with the Pawn Stars when a taxi from the 1992 sci-fi movie "Free Jack" pulls up to the shop. Specially built just for the movie, do the guys give this prop some props, or send it back to the future? Then, a San Francisco Giants uniform owned by baseball legend Willie Mays has Chum and Corey seeing green. Will they try to take this deal into extra innings, or will something make them cry foul? And later, a guy walks in with a fully functioning brass hand cannon. Looking like something from a pirate movie, will Rick see a buried treasure, or is this unusual weapon just a swashbuckling novelty?', '2012-08-20', 21, NULL, '2026-04-03T16:34:17Z', '2026-04-03T16:34:17Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('7eaff220-6d73-4448-9fc0-7389ecb6b463', '8610109b-4fb9-4eae-be54-c549fae5ecc8', 1, 'Scooter Computer And Mr Chips', 'The last of the original series were four segments about the then-novel personal computer technology. The shorts featured two characters by the name of Scooter Computer and Mister Chips, and so these were the only episodes in the series to feature any recurring characters.', '1983-11-26', 3, NULL, '2026-04-03T17:13:55Z', '2026-04-03T17:13:55Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('7eb20b56-3d9f-49f2-9625-266d96f25aa9', '40700e8a-1dce-4895-bede-522a13a8bcad', 21, 'Hot and Cold', 'A Gila monster and a snow leopard make Animal Junction a hot and cold place.', '2001-05-11', 27, NULL, '2026-04-03T17:10:55Z', '2026-04-03T17:10:55Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('7eb7ab34-1c78-4861-854e-434bec1fa0f5', '23af85bf-93be-48cd-913c-09c2f60403da', 9, 'Something Ricked This Way Comes', 'Rick battles the devil and upsets Summer. Meanwhile, Jerry and Morty hang out.', '2014-03-24', 23, '/daA9q3U3ibIcm5OGuklySeIsQWV.jpg', '2026-04-03T15:40:41Z', '2026-04-03T15:40:41Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('7ebae25d-0765-4a31-8d92-1b68b4e30f96', 'a1b69730-d225-48f2-a7e7-1d314cf3b349', 60, 'Episode 60', 'with Valerie Singleton, John Noakes, Peter Purves', '1969-04-21', NULL, NULL, '2026-04-03T17:21:49Z', '2026-04-03T17:21:49Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('7ecbc725-d47e-438d-a5ac-64cb54e4517d', '21384b9c-43fa-410c-b89d-102e7cf9129b', 2, 'Four Lives of Kody''s Wives', 'Since leaving Utah, the wives have settled into separate lives. Janelle continues her weight-loss battle. Robyn fights to keep the family business afloat. Meri works to repair her relationship with Mariah and Christine rethinks her career.', '2013-07-28', 60, NULL, '2026-04-03T16:34:28Z', '2026-04-03T16:34:28Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('7ed81aaf-ab75-41ac-8b78-fdf3b7f0fd9c', '65524b14-e29e-4b04-81d3-fbebe525e9ec', 10, 'Franklin''s Dance Lessons', 'Franklin initially tries to get out of dance lessons before learning it can be fun.', '2004-06-14', 12, NULL, '2026-04-03T17:40:16Z', '2026-04-03T17:40:16Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('7ee068bf-a582-4246-bd48-8fb262e24e85', '63850e1d-d8ed-4fe4-a068-83cb879c170a', 3, 'The Glasses', 'Kramer''s optometrist pal replaces George''s glasses with suspect frames.', '1993-09-30', 22, '/6NaKh36cqIzcladIkTfFLb2Edx0.jpg', '2026-04-03T16:34:10Z', '2026-04-03T16:34:10Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('7ee27709-f925-46b5-82fb-bcb9538dc704', '1d713ca6-4e17-4f84-949c-8cfd98514127', 28, 'Chum Fever', 'Dial in on the Pawn Stars as they check out two antique telephones. Will Corey answer and make the deal solo or will he have to call in some backup? Then, Rick spots a rare porcelain bowl made during the Ch''ien-lung dynasty. Will Rick handle the china with care or will the deal smash to pieces? And later, Chumlee refuses to leave work even though he doesn''t feel well. Will he make it through the day or will Rick get sick of his complaining?', '2014-10-30', 21, '/8WCOTIrFzqRWMVTWHnlXMdgpuF0.jpg', '2026-04-03T16:34:19Z', '2026-04-03T16:34:19Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('7ee341a7-7ece-44d3-887a-ed41a677b2f6', '5a4e38a1-8e54-4974-8097-d7a7b48630a2', 30, 'Episode 30', 'with Valerie Singleton, John Noakes, Peter Purves', '1971-01-01', NULL, NULL, '2026-04-03T17:21:50Z', '2026-04-03T17:21:50Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('7eeb5bab-3f73-4451-8ffc-b19509c23c15', 'ca09391a-de6a-4b2b-aefc-c2efbc80a106', 4, 'Galimoto', 'Viewers learn the many uses for wire: from creating objects of wire art and transporting people on the longest tramway in the world, to playing an integral part in a circus act.', '1991-09-19', 30, NULL, '2026-04-03T17:36:17Z', '2026-04-03T17:36:17Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('7eeb6ced-88a0-41c1-8a59-8559377894dd', '79c64e0a-3488-41bc-9b5c-2243ff15b373', 7, 'Headlines and Heartbreak', 'After a tearful departure from Rachel’s psychic dinner, Amanda turns to Kyle for support while Dorit maintains she’s done nothing wrong. Shocking headlines leave Rachel reeling. Kyle and Mauricio share an emotional walk down memory lane during their visit to Amanda’s home. Kyle hosts a birthday dinner for Erika and Dorit, but the celebration takes a turn when tensions between Dorit and Amanda come to a head.', '2026-01-29', NULL, '/pmsfhMVUBjCLB7E9vdZQLd5lF9Z.jpg', '2026-04-03T16:34:59Z', '2026-04-03T16:34:59Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('7eedbff7-95a7-4a74-b2b8-e4ccffbb654e', 'dbde6570-a68d-4fd7-a1b0-a6037a266a18', 15, 'Scream Therapy', 'Brooks supports Vicki after her huge argument with Briana. Heather decides to take Terry''s surname. Gretchen and Slade seek counselling and Alexis attempts to patch things up with Tamra.', '2012-05-22', 44, NULL, '2026-04-03T16:35:31Z', '2026-04-03T16:35:31Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('7ef01a8a-8a50-4971-aef5-f89e76e86b62', 'ae8f64d9-4b83-4147-a44c-bfe720381f8e', 18, 'Jack''s Big Jump', 'Jack Be Nimble is getting ready for his big jump over eight candlesticks! He tries to jump over them, but instead he knocks them over and falls. Jack runs away and hides.  He messed up and now is having trouble jumping. Baby Bear and Telly find someone to help him—a kangaroo!

The kangaroo sometimes has trouble jumping too, but he sings the Jumping Song to help him get over his fear. Luckily, Jack gets his jump back. He is ready to jump, but instead jumps quickly behind a bench. Jack is upset; he can jump up and down, but can’t jump over the candlesticks. Telly and Baby Bear race out and find a special cow—the cow that jumped over the moon! Jack practices jumping with the support and help from the cow and realizes that he is indeed ready to jump over eight candlesticks. Everybody is chanting when Jack flies into the air and jumps over not eight, but 11 candlesticks! He did it! Hooray! Telly and Baby Bear jump too!', '2009-12-30', NULL, '/9SggZoqGsrqoHiUJL89stPuBvyv.jpg', '2026-04-03T17:36:46Z', '2026-04-03T17:36:46Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('7ef1c20d-a4e4-4c7c-97c8-92b5b6b7b9be', 'c382366d-b65c-4f2a-9e91-200f0d973ae9', 5, 'The Secret About Secrets', '', '2006-05-17', 13, NULL, '2026-04-03T17:37:58Z', '2026-04-03T17:37:58Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('7efcccd3-6751-4ceb-a99b-b75161234e42', '8c0f12e1-5379-4a27-aca2-b69401a33b0f', 28, 'Arthur''s Knee', 'Arthur does not want to tell his mother he hurt his knee, because then she will know he was playing down at the dump—where he is not supposed to go.', '1998-04-09', 13, '/1yu3BDM85ryk89WEMCOF405JZmS.jpg', '2026-04-03T17:37:55Z', '2026-04-03T17:37:55Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('7f00772d-3ea0-44d4-9101-a144a307c8a5', 'a605edf8-69ba-46db-8c0c-523b1ef5447b', 67, 'Episode 67', 'with John Noakes, Peter Purves, Lesley Judd', '1973-05-07', NULL, NULL, '2026-04-03T17:21:51Z', '2026-04-03T17:21:51Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('7f02c71a-25b6-4ce2-8d87-cdcdbb7914d9', '99a96781-44cb-4a5c-9100-71e2a55b6b1a', 7, 'Moving Violations', 'Jeana, Vicki, Tammy and Tamra head down to the U.S. Grant Hotel in San Diego for some housewife hijinks. Newly single Jeana is back on the market and ready for anything. The ladies are in the lap of luxury, enjoying a presidential suite and the San Diego nightlife. A conflict between Jeana and Vicki comes to light and threatens their friendship.

The OC Angels promote their energy drink at the US Open in Huntington Beach but bad driving, bad attitudes and bad luck threaten to ruin it all. Meanwhile, Tamra’s real estate business is booming, while Lauri travels to Oklahoma with daughter, Sophie, to spend some time with the US Women’s Softball Team.', '2007-12-18', 44, '/fglVtpLSvyWFIYQN6NsWucHQCsl.jpg', '2026-04-03T16:35:30Z', '2026-04-03T16:35:30Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('7f02ce37-986a-45c7-ad11-e9a279afdcfd', '495d4222-b33a-46fa-8351-3265798e558b', 13, 'Lighthouse Blues', 'The Gribbles are looking to destroy the lighthouse and the ghosts at the attic are not impressed.', '1990-07-06', 24, '/oFq2UQ2itCD5gjQMgWhpaqZBTkc.jpg', '2026-04-03T17:40:40Z', '2026-04-03T17:40:40Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('7f03f404-ff8c-4434-bbb8-7be143646cae', '52135215-5160-4d42-9d0f-db242b1abcaa', 3, 'Alejandro''s Gift', 'Alejandro gives the gift of water to various desert animals. Also includes Desert Scenes, At the Oasis, Niagara Falls and book reviews for It Rained on the Desert Today, The Desert Alphabet Book and Water, Water Everywhere.', '1995-10-04', 30, NULL, '2026-04-03T17:36:19Z', '2026-04-03T17:36:19Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('7f087dc9-7c63-46cc-b634-d9e881584d43', '20d7138e-eea8-46a8-8ada-2b0f0ee1f674', 37, 'Episode 37', '', '1983-01-20', NULL, NULL, '2026-04-03T17:21:56Z', '2026-04-03T17:21:56Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('7f0adb95-5990-4dc4-a5b8-cedc661689eb', '05c0e384-194c-4417-9f62-803eb615e409', 57, 'Rabbits', 'Title number 0057. Opens with Mister Rogers discussing rabbits brought to the porch by Mr. McFeely. A friend brings over a bunny marionette. Henrietta is bored and is cheered up by a familiar face. It turns out to be Joey Hollingsworth in disguise returning from a trip around the world where he learned new styles of dance and sold many "Rockit" rocking chairs for Corny.', '1968-05-07', 29, NULL, '2026-04-03T17:35:38Z', '2026-04-03T17:35:38Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('7f0eab23-fb4b-42e7-9f1b-6a569e03d90a', 'bb919aec-0d5c-4c58-9a5a-fa2a0a5de2b6', 100, 'Episode 505', '', '1973-04-13', NULL, NULL, '2026-04-03T17:36:30Z', '2026-04-03T17:36:30Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('7f0f99e2-fa5c-4d6a-b23f-efa0a2cbd918', '543ec6dc-c6c7-447c-b5a7-4484d9618391', 6, 'Securing Homeland', 'Michaele asks for Stacie''s help in finding a home in D.C. Stacie is still in search of her biological father, while her mother is of no help. Cat and Mary bond over talks of motherhood. Cat loses a dear friend and is devastated by the loss, feeling alone while her husband is out of town. Tareq has family troubles yet again and Michaele realizes it''s taking a toll on her.', '2010-09-16', NULL, NULL, '2026-04-03T16:35:01Z', '2026-04-03T16:35:01Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('7f11f97a-9655-4d9f-b6c1-04dab8968ed0', 'c373abed-50ef-417e-9f34-4e9050611a1b', 8, 'Hot in Orange County', 'While Heather is in Hollywood filming a guest role on Hot In Cleveland, Terry struggles at home alone with the kids. Meanwhile, Alexis pursues her own acting career in Orange County. Gretchen and Slade ruffle some feathers when they are inconsiderate on Heather’s big day. Then, Lydia confronts her mother about her marijuana smoking habit.', '2013-05-20', 44, NULL, '2026-04-03T16:35:32Z', '2026-04-03T16:35:32Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('7f13f1d1-faca-4b27-839b-0d507aa9d3ab', '96dd06ee-d44a-47f3-9372-e29e8eaa77f5', 8, 'Snow Business', 'It''s Christmas Eve, and Pontypandy''s got four inches of festive snow to keep the kids entertained. They''re playing snowballs, and everyone around  town is enjoying the cold snap, except for Dylis Price. She''s not happy shovelling snow from her shop front and ducking the great hanging icicles above her head. She wonders why the Christmas tree isn''t up in the park yet. Why, the Council have been a bit late this year. She suspects they couldn''t afford one. Her comments give Fireman Sam a jolly idea...', '1988-12-22', 10, '/niA52ErBhIgBemWjcbOYgZ0BJis.jpg', '2026-04-03T17:14:37Z', '2026-04-03T17:14:37Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('7f1afb78-70ec-4763-87ce-59cab0a4c9a0', '3ee646e8-23ae-4dec-bbc6-c7e6a210d55b', 65, 'Telly the Dad', 'Telly, dressed in a sensible cardigan, pretends that he is a dad with Freddy acting as his son. Telly observes Oscar trying to get his niece Irvine to take her nap, something fathers will usually do.

Sponsors: T, W, 12', '1991-02-08', NULL, NULL, '2026-04-03T17:36:38Z', '2026-04-03T17:36:38Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('7f1fed86-72a2-4f2d-b341-bf3128f0e590', 'b761c069-8326-445a-8a55-4adf19467af4', 10, 'Taking Care of Chance / Story Dress / Katie and the Sad World', '', '1994-03-31', NULL, NULL, '2026-04-03T17:11:21Z', '2026-04-03T17:11:21Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('7f2374a7-5aac-4dcd-9a04-cfc2f7a0cb5b', '8bdf0ad3-a798-4d5a-b304-c7501eae6867', 12, 'Who''s Your Daddy?', 'Vicki Gunvalson launches her L.I.F.E. with Vicki cruise and is thrilled to get so much attention from her colleagues, but is frustrated when she can''t seem to get any props from her own family. Jeana Keough and her daughter, Kara, drive to up to Berkley to move Kara into her apartment. They find themselves strangers among the "bums" and "hippies." Tamra Barney visits her dad in Iowa and puts it all on the line, spilling her heart out to her estranged father. Gretchen Rossi does Dallas, reuniting with her four best friends from college. Lynne Curtin and her husband, Frank, take a romantic getaway to San Diego leaving their teenage daughters, Raquel and Alexa, home... with Grandma.', '2009-02-10', 44, '/pwc6uHZpghQIVWqdZvoL3aSmuCB.jpg', '2026-04-03T16:35:30Z', '2026-04-03T16:35:30Z');
