INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('7f266e0a-9764-4445-8205-f3221c57879b', 'a9657e86-4135-49ce-b1f9-c295113077e1', 20, 'Play It and Say It', 'Ord is forgetting the Spanish numbers Quetzal is teaching him, and he is upset.', '2005-03-14', 30, NULL, '2026-04-03T15:26:04Z', '2026-04-03T15:26:04Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('7f27087f-8902-4fe3-9e9e-41f1c3438a41', '9193e795-da7c-40ec-b68f-f63aa7d5174f', 30, 'Inside the Episode: Season 7 Episode 5', 'Inside the Episode: Season 7 Episode 5', '2017-08-13', 5, '/871Rb4J8tLT7umW3hxTAfzJmbsl.jpg', '2026-04-03T15:40:35Z', '2026-04-03T15:40:35Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('7f2797c3-5a75-48f1-88b7-e44cb2b05e5c', '573fa62f-55a9-4f17-97cc-d1a005a83cc8', 25, 'Hide and Seek Chameleon', 'When Elmo and Gabrielle have trouble finding Casey Chameleon, Chris helps them learn all about chameleons and how to find Casey''s hiding spots.', '2025-07-03', 26, '/3RfjACEq3U4kZX6BkSHIRpgde7K.jpg', '2026-04-03T17:36:52Z', '2026-04-03T17:36:52Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('7f291d18-a8c9-4c01-92d4-0b6253d1189d', '1a534647-384b-4c00-bb6c-a3371ad962eb', 30, 'Behind the Wheel', 'Play ball with the Pawn Stars when a 1923 Babe Ruth baseball card, graded a perfect 10, steps up to the plate. Will Rick be able to knock it out of the park on this rare card or will he get called out? Then, Rick is brought back to the 1930s when an unrestored children''s tricycle pedals into the shop. Will he toy with the idea of fixing it up it or will the cost cause him to hit the brakes? And later, after Corey totals his truck, he is forced to drive the company car with Rick''s face on it. Will Corey end up understanding the truck''s true face value or will he force Rick to face facts?', '2015-05-25', 21, '/gItH4gYJ6pfjtklugbD5vyBQKFQ.jpg', '2026-04-03T16:34:19Z', '2026-04-03T16:34:19Z');
