INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('7f2ae166-da2b-4978-a06d-4fd8aafef20a', '0987f081-b3b7-4e3c-abb7-795e56c279d5', 10, 'Twenty Years', 'Frankie worries Mike is tiring of her as their 20th anniversary draws close; Sue tries to get Axl and Brick''s help planning a party for their parents; Axl spoils the end of a book for Brick.', '2012-12-12', 22, '/y8ghzOorLWvah70wzTEc1QKXFpr.jpg', '2026-04-03T15:40:30Z', '2026-04-03T15:40:30Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('7f2dc57a-3c31-4b95-b4e0-cabc6e20fb90', '2a1c12a9-3fc2-44c9-8d37-010d16f56c77', 3, 'Wild Imagination', 'Race around in a shopping cart, learn about pilots and celebrate JJ''s birthday in this fun, interactive sing-along with JJ and his family.', '2023-02-15', 50, NULL, '2026-04-03T15:26:07Z', '2026-04-03T15:26:07Z');
