INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('7fb43eec-f98f-4550-9a52-7f0674b322af', '0fb5ce65-0258-4423-be8a-f7ba9c37bb6b', 6, 'Mystery at Pumpkin Hollow (Part 2)', 'The Why Files and the Detectives are both on the case within Pumpkin Hollow, with strange sounds and disappearing pumpkins to boot.', '2023-10-25', 9, '/uMxYx35Kbu2EH1pXOA5uG6BfNaY.jpg', '2026-04-03T17:14:42Z', '2026-04-03T17:14:42Z');
