INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('80114c4e-5462-417b-a058-89e5fd2df9e6', '1f34e241-4c1d-4586-921a-1c5aeb1fbbaa', 73, 'Episode 2168', 'The Count welcomes the viewer and unveils the number 2, and then presents Snuffy as he is going to count to two. Forgetful Jones is sitting down at Hooper''s with a piece of paper when he calls out to David to ask to borrow a carrot so he can write a note to himself reminding him to order chicken feed.

Sponsors: O, X, 2', '1986-02-26', NULL, NULL, '2026-04-03T17:36:36Z', '2026-04-03T17:36:36Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('8011fb9a-2362-43fe-9e15-8b7aef042f71', '8a5892f6-ccb7-4f02-9a5a-85b134b5f0cf', 11, 'The Cuckoo Clock', 'It doesn''t tell the time any more. It doesn''t sing any more. It is no use at all, except to a homeless bird and her family.', '1976-02-12', 5, NULL, '2026-04-03T17:24:25Z', '2026-04-03T17:24:25Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('8015499f-9931-4905-961b-9724ccca3d05', '65d1cad8-0120-425e-ae9b-5020ce773b32', 1, 'Revolving Door of Lies', 'Shannon is loving the single life as Jenn preps for her wedding; Emily reveals a heartbreaking family issue; Tamra opens up about her past trauma in therapy; Heather deals with problems at her Beverly Hills mansion.', '2025-07-10', NULL, '/1hHpvZdLzA5GBd2q7nrkIWzwJeJ.jpg', '2026-04-03T16:35:36Z', '2026-04-03T16:35:36Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('802585b0-bd02-418b-9218-7afc966dd82e', '58adb9ab-3f1b-4a11-87b6-9b0b2dbb6aaf', 12, 'The Pawnshine State', 'Rise and shine with the Pawn Stars as Rick and Chumlee take a trip to the Sunshine State to check out a fully loaded 1964 Rybovich Yacht. While in Florida, Rick visits his friend, Lisa, at her own pawn shop in town. A local Florida Highwaymen painting catches Rick''s eye, but he also sees opportunity for Lisa''s pawn shop to grow. Rick votes to check out a voting machine from the 2000 Presidential Election that could be a winner for Lisa''s store. Meanwhile, back in Vegas, Corey sees green when a seller brings in some original Incredible Hulk comic books.', '2017-06-05', 21, '/WTaRyk9sgPfoHz2waMgP5Ddo6T.jpg', '2026-04-03T16:34:21Z', '2026-04-03T16:34:21Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('8026947a-a75d-4fa9-852c-0a6fa66a9962', 'f593d90c-5339-42f5-9c88-5bfd48d04075', 22, 'What''s Up, Dog?', 'A wayward balloonist lands in the sheeps field. Shaun and his friends are intrigued by the hot air balloon and inadvertently take to the skies. Down on the ground an ever more desperate Bitzer runs himself ragged attempting to bring the wayward sheep back down to Earth safely.', '2010-12-05', NULL, '/50UG9VIyptbyPA0YeDkkBioX9vG.jpg', '2026-04-03T17:39:31Z', '2026-04-03T17:39:31Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('802a2cd1-08a1-4977-ab28-635881745acd', 'd1863f2f-02ec-40ce-af64-db03fbe518a7', 8, 'When Dinosaurs Walked Sesame Street', 'Elmo, Chris, and their friends on Sesame Street have dressed up as dinosaurs. With help from Elmo''s book, they learn that there are small and big dinosaurs, some dinosaurs are herbivores and some are carnivores and that Big Bird is a dinosaur! Also featuring Jurassic Cookie parody, and Elmo''s World-dinosaurs. Brought to you by the letter D and the number 15.', '2016-02-27', NULL, '/x8KH0N1EeLdrb4nY0KOTbSObxOs.jpg', '2026-04-03T17:36:48Z', '2026-04-03T17:36:48Z');
