INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('80503030-496f-4f72-98ef-539529025e2a', '740a96a0-a075-4be2-be92-a178d0939384', 29, 'Elmo and Abby''s Bubble Fun', 'Alan and Chris introduce Sesame Street''s first-ever Bubble Fest! Elmo, Abby, Telly and the kids gather for the festivities. Telly is excited, as he''s never blown a bubble before, and neither has Abby (her mommy''s always made them with magic).', '2018-06-02', NULL, '/nVUQ0Rf73VntjKj1bCRW31SzoEs.jpg', '2026-04-03T17:36:49Z', '2026-04-03T17:36:49Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('80620b95-0ce9-49c0-be67-040326eb3cc4', 'f6015d9a-ece4-414a-a00b-06cf689fe40b', 8, 'Cool as Ice!', 'It''s an ice-cold special. Find out what it means to be chilly with epic liquid nitrogen experiments. Lindsey and Radzi try ice hockey, HRVY performs in studio, and our guest presenter is the coolest guy around, Steve Backshall!', '2018-02-15', NULL, NULL, '2026-04-03T17:22:10Z', '2026-04-03T17:22:10Z');
