INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('8072862a-72ef-475f-8f9c-11d6b880e1f0', 'ca19f895-1514-4988-a709-95e84eab7cee', 18, 'Once a Pawn a Time in Hollywood', 'When a vintage Yellow Cab hat pulls into the shop, can Rick hail a fare deal? Next, a seller pops in with a gum ball machine. Will he stick to a fair price, or do Corey and Chum have to burst his bubble? Then, Corey gets to play with the world''s first video game console. Can he control the negotiation, or will it be game over? Finally, Rick and Chum are ready for their close up as they head west to check out a treasure trove of Hollywood memorabilia in California.', '2021-05-17', 42, '/eQUEppKj7V2W1e1I9bVK1rCLiaI.jpg', '2026-04-03T16:34:22Z', '2026-04-03T16:34:22Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('808137cd-d039-4b57-9ac8-72470d2ab774', 'f760505e-28a1-4d38-964d-5a2617b5b402', 4, 'Island', '', '1997-09-15', 29, '/mImkZOMdieeJDv4UhneC7CbNJ66.jpg', '2026-04-03T17:39:04Z', '2026-04-03T17:39:04Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('80838ca9-1c99-4fa8-8ea5-69ff296d3cd7', 'd0e5568d-939d-4d89-ab4e-c291a90691cf', 1, 'The Holiday', 'At the seaside Tiger just wants to read his book. Kipper keeps interrupting him so Tiger tells him to go for a swim. Kipper plays ball with a friendly sea lion but Tiger doesn''t believe him. He finishes his book and Kipper starts reading - now he wants to be left alone. Tiger meets the sea lion too and soon all three of them play happily together, book forgotten.', '2000-09-28', 30, NULL, '2026-04-03T17:10:49Z', '2026-04-03T17:10:49Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('80843653-3bcd-44c3-9a0e-8498ba16e9f5', '51c41996-c452-4a28-b174-3765855be794', 5, 'Alike and Different', 'Jeff Gabel surprises Rogers by showing a few peeps. Rogers goes to a circus, where Gabel puts on his clown make-up. The Neighborhood of Make-Believe finds Lady Aberlin in a chicken costume, much to Daniel''s dismay. Aberlin gives sound advice to Daniel and to Nancy Caterpillar.', '1987-11-27', NULL, NULL, '2026-04-03T17:35:44Z', '2026-04-03T17:35:44Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('8086ab47-9c27-4e23-bd26-71e81b591be5', '03485b5e-a5b7-423e-b21e-c00e62216a35', 18, 'Help Around the Workshop', 'Mama puts Papa''s workshop in a neat & orderly fashion. Unfortunately, it caused big problems for Papa.', '2004-04-16', NULL, NULL, '2026-04-03T17:40:22Z', '2026-04-03T17:40:22Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('808c738f-3e0a-43b2-8663-de25e117dcc8', 'bbfee3b4-9c95-48a6-beaa-791fa08b1f43', 63, 'Episode 63', '', '1984-04-19', NULL, NULL, '2026-04-03T17:21:56Z', '2026-04-03T17:21:56Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('80986b4b-12cc-4610-9656-097e4eb65aca', '34bdccfa-3c14-4e1c-9148-85c29aadc0e1', 47, 'Spots and Stripes Forever', 'Chris and Martin are back in an African savannah to learn how camouflage is standard defense for several creatures.', '1996-08-06', 30, NULL, '2026-04-03T17:11:47Z', '2026-04-03T17:11:47Z');
