INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('80a64673-83de-4f34-9a3f-f8f252b5923a', '432a6abd-dcca-44cc-82ce-fb39e33b8949', 31, 'Episode 31', 'Those in the Neighborhood of Make-Believe react in different ways to the presents the Platypus family, returned from Australia, had given them.', '1971-03-29', NULL, NULL, '2026-04-03T17:35:39Z', '2026-04-03T17:35:39Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('80b25538-ad37-491c-914b-0233ab991b4b', '353f8b38-d837-4354-88bd-d51e98a3421a', 17, 'DELETE ME', '', NULL, 5, NULL, '2026-04-03T17:24:26Z', '2026-04-03T17:24:26Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('80b2f932-ca93-4ea8-a1a2-993c9537adba', '5a771f52-fe96-4ea2-b567-a8dde899059e', 3, 'Pawn or Bust', 'A bust of Marlon Brando has Rick making its owner an offer he can’t refuse ... or can he? It''s game on with the Pawn Stars when a Donkey Kong penny bank from the early 1980s barrels into the store. Rick needs to keep both eyes open when he spots a cyclops print made by a member of the band Devo.', '2017-10-23', 21, '/75VRLezNuLTPlDniQMVZvVsUBG5.jpg', '2026-04-03T16:34:21Z', '2026-04-03T16:34:21Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('80b8965c-8b5c-4267-bff8-f36909d6e9cd', '1a534647-384b-4c00-bb6c-a3371ad962eb', 33, 'Dangerous Deals', 'Take caution and revisit some of the most dangerous items that have exploded their way into the pawn shop including: a double barrel Coaching gun from the 1800''s, an extremely rare Let Mat Pistol, a $335,000 mint condition Gatling Gun, a pair of Soviet Missile Launch keys and a post Civil War parade Cannon that leaves the guys shaken but not stirred.', '2015-05-28', 21, '/ouoYLaCRagT3pLnpnVDZlZjurxz.jpg', '2026-04-03T16:34:19Z', '2026-04-03T16:34:19Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('80c65e26-9c3f-40ce-8315-3b791fd96414', '70c8cb46-2494-4dd4-98f6-6bfb9b3faf73', 4, 'Pezzed Off', 'The Pawn Stars have a chance to buy an extremely rare 18th century double-barrel coaching gun engraved with a mysterious golden script. Can they discover its true origins and make a deal or will the inscription hide its secrets forever? Then Corey and Chum meet an outspoken Pez collector looking to sell 50 pieces of classic Americana. Will Corey click out some serious cash for these collectibles, or will he get his sugar fix somewhere else? And later, a woman hopes to sell Rick a 1932 "S" Quarter - a rare version of the first Washington silver quarter introduced into U.S. currency. But Rick has questions about its authenticity, will this quarter be worth its weight in silver, or is it destined for a parking meter?', '2010-01-25', 21, '/1ISiP3mP5RSqiW89rB2MemVdK0w.jpg', '2026-04-03T16:34:16Z', '2026-04-03T16:34:16Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('80cca356-9139-40d3-a71e-973adfc46f07', '5a824218-5831-4c6d-aef3-8b5ba9147532', 16, 'Episode 1591', '', NULL, NULL, NULL, '2026-04-03T17:36:34Z', '2026-04-03T17:36:34Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('80cf7e8a-3adf-4741-b48c-6f52b01fac66', 'de052e8e-7dbd-454a-a6d8-b9afba6e9bfa', 29, 'The Cement Mixer', 'The Wombles get into trouble with some wet cement.', '1973-07-05', NULL, '/7Qo9lhuf3LTc7H6p8sb3uZGd6Wx.jpg', '2026-04-03T17:23:19Z', '2026-04-03T17:23:19Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('80d937e4-56ee-408e-bdb5-4af657ca2ade', '45e01c04-6ac6-41e1-87d8-f749ee230385', 15, 'Poorly Penny', 'On Fireman Sam''s day off the crew are inundated with the Jones'' emergencies. Firefighter Penny Morris has caught a cold, but she still tries to perform her firefighter duties. However, when the Joneses get stuck on Charlie''s boat, Penny''s illness takes hold while she is out on Neptune alone, and Sam has to come to the rescue.', '2008-02-27', 10, '/kkd7RlSWPVoqJwqo62kOEbfdUR2.jpg', '2026-04-03T17:14:38Z', '2026-04-03T17:14:38Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('80dc216d-0331-440f-acca-f98b2c96b75f', '19e027c7-8626-44a9-96ba-d36b323b3a74', 2, 'Wembley and the Gorgs', 'Wembley agrees with everyone, including the Gorgs, who decide he makes a great loyal subject.', '1983-01-17', 24, '/gavPDLa4EWTaffCMMINLAsSdrLI.jpg', '2026-04-03T17:34:59Z', '2026-04-03T17:34:59Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('80df2011-c545-4d33-b13f-7821c8dc1f81', '4892e2af-46c1-4b4e-ac81-eac161b5a347', 56, 'Episode 56', '', '1978-03-30', NULL, NULL, '2026-04-03T17:21:53Z', '2026-04-03T17:21:53Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('80e1299d-1943-4a94-a072-8169e9f36d95', '0fb5ce65-0258-4423-be8a-f7ba9c37bb6b', 13, 'Beaver Blackout', 'Beavers cause a blackout in Pontypandy, and Dilys is unsure what to do with her freezer supplies.', '2023-11-01', 9, '/63t0uO9CZTYlwinvuxnbP3d2Q5K.jpg', '2026-04-03T17:14:42Z', '2026-04-03T17:14:42Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('80f026a2-b7a1-40f0-bfce-e88c6a755fab', '05c0e384-194c-4417-9f62-803eb615e409', 20, 'How windmills work', 'Title number 0020. Opens with Mister Rogers arriving with a model windmill and talks about how windmills work. Judy Rubin, the “Art Lady,” shows some windmills made by children. She and Mister Rogers make windmills of their own. In the Neighborhood of Make-Believe, Daniel tells Handyman Negri he thinks that King Friday is afraid of Donkey Hodie''s biting. Maybe that''s the reason the King won''t allow Donkey Hodie to put his windmill near the castle. When Donkey Hodie convinces the king that he doesn''t bite anymore, the king changes his mind.', '1968-03-15', 28, NULL, '2026-04-03T17:35:38Z', '2026-04-03T17:35:38Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('80f79483-9810-4650-a107-765612aaaeb6', '24003c6d-d919-4616-a7dd-0d38bb7a0656', 14, 'Bus', 'Pat sees the Oxford open-top tour bus and goes for a ride on it.', '1996-07-19', 10, NULL, '2026-04-03T17:19:37Z', '2026-04-03T17:19:37Z');
