INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('81035365-d25b-4e9a-8193-e488c3240913', '97616d6e-5c17-449f-a376-55f1da83d6c3', 7, 'Mister Rogers Talks to Parents About Pets', '', NULL, NULL, NULL, '2026-04-03T17:35:42Z', '2026-04-03T17:35:42Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('81064b32-e5b6-4d74-9e89-137da4158769', 'd199804f-ccf5-4e36-8929-56c1e356b74d', 25, 'Episode 950', '', NULL, NULL, NULL, '2026-04-03T17:36:32Z', '2026-04-03T17:36:32Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('810afaf0-163e-40ae-a3d7-e2a25b222a67', '91c151d9-8497-4056-a4ee-753cdcb08cea', 5, 'Episode 1460', 'A light in the traffic light has burned out and Mister Rogers arrives with a replacement. After replacing the bulb on the green signal, he spends some time talking about crossing the street safely.

In the garage, Mister Rogers shows a recording of a time when Francois Clemmons took him to see the police station. When the clip is finished, Francois Clemmons stops by dressed in his police uniform and sings songs from various Neighborhood operas.

In the Neighborhood of Make-Believe, Lady Aberlin and Grandpere look into the future to see that Collette has married Daniel Striped Tiger. At the tree with Officer Clemmons and X the Owl, Lady Aberlin learns that X has become a professor at Owl Correspondence School. Meanwhile, Lady Elaine Fairchilde has gone to discover new planets, just as her future vision has suggested.', '1976-02-20', NULL, NULL, '2026-04-03T17:35:41Z', '2026-04-03T17:35:41Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('810c12ab-7564-40c4-8961-f9662e8200ae', '51c41996-c452-4a28-b174-3765855be794', 4, 'Alike and Different', '', '1987-11-26', NULL, NULL, '2026-04-03T17:35:44Z', '2026-04-03T17:35:44Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('811ac779-755c-47a2-a2f3-738f9534e6a3', '05c0e384-194c-4417-9f62-803eb615e409', 38, 'King Friday meets Sara Saturday', 'Title number 0038. Opens with Mister Rogers arriving with a bicycle handle. Mr. Rogers demonstrates exercises by using a stationary exercise bicycle and free weights. He then sings "I Like You As You Are". Lady Betty Aberlin tries out the exercise bike. In Make-Believe, Sara Saturday, who had been the damsel in distress a week earlier and frightened by the monster, is welcomed to the Neighborhood of Make-Believe. Lady Aberlin sings "Then Your Heart Is Full Of Love".', '1968-04-10', 30, NULL, '2026-04-03T17:35:38Z', '2026-04-03T17:35:38Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('811ba661-a92b-4605-a974-a7e02491c65a', 'e1ef357b-4edf-412a-a785-7060c0e33bd2', 3, 'Madeline and the Dinosaur Bone', 'A paleontologist comes to the Old House after Genevieve digs up a huge bone in the garden, which turns out to be a fossilized stegosaurus hip bone.', '1995-09-23', 30, NULL, '2026-04-03T16:34:02Z', '2026-04-03T16:34:02Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('811bc842-7106-42d6-93bd-b2c7f8838552', '793a6b2c-7cad-4f12-a943-74729e3d9ca6', 11, 'DELETE ME', '', NULL, 5, NULL, '2026-04-03T17:24:24Z', '2026-04-03T17:24:24Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('8127a66c-bda6-41b1-8969-3a69693ed62e', '97a3d1f5-a8f1-47cd-8122-2e74a092836d', 11, 'Just in Time (3)', 'Frank and Catherine learn that the brush salesman might have been a con artist. Jamal''s dad is getting sick. The team learns that Frank and Catherine helped catch the thief years ago but history will change if they don''t send the information soon.', '1993-11-17', NULL, NULL, '2026-04-03T17:40:28Z', '2026-04-03T17:40:28Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('812ea7e0-5c9f-49d8-b594-e7a13d9ce00d', 'fb06e658-4b54-4682-8783-eaa88a99e61e', 8, 'The Tardy Tumbler', '', '2014-10-02', 13, NULL, '2026-04-03T17:38:01Z', '2026-04-03T17:38:01Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('81302b49-befa-42de-9497-5b8fa9759b18', '68138de2-0900-460a-b58e-480688f1e081', 15, 'Change Is In The Air', 'Since Bear''s friend Ursa has never seen the Big Blue House, he''s decided to take some pictures of things around the Big Blue House and make an album to send to her. As he searches for good opportunities, he finds that the kids of the Big Blue House are curious about his camera. Tutter seems to keep popping up whenever he tries to take a shot in the kitchen, so he finally has Tutter pose for a photo. The other kids have their photos taken as well. Treelo is a bit reluctant because he doesn''t understand how the camera works and is worried he''ll be sucked into it. While taking everyone''s photos, Bear also notices that his camera seems to keep disappearing, but by the time he looks for it again, it''s back where it was. In the Shadow segment, Shadow tells an unusual version of the traditional "Roses are Red" poem. It ends with an alligator eating a pair of blue-suede shoes. 

Songs 

■Picture This 

Notes 

■Ursa later sees the Big Blue House in person when she surprises Ojo for her birthday in "You Never Know."', NULL, 25, NULL, '2026-04-03T17:35:31Z', '2026-04-03T17:35:31Z');
