INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('815328ce-86f7-4ffe-a5cf-331ba90c13b4', '99202760-98d0-4dda-ab20-48d2b5c65987', 4, 'Total Rickall', 'Trapped inside the house with an ever-increasing number of parasitic alien shape-shifters capable of altering memories, an uncertain Rick and the Smiths search for a way to determine which of them are real.', '2015-08-16', 22, '/xVQqoLFSCzFtKp0OkW4PGPc7NtB.jpg', '2026-04-03T15:40:41Z', '2026-04-03T15:40:41Z');
