INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('81b0b451-d23e-4a89-9d1e-171bb5d9e97c', 'abeb8d07-5c86-4f6a-a110-b11cba2a4138', 8, 'The Puppetmaster', 'The gang investigates the bizarre disappearances taking place within an eerie town.', '2007-11-09', 25, '/d1ECriFq8qpttMnHwrAVewSq6IF.jpg', '2026-04-03T17:40:48Z', '2026-04-03T17:40:48Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('81b1aaa5-6838-42df-b601-d3833eb938da', '8b6bbac8-e5ef-49c7-a5c1-197cfb19f772', 14, 'Mister Rogers Talks About Play', 'Mister Rogers visits an underground mushroom farm to see how mushrooms are grown. In Make-Believe, King Friday is reconsidering his "no play" rule, and Lady Elaine Fairchilde is enjoying her freedom to play at a real playground.', '1981-07-23', NULL, NULL, '2026-04-03T17:35:42Z', '2026-04-03T17:35:42Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('81bd2bba-b614-4abc-8b48-d7aec7eaef96', 'c01ddd2a-bdb1-4c97-8d04-58f791ef1c24', 30, 'Jumpers', 'Zoboomafoo welcomes his fellow jumping animals to Animal Junction, from kangaroos to frogs.', '1999-07-01', 27, NULL, '2026-04-03T17:10:55Z', '2026-04-03T17:10:55Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('81c03dc5-ce48-43e4-9ea1-8f6a06cd379a', '58adb9ab-3f1b-4a11-87b6-9b0b2dbb6aaf', 17, 'Frontier Fortune', 'Strum along with the Pawn Stars when a Gibson lap steel guitar jams into the shop. Will Rick rock out an offer or will he be playing a different tune? Next, a letter from pioneer Ezra Meeker and a set of commemorative Oregon Trail coins trek on in. Will Rick pay a frontier fortune or will the deal fall off the wagon? Then, the smell of tobacco fills the air when a Victorian snuff box shows up. Will Corey sniff out a sale or will he strike it down? And later, colonial bone dice from The Stamp Act of 1765 roll in. Will Rick throw the seller a bone or will he revolt against the deal?', '2017-06-26', 21, '/5qywut5C7GHWw8IqPo3qI4XYm2W.jpg', '2026-04-03T16:34:21Z', '2026-04-03T16:34:21Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('81c96b4b-6aab-4670-9d71-1659371d3a7d', 'b2317fc3-1cfc-4f19-b181-effa23959c6d', 16, 'Reunion (3)', 'As the house husbands join the women, new secrets are revealed about Luis, Bill, Evan and the state of Dolores'' relationship with her new boyfriend; Joe and Melissa spar with Jennifer; Teresa and Margaret reach a breaking point.', '2022-05-17', 43, '/zj8BFTPuPfQhrdEOj1iL1tq9nW7.jpg', '2026-04-03T16:35:18Z', '2026-04-03T16:35:18Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('81d67e0e-df6c-435c-b04a-a5b44ac1cdce', 'ba99b779-cada-43a7-902a-2adb472c2e30', 4, 'Episode 4', 'The first two thirds of this episode are a wonderfully crafted and tense escape sequence with the rat catcher on the job and poisonous gas being pumped into the wall cavities. The last third sees our family out in the big wide world, and when you are only 15cm high the world is very big indeed.', '1992-11-29', 30, NULL, '2026-04-03T17:17:47Z', '2026-04-03T17:17:47Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('81d748b6-66c3-4c2e-99a3-cad295366ae5', '684af21e-0459-4832-b094-db0997e354c5', 15, 'Healing Hole', 'Relationships are on the chopping block as the women return from Bimini with new-found confidence and a desire to turn their lives around.', '2012-12-20', 44, '/wBeB3eTvs5kepM1qpY28M6LmXQH.jpg', '2026-04-03T16:35:10Z', '2026-04-03T16:35:10Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('81d81fcc-7b7f-46c2-8390-7863a8db69cb', '6fd9fd9d-e378-411b-94b1-76ba4bd518fe', 54, 'Episode 54', 'with Christopher Trace, Valerie Singleton and John Noakes.', '1966-03-28', NULL, NULL, '2026-04-03T17:21:48Z', '2026-04-03T17:21:48Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('81d923e1-4306-4860-a4f8-fb7ab3527486', 'b054aff3-548c-4f56-b372-b1ea26613abb', 2, 'Mister Rogers Talks About FRIENDS', 'Mister Rogers arrives with a piece of string which he takes to the front porch along with a pan full of soapy water. By tying the string into a loop, he is able to bring it out of the water and use it to make bubbles. As Mister Rogers is making bubbles, Mr. McFeely arrives and invites Mister Rogers to join him on a visit to Betty Aberlin''s house.

At Betty Aberlin''s house, she, along with Mister Rogers and Mr. McFeely, watches as Mary Jo Barron sings songs with a small group of children. While everyone else enjoys a snack, Mister Rogers and Ms. Barron spend some time talking with each other about working with children.', '1982-11-16', 30, NULL, '2026-04-03T17:35:43Z', '2026-04-03T17:35:43Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('81d97f43-021c-4cfa-b033-2145bea4fad4', 'f21ca545-466c-448c-ada5-b8acc8b856dc', 8, 'Tee Time', 'Bernard uses his watch to help his Dad in a game of golf – but is this wise?', '1999-11-12', 15, NULL, '2026-04-03T17:20:05Z', '2026-04-03T17:20:05Z');
