INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('823d8dfc-be79-444e-869a-45e853c1e6b5', '5db3ff78-e439-48e1-8f67-988ecbf85d17', 26, 'Dogtanian''s Dream Comes True', 'Dogtanian, Pip and The Three Musketeers have sailed back to France from Spain, Juliette is there eagerly awaiting Dogtanian''s return. Cardinal Richelieu, Count Rochefort and Captain Widimer are discussing Dogtanian''s return and how to get him, Widimer suggests poison - to the disgust of Rochefort who believes in the Cavalier''s code of honour. Richelieu likes Widimer''s plan and tells him to do it behind Rochefort''s back, if he succeeds he''ll become Count Widimer. Dogtanian is handing out gifts when Rochefort knocks on the door, Planchet goes to answer but only finds a note on the doorstep. The note challenges Dogtanian to a duel and warns him of Widimer''s plan...', '1982-03-26', 24, '/wl1lWmfQ7wp3b8W4jjZK3OEmnCj.jpg', '2026-04-03T17:18:43Z', '2026-04-03T17:18:43Z');
