INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('82515c67-ceaf-409a-b919-1dbeb8639184', '61e0c9d9-337e-4fe4-a0fd-e567b29af115', 16, 'When All Is Said and Done', 'On their final day in Mexico, the ladies surprise Lisa with a Lisa-themed lunch, but things take a turn when Whitney finally pushes Lisa to her limit. Mary reveals her frustration with Angie after feeling disrespected and betrayed. The women come together for a beautiful private dinner where Heather''s attempt to help the women move forward goes horribly wrong.', '2025-01-15', 43, '/is7UaL6Naf8Di8Z2xgz7N9pHTvE.jpg', '2026-04-03T16:35:45Z', '2026-04-03T16:35:45Z');
