INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('83201024-39de-4bc7-bbd4-c1557190f7fd', 'c7994637-b7c7-42c7-aaee-1bff4144fe23', 9, 'A Feisty Fiesta', 'After enlisting a matchmaker, Sutton tries her not-so-steady hand at dating. Annemarie reveals which first impression left a bad taste in her mouth. Dorit is shocked at how far Kyle has waded into a new friendship. Tensions flare at Crystal''s Taco Tuesday between Dorit, Sutton, Crystal and Garcelle. Erika comes to a boiling point with Denise.', '2023-12-20', NULL, '/tw8cWIVw0trlIWK4KeWKrpbwOEq.jpg', '2026-04-03T16:34:59Z', '2026-04-03T16:34:59Z');
