INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('833eb0c7-5b6c-4934-b988-2f64d4e1f304', 'a0fa5075-9ce1-48c1-9995-0c0fd866e549', 8, 'A Perfect Storm Out', 'Bozoma hosts a healing spa day for the ladies that proves to be anything but serene. Garcelle receives a long overdue apology. Kyle is confronted with mounting suspicions over her friendship with PK. Sutton takes issue with Kyle’s stormy escape. Dorit feels betrayed by Erika’s loyalty to Kyle, leaving Erika caught between two friends.', '2025-01-21', 43, '/lSIkvJYXwlS6nuuLjtu5PPBpLMx.jpg', '2026-04-03T16:34:59Z', '2026-04-03T16:34:59Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('83437fb4-d899-468e-881f-a1b997117ca8', '6f731e6b-d3c5-4de6-84e1-7a19cb650e86', 29, 'Blockbuster Buys', 'Break the bank with the Pawn Stars and look back at some of the priciest items in the shop''s history: a $70,000 Panama Pacific gold coin from 1915, a Hydro Jetpack that sends Corey sky high, rare artwork from graffiti sensation Keith Haring and an exclusive Hertz Penske GT Mustang with an $85,000 asking price that has Rick burning rubber.', '2016-03-30', 21, '/m1W2Fz9FYKZL1mTeTeRJ9AYY6kb.jpg', '2026-04-03T16:34:20Z', '2026-04-03T16:34:20Z');
