INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('8365d6c5-1e7c-478a-9b22-d2e8f0217322', '8bdf0ad3-a798-4d5a-b304-c7501eae6867', 10, 'The Girls Want To Come Out And Play', 'Vicki Gunvalson and Jeana Keough take a road trip to Chicago to visit Vicki''s friends from high school and former housewife Kimberly Bryant. Jeana and Vicki attend Jeana''s son, Shane''s, baseball game in Kane County, IL. When Shane mistreats Jeana before and after the game, Vicki and Kimberly defend their friend.

With Jeff still in the hospital and her future uncertain, Gretchen Rossi looks to secure her financial well-being. Tamra Barney invites her brothers over and they talk about their feelings regarding their parents'' divorce. Meanwhile, Tamra''s mother finally undergoes her facelift.

Lynne Curtin decides to throw a cocktail party for the ladies. At the party, Lynne''s unruly teenage daughter, Raquel, helps herself to the bar.', '2009-01-27', 44, '/8H5iGWyW3C5dd2zLKrM8jwbxUCc.jpg', '2026-04-03T16:35:30Z', '2026-04-03T16:35:30Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('836663b6-457c-4949-b2c9-c57f129caace', '7c0e1f66-8835-4e8a-8ad9-0eee57155b4c', 2, 'The Legend So Far', '“The Legend So Far” is an eleven-minute-long recap episode of “Avatar: The Last Airbender” narrated by James Garrett, the voice of Avatar Roku. In this recap, Roku retells some of the events that have occurred in Aang''s journey before episode eighteen, “The Waterbending Master”, and provides a sneak peek of the episodes still to come. It served as an introduction to the three-part Book One finale, which began with the episode “The Waterbending Master”.', '2005-11-18', 12, '/imCl0txmn64itMUt2vFaQCv0Syw.jpg', '2026-04-03T17:40:47Z', '2026-04-03T17:40:47Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('83691817-237d-4042-96e8-cf9e035f33a3', 'e03d79bd-e01f-4414-b0b3-f3b5f26e97f4', 19, 'The Legacy', 'Mike punishes Axl by forbidding him from playing in the last basketball game of the season. Meanwhile, Brick begins wearing his cousins hand-me-downs, and Sue wins a trophy.', '2011-07-22', 22, '/yXgTW3tdTtfetGKGi5TQVHBLmk3.jpg', '2026-04-03T15:40:29Z', '2026-04-03T15:40:29Z');
