INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('83b86ad4-8904-44ca-8076-60ff99844aa9', '2dcbd122-86d8-46e8-bbe5-9143875abd34', 9, 'The Blizzard', 'A blizzard strikes Elwood City and all the kids have to return home. But before they do, they have to hand in their reports. Francine does not finish so she has to write a longer report over the snowstorm days while the adults are scrambling all over the city, losing electricity and supplies.', '1999-10-11', 13, '/t70CvzIRjZuqAqOeDUwpC2jTc4J.jpg', '2026-04-03T17:37:56Z', '2026-04-03T17:37:56Z');
