INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('8483f308-665f-4760-83b4-d9397001b27d', '2dadbc6b-684f-4884-a0b2-57bda7546dc2', 12, 'Play Time', 'Lucy is acting in the school play, but shortly before opening night, the leading male injures himself. The play may have to be cancelled, as no one can understudy in such a short time. That is, unless they happen to have a magic watch...', '2000-12-08', 15, NULL, '2026-04-03T17:20:05Z', '2026-04-03T17:20:05Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('848464db-4abe-4d37-b79a-db2155bf5269', '3430d881-14a2-497d-9cf4-351b78b6aa6a', 1, 'Postman Pat and the Hole in the Road', 'Mr Pringle has been teaching the children about volcanoes and earthquakes. The next day this makes Pat think about holes in the road. While on his rounds, he gets diverted round in a big circle. PC Selby lets all traffic pass through Thompson Ground. Ted gets ready to mend the hole with tar.', '1997-04-03', 15, '/56YvoMZBRdMrPbC394HBzyxo9bi.jpg', '2026-04-03T17:14:30Z', '2026-04-03T17:14:30Z');
