INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('84b1efb6-1095-4a7a-a564-65fa079e31b5', '5b72e664-d3d7-435d-bdc3-a23d29d1178e', 8, 'The Play', 'Old Bear is reading a story to his friends in the garden when Jolly Tall gives them the idea of putting on a play. The toys make a stage on the grass and perform their own, rather special, version of ‘Goldilocks and the Three Bears’. Little Bear doesn’t want to be ‘Baby Bear’ until he realises there will be real porridge in the play. With Rabbit as a rather over-enthusiastic Goldilocks and three bowls of porridge on the table, just about anything could happen.', '1994-10-24', 10, NULL, '2026-04-03T17:18:55Z', '2026-04-03T17:18:55Z');
