INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('8505b21d-8c18-40e5-a7f0-dc1bc9d24cd3', '3087a3ed-e94e-4276-9d02-a78183dea1d3', 9, 'Dress Down and Strip Bare', 'With the ladies back from romantic Anguilla, relationships are tested and this time it''s not only Kenya and Walter in the romantic hot seat. Divorce rumors swirl around Phaedra and Apollo, while Kandi and Todd’s relationship moves forward when they receive a visit from their pastor. Kenya continues to investigate whether her man is serious about love and NeNe gets the money shot in the cover shoot of a lifetime.', '2012-12-30', 43, NULL, '2026-04-03T16:34:46Z', '2026-04-03T16:34:46Z');
