INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('8519ad21-32f3-47b5-96f6-ba6892d73c25', 'ca19f895-1514-4988-a709-95e84eab7cee', 19, 'Off the Rails', 'When Chum gets his hands on a trio of vintage comic strip characters, will the seller play with his emotions, and toy around with a deal? Next, a book by Amelia Earhart flies into the shop. Will Rick dare to make a deal, or will the price soar too high? Then, a pair of "Romeo and Juliet" sculptures hits the counter. Can Chum play a part in the negotiation before it turns tragic? And later, the guys take a trip to meet up with Spencer at the Glamis Sand Dunes to check out a one of a kind sandrail. Can Rick drive home a deal, or will he be left in the dust?', '2021-08-14', 42, '/rh0MtDkaPSd8o8qrVLXPcKqZaUB.jpg', '2026-04-03T16:34:22Z', '2026-04-03T16:34:22Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('851ddd2c-2c79-4b92-80ad-6fa836f00055', 'f5c042dc-0657-42e8-a37d-247414140632', 4, 'Whine Connoisseurs', 'D''Andra plans a day trip to a winery to celebrate Brandi''s birthday, but when Kary criticizes her planning skills, the two of them nearly come to blows. Tiffany gives her daughters a glimpse into her life as a doctor, Kary checks in with Olivia about her depression, and Stephanie bonds with her mom after making a surprising bet with Travis.', '2021-01-26', NULL, '/riuPBPbUVcwm4JP5Ki9wRtbbX6i.jpg', '2026-04-03T16:35:05Z', '2026-04-03T16:35:05Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('851f311c-28a8-44ae-a324-59b746cc151f', '331fc1df-6d70-4d79-b585-bf28024a4124', 7, 'Best Foot Forward', 'Norman Price goes mussel collecting with Charlie, Sarah and James. He attempts to get the most mussels, but ends up getting his foot wedged between two rocks.', '2008-11-19', 10, NULL, '2026-04-03T17:14:39Z', '2026-04-03T17:14:39Z');
