INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('85447475-d8d1-45f6-a470-1a3db30665c0', '5b5e8b2f-0a85-4488-b3dc-3d8b794e6582', 7, 'Un-Noble Women', 'Lydia is hopeful everyone can get along for her magazine''s launch party; Tamra struggles with the scars of her broken family; Tamra thinks Peggy is overstepping her bounds, and things end up not so noble at the Nobleman launch party.', '2017-08-21', 44, '/wjEygQzwvu78xseADFVnSWhs2UG.jpg', '2026-04-03T16:35:33Z', '2026-04-03T16:35:33Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('85471ab0-cea8-4765-b4a9-82a8edaa8bac', 'ae8f64d9-4b83-4147-a44c-bfe720381f8e', 17, 'Squirmadega Car Race', 'Slimey is practicing for the Squirmadega Car Race. He zooms forward, backward, and around and around on the counter of Mr. Hopper’s store. Elmo excitedly gets ready to watch Slimey in the worm car race. Elmo is Slimey’s biggest fan and cheerleader!

The worms’ race cars line up as the sportscaster, Jeff Gordon, introduces the five race car drivers. Elmo cheers! Jeff Gordon discusses the race course. The worms must drive over the laundry basket, under the table and around the fire hydrant to win the race. The worms start their engines and take off! Cars #1, #2, and #3 lose control and are quickly out of the race, but Shawna Wiggleson in Car #4 and Slimey in Car #5 are still going. It’s a close race! Slimey approaches the finishing line, but gets caught in Big Bird’s toes. Shawna pulls ahead and wins!

Elmo is very sad and disappointed. He wanted Slimey to win and thinks Slimey’s sad because he lost the race. But Slimey is happy; he loves racing whether he wins or loses and he loves to practice, too. Elmo learns all that really matters is that Slimey did his best. And so did Elmo! He did a great job cheering Slimey on!', '2009-12-28', NULL, '/1bNi4kApDWldUX7A5YXhuFJorqt.jpg', '2026-04-03T17:36:46Z', '2026-04-03T17:36:46Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('854761d4-b9a9-4498-8080-6e746ff1f42f', '1996ddd8-20c9-4a30-96be-2b87fab8d17c', 32, 'Building Bridges (2)', 'Miss Kelly considers canceling the talent show but the students convince her not to. Rob learns the reason why Victor left his gang but then more vandalism occurs.', '1993-05-02', NULL, '/hHUraxs4yxMipM3ZPVyi2UMBHn8.jpg', '2026-04-03T17:40:28Z', '2026-04-03T17:40:28Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('854834ff-7a9d-4d02-a1df-d5762ca9ad2b', '7b19039a-31ac-425c-8fb1-b51cf2447821', 12, 'The Unmasking of Elizabeth Vargas', 'As the ladies continue to enjoy their getaway in Lake Arrowhead, Gina and Kelly attempt fly fishing while Elizabeth discloses her deepest, darkest secrets to Braunwyn. Back in the OC, Shannon calls the ladies with surprising news and Emily welcomes home Shane from the hospital. Braunwyn struggles with the state of her marriage, and Kelly, Rick and Jolie settle into suburban life.', '2020-12-30', 44, '/1ynUIj2yucH3GRRmVSYQYmJd0KV.jpg', '2026-04-03T16:35:34Z', '2026-04-03T16:35:34Z');
