INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('85512496-4e1c-4299-9bff-d912746c2e9c', '4b2a19e0-2fae-492e-bc31-f78e63d88ebc', 3, 'Pawn Halen', 'All hands on deck with the Pawn Stars when a set of 1814 naval history books from John Adam''s personal library sails into the shop. Will Rick anchor up to a deal or will he throw them overboard? Next, an electronic cigar box guitar signed by the legendary frontman Sammy Hager rocks in. Will Rick think it''s red-hot hit or will he cancel the tour? Then, a 1901 coin sorter comes into the shop. Will Chum count up an offer or will he get rid of the loose change? And later, Rick rides out to see his restored 19th century racing sulky. Will he think it''s a two-wheeled winner or will he gallop out the door?', '2016-08-10', 21, '/6tWMbKPtSmXerGWDaiBwsjuWe8i.jpg', '2026-04-03T16:34:20Z', '2026-04-03T16:34:20Z');
