INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('85565067-deb1-4c1a-99dd-44b50dddb661', 'b2317fc3-1cfc-4f19-b181-effa23959c6d', 9, 'There’s No Crying in Softball', 'As Dolores hosts a charity softball event, Gia gets involved in Margaret and Teresa''s fight. And, Jackie discovers a problem with Evan while Jennifer and Bill''s marriage reaches a breaking point.', '2022-03-29', 43, '/gxs2IJeCHXj4LKfitE70a7PNeD7.jpg', '2026-04-03T16:35:18Z', '2026-04-03T16:35:18Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('8556dfdc-6e16-4acb-abfb-f868fc5294ea', '6fd9fd9d-e378-411b-94b1-76ba4bd518fe', 68, 'Episode 68', 'with Christopher Trace, Valerie Singleton and John Noakes.', '1966-05-16', NULL, NULL, '2026-04-03T17:21:48Z', '2026-04-03T17:21:48Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('855ab786-d753-48b9-a63f-06754b1d2cc9', '90d7a60c-d72f-4aea-89c0-81dc1e187efe', 7, 'Last Waterholes of the Outback', 'Steve travels to the Australian Outback to show us the last remaining major sources of water in this dry area. Animals are saltwater crocodile, freshwater crocodile, brown tree snake, tick, frill neck lizard, cattle and kangaroo.', '1998-08-16', 44, NULL, '2026-04-03T17:39:11Z', '2026-04-03T17:39:11Z');
