INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('85741cf1-4699-453f-861c-d51ffabff172', '262e8e7c-fa78-4578-a216-add6f184c4d2', 9, 'No Place For Home', 'Kody, Meri and Robin realize that there are no polygamist houses to be found in Las Vegas; a surprise birthday party for Meri.', '2011-05-15', NULL, NULL, '2026-04-03T16:34:27Z', '2026-04-03T16:34:27Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('85747e25-9e2a-4db8-bd5c-82ce7710c784', 'e40e6b63-9f84-449f-8e88-53209b0906c8', 9, 'Sleeping Grouchy', 'Oscar and Grundgetta are reading The Tale of Sleeping Grouchy" and Slimey, Telly and Elmo join them. The story begins, "Once upon a time, there was a very, very, very grouchy princess . . ." and it tells the tale of a princess that was so grouchy, she said things like, "Phooey!" "Ewwww!" and "Sounds horrible!" One day the grouchy princess was on a grouchy walk. She said, "Phooey!" so many times that it disturbed a wizard who was walking nearby and he cast a spell on the her, putting her to sleep for a hundred years! Princess Grouchy''s parents were very upset. They loved their grouchy daughter dearly and wanted to find a way to break the sleeping spell. They offered a reward to any prince who could wake the princess up. Prince Elmo came and tried to tickle Princess Grouchy awake with a feather, but it didn''t work. Prince Telly played his loud tuba with his back-up band, The Cat''s Meow, but Princess Grouchy still did not wake up. Finally, Prince Slimey arrived.', '2007-08-29', NULL, '/2NW5tVpaW2Vdhhh0O5y09c9WCX1.jpg', '2026-04-03T17:36:45Z', '2026-04-03T17:36:45Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('857a964d-5456-4b6b-9b9f-ce6eb22316e7', '319bd5d6-ff58-426f-b9da-a0bb2cb87b02', 2, 'Space Exploration', 'Space is hard to explore, because it’s really, really big. Most things in space are so far away that people we build special equipment just to see them. We use telescopes to magnify far-away solar systems, planets, and stars. Rockets send astronauts past the Earth’s atmosphere. Space probes with special cameras send back pictures of planets for scientists to study. Astronauts perform experiments in orbit around the Earth. We do all these things and more to learn more about our universe.', '1997-09-26', 26, '/99eo9VpOaKNbr5uSGTNTXMkJqKf.jpg', '2026-04-03T17:37:22Z', '2026-04-03T17:37:22Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('857d6aa2-a754-4b1e-b75c-55127ef33e4f', 'bb919aec-0d5c-4c58-9a5a-fa2a0a5de2b6', 66, 'Episode 471', '', '1973-02-26', NULL, NULL, '2026-04-03T17:36:30Z', '2026-04-03T17:36:30Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('857f1d35-2cff-4685-a117-b5036431e6b0', '1be79a20-de33-41d1-af17-079035b18d5c', 115, 'Gordon, Susan, and the Kids Go On An Imaginary Car Ride (0115)', 'Kermit sings the original "Being Green".  Ernie and Bert perform the classic "Banana Telephone" skit, Muppet Roosevelt Franklin sings "I''m Roosevelt Franklin", Bob sings an early version of "Who Are The People In Your Neighborhood?" plus Cookie Monster eats Ernie''s cookie, and Oscar calls "Dial-a-Grouch".', '1970-04-17', NULL, '/rdKogWW52J2G5UbAtVg1JMuSjK8.jpg', '2026-04-03T17:36:28Z', '2026-04-03T17:36:28Z');
