INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('8584051b-e34c-4873-89e3-65575fe5d84c', '4f18ac4c-8757-456c-a49a-224f00e6a9f7', 13, 'Abby Thinks Oscar is a Prince', 'Chris reads Abby Cadabby “The Frog Prince”, which she anxiously waits for the ending of. Chris finishes the story and Abby loves it. As Abby walks down the street, she finds herself amazed that a frog of all things could be an enchanted prince. While Oscar deals with a man with some trash behind her, Abby wonders if some on Sesame Street could be a prince. She sees and Oscar and gets the idea that he may be an enchanted prince!', '2008-10-07', 58, '/hPOSBwe1WN1Rw65NJdjy8JopLfE.jpg', '2026-04-03T17:36:45Z', '2026-04-03T17:36:45Z');
