INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('85a43153-d0f8-43e4-8481-f009815830ef', 'de8ec769-16bb-436b-be43-aedc7e18a7d7', 13, 'A New Friend on Sesame Street', 'There''s a new face on Sesame Street! With Elmo and Rosita’s help, military kid Charlie finds her way around the neighborhood and learns that Sesame Street is a place where everyone can be friends - no matter how different they are.', '2020-02-08', NULL, '/df4wf0tmLcpG80NkaZYzKzoaMJY.jpg', '2026-04-03T17:36:50Z', '2026-04-03T17:36:50Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('85a68430-6d8a-4cc7-8013-6b8c55a2b231', '244b0a34-284b-4ec1-b3a7-0e5abff6d0d1', 3, 'The Silent Treatment', 'George wonders whether anyone would notice if he just disappeared, and so vows not to speak until someone notices him. Of course, his friends do notice, and they decide to cheer him up with a surprise party.', '2009-10-13', 13, NULL, '2026-04-03T17:37:59Z', '2026-04-03T17:37:59Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('85bc9d1b-dc83-48f9-ad7b-a800ba63c66d', '8bae6aa3-4b55-4fa6-bc15-8f4317bd1f13', 36, 'Lady Elaine Flies into Space Pt 1', 'Rogers makes a crayon rubbing of leaves. Mrs. McFeely invites him to their house to see a fern and a reptile called a caiman. In the Neighborhood of Make-Believe, Lady Elaine is still thinking about space travel. She sends Mrs. McFeely for leaves on which, Lady Elaine thinks, she can ride to Jupiter.', '1972-04-10', NULL, NULL, '2026-04-03T17:35:40Z', '2026-04-03T17:35:40Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('85bccbd0-7397-4b7b-9d27-adf3630f4497', 'eb7e3bb4-5746-4577-81c6-f5b2dc2efc6e', 8, 'The Chase', 'Tired from trying to escape a machine that shows up every time they try to sleep, Aang and the gang have to escape Azula and her team, but their exhaustion leads to a tight situation. Meanwhile, Zuko must deal with something personal, and Iroh bonds with an unlikely individual.', '2006-05-26', 25, '/jM4D3ngfBqV1VzQeHKOadjT4qxG.jpg', '2026-04-03T17:40:48Z', '2026-04-03T17:40:48Z');
