INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('8612b015-feb9-4660-9652-6e3b4490e31f', '5b2c9365-7bd9-4ca1-a3fb-15f1a024a56e', 8, 'Reunion: Watch What Happens', 'Andy Cohen hosts a reunion edition, featuring the New York cast recapping Season 1 highlights and lowlights. Addressed: the dynamic between Jill and Ramona; and Bethenny''s romantic dramas.', '2008-04-22', 60, '/p7LAfMdx0nplJleHrcFR9tnJKqW.jpg', '2026-04-03T16:35:21Z', '2026-04-03T16:35:21Z');
