INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('869018d0-12c0-4dce-9e4a-c30cb90df472', 'dec4a06d-731b-41e4-8b15-374f47d1f5c7', 14, 'The Importance of Being Family', 'Teresa tries to stay strong as she bids adieu to her husband, who begins a prison sentence. Meanwhile, Siggy visits the Holocaust Memorial and reflects on her father''s experiences, and a possible ray of hope shines on Jacqueline and Teresa''s friendship.', '2016-10-16', 43, '/fPaQmey9HUU4uCJqr6qX3Idrvxu.jpg', '2026-04-03T16:35:16Z', '2026-04-03T16:35:16Z');
