INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('86aa177f-4e3c-42f1-99c9-620b2899b90d', '095258d0-d8db-4096-8ac7-6a42cd4cbdcf', 7, 'Home Is Where The Trash Is', 'Philo and Gunge are sick and tired of being around Marjorie, so they decide to go off and find their home. The only problem is, they don''t know where they originally came from. After a failed attempt to live in Mokey and Red''s room, they travel far away, were caught and made slaves of Wander McMooch, the Trash Heap''s biggest enemy. When the Fraggle Five see that Marjorie is becoming weak without her rodent duo, it''s up to Gobo, Mokey, Wembley, Boober and Red to save Philo and Gunge from McMooch before it''s too late.', '1985-02-11', 24, '/phdQaopEdm9dcd4QoYbmFOZmlfd.jpg', '2026-04-03T17:35:00Z', '2026-04-03T17:35:00Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('86ab43f7-d3e8-4da7-9100-cb4d35a390a4', '02849655-bd95-4d8d-af3b-03321918eeee', 20, 'Madeline''s Valentine', 'Madeline and the girls become extremely jealous when lovesick Genevieve falls in love with a neighborhood dog, but in the end, Madeline helps the girls realize that Genevieve has plenty of love to go around.', '2001-01-17', 30, NULL, '2026-04-03T16:34:02Z', '2026-04-03T16:34:02Z');
