INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('86bb7bba-000e-4387-ac75-e398b09b42af', '787dfa0b-c827-4dad-a82d-0548a6534d88', 16, 'Suspicious Minds', 'Shannon''s Aries party continues with Vicki and Brooks making an early exit leaving the other ladies questioning Brooks'' behavior and Vicki''s involvement. Heather and Terry disagree over a design for the new house, while Tamra shows her son Ryan his new home in the OC. Meanwhile, Shannon begins to question her friendship with Vicki.', '2015-09-21', 44, '/5Hg1210prAb6XfmFGGATJ5moRa0.jpg', '2026-04-03T16:35:32Z', '2026-04-03T16:35:32Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('86c21c6f-d9cd-4371-aa56-8b6e53f8abb5', 'bb919aec-0d5c-4c58-9a5a-fa2a0a5de2b6', 25, 'Episode 430', '', NULL, NULL, NULL, '2026-04-03T17:36:29Z', '2026-04-03T17:36:29Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('86cc8b94-54ca-4ca4-94cb-dc593c856684', '8012f05a-66a3-4254-885f-0a679393f3dd', 9, 'Attack of the Slime Monster (1)', 'Casey is writing a scary story for a local contest about ""Gooey Gus: the Slime Monster"", a doll that spits out grape bubblegum.  Casey thinks her story isn''t scary enough, so she asks for Lenni''s help.  Lenni adds atmosphere and writes how the Slime Monster is about to come after Casey.  Alex and Gaby come to help, too, and Gaby writes about Alex and Jamal finding the Slime Monster seemingly alive in an alley, and then Alex, Gaby, and Casey find the Slime Monster in a crock pot.', '1995-01-22', NULL, NULL, '2026-04-03T17:40:28Z', '2026-04-03T17:40:28Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('86d43e1c-eac0-46d5-9b73-9ff55a09e4e5', '83d04769-45b3-4d29-af02-590315104997', 4, 'Dangerous Games', 'Porsha hosts a field day with different challenges for the ladies; it''s all fun and games until the scorpions come out, forcing the women to answer some prickly questions; Gizelle hosts a Mardi Gras-themed dinner.', '2023-03-30', 52, '/2JcaDZpXBOFSrolUoTYEarqNYOr.jpg', '2026-04-03T16:34:41Z', '2026-04-03T16:34:41Z');
