INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('86e239d5-964c-42d8-a0ee-3c5f9a9d33fa', '1c9ea7d3-e254-4e7b-8a9f-33eea9c6c341', 7, 'What Would Michelle O Do?', 'Marlo takes Porsha on a hookah and Hennessy-fueled pedal tour to get her mind off her break up. Kenya deals with her own relationship issues and visits an estate lawyer to discuss the worst-case scenario. Rumors abound that someone in the group secretly recorded Cynthia talking behind Nene’s back. Meanwhile, Nene seeks advice from her life coach on how to restore her sisterhood with the ladies. Kandi begins to worry she and Todd may not see eye-to-eye when it comes to raising their new daughter, and after weeks of heartache, Porsha reluctantly agrees to attend another therapy session with Dennis and must decide if she’s ready to give him another chance.', '2019-12-15', 43, NULL, '2026-04-03T16:34:49Z', '2026-04-03T16:34:49Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('86e440e2-28a2-44d6-b6fc-e230b801bbe4', 'ecb64ef3-4f80-45a7-b4a9-c04434b02e35', 39, 'Tickets to Ride', 'Take a "magical mystery tour" with the Pawn Stars when a pair of rare tickets to The Beatles film, "A Hard Day''s Night," buzzes into the shop. Will Rick "come together" with these tickets to ride or will he "let it be"? Then, an 1850s Indian Peace Medal, given by President Fillmore, lands in the shop. Will Corey purchase this Presidential peace offering or will he have reservations? And later, Rick gets all hot and bothered when control over the thermostat becomes an all-out war. Will things in the shop get heated or can the guys get Rick to chill out?', '2014-05-15', 21, '/qUyREdxgufr64iHXKmZuMB86hCS.jpg', '2026-04-03T16:34:19Z', '2026-04-03T16:34:19Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('86eb157e-4da2-4ee1-8380-1f5a7743a18d', 'cb8a0322-be77-485b-b339-bdd572bca349', 28, 'D.W.''s Perfect Wish', 'Arthur notices that D.W. is not excited about her birthday. So he tells her about her memories throughout her year as a four-year-old.', '1998-12-31', 13, NULL, '2026-04-03T17:37:56Z', '2026-04-03T17:37:56Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('86ef3e8b-eb29-4f81-9b8f-7f3f83b16c7a', '9193e795-da7c-40ec-b68f-f63aa7d5174f', 249, 'Deleted Scenes from Season 8', 'Alys Karstark (Episode 3), Davos & Fergus (Episode 2), Grey Worm & Missandei at the Feast (Episode 4), Play All (Season 8), Soup in the Trenches (Episode 1), and Tyrion & Sansa in the Crypts (Episode 3).', '2019-05-26', 9, NULL, '2026-04-03T15:40:35Z', '2026-04-03T15:40:35Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('86f525e7-dccc-4d8a-aae1-782839a992a2', '05fa5e18-78d2-41fe-ae30-0c242c7ffb6a', 16, 'Trouble and Squeak', 'Norman has taken the school mouse home to look after. Unsurprisingly, it escapes and causes havock when both Rosa and the mouse end up stuck in Bella''s chimney.', '2003-04-21', 10, '/nY2dU2IZAtTTaNy3IzhNc9QWcup.jpg', '2026-04-03T17:14:38Z', '2026-04-03T17:14:38Z');
