INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('87008477-65c9-4a7e-bc39-ac2e7bf9b4df', '5d57283d-079c-4f66-93c8-33a2feeada89', 11, 'War of the Hecks', 'Sue makes a discovery that leads to an ultimate prank battle with Axl; Brick tries to read a recommended biography on Debbie Reynolds.', '2014-01-15', 22, '/cn2AUeF7IbGAU0vuELcr7BuBbOZ.jpg', '2026-04-03T15:40:30Z', '2026-04-03T15:40:30Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('870360f8-d541-4e8f-ac0a-783e38c64cb9', 'bb919aec-0d5c-4c58-9a5a-fa2a0a5de2b6', 17, 'Episode 422', '', NULL, NULL, NULL, '2026-04-03T17:36:29Z', '2026-04-03T17:36:29Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('87100d75-acff-4b00-98d0-9c40981a1bec', '941b8c65-4454-4336-be7c-1d0591c12f90', 25, 'Pingu Pancakes', 'Mother is making pancakes, and Pingu and Pinga ask if they can help. Mother lets Pinga have a stir, and then Pingu has a turn while Mother gets the stove ready. Mother then has to intervene when Pingu stirs too vigorously and sprays batter over them all, and around the room. Mother then shows them how to flip the pancake in the pan and they clamour to have a go themselves. Pinga goes first and with Mother’s help manages the flip. Pingu wants to try by himself but does it much too hard, and the pancake sticks to the ceiling. Pingu tries again, still gets it wrong and hits the picture on the wall. After a number of further unsuccessful attempts, which leave the room well covered in batter, Mother again shows him how to do it and prepares another pancake for him to flip. This one files out of the door when Father opens it to come in, hitting him in the face. Father flips the pancake back and it lands in the pan, much to the surprise of Pingu and Mother. When Father comes in, Pingu shows that he has at last got the hang of flipping pancakes, and they all applaud. Pingu then makes them all pancakes for tea, but doesn’t make one for himself - he waits for the first one he flipped to drop back onto his plate from the ceiling!', '2004-02-05', 5, '/tYg07lWvoBtlNSicEjn8cKwc9E.jpg', '2026-04-03T17:22:20Z', '2026-04-03T17:22:20Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('87121bb7-e6c0-4932-a1cd-af93ad9eb450', 'bb919aec-0d5c-4c58-9a5a-fa2a0a5de2b6', 45, 'Episode 450', '', '1973-01-26', NULL, NULL, '2026-04-03T17:36:29Z', '2026-04-03T17:36:29Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('8715ee03-78a7-4f5d-9e57-f6dd99a6943d', 'c9adc698-be92-4dd7-94ad-d8f6759361ca', 36, 'Episode 36', 'Rogers works a typewriter specifically used with teleprompters. In the Neighborhood of Make-Believe, Pilot Ito wants to take opera lessons. King Friday calls John Reardon in to teach her.', '1973-04-09', NULL, NULL, '2026-04-03T17:35:40Z', '2026-04-03T17:35:40Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('8716a35a-cfd0-4a0e-a87c-ac89f4d36260', '262e8e7c-fa78-4578-a216-add6f184c4d2', 23, 'Sisters'' Special Delivery', 'The Sister Wives are buzzing with excitement as Robyn''s first contractions finally kick in. But not everyone is happy about it. The emotion builds as each of the Browns face their true feelings about Robyn''s family becoming their own.', '2011-11-27', NULL, NULL, '2026-04-03T16:34:28Z', '2026-04-03T16:34:28Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('8717c2a9-a7ef-4643-bbf7-50a6924687f4', 'd8ccf6d3-e37a-430a-b67d-7fbf269bf0be', 4, 'Don''t Be a Drag', 'On the final day of their Palm Springs trip, Whitney takes over and calls Meredith on her behavior. Monica and Lisa''s tension reveals itself in head-to-toe drag. Angie and Meredith continue to throw insults at each other. Heather and Angie bond during a team building exercise. Mary bows out of participating in the ladies'' plans.', '2023-09-26', 44, '/3xiOub7RxYXcX1D5O29wzRBOQS4.jpg', '2026-04-03T16:35:45Z', '2026-04-03T16:35:45Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('871c3231-96d5-4463-8dae-426574b240f8', '42e591e2-2a88-4434-ae9f-3d4b1d685613', 15, 'Colt to the Touch', 'Put the pedal to the metal with the Pawn Stars as Rick and Corey check out a ''51 Chevy driven by Steve McQueen in his last movie. Will a test drive make Rick feel like the new King of Cool? Then, a man moseys in with a Colt .45 he claims was used to kill Jesse James. Can the guys make a killing of their own? And later, Chumlee checks out an Atari Centipede arcade game. Will he spend a pile of quarters on this classic piece, or is it game over?', '2013-08-01', 21, NULL, '2026-04-03T16:34:18Z', '2026-04-03T16:34:18Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('87282516-365f-44ec-9a76-2e00ad2a9509', '63f9bf6d-39b3-44f4-b885-a56807277a80', 6, 'The Great Santa Claus Switch', 'The show, narrated by Ed Sullivan, begins at the North Pole with Santa Claus and his elves getting ready for another Christmas. However, Cosmo Scam has hatched a plan to kidnap Santa and take his place. As part of the plan, Cosmo plans to abduct Santa''s elves (one at a time) and replace them with his evil henchmen.', '1970-12-20', 50, '/nTOmLGzHlxEn1HEDuCnGGwcnLDK.jpg', '2026-04-03T17:35:23Z', '2026-04-03T17:35:23Z');
