INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('8733dda5-5132-4ec8-ad1b-e485e7adb957', '78a02d50-e3dc-4549-844a-3cf357a32ef4', 13, 'If These Woods Could Talk', 'The ladies finally reach the woods of Georgia for a fabulous weekend of "glamping," but are shocked to learn that they''ll be spending their first night sleeping in tents. Later at the campsite, Marlo confronts Kenya over unresolved issues, leading to a massive argument. The next day, the women begin to come together and bond over their outdoor activities, but things quickly fall apart at dinner when Kandi learns about major rumors flying around about her. Forced to confront old drama and new drama too, the women all decide to speak their truth.', '2017-02-12', 43, '/cP5Z3CERRgfcngz3Pys7pdErO6p.jpg', '2026-04-03T16:34:48Z', '2026-04-03T16:34:48Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('8733ecac-2073-495c-ba4c-9faa320b3658', '46d7a706-c7a8-4ebe-b96f-387c66e8bb8b', 62, 'Episode 1507', '', '1981-02-17', NULL, NULL, '2026-04-03T17:36:34Z', '2026-04-03T17:36:34Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('8734060f-930d-40c5-88f7-47c147b74489', '4eb9b495-7962-41d9-ba8a-3bed48d9bcc6', 6, 'Huff and Puff', 'Whatever happened to the three little pigs after the wolf received his just deserts? Leona and Lionel want to know, so they write their own sequels to the story! Guest Starring Teresa Weatherspoon of the New York Liberty and Vanessa Williams.', '2002-10-21', 30, NULL, '2026-04-03T17:12:28Z', '2026-04-03T17:12:28Z');
