INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('87a6aaa8-62b5-47a0-930b-b42716523783', '1d713ca6-4e17-4f84-949c-8cfd98514127', 35, 'Game Over', 'Lift off with the Pawn Stars when a hovercraft zooms into the shop. Will Rick and Corey be able to keep the negotiation afloat, or will they let the air out of the deal? Then, Corey checks out a set of 1960s The Beatles bobble-heads. Does Corey think The Fab Four are so "Yesterday," or will he "Twist and Shout" to make a deal? And later, when a new arcade game gets bought by the shop, Rick lets the guys plug it in. Who will get the highest score before it''s game over?', '2014-12-04', 21, '/nXDIAAzpEIjvjMyTqokUU8hgxv2.jpg', '2026-04-03T16:34:19Z', '2026-04-03T16:34:19Z');
