INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('87acf3db-af31-4e0a-9b22-779b8f17f33a', '4d2cac0f-38fd-438b-8afa-acf43952e535', 141, 'Episode 141', 'For younger viewers. Introduced by Christopher Trace. The Python. Hugh Tracer tells a story. Alpine Antics, Dreamy Daniel in a cartoon film. Ponds and Jam Jars: 2, with Kenneth Exall, Gillian Hudson, Roger May.', '1961-07-03', NULL, NULL, '2026-04-03T17:21:47Z', '2026-04-03T17:21:47Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('87bb5890-0041-4c07-be8c-7b21f4199f97', 'b2317fc3-1cfc-4f19-b181-effa23959c6d', 1, 'Smoke, Mirrors and Foggy Diamonds', 'Teresa throws a kickoff to the summer party that instantly becomes drama filled when an unsettling video leaks about Luis; Margaret later finds herself revealing a shocking secret about Jennifer to the ladies.', '2022-02-01', 43, '/ont5gmeXCXgDfrQYcjYq2GaoL9Q.jpg', '2026-04-03T16:35:18Z', '2026-04-03T16:35:18Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('87c39217-3c6e-4a5c-991c-ce25dda72907', '0e419615-4c96-4dde-8ed2-715770ba77bb', 26, 'This Is Your Life, Bear', 'When Bear decides to do some relaxing and tune to his favorite station, WCHA-CHA, he hears an announcement for a contest. The station will play a sample from a cha-cha record and the first caller to identify the name of the tune and the artist will win. Bear resolves to sit tight so that we won''t miss the contest, but has to get up to help out when the kids in the Big Blue House call. Luckily, he manages to make it back in time for the contest and succeeds in being the first caller and identifying the record. He wins a trip for himself and everyone in the house to Sequoia City. Tutter overhears him celebrating, but only hears a little of it --- he hears Bear saying that he needs a vacation and thinks that he''s upset. He and the rest of the kids decide to put together a special celebration for Bear to show him how much he''s appreciated.', '2006-04-28', 25, '/16i6qchDIthr4uOJccUotJpmeIn.jpg', '2026-04-03T17:35:32Z', '2026-04-03T17:35:32Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('87c4146c-a73e-4705-aec1-a92b115fbc14', '8a5892f6-ccb7-4f02-9a5a-85b134b5f0cf', 13, 'The Water Tower', 'Some engines are very particular about what they will or will not be willing to drink, for the sake of who or what happens to be in the drink.', '1976-02-16', 5, NULL, '2026-04-03T17:24:25Z', '2026-04-03T17:24:25Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('87c4bfb4-308f-4551-8a93-e29f6e5a448a', '4d2cac0f-38fd-438b-8afa-acf43952e535', 244, 'Episode 244', 'Christopher Trace and Valerie Singleton introduce a magazine programme for younger viewers. Including: Dances from Spain by Manuela Vargas and members of the Spanish Dance Company. Little Watha: 3: The Tomahawk by Oliver Postgate. Is there magic in the Valley of the Gods? Little Watha finds danger - and a gift from the brother of a great brave. Told by Peter Hawkins and Patricia Hayes. Owning a Pony - Ross Salmon and Elizabeth give Moorland King his final training.', '1963-08-26', NULL, NULL, '2026-04-03T17:21:47Z', '2026-04-03T17:21:47Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('87cd590e-45d0-41c2-992b-0b4dfeb1e73b', 'f12380a9-93e5-47bb-9e2f-cf1eed11eee4', 3, 'All About Eggplants', 'Mykelti and Tony drive right into a tornado as Christine and David help them move to North Carolina. Kody and Robyn decide to begin anew while someone makes an unexpected pregnancy announcement.', '2025-10-12', NULL, '/xin9Afl6EYPIgBwmgGQSRafABqX.jpg', '2026-04-03T16:34:33Z', '2026-04-03T16:34:33Z');
