INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('87d3ab70-6da2-469f-808a-38dca09d6d09', 'e606692a-47b7-411e-b54b-7c6bf61a67b7', 1, 'Pigs, Pigs, Pigs!/The Three Little Pigs', 'Theo and Leona don pig snouts for another reading of Pigs Apelnty, Pigs Galore first read in the episode ""Pigs Aplenty."" Midway into the show, Lionel dons three pig snouts as he reads to Leona The Three Little Pigs, heard previously in the episode ""Huff and Puff.""', '2005-04-18', 30, '/qcF110cbV8vifj4L5ZtNk5k1wla.jpg', '2026-04-03T17:12:29Z', '2026-04-03T17:12:29Z');
