INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('88c3653d-11a5-4552-a663-230ec5b3139e', '36ea3814-66b4-4986-b6ee-44559d3562c1', 22, 'Final Curtain Call', 'With Kandi''s musical approaching, ticket sales aren''t where they should be and Porsha isn''t paying attention at rehearsals. NeNe has to see a doctor after enduring strange pain. Apollo and Phaedra discuss their marriage. Kenya has a pet funeral to attend.', '2014-04-13', 43, NULL, '2026-04-03T16:34:46Z', '2026-04-03T16:34:46Z');
