INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('88c75841-038a-4199-bd24-6bdcf03b4bd2', '70c8cb46-2494-4dd4-98f6-6bfb9b3faf73', 13, 'Big Guns', 'The Pawn Stars are presented with the most explosive item to ever walk through the door - a pair of Soviet nuclear missile launch keys. Can the gang count down and launch the deal or will it blow up in their faces? Then Rick hopes to buy an extremely unique 1920s ukulele banjo made by the legendary guitar company Gibson. Will Rick strike up a chord to buy this antique instrument or break a string making an unsound deal? And later a man walks in the shop with two of the biggest guns Rick has ever seen. But when it comes to pricing these behemoths of bang will size really matter?', '2010-03-08', 21, '/ikhJtshxEaJGhuy9oTvjBrp9Ui4.jpg', '2026-04-03T16:34:16Z', '2026-04-03T16:34:16Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('88cc6f54-c99f-44bd-a734-e1ca8810ce28', '69b3befe-579a-43ad-a7d6-ec30ffe3adf7', 60, 'Episode 1115', '', NULL, NULL, NULL, '2026-04-03T17:36:32Z', '2026-04-03T17:36:32Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('88d0815d-dace-4bd7-9274-a78b4d4f82af', 'f9a8d8b3-d72e-437e-a9d5-7477f6d64df8', 8, 'Rudy''s Favorite Sweater', 'When Rudy’s favorite sweater no longer fits, Nina suggests they have a clothing drive so everyone in the neighborhood can donate clothes they don’t need to those who do.', '2022-12-22', 26, '/mt7ctqIYrzeg1JZyqcBBjundmse.jpg', '2026-04-03T17:36:51Z', '2026-04-03T17:36:51Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('88d26cf8-b5fd-4844-b654-beb006500423', '6f731e6b-d3c5-4de6-84e1-7a19cb650e86', 44, 'Famous Finds', 'Search for success with the Pawn Stars and rediscover some of the most famous finds in the shop''s history: a 40-year-old Bob Dylan album that lands Chum face to face with the voice of a generation, molds of Joe DiMaggio''s and John McGraw''s Baseball Hall of Fame busts, a book printed by revolutionary founding father Benjamin Franklin, a suit worn by the Godfather of Soul James Brown, a rare collection of autographs from Gemini space program astronauts and a football program from the first ever NFL championship game that sets Corey on a mission to prove himself.', '2016-07-13', 21, '/kefJSkWrPOkVRo8wGwzECysltVb.jpg', '2026-04-03T16:34:20Z', '2026-04-03T16:34:20Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('88d6c473-2bda-4b2c-b99d-fad5fdd374cf', '04e133fd-c4a3-4dfa-8369-c6dcfd1e3a5a', 77, 'Gordon waits for Mr. Snuffleupagus', 'Gordon settles in beside Oscar''s trash can with food and supplies to finally meet Mr. Snuffleupagus as promised to Big Bird. Oscar and Grundgetta prank Gordon with a trash-can Snuffleupagus disguise, and Susan reminds him of their dinner date that he''s reluctant to leave. When Big Bird excitedly claims Snuffy actually did appear nearby, Gordon realizes his long vigil may have nearly succeeded.

Sponsors: B, C, 6', '1985-03-05', NULL, NULL, '2026-04-03T17:36:36Z', '2026-04-03T17:36:36Z');
