INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('88f80fd6-99de-4d17-a4f8-d3e8d57f493c', '4d2cac0f-38fd-438b-8afa-acf43952e535', 285, 'Episode 285', 'Christopher Trace and Valerie Singleton introduce a magazine programme for younger viewers. If you have ever watched "It''s a Square World," Michael Bentine''s programme, it is likely that you have seen him grappling with the Bumblies. They are little creatures, with twittery voices and rapid movements, who pop up at the most awkward moments - during a lecture or a song - and take over the programme with their antics and furious energy. You must have wondered about them - where they come from, and how they get in. Today you may have a chance to find out because Michael Bentine himself is coming along to talk about them. We say "may" advisedly, because with Bumblies you never know what can happen!', '1964-06-29', NULL, NULL, '2026-04-03T17:21:47Z', '2026-04-03T17:21:47Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('8903f548-b5a2-4ffb-b624-5fb7b39f1ce5', 'bf874be3-7e2f-4a0e-b205-c76ac1ad69fc', 61, 'The Handicap Spot (Syndicated Version)', 'Going out to buy an engagement party present for The Drake, George parks his father''s car in a handicap parking spot, after taking Kramer''s advice.', NULL, 30, NULL, '2026-04-03T16:34:09Z', '2026-04-03T16:34:09Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('8909a07c-ae73-4e00-8b00-cac32cb740ee', '5a771f52-fe96-4ea2-b567-a8dde899059e', 9, 'Royally Pawned', 'A set of royal British armor has Rick suiting up to strike a bargain. Chumlee''s purchase of a U.S. Open custom electric guitar gets no love from Rick. Will Chum be able to net a profit before Rick reaches his break point? Signatures and a movie script from famed comedy duo Abbott & Costello inspire Corey and Chum to reenact a hilarious scene from the film, but the amount of money this seller is asking for is no laughing matter. A seller with an antique coin-operated scale throws his weight around during negotiations. Can Rick get him to lighten up enough to make a deal?', '2017-11-13', 21, '/l17fn2vJ35lqu0bLo5pWXMxugqg.jpg', '2026-04-03T16:34:21Z', '2026-04-03T16:34:21Z');
