INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('89940de2-170c-4103-9f71-08938a097ca3', '63f9bf6d-39b3-44f4-b885-a56807277a80', 4, 'Tales of the Tinkerdee', 'This unaired pilot, produced by Jim Henson and Jerry Juhl, was shot in Atlanta in the summer of 1962. The pilot featured Kermit the Frog, Taminella Grinderfall and King Goshposh, characters who would all reappear a few years later in the Tales From Muppetland TV specials.', NULL, 26, '/nq7xclrocHaMjyxB7yGhfoEG3rj.jpg', '2026-04-03T17:35:23Z', '2026-04-03T17:35:23Z');
