INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('89c778d2-cbdb-4193-ba42-aa68bcf644ba', 'db555b98-87d6-4cd2-b7b4-973f9206cb1e', 10, 'Big Os and Broken Toes', 'Gina’s double date with Shane’s cousin is canceled due to a broken toe. Emily goes to Tamra and Eddie for help to lose weight and learns the situation is more extreme than she thought. Shannon gets an O shot. Braunwyn has a family photo shoot. Emily catches up with former housewife, Alexis Bellino. Meanwhile, Kelly remains in Arizona to visit old friends and her brother JR as she struggles to reconnect with her younger brother Eric and mom Bobbi.', '2019-10-08', 44, '/3az4mOPjUpuBq7QG7YymgYESbTf.jpg', '2026-04-03T16:35:34Z', '2026-04-03T16:35:34Z');
