INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('8a1a5b80-8bb8-4ef4-b2a4-633a2f138e00', 'a31fa1d7-d649-4846-a81f-4f34b6fb3331', 5, 'In and Out of Trouble', 'Paddington has trouble using Mr. Curry''s old hammock.', '1979-10-29', NULL, '/7tmgeQr3mv1wbCgC5lmNi4xP2KP.jpg', '2026-04-03T17:22:52Z', '2026-04-03T17:22:52Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('8a21ac7b-a47d-48ee-ba15-ec9977684137', '97a3d1f5-a8f1-47cd-8122-2e74a092836d', 21, 'Don''t Stop the Music (1)', 'Lenni, Max and Sally are all watching Lenni''s video from the Star Jam episode Building Bridges. Just then, they get a call from Smash Records. Jade Morgan is inspired by the video and wants Lenni to star her in a music video. Lenni has writer''s block so she writes a song about self-confidence. Jade is inspired by the song and decides to allow the team to be in the video.', '1994-01-23', NULL, NULL, '2026-04-03T17:40:28Z', '2026-04-03T17:40:28Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('8a226b11-1ddf-45c5-b320-3a793e0e8839', '190c6e49-8849-4404-87d4-eaef943a6024', 13, 'Oakie Doke And The Wishing Well', 'Dave and Denzil establish a wishing well to collect nuts from wish makers. Doke finds out about this and tricks Dave and Denzil into thinking those wishes do come true.', '1995-12-04', 10, NULL, '2026-04-03T17:19:24Z', '2026-04-03T17:19:24Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('8a230776-43d5-4be8-9bf8-918185853f7d', '40700e8a-1dce-4895-bede-522a13a8bcad', 10, 'Flying Buddies', 'After meeting a flying fox fruit bat, Zoboo wants to fly, too, so the Kratt Brothers build him a pair of wings. Zoboo flies to India with Martin and Chris right behind. On the way, they meet vultures and learn some lessons about flight.', '2001-01-29', 27, NULL, '2026-04-03T17:10:55Z', '2026-04-03T17:10:55Z');
