INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('8a335d4b-5c0e-4bce-9295-22df40e47c9e', '2dcbd122-86d8-46e8-bbe5-9143875abd34', 18, 'Buster''s Best Behavior', 'Buster and Arthur feel like that they are boring and they think they are not good at anything, so they try to imitate each others'' lifestyle.', '1999-10-15', 13, NULL, '2026-04-03T17:37:56Z', '2026-04-03T17:37:56Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('8a371e1b-c588-4d55-a09e-17dc0633a1b0', 'cefd1496-b649-4c62-aef9-35a22558ac08', 10, 'Don''t Cry Over Shattered Glass', 'It''s Brandi''s annual holiday party and she finds herself center of the drama when LeeAnne reveals that Cary can''t be friends with her and Stephanie anymore because of their behavior in Mexico. And when Brandi challenges her for an explanation, Cary sides with Kameron, infuriating Brandi so much, she blurts out a humiliating secret about Cary and Mark.', '2017-10-16', NULL, '/kewNJM5vogELqt08eAtdah60ETG.jpg', '2026-04-03T16:35:04Z', '2026-04-03T16:35:04Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('8a393c8d-4110-4ccb-96d2-1ee5a3711f63', '095258d0-d8db-4096-8ac7-6a42cd4cbdcf', 19, 'The Cavern Of Lost Dreams', 'When Cotterpin Doozer hears that Gobo is the bravest Fraggle in the Rock, she gets him to help her find the Cavern of Lost Dreams, which is where the original tower was built. When they get there, the remaining two Doozers, Yeaster and Crusty, don''t want to come back. Will these two Doozers finally accept the changes that have occurred and move back to the Rock and help build once again?', '1985-05-06', 24, '/qbxwkrLnP4E52QFON6O5YQvWvmg.jpg', '2026-04-03T17:35:00Z', '2026-04-03T17:35:00Z');
