INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('8a4d2c1b-a412-4b4e-8170-a61e0629ff99', 'a1b69730-d225-48f2-a7e7-1d314cf3b349', 71, 'Episode 71', 'with Valerie Singleton, John Noakes, Peter Purves', '1969-05-29', NULL, NULL, '2026-04-03T17:21:49Z', '2026-04-03T17:21:49Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('8a520862-4e70-4276-9a4b-cb81190bab27', '3087a3ed-e94e-4276-9d02-a78183dea1d3', 1, 'Got Sexy Back', 'NeNe looks at a possible reconciliation with Gregg, and Kandi and her new man are moving in together.', '2012-11-04', 43, NULL, '2026-04-03T16:34:46Z', '2026-04-03T16:34:46Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('8a560a8c-0177-4ac3-b810-4a1c36158c7d', 'd5383b3d-5636-4d71-b99c-b84774b4b3c6', 20, 'Pingu The King', 'Pingu is shovelling snow outside the igloo when he has an idea. He’ll build a castle. Pingu builds castle like ramparts round the igloo, and a nearby abandoned door becomes a drawbridge. He goes indoors, makes himself a paper crown, and sets out the kitchen chairs and table for the throne room. Pinga comes and asks Pingu what he’s doing. Pingu visualises himself as the king and explains. Pinga decides she wants to be queen and goes to the toy box. While Pinga is rummaging, Pingu is making a royal carpet with a cloth he gets from the cupboard. Pinga returns wearing a crown, and Pingu bows to her and invites her to sit on her throne. Pingu sits on his throne, and has another idea; he needs some subjects. He goes to the phone and, visualising knights wearing armour in battle, invites his friends over to join in the game. Pingo and Pingg arrive, and come in when the drawbridge is let down. They chortle when they see Pingu and Pinga on their thrones. Pingu acts all imperious, and gets annoyed when Pingo and Pingg don’t respond as he thinks they should, and clouts Pingo on the head, to his surprise. After some more ordering about from Pingu, Pingo goes and gets a carton of drink and a mug from the sideboard, pours some drink into the mug and gives it to Pinga, and gives the carton to Pingu. Pingu and Pinga both have a drink. Pingu tosses the carton to Pingo and Pingg, and it bounces off their heads onto the floor. Pingo goes to have a drink himself, and is not very happy to find the carton empty! Pingu now imagines himself in a coach, and orders Pingo to get it. Pingo bows to Pingu, and gets the toy truck. Pingu gets off his throne and into the truck, envisages himself being driven in the coach and orders them to pull the truck. Pingo gets annoyed and decides he’s had enough, and unceremoniously dumps Pingu out of the truck and onto the floor. While Pinga helps Pingu recover, Pingo and Pingg go outside. Pingg makes a snowball and throws it at Pingu, hitting him on the head. Somewhat dazed, Pingu imagines his castle falling down, takes off his battered crown and throws it in the bin.', '2000-01-30', 5, '/bTMwDS6MD1AmSQJoneff5JVfYl1.jpg', '2026-04-03T17:22:20Z', '2026-04-03T17:22:20Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('8a59912e-8a99-4fd3-a1a6-b32b241857a1', 'a605edf8-69ba-46db-8c0c-523b1ef5447b', 79, 'Episode 79', 'with John Noakes, Peter Purves, Lesley Judd', '1973-06-21', NULL, NULL, '2026-04-03T17:21:51Z', '2026-04-03T17:21:51Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('8a5d01eb-b505-41de-a24a-97458da277bd', '04e133fd-c4a3-4dfa-8369-c6dcfd1e3a5a', 120, 'Episode 2085', 'The residents engage in standard activities and interactions featuring various street scenes. Educational moments are incorporated naturally into their routines. Daily life on Sesame Street continues with its typical rhythm.

Sponsors: B, L, 9', '1985-05-03', NULL, NULL, '2026-04-03T17:36:36Z', '2026-04-03T17:36:36Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('8a62ccab-fc98-45d1-832e-f4647aaafb99', '7bc54df3-f32a-454e-aef6-a9436c35d53b', 49, 'Episode 49', 'Rogers welcomes Mrs. Franks, who demonstrates how to carve leather. Later he discusses wearing an eye patch. In the Neighborhood of Make-Believe, Handyman Negri assures King Friday that his eye is underneath an eye patch.', '1970-04-09', NULL, NULL, '2026-04-03T17:35:39Z', '2026-04-03T17:35:39Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('8a668145-089e-404b-8100-984640b4b013', '331fc1df-6d70-4d79-b585-bf28024a4124', 17, 'Floating Cart', 'Norman Price builds a go-cart with items he has collected from around Pontypandy, but of these items are collected without permission, causing problems for others. He loses control of the cart on its maiden voyage and falls off the quay. Fireman Sam comes to his rescue.', '2008-12-03', 10, NULL, '2026-04-03T17:14:39Z', '2026-04-03T17:14:39Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('8a6c4b61-aee1-451a-b9e2-816016dfec14', 'f15647d3-c8bf-4e37-a6bc-589853787f3b', 2, 'A Star in the Breaking', 'Nick and his cartoon pal McGee learn a lesson in humility when the fame and popularity of being on a game show goes to Nick''s head.', '1989-06-11', 28, '/vzgYoQGvpwGiMSr8LFYRes9ROF7.jpg', '2026-04-03T17:40:08Z', '2026-04-03T17:40:08Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('8a6e770c-d4b1-4524-aa29-6f7e81a98495', '9193e795-da7c-40ec-b68f-f63aa7d5174f', 294, 'Creating the Visual Effects: Season 7', 'Creating the Visual Effects: Season 7', '2020-11-30', 30, NULL, '2026-04-03T15:40:35Z', '2026-04-03T15:40:35Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('8a71257a-85c1-4cca-a37c-65e4c34ea202', '7b19039a-31ac-425c-8fb1-b51cf2447821', 9, 'The Lies That Bind', 'The ladies begin to self-document their lives during the mandated lockdown due to the global pandemic. Elizabeth has a change of heart about her divorce proceedings, Emily and Shane’s relationship takes a turn, and Kelly travels across the country to be with her fiancé, Rick. When tension arises between Shannon and John, Gina gives her two cents. Meanwhile, Braunwyn struggles to keep her sobriety and marriage intact during the quarantine stress. And as Braunwyn digs into Elizabeth’s past, Elizabeth invites the ladies for a bonding trip in Lake Arrowhead and Shannon receives some shocking news.', '2020-12-09', 44, '/9xrGkk0P9IoZdy0HLWtO983lQSZ.jpg', '2026-04-03T16:35:34Z', '2026-04-03T16:35:34Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('8a7c38f9-eb2a-4743-a821-ba35d0af34b1', '3d4e0e45-1c67-475e-b37d-9e7e6b8b942a', 2, 'Halloween Hound: The Legend of the Creepy Collars (2)', 'Continuation of Part 1.', '1997-03-04', 28, NULL, '2026-04-03T17:10:42Z', '2026-04-03T17:10:42Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('8a7e3bed-e14b-44f2-b0de-2c6184d7ac72', '34674c90-410e-427c-be4d-2a6f6f865a80', 15, 'Pin It to Win It', 'Play detective with the Pawn Stars when they try to discover the origins of a mysterious rifle brought into the shop. Will Rick pull the trigger on the deal of his life, or will the negotiation blow up in his face? Then, Corey and the Old Man are presented with a signed print by Leroy Neiman. Considered one of America''s greatest living artists, do the guys draw up an offer for this highly collectable piece of art, or get painted into a corner? And later, a collection of old sports pins needle their way into the shop. Can they nail down a deal or will this one fall apart?', '2012-06-18', 21, NULL, '2026-04-03T16:34:17Z', '2026-04-03T16:34:17Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('8a7e3cdc-4534-42a4-8350-68b1e26b2979', '4861ce46-9045-43c7-963f-27b4ea539804', 98, 'Episode 228', '', '1971-03-24', NULL, NULL, '2026-04-03T17:36:28Z', '2026-04-03T17:36:28Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('8a818c93-b318-4b72-a0bd-2363cdfc351a', '7c422193-b078-49d8-81ef-f2b9f94f059d', 4, 'Elmo says NO!', 'Episode #3009', '1992-11-12', 55, NULL, '2026-04-03T17:36:39Z', '2026-04-03T17:36:39Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('8a881313-6249-41f6-9989-1c230bc8a389', 'e3a28669-91b5-45f7-bb73-5006acc084e8', 6, 'Still Life', 'The Farmer oil paints the farm, but runs out of white paint for the sheep. Shaun tries to fix the painting, but soon the rest of the flock are a riot of colour. Although the painting appears ruined, it actually proves to be a fortune-winning masterpiece at the end.', '2007-03-07', 7, '/sorEnRYTLQ19DMumDUPKJfZduJu.jpg', '2026-04-03T17:39:31Z', '2026-04-03T17:39:31Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('8a8a190d-bb96-4588-b5c8-a6d4961c45a7', 'd7ff9136-a833-4c43-a37c-a985a34f45a9', 10, 'All Your Eggs in One Basket', 'Christine is excited to celebrate her first Easter since divorcing Kody. Janelle says her life is also better without Kody but reveals she would consider polygamy again. After learning Aurora is interested in a boy, Meri reflects on marrying so young.', '2023-10-22', NULL, '/qeZxInUylKzVqGFxnpiLFVLZnUf.jpg', '2026-04-03T16:34:32Z', '2026-04-03T16:34:32Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('8a8defc6-28ec-43fc-9d75-8a0e5a3204b0', '4c79c0b6-21a4-4277-8967-be1e791efdbe', 8, 'Pingu and the Present', 'Pingu is at home, playing aeroplanes, when an envelope is delivered. It’s for Pingu, and when he opens it he sees that it’s a card inviting him to a birthday party. Pinga wants to see it, but Pingu won’t let her, and Mother eventually has to intervene. Mother looks at the card and gives Pingu a fish to pay for a present. Pingu is just on his way out of the door to get the present when Mother tells him to take Pinga with him. Pingu and Pinga is not too happy about that, but Mother insists. At the toyshop, Pingu eventually decides to get a model aeroplane as the present. On the way home Pingu continues to not be very nice to Pinga, this time by hiding from her and being rude to her. While backing away he trips and drops the present, which slides into a small crevice that then gets partially blocked by a small fall of ice, with just a bit of the ribbon from the present sticking out. After searching for a while, Pingu spots where the present has gone and tries to get it out by pulling on the ribbon, but it won’t budge. Pinga says that she’s small enough to go through the gap to get the present, and Pingu is delighted when she gets it. When they get home, Pingu explains to Mother what has happened and sets off for the party, taking Pinga with him to her delight. When they arrive Pingu explains why he’s brought Pinga along as well, and Pinga gives the present.', '2005-01-12', 5, '/vvbk7fCbvQ5ftOhsynVmCrdLXMN.jpg', '2026-04-03T17:22:20Z', '2026-04-03T17:22:20Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('8a969324-8814-41f3-9943-379c72ccd420', 'e48599f8-66ff-4c0f-9274-65b9ae1cda9e', 17, 'Episode 17', 'Real gladiators'' armour and a 2,000-year-old loaf of bread are two of the fascinating collectors'' items John saw when he took Blue Peter cameras to Italy and visited the site of the world''s most devastating volcanic eruption.', '1976-11-08', NULL, NULL, '2026-04-03T17:21:53Z', '2026-04-03T17:21:53Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('8a98aea1-3a33-4f08-b1e0-1fcfe8fe1cf3', '6fd9fd9d-e378-411b-94b1-76ba4bd518fe', 63, 'Episode 63', 'with Christopher Trace, Valerie Singleton and John Noakes.', '1966-04-28', NULL, NULL, '2026-04-03T17:21:48Z', '2026-04-03T17:21:48Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('8aa1b716-e18f-48ce-8537-5e95e85a614b', '151e88a1-9576-4bd1-b84a-c4d64c1c9fe8', 4, 'The Crystal Conundrum', 'Crystal talks through her differences with the group, but the conversation takes an unexpected detour when she brings up old wounds — a stunning revelation that leaves Kyle completely confused. Erika tries to justify her stance on Tom’s legal situation, but Garcelle isn’t impressed. Lisa’s world is turned upside down by a family tragedy, Dorit begins therapy and Diana is confused by Sutton’s dietary choices.', '2022-06-01', NULL, '/1KoCIuYM5xYDPZC5lTBQ02wqBY7.jpg', '2026-04-03T16:34:58Z', '2026-04-03T16:34:58Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('8aa2c489-ccd3-42ce-9c88-893e5c9b02a4', '06030129-ff2d-4490-b66c-9f41bbe7aabd', 16, 'Ferry', 'John goes off to Hampton to see a ferry. When Rosie and Jim see a boat that''s going to the same place as the Ragdoll, they fear that it''s going to cause a crash, but of course, it doesn''t. John hops aboard a ferry to be transported from one path to another that has the river as a collision.', '1990-12-17', 15, NULL, '2026-04-03T17:19:36Z', '2026-04-03T17:19:36Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('8aa6a78d-490c-4beb-a032-71060fac4b43', '1e085f65-4b69-4500-8ffc-654d2f638dbb', 21, 'Elmo and Abby''s Ocean Adventure', 'After Abby turns Sesame Street into a magical ocean, Dorothy disappears, and Elmo and Abby must follow clues to find her.', '2024-03-28', 26, '/70oJJXiEpdErO0ynIjiN8ydX9J2.jpg', '2026-04-03T17:36:51Z', '2026-04-03T17:36:51Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('8aabaf73-c0a3-4ee6-be57-d2d73ac4548d', 'ea73e13c-6962-4804-8305-c303df65f89f', 13, 'The Royal Wedding (3) - Variety show in the Neighborhood of Make-believe', 'The Neighborhood of Make-Believe stages a variety show, which includes a ballet called "The Purple Glove Ballet".', '1969-02-26', NULL, NULL, '2026-04-03T17:35:38Z', '2026-04-03T17:35:38Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('8ab0530c-765b-4208-a608-5b8aad4914ad', '58adb9ab-3f1b-4a11-87b6-9b0b2dbb6aaf', 18, 'Poké Pawn', 'Get ready to GO with the Pawn Stars as a very valuable Pokémon collection makes its way into the shop. Will Rick battle for a sale or will he be defeated? And next, it’s about time the Pawn Stars got a 1926 Dunhill Watch Lighter in the shop, but does it spark enough interest to be worth buying or will the deal flame out?', '2017-07-10', 21, '/7DuUR8NuBnxrKgFyqeHqDuqut4n.jpg', '2026-04-03T16:34:21Z', '2026-04-03T16:34:21Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('8ab25ed0-336c-4aee-a214-e247274cf82f', '4c79c0b6-21a4-4277-8967-be1e791efdbe', 5, 'Mother''s New Hat', 'Mother and Father are out shopping with the children when they pass a hat shop. Father says he’ll buy mother a new hat, and Mother tries on a flowery one and then a hat with a feather. While she’s doing this Pingu and Pinga are amusing themselves by also trying on hats. Mother isn’t sure which of the two hats she wants, but her mind is made up for her as the shopkeeper sells the first hat to another customer, so she ends up with the feathered one. When they get home Mother and Father are both tired out and fall asleep. Pingu comes in the room, sees them asleep, takes the hat out of its box and puts it on. He then goes into the bedroom, puts on a blanket as a cloak and gets a wooden sword, and then plays at musketeers. He twirls the hat around on the tip of his sword but it comes off and Pinga catches it. Pinga puts the hat on and Pingu chases her round the room, and they then have a tug of war with the hat. Pinga ends up with the main part of the hat, and Pingu with the decorative flower, which has come off the hat. Pingu sticks the flower back on, but in the wrong place, and Pinga says that it’s wrong. Eventually they fix up the hat, and manage to sneak it back into its box just before Mother and Father wake up. Mother and Father decide to go for a walk and Mother opens the hat box to get out her new hat, but is very surprised when she sees it as it now has more feathers and a lot more flowers on it than when it was bought. Pingu and Pinga are downcast with Mothers reaction, but are delighted when Mother decides that she likes it. Mother and Father then go off for their walk, and Pingu and Pinga congratulate one another.', '2005-01-07', 5, '/iP06jRMlGYgOQJgMfKgO1cKA7Yg.jpg', '2026-04-03T17:22:20Z', '2026-04-03T17:22:20Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('8ab4c093-1f9c-4f68-b2b7-63d83776b94e', '225b0f03-984b-47f3-a1a3-d3e92175e39d', 81, 'Episode 81', 'with Christopher Trace, Valerie Singleton and John Noakes.', '1967-07-13', NULL, NULL, '2026-04-03T17:21:48Z', '2026-04-03T17:21:48Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('8ab6193c-32de-4404-bfc4-ee5b39105f62', 'd0e5568d-939d-4d89-ab4e-c291a90691cf', 13, 'The Farm', 'Kipper, Tiger (wearing his proper farmer''s boots), Pig and Arnold are off to the farm. Arnold finds a large white egg and makes a nest for it in his buggy. The others tease him, but soon the egg hatches and a duckling appears. It joins it''s mother duck and six brothers and sisters and soon Kipper with Arnold on his shoulders, Tiger slipping in the mud as he carries the buggy, and finally Pig, join the end of the fluffy procession.', '2000-12-21', 8, NULL, '2026-04-03T17:10:49Z', '2026-04-03T17:10:49Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('8ab77712-08e8-48e5-a417-78db8b1e2563', '45e01c04-6ac6-41e1-87d8-f749ee230385', 40, 'Episode 40', '', NULL, NULL, NULL, '2026-04-03T17:14:38Z', '2026-04-03T17:14:38Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('8ab9a9cc-4069-4e64-a493-6e5473253605', 'a6ed03e0-c05f-48f8-9f56-3f1da50e1792', 34, 'Episode 1349', '', '1980-01-10', NULL, NULL, '2026-04-03T17:36:33Z', '2026-04-03T17:36:33Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('8ac14895-7f62-4890-a029-d06b270e17f6', '0e419615-4c96-4dde-8ed2-715770ba77bb', 1, 'Welcome To Woodland Valley (1)', 'In the first part of "Welcome to Woodland Valley," viewers learn that a tragic event has happened in Woodland Valley --- a tree has fallen and ruined part of the village library. Everyone''s upset about it, but the entire Woodland Valley community is pulling together to help out. When the kids of the Big Blue House, including Harry, find out, they decide to help in their own way. Viewers explore more of Woodland Valley than they''ve ever seen before, visiting the library, the post office, the general store and the mouse school that Tutter will be attending, among other locations.', '2002-09-09', 25, NULL, '2026-04-03T17:35:32Z', '2026-04-03T17:35:32Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('8ac36a98-9541-402c-93da-e6523894a7f8', '793a6b2c-7cad-4f12-a943-74729e3d9ca6', 7, 'DELETE ME', '', NULL, 5, NULL, '2026-04-03T17:24:24Z', '2026-04-03T17:24:24Z');
