INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('8ac97087-266f-42ca-bb5f-3cf7b483dda0', 'b6baa6ec-0908-4a47-9001-7e7158985002', 5, 'Butterfly and the Bog Beast', 'The class needs a new mascot for its soccer team. Phoebe suggests butterflies, but everyone thinks they’re wimpy—until The Friz flutters in!', '1995-10-07', 25, '/6s2NKBGQvRSBmiwQUxrcmj45y2a.jpg', '2026-04-03T17:37:48Z', '2026-04-03T17:37:48Z');
