INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('8c1dffc4-b697-40b3-95a5-4a763a3a9fe9', 'bf722849-cddb-452b-9c0f-7f0d96e94c26', 3, 'Responsibility', 'Annie vows to safely deliver her mother’s cakes on her new bike, but she is tempted by Zach’s challenge to a bike race; the resulting accident wrecks her new bike and the cakes. When Annie blames Zach for the accident, Plato spins several tales about the nature of responsibility.', '1996-09-03', 30, NULL, '2026-04-03T17:38:34Z', '2026-04-03T17:38:34Z');
