INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('8c48e82a-5e14-4205-a82f-f36741f718ca', 'f5266c49-eb29-4594-b5d9-f927edfee336', 14, 'Missing Piece', 'Shaun comes across a discarded jigsaw puzzle.', '2014-02-20', NULL, '/mfONRioAZIk0msAUEs1db2bwNRJ.jpg', '2026-04-03T17:39:32Z', '2026-04-03T17:39:32Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('8c4e85ee-d162-4f58-8fbc-9e3bfc349af2', 'db555b98-87d6-4cd2-b7b4-973f9206cb1e', 1, 'New Friend, New Flames', 'Shannon feels better than ever after shedding over 40 pounds and the baggage of her marriage. She immediately hits it off with Kelly’s new friend, Braunwyn, a mom of seven children. Gina starts the year dealing with the ramifications of a recent DUI, while Emily takes on the role of single mother when her husband Shane studies for the California BAR exam. Kelly settles down and is smitten with her new beau, a successful plastic surgeon. Tamra has moved into a new home in her dream neighborhood of Coto de Caza, but is troubled that her sons are not speaking.', '2019-08-06', 44, '/zUhYJIkybB682aUkhN9PPIlCLSi.jpg', '2026-04-03T16:35:34Z', '2026-04-03T16:35:34Z');
