INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('8c5c0f2e-9cb8-4640-af4a-afb3a95131b4', '6f731e6b-d3c5-4de6-84e1-7a19cb650e86', 9, '60''s Pawn', 'The swinging 60s have taken over as the Pawn Stars look back at some of their favorite items: an original Playboy Bunny outfit, a golf ball belonging to President Lyndon Johnson, two tasty coconut cups from the set of "Gilligan''s Island," some unused Beatles tickets, a possible fragment of the Apollo 11 heat shield, a Batphone, and a set of Jimi Hendrix prints that are working their voodoo on Rick.', '2015-11-19', 21, '/gBUfTnlBu1PxfsPshh5oDmyQym6.jpg', '2026-04-03T16:34:20Z', '2026-04-03T16:34:20Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('8c67306b-e082-4d1d-b4b2-127c3480ad30', 'a605edf8-69ba-46db-8c0c-523b1ef5447b', 53, 'Episode 53', 'with John Noakes, Peter Purves, Lesley Judd', '1973-03-15', NULL, NULL, '2026-04-03T17:21:51Z', '2026-04-03T17:21:51Z');
