INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('8c78a544-4a85-4078-8bb6-4a4a9228bc70', '2f8dd629-82c3-4f8e-87c0-963473c49284', 12, 'A Tantrum and a Truce', 'The Puerto Rico trip continues as the women shop and explore San Juan; Erin reveals an explicit picture of Abe to Jenna and Brynn that draws criticism from others; Racquel prepares to see her mother for the first time in six years.', '2024-12-17', 43, NULL, '2026-04-03T16:35:26Z', '2026-04-03T16:35:26Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('8c7a037e-2e35-42d2-a880-c9d28dfddbbc', '58adb9ab-3f1b-4a11-87b6-9b0b2dbb6aaf', 24, 'Business is Brewing', 'Business is brewing at the Gold & Silver Pawn Shop as Rick takes a look at a couple of antique beer items. With beer on his mind, Rick hops over to his friend''s brewery in San Diego to tap into the drink''s history. Also, the guys track down an original McCormick Farmall tractor, but how far will they dig into their pockets for it? And later, Corey must decide if he wants to take action on a "Django Unchained" signed movie slate, while Chum figures out if a print of "Dogs Playing Poker" is a King or a Joker.', '2017-07-31', 21, '/pXGJofU93lxfWzCBx87UtNTUOPz.jpg', '2026-04-03T16:34:21Z', '2026-04-03T16:34:21Z');
