INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('8ca82d2b-0d22-4018-b7fd-46b67357a777', '70c8cb46-2494-4dd4-98f6-6bfb9b3faf73', 27, 'Deals from Hell', 'The Pawn Stars meet a man hoping to sell a several hundred-year old edition of one of the world''s most hellish books - "Dante''s Inferno." Will they pass through the gates of hell for this evil epic or will they be tricked by the devil? Then Rick is presented with an antique serpent shaped sword from the Philippines. Can he hold on to the twisted steal weapon or will this deal slither out of his grip? And later Corey has a chance to purchase photo rights to the late great King of Pop: Michael Jackson. Can he make a "Thriller" of a deal or will he moonwalk straight out of the negotiation.', '2010-06-21', 21, '/mrc0ZJvVeab20Z3LvOK2djBHepV.jpg', '2026-04-03T16:34:16Z', '2026-04-03T16:34:16Z');
