INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('8cb8ccb2-85e6-4d65-9c33-f00a200fedbb', 'de8ec769-16bb-436b-be43-aedc7e18a7d7', 21, 'The Fluffster Kerfuffle', 'When Rudy tries to use Julia’s special toy, Fluffster, as part of a game he’s playing with Elmo and Abby Cadabby, Julia gets very upset. Alan explains that Fluffster helps Julia feel calm, so it’s not a toy she likes to share. Rudy apologizes, and the friends find a different way to play together.', '2020-04-06', NULL, '/tx1Va5Db5LdJq8HD1IJEJAr9HBf.jpg', '2026-04-03T17:36:50Z', '2026-04-03T17:36:50Z');
