INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('8d0fff3d-11fa-49ba-b95c-38e8a0556551', '204d86fb-d99c-4fd1-8dcd-9c1bcfd3c33f', 49, 'Just the Two of Us', 'Zak and Wheezie are working on a secret project and decide to work on it by themselves, but they find it is easier to complete it when they let their friends help them with it.', '2002-04-13', NULL, NULL, '2026-04-03T15:26:04Z', '2026-04-03T15:26:04Z');
