INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('8d18088e-2997-4398-a632-36e8233359d4', 'ffc2a75e-0ffa-4b26-b121-9b91b277594a', 5, 'Friend Or Faux', 'Kandi wants everyone to resolve their differences over a dinner. Phaedra and Kenya get skirmish over Apollo''s lies. Nene and Cynthia come face to face.', '2014-12-07', 43, NULL, '2026-04-03T16:34:47Z', '2026-04-03T16:34:47Z');
