INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('8d1ec93f-ec09-451c-8eef-5bd3ee6407ed', '0e419615-4c96-4dde-8ed2-715770ba77bb', 14, 'Appreciation Day', 'It''s an ordinary day at the Big Blue House, but Bear decides to check his calendar, wondering if there''s anything special coming. He checks his calendar and finds that tomorrow is Teacher Appreciation Day. Wondering if Tutter and the other mice at Mouse School know, he decides to tell them before soccer practice. It turns out when he arrives that the mice were just in the middle of talking about how much they like Miss Maxwell. Bear decides to split them all into teams of two, and partners Tutter with Lily to make Miss Maxwell a gift. Tutter''s not too sure about the arrangment at first, worrying that the shy and quiet Lily won''t be very good at helping him to make Miss Maxwell a gift. Bear, however, persuades Tutter to give Lily a chance and things start coming together nicely. They write a poem for Miss Maxwell. There''s another special appreciation surprise later on. In the Shadow segment, Shadow retells Aesop''s Fable ''The Lion and the Mouse''.', '2003-10-27', 25, '/c3JIOEeD16wGzQHkMNi0HCmH6Tk.jpg', '2026-04-03T17:35:32Z', '2026-04-03T17:35:32Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('8d24ec2c-e2f3-438c-92d6-5892a32f7cad', '54facb0b-db59-41fe-9d64-c7c7221a3c81', 14, 'Caught Between an Ex and a Hard Place', 'On the first night in Miami, Sonja hits the floor after one too many drinks; the women turn their attention to Luann''s attitude. The ladies rally to take in sunshine and art. At a house party, Ramona juggles her ex-husband, Mario, and a new date.', '2019-06-05', 60, '/f8KgZUhoV4c7Pur9WYDcYlCeqhD.jpg', '2026-04-03T16:35:25Z', '2026-04-03T16:35:25Z');
