INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('8d4d3f3c-81d2-4c2d-a26b-832393406e2c', 'c4d795ae-6afa-47d6-9819-4dd057030a3c', 23, 'Reunion (Part 3)', 'The Bye Wig party saga continues; Cynthia glows while talking about her whirlwind romance with Mike Hill; the women discuss the drama surrounding Eva''s wedding party; tensions rise as NeNe and Cynthia go head to head.', '2019-04-21', 43, NULL, '2026-04-03T16:34:48Z', '2026-04-03T16:34:48Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('8d4e3b8d-b1b4-4545-ab64-fe258fd4d066', '54c29014-2dbd-49ff-a23f-cf4c546e0b3a', 14, 'Sex Lies and Facials', 'A Saratoga trip ends with a wives-gone-wild night on the town. Later, Ramona bonds with Avery before her college departure; Sonja''s facialist spreads gossip to Kristen; LuAnn throws a charity auction; and Aviva hosts an art party.', '2014-06-10', 60, NULL, '2026-04-03T16:35:23Z', '2026-04-03T16:35:23Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('8d4eb8fc-1407-46bd-8114-23e774d8019a', '9b144910-398a-47d4-9ccd-823d25cc8b0a', 18, 'Dinasty of Denial', 'New alliances are formed after the trip; Kathy goes to college for a day with her daughter; Teresa invites her ally, Dina, to her Fabellini release party.', '2012-09-09', 43, '/dhHmQgd9xIUWzVepJD8Oxm648jN.jpg', '2026-04-03T16:35:15Z', '2026-04-03T16:35:15Z');
