INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('8d57b2da-acd8-4909-a650-9bc447b3414e', 'dbde6570-a68d-4fd7-a1b0-a6037a266a18', 21, 'Reunion (1)', 'Alexis demands an apology for being called phony; Gretchen accuses Vicki of hypocrisy regarding her relationship with Brooks.', '2012-07-10', 44, NULL, '2026-04-03T16:35:31Z', '2026-04-03T16:35:31Z');
