INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('8d592b79-4dfa-425f-a52d-7acdfac82d10', '4d2cac0f-38fd-438b-8afa-acf43952e535', 24, 'Episode 24', 'A weekly programme for younger viewers.  Including The Story of San Marco, a scale model serial and The Fox and the Crow, a story with pictures by Tony Hart.  Introduced by Christopher Trace and Leila Williams.', '1959-03-26', NULL, NULL, '2026-04-03T17:21:47Z', '2026-04-03T17:21:47Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('8d59b122-835b-4c0c-a84c-8d337889cbae', '4d0fd8a5-5200-4dfc-b96c-ae436dc8803c', 1, 'Tar Beach', 'LeVar''s presence looms over New York once again, this time literally. He''s taken to the roof of one of the nondescript skyscrapers, very close to the bridge mentioned in the featured book, Tar Beach.', '1992-10-05', 30, NULL, '2026-04-03T17:36:18Z', '2026-04-03T17:36:18Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('8d5f143e-7572-4cd7-86bb-1d893fbfc727', 'b3a8be17-d09a-4b92-b8ab-b4897f9777f6', 5, 'Episode 5', '', '2003-05-27', 25, NULL, '2026-04-03T17:21:19Z', '2026-04-03T17:21:19Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('8d6b709e-830e-4e84-b7b4-faf0b1a3e968', 'abfe14ee-db42-4dde-a96a-601ff3c53ecc', 5, 'Cluny''s Clowns', 'A traveling circus comes to Redwall and Cluny uses it to try in infiltrate the abbey with his lieutenants, dressed as clowns. The mysterious circus star, Wild Ivy the Knifethrower, seemingly mesmerizes Matthias. But she is, in fact, an ally. As Cornflower is threatened with death by Cluny, Ivy turns her circus against the rats in an acrobatic battle of fire-eaters versus fur! And Wild Ivy has seen - that Matthias and Cornflower are destined to be together - if Redwall survives.', '1999-09-18', NULL, '/xyZEEqKvFvCTWkRcN69eLRETtkD.jpg', '2026-04-03T17:12:08Z', '2026-04-03T17:12:08Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('8d6e6383-0173-4af8-931f-01a9cf2de484', '79c64e0a-3488-41bc-9b5c-2243ff15b373', 2, 'Bearing It All', 'After an evasive conversation at the Summer Solstice party, Boz and Rachel are left wondering about the sincerity of certain friendships. Erika turns to Sutton for support amid a looming lawsuit. Kyle opens up about the ending of her first relationship since separating from her husband. Dorit fights back tears as her divorce takes a toll on her family. New housewife Amanda meets the group at Jennifer Tilly’s racy Sip & Draw party.', '2025-12-11', NULL, '/S47yat3BXgBWYqgVGgFzU2P3WX.jpg', '2026-04-03T16:34:59Z', '2026-04-03T16:34:59Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('8d70413e-fa83-4724-b75c-18b5cb73d7e8', '7c422193-b078-49d8-81ef-f2b9f94f059d', 69, 'Vegetable pageant', 'Episode #3074', '1993-02-11', 55, NULL, '2026-04-03T17:36:39Z', '2026-04-03T17:36:39Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('8d76fee7-ab71-4fb1-8287-468802ac43ad', '699572f8-2bff-4515-8df3-6e7d1a21f346', 11, 'Gets Programmed', 'Ms. Frizzle’s class opens the school for Mr. Ruhle. But there’s so much to do! “There must be a way to do these chores without actually doing them,” says Carlos. Enter Mr. Ruhle’s new computer and Mikey, Carlos’ whiz kid brother!', '1997-11-22', 25, '/jV1L4bS1bDh3iRsLnOwc4w2B4ce.jpg', '2026-04-03T17:37:49Z', '2026-04-03T17:37:49Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('8d7dc8f0-2107-405d-ad47-e2ff4590c724', '871570b4-bf2f-4ba1-9940-65fb932cb009', 11, 'Ms. Parks Goes to Washington', 'Phaedra hosts a trip to Washington, D.C., to gain support for her Save Our Sons organization. Elsewhere, Kenya''s family drama continues following her return from Detroit, leading to an argument with her aunt; Cynthia and NeNe reconnect over cocktails.', '2016-01-17', 43, NULL, '2026-04-03T16:34:47Z', '2026-04-03T16:34:47Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('8d8a15a1-9eb5-46ba-9a58-22c1cf35a441', 'ebc99729-ccb7-4d64-82c1-42708cd7ba85', 66, 'Episode 66', 'Will Goldie''s puppies qualify as trainee guide-dogs for the blind? Today''s the day they take their all-important tests when Puppy Walking Manager Derek Freeman puts them through their paces in the studio.', '1981-04-30', NULL, NULL, '2026-04-03T17:21:55Z', '2026-04-03T17:21:55Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('8d8cc402-996b-4c2a-8be2-3a8c7c807b79', '6fd9fd9d-e378-411b-94b1-76ba4bd518fe', 17, 'Episode 17', 'with Christopher Trace and Valerie Singleton.', '1965-11-15', NULL, NULL, '2026-04-03T17:21:48Z', '2026-04-03T17:21:48Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('8d8de5c7-6722-403d-ba73-1cb730f359bd', 'd5f0284f-0ee3-45bf-8539-d02a825d15b2', 17, 'Havana Nights', 'Alexia moves into her new apartment; Guerdy shaves her head in preparation for chemotherapy; Adriana hosts a release party for her new song with Emilio Estefan; Larsa and Guerdy''s ongoing feud explodes and forces Russell to step in and speak up.', '2024-02-21', 44, '/6gmBXoxfkWtdslYFv8TSqdYX0Di.jpg', '2026-04-03T16:35:12Z', '2026-04-03T16:35:12Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('8d8df687-3d8a-441b-8da4-0775d24d9c02', 'd034c38d-c0c7-42b4-8876-394b63d84275', 13, 'Girl Fight', 'In the Season 6 finale, Vicki leaves the hospital and continues to deal with her personal problems. Despite all this, she still hosts her annual fall party. Drama lets loose at the bash, especially when ex-cast member Jeana Keough reenters the picture.', '2011-06-05', 44, '/z8OUYBKYpUct19xNV0xi9a004Mb.jpg', '2026-04-03T16:35:31Z', '2026-04-03T16:35:31Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('8d9db412-27f6-4359-bc0a-2211f26175a4', 'd034c38d-c0c7-42b4-8876-394b63d84275', 10, 'It''s Not a Competition', 'Peggy and Alexis discuss their ever-fraying relationship, but their conversation only creates more tension. Meanwhile, Slade''s mother arrives and corners him about his job status; and Vicki and Peggy gather for some wine and whine.', '2011-05-08', 44, '/v7uQD9DqSG1hu2TXFA2KMSaPeFe.jpg', '2026-04-03T16:35:31Z', '2026-04-03T16:35:31Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('8da8d488-d9be-4b10-96c0-7680087cfd4b', 'f5474771-8930-41eb-b0d4-db442233acee', 8, 'Ocean''s Deadliest', 'Steve Irwin is joined by oceanographer and adventurer Philippe Cousteau, grandson of the famous oceanographer Jacques Cousteau, in OCEAN''S DEADLIEST as they explore the waters between Australia''s Gold Coast and the Great Barrier Reef. Throughout this expedition, Philippe and Steve come face to face with venomous fish, huge great white sharks and amazing saltwater crocodiles as they search for the region''s most dangerous animal.', '2007-01-21', 44, NULL, '2026-04-03T17:39:10Z', '2026-04-03T17:39:10Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('8dad347f-0ce3-427f-90e3-004ed836cd9f', 'e1063f87-66c2-4e2d-a913-53362941aa19', 89, 'Episode 364', '', NULL, NULL, NULL, '2026-04-03T17:36:29Z', '2026-04-03T17:36:29Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('8dad3f37-d22f-4dfe-82ac-091e10391fbc', '939d270c-ea8e-4cc8-a5a5-e59df2c8062c', 10, 'Girls Trippin’', 'A newly married Caroline leaves husband Sergio behind to whisk the women away on away on a girls trip to Nurai Island; secrets are revealed during salacious games of Never Have I Ever and Two Truths and a Lie', '2022-08-10', 44, '/phkAmc7blx90ZTdRGvbKQ5BRgoG.jpg', '2026-04-03T16:35:07Z', '2026-04-03T16:35:07Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('8db7489e-e0bd-4ea3-958b-3d53d338acc1', 'e606692a-47b7-411e-b54b-7c6bf61a67b7', 10, 'It''s Red! It''s Green!', '', '2002-10-14', 30, '/JBnnQi3AjuVDnzLqCCEZTuc0w5.jpg', '2026-04-03T17:12:29Z', '2026-04-03T17:12:29Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('8db8644c-ff33-4e51-a241-a68137c2030d', '7eef937c-4483-42bd-bafe-263a7d4e4573', 6, 'Shows and Tells', 'Arnold brings in a webbed hoop for the International Show-and-Tell Competition, left behind by his great-aunt, a famous archaeologist, but he has no idea what it is! Can the kids find out what it is before he takes the stage? With Alex Trebek as the “Sportscaster.”', '1996-10-19', 25, '/4CGc70V82FGbM8dplUsDqRJrwoJ.jpg', '2026-04-03T17:37:49Z', '2026-04-03T17:37:49Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('8db945ed-e2a5-4e79-bea1-8fe4dbdf40be', '05c0e384-194c-4417-9f62-803eb615e409', 100, 'Height and weight', 'Mistee Rogers shows the comparison between two different scales: one to weigh groceries and one to weigh humans. Nurse Miller gives physicals to the neighbors. Lady Elaine refuses to cooperate, turning King Friday upside-down.', '1968-07-05', NULL, NULL, '2026-04-03T17:35:38Z', '2026-04-03T17:35:38Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('8dc772e2-c344-4fd3-bdaf-07f862d6d303', '8a5892f6-ccb7-4f02-9a5a-85b134b5f0cf', 23, 'DELETE ME', '', NULL, 5, NULL, '2026-04-03T17:24:25Z', '2026-04-03T17:24:25Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('8dcfacc1-5d50-47af-acf4-fe456a050d8f', '1c9ea7d3-e254-4e7b-8a9f-33eea9c6c341', 4, 'Love, Marriage, and Sour Peaches', 'On top of the float for WorldPride, Cynthia and NeNe come face to face for the first time since their fallout. Porsha confronts the reality that Dennis was unfaithful. Kenya is forced to acknowledge the growing divide in her long-distance marriage.', '2019-11-24', 43, NULL, '2026-04-03T16:34:49Z', '2026-04-03T16:34:49Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('8dd069b3-735e-43f6-95f0-571d691d8690', 'ea73e13c-6962-4804-8305-c303df65f89f', 60, 'Good rules', 'King Friday completes his set of rules for Lady Elaine''s rocket. Once these rules are followed, the rocket rides more smoothly.', '1969-05-02', NULL, NULL, '2026-04-03T17:35:38Z', '2026-04-03T17:35:38Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('8dd20063-3b8e-4c79-9375-d0c0c2018503', 'a605edf8-69ba-46db-8c0c-523b1ef5447b', 74, 'Episode 74', 'with John Noakes, Peter Purves, Lesley Judd', '1973-06-04', NULL, NULL, '2026-04-03T17:21:51Z', '2026-04-03T17:21:51Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('8dd9967a-d55f-4a04-ac5b-3326212b83e2', '05c0e384-194c-4417-9f62-803eb615e409', 90, 'Presents', 'Mister Rogers brings signs to talk about. After Betty Aberlin visits to bring a gift from King Friday and Sara Saturday, she goes back to Make-Believe to hear King Friday''s announcement that everyone will get a big surprise next week.', '1968-06-21', NULL, NULL, '2026-04-03T17:35:38Z', '2026-04-03T17:35:38Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('8dde65bb-a37d-4980-a932-16b3e42a8d76', 'a3a2c2fb-8276-412c-9d86-5175167be1d7', 14, 'Episode 14', 'with Valerie Singleton, John Noakes, Peter Purves', '1971-10-28', NULL, NULL, '2026-04-03T17:21:51Z', '2026-04-03T17:21:51Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('8ddff561-4d32-443d-9f42-715fd08dbe35', 'fa6f43f4-b944-4c33-ac69-dddbf54c0c16', 2, 'The Nightingale', 'Cathay, a kingdom with harmony and peace. A simple kitchen maid, whose mother is very sick, learns of magical faeries and a root that can cure even the worst disease. She also comes across a beautiful bird, the nightingale, that she soon falls in love with its song.  The emperor, is unpleased to learn that his great and vast palace does not completly please the poets, rather a simple bird, the nightingale, does. His royal court gets the bird, with the help of the kitchen maid, and the emperor is very pleased. After a while, an artificial bird is given to the emperor as a gift. He banishes the other the nightingale. But when the artificial bird breaks, he suddenly becomes deathly ill. It''s up to the nightingale to save him, but will she after he banished her? Mick Jagger portrays the emperor very well, Barbara Hershey is superb as the kitchen maid, and Edward James Olomos is great as the prime minister. The Nightingale has a great message and great fun!', '1983-05-10', 51, '/1yx6LkljpgttBCloLyDeZi8taYW.jpg', '2026-04-03T17:38:40Z', '2026-04-03T17:38:40Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('8defd152-d622-48dc-b77e-5fa7a55ac942', 'bf874be3-7e2f-4a0e-b205-c76ac1ad69fc', 1, 'The Seinfeld Story', 'While doing his stand up act, Jerry takes questions from the crowd. One of the questions is "where did the series come from?" An often asked question, Jerry responds by showing a videotape he''s prepared.', '2004-11-25', 22, '/1MTwKm5Jr3FbJtNmvMS7waqmXXh.jpg', '2026-04-03T16:34:08Z', '2026-04-03T16:34:08Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('8df1f482-241b-430a-b830-d28b39af1237', 'ebc99729-ccb7-4d64-82c1-42708cd7ba85', 25, 'Episode 25', 'Last year nine million Blue Peter viewers raised nearly £4 million to help the starving people of Cambodia. Today you can discover more details about the 1980 Appeal. Your help is urgently needed, so have a paper and pencil handy to take down the Appeal address. There''s good news for pocket money savers too, because Sarah will be showing a Christmas present to make for Grannies and Grandads - so keep a look out for old margarine carton lids - and all will be revealed!', '1980-12-01', NULL, NULL, '2026-04-03T17:21:55Z', '2026-04-03T17:21:55Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('8df2d289-c15e-4ac2-b8dd-61d2fb2eba2e', '227b8429-0dfd-47e4-b874-c37da20c403f', 15, 'Fired Up', 'The Pawn Stars want to buy an airplane propeller that may be historically tied to Charles Lindbergh - can they find an expert or documentation to confirm the link or will this deal crash and burn? Then when a man brings in a 1750s Flintlock Musketoon, Rick has doubts about its authenticity. And later a young man brings the Old Man a key chain that he believes belonged to Willie Nelson - the only question is - which one.', '2009-11-30', 21, '/s3Xh6aQ3GvGQrbTA8i4Gba7U4UY.jpg', '2026-04-03T16:34:15Z', '2026-04-03T16:34:15Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('8df61953-bc51-4bff-84b1-173ee72b6e78', '42e591e2-2a88-4434-ae9f-3d4b1d685613', 14, 'Rage Against that Machine', 'Aim, fire, twist and repeat as the Pawn Stars check out a pair of rifles with double rotating barrels. Designed to give 19th century hunters a 2nd chance, will Rick fire up a quick offer? Then, Corey and Chumlee check out a pair of cleats worn by Yankees legend Bucky Dent during his famous home run. Can they knock this deal out of the park? And later, when Chumlee breaks the coffee machine, the Old Man sends him on a quest for the perfect cup of joe.', '2013-07-18', 21, NULL, '2026-04-03T16:34:18Z', '2026-04-03T16:34:18Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('8df9214f-7391-4488-b52c-cdefab70db7b', '9ae29d08-7ce8-47f9-8584-2d3e861067a8', 10, 'Fly', 'Walt becomes obsessed with a contaminant in the lab and refuses to finish the cook until it is eliminated. A frustrated Jesse attempts to get Walt back on track.', '2010-05-23', 48, '/3ns0vN3bEl7elFWoodHJ9nDBogC.jpg', '2026-04-03T15:40:33Z', '2026-04-03T15:40:33Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('8e1d278c-b665-4c42-bed0-c0da1b0a1edd', '5a824218-5831-4c6d-aef3-8b5ba9147532', 30, 'Episode 1605', '', NULL, NULL, NULL, '2026-04-03T17:36:34Z', '2026-04-03T17:36:34Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('8e2139f7-75a1-4bed-9462-fdfa4f5daea2', 'bbfee3b4-9c95-48a6-beaa-791fa08b1f43', 60, 'Episode 60', 'Petra, the programme''s very first dog, survived the upheaval and today you can see her in her new place of honour in the Blue Peter garden.', '1984-04-09', NULL, NULL, '2026-04-03T17:21:56Z', '2026-04-03T17:21:56Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('8e25eba6-8cac-4ead-a16d-12556266aa12', '0fa92002-82ae-4609-85e3-3982baa99ae1', 21, 'Postman Pat and the Grand Custard Race', 'At the annual sports day, Bill realises that taking part is more important than winning, and is rewarded with a Best Team Player rosette. Then, the adults have a mucky custard race, which ends with Pat covered in custard.', '2005-03-27', 15, '/bRFs81xiO8ERCV4j69OFxNyRdCk.jpg', '2026-04-03T17:14:30Z', '2026-04-03T17:14:30Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('8e28e064-3dc7-4b20-a7c3-703c123b1a44', 'f8b69754-3e41-45e5-832a-64d9c2809ad7', 8, 'Vanishing Act', 'It''s family past day and Bernard''s Great Grandfather was a Pig Farmer. Bernard decides to liven things up until Nicolette manages to steal the watch and will break it, will Bernard be able to retrieve it before the whole world freezes?', '2005-02-24', 15, NULL, '2026-04-03T17:20:06Z', '2026-04-03T17:20:06Z');
