INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('8e4043c8-1e09-4656-8f87-c1e22ea905d0', 'de8ec769-16bb-436b-be43-aedc7e18a7d7', 8, 'A Recipe for Dance', 'Chris and Rudy have trouble learning the dance moves in Nina''s dance class so they sneak out and leave. They realize that they shouldn''t give up so they practice and work together to learn the dance pattern and go back to join dance class.', '2020-01-04', NULL, '/bE1ijxbooDNFzh1sVYZpRMjBEMb.jpg', '2026-04-03T17:36:50Z', '2026-04-03T17:36:50Z');
