INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('8e499b08-bd09-433a-a304-cb544e0515cd', 'bf3ffafd-7d45-4f2c-9f1b-28001bd082db', 64, 'Episode 64', 'Today’s an important day for anyone who helped in the 3Bs Appeal for Guide Dogs for the Blind. John, Peter and Lesley will be reporting on the Auction that took place last Tuesday.', '1975-04-24', NULL, NULL, '2026-04-03T17:21:52Z', '2026-04-03T17:21:52Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('8e541b03-ab29-46a3-b0fe-ec83d37dbba2', 'd589b670-2e75-4922-9f56-029b48e54927', 6, 'Tell All 3', 'The Brown family sits down with television anchor Tamron Hall to dish about everything that happened on camera and off during the last season.', '2014-02-23', NULL, NULL, '2026-04-03T16:34:27Z', '2026-04-03T16:34:27Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('8e59fc05-7aa4-4ca5-a746-28326aaf7d5e', '27d0351a-92f5-4d01-995c-6b5928957075', 14, 'Trials and Tribulations', 'When Heather is asked about how she got her black eye, a heated argument ensues between her and Jen; at Heather''s book cover reveal party, rumors are revealed and tensions rise.', '2023-01-11', 44, '/tudf1ydTRq3cnrTDuJHIxbe3WJM.jpg', '2026-04-03T16:35:44Z', '2026-04-03T16:35:44Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('8e6077ea-3944-483a-9612-ae57aa002761', '8b6bbac8-e5ef-49c7-a5c1-197cfb19f772', 11, 'Mister Rogers Talks About Play', 'In Make-Believe, Bob Dog gets hurt playing, and King Friday bans all play. Mister Rogers says no one can learn or grow without play, but it''s important to play safely. He plays with a wooden riding toy and shows a video of how it is made.', '1981-07-20', NULL, NULL, '2026-04-03T17:35:42Z', '2026-04-03T17:35:42Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('8e60f64e-34ef-415f-9755-2de864deaf98', '20d7138e-eea8-46a8-8ada-2b0f0ee1f674', 36, 'Episode 36', 'Flying Treasure!

By road, air and sea your treasure is reaching the Appeal depot. Sarah takes to the skies and joins the Scottish Ambulance Service which is helping "Blue Peter" viewers in the remote highlands and islands to get their donations to the sorters.', '1983-01-17', NULL, NULL, '2026-04-03T17:21:56Z', '2026-04-03T17:21:56Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('8e65cea3-46d7-4719-95df-1cca475f2cc3', 'db555b98-87d6-4cd2-b7b4-973f9206cb1e', 9, 'Miracle at Miraval', 'The Miraval trip continues as Vicki unleashes another rumor about Kelly, leading Kelly to explode at the Tres Amigas. Everyone goes beekeeping, except Kelly, who stays behind. At beekeeping, Shannon flirts with the beekeeper. After, Emily and Gina hash through their issues. At dinner, an emotional discussion leads to an unlikely apology. And the ladies have some late-night fun in the hot tub, where Brauwnyn reveals how she celebrates Sean’s “monumental” birthdays.', '2019-10-01', 44, '/pCHzaROceDk2v5CbzJfMmpJmkr.jpg', '2026-04-03T16:35:34Z', '2026-04-03T16:35:34Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('8e67e680-ff43-4713-8575-3c9cd4f5378a', '04fb713d-9c59-45f7-8de0-acd7582daa53', 8, 'Bridezilla of Bimini', 'Tensions between Margaret and Danielle rise as Danielle’s wedding demands drive Margaret wild. As Jennifer’s family celebrates her brother’s engagement, Jackie meets with Dolores to try to understand what makes Teresa tick.', '2018-12-26', 43, '/yj7xt7ByvlECBLQChkMrh4OB3tr.jpg', '2026-04-03T16:35:17Z', '2026-04-03T16:35:17Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('8e6d8ead-d75b-4dcc-8106-e251b8876c55', '6c1ec19f-74df-4f35-9a61-17b98175d826', 5, 'Let the Mouse Go!', 'Lisa and Teddi butt heads over Kyle’s emotional meltdown. Garcelle celebrates a milestone in her sons’ lives, while Lisa struggles to stay in the shadows as her daughters launch their clothing line. Dorit and Sutton get into a cat-and-mouse game over a misunderstanding, and Erika notices the cracks in Denise’s laid-back facade when Denise is pushed to a new breaking point.', '2020-05-13', 43, '/fpzfvnkrO2nofG8t0otxeUkjaEK.jpg', '2026-04-03T16:34:58Z', '2026-04-03T16:34:58Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('8e6df61a-01fa-4dfd-82be-e4b9b534cfb8', '225b0f03-984b-47f3-a1a3-d3e92175e39d', 74, 'Episode 74', 'with Christopher Trace, Valerie Singleton and John Noakes.', '1967-06-19', NULL, NULL, '2026-04-03T17:21:48Z', '2026-04-03T17:21:48Z');
