INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('8e70d530-43a3-4c82-9383-3f7d34e9e5ff', '050d8ae1-6cc1-4018-933d-b3c3d13de856', 45, 'Episode 45', 'Lucky Winners!: Today''s the day the results of the competition to design the end papers for the new Blue Peter book will be announced. Don''t miss the judges'' choice.', '1985-02-14', NULL, NULL, '2026-04-03T17:21:57Z', '2026-04-03T17:21:57Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('8e747b94-84e0-4225-ac48-213a1ddd77e7', '432a6abd-dcca-44cc-82ce-fb39e33b8949', 25, 'Episode 25', 'Rogers builds a go-kart with spare parts. In the Neighborhood of Make-Believe, Grand-père begins to make French-fried potatoes.', '1971-03-19', NULL, NULL, '2026-04-03T17:35:39Z', '2026-04-03T17:35:39Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('8e86697a-fff2-48b2-8a82-ff578b2fd407', '3fc7c152-e4f6-426a-a899-36ec454c4403', 79, 'Don''t Bug Me!', 'While hunting for a Flutterby, Max scares Ord with a toy spider, but Max loves bugs and can''t understand how Ord could be afraid of them.', '2000-04-28', NULL, NULL, '2026-04-03T15:26:03Z', '2026-04-03T15:26:03Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('8e8af3f4-cb18-4cba-9d42-1ba253930751', '2dcbd122-86d8-46e8-bbe5-9143875abd34', 13, 'Binky Barnes, Wingman!', 'Binky Barnes has a favourite pastime when Bug Week comes along: Butterflies. He worked very hard to collect these bugs for his report especially a hard blue-coloured kind.', '1999-10-13', 13, NULL, '2026-04-03T17:37:56Z', '2026-04-03T17:37:56Z');
