INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('8e94d896-b329-48ff-bc8f-1a3d09f158ce', '3fc7c152-e4f6-426a-a899-36ec454c4403', 29, 'A Cool School', 'Max is nervous about his first day of school until Emmy takes him to the School in the Sky where Quetzal advises them, "When you''re stuck, don''t give up! Try something new".', '1999-10-08', 30, NULL, '2026-04-03T15:26:03Z', '2026-04-03T15:26:03Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('8e959825-a0c5-42ad-8469-0ea47f3d62c6', 'd5351b60-8a0c-482a-a6dd-4fb860cfe143', 3, 'Episode 1393', 'Mister Rogers arrives having driven his antique car. Taking viewers outside, he shows them the seatbelts before lending the car to Mr. McFeely to make deliveries.

At Negri''s Music Shop, Mister Rogers meets musician Hector Olivera who is playing the organ.

In the Neighborhood of Make-Believe, King Friday XIII gives a photograph of himself to the Platypus family to take on their trip so they can remember "what they are missing while they are away." He asks Handyman Negri to measure the giant Frisbee brought to Make-Believe by Barbara B. Frisbee. Meanwhile, Lady Elaine Fairchilde is warning the Neighborhood about a giant who is coming to throw the Frisbee and is offering seatbelts as protection. Barbara B. Frisbee suggests that everyone will learn the purpose of the giant Frisbee tomorrow.

Back at the house, Mister Rogers talks about how things often seem very big to children. In the kitchen, he uses various cut-outs to talk about "big and small."', '1975-02-19', NULL, NULL, '2026-04-03T17:35:41Z', '2026-04-03T17:35:41Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('8e959bcc-74e7-4d5d-a2f3-5d6eb949f4fa', '79c831cf-2837-48fe-9e27-059281dc30de', 4, 'Big Ben Boing', 'Neil visits Big Ben in Westminster, London.', '1998-01-16', 10, NULL, '2026-04-03T17:19:38Z', '2026-04-03T17:19:38Z');
