INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('8ea82471-7755-4625-a530-5e89dabfe1a3', '9c5608b2-5111-48bc-a907-7f93472c1e03', 18, 'Build a Better Basket', 'Alan, Rosita, and Elmo put together a basket filled with goodies for Little Red Riding Hood to take to her grandmother''s house, but she''s concerned that it may not be strong enough to stand up to the Big Bad Wolf.', '2013-02-14', 58, '/d1ZS1vqv5aosqPRE5rQvBImBPfM.jpg', '2026-04-03T17:36:47Z', '2026-04-03T17:36:47Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('8eac0986-32c3-4999-93b7-dd40ea79cf98', '04e133fd-c4a3-4dfa-8369-c6dcfd1e3a5a', 26, 'Oscar hides', 'Oscar retreats to his trash can seeking peace from Sesame Street''s cheerfulness. His neighbors'' repeated attempts to find him create funny situations that eventually bring him back out.

Sponsors: C, S, 5', '1984-12-24', NULL, NULL, '2026-04-03T17:36:35Z', '2026-04-03T17:36:35Z');
