INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('8eb3449d-ca90-4c86-9151-fe69329c743f', 'bf874be3-7e2f-4a0e-b205-c76ac1ad69fc', 5, 'Inside Looks: Male-Unbonding', 'Inside look from the season 1 episode "Male-Unbonding."', NULL, 3, NULL, '2026-04-03T16:34:08Z', '2026-04-03T16:34:08Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('8eb4a74a-6407-4da4-a156-a5b4bc747490', '050d8ae1-6cc1-4018-933d-b3c3d13de856', 1, 'Episode 1', 'Safari to Kenya

Every year teams of ornithologists from all over the world compete to see how many birds can be spotted in 24 hours. Simon and Janet head north west out of Nairobi, at the start of their 2,000 mile safari, and track down the man whose team holds the record for 1984.

Terry Stevenson notched up 290 species, but had 1,055 possibilities - Kenya''s a bird spotter''s paradise! Don''t miss today''s first report, and catch up with the latest news about the four-legged members of the Blue Peter team - Goldie, Jack and George the tortoise.', '1984-09-10', NULL, NULL, '2026-04-03T17:21:57Z', '2026-04-03T17:21:57Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('8eb9d7a2-6cc2-4a9f-89bd-f5f193201c0b', '98d80972-e53a-43dd-a03a-7703465e6f87', 27, 'Lunch Larceny', 'Lock and load with the Pawn Stars as Corey and Chumlee check out an 1838 Colt Paterson. Formerly owned by a Civil War colonel, will the guys take a shot at this rare firearm? Then, a letter written by Franklin D. Roosevelt gets hand-delivered to the shop. Written shortly after FDR''s bout with polio, can Rick endure a tough negotiation for this piece of presidential history? And later, when Rick''s lunch keeps disappearing, he''s on a mission to find the culprit. Will evidence point to the usual suspect?', '2013-02-18', 21, NULL, '2026-04-03T16:34:18Z', '2026-04-03T16:34:18Z');
