INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('8f2c7d6c-012c-4071-86f5-d414e30abdf2', '671bd4da-3470-40f9-9a03-40fba34d2b8e', 2, 'Please Don’t Feed the Hecks', 'After Frankie gives neighbor Nancy Donahue an old scarf that is just sitting around gathering dust, Nancy returns the favor by baking her a delicious apple pie. Believing she’s stumbled upon a way to get free and tasty meals, Frankie makes it her mission to find miscellaneous items around the house to give to her in exchange for some culinary delights.  Meanwhile, Sue and Lexie prepare to move back into their college apartment but find that it’s been sublet to a man who refuses to leave; and Axl’s new job as the school bus driver gives him a chance to see how Brick’s high school sophomore year is treating him, and he discovers that Mike has refused to speak to Brick’s class on Career Exploration Day.', '2017-10-10', 22, '/6HEauc2GRikvELlxlRYT6xVrfW3.jpg', '2026-04-03T15:40:31Z', '2026-04-03T15:40:31Z');
