INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('8f42b517-0a43-41f1-a822-18c57a7c0c68', 'e6359e6d-9bdb-4aba-9cba-6f7ddd6328f9', 20, 'Reunion (2)', 'Strong emotions persist as Dorit and Teddi struggle to sort out a year of misunderstandings; Kyle reveals the devastating details of her house burglary last Christmas; Camille Grammer joins the ladies and brings an unexpected gift for Andy.', '2018-05-01', 43, NULL, '2026-04-03T16:34:57Z', '2026-04-03T16:34:57Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('8f48cc0d-8f66-40cc-bc55-fee947d0e338', 'cefd1496-b649-4c62-aef9-35a22558ac08', 13, 'Reunion Part One', 'The Real Housewives of Dallas reunite for a dramatic two-part reunion. As D’Andra dances a fine line between loyalty and accountability, Stephanie gives her two cents on Two-Face, and Kameron’s bitter taste for raunchy humor resurfaces. Cary and Brandi lock horns over plastic surgery allegations while a mystery guest causes LeeAnne to be anything but quiet on the set.', '2017-11-06', 44, '/A98ESI6mKGnbim8tvkATt0IFXTm.jpg', '2026-04-03T16:35:04Z', '2026-04-03T16:35:04Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('8f4d2642-3248-4a36-9973-f64439e03339', '65d1cad8-0120-425e-ae9b-5020ce773b32', 3, 'Knee Deep in Lies', 'Heather finds herself negotiating a birthday conundrum; Jenn and Katie support their kids as they move in and out; Shannon introduces her dating bench to Emily and Gina; Katie''s apology attempt to Shannon is met with an explosive reaction.', '2025-07-24', NULL, '/kvKVZHISqMgCzJPu1KzRd0OvnVd.jpg', '2026-04-03T16:35:36Z', '2026-04-03T16:35:36Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('8f4e8a71-0e6c-4351-864f-906e12a11142', '53f9624f-fcf8-4f77-82f6-d2eb3f5376ee', 23, 'The Stars Will Fall From the Sky', 'As Christine''s new dynamic with David continues to flourish, she realizes that she was more alone with Kody than she understood.', '2025-05-04', NULL, '/tbzecgZbGPME2ractIBHtfLKWB5.jpg', '2026-04-03T16:34:33Z', '2026-04-03T16:34:33Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('8f504bcd-0c2a-404f-a7df-f933fdea96ca', '5144de59-e67f-4fcf-919b-7106989ab797', 14, 'Cute Is as Cute Does', 'Julie wants to emulate her favorite singer, Penny Candy, but sees her true colors when a crisis in the greenhouse hits. Nuzzle bores Sizzle to sleep when he tries to show her a photo album of when he was a puppy. Leon and Ben only make cameo appearances.', '1995-02-02', 29, NULL, '2026-04-03T17:12:21Z', '2026-04-03T17:12:21Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('8f524908-8eb3-41b0-b56b-7bfe385a42fb', 'dbd3583f-e9b2-46d1-a37e-309eb666e233', 1, 'Nothing Ventured, Nothing Gained', 'The ladies of Atlanta are back and handling their business. Kandi branches out from her music career to start an adult toy line, while Phaedra begins her own strange undertakings. Cynthia gets the buzz going for her modeling school with a little help from celebrity runway coach Miss J. A very pregnant Kim prepares to move in to a luxury home with boyfriend, baby-daddy, and young NFL star Kroy Biermann. NeNe''s stock has risen since hanging with Donald Trump on Celebrity Apprentice, but Sheree confronts her on a business deal gone bad.', '2011-11-06', 43, '/vONYNipaP4mbYwcWJI2VgCoFSbb.jpg', '2026-04-03T16:34:45Z', '2026-04-03T16:34:45Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('8f5aa563-bc2a-4295-ada0-f321ce04ebb2', '7b19039a-31ac-425c-8fb1-b51cf2447821', 4, 'The Aftershock', 'As Shannon’s housewarming party continues, Braunwyn attempts to reconcile with Gina. After Braunwyn heads home following the disagreement with Gina, the ladies bond over some tequila shots. Gina shocks Emily when she reveals Braunwyn invited her to a meeting as an olive branch. Elizabeth speaks to her anxiety and stress about her upcoming divorce trial. Meanwhile, Kelly can’t wait for Rick to be transferred from New York and move to California full-time, as their addiction for each other grows. After attending her first meeting, Braunwyn calls Shannon to apologize in hopes that she will attend her upcoming 20th anniversary vow renewal.', '2020-11-04', 44, '/oIlHr4ZzMueTF5epGfmAphcoa7O.jpg', '2026-04-03T16:35:34Z', '2026-04-03T16:35:34Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('8f5d805d-28e4-4d85-9c5c-3ca551c93216', 'a3a2c2fb-8276-412c-9d86-5175167be1d7', 49, 'Episode 49', 'with Valerie Singleton, John Noakes, Peter Purves', '1972-03-02', NULL, NULL, '2026-04-03T17:21:51Z', '2026-04-03T17:21:51Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('8f60fdce-b70c-4bb0-ae91-7a9ffe5b5963', 'a4843a51-aeef-427c-902c-7fb3bd670cd4', 18, 'Working Like a Bear', 'It''s time for Bear to go to work, and a bear''s work is berry-picking. He invites the viewers to join him as he locates his berry-picking bucket and hunts for berries to fill it, including strawberries, boysenberries, blueberries, blackberries and huckleberries. Before he finds his bucket, he finds Ojo and Treelo playing in the living room. Their game has come to a halt, as Ojo is tired of Treelo pretending to be a baby. Bear helps her to find something new to play and shows her how Treelo can still be the baby in the new game. Bear learns about Tutter''s work, which includes cleaning up his mousehole and shopping for cheese. Shadow sings the song "I''ve Been Working on the Railroad" and gives Bear a tip as to where to find his berry-picking bucket. Later, after Bear finishes his work, Bear talks with Pip and Pop and helps them to see that they too did work today.', '1997-11-13', 25, NULL, '2026-04-03T17:35:31Z', '2026-04-03T17:35:31Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('8f61707b-ee4b-42bd-92a0-c961b4855d0b', '53587a7e-cd93-44f0-ad79-5fe586dccb8e', 9, 'Snowy Day', 'Kipper must take advantage of the weather after he wakes up one morning to find everything covered in snow.', '1997-10-31', 9, NULL, '2026-04-03T17:10:48Z', '2026-04-03T17:10:48Z');
