INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('8f6e6884-0efe-4d62-9f11-34604aa8df9a', '5c1b881f-ac58-4d72-b63f-209952d4f902', 52, 'Episode 52', 'With Mothering Sunday only six days away, now''s your chance to beat the high cost of flowers in the shops and make some everlasting violets that cost only a few pence. (Have a paper and pencil handy to jot down the instructions.)', '1980-03-10', NULL, NULL, '2026-04-03T17:21:54Z', '2026-04-03T17:21:54Z');
