INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('8f85b2a8-33e5-4ab6-80ba-44bc7b59eac4', 'ecb64ef3-4f80-45a7-b4a9-c04434b02e35', 27, 'April Fooled', 'Charge into battle with the Pawn Stars when Corey checks out a Civil War era sword made by Tiffany & Co. Will he capture the unique weapon or be forced to retreat? Then, the Old Man sails down memory lane with some mementos from his former ship, the USS Chowanoc. Will this Navy nostalgia cause him to ship wreck or will he float away with a sweet deal? And later, when Chumlee misses his chance to retaliate on April Fool''s Day, the guys lay down the rules of pranking, but is the joke on him?', '2014-04-03', 21, '/ebTs3EzLAABb2hIL5lwlu6jCZdy.jpg', '2026-04-03T16:34:19Z', '2026-04-03T16:34:19Z');
