INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('8fc55f8d-b6da-4621-acbc-21d93e0fd417', '5a771f52-fe96-4ea2-b567-a8dde899059e', 30, 'A Treasure Remembered', 'It''s time to say goodbye to the toughest, grumpiest, and most-loved patriarch at the Gold & Silver. Rick, Corey, Chum, and a host of colleagues from the shop remember "the Old Man" - Richard Benjamin Harrison. Enjoy some of the Old Man''s best moments over a decade of funny jabs, odd sayings, fierce negotiations and great buys on Pawn Stars.', '2018-06-27', 21, '/dalrKeMnONrbOOvq7cvez2meQ8E.jpg', '2026-04-03T16:34:21Z', '2026-04-03T16:34:21Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('8fd082e9-ad56-419b-b935-18f0bd2ae4d1', '4892e2af-46c1-4b4e-ac81-eac161b5a347', 34, 'Episode 34', 'During the Second World War the skies of Britain were criss-crossed with beams of light searching out the enemy aircraft. Today one of those searchlights, on its way to the RAF Museum in Hendon, makes a lightning visit to spotlight the Television Centre.', '1978-01-09', NULL, NULL, '2026-04-03T17:21:53Z', '2026-04-03T17:21:53Z');
