INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('90004ccf-fa11-4c74-a9ae-9fbf84ea64ac', 'c21dbd22-5e2e-4414-bb67-750399aaf6f0', 29, 'Pawn with the Wind', 'The Pawn Stars see dollar signs when a $1 bill signed by Clark Gable comes into the shop. Allegedly signed while he served in WWII, will the guys try to cash in on this rare bill, or is it not worth the paper it''s printed on? Then, Corey and Chumlee are presented with a rare 1800s Wells Fargo double barrel shotgun. Made to protect stage coaches in the Old West, will the guys bravely ride shotgun on this deal, or will a misfire cause them to surrender? And later, a souvenir from Ulysses S. Grant''s funeral makes its way into Rick''s hands. Will he see this tribute as a vital piece of presidential memorabilia, or will this keepsake be dead on arrival?', '2012-03-05', 21, NULL, '2026-04-03T16:34:17Z', '2026-04-03T16:34:17Z');
