INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('90120da2-273c-4116-af49-a9a029c06af1', '05c0e384-194c-4417-9f62-803eb615e409', 44, 'Auditions for the opera', 'Title number 0044. Opens with Mister Rogers arriving with a milk bottle. Mr Rogers takes care of a baby chimpanzee. Reardon holds auditions for his opera while Mrs. Frogg provides the costumes. Sara Saturday has to babysit during the opera so Henrietta decides to be a babysitter in the opera.', '1968-04-18', 28, NULL, '2026-04-03T17:35:38Z', '2026-04-03T17:35:38Z');
