INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('90194b50-5854-43d5-adc3-3291059d0e48', '4da606e7-9d23-4682-8bd5-f535e1da706f', 3, 'Franklin''s Gift', 'Franklin made a beautiful present for his mom for Mother''s Day.  He was so proud of it.  But when he heard what his friends have gotten their mothers, he wasn''t so sure about his home made gift after all.', '1998-09-14', 12, NULL, '2026-04-03T17:40:14Z', '2026-04-03T17:40:14Z');
