INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('901e8569-fa60-4018-a987-821d3a097af2', '4da606e7-9d23-4682-8bd5-f535e1da706f', 25, 'Franklin''s Test', 'Franklin so desperately wants to win a pen during a spelling test that he cheated.  When Bear didn''t get a pen because he didn''t pass the test, Franklin felt guilty for not earning the pen fairly.', '1998-11-30', 12, NULL, '2026-04-03T17:40:15Z', '2026-04-03T17:40:15Z');
