INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('90294e67-7bfa-4964-b347-b4d49224138b', '6ef86c27-33e7-47e5-a053-483059dfd16d', 54, 'Episode 54', 'A World War II bomber 15 metres below the freezing, murky depths of Stoney Cove quarry in Leicestershire, is just one of the obstacles Sarah faces during her latest diving test.', '1982-03-22', NULL, NULL, '2026-04-03T17:21:55Z', '2026-04-03T17:21:55Z');
