INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('90fcb56d-7eb1-459c-b225-076da3fecd5c', '8012f05a-66a3-4254-885f-0a679393f3dd', 6, 'Four Days of the Cockatoo (2)', 'Gaby finds a name tag on the bird and learns that its a palm cockatoo, and they nickname the bird Calypso. Casey still can''t understand why she can''t go home to her mother. Gaby decides to make some flyers for Calypso''s real owner. Hawke finds one of them and makes a phony call pretending to be the bird''s real owner. Just then Calvin arrives at Lenni''s house and informs the team that palm cockatoos aren''t permitted in the usa. The team realizes that Gaby is giving the bird to a smuggler,so they leave hoping to warn Gaby before it''s too late.', '1994-11-06', NULL, NULL, '2026-04-03T17:40:28Z', '2026-04-03T17:40:28Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('90fd39e0-d34c-49d0-adc4-b91bc5046b71', 'c4717644-555d-4df1-aec0-c095b101e7c0', 3, 'Summer', 'In this episode of Reading Rainbow, LeVar shows the kids the different sights and sounds of Summer. The different wildlife of Summer, and how they live. Also, there are segments on the different seasons and how they effect different parts of the country. The featured book is "Summers" written by Ron Hirschi, and read by Ossie Davis.', '1994-10-05', 30, NULL, '2026-04-03T17:36:18Z', '2026-04-03T17:36:18Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('90ff3da9-f6ce-4ed8-9163-980c6ae93d52', 'd405f973-4c7e-4cb6-b7c0-d09a884c9b35', 5, 'Following Pecking Orders', 'Jill returns from Australia a new woman---or so she says. Her newfound sense of purpose to avoid gossip quickly ends when she dishes about Ramona during lunch with Kelly, LuAnn and Sonja. In addition, Sonja details the group''s "pecking order" dynamic; Cindy and Ramona meet for drinks, but tension spills over.', '2011-05-05', 42, '/1dZa7D3gjksigCwhDdVIL6JZbyK.jpg', '2026-04-03T16:35:22Z', '2026-04-03T16:35:22Z');
