INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('9136fc32-86c8-40bb-8d49-eead1bcd1b3b', 'c21dbd22-5e2e-4414-bb67-750399aaf6f0', 10, 'Apocalypse Wow', 'The end is near for the Pawn Stars when they check out an alleged original print by Renaissance artist Albrecht Durer. Known for his depictions of the apocalypse, will the guys battle demons to capture this valuable work, or is this demonic image more than they bargained for? Then, Corey feels like a third wheel when he checks out two trike-style motorcycles in the same day. Both equipped with V8 engines, will Corey be overpowered by these tricked out machines, or will a tough negotiation "tri" has patience? And later, a guy comes in with a statue of 80''s advertising icon Spuds McKenzie. Will Rick and Chumlee try to tame this party animal, or has this dog already had his day?', '2011-12-26', 21, NULL, '2026-04-03T16:34:17Z', '2026-04-03T16:34:17Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('913714b8-f51c-4456-989f-2792cbaccf62', '9193e795-da7c-40ec-b68f-f63aa7d5174f', 272, 'Jon''s Inner Struggle', 'The show creators discuss Jon''s changing sense of mission over time.', '2014-02-18', 1, NULL, '2026-04-03T15:40:35Z', '2026-04-03T15:40:35Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('9138f6b3-07a0-4121-8cbb-ef50b90ebb6f', '42253cb1-e961-4018-8dd9-8a69e6f70873', 22, 'Episode 2247', '', NULL, NULL, NULL, '2026-04-03T17:36:37Z', '2026-04-03T17:36:37Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('9139b75f-1a03-407e-8a1b-076d81b3e36d', 'cc140989-c480-4586-b460-8872b416a0b7', 6, 'Dive to the Coral Reefs', 'Within the sea, lies a combination of scuba diving and (just slightly) snorkeling as LeVar and a friend of his dive beneath the ocean to explore a living coral reef and the life around it. Fran Brill narrates Dive to the Coral Reefs, a book that shows the life and structures of the beauty that lies beneath the sea.', '1990-03-26', 30, NULL, '2026-04-03T17:36:17Z', '2026-04-03T17:36:17Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('913eef58-56cb-4823-b8c8-439581525eb6', '6fd9fd9d-e378-411b-94b1-76ba4bd518fe', 66, 'Episode 66', 'with Christopher Trace, Valerie Singleton and John Noakes.', '1966-05-09', NULL, NULL, '2026-04-03T17:21:48Z', '2026-04-03T17:21:48Z');
