INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('915b6300-e81c-48bc-a1aa-603ef80a8810', 'cb8a0322-be77-485b-b339-bdd572bca349', 18, 'The Return of the King', 'When Mr. Ratburn''s class goes to a medieval style fair, his old teacher Mr. Pryce-Jones comes with his new class. Mr. Pryce-Jones'' class wins all the games.', '1998-11-26', 13, NULL, '2026-04-03T17:37:56Z', '2026-04-03T17:37:56Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('915dd88d-640f-46ab-b255-1d4f5d677412', 'cc140989-c480-4586-b460-8872b416a0b7', 4, 'Ludlow Laughs', 'Ludlow is a big grump who never laughs or even smiles. One night he has the funniest dream ever. When he starts laughing, the whole world laughs with him. Also includes LeVar "Clowning Around", Stand Up Comic and book reviews for Pig William, Shake My Sillies Out and The Make Me Laugh! Joke Books.', '1989-07-06', NULL, NULL, '2026-04-03T17:36:17Z', '2026-04-03T17:36:17Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('9160525d-e922-4a7b-b3b7-002a157249c7', 'f812042d-eb85-432e-8047-3675886e0b1b', 19, 'One Thousand and One Tails', 'While greed threatens to grip the humans around him, Wishbone imagines himself as Ali Baba among forty thieves.  The sheer power of 1001 Arabian Nights seems overwhelming.', '1995-11-02', 28, NULL, '2026-04-03T17:10:42Z', '2026-04-03T17:10:42Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('91630831-69f9-4c0f-bb15-82062d185c28', 'db555b98-87d6-4cd2-b7b4-973f9206cb1e', 12, 'Fashion Show Faux Pas', 'Braunwyn’s daughter Rowan makes her debut at OC Fashion Week with her clothing line Dark Rabbit. Shannon takes on the role of momager as she coaches daughter Adeline on how to walk a runway. Rowan and Adeline triumph, while Braunwyn and Kelly back each other up in an argument about Dr. Deb. Meanwhile, Gina gets a new look as she grapples with whether to reconcile with her ex or move forward with a new relationship. Eddie learns about Tamra and Braunwyn’s time in Del Mar. Emily and Braunwyn bond over a discussion about the father figures in their lives. Tamra’s son Ryan has a tattoo removed and agrees to go to therapy.', '2019-10-22', 44, '/4mSGVkOXB9hIz7grF9Hf0PzMWLt.jpg', '2026-04-03T16:35:34Z', '2026-04-03T16:35:34Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('9166af27-2cc8-4a81-bbb1-510e9bcc2626', 'e48599f8-66ff-4c0f-9274-65b9ae1cda9e', 64, 'Episode 64', 'Doctor Who Make  There''s another four months before Dr Who returns to television, but why wait? Ask your grocer for a large cardboard box and build your own toy theatre complete with scenery and monsters. Have a pencil and paper handy for details.', '1977-04-28', NULL, NULL, '2026-04-03T17:21:53Z', '2026-04-03T17:21:53Z');
