INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('91919490-a590-4901-8075-9bf889003d3c', 'b892884d-7b56-4255-a4c6-08f5d0122273', 4, 'Desert', 'Why do camels huddle together in the heat? Which desert stays below freezing for half the year? DESERT treks across the earth''s most parched places to find some of the greatest stories of adaptation and survival. Meet the extraordinary inhabitants of the desert, and witness their startling strategies to capture and conserve that most precious of all commodities - water.', '1996-09-23', 29, '/sZreOodjvvVgj748XQ3eWTmS3uk.jpg', '2026-04-03T17:39:04Z', '2026-04-03T17:39:04Z');
