INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('91b15c81-4b3e-48b7-8e6a-c24b571f3695', '4fe93658-c463-4329-8e64-9d523869c2cb', 21, 'Darth Pawn', 'Make sweet music with the Pawn Stars as they check out a 1763 Stradivarius violin. Found in an attic, could this violin play a tune worth a million bucks or will this deal hit a sour note? Then, Rick and Chumlee meet a man selling life-sized Star Wars figures. Will Rick use the force and buy these rare pieces of galactic memorabilia or will this deal end up in a galaxy far far away? And later, Rick and the Old Man check out the World War II airplane''s version of GPS, an octant. Can they successfully navigate their way to a deal or will they hit turbulence?', '2011-01-31', 21, '/8FzaQS5L6xSoeQOaoeDd3zOQXxj.jpg', '2026-04-03T16:34:16Z', '2026-04-03T16:34:16Z');
