INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('91e84cc1-c43a-4e4d-8630-5bddd71a2404', '0987f081-b3b7-4e3c-abb7-795e56c279d5', 14, 'The Smile', 'Frankie and Mike worry that Axl may not get a sports scholarship; Sue''s school science project involves smiling; Brick wants an iPad.', '2013-02-06', 22, '/rxJ9vkOSc8PhbM206R3U4RcrZHu.jpg', '2026-04-03T15:40:30Z', '2026-04-03T15:40:30Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('91ea7fec-7e18-4b01-a8fb-972a98bccb90', 'c21dbd22-5e2e-4414-bb67-750399aaf6f0', 2, 'Patriot Games', 'Hit the gridiron with the Pawn Stars when they check out a 2004 Super Bowl ring. A genuine player''s ring from the New England Patriots, will the guys rush for extra yardage for this ultimate piece of sports memorabilia, or will a tough negotiation leave them three and out? Then, a guy brings in a diary written by his ancestor during almost every major battle of the Civil War. With a handwriting style nearly impossible to decipher, will they be able to unlock the secrets of the past, or are these memories lost to history? And later, a poster from the movie Bullitt comes roaring into the shop. Signed by Steve McQueen, Robert Duvall, and Jacqueline Bisset, will Rick jump into the chase for this rare piece of movie history, or will some suspicious signatures leave him idling at the side of the road?', '2011-11-28', 21, NULL, '2026-04-03T16:34:17Z', '2026-04-03T16:34:17Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('91eb85ca-bafb-4de7-b09a-c0696aa8c0a3', '8c3cfac1-d882-4904-b38c-d1981628d00e', 32, 'Episode 32', 'Has the Medi-Bike Appeal hit the jackpot? Find out today if your old stamps and coins have reached the target of 400 Medi-Bikes.', '1979-01-01', NULL, NULL, '2026-04-03T17:21:54Z', '2026-04-03T17:21:54Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('91f44a82-cd1e-4cc7-a603-7425b2375c6e', '04e133fd-c4a3-4dfa-8369-c6dcfd1e3a5a', 46, 'Elmo rhymes / Snuffle puppet show', 'Elmo discovers the joy of rhyming while the Snuffle Puppet Show returns with entertaining new performances. Both activities bring laughter and wordplay to Sesame Street.

Sponsors: J, K, 12', '1985-01-21', NULL, NULL, '2026-04-03T17:36:36Z', '2026-04-03T17:36:36Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('91fae39e-099d-497c-8934-d08e70548565', '5db3ff78-e439-48e1-8f67-988ecbf85d17', 22, 'The Jungle Adventure', 'Dogtanian and Pip are still stranded on the island. Pip is hungry so they walk inland to find some food, they find some fruit which Pip knocks from the top of a tree. Before Pip can tuck in they hear a strange noise and go to investigate. They find a "monster with a tail where its mouth should be", also known as an elephant stuck in the mud. They go in to rescue it, Dogtanian doing most of the work, but before it''s out a crocodile comes in. Pip tries to catapult a rock at the croc, but launches himself onto its back, Dogtanian tries to duel it but has to run and is caught in its mouth. The elephant uses his trunk to throw some trees on the croc and saves the day.', '1982-02-26', 24, '/7yGpIahRg2Rf35wk78YkzNMoc6y.jpg', '2026-04-03T17:18:43Z', '2026-04-03T17:18:43Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('91faf7e9-31d7-400b-a5f1-a983e9b0d5a6', '6053b5c1-ce86-425c-8166-e0fcc3466061', 63, 'Episode 63', 'with Valerie Singleton, John Noakes, Peter Purves', '1970-04-27', NULL, NULL, '2026-04-03T17:21:50Z', '2026-04-03T17:21:50Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('91feaaab-5409-49e3-a8e0-75807250ca0f', 'f1959b84-1930-4f85-b2fd-9000b3abf48a', 29, 'Episode 808', '', NULL, NULL, NULL, '2026-04-03T17:36:40Z', '2026-04-03T17:36:40Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('9203e9e5-13a8-4e5a-91a8-1559c7eb04fe', 'd5383b3d-5636-4d71-b99c-b84774b4b3c6', 5, 'Pingu Shows What He Can Do', 'Pingu and Pinga are playing outside the igloo with the bricks, seeing how high they can get a pile without them falling over. Pingi arrives on her scooter, and, unseen by Pingu, watches them playing. Pingu and Pinga laugh when a particularly high pile collapses. Pingi laughs as well; Pingu hears and is surprised to see her. Pingu pretends that he wasn’t enjoying the game, and tries to act macho. Pingi asks Pingu if he’ll come with her, on his scooter. Pingu abandons Pinga, leaving her to play on her own, and goes off on his scooter with Pingi. As they ride away he pretends that he’s on a motorbike by making appropriate engine noises. Mother comes outside, sees Pingu and Pingi riding away, and then sees that Pinga is playing on her own, so she joins her. As Pingi goes on ahead, Pingu hides behind a nearby ice column, then calls out to her. Pingi returns, stops near the ice column and looks around. Pingu comes out from behind the column on his scooter and rushes off. Pinga turns and follows him. They reach some abandoned igloos. Pingi gets off her scooter and enters one. Pingu follows, and then kisses her hand. Pingi responds by giving Pingu a big kiss on the cheek. Pingu is delighted, and exuberantly performs all sorts of tricks on his scooter, to Pingi’s amusement. They then ride around the igloos a bit more before making their way back to Pingu’s home. When they arrive they find Mother building a tower of bricks for Pinga, which Pinga then blows down, and they all laugh.', '1998-01-09', 5, '/bTENHuJYMx19X9bVytd74O24qsN.jpg', '2026-04-03T17:22:20Z', '2026-04-03T17:22:20Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('9204983d-c772-45b5-8f1d-b0f87f3e90cb', '050d8ae1-6cc1-4018-933d-b3c3d13de856', 41, 'Episode 41', 'Happy Birthday, Jack!

Britain''s favourite silver tabby was 9 years old on Tuesday, but he''s still the fastest cat on four paws, and whether he''ll do his famous disappearing act during today''s birthday celebrations is anyone''s guess!', '1985-01-31', NULL, NULL, '2026-04-03T17:21:57Z', '2026-04-03T17:21:57Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('921ab0d5-64f8-4fb8-ac16-c74cb4c4b489', '573fa62f-55a9-4f17-97cc-d1a005a83cc8', 8, 'Nursery Rhyme Day on Sesame Street', 'Reporters Elmo and Abby offer strategies to Nursery Rhyme characters experiencing big feelings of excitement, nervousness, and frustration.', '2025-03-06', 26, '/iR6kce6QtJwy75skJjXjdPeyU8O.jpg', '2026-04-03T17:36:52Z', '2026-04-03T17:36:52Z');
