INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('921e5b01-23e6-4b0d-8590-fa0d6d675df9', 'f4c40307-9b5e-4263-a4e0-dfa138131e7f', 97, 'Talk, Listen, Connect: Deployments', 'This bilingual multimedia outreach program is designed to support military families with children between the ages of 2 and 5 as they cope with the feelings, challenges, and concerns experienced during different phases of deployment.

Elmo faces a difficult transition when his father, Louie, is away. While Louie is away, Elmo''s mom consoles her son, and lets him know that it''s okay to feel nervous about seeing his father again after their time apart. They pass the time while they''re waiting by keeping a daily routine. When it''s finally time for her husband to come home, Elmo''s mom bakes a cake and helps Elmo and his friends decorate for the homecoming.', '2005-08-30', NULL, NULL, '2026-04-03T17:36:27Z', '2026-04-03T17:36:27Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('92218684-e261-4447-bffe-613b0b4a331d', 'a860511c-b630-415e-99a1-a9e0922fbfd7', 14, 'Buster''s Garden of Grief', 'Fritz asks Buster to take care of the community garden for him while he recovers from his ankle injury. Buster has to stop short when he finds out he''s going on a camping trip with his mother. So, he asks Muffy, Francine and Arthur to care for the garden for him.', '2012-05-24', 13, NULL, '2026-04-03T17:38:00Z', '2026-04-03T17:38:00Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('9223c2a7-9a4e-4825-9276-5a31b00b2a46', '98d80972-e53a-43dd-a03a-7703465e6f87', 19, 'Funny Money', 'Get boxed in with the Pawn Stars as they check out an original work by Pablo Picasso. Will the guys shell out some green, or leave the seller feeling blue? Then, a guy moseys in with a saddle used by John Wayne in the movie "True Grit." Do Rick and Corey duke it out over this rare piece, or send the seller riding off into the sunset? And later, a scissor katar knife from the 1800 s slices into the shop. Can Chumlee talk the guys into cutting a deal?', '2013-01-21', 21, NULL, '2026-04-03T16:34:18Z', '2026-04-03T16:34:18Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('9231d3d0-5b6e-41b5-acc0-8fe08fb884c1', 'f593d90c-5339-42f5-9c88-5bfd48d04075', 24, 'Bitzer''s Basic Training', 'Bitzer thinks The Farmer is planning to replace him, so Shaun helps to knock his friend into shape. Unfortunately Bitzer goes completely over the top with his training regime and starts running the farm with military precision driving everyone crazy.', '2010-05-16', NULL, '/6mIRZpFmlbTdGGWPhniYnfGd3zC.jpg', '2026-04-03T17:39:31Z', '2026-04-03T17:39:31Z');
