INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('923cf5fc-ff0d-4172-879a-7bfb16b7f18e', 'c06f15e3-1abd-4c6c-a4ef-93f3eb85cc89', 3, 'Lord Snow', 'Lord Stark and his daughters arrive at King''s Landing to discover the intrigues of the king''s realm.', '2011-05-01', 58, '/8HjOlb4slc1xusMgOtoNpxuTgSI.jpg', '2026-04-03T15:40:35Z', '2026-04-03T15:40:35Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('9241d983-33e3-491e-9647-0a991a645985', 'da06465b-9154-4feb-a455-374df7dab02f', 5, 'As the Porridge Cooled (4087)', 'Telly is doing a “Monster on the Spot” report about Baby Bear, who is telling the story of what really happened to the three bears as their porridge cooled.  Instead of walking, they were very active as they ran and jumped through the woods.  Suddenly, they find they’re lost in the magic garden of a wizard who put a spell on them and turned them into ducks.  Baby Bear, using fun science words, tests his hypothesis that the type of animal they turn into depends on the kind of animal sound they make.  Through his experiment, he finds out that his guess is correct!  They all make bear sounds and transform into bears again.  The wizard wouldn’t let them out of the garden until they name three things about vegetables.  With the help of the Singing Vegetables singing, “We Are the Vegetables,” the three bears figure out that vegetables are delicious, are good for you…and are musical!', '2005-04-08', NULL, NULL, '2026-04-03T17:36:44Z', '2026-04-03T17:36:44Z');
