INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('926a2164-4d14-41c2-97e7-bd8e41ec3b98', '05c0e384-194c-4417-9f62-803eb615e409', 24, 'Mister Rogers gets an eye exam', 'Title number 0024. Opens with Mister Rogers arriving with eye charts. Mr. Rogers has his eyes examined. King Friday wants Donkey Hodie''s windmill to be built somewhere else.', '1968-03-21', 29, NULL, '2026-04-03T17:35:38Z', '2026-04-03T17:35:38Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('927387a7-fadb-496c-bb56-cfbc52d6785d', '876145f4-b55e-4070-b35b-893a67f88bac', 6, 'Bay Breezes and Bad News', 'Frank tries to get to the bottom of David’s intentions towards Dolores. Teresa reveals a surprising secret about Danielle and Marty. Finally, Joe Giudice gets a decision on his immigration appeal. On the other hand, Jennifer roasts the ladies as part of her birthday celebration.', '2019-12-11', 43, '/rmtFS1MonLEhO8y56VnPWOury1g.jpg', '2026-04-03T16:35:18Z', '2026-04-03T16:35:18Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('92745ac2-83ed-4090-b2eb-2f58eb19c17a', 'c01ddd2a-bdb1-4c97-8d04-58f791ef1c24', 27, 'Fast and Slow', 'Between the cheetah and the snail, the Kratts find a great deal about the speed of animals.  Then there is the chameleon, which varies speed a good deal.', '1999-06-28', 27, NULL, '2026-04-03T17:10:55Z', '2026-04-03T17:10:55Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('927556c2-b6aa-43ee-9417-f689d7095257', 'c21dbd22-5e2e-4414-bb67-750399aaf6f0', 7, '$=MC2', 'The Pawn Stars try to stay focused when a limited edition photograph of Albert Einstein comes in the shop. An iconic image from the cover of Time Magazine, if the price goes up, it must come down. Then, Rick and Corey are presented with a collection of confidential documents from the Pentagon. Possibly found at a yard sale, will Rick seal the deal on these Vietnam-era reports or will this classified treasure get him into hot water? And later, the Old Man takes the day off to tour a World War II era B-17 Bomber. With Chumlee along as his driver, will these two have the guts to fly in this 65-year-old Flying Fortress, or will they chicken out and keep their feet on the ground?', '2011-12-19', 21, NULL, '2026-04-03T16:34:17Z', '2026-04-03T16:34:17Z');
