INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('92926e2a-2d64-4e65-ade7-92461c99951b', '852a07b0-f228-4197-9147-7aeed79390bf', 16, 'Be Mine, Galentine', 'Leah clashes with her mother during a family dinner and Luann takes up a sobering, new business venture; Sonja has an untimely brush with Covid-19, spurring a close-knit girls trip back to Ramona''s in the Hamptons.', '2021-08-24', 60, '/usGOqZvxYUimBdqn7I8osFIy0ig.jpg', '2026-04-03T16:35:26Z', '2026-04-03T16:35:26Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('929b451a-3d45-4c4c-8cd6-0347fa30b529', 'c01ddd2a-bdb1-4c97-8d04-58f791ef1c24', 2, 'Eye Spy', 'After admiring the camouflaged coats and amazing night vision of two visiting black jaguar cubs, Martin and Chris build a pair of  "Eye-Spy goggles", a contraption that lets them see the world as various animals do. Jackie replants the evergreen that was her Christmas tree and decorates it with apples and popcorn for the birds.', '1999-01-26', 27, NULL, '2026-04-03T17:10:55Z', '2026-04-03T17:10:55Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('929d7969-d093-4173-b0f4-4266e4b76514', '61e0c9d9-337e-4fe4-a0fd-e567b29af115', 3, 'Basketball, Bobbleheads and the Brow Girl', 'Whitney takes the women on a girl''s trip to Milwaukee, but things heat up when Bronwyn confronts Lisa for not defending her at the ropes course. Meredith reveals an unsavory rumor about Whitney''s jewelry line to Heather. Angie discovers something shocking about Britani''s on-again boyfriend, leaving her to break the news to Britani. The women enjoy a VIP experience at a basketball game where Meili confronts Lisa.', '2024-10-02', 43, '/mjGtairpaG2bZjapUXjCSTlaHZr.jpg', '2026-04-03T16:35:45Z', '2026-04-03T16:35:45Z');
