INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('92aa8b20-f045-4c07-b831-9da62689e62f', '5c1b881f-ac58-4d72-b63f-209952d4f902', 61, 'Episode 61', 'Metric or Imperial?  The results of a nationwide survey of 19,000 viewers are announced on today''s programme. Find out how children voted in England, Northern Ireland, Scotland and Wales, and whether their mums, dads, and grandparents agreed with them!', '1980-04-14', NULL, NULL, '2026-04-03T17:21:54Z', '2026-04-03T17:21:54Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('92aefbb8-3bc5-4ff2-bce6-d87639fef17b', '54facb0b-db59-41fe-9d64-c7c7221a3c81', 11, 'Upstate Girls', 'Newly single Tinsley faces serious questions about having a baby; Sonja and Barbara head upstate to see Luann''s new house, hoping to warn her about the rumblings among the other ladies; Ramona, Bethenny and Dorinda arrive at Luann''s house.', '2019-05-15', 60, '/tdsBEPbW8u3rn7OKzviwatF3vkn.jpg', '2026-04-03T16:35:25Z', '2026-04-03T16:35:25Z');
