INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('92cd03ed-ad4c-4d15-b3f2-d2843a761807', '4091b13b-4db6-4857-ad22-20b5658c6b89', 1, 'C U Next Tuesday?', 'Dolores and David fight over her plastic surgery. Jennifer is stuck in the middle of her parents'' issues. Margaret plans a girls'' trip, but Teresa''s loose lips threaten to destroy the entire vacation.', '2021-02-17', 43, '/yAtqgVcU7nVB1k4oHWYvhrkbI4e.jpg', '2026-04-03T16:35:18Z', '2026-04-03T16:35:18Z');
