INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('92d35074-10d8-4e53-9dc6-f63378ea9a06', '1996ddd8-20c9-4a30-96be-2b87fab8d17c', 25, 'Who''s Who (3)', 'Tina and the gang go to the hotel where Lana Barnes is getting her award. Lana confesses that she does miss her daughter. Her divorced husband tells them that he doesn''t hate her, but her daughter still seems suspicious.', '1993-03-21', NULL, '/qkIBSsIblo5PMcGs4Dq6nZobVvl.jpg', '2026-04-03T17:40:28Z', '2026-04-03T17:40:28Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('92e2dabb-5c41-4bd6-8c51-4a86296a5536', '8bdf0ad3-a798-4d5a-b304-c7501eae6867', 8, 'Naked Wasted', 'Vicki Gunvalson visits her family in Chicago and once again tries to get validation from her less than affectionate mother.

Lynne Curtin and her husband, Frank, canoodle over dinner and fret about some wine missing from the house. Now that Lynne''s daughter, Raquel, is driving, Lynne worries about her drinking and getting behind the wheel.

Gretchen Rossi is taking care of her gravely ill fiancé, Jeff, and reaches the end of her emotional rope.

With Simon''s urging, Tamra Barney takes an etiquette class and hires a top chef to prepare a formal seven-course dinner for all the housewives, which includes premium tequila tasting. When the tequila shots are served, Tamra and Vicki set Gretchen up for a major fall.', '2009-01-13', 44, '/kVMFdHe4HsXYzcYRJfxYJ1PEjS3.jpg', '2026-04-03T16:35:30Z', '2026-04-03T16:35:30Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('92e68012-bc80-4567-b2f0-d05c2c428986', 'cd7ade48-bcf3-49c4-acf2-cde19ca45cf5', 1, 'The Demon Headmaster Takes Over (Part One)', 'Army intelligence descend onto the Bio-Research facility and they trigger the cloning of the Headmaster. Dinah meets Professor Claudia Rowe, a specialist in biology and genetic research.', '1998-01-06', 25, NULL, '2026-04-03T17:40:35Z', '2026-04-03T17:40:35Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('92e7f369-68c9-48ad-a9c2-1c6bbb37b7b8', '5c1b881f-ac58-4d72-b63f-209952d4f902', 3, 'Episode 3', 'Expedition Egypt: Hall of Pillars  Simon and Tina explore one of the Wonders of the World-the temple built in honour of the great god Amun, at Karnak. One hundred and thirty-four massive columns cover an area the size of Westminster Abbey, with the 12 largest big enough for 100 people to stand comfortably on each one!', '1979-09-17', NULL, NULL, '2026-04-03T17:21:54Z', '2026-04-03T17:21:54Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('92eac786-dae6-405e-8e02-c8924459a563', 'a3a2c2fb-8276-412c-9d86-5175167be1d7', 41, 'Episode 41', 'with Valerie Singleton, John Noakes, Peter Purves', '1972-02-03', NULL, NULL, '2026-04-03T17:21:51Z', '2026-04-03T17:21:51Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('92ee0b06-1dbd-4eb4-856f-e0eac4f8d6ed', '78a02d50-e3dc-4549-844a-3cf357a32ef4', 6, 'Tastes Like Trouble', 'Cynthia''s peaceful divorce takes a turn when Peter starts talking about their relationship to the press. While Kenya hopes to reconcile her differences with Matt, Porsha decides she is ready to buy her first home, despite being unsure of what her new relationship has in store. Kandi hosts an afternoon of tasty eats, but Mama Joyce''s choice of words leaves a bad taste in Phaedra’s mouth. Things also heat up when Shereé spills the tea on Porsha’s past.', '2016-12-11', 43, '/4wKxwdxKslTltFFOsvT492whVjZ.jpg', '2026-04-03T16:34:47Z', '2026-04-03T16:34:47Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('92ee0c08-4bca-423b-be7e-96f3943165c9', 'bd5f5a3f-07fa-4689-b67b-02be5d65f1b2', 8, 'Postman Pat and the Go-Kart Race', 'The residents of Greendale learn that cheats never prosper.', '2006-02-20', 15, '/t2dvicPQi1mJZbhdb9JUIaKZfhc.jpg', '2026-04-03T17:14:31Z', '2026-04-03T17:14:31Z');
