INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('930f07ba-bc85-4bfb-ac6e-66f911207867', '5db3ff78-e439-48e1-8f67-988ecbf85d17', 24, 'The Impostor', 'Dogtanian and The Three Musketeers have a mission to deliver the jewels, ''The Lights of the King'' to the Spanish court. Porthos, Athos and Aramis are ready to leave but Dogtanian is still asleep well into the afternoon, Pip wakes him just before the Musketeers arrive. Richelieu and Rochefort have people watching them, and have told all the district governors on the route to stop them.', '1982-03-12', 24, '/7T4m7auVyZr6D14EJIeZMy7pGyu.jpg', '2026-04-03T17:18:43Z', '2026-04-03T17:18:43Z');
