INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('93340573-c177-47a5-94a4-5ffbe5af5cf5', '61e0c9d9-337e-4fe4-a0fd-e567b29af115', 1, 'Costume or Couture?', 'After a tumultuous previous year, Lisa celebrates Valentine''s Day by throwing a Besos party for her friends, but shows no love for Whitney. Meredith confronts Whitney for starting a bath bomb line. Both Angie and Meredith seek apologies for events that transpired last year. Lisa''s friend Bronwyn brings a new level of sophistication, fashion and a critical eye to the group. Heather''s friend Britani makes a less than favorable impression on Mary.', '2024-09-18', 43, '/6uOpN0jTlur2rcFi2okG3bvAmdg.jpg', '2026-04-03T16:35:45Z', '2026-04-03T16:35:45Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('9334f8b4-71ae-4614-afc8-5b33e6fe3cff', 'fb4ecc73-cb92-4c5c-821f-92179058b37b', 93, 'Episode 3748', '', '1998-03-25', NULL, NULL, '2026-04-03T17:36:41Z', '2026-04-03T17:36:41Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('934688ba-8653-4e93-951d-fa37cf3e3449', 'a8db07e5-fba3-49a9-bd12-947c111b39be', 3, 'The Biggest Boob', 'Dorinda confronts Ramona as mayhem from a lingerie party continues. Also, John arrives at the party and gears up for battle with Bethenny. Later, the ladies try to relax in the Hamptons to celebrate Bethenny''s birthday, yet past dramas come into play.', '2016-04-20', 44, NULL, '2026-04-03T16:35:24Z', '2026-04-03T16:35:24Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('93482638-bac2-4761-aa3c-e3935d62a9b9', '7bc54df3-f32a-454e-aef6-a9436c35d53b', 8, 'The Pie Restaurant Pt 3 - Pies', 'Chef Brockett shows how turnovers are made and helps run the new pie restaurant.', '1970-02-11', NULL, NULL, '2026-04-03T17:35:39Z', '2026-04-03T17:35:39Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('9353bf50-beea-4ad8-a5a8-ed3cf46b571d', '80775c3d-fa41-46f6-96ec-efc2e14efdcf', 11, 'Fashionably Fired Up', 'Bethenny invites the women to decorate cupcakes; Kristen remains perplexed about Bethenny''s behavior; Carole has a sex dream; Luann invites everyone to a photo shoot for her new clothing line.', '2015-06-16', 60, NULL, '2026-04-03T16:35:24Z', '2026-04-03T16:35:24Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('9353d3c8-81b1-40d1-a0c6-2c03c0446e88', '38bf8c20-c17c-4071-9226-7887787cf1b1', 13, 'Five, Six, and Thistle Sticks', 'Lionel''s friend, Lenny - a fellow ""Cliffhanger"" aficianado - comes for a visit, after having since moved away. When he arrives at the library, however, Lionel finds out that Lenny doesn''t like ""Cliffhanger"" anymore. That instead, he has taken a liking to a similar book hero, ""Justin Time""! Can Lionel and Lenny still be friends, even if they don''t like the same things?', '2001-04-18', 30, NULL, '2026-04-03T17:12:28Z', '2026-04-03T17:12:28Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('935fb3b7-c7eb-4493-9608-9635351f1f78', 'a6ed03e0-c05f-48f8-9f56-3f1da50e1792', 85, 'Episode 1400', '', '1980-03-21', NULL, NULL, '2026-04-03T17:36:33Z', '2026-04-03T17:36:33Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('9361b93e-fc2e-4369-a133-fee149808cb0', 'e93f04c2-7344-4b93-abba-8ba1b2f8eb35', 104, 'Episode 639', '', NULL, NULL, NULL, '2026-04-03T17:36:30Z', '2026-04-03T17:36:30Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('936366b6-b522-4a0d-8f0e-0768b45fbb4d', '4c79c0b6-21a4-4277-8967-be1e791efdbe', 1, 'Pingu''s Sledge Academy', 'Pingu and his friends Pingo, Pingg and Pongi are out having fun on their sledges, but they’re so boisterous that they’re a menace to everyone else, leaving chaos behind them wherever they go. They go first to a patrolling Sledge Academy students, then to a stall. The Instructor gave Father a vestment. Pingu and his three friends then pass by to an poor lady, from Pingu Wins First Prize, then to a man with the newspaper, and his hat and paper flew. Then they pass by on Pingi, to two igloos and a vegetable stall, and eventually they crash into a fish stall. When Pingu gets home, he’s told by his parents that they’re not happy with his behaviour on the sledge and threaten to take it away from him unless he goes to the Sledge Academy. He and his three friends attend a course and, after a few mishaps, learn to control their sledging. They complete the course successfully and are awarded diplomas.', '2005-01-03', 5, '/hP8neUJGAQ2ecrpJ1qtll5guSO1.jpg', '2026-04-03T17:22:20Z', '2026-04-03T17:22:20Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('936584a6-1b55-4c85-b6d8-398141d33a72', 'f30bbf81-8770-4e74-b68b-280e7c85b52f', 8, 'The Heart Attack', 'George thinks he''s had a heart attack. The doctor tells him otherwise, but he might want to get his tonsils and adenoids removed. Elaine is interested in the doctor and he is interested in her tongue. George not wanting to deal with the cost, follows Kramer''s suggestion of going to a holistic healer. The healer''s cure turns George purple and the ride to the hospital is delayed over a Chuckle.', '1991-04-25', 23, '/qcx6ufKDH0PYQ13T4rHDSCakyw3.jpg', '2026-04-03T16:34:09Z', '2026-04-03T16:34:09Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('9367b882-08a0-464e-859a-97d9fbbbe01f', '4d2cac0f-38fd-438b-8afa-acf43952e535', 198, 'Episode 198', 'All Aboard! with Christopher Trace and Valerie Singleton in a magazine programme for younger viewers.', '1962-09-10', NULL, NULL, '2026-04-03T17:21:47Z', '2026-04-03T17:21:47Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('936f3eaa-fea6-4e16-8dc8-698fc11cef54', 'd5351b60-8a0c-482a-a6dd-4fb860cfe143', 5, 'Episode 1395', 'Mister Rogers cleans out his coat closet and finds a variety of items including stocking caps, dress pants for his sons, and a paper hat. In the kitchen, he uses newspaper to show how to make a paper hat.

At Betty''s Little Theater, Mister Rogers observes as Lester Evans teaches a tap dancing class. Johnny Costa provides the music for the class. Audrey Roth and Mary Lou Autenreith perform a routine they have been practicing before Mister Rogers tries a few basic steps himself.

In the Neighborhood of Make-Believe, Lady Aberlin dances her way to the tree where Henrietta Pussycat is cleaning her house. Henrietta plans to give her clothes she has outgrown to Ana Platypus for dress-up play. X the Owl refuses to try on one of Henrietta''s hats for fun because he expects that he will then become a girl. Lady Aberlin expains to him that wearing someone else''s clothes does not turn them into that person.', '1975-02-21', NULL, NULL, '2026-04-03T17:35:41Z', '2026-04-03T17:35:41Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('937708bb-8a67-43a2-8a3d-521126678183', 'bf874be3-7e2f-4a0e-b205-c76ac1ad69fc', 78, 'Inside Looks (on The Fire)', 'Inside look from the season 5 episode "The Fire."', NULL, 22, NULL, '2026-04-03T16:34:09Z', '2026-04-03T16:34:09Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('93770d4f-3f62-4a71-a5f0-2172d5f18d74', '1a534647-384b-4c00-bb6c-a3371ad962eb', 29, 'Fake or Fortune', 'Test your judgement and revisit the best fakes and surprising fortunes ever to appear on Pawn Stars: a two million dollar painting by Claude Monet, a 1715 gold coin from a sunken ship, a set of rare autographed Hollywood Postcards from the 1950s, a bejeweled Black Widow Brooch and a collection of signed Beatles Memorabilia. Real or fake, these items could mean big bucks or a big bust for the shop.', '2015-05-21', 21, '/z5L59DYU7UvHxJSCjQS7tTqndZP.jpg', '2026-04-03T16:34:19Z', '2026-04-03T16:34:19Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('93777bb6-9ef1-4999-9aed-113346e8cdfc', '3ade5e1f-8441-4c2c-acf6-fb933a61dcfa', 3, 'Hot Mike', 'A revelation forces Gizelle to rekindle her relationship with a long-time foe; Robyn and Juan work to ensure that their financial foundation remains on solid ground; Ashley''s drinking causes Candiace to doubt her baby-making intentions.', '2019-05-19', 42, '/xO3bOuW891chX4FN2PQZgeh9rhp.jpg', '2026-04-03T16:35:39Z', '2026-04-03T16:35:39Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('93782251-b14e-4735-93fb-171649db7a7e', 'efd2082e-32f5-4edd-9a7b-a4326d6992c9', 4, 'So You Think You Can Choreograph', 'Elmo and his friends are making a music video; when they ask Zoe to be the choreographer, she comes up with the perfect dance and teaches everyone the moves.', '2018-12-08', NULL, '/58Y95fUZW5mzGGOy4qdw2HyO63r.jpg', '2026-04-03T17:36:49Z', '2026-04-03T17:36:49Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('93796dea-cf93-4dca-8dcf-69f595a4b5b7', '3fc7c152-e4f6-426a-a899-36ec454c4403', 3, 'To Kingdom Come', 'Ord''s selfishness by refusing to share anything with his friends at a beach party, especially a "wishing shell" he finds, sends him and then everyone else to a strange and unfamiliar land called “Kingdom Come” with no way home, since the owner, Mounsieur Marmadune, also refuses to share the key with them to let them out. However, Ord later learns that sharing with friends can make any wish come true.', '1999-09-07', 30, '/sURQWR4eSQPHooALXpp8UwqChpg.jpg', '2026-04-03T15:26:03Z', '2026-04-03T15:26:03Z');
