INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('941e343c-e6ab-44de-9e9e-3867dd26ef09', '46d7a706-c7a8-4ebe-b96f-387c66e8bb8b', 35, 'Episode 1480', '', '1981-01-09', NULL, NULL, '2026-04-03T17:36:34Z', '2026-04-03T17:36:34Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('94205c8c-4c1a-4666-95e9-f53fb651518f', '6d2b78d7-2612-4afb-81ca-dee774af9c2b', 11, 'Making Mistakes 1', 'Rogers starts off the program by showing a picture book of animals, but the giraffe picture is misplaced as a skunk and the skunk image is misplaced as a giraffe. Susan Linn enters with the puppets she uses in talking to children. The puppets also go to the Neighborhood of Make-Believe all week. One of them, Audrey Duck, has her feelings hurt.', '1987-05-04', 30, NULL, '2026-04-03T17:35:44Z', '2026-04-03T17:35:44Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('942082bc-cc28-46d6-8b07-01e8d5790f4e', 'b6baa6ec-0908-4a47-9001-7e7158985002', 13, 'Ups and Downs', 'There’s a monster in Walkerville Lake! Wanda competes with Gerri Poveri, a TV reporter whose ratings are sinking, to be the first one underwater.', '1995-12-02', 25, '/cLyBsyD94X3KcCMLJQFx98GF6x6.jpg', '2026-04-03T17:37:48Z', '2026-04-03T17:37:48Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('9434c161-72ee-4283-a651-d01cbd252e9d', '54900370-8988-46b8-b7aa-61d2b88d7056', 18, 'Reunion (2)', 'The reunion continues with Mary sharing an emotional update about her son and how she feels about her church being in the spotlight. The women attempt to find resolution about what happened on the plane ride from Canouan. Heather draws a line in the sand with Meredith. Meredith provides some insight into the shocking root of her issues with Britani.', '2026-01-20', 42, '/pb2YHop73T7DF8xxWKRr3qvhyiX.jpg', '2026-04-03T16:35:46Z', '2026-04-03T16:35:46Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('944175ee-b04a-441f-9bc6-3fe28c2e4f7b', '70c8cb46-2494-4dd4-98f6-6bfb9b3faf73', 8, 'Chopper Gamble', 'The Pawn Stars have an opportunity to buy something they''ve never bought before - a helicopter! Can Rick convince the Old Man to come along and spin up a deal? Then Rick has a chance to buy a 240-year-old lottery ticket signed by founding father George Washington. Is this the prize of a lifetime? Later Corey has an opportunity to buy five classic mint condition Pete Rose baseball cards. Should he gamble on baseball?', '2010-02-08', 21, '/5FqGYl2E4xpgjSxredMS4w1GT7V.jpg', '2026-04-03T16:34:16Z', '2026-04-03T16:34:16Z');
