INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('94c33914-c954-4894-b82b-ebe0ec749f0c', 'bd5f5a3f-07fa-4689-b67b-02be5d65f1b2', 18, 'Postman Pat and the Popular Policeman', 'PC Selby tells Pat that he is leaving Greendale. Pat is upset by this, but organises a party to show PC Selby how much he is loved.', '2006-03-06', 15, '/6C4SfJ10bPa95tzGisAcPDV2Mud.jpg', '2026-04-03T17:14:31Z', '2026-04-03T17:14:31Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('94c57838-37a3-4d84-82c0-eef32bb32a6c', '3269a890-bba9-4e6c-9278-f7eb38eb1720', 17, 'Wetlands', 'Wetlands are not just home to different animals and plants, but they also control flooding and help keep the Earth’s water clean. Flood waters move more slowly through wetlands because they have to go through barriers of plants and dirt. Wetlands help stop erosion because the plants stop the soil from washing away. Plants and soil in wetlands slow water enough that bacteria and other decomposer organisms can break down and even absorb some types of pollution. Wetlands are wet. Let’s keep them that way.', '1995-10-06', 26, '/cYfOgud5uFNXx9R65UVixaQVcp6.jpg', '2026-04-03T17:37:21Z', '2026-04-03T17:37:21Z');
