INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('950e4cc9-d304-4bc0-814a-4e4f44104e27', 'd920ebae-f00a-4e25-abfe-40492c74ded6', 5, 'Pawn V. Ferrari', 'Corey and Chum pay a visit to a classic car showroom to see a series 1 Shelby. Will Rick put the pedal to the metal, or pump the brakes? Then, a seller comes into the shop with a classic Nintendo video game and Chum gets his hands on an autographed Olympic snowboard. Will he shred the gnar, or will the deal be ice cold? And later, a military vet brings in a pair of WWII binoculars. Can Rick bring the deal into focus?', '2019-11-18', 42, '/jAXDoEwSlpt65RwPTrbC59G4kuX.jpg', '2026-04-03T16:34:22Z', '2026-04-03T16:34:22Z');
