INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('951d4010-cfea-4685-8e24-85795fda537d', '65524b14-e29e-4b04-81d3-fbebe525e9ec', 8, 'Franklin''s Soccer Field Folly', 'Franklin is embarrassed after he scores a soccer goal - for the opposing team!', '2004-06-12', 12, NULL, '2026-04-03T17:40:16Z', '2026-04-03T17:40:16Z');
