INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('957394bc-2cde-4295-9b1c-e454ecad1ed5', '36e5c604-fea9-4bcf-8343-71bfaf60ecd2', 25, 'Whale of A Tug', 'Theodore finds a whale called Walter who is trapped in seaweed and logs.', NULL, NULL, NULL, '2026-04-03T17:10:11Z', '2026-04-03T17:10:11Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('9578a7f8-cefe-455c-b2a3-4cd5bfc527ad', 'b6baa6ec-0908-4a47-9001-7e7158985002', 1, 'Blows Its Top', 'To help them understand how the Earth makes islands, Ms. Frizzle presents the kids with an island that hasn’t been discovered yet!', '1995-09-09', 25, '/pZQKrrS4qO4AM3vpt8RV7BIXHsc.jpg', '2026-04-03T17:37:48Z', '2026-04-03T17:37:48Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('957d6199-4b51-42aa-b1f2-331a6f12463e', 'a4843a51-aeef-427c-902c-7fb3bd670cd4', 9, 'What''s in the Mail, Today?', 'One morning, Bear steps just outside the Big Blue House to check the mail. There''s plenty of mail, but Pip and Pop are disappointed to learn there''s none for them. Bear cheers them up by letting them deliver the mail to everyone and personally takes a letter to Tutter --- his first ever. It''s from his Grandma Flutter and he''s very pleased to receive it. Pip and Pop deliver a package to Treelo, which turns out to contain a feather. Tutter decides to write a letter back to his Grandma. Ojo also receives mail --- a postcard from her Uncle Koala. Shadow tells a story of a girl who wrote a letter, but lost it.', '1997-10-30', 25, NULL, '2026-04-03T17:35:31Z', '2026-04-03T17:35:31Z');
