INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('9589a005-2319-427d-ad19-134837696d9e', '8bbf02b3-dc84-4cc6-abbc-81cf76acf365', 3, 'Mouths and Feelings', '', '1991-09-05', NULL, NULL, '2026-04-03T17:35:45Z', '2026-04-03T17:35:45Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('958f4a97-de40-44f5-9230-24ab15e61e2a', 'bfdf87ff-01dd-4b54-94bd-19b384f41bdb', 15, 'Shamrocks and Shockwaves', 'The ladies jet off to Ireland to explore Meghan''s heritage and try their luck of the Irish. On a pub crawl, an over indulgence of spirits leads to a sobering exchange of words between Tamra and Kelly, ultimately pushing Tamra over the edge. With Kelly on the outs, the rest of the ladies try to salvage their first day in Ireland by enjoying a traditional Irish Hooley Night.', '2016-10-10', 44, '/6k8k8fJKbFs7t3wysa4L3lNMLGV.jpg', '2026-04-03T16:35:33Z', '2026-04-03T16:35:33Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('959145ae-ed52-44fd-a0c8-57e1466cce02', '0fb5ce65-0258-4423-be8a-f7ba9c37bb6b', 3, 'Seal Watch', 'James is hoping to spot a seal, but his Dad''s binoculars prove to be more trouble then they seem.', '2023-10-23', 9, '/vkgX9hjx8w5OXbixuMsAsFqP5jH.jpg', '2026-04-03T17:14:42Z', '2026-04-03T17:14:42Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('95937dd8-ca49-4926-8006-665de53c4a45', 'da06465b-9154-4feb-a455-374df7dab02f', 10, 'Big Bird, Snuffy and Friends Hike (4092)', 'Maria and Luis are planning for their hike gathering their backpacks, water, and trail mix.  Big Bird and Snuffy are especially excited since they have never been on a hike before!  Maria explains what great exercise it is and how many interesting things you can find around you.  They don’t get very far on their hike because they stop to observe things around them that they’ve never really noticed before - the bark and leaves of a tree, the colors of a pebble on the ground, and even a tap dancing spider!  Even though they don’t get very far, Big Bird and Snuffy had a great time on their very first hike!', '2005-04-15', NULL, NULL, '2026-04-03T17:36:44Z', '2026-04-03T17:36:44Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('9599e00c-56aa-4fd9-9d09-914289ad1a37', '6e0be2a3-a234-453b-abb7-0ba535a93601', 22, 'Franklin''s Lucky Charm', 'Bear feels unlucky, so Franklin gives him a fake four-leaf clover to try and boost his luck.', '2000-07-16', 12, NULL, '2026-04-03T17:40:15Z', '2026-04-03T17:40:15Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('95a19044-de65-461c-a567-9065c3954a99', 'ba99b779-cada-43a7-902a-2adb472c2e30', 1, 'Episode 1', 'The first episode sets the scene and introduces us to the main characters and starts to show us what it is like to be only 15cm high. We find out that they are the only borrowers in the house and also meet the humans that co-inhabit the house. The first of a series of problems start with Pod ''being seen''. Arrietty, who has never been allowed out of their below the floorboards home, is introduced to the art of borrowing.', '1992-11-08', 30, NULL, '2026-04-03T17:17:47Z', '2026-04-03T17:17:47Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('95a1d45c-d77a-4cfb-a472-0c1ce0ea5656', '42991e93-ef88-413f-b7e3-0333f9e7ab36', 12, 'Toothpaste', '', '1994-12-08', NULL, NULL, '2026-04-03T17:19:30Z', '2026-04-03T17:19:30Z');
