INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('95a87a6e-173c-4fb2-95e9-d3094c7b47ed', 'e1ef357b-4edf-412a-a785-7060c0e33bd2', 13, 'Madeline''s Holiday with Mr. Grump', 'In the middle of the winter holiday season, Miss Clavel gets called away from the Old House to care for her ailing aunt.', '1995-12-02', 30, NULL, '2026-04-03T16:34:02Z', '2026-04-03T16:34:02Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('95ab96fc-e1ca-42fc-ba38-d77f9ff901e0', '89ba90ec-2c79-4a12-a11d-7465d1757683', 33, 'Vindicators 2: Little Trains', 'They should probably go to therapy, but instead…', '2022-07-23', 3, '/7OiY0XY9n4SJIcbtr8pfixz5ZWC.jpg', '2026-04-03T15:40:41Z', '2026-04-03T15:40:41Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('95b1bbe2-bfb9-494e-9056-f01c057d4fe6', 'e291df42-d44f-49e5-bf81-2df32ee4a30f', 21, 'The Yard Sale', 'Doc Hogg stops by the Big Blue House to collect for charity. He''s collecting for muskrat relief following recent flooding that left many of them homeless. Bear is completely out of money, so Doc Hogg agrees to come back later. Bear and Ojo then find Tutter struggling to cram an excess of stuff into his mousehole, giving Ojo the idea for a yard sale. The idea takes off and Pip and Pop are assigned to be sales-otters. Treelo finds some things of his own to sell and Ojo helps out by painting pictures. Tutter, however, finds it difficult at first to part with some of his things.', '1999-09-29', 25, NULL, '2026-04-03T17:35:32Z', '2026-04-03T17:35:32Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('95b30752-9a86-4a76-bbb4-4e2bc66da782', '9b144910-398a-47d4-9ccd-823d25cc8b0a', 12, 'The Jersey Side Step', 'A live music festival courts drama; Caroline''s family goes to the Fancy Food Festival in Washington, D.C., but plans to sell water there may go awry after a night of drinking.', '2012-07-15', 43, '/3cP940ZdfXF6fSBZgPv9whjTd6U.jpg', '2026-04-03T16:35:15Z', '2026-04-03T16:35:15Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('95b3fedd-5cc7-44b8-a603-137be92932ea', '5b5e8b2f-0a85-4488-b3dc-3d8b794e6582', 19, 'Candle Wicks and Lunatics', 'Vicki surprises her son Michael with a new role at Coto Financial, while Kelly complains to her mother that she''s finally at a breaking point in her marriage. Tamra fulfills her greatest wish of attending her estranged daughter''s high school graduation. The ladies celebrate the launch of Meghan''s new candle line and Peggy finally comes face-to-face with all the women after her sudden departure in Iceland.', '2017-11-13', 44, '/dbs20ddOU9btbuDfEmdWWbjV9JR.jpg', '2026-04-03T16:35:33Z', '2026-04-03T16:35:33Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('95b4783b-75a7-4454-b4ee-8a1b7515d2ce', 'bf874be3-7e2f-4a0e-b205-c76ac1ad69fc', 14, 'Inside Looks (on The Chinese Restaurant)', 'Inside look from the season 2 episode "The Chinese Restaurant."', NULL, 5, NULL, '2026-04-03T16:34:08Z', '2026-04-03T16:34:08Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('95bb89aa-a808-47ec-8152-1a722deed574', '136b81d3-964d-4b8f-a214-92f00d96d6b9', 3, 'Episode 1838', 'The cast sings about circles while Forgetful Jones accidentally buys basketball sneakers instead of horseshoes for Buster the Horse. Big Bird performs a poem about the letter S with kids acting out related words, though Mr. Snuffleupagus doesn''t appear in time for the conclusion.

Sponsors: S, W, 4', '1983-11-23', NULL, NULL, '2026-04-03T17:36:35Z', '2026-04-03T17:36:35Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('95c0babc-8a97-45fd-8cf7-2084f1e709e7', 'd64c5d0c-41a0-4404-88e7-55c405302d79', 2, 'The Night Lands', 'Arya shares a secret with a familiar recruit; a scout returns to Dany with disturbing news; Theon comes home to the Iron Islands.', '2012-04-08', 54, '/3EW7wYNXUVaHT4XRuIoNFrqhZh5.jpg', '2026-04-03T15:40:36Z', '2026-04-03T15:40:36Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('95c453d7-69cc-45c5-bdfc-655a22dd0895', 'f5266c49-eb29-4594-b5d9-f927edfee336', 15, 'Wildlife Watch', 'A film crew arrives to record a rare bird nesting at Mossybottom Farm.', '2014-02-21', NULL, '/wHDtDxpIB1y9QhWd4yOlo2nDCYU.jpg', '2026-04-03T17:39:32Z', '2026-04-03T17:39:32Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('95c564b3-0c72-45a7-b2f4-d036536ba886', 'd84bd187-f033-42dd-8873-e1099c61de07', 4, 'Episode 663', '', NULL, NULL, NULL, '2026-04-03T17:36:39Z', '2026-04-03T17:36:39Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('95c79070-d1e2-49b8-be41-2f074970fa1d', '1f34e241-4c1d-4586-921a-1c5aeb1fbbaa', 88, 'Episode 2183', 'Big Bird walks up to Susan and the kids on the stoop of 123 Sesame Street, wanting to show them a new trick where he can make a rhyme for any part of the body. Big Bird is still trying to think of a rhyme for "elbow," leading to a montage of him pondering all around the street in frustration.

Sponsors: V, Y, 3', '1986-03-19', NULL, NULL, '2026-04-03T17:36:36Z', '2026-04-03T17:36:36Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('95c88ba9-208c-4f62-a621-4f83741c42c0', '4fe93658-c463-4329-8e64-9d523869c2cb', 12, 'Bare Bones', 'Roar down the road with the Pawn Stars as they stumble upon a Down and Dirty custom motorcycle frame. In need of everything from wheels to a motor, will the gang turn this easy rider into easy cash or is this project simply sputter itself out? Then, a man brings in a collection of Mazon Creek fossils that are hundreds of millions of years old. Will Rick be able to chip away at the seller''s price or is the price set in stone? And later, Rick and Chumlee visit a man with a classic Vegas blackjack table from the Stardust Casino. Will Rick go all in for the win or bust and lose it all?', '2010-10-25', 21, '/sSgQs71Rw44Dtyw29CGSKRPJAAs.jpg', '2026-04-03T16:34:16Z', '2026-04-03T16:34:16Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('95c94afa-f146-46fa-ba4c-860dc83fee61', '1415ef1c-411a-4c26-814a-7c79c3628bc2', 17, 'Tequila-thon', 'It’s a new day in Mexico and the drama continues as Bethenny confronts Ramona about attending the Tequila trip. Tinsley readdresses the press article with Sonja, while some of the other ladies try their hand at surfing. The ladies all go shopping together and Ramona tries to buy her way back into Bethenny’s good graces. Tinsley and Sonja’s tension resurfaces at dinner. Bethenny takes the ladies on an educational day-drinking trip to the agave fields in Tequila. The ladies ride the drunk train back to the villa where Sonja puts Ramona in the hot seat.', '2017-07-26', 60, '/f7lhbHaOEiWdNvoQ7WC2fdjWFTJ.jpg', '2026-04-03T16:35:24Z', '2026-04-03T16:35:24Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('95c95824-a146-4c56-9c28-f356a0c7e78c', 'df77dba2-bbda-4f38-9713-8d5c856f852e', 10, 'The Apple Tree', 'Little Bear decides to grow an apple tree as a surprise for Old Bear. With help from his friends he manages to plant an apple pip in a flower pot. He is disappointed to hear that, despite watering it and keeping it warm, his pip could take years to grow into a tree. However, while he is waiting, Bramwell Brown finds a way that they can help Little Bear make an instant tree that will really surprise Old Bear.', '1993-12-05', 10, NULL, '2026-04-03T17:18:55Z', '2026-04-03T17:18:55Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('95cb9a17-085d-47d3-8a48-0ed1bf4bb691', '2aebfad4-3145-4bc1-9def-5f1d5bdfcfc8', 20, 'The Good Samaritan', 'Jerry witnesses an accident--and is attracted to the victim and the perpetrator.', '1992-03-04', 24, '/lLst66uOgHfVf22rrYvQZv1VIK4.jpg', '2026-04-03T16:34:10Z', '2026-04-03T16:34:10Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('95d95656-0513-4b8e-ba55-d282c2aa5933', 'ea73e13c-6962-4804-8305-c303df65f89f', 7, 'Sara Moves In (2) - Painting a porch swing', 'Rogers paints the swing on the porch of the television house yellow. The Neighborhood of Make-Believe Castle is closed so King Friday can have important meetings.', '1969-02-18', NULL, NULL, '2026-04-03T17:35:38Z', '2026-04-03T17:35:38Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('95da4faa-0fef-4881-b19a-cc2ec3759b98', '698a60df-8ed4-4ca9-bcb1-ebab343dacdd', 9, 'The Opera', 'The man who''s threatening Jerry is the same Joe who''s dating Elaine.', '1992-11-04', 24, '/8uiwamhLmrXBqApgs9rZ0Wg8x3N.jpg', '2026-04-03T16:34:10Z', '2026-04-03T16:34:10Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('95dce2b9-f2b3-4e57-af35-8d6d5141e398', '93651310-a84f-42ef-bcb7-ab8f788f102d', 8, 'Mama Elsa Comes Home', 'Joanna and Adriana try to reconcile; Elsa comes home from the hospital; the sex therapist assigns Joanna and Romain homework; Alexia and Peter try to work through their issues.', '2013-09-30', 44, '/zft9JZiqwOMEbD5tPHo0JnG6CT.jpg', '2026-04-03T16:35:10Z', '2026-04-03T16:35:10Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('95e033e6-789e-4fb6-a84f-14730b080355', '5144de59-e67f-4fcf-919b-7106989ab797', 36, 'Big Boys Don''t Cry', 'Leon cries when the others exclude him from his own pancake making recipe and is labelled a “crybaby” by Ben and Skye. Julie convinces the two that they''ve had reason to cry in the past. Sizzle and Nuzzle filch all the pancakes made, and get sick from doing so.', '1995-03-06', 29, NULL, '2026-04-03T17:12:21Z', '2026-04-03T17:12:21Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('95e28e61-f7c3-41aa-b92e-2a8a8f18caa7', 'd01919fb-98e0-42bf-b9d9-1cecf912f6e1', 17, 'Big Bird and Zoe Have Colds (3802)', '', '1998-12-08', NULL, NULL, '2026-04-03T17:36:42Z', '2026-04-03T17:36:42Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('95ebc453-cb7c-4e94-b58e-d4575d1a5b11', '36ea3814-66b4-4986-b6ee-44559d3562c1', 13, 'Pillow Talk or Pillow Fight', 'After Kenya reveals her plan to have a baby, she meets with a fertility doctor to explore her options. Kandi starts casting for her play and is able to acquire a big performer. NeNe hosts a couples pajama party.', '2014-01-26', 43, NULL, '2026-04-03T16:34:46Z', '2026-04-03T16:34:46Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('95ee07c8-96e1-4ab5-bf05-7789201350f2', '33440d76-e69f-47ad-ac25-862ccbc9dfa1', 19, 'Reunion (1)', 'The season eight reunion kicks off as the women take center stage among their Monarch magazine Icons gallery to rehash all of the drama that occurred both on and off camera. The ladies bond over what they do best, which is talking dirty. Robyn gets called to task for always defending Juan. Candiace is caught off guard when Gizelle and Robyn drop some shocking allegations about Chris. Mia opens up about her new boyfriend and is confronted with a rumor from her past.', '2024-03-31', 43, '/jLLV7jzVWZhsDVZHui2KaEJwKPx.jpg', '2026-04-03T16:35:41Z', '2026-04-03T16:35:41Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('95f2594f-e304-440f-ab3d-c70c736a7cab', 'ab509c47-ec64-4fb3-8560-03873dd0c37e', 11, 'The Switch', 'George suspects that his girlfriend is bulimic; Jerry dates a woman who has a friendlier roommate; Elaine loans out her boss''s tennis racket.', '1995-01-05', 22, '/4wfc5k6BSKPCGgpr6YFa55pL3d7.jpg', '2026-04-03T16:34:11Z', '2026-04-03T16:34:11Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('9607360b-a0bf-4740-8f1e-7c4a65bb84e3', '17e6cc8e-dcf3-4ce6-97db-5a9fc8e31eb5', 20, 'Reunion (3)', '', '2025-07-27', NULL, NULL, '2026-04-03T16:34:50Z', '2026-04-03T16:34:50Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('9609c4fb-12bf-464f-ba1a-20df4d778410', '190c6e49-8849-4404-87d4-eaef943a6024', 7, 'Oakie Doke And The Scooter', 'Inspired by the story of Spotty Scunthorpe''s Scooter, Doke builds a scooter to help with deliveries. When Dave and Denzil try it, they end up crashing it in the pond, but they get it back and clean it up.', '1995-10-23', 10, NULL, '2026-04-03T17:19:24Z', '2026-04-03T17:19:24Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('960d3ff7-0063-4474-92d7-8a394c7e22f6', '3a96d6c6-3736-498a-926f-6c479cdfb73a', 26, 'Franklin Goes to Day Camp', 'Franklin and Bear befriends Possum at day camp until he notices Possum was getting all of Bear''s attention. Franklin tries to clown around and get back Bear''s attention but just ended up getting in trouble.', '1998-01-26', 12, NULL, '2026-04-03T17:40:14Z', '2026-04-03T17:40:14Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('960fa652-8c3d-4bd4-ae48-d7d805a60d0f', '70c8cb46-2494-4dd4-98f6-6bfb9b3faf73', 14, 'Flight of the Chum', 'The Pawn Stars have a chance to buy one of the quietest air crafts ever made - a vintage Schweizer glider. Will the gang soar into a good deal and restore this glider to its high flying status or will they take it too close to the sun and get burned? Then Corey meets a man selling an autographed jersey of famed New York Yankees icon Lou Gehrig. Can he reach deep and catch the Iron Horse''s jersey or will he strike out swinging? And later the Old Man is speechless when a guy comes into the shop with an extremely rare casino chip known as "the one arm bandit." Will the Old Man bet the house for this historic Vegas relic or fold when the stakes get too high?', '2010-03-08', 21, '/mo7H16jg0hnUuGiYt4chBClLXFQ.jpg', '2026-04-03T16:34:16Z', '2026-04-03T16:34:16Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('961a3e99-1ebf-4eb8-83ba-e8ee80951e1d', '3e571866-318e-49df-8b7e-6119d7f3b442', 2, 'Building-A-Pig', '', '2008-11-17', NULL, '/2CW2zkZjuhjAwj7F2eTF8wwyrIx.jpg', '2026-04-03T17:39:30Z', '2026-04-03T17:39:30Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('961eff9a-4166-412b-9b4d-fd45b18dc263', '4d2cac0f-38fd-438b-8afa-acf43952e535', 312, 'Episode 312', 'with Christopher Trace and Valerie Singleton.', '1964-11-19', NULL, NULL, '2026-04-03T17:21:47Z', '2026-04-03T17:21:47Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('961f97a0-ee58-412b-a188-a0720825131e', '3269a890-bba9-4e6c-9278-f7eb38eb1720', 9, 'Germs', 'Don’t panic, but germs are all around you. Germs are bacteria, viruses, protozoa, and fungi, very small one-celled organisms. Your skin keeps most of these organisms from ever getting into your body. If germs slip inside, your body has some powerful weapons to attack and destroy them. And not all germs are bad; there are good germs, too, like the ones that live in our stomach and intestines – our guts.', '1995-04-07', 26, '/grzXSh8MGmxJ75nHe2pMYVxNZwP.jpg', '2026-04-03T17:37:21Z', '2026-04-03T17:37:21Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('96290c28-fedc-4f7c-b637-0b2be96e14bb', '63f9bf6d-39b3-44f4-b885-a56807277a80', 100, 'Muppets Commercials - Purina Dog Chow', 'Rowlf the Dog made his television debut in these rare commercials produced for Purina Dog Chow between 1962 and 1963. Designed by Jim Henson and constructed by master puppet builder Don Sahlin, Rowlf went on to become a national television star on "The Jimmy Dean Show" (1963-1966) before settling into his role as The Muppet Show''s resident piano-playing hound dog. His sidekick in these spots, Baskerville, was also occasionally seen on The Muppet Show.', '1962-12-31', NULL, NULL, '2026-04-03T17:35:23Z', '2026-04-03T17:35:23Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('962bcf7a-4e08-4b98-abd9-93a6b4a1f0e2', 'c9d2b3fb-7845-4f3c-9847-ce1f7717257a', 16, 'From Pawn, With Love', 'Rick Dale steps in to help Corey and Chumlee vie for a shot at love by restoring an antique game from the 1900s; Rick sets his sights on a never-before-seen map from the Battle of Gettysburg.', '2019-07-15', 42, NULL, '2026-04-03T16:34:21Z', '2026-04-03T16:34:21Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('962c09bc-f94b-4992-a353-9c96e1afd357', '050d8ae1-6cc1-4018-933d-b3c3d13de856', 2, 'Episode 2', 'Witches, Wizards and Robots - Behind the Scenes in the Land of Oz!

Janet explores the Emerald City and discovers how a combination of electronics and special photographic effects can conjure up a fantasy land where hens, scarecrows and witches magically come to life!', '1984-09-13', NULL, NULL, '2026-04-03T17:21:57Z', '2026-04-03T17:21:57Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('9631f305-5847-4941-88f3-6923c8bb16ba', '33319c06-a2b0-43bf-8694-b3e8e37e49e9', 6, 'Pony and Trap', 'Neil meets a friend riding a pony and trap. She agrees to let him ride it with her and they go around the Gordano Valley Riding Stables'' course.', '1997-02-14', 10, NULL, '2026-04-03T17:19:38Z', '2026-04-03T17:19:38Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('9632057b-02a2-4604-afdb-8efd28b38ba1', 'ca19f895-1514-4988-a709-95e84eab7cee', 24, 'Jurassic Pawn', 'Chum gets into the teen spirit when a unique piece of Kurt Cobain memorabilia comes into the shop. Will the deal reach nirvana, or will the seller say nevermind? Next, Rick takes a swing at a 1996 Atlanta Braves National League Championship Ring. Then, when a customer comes in with a Jurassic Park POG collection, Chum gets slammed with a hefty asking price of $775,000. And finally, Rick takes Corey to check out his childhood dream car - a 1967 Meyers Manx. But the father/son bonding comes to a screeching halt when a test drive leaves the duo stranded in the desert.', '2021-09-18', 42, '/lStPoagkLUIzgLq4ikHToNyZRKD.jpg', '2026-04-03T16:34:22Z', '2026-04-03T16:34:22Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('96347faf-1c09-415d-85e5-827df589408b', 'd9973960-273b-4a92-a7da-62efe8860d09', 7, 'Fashion Faux Pas', 'Now that Sundance is over, Lisa makes a promise; Whitney grows concerned when her dad says he''s ready to move on from the treatment center; Heather finally comes clean with her daughters over her hesitations with Mormonism.', '2020-12-23', 41, '/scEqwJcyWMdfAT6B55wJjKuEtut.jpg', '2026-04-03T16:35:44Z', '2026-04-03T16:35:44Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('9636c900-0a72-47e9-aa5a-058b22cf7182', 'e1063f87-66c2-4e2d-a913-53362941aa19', 77, 'Episode 352', '', '1972-02-22', NULL, NULL, '2026-04-03T17:36:29Z', '2026-04-03T17:36:29Z');
