INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('966356ec-dc3d-425a-9ef8-d9388bb7cacd', 'a8db07e5-fba3-49a9-bd12-947c111b39be', 17, 'And Away We Finally Go', 'The ladies decide to vacation in Miami, yet they''re conflicted about LuAnn''s last-minute engagement party in Palm Beach. Meanwhile, unresolved issues rise to the surface; Jules visits her parents; and Bethenny visits a friend in Miami.', '2016-07-27', 44, NULL, '2026-04-03T16:35:24Z', '2026-04-03T16:35:24Z');
