INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('966c34a0-3d4e-4110-abfd-43b9bde815c6', 'b590e3d8-e4a6-4360-ba5d-3e2248899d2a', 15, 'Learning', 'Rogers displays a variety of batteries, ready to put them to work in two toys and a cassette player. Mister McFeely then shows Rogers a battery-operated car. While the Neighborhood of Make-Believe remains undecided if there will be a field trip, Daniel suggests not to sacrifice anything in the learning process.', '1992-02-07', 30, NULL, '2026-04-03T17:35:46Z', '2026-04-03T17:35:46Z');
