INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('96e57ad2-f998-4d69-bed3-2811d27ce864', '42e591e2-2a88-4434-ae9f-3d4b1d685613', 31, 'Brush with Greatness', 'Get in the ring with the Pawn Stars when the guys check out a painting by Muhammad Ali. Known more for his skills in the ring than with a brush, can a knockout artist create knockout art? Then, Corey and Chumlee eye a Colt Dragoon pistol. Owned by one of the original settlers of the Lone Star State, will the guys make a Texas size offer? And later, the guys hire a consultant to make the shop more efficient, but will they embrace his changes?', '2013-10-31', 21, '/jBSFcAb4xMVMdxXgPfQSOKzDAhd.jpg', '2026-04-03T16:34:18Z', '2026-04-03T16:34:18Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('96eade25-33c3-499d-a88f-2f580b8a9dca', 'a79a245f-acab-4ebe-aee9-29867f9e52f6', 8, 'Meri''s Crazy Idea Part 2', 'Meri has big news about the bed and breakfast she wants to buy, but it''s not what the Browns were expecting; Mykelti''s wedding rehearsal doesn''t go as smoothly as planned.', '2018-01-28', NULL, NULL, '2026-04-03T16:34:30Z', '2026-04-03T16:34:30Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('96ed0e0f-d2c2-4353-b3cb-b6af5938b079', '208e80de-61e3-4a2f-857f-c667ffc29134', 2, 'Crystal Gayle', 'The Prairie Dog Glee Club sings very well, but Scooter says they have "pack rat blood in ''em -- they keep stealing everything!" The prairie dogs go wild, taking everything Kermit has -- including his collar, which leaves him naked on stage.', '1979-11-02', 26, '/o0jgrMD6TFoF8o5BL0QeTk4dnp5.jpg', '2026-04-03T17:35:25Z', '2026-04-03T17:35:25Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('96edd7a8-a9bc-46af-bb1f-bf07b23f8c4b', '331fc1df-6d70-4d79-b585-bf28024a4124', 50, 'When Fools Rush In', 'James wants to get Bronwyn something special for her birthday, so he borrows Station Officer Steele''s metal detector to find ancient coins, but he ignores Steele''s advice and gets trapped by rocks near the cliffs.', NULL, 10, '/nPTRJDijanaap2rrosWVnnnpBQq.jpg', '2026-04-03T17:14:39Z', '2026-04-03T17:14:39Z');
