INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('970ac39a-d838-4dab-84b8-aa882eb17b5c', '04e133fd-c4a3-4dfa-8369-c6dcfd1e3a5a', 1, 'The adults begin to believe that Snuffy is real', 'Big Bird challenges the adults'' skepticism about Mr. Snuffleupagus by passionately explaining the difference between what''s real and imaginary. Gordon, Maria, and Linda come to his defense, while other adults remain unconvinced. Maria visits Big Bird''s nest and brings back a note from Snuffy, proving his existence to believers and skeptics alike.

Sponsors: A, 2', '1984-11-19', NULL, NULL, '2026-04-03T17:36:35Z', '2026-04-03T17:36:35Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('970b1daf-4659-4b75-9d66-89194602e10c', '119c16d5-1047-45ec-8242-c72a8eed423b', 57, 'My Club Rules', 'The Strawberry Festival is coming to town and Arthur and his friends all band together and form a club to create the perfect float, but when everyone gets their own ideas on what the float should be they all form their own clubs.', '1996-11-14', 13, '/mFL6EHACpb0qXyNP3ywWZeEEYc6.jpg', '2026-04-03T17:37:55Z', '2026-04-03T17:37:55Z');
