INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('973d9300-1f48-4ad5-9395-891a235d82ee', '42e591e2-2a88-4434-ae9f-3d4b1d685613', 7, 'King of Pain', 'The Pawn Stars are a man down when Corey arrives at work with an injured hand and ankle. Will he play hurt, or get benched? Then, Rick brushes up on contemporary art when an oil painting by Jim Daly comes into the shop. Known for his depictions of classic Americana, will Rick pledge allegiance to this piece? And later, a guy brings in a custom built Harley Davidson rat bike. Pieced together with random parts, is this a diamond in the rough, or the Frankenstein of motorcycles?', '2013-06-20', 21, NULL, '2026-04-03T16:34:18Z', '2026-04-03T16:34:18Z');
