INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('974cac7e-9947-4aeb-b9f7-a24f254084ff', 'c7994637-b7c7-42c7-aaee-1bff4144fe23', 12, 'Bitter Pill to Swallow', 'Kyle and Sutton unpack the group dynamics while planning their upcoming trip to Spain. Erika hits the ground running as she sets out to rebuild her career. Dorit reintroduces the group to Homeless Not Toothless and hopes it will be less of a mouthful this time. Crystal finds her voice when confronting Annemarie, and the repercussions echo through the ballroom.', '2024-01-17', 44, '/4q4125SkfP7LlVUqoke5pmmSAcu.jpg', '2026-04-03T16:34:59Z', '2026-04-03T16:34:59Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('974e80c8-0c7f-41dc-9e90-619e8a8b0e88', '0442fb97-1460-4923-8558-b994078dc6b8', 11, 'Taxing Times and Blurry Lines', 'Karen invites Gizelle and Ashley to her homecoming in Virginia, but an emotional visit to her childhood farm shows the ladies a different side of the Grande Dame. Robyn’s tax woes go public. Candiace considers legal action against Monique. Meanwhile, Monique seeks guidance from her pastor, but a shocking past revelation brings her to tears.', '2020-10-11', 42, '/oCeQ77zg3bkd4ocKyMelyiCADEW.jpg', '2026-04-03T16:35:40Z', '2026-04-03T16:35:40Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('974f58f9-7eb4-4ca4-bf2b-129a39581c10', '4d2cac0f-38fd-438b-8afa-acf43952e535', 15, 'Episode 15', 'Toys, model railways, games, stories, cartoons. A weekly programme for younger viewers with Christopher Trace and Leila Williams.', '1959-01-22', NULL, NULL, '2026-04-03T17:21:47Z', '2026-04-03T17:21:47Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('9753e33c-e53d-4a0d-b2ac-663fe2065192', 'dec4a06d-731b-41e4-8b15-374f47d1f5c7', 6, 'Swimming With the Gefilte Fishes', 'Teresa bids adieu to her ankle bracelet and the ladies plan a trip to celebrate. Also: Siggy reconnects with her religious roots; Dolores makes headway on her home renovation; and Melissa corners Jacqueline about a dust-up with Teresa.', '2016-08-21', 43, '/pqKnOm7iEpzfOwlr9JIs4JRDysW.jpg', '2026-04-03T16:35:16Z', '2026-04-03T16:35:16Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('9758e34e-4889-46fc-bf70-6a1f8b864d29', 'a0fa5075-9ce1-48c1-9995-0c0fd866e549', 10, 'Sweet Home Augusta', 'While Kyle gets emotional over her new life, Bozoma tries to make sense of her new future with her man. Sutton plans a trip back home to Augusta with Garcelle and Kyle, but not everyone is met with the Southern hospitality they were hoping for. Kathy’s Capri-inspired dinner gets molto teso when Dorit opens up about the state of her separation as Erika urges her to stand her ground.', '2025-02-04', 43, '/o6ca6mm1C4UZpeNujZzxp3GS69p.jpg', '2026-04-03T16:34:59Z', '2026-04-03T16:34:59Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('975abbe7-d990-44cd-899a-0d21d69c6da5', '4d2cac0f-38fd-438b-8afa-acf43952e535', 317, 'Episode 317', 'With Christmas two weeks away, the Blue Peter team, led by producer Biddy Baxter, is preparing for its seasonal shows. Tonight, Christopher Trace and Valerie Singleton will present some festive items. They''ll share the history of the Christmas tree and introduce a visiting troupe from Kitzbühel, Austria: The Gay Tyrolese, led by Toni Praxmair. This world-famous group of dancers and singers will perform several traditional routines, including the humorous ''Woodcutters'' Dance'' and a ''Miners'' Dance'' using cowbells. The most exciting dance will be the ''Schuhplattler,'' where the performers slap each other''s leather shorts. Additionally, in the first of a new series, Gordon Murray will demonstrate how to make bottle puppets for a Christmas show.', '1964-12-07', NULL, NULL, '2026-04-03T17:21:47Z', '2026-04-03T17:21:47Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('975dea89-3d1c-432c-a7af-214261b5b023', '46d7a706-c7a8-4ebe-b96f-387c66e8bb8b', 129, 'Episode 1574', '', '1981-05-21', NULL, NULL, '2026-04-03T17:36:34Z', '2026-04-03T17:36:34Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('975f4fa5-31ad-4c1e-a0e3-e698ad8363f3', 'd73c357e-1078-4de8-a77a-25c206262a1e', 1, 'The Pet Shop', 'The first episode, Big and Little decide to trade Dog for another pet, mainly because all he does is bark and dig holes in the lawn.', '1992-09-29', NULL, NULL, '2026-04-03T17:24:52Z', '2026-04-03T17:24:52Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('9765758a-c2d4-4c7d-9dfa-a965bfc12316', '0987f081-b3b7-4e3c-abb7-795e56c279d5', 5, 'The Hose', 'A neighbor accuses Frankie of stealing her hose; Sue cancels a road trip to Cincinnati after seeing Mike''s paycheck; Brick learns about the birds and the bees.', '2012-10-17', 22, '/tFZhwF13udbISbAkgcRhcNBDRch.jpg', '2026-04-03T15:40:30Z', '2026-04-03T15:40:30Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('97663435-a166-42c5-8c78-fd553c1b066e', '4892e2af-46c1-4b4e-ac81-eac161b5a347', 31, 'Episode 31', 'Review of the Year  Relive Blue Peter''s highlights of 1977 as John climbs to the top of Nelson''s Column. Spot the disappearing cats and listen to James Galway''s double tin whistles and the Vicar who sounds like a train. Fly over Brazil''s mighty Iguacu Falls and sail in a force nine gale with Clare Francis.', '1977-12-29', NULL, NULL, '2026-04-03T17:21:53Z', '2026-04-03T17:21:53Z');
