INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('97697272-2e8b-4680-89cb-b713984dd5f7', '4f8c16f6-9b92-4be9-9b6b-837f26ad3720', 9, 'Time to Spare', 'Due to a fast clock, Bernard arrives at the go-kart track a whole hour early for a friend''s birthday party. His friend Dylan is also early, so they hang out in the park together, but then Dylan gets his head stuck in some railings. Bernard goes in search of help...and one thing leads to another.', '1998-11-27', 15, NULL, '2026-04-03T17:20:04Z', '2026-04-03T17:20:04Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('976e9a2d-9ffc-40f6-bf44-d453642c9679', '44624ee8-03f0-4261-8379-68daf4666b42', 14, 'More!', 'D.W. is thrilled to be getting an allowance. When she learns that Emily and the Tibbles have been already getting one and have more money, D.W. is devastated.', '2001-11-05', 13, NULL, '2026-04-03T17:37:57Z', '2026-04-03T17:37:57Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('97723039-98f7-4da3-b6bb-031942d3e560', '05c0e384-194c-4417-9f62-803eb615e409', 125, 'Feeling angry', 'Rogers sets up a punching bag, explaining how some people punch a bag when they are angry, saying that rules must be followed in boxing. The Neighborhood of Make-Believe has a surprise for Joey Hollingsworth.', '1968-08-09', NULL, NULL, '2026-04-03T17:35:38Z', '2026-04-03T17:35:38Z');
