INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('977acd78-0657-4573-8e70-27279a4da645', 'e48599f8-66ff-4c0f-9274-65b9ae1cda9e', 76, 'Episode 76', 'Shep made history when he became the first dog ever to be sculpted for Madame Tussaud ''s famous waxworks.  Today JOHN and Shep come face to face with John and Shep at the official unveiling.', '1977-06-13', NULL, NULL, '2026-04-03T17:21:53Z', '2026-04-03T17:21:53Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('977ff913-d89e-4bb2-8c41-c5f55be167e0', '2990012c-38f6-4051-84a5-4ec6da711d80', 4, 'The Treasure Hunt', 'Kipper and Tiger go on a treasure hunt with Tiger''s metal detector, but they can find no real treasure besides a screw, a water pipe, and Arnold''s toys.', '1999-02-11', 9, NULL, '2026-04-03T17:10:48Z', '2026-04-03T17:10:48Z');
