INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('98bb401f-fa03-498f-8e01-4e7984d73a50', 'd6092173-d23b-4449-baff-e0e16fe56c9a', 16, 'Hurricane Housewives', 'The ladies'' trip to New Orleans continues and Marlo gets in the middle of Porsha and Kenya’s feud. Kandi makes a last minute decision to escape the impending hurricane and head home to open Blaze Steakhouse. Back in Atlanta, Porsha reveals to Cynthia that she''s drawing a line in the sand in her relationship with Marlo.', '2021-04-04', 43, '/1x8GwVaN3vNFlpoAhHA3NrTWq5g.jpg', '2026-04-03T16:34:49Z', '2026-04-03T16:34:49Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('98bccadc-3102-4c7d-9298-f395fc5c775b', 'd0e5568d-939d-4d89-ab4e-c291a90691cf', 4, 'Pig''s Sweater', 'Pig is very proud of his new purple woolly sweater and shows it off to Kipper. Arnold spots a big red arrow, and then another, and they follow them into the woods. Pig doesn''t notice he has caught his sweater on a branch. The arrows were Tiger''s idea and he laughs at them from a tree he''s hiding in. Then he realizes they''re lost. The unraveled wool from Pig''s sweater leads them back home.', '2000-10-19', 8, NULL, '2026-04-03T17:10:49Z', '2026-04-03T17:10:49Z');
