INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('98c2b91d-b8ae-464b-9fbf-f149b45cbc7e', 'd920ebae-f00a-4e25-abfe-40492c74ded6', 22, 'Wind Beneath My Mill', 'Chum steps up to the plate when a seller pitches him a signed photo of Cy Young. Will he hit a home run, or strike out? Meanwhile, Rick checks out a giant U.S. Navy Jack. When the negotiation sets sail, will Rick stay aboard, or jump ship? Then, the team takes a hit after a seller brings in a 1930s spanker. Can Rick smack down the money, or will it be a hit and run? And later, it''s morphin time when Chum checks out a guard mask from the "Power Rangers." Will he be able to defeat this mighty deal? And finally, Rick causes a storm with his windmill restoration and enlists the help of Rick Dale to bring the power.', '2020-06-16', 42, '/rkA6ZpoLArW064HSOpOwuW7yEVV.jpg', '2026-04-03T16:34:22Z', '2026-04-03T16:34:22Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('98c6e119-c14d-4885-8281-f6b775db641f', '3ee646e8-23ae-4dec-bbc6-c7e6a210d55b', 73, 'Sonny Friendly''s many game shows', 'Gina, Uncle Wally, Snuffy, and the kids hang out in the yard when they''re visited by Sonny Friendly with another one of his traveling game shows. This time, his game is "Sesame Street''s Funniest Ideas." Snuffy imagines everyone wearing cabbages instead of hats and Sonny tries to get the camera crew. Over at Hooper''s Store, Sonny sobs, unable to come up with a new game show idea.

