INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('98d8f2bc-4a54-40e1-ac18-d31835633f43', '1415ef1c-411a-4c26-814a-7c79c3628bc2', 14, 'A Slippery Slope', 'Sonja digs a deeper grave for herself with Luann. While the ladies hit the slopes, a big news story about Bethenny breaks out online. Bethenny is on the fence about inviting Ramona to Mexico. At dinner, the ladies play a revealing game of "Truth or Dare” and Dorinda ends up attacking Luann.', '2017-07-05', 60, '/cim6mYwcHYP0GQlTGck2Mx89lr6.jpg', '2026-04-03T16:35:24Z', '2026-04-03T16:35:24Z');
