INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('98de43d9-f802-4968-84cc-ad94ab4b03ca', '34674c90-410e-427c-be4d-2a6f6f865a80', 11, 'Silver Linings', 'Take a shine to the Pawn Stars when a guy brings in 100 pounds of pure silver. Including a single brick worth over $35,000, will the guys mine a deal, or will a led center cause the deal to sink? Then, Rick gets stumped when a seller brings in a mysterious book. Hand-written in Cyrillic, can this ancient text turn a successful chapter for the store, or is the end written in stone? And later, the guys flash back to the ''90s when a collection of movie props from "Batman Forever" come into the shop. Will nostalgia lead them to bite, or will they not even bat an eyelash?', '2012-06-04', 21, NULL, '2026-04-03T16:34:17Z', '2026-04-03T16:34:17Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('98e26f34-2195-4a51-a515-3dca42df1f7b', 'c9adc698-be92-4dd7-94ad-d8f6759361ca', 29, 'Episode 29', 'Rogers compares the sounds of a car horn, a trumpet, and a bicycle horn. When he returns to Negri''s Music Shop, he hears trumpeter Ben Benack. In the Neighborhood of Make-Believe, King Friday gets his plane and hires Yoshi Ito to pilot it.', '1973-03-29', NULL, NULL, '2026-04-03T17:35:40Z', '2026-04-03T17:35:40Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('98e66fc7-b829-467c-903f-16a9b44e014a', '54c29014-2dbd-49ff-a23f-cf4c546e0b3a', 11, 'The Ramona Trap', 'The ladies confront Ramona about past behavior. Elsewhere, marital dissension plagues Kristen; LuAnn invites Carole on a double date; and Ramona sets out to make peace with Kristen.', '2014-05-20', 60, NULL, '2026-04-03T16:35:23Z', '2026-04-03T16:35:23Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('98e8ac4c-2a36-4fce-b495-af95ea557251', 'de8ec769-16bb-436b-be43-aedc7e18a7d7', 12, 'Elmo''s Good Luck Charm', 'Elmo loses his lucky baseball card before a game of tee-ball and says he can''t play without it. When Abby, Alan, and Rosita tell Elmo that all he needs to do is practice, Elmo learns that he can still play without his lucky card.', '2020-02-01', NULL, '/lYohhU4Guhh1P2I2JGIfsxzUJxw.jpg', '2026-04-03T17:36:50Z', '2026-04-03T17:36:50Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('98e8c0ac-11ec-4f49-926d-3b6ff2cc962d', 'fc120008-c5c4-47d7-a3a9-91a401394c41', 2, 'Too Much Junk Food', 'Papa decides to enter the Bear Country Run like he did last year but soon he discovers his performance is not as good as it used to be. The cubs try to help him but soon their performance is the same as Papa. Luckily, Dr. Grizzly suggests that they should not eat junk food and start eating healthy foods in time for the race.', '2003-01-07', 11, NULL, '2026-04-03T17:40:21Z', '2026-04-03T17:40:21Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('98f1dca1-e6e8-4dc0-a39a-48d1df1eaa4a', 'd123fd65-efb7-4ebb-a23e-190c447791cf', 5, 'Family Therapy', 'Julia aims to resolve her birthday drama; Nicole contemplates rebuilding a relationship with her dad; Alexia''s family is torn apart as her fiancé and son go head-to-head.', '2022-01-06', 44, '/xwo8UQLoVGIKegps7YlSGuCnfWc.jpg', '2026-04-03T16:35:11Z', '2026-04-03T16:35:11Z');
