INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('98f66848-74e7-4cfc-be19-69d1345399e5', '244b0a34-284b-4ec1-b3a7-0e5abff6d0d1', 9, 'The Great MacGrady', 'When Lakewood Elementary''s beloved lunch lady Mrs. MacGrady is diagnosed with cancer, Arthur and his friends all react differently to the news.', '2009-10-19', 26, NULL, '2026-04-03T17:37:59Z', '2026-04-03T17:37:59Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('98fc08e7-d10a-468c-8f91-539655903a55', '4d2cac0f-38fd-438b-8afa-acf43952e535', 290, 'Episode 290', 'Christopher Trace and Valerie Singleton introduce a magazine programme for younger viewers.', '1964-08-10', NULL, NULL, '2026-04-03T17:21:47Z', '2026-04-03T17:21:47Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('99014633-9c03-4961-8e71-02b44b8a7480', 'b1d55597-d9d2-4eee-ab95-46dbb163291a', 3, 'Pingu Helps With Incubating', 'Pingu’s family has an egg, and while his parents do the laundry, Pingu has to sit on it. At first he is proud and happy to help, but he quickly gets bored, and gets up and starts listening to music called "Woodpeckers From Space". He does dances and other steps, but the egg suddenly sprouts a leg and starts to dance around the house. When Pingu notices this, he tries to stop things and catch the egg before his parents find out, trashing the igloo in the process. Pingu''s parents, eventually noticing the commotion and finding out what''s happening, rush over to help. Father catches the egg and mother turns off the record. Mother finds Pingu hiding in a cupboard beneath the record player; afraid his parents would be angry at him. They are not, however, and mother hugs him. Mother and Pingu clean up the igloo and Father sews him a hat for a great job taking care of the egg.', '1986-06-11', 5, '/oCXCrAH3vmrlXdPhYJVUcXKLxmy.jpg', '2026-04-03T17:22:18Z', '2026-04-03T17:22:18Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('99059fa5-808c-4540-bda9-7ee1e25462c7', 'd8ccf6d3-e37a-430a-b67d-7fbf269bf0be', 12, 'Icy Apologies', 'The ladies are unsure about how they feel about going on a trip with Monica for her birthday as Monica turns to Mary for advice. A lunch between Lisa and Meredith leaves their friendship on shaky ground. When Whitney loses a close friend, she looks to the ladies for support but finds one of them isn''t as empathetic as she expects.', '2023-11-28', 44, '/xRMcrVNHM9wtY6jaw0zEFp71WBD.jpg', '2026-04-03T16:35:45Z', '2026-04-03T16:35:45Z');
