INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('99230057-66f3-4c55-880e-e9c204bedff2', 'b86d15ea-4253-41a5-9f14-4a254ec601e0', 4, 'Gym Rats', 'Melissa''s past is comes back to haunt her. Kathy hosts a birthday celebration for her daughter and husband. Teresa becomes emotional after she runs into her brother while out.', '2013-06-23', 43, '/uKCpumSftFKagAs0viRdPwJUFvE.jpg', '2026-04-03T16:35:16Z', '2026-04-03T16:35:16Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('992d2fad-a2ed-4436-8192-978ecf2c126b', 'ea73e13c-6962-4804-8305-c303df65f89f', 45, 'Grown from tiny seeds', 'Rogers brings in flower pots filled with orchids, tulips, and daffodils. In the Neighborhood of Make-Believe, King Friday is surprised by the sudden quiet. Everyone is watching Handyman Negri building the community center at Someplace Else.', '1969-04-11', NULL, NULL, '2026-04-03T17:35:38Z', '2026-04-03T17:35:38Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('9931f56d-153a-4114-a5a9-0889e4dd584a', '31feb548-2e4c-45db-9c77-61f2bc7451f5', 1, 'Mr. Ratburn and the Special Someone', 'The gang is surprised that Mr. Ratburn is getting married.', '2019-05-13', 13, '/qG5NzW5hW9Xn9Z4llKfyvHkpyZf.jpg', '2026-04-03T17:38:03Z', '2026-04-03T17:38:03Z');
