INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('9939c4ac-b4d6-4f26-9a74-cb20563c9808', 'dbd3583f-e9b2-46d1-a37e-309eb666e233', 15, 'From Motherland to Haterville', 'The ladies head home to find more drama; NeNe''s son is arrested; Kim confronts Kandi about what was said about her in Africa.', '2012-03-04', 43, '/6Qvyfe3WMgF919MoJ7PuicfRx4K.jpg', '2026-04-03T16:34:45Z', '2026-04-03T16:34:45Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('993e0ef6-56b7-4ab7-96c9-50119830c033', 'c7994637-b7c7-42c7-aaee-1bff4144fe23', 11, 'A Celebration of Life', 'The women head to Ojai for Annemarie''s birthday, as frosting isn''t the only thing Sutton is licking. Dorit questions her marriage after PK''s shocking admission in therapy. Kyle hosts a celebration of life event for her late friend.', '2024-01-10', 44, '/bBVz01Ogglddd7F8hOtAD0B25Kw.jpg', '2026-04-03T16:34:59Z', '2026-04-03T16:34:59Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('993f6370-8a6d-4bff-972f-3e4a01efb8b7', '6be74684-83e6-4d00-bd69-3e4fca97cabb', 11, 'Reunion', 'Bravo Media’s The Real Housewives of Dallas brings big drama from the big D on a supersized reunion. For their first rodeo, Andy Cohen sits down with Cary Deuber, Tiffany Hendra, Stephanie Hollman, LeeAnne Locken, Brandi Redmond, their friend Marie Reyes and Cary’s husband Mark Deuber, to rehash the season’s most memorable and difficult moments. In the supersized reunion, Brandi divulges a painful secret about her marriage to Bryan, while Stephanie sets the record straight on Travis’s to-do list. Cary and Mark confront LeeAnne about the scandalous rumor she spread about them, and Tiffany responds to allegations about her racy acting past. Marie also joins the ladies on the couch to share new details about that heated night in Austin.', '2016-06-19', 75, '/86FZgJBH1oYvX6PEAWPWHOOF0BA.jpg', '2026-04-03T16:35:03Z', '2026-04-03T16:35:03Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('994ac6ef-beca-417a-bdfd-45c386e53b41', 'bf874be3-7e2f-4a0e-b205-c76ac1ad69fc', 159, 'Sein-imation: Conquering The Van Wyck', 'Sein-imation is a series of cartoons of Seinfeld episodes. They were released on the Seinfeld DVDs as special features. They used audio from a set episode placed over a new "toon".', NULL, 22, NULL, '2026-04-03T16:34:09Z', '2026-04-03T16:34:09Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('994ebcde-20a0-4e30-9b72-9b739d6baf5e', '56428e5e-7daa-468d-8bd2-076956507aa8', 17, 'Momentum', 'The momentum of a moving thing, like you riding your bike, depends on how much mass you and your bike have and how fast you’re speeding down that hill. An elephant on a bike has more momentum than a mouse on a bike moving at the same speed. A mouse on a fast bike has more momentum than a mouse on a slow bike. If there’s an elephant on a fast bike, you’d better get out of the way.', '1994-11-19', 26, '/jPqY55rQW8Zxg9IFdTRQ45MPpB8.jpg', '2026-04-03T17:37:21Z', '2026-04-03T17:37:21Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('9958206c-87cc-4982-b4d6-8791618b0bac', '91f66da7-56a2-423a-b855-f09d582805b2', 6, 'Violet￢ﾀﾙs Music & What Instrument Does Alvin Play?', 'Lionel and Leona learn about the many instruments they can play.', '2007-10-22', 30, NULL, '2026-04-03T17:12:29Z', '2026-04-03T17:12:29Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('9959470a-b267-4d9d-80ef-c982399f7b3b', '78a02d50-e3dc-4549-844a-3cf357a32ef4', 16, 'Maui Mayhem', 'Extinguishing all hope of a peaceful getaway, the group''s first dinner in Maui escalates to new heights as Kandi and Porsha erupt over who''s to blame for the salacious rumors that have surfaced. Kandi tries to shake off the drama by planning a speed boat adventure without Porsha, meanwhile Shereé and Bob''s courtship hits a major speed bump of its own. Later, Phaedra attempts to mend the ladies'' broken friendships by organizing an emergency "restoration service" and Bob tries to salvage what''s left of his relationship with Shereé.', '2017-03-12', 43, '/eNU8kY0hdyQbLcaYuqWSxooivJX.jpg', '2026-04-03T16:34:48Z', '2026-04-03T16:34:48Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('995ff6cb-7d9f-42bf-98fd-bd6bd1e90cce', 'bddd6427-4f85-402c-b58c-5c18ab159704', 87, 'Episode 882', '', '1976-03-30', NULL, NULL, '2026-04-03T17:36:31Z', '2026-04-03T17:36:31Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('9960e2e5-5ed6-4940-9bd2-05e9dbecdd7a', 'e6254ae4-7d72-493b-8b37-b677d8b76c46', 14, 'Episode 679', '', NULL, NULL, NULL, '2026-04-03T17:36:30Z', '2026-04-03T17:36:30Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('99612e7d-ca4f-404e-b168-9bb0cce613b6', 'a8f3a681-7abc-41e0-9988-9b8804d74611', 13, 'Kody Begs For an Answer', 'The teachers are in for a big surprise when Kody and the wives all attend Parent/Teacher conferences for their kids. Later, Logan graduates from college, but not without some family mayhem. And Kody demands an answer from Meri about having another baby.', '2012-11-25', NULL, NULL, '2026-04-03T16:34:28Z', '2026-04-03T16:34:28Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('99645961-fa49-4c0f-b4a0-e9358b06f2ff', 'c21dbd22-5e2e-4414-bb67-750399aaf6f0', 30, 'Zoodoo', 'The Pawn Stars sing "Hail to the Chief" when an autographed collection of presidential memoirs comes into the shop. Written and signed by President Harry S. Truman, will Rick campaign to buy these rare books, or is the seller just not on the same page? Then, Corey and Chumlee are presented with a toy "Robby the Robot" from the 1956 movie, Forbidden Planet. Can this mechanical gizmo automate the deal or will it run out of batteries?', '2012-03-05', 21, NULL, '2026-04-03T16:34:17Z', '2026-04-03T16:34:17Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('99648ab1-86b6-408c-9e32-46a901ec90c0', '3ea743ef-0a22-47cf-b1d2-62f37e939253', 26, 'Zoe Makes Up a Happy Song', '', '2002-03-11', NULL, NULL, '2026-04-03T17:36:43Z', '2026-04-03T17:36:43Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('9966821d-b36b-47f3-ab5d-6c18e85010d9', '1f34e241-4c1d-4586-921a-1c5aeb1fbbaa', 81, 'The Two-Headed Monster Writes a Story', 'The Count and Gordon count all the body parts on Miles, which add up to "one fine, wonderful, beautiful baby boy." Gladys the Cow feels incensed when she finds Elmo trying to act like her. He claims they''re the same, and Gladys is quick to point out the obvious physical differences.

Sponsors: N, O, 8', '1986-03-10', NULL, NULL, '2026-04-03T17:36:36Z', '2026-04-03T17:36:36Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('99671950-a0f4-48d8-9795-2ef6c41f190e', 'f3100d00-163f-4164-b551-6ed56605a264', 7, 'Episode 7', '', '2002-05-17', 25, NULL, '2026-04-03T17:21:19Z', '2026-04-03T17:21:19Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('9969cdff-5867-41de-9d9d-b2a42aa08b10', '119c16d5-1047-45ec-8242-c72a8eed423b', 18, 'Arthur''s Cousin Catastrophe', 'The Read Family is having a big reunion, with aardvark relatives from all over coming. Arthur normally enjoys the festivities, such as sack-racing and swapping stories, but finds himself hiding because he''s worried that his cousin Mo has a big practical joke planned for him. He remembers her being awful to him in the past and is sure that she has something big planned. However, his worries might just be unfounded.', '1996-10-17', 13, '/nbdPNPdt5TaDVwIrNFLC2sdj9EQ.jpg', '2026-04-03T17:37:55Z', '2026-04-03T17:37:55Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('996ca839-8588-4d73-b7a8-910d8349e1f3', 'd405f973-4c7e-4cb6-b7c0-d09a884c9b35', 8, 'Misfortune Teller', 'LuAnn hosts the ladies in Morocco, where she nabs Sonja and Ramona trying to secretly leave the property shortly after they arrive. Later, Jill runs into an old friend while shopping, and he invites the women to his birthday party, which features a fortune teller and a snake charmer.', '2011-05-26', 43, '/av6Yhf46i8F0q4m0D9YWhktx4Qh.jpg', '2026-04-03T16:35:22Z', '2026-04-03T16:35:22Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('99721cf7-a4de-4ced-8269-05dd49a351c8', '136b81d3-964d-4b8f-a214-92f00d96d6b9', 115, 'Captain Vegetable rhymes / Forgetful in the Fix-It Shop', 'Captain Vegetable leads an entertaining rhyming lesson while Forgetful Jones attempts to work in the Fix-It Shop, causing good-natured chaos everywhere. Despite his bungling efforts and memory lapses, Forgetful manages to complete his assigned task. Everyone appreciates his willingness to help despite his challenges.

Sponsors: M, Y, 2', '1984-04-27', NULL, NULL, '2026-04-03T17:36:35Z', '2026-04-03T17:36:35Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('9978f3c5-0e38-4247-9222-8b970bcc492a', '6f731e6b-d3c5-4de6-84e1-7a19cb650e86', 26, 'Lock, Stock, and Pawn', 'Batter up with the Pawn Stars when an all-star Dodger''s baseball memorabilia bench faces Rick in the bottom of the ninth. Will it be a grand slam sale or will he strike out? Then, a 19th century Hobbs & Co. lock box bolts in. Will Corey hold the key to unlock a deal or will it get jammed? Next, there''s a prankster in the shop when an original Woody Woodpecker oil painting is brought in. Will Rick tap into a sale or will he laugh it off? And later, Rick gets schooled when a set of educational books called the Delphian Course cram into the shop. Will Rick become a deal-making savant or will he have to repeat the class?', '2016-02-10', 21, '/h5gsSAgbl7YJsJq2l2nbFpeI5AD.jpg', '2026-04-03T16:34:20Z', '2026-04-03T16:34:20Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('997be649-c490-48ca-8655-928911c66cc0', 'f0f8b366-cb33-40b3-a50f-a1ca7780916f', 1, 'Mirror, Mirror', 'It''s Red''s 28th birthday in a row since the Festival of the Bells when she finds a magic mirror (named Mavis) that leads her to a very special birthday party.', '1987-01-05', 24, '/5lWpdSWkidfc8BzjCM3amJljDs3.jpg', '2026-04-03T17:35:01Z', '2026-04-03T17:35:01Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('99820778-02ed-4817-9249-806680a812a2', '33319c06-a2b0-43bf-8694-b3e8e37e49e9', 20, 'Theatre', 'Neil visits the Bristol Old Vic Theatre Royal to watch a play.', '1997-06-06', 10, NULL, '2026-04-03T17:19:38Z', '2026-04-03T17:19:38Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('998b0935-a519-4054-9b2e-5b2aaa828034', '05c0e384-194c-4417-9f62-803eb615e409', 128, 'Disappearing', 'Mr Rogers shows how to tie a shoe, and also explains the meaning of the word "disappear," which isn''t always exactly what it seems. With Officer Clemens, The Neighborhood of Make-Believe bids goodbye to Sara Saturday, but she and King Friday declare that she will return. Officer Clemens sings "I Like to Be Told".', '1968-08-14', NULL, NULL, '2026-04-03T17:35:38Z', '2026-04-03T17:35:38Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('99932e2d-c8af-43de-b2a7-ee0e8f2c82d1', 'a3a2c2fb-8276-412c-9d86-5175167be1d7', 21, 'Episode 21', 'with Valerie Singleton, John Noakes, Peter Purves', '1971-11-22', NULL, NULL, '2026-04-03T17:21:51Z', '2026-04-03T17:21:51Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('99a0167c-fb4b-4b93-8729-24e40456c929', '0ba7cc9b-1314-4e1e-b74f-76463a622991', 5, 'Secrets: A Surprise Party for Mister Rogers', 'Rogers writes a message in invisible ink. Mr. McFeely shows a videotape of how suitcases are made. In the Neighborhood of Make-Believe, Chuck Aber must inform Lady Elaine that he had no plans to marry her, but he does have some good news. Rogers finds a message that leads him outside, where several neighbors hold a birthday party for him.', '1988-11-25', NULL, NULL, '2026-04-03T17:35:45Z', '2026-04-03T17:35:45Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('99a621a1-3fc3-4da8-889b-636de9c957aa', '36e5c604-fea9-4bcf-8343-71bfaf60ecd2', 10, 'Theodore, The Vegetable', 'The Dispatcher assigns Theodore to be the tug in charge of an incoming cargo ship called Julia.   However when Theodore actually meets up with her, Julia questions his ability to handle her and Theodore is not so sure himself either.', NULL, NULL, NULL, '2026-04-03T17:10:11Z', '2026-04-03T17:10:11Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('99a6baa3-6c6b-431f-ba8d-218970a43ccf', '3d4d8f6a-9708-47e8-9c99-26ebafdb2609', 130, 'Episode 3655', '', NULL, NULL, NULL, '2026-04-03T17:36:41Z', '2026-04-03T17:36:41Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('99a93fc2-b50e-4195-a491-f7f8adce39d9', '596e6e8f-f651-47f2-83b8-d4cdee8e5927', 1, 'Episode 1', '', '2005-04-03', 25, NULL, '2026-04-03T17:21:20Z', '2026-04-03T17:21:20Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('99abed58-1103-48b4-9599-4e31b6917e1a', '2e6ee129-b32e-4417-9500-56f1cc9bc434', 4, 'The Salamander Room', 'LeVar explores the rain forest and animals in their habitats by visiting a park that recreates the rain forest environment artificially to make the animals comfortable. This episode also includes a film of scientists who study the region''s animals from above by climbing inside a tree''s canopy. Lynne Thigpen reads The Salamander Room, about a little boy who finds a small newt while on a nature walk, and all the rationalizing he does to convince his mother to let him keep the salamander as a pet by turning his bedroom into a model rain forest.', '1993-10-14', 30, NULL, '2026-04-03T17:36:18Z', '2026-04-03T17:36:18Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('99b02310-3de6-4402-b9f6-3adbf1003cc4', '2e6ee129-b32e-4417-9500-56f1cc9bc434', 1, 'Amazing Grace', 'LeVar visits a theater to discuss acting and how pretending to be someone else sometimes helps people express themselves in different ways. He also visits with his friend, Whoopi Goldberg, who was launching her own talk show, and discussed how her unique look has sometimes helped, and hindered her career as an actress/comedienne.', '1993-10-11', 30, NULL, '2026-04-03T17:36:18Z', '2026-04-03T17:36:18Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('99b18782-436b-44eb-a7a1-c1a797bb3759', 'f5474771-8930-41eb-b0d4-db442233acee', 2, 'The Ten Deadliest Snakes in the World', 'Steve and Wes Mannion showcase what they believe to be the ten deadliest snakes on the planet, all conveniently located in Australia.', '2001-08-30', 40, NULL, '2026-04-03T17:39:10Z', '2026-04-03T17:39:10Z');
