INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('99bc43b2-5abf-42d1-8e4d-d860ab45b374', '32192008-7529-4677-933f-c55ea6146368', 15, 'The Rocky Road to Sisterhood', 'On day two of the Colorado getaway, the group heads to Aspen for a day of fun, but not before a confrontation over the guest house accommodations. Monique voices her opinion about Angel’s personal life. Gizelle sets her sights on taking over as host for the remainder of the trip.', '2026-01-18', 42, NULL, '2026-04-03T16:35:42Z', '2026-04-03T16:35:42Z');
