INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('99ceff39-8ba4-4bd9-bc9e-77c59be8c194', '787dfa0b-c827-4dad-a82d-0548a6534d88', 15, 'Fire Signs', 'When Shannon throws an Aries themed party, Brooks finally gets his chance to confront Meghan face-to-face for her relentless digging into his past. And an off-handed comment by Brooks throws Tamra into a rage.', '2015-09-14', 44, '/rZflUJnzbYZjTtSvrYIScXoCxji.jpg', '2026-04-03T16:35:32Z', '2026-04-03T16:35:32Z');
