INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('99f0f932-1b88-40ea-a6d6-071c983449f6', '363a94f9-e0e5-441c-aa86-2be2e9832da1', 9, 'The Pawn Strikes Back', 'When Rick gets a shot at an original Eastman Kodak camera, can he develop a deal before it''s gone in a flash? Next, Corey has a sweet tooth for an unopened box of 1980s Star Wars candy. But when Steve Grad sets his sights on it, will the force be with Corey, or drive him to the dark side? Then, Rick gets reflective when a Rolex mirror comes into the shop. And finally, Chum and Corey hit the road to check out a massive 40-foot brontosaurus skeleton movie prop. Can they bring up a deal, or will the price crush their dreams?', '2021-12-04', 42, '/a4SGcGFetJWRzHORx1BX5jNhXBz.jpg', '2026-04-03T16:34:23Z', '2026-04-03T16:34:23Z');
