INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('99f9c503-dfe5-40ef-b866-15a96a37bb6c', '8c3cfac1-d882-4904-b38c-d1981628d00e', 5, 'Episode 5', 'Including the first TV showing of the prototype of a new British electronic control system for model rail layouts. This exciting invention makes it possible to control four locos simultaneously with only two wires between the control panel and the track.', '1978-09-25', NULL, NULL, '2026-04-03T17:21:54Z', '2026-04-03T17:21:54Z');
