INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('9a2469c6-a3be-4fdc-ba8b-6756c0623990', 'b8c1b631-9850-45f3-9361-cdad5571a492', 6, 'Telling Truely', 'As Ysabel packs up for college, Gwendlyn opens up about her sexuality. Christine reveals her moving timeline, and Kody pushes back. Then, after an overheard conversation, Christine tells Truely about the divorce.', '2022-10-16', 43, '/pR2CA6lFaz1kkQjJ4ziiisXKXPG.jpg', '2026-04-03T16:34:32Z', '2026-04-03T16:34:32Z');
