INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('9a399473-2d49-4596-8761-deaa0d5d08b7', 'd589b670-2e75-4922-9f56-029b48e54927', 13, 'Tell All: Part 1', 'In part one of the Tell All, nothing is off limits as the Browns discuss this season''s jaw-dropping moments. Has Meri''s dream of buying a B&B driven the family even further apart? With Utah''s tough new polygamy law, can the Browns ever go home?', '2018-03-25', NULL, NULL, '2026-04-03T16:34:27Z', '2026-04-03T16:34:27Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('9a3a8f2f-a183-46ab-9057-dcaf8040738b', '70c8cb46-2494-4dd4-98f6-6bfb9b3faf73', 9, 'Spooning Paul Revere', 'The Pawn Stars have a chance to buy a historic silver spoon made by a true American legend - Paul Revere. Can they make a deal and scoop it up, or will this piece of patriotic history ride off into the night? Then the Old Man is presented with a handmade cuckoo clock from the 1800''s. Can he tick-talk his way into a deal, or will this negotiation drive him cuckoo? And later a man tries to sell a mysterious vintage archery bow. Will Rick pluck the right string and make the deal, or will he end up missing the target altogether?', '2010-02-15', 21, '/teBWvXDh5fjnQBaEQ37i1xZlN3.jpg', '2026-04-03T16:34:16Z', '2026-04-03T16:34:16Z');
