INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('9a5907fd-2ae3-4695-9b27-b0f6faea9115', '432a6abd-dcca-44cc-82ce-fb39e33b8949', 63, 'Lady Elaine Wants Attention Pt 3', 'Collette is worried that Grand-père will be lonely when she leaves for Paris. After she leaves, Lady Elaine hears Van Cliburn performing at her Museum-Go-Round.', '1971-05-12', NULL, NULL, '2026-04-03T17:35:39Z', '2026-04-03T17:35:39Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('9a5e2fb8-7b1c-4e22-8389-06e6e4f80e02', '4c79c0b6-21a4-4277-8967-be1e791efdbe', 24, 'Pingu and the Paint', 'Mother and Father go out, leaving Pingu sitting at the table with his painting, which needs finishing. Pingu gets some water, and finishes the painting with some blue, and then orange, paint. As he’s admiring the finished painting, a blob of orange paint falls from the brush onto the table. He tries to get it off, but only succeeds in making a bigger mess, and getting it on his chair as well. He then has an idea! He gets a pot of orange paint and a brush from the shed, and paints the table and everything on it, and the chair, orange. He spots a bit he’s missed, and while painting this gets a blob of orange paint on the wall. His solution to this is to make it slightly larger and rounder, and then frame it. As he’s straightening up the frame he gets some more paint on the wall, and then treads in some paint he’s dropped on the floor and leaves footprints behind as he backs away. As he backs out of the igloo he trips, and lands on his sledge, which slides away and into a lump of ice. The impact jogs the pot of paint and the brush out of Pingu’s hands, and these fly into the air and leave orange paint on a couple of igloos and an ice sculpture when they land. Pingu’s solution to this is to add even more paint to most of the igloos in the village, and the sculpture, in a variety of patterns and colours. The villagers see the results of this and gather to discuss what’s happened, and wonder who’s responsible. Then a villager (that is, the postman) saw a trail of footprints, and they follow them to the barrel in which Pingu is hiding. To clear it up Pingu starts to throw snowballs at the paint, and is quickly helped by Pingg and Pingo, which Punki tries to evade them. The other villagers then join in themselves. It then starts snowing heavily, and the new snow soon finishes off the job of getting rid of all the paint.', '2006-03-01', 5, '/zM7DfrAFNH4sDlNRZJkJWvyXbWa.jpg', '2026-04-03T17:22:21Z', '2026-04-03T17:22:21Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('9a629da2-7bf4-4c79-becc-286415e3bc2c', '6e314631-d72b-4ebd-bf39-d123d19108fc', 23, 'Coming to England', '', NULL, NULL, NULL, '2026-04-03T17:20:13Z', '2026-04-03T17:20:13Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('9a6957ae-8788-4204-bc68-97dd3fe57065', 'd920ebae-f00a-4e25-abfe-40492c74ded6', 27, 'A Loose Cannon', 'Chum has a cow when a seller comes in with a giant collection of figurines from "The Simpsons." Will the seller score some D''OH, or walk away Groening? Meanwhile, Corey checks out an old playing card shuffler. Will he stack the deck, or fold? Then, a seller shows off his original copy of the film Ben Hur. Will Rick take a victory lap, or will the negotiations be a drag? And later, Rick and Corey head out to the range to check out a mountain cannon. Will the deal go off with a bang, or will it all just blow up in smoke?', '2020-07-20', 42, '/mRd4mkN2wadADyHI5ZSHTMqFZrD.jpg', '2026-04-03T16:34:22Z', '2026-04-03T16:34:22Z');
