INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('9a9a4979-ba53-4923-8f8d-d9fa212cfdd0', '9e4790f4-3aab-459c-a5ed-7100b4e39a75', 2, 'Oh Christmas Tree!', 'Erin hosts the group at her sprawling Hamptons home, but champagne and caviar leaves some of the ladies hangry for more. The women divulge personal details during dinner at Erin''s favorite Hamptons hot spot, and Jessel reveals intimate information about her marriage. Luckily, Jenna has the perfect gift to spice things up.', '2023-07-23', 44, '/bqSWSpDoLonw0PHA8k5nYvkOWPA.jpg', '2026-04-03T16:35:26Z', '2026-04-03T16:35:26Z');
