INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('9ac14b25-9807-4806-afdf-40d04bb5240a', '1c9ea7d3-e254-4e7b-8a9f-33eea9c6c341', 20, 'More Love More Problems', 'After a tumultuous trip to Greece, the women are back home in the ATL. Kandi heads to Chicago for a major acting opportunity, but her absence at home reopens old wounds. Eva debuts baby Maverick to the world, while the status of Kenya’s marriage hangs in the balance. Porsha hosts a charity event and the ladies lay it all on the table.', '2020-04-05', 43, NULL, '2026-04-03T16:34:49Z', '2026-04-03T16:34:49Z');
