INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('9b1938b3-84fe-41aa-bb46-8e2e5705d74e', '52f9c16b-a60f-4eb7-b991-5c3bf70877bf', 6, 'Shocking News', 'Jeana struggles as the sibling rivalry escalates between Kara and Shane. Kara spends thousands on clothes for school while Shane receives a brand new car.

In other parts of the community, Kimberly waits to hear from her doctor about a very serious health threat. She braces for the worst and ponders what she would miss if she didn''t have more time with her son, daughter and husband.

Slade''s country bumpkin parents visit in their RV. They don''t understand Slade''s extravagant lifestyle and think his relationship with Jo is doomed. Later, Slade and Jo''s date night turns ugly.

Vicki goes back to Illinois for her high school reunion. While in her hometown, she visits her mother, who is unhappy with how Vicki has changed since moving to California.

Lauri and her best friend, Lorelei, submit bikini photos in hopes of getting invited to a sexy pajama party at the Playboy mansion, where they would have to compete with 20-something girls.', '2006-04-25', 44, '/1gMqXlaNcE36YEORNtTdioeTZYS.jpg', '2026-04-03T16:35:29Z', '2026-04-03T16:35:29Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('9b1c155e-55d5-4fa0-8822-fb47c2ed5766', 'd01919fb-98e0-42bf-b9d9-1cecf912f6e1', 11, 'Telly and Baby Bear Take Turns Wearing Papa Bear''s Hat (3796)', '', '1998-11-30', NULL, NULL, '2026-04-03T17:36:42Z', '2026-04-03T17:36:42Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('9b2121c5-1313-44d4-95d9-55a0d00c9372', '80775c3d-fa41-46f6-96ec-efc2e14efdcf', 6, 'Double Down on Delusion', 'The ladies take a limo ride to Atlantic City to celebrate Ramona''s birthday, her first without Mario. A lavish dinner, raucous gambling, dirty dancing and dramas surrounding Sonja are in the cards.', '2015-05-12', 44, NULL, '2026-04-03T16:35:23Z', '2026-04-03T16:35:23Z');
