INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('9bdfcb33-0b50-4c6a-9ffa-c0c3dadabd82', 'c73fa7f1-7ac6-44d4-ac1f-182a70d92313', 3, 'Car Wash Chaos', 'When the kids set up a car wash competition, Sarah finds herself trapped in Nurse Flood''s car when it rolls into the sea at the beach with the tide coming in. Time to call Ocean Rescue!', '2021-10-05', 10, '/lE17DN9UHNzxF03kh7JaylsJzAr.jpg', '2026-04-03T17:14:41Z', '2026-04-03T17:14:41Z');
