INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('9be7ca02-7baf-44ab-96d7-2acd561cccf6', '110e3467-3698-4e19-a35b-f6ebbaeb4d6b', 1, 'The Three Little Pigs', 'If you work hard you can overcome the most formidable obstacles. Thats the morale of this most popular of fairy tales. Billy Crystal and Valerie Perrine are in trouble when they come up against Big Bad Wolf Jeff Goldblum. Billys older brothers just miss ending up on the wolfs plate by the hair of their chin-ee chin chins when he blows there houses of straw and sticks away. Billy the more practical pig, takes his time and constructs his house out of sturdy brick. when the cigar-chomping wolf arrives- he huffs and puffs but can''t blow Billy''s house down.', '1985-02-12', 51, '/rcfS6BSTnQxOzgYqhXgNiWHVNoL.jpg', '2026-04-03T17:38:41Z', '2026-04-03T17:38:41Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('9bf18657-21e8-4c8b-8943-f62b4468490d', 'c9d2b3fb-7845-4f3c-9847-ce1f7717257a', 17, 'Rebel Without a Pawn', 'Corey and Chumlee rock out with personal memorabilia from legendary AC/DC front man Angus Young. Next up, Hollywood rebel James Dean''s ID bracelet finds its way into the shop before Rick heads east to score big with a rare relic from WWII.', '2019-07-22', 42, NULL, '2026-04-03T16:34:21Z', '2026-04-03T16:34:21Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('9bf840e7-544b-4120-b474-1f49416fd2e4', 'f21ca545-466c-448c-ada5-b8acc8b856dc', 13, 'Ending Time', 'Bernard wakes up on New Year''s Eve to find that his watch has been stolen by an arch-criminal Mr Rattle. Mr Rattle is mean to Bernard and his mother knocks Mr Rattle out with a vase. When he finally gets it back, the villain''s deeds have made the watch stop working. Could the new millennium be the end of Bernard''s watch?', '1999-12-17', 15, NULL, '2026-04-03T17:20:05Z', '2026-04-03T17:20:05Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('9c0102aa-7ea5-4606-96e5-121bd64a452f', 'bf874be3-7e2f-4a0e-b205-c76ac1ad69fc', 21, 'Inside Looks (on The Deal)', 'Inside look from the season 2 episode "The Deal."', NULL, 7, NULL, '2026-04-03T16:34:08Z', '2026-04-03T16:34:08Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('9c028e90-ec36-4cf6-a9f9-8505aa8ad3fd', '852a07b0-f228-4197-9147-7aeed79390bf', 3, 'A High Rate of Interest', 'The ladies take a day trip to a local winery; Eboni questions Ramona''s choice of words; Leah confronts Ramona''s questionable blood plasma donation; the ladies engage in some local retail therapy; Sonja''s true feelings are revealed.', '2021-05-18', 60, '/kJIonflysT0qURPhOGl9z4Ibie0.jpg', '2026-04-03T16:35:26Z', '2026-04-03T16:35:26Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('9c0397ce-b414-4e18-9023-0d1ebaacaa22', '119c16d5-1047-45ec-8242-c72a8eed423b', 53, 'D.W.''s Blankie', 'D.W. loses her blankie and she and Arthur search all over town just to find it.', '1996-11-12', 13, '/sABYOFvPpS4RKDdnrSjvObWa2Xt.jpg', '2026-04-03T17:37:55Z', '2026-04-03T17:37:55Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('9c0a6f20-df4d-4060-9504-c0d2ca312bed', '04fb713d-9c59-45f7-8de0-acd7582daa53', 1, 'Wives and Misdemeanors', 'With less than a year left in Joe''s prison sentence, Teresa comes into her own and decides to enter a bodybuilding competition. Margaret feels the effects of aging. Dolores struggles to forgive Frank. Melissa celebrates her birthday.', '2018-11-07', 43, '/eI83zTHQSQEavYDnCQSCs5rk1VQ.jpg', '2026-04-03T16:35:17Z', '2026-04-03T16:35:17Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('9c0bb663-cac0-405d-8a87-95a71c36e28e', '65524b14-e29e-4b04-81d3-fbebe525e9ec', 21, 'Franklin''s Bike-A-Thon', 'Franklin participates in a charity ride for a new library computer.', '2004-07-25', 12, NULL, '2026-04-03T17:40:16Z', '2026-04-03T17:40:16Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('9c0fb094-6589-42e3-b126-8fcefc75c661', '9ae29d08-7ce8-47f9-8584-2d3e861067a8', 12, 'Half Measures', 'Against Walt''s advice, Jesse lashes out. Fearing for Jesse''s safety, Walt takes drastic action to intervene and tragic event leads to a shocking confrontation.', '2010-06-06', 48, '/mOvMekI0YKm20I42XK93mPCQ4ru.jpg', '2026-04-03T15:40:33Z', '2026-04-03T15:40:33Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('9c125bf6-4b88-4908-9244-7e0bd534d133', '6a2d2839-7106-4c3b-8906-c9b3e4bfcc8b', 19, 'Reunion (1)', 'Andy Cohen hosts as the California ladies come together to deal with the big issues and conflicts of the season.', '2014-09-25', 44, NULL, '2026-04-03T16:35:32Z', '2026-04-03T16:35:32Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('9c14f217-ca0b-4fea-9732-37da7c588c3c', '66a11a09-aee2-4a7b-8543-ab080a9d1be4', 6, 'Medford, 90210', 'Lisa Rinna returns to her hometown of Medford, Ore., to visit her ailing parents; Eileen gets a chance to meet everyone at Kyle''s barbecue party; Brandi pressures Lisa Vanderpump for an answer about her housewarming party.', '2014-12-23', 42, '/dUI0155h5i3mvIYjLOzPB9xyoYA.jpg', '2026-04-03T16:34:56Z', '2026-04-03T16:34:56Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('9c1d45f9-7b92-4de2-8449-c5d34469e1d1', '0e419615-4c96-4dde-8ed2-715770ba77bb', 24, 'A Strange Bird', 'One morning, Bear decides to visit the post office, knowing that Jeremiah can be slow in delivering the mail and wondering if anything''s come. At the post office, he finds a two-week old postcard that reveals that a penguin named Puck from the South Pole is paying a visit to the Big Blue House --- today! Bear hurries home to greet Puck. Everyone there is eager to meet him, but the kids begin to worry when they find his food tastes and his behaviors somewhat odd. They try to play with him, but worry that they just don''t understand him. Meanwhile, Tutter learns all about diversity at Mouse School. 

Songs 

It Takes All Kinds 

Notes 

The kids of the Big Blue House play the song "I Only Have Ice for You" for Puck. The title of this song is a spoof on the classic lounge song "I Only Have Eyes for You", as performed by Frank Sinatra. 

The song in this episode, "It Takes All Kinds," is Track 4 on the album Playhouse Disney 2.', NULL, 25, NULL, '2026-04-03T17:35:32Z', '2026-04-03T17:35:32Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('9c2155ae-7090-4e5d-9992-d7725fa4978c', 'e93f04c2-7344-4b93-abba-8ba1b2f8eb35', 54, 'Episode 589', '', NULL, NULL, NULL, '2026-04-03T17:36:30Z', '2026-04-03T17:36:30Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('9c21667f-f43b-49cd-9f88-bcf35fe9c959', '20d7138e-eea8-46a8-8ada-2b0f0ee1f674', 45, 'Episode 45', 'What do a bent knee dolphin, the flamingo position and an inverted vertical with support sculling have in common? Sarah discovers the answer when she joins the girls of the Rushmoor Synchronised Swimming Club.', '1983-02-17', NULL, NULL, '2026-04-03T17:21:56Z', '2026-04-03T17:21:56Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('9c237193-97ed-47c3-9125-ac5a9310ac37', 'c21dbd22-5e2e-4414-bb67-750399aaf6f0', 27, 'James Gang Rides Again', 'Gang up with the Pawn Stars when original photographs of Old West outlaw Jesse James ride into town. Will the guys break the bank on these incredibly rare items, or will the seller make a quick getaway? Then, Chumlee and the Old Man get an earful when they''re presented with a Leslie organ speaker from the 1950''s. Can they turn up the volume on this negotiation, or is the deal too far out of tune? And later, a guy walks in with a Boy Scout first aid kit from the 1930''s. Will Rick be prepared to make an offer, or will he think it lacks merit?', '2012-02-27', 21, NULL, '2026-04-03T16:34:17Z', '2026-04-03T16:34:17Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('9c2428d7-f35e-45d8-aa90-dde2979d216e', '9193e795-da7c-40ec-b68f-f63aa7d5174f', 100, 'Histories & Lore: The Unsullied', 'Jorah Mormont recounts the legendary Battle of Qohor, in which three thousand Unsullied slave-warriors held off an entire Dothraki horde outside the gates of Qohor.', '2014-02-18', 4, '/jAGQIhdM7zCPs5R4ad0zG0FD6g.jpg', '2026-04-03T15:40:35Z', '2026-04-03T15:40:35Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('9c2480da-074a-43e6-b6e8-50538394bd53', '70d9e397-6813-4785-887d-27d034928bae', 23, 'Pingu and the Postcard', 'A postcard is delivered which Pinga picks up. On it is a picture of a Hawaii beach fringed with palms. On the beach is a dancer who is wearing a garland made with pretty flowers, and a drummer. Pinga shows the card to Pingu, and says that she wants a garland of pretty flowers. Pingu is not sure that he can do anything about it, but Pinga points out Mothers lovely pot of flowers. Pingu goes over to the pot, takes off all the flowers, and makes Pinga a garland with them. He then takes off all the leaves and uses them to mimic the palm trees. Finally he empties the pot, throwing the soil and stem aside, and turns it upside down. He uses the upside down pot with a pan from the stove, which makes a good sound when banged with a spoon, to make a drum. He then plays the drum he’s made while Pinga dances. Mother then arrives home and at first enjoys what she finds them doing, but passes out when she sees what has happened to her plant. Pingu and Pinga rush over to her and are wondering what to do when Father arrives home. They seat Mother in a chair, and Pingu and Pinga explains to Father what they have done, and why. Father goes to the florist and gets a replacement pot of flowers for Mother, who is delighted when she revives and sees them. Mother and Father then enjoy a repeat performance given by Pinga and Pingu.', '1996-08-15', 5, '/iCdb9CsMI6O779iyvw3GMiSr44c.jpg', '2026-04-03T17:22:19Z', '2026-04-03T17:22:19Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('9c26e0d4-66e3-49a0-9289-a29dd63bdd2d', '05c0e384-194c-4417-9f62-803eb615e409', 67, 'Dedication at the Rockit Factory', 'Title number 0067. Opens with Mister Rogers arriving with a yoyo. King Friday is ready to dedicate the new factory, but Lady Elaine senses he is afraid of elevators. This changes some of the dedication.', '1968-05-21', 29, NULL, '2026-04-03T17:35:38Z', '2026-04-03T17:35:38Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('9c283866-f9d1-4046-bc26-1932ea306862', 'a61eda16-b572-4c5b-ba55-57df932417ec', 4, 'Uncle Matt''s Discovery', 'Uncle Matt returns home from Outer Space, and disgraces himself in front of Gobo and his friends. But all that changes when he makes an incredible discovery.', '1986-01-27', 24, '/378HIKCi5S1a8u1AzXIq3PEPJDc.jpg', '2026-04-03T17:35:01Z', '2026-04-03T17:35:01Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('9c2c26a6-0a93-4196-85f6-e64e3996ea6f', 'a8db07e5-fba3-49a9-bd12-947c111b39be', 12, 'Always the Bitch, Never the Bride', 'Ramona and Sonja''s friendship gets back on track as they plot to get Sonja back in Bethenny''s good graces. Meanwhile, Jules shares a secret business project with an impressed Michael; Bethenny has a health scare; and the women gather for a dog wedding.', '2016-06-22', 44, NULL, '2026-04-03T16:35:24Z', '2026-04-03T16:35:24Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('9c33f06c-5629-4e59-8932-7fb21855c516', 'b8c1b631-9850-45f3-9361-cdad5571a492', 9, 'A Polygamist Divorce', 'After dropping off Ysabel in North Carolina, Christine tells her emotional sister wives that her house is under contract and she''s moving to Utah in a week. Then, Kody reveals that he no longer considers himself married to Meri.', '2022-11-06', 42, '/cuRvSGJRUfseX4qSXrQ9vnXqVl0.jpg', '2026-04-03T16:34:32Z', '2026-04-03T16:34:32Z');
