INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('9c391d3b-18de-4142-a708-9ced7c33e138', '8c0f12e1-5379-4a27-aca2-b69401a33b0f', 7, 'Arthur Makes a Movie', 'Arthur wants to see a movie, but he is too young, so he and his friends make a parody of the movie.', '1997-10-23', 13, NULL, '2026-04-03T17:37:55Z', '2026-04-03T17:37:55Z');
