INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('9c3fae38-1118-4a86-a445-1bc2abbb5266', '5144de59-e67f-4fcf-919b-7106989ab797', 5, 'Gotta Dance', 'The kids obtain a sheet of dance steps and learn of various cultural dances while trying to decipher it. Sizzle recalls the time Nuzzle criticized her for carrying her tail wrong and refuses to dance with him again.', '1995-01-20', 29, NULL, '2026-04-03T17:12:21Z', '2026-04-03T17:12:21Z');
