INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('9c407cc0-d3e6-4979-8018-8e55aaa18355', 'b91685b5-c0d4-4040-b72e-620169541bfc', 10, 'Reunion', 'The ''housewives'' get together to dish on some of the more dramatic and sensational events from the second season and reflect on how their lives have been impacted by the series.', '2007-03-20', 44, '/rwv8mt1K34a4DMUGouwcO0c4lS9.jpg', '2026-04-03T16:35:30Z', '2026-04-03T16:35:30Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('9c44bb43-d04d-4e94-8a01-b0dacd2a78e3', '0bbd380c-5cb8-46a6-8838-b5d60223c073', 18, 'Mummenschanz', 'Miss Piggy is repulsed when Gonzo tells her that he loves her. Kermit tries to help by asking Piggy if she would like to go to dinner -- and when she accepts, he fixes her up with Gonzo. Everybody gets karate-chopped.', '1977-01-09', 26, '/cgdBk0EYmSwmgLik4BtKeDsw36Y.jpg', '2026-04-03T17:35:24Z', '2026-04-03T17:35:24Z');
