INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('9c58cf13-42a3-4731-9d16-b4bb7314fb3b', '7c756336-29db-4634-b976-e993e8f51da2', 8, 'War of the Darbys', 'Ashley and Michael''s marriage is tested when she unveils a new menu for their restaurant at a press event and Michael attempts to shut it down. Gizelle and Karen head out for a double date where the truth comes out about Gizelle''s date. Meanwhile Robyn questions her home life and identity after a birthday dinner for her mom. Golf balls fly when Karen attempts to mend fences between Monique, Gizelle, Ashley and everyone.', '2017-05-28', 42, '/oAcrt7hQirnQ0XYSPVrR59oJCir.jpg', '2026-04-03T16:35:39Z', '2026-04-03T16:35:39Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('9c594b55-9e7b-4c78-9209-9aa138c89646', '5a4e38a1-8e54-4974-8097-d7a7b48630a2', 61, 'Episode 61', 'with Valerie Singleton, John Noakes, Peter Purves', '1971-04-23', NULL, NULL, '2026-04-03T17:21:50Z', '2026-04-03T17:21:50Z');
