INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('9c6cf3ee-e899-41a7-b18b-383af67462b0', 'cb8a0322-be77-485b-b339-bdd572bca349', 2, 'The Ballad of Buster Baxter', 'Buster feels left out having missed all the adventures since he was away. He feels that everyone has changed and they feel the same about him, so Arthur plans a party so they can rekindle their friendship with Buster.', '1998-11-16', 13, NULL, '2026-04-03T17:37:56Z', '2026-04-03T17:37:56Z');
