INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('9c7e4802-e45c-43e9-b1f3-391a2a44f719', 'a8f3a681-7abc-41e0-9988-9b8804d74611', 19, 'Hard to Say Goodbye', 'As the Browns prepare a proper send-off for Logan''s graduation, Kody and the wives push hard to get moved into their new homes before Christmas. Will all the pressures of moving and decorating for the holidays get the better of them?', '2012-12-30', NULL, NULL, '2026-04-03T16:34:28Z', '2026-04-03T16:34:28Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('9c8302a9-fc3e-47cd-8349-671976d36465', '235468b0-20fc-4714-bc3f-d7e7aeb25f4b', 16, 'The Art of Arguing', 'Larsa moves into her new house; Alexia and Todd near their divorce deadline; Jody gives Lisa an ultimatum for a proposal; Adriana hosts an Art Basel event, but she starts seeing red after discovering the identity of her birthday cake culprit.', '2025-09-18', NULL, '/7ltt9MxMQr2v9LXwKEj7yReHMsn.jpg', '2026-04-03T16:35:12Z', '2026-04-03T16:35:12Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('9c875c15-a22d-4716-8b4e-7aed8e844f88', '6e0be2a3-a234-453b-abb7-0ba535a93601', 5, 'Franklin Delivers', 'Franklin and Bear are eager to deliver newspapers while the local paperboy is away for the weekend. They soon find out that windy Saturdays are much better for flying kites than delivering papers.', '2000-05-22', 12, NULL, '2026-04-03T17:40:15Z', '2026-04-03T17:40:15Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('9c89de7e-5f35-489f-962b-856a6a28186e', 'e9352408-a84b-4c1a-905c-7aa862062f7f', 22, 'The Shoemaker', 'Pat notices a child with shoes she likes, so she visits Gerry''s Shoe Repairs to have some made especially for her.', '1995-07-16', 10, NULL, '2026-04-03T17:19:37Z', '2026-04-03T17:19:37Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('9c90ec86-facc-420b-82cf-60a0f6cff945', '4892e2af-46c1-4b4e-ac81-eac161b5a347', 80, 'Episode 80', 'A thousand programmes later ...

'' Way back in 1966, if anyone had told me that during the next 12 years I''d make a five-mile fall out of an aeroplane, crash at 90 mph on a bob-sleigh, climb to the top of Nelson''s Column-twice, become a cook, vault over a ditch and be trodden on by an elephant, I''d never have believed them! But they''ve all happened to me during my thousand or so appearances on Blue Peter. Today you can watch some of those extraordinary experiences.'' (JOHN NOAKES )', '1978-07-03', NULL, NULL, '2026-04-03T17:21:53Z', '2026-04-03T17:21:53Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('9c92631d-745e-4464-9abe-05bae71536a3', 'da06465b-9154-4feb-a455-374df7dab02f', 19, 'Elmo and Zoe Claim a Ball (4104)', 'Zoe and Elmo find a ball on "Sesame Street" and begin arguing over whose ball it is. They both keep saying, "It''s mine!" Luis then enters and explains that instead of arguing over whose ball it is, they could have fun with it by sharing, taking turns, and playing together. While Zoe and Elmo are learning to share and take turns, Baby Bear comes in and is so relieved to see his ball! They all begin to argue over whose ball it is again until Zoe and Elmo are finally convinced when Baby Bear shows them the letter "B" that he had marked on the ball for "Baby Bear." Baby Bear could see that Elmo and Zoe are sad to see the ball go so he decides to share the ball, and they all realize that taking turns and playing together is even more fun than owning your own ball.', '2005-09-20', NULL, NULL, '2026-04-03T17:36:44Z', '2026-04-03T17:36:44Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('9c95e555-22bc-4d8b-b202-3a0cb657bb30', '73ae1459-ba91-4185-a9da-bf6f2844af49', 25, 'Secrets Revealed', 'The women dish on confessional fashion choices and react to never-before-seen footage.', '2020-10-01', 44, '/wOqMFVHs4CMdSZRd4sLHASVDnBD.jpg', '2026-04-03T16:35:25Z', '2026-04-03T16:35:25Z');
