INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('9cbdb1ef-650e-4440-95e4-71988987a8a8', '45e01c04-6ac6-41e1-87d8-f749ee230385', 21, 'Day At The Seaside', 'It is Station Officer Steele''s day off from the Fire Service. Elvis persuades Sam to let him be in charge at the fire station. Station Officer Steele, Trevor Evans, Nurse Flood, Mandy, Norman and Dilys Price go to the seaside together, but will the SatNav get them there?', '2008-03-10', 10, '/eI41qZy72xXaNNNGV5T197XzEes.jpg', '2026-04-03T17:14:38Z', '2026-04-03T17:14:38Z');
