INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('9cdbec06-cc62-4ee4-858e-6862d3d7b274', '5db3ff78-e439-48e1-8f67-988ecbf85d17', 17, 'The Journey to England', 'Richelieu and Rochefort know The Three Musketeers & Dogtanian are going to England to recover the Queen''s diamonds. Rochefort tells Richelieu that his men will intercept them and ''finish them off, once and for all''. They arrive at the first group of Rochefort''s men, who have blocked the only road through the forest, Athos, Porthos, Dogtanian and Pip go round another way while Aramis teaches Rochefort''s ruffians some manners. The 4 of them come up to a traffic jam in town, the owners of the carts threaten them when they try to ride past. Athos stays to teach the mongrels some respect while Porthos, Dogtanian and Pip sneak around the other side...', '1982-01-22', 24, '/9ptUqczbEkU6N6bzSAnUMjUdFUr.jpg', '2026-04-03T17:18:43Z', '2026-04-03T17:18:43Z');
