INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('9d5c5e99-3d5e-4fec-a050-8e684f2556ac', 'f5266c49-eb29-4594-b5d9-f927edfee336', 22, 'Bitzer For a Day', 'Bitzer is called upon by the Farmer to help him get fit. That isn''t quite what he had in mind and it is up to the wily Shaun to teach him to see the error of his ways.', '2014-09-19', NULL, '/wh1zoOls4qtlVmlLWXzPSv7wjES.jpg', '2026-04-03T17:39:32Z', '2026-04-03T17:39:32Z');
