INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('9d609d1e-c8b3-44be-83d0-4cd27c78f0ff', 'a61eda16-b572-4c5b-ba55-57df932417ec', 2, 'Wembley''s Wonderful Whoopie Water', 'Wembley''s got a special talent; he can hear water in the rock walls. But when Gobo and Red don''t believe him, he sets out to prove he''s right. When water finally breaks out, the Fraggles discover that this type of water is special. But when the water starts to cause rock quakes and Gobo falls into the cracks, is it finally time to shut down the fun?', '1986-01-13', 24, '/kyPpH4PoWshwHWr8kj2EtipwFNo.jpg', '2026-04-03T17:35:01Z', '2026-04-03T17:35:01Z');
