INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('9d6b7cf4-df98-497b-87f3-a5c672231935', '5db3ff78-e439-48e1-8f67-988ecbf85d17', 11, 'Dogtanian''s Trance', 'Cardinal Richelieu has, after his other underling''s repeated failures, asked Milady to make sure Juliette can''t organise the meeting between the Duke of Buckingham and Queen Anne. Juliette is still on the run from the Cardinal''s guards and manages to run into Planchet and Sandy, using Sandy to escape. Milady is in a nearby coach when Planchet and Dogtanian are discussing what''s happened, from there she lures Dogtanian into her house...', '1981-12-11', 24, '/9ujU2MKMNEklyq6sHRlatRfaZHO.jpg', '2026-04-03T17:18:43Z', '2026-04-03T17:18:43Z');
