INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('9d76d7df-d2b0-478d-87b3-7a8c7b9109b4', 'bbfee3b4-9c95-48a6-beaa-791fa08b1f43', 6, 'Episode 6', 'Tea for Two

Janet toils In the plantations at Nuwara Eliya and discovers there''s far more to producing a good cuppa than meets the eye. it takes five kilos of leaves to fill one basket and skilled pluckers produce three baskets a day-or 2,000 cups of tea.', '1983-09-29', NULL, NULL, '2026-04-03T17:21:56Z', '2026-04-03T17:21:56Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('9d78d6d2-5609-4d6b-b9cd-9d3f4bdf8151', '04e133fd-c4a3-4dfa-8369-c6dcfd1e3a5a', 35, 'The Count counts counts', 'The Count becomes obsessed with counting and recounting, driving friends crazy with his numerical enthusiasm. He finds endless joy in tallying everything on the street.

Sponsors: H, I, 3', '1985-01-04', NULL, NULL, '2026-04-03T17:36:35Z', '2026-04-03T17:36:35Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('9d7ae2fd-c097-4a4f-8a3d-2f233faff263', '87f84063-82b3-45a4-936c-3759e5d91ce3', 1, 'Best of Frenemies', 'The women of Salt Lake City return and fractured friendships have split the group in two. Caught in the middle, Lisa tries to get Jen and Meredith to make amends. While Heather prepares her daughter for college, Whitney throws a birthday bash for her stepson and Mary starts a podcast. Lisa’s friend of 10 years and new housewife, Jennie is introduced.', '2021-09-12', 44, '/2x3fp4NB6zyKXB11G198jXWY5rH.jpg', '2026-04-03T16:35:44Z', '2026-04-03T16:35:44Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('9d808c06-f62d-488d-9f43-ccb8dab0f2b2', '79916e0e-881c-43a7-b4ee-00e5052a94be', 26, 'Theodore''s Backwards Day', 'While working Theodore''s engine breaks down thus resulting in him only being able to go backwards. This incident makes him feel embarrased and so decides to try and hide from everyone the fact that he can''t go forward.', NULL, NULL, NULL, '2026-04-03T17:10:11Z', '2026-04-03T17:10:11Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('9d83c02f-31ef-4045-a0e2-22175128bcbd', 'fb4ecc73-cb92-4c5c-821f-92179058b37b', 64, 'Oscar and Sloppy miss Slimey (3719)', '', '1998-02-12', NULL, NULL, '2026-04-03T17:36:41Z', '2026-04-03T17:36:41Z');
