INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('9dc9c04f-3d9c-43f1-b540-dcaa979e3c88', 'ea73e13c-6962-4804-8305-c303df65f89f', 14, 'The Royal Wedding (4) - How people build houses', 'Lady Elaine Fairchilde and Handyman Negri give their present for the Royal Wedding by changing the old Castle into a new, larger Castle.', '1969-02-27', NULL, NULL, '2026-04-03T17:35:38Z', '2026-04-03T17:35:38Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('9dcbef63-1ea1-4911-986b-a2faf01028d2', '5704fb3f-fbbc-4177-88b0-9226373a9d4e', 31, 'Episode 31', '', '1966-01-24', NULL, NULL, '2026-04-03T17:20:12Z', '2026-04-03T17:20:12Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('9dd3250b-6a46-4186-99e0-c994240e9c30', '650bac93-7b59-41fc-b277-dc6f8bdcd7bb', 10, 'Escape Orson', 'The Hecks find themselves spending New Year''s Day attempting to stave off a zombie apocalypse in the Orson Escape Room, desperately trying to beat the Donahue''s record of getting out with more than one minute, eight seconds to spare. Meanwhile, Brick is convinced that the mild-mannered man assigned to the family''s Escape Room group is really the famous author of the "Planet Nowhere" books; Sue divulges a secret about herself to Axl that''s she''s been keeping since childhood; and Mike is stunned when Frankie reveals that she had a romantic dream involving Frank Sinatra.', '2017-01-03', 22, '/fdBm6pGYiijfnxBrySNVoRNDHcS.jpg', '2026-04-03T15:40:31Z', '2026-04-03T15:40:31Z');
