INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('9dfad1ad-5631-431b-8d01-184221224f00', 'db555b98-87d6-4cd2-b7b4-973f9206cb1e', 23, 'Reunion (3)', 'The reunion concludes as the confrontation between the OG of the OC and the new housewife escalates when Vicki tries to shame Braunwyn over her behavior. Andy wishes Vicki farewell, Emily talks about the worst year of her life, and Shane joins the ladies providing a surprising perspective on their marriage. Gina''s emotional and difficult year is discussed, including a post-season incident that involved the police. The ladies toast to an eventful season 14 with a nod to their trip to Miraval.', '2019-12-26', 44, NULL, '2026-04-03T16:35:34Z', '2026-04-03T16:35:34Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('9e031524-632e-4bca-89a0-5210b17333f1', '61e0c9d9-337e-4fe4-a0fd-e567b29af115', 7, 'The Huzzbands', 'Angie''s anniversary party leaves the group at odds, causing Bronwyn to question who she should invite to Palm Springs. Justin and John work to resolve their issues. Angie takes Heather to task for misrepresenting her comments about Lisa and betraying her trust. Meredith finds herself in conflict with Angie''s husband, Shawn, over a podcast and reveals she''s facing challenges in her marriage with Seth. Bronwyn invites Heather over to make amends, but things quickly go awry.', '2024-10-30', 43, '/bCUDOeeSsYr45VXyjP5SPJbt1u9.jpg', '2026-04-03T16:35:45Z', '2026-04-03T16:35:45Z');
