INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('9ec91a26-091a-4535-a6b2-676667570755', '208e80de-61e3-4a2f-857f-c667ffc29134', 16, 'Jonathan Winters', 'Jonathan is convinced that a gypsy has put a curse on the show, and while Kermit scoffs at the idea, he does notice that everything is going wrong. A few acts have to be canceled, but Kermit refuses to believe there''s a curse until a meteorite falls on his flipper. In the final stage of the curse, everyone begins to speak in mock Swedish.', '1980-02-08', 26, '/xN3HCcjkVSGIcZm9AE55hEwSc4N.jpg', '2026-04-03T17:35:25Z', '2026-04-03T17:35:25Z');
