INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('9efad268-04f9-41bb-8c33-f35d2e4df074', 'a8f3a681-7abc-41e0-9988-9b8804d74611', 6, '4 Wives, 4 Valentines', 'What''s the most awkward day of the year for a Polygamist? Valentine''s Day! And how do the Browns handle monogamy''s biggest holiday of love? This year, Kody takes his young daughters to a daddy-daughter Valentine''s dance at their school.', '2012-06-03', 22, NULL, '2026-04-03T16:34:28Z', '2026-04-03T16:34:28Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('9efc3cdc-7df1-4e2b-a231-4121df03108c', 'ea1650c2-e4f1-46c7-93ba-74b5d45d08e5', 9, 'Nene Get Your Gun', 'Phaedra adjusts to motherhood as she brings her new baby home from the hospital and proving it doesn''t get easier, Kim wrestles with her daughter''s questions about sex. Sheree decides she has had enough and confronts "the doctor" about his evasiveness. Kandi rewrites "The Ring Didn''t Mean a Thing" to make it more Kim friendly and plays the new track at Kim''s parents'' dinner party. Cynthia plans her dream wedding with a celebrated stylist friend and high-end wedding planner, while NeNe''s marriage nears the breaking point as her relationship problems are exposed in a very public way, leading to a dramatic confrontation with Gregg.', '2010-11-28', 43, '/3ebH50I8GrX1JfqfwN4dCnxtYNT.jpg', '2026-04-03T16:34:45Z', '2026-04-03T16:34:45Z');
