INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('9f52b0ca-4f8c-47e7-806f-64c3635d12d8', '7b8e3988-fbf3-4cfc-aeb2-782ae5a64e2d', 14, 'Where’s The Itsy Bitsy Spider?', 'Elmo, Telly, and Rosita wait for the Itsy Bitsy spider to appear on a water spout in the arbor. Chris loves the song “Itsy Bitsy Spider,” so they all sing it together. After Chris leaves, they decide to find Itsy Bitsy. First, they think about where bugs are found: near plants, flowers, and in dirt. Using the clues, they decide the Itsy Bitsy Spider might be in the garden. When they reach the garden, Telly observes a bug with six legs but they find out it’s a beetle, not a spider. The beetle teaches them that a spider is not an insect, but an arachnid, or a bug with eight legs. They come upon a second bug, but it’s another insect- a hopping grasshopper! The grasshopper gives them the clue to check the spider’s home. Rosita spots an ant hill, but they find out that ants, not spiders, live in ant hills. Then they count the ant’s legs and realize it’s an insect, not an arachnid. The ant gives them the clue that a spider lives in a sticky and stringy place. Elmo realizes that they need to look for a spider web. Telly finds part of a web and follows the string until they reach the Itsy Bitsy Spider! But Itsy Bitsy explains she has more important things to do than sing “Itsy Bitsy Spider.” She is waiting for her egg sac to hatch. Suddenly, the sac hatches, and Telly, Rosita, and Elmo watch in awe as the tiny baby spiders are born!', '2010-11-09', NULL, '/jDlNlPkvaYWOigQeuF2WBBZzSXo.jpg', '2026-04-03T17:36:46Z', '2026-04-03T17:36:46Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('9f5a7912-2706-4c34-908b-374c88fd8e0f', 'b2317fc3-1cfc-4f19-b181-effa23959c6d', 15, 'Reunion (2)', 'Margaret and Teresa face off while Jennifer reveals new information about the state of her marriage. Jackie sheds further light on her eating disorder. A heated exchange between Melissa, Margaret and Jennifer causes even Andy to lose his patience.', '2022-05-10', 43, '/hwkkbl4u6VUQY0QjD7QDGa7JW05.jpg', '2026-04-03T16:35:18Z', '2026-04-03T16:35:18Z');
