INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('9fbab685-f1e7-4883-bf42-5dd42f8cb380', 'c1df0e9b-e03e-48e5-a930-61ee5ef85840', 17, 'Just Desserts', 'After eating too much sweets and desserts, Arthur has dreams involving Brothers Grimm fairy tales.', '2000-10-30', 13, NULL, '2026-04-03T17:37:56Z', '2026-04-03T17:37:56Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('9fbc4264-d7f0-4386-aa1c-f8ece7eac096', '4861ce46-9045-43c7-963f-27b4ea539804', 19, 'Episode 149', '', '1970-01-15', NULL, NULL, '2026-04-03T17:36:28Z', '2026-04-03T17:36:28Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('9fbc87c4-b96f-4625-ab91-0767cdcfb7f8', 'a8f3a681-7abc-41e0-9988-9b8804d74611', 4, 'You Asked, Browns Answered', 'Everyone has questions about Polygamy. Today the Browns answer the toughest questions submitted by viewers. From Contraception and gay children to Kody''s favorite and least favorite traits of each wife, nothing is held back.', '2012-05-27', 43, NULL, '2026-04-03T16:34:28Z', '2026-04-03T16:34:28Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('9fbee25b-9ea8-456f-b989-0b59dd38fcd0', '66a11a09-aee2-4a7b-8543-ab080a9d1be4', 18, 'Confessions of a Housewife', 'Lisa Vanderpump refuses to accept Brandi''s apology; the women return home after a final dinner in Amsterdam; Brandi gets bad news about her father''s health; Kyle angrily reveals to Kim what Brandi has been saying behind her back.', '2015-03-17', 42, '/zX0D0ntQKaybCFb9EYusdULTwl0.jpg', '2026-04-03T16:34:56Z', '2026-04-03T16:34:56Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('9fc12d97-19f5-42d3-9cff-1eec40841f06', 'c4d795ae-6afa-47d6-9819-4dd057030a3c', 18, 'The Model Bride', 'The ladies all come together to celebrate Eva and Michael''s big day; the ladies are concerned with Shamari''s behavior; NeNe drops a bomb about her marriage; Kandi and Porsha confront Marlo about a miscommunication that occurred after NeNe''s party.', '2019-03-17', 43, NULL, '2026-04-03T16:34:48Z', '2026-04-03T16:34:48Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('9fcad8a1-ab94-42cb-8b27-168d3025adcc', 'bcab920a-51a5-4cbb-aa59-41578a0eb005', 5, 'Amnesia Appetizers', 'Lisa Vanderpump and Kyle talk female rejuvenation with a plastic surgeon, while Lisa Rinna and Erika meet Eden, daughter of hairstyling icon Vidal Sassoon. Dorit hosts a dinner party where she and her husband PK question Lisa Rinna and Eileen’s grieving decisions. When confronted, Dorit remembers nothing, leading to flared tensions at a luncheon at Camille Grammer''s new Malibu house.', '2017-01-03', 43, '/7EMBegX2TsbSQqqrNZ1TBNLPF9I.jpg', '2026-04-03T16:34:56Z', '2026-04-03T16:34:56Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('9fcd9c8b-cecd-4ac0-a81b-9f885e352de9', '1d39506b-06b8-4f93-9136-0208069bd7e4', 1, 'New Alliances', 'Season 3 opens with summer winding down in the Hamptons and alliances flip-flopping dramatically. Here, a sunny day on a yacht turns stormy due to cruel remarks. Meanwhile, Bethenny returns to Manhattan to pose nude in a PETA photo shoot; LuAnn and Jill reach out to Kelly; Bethenny and LuAnn share a cocktail get-together---but LuAnn may have a hidden motive for the meeting.', '2010-03-04', 43, '/nVYAibrIfoI5mgzx9IZ6QKs7Mwl.jpg', '2026-04-03T16:35:22Z', '2026-04-03T16:35:22Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('9fcf4c56-8bea-4088-b45e-25306026d9b4', '1c0a48a4-4d1c-424b-b54f-265883e6b26e', 6, 'Rap Sheets and Old Beefs', 'An old wound threatens Kandi and Marlo''s friendship, and Drew finds herself firmly planted in the middle; Sheree gets deep into her Glamma life as Kenya explores new business ventures and old grudges.', '2023-06-11', 44, '/7UWCJf74UzIqlkU6oVNthxla7c2.jpg', '2026-04-03T16:34:50Z', '2026-04-03T16:34:50Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('9fd28027-c1b2-4a38-a569-742844ba4a58', '04e133fd-c4a3-4dfa-8369-c6dcfd1e3a5a', 75, 'Big Bird counts backwards', 'Big Bird enthusiastically teaches everyone on Sesame Street to count backwards from ten to one, believing it''s superior because it always ends at one. Maria points out that everyone may already know this from school, so Big Bird pivots to simply encouraging people to attend school instead. Oscar reads from his book of Mother Grouch nursery rhymes, which Gordon critiques for lacking actual rhymes.

