INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('9fe61468-b017-4336-9b93-ca9ca1abb45e', '7c0e1f66-8835-4e8a-8ad9-0eee57155b4c', 14, 'Ask the Creators', 'The Creators of Avatar: The Last Airbender answer questions about the show.', NULL, 4, NULL, '2026-04-03T17:40:47Z', '2026-04-03T17:40:47Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('9fedee05-81e6-4b15-8cbd-f4792d58f946', '63f9bf6d-39b3-44f4-b885-a56807277a80', 24, 'Disneyland''s 35th Anniversary', 'The celebrity-laden special, directed by John Landis and hosted in part by Tony Danza, focused on the changes to Disneyland over the years, as stars recalled their favorite attractions. Miss Piggy and Gonzo are prominently featured in a story-sketch titled "Pigerella," written by Bill Prady. Piggy, recalling her first visit to Disneyland, longs to replace Cinderella (played by Debbie Carman) in the big parade. After much conniving, Piggy succeeds, after "fairy god-thing" Gonzo gets himself and the real Cinderella lost (though Gonzo seems to develop a fondness for Cinderella). Another sketch involved cast members from Cheers, including Rhea Perlman, George Wendt, Kelsey Grammer, and Bebe Neuwirth; Will Smith, Ernest P. Worrell, and C-3PO also made appearances.', '1990-02-04', 30, NULL, '2026-04-03T17:35:23Z', '2026-04-03T17:35:23Z');
