INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('a0132881-eefa-4890-b81e-9169e7c53c34', 'd306a064-e835-417e-8548-0cf806295f31', 12, 'Apology Not Accepted', 'Larsa shows Lisa her support and a good time by taking her to a Miami hot spot; Julia struggles to make progress in the adoption process; Alexia, Nicole, Guerdy and Marysol''s quadruple date heats up when Anthony and Todd exchange words.', '2023-02-02', 44, '/wn5SsfiL73v69IufsxP3T3TTNid.jpg', '2026-04-03T16:35:11Z', '2026-04-03T16:35:11Z');
