INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('a0250fd5-73b9-49a0-96c6-c7cc8626c3d0', '3fc7c152-e4f6-426a-a899-36ec454c4403', 74, 'Lights, Camera, Dragons', 'When Ord loses his pet mouse, Cheddar, Emmy decides to film "The Great Dragon Mouse Mystery" with her video camera. However, she causes some hard feelings when she declines Max''s help and suggests that her cast of dragons work through a lunch break.', '2000-04-25', NULL, NULL, '2026-04-03T15:26:03Z', '2026-04-03T15:26:03Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('a02b2dfe-08de-4bb1-9de0-f782ccd90a32', 'f4c40307-9b5e-4263-a4e0-dfa138131e7f', 20, 'Furry Red Monster Parade', 'It''s hard for Elmo to have a Red Furry Monster Parade when he''s the only red furry monster on SESAME STREET, and so his friends decide to join in. The only problem is the more friends who want to join, the longer the parade name is going to get. How will the gang have a parade that includes everyone without the name of it becoming impossible to remember?', NULL, NULL, NULL, '2026-04-03T17:36:27Z', '2026-04-03T17:36:27Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('a0307f91-98c3-4a1b-a38d-dd1c6667ba50', '1d39506b-06b8-4f93-9136-0208069bd7e4', 5, 'Hot Off the Press', 'Bethenny discovers she''s the focus of a gossip article and comes to suspect that Jill was the source. Meanwhile, Kelly participates in an interview for her Playboy spread; Alex selects designers for a Brooklyn fashion event; Kelly receives an e-mail warning regarding Jill; and Bethenny attempts to call a truce with Jill.', '2010-04-01', 43, '/yYqwGa2BdRaT2k54JR9PRpxqI4M.jpg', '2026-04-03T16:35:22Z', '2026-04-03T16:35:22Z');
