INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('a041518b-8903-4fe2-89f8-94b09c590702', 'ecb64ef3-4f80-45a7-b4a9-c04434b02e35', 46, 'Daddy''s Girl', 'Get tagged with the Pawn Stars when artwork from graffiti sensation Keith Haring comes into the shop. Will this street art draw Rick''s attention or will he not get the picture? Then, Chumlee gets called to the front lines when a Civil War utility tool charges in. Can he take command of the negotiation or will he be forced to surrender? And later, when Rick takes his daughter car shopping, he''s forced to deal with used car salesman - and shop regular - Davey. Can Rick steer clear of a bad buy or will he get stuck with a lemon?', '2014-06-05', 21, '/jVy2O71FVuTpenELMGAWUJGB3qf.jpg', '2026-04-03T16:34:19Z', '2026-04-03T16:34:19Z');
