INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('a08e5736-26db-4513-a2af-8a8c39c80f5e', 'c6d5cf79-f2b0-40af-ad12-91aa4f1b1d21', 12, 'Samurai, Stones and Skateboards', 'Rick rocks out when a seller brings in a blazer worn by the Rolling Stones'' Keith Richards. Can he get some satisfaction, or will he exile the jacket? Then, Chum brings out his inner warrior when a Japanese samurai mask hits the counter. Will he be able to scare up a good price? Meanwhile, Corey tries to paint a picture-perfect deal when a Norman Rockwell autograph comes into the shop. And later, Rick and Chum head to the range to see a big game gun. Will the duo land this huge deal?', '2022-10-26', 41, '/n20IVHMa7ZYsLeDvys4qMqGuZ2d.jpg', '2026-04-03T16:34:23Z', '2026-04-03T16:34:23Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('a09116de-6992-4828-b1e4-420594f4fd18', '5c4e51c6-e207-46ad-875c-72988eb1e13e', 9, 'Spidey Cents', 'The Pawn Stars call Houston with a problem when they are presented with a piece of the heat shield from NASA''s most heroic flight - Apollo 13. Can the team complete their mission and return to profit, or will the price send them spinning out of orbit? Corey and Chumlee hit the dirt when a seller brings them a classic 1973 Husqvarna enduro motorcycle. Will they pay up to fuel the deal or will an unseen engine problem cause the deal sputter out? Rick and Corey are drawn into a web of intrigue when a customer brings in some original artwork from the comic book "Spider Man." Will the guys find they have the super powers to stick this deal or will their spidey sense tell them to let this one go?', '2011-05-02', 21, NULL, '2026-04-03T16:34:16Z', '2026-04-03T16:34:16Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('a095d836-e6d0-4854-b658-5fe6be0cb5ce', '573a556e-ed20-4222-a12d-b1b7779e1b18', 11, 'Wild River of Africa', 'The Luangwa River in Zambia includes hippoes, Nile crocodiles and monitor lizards among its residents. Steve witnesses a crocodile feeding frenzy.', '2000-06-19', 44, NULL, '2026-04-03T17:39:11Z', '2026-04-03T17:39:11Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('a0982386-949d-4441-a310-f3cde09bd894', 'c7ffc8df-4671-47e3-a11b-606828bcb508', 12, 'End Times', 'Hank pushes Gomez to pursue one last lead, while Walt struggles to protect the family. Jesse gets alarming news and rushes to meet with Mr. White.', '2011-10-02', 46, '/ffIjlpJndsel3FkPMpHCnpJ71lw.jpg', '2026-04-03T15:40:34Z', '2026-04-03T15:40:34Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('a09e2ae6-f777-4b26-bd86-06d4f95b9c42', '573fa62f-55a9-4f17-97cc-d1a005a83cc8', 4, 'Jam Session Jam Up', 'At the Sesame Street Jazz Festival, Elmo and Zoe learn to improvise, listen to each other play, and take turns.', '2025-02-06', 26, '/uTpTvuxZ1NZ4qclpIm6WA6M1VBR.jpg', '2026-04-03T17:36:52Z', '2026-04-03T17:36:52Z');
