INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('a0b241ec-91c5-4002-b298-7e177636fac5', '0f64bf9f-8d05-4f5b-9a57-5d0c44ac3f40', 8, 'Robyn''s Big Announcement', 'This is a big week! The adoption of Robyn’s kids is coming to a head as the Browns sign official paperwork with their lawyer. Only one thing stands in their way now... a judge.', '2015-10-18', NULL, NULL, '2026-04-03T16:34:29Z', '2026-04-03T16:34:29Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('a0b305c4-df4d-4e20-99ae-3b4c2d1eda03', '56428e5e-7daa-468d-8bd2-076956507aa8', 12, 'Balance', 'Bill Nye''s going to use the force to pull you into the world of balance. A force is a push or a pull. You can feel a force when someone pushes you. You can use a force to pull a door shut. Anyone can make forces by pushing and pulling, and you don''t need to be Luke Skywalker to use a force. In a game of tug-of-war, if the pull of your team is the same as the pull of the other team, the forces are equal. The two teams are in balance, and the rope doesn''t budge. Things are in balance when forces that are pushing or pulling them are equal. If your tug-of-war team pulls harder than the other team, the forces are not equal. The other team falls all over the place. Unequal forces make things move and twist. A lot of things are designed to take advantage of unequal forces. Wrenches, screwdrivers, door handles, and water faucets use forces made by you to do work. A well-balanced science diet starts with Bill Nye.', '1994-10-15', 26, '/A88ei6AbSPm2Y7AnDCb3bs2XN8I.jpg', '2026-04-03T17:37:21Z', '2026-04-03T17:37:21Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('a0b3aadb-66cc-44ba-8c95-e35caa05e843', 'f829d1fb-64ea-430f-8e0e-b3345653a542', 6, 'They Shoot Crocodiles, Don''t They?', 'Steve gives the viewers a look at the seven cameramen who have captured his encounters with wildlife over the years.', '2003-08-19', 44, NULL, '2026-04-03T17:39:12Z', '2026-04-03T17:39:12Z');
