INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('a0f88381-7e96-40b2-8e72-3bd6c9b36c24', 'f4c40307-9b5e-4263-a4e0-dfa138131e7f', 70, 'Elmo and the Bookaneers', 'Everyone loves to read even pirates! The Bookaneers, led by Tina Fey, have come ashore on Sesame Street, and they want to plunder Elmo s bookshelf. When Elmo finds out how much they love to read, he can t wait to become a bookaneer himself. Can he pass the test and help them find their treasure? Bert and Ernie are also on the hunt for treasure in an episode from the fantastic new claymation series Bert and Ernie s Adventures. Plus, you can sing along with Abby in a song about something she treasures: words! In Elmo s World: Books, Elmo invites you to learn all about the books he treasures. Arrr you ready for a reading adventure?', '2009-04-21', NULL, NULL, '2026-04-03T17:36:27Z', '2026-04-03T17:36:27Z');
