INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('a1022ab5-28cc-4d5d-b920-ac5ca150f510', '23c93536-610c-41c5-ac6b-a6b243423258', 3, 'Momma Knows Best', 'Shocked by the dramatic GnA ousting, the group seeks answers and apologies. Keiarna settles in at her boyfriend''s house. Mia and Inc have a staycation to get some space of their own. Stacey''s close friend TJ comes to town. Gizelle attempts to make amends with the ladies before an upcoming trip, with surprising results.', '2024-10-20', 43, NULL, '2026-04-03T16:35:41Z', '2026-04-03T16:35:41Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('a1085153-cb1a-4b37-9eeb-39cfa8b9e95d', 'c73fa7f1-7ac6-44d4-ac1f-182a70d92313', 6, 'New Dog on the Block', 'Sarah is trying to train Nipper to high-five on command. But when she isn’t paying attention, Nipper wanders off and sparks an oven fire with his paw!', '2021-10-07', 10, '/aBSV5Np0xS9DQpTZenxZJ5j1x4W.jpg', '2026-04-03T17:14:41Z', '2026-04-03T17:14:41Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('a1086ead-b45a-42db-840d-9caf56917f30', '6f731e6b-d3c5-4de6-84e1-7a19cb650e86', 4, 'Godfather of Pawn', 'Feel good with the Pawn Stars when a James Brown suit dances into the shop. Will Rick be saying, "please, please, please" for the Godfather of Soul''s wardrobe or will it be too funky? Then, it''s a game of cat and mouse when Corey and Chum check out an artist proof from the film "Anchors Aweigh." Will the deal set sail or will they be left out at sea? Next, Rick feels exposed when a controversial 1917 Standing Liberty Quarter circulates the shop. Will he be in the money or will the deal not make sense? And later, Chum butters up to a 1920s popcorn maker. Will he make a concession and settle on a price or will the deal go stale?', '2015-10-29', 21, '/hllX5cFmMKk9566ZXS780DVcZYs.jpg', '2026-04-03T16:34:20Z', '2026-04-03T16:34:20Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('a108ff47-bab2-4264-a74e-6a12758561d0', 'ba33491a-8f19-4e61-ae9f-0a67db3c65b0', 10, 'Cleaning Up the Mess', 'The ladies return to Potomac and get back to business; Gizelle and Robyn prepare for their "Reasonably Shady" live show; Karen prepares for a live experience of her own; Ashley gets emotional about her separation with Michael; Gizelle hosts a party.', '2022-12-11', 44, '/wX0UwE87HHMgXSGIWZzErgYpKce.jpg', '2026-04-03T16:35:40Z', '2026-04-03T16:35:40Z');
