INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('a11852d8-9618-4ac5-9b18-3f1c37036f58', '05c0e384-194c-4417-9f62-803eb615e409', 72, 'Stop litterbugs', 'Title number 0072. Opens with Mister Rogers arriving with plant food and talks about how plants and people grow. Judy Ruben shows crafts that kids made with recycled containers. In the Neighborhood of Make-Believe, King Friday and Handyman Negri start a campaign against littering and they learn that everyone is interested in cleaning up the environment.', '1968-05-28', 29, NULL, '2026-04-03T17:35:38Z', '2026-04-03T17:35:38Z');
