INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('a11e4239-1bb0-4120-85fb-8b88b36422ab', '1d39506b-06b8-4f93-9136-0208069bd7e4', 13, 'Shunburn', 'The ladies'' Virgin Islands getaway continues---but it''s not a stunning development when Kelly departs the resort in the middle of the night. Before long, unexpected guests arrive at the island, and a warm welcome does not await them. Back in the Big Apple, Jill tries to reconcile with Ramona and Bethenny.', '2010-05-27', 43, '/aiLpkmnq1QtXBPyylOSrYzSRtIw.jpg', '2026-04-03T16:35:22Z', '2026-04-03T16:35:22Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('a11f6c01-b54a-4beb-a869-3cd7c1f34332', 'd5383b3d-5636-4d71-b99c-b84774b4b3c6', 23, 'Pingu Helps Grandfather', 'Pingu’s family are all at home. Pingu is reading a comic, Pinga is playing doctors, with her teddy as the patient, Father is reading the paper and Mother is knitting. The phone rings. Father answers. It’s Grandfather, who’s had a fall putting up a picture and broken his foot! When Father has rung off and told the family what has happened to Grandfather, he and Mother have a discussion. Pingu goes and sits on the motorised sled, ready to go. The discussion shows no sign of ending, so Pingu calls out to hurry them up. They briefly stop talking, and then resume. Pingu is fed up with waiting, so he gets off the sled and starts walking to Grandfather’s house, muttering to himself. Father gets onto the sled and calls to Mother and Pinga. They come, and then Mother says she’s forgotten something and goes back in to get it. She returns wearing her floral hat. Father moans about the delay, but then Pinga also says she’s forgotten something and goes to get it, coming back carrying her doctor’s bag. Mother and Pinga get on the sled and Father asks if they’re ready to go. They both nod, but then Father can’t start the sled! He also goes back inside and returns, sheepishly showing Mother and Pinga the sled starter key, which he’d forgotten. Mother and Pinga both laugh, and they all set off on the sled. By now Pingu has reached Grandfather’s house. He enters, and commiserates with Grandfather. He then sees the smashed picture on the floor and the stilts, one broken, that Grandfather was using to get high enough, and has an idea. He splints Grandfathers foot using the broken stilt, tying it on with some cloth. Father, Mother and Pinga arrive. Pinga rushes in to help and is surprised to find Grandfather standing, with his foot splinted and using the unbroken stilt as a crutch. They take Grandfather to the hospital. A doctor takes Grandfather inside to be treated, while the others wait outside. Pingu brushes away a tear as Grandfather goes in, and is consoled by Mother. Grandfather then comes out in a wheelchair, with his foot and the broken stilt both neatly bandaged up. Grandfather gives the stilts to Pingu, who gets on them and walks around, to everyone’s amusement.', '2000-03-04', 5, '/6xWiCrra6eucuFb9hcQyu8B0S6D.jpg', '2026-04-03T17:22:20Z', '2026-04-03T17:22:20Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('a1242afd-c05e-4220-81d7-47ce4bab0a41', '01916834-25ec-43d6-9a1b-8ea5d9630adc', 11, 'Power Cut', 'With the Farmer away, Shaun and the flock have fun - but a power outage causes chaos.', '2025-06-09', 7, '/c5doxbIs46wfxAIfxMWLH0AsyMs.jpg', '2026-04-03T17:39:33Z', '2026-04-03T17:39:33Z');
