INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('a14cc76c-cc6a-495b-9534-247cd3c2eab4', '3af7ea64-fa13-4097-b8e4-40af07083054', 28, 'Water Flowing and Stopping Pt 3', 'Rogers talks of turning things on and off, such as a flashlight and a water faucet. Later he goes to Elsie Neal''s Craft Shop where two people are making a papier-mâché tunnel. The Neighborhood of Make-Believe witnesses a fire at Henrietta''s house. Prince Tuesday lets Handyman Negri use his squirt bottle to put it out.', '1974-03-27', 28, NULL, '2026-04-03T17:35:40Z', '2026-04-03T17:35:40Z');
