INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('a16e10d9-b3d1-439b-829f-1557773c72b1', '78a02d50-e3dc-4549-844a-3cf357a32ef4', 17, 'Aloha and Goodbye', 'After Phaedra''s attempt to reunite the group fails, Kandi and Todd decide to bring everyone together for a roast of Peter. Shereé is forced to decide if she should move forward with or without Bob, while Cynthia and Peter come to terms with the end of their marriage. Meanwhile, Kenya and Phaedra''s newfound friendship is put to the test as Kenya hosts a party that has Phaedra feeling seasick on dry land.', '2017-03-19', 43, '/uXTclP4dfPerxw9EqGJ5WUq23rY.jpg', '2026-04-03T16:34:48Z', '2026-04-03T16:34:48Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('a17ebfea-6ef2-43ef-8604-040077eb6a97', '4d2cac0f-38fd-438b-8afa-acf43952e535', 19, 'Episode 19', 'Toys, model railways, games, stories, cartoons. A weekly programme for younger viewers with Christopher Trace and Leila Williams.', '1959-02-19', NULL, NULL, '2026-04-03T17:21:47Z', '2026-04-03T17:21:47Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('a17f1658-2dbc-463b-b1fd-6086ab10ab31', '45e01c04-6ac6-41e1-87d8-f749ee230385', 13, 'Sheepdog Trials', 'Norman Price practices his new career as a shepherd by rounding up Woolly with Radar. However, Woolly and her lamb run into the road and make Mike Flood''s van tip over. Firefighter Cridlington and Station Officer Steele get the hiccups.', '2008-02-25', 10, '/mAHg8LVPiMIl4T4tVOZAfY8KmzP.jpg', '2026-04-03T17:14:38Z', '2026-04-03T17:14:38Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('a188d683-cd2b-46d4-9024-80b422a0acdf', '2e8b61b6-6179-4204-9d2b-c12300836fc8', 10, 'Oakie Doke and the Helpful Mouse', 'The Corncrackers are helping get a surprise party ready for Rose. Root doesn''t turn out to be very useful - until Oakie Doke shows up. Together, they gather flowers, groundling berries and jam tarts (with the help of Root''s tail).', '1997-08-26', 10, NULL, '2026-04-03T17:19:25Z', '2026-04-03T17:19:25Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('a18b9947-6a0e-4dc1-b308-78558278d650', 'f4938e7d-11a8-4756-b405-98bedd7c9b28', 11, 'Pat Goes Sledging', 'Heavy snow has fallen in Greendale and Peter has to clear the roads with his tractor and bulldozer blade. When Pat calls to see Mrs Pottage, everyone has to help dig the snow away but it eventually becomes so bad that Peter has to turn back. When Pat arrives at Thompson Ground, Pat and Alf go on a sledge to deliver a parcel and some groceries to George at Hill Top Farm.', '1981-11-25', 15, '/f5lrOocA0aNMzgI3mAjwV6xnLQn.jpg', '2026-04-03T17:14:29Z', '2026-04-03T17:14:29Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('a18d4e1d-3752-426d-b0df-2c843a489fe6', '301fb913-4e76-408f-b84b-05bf979766fe', 13, 'The Seven', 'Kramer demands compensation from Elaine for his chiropractic effort; Jerry''s flame always wears the same outfit.', '1996-02-01', 22, '/fjOYCiLe7Fg9KT49JKeTrIgVOxd.jpg', '2026-04-03T16:34:11Z', '2026-04-03T16:34:11Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('a190f338-0d2d-4f2b-96da-f5b1d3328331', '05c0e384-194c-4417-9f62-803eb615e409', 71, 'Taking care of your teeth', 'Title number 0071. Opens with Mister Rogers arriving with a toothbrush, tooth paste, and tooth powder. He brushes his teeth and shows a film of his dental checkup. In the Neighborhood of Make-Believe, Mr. McFeely brings Donkey Hodie some mouthwash. Sara Saturday hosts a dance recital at the castle where the dancers dance to the stories told by Donkey Hodie and King Friday, and Sara Saturday.', '1968-05-27', 29, NULL, '2026-04-03T17:35:38Z', '2026-04-03T17:35:38Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('a192dcc8-f548-46d8-8eb5-f20193c54c33', 'fb4ecc73-cb92-4c5c-821f-92179058b37b', 33, 'Telly starts a doo-wop group (3688)', '', '1997-12-31', NULL, NULL, '2026-04-03T17:36:41Z', '2026-04-03T17:36:41Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('a194dfd6-d90a-4b2f-9b26-01fab8a48e1f', '5a6d9a42-165b-4b56-9273-0a06874dfe10', 8, 'Madeline and the Dog Show', 'Even though she outperforms the competition, Genevieve is disqualified from a dog show because she is not a purebred. But after she rescues the Mayor''s dog, the judges change their tune.', '1993-09-19', 30, NULL, '2026-04-03T16:34:01Z', '2026-04-03T16:34:01Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('a1a029d8-1264-4faa-ab6d-60ca0c108345', 'f4c40307-9b5e-4263-a4e0-dfa138131e7f', 89, 'Elmo''s Potty Time', 'Join Elmo as he reminisces about his potty training journey and guides viewers as they embark on theirs. Elmo and his Sesame friends give helpful, confidence-building tips and encourage kids to listen to their bodies. Dance, sing and laugh along as kids learn healthy habits that will last a lifetime.', '2008-10-06', NULL, NULL, '2026-04-03T17:36:27Z', '2026-04-03T17:36:27Z');
