INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('a1b3cbc1-82a2-4769-bfca-01e22fcf38a3', '7bc54df3-f32a-454e-aef6-a9436c35d53b', 51, 'Episode 51', 'Gifts have been pouring in for the imminent birth of Queen Sara''s baby. One of them is a paper crown, which Henrietta takes without asking.', '1970-04-13', NULL, NULL, '2026-04-03T17:35:39Z', '2026-04-03T17:35:39Z');
