INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('a2177142-3359-43fa-b744-a911bfc47c3e', '05c0e384-194c-4417-9f62-803eb615e409', 60, 'Joey Hollingsworth’s dance recital', 'Title number 0060. Opens with Mister Rogers arriving with a marionette. Mr. Rogers demonstrates using a clown marionette and a dance recital by Joey Hollingsworth is prepared in the Neighborhood of Make-Believe. Daniel and Lady Aberlin play a clapping game. It is at the request of Sara Saturday that the recital is planned. King Friday tries to blunt the dance recital by forbidding applause and moving the start time forward, as he tries to woo Sara Saturday.', '1968-05-10', 29, NULL, '2026-04-03T17:35:38Z', '2026-04-03T17:35:38Z');
