INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('a27b06d4-b0cc-4622-91f4-e398978133e0', '4b4d327b-6c8b-459c-9e73-b1d4d84aed77', 7, 'Trick or Treat', 'Brother Bear & Sister Bear celebrate Halloween.', '2003-09-24', NULL, NULL, '2026-04-03T17:40:22Z', '2026-04-03T17:40:22Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('a27bd1bf-6ad7-4b17-93bf-c1a01a5504f0', '18da9943-1963-4e04-a7a0-ae63802bb1fa', 6, 'Rumors', 'The ladies are surprised to learn how the poker night ended, leaving Gina and Emily at odds. Vicki travels to L.A. to record radio commercials for Coto Financial and ends up embarrassing her son Michael in the process. Shannon gets emotional as she goes to court as part of her divorce. Her good friend Tamra surprises Shannon with the gift of a matchmaker, while Kelly dates the “milkman.” After Emily leaves a happy hour early, the other women start to speculate about her marriage.', '2018-08-20', 44, NULL, '2026-04-03T16:35:34Z', '2026-04-03T16:35:34Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('a27bd2c4-551a-4a91-8e23-e34dc6761ddc', '34674c90-410e-427c-be4d-2a6f6f865a80', 3, 'Wild Thing', 'Soar to new heights with the Pawn Stars when an A6 Texan fighter plane buzzes the tower. Actually flown during WWII, will the guys try to land this ultimate piece of war machinery or will they think the whole idea is just plane crazy? Then, a 1974 VW Thing cruises by. The same model as Rick''s first car, will his nostalgia trigger an offer, or will this trip down memory lane turn into a nightmare? And later, a guy brings in his collection of Civil War-era cannon balls. Will Rick and Chumlee shoot for the moon over these cast iron weapons or will their offer be way off target?', '2012-04-16', 21, NULL, '2026-04-03T16:34:17Z', '2026-04-03T16:34:17Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('a2838073-3a09-4d9d-9442-1f8ec3804667', 'de8ec769-16bb-436b-be43-aedc7e18a7d7', 34, 'Fourth of July Celebration', 'It''s July Fourth on Sesame Street! Elmo, Abby Cadabby, and Rudy look for the perfect birthday present for America, but Alan teaches them that holidays are really about spending time with family and friends. Together, they do something kind for all their neighbors.', '2020-07-04', NULL, '/2eLN4SWOswiuNVNv3WRdGBDXIVc.jpg', '2026-04-03T17:36:50Z', '2026-04-03T17:36:50Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('a2857413-8e9c-4332-b1f3-bc1b383852ef', '208e80de-61e3-4a2f-857f-c667ffc29134', 22, 'Andy Williams', 'Miss Piggy asks Andy to sing "Love Story" for her and Kermit, who have just become engaged. Unfortunately, Kermit hasn''t heard about the engagement yet. The rumor slips out, and soon everyone thinks Kermit and Piggy are getting married.', '1980-03-21', 26, '/hbPVfryON6THJmwwpi7jV3GE6FC.jpg', '2026-04-03T17:35:25Z', '2026-04-03T17:35:25Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('a285c56b-699e-4a91-94f0-90626c65ac54', 'bf874be3-7e2f-4a0e-b205-c76ac1ad69fc', 145, 'The Last Lap', 'Comments from the cast and crew of Seinfeld look at the decision to end the series after Season Nine. It gauges reactions to that choice and also gets into the creation of “The Finale” as well as attempts to keep it a secret. We also hear reactions to the episode.', NULL, 22, NULL, '2026-04-03T16:34:09Z', '2026-04-03T16:34:09Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('a28694db-99f2-4038-bb18-491c84b47df5', 'd1863f2f-02ec-40ce-af64-db03fbe518a7', 4, 'Saved by Superfoods', 'The SuperFood Super Foods fly onto Sesame Street to help their friends try new foods, find a healthy snack, and explain the importance of eating breakfast. Also featuring Orange is the New Snack parody, and Elmo the Musical-Tomato. Brought to you by the letter H and the number 10.', '2016-01-30', NULL, '/8tezJGjD4uqVaaSPiETNtRXTArJ.jpg', '2026-04-03T17:36:48Z', '2026-04-03T17:36:48Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('a28b5f52-43d4-42d1-904c-7fe3e010983a', '7c0e1f66-8835-4e8a-8ad9-0eee57155b4c', 18, 'An Interview with M. Night Shyamalan', 'The creators of Avatar: The Last Airbender, Bryan Konietzko and Mike Di Martino, interview the director of the motion picture M. Night Shyamalan.', NULL, 11, NULL, '2026-04-03T17:40:47Z', '2026-04-03T17:40:47Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('a29068a9-f1ad-475c-8ba6-623abe26de85', '3ee646e8-23ae-4dec-bbc6-c7e6a210d55b', 125, 'City-wide water shortage', 'Gordon, Telly, Big Bird, and Mr. Handford see the latest newspaper headline in Hooper''s Store - "WATER SHORTAGE IN CITY." Mr. Handford turns on the TV to see if there''s anything in the news about it.

Sponsors: R, W, 15', '1991-05-03', NULL, NULL, '2026-04-03T17:36:38Z', '2026-04-03T17:36:38Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('a290e46c-744a-4634-a30a-b3afb1e5348a', '3430d881-14a2-497d-9cf4-351b78b6aa6a', 10, 'Postman Pat and the Robot', 'Ted invents a new robot postman to help give Pat a rest. When it goes out for its test run and arrives at the Post Office, it scares Mrs Goggins. When it gets loaded with post, it causes havoc over Greendale. Pat and Ted follow after the robot in Pat''s bus.', '1997-06-05', 15, '/mC91yuoKlXT4JHziXi7WPv2Txeq.jpg', '2026-04-03T17:14:30Z', '2026-04-03T17:14:30Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('a29134b3-9816-4f74-a1d4-7e11895a080f', 'e93f04c2-7344-4b93-abba-8ba1b2f8eb35', 52, 'Episode 587', '', NULL, NULL, NULL, '2026-04-03T17:36:30Z', '2026-04-03T17:36:30Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('a297e523-daa0-414d-b72a-a890540ba91d', 'c7ffc8df-4671-47e3-a11b-606828bcb508', 4, 'Bullet Points', 'The Cartel takes steps to gain the upper hand. Walt and Skyler share an embarrassing secret with the rest of the family. Jesse''s activities draw unwanted attention.', '2011-08-07', 46, '/gzHp77NjrkDOu9sgkLB5PYmwArK.jpg', '2026-04-03T15:40:34Z', '2026-04-03T15:40:34Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('a299be18-c40c-4710-a7b8-458faa621c80', 'd1d267dd-e27f-4543-acb8-0d28f676512a', 6, 'Episode 6', 'with Valerie Singleton and John Noakes', '1967-10-16', NULL, NULL, '2026-04-03T17:21:49Z', '2026-04-03T17:21:49Z');
