INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('a2aab60b-a903-45af-91e6-76661a7a232a', 'bc1b58b0-f2d6-4214-914b-231f27fb4d61', 6, 'Whine and Dine', 'Caroline takes to the airwaves with her new radio show. Meanwhile, the Gorga siblings attempt to settle their differences, but they invariably stir up more tension; and Jacqueline plays referee in a face-off between Teresa and Melissa.', '2011-06-19', 43, '/sxlcZOZQOsmRpCPs4gcHqugKyoB.jpg', '2026-04-03T16:35:15Z', '2026-04-03T16:35:15Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('a2acf6ec-6d3e-4cc7-854f-4bd7a1527c60', 'eb7e3bb4-5746-4577-81c6-f5b2dc2efc6e', 13, 'The Drill', 'Having made it to the outer wall of Ba Sing Se, the kids confront a Fire Nation army that is driving a massive Fire Nation drill, which poses an imminent threat to the last Earth Kingdom stronghold. Meanwhile, Zuko and Iroh make crucial mistakes which begin to attract Jet''s suspicions.', '2006-09-15', 25, '/oinuOajlGzfwvcpmXyPE15IwfTL.jpg', '2026-04-03T17:40:48Z', '2026-04-03T17:40:48Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('a2b0e44a-c047-4712-9b65-d45bcda858fc', '9193e795-da7c-40ec-b68f-f63aa7d5174f', 97, 'Histories & Lore: The Alchemists'' Guild', 'Wisdom Hallyne provides an account of the Alchemist Guild (or Pyromancers), detailing their knowledge of wildfire and how their once great influence in Westeros has faded over the years.', '2013-02-19', 4, '/5UglF9P2MfPGBuNNX6PKIMg5aze.jpg', '2026-04-03T15:40:35Z', '2026-04-03T15:40:35Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('a2b1bb06-385e-4461-9d51-209eeda8b7a4', '684af21e-0459-4832-b094-db0997e354c5', 14, 'Surrounded By Hot Water', 'Karent debates whether to confront Rodolfo about the article. Meanwhile, Lea and Marysol ruin a special dinner by finally hashing out their issues.', '2012-12-13', 44, '/a8OQnkfGxBm8thibcfs7rkM4r9q.jpg', '2026-04-03T16:35:10Z', '2026-04-03T16:35:10Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('a2b28b63-3a8c-4ff9-bc8e-c519bf450e2c', '2990012c-38f6-4051-84a5-4ec6da711d80', 7, 'Tiger''s Sled', 'Tiger gets a new sledge, so Kipper and Tiger go for a ride.', '1999-03-04', 30, NULL, '2026-04-03T17:10:48Z', '2026-04-03T17:10:48Z');
