INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('a2d1b3bf-ff4f-4be0-b075-4344dafddf28', 'f4c40307-9b5e-4263-a4e0-dfa138131e7f', 113, 'A Sesame Street Christmas Carol', 'Oscar the Grouch is visited by three ghosts in an attempt to teach him the true meaning of Christmas.', '2006-11-01', NULL, NULL, '2026-04-03T17:36:27Z', '2026-04-03T17:36:27Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('a2d442de-368f-4a66-9588-aba939d0922c', '1be79a20-de33-41d1-af17-079035b18d5c', 121, 'Treasure Hunt', '', '1970-04-27', NULL, NULL, '2026-04-03T17:36:28Z', '2026-04-03T17:36:28Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('a2d4c8af-2692-4dad-ae9c-a8f583a8d6fd', '80775c3d-fa41-46f6-96ec-efc2e14efdcf', 19, 'New Beginnings, My Ass', 'Sonja''s fashion-week debut gets great press coverage thanks to Bethenny and Ramona''s front-row ruckus; Dorinda and John meet for lunch where he seeks to take their relationship to the next level; conflicts arise at Ramona''s New Beginnings party.', '2015-08-11', 60, NULL, '2026-04-03T16:35:24Z', '2026-04-03T16:35:24Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('a2d85f8f-0c78-4cc3-b656-25917a08b054', 'df895a8e-db4c-48d1-bf84-9a6a650583dc', 11, 'Follow the Bouncing Ball', 'When Alberto and Francine accidentally exchange soccer balls in the park, Alberto''s ball travels with Francine throughout Elwood City and, eventually, the world.', '2011-04-22', 13, NULL, '2026-04-03T17:38:00Z', '2026-04-03T17:38:00Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('a2d9250c-5c68-452e-8b3a-636bcdb9ae5d', '6d2b78d7-2612-4afb-81ca-dee774af9c2b', 7, 'Dance', 'Rogers goes to one of the SeaWorld theme parks to see the killer whales, Shamu and Namu, dance with the spectators. In the Neighborhood of Make-Believe, Lady Elaine sets up a dance studio and invites only the females, because she knows that men don''t dance.', '1987-05-11', NULL, NULL, '2026-04-03T17:35:44Z', '2026-04-03T17:35:44Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('a2dea7d9-f71f-4487-8100-366ab569f66a', '319bd5d6-ff58-426f-b9da-a0bb2cb87b02', 14, 'Erosion', 'Dirt, sand, and rock from the Earth’s surface gets blown, sliced, torn, swallowed and distributed all over the world. What was yesterday’s hill is tomorrow’s flat plain. The planet looks a lot different than it did when it formed four and a half billion years ago. The force of erosion, the slow wearing away of the land, has never ceased.', '1998-05-09', 26, '/y9jaKIXRwtnjel0nVTDT14MqWb2.jpg', '2026-04-03T17:37:22Z', '2026-04-03T17:37:22Z');
