INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('a2e7bf32-851b-46af-ae69-b3b1610a9078', '21745b85-d269-42fa-b4dd-701b2da5c085', 59, 'Episode 59', 'Hannah, the labrador bought by Blue Peter viewers with a silver paper collection, and her latest litter of six puppies (one of them is shown here) - plus Bonnie the Kennel cat. The pups make their debut today.', '1974-04-04', NULL, NULL, '2026-04-03T17:21:51Z', '2026-04-03T17:21:51Z');
