INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('a34dd2df-2d5f-413e-bfd1-8cba7bb5c0a5', '3269a890-bba9-4e6c-9278-f7eb38eb1720', 10, 'Climates', 'There are lots of different climates all over the world. Deserts are warm and dry. Temperate forests are cold and wet. Tropical rain forests are warm and wet. Animals and plants live in climates that are good places for them to live. Cacti wouldn’t grow too well in the Arctic, just like polar bears would over heat in the desert.', '1995-04-14', 26, '/qfQE7A7k2Hb8x9JBfxNMWufWuub.jpg', '2026-04-03T17:37:21Z', '2026-04-03T17:37:21Z');
