INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('a38c173d-f675-4c17-9f9e-54dcfad79dfa', '61e0c9d9-337e-4fe4-a0fd-e567b29af115', 14, 'La VIDA Loca', 'The Mexico trip continues as the ladies set sail on a yacht excursion. Lisa updates the group on life with John and Henry. Britani takes offense at the lack of enthusiasm over her latest announcement. Bronwyn reveals some dark truths about her marriage and is surprised by Heather''s grace and Lisa''s lack of support. Mary arrives and the ladies come together for a beautiful VIDA dinner where Meredith learns her late-night antics have fueled Britani with fresh gossip. Angie and Bronwyn confront Lisa at dinner, causing a dramatic conclusion to the evening.', '2024-12-18', 43, '/jcqNeueUPOa3DITQ5Q6exOUMRHx.jpg', '2026-04-03T16:35:45Z', '2026-04-03T16:35:45Z');
