INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('a38e8e2e-70a8-4ca8-b025-51d4ca163750', '6d2b78d7-2612-4afb-81ca-dee774af9c2b', 5, 'Playthings', 'Rogers shows a videotape of his visit to Lucy, who is a fake wooden elephant on the Jersey coast. He also takes viewers to the toy-lending library. In the Neighborhood of Make-Believe, Lady Elaine finally opens the door to the locked room in the Museum-Go-Round. But all what they find is left to their imagination.', '1986-11-28', NULL, NULL, '2026-04-03T17:35:44Z', '2026-04-03T17:35:44Z');
