INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('a4ad8105-682d-48cf-b89f-416ccb5deb89', 'f4c40307-9b5e-4263-a4e0-dfa138131e7f', 112, 'Being Green', 'Mr. Earth (Paul Rudd) hosts Sesame Street''s first "Earth-a-Thon." Abby, in an attempt to help Elmo be more "green," accidentally turns him the color green. When Abby has a hard time turning back, he begins to sing "It''s Not Easy Being Green," until Mr. Earth convinces him that "It Can Be Easy Being Green."

Telly, Rosita and Cookie Monster are volunteers standing by the pledge phones. After several hours, Cookie Monster can''t bear not having eaten any cookies while taking calls, and eats his phone instead. As the 24-hour Earth-a-Thon comes to a close, Elmo and Abby have learned lots of different ways to "be green."', '2009-08-08', NULL, NULL, '2026-04-03T17:36:27Z', '2026-04-03T17:36:27Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('a4af70ad-90ca-4fe0-94a1-e8199f0dc47b', '1f34e241-4c1d-4586-921a-1c5aeb1fbbaa', 32, 'Episode 2127', '"Explorer Jones" and the kids pretend to be explorers. They''re looking for the alphabet, but Forgetful doesn''t know what it looks like. After identifying it as Maria''s hot plate and Bob''s shovel, he finds it in the direction of the viewer.

Sponsors: F, H, 10', '1985-12-31', NULL, NULL, '2026-04-03T17:36:36Z', '2026-04-03T17:36:36Z');
