INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('a4c5f6ec-ae5c-4bd0-ade3-5c1aabb3589f', '9310a288-5af0-4746-a8d7-d7635ffb6beb', 6, 'Work', 'Mister Rogers arrives with a letter he received from Mr. William Bolger, the Postmaster General of the United States. Showing the postage stamps, Mister Rogers explains that it costs money to send mail and invites viewers along as he visits Mr. Bolger to see how stamps are made.

At Mr. Bolger''s office, Mister Rogers talks to him about being the Postmaster General and his interest in the postal service. Mister Rogers is then introduced to Gordon Morison and Clarence Holbert who show him how stamps are made. Mr. Holbert shows how they are designed and Mr. Morison shows how they are printed.', '1984-04-04', NULL, NULL, '2026-04-03T17:35:43Z', '2026-04-03T17:35:43Z');
