INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('a4ea4304-a676-4976-9e22-7390b378d4b5', '3af7ea64-fa13-4097-b8e4-40af07083054', 1, 'Painting The Walls [1326]', 'In this episode Mister Rogers paints the walls of the television house blue. From Seasons 2-3 the walls of the television house were painted yellow with the brown wooden bottom panels. From Seasons 4-6 The walls of the television house were painted a brighter yellow but more of a tan color and the brown wooden bottom panels were removed from the walls. Parts of the kitchen set were also updated. The walls of the television house would stay blue until the end of the series in 2001. Beginning with this episode Mister Rogers says "You''re alive" in a higher toned voice. This is the first episode to use what would become the show''s more-familiar neighborhood toy-like model town and it was used until the end of the series in 2001.', '1974-02-18', 28, NULL, '2026-04-03T17:35:40Z', '2026-04-03T17:35:40Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('a4ecfd84-19d9-4354-a3c0-5b7333d269ac', '5144de59-e67f-4fcf-919b-7106989ab797', 11, 'Different Drummer', 'Julie plays referee to Skye and Leon’s dispute over whose cultural drum is more significant. The two eventually agree that both drugs are significant in their own way, and neither''s is necessarily better. Sizzle takes up skateboarding.', '1995-01-30', 29, NULL, '2026-04-03T17:12:21Z', '2026-04-03T17:12:21Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('a4f19aa8-32d7-4d5a-95e8-ede471620fce', 'a79a245f-acab-4ebe-aee9-29867f9e52f6', 9, 'PolygaMexicamist Wedding Part 1', 'Mykelti''s polygamist family ties the knot with Tony''s Mexican Catholic family with a unique winter wedding where they beat bride and groom piñatas; Christine forgets to bring Kody''s shirts.', '2018-02-11', NULL, NULL, '2026-04-03T16:34:30Z', '2026-04-03T16:34:30Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('a4f1d93e-ab23-4f9d-8799-f858486a8519', '95ca8b6f-ccbc-431a-9d95-9b23367bbfed', 10, 'Affairs and Accidents', 'Kyle opens her home in La Quinta to the group for a desert getaway, but Erika cannot escape the fallout from her messy divorce. When Lisa questions certain new reports in the media, Dorit offers insights from her own experience. Sutton and Crystal connect with Erika through stories of family loss. Meanwhile, Kathy heats things up in the kitchen – and, with a little help from her friends, cools down in front of a fan.', '2021-07-21', 43, '/8jQwTmEQOP1DPY1EZTwSKoPwMgy.jpg', '2026-04-03T16:34:58Z', '2026-04-03T16:34:58Z');
