INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('a55aac26-572c-4926-9fe4-15cc72300998', 'a0fa5075-9ce1-48c1-9995-0c0fd866e549', 15, 'Trouble in Paradise', 'Kyle and Mauricio speak face-to-face for the first time since he was photographed with another woman. While Boz and her boyfriend try to strengthen their relationship, Dorit and PK try to decide whether to salvage their marriage. The women are off to Saint Lucia where Boz has planned a girl’s trip. But with tension brewing between Sutton and Dorit, will it be trouble in paradise?', '2025-03-11', 43, '/52s7Fpadg0XhDfZg6GfknpxUVvn.jpg', '2026-04-03T16:34:59Z', '2026-04-03T16:34:59Z');
