INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('a574cb51-9620-4373-ba83-3ef12ef6e719', '8c3cfac1-d882-4904-b38c-d1981628d00e', 12, 'Episode 12', '"England expects..." must be the most famous signal in naval history. Today''s programme includes two personal mementoes worn by Admiral Lord Nelson on HMS Victory when he was struck down by a French marksman at the Battle of Trafalgar.', '1978-10-19', NULL, NULL, '2026-04-03T17:21:54Z', '2026-04-03T17:21:54Z');
