INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('a58968bd-1eba-4320-b3d9-192efc8461f7', '119c16d5-1047-45ec-8242-c72a8eed423b', 19, 'Arthur''s Birthday', 'Arthur is excited about his birthday. After shopping for party supplies, he makes invitations and passes them out at school. He then finds out that Muffy is having her party on the same day, at the same time. This starts a huge battle between the boys and the girls in the Ratburn class. Fortunately, Francine and Arthur devise a great solution to the problem.', '1996-10-18', 13, NULL, '2026-04-03T17:37:55Z', '2026-04-03T17:37:55Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('a59116f3-a56b-480b-9e57-759ad7bdc9a7', '3ea743ef-0a22-47cf-b1d2-62f37e939253', 40, 'Elmo and Zoe Play "Follow the Leader"', '', '2002-03-29', NULL, NULL, '2026-04-03T17:36:43Z', '2026-04-03T17:36:43Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('a59226dd-22c8-445c-9375-19153ebbebc4', 'bf874be3-7e2f-4a0e-b205-c76ac1ad69fc', 131, 'Sein-imation: The Del Boca Vista Express', 'Sein-imation is a series of cartoons of Seinfeld episodes. They were released on the Seinfeld DVDs as special features. They used audio from a set episode placed over a new "toon".', NULL, 22, NULL, '2026-04-03T16:34:09Z', '2026-04-03T16:34:09Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('a59261f5-1007-4961-ac78-af219127bd5e', '8bae6aa3-4b55-4fa6-bc15-8f4317bd1f13', 59, 'Episode 59', 'Bob Dog is sad that Queen Sara is too busy with Prince Tuesday.', '1972-05-11', NULL, NULL, '2026-04-03T17:35:40Z', '2026-04-03T17:35:40Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('a5951d06-fa79-4e41-924f-32c5dc7928e8', '0e419615-4c96-4dde-8ed2-715770ba77bb', 19, 'The Great Bandini', 'Bear and our friends from the Big Blue House are on their way to attend a performance of the famous musician, the Great Bandini. All of them are in awe of the Bandini''s skill and on their way, they meet somebody headed to the concert --- Edwina Badger. Edwina Badger helps them all to see the musical talents that they also possess. They learn that there are all sorts of ways to make music and that the voice can be a powerful instrument. In the Shadow segment, Shadow sings a song about jazz music.', '2003-02-07', 25, NULL, '2026-04-03T17:35:32Z', '2026-04-03T17:35:32Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('a59e2766-73b8-41c3-abb4-791216c50233', 'e48599f8-66ff-4c0f-9274-65b9ae1cda9e', 38, 'Episode 38', 'Up Helly Aa!  For hundreds of years the Shetland Islanders have celebrated the end of the Viking winter with a spectacular and fiery ceremony. John reports from the great blaze at Lerwick.', '1977-01-24', NULL, NULL, '2026-04-03T17:21:53Z', '2026-04-03T17:21:53Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('a5a163af-fb34-4f03-b65c-e6b37aa91cbd', 'ca19f895-1514-4988-a709-95e84eab7cee', 3, 'Decoding a Deal', 'Corey finds himself in such a lovely place when a test pressing of the Eagles mega-hit, "Hotel California" comes into the shop. Will the seller take it easy, or to the limit? Meanwhile, Chum checks out a ring from the "Little Orphan Annie" radio show. Will it be a "hard-knock" sale, or will Chum bet his bottom dollar? Then, a customer soars in with a model of Leonardo da Vinci''s flying machine. Will Rick get this deal off the ground, or will it come to a screeching halt? And later, when Rick examines blueprints by renowned architect, Frank Lloyd Wright, can he draw up a sale?', '2020-11-23', 42, '/1WVJD2MFkFYcHxf9JztYgY8FgeD.jpg', '2026-04-03T16:34:22Z', '2026-04-03T16:34:22Z');
