INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('a5adffce-56e0-48bd-affe-6e334340c4e4', 'ad4e4348-3334-4a08-8928-455d9ba524c1', 4, 'Linda Ronstadt', 'Afraid that Linda will steal her frog away, Piggy locks Kermit up in a chest owned by Gonzo when Scooter helps him move his mildew ""collection"" and hides it.', '1980-10-26', 26, '/c8f0KoC9bLTzdLBIoOfkrAvsCrZ.jpg', '2026-04-03T17:35:25Z', '2026-04-03T17:35:25Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('a5afe11a-cfec-458d-b5f7-49559019065d', '45e01c04-6ac6-41e1-87d8-f749ee230385', 19, 'Fireman James', 'James is keen to be a firefighter and listens to calls to Jupiter on his walkie-talkie. After one call he gets to Norman and Lion first and helps rescue them, but then a later call sees him trapped by fire at the Flood''s house.', '2008-03-06', 10, '/zXnc2CRNX1bK8NOonuGDIpyKnov.jpg', '2026-04-03T17:14:38Z', '2026-04-03T17:14:38Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('a5b24969-311b-4fe0-9207-f33d223c8bed', 'f9a8d8b3-d72e-437e-a9d5-7477f6d64df8', 1, 'Community Mural', 'Friends on Sesame Street are painting a mural to celebrate the people in their neighborhood. When Abby has a hard time finding a paint color that is the same as her fur, she learns to mix paint to make a color that looks just like her.', '2022-11-03', 26, '/3anJ8MZIyMxXrsOwwSNB5o3mTS4.jpg', '2026-04-03T17:36:51Z', '2026-04-03T17:36:51Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('a5b4e9bd-d1de-4764-8267-2d0a866be81b', 'bf722849-cddb-452b-9c0f-7f0d96e94c26', 13, 'Perseverance', 'When Plato discovers that Zach and Annie have given up guitar and karate lessons, he takes them on a hike to the top of Plato’s Peak. Along the way, Annie and Zach discover various objects, prompting several stories from Plato and Aurora about the importance of perseverance.', '1997-03-02', 30, NULL, '2026-04-03T17:38:34Z', '2026-04-03T17:38:34Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('a5c3b513-d314-45c3-9c64-d694e5589335', '6ef86c27-33e7-47e5-a053-483059dfd16d', 1, 'Episode 1', 'Expedition Japan: Who was the ''tall, fair-haired and very red-faced European'' pulling the float at Kyoto''s famous Gion Festival? None other than Simon, sweltering in 90°F, and that''s how he was described by five "Blue Peter" viewers who just happened to be in the crowds lining the streets! But that was nothing compared with wading shoulder high into a sea of 50,000 eels, playing the part of a Samurai warrior at the Kyoto Movie Studios and coming face-to-face with the massive 30-stone Sumo wrestlers who make Big Daddy look a mere midget.

And talking of giants, see how Prince has grown during the summer break and catch up with the latest news about all the other four-legged members of the team - Goldie, Jack and Jill and Maggie and Jim.', '1981-09-14', NULL, NULL, '2026-04-03T17:21:55Z', '2026-04-03T17:21:55Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('a5c7c7c4-b6cf-4677-87a7-a163703d0db3', 'd1727ab0-c860-40ec-af59-b76f25c2e0ad', 1, 'Report from the North Pole', 'Three polar bears explain how what''s going on with the environment is effecting their home.', '2009-10-04', 3, NULL, '2026-04-03T17:13:57Z', '2026-04-03T17:13:57Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('a5c9f37f-fa6c-4ae2-9495-7f99d85d10a7', 'd3e13496-e3c8-4903-83b4-5a31fedee232', 5, 'The King of Omashu', 'Aang''s abilities as an airbender are challenged by a strange king.', '2005-03-18', 25, '/6p6CR7ITrtaYEo0IewpFfMVowB8.jpg', '2026-04-03T17:40:47Z', '2026-04-03T17:40:47Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('a5cbe02d-1a0b-4447-b538-0bae2b204481', '204d86fb-d99c-4fd1-8dcd-9c1bcfd3c33f', 18, 'Just Desserts', 'The friends accidentally ruin a Wiggly-Jiggly dessert Mungus the Giant made for his mother''s birthday. So they all pitch in to help him make a new one. Max and Cassie go to pick Buttercups and Catgloves, Zak and Wheezie find pink and yellow seashells, and Ord and Emmy find blue and red round and square bubbles as the ingredients.', '2001-06-21', 30, NULL, '2026-04-03T15:26:04Z', '2026-04-03T15:26:04Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('a5cc8cc8-305f-4fa0-a308-d2f69a213690', 'a605edf8-69ba-46db-8c0c-523b1ef5447b', 3, 'Episode 3', 'with John Noakes, Peter Purves, Lesley Judd', '1972-09-18', NULL, NULL, '2026-04-03T17:21:51Z', '2026-04-03T17:21:51Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('a5cfb7ef-3cbc-44d4-96e6-059c7fc4e19b', 'dbde6570-a68d-4fd7-a1b0-a6037a266a18', 23, 'Lost Footage Special', 'Never-aired footage from season seven includes a double date with Vicki, Brooks, Gretchen and Slade; reunion showdowns; Heather and Alexis pursue their dream careers.', '2012-07-24', 44, NULL, '2026-04-03T16:35:31Z', '2026-04-03T16:35:31Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('a5d5c54d-c68a-4f35-8ec2-00e0c64f5f82', '7b8e3988-fbf3-4cfc-aeb2-782ae5a64e2d', 40, 'Elmo Wants to be Like Gordon', 'Elmo wants to be like Gordon, so he spends a day looking and acting just like him.', '2010-12-15', NULL, '/20WKD3A2XOZRbQ7xvwtMoIEiX8H.jpg', '2026-04-03T17:36:46Z', '2026-04-03T17:36:46Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('a5dba927-19de-448a-8eb4-bdfcef00b77d', '7ccd5605-fe0b-4e00-ae7f-3e3daa252f8b', 8, 'Let Bygones Be Bygones', 'Lynne Curtin meets Gretchen Rossi to discuss the conversation she had with Lynne’s teen daughter Alexa, about her alleged drinking and depression. Vicki invites Tamra to an "all girls" slumber party at her house. Vicki is excited to host a girls-only slumber party to make up for the fact that the men crashed the recent girls trip to Ft. Lauderdale. Later, Vicki surprises her friends by bringing in a psychic who reads their auras and they are caught off guard by some of his insightful readings.', '2010-01-14', 44, '/6ALkPsluwuOpk3HDc4PY7Wn2bG4.jpg', '2026-04-03T16:35:31Z', '2026-04-03T16:35:31Z');
