INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('a670d433-1346-4d11-9661-847bd5611bfb', 'c01ddd2a-bdb1-4c97-8d04-58f791ef1c24', 34, 'Water Creatures', 'When two African penguins stop by Animal Junction, Zoboo, Chris and Martin talk about water creatures. Even though penguins are birds, they swim instead of flying. But these penguins aren''t swimming! Finally, they realize it''s because the pool water is too warm for them. But when the water is chilled with ice cubes, there''s no stopping the penguins! Jaguars love to swim, too, and the Kratts play ball in the big pond with a black jaguar who stops by. Jackie has a new goldfish named Sunny, who is also sensitive about water temperature. To keep from shocking Sunny, Jackie puts his bag into the aquarium until the water in the bag is the same temperature as the aquarium.', '1999-09-08', 27, NULL, '2026-04-03T17:10:55Z', '2026-04-03T17:10:55Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('a67180af-e801-41e8-85b9-7473af530b18', 'bddd6427-4f85-402c-b58c-5c18ab159704', 100, 'Episode 895', '', '1976-04-16', NULL, NULL, '2026-04-03T17:36:31Z', '2026-04-03T17:36:31Z');
