INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('a7144be2-35eb-40d2-a6df-0055d5361819', '79c64e0a-3488-41bc-9b5c-2243ff15b373', 8, 'Do You Remember?', 'The tension continues at Dorit and Erika''s birthday dinner as Kyle is pulled into the middle of Amanda and Dorit''s drama. Rachel''s tough exterior finally cracks. Sutton is put in the hot seat when Dorit calls her out for not having her back. Boz receives a heartbreaking update on her fertility journey.', '2026-02-05', NULL, '/3l6MVT9FGvsv9nj1h9KFYvHgGEe.jpg', '2026-04-03T16:34:59Z', '2026-04-03T16:34:59Z');
