INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('a7258f41-8032-414e-8852-a1a27513ab27', '2aebfad4-3145-4bc1-9def-5f1d5bdfcfc8', 21, 'The Letter', 'Kramer sits for Jerry''s artist girlfriend, but Jerry won''t stand for her temperament, until she declares her feelings.', '1992-03-25', 24, '/glDnCsbbbUqMFwRZqDeLZNrpIA7.jpg', '2026-04-03T16:34:10Z', '2026-04-03T16:34:10Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('a7270d18-79ca-4666-96fd-021656031316', '9e4790f4-3aab-459c-a5ed-7100b4e39a75', 6, 'Anniversorry, Not Sorry', 'Ubah takes Erin diamond shopping for her 10th anniversary party. Jessel navigates the exclusive New York City pre-school scene. At Erin and Abe''s anniversary party, a bored Brynn stirs the pot and Sai gets upset about the lack of food.', '2023-08-20', NULL, '/95ortLTLCWg3Hdh4bNMvh5HU9CO.jpg', '2026-04-03T16:35:26Z', '2026-04-03T16:35:26Z');
