INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('a72abea8-9d2a-4027-b94e-a0b47a9a316d', '1839f036-18a1-4d3e-ac10-890765e2d592', 3, 'The Pea and the Princess', '', '2019-10-15', 13, NULL, '2026-04-03T17:38:03Z', '2026-04-03T17:38:03Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('a72cbfcb-8485-43e7-8bd3-c42f2aa81daf', '27a5a980-ec0d-4637-b5ba-df8324a6405a', 8, 'Heck''s Best Thing', 'Frankie and Mike are convinced that slacker son Axl will blow his interview with a football scout, which could earn him a scholarship to college. Meanwhile, Sue and Brick begin a texting marathon - and rack up some serious charges - when they discover that Aunt Edie accidentally gave them her cell phone; and Frankie tries to be completely attentive to the family''s needs when she realizes that she''s more considerate to outsiders than her own kin.', '2011-11-02', 22, '/3iAylhcNP4030FZ8R5ibF8RsNty.jpg', '2026-04-03T15:40:29Z', '2026-04-03T15:40:29Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('a72fbabd-badb-4fb8-8166-3b321b5360a9', '5046642d-462d-4eb0-8194-0bbd7962af0f', 8, 'The Asparagus of La Mancha', 'An adaption of Spanish novel Don Quixote, "Asparagus of La Mancha" starts with Knight Don Quixote facing three Peas in a surrealist world made of cooking utensils and foods. Then he wakes up. It was a dream. He and his best friend Poncho work in a Spanish restaurant of Cafe LaMancha. However, Jean Claude comes in to inform the duo of a new restaurant opening across the street called ''The Food Factory'', the most successful, and biggest, restaurant in the world. With their customers abandoning them, Don is sure they will go out of businesses. After losing another game of Spanish checkers to Poncho, Don goes back to sleep. He assumes his latest dream has informed him to try different themes to win back their customers. This fails, and shortly after, the Food Factory manager offers Poncho a job at the Food Factory. Poncho refuses. Don''s next dream convinces him to attack the Food Factory.', '2006-09-09', 30, NULL, '2026-04-03T17:39:38Z', '2026-04-03T17:39:38Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('a731975f-30d3-4275-8e5f-af4ca1a10c98', '3af7ea64-fa13-4097-b8e4-40af07083054', 63, 'Episode 63', 'Mister Rogers brings with him a collection of puppets from around the world that were provided by the Lovelace Marionette Theatre. He then goes to Elsie Neal''s shop to find Elsie Neal helping Terri and Chrissy Thompson for their upcoming puppet show. In the Neighborhood of Make-Believe, Lady Elaine is ready to do remote TV work. The first act is Lady Aberlin in a primitive witch costume, which scares Henrietta.', '1974-05-15', 28, NULL, '2026-04-03T17:35:40Z', '2026-04-03T17:35:40Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('a73275a7-2de1-470c-959f-a93b4c22f290', 'f1325b56-44e0-4b6e-89bc-82cac30afea6', 24, 'To Outfox a Fox', 'The friends go to the beach for a picnic but Lily needs help when she gets stranded on a sandbank', '2012-09-15', 10, '/aNnWBlxJ0Bokp00kLWnwNWbNCz2.jpg', '2026-04-03T17:14:39Z', '2026-04-03T17:14:39Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('a73a8359-cdc5-44db-bb8a-ce4faf30a81a', '876145f4-b55e-4070-b35b-893a67f88bac', 2, 'On Lock Down', 'The Giudice Family struggles as Joe is released from prison but transferred to ICE. Dolores plans a fun event to get Teresa’s mind off her troubles, but when Teresa invites Danielle, the day turns to high drama.', '2019-11-13', 43, '/5wocQYCTCa3uyo0kRRLFMkka73U.jpg', '2026-04-03T16:35:18Z', '2026-04-03T16:35:18Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('a73eb89d-03d6-46b5-ac63-1418323dd554', '41328fef-c185-4924-a8b0-791b5b84f8fd', 18, 'Big Horns George', 'George''s bad day gets worse when he comes over to Mrs. McGrady''s house to sing for Koko Taylor and his friends insult his quiet voice.', '2003-12-26', 13, NULL, '2026-04-03T17:37:57Z', '2026-04-03T17:37:57Z');
