INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('a743b8dc-8bb8-44de-a6ef-9b95a173bf9e', '6f81c872-cdb9-42dd-8377-2c17cb6ed4d7', 3, 'Abby Helps Clear Things Up', 'Abby helps Prince Charming calm down at the eye doctor''s office.', '2017-01-21', NULL, '/wgcVOkXqQBRfdlueg8b001jfqLV.jpg', '2026-04-03T17:36:48Z', '2026-04-03T17:36:48Z');
