INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('a7bd835a-6363-4ac5-94e5-99c55b741422', 'c9adc698-be92-4dd7-94ad-d8f6759361ca', 59, 'Mixed-up NOM Pt 4', 'Rogers talks to a glassblower at Elsie Neal''s Craft Shop. Lady Elaine moves all the locales back where they belong. King Friday commissions a Festival of Mad Feelings for the next day.', '1973-05-10', NULL, NULL, '2026-04-03T17:35:40Z', '2026-04-03T17:35:40Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('a7be81f2-bc93-449f-8c65-610bf8c33c12', '2e8b61b6-6179-4204-9d2b-c12300836fc8', 8, 'Oakie Doke and the Runaway Bowls', 'The day after a thunderstorm, Doke helps Rufus and Rain repair their chimney. Meanwhile, Root thinks he can hear giants, and thanks to Hickory and Snoot, there are now several bowls rolling around the woods, causing chaos wherever they go.', '1997-08-19', 10, NULL, '2026-04-03T17:19:25Z', '2026-04-03T17:19:25Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('a7c57796-1faf-4120-8994-2bafae117e7a', '6617316f-2b1c-4733-9f9f-f315db6ade0b', 7, 'Episode 7', '', '1995-02-15', 25, NULL, '2026-04-03T17:21:16Z', '2026-04-03T17:21:16Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('a7c97195-d62b-4f4e-8fff-298fc06d8ee9', 'f5c042dc-0657-42e8-a37d-247414140632', 3, 'Kary''d Away', 'Stephanie starts a charitable foundation and encounters nothing but resistance from Travis, while Tiffany’s demanding mother makes her feel like nothing she does is ever good enough. Kameron hosts an outrageous party for Kary’s 50th birthday, where Tiffany and Kameron spar over chicken feet and things get out of hand after a night of drinking.', '2021-01-19', NULL, '/AmReL4jdrk6g9cjl5HmOrAzvjs4.jpg', '2026-04-03T16:35:05Z', '2026-04-03T16:35:05Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('a7ccebfa-725c-4962-baf9-3a5a34bf52f4', 'f5c042dc-0657-42e8-a37d-247414140632', 1, 'Bursting the Quarantine Bubble', 'With the stay-at-home order finally lifted, the divas of Dallas are ready to make the most of their quarantine bubble, as safely as possible. Kameron gets a new dog and hosts a socially distanced garage sale. Brandi looks for ways to make amends after a controversial video resurfaces on social media, and D’Andra introduces everyone to her friend, Dr. Tiffany Moon.', '2021-01-05', NULL, '/1EdPEciSWUzbB7I0cgZwLUaKxdb.jpg', '2026-04-03T16:35:05Z', '2026-04-03T16:35:05Z');
