INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('a7eea880-c976-4aad-8b4a-9e2868cb4b22', '3f470ec5-a182-4b57-a572-e18864f7f1ea', 3, 'Episode 3', '', '1990-02-27', 25, NULL, '2026-04-03T17:21:15Z', '2026-04-03T17:21:15Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('a7fe85e0-13fe-49ff-953e-a982b0365ea2', '5b5e8b2f-0a85-4488-b3dc-3d8b794e6582', 17, 'A Case of the Vickis', 'Vicki''s health scare continues and brings out a side of Peggy that shocks the ladies. Later, a broken friendship might finally be on the path to mending, while a drunken night causes fractures in another.', '2017-10-30', 44, '/nK0412upxQECRA1okjgkGGtxn1K.jpg', '2026-04-03T16:35:33Z', '2026-04-03T16:35:33Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('a8052c17-5d7d-4524-b9e6-119a35a46bf9', '3fc7c152-e4f6-426a-a899-36ec454c4403', 16, 'The Talent Pool', 'Cassie notices that all her friends have special talents except her, so she goes to the Talent Pool to finds a talent. However, the Pool turns out to be grumpy and refuses to give Cassie a talent.', '1999-09-22', 30, '/tsQCfi9Wd4b7UR2hxz07zDiMtor.jpg', '2026-04-03T15:26:03Z', '2026-04-03T15:26:03Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('a80b66b9-a056-4aed-9844-4d4f562486da', '45e01c04-6ac6-41e1-87d8-f749ee230385', 7, 'Stuck In The Muck', 'There''s trouble for Trevor Evans as the school bus swerves off the road and breaks down in the Pontypandy hills. Unfortunately, mobile phones have no signal up in the Welsh hills and he is stranded - with a beast about. Fireman Sam comes to the rescue, with the assistance of Tom in the helicopter. Then they search for Trevor, who made an attempt of finding help. In the end everyone is safe and they go home. Norman spots a black animal passing over the road just before the bus rounds a corner, but when he tells everyone else about his sighting, nobody believes him.', '2008-02-18', 10, '/s9jcH56dJDSjvBMI5drVs0Gw35i.jpg', '2026-04-03T17:14:38Z', '2026-04-03T17:14:38Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('a80d2030-2cac-43b4-8f5b-b1188f8e6ad5', '0e419615-4c96-4dde-8ed2-715770ba77bb', 2, 'Welcome To Woodland Valley (2)', 'In the second half of the two part special, the plans are coming together for a potluck dinner Bear is holding. Everyone will get together at the Big Blue House, eat good food and talk about solutions to fix up the library. The kids are hard at work collecting books to restore the library''s collection. And Doc Hogg is getting down to business as to just what to do about the tree currently occupying a large portion of the library. He wants to remove it, chop it up and use it for firewood to heat all of Woodland Valley, but Ojo makes a discovery that changes the plan --- a couple of possums living within the tree.  Songs  Good Morning  Everything''s Great About the Library  Woodland Valley Cha Cha  Goodbye Song  Notes  This is a direct continuation from Part 1.  Brad Garrett and Gilbert Gottfried voice the Possums in this episode and receive a "With" credit. They had previously appeared on Hollywood Squares with Bear.', '2002-09-09', 25, NULL, '2026-04-03T17:35:32Z', '2026-04-03T17:35:32Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('a8174837-bf93-4ea5-b4c7-7a1524a1177e', '9193e795-da7c-40ec-b68f-f63aa7d5174f', 105, 'Histories & Lore: The Lord of Light', 'Thoros of Myr details his personal history as a follower of the Lord of Light, from his skeptical youth in Myr, to his visions in the flames that have made him a believer.', '2014-02-18', 4, '/iLKykUL21OQzXuQVlzjWtXctrFO.jpg', '2026-04-03T15:40:35Z', '2026-04-03T15:40:35Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('a81a8c54-f945-4fa9-9dc4-b555b98f1d83', '7b8e3988-fbf3-4cfc-aeb2-782ae5a64e2d', 38, 'Abby''s First Sleep Over', 'Abby goes to Big Bird''s nest for her very first sleepover, and Maria reads her "Hey, Diddle, Diddle.', '2010-12-09', NULL, '/85ZpIdQIXxYNj1yDR65LsoTWpcn.jpg', '2026-04-03T17:36:46Z', '2026-04-03T17:36:46Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('a81aec5a-ec89-4c99-818b-ca44e2c3dff9', '02849655-bd95-4d8d-af3b-03321918eeee', 19, 'Madeline and the Magic Show', 'After Pepito and the girls go to see Harry Houdini''s show, Pepito decides to create his own magic show at home, and puts poor Genevieve in danger. Houdini helps the children see how to use magic properly and shows them how to appreciate the gifts they were born with.', '2001-01-10', 30, NULL, '2026-04-03T16:34:02Z', '2026-04-03T16:34:02Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('a81d7814-8ded-4f86-81fe-927cba25ddf1', '8610109b-4fb9-4eae-be54-c549fae5ecc8', 13, 'Audio Commentary: Conjunction Junction', '', NULL, 3, NULL, '2026-04-03T17:13:55Z', '2026-04-03T17:13:55Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('a81da797-b5ca-427b-86fb-06b08085bc6f', 'a7421c26-c9a2-437a-be12-2cabed2b5a96', 3, 'My Favorite Song / The Milk Monster / Pills', '', '2001-09-19', NULL, NULL, '2026-04-03T17:11:22Z', '2026-04-03T17:11:22Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('a823a067-6ee0-4ef1-ac9e-13ead08d221f', 'ad180412-a5d6-4e4a-8b49-590334f2fc69', 3, 'Water, Water', 'Water becomes an issue for the Animals of White Deer Park. Shadow and Hurkel arrive at the park only to see that the only water source Trey will allow the animals to drink from has been poisoned. That was the stream that The Great White Stag perished from. Meanwhile outside White Deer Park, Owl encounters a Rook  named Moth eaten Rook who wants to talk to her. However Owl flies away with the Rook following her.', '1995-10-12', 25, '/9rAI1Mtop6Qs8nqzdlaePHSYWYt.jpg', '2026-04-03T17:18:49Z', '2026-04-03T17:18:49Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('a824d614-b35e-46c2-aa7e-a338922e4190', '9c9d89df-5f6b-41d0-84c6-b8ca7bd2a2e6', 4, 'Sesame Street Art Museum', 'Everyone is making a painting to hang in Sesame Street’s art museum. Rudy wants to paint a rainbow, but he can’t make the perfect purple. What if he mixes the red and blue paint a little bit at a time? Let’s try!', '2021-12-02', 20, '/gbK1bxWxb9yB9jLjWhOkAZe057F.jpg', '2026-04-03T17:36:50Z', '2026-04-03T17:36:50Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('a8259f3b-43e3-4fa7-a02d-4fb4cc958616', '5a771f52-fe96-4ea2-b567-a8dde899059e', 15, 'Can''t Pawn Me Love', 'Rick travels to an art gallery in the Venetian Hotel to see some monstrously expensive illustrations from the classic children''s book, "Where the Wild Things Are." Back at the shop, a collection of ultra-rare Beatles vinyl records sends Chum across the universe. Can he work it out with the seller, or will he decide to let it be? Chum warms his buns with an antique hot dog bun warmer, while Rick is frank about an electric hot dog cooker. Later, Rick and Chum can only hope to force the sale of a Princess Leia action figure signed by the late Carrie Fisher.', '2018-01-29', 21, '/u2BRSeh7jJPz5NwAO1JSYxaJ4Mn.jpg', '2026-04-03T16:34:21Z', '2026-04-03T16:34:21Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('a8294502-91d8-431e-8510-83cad30ca454', '4091b13b-4db6-4857-ad22-20b5658c6b89', 6, 'Dildos Down the Shore', 'As the ladies and their husbands head down the shore, Teresa finalizes her divorce and Joe Giudice''s rumors about Joe Gorga come to a head. And, a gift from Teresa to Jackie sends the entire group into a tailspin.', '2021-03-24', 43, '/2oUgcLYjvlR14qjPBATiZt6mReZ.jpg', '2026-04-03T16:35:18Z', '2026-04-03T16:35:18Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('a82c7217-4fef-4f29-856b-fbe315e9b107', '136b81d3-964d-4b8f-a214-92f00d96d6b9', 60, 'Big Bird and Snuffy hunt for treasure.', 'Big Bird and Snuffleupagus search for buried treasure on Sesame Street, following clues and hints while learning about cooperation and friendship.

Sponsors: O, X, 11', '1984-02-10', NULL, NULL, '2026-04-03T17:36:35Z', '2026-04-03T17:36:35Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('a8376282-e629-4806-b75f-a7c0aeb4a314', 'c373abed-50ef-417e-9f34-4e9050611a1b', 9, 'Speech Therapy', 'Vicki is torn between spending time with Brooks or babysitting her grandson; Lydia convinces Alexis to talk to Tamra; Gretchen visits a fertility doctor; Tamra gives a speech at the Los Angeles Women''s Expo.', '2013-05-27', 44, '/xhxM8jKRNw72LHamCfn2lYbe4LQ.jpg', '2026-04-03T16:35:32Z', '2026-04-03T16:35:32Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('a8390d3a-420b-4ed4-bcd5-9ce56725ae74', '39505290-458d-46b9-8bdf-69ee037230e2', 1, 'On the Day You Were Born', 'How babies are born is explored, in great detail, in this episode, as a family welcoming their fourth child is profiled during the last few weeks before delivery. Patrick Stewart reads a poem about how special each person is when they come into the world, and how every birth should be celebrated.', '1997-04-07', 30, NULL, '2026-04-03T17:36:20Z', '2026-04-03T17:36:20Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('a83a30db-5412-4124-bea6-d53b9625395e', '4892e2af-46c1-4b4e-ac81-eac161b5a347', 6, 'Episode 6', 'Expedition Brazil  PETER joins the gauchos of Rio Grande do Sul and helps to round up some of Brazil''s five jmillion cattle.', '1977-09-29', NULL, NULL, '2026-04-03T17:21:53Z', '2026-04-03T17:21:53Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('a83d807b-2195-4bcc-8a62-df78f8ba5003', 'f9a8d8b3-d72e-437e-a9d5-7477f6d64df8', 22, 'Monster Truckin''', 'Elmo and Chris are making their own monster truck jump, but they don’t have a ramp. What if they make one out of a pizza box lid? Let’s try!', '2023-03-30', 26, '/8pM7zCB2ttDxt2Aabdm0996P3XX.jpg', '2026-04-03T17:36:51Z', '2026-04-03T17:36:51Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('a83e2574-c6be-4483-8079-ba634b5920e2', 'd5383b3d-5636-4d71-b99c-b84774b4b3c6', 12, 'Pingu in Paradise', 'Pingu and Pinga are playing hide-and-seek. Pingu hides in the toy box while Pinga is counting. Pinga looks for Pingu inside, can’t find him and goes to look outside. She can’t find him there, either. Mother then comes out to go shopping and Pinga tells her she can''t find Pingu. Mother takes Pinga with her to the shops. After they have gone, Pingu peers out of the box and can’t see anyone. He feels tired, falls asleep in the box and has a dream. The toybox moves itself across the floor and the lid on the saucepan rattles about. A plate falls out of the cupboard but as it lands on the floor it morphs into two plates. Pingu suddenly wakes up. The telephone rings and Pingu goes to answer it. The receiver comes off in his hand and the body of the phone then falls off the wall and on to the floor. It turns into flowers, and the receiver that Pingu is holding also turns into a flower. A book and some toys jump out of the toybox and onto the floor. The book morphs into three and they start to dance, together with the lid of the saucepan. Some firewood joins in. The propellor on the toy plane starts to turn, and the plane takes off, does a couple of circuits inside and then flies out of the door. Pingu follows. He can’t see the plane anywhere. The snowman suddenly talks to Pingu and points. Pingu goes to where the snowman is pointing and sees some flowers growing in the snow. To Pingu’s surprise, one of the flowers then changes itself into a large tree. Blossom, and then fruit, form on the tree, and an apple falls off. Pingu eats the apple. Nearby he then sees a cascade of pink liquid (possibly milkshake). He goes across to it, produces a straw and drinks all the liquid. A fish flies up from the last of the liquid, lands on Pingu’s hand and then flies into Pingus mouth. Pingu swallows the fish, and then spots a number of giant lollipops sticking up in the ice a short distance away. He starts to lick a large pink lollipop, and is surprised when it moves away from him. Pingu then wakes, to find Mother and Pinga have returned from shopping. Pinga gives Pingu a pink lollipop she has brought back for him!', '1998-11-20', 5, '/vcTrwXZ5iYdxYWxHXKl74ThhuuY.jpg', '2026-04-03T17:22:20Z', '2026-04-03T17:22:20Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('a847b880-84a2-40cb-bec4-1d3655611196', '6053b5c1-ce86-425c-8166-e0fcc3466061', 26, 'Episode 26', 'with Valerie Singleton, John Noakes, Peter Purves', '1969-12-11', NULL, NULL, '2026-04-03T17:21:50Z', '2026-04-03T17:21:50Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('a84a3192-dc07-4748-abe6-bf72d7a5b5ee', '421c3366-4d98-4baf-b4ad-6ec5047df9f8', 8, 'Just the Ticket', 'Arthur''s ecstatic when he wins free concert tickets on the radio. The problem is, he can only take one friend.', '2013-11-14', 13, NULL, '2026-04-03T17:38:01Z', '2026-04-03T17:38:01Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('a84aed05-05c0-422b-bdc9-6f65e02c8c06', 'f4c40307-9b5e-4263-a4e0-dfa138131e7f', 53, 'Sesame Street: Guess That Shape and Color', 'You’re invited to play a shapes guessing game with Elmo and Zoe and their friends. From squares and circles to ovals and octagons, shapes are everywhere!

But the fun isn’t finished yet. It’s time for more games as Elmo and Zoe are challenged to find a gorgeous rainbow of fabulous food choices. Can they do it? Can your preschooler help them out? Join everyone’s favorite furry monsters in this new video that teaches shapes, colors, and healthy eating.', NULL, NULL, NULL, '2026-04-03T17:36:27Z', '2026-04-03T17:36:27Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('a84e1e48-72f0-4295-b740-359268fe3db3', 'a8c6182e-05e1-4b68-91a5-5126cf6c94f0', 5, 'The Midnight Ride', 'Sarah and James travel to Boston to deliver a message to Patriot leader Dr. Joseph Warren and end up riding with the famous messengers so that they can write about it for the paper.', '2002-09-06', 30, '/pmM9vSteaU2hhp80v9L8Hiw90FF.jpg', '2026-04-03T17:38:28Z', '2026-04-03T17:38:28Z');
