INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('a857700f-b8a5-4504-ab29-09cb235b785a', '8c3cfac1-d882-4904-b38c-d1981628d00e', 60, 'Episode 60', '', '1979-04-09', NULL, NULL, '2026-04-03T17:21:54Z', '2026-04-03T17:21:54Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('a85cd02f-2a8a-48e6-af33-a8c548ef7963', 'e40e6b63-9f84-449f-8e88-53209b0906c8', 8, 'Big Bird Helps Zero', 'On a beautiful day, Big Bird encounters a sad number Zero, who is upset because he is nothing. He sings a song about it. Big Bird sets out to show Zero that being nothing is really something. When they go to Hooper''s Store, Zero asks for a banana split, but Alan realizes he''s out of bananas, which is the perfect cue for a musical number parodying "Yes, We Have No Bananas." In song, Alan explains how the number zero helps him keep track of what he needs to order whenever he runs out of something in the store. This makes Zero feel a little better, but he is still not convinced of his worthiness.', '2007-08-27', NULL, '/znadl8F6PDL4C7geFkeELxGrJpu.jpg', '2026-04-03T17:36:45Z', '2026-04-03T17:36:45Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('a8606ae0-0c43-4ac1-81e3-ba8b713ea085', '9e4790f4-3aab-459c-a5ed-7100b4e39a75', 10, 'Naughty-ical by Nature', 'Erin catches Brynn up on the newest tension between Sai and Jessel. During the group''s picture-perfect boat day, Jessel clashes with Erin and Sai while Brynn and Jenna get closer than ever. Back at the villa, Ubah and Erin''s pranks on each other result in a shocking shift in their friendship.', '2023-09-17', NULL, '/6Kfz6YYQxWsIE7gRJWJlwBsZfGu.jpg', '2026-04-03T16:35:26Z', '2026-04-03T16:35:26Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('a863066a-aa59-45e7-97b9-d28e4b4805b9', 'c9adc698-be92-4dd7-94ad-d8f6759361ca', 12, 'Welcome New Friends Pt 2', 'Rogers discusses sleep, with help from the McFeelys. Sunset reaches the Neighborhood of Make-Believe, and Daniel still doesn''t believe he can to go to Grand-père''s for the night. Donkey Hodie has advertised his need for a helper at Someplace Else.', '1973-03-06', NULL, NULL, '2026-04-03T17:35:40Z', '2026-04-03T17:35:40Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('a86c6cc8-cab6-441f-a1fe-1f0254011b5e', '50ee8f6c-645c-4d48-bab9-53b9f8f7ff2f', 8, 'Goodbye Pacifier', 'Curly Bear is unsure about giving up her binky, so Elmo tries to help.', '2011-10-11', NULL, '/qKWM8PmgO58HOwA0MiwL7X2alQL.jpg', '2026-04-03T17:36:46Z', '2026-04-03T17:36:46Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('a87490a2-d15a-4058-b8c2-05e2fa3d6a59', '38bf8c20-c17c-4071-9226-7887787cf1b1', 18, 'Why the Baboon''s Balloon Went Ka-Boom!', 'Theo wants to teach the cubs a lesson, which he finds in a book of concatenations called Because a Little Bug Went KA-CHOO!  What Theo doesn''t know is that, by pulling that book from the middle of a pile, a pen dropped to the floor, setting off a concatenation in the library.  It culminates with a hot-air balloon''s bursting.', '2001-04-25', 30, '/JY7hJqMMFgRvl0oSGz24gGpteu.jpg', '2026-04-03T17:12:28Z', '2026-04-03T17:12:28Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('a87a0b49-44b5-4b6a-a1c8-3db6a2298a25', '4d2cac0f-38fd-438b-8afa-acf43952e535', 3, 'Episode 3', 'Toys, model railways, games, stories, cartoons. A weekly programme for younger viewers with Christopher Trace and Leila Williams.', '1958-10-30', 15, NULL, '2026-04-03T17:21:47Z', '2026-04-03T17:21:47Z');
