INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('a8865456-3203-438d-9477-daa2ee226f66', '90d7a60c-d72f-4aea-89c0-81dc1e187efe', 8, 'The Crocodile Hunter Goes West', 'Steve and Terri travel west in search of a mate for the Goanna lizards at the reptile park. Also: the pair rappel into a deep bush gorge, but have difficulty trying to get out.', '1998-08-23', 44, NULL, '2026-04-03T17:39:11Z', '2026-04-03T17:39:11Z');
