INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('a89f2569-122d-499f-be33-b19790e578bc', '27d0351a-92f5-4d01-995c-6b5928957075', 6, 'Finsta of Fights', 'When Heather is caught telling a lie, Lisa sets the record straight; Whitney is surprised when Justin is unexpectedly laid off; Meredith and Angie H. have a double date with their husbands.', '2022-11-02', 44, '/f6OCOn8WeOXrpbFtWI2RnFY5VGz.jpg', '2026-04-03T16:35:44Z', '2026-04-03T16:35:44Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('a8a1cf08-4d45-4d14-ae4c-376218836f86', '4d2cac0f-38fd-438b-8afa-acf43952e535', 221, 'Episode 221', 'Christopher Trace and Valerie Singleton introduce a magazine programme for younger viewers, including Ballet for Athletes - David Blair, Premier Danseur of the Royal Ballet, assisted by David Morse, shows why dancers have to be fine athletes and how their exercises can help football, high jumping, hurdling, and all kinds of sport and The Swapping Song. David Blair and David Morse appear by permission of the General Administrator, Royal Opera House Covent Garden, Ltd.', '1963-02-25', NULL, NULL, '2026-04-03T17:21:47Z', '2026-04-03T17:21:47Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('a8a2cc27-7709-48a4-a3b2-c3d3c0640120', '4fe93658-c463-4329-8e64-9d523869c2cb', 1, 'Peeping Pawn', 'The Pawn Stars are presented with a supremely rare 1776 Massachusetts penny made by Revolutionary War legend Paul Revere. With only one other coin known to exist in the world, will the gang crank out a mint for this priceless coin or will they find they can’t spare the change? Then, Rick has an opportunity to buy a hand grenade made by a top-secret American World War II spy program. Will he pull the pin to make a truly explosive deal or will the negotiations have him running for cover? And later, Rick and Corey meet a man hoping to sell his 1950s peep show machine. Will they like what they see and bare their wallets or will it be too stripped down for comfort?', '2010-08-16', 21, '/lQqvRMbwQy5QCau79pGDASDLaYV.jpg', '2026-04-03T16:34:16Z', '2026-04-03T16:34:16Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('a8a7b1b2-91aa-4bec-9392-6ee7009cc225', '68138de2-0900-460a-b58e-480688f1e081', 16, 'Look What I Made', 'Doc Hogg pays a special visit to the Big Blue House to give everyone a checkup. Before he arrives, Pip and Pop dress up as doctors and pretend to give a checkup to Treelo. Bear tells the viewers all about Doc Hogg and what doctors do. Later, Doc Hogg gives everyone their checkup, but Ojo seems to have disappeared. Bear finds her hiding with Snow Bear --- it turns out that she''s scared of getting a shot. Bear helps her out by teaching her a special song that Doc Hogg once taught him. 

Songs 

■Old Doc Hogg 

■Everybody Say Ah 

■Just Say Ow 

Notes 

■This episode was adapted in book form as The Big Blue House Call. 

■There is no Shadow segment in this episode. 

■The dog in the Shadow Projects logo in the closing credits laughs like Doc Hogg instead of barking.', NULL, 25, NULL, '2026-04-03T17:35:31Z', '2026-04-03T17:35:31Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('a8a816f9-ed87-415a-8cae-8fd9532602e1', 'd6092173-d23b-4449-baff-e0e16fe56c9a', 1, 'No Justice, No Peace', 'Porsha’s involvement in the Black Lives Matter movement leads her to Louisville, Kentucky, where she risks everything to demand justice for Breonna Taylor. In the wake of the pandemic, Cynthia and Mike are on different pages when it comes to planning their dream wedding. Kandi prepares to send Riley off to college while anticipating fallout for seeking back child support from Riley’s estranged dad. After almost a year apart, Kenya comes to a crossroads about whether her marriage is worth saving.', '2020-12-06', 43, '/vskjhtU9h7iffoStQUnyMN6CicM.jpg', '2026-04-03T16:34:49Z', '2026-04-03T16:34:49Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('a8ae5a7d-8045-414f-ae56-4096e02015b6', '45e01c04-6ac6-41e1-87d8-f749ee230385', 3, 'Elvis Sings The Blues', 'Elvis Cridlington breaks his leg dancing around the Fire Station and begins to wonder if he is really cut out to be a firefighter. But when Mike Flood ends up dangling precariously from his roof and Norman gets his head stuck in railings, it is up to Elvis to save the day.', '2008-02-13', 10, '/lOcRDyECC43utTMwz7XEpNDkdUv.jpg', '2026-04-03T17:14:38Z', '2026-04-03T17:14:38Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('a8b14374-7ca0-47a4-9cea-726398d9dc78', '19e027c7-8626-44a9-96ba-d36b323b3a74', 5, 'The Thirty-Minute Work Week', 'Wembley has to decide what job he wants to do.', '1983-02-07', 24, '/2Fk3Jv3zdil342l5QsqMDLy3dfB.jpg', '2026-04-03T17:34:59Z', '2026-04-03T17:34:59Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('a8b26ba4-7405-4856-b6bc-1f95530454d3', '0b9d7ae7-218e-45a0-8c3a-e69912f5a6ed', 11, 'Franklin Plants a Tree', 'Franklin''s preconceived notions about trees are turned upside down when he gets the responsibility of planting one.', '1999-11-22', 12, NULL, '2026-04-03T17:40:15Z', '2026-04-03T17:40:15Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('a8b42623-7e70-4127-8388-30f56f9601c4', '204d86fb-d99c-4fd1-8dcd-9c1bcfd3c33f', 9, 'One Big Wish', 'Max is still tired of being little, so he makes a wish in the wishing well which makes him grow giant. But after growing too big with no limit, he later regrets it and wishes to be his own size again.', '2001-06-08', 30, NULL, '2026-04-03T15:26:04Z', '2026-04-03T15:26:04Z');
