INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('a8b5be69-ef7d-46f4-ba15-2f7d2fc05a42', '787dfa0b-c827-4dad-a82d-0548a6534d88', 3, 'Whine Country', 'Heather and the ladies travel to Napa to celebrate the launch of her new sparkling wine Collette. OC transplant Meghan is excited for her first trip to wine country, but is also apprehensive after her recent run-in with Shannon. Shannon continues to struggle with her emotions regarding her husband David''s affair. Also, Tamra reveals her newfound relationship with the lord while also trying to draw some much needed attention to her new boobs.', '2015-06-22', 44, '/yEQShzt6M6dVsA8W2QiwThO7Spk.jpg', '2026-04-03T16:35:32Z', '2026-04-03T16:35:32Z');
