INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('a8ccbad1-fdba-4550-9fe9-6a190a7879cf', '740a96a0-a075-4be2-be92-a178d0939384', 13, 'Book Worming', 'Elmo''s friend Zuzu is visiting Sesame Street from South Africa. After reading all about her home in the Book Nook, Elmo and Alan throw Zuzu a welcome party with South African food, music and traditional clothing. At the party, Zuzu says she read up on Sesame Street, too.', '2018-02-10', NULL, '/8FdDqchS1KEOPVETp6MhUy67xN7.jpg', '2026-04-03T17:36:49Z', '2026-04-03T17:36:49Z');
