INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('a8d78313-233c-4db8-943b-6813a6b541fc', '1cafb2c3-bbcb-4172-b02d-441a5aaa155f', 5, 'Giving and Receiving: Reading with LeVar Burton', 'Rogers presents a gift for Mr. McFeely just as he delivers a book for guest LeVar Burton (the host of the PBS program Reading Rainbow) to read. In the Neighborhood of Make-Believe, the finder balloons reveal Lady Elaine and her friend in an obscure room of the Museum-Go-Round. Then Maggie Stewart Brings A Videotape Of Mr Rogers Taking A Bath', '1998-08-21', NULL, NULL, '2026-04-03T17:35:48Z', '2026-04-03T17:35:48Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('a8dab1a0-cbaa-47e2-96d3-d112d8c7133e', '1c0a48a4-4d1c-424b-b54f-265883e6b26e', 15, 'Sip & Spill ... the Tea', 'Sheree plans an over-the-top "Sip & See" to introduce her friends to her glam baby, Mecca, and discovers a decades-old family secret; Marlo hosts an event to honour those who''ve been through the foster care system.', '2023-08-20', NULL, '/rMB4AgsBo6GkWzf00ydlxaSsDky.jpg', '2026-04-03T16:34:50Z', '2026-04-03T16:34:50Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('a8db9adf-102b-41ce-a249-1e22b8fc1729', '56184a09-a2e5-4d61-b4d5-66a16df3036b', 5, 'The Great Race', '', NULL, 29, NULL, '2026-04-03T17:12:14Z', '2026-04-03T17:12:14Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('a8ddc765-5879-4e7f-bebe-5b2f2974f97f', '2f5a4ffe-2548-4181-85ac-6145cb3e3bf7', 8, 'Aspyn’s Royal Wedding', 'Aspyn and Mitch are getting married with bagpipes, kilts and lots of flower girls. It’s a perfect day but the officiant has lost his voice and the Browns are stressing because they now have to move to Flagstaff within a month.', '2019-03-17', 60, NULL, '2026-04-03T16:34:31Z', '2026-04-03T16:34:31Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('a8e9d1f3-98fd-4863-96f7-39b1878b8fb2', 'c373abed-50ef-417e-9f34-4e9050611a1b', 16, 'Crossroads', 'Alexis comes face-to-face with Gretchen; Heather and Terry receive a surprising offer; Vicki struggles to keep things professional with Brooks; Gretchen plans a surprise marriage proposal for Slade.', '2013-07-22', 44, NULL, '2026-04-03T16:35:32Z', '2026-04-03T16:35:32Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('a8ea05bd-f43d-49ef-a073-bd7e8c969066', '68138de2-0900-460a-b58e-480688f1e081', 8, 'The Ojolympics', 'Bear gets a notice in the mail that he¡¦s just received a free mambo lesson! Everyone is inspired by the subject of learning, including Ojo, who plays make-believe school with Treelo, Snow and Rock Bay. And everybody¡¦s extra excited to learn the mambo with Bear when the instructor turns out to be Grandma Flutter!', NULL, 25, NULL, '2026-04-03T17:35:31Z', '2026-04-03T17:35:31Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('a8eabd94-12c9-4ba0-99e2-102849d17bff', '25fe20d1-6fc6-4236-93f6-73178498cdfa', 5, '1st Wife''s 20th Anniversary', 'While the three wives buy a friendship ring for Kody''s fiancée Robyn, Kody prepares to celebrate his 20th Anniversary with his first wife, Meri. But when nothing goes as planned, will Kody end up in the dog house?', '2010-10-10', NULL, NULL, '2026-04-03T16:34:27Z', '2026-04-03T16:34:27Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('a8ec5e99-c08e-4c43-a3c6-c17c8f73f747', 'bfdf87ff-01dd-4b54-94bd-19b384f41bdb', 1, 'When the Ship Hits the Fan', 'The ladies kick off an explosive 11th season with an epic boat party filled with tensions at an all-time high as Vicki fights to win the ladies back after a year of lies left her friendless and alone. Heather''s mansion is still a work in progress, and so is her relationship with her workaholic husband Terry. Shannon''s marriage is on more solid footing, so it''s time to look for a new home for her family. Unable to have children the old fashioned way, Meghan starts in vitro fertilization (IVF) with no help from husband Jimmy. And new housewife Kelly Dodd brings her big personality to the party, but her loud mouth gets her in big trouble.', '2016-06-20', 44, '/w5gzPJ4zGdCXCNVCivTUfwW7GzJ.jpg', '2026-04-03T16:35:33Z', '2026-04-03T16:35:33Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('a8ee119d-c314-4d54-9fd0-665f5a7de200', '939d270c-ea8e-4cc8-a5a5-e59df2c8062c', 6, 'Dinner on the Rocks', 'Caroline Stanbury clears up some issues with Lesa at an afternoon of high tea; Caroline Brooke throws a pool party; Ayan picks a bone with Nina; Sara’s unsolicited advice leads Caroline Brooke to question her relationship with her.', '2022-07-13', 44, '/arLluxe2DaRkzj5ou3oWZOzZ68R.jpg', '2026-04-03T16:35:07Z', '2026-04-03T16:35:07Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('a8f0ed1a-22d9-4413-9947-fda63f5ab3a2', '991e78f1-03a5-4d26-8f75-75e11db4243c', 11, 'When Things Get Broken: What a Computer Can and Cannot Do', 'Rogers enters with a computer mouse and introduces viewers to a different room of the television house. He introduces viewers to the online neighborhood ([1]). Mr. McFeely shows a video on how a computer mouse is fixed. In the Neighborhood of Make-Believe, King Friday and Queen Sara are searching for the "royal mouse". He has been in the Museum-Go-Round, busily planning a surprise with Lady Elaine.', '1999-04-26', NULL, NULL, '2026-04-03T17:35:48Z', '2026-04-03T17:35:48Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('a8f181f2-e094-4ebd-bebf-547d79d384d2', '4fe93658-c463-4329-8e64-9d523869c2cb', 10, 'Chumdog Millionaire', 'Travel back in time with the Pawn Stars as they encounter an 80''s icon - a DeLorean sports car. Will the gang set the tires ablaze in search of its flux capacitor or is this automobile''s best years all in the past? Then Rick and the Old Man meet a man hoping to sell a letter from President Franklin D. Roosevelt. Will they draft themselves up a New Deal to buy this piece of presidential history or will their campaign lose ground? And later, Rick, Corey and Chumlee have an opportunity to appear on the game show Who Wants to be a Millionaire. Will they jump into the hot seat and go for the big bucks or will Rick''s final answer be no?', '2010-10-18', 21, '/dgRG55RkeWSO1oBSCJceon8EMBy.jpg', '2026-04-03T16:34:16Z', '2026-04-03T16:34:16Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('a8f245b8-7e18-4cbc-9c1c-462478f58de2', '38bf8c20-c17c-4071-9226-7887787cf1b1', 23, 'Good Night, Knight', 'A famous marionette team is preparing to tell the story of Orlando Furioso and his battle to rescue Angelica from the curse of Fallerina.  It''s a story Leona knows by heart, and she has more than a loving desire to see this play.', '2001-05-02', 30, '/wTvXWeQZiNdrpfAAKMT8KWussYN.jpg', '2026-04-03T17:12:28Z', '2026-04-03T17:12:28Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('a8f46ec7-e565-4b6e-bf6b-eab864e992d3', '4fe93658-c463-4329-8e64-9d523869c2cb', 6, 'Ready, Set, Pawn', 'The Pawn Stars burn up the racetrack when a seller brings in a competition dragster racecar. Can the guys set a new track record and win the deal or will the negotiation stall out and finish last. Then, Rick and Corey are presented with a Japanese land mine training kit used to train American soldiers during World War II. Will the guys detect a good deal or will it all blow up in their face? And later, Corey and Chumlee check out a fully restored 1957 Dr. Pepper vending machine. Will they pop a cold one just like the Dr. ordered or will this soda machine deal go flat?', '2010-09-13', 21, '/am2RY92ZtYHOrkRAuKYezjkpjbE.jpg', '2026-04-03T16:34:16Z', '2026-04-03T16:34:16Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('a8f6dac7-d04c-4db4-9a69-447556dc5c4b', '301fb913-4e76-408f-b84b-05bf979766fe', 6, 'The Soup Nazi', 'Cooing between Jerry and his girlfriend irritates George; Elaine runs afoul of a soup vendor; Kramer loses Elaine''s armoire to muggers.', '1995-11-02', 22, '/yJ2WshTPQIbm1sSQLm3vfrRgmtl.jpg', '2026-04-03T16:34:11Z', '2026-04-03T16:34:11Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('a8ff57b2-7863-44e7-acf0-10950220c7e6', 'b8c1b631-9850-45f3-9361-cdad5571a492', 17, 'One on One: Part 3', 'Kody is confronted with the question of whether he has a favorite wife; Kody and Janelle open up about the conflict over holidays and reveal the status of their relationship.', '2023-01-08', 42, '/ybRcKzH0YIf4KLb6fJh9f4z1Nvr.jpg', '2026-04-03T16:34:32Z', '2026-04-03T16:34:32Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('a8ff7343-fd22-4b89-9399-67cebabf23c3', 'a79a245f-acab-4ebe-aee9-29867f9e52f6', 13, 'Risking Arrest Part 1', 'The Brown''s are distraught that the Utah legislator is voting to strengthening its laws against polygamy. Friends are planning a protest march, but if the Brown''s go back to Utah they could be arrested.', '2018-02-25', NULL, NULL, '2026-04-03T16:34:30Z', '2026-04-03T16:34:30Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('a9042d79-0466-4174-9ddc-30f2cad7b48a', '050d8ae1-6cc1-4018-933d-b3c3d13de856', 3, 'Episode 3', 'The Njemps of Lake Baringo: A tough test for the safari truck as Simon and Janet drive to the parched shores of Lake Baringo and meet one of the tribes struggling for survival in Africa''s devastating drought.', '1984-09-17', NULL, NULL, '2026-04-03T17:21:57Z', '2026-04-03T17:21:57Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('a9062c19-e715-4683-88c4-135bc297c5a7', 'b5ab3a72-bc79-4e9b-a531-96739afd7aea', 11, 'The Fiddle', 'Emily brings in an old bucket with a hole in it, which turns out to be the home of a leprechaun, an old friend of Bagpuss, and his magic fiddle plays some tunes for everyone.', '1974-04-23', 15, NULL, '2026-04-03T17:23:58Z', '2026-04-03T17:23:58Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('a906fa7a-e46e-46a9-894f-9e3ca495f9be', '8c3cfac1-d882-4904-b38c-d1981628d00e', 1, 'Episode 1', 'Expedition USA  Hollywood, Houston, New Orleans and Washington are all on the itinerary of Blue Peter''s whistle-stop tour of the USA. Today Lesley and Simon join in the New Orleans 4 July Independence Day celebrations, complete with a dazzling fireworks display.

The human members of the team look pretty much the same. but Goldie, TV''s most famous golden retriever, has trebled her size since she last appeared on the programme! Blue Peter film cameras were down on the farm at Dethick, in Derbyshire, to record Simon''s reactions to his monster pup on his return from the USA.', '1978-09-11', NULL, NULL, '2026-04-03T17:21:54Z', '2026-04-03T17:21:54Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('a90c49d2-844c-4aeb-ba73-117f3cd6260a', 'f79f69a8-e591-41d0-9d4a-3d9683defbbb', 9, 'Loose Lips and Relationships', 'Jenn and Tamra put their issues to rest and plan a triple date. Eddie confronts Ryan about all the rumors. As Heather nears the finish line with her L.A. penthouse, she ventures into new territory with a unique business venture and a surprising offer. Shannon strategizes how to handle discussions of her romantic relationship. Emily and Shane work through parenting issues. Gina brushes up on her real estate skills.', '2023-08-02', 44, '/i5wZiqKNJkRZSWHna5G5oWpYM07.jpg', '2026-04-03T16:35:35Z', '2026-04-03T16:35:35Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('a918c10b-2c78-4d37-bf62-41b64f55b412', 'a9657e86-4135-49ce-b1f9-c295113077e1', 24, 'El Día del Maestro', 'Enrique and his friends help out in the El Día del Maestro, a concert held every year on a different day in Dragon Land for Quetzal. Meanwhile, Cassie must learn to be a good teacher on how to make chalupas.', '2005-03-02', 30, '/gFDM0SqVpMQEjii56k5ezxKYbmz.jpg', '2026-04-03T15:26:04Z', '2026-04-03T15:26:04Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('a91a6d22-8966-43bc-b61f-57574495dfbc', '225b0f03-984b-47f3-a1a3-d3e92175e39d', 2, 'Episode 2', 'with Christopher Trace, Valerie Singleton and John Noakes.', '1966-09-22', NULL, NULL, '2026-04-03T17:21:48Z', '2026-04-03T17:21:48Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('a91d1e61-278c-4fd5-b747-92103d4f826a', 'b6a0f228-7ddc-409c-b808-681b777a6704', 5, 'Mister Rogers Goes to School', 'Mister Rogers arrives with some pictures of various people around the Neighborhood. He talks about how pictures and sounds can remind you of different people who you haven''t seen for a while. To prove this point, Mister Rogers plays on the practice drum pad he purchased at Negri''s Music Shop the previous day to remind viewers of his drum teacher and Joe Negri.', '1979-08-30', 27, '/fXU2trSBkYXIxyFFdYnjcblYqXo.jpg', '2026-04-03T17:35:42Z', '2026-04-03T17:35:42Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('a920676b-8441-4618-9759-cab820fbe982', '5b5e8b2f-0a85-4488-b3dc-3d8b794e6582', 20, 'Reunion (1)', 'The ladies reunite to discuss the events of the 12th season with Lydia being questioned on her opinions. Vicki reports on the latest developments in her relationship with Steve, and Kelly and Shannon both dissect the state of their marriages.', '2017-11-20', 44, '/ogNZFgX46euXPv3FkDeqzJwRGe7.jpg', '2026-04-03T16:35:33Z', '2026-04-03T16:35:33Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('a9225ce1-3dcd-46e1-8e2e-c947ebc9e8eb', '18da9943-1963-4e04-a7a0-ae63802bb1fa', 11, '8 ½ Minutes to Success', 'Shannon flies to Philadelphia with daughter Sophie for her first appearance on QVC; Kelly watches her daughter Jolie audition for a musical; Steve takes Vicki on her first ride on a motorcycle.', '2018-10-01', 44, NULL, '2026-04-03T16:35:34Z', '2026-04-03T16:35:34Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('a92ff7a1-c046-4196-b92c-98c88525e4c1', '353f8b38-d837-4354-88bd-d51e98a3421a', 18, 'DELETE ME', '', NULL, 5, NULL, '2026-04-03T17:24:26Z', '2026-04-03T17:24:26Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('a930a270-67fb-4ab8-b551-b27ab3de2748', '33440d76-e69f-47ad-ac25-862ccbc9dfa1', 10, 'Friendship Is a Mother', 'Candiace hosts a special Mother''s Day brunch with some noticeable absences. Rayvin comes to town to celebrate Karen''s "Triple Twenty" and meets with Gizelle and Grace to talk college. Robyn and Candiace try to see if they can salvage their friendship.', '2024-01-21', 43, '/xc5t5DKHvA7GnLVjPcIzN6bNxxd.jpg', '2026-04-03T16:35:41Z', '2026-04-03T16:35:41Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('a934468b-ea6c-48f0-9d67-a0bc75e00662', 'bbfee3b4-9c95-48a6-beaa-791fa08b1f43', 61, 'Episode 61', 'Boxes X 2 4 2000

A giant tree transplant completes the move of Blue Peter''s souvenirs for the year 2000.', '1984-04-12', NULL, NULL, '2026-04-03T17:21:56Z', '2026-04-03T17:21:56Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('a9361f15-efa6-48dc-92aa-7b82e7a07e96', '3269a890-bba9-4e6c-9278-f7eb38eb1720', 11, 'Waves', 'Energy, things like light, heat, and sound, moves in waves. You’ve probably seen waves in the ocean, or ripples when you throw a rock in a pond. Moving energy is not like the wave you do with your hand.', '1995-04-21', 26, '/nhTm54m4ldcGF8NzPIgu8pd3itw.jpg', '2026-04-03T17:37:21Z', '2026-04-03T17:37:21Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('a9375623-23b4-47f8-a23f-f57c664122eb', '698a60df-8ed4-4ca9-bcb1-ebab343dacdd', 11, 'The Contest', 'George''s mom lands in the hospital; a contest begins among Jerry, George, Kramer and Elaine, involving a naked woman and an attractive man.', '1992-11-18', 24, '/q8vTMeNDqsRuw6Q31fKCUbvYC1W.jpg', '2026-04-03T16:34:10Z', '2026-04-03T16:34:10Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('a93cbcf5-4c55-4087-bb4f-70b86427ce0d', '56428e5e-7daa-468d-8bd2-076956507aa8', 19, 'Atmosphere', 'The air that surrounds Earth is called the atmosphere. Compared to the size of the Earth, the atmosphere is very, very thin. It’s made from gases – mainly nitrogen, oxygen, and water vapor, with a little argon, carbon dioxide, xenon, neon, helium, and sulfur. The atmosphere does a lot for Earth. It blocks ultraviolet light and burns up a lot of meteors. It traps in heat, keeping Earth cozy. Even clouds are formed in the atmosphere – keeping the Earth wet with rain.', '1994-12-03', 26, '/ugOMSgOolgd1nbGzIhVLU3GQ1MX.jpg', '2026-04-03T17:37:21Z', '2026-04-03T17:37:21Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('a942a96d-3cc0-479c-99e2-03aa0da067e9', 'b598da2e-89fd-4e98-8d0d-4bce6bbd4ac9', 6, 'Kris Kristofferson & Rita Coolidge', 'Sketches/Songs: ""Help Me Make It Through the Night"", Gonzo''s Act, ""Muppet Labs"", ""My Wild Irish Rose"", ""Muppet Newsflash"", ""We''re All Alone"", ""A Frog He Would a Wooing Go"", ""New York State of Mind"", ""An Actor''s Life For Me"", ""A Song I''d Like To Sing""', '1978-12-22', 26, '/hvE39JTNwDx1XZyfJtwjTIWk0zT.jpg', '2026-04-03T17:35:24Z', '2026-04-03T17:35:24Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('a94d1d72-fba1-45c2-b1cd-217452361020', '1be79a20-de33-41d1-af17-079035b18d5c', 51, 'The Art Contest', 'Sponsors: E, O, V, 10', '1970-01-19', NULL, NULL, '2026-04-03T17:36:28Z', '2026-04-03T17:36:28Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('a94ececd-7c5e-42b8-866d-7b7801366b8f', 'ca19f895-1514-4988-a709-95e84eab7cee', 4, 'The Spy Who Pawned Me', 'Rick checks out a collection of James Bond movie trading cards. Will Rick secure the cards or will they fall into the fiendish hands of Spectre? Meanwhile, a seller brings in an old Chinese bell, will the deal be music to Corey''s ears? And later, Chum and Antwaun set sail on a trip to Lake Tahoe to check out a vintage sailboat. Will the sail withstand the perils of negotiation or sink to the depths of no return?', '2020-11-30', 42, '/rWvCWoh5K8ZO5rJTN30q2IpYG0b.jpg', '2026-04-03T16:34:22Z', '2026-04-03T16:34:22Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('a9504e0c-5f40-411d-8edc-e83d10a52149', 'bf722849-cddb-452b-9c0f-7f0d96e94c26', 2, 'Honesty', 'When Zach Nichols breaks one of his father’s cameras, he concocts a story to escape blame. However, three cautionary stories he hears up at Plato’s Peak make him see the "big picture", and convince him to confront his father with the truth.', '1996-09-02', 30, NULL, '2026-04-03T17:38:34Z', '2026-04-03T17:38:34Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('a9543c74-a2fa-4dd5-a9f9-d9044bf7ed79', '5704fb3f-fbbc-4177-88b0-9226373a9d4e', 15, 'Episode 15', '', '1965-12-31', NULL, NULL, '2026-04-03T17:20:12Z', '2026-04-03T17:20:12Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('a95525bd-2eff-4cff-baae-53c8ab87b699', '98d80972-e53a-43dd-a03a-7703465e6f87', 30, 'Shekel and Hyde', 'Empty your pockets with the Pawn Stars when the guys eye a 2,000 year old Shekel of Tyre. The same type of coin given to Judas to betray Christ, will they make a deal of biblical proportions? Then, Rick and the Old Man are up in arms over a pair of engraved Colt pistols from the 1860s. Worth a small fortune if they''re factory engraved, can they connect them back to the Colt Armory? And later, when one of Rick''s purchases turns out to be stolen, will the guys ever let him forget it?', '2013-02-25', 21, NULL, '2026-04-03T16:34:18Z', '2026-04-03T16:34:18Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('a95856a9-4d7d-4e01-9c64-319d3bc29de3', '7bc54df3-f32a-454e-aef6-a9436c35d53b', 18, 'Episode 18', 'Rogers enters with a typewriter and the many ways to put the word "typewriter" to paper. In the Neighborhood of Make-Believe, an artist draws paintings of King Friday and Queen Sara.', '1970-02-25', NULL, NULL, '2026-04-03T17:35:39Z', '2026-04-03T17:35:39Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('a95ceaa5-c92a-47fb-bb97-9d01df5b1389', '6f81c872-cdb9-42dd-8377-2c17cb6ed4d7', 35, 'Snazzy Society (repeat)', 'When Segi becomes upset after reading a book about her favorite character, Mando, Chris and Leela help her see that being brown is snazzy. Guest star: Lupita Nyong’o.', '2017-09-02', NULL, '/x4O3FiAjsO1hsnqDHOE16C1PtE0.jpg', '2026-04-03T17:36:48Z', '2026-04-03T17:36:48Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('a965a137-299d-40c7-86ae-96ef97aa119d', '97a3d1f5-a8f1-47cd-8122-2e74a092836d', 8, 'Get the Message (4)', 'With the team reunited and Ghostwriter back. the team puts a phony ad in the paper to catch the art thief.', '1993-10-24', NULL, NULL, '2026-04-03T17:40:28Z', '2026-04-03T17:40:28Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('a9703f1c-3fad-4dd2-b30a-a1901f87e977', 'ecb64ef3-4f80-45a7-b4a9-c04434b02e35', 22, 'Bang Bang', 'Join the front lines with the Pawn Stars, as Rick gets spooked when a WWII embalming kit invades the shop. Will Rick be able to dodge its gruesome history to make a death-defying deal? Then, Corey and Rick get fired up over a pair of Reid knuckle duster pistols. Can they hit the bull''s-eye with these rare guns or will the deal end in a standoff? And later, Rick has plans for a new company website, but Chum has plans of his own.', '2014-03-13', 21, '/wUcK15GWYaUkvqZjvvBMRSWvTqX.jpg', '2026-04-03T16:34:19Z', '2026-04-03T16:34:19Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('a975812e-decd-4c80-9b97-e8135668542c', '432a6abd-dcca-44cc-82ce-fb39e33b8949', 4, 'Episode 4 (#1134)', 'Rogers discusses the about string quartet (e.g. violins, banjos, guitars) and hears each instrument at Negri''s Music Shop. In the Neighborhood of Make-Believe, Mr. McFeely delivers a bass fiddle to King Friday.', '1971-02-18', NULL, NULL, '2026-04-03T17:35:39Z', '2026-04-03T17:35:39Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('a976fbff-685c-47c7-9dbc-265bc3290a1b', 'fe19a277-aed8-44df-a4ac-fc1c4e9941b4', 11, 'High Heels & Record Deals', 'NeNe organizes an over-the-top high heel marathon for her Twisted Hearts Foundation. Lisa and Ed make a tough decision about his NFL career, and Lisa takes a pregnancy test. Despite her engagement with Big Papa, Kim moves forward with starting her wig business. Kandi confronts Kim about not attending her show, and then flies to LA for an important meeting at Capitol Records about a possible record deal. Shereé shoots a promo video for her upcoming fashion show, but Dwight is so not into it. NeNe meets with her uncle and must decide if she’s finally ready to meet the man who claims to be her biological father face-to-face.', '2009-10-08', 43, NULL, '2026-04-03T16:34:45Z', '2026-04-03T16:34:45Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('a9779025-a985-492a-80e9-319ac21b8cf4', '4892e2af-46c1-4b4e-ac81-eac161b5a347', 19, 'Episode 19', '', '1977-11-14', NULL, NULL, '2026-04-03T17:21:53Z', '2026-04-03T17:21:53Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('a9786769-c32e-403d-a1a1-550a50e19bf7', 'ae8f64d9-4b83-4147-a44c-bfe720381f8e', 12, 'Mary, Mary Quite Contrary', 'Mary Mary Quite Contrary walks along Sesame Street and dumps a pile of dirt outside Oscar’s trash can. Gordon explains that she can not leave the dirt; she is making a mess! Mary Mary insists that she is going to grow a garden with silver bells and cockle shells. Gordon tries to tell her that silver bells and cockleshells aren’t alive. Gardens need to have things growing in them, like vegetables, fruits or flowers. Mary Mary decides she will grow flowers in her garden by using dirt, sun, and water.

Later, Alan and Gina walk by Oscar’s trashcan and comment on the beautiful garden. But Oscar doesn’t like it! He wants Mary Mary to move her garden.

As Mary Mary plants more flowers, Oscar decides to have his elephant, Fluffy squirt water at her. Maybe that will get her to move? But as Mary Mary explains, the water helps her flowers to grow. Oscar doesn’t know what to do! He sends over Hairy Hairy, from the Grouch nursery rhyme, with stinky weeds and moldy seeds and three pigs, but even that doesn’t get rid of Mary Mary and her garden. Suddenly, Oscar changes his mind. He likes the horrible smell from the stinky weeds and loud noises from the pigs. It’s a Grouch paradise! Mary Mary finds this out and decides to move the garden.  She likes to be contrary and do the opposite of whatever anyone wants her to do. Mary Mary moves her garden while Gordon happily cleans up the remaining dirt!', '2009-11-30', NULL, '/rv6D5wXt2wX8M9wXDwd4MSkuIXX.jpg', '2026-04-03T17:36:46Z', '2026-04-03T17:36:46Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('a97b378f-05ff-47a2-bc44-92cf40ee5a7c', '8b07363e-5f54-45d6-b036-b43793f7af74', 10, 'Pick a Car, Any Car', 'When the Read family car breaks down, Arthur is heartbroken. He wants to save the vehicle before his parents replace it.', '2002-11-25', 13, NULL, '2026-04-03T17:37:57Z', '2026-04-03T17:37:57Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('a980864e-49b1-47a9-bfe7-a485c3765767', 'f15647d3-c8bf-4e37-a6bc-589853787f3b', 7, 'Do the Bright Thing', 'Nick and the others learn another life lesson on making wise decisions, especially when Nick was planning on buying a new drawing table before settling on a sketch pad.', '1989-07-16', 30, '/rvPAa5EjJMlmj9tJgtoTft8uL8S.jpg', '2026-04-03T17:40:08Z', '2026-04-03T17:40:08Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('a9809857-94d3-4b4f-b230-1b1253f1f3f2', '740a96a0-a075-4be2-be92-a178d0939384', 32, 'Abby and Zoe Love Karate', 'Nina teaches Abby and Zoe all about karate. After learning how to focus and practice, Abby and Zoe manage to kick a ball off a stand with a special karate kick.', '2018-06-23', NULL, '/A2VqtsfeSjc1WNJcYiFOTkOOVkX.jpg', '2026-04-03T17:36:49Z', '2026-04-03T17:36:49Z');
