INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('a9949fdf-36f3-4403-a293-367325c0eec7', '05c0e384-194c-4417-9f62-803eb615e409', 70, 'Glass', 'Title number 0070. Opens with Mister Rogers arriving with a briefcase containing glass blown animals made by Mr. Zandhuis, who then comes to show how glass is blown into different shapes, such as a swan. Henrietta must tell everyone how to get to "Someplace Else", which is where Donkey Hodie lives. Lady Aberlin coerces the king to come with them by telling him one of his famous speeches is expected. Everyone travels from the Neighborhood of Make-Believe to his mysterious home at the Windmill so that Donkey Hodie can get his wish of visitors all day long. Mr Rogers sings "Once Upon Each Lovely Day".', '1968-05-24', 28, NULL, '2026-04-03T17:35:38Z', '2026-04-03T17:35:38Z');
