INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('a9c93ece-6ae0-49d6-893f-b558787b0d7f', 'fa6f43f4-b944-4c33-ac69-dddbf54c0c16', 1, 'Rapunzel', 'From High atop a tower, a beautiful young woman lets down her hair - and lets in love. Thats the time-honored story of Rapunzel. Shelly Duvall, producer of the entire Faerie Tale Theatre series of which Rapunzel is a part , stars as the maiden.Jeff Bridges is the prince who climbs to Rapunzel''s balcony via her long , long hair.And Gena Rowlands is the lovely, but wicked witch who tries to keep them apart.', '1983-02-05', 51, '/2dY9STZD8EfuKvc61tQDEt5sEKD.jpg', '2026-04-03T17:38:40Z', '2026-04-03T17:38:40Z');
