INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('aa643f12-6bdf-41f1-ac55-44041bc7f5df', '78a02d50-e3dc-4549-844a-3cf357a32ef4', 21, 'Reunion Part One', 'The historic four-part reunion kicks off and things get heated when Kenya and Shereé go head-to-head in a battle of the baseboards, addressing the drama surrounding building their dream homes. Phaedra and Kenya discuss the highs and lows of their friendship to determine if there is any hope at saving their rocky relationship. Tensions rise when Kenya questions the effectiveness of Porsha''s anger management, which leads to a fiery verbal encounter between Kandi and Porsha.', '2017-04-16', 43, '/5AheYgLMv1u8opnJt4xRFsJMxiN.jpg', '2026-04-03T16:34:48Z', '2026-04-03T16:34:48Z');
