INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('aa75f3f9-40c7-47b7-aea5-339b4b96209e', '3430d881-14a2-497d-9cf4-351b78b6aa6a', 7, 'Postman Pat Paints the Ceiling', 'Pat offers to paint the ceiling for Granny Dryden. Some paint spills down Pat''s trousers! Pat goes home to change and gets an odd pair of trousers and Sarah can''t help laughing. During his rounds, everyone wonders why on earth Pat is out doing his rounds in shorts.', '1997-05-15', 15, '/6DQ4ex5A2clR1hhUS2dJ8v1vKq9.jpg', '2026-04-03T17:14:30Z', '2026-04-03T17:14:30Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('aa79ad88-e15a-46df-99d8-9844cc003739', '5c1b881f-ac58-4d72-b63f-209952d4f902', 39, 'Episode 39', 'Operation Oily Bird  A mysterious oil-slick off the coast of Somerset has resulted in the biggest bird rescue operation since the Torrey Canyon disaster. Tina helps John Hughes, Warden in charge of the RSPCA''s animal centre at Little Creech, near Taunton, clean up some of the 2,000 guillemots and razor-bills whose lives are in danger.', '1980-01-24', NULL, NULL, '2026-04-03T17:21:54Z', '2026-04-03T17:21:54Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('aa7ba6d2-1b7d-43ee-b256-0bdecc9c0627', '876145f4-b55e-4070-b35b-893a67f88bac', 17, 'Reunion Part 1', 'The reunion kicks off with Melissa, Margaret, Jackie, and Dolores sparring with Jennifer; Teresa remains loyal to her friend; Jackie reveals surprising details about her eating disorder; Dolores comes to a shocking conclusion about her relationship.', '2020-03-04', 43, '/fmpWVnySwQ2Cjo3XXbJDpnTkpb0.jpg', '2026-04-03T16:35:18Z', '2026-04-03T16:35:18Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('aa83eafb-e0c0-4496-970e-9c3edc845bbd', '150d1480-f3f1-43f9-9a22-d2527756fba2', 16, 'Crab-Boiling Over', 'The group wraps up their trip with a crab boil - and things between Ashley and Gordon get heated. Upon their return to Potomac, Mia''s relationship with her mother takes a turn for the worse, and Gizelle''s daughters confront her about her relationship woes.', '2021-10-24', 42, '/pODrnIRp7TRvx0bHtiGbF3Bujz2.jpg', '2026-04-03T16:35:40Z', '2026-04-03T16:35:40Z');
