INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('aa857d29-f558-4c01-9c23-2329dc3e71a1', '91f66da7-56a2-423a-b855-f09d582805b2', 8, 'The Three-Legged Pot & When Jabo Jammed', 'Leona makes a three-legged pot dance; a boy named Jabo doesn''t dance or sing, but he can jam.', '2007-11-05', 30, '/oOwr4iYzc5OovtnuAKzuC4fLJcg.jpg', '2026-04-03T17:12:29Z', '2026-04-03T17:12:29Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('aa94ac4a-071b-4420-88d9-7aada25a0625', '90cc8678-a14f-4d05-bc1e-54a3117895d5', 7, 'The Feud Begins', 'The animals grieve when Dreamer, Fox and Vixen''s cub is found dead. Although it cannot be certain as to the cause of death, Fox believes that Scarface is to blame. The impulsive Bold slips away and wanders into Scarface''s land, where he meets Ranger, Scarface''s son and tries to become friends. Scarface spots them and imprisons Bold in his earth.   Fox and Friendly enter Scarface''s land in an attempt to rescue Bold, but soon become surrounded by blue foxes. Fox manages to convince Scarface to allow Friendly to return home.    Meanwhile Bold was able to cunningly escape just as his father and brother trespassed onto the blue foxes'' territory.   Weasel informs the White Stag about the situation and he steps in to prevent any feuding. Fox is allowed to return to Farthing land, only to find Bold was already there. Fox is infuriated with him and tells him that he will remain where Fox can watch him at all times and is not to wander off. Bold can not take it and feels the park isn''t big enoug', '1994-02-18', 25, '/phRnUuUq6MwRnH0Bm1ZXdv0yU9L.jpg', '2026-04-03T17:18:49Z', '2026-04-03T17:18:49Z');
