INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('aaa7a759-e8ca-4e1a-b524-5ff0852e57d8', '9f448cb8-07f8-4040-840b-c8690371ec41', 4, 'The Little Kicks', 'Elaine''s staff loses respect for her after seeing her dance; George benefits socially when Elaine labels him a "bad seed"; Kramer''s friend forces Jerry into crime.', '1996-10-10', 22, '/aO5blG5gd4MVYaeaFc413Fds6fr.jpg', '2026-04-03T16:34:12Z', '2026-04-03T16:34:12Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('aaa803a6-583c-45c5-8fd6-1264c5b3dd9f', 'b1d55597-d9d2-4eee-ab95-46dbb163291a', 8, 'Pingu and the Avalanche Incident / Barrel of Fun', 'Robby plays around some barrels near some ruins, when he sees a barrel that is half covered with planks, like a sledge. Pingu comes around and he and Robby play with the sledge-barrel. They go down a long and winding hill two times, with Robby being the brakes - almost crashing into a sculpture both times. Unfortunately, when they go down a third time, they lose control, and Robby falls off and Pingu crashes into the sculpture which collapses over him, trapping him inside. Robby goes for help, and gets an emergency paramedic to lift a slab of ice from the rubble in order for Robby to slide under and get Pingu. He gets Pingu out just before the paramedic''s arms give way to the weight of the slab. The paramedic then puts a patch on Pingu''s head, and he, Robby, and the paramedic leave.', '1988-10-29', 5, '/a9HHpnoo4JJ1Dqjx3SKrspRCc49.jpg', '2026-04-03T17:22:18Z', '2026-04-03T17:22:18Z');
