INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('aab449da-188c-41c0-8776-7e9c277d3fc6', '34bdccfa-3c14-4e1c-9148-85c29aadc0e1', 15, 'The Great Bear Show', 'A camping trip in Canada drives Chris and Martin to see the great bear and, in particular, how it gets food.', '1996-06-21', 30, NULL, '2026-04-03T17:11:47Z', '2026-04-03T17:11:47Z');
