INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('ab1b1d13-6887-458a-9650-ef3820cf0595', 'fed71eea-5d41-479c-b12a-beb733409c5c', 27, 'The Cookie Thief', 'A brand new museum has opened on Sesame Street, the Museum of Modern Cookie! Cookie Monster, Elmo, and Chris are very excited to check it out. However, when they step inside, all of the cookie art starts to make Cookie Monster hungry for cookies. Chris explains that he needs to control himself and use only his eyes to look at the paintings.', '2015-02-16', NULL, NULL, '2026-04-03T17:36:48Z', '2026-04-03T17:36:48Z');
