INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('ae024b8e-7035-407c-9a5b-28519ac04a45', '58adb9ab-3f1b-4a11-87b6-9b0b2dbb6aaf', 3, 'Oh Holy Pawn!', 'Get holy with the Pawn Stars as Rick gets the chance to purchase a page from the Gutenberg Bible. Known as the first printed book, will the single page break Rick''s bank or leave him wanting more? Then, Corey checks out a rare six-sheet movie poster from the classic "Ziegfeld Follies" that''s so big it doesn''t even fit on the counter. Will he offer a larger than life price, or leave the seller singing in the rain?', '2017-04-17', 21, '/4694GwQVaN7sxl7BVnzIiqjKzNt.jpg', '2026-04-03T16:34:21Z', '2026-04-03T16:34:21Z');
