INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('ae06c09d-fac3-4b5e-b3a6-737dc55482e0', '5a771f52-fe96-4ea2-b567-a8dde899059e', 22, 'Blades of Deal', 'Rick drives up to a 1984 Ferrari 308 that he hopes to drive off with. Can he accelerate a deal, or will the high asking price throttle negotiations? Corey is all ears when a seller brings in a phone-operated music player from the 1930s. Rick throws his hat into the ring for a cowboy hat owned by Larry Hagman of the TV shows "Dallas" and "I Dream of Jeannie." Later, a Vegas Golden Knights hockey jersey signed by goalie Marc-André Fleury gets an icy reception from Chum and Rick - until Fleury himself skates in to tell them whether it''s authentic.', '2018-02-26', 21, '/sgJXVkvZcUrS94owBWxsYLZ7M1L.jpg', '2026-04-03T16:34:21Z', '2026-04-03T16:34:21Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('ae06e994-65be-47c7-9523-09b34408f4d2', '4d2cac0f-38fd-438b-8afa-acf43952e535', 146, 'Episode 146', 'For younger viewers. Introduced by Christopher Trace and Leila Williams. Including: More About Brownies: 3 and The Absent-Minded Professor, an excerpt from the Walt Disney film.', '1961-08-14', NULL, NULL, '2026-04-03T17:21:47Z', '2026-04-03T17:21:47Z');
