INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('ae0bd76d-9fe6-407f-af84-92a6d4a5d2b8', 'bb5a8843-6181-4a6d-bfdf-33ef2c6be7b8', 3, 'Chateau Get Down', 'Porsha clings to her family after losing yet another friend, but is shocked by accusations from her sister. Meanwhile, a new man challenges Cynthia''s singles game. After an unexpected incident, NeNe is suddenly left home alone to fend for herself, while Kenya struggles to find new ways to connect with her long-distance husband. Shereé plans to turn the Chateau into a disco palace, only to have the dance floor pulled out from under her when the party planner leaves her in a serious bind.', '2017-11-19', 43, '/51GfkrmZ6nAjFIFbtnDTlmYtDHF.jpg', '2026-04-03T16:34:48Z', '2026-04-03T16:34:48Z');
