INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('ae144b4a-11b6-477f-a699-0bdd0b9d4287', '54facb0b-db59-41fe-9d64-c7c7221a3c81', 4, 'Making Up Is Hard To Do', 'Bethenny throws a lunch sit-down with Dorinda and Luann so the two can hash out their issues. Later, Luann begins her court-ordered community service and discusses her first meeting with her parole officer. Tinsley gets a visit from Dale, who puts pressure on her to figure out what''s going on with Scott. Ramona goes on a blind date, while Barbara is shown the door by Dorinda.', '2019-03-27', 60, '/uT2x2QuMSaj6KfM75DyEUFLXBB7.jpg', '2026-04-03T16:35:25Z', '2026-04-03T16:35:25Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('ae1881e8-b4f0-485b-b1ad-724384aa5bef', '96dd06ee-d44a-47f3-9372-e29e8eaa77f5', 1, 'Treasure Hunt', 'Sam introduces Sarah and James to his new metal detector, and they get hooked on looking for treasure. Unfortunately, they manage to burst a water pipe in the park while searching for Bella''s keys! Meanwhile, Norman''s game of ''Knights Of The Round Table'' backfires when his saucepan helmet gets stuck on his head. Overall, it''s a busy day for Sam and the crew...', '1988-09-01', 10, '/j8CQwbECH2Yh8HQQ9hFXvGjPYKd.jpg', '2026-04-03T17:14:37Z', '2026-04-03T17:14:37Z');
