INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('ae41421f-810c-4c99-adac-46db223077d5', '227b8429-0dfd-47e4-b874-c37da20c403f', 10, 'Rick''s Big Bet', 'In this episode, Rick refurbishes a gas pump with a bird''s nest inside, Corey takes a quiz after misidentifying a Faberge crystal glass - if he loses, he works graveyard, if he wins he gets $2500, - and Rick buys some bayonets.', '2009-08-30', 21, '/jGAWeACMSJYmqufmh09eSpVlgAx.jpg', '2026-04-03T16:34:15Z', '2026-04-03T16:34:15Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('ae4429ff-39e6-46c9-8b7e-386d1a20c480', '36ea3814-66b4-4986-b6ee-44559d3562c1', 15, 'Dropping the Ball', 'As a peace offering, Kenya wants to host a masquerade ball that will benefit NeNe''s charity of choice. Porsha attends her audition for Kandi''s musical. Mama Joyce returns to discuss Kandi and Todd''s relationship.', '2014-02-16', 43, NULL, '2026-04-03T16:34:46Z', '2026-04-03T16:34:46Z');
