INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('ae4cfebc-0b3e-4f9f-a811-2dc5ee7ee7f9', '7c756336-29db-4634-b976-e993e8f51da2', 10, 'Welcome to the Bermuda Triangle', 'A "bonding" excursion to Bermuda turns cold when some of the women are shut out of the trip. Robyn makes a critical relationship decision. Monique and Gizelle at last address their issues. The ladies take a sunset cruise.', '2017-06-11', 42, '/bXmoX7NsXoc7fl7r5Uk1k1iPlwD.jpg', '2026-04-03T16:35:39Z', '2026-04-03T16:35:39Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('ae50c830-d7c2-427c-bc26-d381a13623ea', 'dfa60f31-6ef1-4bee-a9ad-554b68a5448b', 5, 'Africa''s Deadliest Snakes', 'Steve journeys to Kenya in search of some of Africa''s most venomous snakes, including the black mamba and cobra.', '2001-02-12', 44, NULL, '2026-04-03T17:39:11Z', '2026-04-03T17:39:11Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('ae53bba5-7f76-4769-9ee2-06a0bc624a28', 'd1863f2f-02ec-40ce-af64-db03fbe518a7', 3, 'Grover''s Street Safari', 'Grover takes Elmo and friends on a Sesame Street Safari and they pretend to be all of the wild animals they see. Also featuring Cookie Monster''s Smart Cookies, and Elmo the Muscial-cowboy. Brought to you by the letter S and the number 5.', '2016-01-23', NULL, '/3sNWZpGWPwg8N9AVdLndzqY1t9g.jpg', '2026-04-03T17:36:48Z', '2026-04-03T17:36:48Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('ae54a75d-ae5e-4d73-9900-6b639b56cf68', '56428e5e-7daa-468d-8bd2-076956507aa8', 15, 'Forests', 'In Bill Nye the Science Guy: Forests, Nye shows students the levels of a forest, which include the canopy, the under story, and the floor. His special guest is Nalini Nadkarni, who has no qualms about going high up in the canopy to check out the wildlife and other happenings there', '1994-11-05', 26, '/53Pkvk4kTYXZ8VBTBLwKrTlfSF8.jpg', '2026-04-03T17:37:21Z', '2026-04-03T17:37:21Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('ae569da5-ddd5-43df-ace5-52eb888351be', 'bd8a516b-9872-472d-a838-7aff1070fea3', 16, 'Cleo Laine', 'Sketches/Songs: "Limbo", "Ain''t Got That Swing", "Pigs In Space", Bruce Schwartz, "Mad Dogs and Englishmen", "Swedish Chef", "(I Wonder Why) You''re Just In Love", Fozzie''s Act, "If"', '1978-01-15', 26, '/xQyUpb5I5PeEubRRTQOC7Q00wJm.jpg', '2026-04-03T17:35:24Z', '2026-04-03T17:35:24Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('ae645da7-edb8-42f3-a2dc-9d325528d65d', 'bf874be3-7e2f-4a0e-b205-c76ac1ad69fc', 74, 'Inside Looks (on The Marine Biologist)', 'Inside look from the season 5 episode "The Marine Biologist."', NULL, 22, NULL, '2026-04-03T16:34:09Z', '2026-04-03T16:34:09Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('ae6f355b-d4f9-409b-a291-b347d23d9431', 'de8ec769-16bb-436b-be43-aedc7e18a7d7', 15, 'There''s a New Count in Town', 'Charlie is counting everything on Sesame Street so the Count decides to leave, thinking he’s not needed anymore. But there’s too much to count for Charlie on her own so she asks for the Count’s help. Charlie explains that she loves to count but she could never take his place. The Count agrees to stay and he and Charlie continuing counting together.', '2020-02-22', NULL, '/7E409c5zSU9wZLrjmVKeGalfNTP.jpg', '2026-04-03T17:36:50Z', '2026-04-03T17:36:50Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('ae6f8d8d-1643-45d7-990e-f135f79fcea9', '0a9aba05-559f-4db4-a6ca-8ac35cc378d1', 8, 'No One', 'While Jaime weighs his options, Cersei answers a request. Tyrion''s plans bear fruit. Arya faces a new test.', '2016-06-12', 59, '/xl2l1a3kXGxWwZqGDgjowBk4x46.jpg', '2026-04-03T15:40:37Z', '2026-04-03T15:40:37Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('ae76db19-8d42-4afe-8a50-2b8deb29f221', 'f4c40307-9b5e-4263-a4e0-dfa138131e7f', 17, 'Elmo Says Boo!', 'Elmo visits The Count''s castle to tell him funny scary jokes. Classic Sesame Street segments are separated with new joke segments set in the castle''s exterior, featuring one Sesame Street character and a child, and interior, featuring The Count, Elmo, and some combination of the Bats, the Skeleton, a painting of the "Groana Lisa," a suit of armor and the Count''s pipe organ.', NULL, NULL, NULL, '2026-04-03T17:36:27Z', '2026-04-03T17:36:27Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('ae77d471-618b-47c2-9d3c-36fd937987ea', '5ba20443-d99f-4820-81f6-6832d3f2bc4f', 20, 'Time', 'Time affects every living thing on Earth. Trees shed their leaves. Some animals only come out at night. There are even insects that only emerge every 17 years. Days, hours, minutes, and seconds – all of these were invented by humans. Humans came up with these units of time to organize their lives and to study the world. One of the first ways humans told time was by noticing the difference between daytime and nighttime. Humans use the Earth revolving around the Sun to divide time into years and seasons. Months are based on the movement of the Moon around the Earth. A day is when the Earth spins completely around its own axis.', '1997-09-12', 26, '/oDIJvvZpEpecmwiMyRM2d90Md6L.jpg', '2026-04-03T17:37:21Z', '2026-04-03T17:37:21Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('ae78c082-7383-43d8-813e-417aaa8469a0', 'd1863f2f-02ec-40ce-af64-db03fbe518a7', 2, 'Mucko Polo, Grouch Explorer', 'With Mucko Polo (Alan Cumming), Elmo, Abby, and Oscar use their five senses to explore and search for the grouchiest things on Sesame Street. Also featuring Grover finds a pyramid and Elmo the Musical-Guacamole. Brought to you by the letter E and the number 6.', '2016-01-16', NULL, '/cY20trMI7vps2VWJE6HIspzRkgI.jpg', '2026-04-03T17:36:48Z', '2026-04-03T17:36:48Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('ae837ce1-3c9a-43f5-ae66-e0a3e47258d3', '3d4d8f6a-9708-47e8-9c99-26ebafdb2609', 27, 'Episode 836', '', NULL, NULL, NULL, '2026-04-03T17:36:41Z', '2026-04-03T17:36:41Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('ae852386-8eca-48d9-9b9f-948ea530daf9', '994c75e5-06fa-4be1-a142-ea7b2c892dd0', 1, 'Curiosity: A Field Trip to ''The Edible Schoolyard''', 'Rogers uses a frame to concentrate on small sections of a large mural. Seeing a set of vegetables in one section of the mural, he reflects on a visit to a vegetable garden, referred to as an "edible school yard". In the Neighborhood of Make-Believe, King Friday is irritated when Purple Panda and his compatriot, Little Panda, fool him. He commands that they cancel all curiosity.', '2000-09-07', NULL, NULL, '2026-04-03T17:35:49Z', '2026-04-03T17:35:49Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('ae863923-a0dc-41ca-8f05-9f3ed33d4631', '79916e0e-881c-43a7-b4ee-00e5052a94be', 4, 'Emily and the Rocket', 'Theodore and Emily see a large light travelling across the sky one night. They at first think that it''s a shooting star but it is later found out that it is something much, much bigger.', NULL, NULL, NULL, '2026-04-03T17:10:11Z', '2026-04-03T17:10:11Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('ae8c431e-9296-41d9-941d-7a98ef8089ee', '70d9e397-6813-4785-887d-27d034928bae', 1, 'Pingu the Cross Country Skier', 'Pingu comes out of his igloo and sees Pingo, on his skis, nearby. Pingu gets his own skis, goes to meet Pingo, and they agree to have a cross-country skiing race. As they are very evenly matched, it soon gets competitive, and Pingu tries to slow up Pingo by putting his ski-stick between Pingo’s legs. Pingo does the splits and stops, but soon gets going again and quickly catches up with Pingu. They come up to another rather older cross-country skier who is travelling more slowly and, as they go past him one to each side, Pingu surprises the other skier by shouting into his ear. The older skier is understandably none too pleased, shouting angrily and waving his stick at Pingu and Pingo as they race off ahead. Both Pingu and Pingo think this is rather funny! A little while later Pingu and Pingo start arguing again, and Pingu repeats his trick with the ski-stick. This time Pingo falls over and is somewhat annoyed, while Pingu stops and has a good laugh. Pingo makes a snowball and throws it at Pingu, knocking Pingu backwards off his skis. As Pingu gets up, the older skier comes past, stops, waves his ski-stick and tells off Pingu and Pingo. Pingu mockingly mimics the older skier, and then he and Pingo start off on their race again. Again they go past the older skier, but this time downhill where they’re all travelling faster. After various evasive manoeuvres by all three, Pingu ends up crashing into the older skier, falling over and breaking a ski. The older skier tells Pingu it was all Pingu’s fault, and starts to ski away. Pingu starts to cry, and the older skier takes pity on him and turns back. He then kindly helps Pingu get home by giving Pingu a ride on the back of his skis to the starting point of the race, where Pingo is waiting to flag them in!', '1995-06-17', 5, '/rcBdUSm28ZYil9MLm0lPnNh0yQg.jpg', '2026-04-03T17:22:19Z', '2026-04-03T17:22:19Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('ae8ff0d7-9f95-4a3f-88cf-1ba90fe35747', '7c422193-b078-49d8-81ef-f2b9f94f059d', 130, 'Big Bird and Snuffy have an adventure', 'Episode #3135', '1993-05-07', 55, NULL, '2026-04-03T17:36:39Z', '2026-04-03T17:36:39Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('ae92d4b7-7ab6-43c4-980d-57fa0cf4bed0', '671bd4da-3470-40f9-9a03-40fba34d2b8e', 16, 'The Crying Game', 'While Frankie feels the need to have a good cry after having a bad week, Mike shares the good news that, after 25 years as manager at the local quarry, he is being offered the job of regional manager but feels uncomfortable saying goodbye to his co-workers. Meanwhile, Brick suspects that he''s being treated unfairly by his health teacher because of how horribly Axl treated her back when he was a student.', '2018-03-13', 22, '/qwle7qisc1jh62dDbtgkXPn8zrC.jpg', '2026-04-03T15:40:31Z', '2026-04-03T15:40:31Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('ae9339f5-03b4-4e80-93e4-5c9c933cb82e', 'fb4ecc73-cb92-4c5c-821f-92179058b37b', 15, 'Little Miss Muffet visits (3670)', '', '1997-12-05', NULL, NULL, '2026-04-03T17:36:41Z', '2026-04-03T17:36:41Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('ae9c5073-adcf-486b-8f0c-690b5c510214', '671bd4da-3470-40f9-9a03-40fba34d2b8e', 7, 'Thanksgiving IX', 'The Hecks take a hectic road trip to Frankie''s sister''s house for Thanksgiving; the kids must decide which one of them will lose their job at Spudsy''s.', '2017-11-14', 22, '/vcaBoD1rMdCcVIVCj2zbh2vgl27.jpg', '2026-04-03T15:40:31Z', '2026-04-03T15:40:31Z');
