INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('aeb24c94-b23a-4bce-8324-f9a727d5c180', '8610109b-4fb9-4eae-be54-c549fae5ecc8', 8, 'Audio Commentary: Lolly, Lolly, Lolly Get Your Adverbs Here', '', NULL, 3, NULL, '2026-04-03T17:13:55Z', '2026-04-03T17:13:55Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('aeb2c2fd-225c-4a3f-a394-ceb472216ac9', 'b6a0f228-7ddc-409c-b808-681b777a6704', 2, 'Mister Rogers Goes to School', 'Mister Rogers takes his television neighbors to a kindergarten classroom at the local school. Prior to beginning the Neighborhood of Make-Believe segment, he disguises the Trolley as a school bus with a cardboard cover. The disguise arouses everyone''s attention in the neighborhood. It gets to the point where King Friday decrees that a school should be built in the neighborhood within three days. After scouting four locations, Lady Aberlin and Handyman Negri decide that the school should be built at Someplace Else. Harriet has agreed to be the teacher for Ana, Daniel, and Prince Tuesday.', '1980-05-22', NULL, NULL, '2026-04-03T17:35:41Z', '2026-04-03T17:35:41Z');
