INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('aebc3834-8889-46c5-a0b3-57e65ac3f955', '70c8cb46-2494-4dd4-98f6-6bfb9b3faf73', 16, 'Helmet Head', 'The Pawn Stars have a chance to shoot and score with a 2006 NBA Championship Ring. Will the gang make the big score or will a surprise Shaq Attack throw the shop off its game? Then Rick considers buying a highly collectible 1964 Austin Healey. Can Rick put the pedal to the metal for this fast British car, or will he find out the hard way there is nothing "simple" about an Austin Healey? And later a man walks into the shop with an extremely old and rare diving helmet from the 1800''s. Will Rick sink some serious cash into this piece of early sea exploration, or will he find the deal just can''t stay afloat?', '2010-04-05', 21, '/6872xeSn2skKYtLghSPNxBIhZ1J.jpg', '2026-04-03T16:34:16Z', '2026-04-03T16:34:16Z');
