INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('aecc5300-46a5-4131-b606-cf8caed5d0c5', '208e80de-61e3-4a2f-857f-c667ffc29134', 20, 'Alan Arkin', 'Alan accidentally drinks Bunsen Honeydew''s Jekyll-and-Hyde potion, and turns into a rampaging monster. He runs amuck, as the ultra-cute Bun-Bun Brothers sing "Zip-A-Dee-Doo-Dah." When Kermit catches Alan in a net, he turns back into himself. Soon, Kermit takes a sip of the potion himself.', '1980-03-07', 26, '/rPCAeUkJytR6B0Uu4EDGgGwiHak.jpg', '2026-04-03T17:35:25Z', '2026-04-03T17:35:25Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('aed473b5-ca5c-4be2-b92d-40dcddf4ea44', 'dfe2c51c-8d2c-4c92-a010-7dbb71c3e48b', 1, 'Amphibian', 'Which frog raises its young in its mouth? Why did ancient people think salamanders were born in fire? AMPHIBIAN investigates the double life of creatures that live both on land and in water. Leap into the fascinating world of frogs, toads, and salamanders, and get a close-up look at the amazing variety of colors, shapes, and sizes in the amphibian family.', '1995-06-05', 29, '/cAx21LqxU6nyMb6r4cPQNPcO3DS.jpg', '2026-04-03T17:39:04Z', '2026-04-03T17:39:04Z');
