INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('af34cefc-88a3-4e9c-b144-3d3c3675c6ff', '10e64538-c78a-4cb0-82f9-17d14256dbac', 1, 'Not Your Brother''s Drop Off', 'Sue''s excitement about moving into the dorm to start college is tempered when she accidentally burns her hair and must cut it short. Axl isn''t interested in helping with Sue''s move. Frankie discovers she''s not sad about Sue moving out of the house while Mike overwhelms Sue with financial and safety guidelines. Brick is clueless when Cindy tells him she wants to take their relationship to the next level.', '2015-09-23', 22, '/wQvbllb8xDyy5zfUHaU48bXcW2O.jpg', '2026-04-03T15:40:31Z', '2026-04-03T15:40:31Z');
