INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('af82629d-47f4-4b9a-bf76-be6e035a592e', 'ca09391a-de6a-4b2b-aefc-c2efbc80a106', 9, 'Kate Shelley and the Midnight Express', 'LeVar takes a train ride from California to Washington state. Along the way, we learn about trains and how the transcontinental railroad came to be. Brian Dennehy narrates the true story of how a young teen named Kate Shelley risked her life to save the engineers of a train that crashed into a river when the bridge near her home collapsed, and how she had to get word to the nearest station to alert them to stop the express train.', '1991-09-26', 30, NULL, '2026-04-03T17:36:17Z', '2026-04-03T17:36:17Z');
