INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('afa4ef5b-d937-4c60-b393-cf325ccaf336', '0b9d7ae7-218e-45a0-8c3a-e69912f5a6ed', 13, 'Franklin''s Day Off', 'Franklin would rather go on a bike ride with Bear, than put away his makeshift tent, but then he has a flat tire which leads him into all kinds of problems that could''ve been prevented if he had put away the tent days ago.', '1999-11-26', 12, NULL, '2026-04-03T17:40:15Z', '2026-04-03T17:40:15Z');
