INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('afe1f74a-be60-4405-aa8c-80a20e4e9744', '6ef86c27-33e7-47e5-a053-483059dfd16d', 32, 'Episode 32', 'RAF Airlift: Operation Pipeline gets a big boost when the RAF comes to the aid of viewers in Scotland, and heavy loads of stamps and coins reach the appeal depot in record time.', '1982-01-04', NULL, NULL, '2026-04-03T17:21:55Z', '2026-04-03T17:21:55Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('aff172b3-556d-41b4-b564-7da6e52f7e66', 'fa6f43f4-b944-4c33-ac69-dddbf54c0c16', 4, 'Jack and the Beanstalk', 'Fe-Fi-Fo-Fum... Remember the shivers you felt from the giants cry when you were a child? Now in this delightful production of Jack and the Beanstalk, a marvelous script and magical special effects recreate the adventure. Dennis Christopher is the idealistic hero who trades a cow for magic beans, then climbs the resulting beanstalk and stumbles onto an incredible adventure. A large part of that adventure is an encounter with Jean Stapleton and Elliot Gould, a giant husband and wife time that make this one of the most memorable episodes.', '1983-09-08', 51, '/3f9BkjGncepKwU3DksvZF567z9u.jpg', '2026-04-03T17:38:40Z', '2026-04-03T17:38:40Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('aff66dcc-fcb8-4488-8332-1fbf9b0c7b2e', '5a4e38a1-8e54-4974-8097-d7a7b48630a2', 22, 'Episode 22', 'with Valerie Singleton, John Noakes, Peter Purves', '1970-12-01', NULL, NULL, '2026-04-03T17:21:50Z', '2026-04-03T17:21:50Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('aff67595-d2d5-4cce-93d6-7779ab875538', '6f731e6b-d3c5-4de6-84e1-7a19cb650e86', 13, '80''s Pawn', 'Check out some totally radical items from the 1980s as the Pawn Stars take a trip down memory lane: a torch from the 1984 Olympics, a yearbook and signed letter from Ronald Reagan, a homemade replica Ghostbusters Proton Pack, a Super Mario statue, a poster from the "Revenge of the Jedi," some Metallica memorabilia, an Apple IIGS and a DeLorean that has Corey heading "Back to the Future."', '2015-12-03', 21, '/fllO3bmOcaK9prKGW2a8084DZzD.jpg', '2026-04-03T16:34:20Z', '2026-04-03T16:34:20Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('aff69e8f-123f-44a2-b310-e363e7816dc5', '0987f081-b3b7-4e3c-abb7-795e56c279d5', 22, 'Hallelujah Hoedown', 'Frankie tells the kids what she wants for Mother''s day so one of them can clue in Mike; after repeatedly failing the driving test, Sue feels resentful when her friends get their licenses; Axl receives stunning news from Cassidy.', '2013-05-08', 22, '/6Sr6NEgHnuEISOcrOkTdRdjD34d.jpg', '2026-04-03T15:40:30Z', '2026-04-03T15:40:30Z');
