INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('b048a3f3-52e6-4b05-a34a-f3308277e57a', 'a8f3a681-7abc-41e0-9988-9b8804d74611', 7, 'Brown Boys Do Vegas', 'The Brown brothers are coming to town! Kody ditches his four wives for his three brothers as they hit up the city of sin. They''re cruising on motorcycles, hanging out at a biker bar, and shooting guns.', '2012-06-10', 21, NULL, '2026-04-03T16:34:28Z', '2026-04-03T16:34:28Z');
