INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('b0503c49-c939-436b-8f8a-2054110ab393', '387da09c-95c3-49e8-a7ff-fcbb68362cc0', 14, 'Then & Now', 'Mr. McFeeley brings a dead bird into the television house and asks Rogers for a box in which to bury it. This prompts a Neighborhood of Make-Believe discussion of death as Lady Aberlin helps Henrietta and Daniel.', '1993-03-12', NULL, NULL, '2026-04-03T17:35:46Z', '2026-04-03T17:35:46Z');
