INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('b0d8dfdb-ff9c-476f-93ad-e317804d4f4e', '9193e795-da7c-40ec-b68f-f63aa7d5174f', 125, 'Histories & Lore: The Kingsguard (Jaime Lannister)', 'Jaime Lannister details the heroes and storied triumphs of the Kingsguard believed to be the most honorable knights in the realm.', '2015-02-17', 4, '/bnPPxLOqaq0jVUTU3B3Watm5QEr.jpg', '2026-04-03T15:40:35Z', '2026-04-03T15:40:35Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('b0d9a8ae-4212-48b1-a30d-a68998dafde2', 'f4c40307-9b5e-4263-a4e0-dfa138131e7f', 65, 'Elmo''s World: What Makes You Happy', 'Join Sesame Street’s curious red monster as he explores the things that make him happy: friends, signing, and dancing. Each episode comes to life in Elmo’s bright, exciting, and very original room – the drawer, door, shade, and TV all join in the fun. Elmo’s visitors in this delightful DVD include his friends from Sesame Street, an Opera diva, and even a dance team! Also featuring Elmo’s pet goldfish, Dorothy, the zany Mr. Noodle, and special guest star Kristen Chenowith.', '2007-01-01', NULL, NULL, '2026-04-03T17:36:27Z', '2026-04-03T17:36:27Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('b0da2f95-2d14-4b8d-9d90-147051a54acf', 'a4843a51-aeef-427c-902c-7fb3bd670cd4', 11, 'A Wagon of Different Color', 'After Bear finds coupons for the market, he decides to take everyone in the Big Blue House to the market. He runs into an unexpected delay when he finds out that Ojo has decided to repaint the wagon. Bear teaches her all about mixing paint to create different colors, Treelo admires all of his own colors in the mirror, and Bear plays fashion consultant when Tutter can''t decide what color outfit would be best to wear to the market.  Songs  What''s in the Mail Today?  Some of the Colors I See  Notes  The events of this episode were loosely adapted as the book Bear Loves Colors!  Tutter shows off his tendency to shout out names of cheeses as if they were epithets in this episode. He shouts out the names of no less than three different cheeses (cheddar chunks, brie and gorgonzola) when he gets upset over being unable to decide what to wear to the market.', '1997-11-03', 25, NULL, '2026-04-03T17:35:31Z', '2026-04-03T17:35:31Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('b0daabc8-b26e-4486-bb4b-73fdc7d3a6ab', '6920e4b0-8f6c-46f2-86e0-48cdee5f6089', 12, 'Pipe Organ', 'When the soup-trolley loses a wheel, Major Clanger tries to make a soup-pump.', '1972-11-03', 9, '/lAgB7vMMhKjuJ7QirO3VCPWXCIR.jpg', '2026-04-03T17:23:53Z', '2026-04-03T17:23:53Z');
