INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('b0f4a43e-db29-4f79-a5c6-c834c88f55b4', 'f9a8d8b3-d72e-437e-a9d5-7477f6d64df8', 12, 'Bubble Trouble', 'It''s national bubble week! Elmo, Rosita, Zoe, and Charlie are filling all of Sesame Street with bubbles to celebrate, but they are getting tired. They wonder if there''s something that could make bubbles for them. What if they put bubble wands on an egg rack in front of a fan and spin it through a tub of soapy water? Let''s try! It works. They didn''t give up and Sesame Street gets filled with bubbles thanks to their new machine!', '2023-01-19', 26, '/vpLAq3XrPwcl7tEUgmg4rpVKvM7.jpg', '2026-04-03T17:36:51Z', '2026-04-03T17:36:51Z');
