INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('b1a0ef8b-2e90-4f9b-aee9-37491343273f', '1a534647-384b-4c00-bb6c-a3371ad962eb', 8, 'Rick Gets Axed', 'Go batty with the Pawn Stars when a piece of original artwork from the 1995 Batman-Spiderman crossover comic swings into the shop. Will Corey and Chum come out heroes and capture this comic book memorabilia, or will their Spidey-senses fail them? Then, Rick checks out a deadly Revolutionary War halberd. Will he walk away with this deadly weapon, or will it be a losing battle? And later, when Chum''s complaints inspire a casual Friday at the shop, will the Old Man dare to dress down?', '2015-02-12', 21, '/4TT1vtRBvoPOqbxbW6MF4k8LQsx.jpg', '2026-04-03T16:34:19Z', '2026-04-03T16:34:19Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('b1a7a2da-de46-44b7-b51e-cb3ad487d5b8', 'bfdf87ff-01dd-4b54-94bd-19b384f41bdb', 16, 'Bringing up Old Ghosts', 'After a bumpy start to their vacation in Ireland, the women head off on separate adventures. Meghan takes Kelly to nearby Greystones Village in an attempt to locate distant relatives, while Vicki, Tamra, Heather and Shannon travel to a milk farm to get up close and personal with Ireland''s finest cows. The two groups reconvene for dinner where Kelly awkwardly tries to make amends with Tamra. However, the peace treaty doesn''t last long, as tensions reemerge and bombs fly when the ladies make their way back to the airport, leaving this group of friends in disarray like never before.', '2016-10-17', 44, '/oKQDZidySsd6SRhPuBZkDPWsHGy.jpg', '2026-04-03T16:35:33Z', '2026-04-03T16:35:33Z');
