INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('b1ba3a0c-209b-4b19-9f00-8ff26a9ce1b4', '082d18af-d82e-4db8-8746-1f7473706dae', 2, 'Miss Nelson Is Back', 'As part of his birthday celebration, LeVar gets made-up like a movie monster, and then gets involved in Harry Blackstone''s magic act. Ruth Buzzi reads Miss Nelson Is Back, all about a group of rowdy students who try to take advantage of their teacher''s absence when she''s out sick one day, and how she gets revenge on them by pretending to be "the meanest teacher in the world, Viola Swamp."', '1983-06-07', 30, NULL, '2026-04-03T17:36:14Z', '2026-04-03T17:36:14Z');
