INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('b209da79-a28a-44cb-ab8c-14056aa1510d', '33e647e7-a3e8-4c3a-93e6-74e08399a790', 2, 'Copy Cat', 'Mr. Gribble''s political campaign includes a competition for a flying machine. So, with a magic copy hat,  Linda mimics a seagull and flies high. But others want a go of the copy hat too...', '1992-04-11', 24, '/fj6ZtHfYKiqslM2ubOv6bsLAeZj.jpg', '2026-04-03T17:40:41Z', '2026-04-03T17:40:41Z');
