INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('b23a227a-140d-4c7a-9ae9-0b2b65085bf9', 'b2317fc3-1cfc-4f19-b181-effa23959c6d', 6, 'Bromance Breakup', 'The guys'' night out turns ugly when the men turn on Bill over Jennifer''s antics; while he''s away, Jennifer takes time and questions the future of her relationship; new allegations surface about Luis.', '2022-03-08', 43, '/qb93HeIh7DmvdtYdxInr7G1KCM7.jpg', '2026-04-03T16:35:18Z', '2026-04-03T16:35:18Z');
