INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('b2cda35f-9022-4cf5-b5b5-32f96b0a49d2', '91f66da7-56a2-423a-b855-f09d582805b2', 1, 'The Problem with Chickens & An Egg Is Quiet', 'Chickens that do not lay eggs; eggs that do not hatch.', '2007-09-17', 30, NULL, '2026-04-03T17:12:29Z', '2026-04-03T17:12:29Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('b2cebc7b-614b-4d9c-941b-447090647291', 'f79f69a8-e591-41d0-9d4a-3d9683defbbb', 6, 'Big Trouble in Big Sky', 'The adventure continues in Montana when the ladies partake in fly-fishing and white-water rafting; Heather helps Gina deal with pent-up emotion, but later feels betrayed and contemplates their friendship moving forward.', '2023-07-12', 44, '/xc7cfL3ZAIV85jyX0z5uD5xGYpP.jpg', '2026-04-03T16:35:35Z', '2026-04-03T16:35:35Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('b2d2c272-7999-4dbc-a3cb-ec7a408b96c0', 'd5f0284f-0ee3-45bf-8539-d02a825d15b2', 13, 'Miami in Mexico', 'The ladies arrive in Mexico City, but Larsa and Alexia start the trip off on the wrong foot; Guerdy discovers someone has been speaking poorly about her to the press; a sexual and provocative dinner experience brings some truths to light.', '2024-01-24', 44, '/5LrR0zuuZgxoBi8gye7neUFxORo.jpg', '2026-04-03T16:35:12Z', '2026-04-03T16:35:12Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('b2df43a2-5dfa-45e3-ad95-c852475a7746', '34674c90-410e-427c-be4d-2a6f6f865a80', 10, 'Family Feud', 'The Pawn Stars experience some family drama when a rifle from the Hatfield-McCoy feud ambushes the shop. Formerly owned by the notorious "Cap" Hatfield, can Rick get this antique Winchester for a fair price, or will the seller force him into a bidding war? Then, a work by rock and roll artist Denny Dent rocks and rolls through the shop. Will this painting of John Lennon be a deal to remember, or will the asking price force Rick to just let it be? And later, a guy comes in with an inkwell owned by William Andrews Clark. Known as the man who helped build Las Vegas, can the guys ink the deal on this piece of local history?', '2012-05-28', 21, NULL, '2026-04-03T16:34:17Z', '2026-04-03T16:34:17Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('b2e22c5b-12bc-4e0e-af8d-4374309f8c06', '852a07b0-f228-4197-9147-7aeed79390bf', 18, 'So... That Happened', 'A special episode pulls the curtain back and reveals never-before-seen moments from Season 13. In this new footage, fans will get a closer look at all the fun the ladies had together, from playing Red Rover at Ramona and Sonja’s birthday party to learning how to twerk to having run-ins with Salem ghosts. Viewers will even get to engage with the episode through a hilarious, multiple choice guessing game of “What Happens Next.”', '2021-09-07', 60, '/i9HtsmFJI3yHaSfdhFr99jJ4b1F.jpg', '2026-04-03T16:35:26Z', '2026-04-03T16:35:26Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('b2e7df20-d0f0-44cc-8cc9-ff81285cd5c4', 'e6254ae4-7d72-493b-8b37-b677d8b76c46', 124, 'Episode 789', '', '1975-04-24', NULL, NULL, '2026-04-03T17:36:31Z', '2026-04-03T17:36:31Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('b2e8ac7c-621d-431c-8358-536f8dfc7c45', 'f12380a9-93e5-47bb-9e2f-cf1eed11eee4', 9, 'Standoff at Coyote Pass', 'It''s an awkward final showdown at Coyote Pass with Kody, Robyn, Janelle, and Meri. Janelle takes a trip to New Orleans and let''s loose with girlfriends to celebrate, and Kody considers finding a therapist to help repair relationships with his children.', '2025-11-23', NULL, '/kx3S3LgeFyozs9YjsGEQj6FTnDL.jpg', '2026-04-03T16:34:33Z', '2026-04-03T16:34:33Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('b2ea403a-486e-4d27-af8d-476944aca630', '095258d0-d8db-4096-8ac7-6a42cd4cbdcf', 10, 'The Secret Society Of Poohbahs', 'Mokey really, really wants to be a part of the Secret Society of Poohbahs, even though Red keeps telling her it''s just a silly club. Then one day Mokey gets a letter saying that the Poohbah''s would like to see her and find out if she''s worthy of being a part of the club. She tells Red of her invitation, only to find out that she wasn''t supposed to tell anyone about it. She goes back to find out if she can be a part of the society, but when a member called the Mind-Reader knows that Mokey told her roommate of the invitation, she''s immediately rejected, but the Beggler Beg and the Vanguard (who look an awful lot like Gillis Fraggle and Convincing John) say that, if she brings her roommate to verify that Mokey''s legit, she can be a Poohbah. Mokey gets all worked up about this, but when she brings Red back so she can be a Poohbah, Mokey finally learns not to take anything too serious that these Fraggles tell her.', '1985-03-04', 24, '/rCi3QUyk2F3IQ4F9PtFOxhwwQug.jpg', '2026-04-03T17:35:00Z', '2026-04-03T17:35:00Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('b2ebc2e2-426f-4033-987b-4e46f21ae520', '0d2293dd-dfca-4591-8f9a-0fbe023f8d1c', 3, 'Betrayer Moon', 'Geralt takes on another Witcher''s unfinished business in a kingdom stalked by a ferocious beast. At a brutal cost, Yennefer forges a magical new future.', '2019-12-20', 68, '/jiNkIfEOsKQNNc0roNmzZZ0VJVi.jpg', '2026-04-03T15:40:45Z', '2026-04-03T15:40:45Z');
