INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('b364eac7-d39f-4244-bf4b-f986b2109377', '0442fb97-1460-4923-8558-b994078dc6b8', 5, 'Look Who''s Squawking', 'Monique invites everyone to her lake house for a weekend retreat, but the ladies are not prepared for her additional guest. Karen expresses her dislike for Wendy''s obsession with her sex life, meanwhile Gizelle and Candiace''s friendship takes a surprising turn. Ashley decides to bring baby Dean along for the festivities, but Wendy''s strong opinions on her decision leaves the women stunned.', '2020-08-30', 42, '/uvadprlCKHv72iP53fKjN3OY4mZ.jpg', '2026-04-03T16:35:40Z', '2026-04-03T16:35:40Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('b366a2f5-d714-466d-81aa-fb53d2166d6e', '465e5a6d-74b6-4ffb-b54f-51103f8329b3', 1, 'When Wives Collide', 'The highly anticipated trip to Turks and Caicos kicks off with shots fired on a private jet, a hunky blast from the past and one Housewife finding herself on an island -- literally.', '2021-11-15', 49, '/nsSkmZYu3aUGZuk14c5ZgWjCKZ7.jpg', '2026-04-03T16:34:40Z', '2026-04-03T16:34:40Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('b374f70f-59d0-4337-8fc8-55cfbf9d7bc3', '331fc1df-6d70-4d79-b585-bf28024a4124', 6, 'Santa Overboard', 'It is nearly Christmas in Pontypandy and Norman is keen to have the best Christmas decorations, which leads to Dilys putting too many into one plug socket, leading to a fire.', '2008-11-18', 10, NULL, '2026-04-03T17:14:39Z', '2026-04-03T17:14:39Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('b37513cf-cb68-4738-8fd8-5065085033f4', 'bff09904-103d-4ae2-9c13-c1febc903a46', 3, 'Saturday Sancocho', 'LeVar attends a rummage sale to observe how people sometimes barter for items when they don''t have money to buy them. Josie de Guzman reads the feature story about a girl who follows her grandmother around the farmer''s market to trade items to get the ingredients for their weekly chicken stew after they discover they are out of all the groceries they need and don''t have cash to buy them.', '1998-10-07', 30, NULL, '2026-04-03T17:36:20Z', '2026-04-03T17:36:20Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('b3796ddf-e242-4966-abd3-c71b6034533a', '4d2cac0f-38fd-438b-8afa-acf43952e535', 165, 'Episode 165', 'A magazine programme for younger viewers. Chris and Leila show you how to make A Doll''s House. An excerpt from the film Babes in Toyland. Shown by courtesy of Walt Disney Productions. Letter M in the Blue Peter Alphabet.', '1962-01-01', NULL, NULL, '2026-04-03T17:21:47Z', '2026-04-03T17:21:47Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('b37b2055-89c4-466d-ad83-742df39b7a2b', '4c79c0b6-21a4-4277-8967-be1e791efdbe', 15, 'Green Eyed Pingu', 'Pingu comes out to play with his ball, when Pingi walks past. Pingu calls to her to stop, catches up with her and starts kissing her on the hand. Then Pingg appears, tags Pingi and they start a game of tag. Pingu tries to join in, but it quickly goes back to Pingg and Pingi playing without Pingu. Pingu has an idea, collects his sledge and then Pingi, and goes off with her. They come to an old igloo, and start a game of hide and seek. Pingu hides, and Pingi starts to look for him. Then Pingg, who has followed them on his sledge, pops up and Pingi starts talking to him, abandoning the game with Pingu. Pingu is jealous and goes off in a huff, then has another idea and gets his ball. He tosses the ball to Pingi, who is on Pingg’s sledge, and she and Pingu start a game of ball. All three of them play together briefly, then it turns into a game of “pig in the middle”, with Pingu as the “pig”, and he never gets the ball. Pingu goes off and comes back with a bunch of flowers and a cuddly toy for Pingi. Pingg goes and gets a ragdoll. Pingu goes off and gets a sledge full of gifts for Pingi, Pingg gets a big bunch of balloons. Pingu dumps the toys in a heap next to Pingi and gets a fish, Pingg then gets a few fish and Pingu then goes and gets a sledge piled high with fish. Pingu and Pingg look at each other across the pile next to Pingi, dump their fish on the pile and face up to one another. They then start a snowball fight, while Pingi is busy getting out from the pile around her. Once out she stands up, and is hit in the face by a snowball thrown by Pingu. They both go to console her, but she shrugs them both away and angrily walks off. Pingu and Pingg make up, and then go off to find Pingi, each with a selection from the gifts. When Pingi sees they’ve made up she kisses Pingg on the cheek, to Pingu’s dismay. She then gives Pingu a proper kiss, to his delight.', '2005-11-30', 5, '/4KnEVq4nmW7Qfl9CsXGGuUcAkhx.jpg', '2026-04-03T17:22:20Z', '2026-04-03T17:22:20Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('b37dfc53-a81d-4817-abde-4e5911409780', '93651310-a84f-42ef-bcb7-ab8f788f102d', 12, 'Bridesmaid Breakdown', 'Lisa is determined to get Lea and Adriana back together; Joanna is becoming stressed and takes it out on Lisa; Adriana and Lea meet to try to settle their issues.', '2013-10-28', 44, '/hfkjgdqYA29lBVzt4WqONd7AiJI.jpg', '2026-04-03T16:35:10Z', '2026-04-03T16:35:10Z');
