INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('b4127a05-8192-489a-8392-a5197ce61455', '082d18af-d82e-4db8-8746-1f7473706dae', 6, 'Digging Up Dinosaurs', 'Technically not the first science-related show in its history, LeVar seeks a place where archaeologists retrieve dinosaur bones. At the end of the program, LeVar buries a time capsule, containing (among other things) a can of old Coke and his picture. Linda Gilman reads Digging Up Dinosaurs, a story about how paleontologists unearth dinosaurs skeletons and preserve them in museum exhibits.', '1983-06-13', 30, NULL, '2026-04-03T17:36:14Z', '2026-04-03T17:36:14Z');
