INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('b42c6e43-7ab4-4b92-b00b-d49d5291169e', 'fb06e658-4b54-4682-8783-eaa88a99e61e', 16, 'Arthur Read, Super Saver', 'After hearing a slideshow on the Great Depression, Arthur begins to worry about the amount of money his family seems to be wasting through usage of water, electricity and lawn mowers.', '2015-09-09', 13, NULL, '2026-04-03T17:38:01Z', '2026-04-03T17:38:01Z');
