INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('b48091e0-58a6-415e-9684-05ee2436c132', 'a4843a51-aeef-427c-902c-7fb3bd670cd4', 1, 'Home Is Where the Bear Is', 'One morning, Bear finds Ojo playing pretend, having created a tent that''s she''s pretending is her home. Her imaginary home gets Bear thinking about his real home, the Big Blue House. Bear decides to take us all on a guided tour of the home. He takes us to the kitchen, which we learn is Tutter''s favorite room. The bathroom is the favorite haunt of Pip and Pop. Treelo likes Bear''s bedroom, mainly because of the bed. Shadow retells the story of the little old lady who lived in a shoe. Finally, Bear also enjoys going up to the attic, because he gets to talk there each night with his friend Luna, the moon.', '1997-10-20', 25, NULL, '2026-04-03T17:35:31Z', '2026-04-03T17:35:31Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('b48325f9-3d79-464a-ad50-71322451ade5', 'e8cd8e7b-a34f-4123-9447-7e1036158f10', 1, 'Hot-Air Henry', 'LeVar goes to South Carolina to ride a hot-air balloon. In another study of how air travel has advanced, schoolchildren visit the Space Camp for Aspiring Young Astronauts. William Windom reads the story of Hot-Air Henry, the misadventures of a cat who sneaks on board his family''s hot air balloon and how he gets back down again.', '1984-01-01', 30, NULL, '2026-04-03T17:36:15Z', '2026-04-03T17:36:15Z');
