INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('b4dd40c9-2da1-484f-aa77-c10e681fb20d', '05c0e384-194c-4417-9f62-803eb615e409', 6, 'Feeling scientific', 'Title number 0006. Opens with Mister Rogers arriving with a large box in a lab coat. To prepare for his scientific endeavor, Mr. Rogers puts on a lab coat and compares various shells and shell-like objects, including a turtle shell, a conch shell, an armadillo''s armored shell and a suit of armor. In the Neighborhood of Make-Believe, Bud Alder compares oil-based and water-based paints. After sharing his wisdom with X the Owl, X teaches Lady Elaine various bird names.', '1968-02-26', 29, NULL, '2026-04-03T17:35:38Z', '2026-04-03T17:35:38Z');
