INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('b5016815-4c02-493e-8e08-99acfe42463f', '870f8a01-5212-482c-8cb0-454cb2196642', 2, 'The Princess Who Never Laughed', 'Ellen Barkin is a forlorn princess yearning for laughs. Howard Hessman is her stern father (the king) who demands to be addressed as "your seriousness". Growing up without humor, the princess becomes more and more morose, finally locking herself in the royal bedchamber and refusing to leave. The king in desperation, decrees a royal laugh-off to make his daughter happy. Enter Howie Mandell as "Weinerhead Waldo" and his pet pig Boris. Together they show the princess what the funniest act in the kingdom really is.', '1986-08-11', 51, '/xJOl6gp6SAGktKOqkm9HPlV2ZbX.jpg', '2026-04-03T17:38:41Z', '2026-04-03T17:38:41Z');
