INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('b5138cde-2e6b-47da-8ba5-876e3248728b', '79916e0e-881c-43a7-b4ee-00e5052a94be', 10, 'Tug of the Year', 'George is sad that he didn''t win the ""Tug of the Year"" contest, and he had practiced so hard for it too.   His other tugboat friends decide to give him a big surprise to cheer him right up.', NULL, NULL, NULL, '2026-04-03T17:10:11Z', '2026-04-03T17:10:11Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('b518ea06-cdd7-476b-90a5-97f4e4a80a92', 'bb919aec-0d5c-4c58-9a5a-fa2a0a5de2b6', 15, 'Episode 420', '', NULL, NULL, NULL, '2026-04-03T17:36:29Z', '2026-04-03T17:36:29Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('b5192ee4-165b-4592-a426-ceb592f6eee7', '5046642d-462d-4eb0-8194-0bbd7962af0f', 4, 'Heroes of the Bible! - Lions, Shephards and Queens (Oh, My!)', 'This collection includes three short stories, beginning with "Daniel and the Lion''s Den," in which Larry the Cucumber portrays Daniel and overcomes adversity and fear thanks to God. Then, in "Dave and the Giant Pickle," an Asparagus goes head-to-head with a giant pickle, and in in "Esther... The Girl Who Became Queen,"  a small-town girl finds the future of her townspeople is up to her.', '2002-03-05', 30, '/jqMoamN82GRClZqKQWLleg2OvCr.jpg', '2026-04-03T17:39:38Z', '2026-04-03T17:39:38Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('b51c9aba-f8db-4b1c-8eee-15aa4fc7d787', '4060ad7f-4b8f-4393-8eb1-66a150b928b6', 4, 'Bye Bye Boo Boos', 'Boo-Boo Busters Elmo and Abby go around Sesame Street in search of friends who need help making their boo-boos feel better.', '2020-12-03', 26, '/7K8YO7PV1F0qCvv47BK3jcPIRs8.jpg', '2026-04-03T17:36:50Z', '2026-04-03T17:36:50Z');
