INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('b52fcbcd-9527-4bbc-b258-9099cdd3a6bb', '35ebddbb-977f-4aac-8aa4-55560de6d4b8', 13, 'Episode 13', '', '2006-05-15', 25, NULL, '2026-04-03T17:21:20Z', '2026-04-03T17:21:20Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('b5338739-2051-4c91-b783-fabf06743555', '150d1480-f3f1-43f9-9a22-d2527756fba2', 21, 'Reunion (4)', 'Nicki Minaj takes over and surprises the ladies of "The Real Housewives of Potomac"; Nicki gets down to business on the reunion stage, unafraid to ask the difficult questions, she leaves no stone unturned.', '2021-11-28', 42, '/4Bvc1erUP6o0NY9zGqivX9mJBTB.jpg', '2026-04-03T16:35:40Z', '2026-04-03T16:35:40Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('b53aa68d-779a-4d12-9d10-7c0dd983ed22', 'e6254ae4-7d72-493b-8b37-b677d8b76c46', 103, 'Episode 768', '', '1975-03-26', NULL, NULL, '2026-04-03T17:36:31Z', '2026-04-03T17:36:31Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('b53aef3c-99cf-4c29-9bb5-af8f0143fa59', '208e80de-61e3-4a2f-857f-c667ffc29134', 11, 'Dizzy Gillespie', 'Statler is sick (of the show), so Waldorf brings his wife Astoria to the show. Meanwhile, Inspector LaBrea of the County Environmental Department arrives backstage to monitor the noise level of the show. LaBrea tells Kermit that to keep the noise down, he has to cut the trumpets for the show. Kermit tries to keep LaBrea busy while Dizzy performs.', '1980-01-04', 26, '/oDDHRkXjMo1JwK9epIgIl7c2Pkx.jpg', '2026-04-03T17:35:25Z', '2026-04-03T17:35:25Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('b53baa37-5745-43f2-ab60-5b25f27c76fe', '1d556682-d9bb-47e1-993f-0b648a8daacd', 99, 'Episode 1284', '', '1979-04-12', NULL, NULL, '2026-04-03T17:36:33Z', '2026-04-03T17:36:33Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('b53d64b5-4ee2-43af-b095-3a4837b0b414', 'e8b959c0-6865-4332-9be1-b8f720716aa8', 17, 'Trees', 'John accidentally breaks a plank of wood and decides to get a new one. He visits a timber yard to see how trees get turned into planks of wood.', '1992-02-03', 15, NULL, '2026-04-03T17:19:37Z', '2026-04-03T17:19:37Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('b53dc5ba-e04c-4be5-8a91-afa4769392a5', 'd0e5568d-939d-4d89-ab4e-c291a90691cf', 6, 'Clay Time', 'Kipper finds Tiger messily trying to make a clay pot on his new potter''s wheel. They decide to make some pots together and Tiger tells Kipper how difficult it is. Pig gives Arnold a ride on the potter''s wheels thinking it is a car without wheels. They find the pots Tiger and Kipper have been making and think they''re chocolate cookies. Tiger has some explaining to do.', '2000-11-02', 8, NULL, '2026-04-03T17:10:49Z', '2026-04-03T17:10:49Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('b53f2a93-c0fb-4028-951a-b293768ba654', '5c1b881f-ac58-4d72-b63f-209952d4f902', 14, 'Episode 14', '''Oh I wish I''d looked after me teeth'' - says Pam Ayres who will be in the studio today rendering her famous poem with its awful warning to compulsive sweet-suckers.', '1979-10-25', NULL, NULL, '2026-04-03T17:21:54Z', '2026-04-03T17:21:54Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('b53f4568-7cef-4bdd-8a6e-24e177663288', 'f9a8d8b3-d72e-437e-a9d5-7477f6d64df8', 5, 'Jobs Day', 'It’s Jobs Day! Elmo and his friends are learning about jobs they would like to do when they grow up. When Gabrielle doesn’t know what she wants to do yet, she learns that if you work hard and practice, you can do anything you want to do. First lady and teacher Jill Biden teaches Elmo, Abby, and Tamir about all different types of jobs.', '2022-12-01', 26, '/iBHTm1p94GSdjOcFDvIZuNNlKGr.jpg', '2026-04-03T17:36:51Z', '2026-04-03T17:36:51Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('b54008d3-6633-47c8-8c18-ce23d5180cde', '04e133fd-c4a3-4dfa-8369-c6dcfd1e3a5a', 110, 'Episode 2075', 'A brief episode featuring simple street scenes and basic educational content. The residents interact naturally while lessons are taught incidentally. Daily life on Sesame Street unfolds with minimal plot.

Sponsors: C, Y, 2', '1985-04-19', NULL, NULL, '2026-04-03T17:36:36Z', '2026-04-03T17:36:36Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('b542bf99-ec50-4130-b4ea-dd13f5e2f5ee', 'e1063f87-66c2-4e2d-a913-53362941aa19', 128, 'Episode 403', '', NULL, NULL, NULL, '2026-04-03T17:36:29Z', '2026-04-03T17:36:29Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('b54a57b1-337d-49bc-9151-0e44da959631', 'e40e6b63-9f84-449f-8e88-53209b0906c8', 12, 'Rosita, Telly, and Zoe Play House', 'Telly, Zoe and Rosita are all excited as they welcome the viewer to Sesame Street, because today they''re playing "house." They can''t wait to pretend to be a big happy family. Rosita will be the mommy, Zoe will be the baby, and Telly will be the dog and the daddy (even though he''d rather be the dog). They sing their happy family song.', '2007-09-06', NULL, '/5Hsmp9oEF4wQmCfwEzRtyPjsUO6.jpg', '2026-04-03T17:36:45Z', '2026-04-03T17:36:45Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('b54cb6c2-5586-47e3-b06f-8213fd359b01', '21745b85-d269-42fa-b4dd-701b2da5c085', 21, 'Episode 21', 'with John Noakes, Peter Purves, Lesley Judd', '1973-11-19', NULL, NULL, '2026-04-03T17:21:51Z', '2026-04-03T17:21:51Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('b54cb99e-16f4-42fe-883a-4e5777228083', '34bdccfa-3c14-4e1c-9148-85c29aadc0e1', 10, 'Creatures of the Night', 'Chris and Martin are in Australia in search of nocturnal animals.  During the night, they enter a cave in search for the elusive ghost bat.', '1996-06-14', 30, NULL, '2026-04-03T17:11:47Z', '2026-04-03T17:11:47Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('b54e647a-501d-413e-a579-f41129146f28', '081f12e2-9239-4946-90a1-47763b935db2', 7, 'Episode 7', '', '1986-03-04', 25, NULL, '2026-04-03T17:21:14Z', '2026-04-03T17:21:14Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('b54f74d7-b01c-49ba-9b6e-2f70853030b4', '06030129-ff2d-4490-b66c-9f41bbe7aabd', 11, 'Falcons', 'John is looking for an idea for a story, so he sails down the canal to a falcon country park to see all kinds of different birds. Rosie and Jim follow him, and watch the demonstrations of the falcons.', '1990-11-12', 15, NULL, '2026-04-03T17:19:36Z', '2026-04-03T17:19:36Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('b54fd350-66bf-4af1-89b8-2d9c056652db', '4091b13b-4db6-4857-ad22-20b5658c6b89', 13, 'House of Horrors', 'Teresa takes her relationship to the next level while Melissa and Joe’s relationship hits a breaking point. Additionally, Jennifer’s excessive drinking threatens to ruin Marge’s Halloween Bash.', '2021-05-12', 43, '/tKdHF1TfEvmAhYaA8QkdX1ESk6D.jpg', '2026-04-03T16:35:18Z', '2026-04-03T16:35:18Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('b553abbe-472c-46ab-8191-d37387981996', '5a771f52-fe96-4ea2-b567-a8dde899059e', 11, 'Top Rope, Bottom Dollar', 'Rick and Chum thumb through an ancient tome that was believed to hold the secret for turning metals into gold. Will the two band together to buy this banned book? A costume signed by "Macho Man" Randy Savage leaves Corey and Chum wrestling with a tough decision. A half dollar that was supposedly pierced by sharpshooter Annie Oakley finds itself in Rick''s crosshairs, but this shot is anything but cheap. Later, a fancy French gunpowder flask leaves Rick locked and loaded - but will he actually pull the trigger on this sale?', '2017-11-20', 21, '/4ZmBAMkwk64gbsgo1YwJa4j4Obj.jpg', '2026-04-03T16:34:21Z', '2026-04-03T16:34:21Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('b554fb53-6995-4e7e-a102-3f65a0ebb75d', '6d2b78d7-2612-4afb-81ca-dee774af9c2b', 9, 'Dance', 'Rogers visits the Dance Theatre of Harlem. Lady Elaine changes the name of her dance studio and sends dance invitations to all the men, except for Grand-père.', '1987-05-11', 30, NULL, '2026-04-03T17:35:44Z', '2026-04-03T17:35:44Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('b55624c1-5ee0-41db-b8b7-d18a04ead05f', '84ce360a-90d1-4fc0-be06-33bdcbe8e60a', 6, 'The Mouse', 'Kipper can''t understand where the contents of his cereal packet have gone, or why his toys are littered all over the place when he knows he put them away. Then he discovers he''s got a little visitor - and life may never be the same again.', '1999-10-28', 30, '/deBaMialfRhZjy3lxXZCvgGUWZ9.jpg', '2026-04-03T17:10:49Z', '2026-04-03T17:10:49Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('b55e1101-b756-4536-b451-383d81bf5d6c', 'f593d90c-5339-42f5-9c88-5bfd48d04075', 21, 'The Boat', 'The farmer gets Bitzer to help him renovate an old boat, but as soon as his back is turned the sheep and pigs turn the refurbishment into a swashbuckling game of pirates.', '2010-04-11', NULL, '/dSBHwVsRNdiNPPUxRFAG2khui6S.jpg', '2026-04-03T17:39:31Z', '2026-04-03T17:39:31Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('b5610abf-0639-498d-93ac-44ce6dc0f01a', '05c0e384-194c-4417-9f62-803eb615e409', 91, 'Building', 'Rogers builds a wood frame. Handyman Negri is building a new balcony on the castle.', '1968-06-24', NULL, NULL, '2026-04-03T17:35:38Z', '2026-04-03T17:35:38Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('b563d091-9727-48a3-8a49-13dc1dfd4156', '61e0c9d9-337e-4fe4-a0fd-e567b29af115', 8, 'The Desert and the Deserted', 'Bronwyn and Todd take the couples to Palm Springs to celebrate their 10th anniversary, but once in the desert, the divisions in the group become clear. Even after being uninvited on the trip, Heather makes her presence known in Palm Springs. Tensions between Lisa and Bronwyn boil over in the hot tub, resulting in Todd asking Lisa and John to leave early. Meredith gets upset when Seth prioritizes work over their marriage, suggesting trouble in paradise.', '2024-11-06', 43, '/oQZ4fuZgzBsOn5wMb8AGf2YkRN7.jpg', '2026-04-03T16:35:45Z', '2026-04-03T16:35:45Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('b56a8f49-7408-4eae-8893-032d0052d76b', 'a4ab988b-114e-4e85-a1d6-45be8ada5f95', 1, 'Leading the way to Literacy Special', '', NULL, 30, NULL, '2026-04-03T17:12:27Z', '2026-04-03T17:12:27Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('b56b293b-2f85-4de1-9bc5-7449ebc1e4e1', '1f34e241-4c1d-4586-921a-1c5aeb1fbbaa', 35, 'Uncle Wally recalls his sailor days', 'Gordon asks Piri, Big Bird, and Mr. Snuffleupagus to watch Miles while he goes to get his dry cleaning. Big Bird and Snuffy try to find ways to keep Miles amused, but their joke telling and dog imitations don''t work very well.

Sponsors: N, P, 3', '1986-01-03', NULL, NULL, '2026-04-03T17:36:36Z', '2026-04-03T17:36:36Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('b56e0db6-bb8b-45eb-887c-bdfaa81a9338', '1cafb2c3-bbcb-4172-b02d-441a5aaa155f', 3, 'Giving and Receiving: How People Make Toilets', 'Rogers brings back The Potty Book that he had introduced back in 1989, and reads it in full, this time. Mr. McFeely shows a videotape of how toilets are made. Betty Okonak Templeton visits the Neighborhood of Make-Believe in search of Lady Elaine.', '1998-08-21', NULL, NULL, '2026-04-03T17:35:48Z', '2026-04-03T17:35:48Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('b576b1f5-0a5e-4c41-9b6d-73978a795f5b', '4d2cac0f-38fd-438b-8afa-acf43952e535', 322, 'Episode 322', 'with Christopher Trace and Valerie Singleton, including The Changing of the Guard - Blue Peter cameras visit Buckingham Palace to see one of London''s most famous spectacles.', '1964-12-28', NULL, NULL, '2026-04-03T17:21:47Z', '2026-04-03T17:21:47Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('b57850fa-01a4-466e-be79-3e905e62acf5', '3190d082-877d-4951-bf7c-ed07ef560040', 5, 'The Purple Coat', 'In New York again, LeVar goes to get a tailor-made jacket. In between comes a visit to the Fashion Institute of Technology.', '1988-08-19', 30, NULL, '2026-04-03T17:36:16Z', '2026-04-03T17:36:16Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('b57e7d31-a804-46be-9922-7d32154f1d8a', '48a6d3b8-3842-41da-aaec-b49a9b65f17f', 7, 'Space Invaders', 'Kipper finds what seems to be a toy spaceship, but never discovers that it is very real.', '1998-11-05', 30, NULL, '2026-04-03T17:10:48Z', '2026-04-03T17:10:48Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('b58047ba-98b6-42d0-9761-ab779cf94133', '3fc7c152-e4f6-426a-a899-36ec454c4403', 33, 'Follow the Dots', 'Ord is afraid that he lost his father''s favorite Whack-It-Back Whistler forever, until Norm the Number Gnome knows where it is and shows everyone how counting to ten will help them find it.', '1999-10-19', 30, NULL, '2026-04-03T15:26:03Z', '2026-04-03T15:26:03Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('b5892ed6-8c4e-4038-a678-c1160ade623e', 'a6ed03e0-c05f-48f8-9f56-3f1da50e1792', 116, 'Episode 1431', '', '1980-05-05', NULL, NULL, '2026-04-03T17:36:33Z', '2026-04-03T17:36:33Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('b592cff1-7f60-4fff-91ad-467858c4b7a0', 'db958af4-9a9a-4533-af9b-f0ff590d1dd9', 16, 'Teresa Gets Married', 'Days after the explosive Prohibition Party, Teresa and Louie prepare to celebrate the wedding of their dreams; with news of Melissa and Joe not attending, Teresa and her family make the best of the circumstances and celebrate with chosen family.', '2023-05-23', 44, '/8ojdG6piqQwWc3qm8kgCR9sKDkD.jpg', '2026-04-03T16:35:19Z', '2026-04-03T16:35:19Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('b5945016-6f1e-4714-bfae-28133aeb9421', '98d80972-e53a-43dd-a03a-7703465e6f87', 13, 'Take the Money and Run', 'Take aim with the Pawn Stars when the guys check out a Kentucky Long Rifle. Made famous by frontier marksmen like Daniel Boone, will the guys take a long shot on this iconic big-game gun? Then, Rick gets a geography test when he''s offered a 1700s map depicting California as an island. Can he plot a course towards a sale, or will this piece just get him lost? And later, Corey''s longtime demand to be made a partner in the shop comes to a head when he says "now or never." Will Rick and the Old Man cut him a deal, or kick him from the nest?', '2012-12-10', 21, NULL, '2026-04-03T16:34:18Z', '2026-04-03T16:34:18Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('b5988779-5e86-4e80-a5d0-6a03410b15b2', 'f07b8794-5625-4682-aae1-e56966b4c7a8', 14, 'Tattle Tales', 'Leon sees his brother accidentally break his father’s favorite lamp. Leon doesn’t want to be a tattletale, but he doesn’t want to lie either. When he learns that telling the truth is not the same as tattling, he knows just what to do.', '1996-02-01', 29, NULL, '2026-04-03T17:12:21Z', '2026-04-03T17:12:21Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('b59cd747-c4d5-4a5a-93ce-1e51b3a3c6b9', '842c6419-ab98-4d34-8845-1d9782291aad', 10, 'Citizenship', 'When Annie’s father is called for jury duty, the family vacation is put on hold. Annie, excited about taking a trip, doesn’t understand why her father can’t just postpone his jury duty, prompting several stories up at Plato’s Peak about citizenship -- the civic virtue.', '1998-04-19', 30, NULL, '2026-04-03T17:38:34Z', '2026-04-03T17:38:34Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('b59e8966-26e7-4fad-a46b-273e07a781b9', '79916e0e-881c-43a7-b4ee-00e5052a94be', 24, 'Theodore and the Northern Lights', 'One night, Theodore and his friend Foduck get to experience the beautiful Northern Lights.', NULL, NULL, NULL, '2026-04-03T17:10:11Z', '2026-04-03T17:10:11Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('b59ed822-f8f1-4858-9523-ed8b77d3fec1', '54c29014-2dbd-49ff-a23f-cf4c546e0b3a', 16, 'Go Yell It on the Mountain', 'A Montana trip continues with tensions lingering between Sonja and LuAnn. Meanwhile, the ladies participate in outdoor activities and a modern-day treasure hunt, but the group divides thanks to a tiff between Heather and Kristen.', '2014-06-24', 60, NULL, '2026-04-03T16:35:23Z', '2026-04-03T16:35:23Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('b5a3d1af-85e4-4d21-ae79-1db5a7bfccc4', '8bae6aa3-4b55-4fa6-bc15-8f4317bd1f13', 2, 'Episode 2', 'Rogers and Mr. McFeely do a bit of secret communicating, with neither one understanding the other. In the Neighborhood of Make-Believe, Lady Elaine is impatient with X''s call for privacy while he writes poetry.', '1972-02-22', NULL, NULL, '2026-04-03T17:35:39Z', '2026-04-03T17:35:39Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('b5b0bb2a-ee2a-48da-a9b9-aa9aeeabcc41', '050d8ae1-6cc1-4018-933d-b3c3d13de856', 54, 'Episode 54', 'Cetiosaurus Lives!

For 17 years, the skeleton of one of the largest of the dinosaurs lay packed in boxes in the basement of Leicester''s museum. Today Cetiosaurus makes his first posthumous public appearance, in the Blue Peter studio -all 40 feet of him! There''s news of Bobby Robson ''s Soccer Funweeks with dazzling footwork from Chris Waddle and John Barnes. And don''t miss the report on the LifeSaver Appeal Auction.', '1985-03-18', NULL, NULL, '2026-04-03T17:21:57Z', '2026-04-03T17:21:57Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('b5bf16a9-e412-447e-ab8a-b36108604d5f', '24003c6d-d919-4616-a7dd-0d38bb7a0656', 7, 'Excercise', 'Pat visits The Metropolitan Club to do some exercise.', '1996-02-16', 10, NULL, '2026-04-03T17:19:37Z', '2026-04-03T17:19:37Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('b5ca5148-72f1-4d30-83d0-ac7306bf11d0', 'f4c40307-9b5e-4263-a4e0-dfa138131e7f', 2, 'Do The Alphabet', 'When Baby Bear must learn his alphabet in one day, Big Bird patiently takes him under his wing in Do the Alphabet. Only "The Method," (a hilarious combination of dance, song, visualization, and group therapy) can help Baby Bear on such short notice.', NULL, NULL, NULL, '2026-04-03T17:36:27Z', '2026-04-03T17:36:27Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('b5ce0d3e-403d-4437-82c9-87b30e8e072b', '7acb58c5-320f-419d-a96f-26ad3cfe2e82', 3, 'Reunion', 'Geralt seeks magical help from a family friend as Ciri and Yennefer clash over plans for the future. Philippa and Dijkstra scheme to get Vizimir in line.', '2023-06-29', 62, '/kIymMMvcDSTasaRYPHX5QOrpLiK.jpg', '2026-04-03T15:40:45Z', '2026-04-03T15:40:45Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('b5ce58d8-55ae-4932-a625-6aed43b1c915', '9b144910-398a-47d4-9ccd-823d25cc8b0a', 8, 'Best Friends For Never', 'Jacqueline''s daughter, Ashley, is running out of options; Lauren makes a shocking decision regarding her weight loss; Teresa explores options with her bankruptcy attorney.', '2012-06-17', 43, '/dXQIONLaVqJ5EXLBsMEWI7OTxAH.jpg', '2026-04-03T16:35:15Z', '2026-04-03T16:35:15Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('b5d59e12-0162-4584-bd86-d4ea9c14afe3', '1d556682-d9bb-47e1-993f-0b648a8daacd', 67, 'Episode 1252', '', '1979-02-27', NULL, NULL, '2026-04-03T17:36:33Z', '2026-04-03T17:36:33Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('b5d87e96-3b05-4e66-a1a6-db572288df6f', 'f812042d-eb85-432e-8047-3675886e0b1b', 37, 'Pantin'' at the Opera', 'Wishbone tells the story of Gaston Leroux''s ""The Phantom Of The Opera.""', '1996-11-06', 28, NULL, '2026-04-03T17:10:42Z', '2026-04-03T17:10:42Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('b5dc2376-2bf5-4c95-b707-b3f512bd465f', '5a824218-5831-4c6d-aef3-8b5ba9147532', 9, 'Episode 1584', '', NULL, NULL, NULL, '2026-04-03T17:36:34Z', '2026-04-03T17:36:34Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('b5e0ba41-d134-4f73-a691-3e97888da62c', '852a07b0-f228-4197-9147-7aeed79390bf', 4, 'Putting the Tiff in Tiffany''s', 'On the second day in the Hamptons, the ladies get a personal training session from Luann''s new fling; after having words with Ramona, Leah decides to take a vow of silence to relieve tension; Ramona hosts a "Breakfast at Tiffany''s" dinner party.', '2021-05-25', 60, '/1TFTVIVKq3jiAKd1AQiObnQuBbS.jpg', '2026-04-03T16:35:26Z', '2026-04-03T16:35:26Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('b5e30286-f8de-4144-8229-5aaac4211661', '225b0f03-984b-47f3-a1a3-d3e92175e39d', 14, 'Episode 14', 'with Christopher Trace, Valerie Singleton and John Noakes.', '1966-11-10', NULL, NULL, '2026-04-03T17:21:48Z', '2026-04-03T17:21:48Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('b5e9aa63-0eaa-4f78-9985-f2e10bb23eaf', 'f4938e7d-11a8-4756-b405-98bedd7c9b28', 3, 'Pat''s Birthday', 'Pat always thought he had managed to keep the date of his birthday to himself. He tells Jess not to give his secret away. When he arrives at the Post Office, all of the post is for Pat. As he then goes on his round, everyone he meets knows it''s his birthday! How did all those people know?', '1981-09-30', 15, '/jxjTU8YroNrvbaBLNHjlfejoajH.jpg', '2026-04-03T17:14:29Z', '2026-04-03T17:14:29Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('b5eb6d24-cf19-401e-8647-c1a1b1c2a50f', 'abeb8d07-5c86-4f6a-a110-b11cba2a4138', 3, 'The Painted Lady', 'When the gang arrives at a suffering fishing village, a mysterious spirit appears to help the villagers.', '2007-10-05', 25, '/jIOrXmDp5YcCwPoeaw6MGLU1rfd.jpg', '2026-04-03T17:40:48Z', '2026-04-03T17:40:48Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('b5f3f250-0701-4784-a997-7ab1a8ab2abc', '876145f4-b55e-4070-b35b-893a67f88bac', 12, 'The Hamptons Hangover', 'Unable to make peace with Jackie and Melissa, Jennifer questions whether she should stay in the Hamptons; the Giudice family visits Joe in ICE; Margaret tries to make peace with her mother; Jackie comes to a realization about her eating disorder.', '2020-01-29', 43, '/pCNNoHC1MZ3axILi9p52Z3uqCCa.jpg', '2026-04-03T16:35:18Z', '2026-04-03T16:35:18Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('b5f41543-9555-4a19-a402-fbd4fe3661c5', '10e64538-c78a-4cb0-82f9-17d14256dbac', 2, 'Cutting the Cord', 'Nervous, Sue overwhelms Frankie and Mike with text messages as she waits for her roommate to arrive. Hutch and Axl deal with an ant infestation. A mysterious bodyguard protects Brick at school.', '2015-09-30', 22, '/wceTF9A9GbCfuAzr4m4oDBBwsHJ.jpg', '2026-04-03T15:40:31Z', '2026-04-03T15:40:31Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('b5f9ce54-746b-488b-9c64-9603046b8f17', '5c16db9d-5e71-40eb-b44e-f559b2ddb8f3', 4, 'Thumbelina', 'Carrie Fisher and William Katt are Thumb-Sized Lovers...Video magic transforms Carrie Fisher into the diminutive heroine of Thumbelina, a girl so tiny she slept in a matchbox, so kind even field mice loved her, so beautiful she married a Prince. Raised by a kindhearted charwoman, Thumbelina is kidnapped and almost forced to marry first a Toad, then a crotchety Mole, played by Burgess Meredith. She manages, however, to escape to a beautiful garden kingdom where she meets a handsome equally tiny Prince, William Katt. This tale teaches us that everyone, no matter how unique, can find someone to love. Featuring production design based on the work of 19th century illustrator George Cruikshank. Thumbelina is a marvelous fantasy that will enchant big and small alike.', '1984-06-11', 51, '/gwc6wAgLMomsfoxjCD6Z12yuYPh.jpg', '2026-04-03T17:38:41Z', '2026-04-03T17:38:41Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('b5faeca9-6906-41b4-8ecb-36bc5e2f4b71', '1d455f60-41e8-4800-9359-4445e4df2b77', 6, 'Environment', 'A major crisis has arisen in the Neighborhood of Make-Believe. Their nearby landfill at Someplace Else has reached the saturation point.', '1990-06-01', NULL, NULL, '2026-04-03T17:35:45Z', '2026-04-03T17:35:45Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('b5fcafea-5893-49da-ac1d-8c3297f72d97', '6ef86c27-33e7-47e5-a053-483059dfd16d', 31, 'Episode 31', 'Remember Simon as an Elvis look-alike, Sarah wearing corsets and Peter slogging it out in the first ever London Marathon? They are just a few of Blue Peter''s 1981 highlights and others include Kevin Keegan in action in the studio, a meeting with Morph, the birth of Goldie''s puppies and leaping through fire with the legendary White Helmets.

If you missed any of these mile-stones today''s your chance to catch up and to look forward to 1982.', '1981-12-31', NULL, NULL, '2026-04-03T17:21:55Z', '2026-04-03T17:21:55Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('b60a2dd5-9f48-49ce-8bce-2087e5069161', '7b8e3988-fbf3-4cfc-aeb2-782ae5a64e2d', 28, 'Telly''s New Shoes', 'Telly makes a shoe wish so the Shoe Fairy will come and give him his first pair of shoes.', '2010-10-07', NULL, '/632T4wu2dX08hjxIWwV8aA8tKrH.jpg', '2026-04-03T17:36:46Z', '2026-04-03T17:36:46Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('b613721b-4f39-4cca-9273-ef37e3ea6b11', 'dec4a06d-731b-41e4-8b15-374f47d1f5c7', 9, 'Driving Miss Siggy', 'Unexpected visitors arrive for Teresa''s book signing. Meanwhile, Melissa focuses on her marriage by throwing a family dinner; Dolores'' business partner tries to fire her up; and Jacqueline gets inside perspective into her husband''s new business venture.', '2016-09-11', 43, '/y0rFAur4tNbQ02UAQw51ujD3mLO.jpg', '2026-04-03T16:35:16Z', '2026-04-03T16:35:16Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('b614ab2d-ff42-4343-82bb-6bd2532301d5', '04fb713d-9c59-45f7-8de0-acd7582daa53', 6, 'Last Fling Before the Ring', 'Dolores catches Frank in another lie. Jackie considers reconciling with her sister; Melissa plans little Joey''s communion. Margaret, Melissa and Teresa plan Danielle''s bachelorette party, but Danielle''s ways lead to an explosive confrontation.', '2018-12-12', 43, '/4iDjJz11BYxZ2eMCwRVZBd2nUf9.jpg', '2026-04-03T16:35:17Z', '2026-04-03T16:35:17Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('b616ffe4-9452-4833-a211-d67effe6df59', 'bc1b58b0-f2d6-4214-914b-231f27fb4d61', 14, 'Belly Up & Up', 'Verbal warfare and an agonizing decision lowlight Jacqueline''s relationship with her daughter. Meanwhile, Teresa''s financial woes escalate. And the wives trek to Kathy''s food-tasting bash, featuring surprise guests and unsavory behavior from Teresa and Melissa.', '2011-08-21', 43, '/iZ8NUbYPjrtBAwSGhJ5w2wBjIKA.jpg', '2026-04-03T16:35:15Z', '2026-04-03T16:35:15Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('b618edda-7db3-41fc-991a-f6a8b2e50e67', 'a2edcb57-63c1-4028-b87b-7faeae2c999b', 13, 'Time Out', 'With Nathan seeing his aunt, can Bernard manage to keep Nathan from being expelled?', '2004-03-30', 15, NULL, '2026-04-03T17:20:06Z', '2026-04-03T17:20:06Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('b624c3fa-5419-40a3-b38e-b84e57054051', '136b81d3-964d-4b8f-a214-92f00d96d6b9', 8, 'Big Bird''s toys', 'Forgetful Jones plays cymbals off-cue during "Pop Goes the Weasel" until he gets the timing right. The group examines autographs on casts and learns that worms are invertebrates, while Big Bird teaches others to put toys away.

Sponsors: T, X, 11', '1983-11-30', NULL, NULL, '2026-04-03T17:36:35Z', '2026-04-03T17:36:35Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('b628985a-2554-4dc4-8bd6-f8db79cce7b5', '89ba90ec-2c79-4a12-a11d-7465d1757683', 12, 'Rick and Morty The Non-Canonical Adventures: Gremlins', 'A claymation recreation of a classic scene from ‘Gremlins’.', '2017-07-11', 1, '/b8PqWFVfBvNWfTCijOnNV4hRaUc.jpg', '2026-04-03T15:40:41Z', '2026-04-03T15:40:41Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('b62ea7b6-9bb6-4d6c-82c7-b6a5d759a9d2', '42e591e2-2a88-4434-ae9f-3d4b1d685613', 8, 'Free Agent', 'Lock and load with the Pawn Stars when a D. Moore pistol from the Civil War shoots into the shop. Owned by a black officer from Louisiana, will Rick charge into this negotiation with guns blazing? Then, the guys check out a signed picture of President Benjamin Harrison. Does it take a Harrison to spot a genuine Harrison signature? And later, the guys put together a team to compete in a quiz competition. Will they let Chumlee join, or would they rather win?', '2013-06-20', 21, NULL, '2026-04-03T16:34:18Z', '2026-04-03T16:34:18Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('b631a7dc-dc42-465a-ba3b-e23987ba0b0b', 'd1d267dd-e27f-4543-acb8-0d28f676512a', 90, 'Episode 90', 'with Valerie Singleton, John Noakes, Peter Purves.', '1968-07-18', NULL, NULL, '2026-04-03T17:21:49Z', '2026-04-03T17:21:49Z');
