INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('b63f9e88-9d5d-4e67-988d-779b6fe1add9', '4892e2af-46c1-4b4e-ac81-eac161b5a347', 46, 'Episode 46', '', '1978-02-20', NULL, NULL, '2026-04-03T17:21:53Z', '2026-04-03T17:21:53Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('b64144ec-b788-421e-ba59-b1fb3808d0ff', '0ebba123-871d-4d2b-a054-eb85d2ad9450', 38, '''Twas The Night Before Easter', 'It’s Easter time in Crisper County and cable news reporter Marlee Meade is hunting for a way to help others. She cooks up a plan to save the old theater with a cast of costume-clad townies, massive props and a 20-foot robot rabbit to perform “Up With Bunnies.” Now there’s only one thing missing– the star of the show! When word spreads that singing sensation Cassie Cassava (Melinda Doolittle) is arriving to perform in her hometown church’s Easter service, Marlee schemes to steal the starlet for her own pageant! But when things go haywire, will it be curtains for Marlee’s dreams–or will she discover the true meaning of Easter and what helping others is really all about?', '2011-03-08', 30, '/1rScTnddsB0AbxLxbxBOIeXblkP.jpg', '2026-04-03T17:39:39Z', '2026-04-03T17:39:39Z');
