INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('b64222f9-cbcc-4191-9314-80787c377083', 'db81ad42-93a7-4926-89e5-d4cefa257b83', 10, 'The Shadow Player', 'In a total eclipse, Linda''s shadow breaks free and tells her how boring she is. But the Shadow Master is out to give the now fun-loving Linda a lesson. So, at a concert, Pete, Bronson and Linda must escape the Shadow Player so Linda can play.', '2001-04-11', 24, NULL, '2026-04-03T17:40:41Z', '2026-04-03T17:40:41Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('b6437acb-d0b3-4f24-b053-78bff49670ea', '5c4e51c6-e207-46ad-875c-72988eb1e13e', 18, 'Honor Thy Father', 'The Pawn Stars declare their independence when a document signed by John Hancock comes into the shop. Will this famous Founding Father''s signature be from the real thing or will they find it''s not worth the paper it''s written on? Then, a guy strums by with a 1934 Rickenbacher "frying pan" guitar. One of the first electric guitars ever made, will Rick cook himself up a fantastic deal or will he end up getting burned? And later, Father''s Day gets off to a rocky start when Rick presents a gift to the Old Man. Will he be able to smooth the tension at the shop or will this rift become a full-blown family feud?', '2011-06-13', 21, NULL, '2026-04-03T16:34:16Z', '2026-04-03T16:34:16Z');
