INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('b6514616-a070-47be-b4ba-6894aed53c1e', '66a11a09-aee2-4a7b-8543-ab080a9d1be4', 9, 'Live and Learn', 'Yolanda and Kyle are apprehensive about dropping their daughters off at college; Lisa Rinna shoots a movie with her husband Harry Hamlin and magician Penn Jillette; Brandi checks out her ex-husband''s new TV reality show.', '2015-01-13', 42, '/pb0mWrA11WUr5V2kvRc9VYm5tUT.jpg', '2026-04-03T16:34:56Z', '2026-04-03T16:34:56Z');
