INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('b6a2880f-2441-4a89-8745-6a1303f9f36c', '65d1cad8-0120-425e-ae9b-5020ce773b32', 7, 'The Truth Will Not Set You Free', 'The ladies wake up in New Orleans after Tamra''s dramatic departure; Shannon finds herself in murky waters when she shows up late to a gator boat tour; Katie''s explanation of contacting an influencer leaves her closest allies to question her stories.', '2025-08-21', NULL, '/xTvOMD6xNN7sALE4XGudQ9FFLhn.jpg', '2026-04-03T16:35:36Z', '2026-04-03T16:35:36Z');
