INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('b6b1365b-1706-4bf0-bf5b-0439f5c026a8', 'ca19f895-1514-4988-a709-95e84eab7cee', 2, 'Rick''s Gone with the Wind', 'Chumlee gets ready to rumble when a rare wrestling figure comes into the shop. Will he be king of the ring, or get smacked down? Then, a portable craps table is smuggled in. Will Corey take a gamble, or roll the dice? Next, Rick checks out a vintage Eclipse windmill. Can he generate a deal before it''s gone with the wind? And later, Corey gets Beatlemania when given the chance to buy a Starr''s drum kit. Will Corey and the seller Come Together or Let it Be?', '2020-11-16', 42, '/6ulp6VhzTisslG4tXtMxyHgqyZ7.jpg', '2026-04-03T16:34:22Z', '2026-04-03T16:34:22Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('b6b4e77e-5b70-404d-8fdb-fe2e03d38f2c', '3eee3180-acb7-429d-95af-f575bb4ab932', 4, 'The Tortoise and the Hare', 'LeVar has entered a bicycle race. He''s in competition not just with the other bikers, but with himself as well. This program also includes a lengthy piece on a karate class. Comedienne Gilda Radner reads the Aesop''s tale of "The Tortoise and the Hare," about an arrogant rabbit that''s over confident that he can beat a determined turtle in a foot race.', '1985-07-05', 30, NULL, '2026-04-03T17:36:15Z', '2026-04-03T17:36:15Z');
