INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('b6bedcab-d47d-493e-94cf-8cefa4c2907b', '5a422aed-bb8f-488b-927d-dbcf59270bbb', 1, 'A Warm Welcome', 'A new season begins as fresh peaches and familiar faces reset the Atlanta circle. Fresh off her divorce, Porsha hosts a couples night meant to celebrate new beginnings...', '2026-04-05', NULL, NULL, '2026-04-03T16:34:51Z', '2026-04-03T16:34:51Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('b6c2a74e-7385-4823-8ae8-8abeee95d98e', '5c16db9d-5e71-40eb-b44e-f559b2ddb8f3', 2, 'The Princess and the Pea', 'Prince Richard is looking for something to complete his life. The royal fool(jester). Helps him decide that he needs a wife, with a demanding mother and a dumbfounded father, that''s all he needs in his life, until Alicia comes along. She is kind and gentle, and persists that she''s a princess. Richard has had it with the demands of his mother and hates all of the princess presented to him, so he decides to marry Alicia. The mother however, is not so sure Alicia, so she puts her to a test to see if she is a real princess which has hilarious consequences! Liza Minelli is classically funny as Alicia. "The Princess and the Pea" is great family fun!', '1984-04-16', 51, '/sycREibCHeAP9ndREwZAdsGtIfI.jpg', '2026-04-03T17:38:41Z', '2026-04-03T17:38:41Z');
