INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('b6e3fe54-132c-4448-807f-d4be23405218', '8bae6aa3-4b55-4fa6-bc15-8f4317bd1f13', 43, 'Lady Elaine''s Purple Phase Pt 3', 'A purple disk drops into the Neighborhood of Make-Believe, giving Lady Elaine and others information on Planet Purple. She tries to emulate the lifestyle of all the Pauls and Paulines on the planet.', '1972-04-19', NULL, NULL, '2026-04-03T17:35:40Z', '2026-04-03T17:35:40Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('b6e75570-d209-419e-9f92-5a75d127e44e', 'c21dbd22-5e2e-4414-bb67-750399aaf6f0', 28, 'Ring around a Rockne', 'The Pawn Stars are blown away when a signet ring that belonged to mob boss Lucky Luciano comes out of hiding. Can the guys make the seller an offer he can''t refuse, or will this deal go to sleep with the fishes? Then, Rick is in the red zone when a letter signed by legendary football coach Knute Rockne steps up to the line of scrimmage. Will Rick win one for The Gipper, or will he fumble the negotiation? And later, Chumlee is presented with a collection of antique Cracker Jack toys. Will he go three strikes and out on these classic collectibles or will he win one for the home team?', '2012-02-27', 21, NULL, '2026-04-03T16:34:17Z', '2026-04-03T16:34:17Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('b6eb9156-0c3c-45d7-baf6-f2db9ead727c', '227b8429-0dfd-47e4-b874-c37da20c403f', 23, 'Bikes and Blades', 'Rick has a chance to buy a 1940 quartermasters spyglass that may be from a WWII ship. Can he discover the ship it came from, or will this deal sink? Then Corey considers buying a customized 1996 Harley Road King motorcycle, but there is one significant flaw - a pink flame paint job. Will Corey get in touch with his feminine side, or will this bike be too hot to handle? The guys also meet with a man hoping to sell knives that his grandfather smuggled back from WWII.', '2009-12-27', 21, '/6i4mWhE34JHiQko6s8o2V2rVTC5.jpg', '2026-04-03T16:34:15Z', '2026-04-03T16:34:15Z');
