INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('b6ef62a6-5b0f-4a2b-aab6-d279d6eb2de0', '991e78f1-03a5-4d26-8f75-75e11db4243c', 7, 'Go-Stop-Go: How People Make Sidewalks', 'Rogers and Chuck Aber discuss the proper safety gear for inline skating. Those in the Neighborhood of Make-Believe think they have made progress to curb Lady Elaine''s random squirts. Mr. McFeely shows a video on how concrete sidewalks are made.', '1999-03-29', NULL, NULL, '2026-04-03T17:35:48Z', '2026-04-03T17:35:48Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('b6f1ac53-c050-4ba0-8efc-e7f22c5abbbc', 'f4c40307-9b5e-4263-a4e0-dfa138131e7f', 54, 'Bedtime With Elmo', 'It’s nighttime on Sesame Street and Elmo doesn’t want to go to sleep yet, he wants to play! Elmo’s Daddy shows Elmo why everyone needs sleep, even little monsters. Children will enjoy this soothing tale as we watch Elmo and his friends get ready for bed; and parents will love the great strategies Elmo’s Daddy uses to get Elmo to sleep. But what if you are afraid of the dark, as Abby Cadabby is? Filled with lullabies and a special favorite book, dreams and happy thoughts; this video will enchant children of all ages, if they don’t fall asleep before it ends! Featuring the special DVD extra of Andrea Bocelli singing “Time to Say Goodnight” to Elmo.[1]', NULL, NULL, NULL, '2026-04-03T17:36:27Z', '2026-04-03T17:36:27Z');
