INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('b6faf8ce-9fd1-4b57-b820-3399e5d10665', '1c0a48a4-4d1c-424b-b54f-265883e6b26e', 1, 'Who’s Gonna Check My New Boo?', 'When Sheree introduces the ladies to her latest squeeze at Ross’ 40th birthday, the ladies reveal her new boo might be up to no good; as the walls close in on Sanya and her family, cracks start to reveal that their living situation isn’t so comfy.', '2023-05-07', 44, '/jKTYGvgsmpvFP17pmOxJj3mdvtO.jpg', '2026-04-03T16:34:50Z', '2026-04-03T16:34:50Z');
