INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('b73881a4-845d-4373-9dd7-e40779a5b101', '73ae1459-ba91-4185-a9da-bf6f2844af49', 24, 'Reunion (3)', 'The drama continues when Dorinda calls out Ramona for not supporting her; Dorinda becomes emotional as she defends herself against accusations that she has an issue with controlling her anger; the ladies attempt to end the reunion on a high note.', '2020-09-24', 60, '/2Hr3yF4A1RIfxSecTY66L23pQtf.jpg', '2026-04-03T16:35:25Z', '2026-04-03T16:35:25Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('b73df810-27a8-45e5-8e23-cf9e1114b6ea', 'e3a58098-e0da-42f7-9709-96dc0a4866c8', 10, 'Everybody''s Special', 'Cornflake S. Pecially feels everyone has forgotten that today is his birthday. It adds to the drama of the surprise birthday party, for which Daniel and Prince Tuesday have made a card. But Mr Mcfeely And Chuck Aber Stops By Videotape How People Make Ham Then As Soon As They Leave Maggie Stewart Brings Another Videotape On How People Make Ice Cream', '1995-09-19', NULL, NULL, '2026-04-03T17:35:47Z', '2026-04-03T17:35:47Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('b7403719-146f-4a3c-b2c9-a6c2a85e4f31', '04e133fd-c4a3-4dfa-8369-c6dcfd1e3a5a', 40, 'Episode 2005', 'Various Sesame Street adventures unfold with moments of learning and discovery throughout the day. Each scene brings its own brand of comedy and heart.

Sponsors: M, N, 8', '1985-01-11', NULL, NULL, '2026-04-03T17:36:36Z', '2026-04-03T17:36:36Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('b7436788-8964-4b6e-a7ad-caab298f08a6', '70d9e397-6813-4785-887d-27d034928bae', 4, 'Pingu''s Big Trip', 'Pingu is on his way home with his sledge when he sees a poster showing a tropical paradise. He is excited, and when he gets home goes into the shed. A lot of sawing and banging is heard. This catches the attention of Pinga, who is playing nearby, and she goes to listen at the door. Pingu tells her to go away. Pingu goes back into the shed to finish off the changes he is making to his sledge – he has put on a deck, and a mast for a sail. He finishes off by putting a small barrel on the sledge. He then raids the igloo for food, taking a fish and a loaf of bread, which he puts into the barrel. He leaves the shed and Pinga goes in, and is surprised to see what Pingu has been doing. She attempts to get into the barrel, but with both her and Pingu’s food supplies it’s too full. To make room she takes out the food and hides it in a nearby box, and gets into the barrel. Pingu then returns with a cloth that he puts on top of the barrel and sets off, pushing the sledge. After a while he’s a bit tired and peckish, so he stops for a rest and a snack. He takes the cloth off the barrel, and is surprised when the barrel jumps about. Pingu is then annoyed when Pinga pops up out of the barrel, and even more annoyed when he discovers that the food he put in the barrel is not there! Pinga then produces a couple of lollipops from her satchel that they eat. They continue on the long journey and stop when they reach another poster. Pinga cries because she is hungry and wants to go home, so Pingu consoles her and they set off home, arriving as it’s getting dark and the stars begin to come out. They go into the igloo and rapturously greet Mother, who has just finished baking a chocolate cake and seems blissfully unaware of their adventure, and they all sit down to eat.', '1995-07-06', 5, '/yWetGx2sFquxOk3rcZFASKXXv1e.jpg', '2026-04-03T17:22:19Z', '2026-04-03T17:22:19Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('b743af79-1bee-4891-9594-7f5a447171de', 'acac417e-2aa3-42e7-9e08-ed0d6071a3ee', 22, 'Reunion (3)', 'Bethenny and Carole continuing to go shot for shot about the dissolution of their friendship; the women relive their stomach-churning trip to Colombia; Carole revisits the highs and lows of her season; Tinsley takes issue with Carole’s protests about their relationship; Sonja discusses a new chapter in her life and delves back into her issues with some of the ladies; and the women end things by sharing their biggest regrets of the season.', '2018-09-05', 60, '/6MzNhUMrOW3AQFriyPf8lP5p6eB.jpg', '2026-04-03T16:35:25Z', '2026-04-03T16:35:25Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('b743de48-560c-41f6-8561-214bcb3aa2fa', '36e5c604-fea9-4bcf-8343-71bfaf60ecd2', 9, 'Theodore and The Welcome', 'Theodore gets his first try at welcoming ships into the harbor but isn''t sure what to say to them.', NULL, NULL, NULL, '2026-04-03T17:10:11Z', '2026-04-03T17:10:11Z');
