INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('b7469454-e8d8-46fd-b18b-86b46f4144c8', '244b0a34-284b-4ec1-b3a7-0e5abff6d0d1', 16, 'Paradise Lost', 'Baby Kate begins to learn to talk, but starts to not be able to understand Pal anymore. They go to the Dolly Llama for an answer.', '2010-04-08', 13, NULL, '2026-04-03T17:37:59Z', '2026-04-03T17:37:59Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('b748a84d-e6ae-42d4-8807-adf32cd501c4', '68138de2-0900-460a-b58e-480688f1e081', 27, 'As Different As Day And Night', 'Bear is having a hard day -- he misses Luna, who he loves very much. Pip and Pop make up a song, "Otter Love", to express their love too. 

Meanwhile, Ojo is furious with Tutter when he accidentally breaks her new toy airplane. She eventually forgives him, learning that friends are more important than things. 

Notes 

■This episode was adapted in storybook form as Love Is All You Need. 

■This episode won a DGA Award in 1999 for Outstanding Directorial Achievement in Children''s Programs.', NULL, 25, NULL, '2026-04-03T17:35:31Z', '2026-04-03T17:35:31Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('b74930e8-3d69-4e92-ae89-5dbc1bde8d59', '0442fb97-1460-4923-8558-b994078dc6b8', 12, 'Fully Charged', 'Wendy and her husband, Eddie host a “Sip and See” for their baby girl, and extend an invitation to Eddie’s estranged parents. Ashley and Michael seek counseling for their issues, while Karen continues to fight for her marriage. After weeks without an apology from Monique, Candiace decides to take a legal next step, and the possibility of jail time for Monique leaves the rest of the ladies in shock.', '2020-10-18', 42, '/1rgLnRELxi4Rnj98K4eYwIApg0h.jpg', '2026-04-03T16:35:40Z', '2026-04-03T16:35:40Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('b74e9db0-f882-4a87-9a8f-5f791d38950d', '6be74684-83e6-4d00-bd69-3e4fca97cabb', 1, 'Everything''s Bigger in Dallas', 'Everything’s bigger in Dallas - the egos, the attitudes, and the bank accounts. Cary hosts a benefit at her home where inappropriate behavior by best friends Brandi and Stephanie raises the ire of social maven, LeeAnne. Later, tensions boil over at a prestigious charity event as Stephanie is dragged into a feud between Brandi and LeeAnne. Meanwhile, Leanne’s best friend, Tiffany, questions whether her recent move back to Dallas from Los Angeles was the right decision for her and her rocker husband, Aaron.', '2016-04-11', NULL, '/imk142ASKMoiPAVllfH8HAceAp.jpg', '2026-04-03T16:35:03Z', '2026-04-03T16:35:03Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('b7624e0a-d0d2-47da-b0bf-402fe85d275f', 'f5266c49-eb29-4594-b5d9-f927edfee336', 13, 'The Dog Show', 'It''s time for the Annual Dog Show and the Farmer is sure Bitzer has a good chance of winning this year. When things don''t quite go as planned, the Farmer comes up with an ingenious idea which might help him win...', '2014-02-19', NULL, '/vp5lKOSEdffUqIKWMwQLVS9xrE4.jpg', '2026-04-03T17:39:32Z', '2026-04-03T17:39:32Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('b762bfef-7033-4ffd-bffb-9950ebf3f41e', 'ce91a034-5625-4fa6-b81b-db773be5502e', 1, 'Vive Legacy', 'Former New York City Housewives Dorinda, Kelly, Kristen, Luann, Ramona and Sonja reunite for a week in St. Barts; Kristen and Dorinda get off on the wrong foot; Kelly is concerned that Kristen seems more like a fan than a Housewife.', '2023-12-14', 48, '/994pZUFH7SXRS7cvEkRUZszHeHy.jpg', '2026-04-03T16:34:41Z', '2026-04-03T16:34:41Z');
