INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('b77ffb0b-3881-4406-8a90-1d7769a4ff43', '8bae6aa3-4b55-4fa6-bc15-8f4317bd1f13', 39, 'Lady Elaine Flies into Space Pt 4', 'The Brown Marionette Company opens one room in their studio for François Clemmons to give voice lessons. In the Neighborhood of Make-Believe, Lady Elaine radios back about her flight through space.', '1972-04-13', NULL, NULL, '2026-04-03T17:35:40Z', '2026-04-03T17:35:40Z');
