INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('b78501db-24e0-4597-80c3-c01f51debcac', 'bf3ffafd-7d45-4f2c-9f1b-28001bd082db', 27, 'Episode 27', 'Today Blue Peter cameras are at the Appeal Depot where parcels of the ‘Three B’s’ - Buttons, Badges and Buckles - are pouring in to reach the target of a guide dog puppy and a block of kennels for the new Puppy Walking Centre. If you haven’t sent your parcel yet, the address is: Blue Peter ‘Three B’s’ Appeal, Royal George Wharf, 88 Bankside, London Se1 Jg', '1974-12-09', NULL, NULL, '2026-04-03T17:21:52Z', '2026-04-03T17:21:52Z');
