INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('b7c62f73-7b40-476c-bb4b-57500a265792', '05fa5e18-78d2-41fe-ae30-0c242c7ffb6a', 26, 'The Big Freeze', 'Norman raises everyone''s temperature with the bed he builds for his pet lamb Woolly.', '2003-05-03', 10, '/14Ggqo4nXs738fX7oe7EMiq5KS3.jpg', '2026-04-03T17:14:38Z', '2026-04-03T17:14:38Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('b7c80180-01f1-46bc-8b58-b612d21b150b', 'a3a2c2fb-8276-412c-9d86-5175167be1d7', 78, 'Episode 78', 'with Valerie Singleton, John Noakes, Peter Purves, Lesley Judd', '1972-06-19', NULL, NULL, '2026-04-03T17:21:51Z', '2026-04-03T17:21:51Z');
