INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('b7cd5ffa-20ad-4207-820f-6fb852382c72', 'd122d150-fb7f-46fa-b9e1-63d3b08a118c', 2, 'Episode 2', 'Pod tells the Hendrearys that he and his family are leaving. Eggletina shows them a way out through the scullery drain, but as they make their way, a roaring wall of water rushes towards them.', '1993-11-21', 30, NULL, '2026-04-03T17:17:47Z', '2026-04-03T17:17:47Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('b7cda4ee-fa2a-4d32-96c4-2176b830e3c4', 'abeb8d07-5c86-4f6a-a110-b11cba2a4138', 2, 'The Headband', 'To better blend in as Fire Nation citizens, Aang enrolls in a Fire Nation school, giving himself an opportunity to learn more about the Nation and to enjoy life as a normal kid for the first time since he discovered he was the Avatar. Meanwhile Zuko, growing more and more paranoid about the Avatar''s false demise, brings himself to confront the imprisoned Iroh.', '2007-09-28', 25, '/2b5qDWFIxJDlv2d7FLPd9IDwdnk.jpg', '2026-04-03T17:40:48Z', '2026-04-03T17:40:48Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('b7cf6123-827a-4a39-8595-f9e66d1de2a4', '04e133fd-c4a3-4dfa-8369-c6dcfd1e3a5a', 109, 'Q is followed by U', 'An educational segment explores the letter Q and explains that it''s almost always followed by the letter U in English. Various words and examples demonstrate this spelling rule. Characters use this rule to help viewers understand how letters work together.

Sponsors: P, Q, 11', '1985-04-18', NULL, NULL, '2026-04-03T17:36:36Z', '2026-04-03T17:36:36Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('b7d1fd61-e8c1-40e9-bac0-21a88514658c', '4f18ac4c-8757-456c-a49a-224f00e6a9f7', 10, 'Curly Bear Chases Birthday Cake', 'Today is Baby Bear''s birthday, and he''s about to celebrate it in the courtyard! Telly arrives with his present, and Baby Bear goes over the plan: first they''ll play some party games, then treat themselves to his Mama Bear''s special chocolate-porridge cake. This cake is very special to him, and he''s worried that his little sister Curly will ruin the cake, so Telly promises to guard Curly from getting her grubby paws on the cake.', '2008-09-24', NULL, '/izo1eaS1VY9X16cGgQ793dcLf56.jpg', '2026-04-03T17:36:45Z', '2026-04-03T17:36:45Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('b7d50c14-b08d-4011-9731-f27074f462ab', 'e6254ae4-7d72-493b-8b37-b677d8b76c46', 61, 'Episode 726', '', '1975-01-27', NULL, NULL, '2026-04-03T17:36:31Z', '2026-04-03T17:36:31Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('b7dab1ee-1274-4db2-a6cc-b2d308348381', '7c542833-ed0a-4272-9c53-e822408ab434', 6, 'The King of Pontypandy', 'When Professor Pickles tells Norman and Peter about the King of Pontypandy, Norman sets out with a metal detector to find his crown.', '2024-10-07', 10, '/sInPyO2CrkDqalJ5FkacTU63OVU.jpg', '2026-04-03T17:14:42Z', '2026-04-03T17:14:42Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('b7dc91ac-5148-4df3-8db7-19a0198dccb3', '225b0f03-984b-47f3-a1a3-d3e92175e39d', 32, 'Episode 32', 'with Christopher Trace, Valerie Singleton and John Noakes.', '1967-01-16', NULL, NULL, '2026-04-03T17:21:48Z', '2026-04-03T17:21:48Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('b7e500a7-197c-4458-a778-af19cc51c6e6', 'df77dba2-bbda-4f38-9713-8d5c856f852e', 8, 'The Fancy Dress Parade', 'Old Bear and Bramwell Brown find an old basket full of bits and pieces and all the toys decide to have a fancy-dress competition. Old Bear agrees to be the judge. The toys have great fun making their costumes and they parade them proudly in front of Old Bear. The parade starts well but soon ends in chaos. Luckily Old Bear finds a way to make sure that everyone’s a winner in the end.', '1993-11-21', 10, NULL, '2026-04-03T17:18:55Z', '2026-04-03T17:18:55Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('b7e502b2-e6f6-4b54-bc9c-63d2551b495d', '3e60f995-fec2-4b9c-b1e7-322c6cd7d0d4', 4, 'Watch with Dorit and Garcelle 7.18', '', '2020-06-17', 43, NULL, '2026-04-03T16:34:54Z', '2026-04-03T16:34:54Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('b7e876fe-5d5c-4138-a3e0-2f2f4512f910', '751012d3-7df1-4084-8e96-0efd6559cf06', 5, 'The Intruder', 'A space probe from Earth lands on the Clangers'' planet.', '1969-12-28', 9, '/gUILZ8ZuvAGx87AwhMJLR8Lvs5J.jpg', '2026-04-03T17:23:53Z', '2026-04-03T17:23:53Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('b7e8f48c-734a-47b8-8e47-87aedd1b2903', '5c1b881f-ac58-4d72-b63f-209952d4f902', 67, 'Episode 67', '', '1980-05-05', NULL, NULL, '2026-04-03T17:21:54Z', '2026-04-03T17:21:54Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('b7eb39be-a622-4401-8b91-4cb8251d7d60', '8bae6aa3-4b55-4fa6-bc15-8f4317bd1f13', 42, 'Lady Elaine''s Purple Phase Pt 2', 'Rogers hears a harpist at Negri''s Music Shop. In the Neighborhood of Make-Believe, Lady Elaine announces she has discovered the Planet Purple, where everything is purple.', '1972-04-18', NULL, NULL, '2026-04-03T17:35:40Z', '2026-04-03T17:35:40Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('b7ef5f4a-62e0-47c8-ab6c-eda09775348a', '5c4e51c6-e207-46ad-875c-72988eb1e13e', 4, 'Missile Attack', 'The Pawn Stars take evasive action when a Cold War era heat-seeking missile guidance system locks onto the shop. Will the guys engage and try to blast this deal out of the sky or is this former military secret still too hot to handle? Then, Corey and Chumlee check out a 1986 Buick Regal. Customized from top to bottom, can Corey shift into gear and hit cruise control or will a bumpy negotiation make this low rider hit rock bottom? And later, a man hops into the shop looking to sell an original 1960''s Playboy Bunny uniform. Will Rick jump up his offer to buy this iconic costume or has the price for this sexy rabbit become over inflated?', '2011-04-11', 21, NULL, '2026-04-03T16:34:16Z', '2026-04-03T16:34:16Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('b7f221a9-1ffc-437a-9c1a-e4133a336cd2', 'd01919fb-98e0-42bf-b9d9-1cecf912f6e1', 41, 'The Grown-Ups Put On a Show (3826)', '', '1999-02-22', NULL, NULL, '2026-04-03T17:36:42Z', '2026-04-03T17:36:42Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('b7f7ebf7-8f2a-4a9c-b2e8-753869f9aaec', '2dadbc6b-684f-4884-a0b2-57bda7546dc2', 11, 'Time to Heal', 'Holiday plans are upset when Bernard injures himself. Could his watch give him more time to heal?', '2000-12-01', 15, NULL, '2026-04-03T17:20:05Z', '2026-04-03T17:20:05Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('b7f7fd06-207a-4954-a18c-71776427e926', '95ca8b6f-ccbc-431a-9d95-9b23367bbfed', 9, 'A Pretty Meltdown', 'Sutton and Crystal continue stirring the sauce at Lisa’s Bolognese lunch, as they lay all their lingering issues out on the table. Amid bombshell news tied to her divorce, Erika unexpectedly melts down to Kyle and Garcelle begins to question the truth. Meanwhile, the group is forced into quarantine and Lisa uses the time at home to dig up hidden treasures for her daughters to finally enjoy.', '2021-07-14', 43, '/1A14WYuKjwq2RgWUpHDLNJUKxbT.jpg', '2026-04-03T16:34:58Z', '2026-04-03T16:34:58Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('b7fef23b-c788-4a07-bcf8-6652235b1b77', 'f4c40307-9b5e-4263-a4e0-dfa138131e7f', 82, 'Season 9 Classic Cuts', 'A collection of classic scenes from Sesame Street''s third season, including:

- It Feels Good When You Sing a Song

- Bert & Ernie: Slice of Life

- Ray Charles: I Got a Song

- Fonzie and Cunningnham: Brushing Teeth

- Taxi Sounds

- School Pageant: Seasons

- Madeleine Kahn: Sing After Me

- Fireworks Alphabet

- Ten Commandments of Health

- Credit Crawl for Season 9

Appears on the DVD ''Sesame Street: Old School, Volume 2''.', NULL, NULL, NULL, '2026-04-03T17:36:27Z', '2026-04-03T17:36:27Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('b8015a71-813e-4dc4-8be8-966ba83104c6', 'fe19a277-aed8-44df-a4ac-fc1c4e9941b4', 1, 'New Attitude, Same ATL', 'The Atlanta ladies are back in the drama-filled second season premiere. Shereé decides to throw herself an “Independence Party” to celebrate her recent divorce, while Lisa and her husband discuss the idea of having another baby. The ladies attend actress and comedienne Niecy Nash’s birthday party, where Shereé and NeNe reflect on their tumultuous past. Kim decides she wants to design a line of wigs, and gets the ball rolling by going to cosmetology school. New housewife Kandi contemplates her new life with fiance AJ, while Sheree’s party plans start to go awry.', '2009-07-30', 43, NULL, '2026-04-03T16:34:45Z', '2026-04-03T16:34:45Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('b81c5502-79da-4aec-9012-76568de7dbc9', '3f27dc9b-9bbe-4aff-8cd9-90be629a885e', 9, 'Episode 9', '', '1997-02-27', 25, NULL, '2026-04-03T17:21:17Z', '2026-04-03T17:21:17Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('b81c7754-e94d-43cf-b319-468aa6662925', '204d86fb-d99c-4fd1-8dcd-9c1bcfd3c33f', 11, 'A New Friend', 'Lorca, a dragon in a wheelchair, comes to the School in the Sky and leads the friends on an exciting treasure hunt.', '2001-06-18', 30, NULL, '2026-04-03T15:26:04Z', '2026-04-03T15:26:04Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('b820f3ea-5f53-4224-be37-2dfc0573e474', '3fc7c152-e4f6-426a-a899-36ec454c4403', 78, 'Much Ado About Nodlings', 'Max accidentally breaks the Nodlings'' wagon with his bulldozer and without it, they are in trouble, making the Giant of Nod furious. When everyone''s attempts to fix it fail, Max sticks it out, determined to correct his mistake.', '2000-04-27', NULL, NULL, '2026-04-03T15:26:03Z', '2026-04-03T15:26:03Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('b8258fdd-8e5f-474d-899a-d6ae8cdf1cd4', '208e80de-61e3-4a2f-857f-c667ffc29134', 17, 'Christopher Reeve', 'Everyone has a superhero bug, donning costumes and trying acts to impress the star of Superman: The Movie.', '1980-02-15', 26, '/sX62tWu5hhYTkIxOqnLlxgvxQS6.jpg', '2026-04-03T17:35:25Z', '2026-04-03T17:35:25Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('b82881cb-029f-4f7b-bd0f-418ab42d3d27', '3ea743ef-0a22-47cf-b1d2-62f37e939253', 24, 'Zoe and Rosita Act Out "Little Red Riding Hood"', '', '2002-03-07', NULL, NULL, '2026-04-03T17:36:43Z', '2026-04-03T17:36:43Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('b82a7a82-99a4-4dc9-b3fe-4fa362fe88b9', 'd1863f2f-02ec-40ce-af64-db03fbe518a7', 12, 'Elmo Steps in for Super Grover', 'When Super Grover''s new sidekick Horatio keeps getting stuck in doorways, Elmo has to answer the distress calls. Also featuring ''Everyday Hero'' song with Aloe Blacc, Cookie Monster''s Aveggies parody, and Elmo the Musical-superheros. Brought to you by the letter H and the number 1.', '2016-03-26', NULL, '/mWWDePQ5V7exWDeuEEAlAJowiwM.jpg', '2026-04-03T17:36:48Z', '2026-04-03T17:36:48Z');
