INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('b84b8bbe-8661-4e99-9823-cad49f489613', 'de8ec769-16bb-436b-be43-aedc7e18a7d7', 6, 'Game Day on Sesame Street', 'Sesame Street has turned into a giant board game called Sesame Stoplight and Elmo, Abby, and Rudy are ready to play. When feeling frustrated during the game, they learn to stop and take a deep breath, think of a plan to solve the problem and then go try their plan. By working together and not giving up, they complete the challenges and win the game.', '2019-12-21', NULL, '/sWi9bjmymFUX3hHSx234JaRf9sb.jpg', '2026-04-03T17:36:50Z', '2026-04-03T17:36:50Z');
