INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('b8949465-c1c3-45a2-9a02-99d5deb06e5b', 'bb5a8843-6181-4a6d-bfdf-33ef2c6be7b8', 14, 'Barcelona Breakdown', 'In the aftermath of Kim''s text heard ''round the world,'' the women demand that Shereé put her friend in check. Porsha wreaks havoc on the streets of Barcelona, and Cynthia gets over her man problems by taking a dip in the lady pond. It''s all fun and games until things go off the rails during a heated debate. As tensions rise the trip comes to a surprising end for one of the ladies.', '2018-02-25', 43, '/pA8RDwZStnxuFSGZo6qDAvcWQ5u.jpg', '2026-04-03T16:34:48Z', '2026-04-03T16:34:48Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('b89769f0-c5bf-4688-ab08-18a2c7cc6a6b', '3ee646e8-23ae-4dec-bbc6-c7e6a210d55b', 129, 'A day at Birdland', 'Telly interrupts the opening sequence wanting to go to Birdland. Susan, Gordon, Miles, and some kids happen to be going there. Hoots welcomes everyone and introduces conductor Duck Ellington and the Sesame Street All-Animal Jazz Ensemble, with special guest Wynton Marsalis on trumpet.

Sponsors: L, Q, 19', '1991-05-09', NULL, NULL, '2026-04-03T17:36:38Z', '2026-04-03T17:36:38Z');
