INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('b8a41978-4ebf-4682-97ca-857a9780cd8e', '87f84063-82b3-45a4-936c-3759e5d91ce3', 17, 'Who’s Calling Who A Fraud?', 'The ride to Zion has the women on edge as Jen and Lisa face off over her refusal to choose sides between Jen and Meredith. Whitney aims to reunite the group with some spiritual healing, but her efforts quickly go to waste when tempers flare at the white dinner. Meredith’s integrity is called into question, and Jen finally gets a chance to ask for the truth.', '2022-01-16', 44, '/jAEIyLm8W6ci8C4P3zH1zXfXLSW.jpg', '2026-04-03T16:35:44Z', '2026-04-03T16:35:44Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('b8ac6e7d-c230-4ab9-a94b-90c8d1a8ed84', '94efc131-3a47-4bcb-a519-330e791ce905', 3, 'The Rescue Party', 'Percy is having a day off and is busy making sandwiches for a picnic. The rabbits are frolicking in the park and the youngest is being a bit too reckless. She tumbles down the hill and lands on Percy''s doorstep. He tells her that he is having a picnic and then warns her to "Look before you leap". She bounds off, barely heeding his words, more excited about telling the other animals that there is a picnic!', '1996-07-20', 15, NULL, '2026-04-03T17:19:01Z', '2026-04-03T17:19:01Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('b8b063cb-d41b-49c5-8699-53c8f361c217', '5a771f52-fe96-4ea2-b567-a8dde899059e', 1, 'Going, Going... Pawn!', 'The Pawn Stars are knocked out of the park when a drive to LA promises Rick a peek at Babe Ruth''s "called shot" bat. Corey has a giant jones for a miniature model of Ralph Lauren''s Bugatti Type 57SC.', '2017-10-16', 21, '/59FvYfQSdUdAQchHREbuVmrzw74.jpg', '2026-04-03T16:34:21Z', '2026-04-03T16:34:21Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('b8b654a8-cdb4-4976-b046-8b036f311f28', '2e8b61b6-6179-4204-9d2b-c12300836fc8', 13, 'Oakie Doke and the Shooting Star', 'The Corncrackers spot a shooting star in the night sky. Scoot and Hickory trick Root with a pretend flying saucer, so Root tricks them with a spaceman costume.', '1998-06-15', 10, NULL, '2026-04-03T17:19:25Z', '2026-04-03T17:19:25Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('b8b96af3-4419-4ba9-ada0-8a273acfe4fb', 'f812042d-eb85-432e-8047-3675886e0b1b', 38, 'Dances With Dogs', 'Lee Natonabah, a Native-American friend of Joe''s, speaks about Navajo culture and story-telling, while Wishbone imagines himself as a young brave in a story that Lee tells.', '1996-11-07', 28, NULL, '2026-04-03T17:10:42Z', '2026-04-03T17:10:42Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('b8bb9e34-50bb-4bce-a3d8-8a6c9359b481', '56108bee-d8f2-4a4b-bd6f-82205c30318e', 1, 'Stay safe near water with Rosie & Jim', 'This video has been produced by British Waterways, which run the country''s canals and rivers, with Ragdoll productions to help children to understand the dangers of Water in am imaginative way using Rosie and Jim, as well as Duck! The 7 minute video covers the safety points featured in a free Rosie and Jim leaflet which can be obtained from the address below. You might find it helpful to teach Children the safety song featured in the video which is sung to the tune of the Rosie and Jim theme song. British Waterways also produce "Rosie & Jim''s Waterway pack", containing Children''s activities and games plus guidance notes for parents priced £1.00 to cover postage and packing.', '1990-11-10', 10, NULL, '2026-04-03T17:19:36Z', '2026-04-03T17:19:36Z');
