INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('b8d3a09a-9b0a-4407-85cb-1a8846466af5', '05044f49-5f9c-4e7f-a74d-b2ff19475d0e', 7, 'Roses are Red, DNA is Blue', 'DIna eats chocolates alone and contemplates divorce; Teresa hunkers down to save her businesses; Melissa tries wooing her husband to spend more time with her.', '2014-08-24', 43, '/pewczy8ziFFuLE5CD61V4t9XTce.jpg', '2026-04-03T16:35:16Z', '2026-04-03T16:35:16Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('b8d572bb-d4a6-48a8-a2c3-80ddc99e23b7', '3415030f-f54d-42b9-a290-aaa05e246d86', 1, 'It''s Worse Than We Thought', 'As the Browns are busy prepping for Madison''s wedding, Mykelti drops a bomb of her own. And while Kody tries to mend fences between Meri and Mariah, he realizes that his own relationship with his first wife is still in a shambles.', '2016-11-27', NULL, NULL, '2026-04-03T16:34:30Z', '2026-04-03T16:34:30Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('b8dad0f2-b3d7-44d0-9e3c-d75e14c65819', '004abc4c-ce77-4df9-8c97-9f56ea8b37ce', 13, 'The Key', 'Kipper finds an old key and remembers it''s for a clockwork mouse in his toybox. His friend Mouse is unimpressed - it''s not like a real mouse. Kipper decides the two mice should have a race and when the clockwork mouse wins, Mouse has had enough. She decides to hide the key.', '2000-04-13', 30, NULL, '2026-04-03T17:10:49Z', '2026-04-03T17:10:49Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('b8e15608-a5b5-4769-93eb-fa89893c85b5', '204d86fb-d99c-4fd1-8dcd-9c1bcfd3c33f', 44, 'The Sorrow and the Party', 'Max is down in the dumps because he didn''t get invited to his friend Brian''s birthday party, so his friends all try to cheer him up.', '2002-04-10', NULL, NULL, '2026-04-03T15:26:04Z', '2026-04-03T15:26:04Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('b8e2633f-791e-4b04-8d5b-d5f2fce82df5', '050d8ae1-6cc1-4018-933d-b3c3d13de856', 62, 'Episode 62', 'See How They''ve Grown!

The terrible triplets are back today - the lion cubs from Windsor Safari Park - and Terry Nutkins will be choosing their names from the thousands of suggestions sent in by viewers. If your idea is picked, you''ll win a VIP all-expenses-paid visit to the park - there are lots of prizes for runners-up too!', '1985-04-18', NULL, NULL, '2026-04-03T17:21:57Z', '2026-04-03T17:21:57Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('b8e3b7f9-1d05-469e-afb1-769590d41332', '6f731e6b-d3c5-4de6-84e1-7a19cb650e86', 16, 'Capture the Pawn', 'Prepare for battle with the Pawn Stars when a rare 1589 book with the instructions for war and fortification guards the shop. Will Rick reinforce a good price or will he protect his wallet? Next, the game is on when Rick checks out an 1840s chess table. Will he capture the sale or will it be a draw? Then, a sale comes a calling when a pair of antique door knockers enter the shop. Will Corey welcome the deal or will he show them the exit? And later, an 1800s experimental rifle holds up the shop. Will Rick and Chum test out an offer or will they fail to fire?', '2015-12-10', 21, '/wVDNaR24FYAK3SemRnFL534FAto.jpg', '2026-04-03T16:34:20Z', '2026-04-03T16:34:20Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('b8eb79fe-e45e-4c6f-b8c1-0c51d0061de1', '34bdccfa-3c14-4e1c-9148-85c29aadc0e1', 29, 'Hyenas Are Cool!', 'The Kratts spend the night in Africa, intent to dispel the myths some people have about the hyena.', '1996-07-11', 30, NULL, '2026-04-03T17:11:47Z', '2026-04-03T17:11:47Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('b8eef833-e0c1-4c1d-91c2-38e351ac7cd3', '05c0e384-194c-4417-9f62-803eb615e409', 39, 'What to wear?', 'Title number 0039. Opens with Mister Rogers arriving with a letter. The Neighborhood of Make-Believe is preparing to hold a reception party for Sara Saturday. Handyman Negri goes to a men''s fashion show at the Museum-Go-Round so he can find the perfect outfit for the reception.', '1968-04-11', 28, NULL, '2026-04-03T17:35:38Z', '2026-04-03T17:35:38Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('b8f0851b-194e-48ba-bf40-026c63f02be7', 'b7538712-04ce-43a6-9163-62280bbb084b', 38, 'Rosita teaches Ernie how to be a Mexican cowboy (3888)', '', '2000-02-23', NULL, NULL, '2026-04-03T17:36:42Z', '2026-04-03T17:36:42Z');
