INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('b932df83-6799-49c1-933c-a714f41de4bf', 'bfdf87ff-01dd-4b54-94bd-19b384f41bdb', 19, 'Reunion (1)', 'The reunion kicks off as the women come together to grill Vicki on her journey from outsider, to insider, to outsider again. Tamra talks religion, being a peace maker and her award-winning a* while Meghan opens up about her baby blues and her relationship with Jimmy. When the ''70'' party accusations fly, new housewife Kelly stands her ground.', '2016-11-07', 44, '/94x8x3aQVJQcI9kaEhS03EBLhnw.jpg', '2026-04-03T16:35:33Z', '2026-04-03T16:35:33Z');
