INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('b957d335-7f27-4e36-a903-190ffc1adc07', '4da606e7-9d23-4682-8bd5-f535e1da706f', 17, 'Franklin and Otter''s Visit', 'Otter has returned for a visit to Woodland and Franklin was excited.  But soon he realizes how things have changed since Otter have moved away, including their once great friendship.', '1998-11-02', 12, NULL, '2026-04-03T17:40:15Z', '2026-04-03T17:40:15Z');
