INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('b95d9416-bc49-4c25-87fa-71fd31472c4f', '7bc54df3-f32a-454e-aef6-a9436c35d53b', 10, 'The Pie Restaurant Pt 5 - Opening of the pie restaurant', 'Dr. Yen Wang shows two laboratory rats, with which he wishes to show that the study of rats is intended to benefit human beings. The Neighborhood of Make-Believe opens the pie restaurant, but King Friday orders Bob Dog to move it to Someplace Else as a response to what he did in episode 9.', '1970-02-13', NULL, NULL, '2026-04-03T17:35:39Z', '2026-04-03T17:35:39Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('b96f129e-c468-45c1-a67e-5ae8fdeca17d', 'acac417e-2aa3-42e7-9e08-ed0d6071a3ee', 16, 'Guess Who’s Arguing At Dinner?', 'As the ladies head out for a day of shopping in Cartegena, Bethenny continues to unravel and the women’s patience with her begins to run out. Carole approaches Sonja for insight on Bethenny. Later over dinner, Tinsley, Ramona, and Sonja try to not eavesdrop on a heated conversation between the two distant friends. A comment Luann makes to Dorinda sends Dorinda off the deep end and puts their friendship on the rocks.', '2018-07-25', 60, '/3iMnV1YSGj0UDItgkFumveCeQWD.jpg', '2026-04-03T16:35:25Z', '2026-04-03T16:35:25Z');
