INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('b9786829-1c30-44a9-8db7-1c926a3aa3a6', '89ba90ec-2c79-4a12-a11d-7465d1757683', 14, 'Rick and Morty The Non-Canonical Adventures: Body Snatchers', 'A claymation recreation of a classic scene from ‘Body Snatchers’.', '2017-07-27', 1, '/uktZHU52N8xKjnhscxjGosD5LmI.jpg', '2026-04-03T15:40:41Z', '2026-04-03T15:40:41Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('b978aa2e-2b1c-42f2-b124-f07432272c2e', '70c8cb46-2494-4dd4-98f6-6bfb9b3faf73', 10, 'Off the Wagon', 'When Corey has a chance to buy an extremely rare Belgium-made 1942 Sarolea motorcycle, Rick has a big concern ... making money. Will they pony up and make a deal or let one of the rarest bikes in America roll out the door? Then the Pawn Stars have a chance to buy a Civil War sword believed to have belonged to a Confederate officer. Will Rick go to battle for this piece of American history, or will its authenticity spark a pawn shop civil war? Then later a woman brings in a cast iron printing press from the 1800''s. Will the Old Man ink an offer or invest in a Xerox machine instead?', '2010-02-15', 21, '/hQM2Op45tdiYBSsMiJAQFxhhjJE.jpg', '2026-04-03T16:34:16Z', '2026-04-03T16:34:16Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('b97b64aa-8124-43dc-b964-5e70f4010909', '332249fa-796b-4f92-b7f8-421d523b0bdc', 1, 'The Edge of Fashion', 'Marlo hosts a high-fashion gala to introduce her business, Le’Archive, to Atlanta’s elite, but not everyone is buying what she has to sell. Drew gets an Olympic workout with her new friend, Sanya, and an epic runaround from her husband, Ralph. Sheree returns with an exciting update on her boyfriend.', '2022-05-01', 43, '/jJNW8Osae0VOVnLJ2sthXoDgipr.jpg', '2026-04-03T16:34:49Z', '2026-04-03T16:34:49Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('b97b9d7c-6497-47ce-a981-a103b829a058', '78a02d50-e3dc-4549-844a-3cf357a32ef4', 15, 'Lei It All on the Table', 'The tea over-floweth when Kandi relays Porsha''s accusations to Cynthia, Shereé, Kenya, and Shamea, all while Porsha spills the details to her sister. Kenya gets a surprise visit from her brother and his kids that helps her realize she needs to make a decision about her relationship with Matt once and for all. Kandi and Todd plan a couples'' getaway to Maui for all the ladies. Phaedra treats Porsha to a day of beauty treatments in order to convince her to attend as her guest. Tensions erupt when Shereé''s attempt to lei it all out on the table backfires and Porsha finally pushes Kandi past her limit.', '2017-03-05', 43, '/blTbi23uL74GoKFM5DYqkoGD5WV.jpg', '2026-04-03T16:34:48Z', '2026-04-03T16:34:48Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('b9816c8a-70aa-4f02-aa08-da6859f833d3', 'a8f3a681-7abc-41e0-9988-9b8804d74611', 3, 'Brutal Honesty', 'As the Sister Wives prepare for Kody''s birthday, Christine tries to reconcile with Robyn by opening up about the problems she''s had since Robyn joined the family. How will Robyn handle this brutally honest conversation?', '2012-05-27', 21, NULL, '2026-04-03T16:34:28Z', '2026-04-03T16:34:28Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('b9822ea2-d861-4780-aacb-4a751b2794bd', '61e0c9d9-337e-4fe4-a0fd-e567b29af115', 11, 'Troop Salt Lake City', 'Heather and Whitney host a girl''s camp to reunite the women, but fractures in the friend group only become more evident. Meredith invites Mary to a gallery to work through their issues, but things quickly go awry. Lisa and Angie meet up to attempt to make amends, but Bronwyn threatens their reconciliation when she reveals what Angie and Whitney have been talking about behind everyone''s back. As her bat mitzvah approaches, Meredith hosts a Shabbat dinner. Mary has a heart-to-heart with Robert Jr. and learns a dark truth.', '2024-11-27', 55, '/gteq7K8BGhJPkH1sArWPmDgYOf2.jpg', '2026-04-03T16:35:45Z', '2026-04-03T16:35:45Z');
