INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('b9fb1876-4b5b-4d98-8c5f-7db711fd795e', '4d2cac0f-38fd-438b-8afa-acf43952e535', 308, 'Episode 308', 'with Christopher Trace and Valerie Singleton.', '1964-11-05', NULL, NULL, '2026-04-03T17:21:47Z', '2026-04-03T17:21:47Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('ba033c5a-77e0-4a24-81a9-1352f87da5ad', '10e64538-c78a-4cb0-82f9-17d14256dbac', 19, 'Crushed', 'Sue develops a huge crush on one of her college professors and goes to extremes to get him to notice her, and Frankie and Mike agree to meet Brick''s girlfriend Cindy''s parents, who end up being just as quirky as their daughter.', '2016-04-06', 22, '/mdQtLUzbsgmLgEFikJqXlRtaXBK.jpg', '2026-04-03T15:40:31Z', '2026-04-03T15:40:31Z');
