INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('ba0a1384-2695-4933-97a2-ae953e271d99', '54c29014-2dbd-49ff-a23f-cf4c546e0b3a', 18, 'Something to Sing About', 'The wives return from Montana as Aviva discovers she''s been the butt of jokes. Meanwhile, Ramona''s husband prepares for an open-mic gig. Heather and LuAnn are also slated to perform, but drama soars when LuAnn backs out.', '2014-07-08', 60, NULL, '2026-04-03T16:35:23Z', '2026-04-03T16:35:23Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('ba104048-3682-4c22-8465-25aeed3bd4d0', '05c0e384-194c-4417-9f62-803eb615e409', 84, 'Campsite Opera', 'Reardon and Lady Aberlin are trying to get King Friday''s permission for their opera. Lady Elaine is a campsite owner in the opera and is not pleased with some guests that appear.', '1968-06-13', NULL, NULL, '2026-04-03T17:35:38Z', '2026-04-03T17:35:38Z');
