INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('bb25748f-c7b7-492f-8254-ee8cb60535d3', 'ad4e4348-3334-4a08-8928-455d9ba524c1', 8, 'Señor Wences', 'In honor of Señor Wences and his puppets, Kermit decides to do something new -- a puppet show! Fozzie wants to do a marionette act with a Dancing Clown puppet, but the marionette eventually pulls Fozzie down on the stage with him and takes control of the strings himself.', '1980-11-23', 26, '/yoBPnPyfwqLuLfGOvyxmsjYVttE.jpg', '2026-04-03T17:35:25Z', '2026-04-03T17:35:25Z');
