INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('bb816318-86c4-4fea-a1ae-1382531f0edd', 'd0b78f22-678e-4e46-9d61-aac40ba206b8', 17, 'A Double Shot of Brandi', 'Kyle plans a girls’ trip to Provence, France. Erika and Lisa Rinna are astonished by Camille talking out of both sides of her mouth about Dorit – and are certain Dorit will call her on it. Denise spends a wild night with new friend Brandi Glanville and gets an earful about the other women.', '2019-06-04', 43, '/tM1vA4WAj1YXpTIWDtWwUJbI9nk.jpg', '2026-04-03T16:34:57Z', '2026-04-03T16:34:57Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('bb86f172-5e3b-4ff7-852e-969f9e88fe2d', '65524b14-e29e-4b04-81d3-fbebe525e9ec', 20, 'Franklin''s Expedition', 'Franklin and Bear go on an expedition for the Woodland Trail Blazers.', '2004-07-24', 12, NULL, '2026-04-03T17:40:16Z', '2026-04-03T17:40:16Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('bb8a358e-1942-4ac0-86d6-1493f9b287de', '227b8429-0dfd-47e4-b874-c37da20c403f', 4, 'Knights in Fake Armor?', 'It''s clear that this is no ordinary pawn shop as the Pawn Stars wheel and deal items ranging from an old school Pac-Man to a Medieval Jousting Helmet. If these items are as real as their owner''s say they are - they could be worth up to $30,000! Then, an old timer brings in a pristine 1884 Trap Door rifle that the guys buy hoping that it still fires. But, when the gun range owner says that simply firing it could cause a "catastrophic malfunction" the guys decide it''s time to bring out their human guinea pig.', '2009-07-26', 21, '/rP5CCApTd1LNPN8YA6iJ0KTWTT5.jpg', '2026-04-03T16:34:15Z', '2026-04-03T16:34:15Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('bb8ca0a1-ef7c-4f8f-9992-744d5494c018', '6f323ed7-50f3-4902-a8b2-2072c5d0489b', 6, 'The Demon Headmaster (Part Six)', 'Dinah begins to work out what is going on and everything hinges on her friends rescuing her.', '1996-01-18', 25, NULL, '2026-04-03T17:40:34Z', '2026-04-03T17:40:34Z');
