INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('bb922295-fd61-46a9-8fc7-d9f1f7e153aa', 'c9adc698-be92-4dd7-94ad-d8f6759361ca', 4, 'Episode 4', 'Chef Brockett is planning to add a soda fountain to his bakery. In the Neighborhood of Make-Believe, Lady Aberlin brings back the toy horse which, when a string is pulled, says "I know". X gives her a toy seagull which says "you know" when a string is pulled.', '1973-02-22', NULL, NULL, '2026-04-03T17:35:40Z', '2026-04-03T17:35:40Z');
