INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('bbedb223-5a6c-405a-bf5c-529d2b1ae112', '1c0a48a4-4d1c-424b-b54f-265883e6b26e', 17, 'Reunion Part 1', '', '2023-09-03', NULL, '/1EZ3Omc7S8fYd4T9Tz40kbdCn4q.jpg', '2026-04-03T16:34:50Z', '2026-04-03T16:34:50Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('bbef9a51-bdba-423f-9f5e-a81671bdf48b', '4fe93658-c463-4329-8e64-9d523869c2cb', 11, 'Gone with the Schwinn', 'The Pawn Stars are brushed with Vegas royalty when they are presented with a huge truckload of personal tapes from Rat Pack legend Sammy Davis Jr. Will they be singing a sweet tune to make this deal or will they be left reaching for the stars? Then, Rick meets a man with a mysterious miniature cannon believed to be from the 18th century. Will Rick make a booming offer for this little noisemaker or will it prove to be all bark and no bite? And later, Corey and Chumlee have a chance to buy a pair of pristine 1950''s Schwinn Phantom Bicycles. Will they pedal themselves up a difficult negotiation or will they be thrown off their game by one sharp turn?', '2010-10-25', 21, '/wDK9RpymogCOhXdlPnYEIvTkkZ3.jpg', '2026-04-03T16:34:16Z', '2026-04-03T16:34:16Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('bbf52b72-39ee-425f-b98f-7a720bcec93f', 'e03d79bd-e01f-4414-b0b3-f3b5f26e97f4', 4, 'The Quarry', 'When Axl is suspended for skipping school, Mike decides it''s time to teach his son a lesson about life and makes him go to work with him at the quarry. But Mike''s master plan backfires when Axl likes the job so much that he wants to quit school and lead the life of a quarryman. Meanwhile, Frankie is devastated when she fears that she accidentally prayed away Sue''s cross-country team after it''s cut by the school; and while practicing a magic trick, Brick makes the main TV remote disappear - and can''t figure out how to make it reappear.', '2010-10-13', 22, NULL, '2026-04-03T15:40:29Z', '2026-04-03T15:40:29Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('bbf88417-f75d-4368-8c4e-4985e25fcc77', 'd1d267dd-e27f-4543-acb8-0d28f676512a', 65, 'Episode 65', 'with Valerie Singleton, John Noakes, Peter Purves.', '1968-04-22', NULL, NULL, '2026-04-03T17:21:49Z', '2026-04-03T17:21:49Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('bbfaf2aa-5d61-4324-9733-aac426d6ad92', '97d7ff20-e6ff-4dbb-bcdd-fd87a1d0fa4e', 9, 'Jumpin'' Jake Flash', 'A set of replica Muppets has Chum feeling green with envy; But will going gonzo over these furry friends land him the goods? Meanwhile, Rick flips over an autograph book from the 1800s, but are the signatures the real deal? Next, when a pair of pants supposedly worn by Keith Richard rolls into the shop, Corey teaches his brother Jake you can''t always get what you want. And later, Rick has a "finger-lickin" good time when he pops over to a gallery in L.A. Will he find the secret ingredient to success, or walk away feeling spicy?', '2023-05-10', 41, NULL, '2026-04-03T16:34:23Z', '2026-04-03T16:34:23Z');
