INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('bc002db9-72df-464d-9b00-e74349cc9b8b', 'ca3f764e-b330-4980-bd7a-2908a73b77b6', 23, 'Reunion (3)', 'Kim Richards exclusively reveals to Andy Cohen, "I am an alcoholic" and discusses life after rehab. Housewife friend Dana Wilkey also appears to recount with her recollection of Game Night followed by the husbands who field viewer questions.', '2012-02-13', 43, '/8huqSp3mFgnphiEk79H1qbJOpEt.jpg', '2026-04-03T16:34:55Z', '2026-04-03T16:34:55Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('bc08d2a3-05c6-4633-b183-65942e8b35f8', '913f846d-85df-4694-8dd4-0d5909f78887', 5, 'Perseverance', 'During a trail bike race with her friend, Zach, Annie is left in the dirt and becomes discouraged.  She rests up at Plato’s Peak, just enough time to hear the story of The Tortoise and the Hare, which teaches her a valuable perseverance lesson: Slow and steady wins the race.', '2000-10-22', 30, NULL, '2026-04-03T17:38:35Z', '2026-04-03T17:38:35Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('bc0f56d7-62f5-4773-915f-041eaf23c994', '1f34e241-4c1d-4586-921a-1c5aeb1fbbaa', 78, 'A day with books on Sesame Street', 'Luis is swamped with work at the Fix-It Shop, and Maria is too busy reading her book - The Adventures of Captain Swashbuckle - to help. While fixing Big Bird''s record player, Luis tells him of a story he''s reading about Captain Swashbuckle, a pirate.

Sponsors: P, U, 7', '1986-03-05', NULL, NULL, '2026-04-03T17:36:36Z', '2026-04-03T17:36:36Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('bc12819f-b8d5-432a-b719-4687bf3e5596', 'bbe54839-4a6e-45e1-b3c5-7b77f98a0e86', 8, 'Episode 8', '', '1994-02-23', 25, NULL, '2026-04-03T17:21:16Z', '2026-04-03T17:21:16Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('bc13d6a6-f7af-485c-817a-9fd235c738b5', '7c756336-29db-4634-b976-e993e8f51da2', 11, 'The Grand Dame Slam', 'A sunset cruise hits rough waters when Charrisse corners Karen about her overbearing hosting duties while in Bermuda. Also, Robyn discovers many men are interested in her. In Potomac, Michael makes changes at the restaurant, and Karen breaks news about her coveted Potomac address.', '2017-06-18', 42, '/qtu1OaDwxWzrfBbJ5y6d7XztShm.jpg', '2026-04-03T16:35:39Z', '2026-04-03T16:35:39Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('bc19fc33-eb77-4e0f-994c-88b382bfab67', '3fc7c152-e4f6-426a-a899-36ec454c4403', 13, 'The Giant of Nod', 'Zak and Wheezie practice for tonight''s concert hosted by Quetzal at Singing Springs, but they war over various songs they wanted to play and disturb the nap of a twelve-inch creature known eponymously as "The Giant of Nod". He desperately throws them in a tree trunk, so it''s up to them to save the gang so they can make it to the concert.', '1999-09-21', 30, '/uYwl6qcISwyZgFb7NjnCEQj1pTr.jpg', '2026-04-03T15:26:03Z', '2026-04-03T15:26:03Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('bc1d1296-4ec6-4589-b757-bba9247ac141', '7b8e3988-fbf3-4cfc-aeb2-782ae5a64e2d', 31, 'Max the Magician', 'Everyone tries to figure out the secrets to Max the Magician''s tricks, only to discover that they''re really just math.', '2010-10-15', NULL, '/zVtdwejXYJXkLfoNdx8ttdB1wm3.jpg', '2026-04-03T17:36:46Z', '2026-04-03T17:36:46Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('bc24e70f-9de2-4c58-80fb-f74ee4dad086', 'ea73e13c-6962-4804-8305-c303df65f89f', 48, 'Lady Elaine’s numbers', 'Officer Clemmons reminds Rogers that Chef Brockett''s birthday will be in two days'' time. In the Neighborhood of Make-Believe, Lady Elaine tells King Friday he cannot always be number 1. This shows that all the house numbers on all the locales are coming down.', '1969-04-16', NULL, NULL, '2026-04-03T17:35:38Z', '2026-04-03T17:35:38Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('bc25823b-d2e5-4506-b079-81431482687c', 'f30bbf81-8770-4e74-b68b-280e7c85b52f', 12, 'The Busboy', 'George inadvertently meddles in the life of a busboy, by getting him fired. He tries to rectify things; however, he winds up compounding them by losing the busboy''s cat. Elaine discovers that a week is much too long to have a houseguest. She does everything in her power to get him out. The busboy''s life is saved and made for the better after his involvement with George, until he meets Elaine''s houseguest.', '1991-06-26', 23, '/sxybPj7nX8a0M4bULeVWzFVb2R0.jpg', '2026-04-03T16:34:09Z', '2026-04-03T16:34:09Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('bc3018b1-2758-4290-aef4-9363f69204d0', 'efd2082e-32f5-4edd-9a7b-a4326d6992c9', 25, 'Welcome to Sesame Hospital', 'Rosita, Abby, and Telly play hospital and pretend to be a doctor, nurse and x-ray technician. Chris pretends to be their patient and they help heal his funny bone.', '2019-05-04', NULL, '/hiDlDqfd2kkLwCnw2onOk8fphPc.jpg', '2026-04-03T17:36:49Z', '2026-04-03T17:36:49Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('bc306ccb-d44c-454a-a018-5bd08e4cff40', 'ea73e13c-6962-4804-8305-c303df65f89f', 24, 'Magic Kite (4) - Teaching the magic kite', 'X wants the magic kite to add. Joey Hollingsworth returns just as Corny makes a rocking chair for kites.', '1969-03-13', NULL, NULL, '2026-04-03T17:35:38Z', '2026-04-03T17:35:38Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('bc37c431-9675-4c4b-9985-707d8efd1e65', 'd199804f-ccf5-4e36-8929-56c1e356b74d', 42, 'Episode 967', '', '1977-01-25', NULL, NULL, '2026-04-03T17:36:32Z', '2026-04-03T17:36:32Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('bc392744-f6e4-44eb-86c5-14cab42d2cc3', 'bd8a516b-9872-472d-a838-7aff1070fea3', 4, 'John Cleese', 'Gonzo catches a cannonball with his bare hand, which stretches his arm out. Fozzie and Floyd crack jokes about the situation. Gonzo turns to John for help, but John ends up pulling the rest of his limbs out to match.

Meanwhile, John isn''t pleased with being on the show. He''s tied to his chair before the show, he complains about the number of pigs and monsters on the show, and he gets roped into doing a closing number.', '1977-10-21', 26, '/4iM8Yc12oTKHNTvgi7hkPfRQsyZ.jpg', '2026-04-03T17:35:24Z', '2026-04-03T17:35:24Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('bc3991bf-9be8-4d50-ba06-b49a7af8fd24', '01b3a1e3-d0e8-4f2b-a56d-9d55669ab5f2', 12, 'One on One: Part 2', 'The Browns sit down individually to talk about their most contentious season yet. Kody, Christine and Meri answer burning questions about the current state of their relationships, and the rest of the family discusses the challenges brought on by COVID.', '2022-02-06', NULL, '/wqFqFAxKXvh3SsxiKzdFgk3rOuD.jpg', '2026-04-03T16:34:32Z', '2026-04-03T16:34:32Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('bc449752-c5f2-49de-a5ff-02aa0d8b487b', 'e3a28669-91b5-45f7-bb73-5006acc084e8', 11, 'The Kite', 'What''s more fun than a kite on a windy afternoon? Nothing when Shaun and pals are concerned.', '2007-03-12', 7, '/2htsQuYesFWARz9UiTzzzaus1Ko.jpg', '2026-04-03T17:39:31Z', '2026-04-03T17:39:31Z');
