INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('bc5c68b6-5f91-49ae-9a49-446c269be88f', '6f731e6b-d3c5-4de6-84e1-7a19cb650e86', 23, 'Pawn Brothers', 'Ring in the change with Pawn Stars when a 1894 S Barber Dime jangles into the shop. Will Rick call heads on a deal or turn tail and run? Next, a John Belushi autograph lampoons its way in. Will Corey laugh all the way to the bank or will he be left singing the blues? Then, a 1950s Jim Henson puppet pops in. Will Rick have a hand in an offer or will he put a sock in it? And later, a 1965 Schwinn bicycle strolls into the shop. Will Rick ride off with a bargain or will the gears fall off?', '2016-01-20', 21, '/ajMQd64ne59ltIcfvFZFJIqaXM6.jpg', '2026-04-03T16:34:20Z', '2026-04-03T16:34:20Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('bc5dedd9-be1d-4c4b-bcdf-788a268a191e', '01916834-25ec-43d6-9a1b-8ea5d9630adc', 15, 'Treasure Hunt', 'Shaun must find Bitzer''s missing bone, but X doesn''t always mark the spot.', '2025-06-13', 7, '/l3a2isCFSeGWZJpnEKVot0BVTcw.jpg', '2026-04-03T17:39:33Z', '2026-04-03T17:39:33Z');
