INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('bcac8f71-b99e-4c6a-97d8-5046b3930419', '6c47406b-b3d6-40d8-b483-1ae1b3d30009', 5, 'Brave New Rescues', 'Fireman Sam is back for more heroic adventures in fire safety! Fireman Sam and his friends in Pontypandy work together to save the day when Mike’s kitchen catches fire, Dilys gets stuck out at sea and Norman cries wolf! Come along with the hero next door and his brave brigade for some courageous adventures and daring new rescues the whole family will enjoy!', NULL, 10, NULL, '2026-04-03T17:14:36Z', '2026-04-03T17:14:36Z');
