INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('bcbc1292-1352-470e-8ca6-4ef8bb6eda53', 'f5c042dc-0657-42e8-a37d-247414140632', 16, 'Southfork Goes South', 'Recreating the infamous “Who Shot J.R.?” moment from the hit series Dallas, the ladies try to solve the mystery of "Who Shot Brandi?" The husbands join their wives for a day of fun and armadillo racing, but the absence of Eduardo proves too much for Kary to handle. A night of partying turns destructive when Kary and Brandi break into the iconic J.R. Room, causing the other ladies to confront them about their behavior.', '2021-04-27', NULL, '/712G3EkfZ630lcxGtGYbP5b9Waj.jpg', '2026-04-03T16:35:05Z', '2026-04-03T16:35:05Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('bcbea09d-87c0-4bee-a215-b27be4c2897c', '73ae1459-ba91-4185-a9da-bf6f2844af49', 2, 'Stooping to a Lower Level', 'In the city, Tinsley defends herself to Sonja and Leah over her continuing feud with Dorinda. To celebrate the end of summer the ladies head out to Ramona’s house in the Hamptons for a long weekend. Tinsley’s flu leaves her voiceless and Leah’s tattoos become big news. Despite being relegated to the basement, Luann apologizes to the women for her behavior over the last year.', '2020-04-09', 60, '/ofvkatcwtsgcdFFRthY8Q7gJzo0.jpg', '2026-04-03T16:35:25Z', '2026-04-03T16:35:25Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('bcc182d7-4fe0-408b-84f8-63f6ab4dce81', '69b3befe-579a-43ad-a7d6-ec30ffe3adf7', 4, 'Episode 1059', '', NULL, NULL, NULL, '2026-04-03T17:36:32Z', '2026-04-03T17:36:32Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('bcc4f47a-7d2c-43bd-8ef8-a78cf61ae257', 'acac417e-2aa3-42e7-9e08-ed0d6071a3ee', 19, 'Life is a Cabaret', 'It''s the night of Luann''s cabaret show, #CountessandFriends. Over pre-cabaret drinks, Dorinda, Carole, and Tinsley go over some shocking guest list faux paus on the Countess''s part. During the performance, Luann gets heckled, and Sonja shows some skin. At the after party, Ramona has a burning question for Bethenny and Dorinda has some parting words for Luann.', '2018-08-15', 60, '/6vkHva0CuLc9L2ZbvMeKpH1pmTp.jpg', '2026-04-03T16:35:25Z', '2026-04-03T16:35:25Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('bcc71983-6962-49a5-a6dc-8e1db9589032', '4861ce46-9045-43c7-963f-27b4ea539804', 23, 'Episode 153', '', '1970-01-21', NULL, NULL, '2026-04-03T17:36:28Z', '2026-04-03T17:36:28Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('bcc73950-b94d-4620-9eda-254e410e9161', 'f6015d9a-ece4-414a-a00b-06cf689fe40b', 16, 'The Big Birthday Balloon and Alesha', 'We announce the winner and runners-up of our Big Birthday Balloon competition, with an extra special reveal of the winning balloon! Britain''s Got Talent superstar Alesha Dixon tells us all about her new book and we also announce another competition.', '2018-04-12', NULL, NULL, '2026-04-03T17:22:10Z', '2026-04-03T17:22:10Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('bcccad6b-b413-4c9e-90b0-a9ac2a445cc0', '02c86ae3-8c3b-4cc0-8e1f-0b27d01dcd91', 1, 'Welcome One, Welcome ATL', 'In the premiere episode of Real Housewives of Atlanta, NBA wife DeShawn and her family see their custom built mansion for the first time and she begins the search for the perfect staff to run it. Real estate powerhouse Lisa is learning to balance business and motherhood with her NFL hubby''s support. Meanwhile, after a three-year divorce battle with former NFL player Bob Whitfield, socialite Shereé plans a birthday blowout at her estate to celebrate her new life, and cracks the whip on her staff to make sure no detail is missed - from the Louis Vuitton cake to the exclusive guest list. All the Housewives are invited, including NeNe, who has ongoing tension with Shereé. In between shopping sprees funded by her mystery multi-millionaire boyfriend, "Big Papa," blonde bombshell Kim meets NeNe for lunch and they plan to arrive at Shereé''s party fashionably late, but a scene erupts when one of them isn''t on the list.', '2008-10-07', 43, NULL, '2026-04-03T16:34:44Z', '2026-04-03T16:34:44Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('bcd176da-3e45-47d7-ae8e-70672674b3c1', '332249fa-796b-4f92-b7f8-421d523b0bdc', 15, 'No Michelle Obama', 'On their last day in Jamaica, Sanya and Kenya can’t move past a miscommunication. Kandi refuses to forgive Marlo for their epic showdown. Shereé puts She by Shereé planning into full throttle.', '2022-08-21', NULL, '/cZ5u28hOeGculKMQYMc5ORe22j3.jpg', '2026-04-03T16:34:49Z', '2026-04-03T16:34:49Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('bcdd460e-d28c-42a3-94e5-a408d5851cc4', '7c422193-b078-49d8-81ef-f2b9f94f059d', 5, 'Cyranose de Bergerac undergoes sensitivity training', 'Episode #3010', '1992-11-13', 55, NULL, '2026-04-03T17:36:39Z', '2026-04-03T17:36:39Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('bcdf2ca7-7842-49dc-909f-ca572fd0893f', '3269a890-bba9-4e6c-9278-f7eb38eb1720', 6, 'Evolution', 'All living things have genes, which are like little sets of blueprints. Genes have information about the color of your eyes, the shape of your nose, and whether you hair is straight or curly. When living things make other living things, they pass copies of these blueprints to the offspring. The copies are mixtures. They’re never exact, never quite perfect. So, the cool thing is that no two sets of blueprints are exactly alike. So each living thing is different from other living things. Scientists know about evolution from fossils. Fossils show how living things used to look millions of years ago. Scientists take information from fossils to see how living things have changed over thousands, hundreds of thousands, and millions of years.', '1995-02-17', 26, '/srLsvT8m0oYm6ZZBHOS11nEA1sN.jpg', '2026-04-03T17:37:21Z', '2026-04-03T17:37:21Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('bcdfb209-8ce8-4d03-8f21-aa48bd8f3b31', 'acac417e-2aa3-42e7-9e08-ed0d6071a3ee', 4, 'War and P.O.S.', 'Tensions boil over between Dorinda and Sonja at Luann’s brunch; at Ramona’s dinner party, Tinsley delivers a low blow to Sonja that shocks the whole party; Sonja calls out Ramona for not being a true friend in a text message.', '2018-04-25', 60, '/uXM7RAXWiG2iP4dUuRWJlYVSPP6.jpg', '2026-04-03T16:35:25Z', '2026-04-03T16:35:25Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('bce55017-3bcf-4db5-aa5b-437fb92dfbef', '4060ad7f-4b8f-4393-8eb1-66a150b928b6', 32, 'Family Day', '', '2021-06-10', 26, '/f5iGOUdooxBToJnBEV6M8atz5I3.jpg', '2026-04-03T17:36:50Z', '2026-04-03T17:36:50Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('bce80ab2-fcad-4267-8f42-975411530c39', '4d2cac0f-38fd-438b-8afa-acf43952e535', 274, 'Episode 274', 'Christopher Trace and Valerie Singleton introduce a magazine programme for younger viewers.', '1964-04-06', NULL, NULL, '2026-04-03T17:21:47Z', '2026-04-03T17:21:47Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('bce8dace-6f3b-49a2-8c3c-4d4f3a4a70ec', 'bbfee3b4-9c95-48a6-beaa-791fa08b1f43', 1, 'Episode 1', 'Gentle Giants!

There''s no doubt who stole the show during this year''s Summer Expedition - the elephants.

They''re Sri Lanka''s most useful piece of farm equipment, with great advantages over the tractor. For instance, you don''t need import licences, or any spares. An elephant has no use for petrol or oil, he''s very unlikely to break down, and he can get to places where no wheeled vehicle can penetrate. But his greatest advantage is his intelligence.

Simon, Peter and Janet discovered bathing Goldie is a pushover, compared with scrubbing their four-ton tuskers. They used coconut husks for loofahs and a soaking wet time was had by all-there''s no doubt elephants have a huge sense of humour!

Don''t miss today''s first report, and catch up with the latest news about the four-legged members of. the Blue Peter team - Goldie, Jack, and George the tortoise.', '1983-09-12', NULL, NULL, '2026-04-03T17:21:56Z', '2026-04-03T17:21:56Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('bcebb211-118b-4b2b-a5c6-0b51c9b60d12', 'ca70502b-d862-4cdd-8071-468d6644d517', 3, 'Chapter Three: The Monster and the Superhero', 'Murray and Joyce fly to Alaska, and El faces serious consequences. Robin and Nancy dig up dirt on Hawkins'' demons. Dr. Owens delivers sobering news.', '2022-05-27', 64, '/iSvNiCJ0XIEUyj6kydm1wISZHeM.jpg', '2026-04-03T15:40:40Z', '2026-04-03T15:40:40Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('bcf3129c-53fd-49b1-be00-02c482efd7d7', 'f07b8794-5625-4682-aae1-e56966b4c7a8', 24, 'Cowpokes', 'Julie and Leon are scared of something they’ve never tried: horseback riding. They find out that when you have the courage to try new things you end up being proud of yourself. Ben and Jody do not appear in this episode.', '1996-02-15', 29, NULL, '2026-04-03T17:12:21Z', '2026-04-03T17:12:21Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('bcfa397e-d00d-4ee9-b0dd-969e80b8a1d6', '9193e795-da7c-40ec-b68f-f63aa7d5174f', 305, '2015 Comic Con Panel', '', '2020-11-16', NULL, NULL, '2026-04-03T15:40:35Z', '2026-04-03T15:40:35Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('bcfe5b89-3ede-4a15-a7e8-54599e6a9542', 'ecb64ef3-4f80-45a7-b4a9-c04434b02e35', 44, 'Pawn U', 'Turn the page with the Pawn Stars when a first edition of Mark Twain''s "A Yankee in King Arthur''s Court" finds itself in the shop. Will Rick make a deal that''s one for the books or will it be nothing to write home about? Then, the guys take a trip to Neverland when a 1953 Peter Pan animation flies in. Will Corey and Chumlee join the Lost Boys or make the seller walk the plank? And later, Rick takes his business expertise to the classroom. Can he school some college students on the tricks of the trade or will they end up teaching him a lesson?', '2014-05-29', 21, '/s2HmrbjeYDYTQZCrLh1ZLLeQNs0.jpg', '2026-04-03T16:34:19Z', '2026-04-03T16:34:19Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('bd044f2f-b0d8-4136-ac65-9299263a1a80', '3087a3ed-e94e-4276-9d02-a78183dea1d3', 2, 'Excess Breeds Success', 'NeNe promotes her new TV sitcom. Meanwhile, Kim celebrates a birthday, yet the daunting thought of being homeless looms over her. Also: Kandi and Phaedra bond with new housewife Kenya Moore, who struggles with various issues; Cynthia throws a party but tangles with Kenya.', '2012-11-11', 43, NULL, '2026-04-03T16:34:46Z', '2026-04-03T16:34:46Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('bd0606c5-3cae-45ec-883b-7da510255849', '8b6bbac8-e5ef-49c7-a5c1-197cfb19f772', 10, 'Competition', '', '1981-06-05', NULL, NULL, '2026-04-03T17:35:42Z', '2026-04-03T17:35:42Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('bd073f85-74f5-4dcd-9e91-06659bcbc18e', '1d713ca6-4e17-4f84-949c-8cfd98514127', 13, 'Break on Through', 'Break on through with the Pawn Stars when a painted bedroom door from the childhood home of The Doors'' Jim Morrison lands in the shop. Will this unique canvas light Rick''s fire or will it leave him singing the roadhouse blues? Then, Chumlee checks out a 1988 Zelda board game. Will he use a link to the past and win big or will he not have enough hearts to bring the game home? And later, when Corey gets a lead on a rare and perfectly restored collection of Indian motorcycles from the early-to-mid 1900s, Rick decides to tag along to keep him in check. Can he steer Corey away from overspending or will things fishtail into a roadside disaster?', '2014-09-01', 21, '/4Geoo1bKLZwW3Byz1RIfzjVs7mF.jpg', '2026-04-03T16:34:19Z', '2026-04-03T16:34:19Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('bd0f8406-7c97-4e4a-b02b-c02e75a1b315', '332249fa-796b-4f92-b7f8-421d523b0bdc', 9, 'Midnight in the Chateau of Good & Evil', 'Sheree plans a lavish slumber party to cheer herself up after Tyrone’s betrayal. Marlo makes a difficult parenting decision regarding her nephews. Drew’s mom delivers a prophecy about a female adversary in their midst.', '2022-07-10', NULL, '/iW60K5auL6KY8GZ2HasBX9uJjjP.jpg', '2026-04-03T16:34:49Z', '2026-04-03T16:34:49Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('bd1c35b5-6213-41c5-92fc-d4052c30d6b1', '262e8e7c-fa78-4578-a216-add6f184c4d2', 7, 'The Brown Family Decision', 'To celebrate Christmas, the Browns head off to a snow-bound cabin in the mountains to get away from the pressure of their ongoing police investigation. And later, a decision will be revealed that will affect the families lives once again.', '2011-05-08', NULL, NULL, '2026-04-03T16:34:27Z', '2026-04-03T16:34:27Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('bd22d57c-a498-41f6-8465-376d2def1d09', '0d24c742-83f2-4f37-8a5d-0b09c7df6a7f', 2, 'Dream of a Wish Fulfilled', 'Ciri gets a chance to prove herself during a robbery. Geralt gains an unlikely ally, as does Yennefer when she visits Montecalvo to look for sanctuary.', '2025-10-30', 61, '/ciupzVmgLZ1RLvQQklgxSNmUANY.jpg', '2026-04-03T15:40:46Z', '2026-04-03T15:40:46Z');
