INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('bd35bbd5-c40b-4e4e-b90a-783175fdff22', 'bb5a8843-6181-4a6d-bfdf-33ef2c6be7b8', 21, 'Reunion (3)', 'Kim reflects on her return to the show, which leads to a fiery verbal encounter with Kenya. While NeNe and Kim go head-to-head in the ultimate battle of words.', '2018-04-22', 43, NULL, '2026-04-03T16:34:48Z', '2026-04-03T16:34:48Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('bd35df72-69c3-45f9-8626-e8ec6b5e571d', '5144de59-e67f-4fcf-919b-7106989ab797', 9, 'Roamantics', 'Ben brings in an ant farm to show everyone, but Leon unwittingly wreaks havoc in an attempt to give the ants fresh air, and has to make some sacrifices to restore order to The Puzzle Place. Nuzzle gets carried away with a roll of paper towel.', '1995-01-26', 29, NULL, '2026-04-03T17:12:21Z', '2026-04-03T17:12:21Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('bd432335-1b64-4570-b092-b3a6cfbc24f4', 'f593d90c-5339-42f5-9c88-5bfd48d04075', 14, 'Hide And Squeak', 'The Farmer is terrorised when a cute mouse appears in the farmhouse and Pidsley the cat is ordered to dispose of the rodent. When the mouse takes refuge in Shaun''s fleece, the flock persuade him to protect their new friend from the pitiless cat.', '2010-01-10', 7, '/9RIhwqqXLFgZgz3qDJGYfELqFuN.jpg', '2026-04-03T17:39:31Z', '2026-04-03T17:39:31Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('bd45a4df-0409-40e4-99d2-592cadb95bc2', '02c86ae3-8c3b-4cc0-8e1f-0b27d01dcd91', 5, 'Out of Tune', 'Shereé and Lisa let loose at a pole dancing class. Lisa, DeShawn, NeNe and their husbands spend a luxurious evening together at a vineyard to celebrate DeShawn''s 34th birthday. The dinner takes a turn for the worse after NeNe starts to gossip about Shereé and makes up a nasty song about Kim''s music career. Kim and Shereé have a Botox date during which Kim finds out about the song NeNe sang about her, the two bond over mistrust for NeNe. When Kim ignores NeNe during an afternoon of lingerie shopping, the tensions mount and things get ugly. Kim''s plans for stardom are at stake as Grammy Award-winning producer Dallas Austin sends her to celebrity music coach, Miss Jan. Meanwhile, inspired by DeShawn, NeNe starts her own foundation for battered women, Twisted Hearts. She throws a "Big Hats" fundraising brunch and opens up about her past turmoil to a moved audience. After futile efforts to get NeNe and Kim to talk, DeShawn joins NeNe for a girls'' night where they focus on surrounding themselves with positive people and true friends.', '2008-11-04', 43, NULL, '2026-04-03T16:34:44Z', '2026-04-03T16:34:44Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('bd45b09f-417d-4e7f-bfcf-2d7a6e674439', '526bd779-909a-480d-a38d-1fa625a7c21f', 5, 'Karen''s Grande Dame Reunion - Part 2: Surry Secrets', 'After an intense exchange, Aunt Val shares her plan for the future of the family farm. Karen and Rayvin learn more details about their ancestral history and are shocked by the secrets found along the way. The Family Reunion begins with a good time outdoors, but when the Wooden men join Karen for a tough conversation about the legacy of the farm, Val makes a revelation that leaves everyone floored.', '2022-04-25', NULL, NULL, '2026-04-03T16:35:38Z', '2026-04-03T16:35:38Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('bd473b0d-2c2b-48a5-90c1-34e80689a55c', '2005d71d-54eb-49f8-ae9c-039eae4089b3', 14, 'Water, Water Everywhere', '', '2000-04-04', 10, NULL, '2026-04-03T17:19:39Z', '2026-04-03T17:19:39Z');
