INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('bdd15276-4370-4ee0-a795-ea7734491280', 'f760505e-28a1-4d38-964d-5a2617b5b402', 2, 'Flight', 'Which two skills must a natural-born flier master simultaneously? What outlandish experiments did early aviators try? FLIGHT combines the story of manned flight with a celebration of nature''s great fliers, from birds to insects. Discover how human designers borrow ideas from the natural world to build today''s sophisticated machines.', '1997-09-01', 29, '/2wPdUErmQTGoBpw3wQDXEVMzw18.jpg', '2026-04-03T17:39:04Z', '2026-04-03T17:39:04Z');
