INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('bde97334-8c54-4583-a8be-0b0ec808681a', '3087a3ed-e94e-4276-9d02-a78183dea1d3', 11, 'This Donkey Kicks', 'Phaedra and Apollo focus on their workout video, leading to business complications with Kenya. Meanwhile, NeNe tries to acclimate to Hollywood life; Kandi throws a birthday bash for Todd, yet Kenya interferes with the celebration.', '2013-01-13', 43, NULL, '2026-04-03T16:34:46Z', '2026-04-03T16:34:46Z');
