INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('bdf18bef-4552-4d55-911c-c844c8c3b801', '27d0351a-92f5-4d01-995c-6b5928957075', 11, 'High Stakes and Friendship Breaks', 'Heather and Lisa come together to address Jen''s behaviour, but the conversation comes to a halt when Jen reveals information about her mental health; Whitney is put on blast for claiming she wanted a friendship break from Heather.', '2022-12-14', 54, '/iAnoUbDwXROAjWwJ9IKtuZDzDHB.jpg', '2026-04-03T16:35:44Z', '2026-04-03T16:35:44Z');
