INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('bdf9c1e9-52f1-485b-8378-1aa91dc45af8', '9193e795-da7c-40ec-b68f-f63aa7d5174f', 215, 'Behind the battle for the wall', 'Follow the cast and crew into the most ambitious battle yet. The extensive documentation, including previously unpublished material, curbs the difficulties that arose in creating one of the strongest episodes in the entire series.', '2015-02-17', 37, '/KeRevRJ3QcJXrcR8Spe7drLjCz.jpg', '2026-04-03T15:40:35Z', '2026-04-03T15:40:35Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('be02b41a-e8d0-48bc-a86f-301b418ed25f', 'a8db07e5-fba3-49a9-bd12-947c111b39be', 20, 'Say It Ain''t So', 'The final morning in Miami finds Luann devastated after Bethenny spills news about Tom. Also: Luann checks into a hotel and sizes up her situation, and Bethenny hosts a Mexican-theme bash with a piñata packed with big-bucks jewelry. The Season 8 finale.', '2016-08-24', 44, NULL, '2026-04-03T16:35:24Z', '2026-04-03T16:35:24Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('be0765eb-9a1a-4563-8b97-54a71e385021', '79916e0e-881c-43a7-b4ee-00e5052a94be', 22, 'Hank''s Hiccups', 'Hank has a severe case of the hiccups that interfer with his work assigned to him.', NULL, NULL, NULL, '2026-04-03T17:10:11Z', '2026-04-03T17:10:11Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('be07e630-4bc3-46e1-8d11-3e888a0997cc', 'dc5ee380-3f45-44d5-addd-a900a1ea77b2', 1, 'Episode 1', '', '2022-09-05', 63, NULL, '2026-04-03T15:26:07Z', '2026-04-03T15:26:07Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('be0a5836-8c80-4d37-b53a-b17d5d2426d2', '7b8e3988-fbf3-4cfc-aeb2-782ae5a64e2d', 16, 'Rakhi Road', 'Leela is making bracelets to celebrate an Indian holiday called Rakhi, a time when sisters, brothers, and friends show how much they love each other by exchanging special bracelets, foods, and gifts. Leela already sent a bracelet to her brother, Sunil, in India and now she is expecting a bracelet from him any moment. While she waits, she helps Telly and Zoe make bracelets for their friends. Just then, a delivery person brings a box that turns out to be a sample of laundry detergent-- not her brother’s gift. Meanwhile, at Hooper’s Store, Elmo comes upon Chris who is making a bracelet for Leela. He wants to do something special for Leela since she’s feeling homesick. They decide to use the computer to learn more about Rakhi and to find some recipes for traditional Indian foods such as phirni, carrot halwa and laddoo. Now all they need is some Indian music to make the Rakhi party complete! Leela is surprised and happy to see how Chris and Elmo brought a little bit of India to Sesame Street with all of the decorations, food, and music. Everyone exchanges their bracelets and Sunil’s bracelet for Leela finally arrives in the mail! Now the Rakhi party can really begin. Everyone dances and sings about the importance of friendship and family.', '2010-11-26', NULL, '/AckzzBVfG3aWcbDlnFsMPv2VMQw.jpg', '2026-04-03T17:36:46Z', '2026-04-03T17:36:46Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('be0c1db3-5608-4140-b5c3-68a16d1624cd', 'f12380a9-93e5-47bb-9e2f-cf1eed11eee4', 14, 'You Are Toxic to Me', 'The Sister Wives are moving on as Meri begins dating and Janelle starts a farm in North Carolina but an attempt to sell the Coyote Pass land goes bad when Kody considers going behind Meri''s back.', '2025-12-28', NULL, NULL, '2026-04-03T16:34:33Z', '2026-04-03T16:34:33Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('be0cbb60-f5c6-4a7e-ac87-496b93d6b336', '136b81d3-964d-4b8f-a214-92f00d96d6b9', 69, 'Episode 1904', 'Bob and Susan perform a delightful country-style counting song about little baby pigs for the children gathered on Sesame Street, teaching numbers through music and fun.

Sponsors: J, T, 4', '1984-02-23', NULL, NULL, '2026-04-03T17:36:35Z', '2026-04-03T17:36:35Z');
