INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('be0e97df-b52d-4537-b6c2-d63b12c2636a', '8c0f12e1-5379-4a27-aca2-b69401a33b0f', 2, 'Draw!', 'After Francine makes fun of Fern for liking Mr. Ratburn''s puppet shows, Fern gets revenge by drawing an unflattering comic strip making fun of Francine, and pretty soon, everyone else tries it too.', '1997-10-20', 13, '/4IYd5M2YtNW4V3OMTKFDx7zP2aB.jpg', '2026-04-03T17:37:55Z', '2026-04-03T17:37:55Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('be1732c9-4e70-4bf0-aec2-5c6da6cb6fbd', '319bd5d6-ff58-426f-b9da-a0bb2cb87b02', 4, 'Architecture', 'Towers, teepees, castles, and condominiums – some kind of planning goes into all buildings, no matter how big or small. Architects are people who design buildings, and the areas around buildings. Usually architects draw on a computer or a big desk (a drawing board). The plans show the dimensions of all parts of a building. Architects try to design with the purpose of the building in mind, but even buildings used for the same thing can look very different.', '1997-10-24', 26, '/7Lo3pWHyNi9Mjtt4KyBGWhuAiAu.jpg', '2026-04-03T17:37:22Z', '2026-04-03T17:37:22Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('be1a2b6e-647c-448d-ac38-7845842195a8', '6f731e6b-d3c5-4de6-84e1-7a19cb650e86', 36, 'Stairway to Pawn', 'Get your ghoul on with the Pawn Stars when a talking Herman Munster doll creeps into the shop. Will Chum think it''s franken-tastic and make a deal or will he get spooked out? Next, things get amped up when a bass guitar signed by John Entwistle from the "Who" and John Paul Jones from "Led Zeppelin" is brought in. Will Rick pick up a sale or will he fret and miss out? And later, Rick''s in mint condition when he checks out a rare 1867 Proof Shield Nickel. Will he strike up an offer or will he discontinue the deal?', '2016-05-25', 21, '/aCNzeygSk2Xmi1jo52oKIOPZ8Pa.jpg', '2026-04-03T16:34:20Z', '2026-04-03T16:34:20Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('be1a5f54-1b98-4dc0-9855-109a62695785', 'c4d795ae-6afa-47d6-9819-4dd057030a3c', 24, 'Porsha''s Having A Baby Part 1', '', '2019-04-28', 43, NULL, '2026-04-03T16:34:48Z', '2026-04-03T16:34:48Z');
