INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('be1f7a3b-f4aa-4541-a379-85180adf17af', '793a6b2c-7cad-4f12-a943-74729e3d9ca6', 15, 'DELETE ME', '', NULL, 5, NULL, '2026-04-03T17:24:24Z', '2026-04-03T17:24:24Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('be23dfb6-4b9f-4d06-81c3-2c4c1200a00b', 'c21dbd22-5e2e-4414-bb67-750399aaf6f0', 15, 'Crosby, Stills and Cash', 'The Pawn Stars are blown away when a pair of WWII bomb fins drop into the shop. Designed to keep bombs on target, will the guys try to blast out a deal for these rare military items, or will they run for cover as the negotiation implodes? Then, Rick tries to get in tune with a guy who brings in a Martin guitar signed by 60''s super group Crosby, Stills and Nash. Will Rick''s offer be music to the seller''s ears, or will he get nothing but feedback? And later, the guys continue their daunting search for a new employee to work the night shift. Will they pick beauty over brains or go with a safe bet?', '2012-01-16', 21, NULL, '2026-04-03T16:34:17Z', '2026-04-03T16:34:17Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('be26cf8a-5fa0-408c-bcea-bec4d8c5867f', 'e40e6b63-9f84-449f-8e88-53209b0906c8', 13, 'Gabi, Telly, and Zoe Have a Picnic', 'Gabi, Zoe and Telly are gathered around at a picnic table outside of Hooper''s Store for a picnic. Maria brings them a melon and sets it on the table. They briefly turn their attention away from the melon while Telly shows them the triangular napkins he brought. But when Telly goes to get the melon, he finds it''s missing! Everyone is confused - where did the melon go? It''s not under the table.', '2007-09-10', NULL, '/vxo24Mg6O6veE32BTuLlBt68hf1.jpg', '2026-04-03T17:36:45Z', '2026-04-03T17:36:45Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('be2841f5-8161-4055-be53-75113aaa55d2', 'bc1b58b0-f2d6-4214-914b-231f27fb4d61', 1, 'In The Name Of The Father', 'Melissa and Kathy are busy preparing for a family christening. Jacqueline''s lunch with Ashley goes sour when her feelings of guilt and frustration boil over, and Teresa focuses on saving her family from ruin.', '2011-05-16', 43, '/hWPEHjrDsdkNOh93Zziwnixq2Fb.jpg', '2026-04-03T16:35:15Z', '2026-04-03T16:35:15Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('be31ef26-019f-4dcb-a615-0a74d7ca027b', '787dfa0b-c827-4dad-a82d-0548a6534d88', 5, 'Game Changer', 'Vicki gets a phone call that forever changes her life. Shannon offers an olive branch to Meghan when she hosts a Bunco party at her house. Meanwhile, Meghan moves into another house and Heather has an unorthodox date night with Terry that gets a little bloody.', '2015-07-06', 44, '/A43UEVqU2Nkti3yDWoKMSnVGfqQ.jpg', '2026-04-03T16:35:32Z', '2026-04-03T16:35:32Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('be35fcb6-03bf-4f2f-ab7d-a13d0602f8ae', 'de8ec769-16bb-436b-be43-aedc7e18a7d7', 2, 'The Great Sesame Street Cake Off', 'Cookie Monster and Gonger team up against Grover and Alan in a competition to see who can bake the best birthday cake for Nina. Elmo and Rosita help the two teams work together, combining one team’s cake and the other team’s frosting to make the ultimate birthday treat.', '2019-11-23', 30, '/38s0GdDj8lb1RLAiElnrVwTea8p.jpg', '2026-04-03T17:36:50Z', '2026-04-03T17:36:50Z');
