INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('be3cb3cf-bd51-4588-b822-d7fc143cbf90', 'ecb64ef3-4f80-45a7-b4a9-c04434b02e35', 5, 'I''ll Be Doggone', 'Take one giant leap for mankind with the Pawn Stars when Rick checks out a jetpack from the Gemini space program. Used to prove that jetpacks could work in zero gravity, will Rick''s offer be out of this world? Then, Chumlee''s nuts over a Snoopy comic book with a personal drawing from Charles Schulz. Will Chumlee be able to kick the proverbial football and make a deal? And later, Rick''s take on a commercial for the pawn shop inspires Chumlee to make a version of his own. Whose commercial will reign supreme?', '2014-01-16', 21, '/aRjyIEXY4UbcPAnjGhO8BwXu6Zr.jpg', '2026-04-03T16:34:19Z', '2026-04-03T16:34:19Z');
