INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('bed018aa-aacc-4324-91f5-6d526b5f8c68', '04207e76-d855-4f29-a066-1732feea34b5', 1, 'Water Under The Table', 'The birth of Jacqueline''s baby boy brings the Manzo sisters even closer together and Danielle is still trying to make her way into their inner circle. Meanwhile, when Caroline throws her annual Sheriff''s Fundraiser and doesn''t invite Danielle, Danielle makes sure that everyone knows she was excluded.', '2010-05-03', 43, '/kVVO1RGkLte4QkioDgfhZUUMcjL.jpg', '2026-04-03T16:35:15Z', '2026-04-03T16:35:15Z');
