INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('beff6427-454b-4fb5-99cb-0ead2e759892', '421c3366-4d98-4baf-b4ad-6ec5047df9f8', 13, 'Pets and Pests', 'When a mouse is discovered in the Read house, Arthur uses Nemo to try get rid of it, making Pal worried. Then, Ladonna shows up and shows Arthur, D.W., and Bud that mice can be friends as well as foes.', '2014-04-22', 13, NULL, '2026-04-03T17:38:01Z', '2026-04-03T17:38:01Z');
