INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('bf1460e0-4360-482d-a0d8-d8aaef7355fe', '7ccd5605-fe0b-4e00-ae7f-3e3daa252f8b', 2, 'Friends, Enemies, and Husbands', 'Lynne Curtin''s private showing for the ladies of her cuff line comes to a screeching halt thanks to a heated fight between rivals Tamra Barney and Gretchen Rossi. The camps divide, with Tamra unloading her feelings on her friend, Vicki Gunvalson, while Gretchen tells her side of the story to Jeana Keough and Lynne. But Lynne is feeling her loyalties pull in two directions now that she and Tamra Barney have grown closer. Meanwhile, Simon sells a luxury car to an acquaintance and his wife – Jim and Alexis Bellino – and he invites them on a double date so Alexis can meet Tamra.', '2009-11-12', 44, '/y6LO3aUfJlbsS9RC8Zu3yTDCpHz.jpg', '2026-04-03T16:35:31Z', '2026-04-03T16:35:31Z');
