INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('bf513105-fe8c-46cf-945a-5d382b750bbd', 'e03d79bd-e01f-4414-b0b3-f3b5f26e97f4', 9, 'Thanksgiving II', 'Mike begrudgingly invites his brother, Rusty, who is temporarily living in a tent, and his father, Big Mike, who has recently broken his hip, to join him for the annual Heck family Thanksgiving. But when Frankie observes the macho Heck men''s non-communicative nature, she encourages a not-so-receptive Mike to engage them in a real conversation and express their feelings. Meanwhile, Brick is ecstatic when he discovers that Bob is bringing his girlfriend, Linda - the local librarian who loves books as much as Brick does - to Thanksgiving; and Sue wants to start a mother-daughter tradition of baking a pie for the holiday, but ends up getting more sliced up than the crust.', '2010-11-24', 22, '/d3uaevdcZgFS6Ocm7kDH3XeRsCR.jpg', '2026-04-03T15:40:29Z', '2026-04-03T15:40:29Z');
