INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('bf5773ef-697c-4f11-a467-e1d0611b31c1', '5046642d-462d-4eb0-8194-0bbd7962af0f', 15, 'The Pirates Who Don''t Do Anything - A VeggieTales Movie', 'Three lazy misfits - very timid Elliot (Larry the Cucumber), lazy Sedgewick (Mr. Lunt) and no self-confident George (Pa Grape) - dream of the day of putting on a show about pirates. With their own problems of might not having this dream come true, they soon find themselves traveling back in time into the 17th century and begin a quest to rescue a royal family from an evil tyrant, and learn about being pirates.', '2008-01-11', 30, '/4brqm4xO1K5HrACtI0ZC0ZvtU7g.jpg', '2026-04-03T17:39:38Z', '2026-04-03T17:39:38Z');
