INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('bf67f3ec-70e5-4aab-82b4-6d60530d7f3c', 'ecb64ef3-4f80-45a7-b4a9-c04434b02e35', 38, 'All In', 'Ante up with the Pawn Stars when a poker cheating device finds its way into the shop. Will the guys cash in their chips and score this devilish instrument of deception or be forced to fold? Then, a mysterious suicide ring believed to be from WWII finds its way into Rick''s fingers. Will he move in for the kill or be stopped dead in his tracks? And later, Chum hosts his own poker night, but will his party be a full house or a royal flush?', '2014-05-08', 21, '/1oKshNEJliH5GDilAQDSfNaszcq.jpg', '2026-04-03T16:34:19Z', '2026-04-03T16:34:19Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('bf73bb4c-2082-446b-b2df-5a3c23b1503d', '650bac93-7b59-41fc-b277-dc6f8bdcd7bb', 20, 'Adult Swim', 'After discovering that he doesn''t have a decent suit to wear for upcoming business interviews, Frankie is thrilled when Axl agrees to let her take him shopping to help him pick out a suit; and when Mike threatens to do away with the family summer pool if Sue and Brick don''t start using it, they begin to worry that he and Frankie may take even more things away from around the house from their childhood that they don''t use anymore as they edge towards adulthood.', '2017-04-18', 22, '/gD4AMqbOBja7SwNw7lR6B4Hv4rw.jpg', '2026-04-03T15:40:31Z', '2026-04-03T15:40:31Z');
