INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('bfb64236-8d0a-4198-b2ae-a8e763821bd0', '7c542833-ed0a-4272-9c53-e822408ab434', 26, 'The Big Show', 'It''s time for the finale of the Pontypandy Festival - the Big Pontypandy Talent Show! But when Elvis knocks a drink over the drone control panel, the drones crash land, causing fires in the fields all around the show area.', '2024-11-12', 10, '/xUx3x5JCQD6M8IIRcT5fpcxDLN5.jpg', '2026-04-03T17:14:42Z', '2026-04-03T17:14:42Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('bfba5986-2a25-4276-aa95-e324519f3c2b', 'ec8d3322-8ca2-4e8d-9d22-268aee320274', 8, 'Gold and Silver Horde', 'Rick checks out a horde of coins from Kentucky – but is all that glitters gold? Or will Rick be played for a fool? Then, Chum gets into the spirit when a mentalist brings in a magical clock. Will it be time for a deal, or will Chum get ghosted? Later, Corey isn’t ready to say die to a deal when a seller brings in a poster from “The Goonies” – but will this be treasure, or will Corey be cursed? And finally, Chum tries to drum up a deal on a sparkling snare. Will the seller feel the rhythm, or will Chum have to tap out?', '2025-03-19', 42, '/u35xouZz4cPBPn5cObbwBlUXpjM.jpg', '2026-04-03T16:34:24Z', '2026-04-03T16:34:24Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('bfbab03d-20b8-436b-bf8e-9ac458042ea3', 'd8ccf6d3-e37a-430a-b67d-7fbf269bf0be', 11, 'If I Could Churn Back Time', 'Heather proposes a group trip to celebrate Monica''s birthday, causing unresolved tensions between Monica and Lisa to reach a boiling point. Angie leans on Whitney for advice about her marriage woes. Whitney and Justin join Meredith and Seth on their new podcast and open up about the status of their marriage. Heather throws a Pioneer Day-themed lunch to thank her friends for their support, but the day ends with hurt feelings and the upcoming trip hanging in the balance.', '2023-11-21', 44, '/cRDAvCcLzcj4XwQ5V6UN8Xh1xpF.jpg', '2026-04-03T16:35:45Z', '2026-04-03T16:35:45Z');
