INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('c05d3773-7b6b-4e0c-9032-53d186c8f09f', 'f15647d3-c8bf-4e37-a6bc-589853787f3b', 4, 'Skate Expectations', 'After trying to protect a geeky boy, Philip, from Derrick, Nick finds himself in a skateboarding contest, even though he isn''t that good at it. He practices, but on the day of the race, Derrick''s friends try to sabotage it. However, Nick''s friends notice and even though he loses the race, they disqualify Derrick and so he does end up winning. He learns about cheating, practice, friendship, and standing up for others.', '1989-06-25', 28, '/cZ6Aw7nxzqDuPLk9ngoC0NH0WXF.jpg', '2026-04-03T17:40:08Z', '2026-04-03T17:40:08Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('c060f2c7-d4c2-4728-936c-1e00c41e0841', '70cac5ca-fb7f-4cb7-8c9b-004d44124a1d', 9, 'When Chairs Fly', 'Teresa, Melissa, Margaret, and Danielle square off with Dolores, Siggy and Kim D at the annual Posche Fashion Show. Teresa confronts Kim D face to face about the cheating rumours and the women wonder whether they should go to Italy together.', '2017-12-06', 43, '/21R5m2hXOfOHz8Ip6qiThXVbTPj.jpg', '2026-04-03T16:35:17Z', '2026-04-03T16:35:17Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('c0615a50-5986-42ab-b2c1-02a0403798b7', 'db958af4-9a9a-4533-af9b-f0ff590d1dd9', 1, 'New Friends, Same Jersey', 'When Melissa throws a 1980s-inspired roller-skating party, Teresa takes the opportunity to mend fences with Margaret, not her brother; while Dolores draws boundaries with Frank and her new man, Jennifer struggles to move forward from past offenses.', '2023-02-07', 55, '/amecNHC7lqRkXlV7qCZigIXn47b.jpg', '2026-04-03T16:35:19Z', '2026-04-03T16:35:19Z');
