INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('c06c97d2-ad62-4ee7-8d5c-878c7e5ecccf', 'c382366d-b65c-4f2a-9e91-200f0d973ae9', 1, 'Happy Anniversary', '#1001"Happy Anniversary"Mr. Ratburn shows a film about perspective and then assigns the class an essay about it. Arthur and Buster are disappointed to have homework on the weekend of the big Bionic Bunny / Dark Bunny special (in which everything will be revealed), but vow to complete it before the start of the special. Arthur, however, struggles with the assignment. Mr. and Mrs. Read are celebrating their tenth anniversary at a fancy restaurant. They''re dropping Arthur off for Buster''s sleepover and D.W. at Grandma Thora''s. But car troubles leave everyone stranded. Things seemingly go from bad to worse when Arthur and D.W. get locked in a storage room in an old diner. They''re disappointed, and a bit scared, but find inspiration in an old radio drama called "Kid Carter and his Sidekick Mistral.', '2006-05-15', 26, NULL, '2026-04-03T17:37:58Z', '2026-04-03T17:37:58Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('c0711bf1-d7a4-426a-aab0-4f1d5880a403', 'de8ec769-16bb-436b-be43-aedc7e18a7d7', 30, 'Making the Band', 'A rock star is performing on Sesame Street, but his equipment is in the wrong town so the gang helps build and design replacements so the show can go on.', '2020-06-06', NULL, '/1zsbfFK0YrrFz8pSHrRy09QOAhq.jpg', '2026-04-03T17:36:50Z', '2026-04-03T17:36:50Z');
