INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('c0b522ca-d77b-43a3-a1bf-15471cde3f93', '0b9d7ae7-218e-45a0-8c3a-e69912f5a6ed', 17, 'Franklin and the Puppy', 'A lost puppy follows Franklin around, and Franklin wants to keep him.', '2000-01-17', 12, NULL, '2026-04-03T17:40:15Z', '2026-04-03T17:40:15Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('c0bcdb76-9bad-46a1-8ab4-ad656eda9399', '119c16d5-1047-45ec-8242-c72a8eed423b', 47, 'Arthur''s Tooth', 'When Arthur is teased by Francine and the others because he hasn''t lost all of his baby teeth yet,  he becomes determined to lose his tooth and fit in with the others.', '1996-11-07', 13, NULL, '2026-04-03T17:37:55Z', '2026-04-03T17:37:55Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('c0bf532f-154e-4fc6-bd07-dcd015ee0eb5', '5c4e51c6-e207-46ad-875c-72988eb1e13e', 33, 'Teacher''s Pet', 'Look out below when the Pawn Stars set their aim on a World War II era bomb-sight. Used by U.S. bombers to direct their big-bang cargo, will the guys be able to keep this negotiation on target, or will heavy flak blow the deal out of the sky? Then, Corey and the Old Man hope their fortunes will rise when they go check out a stock ticker from the 1930''s. Will this deal pay big dividends, or will the market crash and burst their bubble? And later, when Antwaun the shop security guard shows interest in learning the pawn business, Chumlee agrees to teach him how it''s done. But can Chumlee go from class clown to teacher''s pet without a trip to the principal''s office?', '2011-09-19', 21, NULL, '2026-04-03T16:34:17Z', '2026-04-03T16:34:17Z');
