INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('c245bcea-1709-459a-a336-211d9acde342', '70cac5ca-fb7f-4cb7-8c9b-004d44124a1d', 2, 'Let Them Eat Cake', 'After an explosive fight, Siggy and Dolores align themselves against Teresa and Melissa; the rift between Margaret and Siggy turns ugly; Dolores deals with the challenges of having her ex-husband and their son, Frankie, under the same roof.', '2017-10-11', 43, '/ubZUegPKd8nIQGNMvaolhG4ruu7.jpg', '2026-04-03T16:35:17Z', '2026-04-03T16:35:17Z');
