INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('c270b667-e972-4782-98a8-f12eb23693c1', '3fa8fce3-db8c-4348-9424-8ff9df38a50f', 4, 'George Scraps His Sculpture', 'George volunteers to create a piece of art for the county-wide art show and can''t decide what to make.', '2021-03-10', 13, NULL, '2026-04-03T17:38:03Z', '2026-04-03T17:38:03Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('c274c49b-2878-4688-959d-ffd19527f786', 'ea1650c2-e4f1-46c7-93ba-74b5d45d08e5', 10, 'Auto-Tuned-Up', 'It''s time for Kim to face her fears and work with the vocal coach who once told her that she didn''t know what she was doing. Meanwhile, Sheree is ready to take her newfound passion for acting to the next level by auditioning for a talent agency and considering a role in a local play. While Phaedra and Apollo bask in the joys of new parenthood, Cynthia is caught in an uncomfortable position when Peter confronts NeNe about taking all of Cynthia''s attention away from him. It all comes to a head at the "Fast Life Drag Race" when Kim thinks that the other ladies are getting too close for comfort with her girlfriend Tracy and NeNe does not appreciate the cold shoulder she gets from Peter.', '2010-12-05', 43, '/9au0PUElBYh9wPhFGFWACKPg38Z.jpg', '2026-04-03T16:34:45Z', '2026-04-03T16:34:45Z');
