INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('c27d0068-85c4-45e1-bad9-084f5a79b609', '2990012c-38f6-4051-84a5-4ec6da711d80', 1, 'The Lost Mug', 'Arnold loses his mug in the woods, so he, Kipper, and Pig set out to find it. Soon, Arnold meets a squirrel who happily drops acorns on passing people.', '1999-01-21', 30, NULL, '2026-04-03T17:10:48Z', '2026-04-03T17:10:48Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('c27f5fb5-d452-4633-8f30-8dc946fde9e6', '5a771f52-fe96-4ea2-b567-a8dde899059e', 27, 'Here''s Looking at You, Pawn!', 'This episode of Pawn Stars takes flight with a 1911 first edition novel of Peter Pan, but would Rick rather spend his Shenan-doah on a piece of scrap metal from an infamous fallen airship? Also, a seller tries to sweep Rick off of his feet with an ancient kneeling Thepanom statue. And later, everybody comes to Rick''s, but it''s up to Corey if a "Casablanca" movie poster is worth the six figures it would take to watch a deal take place.', '2018-05-07', 21, '/5DjMVvl021NzEsLWTkx8CSX6Egs.jpg', '2026-04-03T16:34:21Z', '2026-04-03T16:34:21Z');
