INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('c29b5ab9-50fb-4043-b59c-82246984989c', 'd306a064-e835-417e-8548-0cf806295f31', 14, 'Rage, Release, Repeat', 'Marysol arrives in the Bahamas and receives hurtful news about her ex; after an explosive dinner, a rage ritual ends in injury; while on a private island, Adriana makes a comment about Alexia''s son that causes her to go off the deep end.', '2023-02-16', 44, '/g3DfnwhWLhEjTBpu3zzHfqMdctF.jpg', '2026-04-03T16:35:11Z', '2026-04-03T16:35:11Z');
