INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('c2a295a1-0837-4e05-81ac-a996d4e5fa25', '9193e795-da7c-40ec-b68f-f63aa7d5174f', 16, 'The Game Revealed: Season 6 Episode 1 & 2', 'The Game Revealed: Season 6 Episode 1 & 2', '2016-08-01', 60, '/lVFVxh3iayEd7mAtLwo94j34zeC.jpg', '2026-04-03T15:40:35Z', '2026-04-03T15:40:35Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('c2a7c437-8b1c-4aaa-9fa3-740b81a84193', '7b8e3988-fbf3-4cfc-aeb2-782ae5a64e2d', 4, 'The Ironing Monster', 'Leela and Elmo are sorting laundry in the Laundromat when Grover stops by to have his Super Grover cape cleaned. Grover realizes that people all over the Laundromat need his help. Bert has soggy socks, Gina is out of fabric softener, and Cookie Monster has a stain. Without his cape, a new superhero must be born! Grover returns as Iron Monster, complete with a metal suit! Chris shows up asking Leela to break his dollar so he can do his laundry. Iron Monster misunderstands and wrestles with the dollar to “break” it. Leela comes back and explains that Chris just needs quarters&ndas; four quarters for each dollar. Gabi comes to the Laundromat with two mustard stains on her sweatshirt. Iron Monster tries to get rid of the stains by subtracting them, but adds five more stains instead! Leela shows Iron Monster how to subtract all of the stains with a stain remover as Elmo counts along. Finally, Iron Monster tries to solve Maria’s problem by using static cling to find Maria’s missing sock. After laundry goes flying everywhere, Leela suggests they check the missing sock box. They sort through different patterns and find the lost red and white striped sock. Finally, Grover’s cape is ready. Before he flies off for his next adventure, Grover points out that Iron Monster is not needed anymore because the Laundromat already has a fantastic superhero, Leela!', '2010-09-30', NULL, '/9fk8kxUvpRMnNg9KnzJWo86e65H.jpg', '2026-04-03T17:36:46Z', '2026-04-03T17:36:46Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('c2ad5a1d-0cc2-4d74-a3f6-dd50873cc385', '8bae6aa3-4b55-4fa6-bc15-8f4317bd1f13', 7, 'Episode 7', 'Rogers'' son Jamie and a friend play with a toy on the floor of the television house. In the Neighborhood of Make-Believe, Robert Troll starts a game of catch, but doesn''t want to throw because he thinks no one will throw back.', '1972-02-29', NULL, NULL, '2026-04-03T17:35:40Z', '2026-04-03T17:35:40Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('c2b33887-c7a7-40f5-b4c0-bbfc2f482491', '66a11a09-aee2-4a7b-8543-ab080a9d1be4', 15, 'Welcome to Amsterdam?', 'The women are forced to set aside their differences and work together as teams while taking part in Yolanda''s scavenger hunt; the women embark on a group trip to Amsterdam; at a charity gala, Kim reproaches Lisa Rinna for talking behind her back.', '2015-02-24', 42, '/3aduFCY6rciA0TEmVsQ0Dg3NjyR.jpg', '2026-04-03T16:34:56Z', '2026-04-03T16:34:56Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('c2bc7995-3fd8-4633-9879-43df74752191', 'dc6ef505-d194-4259-b256-5711d25aca6b', 2, 'Stormborn', 'Daenerys receives an unexpected visitor. Jon faces a revolt. Sam risks his career and life. Tyrion plans the conquest of Westeros.', '2017-07-23', 59, '/6ZLuB2YZeXTCEETnbPe5MNKCsio.jpg', '2026-04-03T15:40:37Z', '2026-04-03T15:40:37Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('c2bf7eb3-ba51-49f8-9d87-73bb8c7b4f5a', '5db3ff78-e439-48e1-8f67-988ecbf85d17', 1, 'Dogtanian''s Journey', 'Dogtanian is fighting his rival François LaVache, son of the Mayor, with wooden swords and beats him easily. A Musketeer from Paris watches on his way to meet the noblest man in Béarn and congratulates Dogtanian on his victory. François rushes home assuming he''s there to meet his father, but Dogtanian sees the Musketeer arrive at his house. We find out that Dogtanian''s father is friends with Monsieur de Treville, Captain of the Musketeers...', '1981-10-09', 24, '/8abTqsVbxKq3nW0cNpjjhCyLwt3.jpg', '2026-04-03T17:18:43Z', '2026-04-03T17:18:43Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('c2c18980-882a-4db0-8b0e-b0d9c79ffa32', 'd2f2ce63-96af-4899-92a8-3da5ea3913ce', 7, 'All Dried Up', 'Always the caring soul, Phoebe goes on a crusade to save the animals and plants of the desert -- and discovers how well they take care of themselves.', '1994-10-22', 26, '/lgne7NvKbhGpVB7MT4GEdlHN3Vr.jpg', '2026-04-03T17:37:48Z', '2026-04-03T17:37:48Z');
