INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('c2c73f79-f71c-4990-9dc1-08e7564a1d9b', '10e64538-c78a-4cb0-82f9-17d14256dbac', 12, 'Birds of a Feather', 'Axl begins his internship at a snack-making company; Frankie complains about working for Smile Superstars; and Cindy confesses to Mike that she kissed another boy. Meanwhile, Sue''s professor challenges her to stop seeing the world in a positive light for a writing assignment.', '2016-01-13', 22, '/icDGD0C6orqadaBzVLm28Oy0i5W.jpg', '2026-04-03T15:40:31Z', '2026-04-03T15:40:31Z');
