INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('c2dd50ea-8507-4063-a43a-794448f1420b', '1cfdff3a-d531-4a9e-afc9-8010a979dd27', 6, 'The Voyage of the Dawn Treader (4)', 'The world''s end and the final enchantment draw near.', '1989-12-24', 30, '/zV3LvtIsVUBdwJVnRGKWHhPbSAr.jpg', '2026-04-03T17:17:41Z', '2026-04-03T17:17:41Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('c2de62e2-e325-4d05-9aa1-c27852d48e69', '3982796b-5451-4100-9042-46bedf6a20a5', 15, 'Pingu''s Birthday', 'It’s Pingu’s birthday, and he’s having a party with Pinga and his friends Pingo and Pingi. The party area is decorated with balloons and lights, and there are snacks and drinks on the table. Grandfather is providing music on the accordion. Robby arrives with a present for Pingu. It’s a cap, which he promptly puts on. Pingu shows the others what he’s received; a book, some crayons and a ball. They then all tuck in to the snacks and drink. Pingu shares a drink and a snack biscuit with Pingi (which leads into a Lady and the Tramp-style kiss). Pingi then pulls Pingu’s cap over his eyes so he can’t see and tells him he has to find her. He goes where he thinks she is, but she steps out of the way. She calls, and he changes direction towards her, but she steps out of the way again. Robby calls, and Pingu tries to catch him, but Robby backs away. The others all join in, calling in turn, and Pingu doesn’t know whom to find. Eventually he looks for Pingi again, but she moves out of the way and he collides with Mother, who has just come out of the igloo. She takes his hat off so he can see whom he’s found, then puts it back on. The game continues, Pingu not managing to find anyone. Mother then comes out with the cake and they all gather round. Pingu, now feeling much better, blows out the candle, the others sing “Happy Birthday” (in Penguinese) to Pingu, and then they all dig into the cake.', '1993-07-06', 5, '/49sdYHfKiP9gXpN5QuFAa7QDJUn.jpg', '2026-04-03T17:22:19Z', '2026-04-03T17:22:19Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('c2f21171-ff29-4c03-a26d-8d03c62777f2', '7eef937c-4483-42bd-bafe-263a7d4e4573', 4, 'Under Construction', 'Two inches tall and trapped in a bathroom at Wanda’s house, the kids must use what they’ve learned about structures to escape before Wanda’s mother discovers them.', '1996-10-05', 25, '/zE2SOfuQeyQKNAkhfRari0pi0t9.jpg', '2026-04-03T17:37:49Z', '2026-04-03T17:37:49Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('c2f872d9-5dcd-44a3-a5ba-c1ab90f0475d', '04e133fd-c4a3-4dfa-8369-c6dcfd1e3a5a', 18, 'The Sesame Street 500', 'The neighborhood organizes the Sesame Street 500 race featuring homemade vehicles and friendly competition. The event showcases everyone''s creativity and determination to win.

Sponsors: L, Q, 6', '1984-12-12', NULL, NULL, '2026-04-03T17:36:35Z', '2026-04-03T17:36:35Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('c2f8de00-f33c-4381-811c-827ec2a41bb1', '4b2a19e0-2fae-492e-bc31-f78e63d88ebc', 29, 'Under Pressure', 'Shine on with the Pawn Stars when a drawing by John Lennon scribbles into the shop. Will Rick give this piece a chance or will he fail to imagine an offer? Next, Senator William Sharon''s engraved menu from the Comstock Lode mines in. Will Rick see the silver lining or will the deal get tarnished? Then, a Rolex water pressure tester ticks in. Will Corey make time for an offer or will it get water damaged? And later, a 1950s Buddy Lee doll struts in. Will Rick zip up a deal or will he think it’s child''s play?', '2017-02-06', 21, '/sXdgMZ4ieqS1C5Yip2Kso3YBUMc.jpg', '2026-04-03T16:34:20Z', '2026-04-03T16:34:20Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('c2fdaab5-cde5-4806-b7c9-22473275f577', 'c7ffc8df-4671-47e3-a11b-606828bcb508', 8, 'Hermanos', 'Skyler develops an unusual solution to her money troubles. Hank enlists Walt to investigate a theory. Walt''s impatience with Jesse grows.', '2011-09-04', 48, '/jwGeSa4lw93UqvxoII5kb4nko1b.jpg', '2026-04-03T15:40:34Z', '2026-04-03T15:40:34Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('c2fdd324-3a95-4007-bced-ebf4e5062656', '0d24c742-83f2-4f37-8a5d-0b09c7df6a7f', 1, 'What Doesn''t Kill You Makes You Stronger', 'Geralt sets out to save Ciri from the claws of Emhyr, unaware of her true fate. Beset by Vilgefortz, Yennefer attempts to uncover his plan.', '2025-10-30', 59, '/ihhPrHJhamp5iGu6LACWMzTT94r.jpg', '2026-04-03T15:40:46Z', '2026-04-03T15:40:46Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('c2fe8615-21c8-4caf-8e94-204c4d4c0891', 'e8b959c0-6865-4332-9be1-b8f720716aa8', 4, 'Hair', 'John visits Renoir Hair Salon in Birmingham.', '1991-10-21', 15, NULL, '2026-04-03T17:19:37Z', '2026-04-03T17:19:37Z');
