INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('c3022971-3aea-4cc5-bf0b-89eb12c7cfd0', '0fa92002-82ae-4609-85e3-3982baa99ae1', 2, 'Postman Pat and the Surprise Present', 'It is Dr. Gilbertson''s birthday, but after Pat gives her a lift, she tells him she has not got time to bother celebrating. Pat and the other villagers all decide to throw a special party for her: Ted, Ajay, Pat and PC Selby works hard to restore a vintage car as a birthday present, the children compose a special song, and Nisha and Sarah make the birthday tea.', '2005-02-28', 15, NULL, '2026-04-03T17:14:30Z', '2026-04-03T17:14:30Z');
