INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('c31fa7c0-7279-4325-b9f8-f49e58908f0f', '1a534647-384b-4c00-bb6c-a3371ad962eb', 16, 'One Man''s Junk', 'Step up to the plate with the Pawn Stars when a baseball believed to be signed by the 1959 World Series Champions, the Dodgers, gets thrown into the shop. Will Corey be able to hit it out of the park or will he strike out? Then, Rick gets his big break when he is presented with a rare Berndt-Maurer 1930s movie camera. Will he yell "Action" on the deal or will it be a bad take? And later, the Old Man vows retribution after Rick bans all junk food from the shop. Will revenge be sweet for the Old Man or will the plan go sour?', '2015-03-12', 21, '/cBGNdENFwqfstLhMjoElLD4LPcU.jpg', '2026-04-03T16:34:19Z', '2026-04-03T16:34:19Z');
