INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('c3d7ef44-b281-41f0-935d-b120343ae442', '3fdccc2c-e563-42fb-8874-c93879cd4141', 18, 'Return To Sender', 'The farmer receives a mystery gift from his antipodean cousin. Unimpressed with the present, he attempts to throw it away only for it to keep reappearing. He becomes convinced it has magical powers.', '2016-11-16', NULL, '/l4H8fZ0WSQvE6FDMjJKWfGYczJx.jpg', '2026-04-03T17:39:32Z', '2026-04-03T17:39:32Z');
