INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('c3ef0802-db15-4343-b666-16fa777bd13e', '573a556e-ed20-4222-a12d-b1b7779e1b18', 6, 'Australia''s Wild Frontier', 'Steve and Terri venture out to Cape York in Queensland, Australia, one of the most remote areas in the country. Among the creatures they spot are the Scrub Python, the Slately Grey Snake, feral pigs, a Rusty Monitor Goanna and the tree-jumping Canopy Goanna, the rarest goanna species in the world.', '1999-09-09', 44, '/aLg6u9W60AXYPCCjwTex77n6jc2.jpg', '2026-04-03T17:39:11Z', '2026-04-03T17:39:11Z');
