INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('c428156b-d836-4110-a42b-1e37852b7ca3', 'de8ec769-16bb-436b-be43-aedc7e18a7d7', 29, 'The Treasure of Yucky Mama', 'During Oscar the Grouch’s spring “cleaning,” he finds a fifty-year-old treasure map - but the neighborhood looks much different than it used to! Will Elmo, Abby, Nina, Oscar, and Charlie learn enough about Sesame Street’s history to complete three grouchy challenges and find Yucky Mama''s treasure?', '2020-05-30', NULL, '/47cua22AUtGBdm8j4QYkf6VT6bR.jpg', '2026-04-03T17:36:50Z', '2026-04-03T17:36:50Z');
