INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('c4d1fed3-9dec-45a2-9bf3-373308050458', '58adb9ab-3f1b-4a11-87b6-9b0b2dbb6aaf', 1, 'Pawns Ahoy!', 'Sail away with the Pawn Stars as a peg leg pistol hobbles its way into the shop. Will Rick and Corey say, "ahoy" or will they toss it overboard if it doesn''t fire? Then Corey and Chum check out four yearbooks signed by the ultimate teenager, James Dean. Will Corey be a rebel without a cause and turn down the offer or will he be a cool kid and make a sale?', '2017-04-10', 21, '/chNvqJKXlwEm7AwaCXd8TSf2Y9Z.jpg', '2026-04-03T16:34:21Z', '2026-04-03T16:34:21Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('c4d638dc-9762-4fe0-b855-22e4183fcd24', 'bff09904-103d-4ae2-9c13-c1febc903a46', 4, 'When Aunt Lena Did the Rhumba', 'LeVar explores Broadway as he looks at live entertainment options. Lucie Arnaz reads the feature story, about a young girl who decides to put on a show for her aunt, who usually treats her to Broadway play matinees, but now Aunt Lena is laid up in bed following a fall, and she gets depressed because she''s missing her stories.', '1998-10-08', 30, NULL, '2026-04-03T17:36:20Z', '2026-04-03T17:36:20Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('c4db4b68-0d77-4a0d-bdcf-94413b281856', '23c93536-610c-41c5-ac6b-a6b243423258', 18, 'Reunion (1)', 'The season nine reunion begins with a surprise as the ladies learn that the Grande Dame will not be in attendance, but not completely absent either. Wendy expresses her disappointment with Karen''s lack of accountability this season. Ashley, Mia and Stacey reveal the statuses of their divorces. Jassi and Stacey confront Mia about her shocking behavior during her off-camera birthday in Miami.', '2025-02-16', 43, NULL, '2026-04-03T16:35:41Z', '2026-04-03T16:35:41Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('c4dcdfbf-4fd1-47b4-b306-18cbeb52b6c8', '95ca8b6f-ccbc-431a-9d95-9b23367bbfed', 8, 'The Good, the Bad and the Ugly Leather Pants', 'Harry Hamlin’s homemade Bolognese sauce spices up Lisa’s gathering, but Crystal’s non-apology pushes Sutton to her boiling point. Garcelle’s birthday surprise has her wishing big and Kathy has unexpected news for Kyle about their sister, Kim.', '2021-07-07', 43, '/kDBZncpzpbQxWZ7uaoJ5sgOkUEP.jpg', '2026-04-03T16:34:58Z', '2026-04-03T16:34:58Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('c4dd5257-6889-409c-b097-c72a251d5807', '2f5a4ffe-2548-4181-85ac-6145cb3e3bf7', 5, 'Mariah''s Big Announcement', 'Christine and Meri try to recover the fun relationship they had years ago; Kody and Christine go to check out Flagstaff, Ariz.; Mariah has something big to announce to the family; Janelle talks to her kids about the move.', '2019-02-24', NULL, NULL, '2026-04-03T16:34:31Z', '2026-04-03T16:34:31Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('c4de932f-2f9c-40fc-b725-ad76f06f2889', '1996ddd8-20c9-4a30-96be-2b87fab8d17c', 28, 'Over a Barrel (2)', 'The team is frustrated when the garden is closed. They make their own warnings signs and learn that the barrels where dumped illegally. Tina''s brother gets into a fight with her family and the team gets a mysterious phone call.', '1993-04-18', NULL, '/ceLczMTTBXLLHlvSDfqAOWp6pJy.jpg', '2026-04-03T17:40:28Z', '2026-04-03T17:40:28Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('c4e0194a-a17b-4cf0-9d6d-237f78d1428e', '3a96d6c6-3736-498a-926f-6c479cdfb73a', 12, 'Franklin''s Blanket', 'Franklin is spending a night at his aunt''s place but couldn''t find his favorite blue blanket. His friends and father tried to give Franklin something in it''s place but in the end all Franklin really want is his special blanket.', '1997-11-27', 12, NULL, '2026-04-03T17:40:14Z', '2026-04-03T17:40:14Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('c4e1ef21-e04f-49db-b159-cd078d052d6d', 'de052e8e-7dbd-454a-a6d8-b9afba6e9bfa', 25, 'The Snow Wombles', 'The annual competition to see who can make the best snowman.', '1973-06-28', NULL, '/mHTMaNypTSvlJ2gR7ELzZvAC9Ig.jpg', '2026-04-03T17:23:19Z', '2026-04-03T17:23:19Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('c4e20118-103e-4512-81d0-27cec381a404', '4d2cac0f-38fd-438b-8afa-acf43952e535', 272, 'Episode 272', 'Christopher Trace and Valerie Singleton introduce a magazine programme for younger viewers.', '1964-03-16', NULL, NULL, '2026-04-03T17:21:47Z', '2026-04-03T17:21:47Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('c4e82668-5b13-423f-83a3-e560264d0aaa', '4b4d327b-6c8b-459c-9e73-b1d4d84aed77', 4, 'The Haunted Lighthouse', 'The bear family encounters an old lighthouse.', '2003-09-19', NULL, NULL, '2026-04-03T17:40:22Z', '2026-04-03T17:40:22Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('c4f17fc4-af89-4cfc-9cf8-c7db5ad095e9', 'dbd3583f-e9b2-46d1-a37e-309eb666e233', 11, 'Shaping Up and Shipping Out', 'Kim tries another get-skinny-quick trick as Kandi suffers through a boot camp workout to shed pounds before her trip to Africa. Phaedra fills Apollo in on socialite Marlo’s criminal history and decides to keep her distance from now on. Meanwhile, NeNe hatches a secret plan to bring Marlo along on the ladies’ 10-day journey to South Africa. While the other women prepare for their vacation, Kim is forced to prepare for life without Kroy when the NFL lockout comes to a sudden end.', '2012-01-22', 43, '/kEqjsvpYQa5I29rrtmAUaqsN1ay.jpg', '2026-04-03T16:34:45Z', '2026-04-03T16:34:45Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('c4f40225-6dc3-48ec-bfd8-0151cad0dd9b', '42e591e2-2a88-4434-ae9f-3d4b1d685613', 6, 'Dog Day Afternoon', 'It''s dog eat dog for the Pawn Stars when Corey''s pet pooch spends a day at the shop. Is it man''s best friend, or the Old Man''s worst nightmare? Then, a guy brings in a cavalry sword used by John Wayne in the movie Rio Grande. Will it take a "grande" cut out of their bankroll? And later, a Civil War medical syringe jabs into the shop. Will Rick and Chumlee plunge into this deal, or do needles make them squeamish?', '2013-06-13', 21, NULL, '2026-04-03T16:34:18Z', '2026-04-03T16:34:18Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('c4f58970-6cd1-4fe4-bb78-056936879b43', 'a84aa42d-e738-4081-8da9-1faec0209ee9', 24, 'Average Rules', 'Parent-Teacher conferences cause Frankie to worry about the kids. In them she''s told Axl is gifted but not applying himself, that her teachers still do not know who Sue is, and Brick may have to repeat the second-grade due to failure to return over 30 library books. Guest star Betty White as the school librarian.', '2010-05-19', 22, '/lTyxpx7qY3xLdNSSCY6pzrkQsEQ.jpg', '2026-04-03T15:40:28Z', '2026-04-03T15:40:28Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('c4f6fed9-4d14-405f-bd68-918304cc7e01', 'd5351b60-8a0c-482a-a6dd-4fb860cfe143', 8, 'Episode 1398', 'Mister Rogers arrives with some magnets which he takes to the kitchen to show how they attract each other: "Magnets are hard to explain, but they''re really fun to play with. Looking at one of the magnets which is shaped like a horseshoe, he mentions that Bob Trow is making a horseshoe game at the shop.

At Bob Trow''s workshop, Mister Rogers and Mr. Trow practice horseshoes on the new post Mr. Trow has made.  In the Neighborhood of Make-Believe, King Friday and Prince Tuesday sees Ino A. Horse through a telescope.', '1975-02-26', NULL, NULL, '2026-04-03T17:35:41Z', '2026-04-03T17:35:41Z');
