INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('c50bb977-0b86-43e3-a39d-04fc64cd42eb', 'd123fd65-efb7-4ebb-a23e-190c447791cf', 3, 'Painted with Pride', 'Larsa puts her house on the market; Nicole reveals her traumatizing childhood to Lisa; Alexia meets Herman’s lover; Adriana hosts Martina’s first solo art show while juggling two dates.', '2021-12-23', 44, '/aQnTe8MQHM3oElfKzG4ctBG602Z.jpg', '2026-04-03T16:35:11Z', '2026-04-03T16:35:11Z');
