INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('c511c366-deff-4b43-80e4-9a569f8a55a9', 'bbfee3b4-9c95-48a6-beaa-791fa08b1f43', 34, 'Episode 34', 'Merseyside: Twenty-five nations will be building gardens for Britain''s first International Garden Festival that opens on Merseyside in May, and your design could be included! Have a pencil and paper handy for the details and check with the plan of the Blue Peter site on Back Page before you send in your entry. There are prizes galore, and the best design of all will win the holiday of a lifetime in Singapore.', '1984-01-09', NULL, NULL, '2026-04-03T17:21:56Z', '2026-04-03T17:21:56Z');
