INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('c5187c0b-0e05-4869-b86d-6ed271ceecd4', 'c01ddd2a-bdb1-4c97-8d04-58f791ef1c24', 17, 'Ears Hear', 'Rabbits, bloodhounds, springhares, and foxes weigh in as Chris and Martin want to hear every animal''s range of hearing.', '1999-02-16', 27, NULL, '2026-04-03T17:10:55Z', '2026-04-03T17:10:55Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('c51dd032-05ca-4df8-b6a4-00ac63d82faf', '831e3a6b-c1a7-48b7-a5ac-b18ed67beb10', 11, 'Reunion (1)', 'Fevers spike as Gizelle, Katie, Ashley, and Robyn try to pull Karen off her podium as the Grande Dame of Potomac. Ashley defends her hostessing, her husband and her humping despite the slings and arrows of shade-rageousness. Robyn makes a surprising admission about her feelings for her ex-husband. And questions about the sensitive topic of race spark a high-octane feud.', '2016-04-10', 42, '/zt05b0CTebeM6JKvalMUZj4mEIj.jpg', '2026-04-03T16:35:38Z', '2026-04-03T16:35:38Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('c5244b12-1b2a-4c11-af92-8f6e5b294516', '5144de59-e67f-4fcf-919b-7106989ab797', 27, 'Bread and Matzoh', 'Skye brings some special bread from his tribe to share with the kids but is troubled when Jody refuses to try any for eight days. It turns out the reason is because of one of her own Jewish customs. Sizzle and Nuzzle get very hungry because the kids forget to feed them.', '1995-02-21', 29, NULL, '2026-04-03T17:12:21Z', '2026-04-03T17:12:21Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('c5254760-8649-429e-a2b3-1810492d290a', 'fb4ecc73-cb92-4c5c-821f-92179058b37b', 57, 'Episode 3712', '', '1998-02-03', NULL, NULL, '2026-04-03T17:36:41Z', '2026-04-03T17:36:41Z');
