INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('c532bc15-29e8-41d8-9d94-4a6e6204d6d1', '4892e2af-46c1-4b4e-ac81-eac161b5a347', 29, 'Episode 29', 'Peter Purves and Lesley Judd and the latest news of the Key-Note Appeal. Watch the totaliser totting up your envelopes. Every single key and car will help reach the Two Million Target. Send your contribution to the depot at: [address removed]. Also in today''s programme, PETER visits the studio of sculptor WILLIAM TYMIM to film the first stages in the making of the bronze statue of Petra.', '1977-12-19', NULL, NULL, '2026-04-03T17:21:53Z', '2026-04-03T17:21:53Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('c5360c2c-6d9b-4543-9571-2c69bf11df41', '9193e795-da7c-40ec-b68f-f63aa7d5174f', 306, 'How the Storm was Born', 'Behind-the-scenes featurette about the making of Game of Thrones Season 8, specifically focusing on the penultimate episode  and the destruction of King''s Landing.', '2019-07-24', 30, '/vCgwwoQ88NIzhpOLV2DqoxqwnKS.jpg', '2026-04-03T15:40:35Z', '2026-04-03T15:40:35Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('c536e429-1e0b-4ec3-bdd0-0e120fbbbf42', '3fc7c152-e4f6-426a-a899-36ec454c4403', 76, 'The Great White Cloud Whale', 'The friends help Captain Scallywag (from “Sky Pirates”) find a Great White Cloud Whale, who swallowed his ship.', '2000-04-26', NULL, NULL, '2026-04-03T15:26:03Z', '2026-04-03T15:26:03Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('c53975fd-28d3-41b6-aa74-b840420f22f2', 'ebc99729-ccb7-4d64-82c1-42708cd7ba85', 30, 'Episode 30', 'This time next week, Christmas Day will be nearly over. If your cards are arriving thick and fast and there''s nowhere left to put them, you might like to make a Christmas card hanger that doubles up as a very attractive last-minute decoration.', '1980-12-18', NULL, NULL, '2026-04-03T17:21:55Z', '2026-04-03T17:21:55Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('c541ad3e-b800-44a4-9794-70a8d7e87820', '52a47058-98e0-4ccb-aba0-b1481fbc2a96', 2, 'Black Ball''d', 'It''s party central between a ladies'' luncheon (with transportation issues) and an all-star gala (with an interloper). See the shots from the shindigs here.', '2011-03-01', 44, '/ajbA34JYt68NWHrXNSDBQtPeHFN.jpg', '2026-04-03T16:35:10Z', '2026-04-03T16:35:10Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('c54a20c5-410e-4dea-a89f-51a96f485c84', '941b8c65-4454-4336-be7c-1d0591c12f90', 15, 'Pingu and the Knitting Machine', 'Mother arrives home with a big package. Pingu wants to know what’s in it, so is close by when Mother reveals the contents – a knitting machine. The machine knits what Pingu thinks is a hat, and he puts it on, but Mother shows him that it’s not a hat but a tea cosy. Mother and Pingu go outside, and Mother puts a sign outside the door indicating that she’s ready to knit things. Grandfather comes by and Pingu tells him all about the new machine. He goes inside just as Robby turns up. When Grandfather comes out he has a new pair of knitted mittens and a scarf. He gives the scarf to Robby and they both go off. Pingu goes back inside. Mother is busy knitting. Pingu goes up to the machine and starts fiddling with one of the balls of wool. Mother tells him to leave it alone and to go and play. He goes away, but sidles back and has another play with the wool. Mother again tells him to stop. Mother then loads up her basket with things she’s knitted and goes out, and Pingu grabs the chance to have a go on the machine. He sits up to the machine, changes the balls of wool for different colours and sets the machine going. Pinga arrives as the machine starts to knit a scarf, which gets longer and longer. Pinga feeds in new balls of wool and the scarf gets even longer. Pingu tries to stop the machine, but it goes even faster and he and Pinga end up wrapped tightly in a roll of the scarf. Mother comes back, and is surprised at what she finds. Then Father comes in, unrolls Pingu and Pinga, and Mother tells them off. They tidy up the long scarf and then Pingu has an idea, so the machine is used to make a hat for each of the four of them using the wool from the scarf.', '2004-01-22', 5, '/hvQ4AYsjVSJgzb9HZjrxPGzh1RO.jpg', '2026-04-03T17:22:20Z', '2026-04-03T17:22:20Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('c553d747-2e6e-48fe-b211-a412104218fc', 'fc120008-c5c4-47d7-a3a9-91a401394c41', 26, 'The Giddy Grandma', '', '2003-02-16', NULL, NULL, '2026-04-03T17:40:21Z', '2026-04-03T17:40:21Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('c556a9dc-bbf2-4072-a910-bb6c183f57ff', 'dfe2c51c-8d2c-4c92-a010-7dbb71c3e48b', 9, 'Insect', '', '1995-05-29', 29, '/hNPgZaX4oNXhbZxuoEDYH0U4Sr2.jpg', '2026-04-03T17:39:04Z', '2026-04-03T17:39:04Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('c558cd0e-483f-4280-9e85-9a39505b6db0', '1415ef1c-411a-4c26-814a-7c79c3628bc2', 16, 'Three Tequila...Floor!', 'The ladies arrive in Mexico, with Ramona and Sonja scrambling for the best villa room and swiftly alienating themselves. Tinsley addresses a damaging article about her. Luann takes a boozy tumble. Bethenny reprimands Sonja for her bad behavior.', '2017-07-19', 60, '/6yiPpFDKDZPYdBH0UJXtWdzC3SJ.jpg', '2026-04-03T16:35:24Z', '2026-04-03T16:35:24Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('c5673c70-936d-48a9-9abc-ff78af3fdab9', '2afe02c5-499e-4d46-ad93-0504a321941f', 3, 'Escape From Marshank', 'Martin demonstrates he is a born leader, and everybody sees it.  Rose sees something else in Martin.', '2001-12-17', NULL, '/f1Yix74vzc7WtKlMxJHFIlXXc7X.jpg', '2026-04-03T17:12:08Z', '2026-04-03T17:12:08Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('c5678886-4264-4ca2-8c19-4688617de2c5', 'b7538712-04ce-43a6-9163-62280bbb084b', 23, 'Ernie Becomes a Birdketeer  (3873)', '', '2000-02-02', NULL, NULL, '2026-04-03T17:36:42Z', '2026-04-03T17:36:42Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('c5731908-8bfc-4f91-9caf-cfdb19ac4ec2', 'e3a28669-91b5-45f7-bb73-5006acc084e8', 27, 'Bitzer Puts His Foot In It', 'The farmer gets ready for a date and wants to look his best, so it''s time to dust off his prized hairpiece. Shaun can''t resist trying the wig on but loses it while showing off to the flock. The race is on as Shaun and Bitzer try to return the wig in time for the farmer''s big night.', '2007-09-06', 7, '/jzUknn1O7w8hb5U3wiavtptan3H.jpg', '2026-04-03T17:39:31Z', '2026-04-03T17:39:31Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('c57669d6-c22a-4726-b2b5-6b3f54887375', '97616d6e-5c17-449f-a376-55f1da83d6c3', 17, 'Mister Rogers Talks About MAKE-BELIEVE', 'Mister Rogers arrives with a popcorn popper which he has received as a gift from his wife. Taking it to the kitchen, Mister Rogers begins to demonstrate the popper when he receives a phone call from Joe Negri inviting him come to the music shop.

At Negri''s Music Shop, Mister Rogers is introduced to Ray Detwiler, a horn player who demonstrates a variety of rare horns. With Mr. Detwiler, Mister Rogers and Mr. Negri play Tree Tree Tree.

Back at the house, Mister Rogers returns to the popcorn popper which he demonstrates for viewers. Patiently waiting for the popcorn to pop, Mister Rogers sings Let''s Think of Something to Do.', '1982-07-01', NULL, NULL, '2026-04-03T17:35:42Z', '2026-04-03T17:35:42Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('c5795ade-a601-467e-a584-fbfa597cfa2f', '5144de59-e67f-4fcf-919b-7106989ab797', 34, 'Just Kidding', 'The others tease Skye when he forgets to bring a bat to a baseball game, prompting Skye to get upset and leave. Ben feels badly their teasing, even though they were just joking. Sizzle and Nuzzle climb up a tree in the greenhouse but are too scared to come down. Leon and Kiki only make cameo appearances.', '1995-03-02', 29, NULL, '2026-04-03T17:12:21Z', '2026-04-03T17:12:21Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('c57da56c-3106-4641-b370-112bafe0ef32', '1be79a20-de33-41d1-af17-079035b18d5c', 15, 'Happy Music', 'Sponsors: J, O, R, 6, 7', '1969-11-28', NULL, NULL, '2026-04-03T17:36:28Z', '2026-04-03T17:36:28Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('c5810f93-7b8d-4efc-ab86-ab4c770a9d28', '5704fb3f-fbbc-4177-88b0-9226373a9d4e', 32, 'Episode 32', '', '1966-01-25', NULL, NULL, '2026-04-03T17:20:12Z', '2026-04-03T17:20:12Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('c583eca9-b10b-4a5a-81af-7a44475944cf', 'ea73e13c-6962-4804-8305-c303df65f89f', 3, 'The Froggs are Moving (3) - Lady Elaine becomes a curator', 'Rogers discusses antiques and uses a vacuum cleaner to show how it works. In the Neighborhood of Make-Believe, Lady Elaine applies for the position of Museum-Go-Round curator. Since she knows everything in the Museum, she is awarded the job. This enables the Frogg family to move to Westwood.', '1969-02-12', NULL, NULL, '2026-04-03T17:35:38Z', '2026-04-03T17:35:38Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('c58574b6-ea40-4919-a7df-09e65552c8b6', 'cc140989-c480-4586-b460-8872b416a0b7', 3, 'Little Nino''s Pizzeria', 'LeVar makes a pizza, while "The Wonder Years" star Josh Saviano reads a story about about a boy who''s father runs a pizzeria.', '1989-07-05', 30, NULL, '2026-04-03T17:36:17Z', '2026-04-03T17:36:17Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('c5871df9-4ecd-4376-80b7-8bfc564121bf', '05c0e384-194c-4417-9f62-803eb615e409', 73, 'Rainbow cookies', 'Title number 0073. Opens with Mister Rogers arriving with two boxes which contain a ring and a hat. Mr Rogers sings "Let''s Go Right Away". Lady Elaine is derided for throwing litter around as a protest. What she really has wanted is one of Chef Brockett''s cookies.', '1968-05-29', 28, NULL, '2026-04-03T17:35:38Z', '2026-04-03T17:35:38Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('c58b2fb2-1b7e-4a58-b504-a9f0a1be9263', '5ee9d1ca-b0a3-4dfe-bb10-1f61014f25a5', 5, 'Episode 5', '', '1993-02-05', 25, NULL, '2026-04-03T17:21:16Z', '2026-04-03T17:21:16Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('c58c56f1-e42d-4c59-8051-85b9e92629b3', 'b0e57338-0cf1-43cf-b91d-e668b6cefee3', 5, 'DELETE ME', '', NULL, 5, NULL, '2026-04-03T17:24:26Z', '2026-04-03T17:24:26Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('c58e684e-6703-461c-86f8-2281f822b41f', '227b8429-0dfd-47e4-b874-c37da20c403f', 6, 'Damn Yankees', 'The Old Man hopes to hit a home run when a baseball autographed by the 1951 World Series Champion New York Yankees comes into the shop but he''ll need to verify its authenticity before he steps up to the plate. Then, Rick checks out a 25-piece Knights of the Round Table set but with all the kings'' men accounted for, is it really worth its weight in gold? Finally, the Pawn Stars have a chance to buy a West Point Cadet jacket owned by a famous general in 1909 - will they try it on for size, or send it to the Salvation Army?', '2009-08-02', 21, '/6ytwfWTtm4MTf6luPmKtvpv4wPc.jpg', '2026-04-03T16:34:15Z', '2026-04-03T16:34:15Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('c590b6c8-13e9-4a7f-b5f6-38d234342231', '3430d881-14a2-497d-9cf4-351b78b6aa6a', 9, 'Postman Pat and the Big Surprise', 'Pat does some gardening before work. When he tries to remove a weed, he sprains his back and Sarah calls Dr Gilbertson in. Pat needs a day in bed so Sarah offers to take the post instead. Everyone is surprised to see Sarah delivering the post instead of Pat. Sarah has also forgotten something.', '1997-05-29', 15, '/34wcgLzXfS3esfsMbx58E7w1BA4.jpg', '2026-04-03T17:14:30Z', '2026-04-03T17:14:30Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('c590c73d-cf03-4d56-adf9-e70f8aa6b013', '53f9624f-fcf8-4f77-82f6-d2eb3f5376ee', 28, 'One on One (3)', 'In part three of this One-on-One interview special, Meri discusses her distrust over Coyote Pass.', '2025-06-08', NULL, '/i3I46TN3M6HKRQKiWEaSXP11Typ.jpg', '2026-04-03T16:34:33Z', '2026-04-03T16:34:33Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('c592c1df-1126-43ef-a824-134cbf681f9f', 'e03d79bd-e01f-4414-b0b3-f3b5f26e97f4', 5, 'Foreign Exchange', 'Against the family''s wishes, Frankie invites a Japanese foreign exchange student to live with them, in the hopes of exposing him to American life; however, the Hecks get frustrated when he shows no interest in them or America.', '2010-10-20', 22, NULL, '2026-04-03T15:40:29Z', '2026-04-03T15:40:29Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('c595c1c8-78dd-4a2c-a1cf-a901f0e22ce0', '5062ce29-8dbb-48ab-879b-0771221678d5', 2, 'The Fox''s Hiccups', 'Squirrel tells Fox a rather funny joke, which gave him the hiccups because he has been drinking lemonade. The others try to cure him, but out of them, Owl only succeeds, which then gave her the hiccups!', '1999-09-26', 15, NULL, '2026-04-03T17:19:02Z', '2026-04-03T17:19:02Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('c5963799-97a8-41a3-b48a-d9bde575ff79', 'd1863f2f-02ec-40ce-af64-db03fbe518a7', 7, 'The Best Friend Band', 'Elmo and Abby learn how to compromise and combine their two favorite songs, creating the Best Friend Song. Also featuring ''That''s Music'' song with 5th Harmony, Murray had a little lamb-music school, and Elmo''s World-violins. Brought to you by the letter M and the number 5.', '2016-02-20', NULL, '/rcThkjilcVoTD1vBtwG7T51JTcq.jpg', '2026-04-03T17:36:48Z', '2026-04-03T17:36:48Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('c59dd064-f9fc-49a4-9afc-56253bd0621d', '94efc131-3a47-4bcb-a519-330e791ce905', 2, 'The Secret Path', 'Percy is very busy with all his work around the park, and does not have time to play with the animals, who are bored and looking for someone to have fun with.', '1996-03-12', 15, NULL, '2026-04-03T17:19:01Z', '2026-04-03T17:19:01Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('c5a3ac81-170d-4560-baf7-163613f8e9b6', 'e13f4aa4-dd8a-48d5-8cc1-1c258f43e44d', 108, 'Season 1 Reunion', 'The five women reunite to tell their stories and reflect on the show.', '2006-05-13', 44, NULL, '2026-04-03T16:35:29Z', '2026-04-03T16:35:29Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('c5a9c162-2ec6-433e-956f-43607477a8e4', '3af7ea64-fa13-4097-b8e4-40af07083054', 36, 'Harvest Festival Pt 1', 'Chef Brockett makes waffles at the McFeelys'' house. In the Neighborhood of Make-Believe, he begins searching for maple syrup. Lady Elaine promises she will make syrup by Thursday.', '1974-04-08', 28, NULL, '2026-04-03T17:35:40Z', '2026-04-03T17:35:40Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('c5aecfdb-8fcf-4667-9f07-829f0d56880d', '4d2cac0f-38fd-438b-8afa-acf43952e535', 102, 'Episode 102', 'A magazine programme for younger viewers.  Introduced by Christopher Trace.  Including Packi''s Caravan.  Told and drawn by Tony Hart and Pollyanna, an extract from the new Walt Disney film.', '1960-09-30', NULL, NULL, '2026-04-03T17:21:47Z', '2026-04-03T17:21:47Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('c5aed4b3-9098-41ea-94f3-48e15bf54e6e', 'ca09391a-de6a-4b2b-aefc-c2efbc80a106', 6, 'Opt: An Illusionary Tale', 'In this episode, all is not what it seems as LeVar demonstrates optical illusions from the book by Arline and Joseph Baum. He also shows how special effects are created for television; meets artist Christian Thee, who paints trompe l''oeil, or "trick-the-eye," paintings; and shows clips of kids creating their own optical illusions as well as camouflage tricks that animals use to deceive predators.', '1991-09-23', 30, NULL, '2026-04-03T17:36:17Z', '2026-04-03T17:36:17Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('c5af91f0-7638-4c6b-a2bf-c20b0b4efdf6', 'fb4ecc73-cb92-4c5c-821f-92179058b37b', 45, 'Mumford helps Oscar (3700)', '', '1998-01-16', NULL, NULL, '2026-04-03T17:36:41Z', '2026-04-03T17:36:41Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('c5ba2d8a-872a-40d8-ae50-1ce54a3b453b', 'd5f0284f-0ee3-45bf-8539-d02a825d15b2', 3, 'Loose Lips', 'Guerdy confides in Larsa that she has cancer, but Larsa repeats the news to her guests at Marcus'' welcome home party; Nicole decides to have another baby; Julia takes opera lessons to surprise Martina, but upsets her wife in the process.', '2023-11-15', 44, '/ezJ1dCsSN455n4dT1Dhcpj0FiuE.jpg', '2026-04-03T16:35:12Z', '2026-04-03T16:35:12Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('c5c039a7-eaa2-4eb5-b68c-97965da6a13b', '4bf3b194-81b8-4726-8850-62b05609eac8', 12, 'Very Behind The Times', 'An enormous road to be built causes panic.', '1975-09-30', NULL, NULL, '2026-04-03T17:23:20Z', '2026-04-03T17:23:20Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('c5c4f371-fc7a-453a-9046-72c6d45e549a', '42e591e2-2a88-4434-ae9f-3d4b1d685613', 45, 'Put Your Hands Up', 'Put your hands up with the Pawn Stars as the guys check out a wanted poster for legendary criminal John Dillinger. Will they capture it for the shop, or let this one get away? Then, a Lambretta scooter zooms into the shop. Can this vintage Italian ride withstand a test ride by Chumlee? And later, the guys bet on who can take the most steps in a week, but will one of them rig the count?', '2013-12-26', 21, '/r5q7SP4w74nCkF01CJae52Y5glx.jpg', '2026-04-03T16:34:18Z', '2026-04-03T16:34:18Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('c5cdb919-ac8d-4a37-bb52-0105ca8db577', '33825a15-37dc-4ff9-82bd-cc720498149a', 7, 'Ghost Busted', 'Brandi continues to attempt to bond with her daughter Brooklyn, while Stephanie and Kameron try to work things out after their dust-up at LeeAnne’s lingerie shower. Kary confronts LeeAnne about D’Andra, and all the girls go ghost hunting at a real haunted house, but find themselves haunted by ghosts of the past.', '2019-10-16', NULL, '/otxToV48UqMzGiQwrYglusQbvfM.jpg', '2026-04-03T16:35:04Z', '2026-04-03T16:35:04Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('c5cfc46d-1dc7-4d81-bd43-9a34dd909391', 'e48599f8-66ff-4c0f-9274-65b9ae1cda9e', 72, 'Episode 72', '', '1977-05-26', NULL, NULL, '2026-04-03T17:21:53Z', '2026-04-03T17:21:53Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('c5d2dd60-104b-4c59-9782-61e44921017d', 'd0b78f22-678e-4e46-9d61-aac40ba206b8', 12, 'The Ultimate Ultimatum', 'After weeks of not speaking, Lisa Vanderpump finally sits down with Dorit to hash out their issues. Unresolved tension between Kyle and Dorit comes to a head at Teddi''s dinner party. Meanwhile, Erika and Lisa Rinna endure a challenging workout, while Denise gets her first taste of Camille''s insincere ways.', '2019-04-30', 43, '/nsrnFOxV9DqgojSvKIgauXurYM3.jpg', '2026-04-03T16:34:57Z', '2026-04-03T16:34:57Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('c5d6e773-9898-46ed-9995-1053e27a3566', 'd034c38d-c0c7-42b4-8876-394b63d84275', 9, 'Whine Pairings', 'Peggy and Micah throwing their annual dinner party and hire celebrity chefs, Susan Feniger and Mary Sue Miliken of Border Grill, to cater the event. Tamra’s new boyfriend, Eddie, meets the ladies for the first time. During the party, Alexis causes a scene and flees the table, leaving Peggy livid and Donn is shocked by Vicki’s comment to the group about wishing they had started their own family together. Mary Sue Miliken of Border Grill is a contestant on Top Chef Masters 3.', '2011-05-01', 44, '/jSw2BJZZA8NwfjCbqkQRpm8Iwte.jpg', '2026-04-03T16:35:31Z', '2026-04-03T16:35:31Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('c5d7a5f5-5e06-4661-95d8-956cea8c543a', '63f9bf6d-39b3-44f4-b885-a56807277a80', 2, 'The Muppet Show: Sex and Violence', 'In this half-hour variety special, the Muppets parody the proliferation of sex and violence on television. Nigel, Sam the Eagle, and hippie guitarist Floyd prepare for a Pageant based on the Seven Deadly Sins.', '1975-03-19', 26, '/oqUjyPItcRhd7V4DvZUPCiEmuwX.jpg', '2026-04-03T17:35:23Z', '2026-04-03T17:35:23Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('c5d96aa6-2be9-4166-8158-42fc75e04c85', 'd1d267dd-e27f-4543-acb8-0d28f676512a', 60, 'Episode 60', 'with Valerie Singleton, John Noakes, Peter Purves', '1968-04-01', NULL, NULL, '2026-04-03T17:21:49Z', '2026-04-03T17:21:49Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('c5dfac40-a457-46d7-9ca2-82bfeef2c320', '2b968a9c-5fc0-4e93-bcf9-31d3e4c7b210', 19, 'Episode 19', '', '1975-11-10', NULL, NULL, '2026-04-03T17:21:52Z', '2026-04-03T17:21:52Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('c5f0a70a-8e55-44c3-a7b8-0bb4fd78388a', '97616d6e-5c17-449f-a376-55f1da83d6c3', 2, 'Mister Rogers Talks About DISCIPLINE', 'Mister Rogers arrives with a piano roll for a player piano. He explains how a piano roll works and talks briefly about how he had to practice regularly to learn to play the piano. At Negri''s Music Shop, Joe Negri helps Mister Rogers to demonstrate a player piano before they look inside to see how it works. Before Mister Rogers leaves, Mr. Negri shows a short film about how piano rolls are made.', '1982-03-01', NULL, NULL, '2026-04-03T17:35:42Z', '2026-04-03T17:35:42Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('c5f14f23-3973-491d-8d05-b033ce0aeaa0', '4d2cac0f-38fd-438b-8afa-acf43952e535', 265, 'Episode 265', 'Christopher Trace and Valerie Singleton introduce a magazine programme for younger viewers.', '1964-01-27', NULL, NULL, '2026-04-03T17:21:47Z', '2026-04-03T17:21:47Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('c5f8508a-4ba1-4314-9a7a-03ccb1515fe9', '3ee646e8-23ae-4dec-bbc6-c7e6a210d55b', 72, 'Remembering times of sadness', 'Susan tells the viewer that today, everyone will be discussing times when they felt sad. Prairie Dawn is the first to go, describing the day she got sick on the premiere of her new pageant, "The Life of a Potato.". A flashback shows Susan tending to a bed-ridden Prairie.

Sponsors: C, N, 0', '1991-02-19', NULL, NULL, '2026-04-03T17:36:38Z', '2026-04-03T17:36:38Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('c5fba633-1503-4cb4-aca3-04762296389a', '7b8e3988-fbf3-4cfc-aeb2-782ae5a64e2d', 25, 'Grouch Mother''s Day', 'Oscar tries to give his mom the worst Grouchy Mother''s Day ever, but he has keen competition from his sister Bunny. Also: the "Word on the Street" features Rachel Griffiths ("Brothers & Sisters") discussing the word "dozen" with Elmo.', '2010-12-30', NULL, '/ntm2GNk51ktqsxxmPXHPe50BnV1.jpg', '2026-04-03T17:36:46Z', '2026-04-03T17:36:46Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('c5fc673d-824d-4539-8c40-165b164cf8fb', 'bf874be3-7e2f-4a0e-b205-c76ac1ad69fc', 141, 'Inside Looks (on The Nap)', 'Inside look from the season 8 episode "The Nap."', NULL, 22, NULL, '2026-04-03T16:34:09Z', '2026-04-03T16:34:09Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('c5fcfc51-b35a-4c2e-9b19-0b0431dba992', '3415030f-f54d-42b9-a290-aaa05e246d86', 7, 'Guide to Wedded Bliss', 'Relive special moments from three Brown family weddings. Robyn and Kody get married as the other wives help celebrate. The entire family takes part in a commitment ceremony. Plus, Kody and Janelle''s daughter Maddie says "I do", at the wedding altar.', '2016-12-25', NULL, NULL, '2026-04-03T16:34:30Z', '2026-04-03T16:34:30Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('c5fdf0d3-1487-4348-b5eb-3f44fee5c9c8', 'b1d55597-d9d2-4eee-ab95-46dbb163291a', 7, 'Pingu and the Snowball fight', 'Robby the seal jokingly attacks Pingu with snowballs. Pingu is enticed immediately to join an acrobatic game in which a large pink fish is the object of their japery. Pingu, in a bizarre moment of claustrophobic inertia, finds the fish''s mouth trapped over his head and Robby, briefly abandoning his joking around, aids his relatively new friend by removing the fish from Pingu''s head. They then play a tennis-style game using the fish. However, the fish is eventually caught on the rope and, after a futile attempt to retrieve the fish, Pingu retrieves it using a pair of ice-stilts placed conveniently by his igloo. Robby strips the fish of its skin and flesh and divides fish in totally equal parts.', '1987-10-15', 5, '/ahxt0jqjTiXMJj0n1djZ8nHMIg8.jpg', '2026-04-03T17:22:18Z', '2026-04-03T17:22:18Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('c5fe02e3-d948-4bb5-abe3-898a60699c69', '79c64e0a-3488-41bc-9b5c-2243ff15b373', 16, 'The Last Supper', 'The ladies’ Italian adventure comes to a dramatic end with an explosive final dinner that leaves longstanding friendships fractured. Back in Beverly Hills, Dorit poses for her book cover. Boz looks for a new house with Keely. Rachel hopes the fallout from Tuscany doesn’t ruin the disco vibes at her birthday bash.', '2026-04-02', NULL, NULL, '2026-04-03T16:34:59Z', '2026-04-03T16:34:59Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('c600aaf3-1416-4ef0-ad16-cc4ebba4870b', '84a24124-2290-4b86-aa88-5514da7bd0b6', 8, 'Going Away and Coming Back', 'Rogers gets a feel for shooting a basketball from a chair. This segues eventually to his visit with a wheelchair basketball team called the Steelwheelers. More residents in the Neighborhood of Make-Believe join in Stephen''s search for a hidden tunnel. One clue comes from a scrap of paper.', '1994-04-12', NULL, NULL, '2026-04-03T17:35:47Z', '2026-04-03T17:35:47Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('c60652e8-4e4d-4215-8cf7-2c6d37283af5', '421c3366-4d98-4baf-b4ad-6ec5047df9f8', 11, 'Speak Up, Francine!', 'The local creek is polluted! Francine is determined to get the word out at the annual Earth Day rally, but she can''t seem to speak up, so Ladonna attempts to help.', '2014-04-21', 13, NULL, '2026-04-03T17:38:01Z', '2026-04-03T17:38:01Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('c60b26c0-dd75-4e7a-ab13-81ee4f566723', '4d2cac0f-38fd-438b-8afa-acf43952e535', 331, 'Episode 331', 'with Christopher Trace and Valerie Singleton.', '1965-01-28', NULL, NULL, '2026-04-03T17:21:47Z', '2026-04-03T17:21:47Z');
