INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('c60f7a65-4884-4c81-b20d-a15dac94025b', 'f4d370ca-3c39-40a8-911d-e2b5e7c6b0d7', 12, 'The Birthday Camp', 'It is Little Bear’s birthday and the toys have given him a tent. He is so excited that he wants to sleep in it that night. Old Bear isn’t so sure but Rabbit volunteers to look after him, so they all go out in the garden to put up the tent. As it gets dark Little Bear and Rabbit discover that they are still rather hungry but they have forgotten to bring a torch to find the food. However a night-time visitor comes to their rescue and the birthday goes on getting better long into the night.', '1996-11-20', 10, NULL, '2026-04-03T17:18:56Z', '2026-04-03T17:18:56Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('c60ffda5-16a4-4b8d-ad62-a5c59c30ca94', 'd1d267dd-e27f-4543-acb8-0d28f676512a', 48, 'Episode 48', 'with Valerie Singleton, John Noakes, Peter Purves.', '1968-02-19', NULL, NULL, '2026-04-03T17:21:49Z', '2026-04-03T17:21:49Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('c61264ee-b973-44ea-8c46-71ffb066803a', 'b2317fc3-1cfc-4f19-b181-effa23959c6d', 11, 'Nightmare in Nashvegas', 'After 20 years, Teresa moves out of her home and Frank moves in with his kids. Dolores hosts a Nashville getaway. A fight between Teresa and Margaret leaves the group divided.', '2022-04-12', 43, '/wu63JyrpKp13Q7Fhq1DRduYo6S2.jpg', '2026-04-03T16:35:18Z', '2026-04-03T16:35:18Z');
