INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('c6a52c8e-4e11-4c19-a965-8c1d591a1768', 'bcab920a-51a5-4cbb-aa59-41578a0eb005', 13, 'Cake Therapy', 'Erika flexes her acting muscles as she rehearses for her upcoming soap role with Eileen. Lisa Vanderpump and Ken visit their new dog rescue center. Later, Kyle throws a cake tasting for Wilson Phillips singer Carnie Wilson, where Lisa Rinna makes a startling—and very public—confession to Kim.', '2017-02-28', 43, '/3Dqp3HGXzH8onrVitk1vNxJJlcc.jpg', '2026-04-03T16:34:56Z', '2026-04-03T16:34:56Z');
