INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('c703731c-10c2-4699-bd19-de6baab3d6a8', '42e591e2-2a88-4434-ae9f-3d4b1d685613', 46, 'A Very Vegas Christmas', 'Celebrate the holidays Vegas style as the guys from Pawn Stars, Counting Cars and American Restoration get together for a Christmas barbecue. First they''ll deck the halls with pawn shop drama, when they debate the best and worst deals they''ve ever made. Then, the guys take a look back at all of the amazing restorations that Rick Dale and Danny have done for the pawn shop. And later, it''s finally time to eat. But can these guys cook as well as they negotiate?', '2013-12-19', 21, '/cRiUJ4yQCql5a8q42MKmPk7vE8x.jpg', '2026-04-03T16:34:18Z', '2026-04-03T16:34:18Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('c706fc62-315a-4b03-b014-f9d1d696ba3e', 'dbde6570-a68d-4fd7-a1b0-a6037a266a18', 6, 'The Party''s Over', 'The Bunco Party takes an uncomfortable turn when Slade and some of the O.C. men, invited by Tamra, join the party. Confronted immediately about the insulting things he said about Vicki in his comedy routine, Slade aggressively defends himself.', '2012-03-13', 44, NULL, '2026-04-03T16:35:31Z', '2026-04-03T16:35:31Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('c7095a71-56b1-429e-8011-da0d973fa897', '4900fc8d-5e7e-408e-972e-ce9269d203b3', 1, 'Fancy Pants is Back', 'After a five-year hiatus, Heather Dubrow is back; Gina and Emily pay a visit to Dr. Jen Armstrong for some OC style self-care; things go awry when Shannon spills a secret about her old friend, Nicole, leaving Gina and Emily in an awkward position.', '2021-12-01', 44, '/cZ0CyyNnfFMbE8D2Zt760K5AJCe.jpg', '2026-04-03T16:35:35Z', '2026-04-03T16:35:35Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('c70cbb26-4b23-4d95-82be-15412f5a3b43', '33e647e7-a3e8-4c3a-93e6-74e08399a790', 10, 'Yuckies', 'While Mr.Gribble sets out to destroy a rainforest and erect a casino, Nell sets out to save the magic Yuckles from extinction.', '1992-06-05', 24, '/p59UpeidWkpAUhRjs30u0tdbQyH.jpg', '2026-04-03T17:40:41Z', '2026-04-03T17:40:41Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('c70e7dc3-92d9-4b42-b6ee-b2ca9de579a8', 'bf0f7445-f58f-467f-a81b-fcc2bf6bca21', 21, 'Wembley and the Great Race', 'Wembley and Gobo''s friendship is strained when Wembley beats Gobo in a race.', '1984-05-21', 24, '/wI9Kvdqt2H1bhXqzMPVSZKaHwoI.jpg', '2026-04-03T17:35:00Z', '2026-04-03T17:35:00Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('c71566d9-a3a9-4a8e-97cc-ae86891c85a7', '45e64a15-8fc0-4e4b-a1ca-9e3f42f3634d', 1, 'Flight', 'Things that fly need air. Even though we walk through it, breathe it, and sneeze it, air seems to be a whole   bunch of nothing. But air is there, and it''s powerful. Balloons inflate because air presses on the insides   and outsides of the balloon. Air pressure in tires supports the weight of bikes, buses, trucks, cars, and   planes. But air doesn''t need to be inside something to exert pressure. Air that moves around pushes,   too.   What do birds, planes, kites, Frisbees, and helicopters have in common? They fly because moving air   creates lift, or a push up. Airplane wings are shaped to push air down. The momentum of the air going   down pushes wings up. Air above the wing gets going faster than the air underneath. Fast-moving air   zips along, without pushing as hard side to side or up and down. The slow air pushes up from below   harder than the fast air pushes down from above ... and you''re airborne!   Every flying thing, from the tiniest flying insect to the biggest airplane, us', '1993-09-10', 26, '/jSE0by5opmjybp3tl6GPSFK0vSQ.jpg', '2026-04-03T17:37:20Z', '2026-04-03T17:37:20Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('c71df656-831c-4aeb-aff0-a0dbe4c77943', 'c01ddd2a-bdb1-4c97-8d04-58f791ef1c24', 28, 'Horses', 'Everybody likes horses, so the Kratts spend time with a foal and her mother, a strong Belgian draft horse.  Then the brothers learn what''s different about zebras.', '1999-06-29', 27, NULL, '2026-04-03T17:10:55Z', '2026-04-03T17:10:55Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('c72a3889-ac17-4395-aef5-37513e476054', '66a11a09-aee2-4a7b-8543-ab080a9d1be4', 3, 'Pay Attention to Me!', 'Lisa Vanderpump arranges a private birthday dinner for Lisa Rinna at PUMP. Harry Hamlin shows up with just the perfect gift. Brandi settles into her new home.', '2014-12-02', 42, '/xL2WxEDsGpE9TwZ1mBrypUPX9AK.jpg', '2026-04-03T16:34:56Z', '2026-04-03T16:34:56Z');
