INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('c74a2ee8-5e6d-43ff-807d-b0c2fbcc89be', 'a0fa5075-9ce1-48c1-9995-0c0fd866e549', 13, 'Caviar Catastrophe', 'Sutton and Dorit’s feud gets dirty as a food fight almost breaks out at Jennifer Tilly’s first group lunch. Bozoma’s hopes for her fertility journey are met with a reality check. Shocking photos leave Garcelle and Erika seeking answers. Kyle facing even more questions about her future.', '2025-02-25', 43, '/tx8JjRBOkmbLHWj0o4yGfHr3HgS.jpg', '2026-04-03T16:34:59Z', '2026-04-03T16:34:59Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('c74dd39f-2a99-4d4d-8032-a4ed2ec442fa', '1d713ca6-4e17-4f84-949c-8cfd98514127', 42, 'Oldest Trick in the Book', 'Climb to new heights with the Pawn Stars when a signed, limited edition copy of Seven Years in Tibet is brought in. Can Rick read between the lines on this literary classic or will he judge a book by its cover? Then, things get comedic when Corey and Chumlee check out a Three Stooges promotional projector. Will they have the last laugh or will the joke be on them? And later, Chum tries to institute new policies in order to liven up the beginning of the work week. Can he successfully turn it into a fun day or will it be just another manic Monday?', '2014-12-18', 21, '/1FNrhQEu1a7okOyOmPqBQQzaOK5.jpg', '2026-04-03T16:34:19Z', '2026-04-03T16:34:19Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('c74fee80-17c9-44ec-a64e-c37e2c096f69', '0e419615-4c96-4dde-8ed2-715770ba77bb', 15, 'Show Your Stuff', 'One weekend, Bear decides to start a new hobby --- "whittlin''." He gets a block of wood and an instruction book, but finds that his early efforts don''t look much like the duck in the book. He determines, however, to keep trying. Meanwhile, the kids in the Big Blue House are exploring talents of their own. Ojo continues working on her bike-riding, while Pip and Pop have developed a synchronized-swimming routine. Treelo searches all over for his talent. Tutter, however, experiences a lack of confidence when he learns how great Rita is at kicking the ball in soccer. He tells Bear that he''s quitting the team.  Songs  Do Your Thing  Notes  There is no Shadow segment in this episode.', '2003-11-03', 25, NULL, '2026-04-03T17:35:32Z', '2026-04-03T17:35:32Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('c751fb27-fa44-414e-b78e-85f2c0288da0', 'a79a245f-acab-4ebe-aee9-29867f9e52f6', 4, 'Groomzilla Part 2', 'Mykelti, her moms & her fiance Tony go wedding dress shopping and he''s very opinionated! Then the Sister Wives go see the B&B Meri wants to buy in Utah, but worry it will pull her away. Later, Madison shows up with big news, leaving Janelle in tears.', '2018-01-14', NULL, NULL, '2026-04-03T16:34:30Z', '2026-04-03T16:34:30Z');
