INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('c764fe62-a8bf-4223-9b56-b5bcdb884368', '34674c90-410e-427c-be4d-2a6f6f865a80', 1, 'Guilty as Charged', 'The Pawn Stars are up in arms when a late 1700''s flintlock four-barrel handgun takes aim at the shop. Will Rick bite the bullet for this 4-piped pistol, or does he let it shoot by? Then, Rick and the Old Man are presented with a book of misprinted Eisenhower postage stamps. Are these first class mistakes or will they be returned to sender? And later, when Rick finds broken merchandise in the warehouse, he uses the shop''s security camera to try and track down the guilty party.', '2012-04-09', 21, NULL, '2026-04-03T16:34:17Z', '2026-04-03T16:34:17Z');
