INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('c773dc4f-8737-4637-9015-8c0444686421', '7c422193-b078-49d8-81ef-f2b9f94f059d', 53, 'Telly is "Triangle Guy"', 'Episode #3058', '1993-01-20', 55, NULL, '2026-04-03T17:36:39Z', '2026-04-03T17:36:39Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('c7765f9c-87bc-4e3b-9864-1eaa910c053d', '3269a890-bba9-4e6c-9278-f7eb38eb1720', 4, 'Rocks & Soil', 'We live on top of rocks – the Earth’s surface. There are three basic types of rocks — igneous, sedimentary, and metamorphic — and each type is made a different way. Igneous rocks are made from cooled lava. Sedimentary rocks are made from small pieces of other rocks stuck together. Metamorphic rocks are formed when other rocks are heated or pressed, or both. One type of rock can change into another type of rock as the Earth’s surface shifts and changes. It takes the right conditions and a lot of time.', '1995-02-03', 26, '/i4821AlQyvq1wB3OvlZHIlhO79a.jpg', '2026-04-03T17:37:21Z', '2026-04-03T17:37:21Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('c7864711-22c8-449b-974a-1244b07dd4e1', '5c1b881f-ac58-4d72-b63f-209952d4f902', 11, 'Episode 11', '21st Birthday Programme  Join in the celebrations with Simon, Chris, Tina and the animals, including the first-ever presentation of the Blue Peter ''Award for Outstanding Endeavour''. With William the Conqueror and 14 dinosaurs in the studio, plus the band of the Royal Marines, anything might happen!', '1979-10-15', NULL, NULL, '2026-04-03T17:21:54Z', '2026-04-03T17:21:54Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('c7a00099-f33c-4996-9d5f-d0f4abeb04e7', '4d2cac0f-38fd-438b-8afa-acf43952e535', 349, 'Episode 349', 'with Christopher Trace and Valerie Singleton.', '1965-04-01', NULL, NULL, '2026-04-03T17:21:47Z', '2026-04-03T17:21:47Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('c7a15171-f303-4927-a8f2-668fcdd55838', 'ecdefd77-a7ac-4344-bea1-fb1df2fd0ac9', 2, 'A Very Important Time', 'After receiving an unexpected visit from the Postman, Sam accidentally messes up her future. Can she correct her mistake to put the course of time right again?', '2001-11-27', 15, NULL, '2026-04-03T17:20:05Z', '2026-04-03T17:20:05Z');
