INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('c7d46c26-f2af-49bf-80b6-582a4cf71613', 'ca19f895-1514-4988-a709-95e84eab7cee', 16, 'Pawn Stars and Movie Stars', 'Rick and Chum flip out when Spencer stops by the shop with a few vintage items. Will they tilt the negotiations in their favor, or will they not be able to see eye to eye? Next, a Bruno Mars platinum album spins into the shop. Can Corey land a funky deal, or will he get locked out of negotiations? Later, Chum twists and shouts when a pair of boots signed by Ringo Starr walk into the shop. Will he and the seller be able to come together, or will Chum have to make his peace with not landing a deal? And finally, Rick calls in actor Dennis Quaid to help authenticate a signed poster for his upcoming movie. Can Rick be a great communicator, or will the seller give him the cold shoulder?', '2021-05-03', 42, '/vtDX07MEGZvEvUlchjTIYI3YTKE.jpg', '2026-04-03T16:34:22Z', '2026-04-03T16:34:22Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('c7dc8a2a-f258-4557-8141-6da8c18c8836', '36e5c604-fea9-4bcf-8343-71bfaf60ecd2', 1, 'Theodore and The Oil Rig', 'A new oil rig called Tex is very rude to Theodore and Hank and he simply just doesn''t want their help. However, when a terrible storm puts Tex in grave danger will he then accept the tugs'' help?', '1993-07-05', NULL, NULL, '2026-04-03T17:10:11Z', '2026-04-03T17:10:11Z');
