INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('c806565d-3f73-496f-b680-69e5b8fb36bd', '97a3d1f5-a8f1-47cd-8122-2e74a092836d', 19, 'Who is Max Mouse? (3)', 'Jamal suspects that Janice lied about having her own computer. The team challenges Max Mouse to some online games and creates their own screen name and get the phone numbers of their suspects.  Then they learn Calvin had another screename: Red Parrot, so they take him off the list. Hector gets some tutoring from Alex on how to face up to a bully. Just then Lenni and Jamal''s names and phone numbers appear on the police suspect list.', '1994-01-10', NULL, NULL, '2026-04-03T17:40:28Z', '2026-04-03T17:40:28Z');
