INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('c80ec819-764f-4ac4-a663-5afe74c54e95', 'fc120008-c5c4-47d7-a3a9-91a401394c41', 19, 'The Talent Show', 'Convinced that he doesn''t have any talent to offer for the upcoming school talent show, Brother is recruited to be the talent scout. Guided by Teacher Bob''s advice that everyone has talent, Brother helps the other cubs discover their own special talents. In so doing, Brother discovers he also has a talent just as Teacher Bob suspected--a talent for finding talent.', '2003-01-30', NULL, NULL, '2026-04-03T17:40:21Z', '2026-04-03T17:40:21Z');
