INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('c81fd599-6567-4858-bd31-e37bc5b7d05e', 'f4c40307-9b5e-4263-a4e0-dfa138131e7f', 58, 'Elmo Visits the Doctor', 'Join Elmo on his first trip to the doctor’s office! Elmo and his Sesame Street friends learn how going to the doctor can help an earache, a fever, and a stuffy nose feel better. Loaded with clever songs, brand new animation, lighthearted lyrics, and a never-before-seen Elmo’s World that explores being a doctor, this fun-filled video will help preschoolers learn that going to the doctor can be a prescription for fun! DVD bonus feature: Kid Friendly Instant Play Elmo Doctor Game!', NULL, NULL, NULL, '2026-04-03T17:36:27Z', '2026-04-03T17:36:27Z');
