INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('c8db1c2e-f5f5-4b90-a791-0b6ca8deb297', '98d80972-e53a-43dd-a03a-7703465e6f87', 6, 'Man. Make. Fire.', 'Go cruising with the Pawn Stars when Rick and the Old Man eye a 1949 Hudson Commodore. A premium luxury ride of the post-war era, will the guys add this classic car to their collection, or put the brakes on negotiations? Then, when a guy brings in a 2,000 year-old fire starter, the guys challenge Chumlee to create fire the old fashion way. And later, Rick is blown back to the ice age when he''s presented with a fossilized mastodon tusk, but can he sink his teeth into the deal before Chumlee burns down the shop?', '2012-11-13', 21, NULL, '2026-04-03T16:34:18Z', '2026-04-03T16:34:18Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('c8dbcf54-c29c-4312-a542-807c74f2cc22', '9d74600d-7222-47c1-bd1b-635f5b41b7d1', 6, 'Space Case', 'Is there life on other planets and stars? LaVar sends a message to aliens who might be watching and a radio telescope in Puerto Rico is profiled. Today''s featured story is about a being from outer space who visits Earth.', '1986-06-30', 30, NULL, '2026-04-03T17:36:15Z', '2026-04-03T17:36:15Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('c8e0d800-c2ea-4b7e-8a2a-89aa4f8c62bf', '0ebba123-871d-4d2b-a054-eb85d2ad9450', 46, 'Merry Larry and the True Light of Christmas', 'Bob and Larry are going all out to make it the best Christmas ever at the Spring Valley Mall. With music, decorations and a light show like no other, it''s an all-out spectacle to outshine the competition! But a little girl with a big heart changes everything when she shows them all what Christmas is really about.', '2013-10-22', 30, '/oqxKFnbSRF18nqfyGkqjBXBZS3Q.jpg', '2026-04-03T17:39:39Z', '2026-04-03T17:39:39Z');
