INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('c8e67e3f-1c13-4e41-af52-2d3658edb8af', 'b6c01284-0ce9-4210-b2a6-29bd5fae150b', 1, 'A Victim of Gravity', 'The Tokens harmonize Newton''s theory that gravity keeps things down.', '1978-09-16', 3, '/1uMQQQHCTHrf5RflNZkRfMREh03.jpg', '2026-04-03T17:13:56Z', '2026-04-03T17:13:56Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('c8ed8c70-7fe5-4324-b06b-ba3a0b80a6aa', 'e03d79bd-e01f-4414-b0b3-f3b5f26e97f4', 11, 'Taking Back the House', 'After years of being at their kids'' beck-and-call and never having time for themselves, Frankie and Mike decide to take charge of their lives and regain control over the Heck household. But Axl, Sue and Brick don''t plan on going down without a fight.', '2011-01-05', 22, '/s9TZHLaoNmfuty6R74Cb1kE24qw.jpg', '2026-04-03T15:40:29Z', '2026-04-03T15:40:29Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('c8f4113f-d946-4c97-860f-0792cdc4122e', '4d2cac0f-38fd-438b-8afa-acf43952e535', 145, 'Episode 145', 'For younger viewers. Introduced by Christopher Trace. Including More About Brownies: 2 and an excerpt from the film The Boy Who Stole a Million with a visit from Maurice Reyna, the young boy who plays the title role (shown by courtesy of British Lion/Bryanston).', '1961-07-31', NULL, NULL, '2026-04-03T17:21:47Z', '2026-04-03T17:21:47Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('c8f99ad9-0424-435d-80bb-7d1d2f697d6c', 'e3a28669-91b5-45f7-bb73-5006acc084e8', 22, 'Who''s the Mummy?', 'Shaun finds himself out of his depth when newly hatched chicks believe he''s their mummy, aw.', '2007-09-03', 7, '/6XGYXwAjhs3E2Mrvm0bYRenpggR.jpg', '2026-04-03T17:39:31Z', '2026-04-03T17:39:31Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('c8fb2d42-a65c-4691-8381-1ab5df58022b', '0b9d7ae7-218e-45a0-8c3a-e69912f5a6ed', 9, 'Franklin and the Fortune Teller', 'Beaver tells Franklin that he will have a bad day, so Franklin becomes cautious the following day and ends up missing out on a lot of great stuff.', '1999-11-08', 12, NULL, '2026-04-03T17:40:15Z', '2026-04-03T17:40:15Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('c907aa96-523a-4f3e-9bfd-d20f05aa7f44', '3982796b-5451-4100-9042-46bedf6a20a5', 16, 'Pingu at the Fairground', 'Pingu, Pinga, Mother and Father go to the funfair. They pass some balloons but don’t buy one. They come to a barrel organ, Pingu gives the player some money and he plays a tune. Pingu and Pinga rush on and stop at a candyfloss seller, and they both have some. At the “hit the tins” stall Pingu has a go, gets all the tins down in his three throws, and receives a lollipop as a prize. Pinga also has a go, but she throws before the stallholder has completely finished putting back the tins. The ball misses, bounces off the backboard onto the stallholders head, and then into the tins, knocking them all down. The stallholder is not very happy about this, talks angrily to her and doesn''t give her a prize. They move quickly on. Both Pingu and Pinga then have an ice cream. At the sweet stall Father buys Mother a candy pendant that he puts round her neck, and Pingu and Pinga each have a twisty candy stick to eat. Pingu and Pinga have a ride on the roundabout. Pingu then rides on the swings, and Mother is concerned by how high he''s going. When he gets off he feels a bit poorly. On the way home, Pinga has some more candyfloss, but Pingu doesn’t want any. They each get a balloon, but Pingu misses the string when taking the balloon off the seller and the balloon floats away, so Pinga lets go of hers as well. Then they all go home.', '1993-07-13', 5, '/upUUzfjnsSSUwlfnqvhs0vijFSl.jpg', '2026-04-03T17:22:19Z', '2026-04-03T17:22:19Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('c908dea4-1b67-46c4-8034-bb8621077295', '83d1c2fb-7cd9-4977-9a5d-98d36cfb59d3', 3, 'Episode 572', '', NULL, NULL, NULL, '2026-04-03T17:36:37Z', '2026-04-03T17:36:37Z');
