INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('c92ccd67-a528-42ba-bf37-48db4bbd7d26', 'd405f973-4c7e-4cb6-b7c0-d09a884c9b35', 14, 'Burlesque Is More', 'Sonja hosts a burlesque-themed party and puts on a show for her guests. Elsewhere, Jill visits her daughter at college; LuAnn and Jill hear LuAnn''s new single at the recording studio; and Simon confronts Jill about her cyber-bullying accusations.', '2011-07-07', 42, '/zF32P4qs4HMnPiiPnU1umrc9c7O.jpg', '2026-04-03T16:35:22Z', '2026-04-03T16:35:22Z');
