INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('c94677e7-f944-49f2-b0fb-d8ebe5221ace', '740a96a0-a075-4be2-be92-a178d0939384', 23, 'The Happy To Be Me Club', 'Big Bird feels bad about himself after being teased, but Abby reminds him that he is special.', '2018-04-21', NULL, '/u2l5pGk9Bs0kIRqkVbXosZXYSR3.jpg', '2026-04-03T17:36:49Z', '2026-04-03T17:36:49Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('c947b30f-ee93-4dc7-9bf2-f95753406edb', '4f18ac4c-8757-456c-a49a-224f00e6a9f7', 16, 'Elmo Steps In for Super Grover', 'Chris welcomes the viewer and meets up with Elmo, whose toy airplane is stuck in the tree. He suggests using a ladder, when all of a sudden, Super Chicken and his assistant, Robin, fall out of the sky. The duo begins to formulate a plan when Super Grover crash lands to save the day!', '2008-10-08', NULL, '/xN3nlCCIjRCRzbvvuJUsckIO4bi.jpg', '2026-04-03T17:36:45Z', '2026-04-03T17:36:45Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('c948e782-e715-4125-9370-b92699e4475e', '40700e8a-1dce-4895-bede-522a13a8bcad', 1, 'Green Creatures', 'Zoboo realizes that plants and trees are as alive as all the creatures he meets in Animal Junction. The Kratt Brothers teach the lemur that plants grow well if they get good soil, lots of sunlight and enough water. And there are plenty of creatures willing to help plants flourish, including Toothbrush the elephant, Popcorn the binturong and a whole family of sloths. When Martin and Chris follow Popcorn to India, they visit a 2,000-year old fortress, where green creatures like vines and plants are taking over the site.', '2000-10-03', 27, NULL, '2026-04-03T17:10:55Z', '2026-04-03T17:10:55Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('c94abe07-883c-4f86-83e7-d7cc6ca6c998', '4fe93658-c463-4329-8e64-9d523869c2cb', 16, 'Packing Heat', 'Take a ride with the Pawn Stars as they check out a 1962 mobster-style Cadillac Fleetwood limousine. Will the guys make an offer the seller can''t refuse or will the deal become too much of a stretch? Then, Rick and Chumlee are presented with a collection of 1990s Atlanta Braves championship World Series rings. Will Rick step up to the plate and take negotiations into extra innings or will he strike out looking? And later, a man walks into the shop with two vintage pistol lighters. Will Corey pull the trigger to fire up a deal or is this seller just blowing smoke?', '2010-12-13', 21, '/iXBDwKguI3lc0pRzzpD8oM0y8ty.jpg', '2026-04-03T16:34:16Z', '2026-04-03T16:34:16Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('c96fa457-5ebe-4ab9-b957-00a7c282c314', '54c29014-2dbd-49ff-a23f-cf4c546e0b3a', 12, 'Requiem for a Poodle', 'Sonja reaches out to a spiritual healer. Meanwhile, Kristen auditions for a workout video; Aviva''s father returns with a surprise; and the ladies assemble for a memorial for Sonja''s dog.', '2014-05-27', 60, NULL, '2026-04-03T16:35:23Z', '2026-04-03T16:35:23Z');
