INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('c9b6d739-17e9-4eaa-84dc-928b8f7f9671', 'f8b69754-3e41-45e5-832a-64d9c2809ad7', 10, 'Cookie', 'When a superstar decides to sing at the school, the janitor has too many jobs to handle. Bernard helps him out, with bad consequences as well as Mr. Steel rocking his way to love.', '2005-03-10', 15, NULL, '2026-04-03T17:20:06Z', '2026-04-03T17:20:06Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('c9b85a40-942a-4055-b7a4-6985b142b7ed', '095258d0-d8db-4096-8ac7-6a42cd4cbdcf', 4, 'The Grapes Of Generosity', 'Gobo finds the legendary "Grapes of Generosity", mystical fruits which are rumored to compel anyone who eats them to share them with others. However, when Gobo brings them back, he ends up eating them and keeping them all to himself. Before long, Gobo becomes weightless, and tries to hide it from everyone else. But when he hears that Red climbed to the very top of the Great Hall, it''s up to him to get Red down safely, and finally admit to everyone that his own problem was caused by being greedy.', '1985-01-21', 24, '/h2jl5Lwei8vKIb1AKgvxff1M1eX.jpg', '2026-04-03T17:35:00Z', '2026-04-03T17:35:00Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('c9b8ee92-b1df-4b6e-94d2-3c48283ea736', 'bbfee3b4-9c95-48a6-beaa-791fa08b1f43', 5, 'Episode 5', 'Meet the bird with a six-foot wing span that can soar to an incredible 200 feet before swooping on its prey at 45 miles-an-hour: Heidithe white bellied sea eagle.', '1983-09-26', NULL, NULL, '2026-04-03T17:21:56Z', '2026-04-03T17:21:56Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('c9c9d3d7-6068-4fd8-a19b-a9e57cd67df7', 'c373abed-50ef-417e-9f34-4e9050611a1b', 11, 'Dirty Dancing in Mexico', 'While still in Puerto Vallarta, Vicki, Lydia and Tamra continue their night away partying — while Heather and Gretchen continue to sit back in the limo. Gretchen tells Vicki how much she was annoyed by her antics but Tamra shocks the ladies when she tells the specifics of her past to Gretchen. Back at the resort, Mexican strippers arrive to spice up the night but Lydia is a bit nervous about the whole situation. Alexis, home in Orange County, asks Jim for an item that he is unwilling to purchase.', '2013-06-10', 44, '/6oPwS7xjPpGKVah7rInJMTJm1zc.jpg', '2026-04-03T16:35:32Z', '2026-04-03T16:35:32Z');
