INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('c9d3089c-d7a0-493c-b65f-e85c1091a455', '68138de2-0900-460a-b58e-480688f1e081', 6, 'You Learn Something New Every Day', 'Today, everybody wants time with Bear, and he gets the big idea to make a schedule that will accommodate everyone''s wishes. Everyone''s happy with this arrangement except for Treelo, who''s having a hard time waiting for sunset time, his scheduled time with Bear. He even goes as far as to change the clock to make his time come faster! Eventually, Treelo sees the sun - Bear''s good friend, Ray V set...right at the end of the day, at the right time.', NULL, 25, NULL, '2026-04-03T17:35:31Z', '2026-04-03T17:35:31Z');
