INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('ca0a594a-c870-485f-b3ea-53a5b6d86d53', '23c93536-610c-41c5-ac6b-a6b243423258', 17, 'All Bark, No Bite', 'Gizelle honors her father, Ashley gives a major life update and Dr. Wendy goes to the White House. Karen''s latest court date looms as she questions her friendships. Stacey''s charity event unravels in an unexpected fashion.', '2025-02-02', 55, NULL, '2026-04-03T16:35:41Z', '2026-04-03T16:35:41Z');
