INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('ca18b1f4-67ea-491f-b257-e98ac0698b7d', '87f84063-82b3-45a4-936c-3759e5d91ce3', 12, 'A House Divided', 'Separated from the church, Heather meets with her estranged sister to make amends. Whitney feels blindsided when Mary''s late night gifting results in a renewed friendship with Lisa. And when the group gathers to hash out their grievances before heading home, a heated argument divides the ladies, leaving two behind in Vail.', '2021-12-05', 44, '/oLuYhtu8aw5gYnvEHQoYV32AsCZ.jpg', '2026-04-03T16:35:44Z', '2026-04-03T16:35:44Z');
