INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('ca5359e8-80ca-4001-b9f2-f1d0909b2677', 'bbfee3b4-9c95-48a6-beaa-791fa08b1f43', 65, 'Episode 65', 'Resistance

Secret agents'' equipment, hidden message compartments and two dolls made in the notorious Revensbruck concentration camp by Second World War heroine Odette Hallowes , are just a few of the items in a major exhibition that opens shortly at the Imperial War Museum. Janet tells the story of the Resistance-the bravery of thousands of ordinary men and women during the Nazi occupation of Europe.', '1984-04-30', NULL, NULL, '2026-04-03T17:21:56Z', '2026-04-03T17:21:56Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('ca535ae7-0318-4bfe-ba30-aee2e8634156', 'a9657e86-4135-49ce-b1f9-c295113077e1', 25, 'All Together Now', 'The friends go to the Dragon Land Carnival, but when Emmy and Enrique go off to play together, Max feels left out. However, Emmy and Enrique don''t notice it.', '2005-03-16', 30, NULL, '2026-04-03T15:26:04Z', '2026-04-03T15:26:04Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('ca56ec74-50f1-4b1b-bb1b-40fc8fc8cb5e', '4f18ac4c-8757-456c-a49a-224f00e6a9f7', 3, 'Sock Chaos at the Laundromat', 'At the new Sesame Street laundromat, Chris welcomes the viewer as he does his laundry. He says he loves the noises the washing machines make (singing a variation of "The Wheels on the Bus"), while an Anything Muppet lady disagrees with him. He folds his clothes, then notices he''s got one missing sock (all the rest of his socks are in pairs). He wonders where his sock went, when Abby Cadabby poofs into view. He shows her the one sock he has which is missing its match, and she proceeds to show him the trick she was going to show Elmo: her "Two Trick," which involves turning one thing into two.', '2008-08-13', NULL, '/tXLeL5wFZgMnYxCwnrc8DcYkyjb.jpg', '2026-04-03T17:36:45Z', '2026-04-03T17:36:45Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('ca5ce137-0276-4f04-9528-c50fd3be7b29', '5ee9d1ca-b0a3-4dfe-bb10-1f61014f25a5', 4, 'Episode 4', '', '1993-01-29', 25, NULL, '2026-04-03T17:21:16Z', '2026-04-03T17:21:16Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('ca63419e-e27c-4927-affc-99e023e16534', '0987f081-b3b7-4e3c-abb7-795e56c279d5', 11, 'Life Skills', 'Axl feels embarrassed when he and Sue are asked to work on a school project together; Brick''s school therapist (Dave Foley) tries to help him make friends.', '2013-01-09', 22, '/tPjoDyRDupFd98tsgYPmF3CjrdQ.jpg', '2026-04-03T15:40:30Z', '2026-04-03T15:40:30Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('ca6f295c-5390-49a6-9fbb-102b39f6b36a', 'e6ea1431-9e67-4637-83ae-a11073e8c7e0', 16, 'Hearing Is Believing', 'The ladies shop for diamonds in support of Camille''s cancer charity. Meanwhile, Lisa Vanderpump rallies her pals for a march; trust issues surround Lisa Rinna and Yolanda; and Erika''s private jet is used for a trip to New York for Yolanda''s Lyme Gala.', '2016-03-15', 43, '/leXBnppdUURmb1hxfDclhmtAnVH.jpg', '2026-04-03T16:34:56Z', '2026-04-03T16:34:56Z');
