INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('ca81576e-96e0-4b7c-8d53-ccb569adf876', '119c16d5-1047-45ec-8242-c72a8eed423b', 15, 'Arthur''s New Puppy', 'Arthur has a new puppy is exactly what he wanted. But the only problem is that he destroys everything in sight, so can Arthur teach Pal to behave, before his parents do something with Pal because of all the disasters he is causing.', '1996-10-16', 13, '/z1xN87QNVXNt778gUzJbn5P7nDH.jpg', '2026-04-03T17:37:55Z', '2026-04-03T17:37:55Z');
