INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('ca9eb9a3-5169-4ad2-b974-dfcca254569e', 'a1b69730-d225-48f2-a7e7-1d314cf3b349', 39, 'Episode 39', 'with Valerie Singleton, John Noakes, Peter Purves', '1969-02-06', NULL, NULL, '2026-04-03T17:21:49Z', '2026-04-03T17:21:49Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('caa485f7-2855-4bd3-8e1f-1ebe13f3bda8', '095258d0-d8db-4096-8ac7-6a42cd4cbdcf', 15, 'Born To Wander', 'The Storyteller''s having a story-telling session in Gobo''s room, so Gobo decides that he wants to hear about Uncle Matt''s first big journey. We see a flashback of little Matt- who''s dressed like Gobo is now-with his Uncle Gobo, who thinks that his nephew Matt is annoying and clueless. Back then, Fraggles either ate mushrooms or Doozer constructions, but when the mushrooms run out, Uncle Gobo and Matt try to find some food. However, Matt causes a rock quake, and breaks Uncle Gobo''s leg. So Matt goes off by himself to find food, and as he''s wandering, a rock slide occurs, and when it''s over, Matt finds a hole out into the Gorg''s Garden. He goes out to explore, scares Ma and Pa Gorg, and brings back to the Rock a radish, which Matt thinks is a shiny red boulder, thus giving the Fraggles a new food source.', '1985-04-08', 24, '/lHpqAvGppi5xO2t8iLwxIvWEgGL.jpg', '2026-04-03T17:35:00Z', '2026-04-03T17:35:00Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('caa6ceeb-a1d1-4282-9196-e10459a6786e', '70d9e397-6813-4785-887d-27d034928bae', 18, 'Pingu has a Fishing Competition', 'Pingu, Pingo and Pongi decide to have a fishing competition. When they arrive where they’re gong to fish they first have to cut holes in the ice. Pingu and Pingo do theirs quickly and start fishing, Pongi struggles to get the saw into the ice. Robby then pops up out of Pingu’s hole, and they all have a laugh at Pongi’s efforts. Robby then helps by cutting out the hole from underneath. Pongi then breaks his rod and has to repair it. Once they’ve all managed to get fishing nothing very much happens for a while and they have difficult in staying awake. Then a fish jumps out of Pongi’s hole and drops back into the water. Pingu tells Pongi that he wants to swap holes with him, which Pongi does reluctantly. After a while another fish jumps, this time from Pingu’s original hole. Pingu swaps with Pongi again, and manages to catch a small fish that he shows off to the others. Then Pongi gets a bite, and it takes all three of them working together to drag the huge fish out of the water. On the way home Pingu and Pingo push the large fish, with Pongi on top, up an incline and pause for breath. They start thinking about the feast they’re going to have on the huge fish. Pongi sees this and slides off down the slope on the other side, and away, much to Pingu and Pingo’s consternation.', '1996-07-11', 5, '/2LdPJtt9XZ0TDi4y3uOGuS7E1ed.jpg', '2026-04-03T17:22:19Z', '2026-04-03T17:22:19Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('caa9e399-9d68-477c-93e4-6e4fb077f256', 'f29f456f-8e38-49af-8808-7943977100ec', 1, 'Buster''s Second Chance', 'After Brain wins a science fair, Buster begins to wonder how different his life would be if he was smarter.', '2016-10-10', 13, NULL, '2026-04-03T17:38:02Z', '2026-04-03T17:38:02Z');
