INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('cb0afdd5-fc23-4a68-b399-a8759bf1d15e', '8bae6aa3-4b55-4fa6-bc15-8f4317bd1f13', 51, 'Telecan Crisis Pt 1', 'The bulb burns out in Picture-Picture, so Rogers gets a new bulb at Negri''s Music Shop. In the Neighborhood of Make-Believe, the telecan kiosk by the Tree begins to bob up and down uncontrollably.', '1972-05-01', NULL, NULL, '2026-04-03T17:35:40Z', '2026-04-03T17:35:40Z');
