INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('cb244e18-b6b4-4eec-9de9-dead1a4ff709', '1a534647-384b-4c00-bb6c-a3371ad962eb', 32, 'Penny for your Pawn', 'Test your strength with the Pawn Stars when a 1930s Gottlieb grip tester pulls up to the shop. Will Rick muscle in on the deal for this vintage game or will it not work out? Then, Rick gets hung up on a limited edition piece of abstract art by Hollywood actor, Anthony Quinn. Will he be able to sculpt a concrete deal or will the seller stonewall him? And later, Chum offers to help promote the shop by trying to make images of the Old Man go viral. Will his idea break the internet or will he end up crashing the whole system?', '2015-05-28', 21, '/6KbQSEaqFg3wsiCYiO2JuYi4JAD.jpg', '2026-04-03T16:34:19Z', '2026-04-03T16:34:19Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('cb266f29-c50c-47b1-968f-590f32d102be', 'f5266c49-eb29-4594-b5d9-f927edfee336', 27, 'Save the Dump', 'When the prospect of the Farmer''s new golf course ruining their dump begins to become a reality, Shaun and the Flock have to resort to canny ways to save their prized resources.', '2014-09-25', NULL, '/r0XWuaz6stYoqd5Ija90X5MXJzu.jpg', '2026-04-03T17:39:32Z', '2026-04-03T17:39:32Z');
