INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('cb3650ed-7614-4033-aff9-4946b4910746', 'f829d1fb-64ea-430f-8e0e-b3345653a542', 5, 'River of the Dammed', 'Steve is the special guest of the Belize Zoo as they celebrate their 20th anniversary. He also travels up the Macal River to observe a controversial dam project and tangles with a highly venomous fer-de-lance snake while searching for Morelet crocodiles.', '2003-06-13', 44, NULL, '2026-04-03T17:39:12Z', '2026-04-03T17:39:12Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('cb3c0440-73f5-4e79-aebb-4a2682c47510', '6c1ec19f-74df-4f35-9a61-17b98175d826', 11, 'Kiss and Tell All', 'Lisa invites Dorit and the others on a glamorous Roman getaway. Denise tries to make nice with Erika, but gets an ice-cold shoulder instead. Garcelle digs into Sutton’s past, while Brandi drops a bomb on Kyle and Teddi which threatens to turn their dream vacation into a nightmare.', '2020-07-22', 43, '/392Xdf52nxD8x2xFLasrbDwpuXf.jpg', '2026-04-03T16:34:58Z', '2026-04-03T16:34:58Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('cb3e0a5d-6b2f-41aa-9f6b-f4dfea2797d0', '34674c90-410e-427c-be4d-2a6f6f865a80', 16, 'Love Me Spender', 'Rock out with the Pawn Stars when an Elvis Presley contract gyrates into the shop. Signed before The King got famous, will the guys try to buy this piece of music history, or will they send the seller to Heartbreak Hotel? Then, Chum and Corey look down the barrel of a rare Winchester rifle. Made for the popular 1800''s sport of target shooting, can the guys score a bulls eye with this deal? And later, a seller brings in a set of buttons that belonged to the Queen of France, Marie Antoinette. Will Rick be able negotiate without losing his head?', '2012-06-25', 21, NULL, '2026-04-03T16:34:17Z', '2026-04-03T16:34:17Z');
