INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('cb7a5396-b289-4a83-a0f5-7bc348818d38', 'a61eda16-b572-4c5b-ba55-57df932417ec', 13, 'Boober Gorg', 'After being hit on the head by an exploding radish, Boober gets amnesia and thinks he''s a Gorg. When he tells Ma and Pa Gorg, they believe him, because they think a sorceror has changed Junior, who is missing, into a Fraggle.', '1986-03-31', 24, '/6HaCY4wcWvHWphXjLAxQb5X5Ir8.jpg', '2026-04-03T17:35:01Z', '2026-04-03T17:35:01Z');
