INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('cbae4dfd-4d2b-4852-a472-cc3daf83ec43', '65524b14-e29e-4b04-81d3-fbebe525e9ec', 22, 'Franklin''s Candy Caper', 'When Franklin puts a strange penny in Mr. Mole''s candy machine, all of the candy comes out.', '2004-07-25', 12, NULL, '2026-04-03T17:40:16Z', '2026-04-03T17:40:16Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('cbaf7a50-c88f-436a-b9c7-83712db6682d', 'ea1650c2-e4f1-46c7-93ba-74b5d45d08e5', 11, 'Contract Player', 'It''s time for Kim to start rehearsing for her upcoming tour with Kandi, but she''s more interested in get-skinny-quick treatments than learning the choreography for her show. Sheree receives some good news about her talent agency audition and enlists Kandi''s help to prepare for her role in a local play. Tension lingers from NeNe and Peter''s blow-up phone fight. The ladies think that Cynthia''s priorities are a bit off, but Cynthia has a plan to smooth things over with NeNe. Meanwhile, Dwight tells Phaedra what everyone has been saying about her mysterious pregnancy. Phaedra is not happy and intends to confront the ladies about the gossip.', '2010-12-12', 43, '/pUmFPTx4X3Iodyw6k6IrYKaWFdT.jpg', '2026-04-03T16:34:45Z', '2026-04-03T16:34:45Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('cbb43f3d-992b-48d2-81fb-a57f6ed431ae', 'bf874be3-7e2f-4a0e-b205-c76ac1ad69fc', 41, 'Inside Looks (on The Keys)', 'Inside look from the season 3 episode "The Keys."', NULL, 6, NULL, '2026-04-03T16:34:09Z', '2026-04-03T16:34:09Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('cbbd7f80-63aa-4452-bb0f-06cb1fe78c7d', 'e4023da2-33d7-4a2b-a04a-ca449bd23935', 2, 'The Loneliest Locker', 'Mike and Frankie search for second jobs in order to send Sue to a good college, Sue and Brad produce a play for school, Brick finds some of his old "lost" toys, and Axl raids the house to furnish his new home.', '2014-10-01', 22, '/puyR1ayxpRBUt5yziZEJDiIoYD2.jpg', '2026-04-03T15:40:30Z', '2026-04-03T15:40:30Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('cbc1618c-f41a-4c22-a9d1-8f1fef66fe49', '34674c90-410e-427c-be4d-2a6f6f865a80', 7, 'Bossy Pants', 'The Pawn Stars are flying high when a panel off the world''s fastest airplane, the SR-71 Blackbird, soars by the shop. A supersonic spy jet from the Cold War, will the guys have the intelligence to make a deal? Then, a solid bronze 16th century cannon fires into the shop. Specially made for use on ships, can the guys battle on the high seas for this antique weapon or will the deal sink their fortunes? And later, a customer brings in a vintage pair of gigantic Levis jeans. Used as a display in stores, will Rick and Chum wear the pants in this deal or will they need to button up their skills?', '2012-05-21', 21, NULL, '2026-04-03T16:34:17Z', '2026-04-03T16:34:17Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('cbc83be9-f056-4368-9c01-ed27ff7a3600', '6ef86c27-33e7-47e5-a053-483059dfd16d', 37, 'Episode 37', '', '1982-01-21', NULL, NULL, '2026-04-03T17:21:55Z', '2026-04-03T17:21:55Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('cbc96dc5-6691-4377-ba84-3bf08a000ca3', '4d2cac0f-38fd-438b-8afa-acf43952e535', 377, 'Episode 377', 'with Christopher Trace and Valerie Singleton.', '1965-07-15', NULL, NULL, '2026-04-03T17:21:47Z', '2026-04-03T17:21:47Z');
