INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('cbdd0745-d164-482b-b642-bdc9c1a5c8ff', '6e314631-d72b-4ebd-bf39-d123d19108fc', 24, 'The House at Pooh Corner', '', NULL, NULL, NULL, '2026-04-03T17:20:13Z', '2026-04-03T17:20:13Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('cbe5865b-ce0e-4408-a6a3-ba626a7062e6', 'e03d79bd-e01f-4414-b0b3-f3b5f26e97f4', 6, 'Halloween', 'Frankie is excited over being invited to an adult neighborhood Halloween party. But will she be able to get Mike to dress up in a costume, or will he have his own idea of fun? Meanwhile, a melancholy Sue''s spirits are lifted when she discovers that Reverend TimTom is back in town and hosting a Halloween church event; things don''t go quite as planned for Axl, his friends or their dates as they head out to an exclusive haunted house party; and Brick chooses a unique Halloween costume that is not easily defined.', '2010-10-27', 22, '/tCqtQiIgWPLNz5AvlPezn4JOcep.jpg', '2026-04-03T15:40:29Z', '2026-04-03T15:40:29Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('cbe9e0ae-7899-4eeb-bcc9-6486653ed40a', '8c3cfac1-d882-4904-b38c-d1981628d00e', 9, 'Episode 9', 'with Lesley Judd, Simon Groom, Christopher Wenner and Clare Francis who returns to the studio with an exciting account of her 27,000-mile sail around the world on ADC Accutrac.', '1978-10-09', NULL, NULL, '2026-04-03T17:21:54Z', '2026-04-03T17:21:54Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('cbf6c515-063d-4658-b526-5faca8987136', '97a3d1f5-a8f1-47cd-8122-2e74a092836d', 4, 'Am I Blue? (4)', 'Gaby writes an apology letter to her parents while the team learns of the real culprits identities. Gaby is cleared from the suspect list and to show their forgiveness, her parents and the producer of Galaxy Girl surprise Gaby with a visit from the actress who plays Galaxy Girl.', '1993-09-26', NULL, NULL, '2026-04-03T17:40:28Z', '2026-04-03T17:40:28Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('cbf9cce9-9b57-4d3c-9476-dfb0b7259d6c', '740a96a0-a075-4be2-be92-a178d0939384', 11, 'Kitty Kindness', 'When a lost kitten gets discovered on Sesame Street, Chris and Elmo put up signs to try and find its owner; Grover and Cookie Monster help look after the kitten and learn how to take care of it.', '2018-01-27', NULL, '/xOzfF2zyBC2nZ4zyFK95TkPJKEU.jpg', '2026-04-03T17:36:49Z', '2026-04-03T17:36:49Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('cbfa6d39-bf14-43ba-bdc0-9971389c5f8c', '97a3d1f5-a8f1-47cd-8122-2e74a092836d', 25, 'What''s Up With Alex? (1)', 'Jamal is happy when Casey goes back home. Tina finds her school ID in a trash can and realizes the last place she had it was in her jacket - in her locker. Jamal and Tina find out that her locker was broke into and her expensive sheepskin jacket has been stolen. Other thefts occur at Hurston. The team (and Ghostwriter) learn that Maria''s camera was stolen, and Delilah''s tape recorder as well. With Ghostwriter''s help, they discover that a fence named Big Ralph is selling the stolen items and on their stakeout, they see Delilah buying her tape recorder back. Hector goes to look at the stuff but Ralph catches him. Meanwhile, Alex is chosen to be an alternate on the Dragon''s basketball team but ends up taking Victor''s place when Victor gets mad at the captain (Kevin) and quits.  Alex hangs out with his teammates, Kevin and Spencer, and ends up coming home late and getting in trouble with his father.', '1994-04-10', NULL, NULL, '2026-04-03T17:40:28Z', '2026-04-03T17:40:28Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('cc00628b-68da-42a6-bc20-e0195d4ce715', 'e48599f8-66ff-4c0f-9274-65b9ae1cda9e', 36, 'Episode 36', 'Glen Nevis Splashdown!  John goes mattress racing in Scotland and joins the men of the Lochaber Mountain Rescue Team on their annual splash down the icy rapids of Glen Nevis.', '1977-01-17', NULL, NULL, '2026-04-03T17:21:53Z', '2026-04-03T17:21:53Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('cc06ee90-9d2f-4094-8685-415e8e9773cf', '1d556682-d9bb-47e1-993f-0b648a8daacd', 88, 'Episode 1273', '', '1979-03-28', NULL, NULL, '2026-04-03T17:36:33Z', '2026-04-03T17:36:33Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('cc07dbad-d4ee-4ac8-9763-5299ffba5399', '63f9bf6d-39b3-44f4-b885-a56807277a80', 7, 'Hey, Cinderella!', 'Cinderella lives with her wicked stepmother (as everyone who ever read the fairy tale knows), but what part of the story is never told is how Cinderella''s fairy godmother had help from monsters, a prince pretending to be a gardener, and none other than Kermit the Frog.', '1969-03-16', 26, '/mss7XqtaOnujxd1BwOsES5uKdsF.jpg', '2026-04-03T17:35:23Z', '2026-04-03T17:35:23Z');
