INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('cc1ca973-88de-43da-aa5f-c755eb74ab06', 'd2f2ce63-96af-4899-92a8-3da5ea3913ce', 13, 'Kicks Up a Storm', 'The Friz transforms the bus into a Weathermobile and -- in a wild ride through the skies -- Ralphie becomes the meteorological superhero of his dreams.', '1994-12-04', 26, '/skiHDl6d5jvuq3cX7kmYUdHIhkg.jpg', '2026-04-03T17:37:48Z', '2026-04-03T17:37:48Z');
