INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('cc284445-72a9-4dc9-97b5-dcd419548d08', '36ea3814-66b4-4986-b6ee-44559d3562c1', 19, 'Mexi-Loco', 'Phaedra feels that it''s time to question Apollo and Kenya. Gregg discloses an issue he has with Peter. Kenya wants to re-do NeNe''s pillow talk event with the hope that things will go smoother.', '2014-03-23', 43, NULL, '2026-04-03T16:34:46Z', '2026-04-03T16:34:46Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('cc322cac-a42a-4898-9da8-92697b5ede76', 'd3e13496-e3c8-4903-83b4-5a31fedee232', 11, 'The Great Divide', 'While on their way to the North Pole, Aang and his friends arrive at a giant canyon where two groups of refugees are bickering over who should get to go across.  Aang decides to walk across with the two groups to ensure they don’t fight one another.  However, he soon learns that the two tribes have been feuding for one hundred years and they both believe their actions are justified.  But when the predators inside the canyon start to come out, Aang is stuck trying to defend both tribes from each other and the vicious wildlife.', '2005-05-20', 25, '/rApMjdBNbwInH5zpqSquJ9Yi3hp.jpg', '2026-04-03T17:40:47Z', '2026-04-03T17:40:47Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('cc3ab5c7-eaed-4bcd-b127-820349048914', '5a4e38a1-8e54-4974-8097-d7a7b48630a2', 20, 'Episode 20', 'with Valerie Singleton, John Noakes, Peter Purves', '1970-11-24', NULL, NULL, '2026-04-03T17:21:50Z', '2026-04-03T17:21:50Z');
