INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('cc418915-f565-4437-8b3d-398d0fb7ebb6', '67e1143e-c43b-4f93-87d1-64e1bb6e199d', 23, 'A Big Surprise & Matilda Ramsay!', 'Lindsey and Radzi try their hand at indoor skydiving.', '2016-06-10', NULL, NULL, '2026-04-03T17:22:09Z', '2026-04-03T17:22:09Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('cc41b078-37dd-4787-9507-a7c2757c87c2', '1a534647-384b-4c00-bb6c-a3371ad962eb', 27, 'Rick''s Roulette', 'Head to Tinsel Town with the Pawn Stars as Rick auctions off some of the shop''s coolest finds. Will Rick have a blockbuster weekend or will he his trip be a big flop? Back in Vegas, Corey and Chum go off-road to check out an Ultra 4 Racecar. Will they cross the finish line with a deal or end up with wiping out? Then Rick witnesses one of the biggest collections of Mickey Mouse memorabilia in the world. Will Rick''s Disney dreams come true, or will the deal be a happily never after? And while Rick is in L.A., Chum thinks the shop should have its own auction. Will Chum create a bidding war or give away items for free?', '2015-05-14', 42, '/jvV1JUZpTkGdCvC4QBGhWgsNtls.jpg', '2026-04-03T16:34:19Z', '2026-04-03T16:34:19Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('cc420fbb-cadb-45d1-8aac-3ed742ef9fa3', 'bb919aec-0d5c-4c58-9a5a-fa2a0a5de2b6', 42, 'Episode 447', '', '1973-01-23', NULL, NULL, '2026-04-03T17:36:29Z', '2026-04-03T17:36:29Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('cc44992c-568b-4162-95db-f52ef8d75a3f', 'ea73e13c-6962-4804-8305-c303df65f89f', 49, 'A cake for Chef Brockett', 'Rogers has to keep secret the cake he is making for Chef Brockett''s birthday. In the Neighborhood of Make-Believe, Robert Troll, X, and Daniel discuss their gifts for Brockett.', '1969-04-17', NULL, NULL, '2026-04-03T17:35:38Z', '2026-04-03T17:35:38Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('cc467fc2-b33e-4fbb-a569-b318e398ae55', '3ee646e8-23ae-4dec-bbc6-c7e6a210d55b', 36, 'Telly loves Oscar', 'Holding a suitcase, Telly bangs on Oscar''s trash can to let Oscar know that he will be away visiting his cousin for. Once Telly leaves, Oscar gets a singing telegram delivered from a tap-dancing Anything Muppet (David Rudman).

Sponsors: H, O, 14', '1990-12-31', NULL, NULL, '2026-04-03T17:36:38Z', '2026-04-03T17:36:38Z');
