INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('cc4b20e9-ce47-4e46-94df-2fe3b28f1668', '1996ddd8-20c9-4a30-96be-2b87fab8d17c', 29, 'Over a Barrel (3)', 'Tina and Alex learn from Momo that someone substituted his boss''s barrel''s but he has no access to his files. They ask Ghostwriter for some help and learn who substituted the barrels. They go straight to Miller''s place and learn that he also sponsors a children''s program. They overhear him arguing over the phone  about the barrels and planing to destroy some invoices that prove he is responsible for the toxic waste. They head town to Momo''s place to get the invoices but someone has gotten to the invoices first. They realize that Miller is probably the thief but have no proof.', '1993-04-25', NULL, '/WMwH5HyZUL2gGq3j8thyDWa3sa.jpg', '2026-04-03T17:40:28Z', '2026-04-03T17:40:28Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('cc4f4a5a-6dc6-4c82-b6f0-ac8643a3d2cf', 'c7994637-b7c7-42c7-aaee-1bff4144fe23', 4, 'Hellevator', 'The women recover after a meltdown in Las Vegas, but Erika''s elevator callout of Sutton leaves everyone floored. Dorit and Garcelle want Kyle to put her cards on the table about her marriage.', '2023-11-15', NULL, '/z7GC3sT8CAw6iFcOMy2bEd0ZrjP.jpg', '2026-04-03T16:34:59Z', '2026-04-03T16:34:59Z');
