INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('ccf60eae-2dc7-4f7a-a25f-fd3f4ba94a6d', 'f4938e7d-11a8-4756-b405-98bedd7c9b28', 2, 'Pat and the Magpie Hen', 'Pat stops for a picnic lunch near Thompson Ground halfway through his round. He falls asleep in the warm sunshine. Some hens cause mischief, one takes Pat''s sandwiches and the other takes Pat''s keys! The hen surprisingly leaves Pat''s keys in a nest in a tree. Dorothy soon comes to see what the commotion is about. Pat and Dorothy then go to get a ladder and Pat climbs up the tree to find a magpie''s nest with some other missing things. Who has ever heard of a magpie hen?', '1981-09-23', 15, '/vDpTIz2cBkPgTMelNImha5gks0r.jpg', '2026-04-03T17:14:29Z', '2026-04-03T17:14:29Z');
