INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('cd4fd7d6-1db0-41b3-8bea-1b4f4bde1c03', '7b19039a-31ac-425c-8fb1-b51cf2447821', 3, 'The Splash Heard Round the OC', 'Shannon’s got a new house, boyfriend, body, and revamped food line to celebrate and is ready to show it all off at her housewarming party. Emily is hopeful that she can finally make peace with Shannon. Kelly and Gina question Elizabeth’s romantic relationship. Meanwhile, Gina confronts Braunwyn and Shannon about the comments they made about her new home.', '2020-10-21', 44, '/1Fb8EhQRJwme1HQR4PsJFDggvkO.jpg', '2026-04-03T16:35:34Z', '2026-04-03T16:35:34Z');
