INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('cd56598e-8e0e-4c05-9e55-73e0295fa740', '04207e76-d855-4f29-a066-1732feea34b5', 14, 'The Chanels of Venice', 'Teresa, Caroline and Jacqueline set sail on a cruise to Italy with their families, but the mix of three family generations can make for some rough waters. Back in Jersey and with the other wives away, Danielle slyly maneuvers onto enemy turf.', '2010-08-09', 43, '/3DOxUili6aNiBg0p8gZK77ZkZJM.jpg', '2026-04-03T16:35:15Z', '2026-04-03T16:35:15Z');
