INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('cd730829-ca4a-4362-ac37-80ec40cc176f', '78a02d50-e3dc-4549-844a-3cf357a32ef4', 11, 'Thelma and Louise Take Flint', 'Phaedra and Kenya rekindle their friendship as they travel to Flint, Michigan, to participate in Phaedra''s summer camp. Back in Atlanta, Cynthia makes herself at home at Kandi''s house. Bob gets another shot to try to win back Shereé, while Porsha starts seeing red flags in her relationship with Todd. After a cathartic and emotional camp experience, Phaedra brings everyone together to discuss a camping trip with all the ladies -- but concerns about Porsha''s past anger issues lead some of the women to question whether or not they should go on the trip.', '2017-01-22', 43, '/7sZpxbNdFoLxmCVoYRHshWdYLJp.jpg', '2026-04-03T16:34:47Z', '2026-04-03T16:34:47Z');
