INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('cdbd859f-54a8-48f0-8bc7-f75946946124', '73ae1459-ba91-4185-a9da-bf6f2844af49', 23, 'Reunion (2)', 'The ladies relive their trips to the Hamptons, Newport and Mexico, including all the drama in between; Ramona addresses Leah''s behavior, and tempers flare when she claims Leah ruined her birthday party with her risqué dance moves.', '2020-09-16', 60, '/yqtfW7UHfjGvEiuSVOn1OicYx8n.jpg', '2026-04-03T16:35:25Z', '2026-04-03T16:35:25Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('cdca5b59-3fa6-4cff-9410-bb63710dcce1', 'fe19a277-aed8-44df-a4ac-fc1c4e9941b4', 13, 'Catwalks & Cat Fights', 'After almost 2 years “She by Shereé” is about to debut, but big changes are on the horizon and serious trouble is brewing between the ladies. As Lisa prepares for a new future without Ed''s NFL paycheck, Kandi finally sees a breakthrough between AJ and her mother, and Shereé tries to keep it together before her clothes go down the catwalk. Meanwhile, it’s NeNe who is ready for a meltdown. After her return from meeting the man who claims to be her father, she butts heads with Gregg, battles with Kandi at Shereé’s show, and has a blowout fight with Kim. Will a glass of wine be able to undo the damage this time?', '2009-10-22', 43, NULL, '2026-04-03T16:34:45Z', '2026-04-03T16:34:45Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('cdd65b63-ecf5-4b98-8f21-da79574d0c00', '04fb713d-9c59-45f7-8de0-acd7582daa53', 10, 'From Turkey With Love', 'Jennifer departs for Turkey to celebrate her brother''s engagement; Danielle sends Margaret a text that could end their friendship; Dolores hosts a charity event. Melissa finds out how Joe feels about their daughter taking over the family business.', '2019-01-09', 43, '/9vF2Oo2drEKFOj7hAbFHeIDwu1R.jpg', '2026-04-03T16:35:17Z', '2026-04-03T16:35:17Z');
