INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('ce366715-f492-416f-850b-726d7710d404', 'f5c042dc-0657-42e8-a37d-247414140632', 8, 'Austin, We Have a Problem', 'In part two of the trip to Austin, D’Andra and Kary finally find common ground – even if it is on the water. Tiffany bonds with Stephanie and Kameron, while Brandi finds herself walking on eggshells around Tiffany and confronts her about feeling like she can’t be herself around her.', '2021-03-02', NULL, '/zv6Ro6tRWiYwR03KP88JwJJV5Vi.jpg', '2026-04-03T16:35:05Z', '2026-04-03T16:35:05Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('ce39350d-512c-456c-a952-97ec1ad906af', '1c0a48a4-4d1c-424b-b54f-265883e6b26e', 11, 'Make Ups, Slip Ups and Cover Ups', 'Sheree continues her healing journey through Algarve, Portugal, by taking the ladies to a few local experiences. Kenya seeks a different kind of healing following a freak accident. Drew finds herself battling friends and some serious allegations about her past when she accuses Kandi of telling a lie.', '2023-07-23', 44, '/9jO8scQ5De4jg5HCjbCq9SV8CMW.jpg', '2026-04-03T16:34:50Z', '2026-04-03T16:34:50Z');
