INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('ce88a099-e0c3-42bd-936a-bd1a10a4d653', 'd46f25ad-9612-4516-91df-d1ace11fec38', 1, 'New Studio, Epic World Record Battle and Racing Challenge', 'Joel, Abby, Shini and Henry reveal a brand new look for the Blue Peter studio, including new presenter Hacker T Dog!  Gladiator Steel joins us for a world record challenge, and Joel races a supercar!', '2025-09-05', 25, NULL, '2026-04-03T17:22:12Z', '2026-04-03T17:22:12Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('ce8e3d88-b1db-4790-b8bd-19eacf243b58', '9193e795-da7c-40ec-b68f-f63aa7d5174f', 243, 'Anatomy of a Scene: Planning a Royal Wedding', 'Likely on the Season 4 Blu-ray. Part of the Bonus Features on the Disc 1 on UHD sets', '2015-02-17', 23, NULL, '2026-04-03T15:40:35Z', '2026-04-03T15:40:35Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('ce90ad5c-2d47-4e8c-a4d3-9b87d7f255ed', 'bd5f5a3f-07fa-4689-b67b-02be5d65f1b2', 27, 'Postman Pat''s Ice''Capade', 'It is winter in Greendale and everything is turned to ice - including the engine on the Greendale Rocket.', '2006-03-17', 15, '/aZdubZbIBenyOL0DMWvoQnU3mDS.jpg', '2026-04-03T17:14:31Z', '2026-04-03T17:14:31Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('ce90af03-f692-4e71-880b-dda6a539e6d4', '871570b4-bf2f-4ba1-9940-65fb932cb009', 21, 'Secrets Revealed', 'The Georgia peaches continue to throw shade with never-before-seen footage from Season 8 including Porsha and Phaedra''s makeover of Kim, as well as juicy moments from Peter and Cynthia''s video-gate drama. Plus, more heated moments from Kenya and Kim''s epic showdown are unveiled.', '2016-04-10', 43, NULL, '2026-04-03T16:34:47Z', '2026-04-03T16:34:47Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('ce98d9f4-ca53-4755-8b78-22c9dcaf8cc5', 'de052e8e-7dbd-454a-a6d8-b9afba6e9bfa', 24, 'Games In The Snow', 'The Wombles have fun in the snow and, in the process, create a minor avalanche', '1973-06-27', NULL, '/23vchL2DS9i26man1lRLtI0V3x4.jpg', '2026-04-03T17:23:19Z', '2026-04-03T17:23:19Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('ce9cc6e4-56f4-4203-8eb5-660a7e113754', 'bf874be3-7e2f-4a0e-b205-c76ac1ad69fc', 115, 'Inside Looks (on The Caddy)', 'Inside look from the season 7 episode "The Caddy."', NULL, 22, NULL, '2026-04-03T16:34:09Z', '2026-04-03T16:34:09Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('ce9cd84d-e2c1-4af4-a817-94b747d55446', '1a534647-384b-4c00-bb6c-a3371ad962eb', 7, 'The Smoking Gun', 'Join the revolution with the Pawn Stars when a Brown Bess musket fires its way into the shop. Will Rick hit the target with a deal or will there be a misfire? Then, Rick hits the books when Thomas Jefferson''s personal copy of Jay''s Treaty marches in. Will this piece of United States'' history cause Rick to surrender or will he fight his way to a deal? Later on, Corey gets rocked when a smashed guitar from KISS front man Paul Stanley comes by. Will Corey rock n'' roll all night or will he end up getting played? And later, Rick tries to snap Chum out of it when he''s bored at work. Will it be a historic victory for Rick or will Chum revolt?', '2015-01-25', 42, '/tZ9v16XdnwoiQYFMQUiA5XuUPcN.jpg', '2026-04-03T16:34:19Z', '2026-04-03T16:34:19Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('cea0a0e5-08d4-4f20-a077-95634403e8d7', 'd920ebae-f00a-4e25-abfe-40492c74ded6', 10, 'Ship Happens', 'Rick heads to Boston to check out an iconic warship. Will he sign for the USS Constitution, or will this deal sink his battleship'' Meanwhile, Corey asks for Help! when a Paul McCartney signed guitar Wings into the shop. Can he Come Together with the seller, or will he Let It Be'' Then, when the guys get a look at a curious corkscrew collection, will it have them popping bottles, or spiraling out of control'' Finally, when Rick gets a lead on an Apple 1, he has to decide if he wants a byte.', '2020-02-03', 42, '/3JzcUrPpbjo4BHPLYvA2uXuqPDM.jpg', '2026-04-03T16:34:22Z', '2026-04-03T16:34:22Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('cea16b6c-1f95-4745-a26d-90f341d067ef', '1cafb2c3-bbcb-4172-b02d-441a5aaa155f', 7, 'You and I Together: A Visit with Koko the Gorilla', 'Rogers'' comforts a visit with Koko the Gorilla. No such warmth can be found in the Neighborhood of Make-Believe when a different gorilla visits. The lone exception is Lady Aberlin, who finds the gorilla tame.', '1998-08-21', NULL, NULL, '2026-04-03T17:35:48Z', '2026-04-03T17:35:48Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('cea1c5f7-fa1d-4350-b162-adcc949f579b', '228172b6-fed0-4226-acdf-820049d2c72e', 6, 'Different Wives and Rules', 'Utah has decriminalized polygamy, and Christine toys with the idea of moving back. Coronavirus cases are rising, and Arizona goes into lockdown. Janelle tells Kody to stop coming over, and the whole family grapples with how to handle it.', '2021-03-21', NULL, NULL, '2026-04-03T16:34:31Z', '2026-04-03T16:34:31Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('cea22869-f6c6-4e16-ac90-fabb4a70b162', '4900fc8d-5e7e-408e-972e-ce9269d203b3', 14, 'The Exorcism of Gina', 'Tensions continue to rise between Gina and Shannon. Heather decides to address her lingering issues with Shannon, but is met with fierce opposition. Emily plans to celebrate her marriage with Shane, while Gina calls in reinforcements to conquer her Cabo demons. And just as the women come together to support the launch of Gina’s business, Noella gets earth-shattering news.', '2022-03-23', 44, '/daBShyybBm6gZgNuSNx4zRDnZub.jpg', '2026-04-03T16:35:35Z', '2026-04-03T16:35:35Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('ceaba51a-2d59-4d53-b981-2fafc359890a', 'a1b69730-d225-48f2-a7e7-1d314cf3b349', 57, 'Episode 57', 'with Valerie Singleton, John Noakes, Peter Purves', '1969-04-10', NULL, NULL, '2026-04-03T17:21:49Z', '2026-04-03T17:21:49Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('cead179f-ddea-41f2-acae-a498951cfe22', '200eca8d-ccb8-4470-b0fa-868d95b41c33', 5, 'First of His Name', 'Cersei and Tywin plot the Crown''s next move. Dany discusses future plans. Jon Snow embarks on a new mission.', '2014-05-04', 54, '/bf0Z9votO2jqQLI0Y66TqfTjlyq.jpg', '2026-04-03T15:40:36Z', '2026-04-03T15:40:36Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('ceb0171b-bd1b-4bf9-b83b-2bff830b48f6', 'eae164b1-7fae-44ba-8ecb-7b089255345c', 1, 'Pilot', 'Bravo gives viewers a sneak peek of the upcoming series "The Real Housewives of New York City," an up close and personal look at this season''s Housewives and a preview of what''s to come.', '2008-01-22', 60, NULL, '2026-04-03T16:35:21Z', '2026-04-03T16:35:21Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('ceb2f98a-8fa6-4dff-8b2f-9475bd5d79a5', '9310a288-5af0-4746-a8d7-d7635ffb6beb', 7, 'Work', 'Mister Rogers arrives with a piece of string that came on a package. Using the loop, Mister Rogers shows a few games and tricks that can be played with such a string and then sings Did You Know.

After a phone call from Jane Henshaw, Mister Rogers visits her at the Neighborhood dairy farm where he learns about cows. He also sees how cows are milked and how the milk is bottled.', '1984-04-05', NULL, NULL, '2026-04-03T17:35:43Z', '2026-04-03T17:35:43Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('ceb4e292-7b32-460b-8915-a003e0d0e939', '6ef86c27-33e7-47e5-a053-483059dfd16d', 7, 'Episode 7', 'Christmas Stamps

This year''s Christmas stamps and official First Day Cover have been designed by "Blue Peter" viewers. A colossal 500 million have been printed and you can see them roll off the presses at the printers in today''s first public preview.', '1981-10-05', NULL, NULL, '2026-04-03T17:21:55Z', '2026-04-03T17:21:55Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('cebf4b73-55d7-47f9-9449-34cf6dd09649', '9193e795-da7c-40ec-b68f-f63aa7d5174f', 167, 'Histories & Lore: Highgarden', 'Randyll Tarly describes the battles, marriages, and alliances surrounding Highgarden, the seat of House Tyrell.', '2017-12-12', 4, '/1Kc8d2KtCmFzlgW87JnTOKfBPEB.jpg', '2026-04-03T15:40:35Z', '2026-04-03T15:40:35Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('cebfeb13-84f7-48c1-b25a-6fb4e59dbfa1', '5b2c9365-7bd9-4ca1-a3fb-15f1a024a56e', 9, 'The Lost Footage', 'Previously unseen footage from the sudsy, New York-based reality show is presented. Included: insight into Bethenny''s romantic life; drama at a Hamptons party; extended snippets of a catfight; and sparked rumors.', '2008-05-27', 60, '/fx9N8crM4D2jDc6FK2PmSitj4lr.jpg', '2026-04-03T16:35:21Z', '2026-04-03T16:35:21Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('cec5c275-7bcb-4578-91ea-b98dcf0661c2', 'acac417e-2aa3-42e7-9e08-ed0d6071a3ee', 9, 'Holidazed and Confused', 'Carole and Bethenny continue to hash out their issues during the murder mystery dinner party. Back in the city, Bethenny''s holiday party is interrupted by a surprise, which leads to hurt feelings. At Luann''s blood drive, Carole is upset when she finds out that Bethenny has been talking about her behind her back. Then, Ramona confronts Bethenny on an epic sidewalk phone call. In a shocking turn of events, Luann gets arrested over the holiday.', '2018-05-30', 60, '/gKfZhheAHDtBdQpgw192Fi5DBQ7.jpg', '2026-04-03T16:35:25Z', '2026-04-03T16:35:25Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('cecd9634-347e-45b4-9ef9-e02fec12bef1', 'e3a28669-91b5-45f7-bb73-5006acc084e8', 39, 'Save the Tree', 'It is a scorching hot day, and the Flock is desperate to cool down in the Sheep Dip. There''s only one thing in their way: the sun-bathing Farmer!', '2007-09-13', 7, '/5TBgpVdbDkCKyMfUvD7r4AnXJfX.jpg', '2026-04-03T17:39:31Z', '2026-04-03T17:39:31Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('cece976d-0233-418d-80df-d44070c72b74', 'b054aff3-548c-4f56-b372-b1ea26613abb', 12, 'Mister Rogers Talks About DAY CARE & NIGHT CARE', 'Mister Rogers arrives with the materials needed to make a latch-hook rug which he has borrowed from Chef Brockett. He demonstrates the latch hook before returning the supplies.

At Brockett''s Bakery, Chef Brockett has a display of various kinds of rugs which he and Mister Rogers look at in detail. Mr. McFeely stops by the bakery to pick up a delivery which needs to be taken to a local daycare provider.', '1983-04-25', NULL, NULL, '2026-04-03T17:35:43Z', '2026-04-03T17:35:43Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('ced04bbc-47fd-404e-93ad-77c5110fbcbd', '1c0a48a4-4d1c-424b-b54f-265883e6b26e', 3, 'A Star Is Re-Born', 'Drew receives an invitation to perform with friend and R&B artist Candiace Dillard-Bassett, sparking hopes of relaunching her stalled music career. Kandi reveals to Monyetta and Don Juan that Momma Joyce''s harsh comments at BravoCon have upset Todd and their kids. Marlo is triggered when Drew brings up a recent incident at Kandi''s restaurant, which causes her to spiral.', '2023-05-21', 44, '/78UHlr7nHNuBe3iAIfNzFufhzVr.jpg', '2026-04-03T16:34:50Z', '2026-04-03T16:34:50Z');
