INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('cf1d613e-63d7-4fe5-b211-3db2d9d1aacc', 'ecb64ef3-4f80-45a7-b4a9-c04434b02e35', 1, 'Finding Fonzie', 'Get starstruck with the Pawn Stars when the guys check out an original poem handwritten by Marilyn Monroe. Will her words leave them speechless? Then, a hybrid rocket engine blasts in. Built into a suitcase as a sales sample, will the asking price for this oddity be sky high? And later, when Rick''s autographed Henry Winkler photo goes missing, he goes to great lengths to bring Fonzie home.', '2014-01-02', 21, '/aO8h8aTJSNPG86QMUu3GjKP9wr2.jpg', '2026-04-03T16:34:19Z', '2026-04-03T16:34:19Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('cf222426-f489-4b3d-9505-bc7ab8c85dc5', '9193e795-da7c-40ec-b68f-f63aa7d5174f', 70, 'Histories & Lore: Robert''s Rebellion (Viserys Targaryen)', 'Viserys Targaryen bitterly recalls the treachery of the Usurper Robert Baratheon putting an end to the Targaryen dynasty.', '2012-03-05', 3, '/cVlDm5zj9qhw1QZ5k0Mi2G5iyWa.jpg', '2026-04-03T15:40:35Z', '2026-04-03T15:40:35Z');
