INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('cf306f2c-7a52-4993-b214-bcd5d624f01e', '421c3366-4d98-4baf-b4ad-6ec5047df9f8', 12, 'Waiting for Snow', 'Ladonna can''t wait to experience her first blizzard. Skiing, sledding, snow days! If only the weather would cooperate. Arthur and Buster attempt to help her. Meanwhile, D.W teaches Bud how to make snowballs.', '2014-04-21', 13, NULL, '2026-04-03T17:38:01Z', '2026-04-03T17:38:01Z');
