INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('cf623de6-2f0b-4523-808f-6e161bc570d4', 'bfdf87ff-01dd-4b54-94bd-19b384f41bdb', 11, 'The Moral Minority', 'As the women recover from the accident in Glamis, Tamra returns intent on carrying on with the trip. New alliances form in the wake of Meghan and Shannon''s refusal to visit Vicki at the hospital. Back in the OC, Tamra contemplates postponing her fitness competition. While Meghan goes to Vicki''s house to make amends, Shannon attempts to get back into her friends'' good graces.', '2016-09-12', 44, '/nUOKY2d5MGhi51DEND0v6CEbnxh.jpg', '2026-04-03T16:35:33Z', '2026-04-03T16:35:33Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('cf624e08-e6d5-4026-8386-9534afe424e8', 'e48599f8-66ff-4c0f-9274-65b9ae1cda9e', 24, 'Episode 24', 'The 1976 Appeal is on! Help fill the Blue Peter Depot. Find out today how much has already arrived and what you can do to help reach the target.', '1976-12-02', NULL, NULL, '2026-04-03T17:21:53Z', '2026-04-03T17:21:53Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('cf64f88c-adb1-4c4a-8bc1-ad835f3ad114', '53f9624f-fcf8-4f77-82f6-d2eb3f5376ee', 4, 'How the Mighty Have Fallen', 'The Brown family spends Thanksgiving apart. Christine and Robyn put their differences aside to visit with Mykelti''s newborns. Robyn pushes Kody to reconcile with his kids. Then, Christine reveals that she went on a promising first date.', '2024-10-06', 43, '/mvuIArl7bzCdqfm0HugKzRMbsoX.jpg', '2026-04-03T16:34:33Z', '2026-04-03T16:34:33Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('cf66fdf0-1666-46f5-bd4f-498419061925', 'c9adc698-be92-4dd7-94ad-d8f6759361ca', 52, 'Episode 52', 'Rogers has a ukulele he wants Joe Negri to sell. In the Neighborhood of Make-Believe, Henrietta and Lady Elaine are at odds: both wishes she could be the other.', '1973-05-01', NULL, NULL, '2026-04-03T17:35:40Z', '2026-04-03T17:35:40Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('cf6bdb27-5d0a-45b8-987d-12167249e8ea', '101549f4-6ed1-45fa-b543-d08723f65306', 12, 'Episode 731', '', NULL, NULL, NULL, '2026-04-03T17:36:39Z', '2026-04-03T17:36:39Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('cf6d4849-43c7-48dd-974a-ad7a3f999792', '1be79a20-de33-41d1-af17-079035b18d5c', 1, 'Gordon Introduces Sally to Sesame Street (0001)', 'In the first episode of Sesame Street, Gordon takes a girl named Sally on a tour of Sesame Street, introducing her (and the viewers) to the various characters on the show. On the street, Sally meets the human cast -- Gordon, Susan, Bob and Mr. Hooper -- as well as two Muppet characters, Big Bird and Oscar the Grouch.', '1969-11-10', NULL, '/49IucoIY5an8lBVLrTXddMExcqY.jpg', '2026-04-03T17:36:28Z', '2026-04-03T17:36:28Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('cf711977-fd7b-4c5e-b0fc-564f83300e5b', '1d556682-d9bb-47e1-993f-0b648a8daacd', 72, 'Episode 1257', 'A TV-addicted Telly Monster moves to Sesame Street.  Cookie eats his way through an avalance as train conductor "Casey McFee".  The Count sings "The Song of the Count".  Kermit reports on Sleeping Beauty for Sesame Street News".  Plus the Harvey Kneeslapper skit.', '1979-03-06', NULL, NULL, '2026-04-03T17:36:33Z', '2026-04-03T17:36:33Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('cf7991c1-669f-4067-a37f-a3e9a223b69b', 'a6ed03e0-c05f-48f8-9f56-3f1da50e1792', 19, 'Episode 1334', '', '1979-12-20', NULL, NULL, '2026-04-03T17:36:33Z', '2026-04-03T17:36:33Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('cf8bd70d-996c-4028-afdb-ff96f57043d3', '3087a3ed-e94e-4276-9d02-a78183dea1d3', 20, 'Divas into Icons', 'Now that Kenya has moved beyond Walter and the Battle of the Booties with Phaedra, she decides to throw a big party; everyone must come in assigned costumes to her Hollywood Icons gala. The ladies are all dressed to impress, but one rogue Housewife turns an evening of elegance into a full-fledged showdown and this time Kenya might have gone too far.', '2013-03-31', 43, NULL, '2026-04-03T16:34:46Z', '2026-04-03T16:34:46Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('cf9997c9-714c-4362-9bb6-6708e5e6a8dc', '4da606e7-9d23-4682-8bd5-f535e1da706f', 12, 'Franklin''s Music Lessons', 'Franklin and his class were entertained by Mrs. Panda and her piano. This inspired Franklin and Beaver to take up piano lessons from Franklin''s Granny. He didn''t realize how practice can really be perfect until he noticed how well Beaver was playing the piano while he was out goofing off.', '1998-10-12', 12, NULL, '2026-04-03T17:40:15Z', '2026-04-03T17:40:15Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('cf9dd926-56a8-4329-b501-1952f3f9e913', '432a6abd-dcca-44cc-82ce-fb39e33b8949', 11, 'Episode 11', 'Miss Paulifficate bumps into Daniel''s toy tiger and rips it, but she glues it back together. They give a letter to Dr. Bill Platypus.', '1971-03-01', NULL, NULL, '2026-04-03T17:35:39Z', '2026-04-03T17:35:39Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('cf9e1b8a-6488-4421-b4f3-6ee75fc5e884', '46d7a706-c7a8-4ebe-b96f-387c66e8bb8b', 53, 'Episode 1498', '', '1981-02-04', NULL, NULL, '2026-04-03T17:36:34Z', '2026-04-03T17:36:34Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('cfa9279d-36c7-4d84-bbeb-3b3c7b159382', '1a534647-384b-4c00-bb6c-a3371ad962eb', 34, 'Pawn of the Jedi', 'Travel far, far away with the Pawn Stars when a draft of the original "Star Wars" script signed by George Lucas soars into the shop. Will Rick and Chum win the war for this obi-one of a kind piece or will the force not be with them? Then, Rick goes back in time when he checks out a terracotta medallion of Benjamin Franklin. Will Rick cash in on this patriotic piece or will he be frank in turning it down? And later, Chum wants to open a museum to display some of the shop''s hidden items. Will Chum be able to create a work of art or will Rick turn Chum''s plans into ancient history?', '2015-06-04', 21, '/lsQiitNHeG0ML85NnRUUL6CXHNd.jpg', '2026-04-03T16:34:19Z', '2026-04-03T16:34:19Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('cfa98d9b-f479-4652-a154-57b5f5263f7b', '0fb5ce65-0258-4423-be8a-f7ba9c37bb6b', 11, 'Great Reading Rescue', 'It''s the grand opening of the community library, but they''re out of books. With a mission set by Mandy, can Norman and James save the opening?', '2023-10-30', 9, '/wW2FXMFYBPfksP0pgctROM30vPz.jpg', '2026-04-03T17:14:42Z', '2026-04-03T17:14:42Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('cfa9aaab-9539-45b2-b695-3cceabfb677f', '95eff6e0-032d-45f2-8003-826d9c82b439', 3, 'The Robbery', 'Jerry is robbed after Kramer fails to close the apartment door. Elaine talks Jerry into looking at a fabulous apartment in the hopes that she can then have Jerry’s place. Things are further complicated when George decides he wants the new place too.', '1990-06-07', 23, '/dbfB7fSqrh41ukwIcxkpZUwMasq.jpg', '2026-04-03T16:34:09Z', '2026-04-03T16:34:09Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('cfa9b5d6-36a1-4688-be36-5ce80e7bf762', '9193e795-da7c-40ec-b68f-f63aa7d5174f', 184, 'Season 1 Character Profiles: Catelyn Stark', 'Character profiles of the 15 main characters in the words of the respective actors.', '2012-03-05', 1, '/dgHuVCqfV9yULz4Rz2svU809sSd.jpg', '2026-04-03T15:40:35Z', '2026-04-03T15:40:35Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('cfadf2aa-5ce5-40b6-8054-3f8b7717366f', 'c4d795ae-6afa-47d6-9819-4dd057030a3c', 19, 'No Money Mo Problems', 'Eva’s post-honeymoon bliss crashes down around her as Marlo serves up a steaming pot of tea regarding her living situation. Since her melt down at Eva’s wedding, Nene struggles over what’s next for her marriage. Kandi and Todd celebrate the opening of their second OLG restaurant, and though Porsha opts out of the festivities, the rumors about Eva become the bigger hot topic.', '2019-03-24', 43, NULL, '2026-04-03T16:34:48Z', '2026-04-03T16:34:48Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('cfb5cd15-2074-4d2f-9657-d1eeb454be10', 'eba5535a-00c7-4ed6-b186-382d83c5181b', 11, 'Episode 1716', '', NULL, NULL, NULL, '2026-04-03T17:36:34Z', '2026-04-03T17:36:34Z');
