INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('cfc05949-13e1-45c2-a300-5d6f990107ea', 'a1b69730-d225-48f2-a7e7-1d314cf3b349', 72, 'Episode 72', 'with Valerie Singleton, John Noakes, Peter Purves', '1969-06-02', NULL, NULL, '2026-04-03T17:21:49Z', '2026-04-03T17:21:49Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('cfc45808-bcff-4fbe-bcdc-4eb2bf50a0ee', '61e0c9d9-337e-4fe4-a0fd-e567b29af115', 17, 'Reunion (1)', 'The women of Salt Lake come together in New York City to rehash this past season. Bronwyn opens up to the women about her difficult entry into the group and confronts Lisa about a damaging comment regarding her daughter. The rift continues to grow when Lisa shares receipts that threaten the future of their friendship. Meredith and Angie attempt to resolve their long-standing issues, and Whitney addresses the rumors about her business. When the husbands take the stage, Bronwyn''s husband, Todd, faces off in a spicy exchange with the Barlows.', '2025-01-22', 43, '/ydwyWTj0akUctSZuaEs0aQiL5CD.jpg', '2026-04-03T16:35:45Z', '2026-04-03T16:35:45Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('cfc63433-9fce-47dc-a645-5b00744b55fa', '9193e795-da7c-40ec-b68f-f63aa7d5174f', 35, 'The Game Revealed: Season 7 Episode 3', 'The Game Revealed: Season 7 Episode 3', '2017-09-11', 60, NULL, '2026-04-03T15:40:35Z', '2026-04-03T15:40:35Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('cfc7ee28-73d5-4574-9f82-51d6c0e963b6', 'de052e8e-7dbd-454a-a6d8-b9afba6e9bfa', 27, 'Spring Cleaning Time', 'When the Wombles have to spring clean, an elastic washing line leads to trouble.', '1973-07-02', NULL, '/kWiHFUCFMg1Y0fXkb3C21dT2iQ2.jpg', '2026-04-03T17:23:19Z', '2026-04-03T17:23:19Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('cfcd0127-2533-449c-a7ed-316eb014db60', '9193e795-da7c-40ec-b68f-f63aa7d5174f', 253, 'The Bedding Ceremony', 'Author George R.R. Martin and producer D.B. Weiss discuss the bedding ceremony depicted in the series as part of a medieval wedding.', '2014-02-18', 2, NULL, '2026-04-03T15:40:35Z', '2026-04-03T15:40:35Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('cfd3aa49-3e1d-4959-8f67-fc8b13be8b2f', '70c8cb46-2494-4dd4-98f6-6bfb9b3faf73', 22, 'Trail Breaker', 'The Pawn Stars look to buy an American off-roading motorcycle classic–a 1967 Rokon Trailbreaker - but will this deal get stuck in the mud? Then, Rick is hesitant when a man brings in a rare mint condition 1715 Escudo Spanish Gold Coin. Will it be a fool''s fake or worth mucho dinero? And later, the Old Man has a chance to buy a memorabilia collection from boxing superstar Muhammad Ali. Will he come out swinging for the KO or throw in the towel?', '2010-06-07', 21, '/8cbw5F3K5bRKB31c9mygTfyCFyl.jpg', '2026-04-03T16:34:16Z', '2026-04-03T16:34:16Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('cfd552c8-b908-4fd8-abed-252069066b27', '1be79a20-de33-41d1-af17-079035b18d5c', 122, 'Big Bird Builds a Race Car', '', '1970-04-28', NULL, NULL, '2026-04-03T17:36:28Z', '2026-04-03T17:36:28Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('cfd5714c-2be4-47a4-af17-bd349fb4b9b8', 'be719633-fbf1-4df5-87e4-2da02389f497', 5, 'Reeds on the Roof', 'Neil comes across a man gathering reeds who then shows him using them to thatch a house''s roof.', '1999-02-02', 10, NULL, '2026-04-03T17:19:39Z', '2026-04-03T17:19:39Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('cfd6cefa-f1da-4b04-9c94-a0577af5359d', '7c422193-b078-49d8-81ef-f2b9f94f059d', 25, 'Oscar loses his voice (repeat)', 'Episode #3030

The main story of this episode is a repeat of episode #2830.', '1992-12-11', 55, NULL, '2026-04-03T17:36:39Z', '2026-04-03T17:36:39Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('cfd8ad3c-d640-4f46-9e44-ddc77c86d40e', '9df0f8c1-723f-4061-8692-e8c51a6a7223', 5, 'Episode 5', '', '2026-06-21', NULL, NULL, '2026-04-03T15:40:44Z', '2026-04-03T15:40:44Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('cfdb7312-3dc9-493d-96de-3e93e3d05136', '671bd4da-3470-40f9-9a03-40fba34d2b8e', 19, 'Bat Out Of Heck', 'Frankie is surprised but relieved when Dr. Goodwin agrees to buy all of the peanut brittle that Brick needs to sell for school. But the good doctor displays a bit of Mr. Hyde behavior when Frankie doesn''t deliver the product in an expeditious manner. Meanwhile, Axl is getting sick and tired of having Mike tell him how to run his life; and things go off the rails when Axl attempts to trade in the Winnebago and buy a car. Sue is more determined than ever to win a very prestigious and competitive hotel scholarship; and Frankie swears that she''s seeing something mysterious flying through the house.', '2018-04-10', 22, '/9svqyvWLBXmrs6xxBjHZPaFwbjw.jpg', '2026-04-03T15:40:31Z', '2026-04-03T15:40:31Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('cfe2daba-9bc3-4aeb-937b-92b4c304d6bc', 'db81ad42-93a7-4926-89e5-d4cefa257b83', 1, 'Welcome Back', 'Mr. Snapper is directing a play for the bicentenary of  Port  Niranda. Fay has a secret (she''s pregnant) and a the ghosts of the Von Clapp family want their 15 minutes of fame.', '2001-01-31', 24, NULL, '2026-04-03T17:40:41Z', '2026-04-03T17:40:41Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('cfe640c0-6477-4b2d-abb4-832e44fe4aee', 'ecb64ef3-4f80-45a7-b4a9-c04434b02e35', 21, 'You Snooze, You Lose', 'Battle it out with the Pawn Stars when Rick checks out a German two-handed sword. Built in the early 1600s, will he execute a deal for this antique weapon or lose his edge? Then, Corey steps up to the plate when a set of 1933 baseball cards slide into the shop. Will he score big or get thrown out of the game? And later, Corey''s noisy new neighbors are keeping him up at night. Will he find a quiet place to rest or become the shop''s worst nightmare?', '2014-03-13', 21, '/t883tO3qjCTWX7xU6Weln8J5GUF.jpg', '2026-04-03T16:34:19Z', '2026-04-03T16:34:19Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('cfe64efb-169c-4d2b-8925-a949863ebe3c', 'c5ae23d0-08df-4f18-af08-0ccc8fdef868', 8, 'Like a Windy Day; Winter Is the Warmest Season', '', NULL, 30, NULL, '2026-04-03T17:12:30Z', '2026-04-03T17:12:30Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('cff27941-19cf-458b-a903-9fa87e1438c3', '110e3467-3698-4e19-a35b-f6ebbaeb4d6b', 4, 'Cinderella', 'Cinderella is once again helped to the ball by her fairy godmother (this time played by the hilarious Jean Stapleton) as the story of Cinderella unfolds and how she loses her glass slipper-- this one has an amusing twist at the end -- that shows even fairy godmothers are vindictive.', '1985-08-12', 51, '/u58qqzJQlXis6dFO0F57UfLo300.jpg', '2026-04-03T17:38:41Z', '2026-04-03T17:38:41Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('cff349c3-6343-4199-a6dc-a73719429d83', 'de8ec769-16bb-436b-be43-aedc7e18a7d7', 24, 'Dog Day Engineers', 'Zoe and Rosita help Nina dog sit but their arms get tired after continuously throwing the balls. They don''t give up and keep thinking of a way to solve this problem. They figure out how to design a bike-powered ball-throwing machine they can pedal using their feet. They are two real engineers!', '2020-04-25', NULL, '/ySlhxTaYJhmLz4sGYIyDwZ89Kjw.jpg', '2026-04-03T17:36:50Z', '2026-04-03T17:36:50Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('d001d114-cd79-4c77-9533-5c0042a8ee43', '05c0e384-194c-4417-9f62-803eb615e409', 16, 'Making things for others', 'Title number 0016. Opens with Mister Rogers arriving with lumber scraps and uses nails to hammer some of the pieces together to make a boat. In this episode, the puppet character Donkey Hodie appears for the first time. In the Neighborhood of Make-Believe, artist Virgil Cantini visits and shows King Friday some of his nail sculptures. Lady Aberlin knits a sweater for Henrietta Pussycat. X the Owl wants a gift too, so Lady Aberlin promises to knit him a scarf.', '1968-03-11', 28, NULL, '2026-04-03T17:35:38Z', '2026-04-03T17:35:38Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('d00d507a-5736-4b46-b086-f04436d584c4', 'd84bd187-f033-42dd-8873-e1099c61de07', 11, 'Episode 670', '', NULL, NULL, NULL, '2026-04-03T17:36:39Z', '2026-04-03T17:36:39Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('d01c51cf-0de2-4881-a8ba-8550df38039a', '991e78f1-03a5-4d26-8f75-75e11db4243c', 2, 'Noisy and Quiet: How People Make Ribbons', 'Rogers attends the rehearsals for a dance team that performs with long ribbons. Henrietta, X, and a muted Bob Dog are frightened when they see so many of their neighbors in strange costumes. What they don''t know is that these costumed neighbors are staging a parade.

This is the last episode that Bob Trow appears in. He died a few months before it aired.', '1999-02-22', NULL, NULL, '2026-04-03T17:35:48Z', '2026-04-03T17:35:48Z');
