INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('d0617494-8edc-4680-836d-909a6ec670e3', 'f4c40307-9b5e-4263-a4e0-dfa138131e7f', 47, 'The Best of Elmo 2', 'Join everyone''s favorite red monster for a fun filled story featuring some of the most popular Elmo segments ever! Elmo meets a robot on Sesame Street who is losing his power. The robot is a "Memorybat," and he needs "memories" to power up again. Elmo Gladly shares his memories of special times with his friends - singing about the outdoors with Jason Mraz, rhyming with Adam Sandler, reciting the alphabet with India.Arie, and counting to four with Feist. Elmo remembers even more fun with Destiny''s Child, David Beckham, and The Goo Goo Dolls. Will Memorybat get his power back? Every Elmo fan, young and old, will enjoy this story of friendship and treasure this collection.', NULL, NULL, NULL, '2026-04-03T17:36:27Z', '2026-04-03T17:36:27Z');
