INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('d101bdb2-e898-420e-b274-76636eaff4d4', '937ee587-e2eb-46aa-9a69-3d6bab04398f', 9, 'Meanwhile Back at the Ranch', 'LeVar travels to an old west town made to look like life in the 1880''s to see how times have changed in the last 100 years. He explores how cowboys lived and traveled, and he also shows how stunt riders practice tricks on their horses for western movies. Hoyt Axton reads the featured book, a story told in comparisons about a rancher who decides to spend the day in a town 84 miles from home, and the strange happenings at his ranch back home while his wife stayed home to plant potatoes.', '1987-07-02', 30, NULL, '2026-04-03T17:36:16Z', '2026-04-03T17:36:16Z');
