INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('d1b1e28e-68b1-4bf1-b139-5a4a2c45647c', '8b6bbac8-e5ef-49c7-a5c1-197cfb19f772', 1, 'Divorce', 'Mr. McFeely relives memories of his wedding. Previewing the Neighborhood of Make-Believe storyline, Prince Tuesday befriends a girl whose parents are divorced. This episode has 2 make-believe segments in one show.', '1981-02-16', NULL, NULL, '2026-04-03T17:35:42Z', '2026-04-03T17:35:42Z');
