INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('d1b87b30-6e62-4b81-8666-029342b2ca17', '4a8e3db0-8068-4ff3-942f-91f45f665f20', 19, 'The Ram in the Pepper Patch', 'The naughty ram from the book ""The Ram in the Pepper Patch"" escapes into the library, where he proceeds to make a mess out of everything!', '2000-04-27', 30, NULL, '2026-04-03T17:12:27Z', '2026-04-03T17:12:27Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('d1c2ebb8-2f34-424f-8aad-7ef18c305203', '97616d6e-5c17-449f-a376-55f1da83d6c3', 3, 'Mister Rogers Talks About DISCIPLINE', 'After a brief mention of the trouble he had zipping his sweater, Mister Rogers shows a handful of plastic pieces. He explains that these pieces are melted down and used to make dolls.

Inviting viewers along, Mister Rogers visits a factory where dolls are made.

Returning to the house, Mister Rogers talks about how dolls are made and people are born -- dolls are put together and people grow together. This leads perfectly into Everything Grows Together.', '1982-03-02', NULL, NULL, '2026-04-03T17:35:42Z', '2026-04-03T17:35:42Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('d1c701d1-3c0d-42eb-a07c-428146653788', '22beba7f-9b8e-4563-93da-46e76ecba427', 22, 'Gina Adopts A Baby (1)', 'Gina flies off to Guatemala to pick up Marco, the baby she is adopting. Maria goes with her to help her with her Spanish.', '2006-11-06', NULL, '/uzIcgo5hkhUgbW4LgO9SWMFtVDA.jpg', '2026-04-03T17:36:44Z', '2026-04-03T17:36:44Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('d1cd2cbb-11dc-46ef-8f75-4a429ac8fbd8', 'e13f4aa4-dd8a-48d5-8cc1-1c258f43e44d', 913, 'The Social Edition', 'An episode featuring social-media content.', '2014-07-14', 44, NULL, '2026-04-03T16:35:29Z', '2026-04-03T16:35:29Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('d1cdb8e5-1bee-4af7-816f-37983b16b9d8', '699572f8-2bff-4515-8df3-6e7d1a21f346', 10, 'Gets Charged', 'It’s Valentine’s Day and the class is selling lightbulbs. When they stop at Ms. Frizzle’s house to sell her one, they find that her battery-operated doorbell doesn’t work.', '1997-11-15', 25, '/1x2R34wyXgle3WRf5U1igIHseZr.jpg', '2026-04-03T17:37:49Z', '2026-04-03T17:37:49Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('d1d4d2a3-4109-40e4-9c14-5e5f917e3ae2', '119c16d5-1047-45ec-8242-c72a8eed423b', 27, 'Arthur the Wrecker', 'Arthur breaks his mom''s computer. Can he fix it before she finds out?', '1996-10-24', 13, NULL, '2026-04-03T17:37:55Z', '2026-04-03T17:37:55Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('d1d60a0b-7900-41b9-aa49-8978e4c9a673', '5ff41814-d526-460e-9bf2-4945df6efab2', 5, 'The Hobbit, part 5 - Flies and Spiders', '', '1979-10-05', 15, NULL, '2026-04-03T17:20:12Z', '2026-04-03T17:20:12Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('d1dbf06d-9871-49bc-81d0-c8d754dfb2b8', '6ef86c27-33e7-47e5-a053-483059dfd16d', 50, 'Episode 50', '', '1982-03-08', NULL, NULL, '2026-04-03T17:21:55Z', '2026-04-03T17:21:55Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('d1dd7bb8-6a5d-4821-9db0-193dee6501e0', '97a3d1f5-a8f1-47cd-8122-2e74a092836d', 22, 'Don''t Stop the Music (2)', 'As the team starts rehearsing for Lenni''s video, strange things start happening. The lights go out, someone puts glue where their feet are going to be put and a wireboard short circuits. The team realizes that whoever is behind the sabotage must be working on the video. Leif isn''t upset with the glue. Sonia wants to use the accidents for publicity. Ghostwriter reads a letter to David from Marlon Campbell, the same guy who tried to bribe Lenni to work for him. But, David says that he doesn''t know Marlon. Casey Austin, Jamal''s cousin, sneaks into the studio to spy on Jamal. Jamal and Gaby read an article that years ago Leif and Jade used to be lovers. Leif was in show business with a few hits but when he dropped Jade broke up with him and he hasn''t forgiven her. They hear a noise and thinks it''s Leif running away scared, so they decide to surround him but instead find Casey.', '1994-01-30', NULL, NULL, '2026-04-03T17:40:28Z', '2026-04-03T17:40:28Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('d1de57c1-3323-48bc-b297-ceb50aa14a94', 'e40e6b63-9f84-449f-8e88-53209b0906c8', 15, 'Big Bird, Elmo & Abby, Song for 3', 'Big Bird and Elmo are excited, because they''ve got a special song for two friends, which they are. They count each other, and sing "One and One Make Two." They almost sing it again, when Abby Cadabby appears in a poof, and asks to join them. Suddenly, Big Bird realizes the song won''t work this time, because it''s a song for two, and if Abby joins them, they won''t be two anymore, but three. What to do? Abby suggests making herself disappear, but that turns out to be not such a good idea. The three friends decide they should ask Gabi what they should do. They explain their predicament, and Gabi suggests they sing a song for three instead of two. What a great idea!', '2007-09-14', NULL, '/nHb9qI6y1KCGfEXMGnNUa2zt11A.jpg', '2026-04-03T17:36:45Z', '2026-04-03T17:36:45Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('d1e0b19a-e913-4119-ac22-842876256d74', '5062ce29-8dbb-48ab-879b-0771221678d5', 4, 'The Rabbit Who Was Afraid of the Dark', 'Rabbit has become afraid of the dark, and the others don''t know what is causing it, but Percy does - she hasn''t been eating enough carrots! She then eats some more, and is then able to see in the dark, and is not scared anymore.', '1999-10-10', 15, NULL, '2026-04-03T17:19:02Z', '2026-04-03T17:19:02Z');
