INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('d259062b-3d19-4cd1-904e-ca622a75945c', 'be719633-fbf1-4df5-87e4-2da02389f497', 12, 'Baby Elephant', 'Neil comes across a man carrying equipment to wash a "very big baby". After offering to carry the equipment to Twycross Zoo, Neil, along with Rosie and Jim, discovers that it is a baby elephant.', '1999-04-06', 10, NULL, '2026-04-03T17:19:39Z', '2026-04-03T17:19:39Z');
