INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('d26901c9-a0d4-437d-ad92-d6015ac19b31', 'd920ebae-f00a-4e25-abfe-40492c74ded6', 15, 'Pawnsplosion', 'When given the chance to drive a WWII tank, Rick says Sherman, but will he go to war to own this piece of history'' Meanwhile, two is a party, but three''s allowed when a Triplet Bicycle rolls in. Then, vintage toy soldiers march into the shop. Will they get Corey''s attention, or retreat'' Next, Rick and Corey are visited by Haunted Mansion memorabilia. Will they possess the spooky souvenirs or cast them out'' Later, things get HOT when Chum finds a flamethrower. Will he fire up a deal, or get burned''', '2020-03-27', 42, '/yhkzKkgLXJFQg3yTmWZCKuYMoYh.jpg', '2026-04-03T16:34:22Z', '2026-04-03T16:34:22Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('d26be5c3-47ff-4c87-b6bb-80b04f6059b4', '6a2d2839-7106-4c3b-8906-c9b3e4bfcc8b', 6, 'Showdown at the Hoedown', 'Tension simmers between Heather and Shannon in the wake of their dispute over seating at a dinner. Elsewhere, Vicki struggles with her daughter''s decision to move; and Heather throws a hoedown bash, where a mechanical-bull mishap creates drama.', '2014-05-26', 44, NULL, '2026-04-03T16:35:32Z', '2026-04-03T16:35:32Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('d26c2df9-e5cb-4927-b2cf-83b2e067cb58', '58adb9ab-3f1b-4a11-87b6-9b0b2dbb6aaf', 26, 'Stamp Stumped', 'Call it heads or tails, when Rick flips around a few gold and silver coins that come into the shop. Will he buy them all or call it chump change and walk away from the deal? Also, Corey is a bit stuck on whether some odd tax stamps are even worth the paper they''re printed on. Later, Chumlee is hoping everything is gonna be alright when a signed Bob Marley album comes in. Will he be jammin'' out to a big sale or will it be no deal, no cry? To round out the offerings, Rick considers taking some concertina lessons and a vintage Win-a-Card game could be Topps for Corey.', '2017-08-07', 21, '/xboa2DorTAqc2kP3YInTzWLoIXG.jpg', '2026-04-03T16:34:21Z', '2026-04-03T16:34:21Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('d2747801-7a16-4c5e-b62c-d352dab7184f', '8c3cfac1-d882-4904-b38c-d1981628d00e', 54, 'Episode 54', '', '1979-03-19', NULL, NULL, '2026-04-03T17:21:54Z', '2026-04-03T17:21:54Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('d27b2769-f600-43dc-bfdc-0515ac33f30c', '3a96d6c6-3736-498a-926f-6c479cdfb73a', 16, 'Franklin''s New Friend', 'A new family have moved into Woodland and Franklin is curious. Little did he know the new kid in town is also a six foot tall Moose!', '1997-12-15', 12, NULL, '2026-04-03T17:40:14Z', '2026-04-03T17:40:14Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('d27c4aec-9e90-491f-b551-08ce103b4169', '225b0f03-984b-47f3-a1a3-d3e92175e39d', 36, 'Episode 36', 'with Christopher Trace, Valerie Singleton and John Noakes.', '1967-01-30', NULL, NULL, '2026-04-03T17:21:48Z', '2026-04-03T17:21:48Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('d2802b71-1106-4e8c-8cf6-48a47a4141f1', '02849655-bd95-4d8d-af3b-03321918eeee', 12, 'Madeline at the Hotel Riche', 'When the pipes burst and the old house is closed for a plumbing overhaul, Madeline and the girls move into Lord Cucuface''s lavish suite at the Ritz. While there, they help a lonely rich girl and a hungry homeless girl, and soon discover that they''d rather have each other''s love than live an empty upscale existence.', '2000-11-24', 30, NULL, '2026-04-03T16:34:02Z', '2026-04-03T16:34:02Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('d2807e4b-ccde-42d0-b6df-162a3eafd757', '54facb0b-db59-41fe-9d64-c7c7221a3c81', 12, 'Luann Land', 'The women dine out with Ramona at the same place where she mourned her mother''s passing; Luann takes Sonja, Tinsley and Barbara out on the town for a night of cabaret; Bethenny and Ramona have a heart to heart about their abusive upbringings.', '2019-05-22', 60, '/sLBgq1neliske7hs8mnbjGTPebC.jpg', '2026-04-03T16:35:25Z', '2026-04-03T16:35:25Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('d280e0f8-2d9c-45e7-92e3-7251aae47d44', 'cb8a0322-be77-485b-b339-bdd572bca349', 10, 'Revenge of the Chip', 'D.W''s mom tells the newspapers and everyone in town that story about D.W. and the green chip embarrassing her ultimately.', '1998-11-20', 13, NULL, '2026-04-03T17:37:56Z', '2026-04-03T17:37:56Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('d284077a-4e8b-49a0-9872-96b047d1608e', '9193e795-da7c-40ec-b68f-f63aa7d5174f', 293, 'Creating the Visual Effects: Season 6', 'Creating the Visual Effects: Season 6', '2020-11-24', 22, NULL, '2026-04-03T15:40:35Z', '2026-04-03T15:40:35Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('d284c098-369f-409b-9632-1c1854afcf95', '7b8e3988-fbf3-4cfc-aeb2-782ae5a64e2d', 11, 'Snuffle Sneeze', 'Snuffy can''t stop sneezing after meeting up with Big Bird, who''s fresh from a dust bath. Gina thinks it might be an allergy and does some tests to see if it is.', '2010-11-01', NULL, '/5HltrFbsp4Sbk4LZv4sA8NntyKB.jpg', '2026-04-03T17:36:46Z', '2026-04-03T17:36:46Z');
