INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('d2996b58-5ae2-4d74-b5bd-c4d18b036080', '51f03551-ba41-409d-85f4-e51bddfdf82e', 9, 'Wife in the Fast Lane', 'A business theme features Ramona busy on her skin-care line and throwing a showcase party for the product. Meanwhile, LuAnn meets with a writer to finish her book; Bethenny promotes her food fare; and Kelly works on her jewelry business in Los Angeles. Meanwhile, Simon hopes to add a special touch to Alex''s birthday.', '2009-04-14', 60, '/zdBHM7Lzq4RqUNCSLwOweizYFl1.jpg', '2026-04-03T16:35:22Z', '2026-04-03T16:35:22Z');
