INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('d2a9683a-48b2-43e4-946e-21d3d3ce5525', '831e3a6b-c1a7-48b7-a5ac-b18ed67beb10', 7, 'Reading Is Fundamental', 'An evening of bonding takes a tense turn when Gizelle confronts Katie, prompting the others to encourage Katie to put Gizelle in her place. Elsewhere, Ashley''s newfound friendships come into question courtesy of a surprise from her husband.', '2016-03-13', 42, '/5lYWdTX6ZWueOER5bIjUfIGNhnI.jpg', '2026-04-03T16:35:38Z', '2026-04-03T16:35:38Z');
