INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('d302a45b-6e54-41d2-963c-bbd9dd89bd79', '151e88a1-9576-4bd1-b84a-c4d64c1c9fe8', 10, 'So You Say', 'As Sutton''s garden party finds itself in the weeds after Lisa''s outburst, Erika seeks forgiveness from Garcelle for her past indiscretions. Meanwhile, Crystal gets involved in Sutton''s love life and Kyle is left reeling by an accusation she does not agree with. Dorit finds comfort in Hanukkah traditions, but a frigid lunch has Diana feeling anything but the holiday spirit.', '2022-07-13', NULL, '/anIWLDwkiqtnrQlsD148BcWpapP.jpg', '2026-04-03T16:34:58Z', '2026-04-03T16:34:58Z');
