INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('d3096fda-2671-45b0-aefe-e283edbf01cb', 'ca19f895-1514-4988-a709-95e84eab7cee', 13, 'Rick''s Surreal Supper', 'When Chum gets his hands on a one-of-a-kind chair with a strange feature, will Rick turn a blind eye to his spending? Then, a helmet that once belonged to Evel Knievel lands in the shop. Will Rick take a leap of faith, or will the deal crash and burn? Next, Corey pedals into the past with a toy inspired by the Weinermobile. Will he get roasted by the seller, or can he sink his teeth into a deal? And finally, Rick cracks open a cookbook by artist Salvador Dali, and gets a surreal idea – to host a dinner party. But when things quickly get hairy, will Rick melt under pressure?', '2021-04-12', 42, '/qRf6sx6OBYlqPQEqHlSQQetDvOa.jpg', '2026-04-03T16:34:22Z', '2026-04-03T16:34:22Z');
