INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('d3368e02-3850-41c3-af96-dd24bf558f85', '4f18ac4c-8757-456c-a49a-224f00e6a9f7', 19, 'Sesame Street Bird Games', 'Chris and Alan close Hooper’s Store, welcome the viewer and plan on going bowling. However, their plans are put on hold when they hear a fanfare and Big Bird shows up, announcing the “Sesame Street Bird Games” and tells them they’re the judges. A penguin adviser arrives and hands Alan an envelope with the game’s rules. He also gives them their judicial headgear. Alan questions why they must do it and Big Bird points out that it will be fair if non-birds judge the events. The other two contestants arrive (a chicken and a duck), so the games can now commence!', '2008-10-20', NULL, '/8MBqVqPhu2PKLV2iIfn2RpMQyhV.jpg', '2026-04-03T17:36:45Z', '2026-04-03T17:36:45Z');
