INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('d354ae26-57f5-4100-9ad9-0f14e767f7b6', 'f4c40307-9b5e-4263-a4e0-dfa138131e7f', 120, 'Ready for School', 'Big Bird, Baby Bear and the rest of the gang all get together to help apprehensive Elmo prepare for his first day of school. Once he learns of the singing and dancing, arts and crafts and all-around fun that awaits him at school, Elmo''s raring to go. Packed with great songs, memorable characters and the trademark Sesame Street charm, this feature is perfect for toddlers on the verge of their own first day of school.', NULL, NULL, NULL, '2026-04-03T17:36:27Z', '2026-04-03T17:36:27Z');
