INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('d3774d36-bf4d-450e-8315-c8af798d6d47', '6f731e6b-d3c5-4de6-84e1-7a19cb650e86', 32, 'One in a Million', 'Dig for gold with the Pawn Stars and uncover some of the rarest items in the shop''s history: the holy grail of Hot Wheels - a 1969 Beach Bomb Prototype, a first-edition Revolutionary War military protocol manual, an induction motor developed by the father of electricity: Nikola Tesla, a sacred $150,000 Star Wars Boba Fett action figure, a 19th century Nepalese Bira Gun and a set of Houdini-owned shackles that leave Chumlee in a real bind.', '2016-04-27', 21, '/ci74N3ecHaHUyez0iydARBGmKXo.jpg', '2026-04-03T16:34:20Z', '2026-04-03T16:34:20Z');
