INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('d3b5977f-1945-4fe2-bc4b-abeefc021071', '3269a890-bba9-4e6c-9278-f7eb38eb1720', 1, 'Planets & Moons', 'Each planet is different. They are all different sizes – Pluto’s the smallest, and Jupiter’s the biggest. They come in a variety of colors – Mars is covered with rust, so it looks red; the methane (cold natural gas) in the atmosphere of Uranus makes it look blue; and Saturn’s colorful rings are made of icy rock. As far as we know now, Earth is the only planet in our solar system that is home to living things.', '1995-01-14', 26, '/skQcEBJInzVFqXhOX33ZNNwHy2R.jpg', '2026-04-03T17:37:21Z', '2026-04-03T17:37:21Z');
