INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('d3dbc7dd-e421-418d-a9b9-3459463adf8a', 'bb5a8843-6181-4a6d-bfdf-33ef2c6be7b8', 2, 'Say Yes to Distress', 'After the showdown at Cynthia''s 50th birthday party, Porsha''s sister, Lauren and niece, move into her palace. Cynthia struts her way back into the dating scene with a much younger beau. After the fallout from the painful history with ex-husband Bob was made public, Shereé meets with a life coach to help get her life back on track. Meanwhile, Kenya is confronted with scrutiny about her husband, which turns out to be more than she can handle. A few of the ladies attend Shamea''s bridal shower, and all seems well until Porsha gets called out for being a shady best friend.', '2017-11-12', 43, '/oaAZ9BpP9vxmcYi31ulsstsMVyJ.jpg', '2026-04-03T16:34:48Z', '2026-04-03T16:34:48Z');
