INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('d42b7412-c2f4-4121-abad-7fd6cfdfee39', 'a3a2c2fb-8276-412c-9d86-5175167be1d7', 50, 'Episode 50', 'with Valerie Singleton, John Noakes, Peter Purves', '1972-03-06', NULL, NULL, '2026-04-03T17:21:51Z', '2026-04-03T17:21:51Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('d42c2bcb-c896-484e-abb1-5d4bd4474dfe', 'ea1650c2-e4f1-46c7-93ba-74b5d45d08e5', 4, 'Petty Boughetto', 'Despite the toll her marital problems and troubles with Bryson are taking on NeNe, she is determined to get her "happy" back, even if that’s through plastic surgery. Phaedra and Cynthia finally find time to get to know each other better as they attend Atlanta''s premiere horse racing event, the Steeple Chase. Inspired by a late night host, Kim is ready to be a two-hit wonder and asks Kandi to write her next song. Dwight helps Phaedra plan her over-the-top Kentucky Derby-themed baby shower. Kandi, Cynthia and Kim quickly realize this shower is unlike any other shower they''ve ever attended.', '2010-10-25', 43, '/7pev8Ynnkn1s5uydtLCD1iNVLRI.jpg', '2026-04-03T16:34:45Z', '2026-04-03T16:34:45Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('d42e2a7c-efae-4a04-bbc1-0fe46f40191b', '17e6cc8e-dcf3-4ce6-97db-5a9fc8e31eb5', 1, 'Welcome Back Peaches', 'Porsha returns to the spotlight amid her tough divorce, but not everyone is welcoming; Drew navigates an awkward home life as a rumor about her and Porsha''s ex spreads', '2025-03-09', 42, '/l9e9QaZqTcK3x2NVwL6DKGrYENZ.jpg', '2026-04-03T16:34:50Z', '2026-04-03T16:34:50Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('d42fd4f7-e3ac-41f1-8e4e-9e14ef715a58', '225b0f03-984b-47f3-a1a3-d3e92175e39d', 57, 'Episode 57', 'with Christopher Trace, Valerie Singleton and John Noakes.', '1967-04-17', NULL, NULL, '2026-04-03T17:21:48Z', '2026-04-03T17:21:48Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('d4311d2b-3804-4beb-b9a2-165ae39b6bf5', '8c0f12e1-5379-4a27-aca2-b69401a33b0f', 15, 'Arthur vs. the Piano', '', '1997-10-29', 13, NULL, '2026-04-03T17:37:55Z', '2026-04-03T17:37:55Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('d4371c03-057f-4673-946e-272e7af46850', '3269a890-bba9-4e6c-9278-f7eb38eb1720', 7, 'Water Cycle', 'About 70% of the Earth’s surface is covered in water, and almost all of that water has been around since the Earth formed billions and billions of years ago. That means a glass of water you drink today could be water that a dinosaur once sipped. Water is constantly recycled on Earth as rain, snow, sleet and hail. It makes its way in and out of oceans, lakes, streams, hail, and glaciers. Scientists call the recycling of water the water cycle (not that bad, huh?).', '1995-03-24', 26, '/a8yNGYQHai9VvVUg7rKhrY3cDVp.jpg', '2026-04-03T17:37:21Z', '2026-04-03T17:37:21Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('d43bfe87-6601-4ebe-89d9-c5d5998cbd19', '68138de2-0900-460a-b58e-480688f1e081', 1, 'Ooh, Baby, Baby', 'Grandma Flutter drops her granddaughter, Baby Blotter, off at the Big Blue House while she goes to her dance class. Bear helps Tutter learn how to care for a baby -- but everyone''s at a loss when Blotter starts to cry. The day is saved by Treelo, who comforts the baby and gives her his rattle.', '1998-06-08', 25, NULL, '2026-04-03T17:35:31Z', '2026-04-03T17:35:31Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('d43c925a-27f1-42d9-a460-528fe6b2ff42', '6617316f-2b1c-4733-9f9f-f315db6ade0b', 10, 'Episode 10', '', '1995-03-08', 25, NULL, '2026-04-03T17:21:16Z', '2026-04-03T17:21:16Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('d4406b9a-5703-4e29-bc68-c9b1ff98fec3', 'f21ca545-466c-448c-ada5-b8acc8b856dc', 2, 'Out of Time', 'Bernard''s Mum and Dad both have meetings to attend and have an argument about the meetings, not realising that Bernard is there, so thinking they don''t care anymore Bernard looks after himself for the Afternoon.', '1999-09-17', 15, NULL, '2026-04-03T17:20:05Z', '2026-04-03T17:20:05Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('d4473516-4042-4c98-8ed4-b6bcb76cdc0d', '5c1b881f-ac58-4d72-b63f-209952d4f902', 48, 'Episode 48', '', '1980-02-25', NULL, NULL, '2026-04-03T17:21:54Z', '2026-04-03T17:21:54Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('d44d5cb6-76f7-45f3-ae05-5f2be111d3ee', 'd3e13496-e3c8-4903-83b4-5a31fedee232', 13, 'The Blue Spirit', 'While Aang, Katara and Sokka are traveling, Sokka gets a fever. Katara and Aang try to help Sokka, when Katara also catches the fever. It''s up to Aang to go up on his own to save his two friends. But before he can get the medicine he is captured by the newly promoted Admiral Zhao and put in Zhao''s fortress.', '2005-06-17', 25, '/cyD4FCLS0vaxLmHantYqMkqACh5.jpg', '2026-04-03T17:40:47Z', '2026-04-03T17:40:47Z');
