INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('d4534d7b-22cd-4a03-81f0-b5803d26c5fd', '4060ad7f-4b8f-4393-8eb1-66a150b928b6', 34, 'Cinderella''s Clockworks', '', '2021-06-24', 26, '/qETmikNsyi5on1YVKMUapE5XorC.jpg', '2026-04-03T17:36:50Z', '2026-04-03T17:36:50Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('d456269f-cf8d-4706-b2cb-7e4788e222be', '015cceb3-0a47-4f26-a683-81a4696951f0', 8, 'Postman Pat and the Greendale Rocket', 'The children set off on a school outing and are very excited when they discover Greendale''s old forgotten steam train, the Greendale Rocket. Everyone volunteers to get the Greendale Rocket back into action. Pat and Ted try to get the engine working again. Will it work again in time for the grand reopening?', '2003-09-06', 25, NULL, '2026-04-03T17:14:29Z', '2026-04-03T17:14:29Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('d457a72c-ffc3-4912-aef9-cca8327d46db', 'ea73e13c-6962-4804-8305-c303df65f89f', 36, 'Shoes and magic', 'A Wizard enters the Neighborhood of Make-Believe to find Lady Elaine Fairchilde. He plays games and then stubs his toe, prompting Dr. Platypus, who also meets King Friday for the first time.', '1969-03-31', NULL, NULL, '2026-04-03T17:35:38Z', '2026-04-03T17:35:38Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('d45b8277-a09c-4094-9193-a06576adfa2b', '18da9943-1963-4e04-a7a0-ae63802bb1fa', 18, 'Femme Finale', 'Emily plans a Femme Fatale party for the ladies, as her mother, Susan, visits Orange County for the first time in five years; Shannon has a very adult conversation with her 16-year-old daughter, Sophie; Tamra and Gina try to hash out their issues.', '2018-11-19', 44, NULL, '2026-04-03T16:35:34Z', '2026-04-03T16:35:34Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('d464dc85-53c0-4f0c-9654-9c21de24a904', '98d80972-e53a-43dd-a03a-7703465e6f87', 23, 'Comic Con', 'Fly high and aim low with the Pawn Stars as they check out a Japanese machine gun camera. Used to train fighter pilots during WWII, will the guys have the skills to keep this deal on target? Then, Chumlee and Corey take a look at some sketches drawn by Spider-Man creator Stan Lee. Known as a writer, but never an artist, are they legit, or a web of lies? And later, Rick and the Old Man eye a $1,000 Federal Reserve note from 1918. Will they fork over a stack of hundreds, or is this G note past its prime?', '2013-02-04', 21, NULL, '2026-04-03T16:34:18Z', '2026-04-03T16:34:18Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('d4707d18-b8ff-4cc7-a9d8-ab6af20cb421', 'd1d267dd-e27f-4543-acb8-0d28f676512a', 61, 'Episode 61', 'with Valerie Singleton, John Noakes, Peter Purves.', '1968-04-04', NULL, NULL, '2026-04-03T17:21:49Z', '2026-04-03T17:21:49Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('d4733887-3ba1-491e-a9e5-d4bf3a549814', 'bb5a8843-6181-4a6d-bfdf-33ef2c6be7b8', 13, 'Livin'' La Villa Loca', 'The ladies'' arrival in Barcelona gets off to a bumpy start when Cynthia confronts Eva and Porsha about the tea they spilled concerning Will. Cynthia''s hosting duties are questioned after the ladies arrive at their "villa" and things heats up between Marlo and Kandi when shade is thrown at the group dinner. Back home in Atlanta, Kim gets wind of a joke made at her expense and all of the ladies are shocked by her next move.', '2018-02-18', 43, '/2nLR31KuZqurHmF48Bn9FBTSoTr.jpg', '2026-04-03T16:34:48Z', '2026-04-03T16:34:48Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('d47c9eb8-1e74-4701-8135-17a39d46e94b', '87989283-6fea-40d7-8d91-22c4947db105', 14, 'Baby Steps', 'Maddie thinks she''s in labor, but it''s a false alarm, so Kody heads back to Flagstaff. Kody and Robyn are at wits'' end over their struggle to close on her house. Then, Kody and Meri head to their therapist in Vegas, where the brutal truth comes out.', '2020-04-05', NULL, NULL, '2026-04-03T16:34:31Z', '2026-04-03T16:34:31Z');
