INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('d4b8c67b-0941-422a-ba71-78f9574c09a9', '2f5a4ffe-2548-4181-85ac-6145cb3e3bf7', 12, 'Tell All: Part 1', 'In Part 1 of Sister Wives Tell All, the Browns are left reeling as frank discussion leads to new insights and emotional meltdowns. Will the family ever settle down in one location? Did Meri''s Bed and Breakfast further damage her relationship with Kody?', '2019-04-14', NULL, NULL, '2026-04-03T16:34:31Z', '2026-04-03T16:34:31Z');
