INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('d4c1deda-8173-49a7-8483-a2eda1061727', '98d80972-e53a-43dd-a03a-7703465e6f87', 9, 'Sweet Pawn of Mine', 'Kick off your shoes with the Pawn Stars when Rick and the Old Man are offered a pair of slippers owned by Pope Leo XIII. Considered one of history''s most influential popes, will the guys have a prayer of making a deal? Then, Chumlee and Olivia are working the night shift when a guy brings in a driver''s license owned by god guitarist of Guns N Roses: Slash. Is this rock memorabilia worth waking up Rick? And later, the Old Man''s 20 cup-a-day coffee habit sparks a family intervention. But can you really teach this old dog a new trick?', '2012-11-26', 21, NULL, '2026-04-03T16:34:18Z', '2026-04-03T16:34:18Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('d4c3a136-a613-40cc-b0ae-849e0a20aa67', 'bb919aec-0d5c-4c58-9a5a-fa2a0a5de2b6', 26, 'Episode 431', '', NULL, NULL, NULL, '2026-04-03T17:36:29Z', '2026-04-03T17:36:29Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('d4c47f47-8715-4b64-aa65-508175cfb3f3', '5b72e664-d3d7-435d-bdc3-a23d29d1178e', 11, 'Little Bear''s Book', 'Old Bear promises to read Little Bear a very special bedtime story because he has been so helpful. Little Bear is very excited as he gets ready for bed but then he can`t find Old Bear anywhere. It seems that everyone else is also too busy to read him a story. Little Bear is very disappointed, but he needn’t worry; he eventually discovers Old Bear and the reason why all his friends have been so busy. And his bedtime story really is extra special.', '1994-11-15', 10, NULL, '2026-04-03T17:18:55Z', '2026-04-03T17:18:55Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('d4cb0936-88e4-4375-8422-f0ab99c768b6', 'e48599f8-66ff-4c0f-9274-65b9ae1cda9e', 68, 'Episode 68', 'News of the latest Guide Dogs for the Blind Training Centre and the 3Bs Appeal Puppy Kennels.', '1977-05-12', NULL, NULL, '2026-04-03T17:21:53Z', '2026-04-03T17:21:53Z');
