INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('d4df64e0-8912-4ef6-8dee-fe939a6f549f', '9193e795-da7c-40ec-b68f-f63aa7d5174f', 164, 'Histories & Lore: The Dragonpit', 'Varys and Qyburn recall the era when Targaryen dragons were housed in King''s Landing.', '2017-12-12', 4, '/l3seMbNJGJEZAwa3rrgGTRGTHK0.jpg', '2026-04-03T15:40:35Z', '2026-04-03T15:40:35Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('d4ed4542-9085-4726-b318-e982d8407b29', '119c16d5-1047-45ec-8242-c72a8eed423b', 12, 'Arthur Accused!', 'Arthur had a job to collect coins for Mrs. McGrady to raise money for a new dog for the Elwood City firemen, and when he left the bag of quarters where Mrs. McGrady was working, she said she never received them. While this was happening, Buster opened his detective agency, he has no idea his first job will involve Arthur. Now, it is up to Buster to solve this mystery, was Arthur the real thief?....', '1996-10-14', 13, '/254fZiTjQZA9p5iyKIhixafaYq5.jpg', '2026-04-03T17:37:55Z', '2026-04-03T17:37:55Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('d4ed5bfa-be08-4ca7-92fc-085a9de627d7', '4861ce46-9045-43c7-963f-27b4ea539804', 46, 'Episode 176', '', '1971-01-11', NULL, NULL, '2026-04-03T17:36:28Z', '2026-04-03T17:36:28Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('d4ef33c6-547d-4e0e-ac92-1e4654add4ea', 'd5383b3d-5636-4d71-b99c-b84774b4b3c6', 18, 'Pingu Gets Organized', 'There’s nobody in when Father gets home from work. The igloo is in a mess, with toys all over the floor and cooking stuff not put away. As he starts to tidy up, Pingu comes in. Father asks Pingu to put away the toys, and gets on with clearing up the cooking stuff himself. Pingu tosses all the toys into the toy box, and tells Father that he’ll go and tidy up the bedroom. While Pingu is in the bedroom Pinga arrives. She rummages in the toy box and, tossing toys out of the way, emerges with Pingu’s toy engine. She goes outside to play with it. Father is there, hanging up the washing. Pinga shows him the toy she’s got, and makes it go in a circle round herself. Pingu comes out from the bedroom and is a bit niggled to find toys left out on the floor. He puts them away, goes outside, and is even more annoyed to find Pinga with his engine. He grabs it from her, which makes Pinga distraught. Father comes over to mediate, and whispers something to Pingu. Pingu thinks this is a good idea, gives the engine back to Pinga and goes back indoors. He soon comes back out, pulling a truck full of toys, and he and Father build a ramp to slide the toys down. Pinga, meanwhile, is building with the bricks. Pingu makes a tunnel at the bottom of the ramp, and he and Father slide all sorts of toys down the ramp, but none go through the tunnel! Finally, Father rolls the engine down the ramp, and Pingu is delighted when it rolls through the tunnel. Father goes inside, and initially is not very happy when he finds the toy box on its side with the toys spilling out. However, on reflection he realises that children will always make a mess and decides not to worry about it.', '1999-12-08', 5, '/zBPY5RPw3ODwz5FWICweqMR83e4.jpg', '2026-04-03T17:22:20Z', '2026-04-03T17:22:20Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('d4f41849-da76-4910-bf81-04a78f04bb21', '9193e795-da7c-40ec-b68f-f63aa7d5174f', 64, 'Histories & Lore: The Field of Fire (Viserys Targaryen)', 'Viserys Targaryen reflects on the victory which secured Aegon I Targaryen''s domination of the Seven Kingdoms.', '2012-03-05', 3, '/yWigadZG1h1Z25GIFg7An5blbl8.jpg', '2026-04-03T15:40:35Z', '2026-04-03T15:40:35Z');
