INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('d50d6b0c-5dce-4c08-8ef4-bda5980ac597', 'd034c38d-c0c7-42b4-8876-394b63d84275', 8, 'Kiss and Tell', 'For Gretchen’s birthday, Slade surprises her with a poor man’s party of take-out food and a unique gift that leaves her speechless. Peggy and Tamra are excited to model in an OC Designer’s fashion show, but a surprise model throws Tamra for a loop. Former housewife, Lynne Curtin goes to Fernanda’s gym to workout, but when Tamra is a no-show, Fernanda shares a shocking secret.', '2011-04-24', 44, '/k1S3tv5icpMNuyYVvsjrYCS3epr.jpg', '2026-04-03T16:35:31Z', '2026-04-03T16:35:31Z');
