INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('d513cee1-2603-4d28-8fd1-68186ab719bf', 'f29f456f-8e38-49af-8808-7943977100ec', 10, 'The Butler Did It', 'Mr. Crosswire gets a robot butler, but Muffy fears Bailey may be replaced.', '2017-05-30', 13, NULL, '2026-04-03T17:38:02Z', '2026-04-03T17:38:02Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('d516be42-f994-4ae0-8f65-91731a6f363b', '45e64a15-8fc0-4e4b-a1ca-9e3f42f3634d', 2, 'Earth''s Crust', 'Don''t just go with the flow. Settle down on the crust.   Imagine a world without any crust. There would be no pies, just goopy filling, no bread, no hamburger   buns, and no you or me. That''s right. You, and every living thing we know of, live on or in the Earth''s crust.   And, living things need the Earth''s crust to survive. Let''s look at the science of the surface.   By carefully studying the Earth''s surface, scientists have discovered that the Earth is made up of gigantic   layers. At the center of the Earth, there is a core â€“ a big ball of solid metal mostly iron.   The core is surrounded by a layer of liquid iron and other minerals. We usually just call it the outer core.   The next layer, around the outer core is called the mantle. You may have seen a mantle above a fireplace.   Well, the mantle is above the Earth''s hot core places. The mantle is gooey hot nearly melted rock that   flows the way asphalt does on a hot summer day. Scientists often say that the mantle is plastic. It', '1993-09-17', 26, '/gNQSLdpNBavZE5L1S7GEmJZZXG5.jpg', '2026-04-03T17:37:20Z', '2026-04-03T17:37:20Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('d51774f1-dd51-4f2e-9dd1-1619de1d909d', 'be719633-fbf1-4df5-87e4-2da02389f497', 16, 'Road Boat', 'Neil has the Ragdoll transported on the back of a lorry through Loughborough, to reach the next canal.', '1999-05-04', 10, NULL, '2026-04-03T17:19:39Z', '2026-04-03T17:19:39Z');
