INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('d5b4b5c3-1ca3-4328-80dd-bb53494ff7af', 'f07b8794-5625-4682-aae1-e56966b4c7a8', 12, 'Off the Track', 'Ben and Leon fight over who gets to lay the last piece of train track. They get so angry that they hit each other and their fight ruins the game for everyone, including themselves. Once they realize that fighting is a bad idea, they learn what else they can do when they feel so angry that they want to hit someone. A replay of their fight shows them points where they could have stopped to talk things out.', '1996-01-30', 29, NULL, '2026-04-03T17:12:21Z', '2026-04-03T17:12:21Z');
