INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('d5dfb688-e808-4380-9acd-202adcd4b1ab', 'f593d90c-5339-42f5-9c88-5bfd48d04075', 30, 'The Big Chase', 'When Timmy drives off on the farmer''s brand new quad bike, Shaun, Bitzer and the flock have to give chase by any means available. Very soon half the animals on the farm have joined in the chase. Can the sheep rescue Timmy and return the quad bike before the farmer finds out?', '2010-07-25', NULL, '/pAnd7EIrFNFhApvkQeONuMf8alD.jpg', '2026-04-03T17:39:31Z', '2026-04-03T17:39:31Z');
