INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('d5f1d51e-b034-4aa7-8ed4-e71ba657b8e5', 'db958af4-9a9a-4533-af9b-f0ff590d1dd9', 5, 'Driving Miss Crazy', 'Danielle throws Valentina a Barbie-themed birthday party; Rachel struggles with the fact that not everyone in her family wants another baby; Teresa and her daughters go wedding veil shopping; Jennifer Aydin warns Melissa to watch out for Marge.', '2023-03-07', 44, '/2foWql5pysHFJWS1A81IfWtBIVD.jpg', '2026-04-03T16:35:19Z', '2026-04-03T16:35:19Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('d5f4a9fe-205d-40c1-94ec-f40a4729a18e', 'ffc2a75e-0ffa-4b26-b121-9b91b277594a', 25, 'Reunion (3)', 'NeNe and Cynthia discuss a possible reconciliation; when Dr. Jeff joins the women to rehash their group therapy session, NeNe breaks down in tears and opens up about her personal history.', '2015-05-10', 43, NULL, '2026-04-03T16:34:47Z', '2026-04-03T16:34:47Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('d5fb4562-c1d0-4452-bc85-69c5b6c159b4', '1996ddd8-20c9-4a30-96be-2b87fab8d17c', 11, 'To Catch a Creep (2)', 'The team tries to look harder for the ones responsible for the smear flyers. Alex learns that the girl who is susposely trying to sabatoge his election likes him. New transfer student Rob encounters Ghostwriter.', '1992-12-06', NULL, '/aSxcLg4M9jpxkTFC8Q2j8CZVv1o.jpg', '2026-04-03T17:40:28Z', '2026-04-03T17:40:28Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('d5fc0b46-e874-4c18-993d-135de7dd7b08', '99a96781-44cb-4a5c-9100-71e2a55b6b1a', 10, 'Diamonds Are a Girl''s Best Friend', 'It’s the Big 4-0 for Tamra, and everyone’s invited to celebrate aboard Simon’s new yacht. It’s drunken fun in Newport Beach as Simon surprises Tamra with a gift that has all the ladies’ tongues wagging. Quinn and Billy have been dating for three months and things are going well, but there are huge differences between them. Quinn is ready to have “the talk,” but Billy has other plans. Officially separated, Jeana contemplates divorce. But not before she enjoys the former glory of her Playboy days. Jeana is going to Glamour on, the largest celebrity autograph convention, celebrating 25 Years of Playboy. With only days until their wedding, George and Lauri are frantically caught up in preparations. But missing from the plans is Lauri’s son, Josh. Estranged for several months, Lauri really wants Josh to be part of her special day but in order for that to happen, Josh must agree to meet with a therapist.', '2008-01-15', 44, '/sqbVToEVIVudknCtNvhVGrbhyEL.jpg', '2026-04-03T16:35:30Z', '2026-04-03T16:35:30Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('d5ff50ef-0275-41e3-bbb8-476ed7ab794e', 'c73fa7f1-7ac6-44d4-ac1f-182a70d92313', 1, 'Norman Burns Up the Dancefloor', 'Norman, hiding from Lily who''s eager to dance with him at the Disco, accidentally sets fire to the Wholefish Café, trapping Bronwyn and Lion upstairs!', '2021-10-04', 10, '/yKwYnVyDwkCfrcYt2oGtt9IBomn.jpg', '2026-04-03T17:14:41Z', '2026-04-03T17:14:41Z');
