INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('d623e233-2560-4269-92f9-459ac941fd85', '6f731e6b-d3c5-4de6-84e1-7a19cb650e86', 6, 'Eye of the Tiger', 'Go undercover with the Pawn Stars when a banner from the WWII secret airborne division, The Flying Tigers, infiltrates the shop. Will Rick make a covert deal or will the mission be compromised? Then, things get messy when a 1980s Ooze-It toy seeps in. Will Chum squeeze out a good price or will it slip through his fingers? And later, Rick is muted by an unsigned illustration from the silent film era. Will he entertain a sale or will he be at a loss for words?', '2015-11-05', 21, '/uiqefh6wqFtbtjcxassWbuBWTtT.jpg', '2026-04-03T16:34:20Z', '2026-04-03T16:34:20Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('d62b4926-e769-4059-a92c-644b453c46b3', '0bbd380c-5cb8-46a6-8838-b5d60223c073', 7, 'Florence Henderson', 'The Muppet Theatre is plagued by a variety of pig-related problems, both onstage and off. First, The Bouncing Borsalino Brothers flub their act and crash through the stage floor. Backstage, Miss Piggy throws herself at an uninterested Kermit and then jealously interrupts his onstage Talk Spot, physically threatening guest star Florence Henderson, whom she thinks is horning in on her frog. The feud continues in the Panel Discussion as Florence throws pig slurs around.', '1976-10-17', 26, '/mHUqVHjYmH6a9a6YhInJ5grkWGv.jpg', '2026-04-03T17:35:24Z', '2026-04-03T17:35:24Z');
