INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('d6370dcc-1805-4828-85bc-61f6a01dfc5e', 'd920ebae-f00a-4e25-abfe-40492c74ded6', 3, 'Boats and Bros', 'As Rick and Chum continue their picking adventure in Michigan, Rick takes a gamble on a WWI helmet and a vintage RC Cola machine. Will they pop the top on the deal, or will it fall flat? Meanwhile, back at the shop, Corey goes toe-to-toe with a seller over a one-of-a-kind “Rocky III” statue. Will it be a knockout deal, or will it hit below the belt?', '2019-11-04', 42, '/AiELoFUs1PF9u2nQmJJj7NOZ25P.jpg', '2026-04-03T16:34:22Z', '2026-04-03T16:34:22Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('d639ade0-e339-4b26-a53d-0c7b37ed3275', 'f79f69a8-e591-41d0-9d4a-3d9683defbbb', 10, 'A Doppelgänger Disaster', 'Jenn and Tamra co-host a party where the ladies dress as each other. Tamra pushes Eddie to figure out his next business venture. Heather informs Gina that Shannon is talking about Gina’s relationship. Vicki brings a keg to the party, kicking off a salacious game night. Shannon confronts Heather about revealing too much about her relationship, but fingers get pointed elsewhere, leading to an abrupt end to the party.', '2023-08-09', NULL, '/77e7RVw09ol707KKlXXUBIWV2t5.jpg', '2026-04-03T16:35:35Z', '2026-04-03T16:35:35Z');
