INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('d742d9fe-ecf7-4035-a5d4-e31a1b8db3dc', '6fd9fd9d-e378-411b-94b1-76ba4bd518fe', 60, 'Episode 60', 'with Christopher Trace, Valerie Singleton and John Noakes.', '1966-04-18', NULL, NULL, '2026-04-03T17:21:48Z', '2026-04-03T17:21:48Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('d74d687f-33c7-40ac-a36f-e10608589f2c', '4d2cac0f-38fd-438b-8afa-acf43952e535', 256, 'Episode 256', 'Christopher Trace and Valerie Singleton introduce a magazine programme for younger viewers.', '1963-11-18', NULL, NULL, '2026-04-03T17:21:47Z', '2026-04-03T17:21:47Z');
