INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('d76180a2-5500-46f6-9ae4-703183d80283', '4d2cac0f-38fd-438b-8afa-acf43952e535', 155, 'Episode 155', 'For younger viewers. Introduced by Christopher Trace and Leila Williams. Including Blue Peter Alphabet: C for Cooking. Packi''s Adventures, written and drawn by Tony Hart. Blue Peter Third Birthday Surprise.', '1961-10-16', NULL, NULL, '2026-04-03T17:21:47Z', '2026-04-03T17:21:47Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('d761bdf2-c95c-4632-bd62-77c6fbc63dd1', 'bf3ffafd-7d45-4f2c-9f1b-28001bd082db', 4, 'Episode 4', 'Expedition - Thailand  Ankle-deep in mud, John, Peter and Lesley help out in the rice fields and discover a village where everyone makes special umbrellas that disintegrate at the first drop of rain!', '1974-09-19', NULL, NULL, '2026-04-03T17:21:52Z', '2026-04-03T17:21:52Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('d7639d52-d101-470d-8828-88c935788707', 'bddd6427-4f85-402c-b58c-5c18ab159704', 79, 'Episode 874', '', '1976-03-18', NULL, NULL, '2026-04-03T17:36:31Z', '2026-04-03T17:36:31Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('d76a9cf6-4612-4246-84b0-d266403e3915', '4b2a19e0-2fae-492e-bc31-f78e63d88ebc', 28, 'Houston, We Have a Deal', 'Moonwalk with the Pawn Stars when a lunar Bible from Apollo 14 lands in the shop. Will Rick make a good offer on the good word or leave it in orbit? Next, a 1930s Buck Rogers Disintegrator Gun zaps in. Will Corey laser in on a deal or will it be an atomic bust? Then, miniature samples of a 1950s kitchen cook their way in. Will Rick think the mini models mean big money or will he walk away from everything and the kitchen sink? And later, a 1950s Beetle Bailey original print marches in. Will Rick draft a deal or will he go AWOL?', '2017-01-30', 21, '/5p54YyLNcbAUgJPL2AkX10iOEtP.jpg', '2026-04-03T16:34:20Z', '2026-04-03T16:34:20Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('d773e412-97c6-47c3-9c0c-fc8561f9d578', '05c0e384-194c-4417-9f62-803eb615e409', 23, 'All about eyeglasses', 'Title number 0023. Opens with Mister Rogers arriving with a thin case of eyeglasses. Mister Rogers discusses the use of eyeglasses and Picture Picture shows how they are made. Henrietta also receives glasses from Nurse Miller.', '1968-03-20', 29, NULL, '2026-04-03T17:35:38Z', '2026-04-03T17:35:38Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('d7753222-ff23-47a2-8bc7-2f11cc399918', '7c422193-b078-49d8-81ef-f2b9f94f059d', 13, 'Goldilocks is absent from day care', 'Episode #3018', '1992-11-25', 55, NULL, '2026-04-03T17:36:39Z', '2026-04-03T17:36:39Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('d77abc6c-5a45-475a-9e75-7058ac835647', 'ecdefd77-a7ac-4344-bea1-fb1df2fd0ac9', 7, 'Running on Time', 'Bernard receives a model train, but has no tracks to see it run on. He makes a friend in someone with a large model railway, Mr. Arnold. But when Mr. Arnold finds a note from his wife saying she''s left him, can his knowledge of trains and Bernard''s watch help save their marriage?', '2001-12-04', 15, NULL, '2026-04-03T17:20:05Z', '2026-04-03T17:20:05Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('d77c585e-b6d1-4711-aaa6-e454d08e8930', 'a3a2c2fb-8276-412c-9d86-5175167be1d7', 1, 'Episode 1', 'with Valerie Singleton, John Noakes, Peter Purves', '1971-09-13', NULL, NULL, '2026-04-03T17:21:51Z', '2026-04-03T17:21:51Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('d781263d-3b2a-4a6e-a333-be0378b0d696', '54c29014-2dbd-49ff-a23f-cf4c546e0b3a', 21, 'Reunion (1)', 'Part 1 of 3. The Big Apple ladies gather for a reunion hosted by Andy Cohen. Included: Ramona is cornered about her behavior toward Kristen in Montana; Aviva addresses her use of foul language in front of children; and Carole confronts Sonja about rumors and gossip.', '2014-07-29', 60, NULL, '2026-04-03T16:35:23Z', '2026-04-03T16:35:23Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('d78b8c47-ff60-4e79-99f8-eec78bf33cd9', '6a2d2839-7106-4c3b-8906-c9b3e4bfcc8b', 1, 'Hawaii 5 Uh-Oh', 'Vicki tries to move forward when her divorce is finalized in the Season 9 opener. Also: Tamra''s gym is open for business; and Heather invites Vicki and Tamra to Hawaii for a weekend getaway, but friction develops over wardrobe choice.', '2014-04-14', 44, NULL, '2026-04-03T16:35:32Z', '2026-04-03T16:35:32Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('d7917c8f-d906-4af6-b3de-ec25650a4c7b', '913f846d-85df-4694-8dd4-0d5909f78887', 2, 'Work', 'Annie decides to build an electric motor from scratch for her science, but when the task turns out to be harder than she expected, she is prepared to give up. That is, until Plato tells her the story the Wright Brothers who worked tirelessly to make their dream of human flight a reality.', '2000-10-01', 30, NULL, '2026-04-03T17:38:35Z', '2026-04-03T17:38:35Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('d793295a-9e35-4303-bd2d-7e6ad14025fb', 'a1b69730-d225-48f2-a7e7-1d314cf3b349', 1, 'Episode 1', 'with Valerie Singleton, John Noakes, Peter Purves', '1968-09-23', NULL, NULL, '2026-04-03T17:21:49Z', '2026-04-03T17:21:49Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('d793d2ff-2d85-476a-8506-27410baee25c', 'db555b98-87d6-4cd2-b7b4-973f9206cb1e', 22, 'Reunion (2)', 'In part two of the reunion, tensions flare between Kelly and the Tres Amigas as the ladies continue their debate about what went down at Miraval, including all of the rumors that were lobbed at Kelly. Braunwyn opens up about how the show has complicated her relationship with her mother, Dr. Deb. Emotions run high as the Kelly versus Vicki feud is replayed and Kelly gets emotional about the loss of her former friend. Tamra gives updates on her family and her new business. Questions about Tamra’s true motivations as a friend turns into a heated argument between Kelly and Shannon. The group trip to Florida is brought up and Vicki surprises everyone by insisting Braunwyn and her wilder ways has “destroyed” the show she created.', '2019-12-23', 44, '/danAExZJmTSASq2KbfqGLMzGP0O.jpg', '2026-04-03T16:35:34Z', '2026-04-03T16:35:34Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('d793f998-084b-48eb-bf04-b4a1ada1d6b1', '89dd3601-0e7f-4ca9-bdf6-de9f731329e3', 5, 'Moving Parts', '', NULL, NULL, NULL, '2026-04-03T17:40:29Z', '2026-04-03T17:40:29Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('d794aa53-333f-4b82-a0ca-64b4c723b5cd', '5c1b881f-ac58-4d72-b63f-209952d4f902', 55, 'Episode 55', 'A-Z of Space  Since 1957 five planets in our solar system have been photographed and men have walked on the moon. Reg Turnill, who reported for the BBC on the space programmes, investigates what the future holds for interplanetary explorers.', '1980-03-20', NULL, NULL, '2026-04-03T17:21:54Z', '2026-04-03T17:21:54Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('d7969bd7-5686-49aa-9c1e-b6a65ef2cdb5', '70c8cb46-2494-4dd4-98f6-6bfb9b3faf73', 12, 'Backroom Brawl', 'The Pawn Stars are presented with a mysterious pocket-sized sundial believed to be from the 16th Century ... complete with a concealed secret inside. Will the gang be able to shine a light on this puzzling piece of history, or will the seller darken their day by shooting for the moon? Rick and the Old Man have a chance to buy a photo album of famed union organizer Jimmy Hoffa. Will they wheel up a deal for this item, or will it be sent back to be hidden and buried away for ever? Then later Corey and Chumlee set their sights on a rifle sharpshooting arcade game from the 60''s. Will Corey target a good price for this vintage game, or will his plan backfire?', '2010-03-01', 21, '/kdfFamPIxwbo6nhvgTGDJBdEhpt.jpg', '2026-04-03T16:34:16Z', '2026-04-03T16:34:16Z');
