INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('d7ed7942-1d33-4323-ab4c-777c7ec0a335', '227b8429-0dfd-47e4-b874-c37da20c403f', 14, 'Old Man''s Gamble', 'The Pawn Stars get a call about a 1979 KISS pinball machine - can it still "Rock ''n Roll All Nite", or will it steal Corey''s quarter and KISS the deal goodbye? Then Rick is stumped when a woman brings in a 1914 Star-note $20 bill. Will everyone walk away with new money, or will it turn out to be chump change? And when an old easy rider brings in his classic 1982 Harley Davidson Shovel-head, Chumlee decides to buy it for himself - but can he raise the cash before the Old Man sells it off.', '2009-09-27', 21, '/ywCeVJN0GvtuuSYg18rmCrmMPGp.jpg', '2026-04-03T16:34:15Z', '2026-04-03T16:34:15Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('d7f4b35c-c5ed-4daa-81b7-b84953706e4a', '10e64538-c78a-4cb0-82f9-17d14256dbac', 5, 'Land of the Lost', 'Frankie asks Reverend TimTom to find out why Mike is being distant; and Sue invites Brick to visit her at college, but she loses him after running into the handsome Abercrombie guy. Meanwhile, Axl and Hutch complain to the city about an ant infestation.', '2015-10-21', 22, '/ymtnpwe2ulpuUOpH3Mp0xXXi8nr.jpg', '2026-04-03T15:40:31Z', '2026-04-03T15:40:31Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('d7ff203f-c8a0-4ab9-b3ec-fff102803d00', 'dec4a06d-731b-41e4-8b15-374f47d1f5c7', 16, 'And Then There Were Four', 'Melissa hosts her first Envy Fashion Show while striving to prove the legitimacy of her boutique; Dolores surprises her ex-husband; Teresa contemplates her financial future; the women meet for lunch, during which Siggy plays mediator.', '2016-10-30', 43, '/l1xd6Otv1Yo1RcK6QHjsTOBHsA6.jpg', '2026-04-03T16:35:16Z', '2026-04-03T16:35:16Z');
