INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('d805e2e0-d47d-4053-b609-8039108b0edf', '876145f4-b55e-4070-b35b-893a67f88bac', 8, 'Hair Today, Gone Tomorrow', 'Margaret tries to do damage control against her Vineyard Vines Lawsuit. Jennifer’s daughter tries to convince her grandmother to accept that her uncle is gay. Meanwhile, Melissa and Joe share their baby news with their kids, and when Teresa invites all the ladies to a shopping event, Margaret and Danielle’s feud reaches new heights.', '2020-01-01', 43, '/k4pI4hfFGqCQFbwLoTv4DzBeiYi.jpg', '2026-04-03T16:35:18Z', '2026-04-03T16:35:18Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('d8067ff4-4ca7-4a3e-9341-cc487b8bf34f', 'fe19a277-aed8-44df-a4ac-fc1c4e9941b4', 10, 'Better Tardy Than Never', 'Fresh off her fight with Kandi and Kim, NeNe distances herself even further from the ladies. Kim and Kandi team up to finish the recording of "Tardy for the Party" in time for their joint birthday party where Big Papa has a BIG surprise for Kim. Shereé leaves Dwight in charge of her fashion show as she and Tania head to New York to check out her "She by Shereé" samples. Ed tells Lisa that he''s interested in working in broadcast if he doesn''t go back to the NFL. Kandi performs solo for the first time in a long time.', '2009-10-01', 43, NULL, '2026-04-03T16:34:45Z', '2026-04-03T16:34:45Z');
