INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('d8ea80dd-ad9c-461d-abaa-abc0b66b9532', '36ea3814-66b4-4986-b6ee-44559d3562c1', 6, 'The Old Lady and the Shoe', 'Phaedra, still upset with Apollo, returns home to Atlanta. Cynthia and Leon — Noelle''s dad — sit down with Noelle to tell her about "the birds and the bees". Kenya comes to the conclusion that it''s time to get her priorities straight. Due to the stress of her divorce and the never-ending rumors, Porsha is admitted to the hospital. Kandi and Todd start the lengthy process of planning their wedding.', '2013-12-08', 43, NULL, '2026-04-03T16:34:46Z', '2026-04-03T16:34:46Z');
