INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('d90fe8e2-1167-4265-846b-4570354b64cb', '32192008-7529-4677-933f-c55ea6146368', 18, 'Reunion (1)', 'While the women of Potomac gather to discuss Season 10, the topic on everyone''s mind is Wendy''s recent legal woes. Stacey is held accountable for her season of alleged loose truths. Angel confronts the women in regards to her treatment in the friend group. Tensions with Ashley boil over.', '2026-02-15', 42, NULL, '2026-04-03T16:35:42Z', '2026-04-03T16:35:42Z');
