INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('d97df1cc-768c-4999-8415-2cf8622cc637', 'a84aa42d-e738-4081-8da9-1faec0209ee9', 21, 'Worry Duty', 'Frankie is worried that Axl''s going to get his heart crushed again when his on-again/off-again girlfriend, Morgan (Alexa Vega, "Spy Kids," "Ruby & the Rockits"), re-enters his life and tries to mold him into the man she wants him to be. Meanwhile Brick learns what it means to be a mother hen when he has to watch over a baby chick for a school science project.', '2010-04-28', 22, '/uzxLVLP5k4D6bg10fOkZltjE0bG.jpg', '2026-04-03T15:40:28Z', '2026-04-03T15:40:28Z');
