INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('da13a870-622b-4d77-87f5-cad060f20e97', '319bd5d6-ff58-426f-b9da-a0bb2cb87b02', 10, 'Lakes & Ponds', 'What do you get when you have a big hole in the ground and some water? Lakes and ponds. All lakes and ponds have one thing in common – they happen when a basin, or hole, forms, and then fills with water. A glacier may grind a long gulch, volcanoes and earthquakes may make a sinkhole, or engineers may build a dam – they can be human or beaver.', '1998-02-21', 26, '/d3LgU4o9CCTPkp1huM89vezox8k.jpg', '2026-04-03T17:37:22Z', '2026-04-03T17:37:22Z');
