INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('dabf31cf-bdbd-45ae-a303-f7973c01325d', '151e88a1-9576-4bd1-b84a-c4d64c1c9fe8', 18, 'Rocky Mountain Bye', 'Kyle plans the perfect Aspen day, but tempers run hot after Erika gives her the cold shoulder. While Diana and Garcelle pick sides, Dorit finds herself caught in the middle. Crystal and Sutton go hat shopping, where flames get fanned when Lisa snubs Kathy. After tears and turmoil, the group tries to rally for a fun final night, but one woman’s after-hours behavior ruins the night for everyone.', '2022-09-14', NULL, '/dcvZdqzYN7CrzSlre0hazUWmSg4.jpg', '2026-04-03T16:34:58Z', '2026-04-03T16:34:58Z');
