INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('daca54d9-12b6-40f1-9abf-15506f49f027', '70c8cb46-2494-4dd4-98f6-6bfb9b3faf73', 18, 'Hell Week', 'The Old Man has an opportunity to buy lost footage of legendary President Franklin Delano Roosevelt. Can he muster the money for this 8mm piece of White House history or will this film end up on the cutting room floor?  Then Rick considers buying a huge antique cast iron coffee grinder from the 1800''s and a lunch box from the 1960''s. And later Corey and Chumlee are challenged to compete in a parking lot obstacle course, designed just for them by the Old Man. Erik M. Underwood guest stars in this episode.', '2010-04-19', 21, '/c7Hfokk0GOh9sCjO1qwA6PrETXj.jpg', '2026-04-03T16:34:16Z', '2026-04-03T16:34:16Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('dace3d9b-860e-47fb-bbce-53568107bffd', 'c21dbd22-5e2e-4414-bb67-750399aaf6f0', 20, 'Yankee Panky', 'The Pawn Stars get ready to rock when a man brings in an extremely rare original poster from one of Jimi Hendrix''s final performances. Will Rick play along with the seller''s asking price and make a deal, or will the negotiations hit a sour note? Then, Rick and the Old Man get revved up when a race suit worn and autographed by actor Paul Newman roars into the shop. But will a lack of official paperwork bring the deal to a screeching halt before it reaches the finish line? And later, Rick and Corey are in scoring position when a customer brings in a photo signed by three baseball Hall-of-Famers: Mickey Mantle, Willy Mays and Harmon Killebrew. Can Rick and Corey make a record breaking deal or will they strike out?', '2012-01-30', 21, NULL, '2026-04-03T16:34:17Z', '2026-04-03T16:34:17Z');
