INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('daf92e52-5351-456c-9604-129821f3d61d', '319bd5d6-ff58-426f-b9da-a0bb2cb87b02', 11, 'Smell', 'How do noses work? Objects give off tiny amounts of tiny molecules into the air. When just a few of these molecules get up your nose, they dissolve in the mucus up there. Some molecules come into contact with special receptors on what’s called your “olfactory membranes.” Each nostril has a membrane, and each membrane is only about the size of a postage stamp. The membranes hold millions of receptor cells, each of which are ready to send messages to the brain about the molecules that go up your nose.', '1998-02-28', 26, '/wbKGPtG5ADg50dkR2FbTXQHInBv.jpg', '2026-04-03T17:37:22Z', '2026-04-03T17:37:22Z');
