INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('dba85637-f69d-4907-bc5e-3028f5ec537c', '4d2cac0f-38fd-438b-8afa-acf43952e535', 241, 'Episode 241', 'Christopher Trace and Valerie Singleton introduce a magazine programme for younger viewers. Including: Owning a Pony, a Dartmoor pony finds a home and Who Built The Ark? played and sung by Steve Benbow and John Langstaff.', '1963-07-29', NULL, NULL, '2026-04-03T17:21:47Z', '2026-04-03T17:21:47Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('dbaa670b-4732-44e8-bf1d-d1873252a65f', '34674c90-410e-427c-be4d-2a6f6f865a80', 18, 'Hot and Colt', 'Take aim at the Pawn Stars when a Colt Paterson revolver pops into the shop. Believed to be a prototype of Colt''s first gun, will the guys draw up a plan to own this piece of firearms history, or does the seller''s story need a little work? Then, the Old Man relives the glory days when a 1955 GMC truck drives in. The last GMC with a classic rounded body design, does what''s under the hood live up to the iconic look? And later, life imitates art when a guy brings in an animation cel from the 1960''s cartoon "Tennessee Tuxedo and His Tales." Complete with a picture of "Chumley the Walrus," will Corey break the bank over his best friend''s namesake, or is the cel simply not suited for the shop?', '2012-07-02', 21, NULL, '2026-04-03T16:34:17Z', '2026-04-03T16:34:17Z');
