INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('dc6f0d3b-972b-4462-91a8-7e7463083bc8', 'd9973960-273b-4a92-a7da-62efe8860d09', 16, 'Reunion (3)', 'The husbands take the stage and Justin reveals shocking details about leaving the Mormon church, Robert addresses Jen and her husband, Sharrieff, and Whitney shares an update on her dad’s sobriety. Emotions come to a head when Jen opens up about cultural insensitivities within the group, leaving the women startled and confused with Jen even more hurt than before.', '2021-02-24', 42, '/5NTxk9fSEi7qmoe0G2uJ7EiPTqh.jpg', '2026-04-03T16:35:44Z', '2026-04-03T16:35:44Z');
