INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('dc71e830-3abe-4565-ac19-99197f785fd3', 'dec4a06d-731b-41e4-8b15-374f47d1f5c7', 10, 'Cut the Cancer Out', 'Emotions soar in New Jersey when Jacqueline chokes up over a special proposal and Teresa fumes during a strained family reunion. In addition, Dolores focuses on her gym business, and Melissa suggests a group getaway to Vermont.', '2016-09-18', 43, '/os7rM4MSmKo75gvGeJDV8dYQse7.jpg', '2026-04-03T16:35:16Z', '2026-04-03T16:35:16Z');
