INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('dc853bde-dc26-4f2e-befb-d55e932517b2', '9193e795-da7c-40ec-b68f-f63aa7d5174f', 158, 'Histories & Lore: House Dayne', 'The young Eddard Stark recounts the history of House Dayne, the former kings and lords of Starfall, and how they have been linked to their legendary sword Dawn, especially his last and greatest bearer, Arthur Dayne, the Sword of the Morning.', '2016-11-15', 5, '/sRjY3jvI7cBxKsWSFHcI8PUYNYZ.jpg', '2026-04-03T15:40:35Z', '2026-04-03T15:40:35Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('dc8b63b7-20d4-4a06-9322-c26258643670', 'ad4e4348-3334-4a08-8928-455d9ba524c1', 18, 'Johnny Cash', 'In honor of Johnny Cash''s appearance, the show is simulcast over country radio station WHOG, and the radio broadcast threatens to overwhelm the actual show. The head of WHOG, Big Tiny Tall Saddle, insists on making all the decisions. He refuses to let Rowlf go on, and instead schedules Grampaw McGuire and his whistling bricks. Kermit tries to run his own show, but Big Tiny is one of the toughest men alive -- when he''s annoyed, he has a habit of wrapping microphone stands around people''s necks. Fozzie is replaced by Wally Whoopie, a stand-up comedian who makes fun of the bear -- which inspires Kermit to stand up for his friend, and his show.', '1981-02-01', 26, '/bcYjGf4Na4lXbrhwkr7WthEvSUa.jpg', '2026-04-03T17:35:25Z', '2026-04-03T17:35:25Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('dc8efc33-81df-41c8-b8f2-992add8bf3b7', '8ae35fd8-5626-43d7-a1ea-0e43192d1c36', 1, 'Dudley and the Cowardly Ghost', '', NULL, 29, NULL, '2026-04-03T17:12:15Z', '2026-04-03T17:12:15Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('dc916d50-13dd-4923-b302-d407a2e3d2cf', '7eef937c-4483-42bd-bafe-263a7d4e4573', 12, 'Rocks and Rolls', 'To celebrate the founding of Walkerville, Ms. Frizzle’s class sculpts a stone likeness of its founding father, Captain Walker. As they add the finishing touches, the statue tumbles down the mountain. Ms. Frizzle turns the Bus into a huge boulder and the kids into rocks while bumping down the mountain in a desperate attempt to save the statue.', '1996-11-30', 25, '/nyG4cABBOmU0CrhX3OH6i8RDPRA.jpg', '2026-04-03T17:37:49Z', '2026-04-03T17:37:49Z');
