INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('dd017ced-64d7-4483-a350-863939bf6022', '78a02d50-e3dc-4549-844a-3cf357a32ef4', 12, 'Into the Woods', 'Despite Porsha’s recent outburst, Phaedra and Kenya want to move forward with their plans for a “glamping” trip, hoping for a weekend of bonding and unity. Meanwhile, Porsha’s feelings about Phaedra''s loyalty are tested. Cynthia meets with Matt to get to the bottom of his anger issues, but things backfire when her friendship with Kenya is put on the line. Kandi throws a surprise engagement party for Shamea, where Shereé spills some tea that puts Porsha in hot water. As the group prepares to head out on their trip, a couple of surprise guests make for a bumpy ride into the woods.', '2017-01-29', 43, '/odmL9dmQF14SdbVGkkVaNFjyu6o.jpg', '2026-04-03T16:34:48Z', '2026-04-03T16:34:48Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('dd031068-c978-4281-b31f-3c70af53ac38', 'e1ef357b-4edf-412a-a785-7060c0e33bd2', 2, 'Madeline on the Orient Express', 'Madeline, Pepito and the girls take the famed Orient Express to Istanbul to compete in the International Spelling Bee.', '1995-09-16', 30, NULL, '2026-04-03T16:34:02Z', '2026-04-03T16:34:02Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('dd0ed148-7b7e-40ca-bdf8-d563f436a803', '050d8ae1-6cc1-4018-933d-b3c3d13de856', 49, 'Episode 49', 'Tales from the Secret Annexe

The diaries of a 13-year-old girl written during the Nazi occupation of Holland, inspired millions of people all over the world. Re-live Anne Frank''s story -on the day more of her secret writings are published.', '1985-02-28', NULL, NULL, '2026-04-03T17:21:57Z', '2026-04-03T17:21:57Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('dd1686ef-880f-4695-b929-19030f1aa5c4', 'fed71eea-5d41-479c-b12a-beb733409c5c', 5, 'Enthusiastic Penelope', 'Chris helps Penelope, an overly excited penguin, learn how to control herself and make new friends.', '2014-09-19', NULL, '/lMZqWB1SjTwmBoVqJ9yO49CXNOI.jpg', '2026-04-03T17:36:48Z', '2026-04-03T17:36:48Z');
