INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('dd19fe08-256b-41cb-9228-f04eded46d20', '8bdf0ad3-a798-4d5a-b304-c7501eae6867', 5, '120 In The Shade', 'Jeana Keough, Vicki Gunvalson and Tamra Barney go to Lake Havasu for the Fourth of July, but when Jeana brings Vicki''s nemesis, Frankie, Vicki feels betrayed and refuses to speak to Jeana. Later, Ryan reveals his latest tattoo in the strangest of places, which causes Tamra to have a meltdown. Meanwhile, Gretchen Rossi vacations with her family in the Central California mountains at Bass Lake but is devastated when she gets the news that Jeff is not doing well in the hospital. Lynne Curtin prepares for her daughter, Raquel''s, upcoming 18th birthday party. An incident at her home spray-tan party tests Lynne''s patience when Raquel has a spoiled brat fit.', '2008-12-23', 44, '/gxJxu4AZCjja3vUMjZWtWG8zqY8.jpg', '2026-04-03T16:35:30Z', '2026-04-03T16:35:30Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('dd1badd5-a610-4739-a4e0-2583f91c2401', '78a02d50-e3dc-4549-844a-3cf357a32ef4', 20, 'Chateau She Did That', 'Shereé unveils Chateau Shereé at a housewarming party. At the party, things heat up when Kenya finds herself going toe-to-toe with a blast from the past. Cynthia carries the bone that Apollo''s girlfriend was a guest at Kandi and Todd''s OLG Restaurant preview. Phaedra lends a helping hand to Kandi''s former disgruntled employee. Porsha discovers a new sense of clarity in her relationship with Todd.', '2017-04-09', 43, '/cAVWrWo3qtGPY2ZjfBSS4mObTAf.jpg', '2026-04-03T16:34:48Z', '2026-04-03T16:34:48Z');
