INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('ddb4344a-be57-440b-b3e9-e09abac7e0d8', 'b1d55597-d9d2-4eee-ab95-46dbb163291a', 13, 'Pingu Plays Ice Hockey', 'Pingu, Robby and their new friend Pongi are dawdling around when they see a hockey team having a game. They decide to join in. At the first two tries they didn''t get a goal, but then on the next try, they get one. The other team is a bad loser, however, and on the final try, they play aggressively to ensure they do not win, knocking them with the putt, forcing them into corners, and so on, and they win the game. They want another game, but Pingu and his friends refuse due to the team''s bad sportsmanship and for injuring Robby as well. Them and the team then discard all their gear, and do figure skating instead, and the song called "Hand in Hand".', '1989-12-18', 5, '/lPO25bwHEFRMlYCgH7KVMKSxYdg.jpg', '2026-04-03T17:22:18Z', '2026-04-03T17:22:18Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('ddc1880b-70ff-418f-b71c-58985dc1e31d', '495d4222-b33a-46fa-8351-3265798e558b', 1, 'Skeleton on the Dunny', 'The Twist Family - Tony, his twins Pete and Linda, and Bronson have moved into the lighthouse at Port Niranda. Only the toilet is haunted by the ghost and the kids must defeat him if they ever want to use their septic system again.', '1990-04-06', 24, '/oCf4GJmAQZrURSDo9wk8aU8OKJa.jpg', '2026-04-03T17:40:40Z', '2026-04-03T17:40:40Z');
