INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('ddc7f552-527b-4e6a-97c2-b102c3bfac1e', '3fdccc2c-e563-42fb-8874-c93879cd4141', 8, 'Dangerous Deliveries', 'Every time the postman pays the Farmer a visit, Bitzer''s canine instincts get the better of him, resulting in shredded mail and and an irate farmer. Shaun decides to help out by taking on the role of Bitzer''s therapist...', '2016-09-14', NULL, '/xbkMIlHFDj17lUO3Nhigl9pWYDs.jpg', '2026-04-03T17:39:32Z', '2026-04-03T17:39:32Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('ddc8e0f1-3afb-4e50-a751-17920d19236f', '4b2a19e0-2fae-492e-bc31-f78e63d88ebc', 13, 'Hidden Pawn', 'Go all in with the Pawn Stars when a 1769 playing card with a political message shuffles into the shop. Will Rick show his hand and make a deal or will the odds be stacked against him? Then, Corey shifts gears and checks out a motorcycle that was owned by actor Dennis Hopper. Will the deal go down like "Easy Rider" or will he pump the breaks? Next, Rick lights up when an antique stained glass lamp illuminates the shop. Will he be blown away and make an offer or will he throw shade? And later, three "Charlie''s Angels" figurines sneak in. Will Corey be saying "Good morning, Angels" or will the mission be compromised?', '2016-11-14', 21, '/2ZpRXPFOXV8PlVsbIHNG6EVoBtb.jpg', '2026-04-03T16:34:20Z', '2026-04-03T16:34:20Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('ddcefd3d-ddde-4fb0-a811-4503001ea727', '27947392-39ba-45a6-b67b-fc609eb26e51', 10, 'Pontypandy Wonderland', 'It''s Christmas Eve in Pontypandy and Sarah is preparing for a Pontypandy Wonderland, but a snow machine causes problems for her and Hannah!', NULL, 10, '/kuIPxlMkjqfndxvS9EXQerVNsFl.jpg', '2026-04-03T17:14:41Z', '2026-04-03T17:14:41Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('ddd39f34-363f-4774-b807-5da97c6bb590', '151e88a1-9576-4bd1-b84a-c4d64c1c9fe8', 21, 'Not My Sister''s Keeper', 'Garcelle celebrates her success with a big party and makes an even bigger purchase with some encouragement from Sutton and Crystal. Lisa’s refusal to accept Kathy’s apology leaves Kyle holding the bag for her sister. As the ladies are draped in diamonds at Kyle’s charity gala, stories swirl in the tabloids and Dorit wonders if there is a leak in their circle. Erika and Lisa continue to call out Kathy, leaving Kyle to question if any of her friends can truly be trusted.', '2022-10-05', NULL, '/qwnrHT06sDxyuzDGiSfc1AU7Qkm.jpg', '2026-04-03T16:34:58Z', '2026-04-03T16:34:58Z');
