INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('de5e780b-4dbf-4178-937d-487bc08f7da0', 'd034c38d-c0c7-42b4-8876-394b63d84275', 1, 'Amped Blondes and Evil Eyes', 'Season 6 begins with Tamra organizing a shopping party. She invites all the ladies in an effort to be more social, but the drama heightens when a boozy Gretchen misbehaves and calls Tamra an Evil Bitch.', '2011-03-06', 44, '/oWR8qpM0r8WY3a5UZiix16s8UFU.jpg', '2026-04-03T16:35:31Z', '2026-04-03T16:35:31Z');
