INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('de6fd270-dd46-49b2-98d6-2e516e6b7e14', '363a94f9-e0e5-441c-aa86-2be2e9832da1', 2, 'When Pawns Cry', 'When an early handheld video game system comes into play, will Corey be able to make a deal before it''s game over? Then, a seller brings Rick a tambourine once played by Prince. Will the negotiation have Rick partying like it''s 1999, or will doves not be the only ones crying? Next, Corey checks out a baseball roster signed by Ty Cobb. Is this a peach of an item, or a swing and a miss? And when a program for a silent film hits the counter, Rick and Chum reminisce about their trip to Italy. Will Corey''s jealousy get the better of him, or will he be able to expresso his feelings?', '2021-10-09', 42, '/gQ6dwaqohOlBFpZkbI8jzJy92r8.jpg', '2026-04-03T16:34:23Z', '2026-04-03T16:34:23Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('de71e022-3d81-424e-8e89-bfbf8e06d2d3', '87f84063-82b3-45a4-936c-3759e5d91ce3', 4, 'Friendship Roulette', 'All bets are off when the ladies are invited to a casino-themed fundraiser; Mary is nervous to see Jen, Meredith gets a vampire facial, and Whitney and Lisa clash when Lisa is accused of sabotaging the party.', '2021-10-03', 44, '/m9l8yI302JCkKabWGR8BftFLuPE.jpg', '2026-04-03T16:35:44Z', '2026-04-03T16:35:44Z');
