INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('deaec839-8641-42a5-9627-403006825b76', 'e48599f8-66ff-4c0f-9274-65b9ae1cda9e', 39, 'Episode 39', 'Jack and Jill, Blue Peter''s twin tabbies, celebrate their first birthday on Saturday. Today you can see a flashback of their very first TV appearance.', '1977-01-27', NULL, NULL, '2026-04-03T17:21:53Z', '2026-04-03T17:21:53Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('deaef5b2-611f-4f86-b3fa-b5b4dcd5abce', '87989283-6fea-40d7-8d91-22c4947db105', 3, 'Lonely in Flagstaff', 'Meri returns to Flagstaff but still feels alone. When she meets the other Sister Wives for lunch, old tensions bubble to the surface. Meanwhile Kody has a plan to reunite the family.', '2020-01-12', NULL, NULL, '2026-04-03T16:34:31Z', '2026-04-03T16:34:31Z');
