INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('debde73d-c0a3-48c8-891c-6e3aaafe3c8e', 'f593d90c-5339-42f5-9c88-5bfd48d04075', 31, 'The Magpie', 'A magpie has nested in the big tree and is causing chaos by stealing everything around the farm. The magpie''s nest soon begins to fill up with loot and Shaun has to come up with a brilliant plan to outwit the burgling bird.', '2010-06-13', NULL, '/gB2zTHHAjvxqc9mfFgV6qCu6ji.jpg', '2026-04-03T17:39:31Z', '2026-04-03T17:39:31Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('debeccf8-5bb5-4878-8619-2f9b25bab696', 'd1d267dd-e27f-4543-acb8-0d28f676512a', 19, 'Episode 19', 'with Valerie Singleton and John Noakes', '1967-11-30', NULL, NULL, '2026-04-03T17:21:49Z', '2026-04-03T17:21:49Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('dec23e41-cd4a-45b5-90d3-2a6ef1a403d1', '4861ce46-9045-43c7-963f-27b4ea539804', 117, 'Episode 247', '', '1971-04-20', NULL, NULL, '2026-04-03T17:36:29Z', '2026-04-03T17:36:29Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('dec31bbc-9dbb-47fe-a4af-c28785969ce9', '22beba7f-9b8e-4563-93da-46e76ecba427', 24, 'Gina Adopts A Baby (3)', 'Snuffy and Big Bird want to play with Marco, so they bring over a wagon filled with baseball equipment, rollerskates, a pogo stick, and checkers. Gina tells them the baby is too young to play with any of those things and suggests that they think like babies to come up with games everyone can play together.', '2006-11-14', NULL, '/i91oBYnc2qQKZhOyMSDzEuFxcYr.jpg', '2026-04-03T17:36:44Z', '2026-04-03T17:36:44Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('dec647ee-d573-45a4-bc5a-6c4ec5cee30b', '050d8ae1-6cc1-4018-933d-b3c3d13de856', 16, 'Episode 16', 'Gripped Up With Zoe.

Hair-raising stunts, acrobatics and trampolining are all in a day''s work for Michael, but one thing Blue Peter''s new action man has never attempted is rock climbing.

Zoe Brown of Old Man of Hoy fame starts Michael off on his climbing career with lots of useful tips for other beginners.', '1984-11-01', NULL, NULL, '2026-04-03T17:21:57Z', '2026-04-03T17:21:57Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('dec6bfd1-fd18-4f85-9682-18009653dd57', 'f1325b56-44e0-4b6e-89bc-82cac30afea6', 5, 'Elvis In Concert', 'Pontypandy is holding a Charity Concert and Elvis is to be the star act. Mike and Elvis have got a giant wooden guitar, but they fail to see a cliff and Mike ends up falling down, clinging onto it.', '2012-04-14', 10, '/eqgc1WGXRHMS7ksdc5jB1OSFIU.jpg', '2026-04-03T17:14:39Z', '2026-04-03T17:14:39Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('dec910da-d5df-4f4a-bbf6-581b9c64ef52', '5ba20443-d99f-4820-81f6-6832d3f2bc4f', 4, 'Earthquakes', 'Earthquakes happen when pieces of land in the Earth’s crust scrape together. The crust of the Earth is made of big slabs of land called plates that are constantly moving just a little bit. The plates scrape by one another, and sometimes they don’t move smoothly. An earthquake happens when the plates get unstuck suddenly and jerkily slip past each other. The majority of earthquakes occur along plate boundaries such as the boundary between the Pacific Plate and the North American plate. One of the most active plate boundaries for earthquakes is the massive Pacific Plate commonly referred to as the Pacific Ring of Fire. The fire comes from the volcanoes that form near the edge of the plates.', '1995-11-24', 26, '/38rO4Avkyapnt7P793vQJaGAobt.jpg', '2026-04-03T17:37:21Z', '2026-04-03T17:37:21Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('decd91d1-571c-42eb-9b74-0f02dd6ba2dc', '02849455-d14b-476b-9603-eef5fb5d2ab3', 17, 'Hot Gossip, Cold Pizza', 'Karen meets with her assistant Matt to find out his involvement in the alleged rumors regarding her living situation. Ashley finally comes clean to her mother about some of Michael’s inflammatory comments, causing more tension between the two. Determined to find out the truth about whether Karen really lives in her house, Gizelle, Robyn and Ashley plan a scheme of epic proportions.', '2018-07-29', 42, '/znXikPmOmQA1mP2emXkfhSzR6DS.jpg', '2026-04-03T16:35:39Z', '2026-04-03T16:35:39Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('ded07503-3cc8-487a-b838-3fa1dea688c0', '4d2cac0f-38fd-438b-8afa-acf43952e535', 318, 'Episode 318', 'with Christopher Trace and Valerie Singleton.', '1964-12-10', NULL, NULL, '2026-04-03T17:21:47Z', '2026-04-03T17:21:47Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('ded4796e-058d-46e7-baf0-fd9505071e95', '939d270c-ea8e-4cc8-a5a5-e59df2c8062c', 14, 'Reunion (2)', 'Caroline Stanbury and Lesa dig their heels in the sand and hash out their issues; Ayan reveals more of herself and opens up about her childhood trauma; the ladies exchange gifts to show each other what they think about one another.', '2022-09-07', 44, '/nP9uEftlZAfIcW8FrJCrSP4rl6m.jpg', '2026-04-03T16:35:07Z', '2026-04-03T16:35:07Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('dedfb32d-050e-47a2-a8aa-6770d92baf6d', '5c1b881f-ac58-4d72-b63f-209952d4f902', 65, 'Episode 65', 'The Rochdale Pioneers  It''s hard to imagine life without supermarkets and nowadays we take clean shops and clearly-marked prices and weights for granted. But 130 years ago finding a shop you could trust was very difficult indeed - until a group of writers in Rochdale started Britain''s first co-op.', '1980-04-28', NULL, NULL, '2026-04-03T17:21:54Z', '2026-04-03T17:21:54Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('dedff9bc-93e0-45d1-aa2b-b5a747c4d6f0', 'b892884d-7b56-4255-a4c6-08f5d0122273', 8, 'Rock and Mineral', '', '1996-10-21', 29, '/y7W4e4O5ZdRPu6bG1tzsuGqQdO0.jpg', '2026-04-03T17:39:04Z', '2026-04-03T17:39:04Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('dee2dd96-80c6-4ac7-ae71-bea453f589f2', '4b2a19e0-2fae-492e-bc31-f78e63d88ebc', 17, 'Gotham Pawn', 'Save the day with the Pawn Stars when limited edition Batman and Joker Bolin Guitars swoop into the shop. Will Corey be the superhero and make a deal or will he become the villain? Next, a bronze sculpture by M.L. Snowden molds its way in. Will Rick carve up an offer or will the art go unappreciated? Then, a pair of signed Betty Crocker letters get Rick cooking. Will he make a delicious deal or will he find it unappetizing? And later, a WWII era Adolf Hitler pincushion pokes in. Will Corey take a stab at a sale or will his offer be offensive?', '2016-12-12', 21, NULL, '2026-04-03T16:34:20Z', '2026-04-03T16:34:20Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('def62741-a6db-4deb-8c18-b1641927edd5', 'a4843a51-aeef-427c-902c-7fb3bd670cd4', 7, 'Why Bears Can''t Fly', 'Pip and Pop invite Bear to the Otter Pond for a game of catch, but he keeps getting distracted by other events in the Big Blue House. Ojo and Treelo are pretending to fly and it gets Bear thinking about gravity and things that fly. When Ojo takes a fall and hurts herself, however, after trying to fly for real, Bear has to tell her that bears and kids can''t fly, no matter how hard they try. He also helps Tutter to use gravity to get eggs into his mouse hole. In the Shadow segment, Shadow retells the story of Humpty Dumpty.  Songs  Gravity (Music and Lyrics by David Yazbek)', '1997-10-28', 25, NULL, '2026-04-03T17:35:31Z', '2026-04-03T17:35:31Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('df00ca0d-e81e-404a-a446-3a936e6432e1', 'd391db30-fad9-43af-b35c-e22468ff88b4', 13, 'Episode 13', '', '1999-03-30', 25, NULL, '2026-04-03T17:21:18Z', '2026-04-03T17:21:18Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('df04d002-6cf2-418f-bff9-129e7f837bb3', 'f760505e-28a1-4d38-964d-5a2617b5b402', 6, 'Monster', 'From Medusa to Dracula, all cultures have their monsters! In this exciting DVD, students learn what makes things scary and build an understanding of the universal presence of mythical creatures, such as vampires and dragons. Explorer the science behind many myths, identify viruses and bacteria, and uncover our love/hate relationship with monsters of all types, from mosquitoes to dragons.', '1997-09-29', 29, '/mdMxQQGaCfkTQMfmzt6EOPJhcv5.jpg', '2026-04-03T17:39:04Z', '2026-04-03T17:39:04Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('df054cb5-94b3-439b-8796-798ab65656a9', 'ba33491a-8f19-4e61-ae9f-0a67db3c65b0', 3, 'Stand in Your Truth', 'Robyn loses her cool with Wendy and accuses her of being phony when it comes to Mia''s alleged health scare; Gizelle''s allegations against Chris leave Candiace furious; Robyn asks Juan for a prenup, but things don''t go as planned.', '2022-10-23', 44, '/oF14heaENhSh73TKP4AgrBK1ptu.jpg', '2026-04-03T16:35:40Z', '2026-04-03T16:35:40Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('df0a6b8a-3cf6-4ef4-99f0-7ca24b7b5df4', '42b5a684-5208-4f8f-919a-f981b968630f', 4, 'Step by Step', 'Leona and Lionel have discovered what appears to be a treasure map and a set of directions that Barnaby B. Busterfield III left behind.  It''s off on a treasure hunt for the lions and pigeons.', '2003-09-18', 30, NULL, '2026-04-03T17:12:28Z', '2026-04-03T17:12:28Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('df0c386f-14d2-435e-9e8f-7a5b88a71fa9', '24003c6d-d919-4616-a7dd-0d38bb7a0656', 11, 'Making Pizza', 'Pat visits Gourmet Pizza Company in Oxford.', '1996-06-28', 10, NULL, '2026-04-03T17:19:37Z', '2026-04-03T17:19:37Z');
