INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('df125c7a-be71-4c3d-8e96-63ae2dafb563', '487fdbcd-ec5a-454e-8268-b50566eb8546', 8, 'The Sisterhood of the Traveling Voice Note', 'Still reeling from Caroline Stanbury''s housewarming, the ladies jet off to Bali, but one of the ladies is missing in action; Caroline Stanbury decides to drop a bombshell to the group.', '2024-07-23', 43, '/iu86IDsQ3znLxYoEm21js5eqTK1.jpg', '2026-04-03T16:35:07Z', '2026-04-03T16:35:07Z');
