INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('df300ef5-e8e3-4783-85af-b8032331f37b', '27d0351a-92f5-4d01-995c-6b5928957075', 10, 'High Heels in the High Seas', 'The chaos on the high seas continues as designer shoes end up overboard; pushed to her limit, Lisa reconsiders her friendship with Jen; the ladies get ready for a luau dinner, but tensions come to an all-time high when the women throw shots.', '2022-12-07', 44, '/61Cx9FfZyEkYZNUgeY7RDwX76pG.jpg', '2026-04-03T16:35:44Z', '2026-04-03T16:35:44Z');
