INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('df36dfce-d26f-41b6-8805-8b14aea4a360', '9c9d89df-5f6b-41d0-84c6-b8ca7bd2a2e6', 18, 'Fort Rudy', 'Elmo and Rudy are having a sleepover and building a pillow fort  but they don''t have a pillow big enough for the roof. This is a problem! They wonder what they can use to build a strong and sturdy roof. What if they use a blanket and weigh it down with heavy books so it doesn''t fall down? Let''s try! It works. Elmo and Rudy didn''t give up and built a pillow fort. Let the sleepover begin!', '2022-03-10', NULL, '/ZH0T5Zb9n8D9EySwHcd6sggpkM.jpg', '2026-04-03T17:36:50Z', '2026-04-03T17:36:50Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('df410885-7ade-41df-a5a7-d416cc1f3b91', '1d556682-d9bb-47e1-993f-0b648a8daacd', 3, 'Episode 1188', 'Sponsored by R, T, 4.', '1978-11-29', NULL, NULL, '2026-04-03T17:36:32Z', '2026-04-03T17:36:32Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('df458749-a65e-4bc6-b9cf-0da178efc628', 'e4023da2-33d7-4a2b-a04a-ca449bd23935', 7, 'Thanksgiving VI', 'Thanksgiving for the Hecks at a local restaurant buffet doesn''t go well when Sue feels that Mike doesn''t like her boyfriend, Darrin, and Brick invites his quirky girlfriend, Cindy.', '2014-11-19', 22, '/bodWbom1Tdo72Bduj8wuxa90ofD.jpg', '2026-04-03T15:40:30Z', '2026-04-03T15:40:30Z');
