INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('df4b694d-8bfd-4b4d-812b-19ed0b3ddbff', '79c64e0a-3488-41bc-9b5c-2243ff15b373', 19, 'Episode 19', '', NULL, NULL, NULL, '2026-04-03T16:34:59Z', '2026-04-03T16:34:59Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('df50c971-15ee-4bcf-9c45-ad6aa6f8d5f6', '23c93536-610c-41c5-ac6b-a6b243423258', 11, 'Secrets of the Love Lagoon', 'Stacey gets some heat for her relationship with TJ. Wendy makes a grand invitation to continue her 40th festivities in Panama. Karen hosts a "Love Lagoon" party at her home – full of risqué questions, unexpected answers and one uninvited guest with eight uninvited balloons.', '2024-12-15', 43, NULL, '2026-04-03T16:35:41Z', '2026-04-03T16:35:41Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('df5281ba-df84-45be-81ba-0ad19a157fdb', 'f4c40307-9b5e-4263-a4e0-dfa138131e7f', 68, 'A Magical Halloween Adventure', 'Boo, Creak, Ahh, Shriek! Halloween is the time of jack-o-lanterns, dressing-up, and lots of silliness on Sesame Street. It''s a Halloween extravaganza when the monsters from Sesame Street get invited to a Tricks & Treats party. But when Mumford the Magician has some trouble with his magic wand, Elmo and friends get sidetracked on a wonderful hayride. Share in the surprises as they learn to carve pumpkins, make scarecrows, and discover that monsters don''t really have to be scary! Features special guest star Caroline Rhea as Gilda the Great!', NULL, NULL, NULL, '2026-04-03T17:36:27Z', '2026-04-03T17:36:27Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('df5293dc-5266-425b-9d52-558329e9f605', '119c16d5-1047-45ec-8242-c72a8eed423b', 26, 'Buster''s New Friend', 'Arthur is lonely when Buster starts spending time with a new super-cool friend named Mike.', '1996-10-23', 13, NULL, '2026-04-03T17:37:55Z', '2026-04-03T17:37:55Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('df54c6bf-b2a3-4a05-8d23-9978728c8e2e', '04e133fd-c4a3-4dfa-8369-c6dcfd1e3a5a', 106, 'Trumpet Afternoon', 'Ernie blows his trumpet, creating loud and sometimes off-key notes that bother the residents. Various characters react to the trumpet sounds throughout the afternoon. Despite the noise challenges, the episode celebrates music and Ernie''s enthusiasm for his instrument.

Sponsors: I, N, 10', '1985-04-15', NULL, NULL, '2026-04-03T17:36:36Z', '2026-04-03T17:36:36Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('df5c302c-9706-44ce-8fe2-6fcd631f240d', 'ebc99729-ccb7-4d64-82c1-42708cd7ba85', 49, 'Episode 49', '', '1981-02-26', NULL, NULL, '2026-04-03T17:21:55Z', '2026-04-03T17:21:55Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('df600291-9732-4945-a1c6-4b2ce8118d02', 'e40e6b63-9f84-449f-8e88-53209b0906c8', 19, 'Zoe and Rosita Find Abby''s Magic Wand', 'While pretending to be leaping elephants, Zoe and Rosita encounter a mysterious object lying on a crate. Rosita thinks it looks like a popsicle stick, but Zoe remembers where she''s seen it: it''s Abby Cadabby''s magic wand! Rosita wonders what it would be like to be a fairy god-monster and do wonderful magical things for everyone every day - but Zoe advises her against waving the wand, because she''s not a fairy god-monster.', '2007-09-26', NULL, '/l10jqWq3q5AlJSLXkkj1nu7lYMy.jpg', '2026-04-03T17:36:45Z', '2026-04-03T17:36:45Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('df634e47-9cd0-4a0b-a99b-131e8e019438', 'd123fd65-efb7-4ebb-a23e-190c447791cf', 4, 'It''s Your Party and I''ll Cry if I Want To', 'Julia and Guerdy share shocking revelations about their past; Larsa goes house hunting; Adriana receives a foot massage that rubs Martina the wrong way; the ladies celebrate Julia''s birthday, but Adriana and Guerdy come to blows.', '2021-12-30', 44, '/bqkyqql8hukFOim8qW57W2TbmX5.jpg', '2026-04-03T16:35:11Z', '2026-04-03T16:35:11Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('df680ee1-85c8-4203-94ed-26f638313b72', '1a8f02c5-f727-4ce3-9bb2-5946d236e47c', 4, 'Chapter Four: Sorcerer', 'The military tightens its grip on the town. Mike, Lucas and Robin orchestrate a daring escape. El comes face-to-face with the enemy.', '2025-11-26', 87, '/r0uVKBsPj74lQGNRdC9IM2P5roW.jpg', '2026-04-03T15:40:40Z', '2026-04-03T15:40:40Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('df682ae8-b6d2-474c-a0b4-d9aaa32a13a8', 'c06f15e3-1abd-4c6c-a4ef-93f3eb85cc89', 5, 'The Wolf and the Lion', 'Catelyn has captured Tyrion and plans to bring him to her sister, Lysa Arryn, at The Vale, to be tried for his, supposed, crimes against Bran. Robert plans to have Daenerys killed, but Eddard refuses to be a part of it and quits.', '2011-05-15', 55, '/u7e1qSWE6v8jfY9vGNrckX47DGN.jpg', '2026-04-03T15:40:35Z', '2026-04-03T15:40:35Z');
