INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('df76ee96-ec87-4c08-a545-13d2f618eadb', '22beba7f-9b8e-4563-93da-46e76ecba427', 15, 'Baby Bear''s Great Invention!', 'On a very busy day at Hooper''s store, Baby Bear decides to create an automatic lemonade-pouring machine to help Miles out. He draws up the plans for his invention and then recruits Telly and Elmo to help build it.', '2006-09-13', NULL, '/cBc12SzXR1gluvYFtKLveJHVI7b.jpg', '2026-04-03T17:36:44Z', '2026-04-03T17:36:44Z');
