INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('df7aa575-84ad-41c0-9950-006c6169aba9', '3f470ec5-a182-4b57-a572-e18864f7f1ea', 6, 'Episode 6', '', '1990-03-20', 25, NULL, '2026-04-03T17:21:15Z', '2026-04-03T17:21:15Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('df83e5da-9d6c-4ea3-8f6c-4e8dd3da05f1', '7bc54df3-f32a-454e-aef6-a9436c35d53b', 36, 'Death of a Goldfish', 'A fish in Rogers'' tank has died. Rogers buries it and, with Bob Trow''s help, constructs a tombstone with a pentagon that bears a fish drawing. In the Neighborhood of Make-Believe, concern hits when the Trolley stops at the Castle and doesn''t move. Eventually, with help from Bill Platypus, they find out that the Trolley simply suffered a derailment, preventing full electrical pickup (as explained earlier by Mister Rogers).', '1970-03-23', NULL, NULL, '2026-04-03T17:35:39Z', '2026-04-03T17:35:39Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('df8c5fdb-b0be-40ce-a947-b0c577c884b6', '1c9ea7d3-e254-4e7b-8a9f-33eea9c6c341', 9, 'A Whine of a Time', 'The ladies head to Canada to partake in the annual Toronto Carnival but before the festivities can get started, Porsha gets a few things off her chest after Kandi reveals that Eva has not been the loyal friend she claims to be. Riding high off her recent engagement, Cynthia wonders whether or not Kenya purposely tried to ruin Mike’s proposal. In the aftermath of their recent triple date, Kenya reveals that things with Marc have not improved. As the ladies settle into their first night in Toronto, a surprise guest shows up!', '2019-12-29', 43, NULL, '2026-04-03T16:34:49Z', '2026-04-03T16:34:49Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('df903357-12ea-4354-95d9-112ac8e78890', '05fa5e18-78d2-41fe-ae30-0c242c7ffb6a', 5, 'Bathtime for Dusty', 'Scruffy dog Dusty is chosen to be the fire station mascot, but first he must have a bath. Dusty is not keen on the idea, though.', '2003-04-04', 10, '/eqo7D6Oa0pEZhx1qFwxYq6bRvjM.jpg', '2026-04-03T17:14:38Z', '2026-04-03T17:14:38Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('df9b4d91-0111-4aed-a00d-6bd0606b6eef', 'dbde6570-a68d-4fd7-a1b0-a6037a266a18', 11, 'What''s New Pussy Cat', 'Heather goes for an audition but is torn about being a working actress and raising four children simultaneously. Alexis is set to hire a coach to help her dreams of being a television host.', '2012-04-24', 44, NULL, '2026-04-03T16:35:31Z', '2026-04-03T16:35:31Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('df9ce2fd-029f-406e-9b82-272d5e9f4e64', 'd01919fb-98e0-42bf-b9d9-1cecf912f6e1', 50, 'Zoe''s Zoemobile Delivery Service (3835)', '', '1999-03-26', NULL, NULL, '2026-04-03T17:36:42Z', '2026-04-03T17:36:42Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('dfa24f1c-299d-4d39-81f1-4cd3cc1f76aa', '34bdccfa-3c14-4e1c-9148-85c29aadc0e1', 13, 'Weird Creatures', 'Weirdness is in the eye of the beholder, or the species.  This Chris and Martin learn when they go searching for what they think is the ultimate in weirdness: egg-laying mammals.', '1996-06-19', 30, NULL, '2026-04-03T17:11:47Z', '2026-04-03T17:11:47Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('dfa283d0-898c-4446-b31d-313ae3dc5cd7', '45e01c04-6ac6-41e1-87d8-f749ee230385', 30, 'Episode 30', '', NULL, NULL, NULL, '2026-04-03T17:14:38Z', '2026-04-03T17:14:38Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('dfa2fb32-a926-4562-b21c-1baf6ec1e237', '4060ad7f-4b8f-4393-8eb1-66a150b928b6', 11, 'Tough Monster Race', 'Elmo, Abby, Grover, and Nina want to make an obstacle course on Sesame Street. But they don’t have anything to go over, under, around, or through. They wonder what they can find around them to make these obstacles. What if they use a broom to go over, a blanket to go under, pool noodles to go around, and a cardboard box to go through? It works! The friends made the best monster obstacle course ever.', '2021-01-21', 26, '/xi0o6FuEHxOZfzgPy5R5DLmTgde.jpg', '2026-04-03T17:36:50Z', '2026-04-03T17:36:50Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('dfa3129a-ca53-4fc4-ba88-50099627de9b', '69b3befe-579a-43ad-a7d6-ec30ffe3adf7', 15, 'Episode 1070', '', NULL, NULL, NULL, '2026-04-03T17:36:32Z', '2026-04-03T17:36:32Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('dfa64da9-864a-44d7-9b6c-857d0d1ec1cb', '4fe93658-c463-4329-8e64-9d523869c2cb', 18, 'Houdini''s Handcuffs', 'The Pawn Stars work their magic when they''re presented with handcuffs and leg shackles once owned by the legendary magician Harry Houdini. Will a sleight of hand help them unlock an amazing deal or will everything disappear in a puff of smoke? Then, a seller rushes in with a Vince Lombardi Super Bowl Trophy from the 1999 St. Louis Rams. Will Rick and Chumlee throw a Hail Mary for the game-winning touchdown or will a bad negotiation force a fumble? And later, Corey and Chum come across a collection of comic buttons found inside Pep cereal in the 1940''s. Will this old nutritious breakfast give the boys an edge or will they find it''s all too much to stomach?', '2011-01-17', 21, '/jcr11ZuzHXAxPWRmHLR5SvGExWv.jpg', '2026-04-03T16:34:16Z', '2026-04-03T16:34:16Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('dfa986ec-5d35-421d-8261-d65eefb684dc', 'bb919aec-0d5c-4c58-9a5a-fa2a0a5de2b6', 86, 'Episode 491', '', '1973-03-26', NULL, NULL, '2026-04-03T17:36:30Z', '2026-04-03T17:36:30Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('dfb1070e-214a-4c32-8833-5c241168b78d', '5ba20443-d99f-4820-81f6-6832d3f2bc4f', 16, 'Heart', 'Your heart pumps your blood around your body, all hours, every day of the week, to keep you alive. Your heart is about the size of your fist, and it’s made of special muscle called “cardiac” (KAR-dee-ak) muscle.

Cardiac muscle lets your heart keep the beat, it can also speed up or slow down, depending on what your body needs. Your heart works like an automatic pump – it squeezes, or contracts, and un-squeezes, or relaxes, to push blood through the four different sections of your heart. Valves, special one-way openings, are like little doors between the sections – making sure your blood moves in only one direction through your heart, to your lungs, back to your heart, and then around your body again.', '1996-02-14', 26, '/d5vCggoMSmWGd7bLUTgeSoBvXdJ.jpg', '2026-04-03T17:37:21Z', '2026-04-03T17:37:21Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('dfb25f99-6f19-4bdd-8b14-d5c4de0947f8', 'f13cb622-84e3-4654-a8f1-0ceab09a9ca6', 10, 'Franklin''s Bargain', 'When Bear buys a neat detective kit at Mr. Mole''s shop, Franklin is disappointed to learn that they''re all sold out, but Bear tells him that he can get a "Super Snooper Spy Kit," however, he''ll have to get it before it''s sold out. Franklin checks his savings and finds that he doesn''t have enough money. Hoping to earn the money, he decides to strike a bargain with his Dad to get it by doing an extra chore. He first deals around doing the dishes and then fails keep up his end of the bargain after agreeing to a different chore.', '2002-05-27', 12, NULL, '2026-04-03T17:40:16Z', '2026-04-03T17:40:16Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('dfb29fd4-c7ed-45ee-b175-d77f2aa37042', '204d86fb-d99c-4fd1-8dcd-9c1bcfd3c33f', 47, 'Puzzlewood', 'Emmy and the dragons discover getting lost can be fun when they have to put their heads together to find a way out of the Puzzlewood forest.', '2002-04-12', NULL, NULL, '2026-04-03T15:26:04Z', '2026-04-03T15:26:04Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('dfb46e71-00df-4e0e-a43f-c01f0d928550', 'bcab920a-51a5-4cbb-aa59-41578a0eb005', 7, 'It''s Expensive to Be Me', 'After her explosive encounter with Kim at Kyle’s game night, Lisa Rinna vents to Eden. Erika records the music video for her new song before jetting off to Mykonos, Greece, with Kyle. Lisa Vanderpump’s son Max begins a quest to find his biological parents, while Dorit tries to find common ground with Lisa Rinna and Eileen.', '2017-01-17', 43, '/u9ix1RWnsgdB4d3Rey6q2U8rtvk.jpg', '2026-04-03T16:34:56Z', '2026-04-03T16:34:56Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('dfc00a46-e8b2-4509-ae95-ec81c4a08fa3', '42991e93-ef88-413f-b7e3-0333f9e7ab36', 6, 'Cleaning', '', '1994-10-27', NULL, NULL, '2026-04-03T17:19:30Z', '2026-04-03T17:19:30Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('dfc3ec3c-8c9d-4655-9944-bc760bb282e9', '97a3d1f5-a8f1-47cd-8122-2e74a092836d', 20, 'Who is Max Mouse? (4)', 'The team challenges Max Mouse to a game of ghost while Ghostwriter heads through cyberspace to finally catch it. Ghostwriter gets the phone number of Max Mouse, and they learn who she is: Janice.  She said she did all of the things because she wanted attention.', '1994-01-16', NULL, NULL, '2026-04-03T17:40:28Z', '2026-04-03T17:40:28Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('dfc44cc9-46ab-4d2d-9df0-abcedde80161', 'db958af4-9a9a-4533-af9b-f0ff590d1dd9', 14, 'Rat in the Street', 'The Catanias go out for a celebratory family dinner, Paul and Brittany included; Frank continues to poke at Paul as Paul hints there may be more than just one wedding in the group''s near future; Rachel and John share big news with Jaiden.', '2023-05-09', 44, '/hJ0XZuZnttLrZ8vljIgYR2Eo8zv.jpg', '2026-04-03T16:35:19Z', '2026-04-03T16:35:19Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('dfc46e07-c98d-49fe-85ef-aa217bc9f67d', '6fedba82-52f3-4184-be77-6b26e556cd0e', 25, 'Paddington Hits the Jackpot', 'Paddington is a contestant on quiz show ''Lucky For Some''.', '1976-05-13', NULL, NULL, '2026-04-03T17:22:52Z', '2026-04-03T17:22:52Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('dfcafd41-c41f-433d-9939-af13de227b0a', '10e64538-c78a-4cb0-82f9-17d14256dbac', 3, 'The Shirt', 'Frankie is shocked when Mike trades in his flannel for a Hawaiian shirt. Sue accidentally tells Devin that Axl loves her, leading Devin to question their relationship. Brick gets overambitious while cleaning the bathroom.', '2015-10-07', 22, '/dsduoxSPDjYXR7wfDJdkhNtBTgd.jpg', '2026-04-03T15:40:31Z', '2026-04-03T15:40:31Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('dfcb659e-094c-49f2-9a32-23a67fc5e1ce', '5062ce29-8dbb-48ab-879b-0771221678d5', 7, 'The Owl''s Lesson', 'Owl discovers a little bird who doesn''t know how to fly, so she attempts to teach him. Then Percy comes along and explains he can''t fly because he''s only little, which Owl doesn''t know.', '1999-10-31', 15, NULL, '2026-04-03T17:19:02Z', '2026-04-03T17:19:02Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('dfcc9167-3808-48fd-b476-c0febacc9b58', '9d74600d-7222-47c1-bd1b-635f5b41b7d1', 8, 'Imogene''s Antlers', 'LaVar visits the Philadelphia Zoo in Pennsylvania to learn about animals with horns and antlers. In today''s featured story, a young girl wakes up one morning to discover she''s grown her own pair of antlers.', '1986-07-02', 30, NULL, '2026-04-03T17:36:15Z', '2026-04-03T17:36:15Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('dfcd8bd5-9196-4bcf-ae35-15d4ee9590a4', '04e133fd-c4a3-4dfa-8369-c6dcfd1e3a5a', 61, 'Episode 2026', 'Characters explore surprising adventures around Sesame Street with unexpected twists at every turn. Each moment brings its own special kind of fun and learning.

Sponsors: Y, Z, 5', '1985-02-11', NULL, NULL, '2026-04-03T17:36:36Z', '2026-04-03T17:36:36Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('dfd04883-5567-497e-9e6f-a70b703198bb', 'c6d5cf79-f2b0-40af-ad12-91aa4f1b1d21', 10, 'Yay or Neigh?', 'When a customer soars into the shop with a rare H.G. Wells book, and an astronomical asking price, will Corey shoot for the stars? Next, there''s no horsing around when a statue made of turquoise moseys on in. Will it be a yay, or a neigh for Rick? Then, Chum spins over to LA to have a record collection appraised. Did he scratch on this deal, or will their value be music to his ears? And finally, Rick casts his line at a vintage Plymouth ''Cuda muscle car--but will it be enough for its owner to bite?', '2022-10-12', 42, '/fkFlGG6hUM3uGXcKdblXox8hU7g.jpg', '2026-04-03T16:34:23Z', '2026-04-03T16:34:23Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('dfd09dd4-561d-4b58-9135-d39bfec288a9', 'a0fa5075-9ce1-48c1-9995-0c0fd866e549', 11, 'Mind Your Business', 'Sutton takes Garcelle and Kyle to visit her childhood home as old wounds are reopened. Dorit and PK reconnect, but Erika senses a trap. Bozoma is ready for the next step of her fertility journey, but not without her daughter’s approval. Sutton confronts her mother about the past and their future.', '2025-02-11', 43, '/4xHWruEuDDiwNb8VamrXXXRIOFd.jpg', '2026-04-03T16:34:59Z', '2026-04-03T16:34:59Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('dfd89466-0cd3-4840-ad5c-5487145db61b', '8bae6aa3-4b55-4fa6-bc15-8f4317bd1f13', 19, 'Episode 19', 'X wants to ask King Friday for a job. He earns the title printer of Royal calling cards.', '1972-03-16', NULL, NULL, '2026-04-03T17:35:40Z', '2026-04-03T17:35:40Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('dfdca875-4b1b-477f-9f70-884e69250d9f', '2e6ee129-b32e-4417-9500-56f1cc9bc434', 5, 'Silent Lotus', 'This episode takes a look-in at deaf culture. LeVar discusses forms of communication that doesn''t involve words, like hand signals, mime, and gestures, like in charades. He also asks a friend who is a deaf actress to teach him some sentences in sign language. Lea Salonga reads the featured story of a shy young girl in Cambodia, whose parents realized her lack of communication was due to being a deaf mute, but in noticing her natural talent for dancing, approached the king to request that their daughter be allowed to join the royal dancing troupe.', '1993-10-15', 30, NULL, '2026-04-03T17:36:18Z', '2026-04-03T17:36:18Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('dfe12042-54ff-4cc6-8a39-907633e34f82', 'e93f04c2-7344-4b93-abba-8ba1b2f8eb35', 49, 'Cookie Monster’s Cousin Apple Monster Visits (0584)', '', NULL, NULL, '/5oIY0dH1HWkkGJROVGlPUFYLfp6.jpg', '2026-04-03T17:36:30Z', '2026-04-03T17:36:30Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('dfe169c8-a74c-43fc-9186-f1de72a0fd2d', '6b5caa66-f66f-4ed1-817f-a00bad08790e', 9, 'Reunion: Watch What Happens (2)', 'Danielle''s book is still at the forefront of the housewives'' minds and the ladies chide her for bringing it to the dinner party. Later, Danielle asks whether she was the reason Jacqueline and Dina briefly stopped speaking to each other and both give her separate answers.', '2009-06-25', 43, '/fYjKoTkR9qmL7C9OyLbxkWmqtm2.jpg', '2026-04-03T16:35:14Z', '2026-04-03T16:35:14Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('dfe21e3b-6e98-4342-b4b6-a7067275ab71', 'c67a8787-4971-4961-b536-1ff01924e2a9', 19, 'Big Brother Binky', 'When Binky''s parents tell him that they''re adopting from China, he isn''t sure what to make of it at first. He learns that "adopting" means that he''s going to become an actual big brother to a baby girl and will be heading to China to meet his new sister. Binky eagerly assists with preparations for the big trip and the new arrival, but begins to become concerned that his parents will no longer have any time for him. After his worries are eased, the big moment finally comes. At first, Binky is ill at ease around his new sister, who seems to cry a lot, but then discovers a special talent. Back at home, he''s eager to show off his new talent to his friends, but finds that he seems to have lost it.', '2007-09-07', 26, NULL, '2026-04-03T17:37:59Z', '2026-04-03T17:37:59Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('dfe7174c-0df1-4d5e-adc9-a3103f19c1c7', 'e6ea1431-9e67-4637-83ae-a11073e8c7e0', 4, 'The M Word', 'Kyle reflects on her career when her 7-year-old daughter, Portia, expresses an interest in acting; Lisa Vanderpump invites the women over to show off the mini-horses; Lisa Rinna makes a shocking suggestion about Yolanda''s health.', '2015-12-22', 43, '/iNiJ9gRIKWEeHFoiFG33sfmmdFN.jpg', '2026-04-03T16:34:56Z', '2026-04-03T16:34:56Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('dfefb921-148a-409b-83a7-f67729b7b0cc', '9193e795-da7c-40ec-b68f-f63aa7d5174f', 138, 'Histories & Lore: Robert''s Rebellion (Barristan Selmy)', 'Barristan Selmy recounts how he was named to the Kingsguard, saw King Aerys descend into madness but revered Prince Rhaegar Targaryen. Barristan describes the fateful Tourney at Harrenhal, the ensuing War of the Five Kings, and how he fought beside Rhaegar at the Battle of the Trident where he was killed.', '2016-03-15', 6, '/fiH6P2z9BtAconZ5V70J9av0jPr.jpg', '2026-04-03T15:40:35Z', '2026-04-03T15:40:35Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('dffd90eb-f89d-4c59-937b-545b327952f0', '9193e795-da7c-40ec-b68f-f63aa7d5174f', 221, 'Anatomy of an episode: Mother''s Mercy', 'We experience, how "Mother''s Mercy" came about - an episode that fans will be discussing for years to come: from the script concepts to the final visual effects.', '2016-03-15', 30, '/e2wOg8QQIKGN7Vdm45Eszme3Upu.jpg', '2026-04-03T15:40:35Z', '2026-04-03T15:40:35Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('e008cd89-ead2-429e-8039-4e2b2c0f0a75', '6fd9fd9d-e378-411b-94b1-76ba4bd518fe', 73, 'Episode 73', 'with Christopher Trace, Valerie Singleton and John Noakes.', '1966-06-06', NULL, NULL, '2026-04-03T17:21:48Z', '2026-04-03T17:21:48Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('e00ac9cb-7986-4e00-82a1-70ee315042b6', 'a6ed03e0-c05f-48f8-9f56-3f1da50e1792', 36, 'Episode 1351', '', '1980-01-14', NULL, NULL, '2026-04-03T17:36:33Z', '2026-04-03T17:36:33Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('e00c7634-ba83-4f83-8ea2-f3bd97740179', '54facb0b-db59-41fe-9d64-c7c7221a3c81', 3, 'It’s A Clam Shame', 'Barbara’s clambake continues as uninvited Ramona is confronted by Luann for spreading rumors, forcing her to leave with a doggie bag and without her pride. Back in the city, Dorinda and Barbara try to clear things up over lunch. Meanwhile, Bethenny heads to North Carolina for more relief work after the Hurricane Florence flooding. Sonja throws a party to celebrate a recent cover shoot for a fashion magazine.', '2019-03-20', 60, '/agndvcYNb3a8tfSWlUSDAZbhbI2.jpg', '2026-04-03T16:35:25Z', '2026-04-03T16:35:25Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('e00f4aa1-36f2-46a7-958c-90fe5e95c05d', '8730c55e-8443-44b0-afef-a369c478b14f', 6, 'Breakfast Song', '', NULL, NULL, NULL, '2026-04-03T15:26:09Z', '2026-04-03T15:26:09Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('e0115a22-eef0-4e43-9c46-5dbc435e18dd', '5a771f52-fe96-4ea2-b567-a8dde899059e', 8, 'The Pawn Commandments', 'The Pawn Stars get all wound up over an automaton that performs a magic trick. A seller with a Bible from the 1500s tries to make a believer out of Corey, but his go-to book expert warns him to beware of false profits. Rick hedges his bets when a horse race gambling machine gallops into the store. And later, Rick has a set of insignias from a WWII bombardment group square in his sights.', '2017-11-06', 21, '/eRCKMPqgc2Rgs1kSKMcsoJ4Vww6.jpg', '2026-04-03T16:34:21Z', '2026-04-03T16:34:21Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('e016b7a2-f236-4fb8-a0e1-ef2e73313442', 'd1d267dd-e27f-4543-acb8-0d28f676512a', 11, 'Episode 11', 'with Valerie Singleton and John Noakes', '1967-11-02', NULL, NULL, '2026-04-03T17:21:49Z', '2026-04-03T17:21:49Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('e01a4e01-78e4-4601-a0ff-0b5bccc3b237', '41569c39-4b4f-4a37-a6cc-145c050d8e0c', 12, 'Episode 12', '', '1998-03-24', 25, NULL, '2026-04-03T17:21:17Z', '2026-04-03T17:21:17Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('e0200600-b9a6-4879-940e-27eacf65354f', '684af21e-0459-4832-b094-db0997e354c5', 4, 'She beat me to the Tweet!', 'Romain threatens Joanna with leaving after her meltdown; Adriana excludes Karent from a Dali exhibit; Ana defends Marysol; Lisa warns Karent about the other women.', '2012-10-04', 44, '/wszxtQoYfBjHw24hDwG8qd7QirO.jpg', '2026-04-03T16:35:10Z', '2026-04-03T16:35:10Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('e0223cd4-ea54-4ede-9844-801cc9cb4aad', '54900370-8988-46b8-b7aa-61d2b88d7056', 12, 'First Amendment Rights, and Wrongs', 'It’s tea time and the kettle is hot! In an effort to smooth things over within the group, Bronwyn embraces her new US citizenship and hosts a Spill the Tea party that quickly turns into chaos.  Meredith finds herself in the hot seat as she’s faced with fresh accusations from the women. After the dust settles, Angie shakes things up with a surprise for the women.', '2025-12-02', 42, '/bY6jgdPmF86wGxGX7jf1FYTCNN4.jpg', '2026-04-03T16:35:46Z', '2026-04-03T16:35:46Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('e027d006-9bbf-43ed-8bd0-067960865037', '49a00924-9169-4b3f-b8f0-d7bd68794db9', 2, 'The Icing on the Brain Cake', 'Danielle takes the first steps in making Valentina a star; Melissa and Joe host a bittersweet celebration for Antonia''s birthday before she leaves for college; lingering drama between Rachel, John and Teresa threatens to ruin the entire trip.', '2024-05-12', NULL, '/cYtTo2dRNjo3xUzrMwF4ytxo1jL.jpg', '2026-04-03T16:35:19Z', '2026-04-03T16:35:19Z');
