INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('e0399fef-5dd5-41e4-b01c-93c962458c2a', 'e3a28669-91b5-45f7-bb73-5006acc084e8', 38, 'Snore-Worn Shaun', 'Shirley''s snoring is keeping the flock awake, so Shaun decides that the only way to get a peaceful night''s sleep is to get her out of the barn.', '2007-09-13', 7, '/8zDoNR4vhArW4H9OFWp11hvHWJx.jpg', '2026-04-03T17:39:31Z', '2026-04-03T17:39:31Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('e03a05d0-e37e-4cde-ba66-1beb932f7f22', 'd1d267dd-e27f-4543-acb8-0d28f676512a', 85, 'Episode 85', 'with Valerie Singleton, John Noakes, Peter Purves.', '1968-07-01', NULL, NULL, '2026-04-03T17:21:49Z', '2026-04-03T17:21:49Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('e03f8b63-7f2a-433f-9860-68af98c56850', '3fc7c152-e4f6-426a-a899-36ec454c4403', 19, 'Eggs Over Easy', 'Cyrus, a Slinky Serpent, steals a Rhyme Bird egg and Cassie feels let down that she did not speak up when needed.', '1999-09-24', 30, '/nMezynFC8V1iJBET4WLfeOTGMl7.jpg', '2026-04-03T15:26:03Z', '2026-04-03T15:26:03Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('e0443589-5dd7-4565-8001-56e3de778063', 'd5351b60-8a0c-482a-a6dd-4fb860cfe143', 17, 'Episode 1407', 'Mister Rogers arrives with three balls and a film but does not get the opportunity to show any of them before Mr. McFeely arrives with a film about tadpoles.  In the Neighborhood of Make-Believe, Bob Dog and Francois Clemmons are playing fetch with a ball when Lady Elaine joins in for a moment.', '1975-03-11', NULL, NULL, '2026-04-03T17:35:41Z', '2026-04-03T17:35:41Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('e0498cd8-ec05-4481-8537-ac210c0c621c', '97616d6e-5c17-449f-a376-55f1da83d6c3', 12, 'Mister Rogers Talks About PETS', 'Mister Rogers arrives with a collection of animal paintings made by some young friends. After looking at the paintings, he invites viewers along as he visits the Neighborhood Zoo.

At the Zoo, Mister Rogers meets Barbara Bingham who allows him to help feed the panda bears. Mister Rogers then goes on to see elephants, giraffes, tigers, and lions.

Back at the house, Mister Rogers talks about there was not a zoo nearby when he was a child. It was during a parade when he was able to see different kinds of animals.', '1982-06-04', NULL, NULL, '2026-04-03T17:35:42Z', '2026-04-03T17:35:42Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('e04dfccf-9267-47e5-b7e4-4c87c2e165c6', '2b968a9c-5fc0-4e93-bcf9-31d3e4c7b210', 66, 'Episode 66', '', '1976-04-26', NULL, NULL, '2026-04-03T17:21:52Z', '2026-04-03T17:21:52Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('e051ab56-301b-466a-8d44-75f0fc788af3', '90cc8678-a14f-4d05-bc1e-54a3117895d5', 5, 'A Joke Backfires', 'Its spring and Vixen finally gives birth to her cubs. The animals all gather to congratulate the new parents and to help decide on names for the four cubs. The poachers still plague all the animals in the park but when the warden returns they believe their troubles to be over. However the poachers continue to hunt in the park while the warden remains ignorant to their nightly activities. Fox sets into motion a plan to get rid of the poachers by bringing them to the attention of the warden. Wandering round in the open and calling out they finally spot him and give chase - straight to the warden''s cottage. Hearing gunshots the warden runs out and catches the poachers in the act, putting a stop to their hunting for good.', '1994-02-04', 25, '/cQBxmW9rY8Pb6YY4C0fu5hR7Mbp.jpg', '2026-04-03T17:18:49Z', '2026-04-03T17:18:49Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('e0534054-39c4-44b2-9a5f-a611fea2cedb', '4060ad7f-4b8f-4393-8eb1-66a150b928b6', 24, 'Elmo and Rosita''s Tallest Block Tower Ever', '', '2021-04-22', 26, '/vBc5ynAQy2W80GRZrQLnShvYiiu.jpg', '2026-04-03T17:36:50Z', '2026-04-03T17:36:50Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('e0575a48-aeb9-4578-82b4-1243c184d65c', 'ecb64ef3-4f80-45a7-b4a9-c04434b02e35', 9, 'Smurf and Turf', 'Go six feet under with the Pawn Stars when the guys check out a 19th century Fisk iron casket. Will this eternal tomb hold Rick''s interest or be left for dead? Then, Corey and Chumlee toy with the idea of making an offer on a massive Smurf collection. But will a tough negotiation leave them feeling blue? And later, Davey Deals is a long-time friend of the shop, but what happens when said friend overstays his welcome?', '2014-01-30', 21, '/e522mtxHcR7bmougyrYP3KC0rFC.jpg', '2026-04-03T16:34:19Z', '2026-04-03T16:34:19Z');
