INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('e0a260b7-8d24-4ecc-b074-aae33367e175', '9310a288-5af0-4746-a8d7-d7635ffb6beb', 5, 'Conflict', 'Mister Rogers arrives with a record player which he demonstrates in the kitchen. The record he plays is a 45 RPM recording of Everybody''s Fancy. He then shows a film about how people make record players.

In the Neighborhood of Make-Believe, everyone is preparing for a celebration of peace. The citizens of Southwood are invited to the celebration by Queen Sara.

The children of the Neighborhood are working with Lady Elaine Fairchilde as they sing Peace and Quiet while Lady Aberlin goes throughout the Neighborhood asking everyone what they think about peace. Keith, the carpenter from Southwood, helps the Neighborhood school by using Corney''s parts to make a record player.', '1983-11-11', NULL, NULL, '2026-04-03T17:35:43Z', '2026-04-03T17:35:43Z');
