INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('e0beeb50-48ba-4fe0-a618-3a3eb2e5847a', '0442fb97-1460-4923-8558-b994078dc6b8', 4, 'Celebrations and Strange Explanations', 'Gizelle struggles with the fact that her daughters have questions about her rekindling a relationship with their father, and turns to her best friend Kal for guidance. Candiace and Ashley finally bury their year-long feud, meanwhile Monique expresses her marital frustrations to Chris. Karen decides to throw a lavish housewarming party, but Candiace and Gizelle’s spat almost puts the celebration on pause.', '2020-08-23', 42, '/dgIXmF8oOK9BthfG4eJeHcvRtdU.jpg', '2026-04-03T16:35:40Z', '2026-04-03T16:35:40Z');
