INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('e0ef2fda-4d76-4b05-9831-802c2843fc4d', '1be79a20-de33-41d1-af17-079035b18d5c', 39, 'Episode 39', 'Sponsors: L, U, Y, 4, 5', '1970-01-01', NULL, NULL, '2026-04-03T17:36:28Z', '2026-04-03T17:36:28Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('e0f05d50-dbd6-457e-b472-f139769bcf60', 'dfa60f31-6ef1-4bee-a9ad-554b68a5448b', 18, 'Graham''s Revenge', 'Steve and the team at Australia Zoo successfully transfer the ornery crocodile Graham and his girlfriend Bindi to a new enclosure. Not long after, Steve and Wes Mannion have to enter the enclosure. Graham gets his revenge by attacking Wes. Steve saves the day by jumping on Graham, although Wes suffers severe injuries.', '2002-08-10', NULL, NULL, '2026-04-03T17:39:11Z', '2026-04-03T17:39:11Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('e0f43dcc-eb52-4280-ab08-64e6fd10817b', '262e8e7c-fa78-4578-a216-add6f184c4d2', 10, 'Gambling on the Future', 'Kody must tell the younger children that they will be leaving Utah forever; plans turn to panic when the media gets news of the move.', '2011-05-22', NULL, NULL, '2026-04-03T16:34:27Z', '2026-04-03T16:34:27Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('e0fa5785-4ad8-4b7e-a190-e642e18325f2', '9193e795-da7c-40ec-b68f-f63aa7d5174f', 157, 'Histories & Lore: Oldtown', 'Grand Maester Pycelle and Qyburn debate the records and theories about the history of Oldtown, the oldest city of Westeros, the noble house that governs it and the Citadel, the refuge and home of the noble order of the Maesters', '2016-11-15', 6, '/eINX4oibds6Ouj81E6PGXopTTjl.jpg', '2026-04-03T15:40:35Z', '2026-04-03T15:40:35Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('e0fc33da-c70d-4ef7-9035-d7bb1e6e22aa', '9193e795-da7c-40ec-b68f-f63aa7d5174f', 262, 'History of Slaver''s Bay', 'Author George R.R. Martin tells the history of slaver''s bay.', '2014-02-18', 1, NULL, '2026-04-03T15:40:35Z', '2026-04-03T15:40:35Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('e106112e-22bc-4916-9305-15ad58fd7ed8', '119c16d5-1047-45ec-8242-c72a8eed423b', 42, 'The Perfect Brother', '', '1996-11-04', 13, NULL, '2026-04-03T17:37:55Z', '2026-04-03T17:37:55Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('e1095d2a-4fc7-4c76-a792-4e2257149e75', 'bf874be3-7e2f-4a0e-b205-c76ac1ad69fc', 3, 'Seinfeld Beginnings', 'Beginnings of collaboration between Jerry Seinfeld and Larry David.', '2004-01-01', 22, '/wjrdny4EUz14nXhsmeq6DwZjHPN.jpg', '2026-04-03T16:34:08Z', '2026-04-03T16:34:08Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('e109f33c-3752-459c-ae0f-22e6843a058e', '3b5276ce-bc20-43eb-a638-fe5ced3178a8', 4, 'The Last of the Starks', 'In the wake of a costly victory, Jon and Daenerys look to the south as Tyrion eyes a compromise that could save countless lives.', '2019-05-05', 79, '/qe508xwVVO7cF2oWzfJp52StkTk.jpg', '2026-04-03T15:40:38Z', '2026-04-03T15:40:38Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('e10c2e0c-5f46-4204-b078-dc0ce56ae48a', '7c756336-29db-4634-b976-e993e8f51da2', 13, 'Reunion (1)', 'The ladies revisit this season’s highs and shady lows as suspicions surrounding Karen''s move are revealed and the question of who will claim the new title of “Grande Dame of Potomac” is answered. Gizelle and Monique go head to head, while Charrisse disputes cheating allegations. Rumors continue to swirl about Robyn and Juan’s relationship, leading Robyn to call out Ashley for her meddling. And the reunion takes a shocking turn when Charrisse accuses Gizelle of having an open relationship in her first marriage.', '2017-07-09', 42, '/oUg4Blc1GkDgQLT7kgITQvMm2De.jpg', '2026-04-03T16:35:39Z', '2026-04-03T16:35:39Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('e1148c6b-1cd1-4b02-96f5-47c12e30aff5', 'bf3ffafd-7d45-4f2c-9f1b-28001bd082db', 12, 'Episode 12', 'with John Noakes, Peter Purves, Lesley Judd', '1974-10-17', NULL, NULL, '2026-04-03T17:21:52Z', '2026-04-03T17:21:52Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('e115a313-593f-44b4-8a77-46e101768a26', 'ad4e4348-3334-4a08-8928-455d9ba524c1', 13, 'Glenda Jackson', 'Glenda reveals herself to be Black Jackson the pirate captain, and she takes over the Muppet Theater with the help of Short John Silver (Sweetums) and Eric, a heartless pirate parrot (in disguise as a penguin). They tie Kermit up, turn the theater into a ship, and cast off to look for buried treasure. The show ends with a musical battle at sea, with Gonzo and a crew of chickens fighting to save Kermit and the theater.', '1980-12-28', 26, '/fph4B4dfemicHv0rrXoCEy4PvQC.jpg', '2026-04-03T17:35:25Z', '2026-04-03T17:35:25Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('e115dff7-29d3-4be4-8c18-f3cff4416935', 'a6efe883-0113-4477-bf06-57b42a3770ee', 23, 'The Finale (1)', 'The gang plans a trip to Paris to celebrate after NBC picks up Jerry and George''s sitcom. But there''s an in-flight emergency, stranding them in a small town.', '1998-05-14', 56, '/eYxgFMhFfoz742lfOCgLFROg5iT.jpg', '2026-04-03T16:34:12Z', '2026-04-03T16:34:12Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('e119ce28-8d1f-4f4e-aaf7-4eafc167c988', '27a5a980-ec0d-4637-b5ba-df8324a6405a', 21, 'The Guidance Counselor', 'Sue finds a kindred spirit in her awkward school guidance counselor, Jane Marsh (Whoopi Goldberg), who inspires her to reinvent herself. Meanwhile, Frankie is ecstatic when she and Mike buy a much needed new bed but is gobsmacked when her stubborn husband insists on assembling it himself; and Brick attempts to call the President to outlaw the Presidential Fitness Challenge, which would force him to accomplish some strenuous physical exercises at school.', '2012-05-02', 22, '/AmV8EFmBDnjvVGT4KNB7QlFYhUu.jpg', '2026-04-03T15:40:29Z', '2026-04-03T15:40:29Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('e11adfbc-811f-45da-a668-c01e8499e720', 'ea73e13c-6962-4804-8305-c303df65f89f', 31, 'A present from the king and queen', 'In the Television house, Rogers plays a matching game. In the Neighborhood of Make-Believe, the Royal Family give moving frames to X, Henrietta, and Lady Elaine.', '1969-03-24', NULL, NULL, '2026-04-03T17:35:38Z', '2026-04-03T17:35:38Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('e11c8ec8-fc52-4a6a-bddd-0f857a1bfb6a', '52135215-5160-4d42-9d0f-db242b1abcaa', 1, 'The Wonderful Towers of Watts', 'LeVar visits Watts, a neighborhood in Los Angeles. The featured story is about Simon Rhodia and The Watts Towers. Also featured are young Watts residents trying to make the neighborhood a better place.', '1995-10-02', 30, NULL, '2026-04-03T17:36:19Z', '2026-04-03T17:36:19Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('e11e2745-66f4-469b-8017-c97eb713e4e3', '3982796b-5451-4100-9042-46bedf6a20a5', 24, 'Pingu and the Stranger', 'Pingu has gone out to get some fish from the fish stall. While he’s on the way, two strangers enter the village, and are shunned by everyone they meet. Pingu arrives at the fish stall, gets out his shopping list and is about to tell the stallholder what he wants when the stallholder sees the two strangers, who are just behind Pingu. The stallholder quickly closes the stall and walks away, leaving Pingu without any fish to take home. Pingu walks away, but hides behind a nearby igloo, and then surreptitiously follows the two strangers out of the village to a nearby ice pool. Another penguin is fishing. One of the strangers takes out a shell horn and blows it, getting a rasping squawk noise. The two strangers look up, and soon a fish drops from the sky into the hands of one of the strangers. Pingu is amazed. The stranger with the horn blows it again. Another fish drops from the sky and lands on the ice nearby, but this time the penguin fishing and Pingu are looking up, and they see that a seagull is dropping the fish. The strangers offer the fish to the penguin fishing, but he refuses and hurriedly walks off. Pingu comes out from where he’s been hiding and walks up to the strangers, who give him the fish and let him try the horn. Pingu blows, but only gets a gentle squeak from the horn. The strangers urge him to try again, and he gets a raspberry sound. No fish is dropped either time. Then the seagull swoops to catch a fish from the pool, and as it flies overhead the strangers urge Pingu to blow again. This time he gets a better sound, and the seagull responds with a squawk, dropping the fish it has just caught! The fish is given to Pingu, and Pingu then soon fills the basket with fish. As they’re waiting for the seagull again some of the villagers come to look at what is happening. The next fish dropped by the seagull lands on one of the villagers, and after initial amazement they all laugh. The horn is shown around and the villagers chat happily with the strangers.', '1994-09-14', 5, '/3vPNkuLX1UMdNLntOBiBgXzg2QI.jpg', '2026-04-03T17:22:19Z', '2026-04-03T17:22:19Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('e12c65fd-ea79-4eea-92a9-1177e6dd9fd6', '56fc6204-8c9d-4ba3-a4e7-0d0a7de40dc3', 9, 'The Dinner Party from Hell', 'Camille throws a glamorous dinner party at her Malibu home and, in addition to the housewives, she invites a few special guests. The guests, however, bring up a sore subject and sparks fly between all the women in an explosive showdown.', '2010-12-16', 43, '/jS8ocDmpIIVIymtHLlo5iGiYiT.jpg', '2026-04-03T16:34:54Z', '2026-04-03T16:34:54Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('e12dcd1b-093c-47a5-a46f-e843c0165bae', '151e88a1-9576-4bd1-b84a-c4d64c1c9fe8', 16, 'Altitude Adjustment', 'Kyle charters a private plane and flies the women to Aspen in style, but Dorit packs emotional baggage along with her snow pants. The mountain weather isn’t the only thing that’s cold, as Garcelle and Sutton ice out Erika in a very public fashion. Kyle’s ski chalet goes from cozy to creepy when Rinna summons the spirits with a Ouija board. Diana and Sutton’s feud is rekindled after a combustible word leaves the ladies fuming.', '2022-08-31', NULL, '/1fHXpiww3mJ9LptnT2M9yjXwNzB.jpg', '2026-04-03T16:34:58Z', '2026-04-03T16:34:58Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('e12ee496-7eca-4e66-b23d-3a9c9ee17679', '5c1b881f-ac58-4d72-b63f-209952d4f902', 26, 'Episode 26', '', '1979-12-06', NULL, NULL, '2026-04-03T17:21:54Z', '2026-04-03T17:21:54Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('e131ef51-27ab-424a-89cb-aafe10498e4b', 'f829d1fb-64ea-430f-8e0e-b3345653a542', 9, 'Island of Snakes', 'Steve Irwin travels to Sri Lanka to help laborers contend with some of the most venomous snakes in the world like the Russell''s vipers and the cobras. And, for the first time in his life, he goes head-to-head with a man-eating mugger crocodile.', '2004-06-16', 44, NULL, '2026-04-03T17:39:12Z', '2026-04-03T17:39:12Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('e137b8c5-20a1-4cfc-97ad-93bcaed9ab7a', '8dd9292d-bcb1-4864-8297-4f6c3313f8c6', 11, 'Singled Out', 'Shannon and Vicki head to St. Louis for their live show tour; Heather and Alexis attend the GLAAD Awards; Tamra and Katie''s daughters bond over similar childhood experiences; Jenn hosts a poolside party.', '2024-09-19', NULL, '/7H75vjT70Y7tF4Pnv0jjzHYmec2.jpg', '2026-04-03T16:35:35Z', '2026-04-03T16:35:35Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('e14210f1-d8b6-4746-9bb3-e48856e565f6', '55930d10-8ec2-4a20-8c94-52d9b5329bae', 3, 'High Sparrow', 'In Braavos, Arya sees the Many-Faced God. In King''s Landing, Queen Margaery enjoys her new husband. Tyrion and Varys walk the Long Bridge of Volantis.', '2015-04-26', 60, '/dwOS9tOOqodTpuK0S1hSM2kFoXB.jpg', '2026-04-03T15:40:37Z', '2026-04-03T15:40:37Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('e14b49f2-91c9-442e-be4b-d14ac40051d8', 'ea1650c2-e4f1-46c7-93ba-74b5d45d08e5', 17, 'Reunion (1)', 'Hosted by Bravo''s Andy Cohen, the ladies of Hotlanta, Cynthia Bailey, Kandi Burruss, NeNe Leakes, Phaedra Parks, Sheree Whitfield, Kim Zolciak get together to set the record straight on some of the most talked-about antics of the season and answer some of America''s most burning questions.', '2011-02-13', 43, '/keBr62n5PeoMbqLyTwIuRwQfb7d.jpg', '2026-04-03T16:34:45Z', '2026-04-03T16:34:45Z');
