INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('e1614510-7b9d-4045-9e3f-898ec1cca770', '2aebfad4-3145-4bc1-9def-5f1d5bdfcfc8', 22, 'The Parking Space', 'George argues with a stranger over a "dream" parking space in front of Jerry''s apartment.', '1992-04-22', 24, '/i1nIU4Xc3rRhMmk7Ul6JDInVorz.jpg', '2026-04-03T16:34:10Z', '2026-04-03T16:34:10Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('e164956b-19d8-41f9-935c-c5e51c8f5d91', '871570b4-bf2f-4ba1-9940-65fb932cb009', 12, 'Beauties & the Beat', 'Kandi and Todd take a refresher course in parenting as they prepare for Baby Tucker''s arrival. Meanwhile, Phaedra and Ayden set out to celebrate Apollo''s birthday; Kim plans a makeup-free brunch; and Cynthia gears up for her eyewear commercial.', '2016-01-24', 43, NULL, '2026-04-03T16:34:47Z', '2026-04-03T16:34:47Z');
