INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('e16634da-8bc2-471d-86da-7d87abb65a29', '98d80972-e53a-43dd-a03a-7703465e6f87', 34, 'Hello, Goodbye', 'Get by with a little help from the Pawn Stars when alternative artwork for "Sgt. Pepper''s Lonely Hearts Club Band" rocks into the shop. One of the Beatles'' most iconic albums, will the guys twist and shout for this piece of music history? Then, Rick eyes a pair of lithographs by Joan Mir and Marc Chagall. Both leaders of the Surrealist movement, can he dream up a deal? And later, the guys get a little starstruck when actor Steve Carell wanders into the shop. Will it be just another day at the office?', '2013-03-11', 21, NULL, '2026-04-03T16:34:18Z', '2026-04-03T16:34:18Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('e168aa89-79db-47ad-9202-34148c5e5d02', '8b07363e-5f54-45d6-b036-b43793f7af74', 3, 'Francine''s Split Decision', 'When Francine''s bowling tournament and her cousin''s bar mitzvah take place at the same time, her friends help her attend both events at once.', '2002-10-09', 13, NULL, '2026-04-03T17:37:57Z', '2026-04-03T17:37:57Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('e169a2e0-8c48-4b57-9b1d-7db78c9fe933', '225b0f03-984b-47f3-a1a3-d3e92175e39d', 40, 'Episode 40', 'with Christopher Trace, Valerie Singleton and John Noakes.', '1967-02-13', NULL, NULL, '2026-04-03T17:21:48Z', '2026-04-03T17:21:48Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('e16bab0a-8a59-4487-a023-21b72fc29ba6', '9ae29d08-7ce8-47f9-8584-2d3e861067a8', 8, 'I See You', 'The family waits for news about Hank. While Jesse covers at the lab, Walt attempts to placate Gus. After witnessing a disturbing outburst, Walt worries he and his family are in danger.', '2010-05-09', 48, '/edBDR59bzVWdMtCawimRzOMgrlW.jpg', '2026-04-03T15:40:33Z', '2026-04-03T15:40:33Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('e16eb051-3441-474e-a135-48c102945b97', 'f0f8b366-cb33-40b3-a50f-a1ca7780916f', 2, 'The Riddle of Rhyming Rock', 'In setting out to solve the riddle of Rhyming Rock, Gobo learns from the Storyteller about a book of magic spells his Uncle Matt discovered. The book includes a spell for solving riddles. But he doesn''t hear the whole story and when he uses the spell everything goes wrong and Gobo has to find a way to right the damage he has done.', '1987-01-12', 24, '/9FxVexgFhOIfIk0CVcYnq47Htbf.jpg', '2026-04-03T17:35:01Z', '2026-04-03T17:35:01Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('e170774a-02ae-4ebd-9dfc-bb84069f15d4', '3d4e0e45-1c67-475e-b37d-9e7e6b8b942a', 9, 'Pup Fiction', 'Intrigue and mystery surrounds a letter addressed to Wanda.  In trying to trace the anonymous note, Wishbone drifts into Jane Austen''s gothic horror novel Northanger Abbey.', '1997-03-11', 28, NULL, '2026-04-03T17:10:42Z', '2026-04-03T17:10:42Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('e172d670-a7df-44be-bfa2-2dc7b6b45cab', 'be719633-fbf1-4df5-87e4-2da02389f497', 10, 'Keep Fit', 'Neil decides to keep fit, but is startled when he sees what appears to be a ghost under a sheet, which turns out to be Rosie and Jim.', '1999-03-23', 10, NULL, '2026-04-03T17:19:39Z', '2026-04-03T17:19:39Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('e173fe77-96d8-4c43-99a3-3b11ba3eb6df', '21745b85-d269-42fa-b4dd-701b2da5c085', 15, 'Episode 15', 'Five months ago Lesley visited Whipsnade Zoo for the selection of the 3rd Battalion Royal Regiment of Wales’s new mascot. Today you can watch Dewi II’s debut at Cardiff Castle in front Of HRH the Prince of Wales, and see how he reacted to his period of intensive square bashing.', '1973-10-29', NULL, NULL, '2026-04-03T17:21:51Z', '2026-04-03T17:21:51Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('e179ec4f-d875-4d85-a2ce-eea68e1d689c', '5c1b881f-ac58-4d72-b63f-209952d4f902', 63, 'Episode 63', 'Crack Pots  Do you throw away your broken plates and cups and saucers? They don''t in Guernsey! Simon and Goldie investigate the Channel Island''s famous crockery-covered Chapel.', '1980-04-21', NULL, NULL, '2026-04-03T17:21:54Z', '2026-04-03T17:21:54Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('e181dd99-ae39-440a-b953-b383bab4ede1', '4b2a19e0-2fae-492e-bc31-f78e63d88ebc', 16, 'Silver Stash Pawn', 'Laugh it up with the Pawn Stars when a first edition of The Adventures of Bob Hope comic gets Rick and Chum chuckling. Will they entertain an offer or "boo" it out of the shop? Then, an ancient Egyptian mummy mask gets Corey all wrapped up. Will he preserve a sale or will the deal be deceased? And later, things heat up when a 1950s Disney fire extinguisher blazes in. Will Rick add fuel to the fire and make an offer or will the flame fizzle out?', '2016-12-05', 21, '/nfmw3z9q5l5lvDX3u7wkUacLrIe.jpg', '2026-04-03T16:34:20Z', '2026-04-03T16:34:20Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('e18205cd-1458-4190-a033-a5e67fda1698', '387da09c-95c3-49e8-a7ff-fcbb68362cc0', 6, 'Love', '', '1993-03-19', NULL, NULL, '2026-04-03T17:35:46Z', '2026-04-03T17:35:46Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('e18422cc-cd7c-4a4a-9c01-ca9d93cc26cf', 'ebc99729-ccb7-4d64-82c1-42708cd7ba85', 79, 'Episode 79', 'Paper Doll: see a pile of newspapers and chicken wire transformed into a lifesized Sarah. Artist Terry Wall specialises in papier mache sculptures and you can watch him today.', '1981-06-22', NULL, NULL, '2026-04-03T17:21:55Z', '2026-04-03T17:21:55Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('e184a4a5-ad06-4769-a72b-68413327cbf0', 'abfe14ee-db42-4dde-a96a-601ff3c53ecc', 2, 'Cluny the Scourge (2)', 'While Redwall prepares for a long siege, Cluny steals the symbolic tapestry of Martin the Warrior from within the abbey, and Matthias learns that Martin''s great sword still exists - but nobody knows where. As Cluny''s next attack is repulsed Matthias meets a new ally, Basil Stag Hare, and learns that his own destiny is inextricably linked to his hero Martin. Matthias will become Redwall''s next protector - but only if his quest for the sword is successful.', '1999-09-11', NULL, '/aYDRXIunGis0pJHyZx2Ft6W76uR.jpg', '2026-04-03T17:12:08Z', '2026-04-03T17:12:08Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('e187d849-7c74-4723-a02b-3e4a6ff460ac', '91f66da7-56a2-423a-b855-f09d582805b2', 4, 'How to Be a Good Dog & Not Afraid of Dogs', 'A cat tries to teach a dog how to behave; a boy realizes dogs aren''t as scary as he thought.', '2007-10-08', 30, NULL, '2026-04-03T17:12:29Z', '2026-04-03T17:12:29Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('e1890d68-69c9-41c7-b45d-dc3abdddd343', '4a8e3db0-8068-4ff3-942f-91f45f665f20', 11, 'To the Ship! To the Ship!', 'The lions learn about a real-life pirate named Ann Bonnie, after Lionel refuses to let Leona play pirates with him (claiming that there was no such thing as girl pirates).', '2000-04-16', 30, NULL, '2026-04-03T17:12:27Z', '2026-04-03T17:12:27Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('e1894a8a-1601-4f41-a03a-a3dc0e0dada5', '5c1b881f-ac58-4d72-b63f-209952d4f902', 18, 'Episode 18', 'Top cook Delia Smith joins the team for the results of the Gorgeous Grub competition.

Find out if you''ve won one of the unique Blue Peter aprons and whether your recipe has been chosen for the Gorgeous Grub Cook Book to help raise funds for the International Year of the Child.', '1979-11-08', NULL, NULL, '2026-04-03T17:21:54Z', '2026-04-03T17:21:54Z');
