INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('e18ffe41-0a4a-45f9-9a43-c3cf4e9965df', '787dfa0b-c827-4dad-a82d-0548a6534d88', 1, 'Under Construction', 'Season 10 kicks off with new boobs, a new housewife and a whole new set of problems for the ladies of the OC. Vicki announces that her boyfriend Brooks is now living with her, but that''s not her biggest news when it comes to Brooks. Heather is busy building the dream house of a lifetime, while Shannon and David are trying to repair their broken marriage. New housewife, Meghan King Edmonds is ready to play ball, and Tamra adds new boobs to her chest while also getting something off her chest with Vicki.', '2015-06-08', 44, '/8Vgj6QowHM0f3918Q5zoPiZsg56.jpg', '2026-04-03T16:35:32Z', '2026-04-03T16:35:32Z');
