INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('e1d2f308-9f12-4734-ba8b-762853366d50', 'bd8a516b-9872-472d-a838-7aff1070fea3', 3, 'Milton Berle', 'Fozzie Bear is so intimidated by the thought of meeting Milton Berle, "the King of Comics," that he spends the whole show hiding from the guest star. His flimsy disguises don''t fool Kermit or Scooter, but when Fozzie finally overhears Milton saying that he''d like to do a song-and-dance with him, Fozzie springs out of hiding, and the pair performs "Top Banana" together in baggy pants and big shoes.', '1977-10-14', 26, '/kpuNRWoTIbeRJrgOxFevpSNUcW9.jpg', '2026-04-03T17:35:24Z', '2026-04-03T17:35:24Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('e1d39f8f-885a-4aa8-b7e1-d6c2be794b50', '5144de59-e67f-4fcf-919b-7106989ab797', 7, 'Butterfingers', 'The kids hold a relay race, but Ben drops his baton, prompting the nickname “Butterfingers” from everyone else. Nuzzle tries to show off his bravado by wanting to be called “Professor Muscles.”', '1995-01-24', 29, NULL, '2026-04-03T17:12:21Z', '2026-04-03T17:12:21Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('e1d4d52e-b1fd-48d7-afdf-ccdc4b66b4b9', '70c8cb46-2494-4dd4-98f6-6bfb9b3faf73', 20, 'The British Are Coming', 'The Pawn Stars are presented with a classic 1946 Seeburg Jukebox. Will the gang tune up their wallets and hit a high note of a deal, or will it become the day the music died? Then Rick and Corey meet a man hoping to sell a 1775 Massachusetts war bond but is there something special hidden in the engraving? Finally Rick and the Old Man check out a 1965 Chevy Impala. Having fond childhood memories for this car, will Rick be swayed by nostalgia and rev up a good deal, or will the Old Man bring it all to a screeching halt?', '2010-04-25', 21, '/kvEUr27uKVdQFlmq0KCIvo5PST3.jpg', '2026-04-03T16:34:16Z', '2026-04-03T16:34:16Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('e1d7bb3f-695b-4349-84fd-435b8ef269ed', 'e93f04c2-7344-4b93-abba-8ba1b2f8eb35', 67, 'Big Bird and Oscar Clear the Snow (0602)', '', NULL, NULL, NULL, '2026-04-03T17:36:30Z', '2026-04-03T17:36:30Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('e1dc6ea3-e7ec-4172-8f65-a18ed160920d', 'a8db07e5-fba3-49a9-bd12-947c111b39be', 11, 'Invitation Interrupted', 'Sonja sets out to change her ways. Meanwhile, LuAnn makes a surprising announcement about her romantic life; Bethenny plans a getaway to Mexico, but the group fractures over who should or shouldn''t be invited; and Carole fosters a kitten.', '2016-06-15', 44, NULL, '2026-04-03T16:35:24Z', '2026-04-03T16:35:24Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('e1e1c878-adaa-4a81-9117-fcb4d59f167f', 'e4023da2-33d7-4a2b-a04a-ca449bd23935', 11, 'A Quarry Story', 'Frankie must work at Ehlert Motors for one day in order to collect her pay on an old paycheck, Mike offers Sue a part-time job at the quarry, and Mike’s dad attempts to persuade a lazy Axl to help replace the damaged kitchen sink.', '2015-01-14', 22, '/gvIKu53ypP5rA7D27Fy2mGB9TXh.jpg', '2026-04-03T15:40:30Z', '2026-04-03T15:40:30Z');
