INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('e1e42d7d-f718-4a5a-b7ae-4a4db56162f8', 'bd8a516b-9872-472d-a838-7aff1070fea3', 11, 'Steve Martin', 'Kermit cancels the show in order to audition new acts. Guest star Steve is angry at first, but he goes on to perform for the cast. Fozzie worries that Kermit plans to hire replacements, especially after the audition of a canine comedian, Baskerville the Hound. Kermit tells Fozzie that he should appreciate seeing another artist''s work -- until Lenny the Lizard auditions as a new emcee. A young singing girl, called Mary/Terry/Carrie Louise, is systematically removed off, when she makes an attempt of audition with her croaking partner.', '1977-12-09', 26, '/uxKypdheEHNdpzwekHMQ1arvzHH.jpg', '2026-04-03T17:35:24Z', '2026-04-03T17:35:24Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('e1e574d7-f94d-4c51-b767-2183ae5c6a32', '20d7138e-eea8-46a8-8ada-2b0f0ee1f674', 72, 'Episode 72', 'Robinson Crusoe: The true story behind the classic tale of shipwreck and adventure and a chance to meet the great nephew ten times removed of the real Robinson Crusoe - Alexander Selkirk.', '1983-06-02', NULL, NULL, '2026-04-03T17:21:56Z', '2026-04-03T17:21:56Z');
