INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('e2419562-a0b8-4798-894d-2e6c76d3d47c', 'f4c40307-9b5e-4263-a4e0-dfa138131e7f', 104, 'Elmo''s World: Flowers, Bananas & More!', 'Join Sesame Street''s curious red monster as he explores flowers, bananas, and hair! Elmo''s World offers kids and adults a fresh and light-hearted take on the world around them. Each episode comes to life in Elmo''s bright, exciting, and very original room - the drawer, door, shade, and TV all join in the fun. And he''s even visited by a Muppet banana and a talking cactus! Also featuring Elmo''s pet goldfish, Dorothy, the zany Mr. Noodle, and classic songs that will delight viewers of all ages.', '2002-05-14', NULL, NULL, '2026-04-03T17:36:27Z', '2026-04-03T17:36:27Z');
