INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('e257cd9e-4f42-4f09-81da-7263169c3176', 'a0fa5075-9ce1-48c1-9995-0c0fd866e549', 19, 'Reunion Part 2', 'The reunion continues as Kyle and Dorit face off over Kyle’s text to PK, putting more strain on their already fragile friendship. Boz stands firm on her claim that one of the women is not telling the truth. The fabulous Jennifer Tilly joins the action, but it isn’t all diamonds and caviar when she’s called out for her shady comments. Sutton is put in the hot seat, first by the arrival of Kathy Hilton and then for short-changing the size of Dorit’s wallet.', '2025-04-08', 43, '/3FUB6ScDd1odUWCoVi5Y1jgLra.jpg', '2026-04-03T16:34:59Z', '2026-04-03T16:34:59Z');
