INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('e327e0dd-cc4e-4ed9-a483-bf8a3e5f7e2c', '8bae6aa3-4b55-4fa6-bc15-8f4317bd1f13', 15, 'Episode 15', 'Rogers goes to traffic court to plead the case that led to his parking ticket. Lady Elaine leads a march on the Castle to show that everyone has different interests.', '1972-03-10', NULL, NULL, '2026-04-03T17:35:40Z', '2026-04-03T17:35:40Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('e3295850-e1e5-4b12-b585-13ef1883f8af', '787dfa0b-c827-4dad-a82d-0548a6534d88', 7, 'Bowling in Heels', 'Vicki enlists the powers of a medium to try and communicate with her mother. Shannon discovers that to lose physical weight, she has to do more than just exercise, she must deal with the weight of her emotions too. Meghan tries to teach her step daughter responsibility but learns a lesson about parenting instead.  While Tamra and Eddie struggle to work together at the gym, Heather is eager to start a new project with Terry. All the ladies come together for a fun night of bowling and a surprise announcement.', '2015-07-20', 44, '/hLAffab9kUpN5s8OuXiq9ByWiaM.jpg', '2026-04-03T16:35:32Z', '2026-04-03T16:35:32Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('e32f69fe-55b2-4bf5-8956-95660bb2ea24', 'ebc99729-ccb7-4d64-82c1-42708cd7ba85', 46, 'Episode 46', '', '1981-02-16', NULL, NULL, '2026-04-03T17:21:55Z', '2026-04-03T17:21:55Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('e3300b84-a44d-49f7-94e3-0f93b07c9c23', '70d9e397-6813-4785-887d-27d034928bae', 12, 'Pingu and the Broken Vase', 'Mother goes out, leaving Pingu and Pinga alone at home. They make themselves a makeshift house indoors, using the chairs as walls with a blanket on top as the roof. They take some toys and cushions into the makeshift house, but it collapses on them, much to Pingu’s annoyance. They then have an argument, and Pinga throws a cushion at Pingu, hitting him on the head. Pingu chases Pinga around the room, and throws the cushion back at Pinga. He misses, but hits a vase on the sideboard. The vase falls off the sideboard and shatters on the floor. They then realise that their parents are due back shortly, and rush to tidy everything up. Pingu wraps the pieces of the vase in a cloth and puts it in the cupboard, and tells Pinga not to say anything. Father then arrives with a bunch of flowers for Mother, and is surprised when he can’t find the vase. Pingu and Pinga deny any knowledge of the vase’s whereabouts, but Father becomes worried after he finds a piece on the floor! To Pingu’s dismay, Pinga tells Father what happened and shows him the bag where the pieces of the vase are hidden. Father looks furiously at Pingu, who bursts into tears. Father spots a jar on the dresser and puts it onto the table with the flowers in it, which cheers everyone up. Mother then arrives back and is rather pleased with the flowers, but Pingu is still dismayed when Pinga tells her everything that has happened.', '1995-08-31', 5, '/lrMJJbJJKxDyWr3o2PiRkrsFqxz.jpg', '2026-04-03T17:22:19Z', '2026-04-03T17:22:19Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('e33f1bc7-66f2-4023-abda-0a8b60a12e7b', 'ad4e4348-3334-4a08-8928-455d9ba524c1', 10, 'Gladys Knight', 'The theater is under repair, but the workers have to destroy in order to build.  They take the roof right off, leaving this show victim to the elements.', '1980-12-07', 26, '/xbqfgm6kIPfkOwrpX2eJ0coRKAb.jpg', '2026-04-03T17:35:25Z', '2026-04-03T17:35:25Z');
