INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('e344c1bc-abca-4107-9449-a0392a04eac7', '8d0a597a-2adc-4192-80db-5d2e1fa55068', 7, 'Ricker than Fiction', 'Rick and Morty write the next installment of their favorite movie franchise. Pure cinema, broh.', '2025-07-06', 23, '/A8lJdG8eSdvXRRp8f9kiBoHFktz.jpg', '2026-04-03T15:40:44Z', '2026-04-03T15:40:44Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('e3462d55-0357-449b-95e9-2067da5c8123', '0ebba123-871d-4d2b-a054-eb85d2ad9450', 113, 'The Pirates Who Don''t Do Anything Sing-Along Songs and More!', 'not a part of this series; shouldn''t be here', NULL, 30, '/xhBKibZ7ocpMGVZDbEejm46hbDd.jpg', '2026-04-03T17:39:39Z', '2026-04-03T17:39:39Z');
