INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('e34f52f6-b008-4179-bee1-59b75a4fbefa', '4f18ac4c-8757-456c-a49a-224f00e6a9f7', 18, 'Three Cheers for Us', 'Zoe''s cheers help Elmo bounce a basketball three times in a row, so he asks if he can be a cheerleader with her. Together, they inspire Telly to master a pogostick trick, and he joins them as well.', '2008-10-13', NULL, '/13Lr6AnckjJAentmAh23UKBW05U.jpg', '2026-04-03T17:36:45Z', '2026-04-03T17:36:45Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('e3559d26-6b9a-4d1d-aba0-760f42f0f34e', '20d7138e-eea8-46a8-8ada-2b0f0ee1f674', 14, 'Episode 14', 'Desert War in Dorset! How do you re-create a desert epic in Britain? That was the problem ex-Blue Peter designer Paul Joel faced when he began work on the BBC''s new Sunday serial Beau Geste - in Dorset! Today Paul reveals his secrets, including the 19th-century fort he built out of scaffolding and plaster.', '1982-10-28', NULL, NULL, '2026-04-03T17:21:56Z', '2026-04-03T17:21:56Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('e3581ad1-d8a3-463f-8352-d8eebe4aabf3', 'ae8f64d9-4b83-4147-a44c-bfe720381f8e', 22, 'The Counting Booth', 'Uh-Oh! The Count has to leave his Counting Booth and has no one to watch it while he is gone. Luckily, Elmo and Abby agree to become the official Counting Booth Counters while he is away. They immediately have their first visitors, the Three Little Pigs. They ask to be counted one by one to make sure they are all there.

Next, Old McDonald brings his chickens to the Counting Booth. He wants them to be counted in pairs—the same way The Count counts them. But Elmo and Abby are hesitant; they have never counted by two before! Maria comes along and shows them how to count by groups of two.

Suddenly, Baby Bear runs into the counting booth holding ten boxes of crayons with five crayons in each. He explains that he doesn’t know how many crayons he has all together. Elmo is nervous, he has never counted by fives, but with the help of Maria, Abby and Elmo they are able to count each box by five. Next, Snuffy and Big Bird can’t figure out how many fingers all the birdkeeters have together. Elmo and Abby suggest counting by five, but Maria has a better suggestion. Why not count by ten? Elmo, Abby, Big Bird, and Snuffy count by ten all the way to eighty!  Finally, Super Grover runs in.  He needs a count down to fly off and save the world!  With some help from Super Grover and a number line, Elmo and Abby are able to count down to one as Grover blasts off. The Count returns as Abby and Elmo share their new counting abilities!', '2010-01-25', NULL, '/tRGB61Npp6wabSox4GlJsil0uq4.jpg', '2026-04-03T17:36:46Z', '2026-04-03T17:36:46Z');
