INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('e382f7f7-8c6a-472f-b429-e4aceb0800f3', '33440d76-e69f-47ad-ac25-862ccbc9dfa1', 7, 'Don''t Rock the Boat', 'The ladies experience a chicken spin on bingo, but Robyn flies the coop early when she''s sent over the edge. Gizelle and Karen discuss the state of the group. Everyone comes together to celebrate Karen''s "triple 20" with an adventurous excursion.', '2023-12-17', 43, '/iZx4Co7u6rgGCKk6VwftTFiOLVl.jpg', '2026-04-03T16:35:41Z', '2026-04-03T16:35:41Z');
