INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('e395ffb7-886c-4fd3-8ab8-7d527996290f', 'ca09391a-de6a-4b2b-aefc-c2efbc80a106', 2, 'The Adventures of Taxi Dog', 'LeVar is a taxi driver in New York for a day, but the focus of this show soon lands on the subject of a service dog as well as how dogs are such good pets to us. Vincent Gardenia reads the story of an adopted stray dog who helps his new owner, a cab driver, get better tips when he entertains the customers on rides.', '1991-09-17', 30, NULL, '2026-04-03T17:36:17Z', '2026-04-03T17:36:17Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('e3969eac-0b9b-40e3-ab4a-9a10029dd1a0', '650bac93-7b59-41fc-b277-dc6f8bdcd7bb', 6, 'Thanksgiving VIII', 'Frankie decides that April is not good enough to be with Axl and does anything she can to keep her out of the annual family Christmas photo. Frankie must fight for Axl''s attention when he announces that he will be spending Thanksgiving with April.', '2016-11-22', 22, '/1hGvIreiioIy37UcsphydGn4nwn.jpg', '2026-04-03T15:40:31Z', '2026-04-03T15:40:31Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('e399cefe-a15e-4576-aa7a-aff2e5daa1f5', 'f30bbf81-8770-4e74-b68b-280e7c85b52f', 4, 'The Phone Message', 'George blows an invitation upstairs with his latest girlfriend and then when he tries to make restitution he leaves progressively nastier messages on her answering machine. He gets the chance to prevent her from hearing her messages by having Jerry switch the tape out of her machine, while he distracts her. Jerry and his girlfriend have a disagreement about a TV commercial for Dockers, and his telling his friends about their conflict.', '1991-02-13', 23, '/b6snoiJQoLewWzdz1gB37Zb1Bik.jpg', '2026-04-03T16:34:09Z', '2026-04-03T16:34:09Z');
