INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('e3ee0571-1e19-41ce-9043-abc0aeb26a1f', 'bf0f7445-f58f-467f-a81b-fcc2bf6bca21', 16, 'Junior Sells the Farm', 'Junior is tricked into selling the castle by the insidious Wander McMooch.', '1984-04-16', 24, '/f5sk6wEJTpwPZRZHlsYG6uthW2Q.jpg', '2026-04-03T17:35:00Z', '2026-04-03T17:35:00Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('e3f243b7-a545-4e8c-a82f-6d4bedd12715', '3982796b-5451-4100-9042-46bedf6a20a5', 17, 'Pingu as a Babysitter', 'Mother is going out with a friend, and Pingu has the job of babysitting the twins. After Mother and her friend have gone the twins, who were lying peacefully in bed, throw their pillows at Pingu, hitting him on the head. Then one twin cries because his dummy has come out. While Pingu is retrieving the dummy and washing it, the other twin crawls off and pulls the tablecloth off the table. Pingu is just in time to stop the vase smashing on the floor. The first twin then grabs the frying pan that’s on the stove. Pingu eventually gets both of them into their highchairs and feeds them. While he’s feeding one, the other is yelling, and vice versa. Eventually they both stop crying and Pingu checks their nappies. Luckily only one has a dirty nappy so Pingu changes it, and tucks them both back into bed. He then sits down with a book, but they both start to wail again. They don’t want their teddies, but doze off when Pingu rocks the bed. Pingu goes back to the chair, but they start crying so he rocks them back to sleep again. Then he has an idea, and ties a cord to the end of the bed, with the other end of the cord tied to his foot. Now, when they start crying, he can waggle his foot and rock the bed without having to get out of the chair. When Mother and her friend arrive back the twins are fast asleep; Pingu is in the chair with his foot rocking the bed, also fast asleep!', '1993-07-27', 5, '/ZtcDKikHyG53QLyvb78tvjX8Db.jpg', '2026-04-03T17:22:19Z', '2026-04-03T17:22:19Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('e3f8b5a1-b843-408e-96ba-ed4bb9034710', 'efd2082e-32f5-4edd-9a7b-a4326d6992c9', 35, 'Cookie Monster''s Museum Mystery', 'A brand-new museum has opened on Sesame Street - the Museum of Modern Cookie! Cookie Monster, Elmo and Chris are very excited to check it out. While walking around the museum, the paintings suddenly begin to disappear and the museum guards think Cookie Monster stole them. With Abby''s help, Cookie Monster, Elmo and Chris catch who really was taking the cookie art. Season finale.', '2019-07-13', NULL, '/qB2NLitBsxBYocOv4VQysLPEMeI.jpg', '2026-04-03T17:36:49Z', '2026-04-03T17:36:49Z');
