INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('e4046370-ab2f-440d-8c6c-3bfd9594b44a', 'd7ff9136-a833-4c43-a37c-a985a34f45a9', 17, 'One on One: Part 3', 'In this final episode of one-on-one interviews, Kody is confronted with the question of whether he has a "favorite wife." Then, Kody and Janelle open up about the conflict over holidays and reveal the status of their relationship.', '2023-12-10', NULL, '/tGPsETIcrm6BbGxbuxJvPf4Qx8y.jpg', '2026-04-03T16:34:32Z', '2026-04-03T16:34:32Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('e40eb876-88b2-436b-b6e6-a222789ddc5c', '4fe93658-c463-4329-8e64-9d523869c2cb', 4, 'Getting A Head', 'The Pawn Stars are presented with a classic piece of Detroit muscle - a 1969 Buick Skylark. Will the gang put the pedal to the metal and restore this beauty or will the deal get flooded and stall out? Then, Chumlee and the Old Man look to buy a Civil War field desk complete with captured Confederate documents. Will they sound a charge and seize this rare piece of U.S. history or will suspicion cause them to retreat? And later, Rick is presented with a piece from the jungles of the Amazon - a human shrunken head. Will he slice up a deal for this rare tribal charm or will he decide the shop doesn''t need the bad karma?', '2010-09-06', 21, '/j1HF1yQzB3zx6ObzV500rfQCzOd.jpg', '2026-04-03T16:34:16Z', '2026-04-03T16:34:16Z');
