INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('e44796cf-f8a6-4aed-a869-9386c8c77e13', 'f5266c49-eb29-4594-b5d9-f927edfee336', 18, 'Remote Control', 'Bitzer is sent to fix the faulty TV aerial and asks the flock for help.', '2014-02-26', NULL, '/A1xur8QYBkhGOJYZJgyeclJxNRA.jpg', '2026-04-03T17:39:32Z', '2026-04-03T17:39:32Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('e44f3d7d-a9bb-4503-a595-6d4600c420d0', '0b9d7ae7-218e-45a0-8c3a-e69912f5a6ed', 19, 'Franklin and the Copycat', 'Rabbit steals Franklin''s technique for drawing storm clouds.', '2000-01-31', 12, NULL, '2026-04-03T17:40:15Z', '2026-04-03T17:40:15Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('e4534a17-efa9-4f08-9d42-9919e576aa8e', '7b8e3988-fbf3-4cfc-aeb2-782ae5a64e2d', 2, 'The Happy Scientists', 'Gordon is grading his classes’ science experiments when Elmo, Rosita, and Telly run in and accidentally land on the papers. Gordon encourages Elmo, Rosita, and Telly that anyone, including them, can be scientists. All they need to do is to ask questions and investigate! They look around Sesame Street and see Leela giving Barkley a bath. Elmo comes up with a question: Does everyone on Sesame Street take a bath? Gordon guides them through the scientific process. First, Elmo and Rosita hypothesize, or guess, that everyone takes a bath. Telly isn’t sure that everyone takes a bath so he forms a different hypothesis. They investigate and record their observations in their journals. They find out that Chris takes a bath, a cat licks itself and takes a tongue bath, a sparrow takes a dust bath, an owl takes a sun bath to get rid of germs, and even Oscar takes a mud bath in his trash can. This makes Telly mad since his hypothesis was wrong-everyone does take a bath on Sesame Street. Gordon explains that it’s okay to be wrong in science because the most important part is the process, or the steps you take to get your answer. Telly, Rosita, and Elmo become happy scientists! They not only learn all about the scientific process, but also find an answer to their important question!', '2010-09-28', NULL, '/x0O9Oc7as81CNw5aOXcMwVNDtw0.jpg', '2026-04-03T17:36:46Z', '2026-04-03T17:36:46Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('e454d373-d68e-423d-9edb-771d21fb4ebe', '6a2d2839-7106-4c3b-8906-c9b3e4bfcc8b', 3, 'Fakes-Giving, Fake Friends', 'Dinner continues at Shannon''s OC abode. In addition, Shannon''s marriage is dissected by the others; Heather departs for the holidays; and the ladies address their grievances at a "fakes-giving" feast.', '2014-04-28', 44, NULL, '2026-04-03T16:35:32Z', '2026-04-03T16:35:32Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('e45fcd08-35b8-43cd-9546-56bd7ab74de3', '3ee646e8-23ae-4dec-bbc6-c7e6a210d55b', 93, 'Cleaning the vacant lot', 'The Pigeon Sisters do some morning strutting and cooing, when Gordon shows off the trash bins the city has provided them. Gordon observes the litter and has a flash of inspiration — they can turn the vacant lot into a garden! He and the pigeons imagine what it''ll look like, singing "I See a Garden."

Sponsors: F, Q, 17', '1991-03-20', NULL, NULL, '2026-04-03T17:36:38Z', '2026-04-03T17:36:38Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('e4670730-36ec-46e4-a94a-6519d097ed76', '7bc54df3-f32a-454e-aef6-a9436c35d53b', 23, 'The Clemmonses are Moving Pt 3 - Fish', 'Betty Aberlin gives Rogers a black angel fish for his tank. In the Neighborhood of Make-Believe, she dresses up as one. At the Tree, she introduces a song praising Henrietta Pussycat.', '1970-03-04', NULL, NULL, '2026-04-03T17:35:39Z', '2026-04-03T17:35:39Z');
