INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('e46a46b2-f318-49f2-bf74-fbcfa1c7bc1c', 'c0c0b0ba-e6e3-4a30-9567-1102881eddf3', 1, 'Based on a True Story', 'A new girl named Ladonna moves to Elwood City from Louisiana with her family. In order to make friends, she tells the Lakewood students stories about her life. As she continues with her tales, the stories begin to repeat, and the kids are noticing. Ladonna begins to fabricate her stories and is caught by the Brain when she makes an actual mistake.', '2012-10-15', 13, NULL, '2026-04-03T17:38:00Z', '2026-04-03T17:38:00Z');
