INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('e48c34a8-0028-483d-9429-9ed548e63c5a', 'dfa60f31-6ef1-4bee-a9ad-554b68a5448b', 1, 'Sidewinders of Arizona', 'Steve and Terri visit the Barry M. Goldwater Military Range in Arizona to track down the sidewinder rattlesnake. Afterward, Steve visits the airmen at Luke Air Force Base, who prove to be fans of his show. Steve gets the opportunity to fly in an F-16, the plane that carries the sidewinder missile named after the rattlesnake.', '2000-11-19', 44, NULL, '2026-04-03T17:39:11Z', '2026-04-03T17:39:11Z');
