INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('e65f61ba-65ae-45cd-b9cd-4e6f06e6418c', '9ae29d08-7ce8-47f9-8584-2d3e861067a8', 13, 'Full Measure', 'With Jesse on the run and Mike in hot pursuit, Walt negotiates a bargain with Gus and concocts a disturbing plan to provide for his and Jesse''s safety.', '2010-06-13', 48, '/jdi3BLxvs61t3ZyXNKwQQqTI8YD.jpg', '2026-04-03T15:40:33Z', '2026-04-03T15:40:33Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('e660daf0-7575-49a8-be54-b02fcde9b3cb', 'f4c40307-9b5e-4263-a4e0-dfa138131e7f', 48, 'Abby and Friends: P Is for Princess', 'Once upon a time on Sesame Street there lived a fairy in training named Abby Cadabby, and she loved going on all kinds of adventures. She loved playing princess with friends like Rosita, but what happens when a misguided Prince (played by actor Paul Rudd) tries to rescue them? Pretending and the Letter P are the focus of two more stories in this enchanting title that also features fun with Natalie Portman and Elmo in "The Princess and The Elephant". This title will also feature two bonus episodes of Sesame Street''s animated show Abby''s Flying Fairy School.', NULL, NULL, NULL, '2026-04-03T17:36:27Z', '2026-04-03T17:36:27Z');
