INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('e66ed321-e3fe-42ce-a947-f4d37663a9b4', '2b968a9c-5fc0-4e93-bcf9-31d3e4c7b210', 29, 'Episode 29', '', '1975-12-15', NULL, NULL, '2026-04-03T17:21:52Z', '2026-04-03T17:21:52Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('e67126b3-4008-4a85-901a-cf05694a90ef', '6f731e6b-d3c5-4de6-84e1-7a19cb650e86', 20, 'The Pawn Awakens', 'Wield a lightsaber with the Pawn Stars when a one-of-a-kind "Star Wars" packaged Boba Fett prototype strides into the shop. Will the Force be with Rick or will he not pay the bounty? Next, an early 1900s Shelby bicycle wheels in. Will Corey frame out a deal or tire of negotiations? Then, Steve Grad wows Rick with his otherworldly "Star Wars" autographed poster and massive card collection. Are these the Droids he’s looking for or will he think it''s a C-3P-no? And later, a "Star Wars"-used piece of the Death Star docks at the shop. Will Rick laser in on an offer or will it blow up in his face?', '2016-01-06', 21, '/p7a8CvlHQ3XVLjZvhpNYaN1X05B.jpg', '2026-04-03T16:34:20Z', '2026-04-03T16:34:20Z');
