INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('e68092c8-2afe-452b-a09b-15b71c5b2260', '004abc4c-ce77-4df9-8c97-9f56ea8b37ce', 5, 'Pig''s Shop', 'Pig sets up a sweet shop with Arnold as his assistant. Kipper says he''d like one of each but Pig wants to be paid. He says he''ll take a conker in exchange for a gobstopper. But he''s made the same offer to Tiger - and in a game of conkers with Kipper, it turns out Tiger''s world beating conker is, in fact, a gobstopper on a string.', '2000-02-17', 30, NULL, '2026-04-03T17:10:49Z', '2026-04-03T17:10:49Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('e682c65c-cc4e-4018-be05-80b0ad3e6ba8', '015cceb3-0a47-4f26-a683-81a4696951f0', 2, 'Postman Pat''s 123', 'Tom Pottage is now having trouble with his numbers from 1 to 10, so Pat helps him once again by making Tom a blue 123 notebook.', '1990-10-20', NULL, NULL, '2026-04-03T17:14:29Z', '2026-04-03T17:14:29Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('e6946969-3198-4eb5-b101-7f5ed557bec4', '8a5892f6-ccb7-4f02-9a5a-85b134b5f0cf', 4, 'Unidentified Objects', 'Jones and Dai are relaxing when they spot some strange objects in the sky. The source appears to be Mr Dinwiddy''s goldmine.', '1976-02-16', 5, NULL, '2026-04-03T17:24:25Z', '2026-04-03T17:24:25Z');
