INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('e69574a8-5f3d-44dd-892f-139d81303dac', '8c0f12e1-5379-4a27-aca2-b69401a33b0f', 22, 'Buster Hits the Books', 'Buster needs to write a book report, but he has never finished a book. His friends try to find one he can finish.', '1998-04-06', 13, NULL, '2026-04-03T17:37:55Z', '2026-04-03T17:37:55Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('e69679ce-c377-4a8b-9cf0-ab22d098a1f9', '6f731e6b-d3c5-4de6-84e1-7a19cb650e86', 19, 'Wicked Weapons', 'The Pawn Stars are breaking out the big guns as they revisit some of the most wicked items to ever come in the shop: a thermonuclear weapon warhead cover, a desk with a dark secret, a percussion pistol from the 1800s, a child-sized musket, a collection of knives, a thunder mug, and a massive mortar that bowls Rick over.', '2015-12-17', 21, '/sRKcRJAeNsbZUhGTTw4a7qFDvkK.jpg', '2026-04-03T16:34:20Z', '2026-04-03T16:34:20Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('e698b682-f03e-4cc0-9ca1-aed63804f445', '27947392-39ba-45a6-b67b-fc609eb26e51', 22, 'Baking Blunder', 'The Pontypandy Pioneers bake up a storm to earn their baking badges, but when a greasy oven bursts into flames, they call the rescue teams.', '2023-07-02', 10, '/pE1otS8PT6QLGfsQUEPGqMb8Fny.jpg', '2026-04-03T17:14:41Z', '2026-04-03T17:14:41Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('e6a283e3-51ac-40fc-a3e6-60cbcca324ec', 'e291df42-d44f-49e5-bf81-2df32ee4a30f', 10, 'What''s Mine Is Yours', 'A package comes in the mail for Ojo --- a book from Ursa titled Bears Around the World. Ojo wants to keep it all for herself at first and read it alone, despite Tutter and Treelo''s pleas for her to share it. Bear explains to them that sometimes when somebody has something new, they might want to keep it to themselves at first. But as Ojo becomes excited by the book, she begins to change her thinking. Meanwhile, Bear finds himself sharing quite a bit. He shares his food, he shares his berry-picking bucket with Pip and Pop and he lets Ojo, Tutter and Treelo use his bed as a comfy reading spot. 

Songs 

What''s in the Mail Today? 

What''s Mine is Yours 

Notes 

This episode is somewhat similar to the first season''s "Share, Bear." It involves a picnic, just like in "Share, Bear." 

Bear reads the names of two potential alternate Bear in the Big Blue House shows from Ojo''s book --- Bear in the Big Bamboo House and Canadian Bear in the Big Log Cabin (from Canada, near Saskatchewan).', NULL, 25, NULL, '2026-04-03T17:35:32Z', '2026-04-03T17:35:32Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('e6a6b199-4df8-48a7-a711-9f987b475584', '7c0e1f66-8835-4e8a-8ad9-0eee57155b4c', 6, 'Super Deformed Shorts: School Time Shipping', 'Another edition of Tiny Aang, Katara, Sokka, Toph, Zuko, Iroh, and Appa''s adventures— this time with ever more Chibi characters! The Golden Dragon Dance is coming up and Tiny Aang wants to ask Tiny Katara, but he''s got plenty of competition from Tiny Zuko, Tiny Jet, and Tiny Haru!', '2007-09-11', 4, '/mzSSiOS7YJcIK7g3ewRdKjlMrSe.jpg', '2026-04-03T17:40:47Z', '2026-04-03T17:40:47Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('e6acd4d1-aa41-4193-9e5e-1fd1f1e37387', 'e6359e6d-9bdb-4aba-9cba-6f7ddd6328f9', 16, 'Holy Schnitzel', 'A peaceful horseback ride through the German countryside takes a dangerous turn for Kyle and Lisa Rinna. The ladies get emotional while visiting the Eisenman Holocaust Memorial and Berlin Wall. The group gets into the Oktoberfest spirit when they spend the night dancing at a Berlin beer hall.', '2018-04-03', 43, NULL, '2026-04-03T16:34:57Z', '2026-04-03T16:34:57Z');
