INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('e6c2ea41-693f-4874-b18a-d00365d2591a', '1d713ca6-4e17-4f84-949c-8cfd98514127', 10, 'Shufflin'' and Hustlin''', 'Stay awake with the Pawn Stars when an early, illustrated version of Rip Van Winkle is brought into the shop. Will the beautiful illustrations arouse Rick to spend for this classic or will he end up losing sleep over it? Then, Corey and Chum encounter a candle in the shape of President Richard Nixon''s head. Will this unique item light a fire under the guys or will they get burned? And later, in order to get the Old Man to be more active, the guys take him out to play shuffleboard. But will he play by the rules or will he turn this excursion into a shuffle hustle?', '2014-08-07', 21, '/Y9SCzhhQaMd0mP9DmwPu8LFPr3.jpg', '2026-04-03T16:34:19Z', '2026-04-03T16:34:19Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('e6c85263-bbd7-4c8b-bbd1-402fc5a4ed6e', 'e4023da2-33d7-4a2b-a04a-ca449bd23935', 23, 'Mother''s Day Reservations', 'Mike''s incompetence threatens to ruin Frankie''s Mother''s Day. Mike tells Axl, Sue, and Brick to put some effort into a gift for Frankie. Frankie asks the kids how they would differ from her as parents.', '2015-05-06', 22, '/ooHDGjzMzaLUQujUfoh48ahRlKO.jpg', '2026-04-03T15:40:30Z', '2026-04-03T15:40:30Z');
