INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('e6db33ad-24aa-4575-bec9-2d2d38f1cf0a', '63f9bf6d-39b3-44f4-b885-a56807277a80', 27, 'Of Muppets and Men', 'This made-for-TV documentary treats Muppet fans to a behind-the-scenes look at the making of their favorite program, The Muppet Show. Includes interviews with creators Jim Henson, Frank Oz, and the rest of the crew of the series, as both themselves and as their Muppet characters, who share their experiences from working on the set, as well as discuss the special efforts that went into bringing each episode to life.', '1981-01-01', 26, NULL, '2026-04-03T17:35:23Z', '2026-04-03T17:35:23Z');
