INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('e72ce89f-b181-44db-8950-63771a7ccd23', '465e5a6d-74b6-4ffb-b54f-51103f8329b3', 2, 'Days of Our Wives', 'Day two starts with an afternoon on a luxury catamaran, but a fun day on the ocean quickly goes south when Ramona''s selfish side comes out; during the infamous Bailey-Q, Cynthia is taken aback by the ladies'' reactions to her shady game.', '2021-11-15', 45, '/ie9UJW03az1r5B4Z8by8GAOFUrw.jpg', '2026-04-03T16:34:40Z', '2026-04-03T16:34:40Z');
