INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('e7498c1d-d25b-4597-ab7a-e248780642c0', '787dfa0b-c827-4dad-a82d-0548a6534d88', 21, 'Reunion (2)', 'On part two of the reunion, the ladies get wild and crazy looking back at the best OMG moments of season 10. While Shannon faces scrutiny about her marriage and David''s affair, tensions rise when Heather gets heated about Vicki''s betrayal of Tamra. Jim Edmonds also joins the ladies on the couch and is put in the hot seat about his marriage to Meghan. Briana makes an appearance and is no holds barred when it comes to her opinions about Brooks.', '2015-10-26', 44, '/vD5uPOGcUE4tViTITegqR0mso6S.jpg', '2026-04-03T16:35:32Z', '2026-04-03T16:35:32Z');
