INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('e74f1a37-5f7f-4631-9d62-0f1180eee328', '4d2cac0f-38fd-438b-8afa-acf43952e535', 18, 'Episode 18', 'Toys, model railways, games, stories, cartoons. A weekly programme for younger viewers with Christopher Trace and Leila Williams.', '1959-02-12', NULL, NULL, '2026-04-03T17:21:47Z', '2026-04-03T17:21:47Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('e7557619-e18d-4f16-9a6d-4a92ff5ea255', 'd5383b3d-5636-4d71-b99c-b84774b4b3c6', 16, 'Pingu''s Wish', 'When Pingu is out, he sees a poster fr a magic show and pretends that he’s the magician performing. On the way home he finds a magic wand, and conjures up a hat and four flowers. Pingo comes by and asks Pingu what he’s doing. Pingu turns to Pingo, and while he explains, the hat and flowers disappear. When Pingo says he can’t see anything, Pingu turns and is amazed that the hat and flowers aren’t there. Pingo consoles Pingu, and they walk on together. They reach the toyshop. On display is a magic box that Pingu decides he really wants. He rushes home to ask Mother, but she tells him he’ll have to wait till Christmas. Pingu plods unhappily out. After he’s gone, Mother realises how far away Christmas is and has a change of heart, so she rings Father and tells him to get the magic box on his way home. When Pingu arrives back at the toyshop, he’s dismayed to find that the box has gone, so he goes back home again. When he arrives, Mother and Father are waiting. Father puts on a top hat and pretends to be a magician. He then tells Pingu to cover his eyes. Mother goes and gets a Christmas tree and a wrapped present from where they were hidden. Father makes some more magic sounds and tells Pingu he can now look. Pingu is amazed to see the tree and a present, and on opening the present is really delighted to find that it’s the magic box that he wanted.', '1999-07-26', 5, '/raeQetc1NxWNVaUhfBsqq8f9vQ7.jpg', '2026-04-03T17:22:20Z', '2026-04-03T17:22:20Z');
