INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('e786e333-4719-4679-8236-2a60c5b18d6c', '54900370-8988-46b8-b7aa-61d2b88d7056', 5, 'The Salt Lake City Soup Man', 'Whitney treats her friends to a wine tasting with psychic readings. Bronwyn gets insight on her relationship with her mother and Lisa is challenged to face some hard truths about her marriage. Whitney questions if Britani has been telling them the truth about Jared. Meredith confronts Lisa for spreading rumors about her in the past, reigniting Lisa’s feud with Angie and causing friction between Angie and Mary.', '2025-10-14', 42, '/a2f4qsYlkZ4yOJ1XmouJSPr9Qio.jpg', '2026-04-03T16:35:46Z', '2026-04-03T16:35:46Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('e7916858-8c4c-4fb4-9343-6c5ce3d8667a', '27947392-39ba-45a6-b67b-fc609eb26e51', 9, 'Pontypandy Wonderland', 'When a fire causes a quest to turn into a problem, the firefighters use this opportunity to try out their new uniforms!', NULL, 10, '/zubwm1aq8gj1BFUTROGQIzPOTIb.jpg', '2026-04-03T17:14:41Z', '2026-04-03T17:14:41Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('e792e305-5745-4630-ac30-cfed648b6515', 'ad4e4348-3334-4a08-8928-455d9ba524c1', 24, 'Shirley Bassey', 'Kermit borrows fifty million dollars worth of gold for Shirley''s closing number, "Goldfinger". Security guard Bruno is suspicious that Kermit wants to steal the gold, but keeping an eye on the frog makes him overlook a band of pig thieves, who steal all the gold as Shirley sings.', '1981-03-15', 26, '/wvU1z7hyP7Yd0BKCIMye42cNBio.jpg', '2026-04-03T17:35:25Z', '2026-04-03T17:35:25Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('e794e7df-eb77-4a82-99d1-180e544fcd11', '6ef86c27-33e7-47e5-a053-483059dfd16d', 69, 'Episode 69', 'Lloyds of London

In 1688 Edward Lloyd opened a house near the River Thames for the new popular drink, coffee. Simon reports from the world''s centre for Shipping Insurance, where the tragic Loss Book records disasters like the sinking of the Titanic, and rings the famous Lutine Bell from the French frigate captured by the British in 1793. For over a century the bell has been rung at Lloyds to warn of stop-press events - once for bad news, twice for good.', '1982-05-20', NULL, NULL, '2026-04-03T17:21:55Z', '2026-04-03T17:21:55Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('e7994937-f3a7-4167-8ad0-9df278a32f9b', '9193e795-da7c-40ec-b68f-f63aa7d5174f', 195, 'Season 1 Character Profiles: Tyrion Lannister', 'Character profiles of the 15 main characters in the words of the respective actors.', '2012-03-05', 2, '/dIM1y1OCUwmXauVTDhLYKB3Z1va.jpg', '2026-04-03T15:40:35Z', '2026-04-03T15:40:35Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('e7a06ae2-8394-41ef-9a4a-bcf7f800ce03', '6053b5c1-ce86-425c-8166-e0fcc3466061', 31, 'Episode 31', 'with Valerie Singleton, John Noakes, Peter Purves', '1970-01-01', NULL, NULL, '2026-04-03T17:21:50Z', '2026-04-03T17:21:50Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('e7a17220-45fb-4d45-bea5-7d657a35b3d1', '6f731e6b-d3c5-4de6-84e1-7a19cb650e86', 39, 'Pawn of Liberty', 'Catch a wave with the Pawn Stars when an original Beach Boys surfboard rides into the shop. Will Rick hang ten with a totally awesome deal, or will he have a gnarly wipe out? Next, Rick gets adventurous when a magazine feature penned by Mark Twain turns up. Will it be an instant classic or will it be sold down the river? Then, things get sloppy when an early 1900s spirit hydrometer pours in. Will Corey have the liquid courage to make an offer or will he be off the sauce? And later, things get psychedelic when an original Peter Max Statue of Liberty painting is brought in. Will Rick liberate a deal or will it get torched?', '2016-06-22', 21, '/u2Pi1LrzAdKSW8qmjOZQL16d2Hf.jpg', '2026-04-03T16:34:20Z', '2026-04-03T16:34:20Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('e7a408f4-97fd-41f8-b9e6-5046f6ff4c0e', '84a24124-2290-4b86-aa88-5514da7bd0b6', 10, 'Going Away and Coming Back', 'Chuck Aber surprises Rogers with what he calls his "piece of equipment." It''s heavy machinery used for digging dirt. Mr. McFeely shows a videotape on how tortilla chips are made from blue corn. Friends in the Neighborhood of Make-Believe discover the secret tunnel and learn where it goes.', '1994-04-26', NULL, NULL, '2026-04-03T17:35:47Z', '2026-04-03T17:35:47Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('e7a51487-ffda-49a7-b5d7-198af04cd88c', '49a00924-9169-4b3f-b8f0-d7bd68794db9', 14, 'Off the Rails', 'The ladies of the Garden State reconvene for the first time to watch and react to the finale.', '2024-08-11', NULL, NULL, '2026-04-03T16:35:19Z', '2026-04-03T16:35:19Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('e7a9261d-334d-4a20-a76c-92558568397c', '787dfa0b-c827-4dad-a82d-0548a6534d88', 10, 'Girl Code', 'Hung-over from a night of drinking, Vicki and Shannon deepen their friendship by discussing the details of David''s affair.  Meanwhile, the other ladies head out on an excursion that puts them in deep water. Later Tamra, wanting to get everything out in the open, sparks a controversy over girl code and pot stirring. Meghan surprises the ladies at the final dinner.', '2015-08-10', 44, '/njFRAkSv9wEXSHWmdg2BJopQtQU.jpg', '2026-04-03T16:35:32Z', '2026-04-03T16:35:32Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('e7aa0623-e0f1-457f-be64-5b98465f45fb', '119c16d5-1047-45ec-8242-c72a8eed423b', 16, 'Arthur Bounces Back', 'Arthur''s dream is to have Moon shoes, but he does not have the ten dollars to get them. When he begins working chores to receive money, he got too desperate and does something he will regret.', '1996-10-16', 13, '/jlifaVLg6nCjXN6Rt221e4Nfpru.jpg', '2026-04-03T17:37:55Z', '2026-04-03T17:37:55Z');
