INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('e7b26e7a-2860-4f59-ae87-b7043a2aa7b2', 'b86d15ea-4253-41a5-9f14-4a254ec601e0', 9, 'On Thin Guid-Ice', 'Teresa, her brother and their spouses see a relationship expert; Caroline has a surprising healing agenda.', '2013-07-28', 43, '/7MDPu2dR801V1ruZ1EYWv4SVzAK.jpg', '2026-04-03T16:35:16Z', '2026-04-03T16:35:16Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('e7b7e3f7-1b7d-4ca0-8626-8c32a6b953bb', '05044f49-5f9c-4e7f-a74d-b2ff19475d0e', 14, 'Judgement Day', 'Rumors swirl and create tension between Teresa and Teresa just as Dina''s charity event draws near in the Season 6 finale. Also: Melissa breaks ground on her dream home; and Teresa and Joe Giudice learn their legal fate.', '2014-10-19', 43, '/mgH9cQa4JQFxj2X63X9MmyRhW3k.jpg', '2026-04-03T16:35:16Z', '2026-04-03T16:35:16Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('e7ca19ec-cd42-4642-9eaf-ea8139c68037', '9b95011e-93db-4e56-a45d-8aa956c15997', 6, 'Escape from Pontypandy Island', 'When the Pontypandy Pioneers go on a day trip with Trevor to Pontypandy Island, Norman, Mandy, James and Sarah are all desperate to prove that they will be the best explorers.', '2014-05-10', 10, '/xEzVsAX4xOcTZ1tDj2z50uiMeBK.jpg', '2026-04-03T17:14:40Z', '2026-04-03T17:14:40Z');
