INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('e82334fd-4555-41bc-a88f-aac3a7530e5f', '65d1cad8-0120-425e-ae9b-5020ce773b32', 10, 'Whine or Champagne?', 'The ladies embark on dueling trips as Tamra invites Shannon, Jenn and Gina to Temecula in an effort to rebuild her friendship with Shannon; Heather takes the opportunity to host an adult sleepover in Beverly Hills with Emily and Gretchen.', '2025-09-11', NULL, NULL, '2026-04-03T16:35:36Z', '2026-04-03T16:35:36Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('e8241b05-eba6-40ad-a54b-2b0c26d4a725', '10e64538-c78a-4cb0-82f9-17d14256dbac', 11, 'The Rush', 'As Sue desires to join a sorority, Frankie feels useless when Brick decides to go shopping by himself. Axl helps Mike to use social media for his project.', '2016-01-06', 22, '/tAh9KgJdZuxEbr7iLrWxpED3cMS.jpg', '2026-04-03T15:40:31Z', '2026-04-03T15:40:31Z');
