INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('e82f0608-a814-432e-bc9d-73761692a8d5', 'd920ebae-f00a-4e25-abfe-40492c74ded6', 2, 'A Show About Nothing', 'All ears ring when a rare keepsake from Seinfeld sends John O’Hurley into the shop. Then, Rick travels East after a new ride. Will Rick choose land with the rare 1960s muscle car or will the 1920s rum-running boat lead him to Sea?', '2019-10-28', 42, '/5mx8O9oY6svnSDDrPS6l58XpF0K.jpg', '2026-04-03T16:34:22Z', '2026-04-03T16:34:22Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('e830152f-6883-486b-81a3-28cde694edcb', '272db816-9822-485a-b231-6e060d0ccb1a', 16, 'DELETE ME', 'When Ivor leaves to seek his fame and fortune, who or what can take his place?  Is it worth a load of gold just for the pleasure of seing it go?', '1977-12-16', 5, NULL, '2026-04-03T17:24:25Z', '2026-04-03T17:24:25Z');
