INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('e84e4e44-6705-407d-a180-1efef16cce5e', 'bd8a516b-9872-472d-a838-7aff1070fea3', 8, 'Bernadette Peters', 'Robin wants his own spot on the show, but his uncle Kermit doesn''t even notice him with bigger costars like Thog, Sweetums, and Timmy stomping around. The little frog even tries to run away but just ends up locked in his own suitcase. When Bernadette Peters notices him and tries to cheer him up, however, Robin finds out that all the Muppets believe in him. He becomes so confident that he demands to sing "They Call the Wind Maria," but Kermit settles on a cute, little song called "I''m Five" instead.', '1977-11-18', 26, '/peUxECsz1JNt81hMmw0ulkaAoQ4.jpg', '2026-04-03T17:35:24Z', '2026-04-03T17:35:24Z');
