INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('e86c8329-84bd-48fc-ab9a-988c2cd78206', 'f5c042dc-0657-42e8-a37d-247414140632', 2, 'You Dim Sum, You Lose Some', 'Kameron spars with a controlling Court, who refused to keep her informed about their house-selling process. D’Andra sees her Shaman and reveals that her step mother, whom she hasn’t spoken to in 16 years, has recently reached out to her. Kary’s daughter Olivia comes home from college in Los Angeles suffering from stress and anxiety. Tiffany throws a Dim Sum brunch and finds herself going head to head with Kameron.', '2021-01-12', NULL, '/eeMX0HhntVv8R1A0c4VsHsCUStr.jpg', '2026-04-03T16:35:05Z', '2026-04-03T16:35:05Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('e86ce33a-272d-453e-b893-e81ac419f827', 'bcab920a-51a5-4cbb-aa59-41578a0eb005', 20, 'Reunion (2)', 'Drama continues to run high as Erika, Eileen and Lisa Rinna stand their ground against PK’s attempts to explain himself. The women share insights into their various careers and laugh at the over-the-top ways they greet each other. However, things take a turn when Eden and Kim Richards join the ladies. Simmering issues quickly come to a head and it all becomes too unbearable for one of the ladies.', '2017-04-18', 43, '/fkFnHFJD6bj9Ekl6nVC3L6IwxCj.jpg', '2026-04-03T16:34:56Z', '2026-04-03T16:34:56Z');
