INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('e89f98db-1863-4296-b9d3-17c538a48b86', 'c06f15e3-1abd-4c6c-a4ef-93f3eb85cc89', 7, 'You Win or You Die', 'Robert has been injured while hunting and is dying. Jon and the others finally take their vows to the Night''s Watch. A man, sent by Robert, is captured for trying to poison Daenerys. Furious, Drogo vows to attack the Seven Kingdoms.', '2011-05-29', 58, '/o6ldSDhIINGNKZR62mHf2m64dD.jpg', '2026-04-03T15:40:35Z', '2026-04-03T15:40:35Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('e8a1da79-b497-4e5f-8707-83d87c4bc31a', '9193e795-da7c-40ec-b68f-f63aa7d5174f', 288, 'Creating the Visual Effects: Season 1', 'Creating the Visual Effects: Season 1', '2020-11-10', 18, NULL, '2026-04-03T15:40:35Z', '2026-04-03T15:40:35Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('e8a9eed1-cc51-4332-88e5-fc0712df898c', 'ae8f64d9-4b83-4147-a44c-bfe720381f8e', 1, 'Frankly It''s Becoming a Habitat', 'Big Bird is eating a hot bowl of soup on a cold day outside Hooper''s Store when Freddy Flapman, played by Lin-Manuel Miranda, from Flychert Real Estate, finds Big Bird and tries to convince him to migrate somewhere warm. Freddy Flapman tells him that he might like living in a new habitat and takes Big Bird on a virtual tour! First, Freddy Flapman takes Big Bird to the beach where there are pelicans and gulls and beautiful ocean views. Next, Freddy Flapman transforms Sesame Street into a big swamp where Big Bird learns all about this habitat and where owls and ducks like to live. Freddy Flapman pops up one last time and Big Bird’s nest area is turned into a beautiful rainforest! Big Bird likes it. The rainforest is warm and colorful and has animals of every color and size. In fact, Big Bird likes it so much he wants to move there! Big Bird begins packing and waving good bye to all of his friends on Sesame Street. Just as he is about to leave, Big Bird’s friends remind him of all the things he would miss if he migrated to the rainforest. Big Bird realizes he can’t leave, after all this is where all of his friends are and Sesame Street is where he belongs!', '2009-11-10', NULL, '/7pOrzwkI9hHwWXeMpatdIMYD6WL.jpg', '2026-04-03T17:36:46Z', '2026-04-03T17:36:46Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('e8ab97d1-1a38-4c49-9cdb-1c93178ecd79', 'd5351b60-8a0c-482a-a6dd-4fb860cfe143', 9, 'Episode 1399', 'Mister Rogers arrives with a chromaharp (autoharp) and shows how it is played as he sings Old MacDonald. He shows a picture of a standing harp in a book.

At Brockett''s Bakery, Mister Rogers compares the size of his chromaharp with a large harp in the bakery''s soda shop. Chef Brockett arrives with Edward Druzinsky who plays the harp.

Returning to his house, Mister Rogers finds a note from the Gordons who had stopped by to see him and gone to his home to look for him. Calling his wife, he asks her to send the Gordons back to the television house.

In the Neighborhood of Make-Believe, Handyman Negri and Daniel Striped Tiger are trying out various musical instruments as they wait for the Platypus family to return from Westwood.', '1975-02-27', NULL, NULL, '2026-04-03T17:35:41Z', '2026-04-03T17:35:41Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('e8af9032-9a19-4338-a3ed-e5914bbd2e57', '4d2cac0f-38fd-438b-8afa-acf43952e535', 139, 'Episode 139', 'For younger viewers. Wallis Rigby and Christopher Trace talk about making models that fly. The Girl on the Rock, Hugh Tracey tells a story and Aerobatics, Dreamy Daniel in a cartoon film.', '1961-06-19', NULL, NULL, '2026-04-03T17:21:47Z', '2026-04-03T17:21:47Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('e8b3be0c-7eee-4f0a-ae59-ff9fafba8b1c', 'ba33491a-8f19-4e61-ae9f-0a67db3c65b0', 16, 'The Naked Truth', 'After returning from vacation, the ladies discover that what happens in Mexico doesn''t always stay in Mexico; Ashley spills the beans about Mia and Wendy''s interesting exchange; Charrisse shares a story about Karen that leaves the ladies shocked.', '2023-01-29', 44, '/104lCOT1OlnQEbg7RTSqFZ5402Y.jpg', '2026-04-03T16:35:40Z', '2026-04-03T16:35:40Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('e8b5b9f0-288f-4f15-9e1d-5d9b25b0379c', '50ee8f6c-645c-4d48-bab9-53b9f8f7ff2f', 2, 'Rocco''s Boat', 'Elmo and Zoe make a boat for Zoe''s pet rock Rocco.', '2011-09-27', NULL, '/bZgQewaIS9IXFsVmsFX4aEpu1N5.jpg', '2026-04-03T17:36:46Z', '2026-04-03T17:36:46Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('e8b7925d-787f-4698-8068-175d1c6a709b', '89dd3601-0e7f-4ca9-bdf6-de9f731329e3', 9, 'Teacher''s Pet', '', NULL, NULL, NULL, '2026-04-03T17:40:29Z', '2026-04-03T17:40:29Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('e8c46531-4d95-4bdc-aa0f-bb448641d130', '7c422193-b078-49d8-81ef-f2b9f94f059d', 42, 'Telly hosts "The Wide World of Numbers" (repeat)', 'Episode #3047

The main story of this episode is a repeat of episode #2823.', '1993-01-05', 55, NULL, '2026-04-03T17:36:39Z', '2026-04-03T17:36:39Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('e8c7c256-4eeb-4571-b585-38184ab9c593', '3ea743ef-0a22-47cf-b1d2-62f37e939253', 7, 'Cousin Bear Is Afraid of Shadows', '', '2002-02-12', NULL, NULL, '2026-04-03T17:36:43Z', '2026-04-03T17:36:43Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('e8c860ac-9575-497e-a7d0-91bfee2e3eaf', '9310a288-5af0-4746-a8d7-d7635ffb6beb', 11, 'Mister Rogers Talks About GRANDPARENTS', 'Rogers takes the model Neighborhood Trolley to the Pennsylvania Trolley Museum in Washington, PA filled with real trolleys. He rides one of the restored trollies (Philadelphia Rapid Transit Company #5326) in one direction and drives it back in the other direction. After returning to the television house, Rogers shows the controls of how he operates the Trolley. In the Neighborhood of Make-Believe, the Trolley and everyone else is surprised with a French trolley called "Grandparents'' Express." It has a message for Grand-père that his granddaughter Colette is visiting.', '1984-05-07', NULL, NULL, '2026-04-03T17:35:43Z', '2026-04-03T17:35:43Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('e8d6a6a5-c76b-43c1-9838-63b8bb8b8d0a', '4a8e3db0-8068-4ff3-942f-91f45f665f20', 14, 'Lionel''s Great Escape Trick', 'Lionel gets a few pointers on the technique of doing magic tricks, from the master magician Harry Houdini, himself. When he locks himself in the closet for his act, though, Leona fears that he''s stuck in there, so she asks Click to come up with some magic words in order to get her brother out of the closet.', '2000-04-20', 30, NULL, '2026-04-03T17:12:27Z', '2026-04-03T17:12:27Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('e8d7f25d-a21e-4f18-aecb-d66e862e1b6f', '05c0e384-194c-4417-9f62-803eb615e409', 81, 'Mail delivery', 'John Reardon pretends to be a mailman while he visits the Neighborhood of Make-Believe. He sends a note that King Friday and Edgar Cooke are staying with Sara Saturday a few extra days. Lady Elaine, meanwhile, wants to set up a campsite at the Castle garden.', '1968-06-10', NULL, NULL, '2026-04-03T17:35:38Z', '2026-04-03T17:35:38Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('e8ddc99e-16f9-4374-91b1-444c89844c02', '5b5e8b2f-0a85-4488-b3dc-3d8b794e6582', 9, 'Drag Bingo Bombshell', 'Kelly suspects her new pal Shannon of being up to her old tricks and confides in Meghan. Meghan puts her detective hat back on to investigate Vicki''s issues with Shannon and Tamra. Vicki''s looking to move forward with her new love, while Peggy takes her daughter to New York. The ladies attend a Drag Bingo event, where Lydia faces a moral dilemma and old arguments spark anew.', '2017-09-04', 44, '/6hBqWNUF04TqHBFbPSRLwe5pHTZ.jpg', '2026-04-03T16:35:33Z', '2026-04-03T16:35:33Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('e8df1085-45cc-4b73-b8d6-83f0890d6f98', '96dd06ee-d44a-47f3-9372-e29e8eaa77f5', 3, 'Thief in Pontypandy', 'Sam''s mislaid his watch, Bella''s necklace has disappeared and Dilys'' earrings have gone missing! Can Sam solve the mystery?', '1988-09-15', 10, '/z3o5ZBSpobjqpICUKmoRFSOhwpb.jpg', '2026-04-03T17:14:37Z', '2026-04-03T17:14:37Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('e8e00e74-d5e6-4b90-9a27-d4d3c0023829', 'ae8f64d9-4b83-4147-a44c-bfe720381f8e', 23, 'Tribute to Number Seven', 'Today is the number seven day on Sesame Street! Rosita, Abby, and Zoe begin singing about the number seven as they count seven dancing chickens. Next, Maria does the number seven rumba. As the seven celebration continues, a sniffling letter “S” arrives. He is sad because he can’t think of anything to do to help celebrate the number seven. Abby and Zoe get an idea! What if the letter “S” finds seven words that begin with the letter “S?”

Abby, Zoe, and the letter “S” search for seven “S” words, and then sing a song about the words. Afterward, Abby performs number seven magic. Abby makes the number seven rise out of Elmo’s hat, seven butterflies appear out of Elmo’s ear, and—oh no! Seven Elmos appear instead of seven pumpkins! Luckily, Abby turns seven Elmos back into one Elmo, and tries her magic trick again. She succeeds! Abby turns one pumpkin into seven pumpkins. Hooray! It is an amazingly, awesome, super terrific, seven celebration!', '2010-01-27', NULL, '/5LauTbay0wS5Ejw6S2JgRhGojFb.jpg', '2026-04-03T17:36:46Z', '2026-04-03T17:36:46Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('e8e051fa-f6bc-496b-bc5a-28c74e87949e', '050d8ae1-6cc1-4018-933d-b3c3d13de856', 77, 'Episode 77', 'Janet goes back in time to the 1890s and the days when grand houses were the setting for glittering parties. At Warwick Castle the guests for dinner one hot June evening in 1898 included two future kings, a prime minister-to-be and a dazzling array of High Society''s most beautiful ladies. You can meet them all, as they prepare for the feast!', '1985-06-17', NULL, NULL, '2026-04-03T17:21:57Z', '2026-04-03T17:21:57Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('e8e6fc9b-0c4d-4ec1-a2be-b0a892318e0c', '9193e795-da7c-40ec-b68f-f63aa7d5174f', 223, 'New characters and locations', 'Explore the new races, cultures and locations in Season 5.', '2016-03-15', 8, '/1HIA0ahWr4MxF6psVvJ9ZGORMN0.jpg', '2026-04-03T15:40:35Z', '2026-04-03T15:40:35Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('e8f0cbeb-f7c5-4243-b9ff-906f2dbbb5cf', 'd46f25ad-9612-4516-91df-d1ace11fec38', 2, 'Gaming Top Tips and Joel''s Toughest Challenge Yet', 'Top online gamers Yammy and Slogo join us for gaming masterclasses on Minecraft and Roblox. Meanwhile, Joel takes on his toughest challenge yet – scaling heights and descending cliffs to try to complete the Royal Marines Mountain Leader training.', '2025-09-12', 25, NULL, '2026-04-03T17:22:12Z', '2026-04-03T17:22:12Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('e8f41980-abe2-4e68-b103-3b701bc554bf', 'ca3f764e-b330-4980-bd7a-2908a73b77b6', 14, 'Malibu Beach Party from Hell', 'Brandi Glanville tries to throw a nice party for the women at a Malibu beach house, but the tension between Taylor Armstrong and Camille Grammar reaches a boiling point.', '2011-12-05', 43, '/oiSNGnAYVXhQJBoQseNdjyrbfYK.jpg', '2026-04-03T16:34:54Z', '2026-04-03T16:34:54Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('e8f467c1-9b78-4b42-aaa0-448a2507857d', '99202760-98d0-4dda-ab20-48d2b5c65987', 6, 'The Ricks Must Be Crazy', 'Rick and Morty travel inside the car''s battery, where Morty discovers Rick has created a universe containing sentient life solely to produce power for him. Meanwhile, Summer must deal with being locked in the car with Rick''s overzealous security system.', '2015-08-30', 23, '/9T5ZiW2qhqMRdx79q800SBYbxDv.jpg', '2026-04-03T15:40:41Z', '2026-04-03T15:40:41Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('e8f4d85f-bcf9-485f-9714-fbb09ffb59ab', 'bf3ffafd-7d45-4f2c-9f1b-28001bd082db', 71, 'Episode 71', 'Lesley visits Helston for one of Cornwall’s most important events -Flora Day. From dawn to dusk, thousands of people throng the streets singing and dancing the famous Furry Dance. Lesley investigates the behind-the-scenes preparations and joins in with the traditional revelries.', '1975-05-19', NULL, NULL, '2026-04-03T17:21:52Z', '2026-04-03T17:21:52Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('e8f4ff9b-f7f2-490f-aa37-a889392f3fb1', '87989283-6fea-40d7-8d91-22c4947db105', 4, 'Four Wives, One House?', 'On Christmas Eve, Kody finally presents to his family his pitch for all four wives to live in one big house. Janelle actually likes the idea, but Christine is dead set against it. Merry Christmas!', '2020-01-19', NULL, NULL, '2026-04-03T16:34:31Z', '2026-04-03T16:34:31Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('e8f7424a-22ca-4ad4-a3d2-0ddcd2a80a98', '6ef86c27-33e7-47e5-a053-483059dfd16d', 30, 'Episode 30', 'The latest news of the Operation Pipeline Appeal. Your stamps and coins are still desperately needed to give villages in Java supplies of pure water, and the Depot at [address removed], is open over Christmas except for tomorrow and Boxing Day.

Join in with carols round the tree with children of Allfarthing''s School, Warlingham County Secondary School and the Band of the Chalk Farm Branch of the Salvation Army, and can you penetrate the disguises worn by Simon, Sarah and Peter in the Blue Peter Panto?', '1981-12-24', NULL, NULL, '2026-04-03T17:21:55Z', '2026-04-03T17:21:55Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('e8f75db4-8959-4428-9ce8-22db7d26dfa2', '1be79a20-de33-41d1-af17-079035b18d5c', 116, 'Episode 116', '', '1970-04-20', NULL, NULL, '2026-04-03T17:36:28Z', '2026-04-03T17:36:28Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('e8f79388-b4dd-49bb-a63f-f1b37c071f06', 'd3e13496-e3c8-4903-83b4-5a31fedee232', 10, 'Jet', 'While traveling towards the North Pole, the group almost gets captured by the Fire Nation.  However, when a charismatic young man and his band of rebels attack the Fire Nation camp and rescue them, they learn that they are trying to resist the Fire Nation’s motives to expand their territory.  Katara and Aang really enjoy their time with the band of rebels, but Sokka soon discovers that they aren’t as noble as meets the eye.', '2005-05-06', 25, '/aoHnmhUAmMDx8oV9iimMVsScvrW.jpg', '2026-04-03T17:40:47Z', '2026-04-03T17:40:47Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('e8fa8658-b3ce-496d-8dc3-a907b4fbd5d4', 'ab509c47-ec64-4fb3-8560-03873dd0c37e', 19, 'The Jimmy', 'A gym member teams with George in business and makes a date with Elaine to see Mel Torme; Jerry suspects his dentist of hanky-panky.', '1995-03-16', 23, '/4qnf5cnEKZnLGR7Y04qsTwMSjw0.jpg', '2026-04-03T16:34:11Z', '2026-04-03T16:34:11Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('e9007883-d5c6-4e86-b821-05d8e3c8bc93', 'b7538712-04ce-43a6-9163-62280bbb084b', 49, 'Oscar accidentally wishes Maria "Buenos días" (3899)', '', '2000-03-09', NULL, NULL, '2026-04-03T17:36:42Z', '2026-04-03T17:36:42Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('e902c649-6873-4029-b0b8-ca46371f5ce9', '831e3a6b-c1a7-48b7-a5ac-b18ed67beb10', 1, 'Mind Your Manners', 'Welcome to Potomac, where proper etiquette is key, and breaking the rules comes with serious consequences. At a birthday party celebrating Karen Huger, grande dame of Potomac high society, Gizelle Bryant’s lack of manners puts the two divas into a battle for supremacy. And as if that wasn’t enough, Gizelle is under fire from Charrisse Jackson Jordan, for acting not very lady like in her plush home. International model Katie Rost, a divorced socialite with three toddlers, is doing everything in her power to get her boyfriend to put a ring on it. Meanwhile, Robyn Dixon, who lives with her ex-husband, former NBA star Juan Dixon, must decide if she wants to rekindle her relationship with her ex.', '2016-01-17', 42, '/nELt2MS9a2tq5Y5oOf6XxDWucMm.jpg', '2026-04-03T16:35:38Z', '2026-04-03T16:35:38Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('e904c689-f90d-45f6-bfb0-4dfd05b3939f', 'ac068b8e-80f6-46bf-afb2-dcebcf76dc36', 9, 'Up!', 'Julie and Ben are surprised by Kyle''s new activity of rock climbing. They incorrectly assume that people who use wheelchairs can''t do something physically challenging, like climbing rocks. They soon become Kyle''s biggest supporters, though.', '1998-12-03', 29, NULL, '2026-04-03T17:12:21Z', '2026-04-03T17:12:21Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('e9088f30-22de-4eb2-b350-a13f5b328f32', '4eb9b495-7962-41d9-ba8a-3bed48d9bcc6', 8, 'Help!', 'The search for a lost book helps Theo and Cleo teach the cubs about responsibility.', '2002-11-04', 30, NULL, '2026-04-03T17:12:28Z', '2026-04-03T17:12:28Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('e90be924-6465-46a1-95f1-357d00c7af5b', 'a3a2c2fb-8276-412c-9d86-5175167be1d7', 65, 'Episode 65', 'with Valerie Singleton, John Noakes, Peter Purves', '1972-04-27', NULL, NULL, '2026-04-03T17:21:51Z', '2026-04-03T17:21:51Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('e90f5e19-b7ec-4e24-b093-400e408ea46e', 'fe19a277-aed8-44df-a4ac-fc1c4e9941b4', 8, 'Scrambled Egos', 'Kandi pushes an emotional Kim to face her fears and step back into the Atlanta music scene. Will Kim attempt to record again? Newly single Sheree shapes up with her expensive fitness trainer, who attempts to find her love. Meanwhile, all of the ladies get glammed up for a black tie event to reveal their edgy Alter Ego photos, but the night takes a dramatic turn when Kim has a serious accident and steals the spotlight from everyone.', '2009-09-17', 43, NULL, '2026-04-03T16:34:45Z', '2026-04-03T16:34:45Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('e914a0b1-65f4-4a31-b656-51c2dafca4e1', 'd1d267dd-e27f-4543-acb8-0d28f676512a', 38, 'Episode 38', 'with Valerie Singleton, John Noakes, Peter Purves.', '1968-01-15', NULL, NULL, '2026-04-03T17:21:49Z', '2026-04-03T17:21:49Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('e918530a-f635-40bf-a097-bea4251bdd46', '4d2cac0f-38fd-438b-8afa-acf43952e535', 208, 'Episode 208', 'All Aboard! with Christopher Trace and Valerie Singleton in a magazine programme for younger viewers.', '1962-11-19', NULL, NULL, '2026-04-03T17:21:47Z', '2026-04-03T17:21:47Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('e91e207a-388f-412b-b1ab-0548e1b92f58', '61e0c9d9-337e-4fe4-a0fd-e567b29af115', 12, 'Mazel, Meredith', 'Meredith becomes a bat mitzvah. After breaking Whitney and Angie''s trust, Bronwyn is confronted for spilling their secrets. Mary tries to work through her issues with Meredith while grappling with personal issues at home. The party takes a surprising turn when hair argument arises.', '2024-12-04', 43, '/8umF8Q8gP8DyIzlSK6fIVBpF4tU.jpg', '2026-04-03T16:35:45Z', '2026-04-03T16:35:45Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('e91f1d9c-e770-4c23-8308-d60ce3bb1e94', '8a5892f6-ccb7-4f02-9a5a-85b134b5f0cf', 6, 'Chickens', 'Ivor has gone off on his own again. Dai gets quite cross about it, while Jones finds Ivor at Mr Pugh''s farm along with some guests.', '1976-02-03', 5, NULL, '2026-04-03T17:24:25Z', '2026-04-03T17:24:25Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('e922feb0-1452-4b33-862a-837853a030f1', 'c13cac45-2554-4775-bb86-c6aa65c1ca2e', 1, 'Wild in the USA', 'Steve follows Terri to her home state of Oregon, and to New York, to watch beavers and raccoons. Steve also helps Terri to relocate her pet cougar, Malina. Animals are alligator snapping turtle, American alligator, grey kangaroo, freshwater crocodile and red-belly black snake.', '1997-04-05', 44, NULL, '2026-04-03T17:39:10Z', '2026-04-03T17:39:10Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('e9243dce-6f19-45dc-8e94-e060f7475362', '1a534647-384b-4c00-bb6c-a3371ad962eb', 37, 'Coolest Collectibles', 'Geek out with the Pawn Stars and revisit some of the Coolest Collectibles ever to make their way into the shop: a $40,000 Elvis worn Super-fly Coat, a massive collection of Star Trek memorabilia, a copy of the first ever "Playboy" magazine featuring Marilyn Monroe, a1963 first Edition of "The Amazing Spiderman" and a Replica of the Batmobile that drives Chum batty.', '2015-06-11', 21, '/54IKhruM1C8v2XJ8CRXkjOuEcvJ.jpg', '2026-04-03T16:34:19Z', '2026-04-03T16:34:19Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('e928b180-4269-432b-9473-bb62e4622da5', '740a96a0-a075-4be2-be92-a178d0939384', 6, 'Clothing Drive', 'Rudy''s favorite sweater no longer fits him, so Nina suggests having a clothing drive where everyone can give clothes they do not need to people who do need them; Rudy''s sweater goes to a little girl who is very excited to wear it.', '2017-12-23', NULL, '/9nrvXGw59irjYcdbv4SUcbjnbtN.jpg', '2026-04-03T17:36:49Z', '2026-04-03T17:36:49Z');
