INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('e9379ce8-ef9c-4646-8a5c-3c93a3d4083e', '5fa796b4-eaa3-4d89-a746-0a8b86cb8432', 1, 'The Magic School Bus Inside the Earth', 'Burton introduces the episode by talking about cavern and cave exploring. The featured book, "The Magic School Bus Inside The Earth", is narrated by Keshia Knight Pulliam. Eccentric Ms. Frizzle takes her students on a science field trip to the center of the earth while teaching them about geology. Burton then visits California Caverns, where he learns about stalagmites, stalactites, and other crystal formations and goes spelunking with a cave expert.', '1990-09-10', 30, NULL, '2026-04-03T17:36:17Z', '2026-04-03T17:36:17Z');
