INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('e987c22c-9acd-4036-a499-eaaadc532016', '7c542833-ed0a-4272-9c53-e822408ab434', 22, 'History Trails', 'When Professor Pickles decides to create a historical walking trail, he doesn''t realize that his decision to use real props instead of cardboard ones will result in an emergency of big proportions.', '2024-11-06', 10, '/fXKeuruQrtqr6ftdmtAyD28OpEQ.jpg', '2026-04-03T17:14:42Z', '2026-04-03T17:14:42Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('e98a3bf5-8e67-4ac9-999e-b9283052ba25', '3982796b-5451-4100-9042-46bedf6a20a5', 6, 'Pingu''s Curling Game', 'Robby, who has a proper curling stone, invites Pingu to have a game with him. Pingu doesn’t have a curling stone, but borrows Mother’s hot water bottle to use instead. On their first go, Robby gets his the furthest, on the second Robby again gets his the furthest, but both finish up near a neighbour who is sitting on an ice block reading, and he tells them off for disturbing him. They swap stones, and play back the way they came. Robby wins this as well. Pingu is annoyed, and plays the stone as hard as he can. Unfortunately, it goes toward the neighbour who is reading and knocks the seat from under him, depositing him on the ice on his backside! He is understandably rather annoyed at this and goes to tell Pingu off, but Robby tries to pull him back. This annoys him even more and he follows Pingu home. Pingu goes indoors and hides, but the neighbour bangs on the door and comes in. The neighbour explains to Pingu’s Mother what has happened, and Mother gets Pingu to apologise. Fortunately, by now the neighbour has cooled off a bit, and he and Pingu shake hands. The neighbour and Pingu then have a game. Pingu gets his the furthest (because his jumps over the other!), much to the neighbour’s annoyance.', '1992-01-26', 5, '/enTgwx7Y1WRZEnaltIMOOtxlmst.jpg', '2026-04-03T17:22:19Z', '2026-04-03T17:22:19Z');
