INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('e9c05738-940d-41e5-abcd-1eb93b6f597f', 'ca19f895-1514-4988-a709-95e84eab7cee', 9, 'Gotsta Get Pawned', 'Chum huddles up for a chance to buy an early 20th century football. Can he get this deal across the goal line before the seller hikes up the price? Next, a life-size Spider-Man flies into Rick''s web. Will his spidey senses tingle for an offer? Then, a vintage military ID maker marches into the shop. Will it leave an impression on Corey, or will he let the dog tags out? Finally, ZZ Top''s Sharp Dressed Man, Billy Gibbons makes a surprise appearance at the Gold & Silver. He''s here to reclaim some lost memorabilia, but first someone''s Gotsta Get Paid.', '2021-01-04', 42, '/joawCpYkvZw18mcewLSAAe5u3y6.jpg', '2026-04-03T16:34:22Z', '2026-04-03T16:34:22Z');
