INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('e9d5c5d3-aede-4f26-8e35-52bdb2633a1f', '6f731e6b-d3c5-4de6-84e1-7a19cb650e86', 3, 'Fender Bender', 'Get heroic with the Pawn Stars when a 1939 Superman doll flies into the shop. Will Rick save the day and make a deal or will it be his kryptonite? Then, Corey gets electrified when a 1952 Fender Telecaster guitar jams in. Will it have the rock `n'' roll chops or will it get the axe? Later, an antique Japanese matchlock gun shoots into the shop. Will Rick draw first and make an offer or will he bite the bullet?', '2015-10-29', 21, '/tgtW2SJjzpEZCN3c51xMG9QNBcp.jpg', '2026-04-03T16:34:20Z', '2026-04-03T16:34:20Z');
