INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('ea6652a1-79a7-4d8a-826d-6063aa1f269e', '90cc8678-a14f-4d05-bc1e-54a3117895d5', 9, 'Narrow Escapes', 'Bold is helpless and starving due to his gunshot wound but luckily for him Crow agrees to help him and fetches Shadow. She tends to him and stays with him until he feels stronger. But while she goes out hunting he slips away not wanting to be dependent on anyone. He heads towards a farmhouse where Shadow catches up to him. She understands his need to be independent and live his own life and tells him to be careful. He catches a chicken but alerts the farmer and his dog who give chase. Bold dashes down a nearby hole but the farmer tries to dig him out. Falling debris lands on Bold and knocks him unconscious, making the farmer believe that he is dead. Crow tells him that he is extremely lucky and suggests that if he still wants to feed off humans to try the town.   The rest of the Farthing Animals are still worried about Scarface. Adder gets cornered by him and hides down a hole but not before he tears her tail. The animals decide to punish the Weasels and hold a trial for them. Fox sets', '1994-03-04', 25, '/p89DHYyRjdFHnpkQBYbxSotCNOQ.jpg', '2026-04-03T17:18:49Z', '2026-04-03T17:18:49Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('ea755ae2-6fff-433c-ab6c-e62c7c65036f', '4d2cac0f-38fd-438b-8afa-acf43952e535', 223, 'Episode 223', 'Christopher Trace and Valerie Singleton introduce a magazine programme for younger viewers, Including In Search of a Unicorn: Part 1, a new adventure series by Edward and Anna Standon and Ballet for Athletes - David Blair, Premier Danseur of the Royal Ballet, assisted by David Morse and Sandy Davies, shows more ways in which ballet exercises can help all kinds of sport.', '1963-03-11', NULL, NULL, '2026-04-03T17:21:47Z', '2026-04-03T17:21:47Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('ea78edfb-75c3-4299-867a-0431be2bcbc5', '5a6d9a42-165b-4b56-9273-0a06874dfe10', 9, 'Madeline and the Easter Bonnet', 'Just in time for Easter, Madeline updates the old hat belonging to Bon Bon, the milk horse. But then an enormous gust of wind sends the hat flying across town, into the shop of a struggling designer, who attempts to market it in time for Easter.', '1993-09-26', 30, NULL, '2026-04-03T16:34:01Z', '2026-04-03T16:34:01Z');
