INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('ea86d386-41d3-4f71-bc76-b7c0b4bd1081', 'e03d79bd-e01f-4414-b0b3-f3b5f26e97f4', 13, 'Super Sunday', 'As the Super Bowl approaches, Mike is thrilled when Brick takes his advice and studies up on football in order to understand and talk the sport. But Axl thinks his little brother is taking over his turf by being Mike''s football buddy - a position Axl used to cherish. Meanwhile, Frankie thinks her professional career is looking up when Mr. Ehlert chooses her to accompany him to a managerial seminar, and ex-boyfriend Brad asks Sue to be his dance partner for the school''s annual Square Dancing with the Stars.', '2011-01-19', 22, '/ifjsWvn6ox0ogozxKuw3PAxnj6C.jpg', '2026-04-03T15:40:29Z', '2026-04-03T15:40:29Z');
