INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('ea89c6e2-af49-4b72-b081-99a19d38d2de', 'eb7e3bb4-5746-4577-81c6-f5b2dc2efc6e', 1, 'The Avatar State', 'Plagued with nightmares featuring the devastating power of his Avatar State, Aang and the gang meet an Earth Kingdom general who has big plans for defeating the Fire Nation. Meanwhile, Zuko and Iroh, having survived the failed attack on the North Water Tribe, have a surprise visit from Zuko''s sister with seemingly good news.', '2006-03-17', 25, '/oIy3PKC460qRbiPIxNKiuVf9QSH.jpg', '2026-04-03T17:40:48Z', '2026-04-03T17:40:48Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('ea8dda4d-93fa-468c-bd40-36e519e2000a', '20487d17-58fa-43a1-8d44-0d0423a9c960', 8, 'High Flyin'' Dragon', '', NULL, 29, NULL, '2026-04-03T17:12:14Z', '2026-04-03T17:12:14Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('ea8e175d-726e-464c-bf77-b54eff53ea42', '54900370-8988-46b8-b7aa-61d2b88d7056', 14, 'My Big Fat Greek Mother''s Day', 'It''s Mother''s Day in Santorini and Meredith''s mood sours after missing a chance to speak with her son. Tensions linger after the previous night''s dinner. The group shares laughs poolside before heading out for the night.', '2025-12-16', 42, '/y4oDCUNnUxarkh6KQyIjMc917pY.jpg', '2026-04-03T16:35:46Z', '2026-04-03T16:35:46Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('ea8f7e51-1716-47b7-b13d-86de2546328c', 'ba99b779-cada-43a7-902a-2adb472c2e30', 3, 'Episode 3', 'Things look too good to be true with their new human friend bringing them more presents than they know what to do with. Unfortunately, it is too good and the family of borrowers is discovered and the rat catcher is called in.', '1992-11-22', 30, NULL, '2026-04-03T17:17:47Z', '2026-04-03T17:17:47Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('ea98eb89-a39c-422b-abbf-02f075a8090a', 'bf874be3-7e2f-4a0e-b205-c76ac1ad69fc', 94, 'Inside Looks (on The Race)', 'Inside look from the season 6 episode "The Race."', NULL, 22, NULL, '2026-04-03T16:34:09Z', '2026-04-03T16:34:09Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('ea9f2e89-8309-4c24-84b8-3926af9dc071', '526bd779-909a-480d-a38d-1fa625a7c21f', 4, 'Karen''s Grande Dame Reunion - Part 1: The Grande Dame of Surry County', 'Karen sets out to plan her first ever family reunion at the Wooden farm in Surry County, Virginia - but it''s not all fun and games. Prior to the reunion, Karen''s young cousins task her with confronting Karen’s Aunt Val, the current owner of the family farm, about the succession plan for the land. With no plan in place, the younger generation could lose everything - but the question is, does Val want to lose control?', '2022-04-17', NULL, NULL, '2026-04-03T16:35:38Z', '2026-04-03T16:35:38Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('eaa4fd43-1693-44fe-938f-89fc25e313ea', '831e3a6b-c1a7-48b7-a5ac-b18ed67beb10', 8, 'All Shades of Shade', 'Gizelle''s inner entrepreneur takes center stage, but the shade is real when Katie blows off a focus group for her budding makeup line. Juan and Robyn take a romantic trip down memory lane, making her more confused than ever about the state of their relationship. Karen launches a charity event close to her heart, but Ashley and Michael must get "on par" before they are welcome in her home. And will Karen push Ashley one-step too far?', '2016-03-20', 42, '/xbgOwSFacyzhzWUmls68NeZIMii.jpg', '2026-04-03T16:35:38Z', '2026-04-03T16:35:38Z');
