INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('eaa9a23b-39b6-4511-9853-c6d0ba0e3d22', '66006278-baf0-485f-8dad-b214343509f6', 3, 'Conjunction Junction', 'A train yard engineer helps us understand conjunctions.', '1973-09-29', 4, '/59H0g9uYFaFok55QBrCaHyJuG3X.jpg', '2026-04-03T17:13:55Z', '2026-04-03T17:13:55Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('eaaa72b1-3d6b-4c3f-a0f5-d6a66f4b6a68', 'd034c38d-c0c7-42b4-8876-394b63d84275', 5, 'No Hate', 'Peggy consults a nip-tuck surgeon. Meanwhile, Vicki has trouble balancing her workload demands with family time. And Fernanda throws a party to celebrate her citizenship, but tensions run high when Tamra can''t attend.', '2011-04-03', 44, '/pXkqR6vgO133Ii5s46w26Hl9Bq1.jpg', '2026-04-03T16:35:31Z', '2026-04-03T16:35:31Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('eaab2e74-8b83-4fb9-8c4f-58f30426471e', '2b968a9c-5fc0-4e93-bcf9-31d3e4c7b210', 2, 'Episode 2', 'For the past six months Buttons, the 3 Bs Appeal trainee guide dog puppy, has been puppy-walked on the programme. Now, in her Advanced Test, she has to prove whether or not she''s good enough to go away to school to be enrolled at a Guide Dogs for the Blind Training Centre.', '1975-09-11', NULL, NULL, '2026-04-03T17:21:52Z', '2026-04-03T17:21:52Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('eab37d98-8d31-4119-a269-eaebb3fb0165', '095258d0-d8db-4096-8ac7-6a42cd4cbdcf', 8, 'Believe It Or Not', 'Red and Wembley decide they''re going on an adventure out in the Gorg''s Garden today. At the same time, Ma is trying to get Pa and Junior to clean the basement, which is something that they really don''t want to do. Junior catches a fluffy little creature named Skinfrith, and then Red and Wembley set him free so they can have some fun. But what they don''t know is, this Skinfrith is a magical creature that can change into anything that someone can imagine. And before long, Skinfrith gets into the Gorgs'' basement, and Ma thinks there''s a terrible beast inside, which is what Skinfred turns into. Wembley and Red sneak in to save their new friend, but they need to convince Ma Gorg, who''s trapped in the basement with them, that Skinfrith isn''t all as bad as he seems.', '1985-02-18', 24, '/2ZJJB220b8OEoc2xeGLUvrOuhmh.jpg', '2026-04-03T17:35:00Z', '2026-04-03T17:35:00Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('eab655a8-d484-4270-9ff0-4e10176ec9b0', '4861ce46-9045-43c7-963f-27b4ea539804', 104, 'Episode 234', '', '1971-04-01', NULL, NULL, '2026-04-03T17:36:28Z', '2026-04-03T17:36:28Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('eabaf19c-1cf2-4a87-a264-36a8b4fa1e03', '2b968a9c-5fc0-4e93-bcf9-31d3e4c7b210', 51, 'Episode 51', '', '1976-03-04', NULL, NULL, '2026-04-03T17:21:52Z', '2026-04-03T17:21:52Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('eabb0296-941a-48b3-aad0-94ee1c53cef8', '97616d6e-5c17-449f-a376-55f1da83d6c3', 16, 'Mister Rogers Talks About MAKE-BELIEVE', 'Mister Rogers arrives with a small kitten which causes a bit of a distraction as he opens with Won''t You Be My Neighbor. After changing his shoes, Mister Rogers explains that he found the kitten outside and believe that it belongs to Chuck Aber. A quick phone call to Mr. Aber lets him know that his kitten has been found.

Arriving quickly by way of his sister''s car, Mr. Aber is reunited with his kitten before he sings and slightly altered version of Sometimes People are Good: "Sometimes kitties are good..." Showing viewers the inside of the car, Mister Rogers takes a moment to talk about seat belts, car seats, and other automobile safety. Back inside, Mister Rogers shows a film about workers installing seat belts in cars.', '1982-06-30', NULL, NULL, '2026-04-03T17:35:42Z', '2026-04-03T17:35:42Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('eabe4093-3dad-4912-b072-85406e14df23', 'f4d370ca-3c39-40a8-911d-e2b5e7c6b0d7', 4, 'The Colour Chase', 'The toys are having a drawing competition and when it’s finished they want to play another game. Old Bear suggests they have a competition to find objects that match the colour of the pencil they have chosen. They all set off in search of coloured objects that match their pencils. Little Bear is disappointed that he picked brown for his colour because he can’t find many brown things but gets a double surprise as the colour chase comes to an end.', '1996-09-25', 10, NULL, '2026-04-03T17:18:56Z', '2026-04-03T17:18:56Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('eacb654e-060c-431f-a21e-53dd5d09b4e7', 'dd4554c2-6e74-499a-808a-7dad5f2be50f', 11, 'Confessions', 'Jesse decides to make a change, while Walt and Skyler try to deal with an unexpected demand.', '2013-08-25', 48, '/w8Aw3SPdT3uyZpP2pCnKHEIMYj3.jpg', '2026-04-03T15:40:34Z', '2026-04-03T15:40:34Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('eacdcb18-d327-400d-9e9b-9b342bb47279', '55930d10-8ec2-4a20-8c94-52d9b5329bae', 7, 'The Gift', 'Jon prepares for conflict. Sansa tries to talk to Theon. Brienne waits for a sign. Stannis remains stubborn. Jaime attempts to reconnect with family.', '2015-05-24', 59, '/n4BFZfiqOX1l5l6uYtpDS4m19WX.jpg', '2026-04-03T15:40:37Z', '2026-04-03T15:40:37Z');
