INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('eaffc1fa-05f8-4691-8e75-f28bb34e3969', '53587a7e-cd93-44f0-ad79-5fe586dccb8e', 2, 'The Umbrella', 'Kipper''s friend invites him to go fishing, but the only thing he can find to use as a fishing pole is an umbrella, which brings a lot of unexpected adventures on the way to meet his friend.', '1997-09-12', 9, '/6rCjT2yKi0ITHel7qBuBQ3NRapQ.jpg', '2026-04-03T17:10:48Z', '2026-04-03T17:10:48Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('eb00ba81-abc5-48f6-b791-2e6f43230668', '4d2cac0f-38fd-438b-8afa-acf43952e535', 85, 'Episode 85', 'A magazine programme for younger viewers.  Introduced by Christopher Trace and Leila Williams.  Including Life in the Royal Navy: 1: The Captain and Flags - H.M.S. Keppel.  Members of the ship''s company explain their jobs.  Film specially shot by cameramen of the Royal Navy and National Anthems: 4: Eire.', '1960-06-03', NULL, NULL, '2026-04-03T17:21:47Z', '2026-04-03T17:21:47Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('eb02f728-872f-46be-9c63-b39c53674bb0', '3dc690a7-6dd8-4754-979a-02a9bf5d18db', 3, 'Paddington''s Birthday Bonanza', 'Paddington worries about not having enough money to buy a present for Mr Brown''s birthday, so he attempts to be a one-man band. As usual, things get out of hand.', '1987-12-26', 30, NULL, '2026-04-03T17:22:52Z', '2026-04-03T17:22:52Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('eb03363a-5575-4262-8558-7d62f5ed374f', 'c6d5cf79-f2b0-40af-ad12-91aa4f1b1d21', 5, 'Fender Vendor', 'Rick takes a swing at a Honus Wagner baseball card. Chum strums a custom Fender by popular guitar maker John Carruthers.', '2022-05-21', 42, '/oF9l59Gfc5q1FB1yGEZ4rZMHPJe.jpg', '2026-04-03T16:34:23Z', '2026-04-03T16:34:23Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('eb08a29a-cc90-4fde-a205-8ea3a631eaf9', '3b154d00-cb7b-49c4-a053-6ebbbe906eba', 18, 'Rosita Befriends a Frog Wearing a Crown (4048)', '', '2003-04-30', NULL, NULL, '2026-04-03T17:36:43Z', '2026-04-03T17:36:43Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('eb0a9d29-95b5-4f49-bfc1-a99076c5da3a', '4fe93658-c463-4329-8e64-9d523869c2cb', 27, 'Robosaurus', 'The Pawn Stars run for their lives when they come face-to-face with the fire-breathing, 31-ton mammoth Robosaurus. Will the guys stare down this car-crushing behemoth to make a deal or did they bite off more than they can chew? Then, Rick and Chumlee are presented with a cast iron Uncle Sam coin bank from 1886. Can they convince the seller to make fair withdrawal or will he cash out? And later, a computer meltdown threatens to bring the shop''s business to a standstill. Can the guys figure out how to operate without technology or will they close up shop for the first time in 22 years?', '2011-03-21', 21, '/gmp9jXE8BmHtcbOq7SOY0hSNAw2.jpg', '2026-04-03T16:34:16Z', '2026-04-03T16:34:16Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('eb0c5986-9049-40b1-bd3b-7a1f70148161', 'd1727ab0-c860-40ec-af59-b76f25c2e0ad', 8, 'A Tiny Urban Zoo', 'How to make your own tiny urban zoo.', '2009-05-18', 3, NULL, '2026-04-03T17:13:57Z', '2026-04-03T17:13:57Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('eb1180ee-d600-4d4d-860b-d744da878cca', 'e93f04c2-7344-4b93-abba-8ba1b2f8eb35', 6, 'Episode 541', '', '1973-11-26', NULL, NULL, '2026-04-03T17:36:30Z', '2026-04-03T17:36:30Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('eb130366-3182-40ed-b3c9-453ebbfc1c37', 'e1063f87-66c2-4e2d-a913-53362941aa19', 22, 'Episode 297', '', NULL, NULL, NULL, '2026-04-03T17:36:29Z', '2026-04-03T17:36:29Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('eb1cefa0-6cd6-44c1-8c5f-e2bf7bbd29d0', 'f812042d-eb85-432e-8047-3675886e0b1b', 27, 'The Count''s Account', 'Damont gets David into trouble after he uses one of David''s inventions. Meanwhile, Wishbone as Edmond Dantes seeks revenge against his enemies in Alexandre Dumas'' The Count of Monte Cristo.', '1996-03-05', 28, NULL, '2026-04-03T17:10:42Z', '2026-04-03T17:10:42Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('eb1d6ef5-1627-4499-8120-f6c183c39043', 'c0c0b0ba-e6e3-4a30-9567-1102881eddf3', 16, 'Fern and the Case of the Stolen Story', 'Suffering from a case of writers'' block, Fern begins to copy some of Ladonna''s stories.', '2013-05-09', 13, NULL, '2026-04-03T17:38:00Z', '2026-04-03T17:38:00Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('eb1dd2b6-18ad-4919-9e7f-94c15c7b48d7', 'b7538712-04ce-43a6-9163-62280bbb084b', 64, 'Goldilocks is on vacation, so the Big Bad Wolf takes her place (3914)', '', '2000-05-11', NULL, NULL, '2026-04-03T17:36:42Z', '2026-04-03T17:36:42Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('eb20bfae-cc09-4691-a3e8-2ab69b095133', 'ae8f64d9-4b83-4147-a44c-bfe720381f8e', 8, 'Stinky''s Annual Birthday Flower', 'Elmo and Zoe are coloring when they find out it''s Stinky the plant’s birthday. Zoe and Elmo decide to get him a present. Elmo surprises Stinky by giving him a drum, but plants can’t hold drumsticks. Zoe has an idea! What about a lovely tutu? Zoe surprises Stinky with a tutu to wear when he dances. Stinky tries to dance, but is unable to, as he is a plant in a pot!

Rosita and Cookie Monster come along with their own presents. Rosita brings Stinky a guitar but his leaves scratch the strings and make a horrible sound. Next, Cookie Monster rushes in with a plate of cookies but plants don’t eat cookies. Big Bird comes along and gives Stinky balloons. He ties the balloons to Stinky’s pot, but Stinky begins to fly away! Luckily, Chris rescues him and brings him back safely to the ground.

Elmo explains to Chris that they have been trying to get Stinky the perfect birthday gift. Chris reminds Elmo they should think about what Stinky would like for his birthday not what each of them would like. Elmo asks Stinky what plants need. That’s easy! He already has soil, so he needs water, sunlight and love! Big Bird carries Stinky’s pot over to a spot on the table in the sun, Cookie Monster carries over a pitcher of water and waters Stinky, and Zoe and Rosita give him a big hug! Then they throw him a big birthday party and sing about the importance of giving sun, water, and love to plants like Stinky!', '2009-11-19', NULL, '/mQ14JPCINrH1BlAvQ78CbB0Ubzb.jpg', '2026-04-03T17:36:46Z', '2026-04-03T17:36:46Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('eb21bfb8-e67e-4e3b-9bc7-87a0ce267a48', 'bbfee3b4-9c95-48a6-beaa-791fa08b1f43', 4, 'Episode 4', 'Expedition Sri Lanka: Shipwrecked Sailor!

More than 300 years before "Blue Peter"''s expedition Robert Knox, a young English sailor, was shipwrecked on the island and taken prisoner by King Raja Singha. Peter and Janet go back in time and discover more about this remarkable man held captive for 19 years before his skilfully plotted escape.', '1983-09-22', NULL, NULL, '2026-04-03T17:21:56Z', '2026-04-03T17:21:56Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('eb222238-bdc7-4ecd-83c4-b417348512be', 'e6254ae4-7d72-493b-8b37-b677d8b76c46', 127, 'Episode 792', '', '1975-04-29', NULL, NULL, '2026-04-03T17:36:31Z', '2026-04-03T17:36:31Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('eb225f68-b326-4ad4-9886-67a734af7a2d', '73ae1459-ba91-4185-a9da-bf6f2844af49', 5, 'Not So Model Behavior', 'It’s fashion week in NYC. Sonja is preparing for her "Sonja, by Sonja Morgan" fashion show and the ladies sit front row for Tinsley’s big return to the runway. Luann plans her new cabaret show, “Marry, F, Kill,” while Leah fears that Sonja resents her for comments she made.', '2020-04-30', 60, '/yaGGDwFPmnIKCjlPIxnEB1QVRKt.jpg', '2026-04-03T16:35:25Z', '2026-04-03T16:35:25Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('eb265c4a-0195-432e-9b88-3e7fe435e763', 'f4d370ca-3c39-40a8-911d-e2b5e7c6b0d7', 7, 'Duck Tries To Fly', 'Little Bear and Rabbit find Duck trying to improve his flying skills. They decide to try to help him but their various contraptions don’t seem to be too successful; even Little Bear ends up flying further than Duck. Duck is beginning to think that flying is not such a good idea when Sailor offers him two old sails from his boat. The triangles of cloth give Duck a good idea and when the toys all go out in the garden they do see a bit of flying after all.', '1996-10-16', 10, NULL, '2026-04-03T17:18:56Z', '2026-04-03T17:18:56Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('eb2df8e5-6004-4649-a563-3cba1a136e80', '80775c3d-fa41-46f6-96ec-efc2e14efdcf', 17, 'London Calling', 'Carole and Dorinda arrive in London to retrieve Anthony''s ashes and bond over the shared experience of losing their husbands; Sonja tries to teach the newly single Ramona about the dating world; everyone wears red to Bethenny''s fiery party.', '2015-07-28', 60, NULL, '2026-04-03T16:35:24Z', '2026-04-03T16:35:24Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('eb2e0198-9764-440b-b51c-806419e39c40', '6053b5c1-ce86-425c-8166-e0fcc3466061', 8, 'Episode 8', 'with Valerie Singleton, John Noakes, Peter Purves', '1969-10-09', NULL, NULL, '2026-04-03T17:21:50Z', '2026-04-03T17:21:50Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('eb309a72-b46d-4ffa-bc25-f906b0dba2ba', 'c01ddd2a-bdb1-4c97-8d04-58f791ef1c24', 19, 'Running', 'Martin and Chris run like other animals, beginning with the emu, extending to the crab, the fisher, the gecko, and the cheetah.', '1999-02-18', 27, NULL, '2026-04-03T17:10:55Z', '2026-04-03T17:10:55Z');
