INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('eb3305f6-e017-49c3-afba-70ce9f7537ed', 'efe209c2-704a-406f-824f-919caae6cd73', 3, 'Sing-along Time Together', '', '2022-04-01', 49, '/2Kn4SkHwn6iCWdfzh2su3siuCQ6.jpg', '2026-04-03T15:26:07Z', '2026-04-03T15:26:07Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('eb346fde-e907-40d4-a06f-62dc27b8c0e3', '70d9e397-6813-4785-887d-27d034928bae', 15, 'Pingu and the Mix Up', 'Pingu is looking after a neighbour’s egg, which is on a padded sledge outside the neighbour’s igloo, while she and Mother go out. It doesn’t take long before he starts to get restless. Then Pingo arrives, and Pingu abandons looking after the egg in favour of a game of ball with Pingo. A little while later, when Pingu goes past the sledge to recover an over-hit ball, he notices with dismay that the egg has gone. He and Pingo can’t find the egg nearby and go off in search of it, with Pingu pulling the sledge. They spot it going into another neighbour’s igloo while this neighbour, who has tufts on her head, is distracted hanging out the washing. The other neighbour also has an egg, which is on a cot in the igloo. The run-away egg jumps onto the cot, knocking the other neighbours egg off onto the floor. Pingu and Pingo sneak into the igloo and recover the egg that’s on the floor, thinking it’s the one they’ve been chasing, and Pingu returns with the egg to the original neighbours igloo. This neighbour has returned home by the time that Pingu gets back, and she rewards him for looking after her egg with a lollipop. The egg that Pingu has returned then cracks open, and a baby penguin is born. The original neighbour is initially happy, but then sees that it’s not her baby as it has a yellow beak and a tuft on its head. She''s angry with Pingu, and takes the lollipop away. Pingu then realises what has happened, explains, and he and the neighbour go to the other neighbours house, where the other egg has now hatched. The babies are united with their correct mothers, everyone is happy and Pingu gets the lollipop back.', '1996-06-20', 5, '/1x3YEGZESDidb1LESyopSvkEdzh.jpg', '2026-04-03T17:22:19Z', '2026-04-03T17:22:19Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('eb34d2ab-6718-4734-b3ac-d927eaef4ccc', '46d7a706-c7a8-4ebe-b96f-387c66e8bb8b', 22, 'Episode 1467', '', '1980-12-23', NULL, NULL, '2026-04-03T17:36:34Z', '2026-04-03T17:36:34Z');
