INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('eb3fd832-67e9-4571-bcb7-56ed5190aec5', '5a6d9a42-165b-4b56-9273-0a06874dfe10', 17, 'Madeline in Hollywood', 'Madeline is ''discovered'' by a Hollywood director and is transported to California for her motion picture debut with her idol, Sugar Dimples.', '1993-11-21', 30, NULL, '2026-04-03T16:34:01Z', '2026-04-03T16:34:01Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('eb414b0f-2a23-451a-882e-df825828d12e', '65d1cad8-0120-425e-ae9b-5020ce773b32', 14, 'Hoedown Throwdown', 'Tamra meets with Katie in hopes of uncovering the truth; Shannon and Jenn''s friendship continues to blossom when they engage their dogs with a pet psychic; Heather hosts an event for the Trevor Project.', '2025-10-09', NULL, NULL, '2026-04-03T16:35:36Z', '2026-04-03T16:35:36Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('eb470329-171c-4e80-a739-f2ee37b51d02', '3982796b-5451-4100-9042-46bedf6a20a5', 11, 'Pingu and the Camera', 'Pingu is out taking photographs of Robby. He then photographs an interestingly shaped block of ice from a variety of positions. Meanwhile Robby has found an ice-bridge, and shows it to Pingu. Robby climbs up to the top, and Pingu takes some photographs of him there, in various poses. They then spot a hot-air balloon drifting past, and Pingu snaps this as well. A photojournalist arrives, who also takes some pictures of the balloon, with Pingu standing in the foreground. Pingu goes home, and then goes with Father to the photo-shop to have the film developed. Unfortunately there’s nothing on the film, as Pingu has forgotten to take the lens cap off the camera. Pingu goes sadly home, and father consoles him. Mother and Pinga arrive home with the paper, and Mother shows Pingu the front page, which has a big picture of the balloon with Pingu standing in front. Pingu cheers up, and Mother frames and hangs the picture from the paper on the wall. Pinga wants to take a picture of Mother, Father and Pingu in front of the balloon picture. Pingu has to remind her to take the lens-cap off first!', '1993-03-09', 5, '/moKfXigWkVARcdTFCHj4iNTR7Bi.jpg', '2026-04-03T17:22:19Z', '2026-04-03T17:22:19Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('eb516cc7-bf77-4a5d-8423-c652c18a373a', 'b86d15ea-4253-41a5-9f14-4a254ec601e0', 8, 'Scum One, Scum All', 'Teresa''s husband and brother fight; Caroline tries to keep the family together.', '2013-07-21', 43, '/uO3GFTYlgHMOXKIQ0MUNIGT0ihV.jpg', '2026-04-03T16:35:16Z', '2026-04-03T16:35:16Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('eb5635a2-d3d4-4e23-ab2d-ad4d870f8e2d', '3af7ea64-fa13-4097-b8e4-40af07083054', 27, 'Water Flowing and Stopping Pt 2', 'Audrey Roth''s daughter Holly shows some of her crafts at Rogers'' television house. Later Rogers hears a Vietnamese musician at François Clemmons'' studio. The Neighborhood of Make-Believe also becomes the perfect place for a magic switch to turn the Castle fountain on or off.', '1974-03-26', 28, NULL, '2026-04-03T17:35:40Z', '2026-04-03T17:35:40Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('eb593009-fcfd-4682-94c9-29ab8f10bac7', 'bbfee3b4-9c95-48a6-beaa-791fa08b1f43', 17, 'Episode 17', 'See How They Run!

Six of the fastest feet in Britain flash past today when Himalayan runners Richard and Adrian Crane join Steve Cram in the studio.', '1983-11-07', NULL, NULL, '2026-04-03T17:21:56Z', '2026-04-03T17:21:56Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('eb5a288c-6ac9-46a1-acd4-9e7e34c78006', '7c542833-ed0a-4272-9c53-e822408ab434', 17, 'Grandpa Day', 'When James and Sarah compete for the title of ''best steam driver,'' James accidentally spills a burning coal into a pile of wood, sparking a fire.', '2024-11-04', 10, '/9qFjFlbo6d6c6DprL82Ddf3OwZo.jpg', '2026-04-03T17:14:42Z', '2026-04-03T17:14:42Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('eb5fb7f0-1f9a-4df3-a074-bb78eca73cbf', '5c1b881f-ac58-4d72-b63f-209952d4f902', 9, 'Episode 9', 'It''s smelly work down on the farm as Simon and Goldie get to grips with silage-making to feed the cows this winter.', '1979-10-08', NULL, NULL, '2026-04-03T17:21:54Z', '2026-04-03T17:21:54Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('eb60ba8d-0b57-4c8f-a051-b596e94b43a2', 'efd2082e-32f5-4edd-9a7b-a4326d6992c9', 20, 'Elmo the Engineer', 'Elmo and his dad become engineers as they design a device to help Elmo put away his toys.', '2019-03-30', NULL, '/k5XQdQLCJHdgzdMAKE1lIXjEzWu.jpg', '2026-04-03T17:36:49Z', '2026-04-03T17:36:49Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('eb61124b-1c72-4635-9df2-c7c40112cce4', '68138de2-0900-460a-b58e-480688f1e081', 29, 'The Way I Feel Today', 'One morning, Bear is trying to decide on what type of tea to have --- cold iced tea or hot tea. With the viewers'' help, he decides on the iced tea. He also finds Tutter trying to get some tea as well, but needing his help to get a glass and the sugar. At first, Tutter is bothered by how his small size keeps him from doing anything. Then, he helps Bear and he finds that being the opposite of big isn''t so bad after all. More opposites are explored when Bear keeps filling his lemonade glass and Pip and Pop keep emptying it. He also shows Ojo and Treelo how they can dance together, alternating their opposite favorite styles of music. In the Shadow segment, Shadow presents a feature called "Tales of Incredible Opposites," featuring a story about Jack Sprat and his wife. 

Songs 

EditGood Morning (Shortened Version) 

Opposites

Notes 

The dog in the Shadow Projects logo in the closing credits shouts "Go, Daddy!"', NULL, 25, NULL, '2026-04-03T17:35:31Z', '2026-04-03T17:35:31Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('eb64e564-9e11-4f87-9f06-485ff65aa04f', '22beba7f-9b8e-4563-93da-46e76ecba427', 16, 'Slimey The Hero!', 'When Slimey says that he wants to be a hero just like Trash Gordon, Rosita and Elmo are doubtful because they think heroes are supposed to be big and strong. But Oscar reassures him that he can do it, and Slimey takes on the mission of saving the letter of the day.', '2006-09-14', NULL, '/nlXmkLkDw3zVDXveiW1Xfm4Vwox.jpg', '2026-04-03T17:36:44Z', '2026-04-03T17:36:44Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('eb69c2f1-6609-4857-b4a8-cb4199680579', 'bb919aec-0d5c-4c58-9a5a-fa2a0a5de2b6', 107, 'Episode 512', '', '1973-04-24', NULL, NULL, '2026-04-03T17:36:30Z', '2026-04-03T17:36:30Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('eb6b1978-5111-48eb-ba52-6d2152b2e800', '1d713ca6-4e17-4f84-949c-8cfd98514127', 34, 'Off to the Races', 'Strike silver with the Pawn Stars when the book "The Big Bonanza" hits the shop. Can Rick find a gold mine or will he only dig up dirt? Then, Rick moves mountains when an ancient Tibetan door comes in. Will the sky be the limit on this deal or will the door be slammed in his face? And later, after Corey gets a ticket, the guys decide to find out who''s the better driver down at the racetrack. Who will get the checkered flag and who will spin out?', '2014-11-20', 21, '/1jCLCOPhTlIjjVOwYky8BAc6aPA.jpg', '2026-04-03T16:34:19Z', '2026-04-03T16:34:19Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('eb6c39b5-6c0f-4354-8aa1-cbeaa70cd2f0', '225b0f03-984b-47f3-a1a3-d3e92175e39d', 29, 'Episode 29', 'with Christopher Trace, Valerie Singleton and John Noakes.', '1967-01-05', NULL, NULL, '2026-04-03T17:21:48Z', '2026-04-03T17:21:48Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('eb7345e5-6450-4b11-a5e3-11600117b19e', 'd84bd187-f033-42dd-8873-e1099c61de07', 2, 'Episode 661', '', NULL, NULL, NULL, '2026-04-03T17:36:39Z', '2026-04-03T17:36:39Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('eb7869b6-6793-43d3-87fb-6b694f603cf0', '97616d6e-5c17-449f-a376-55f1da83d6c3', 18, 'Mister Rogers Talks About MAKE-BELIEVE', 'Mister Rogers arrives and quickly moves into the opera which has been planned throughout the week. The opera is to include various components from the previous four episodes and will focus around "Spoon Mountain."

The opera opens with Joe Negri playing the part of the Storyteller as he sings an introductory tune. The royal family of King Kittypuss, Queen Mumsiebelle, and the Prince Extraordinary (played by Chef Brockett, Miss Paulificate, and Chuck Aber) are deciding who will celebrate a birthday today. After it is determined that it will be Queen Mumsiebelle''s birthday, Kittypuss'' surprise gift to her is a mountain -- Spoon Mountain.', '1982-07-02', NULL, NULL, '2026-04-03T17:35:42Z', '2026-04-03T17:35:42Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('eb78799a-08b4-4d24-88c8-01f79c5f4a94', '97a3d1f5-a8f1-47cd-8122-2e74a092836d', 1, 'Am I Blue? (1)', 'Gaby is excited when she learns that her heroine, Galaxy Girl, is making a special show at Hurston. She wants to buy a Galaxy Girl costume to wear at the assembly but she doesn''t have enough money, so she borrows some money from her parents cashier planing to return the costume and get a refund. At the show something goes wrong and the model spaceship is stolen. She can''t return the costume because it was on sale. Gaby is heart broken when she doesn''t get to meet Galaxy Girl. She becomes more worried when the team leaves to confront Calvin but is even more scared when she finds the space ship model in her toy chest.', '1993-09-12', NULL, NULL, '2026-04-03T17:40:28Z', '2026-04-03T17:40:28Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('eb7ead6e-8682-452a-bc5d-4f0aacab2151', '04e133fd-c4a3-4dfa-8369-c6dcfd1e3a5a', 121, 'Episode 2086', 'A short episode with minimal scenes and interactions among the regular cast. Basic educational content is included. The focus is on simple, everyday moments.

Sponsors: J, S, 8', '1985-05-06', NULL, NULL, '2026-04-03T17:36:36Z', '2026-04-03T17:36:36Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('eb7fe54e-ed03-4f95-b036-92dd3aa04bf2', '63850e1d-d8ed-4fe4-a068-83cb879c170a', 6, 'The Lip Reader', 'A tennis lineswoman is game to help George learn why he''s been dumped.', '1993-10-28', 22, '/pCVBjLJ02RyBvWFB0PFxYan0reg.jpg', '2026-04-03T16:34:10Z', '2026-04-03T16:34:10Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('eb8aa64e-3be7-4b4a-8a02-66dedc7f6156', 'e9352408-a84b-4c1a-905c-7aa862062f7f', 24, 'Roller Skating', 'Pat comes along with friends to Coventry Sports Centre to watch their daughter, Jade, roller skating.', '1995-07-30', 10, NULL, '2026-04-03T17:19:37Z', '2026-04-03T17:19:37Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('eb8f33fb-da3a-40ad-a668-c52af6100fae', '852a07b0-f228-4197-9147-7aeed79390bf', 6, 'Stop and Throw the Roses', 'The gravity of Luann and Eboni’s paint party confrontation begins to set in, and beachside fishing turns cold when politics are brought up in conversation. Meanwhile, Heather’s faux pas comes back to haunt her as the ladies glam for Luann’s 70’s style Halloween pageant.', '2021-06-08', 60, '/jcwVOjvr0Yg5v9K8puh8AsZM4jx.jpg', '2026-04-03T16:35:26Z', '2026-04-03T16:35:26Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('eb8fa343-bf65-445a-b3ad-2861c9cddf40', 'dbde6570-a68d-4fd7-a1b0-a6037a266a18', 14, 'Happily Never After', 'Slade''s engagement ring shopping plans; Alexis throws a birthday party for her twins; Tamra gets a tattoo removed; Vicki and Briana fight.', '2012-05-15', 44, NULL, '2026-04-03T16:35:31Z', '2026-04-03T16:35:31Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('eb91cbf0-ab02-4983-a174-1d1bdaaab73b', '0b9d7ae7-218e-45a0-8c3a-e69912f5a6ed', 23, 'Franklin and the Thunderstorm', 'Franklin doesn''t want his friends to know that he is afraid of thunderstorms.', '2000-02-14', 12, NULL, '2026-04-03T17:40:15Z', '2026-04-03T17:40:15Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('eb94e96e-b525-47a5-aa05-e64287c2ee0c', '7bc54df3-f32a-454e-aef6-a9436c35d53b', 5, 'The NOM Models Pt 5 - Making mud pies', 'Title number 1070. Opens with Mister Rogers arriving with a small cup and spoon from the ice cream shop. Rogers receives the Factory model from Robert Trow. Beforehand, Rogers makes simple puppets from wooden spoons. In the Neighborhood of Make-Believe, Lady Elaine orders chairs from Cornflake in preparation for her new pie restaurant.', '1970-02-06', 29, NULL, '2026-04-03T17:35:39Z', '2026-04-03T17:35:39Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('eb98c4c7-bb9b-4a4d-ae13-6b219636364f', '573fa62f-55a9-4f17-97cc-d1a005a83cc8', 26, 'Counting Bats', 'Elmo, Abby, and The Count play a game of hide-and-seek in The Count''s Castle to round up all ten Batty Bats before nap time.', '2025-07-10', 26, '/e6Iyy5fQnYgsCdil4PvXfhGpQ7j.jpg', '2026-04-03T17:36:52Z', '2026-04-03T17:36:52Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('eb9c0c37-dfda-478d-980f-eb400afeed3f', '87989283-6fea-40d7-8d91-22c4947db105', 8, 'Doubting Polygamy', 'Kody tells his friend Kyle, a polygamist whose first wife left him, that he is feeling jaded about polygamy. Kody''s wives are refusing to all live under one roof and the roller-coaster of houses sold, lost and stalled has everyone at a boiling point.', '2020-02-23', NULL, NULL, '2026-04-03T16:34:31Z', '2026-04-03T16:34:31Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('eb9c9c97-e17d-43ea-bb79-89617d6daa31', '7bc54df3-f32a-454e-aef6-a9436c35d53b', 43, 'Episode 43', 'Rogers goes to Negri''s Music Shop to see Betty Aberlin perform a few simple magic tricks. Lady Elaine has her reservations about the upcoming play the Neighborhood of Make-Believe will stage. Mr. Anybody tells her she can be in the play if she asks to.', '1970-04-01', NULL, NULL, '2026-04-03T17:35:39Z', '2026-04-03T17:35:39Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('eb9ce02f-cdd2-40b7-afdc-8e3855d049af', '27a5a980-ec0d-4637-b5ba-df8324a6405a', 9, 'The Play', 'Frankie is thrilled when she learns that the Orson Community Theater is putting on a production of "The Wizard of Oz," and that kids don''t need to audition to be munchkins, as they will be automatically cast - which is a perfect scenario for a hapless Sue. But things quickly go awry when Frankie is cast in a singing role and learns the director is not happy with Sue''s performance and may cut her from the play. Meanwhile, Brick asks his unreliably quirky Uncle Rusty to attend his school''s Special Friends Day - with disastrous results.', '2011-11-16', 22, '/gOl6sYbz8eOyjldCSYQYQG2Hdjw.jpg', '2026-04-03T15:40:29Z', '2026-04-03T15:40:29Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('eba2b5d6-f0a2-4844-8a3a-6dbedc75c944', '6f81c872-cdb9-42dd-8377-2c17cb6ed4d7', 5, 'Having a Ball', 'When Saul the Ball is disappointed that he can’t play ball with Elmo and Rosita inside the house, Elmo and Rosita help him use his imagination to play other games.', '2017-02-04', NULL, '/dtuqYoSjKJCmXBsy8FUrYFpJebd.jpg', '2026-04-03T17:36:48Z', '2026-04-03T17:36:48Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('ebaaaea0-a390-41ca-ab4a-ce673c76d2a2', '05c0e384-194c-4417-9f62-803eb615e409', 49, 'Bubbles', 'Title number 0049. Opens with Mister Rogers arriving with a straw in his front pocket. Mr. Rogers uses drinking straws to demonstrate the use of blowing soap bubbles. Mrs. Rubin also shows paintings that were all done with straws. King Friday is missing Sara Saturday. Lady Aberlin invites everyone to the castle to see a dancer named Paul Draper.', '1968-04-25', 29, NULL, '2026-04-03T17:35:38Z', '2026-04-03T17:35:38Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('ebaec756-dda8-4158-8998-0885c977c408', '33440d76-e69f-47ad-ac25-862ccbc9dfa1', 17, 'Fashion Show-Down', 'The ladies of Potomac are handling their business. Ashley and Gizelle work on their fashion line, GnA. Robyn and Juan tour potential franchise locations. Wendy organizes her pilot episode. Mia brings everyone together for an iconic photoshoot, but drama is just on the horizon at a GnA showcase.', '2024-03-17', 43, '/9IpnPSYTZNXn71rU9HbIcO9rALf.jpg', '2026-04-03T16:35:41Z', '2026-04-03T16:35:41Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('ebb79d51-6fa9-4187-89a8-0e66ea41a661', '54facb0b-db59-41fe-9d64-c7c7221a3c81', 20, 'Reunion (3)', 'The women finish raking Luann over the coals about her sobriety; Barbara joins the ladies to discuss her scandalous comment about Luann''s singing; the ladies relive some of their most outrageous moments; Sonja is in the spotlight for her drinking.', '2019-07-25', 60, '/5cC4mDbqXuOkbtYPQWXT67Up4Bo.jpg', '2026-04-03T16:35:25Z', '2026-04-03T16:35:25Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('ebbeec81-a694-44cd-8140-1b9de977f5a9', '2389d176-a1a8-4624-9b1c-9c0c12a3be4e', 1, 'Dilys'' Forgetful Day', 'When Dilys falls off the ladder, Norman''s got a lot of explaining to do!', '1990-10-15', 10, '/zBOWiAWEQSgfH5y9UTdV6mIOXH.jpg', '2026-04-03T17:14:37Z', '2026-04-03T17:14:37Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('ebc1bba9-b790-4bf2-92ce-4b52c2a7d16f', 'ecb64ef3-4f80-45a7-b4a9-c04434b02e35', 31, 'Sleeping Giant', 'Jam along with the Pawn Stars when a 1969 Les Paul Professional guitar rocks its way into the shop. Will this classic strike a chord with Rick or will he be left singing a different tune? Then, Corey and Chumlee hit the brakes when they spot a 1930s Rolls-Royce hood ornament. Will they get on the fast track to a good deal or be left in the dust? And later, when the guys notice the Old Man snoozing more than usual they try to take matters into their own hands. Can they wake the sleeping giant or will he become their worst nightmare?', '2014-04-17', 21, '/obhVMU8M33IjKGEpj3dyJowiGcm.jpg', '2026-04-03T16:34:19Z', '2026-04-03T16:34:19Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('ebc4f178-22a6-4dbf-a2f9-70f94e665865', 'ad4e4348-3334-4a08-8928-455d9ba524c1', 21, 'Paul Simon', 'Paul inspires Gonzo to be a songwriter. Unfortunately, Gonzo writes songs like "For You": "For youuu... I''d wash my hair with stinky glue, I''d fry my legs and eat them too, I''d put a spider in my shoe -- for yoouuuu!" Paul is stunned. Later, Gonzo''s chickens run off with Paul, so Gonzo develops a new obsession -- asparagus. But at the end of the episode both the chickens and the asparagus run away when Paul asks for chicken with a side of asparagus.', '1981-02-22', 26, '/3ifthNvZrPAxxRnQXk7waK0Dkkd.jpg', '2026-04-03T17:35:25Z', '2026-04-03T17:35:25Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('ebc4f9fc-2ffe-43a1-9ab5-20020b9e1f3e', '319bd5d6-ff58-426f-b9da-a0bb2cb87b02', 19, 'Science of Music', 'Music is the art and science of expressing ideas and feelings through sound. A sad song can say more about how someone feels than most words, and a familiar song can make crowds clap together and feel like one happy family. Whatever the emotion, music seems to have a way to communicate it. The music we listen to today is the result of years of experimentation with sounds. As people figured out what they liked best, they invented instruments that could play their favorite tones and developed popular rhythms, or patterns of beats. Each note of music, and every tone of each instrument is a sound wave. Some sound waves sound great together. Some not so good. Getting the exact soundwaves in the pattern you want – now that’s science.', '1998-06-13', 26, '/pMXCd8Voj0hm29Rw1ALbb9BRXQY.jpg', '2026-04-03T17:37:22Z', '2026-04-03T17:37:22Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('ebc9e214-58ae-4d98-b80d-44cf568ad69c', '1d556682-d9bb-47e1-993f-0b648a8daacd', 102, 'Episode 1287', '', '1979-04-17', NULL, NULL, '2026-04-03T17:36:33Z', '2026-04-03T17:36:33Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('ebcf2f49-f000-435a-b788-2514d5cac8b7', 'df895a8e-db4c-48d1-bf84-9a6a650583dc', 5, 'Nicked by a Name', '', '2010-10-13', 13, NULL, '2026-04-03T17:38:00Z', '2026-04-03T17:38:00Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('ebd4d82c-5c9c-45ce-bbcc-803eaedde572', 'f07b8794-5625-4682-aae1-e56966b4c7a8', 10, 'We Three Kings', 'When Leon’s uncle tells him he’s the “king of kids,” Leon suddenly gets an ego boost and acts royally around The Puzzle Place, making Skye and Ben his subjects. Eventually, pro-basketball player Cedric Ceballos tells them that there is a difference between being bossy and being a leader. Sizzle suddenly decides to be “queen of cats” and makes Nuzzle do everything for her.', '1996-01-26', 29, NULL, '2026-04-03T17:12:21Z', '2026-04-03T17:12:21Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('ebdfaf90-ec24-4249-b1da-5cf1dee6770c', '1d713ca6-4e17-4f84-949c-8cfd98514127', 32, 'McQueen Dreams', 'Take flight with the Pawn Stars when a letter from WWI fighter pilot Eddie Rickenbacker soars into the shop. Will Rick land this piece of history, or will the deal take a nosedive? Then, Corey takes a look at a military swagger stick from 1865. Will Corey bring out the big guns to make the deal, or will a tough battle push him into retreat? And later, after Rick gets excited for some "The Great Escape" movie posters, the guys make fun of his mancrush on Steve McQueen. Will their teasing be a "Bullitt" to Rick''s heart, or will Rick make "The Getaway" from their taunts?', '2014-11-13', 21, '/5fj5binCaHIjjHBJD3RZrb0ABTj.jpg', '2026-04-03T16:34:19Z', '2026-04-03T16:34:19Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('ebe8547b-aff0-4e01-b1f2-a6f1d16966b1', 'a3a2c2fb-8276-412c-9d86-5175167be1d7', 8, 'Episode 8', 'with Valerie Singleton, John Noakes, Peter Purves', '1971-10-07', NULL, NULL, '2026-04-03T17:21:51Z', '2026-04-03T17:21:51Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('ebe869bd-e0a6-42e0-a30d-d8f15adbe3e1', '1d556682-d9bb-47e1-993f-0b648a8daacd', 110, 'Episode 1295', '', '1979-04-27', NULL, NULL, '2026-04-03T17:36:33Z', '2026-04-03T17:36:33Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('ebe9335a-f443-42ac-8615-1f3cff87d59a', '5a771f52-fe96-4ea2-b567-a8dde899059e', 4, 'Chum''s Risky Business', 'Chumlee is holding out for a superhero when a seller brings in boxes upon boxes of inherited comic books. Rick learns you have to buy money to make money when some rare turn of the century currency hits his counter. Chumlee flips out when an antique pinball machine launches into the store.', '2017-10-23', 21, '/qLq8ty5rCa6nAEhpBujfoz0wtkU.jpg', '2026-04-03T16:34:21Z', '2026-04-03T16:34:21Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('ebeedf39-d5ca-4bcd-bf40-5f53306623c7', '1be79a20-de33-41d1-af17-079035b18d5c', 17, 'Oscar''s Hiccups', 'Sponsors: D, E, M, 8, 9', '1969-12-02', NULL, NULL, '2026-04-03T17:36:28Z', '2026-04-03T17:36:28Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('ebf0263c-7f93-4ac0-9ace-7f131c002384', '1f34e241-4c1d-4586-921a-1c5aeb1fbbaa', 71, 'Gladys presents herself', 'Big Bird has asked Gladys the Cow to help say hello to the viewer, but she balks at a cow of her talent being wasted on such a menial task. Maria questions why Oscar has left an old, junky car seat out on the street. Oscar tells her it''s for an important lesson about safety, and the Grouchketeers show how to use a seatbelt.

Sponsors: A, D, 9', '1986-02-24', NULL, NULL, '2026-04-03T17:36:36Z', '2026-04-03T17:36:36Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('ebf0951b-5476-43cc-bf14-52cb7c2cb280', '3982796b-5451-4100-9042-46bedf6a20a5', 21, 'Pingu''s Hospital Visit', 'Pingu and Mother visit the injured Pinga in hospital. When they enter the hospital, a doctor is pulling a badly injured penguin who got hurt in a bad post truck accident. When they find Pinga, Pinga is pleased to see them, and Pingu shows her a picture he’s drawn of her accident. The nurse comes in to treat Pingi, who is in the bed next to Pinga, and puts a screen between the beds. Mother gives Pinga some flowers, and both Pinga and Pingu have an apple. Pingu’s getting a bit bored, so he rides around on a stool with wheels. He then sees the shadows that are being made on the screen by the nurse and Pingi by a light the nurse turned on. The nurse turns off the light and goes out. Pingu pulls the screen round in front of Pinga and Pingi, puts a mobile table behind the screen, a pillow into the table, and the light behind. He turns on the light and gives a shadow performance to Pinga, Mother and Pingi, pretending to be a surgeon operating. Mother, Pinga and Pingi find Pingu’s performance very amusing and laugh out loud. The noise attracts the attention of the nurse and a surgeon, who come in to find out what’s causing all the laughter. They see the end of Pingu’s performance, and applaud with the others when Pingu finishes. Pingu is given his own surgeons outfit as a prize for his performance.', '1994-08-24', 5, '/ypGGBR8k7e4FPyIJAoD7KbAgO9W.jpg', '2026-04-03T17:22:19Z', '2026-04-03T17:22:19Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('ebf41b7b-4054-4713-81f5-426cbc856384', '9c9d89df-5f6b-41d0-84c6-b8ca7bd2a2e6', 33, 'Goldilocks and the Three Homes', '', '2022-06-23', NULL, '/cR4qyYVUbiRYcSOUkf5P4czde2t.jpg', '2026-04-03T17:36:50Z', '2026-04-03T17:36:50Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('ebf4dc28-9299-4c7f-8c77-eae008712dd0', '0fb5ce65-0258-4423-be8a-f7ba9c37bb6b', 5, 'Mystery at Pumpkin Hollow (Part 1)', 'The Why Files and the Detectives are both on the case within Pumpkin Hollow, with strange sounds and disappearing pumpkins to boot.', '2023-10-25', 9, '/2mHdKiQofNNuRHxbtfzf4Z0sFXW.jpg', '2026-04-03T17:14:42Z', '2026-04-03T17:14:42Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('ec01a885-2df1-4f60-a429-90a0b1f79579', 'ffc2a75e-0ffa-4b26-b121-9b91b277594a', 7, 'Nice to Metria', 'Cynthia returns to work and joins forces with singer-actress Demetria McKinney. Meanwhile, NeNe goes live on the air in Tampa to debut her clothing collection; Kenya meets a prominent producer; and Kandi receives cold treatment from Mama Joyce at a family barbecue.', '2014-12-21', 43, NULL, '2026-04-03T16:34:47Z', '2026-04-03T16:34:47Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('ec04b86b-282f-4930-9081-3a0724be58c0', 'f63c3f61-0970-4e37-81cc-2b9045a9952c', 42, 'Zoe''s Zoemobile Delivery Service (Repeat) (3957)', '', '2001-02-27', NULL, NULL, '2026-04-03T17:36:42Z', '2026-04-03T17:36:42Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('ec09fcbf-4f14-480c-a1c2-ef8937e759af', '70d9e397-6813-4785-887d-27d034928bae', 14, 'Pingu Seeks Revenge', 'Pingu has been out with Pingi, and kisses her goodbye. Pingg spots them and, while Pingu is waving to Pingi as she walks away, throws a snowball at Pingu which hits him on the back of the head. Pingg is amused; Pingu is annoyed. Pingu throws a snowball back that Pingg avoids. After again being hit on the head by a snowball thrown by Pingg, Pingu chases him home, throwing several snowballs at him on the way, but none of the snowballs hit their target. Pingu and Pingg end up with Pingu on the wooden bridge over the water in front of Pingg’s igloo, exchanging words with Pingg who is by the front door. Pingu is still annoyed, but then has an idea. He goes home, gets a saw, returns and cuts partway through the bridge. He then stands at the edge of the bridge and taunts Pingg, who comes out of the igloo and shouts back. Just then Grandfather comes to use the bridge, and starts across. Pingu tries to stop him crossing by going onto the bridge and shouting, and jumping up and down. The bridge breaks as Pingu had planned but he, rather than Pingg, ends up in the water! Pingu is rescued, but is completely frozen in a block of ice. Once home Mother, aided by Pinga, and a lot of hot-water bottles, thaws him out. Pinga then laughs at him.', '1996-06-13', 5, '/9cHygYtWxRJdn35FzysalSOMTjF.jpg', '2026-04-03T17:22:19Z', '2026-04-03T17:22:19Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('ec0dd10d-2bb3-4126-8bc5-b8e864e35fee', 'f812042d-eb85-432e-8047-3675886e0b1b', 22, 'The Pawloined Paper', 'Joe has a substitute teacher for his class, who he likes a lot.  After a word puzzle he makes up about her gets snatched, courtesy of Curtis, Joe must get it back before anyone sees it.  Meanwhile, Wishbone tears the living room upside down looking for his toy newspaper, which is right under his nose the whole time, just like where the stolen letter is hidden in today''s story ""The Purloined Letter"" by Edgar Allen Poe', '1995-11-05', 28, NULL, '2026-04-03T17:10:42Z', '2026-04-03T17:10:42Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('ec1b058b-cc4d-47e3-9fe0-7add1616973e', '301fb913-4e76-408f-b84b-05bf979766fe', 2, 'The Postponement', 'Elaine shares her feelings about George with the wrong person. Meanwhile, George discovers the power of tears.', '1995-09-28', 22, '/25VI2m8Pe5gGQfnZUO2uVkYa0tX.jpg', '2026-04-03T16:34:11Z', '2026-04-03T16:34:11Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('ec1dc5a9-afd3-4913-89e8-5dbd01c50170', '4d2cac0f-38fd-438b-8afa-acf43952e535', 259, 'Episode 259', 'Christopher Trace and Valerie Singleton introduce a magazine programme for younger viewers.', '1963-12-09', NULL, NULL, '2026-04-03T17:21:47Z', '2026-04-03T17:21:47Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('ec1f1a6b-5667-4191-b3ff-5f4a00b4fba3', '2afe02c5-499e-4d46-ad93-0504a321941f', 11, 'Felldoh''s Revenge', 'Rose leads Martin and his friends to Noonvale and find out that Brome has not made it back.', '2002-02-11', NULL, '/rDm7fbeF98uJNmwdrRfiuVPHzmI.jpg', '2026-04-03T17:12:08Z', '2026-04-03T17:12:08Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('ec23b9f7-ce6a-40af-b1dc-3cd124a55b51', '8c3cfac1-d882-4904-b38c-d1981628d00e', 11, 'Episode 11', 'The 20th Birthday Celebrations: Join in with guests Leila Williams, Christopher Trace, Valerie Singleton, John Noakes and Peter Purves.

Watch out for the nationwide Birthday Balloon Launch from Aberdeen, Cardiff, Belfast, Manchester and the roof of Television Centre in London. If a balloon lands near you, put the label in the post and win a special Birthday Badge.', '1978-10-16', NULL, NULL, '2026-04-03T17:21:54Z', '2026-04-03T17:21:54Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('ec24351f-8b7d-4eb6-81e5-860f179189f4', '9193e795-da7c-40ec-b68f-f63aa7d5174f', 273, 'Jon''s Tragic Flaw', 'The show creators discuss Jon''s inability to kill an innocent man.', '2014-02-18', 1, NULL, '2026-04-03T15:40:35Z', '2026-04-03T15:40:35Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('ec25d31d-156b-4e8e-87e0-88a65aa2cb4c', '27947392-39ba-45a6-b67b-fc609eb26e51', 12, 'Swift Drift', 'Norman and Krystyna''s younger brother Peter get lost at sea when their ship starts to sink, but Krystyna is here to save the day.', '2023-02-14', 10, '/wgKbi5BkC006ynMtZdGev1u8LjN.jpg', '2026-04-03T17:14:41Z', '2026-04-03T17:14:41Z');
