INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('ec2ffc7f-0ee6-4c85-95da-4f2961dee6e9', '943b0c94-0cc5-40e8-a0e1-bd5660772cc3', 15, 'Vacation, All I Never Wanted', 'The ladies'' vacation continues, yet Ramona frets that it''s turning into a couple''s retreat. On the final night, Sonja and Ramona spark tension when they duck out on the wives'' original plans to see a concert.', '2012-09-10', 60, NULL, '2026-04-03T16:35:23Z', '2026-04-03T16:35:23Z');
