INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('eca02bac-4af5-4abb-885f-27526943b587', '42e591e2-2a88-4434-ae9f-3d4b1d685613', 10, 'The Pawntridge Family', 'Prepare to dive with the Pawn Stars as the guys check out a first edition copy of 20,000 Leagues Under The Sea. One of the rarest first editions, can they navigate this monster deal? Then, a collection of signed Metallica memorabilia rocks into the shop. Will the negotiation have Corey and Chumlee banging their heads? And later, when Rick starts taking guitar lessons, the guys try to talk him into a pawn shop jam session.', '2013-06-27', 21, NULL, '2026-04-03T16:34:18Z', '2026-04-03T16:34:18Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('eca281a5-e9b8-4222-8ac8-50e07ec0962c', 'e38e9d87-1432-4a1a-a7d0-64a559bf7570', 5, 'Snare For The Unwary', 'When the normally cowardly Mr Pheasant offers to go back and look for Adder on the farm he is shocked to find that his wife has been made into the farmer''s dinner. It is then that he too gets shot. The other animals hear the gun shot and realise what has happened so Owl volunteers and flies over to the farm in search of Adder. Owl finds Adder and they catch up with the rest of the animals and continue on the journey. While crossing a river, the rabbits panic in the water so Fox jumps in to save them. However in their panic they try to climb onto him and put him in danger as well. Badger swims in to help the exhausted Fox and keep him afloat. While the rabbits are taken to safety a large log, floating down stream strikes Fox and Badger.', '1993-01-31', 24, '/tMwN4lV85PXGFZgzjWdfmbM3XiH.jpg', '2026-04-03T17:18:49Z', '2026-04-03T17:18:49Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('eca31530-bcdb-40b4-8c79-72d2424e72e8', '06030129-ff2d-4490-b66c-9f41bbe7aabd', 22, 'Pottery', 'John travels to visit a pottery at Elmley Castle near Pershore in Worcestershire.', '1991-02-11', 15, NULL, '2026-04-03T17:19:36Z', '2026-04-03T17:19:36Z');
