INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('ecb865f3-6027-4e69-a86d-aa24c83c7406', '5b2c9365-7bd9-4ca1-a3fb-15f1a024a56e', 4, 'Social Wife', 'Four of the housewives gather for dinner at a ritzy restaurant, but not all goes down easy when Alex annoys Bethenny. Other wives'' tales: Ramona hits the town with her gal pals; LuAnn socializes with her twentysomething niece; Bethenny tries to take her romance to the next level; and Ramona escorts her daughter to a film audition.', '2008-03-25', 60, '/mGYS1YwwqNmbWJ788efeL2cOyRI.jpg', '2026-04-03T16:35:21Z', '2026-04-03T16:35:21Z');
