INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('ecf9cad0-6836-45c1-a153-13ee2d54b17d', '97616d6e-5c17-449f-a376-55f1da83d6c3', 10, 'Mister Rogers Talks About PETS', 'Mister Rogers arrives empty-handed and has some quiet time on the porch while he waits for Bob Trow to arrive with his dog. As he waits, he sings It''s a Perfectly Beautiful Day and is surprised when Mrs. McFeely stops by with a parrot in a cage. Just as she leaves, Bob Trow arrives with his dog, Barney, and leaves him in Mister Rogers'' care for the night.

In the Neighborhood of Make-Believe, Bob Dog is preparing to have his picture taken as a birthday surprise for Ana Platypus. Meanwhile, Daniel is disappointed in his efforts to make his own gift -- a Magic Electronic Supersonic Firemobile -- and decides to seek help from Corney and Handyman Negri. At the castle, Mr. McFeely delivers a parrott which King Friday plans to give to Ana. When King Friday realizes that the parrot will not properly address him as King, he asks Mr. McFeely to take it away. To comfort himself, he brings out his own trusty pet, Troglodytes Aedon.', '1982-06-02', NULL, NULL, '2026-04-03T17:35:42Z', '2026-04-03T17:35:42Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('ecf9cf10-4418-48f8-b9f0-74e9e961e0f1', 'bcab920a-51a5-4cbb-aa59-41578a0eb005', 3, 'Going Commando', 'Kyle and Lisa Rinna cross paths in New York City while traveling with their daughters. Back in Beverly Hills, Lisa Vanderpump surprises Ken with a $25,000 watch on his birthday, and Eileen continues to struggle with the loss of her mother. Later, over drinks with the group, Erika''s short dress leads to quick peeks and judgments passed.', '2016-12-20', 43, '/1myrgy0vOB5dM9na8gnKnk0FloH.jpg', '2026-04-03T16:34:56Z', '2026-04-03T16:34:56Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('ecfb3a0d-d216-4df1-bbc4-fe4173672098', 'efdf1e4f-8476-4382-a9d7-2b9da4188be0', 13, 'Helping', 'Rogers visits B. Smith''s restaurant and reunites with B. Smith herself. Smith returns to the Neighborhood of Make-Believe and leaves a napkin for Queen Sara. But the napkin is swept away, because of Lady Elaine''s army of "vacuum sweepers".', '1996-08-16', NULL, NULL, '2026-04-03T17:35:47Z', '2026-04-03T17:35:47Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('ed025365-71b2-4f18-9a76-e38fd5ce1117', 'dbde6570-a68d-4fd7-a1b0-a6037a266a18', 8, 'Dirty Housewives', 'Tamra, Gretchen and Heather compete in a charity Mud Run, Alexis has her nose cast removed, and Vicki gets answers about Briana''s health.', '2012-04-03', 44, NULL, '2026-04-03T16:35:31Z', '2026-04-03T16:35:31Z');
