INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('ed139b19-bab0-405e-b595-05900a985163', '4d2cac0f-38fd-438b-8afa-acf43952e535', 251, 'Episode 251', 'Christopher Trace and Valerie Singleton introduce a magazine programme for younger viewers. Including: Model Railways: Planning a small layout and Bengo''s Dog Show by Tim. Told by Tim Gudgin.', '1963-10-14', NULL, NULL, '2026-04-03T17:21:47Z', '2026-04-03T17:21:47Z');
