INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('ed263e05-07a6-4cc3-8139-7b5b45c11eb1', 'bf874be3-7e2f-4a0e-b205-c76ac1ad69fc', 106, 'Sein-imation: Dr. Cosmo on Marriage & Family', 'Sein-imation is a series of cartoons of Seinfeld episodes. They were released on the Seinfeld DVDs as special features. They used audio from a set episode placed over a new "toon".', NULL, 22, NULL, '2026-04-03T16:34:09Z', '2026-04-03T16:34:09Z');
