INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('ee485719-ba3f-4346-a693-1b7786d90043', 'c01ddd2a-bdb1-4c97-8d04-58f791ef1c24', 3, 'Dinosaurs', 'While the brothers are building a model of a dinosaur they call the ""Martinandchrisaurus,"" Zoboo tells them he thinks he saw a dinosaur on his way to Animal Junction. The mystery creature turns out to be a monitor lizard. Jackie breaks open a pellet from an owl''s stomach to see its prey''s bones and fur inside, then runs into the Kratts while visiting the Royal Ontario Museum to see dinosaur bones.', '1999-12-07', 27, NULL, '2026-04-03T17:10:55Z', '2026-04-03T17:10:55Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('ee4bac20-0fc9-4c23-bf04-a95d82cdbda9', '23c93536-610c-41c5-ac6b-a6b243423258', 9, 'Mediation Nation', 'Ashley and Stacey each attend their divorce mediation appointments with unforeseen outcomes. Keiarna and Greg examine their relationship more closely. Gizelle spends time with Grace as she anticipates becoming an empty nester. Mia is pushed to her breaking point when her life choices are questioned.', '2024-12-01', 43, NULL, '2026-04-03T16:35:41Z', '2026-04-03T16:35:41Z');
