INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('ee5a259b-164c-4599-9c78-0898c7975932', '1415ef1c-411a-4c26-814a-7c79c3628bc2', 2, 'It Girl, Interrupted', 'Former “it girl” Tinsley Mortimer, has just moved back to the city after a tumultuous few years, including getting arrested, and is the latest boarder in Sonja’s townhouse. Bethenny invites Carole and Ramona over to discuss life, politics and Sonja’s new roommate’s tragic fall from the heights of the NYC social scene. Ramona fills Dorinda in on the dirt she has about Tom, Luann’s fiancé. Sonja throws a Mad Hatter tea party to introduce everyone, except Dorinda, to Tinsley.', '2017-04-12', 60, '/gHORgZdi1k2cPNrHkdZXaSLBvTo.jpg', '2026-04-03T16:35:24Z', '2026-04-03T16:35:24Z');
