INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('ee61d119-67ab-4a68-aef3-9029310a3871', '73ae1459-ba91-4185-a9da-bf6f2844af49', 20, 'No Party Like a Mob Party', 'Leah hosts a party for the 15th anniversary of her brand, Married to the Mob. Luann meets with a ghostwriter for her new memoir and Dorinda celebrates her birthday out on the town with the ladies and John.', '2020-08-27', 60, '/d7lBfPIe50E0xv04Vm0OWhka33m.jpg', '2026-04-03T16:35:25Z', '2026-04-03T16:35:25Z');
