INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('ee7816cb-d281-4240-bd0c-c09a56930be0', '0fa92002-82ae-4609-85e3-3982baa99ae1', 22, 'Postman Pat and the Lucky Escape', 'Pat and the Reverend are accidentally lost in the vestry. While PC Selby and the others chase after Dr. Gilbertson to retrieve the vestry key, Pat and Rev. Timms find a way to escape through an underground passage.', '2005-03-28', NULL, '/gnb626VQXv8wqLbaPSsM5q8EI8f.jpg', '2026-04-03T17:14:30Z', '2026-04-03T17:14:30Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('ee7819b7-bcb1-4312-8e54-29f81cd0dcc7', '5144de59-e67f-4fcf-919b-7106989ab797', 19, 'Party of One', 'Leon learns a hard lesson in racism when he’s barred from attending a friend’s birthday party simply because he’s African-American. Nuzzle refuses to fetch a stick for Kiki because she didn’t say “the magic word” (which Sizzle tries in vain to guess).', '1995-02-09', 29, NULL, '2026-04-03T17:12:21Z', '2026-04-03T17:12:21Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('ee79be3a-6314-448b-9de3-53db3f9cdf7a', '9193e795-da7c-40ec-b68f-f63aa7d5174f', 178, 'The Real History Behind Game of Thrones (Part 1)', 'Watch historians, along with George R. R. Martin, explore the interweaving inspirations of the actual players in the era known as "The Wars of the Roses" and other historical events in this two-part series.', '2016-03-14', 18, '/vugVYerD7nOsSXv8KqokcZNUd7O.jpg', '2026-04-03T15:40:35Z', '2026-04-03T15:40:35Z');
