INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('ee8f0b61-849b-4f21-ab51-5c3a06226d58', '20d7138e-eea8-46a8-8ada-2b0f0ee1f674', 28, 'Episode 28', 'All the stop press news about the 1982 Appeal which is bringing life-saving help to children and babies suffering from acute and chronic renal failure. If your parcel of treasure is too heavy to put in the post, stand by for details of a nationwide free delivery service and see the number of parcels flashing on the Totaliser.', '1982-12-16', NULL, NULL, '2026-04-03T17:21:56Z', '2026-04-03T17:21:56Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('ee8fdfee-6fd3-43fb-89af-426d7b4d02a6', '3ee646e8-23ae-4dec-bbc6-c7e6a210d55b', 114, 'Elmo borrows Radar from Big Bird', 'Savion plays a rhyming game with the viewer while tap-dancing. Big Bird recites a poem for Gina, Snuffy, Savion, and the kids and they must guess who the subject is. He''s someone with them right now, covered in fur, and is cute and small - it''s Radar!

Sponsors: V, Y, 18', '1991-04-18', NULL, NULL, '2026-04-03T17:36:38Z', '2026-04-03T17:36:38Z');
