INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('ee9783bf-53e7-4d38-8f45-9d5eb7ded75b', '2dadbc6b-684f-4884-a0b2-57bda7546dc2', 9, 'Autograph Time', 'Lucy gets the chance to see her favourite boyband, Altitude. She sneaks into their room and gets them tea because they think the food is horrible. On the way back to the studio, she finds out that Abby has had an accident; that is until Lucy realises she hasn''t got a ticket. Abby is played by Samantha Birch, the actress who plays Sam in the following series.', '2000-11-17', 15, NULL, '2026-04-03T17:20:05Z', '2026-04-03T17:20:05Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('eea4b43a-1389-4464-94a3-c190963bbb81', 'dbd3583f-e9b2-46d1-a37e-309eb666e233', 18, 'Fresh Princes', 'Kroy returns home after a monthlong stay at football camp. Kim welcomes him with a home-cooked meal—prepared by a private chef, of course. Meanwhile, NeNe has an important conversation with her youngest son; Phaedra hosts an extravagant church ceremony for her son, but drama surfaces between Kim and Cynthia.', '2012-03-25', 43, '/vL51RWruexcbCGeb5O6DOIIBRvn.jpg', '2026-04-03T16:34:45Z', '2026-04-03T16:34:45Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('eea69323-441a-49b0-9ad9-13aea9053dc1', '7bc54df3-f32a-454e-aef6-a9436c35d53b', 44, 'Episode 44', 'Rogers brings two gerbils to his television house. On a visit to the McFeelys'' house, he finds Mr. McFeely looking after a Saint Bernard. In the Neighborhood of Make-Believe, Bob Dog is practicing for his role in the play "Let the Vet Get the Pet", but it isn''t easy.', '1970-04-02', NULL, NULL, '2026-04-03T17:35:39Z', '2026-04-03T17:35:39Z');
