INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('eeb0f1a5-ef2d-4ec0-aea7-9bb8ef003181', '1d713ca6-4e17-4f84-949c-8cfd98514127', 25, 'Hidden Treasure', 'Shoot the breeze with the Pawn Stars when a tree with an 1800s revolver inside it takes root in the shop. Will Rick think money grows on this tree or will he be barking up the wrong one? Then, Chumlee gets creative when checking out a Renaissance etching by Pietro Facchetti. Will Chumlee be able to etch out a deal or will the artwork fail to leave an impression? And later, the Old Man demands the shop give a Senior Citizen''s Day discount. Will Rick respect his elders or will he tell the old guard to hit the road?', '2014-10-23', 21, '/t6CJ4PbXkYWLTzkp4q5tfapuxXZ.jpg', '2026-04-03T16:34:19Z', '2026-04-03T16:34:19Z');
