INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('ef7bd49b-14d3-4ece-ba65-01816b3d7ba9', '119c16d5-1047-45ec-8242-c72a8eed423b', 21, 'Arthur''s Baby', 'Viewers are taken back, as Arthur and D.W. recollect what happened when Baby Kate was first-born. D.W. is excited with anticipation, but Arthur is very worried. His worries are only made worse when his friends tell him about all the awful stuff that''s going to happen when the baby comes. Still, Arthur, is determined to be a good big brother, but ends up thinking that the baby hates him!', '1996-10-21', 13, NULL, '2026-04-03T17:37:55Z', '2026-04-03T17:37:55Z');
