INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('ef81f1ba-f81e-4480-a170-7b65ee675cc9', 'c01ddd2a-bdb1-4c97-8d04-58f791ef1c24', 35, 'Who''s In the Egg?', 'Rhode Island Red chicks hatch at Animal Junction, but Zoboo, Martin and Chris don''t have any idea what''s inside a strange egg they find in the nest. The guys are surprised to discover it''s a baby alligator, which they take home to mom. Jackie and the Animal Helpers protect salmon eggs so tiny and delicate they can easily break if the water around them is disturbed by making sure people cross the stream away from the salmon eggs.', '1999-09-09', 27, NULL, '2026-04-03T17:10:55Z', '2026-04-03T17:10:55Z');
