INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('ef9e2951-4c66-4bc0-934d-9c81e1249fe7', 'c9adc698-be92-4dd7-94ad-d8f6759361ca', 42, 'Episode 42', 'Rogers visits Mrs. McFeely. In the process, both express their feelings about her illness. In the Neighborhood of Make-Believe, Lady Elaine and Bob Dog show off their bravery.', '1973-04-17', NULL, NULL, '2026-04-03T17:35:40Z', '2026-04-03T17:35:40Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('ef9ed9f3-d47a-4b63-9726-f5db6b8882c1', 'f4c40307-9b5e-4263-a4e0-dfa138131e7f', 1, 'The Letter of the Month Club', 'Telly Monster couldn''t be more excited about his new Letter of the Month Club membership, and soon Vinnie the Delivery Guy is at the door with the letter A. Then a B arrives, followed by C, and D--and best of all, every letter comes with sound! The only problem is that the letters are taking over Hooper''s store and Telly will have to choose between his letters and his friends.', NULL, NULL, NULL, '2026-04-03T17:36:27Z', '2026-04-03T17:36:27Z');
