INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('efa56bae-8d31-4e50-aca6-f6ac714ca01d', '332249fa-796b-4f92-b7f8-421d523b0bdc', 6, 'Don''t Be Sea Salty', 'Marlo picks up the pieces of Sheree’s broken heart with fashion, food and friendship. Another friendship continues to sour after Sanya uninvites Drew from a photo shoot. Things get spicy at a Jamaican cooking class when the ladies turn up the heat and air out their grievances.', '2022-06-12', NULL, '/skSYqlASN9Fm2TZO52EyZnJQPUi.jpg', '2026-04-03T16:34:49Z', '2026-04-03T16:34:49Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('efa92dbd-76f4-435f-bae1-09939eb0de68', '650bac93-7b59-41fc-b277-dc6f8bdcd7bb', 23, 'Fight or Flight', 'Having finally graduated college, Axl tells Frankie and Mike that he''s planning on going to Europe over the summer with Kenny. Although Frankie thinks this is a great once-in-a-lifetime opportunity, Mike is less than pleased and thinks his slacker son should be putting all of his summer efforts into finding a job. Meanwhile, Sue begins to panic after she barely scrapes a parked SUV and doesn''t hear back from the owner after leaving several notes on the windshield, and Brick discovers that his sudden onset of backaches is due to not sitting in his lawn chair, which was replaced by a normal kitchen-table chair.', '2017-05-15', 22, '/gDmi1vYQFYlfu99WY5chZXXmke2.jpg', '2026-04-03T15:40:31Z', '2026-04-03T15:40:31Z');
