INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('efb4be58-868f-4f9e-a629-143bbaf81e39', '842c6419-ab98-4d34-8845-1d9782291aad', 3, 'Integrity', 'When Annie’s handmade weathervanes sell like crazy at the school fair, she cuts a few corners to keep up with the demand. Later, when the weathervanes begin to fall apart, Annie is confronted by angry customers who want their money back. Humiliated, Annie retreats to Plato’s Peak where she hears several tales about the concept of "integrity."', '1998-03-01', 30, NULL, '2026-04-03T17:38:34Z', '2026-04-03T17:38:34Z');
