INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('efb6b720-0534-430a-85b2-f873f2724b32', '96dd06ee-d44a-47f3-9372-e29e8eaa77f5', 2, 'Sam''s Day Off', 'Sam''s popcorn machine is just the ticket for the cinemas, until it suffers from a touch of flumbustication!', '1988-09-08', 10, '/gvUsnFGcwpZR5nlNchXqTfDZySS.jpg', '2026-04-03T17:14:37Z', '2026-04-03T17:14:37Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('efb9272b-9307-4842-ba7f-4417bedb39ae', '42684fca-0bc7-4f4c-bf7d-f41fd288a764', 19, 'Postman Pat''s Popstars', 'Everyone in Greendale is auditioning for Charlie and Julian''s new band. It''s seems no one is right, but will Lucy Selby have the confidence to audition?', '2004-10-05', 15, '/pnWLalNP3DxzzTu7S6lRkJ7dRMA.jpg', '2026-04-03T17:14:30Z', '2026-04-03T17:14:30Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('efbb9d23-45ff-49e6-a1ed-c62f37b836ec', '58adb9ab-3f1b-4a11-87b6-9b0b2dbb6aaf', 2, 'Pawnball Wizard', 'Aim for the high score with the Pawn Stars when a rare Captain Fantastic pinball machine comes into the shop. Will Rick jump at the chance to become the pinball wizard? Then, Corey is offered a Leroy Neiman painting of Marilyn Monroe performing at JFK''s 45th birthday party. After a tense negotiation, something''s gotta give. And later, will Chumlee try to buy a set of stamps from the Stamp Act of 1775 without representation?', '2017-04-10', 21, '/pJldeEp2KD4e1EmW2OBqUxJ2ZjQ.jpg', '2026-04-03T16:34:21Z', '2026-04-03T16:34:21Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('efbc28a5-b0b1-4435-9b1e-28e90988a79b', '110e3467-3698-4e19-a35b-f6ebbaeb4d6b', 5, 'Puss in Boots', 'The amusing story about a millers son who inherits a cat-- not just any cat -- a cat who insists on wearing people''s clothing. But all the money is not wasted -- Puss has a plan to get his master (Ben Vereen) married to the lovely Princess Lovinia-- the only thing standing in the way is the evil ogre. Puss proves that cats are clever in this funny adaption of the Perrault story!', '1985-09-09', 51, '/rptXR8gWHPuDgoThMAi0mCf3DAe.jpg', '2026-04-03T17:38:41Z', '2026-04-03T17:38:41Z');
