INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('efc9f013-0f5a-47ec-986f-dd105524b077', 'de052e8e-7dbd-454a-a6d8-b9afba6e9bfa', 28, 'Marrow Pie', 'The Wombles use too much fertiliser on a marrow, causing it to grow and grow.', '1973-07-03', NULL, '/oGWChzIDciq6NuSIAOnuN2pwljS.jpg', '2026-04-03T17:23:19Z', '2026-04-03T17:23:19Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('efccbb71-2ea0-494f-8a25-63621725525c', '050d8ae1-6cc1-4018-933d-b3c3d13de856', 32, 'Episode 32', 'It was the year Blue Peter turned detective and collected a few bruises!

Remember when Bill and Ben, the stolen Flower Pot Men, were rescued in the nick of time? And when Peter Hawkins revealed the mystery of the Flob-a-Dob Flower Pot language? How was Michael transformed into Tik Tok, the mini-robot from Oz? Was Janet really chopped in three? How can you trampoline with skis on - and what was the secret of the see-through bath?

Other highlights include World Land Speed Record holder Richard Noble''s fire-fighting car, the agony of the Royal Navy Field Gun race, the muddy battle of Ashbourne Football and how free-falling Janet broke her pelvis!

If you missed any of these magic moments in 1984 today is your chance to catch up - and look ahead to 1985.', '1984-12-31', NULL, NULL, '2026-04-03T17:21:57Z', '2026-04-03T17:21:57Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('efcccf56-2e8d-4f3f-b10d-dc1a4c1c4443', '1e085f65-4b69-4500-8ffc-654d2f638dbb', 2, 'The Oct-Dough-Pus', 'Grover and his friend, the octopus, are helping at Hooper''s Store but the octopus can only cook bread. With help from his friends, Grover fulfills his customer''s order while learning that families all over the world make bread in different ways, shapes, and sizes!', '2023-11-16', NULL, '/6wyFI6VquOuCl879XNLUrtUX99s.jpg', '2026-04-03T17:36:51Z', '2026-04-03T17:36:51Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('efce5ea9-b3fb-4438-b88e-d32079985032', '0fa92002-82ae-4609-85e3-3982baa99ae1', 6, 'Postman Pat and the Fancy Dress Party', 'Lucy doesn''t have anything to wear to the party.', '2005-03-04', 15, '/98Na5W2CYVZkWHtoGf7lWJKb0vT.jpg', '2026-04-03T17:14:30Z', '2026-04-03T17:14:30Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('efd4d99d-2e2c-4c59-9d8d-6c91f8f51b7a', 'b8c1b631-9850-45f3-9361-cdad5571a492', 13, 'Coronapocalypse', 'Now that Christine has left the family, big problems with Kody and Janelle''s marriage bubble to the surface; before they can address them, however, Kody and Robyn both get COVID-19; Robyn ends up in the hospital wondering if she''s going to survive.', '2022-12-04', 41, '/iVOL24QJHgUV1KYKzNsWdubt6Bt.jpg', '2026-04-03T16:34:32Z', '2026-04-03T16:34:32Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('efd6b772-7e34-49a8-9e50-f414fc3c0e5e', 'ecdefd77-a7ac-4344-bea1-fb1df2fd0ac9', 1, 'Changing Times', 'Bernard can''t wait to get his watch back when he arrives back from America, but finds it needs to be repaired, and in the meantime is given an alarm clock by the Postman. Everyone is wondering why Bernard came back home.', '2001-11-26', 15, NULL, '2026-04-03T17:20:05Z', '2026-04-03T17:20:05Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('efd798ca-c181-485c-8683-ffb8258d3fca', 'bfdf87ff-01dd-4b54-94bd-19b384f41bdb', 4, 'Frozen Assets', 'As Kelly''s beach party moves indoors, Vicki and Shannon have a chilly face-off about the fate of their friendship. Meghan meets Jimmy''s frozen sperm for the first time as the couple moves one step closer to starting their family. Heather laments how Terry''s tough schedule is jeopardizing their family unit and Meghan advises Kelly to keep quiet when it comes to her opinions on Vicki. A medical emergency lands Briana in the hospital, leaving Vicki to step in as single grandma. Shannon enlists Tamra''s help in making a tough decision regarding Vicki.', '2016-07-18', 44, '/yYwORTVm8qXfzTGAlGfQsE45Far.jpg', '2026-04-03T16:35:33Z', '2026-04-03T16:35:33Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('efd7c1e7-e2eb-4327-83d7-2d30a3cc04e9', 'de8ec769-16bb-436b-be43-aedc7e18a7d7', 20, 'Neighborhood Safari', 'Grover takes Elmo and friends on a Sesame Street Safari and they pretend to be all of the wild animals they see.', '2020-03-28', NULL, '/9biVVVSOrkfA4C9zr3FxVnVo41w.jpg', '2026-04-03T17:36:50Z', '2026-04-03T17:36:50Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('efd9f672-3199-4ee2-bb85-a1586c9b78c7', '6fd9fd9d-e378-411b-94b1-76ba4bd518fe', 26, 'Episode 26', 'with Christopher Trace and Valerie Singleton.', '1965-12-20', NULL, NULL, '2026-04-03T17:21:48Z', '2026-04-03T17:21:48Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('efda247e-2ece-48f9-a8fc-799655c14132', '235468b0-20fc-4714-bc3f-d7e7aeb25f4b', 18, 'Reunion Part 1', 'Guerdy holds the ladies accountable for their actions, or lack thereof, during the infamous water throw. Alexia shares where she currently stands with Todd. Stephanie addresses rumors about her marriage. Julia drops a scandalous bomb.', '2025-10-02', NULL, NULL, '2026-04-03T16:35:12Z', '2026-04-03T16:35:12Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('efe16ee8-4da6-4130-9478-68f1b5c2a67e', '0e419615-4c96-4dde-8ed2-715770ba77bb', 11, 'The Amazing Skippy', 'Treelo invites his squirrel friend Skippy for a visit to the Big Blue House and the kids are all excited to meet him. They are all surprised to learn that Skippy is blind and have a lot of questions for Bear while Treelo takes Skippy on a tour. They learn from Bear that Skippy has a disability, but isn''t sick and that he likes to do many of the same things they do. As Skippy joins the kids during the day, they begin to wonder if he has special powers. He seems to know things that he seemingly couldn''t know without some sort of special power. Skippy, however, teaches them that there''s a lot one can tell by using all one''s senses.', '2002-10-07', 25, NULL, '2026-04-03T17:35:32Z', '2026-04-03T17:35:32Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('efe2a1c8-8be8-436e-98e1-b1ab678459d5', '1cafb2c3-bbcb-4172-b02d-441a5aaa155f', 14, 'Little and Big: Inventor of a Sphere that Goes from Little to Big', 'Mr. McFeely shows a videotape of his visit to inventor Chuck Hoberman. Rogers gets a visit from Mrs. McFeely. In the Neighborhood of Make-Believe, Handyman Negri rescues both Bob Dog and Lady Elaine. Rogers plays a cassette tape of cello music and reflects on Yo-Yo Ma and his son Nicholas.', '1998-08-14', 30, NULL, '2026-04-03T17:35:48Z', '2026-04-03T17:35:48Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('efea67fc-73dd-4abd-afc8-b5643c1f28fd', 'ecdefd77-a7ac-4344-bea1-fb1df2fd0ac9', 8, 'A Worrying Time', 'Sam tries to cure her aunt Rowena of worrying all the time by trying to get her to try high-risk activities, but she is too worried. But when Sam ends up in danger, can her aunt get over her fears to save Sam?', '2001-12-05', 15, NULL, '2026-04-03T17:20:05Z', '2026-04-03T17:20:05Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('efedd3bb-c2fc-4d67-bd2c-758ae6e3d17f', '02849455-d14b-476b-9603-eef5fb5d2ab3', 10, 'RSVPlease!', 'Candiace attempts to persuade her mother to give her control of the family business, while Ashley and Michael revisit their prenup. Monique and Robyn host two different events on the same day, forcing the ladies to reveal their loyalty. After celebrating her birthday without Sherman, Gizelle begins to re-evaluate their relationship and receives advice from a very unlikely source.', '2018-06-03', 42, '/rfmLsSORP4ng5OZsw2nYeLdXdTz.jpg', '2026-04-03T16:35:39Z', '2026-04-03T16:35:39Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('eff3de8f-7e88-41f2-a627-55ecd21e0c67', 'a1b69730-d225-48f2-a7e7-1d314cf3b349', 42, 'Episode 42', 'with Valerie Singleton, John Noakes, Peter Purves', '1969-02-17', NULL, NULL, '2026-04-03T17:21:49Z', '2026-04-03T17:21:49Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('effa772a-b210-44e8-a91b-083e9d16f8e3', '1d713ca6-4e17-4f84-949c-8cfd98514127', 23, 'Smarty Pants', 'Get ready to rock with the Pawn Stars when a guitar owned by music legend Stephen Stills strums through the door. Can Rick take the lead in the negotiation or will he end up getting played? Then, Corey tries to stay focused when a 1800s detective''s camera comes into the shop. Will he be able to snap up a picture perfect deal or will he get shot down? And later, Chumlee faces off with Rick in a battle of wits. Will Rick be the smart money in this pawn showdown or can Chumlee beat the boss?', '2014-10-16', 21, '/j8X41QCVLU9POeLEqYep4delBAD.jpg', '2026-04-03T16:34:19Z', '2026-04-03T16:34:19Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('effc595b-5c21-428c-bcaa-aa00032cffb2', '42e591e2-2a88-4434-ae9f-3d4b1d685613', 2, 'Grumpy Old Man', 'Keep it reel with the Pawn Stars when Rick checks out a recorded telephone conversation of President John F. Kennedy. Capturing a rare moment in which JFK was angry, can Rick keep this deal on track? Then, the guys are flying high when an F16 flight suit buzzes by the shop. Will their offer meet the sky high expectations? And later, the Pawn Shop becomes a hostile work environment when Chumlee tries to secretly record the Old Man yelling at him.', '2013-05-30', 21, NULL, '2026-04-03T16:34:18Z', '2026-04-03T16:34:18Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('f00162a8-4ab6-41df-9120-f3f1fdf5f772', 'a605edf8-69ba-46db-8c0c-523b1ef5447b', 31, 'Episode 31', 'with John Noakes, Peter Purves, Lesley Judd', '1972-12-28', NULL, NULL, '2026-04-03T17:21:51Z', '2026-04-03T17:21:51Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('f002a97c-c1e7-4b86-a8e4-349451cce3c0', '9193e795-da7c-40ec-b68f-f63aa7d5174f', 104, 'Histories & Lore: House Tully', 'Brynden Tully details the history of House Tully, the noble and diplomatic Lords Paramount of the Riverlands.', '2014-02-18', 5, '/yRsD7hZ4EyVQIVgApD6W5MijteD.jpg', '2026-04-03T15:40:35Z', '2026-04-03T15:40:35Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('f0090d85-5b18-4855-8a43-fac7a49132f0', 'efd2082e-32f5-4edd-9a7b-a4326d6992c9', 13, 'The Big Pretend Band', 'Bert learns how to use his imagination and pretend-play a saxophone so that he can join his friends in their pretend band and play in a concert.', '2019-02-09', NULL, '/kxklHW3YjBjdg17uJxSDQxhAkXG.jpg', '2026-04-03T17:36:49Z', '2026-04-03T17:36:49Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('f00a2660-1f45-44fd-8973-04796f86343c', '87f84063-82b3-45a4-936c-3759e5d91ce3', 5, 'Gin and Bear It', 'After the catering fiasco, Whitney and Lisa find a way to put aside their differences; Jen apologizes to Brooks, Heather celebrates Ashley''s college acceptance, and the guys enjoy a night away from their wives.', '2021-10-10', 44, '/rJ8VTCDoc92JcMSKIJh4dFLFM3a.jpg', '2026-04-03T16:35:44Z', '2026-04-03T16:35:44Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('f00a5102-8e8e-4765-ad8a-c98b6a47c63e', 'ecb64ef3-4f80-45a7-b4a9-c04434b02e35', 45, 'Dam Good Time', 'Pay the price with the Pawn Stars when Rick negotiates the sale of a cigar box once belonging to JFK. Can he get top dollar or will the deal go up in smoke? Then, a Civil War era photograph of General Custer arrives in the shop. With its authenticity in question, will Rick fight a losing battle or will he dodge a bullet? And later, after a good sales week, Rick surprises his staff with a field trip to the Hoover Dam. Will the group feel like they''re treading water or will they have a dam good time?', '2014-06-05', 21, '/v6FNyrBlOzy47JDZWXp53t7Mrpo.jpg', '2026-04-03T16:34:19Z', '2026-04-03T16:34:19Z');
