INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('f01bf6dc-787d-4bbc-901f-0adebfaf4b93', '136b81d3-964d-4b8f-a214-92f00d96d6b9', 79, 'Episode 1914', 'Maria teaches the children how to measure ingredients carefully and follow a simple recipe to bake delicious cookies. As they work together, the kids learn about precise measurement and develop patience while waiting for their treats to bake. Everyone enjoys the reward of sharing their warm, homemade cookies together.

Sponsors: F, Z, 3', '1984-03-08', NULL, NULL, '2026-04-03T17:36:35Z', '2026-04-03T17:36:35Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('f01c39b0-a558-4c6b-a6da-18d9365a2ce8', 'ebc99729-ccb7-4d64-82c1-42708cd7ba85', 55, 'Episode 55', 'Make sure mums and aunties are not around for this edition of the programme, as Sarah shows how to make a special card for Mothering Sunday.', '1981-03-19', NULL, NULL, '2026-04-03T17:21:55Z', '2026-04-03T17:21:55Z');
