INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('f02ea60d-97fb-400d-ac7b-3720d177f85a', '650bac93-7b59-41fc-b277-dc6f8bdcd7bb', 22, 'The Final Final', 'Frankie, Mike and Brick begin to notice that their luck has changed dramatically for the better after the Prairie Scouts accidentally paint the Donahue''s address on their curb; and after missing his final college test before he graduates, Axl pleads with his teacher to let him take it, otherwise he won''t be able to graduate. Meanwhile, Sue confides to Brad that her sophomore year in college was kind of a letdown. But a chance to speak to students at her former high school about college life leads her to a realization about her status as a student while at Orson High. A talk with Brad leads into an impromptu musical number about Sue''s many accomplishments over the years.', '2017-05-09', 22, '/2kXGwRkSVUvcxojTQjTQKaOkG3a.jpg', '2026-04-03T15:40:31Z', '2026-04-03T15:40:31Z');
