INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('f0382133-a828-432b-b64f-cb3ad6e9078a', '6f81c872-cdb9-42dd-8377-2c17cb6ed4d7', 8, 'Snuffy''s Dance (repeat)', 'Zoe choreographs a ballet and the dancers must work together to figure out how to make Snuffy fly.', '2017-02-25', NULL, '/zdmQhjdaBslxYcWRchaDEZZypvj.jpg', '2026-04-03T17:36:48Z', '2026-04-03T17:36:48Z');
