INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('f039e607-6ebe-4d6c-b877-e25a8324af47', '4a8e3db0-8068-4ff3-942f-91f45f665f20', 2, 'The Lost Rock', 'A lost rock mysteriously appears in the library, and he can''t remember who he is or where he comes from. The lions then decide to set out and search for clues as to what book the rock belongs in.', '2000-04-04', 30, NULL, '2026-04-03T17:12:27Z', '2026-04-03T17:12:27Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('f0409640-84ca-4ba3-b845-f0c8c437370a', '5db3ff78-e439-48e1-8f67-988ecbf85d17', 3, 'Paris, the City of Dreams', 'As Dogtanian continues his long journey to Paris he''s soaked by a passing coach. He catches up to the coach and complains angrily to the driver when Julliette comes out and dries him off with her handkerchief. Juliette then tells Dogtanian he''s on the outskirts of Paris...', '1981-10-23', 24, '/rsS877nEcHUUSv6T2wLKgexFrpe.jpg', '2026-04-03T17:18:43Z', '2026-04-03T17:18:43Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('f042aeed-4d93-4958-a7de-c2e00b16e233', 'e03d79bd-e01f-4414-b0b3-f3b5f26e97f4', 1, 'Back to School', 'Frankie comes up with a plan to stay on top of her kids'' schedules; Brick''s new teacher (Doris Roberts) accuses Frankie of being overprotective.', '2010-09-22', 22, NULL, '2026-04-03T15:40:29Z', '2026-04-03T15:40:29Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('f04323b3-affd-44f2-b015-6d84ad485715', '45e01c04-6ac6-41e1-87d8-f749ee230385', 6, 'Twitching The Night Away', 'Norman and Trevor go bird watching. Elvis is preparing to go on a TV show and says he might not be a fireman for much longer. However he decides to help when the forest catches fire.', '2008-03-03', 10, NULL, '2026-04-03T17:14:38Z', '2026-04-03T17:14:38Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('f0446a0e-0747-4410-9b5e-89ec280ec204', '1a534647-384b-4c00-bb6c-a3371ad962eb', 25, 'Avengers Assemble', 'Save the day with the Pawn Stars when two original #1 comic books from the Avengers and Giant Size X-Men series fly into the shop. Will Rick "marvel" over these rare finds or will he play the villain? Then, Corey is faced with a mystery when he is presented with a cane belonging William Pinkerton from the infamous Pinkerton detective agency. Will he call in an expert to help investigate or will he end up closing the case? And later, Chumlee leaves work to track down his own comic book collection. Will he return with the Holy Grail or will his comics not make the grade?', '2015-05-07', 21, '/it67hPWstKPnPcyLJl9tSCSwU2I.jpg', '2026-04-03T16:34:19Z', '2026-04-03T16:34:19Z');
