INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('f0edd7e8-8467-4d8b-91b3-c2255f31eeee', 'f5266c49-eb29-4594-b5d9-f927edfee336', 25, 'Hidden Talents', 'Mowermouth the goat gets to annoy everyone when he places first Shaun, then the Flock under his hypnotic spell. Bitzer and Shaun need teamwork to put the goat in his place.', '2014-09-29', NULL, '/7GynqmGDvRbO7dmrSBlLnGbUAiZ.jpg', '2026-04-03T17:39:32Z', '2026-04-03T17:39:32Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('f0f002ba-d11e-4334-9063-05c139a808aa', 'd5383b3d-5636-4d71-b99c-b84774b4b3c6', 13, 'Pingu''s Dangerous Joke', 'Pingu is out walking. As he goes past a neighbour’s igloo he hears snoring. He throws a snowball at the igloo which lands on the bell, making it ring. Pingu then hides behind a nearby mound. The ringing of the bell wakes up the neighbour, who comes out to see who is there. He can’t see anyone, but then spots the snow on the doorbell. He brushes it off and angrily goes back inside. Pingu thinks this is very funny! Pingu walks on and arrives at Grandfather’s house, just in time to see Grandfather walking off, pulling his sledge. Pingu runs to get ahead of Grandfather, hides as Grandfather goes past, and then follows surreptitiously as Grandfather continues on. Grandfather reaches some old abandoned igloos and starts to collect odd scraps of wood, loading them into a box on his sledge. Pingu has an idea, and hides while Grandfather continues to search for wood. When Grandfather goes a bit further away, Pingu comes out and knocks the box of wood off the sledge, then hides again. Grandfather is surprised when he sees what has happened to his box, and tries to find out what caused the wood to fall off. He stops to examine the ice nearby. Pingu, meanwhile, has crept up to the top of a mound of ice next to where Grandfather is searching, and slides some ice down the mound, which lands at Grandfathers feet. Pingu chortles at Grandfather’s surprise. While Grandfather is consoling himself with a sandwich, a boulder of ice that Pingu loosened when he got the previous ice for sliding, starts to roll down the slope towards Grandfather. Pingu is dismayed and calls out a warning; Grandfather looks up, sees the boulder heading towards him and, dropping his sandwich, jumps out of the way just in time. His sandwich is totally squashed! Pingu slides down, and says he’s sorry when Grandfather tells him off for playing such a thoughtless trick. Pingu then picks up the box of wood he knocked off the sledge earlier, puts it on the sledge and helps Grandfather to get it home.', '1999-01-21', 5, '/8TcFo6YBu89m1YkpCsepEOwRjXd.jpg', '2026-04-03T17:22:20Z', '2026-04-03T17:22:20Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('f0f0c62c-0cc8-4d91-8572-12b1a6eef9a4', '4d2cac0f-38fd-438b-8afa-acf43952e535', 52, 'Episode 52', 'The magazine programme for younger viewers celebrates its First Birthday with a visit to Switzerland.  Introduced by Christopher Trace and Leila Williams.', '1959-10-16', NULL, NULL, '2026-04-03T17:21:47Z', '2026-04-03T17:21:47Z');
