INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('f19e76f2-e7ab-4908-abe0-b4360efd89da', 'eb7e3bb4-5746-4577-81c6-f5b2dc2efc6e', 10, 'The Library', 'When Aang and his friends find a professor who knows of a library that contains information about the world, Sokka decides to go there to hopefully find some information to use against the Fire Nation. The library is guarded by the knowledge spirit, Wan Shi Tong, who unfortunately doesn''t welcome humans into his library, because he believes they only seek information for evil purposes.', '2006-07-14', 25, '/fvAu7bhOFyI9HEt1Msp0WutlILb.jpg', '2026-04-03T17:40:48Z', '2026-04-03T17:40:48Z');
