INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('f1a60154-0f1a-47f5-b32d-47e19cdc4cd4', '04fb713d-9c59-45f7-8de0-acd7582daa53', 9, 'Communion and Confession', 'The feud between Teresa and Jackie threatens to upset Joey''s communion; Jennifer is offended when she learns that Jackie has written an article about her family. Dolores plans an event for a homeless shelter; Milania copes with her detained father.', '2019-01-02', 43, '/lD2tfFJmjigLRUowOKmKdXYDoTg.jpg', '2026-04-03T16:35:17Z', '2026-04-03T16:35:17Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('f1b1daf3-5154-4a6e-97df-89a82f3a9877', '3982796b-5451-4100-9042-46bedf6a20a5', 12, 'Pingu''s Parents Have no Time', 'Pingu and Pinga are flying their kite when the wind goes light and it crashes onto the roof of the igloo. Pingu tries to pull it off with the string but the string breaks. Pinga goes inside to get help from Mother or Father, but they’re busy and say that they have no time to help. Outside, Pingu is trying to dislodge the kite by throwing snowballs at it. The first one hits Pinga as she comes back out of the igloo. She cries, but is comforted by Pingu. The second hits the kite, which slides off the roof and lands on the ground in a broken heap. This time Pingu goes in to ask for help, but Mother and Father are still too busy. Pingu and Pingu then go off on the sledge to see Grandfather, who helps them make a new kite. Meanwhile, Mother and Father realise it is getting late and go outside to get Pingu and Pinga, but there’s no sign of them. They get on Fathers motorised sledge and go looking, asking the post-office attendant, the fishmonger and a neighbour if they’ve seen them. They all say they haven’t. Eventually they arrive at Grandfather’s igloo, where they see a kite being flown behind the igloo; Pingu is flying the new kite, watched by Pingu and Grandfather. Mother and Father thank Grandfather for his help, and Mother, Father, Pingu and Pinga all go back home together', '1993-05-09', 5, '/nRqFZed0YMw3h0qHDuu6MjAmFig.jpg', '2026-04-03T17:22:19Z', '2026-04-03T17:22:19Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('f1b5685f-06d8-4b85-b4c3-0f99b179b170', '1f34e241-4c1d-4586-921a-1c5aeb1fbbaa', 127, 'Leo''s street party', 'Gordon comes across Dexter juggling in the yard and wishes he can juggle as well as he can. Telly has caught word that Leo the Party Monster is throwing a dance party, but has a big worry - he doesn''t know how to party. Leo tries teaching him some of his moves and recommends he practice.

Sponsors: B, E, 3', '1986-05-13', NULL, NULL, '2026-04-03T17:36:36Z', '2026-04-03T17:36:36Z');
