INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('f1b93516-e901-41c4-b9d8-33090cb60adc', '42684fca-0bc7-4f4c-bf7d-f41fd288a764', 17, 'Postman Pat and the Job Swap Day', 'The school roof needs repairing so Pat suggests that Greendale has a job swap day to raise enough sponsorship money.', '2004-10-01', 15, '/xl4aS41fl4Lzu3ReXMr4ml62iq2.jpg', '2026-04-03T17:14:30Z', '2026-04-03T17:14:30Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('f1ba7d8b-727b-4f05-98b7-888b71a0d2a0', '1996ddd8-20c9-4a30-96be-2b87fab8d17c', 31, 'Building Bridges (1)', 'The team is excited about the upcoming star jam talent show because they are in charge of it. When their friend Cambell arrives with a sore eye, they realize that violence is in the neighborhood. Rob, a coaching assistant, makes friends with an ex-gang member. The gang feels safe that Hurston hasn''t been the target of vandalism. Or has it?', '1993-04-25', NULL, '/yFMmVXAnXWuGxNOD0ZyOGSRXvaF.jpg', '2026-04-03T17:40:28Z', '2026-04-03T17:40:28Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('f1bb45a1-8245-4877-acfa-83ad38b6b09c', '097823b3-4b9f-460d-9ccf-923af9e525bb', 14, 'Celebrations', 'Friday''s Comet arrives in the Neighborhood of Make-Believe, bearing a note that neither King Friday nor anyone else will forget. They all go to the Museum-Go-Round for Henrietta''s surprise birthday party. After the party, Henrietta is surprised to hear that Reardon is making a new opera that will air the next day.', '1986-05-08', 30, NULL, '2026-04-03T17:35:44Z', '2026-04-03T17:35:44Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('f1c1dedd-4aca-4b3c-86d9-6e5b58af277f', 'e40e6b63-9f84-449f-8e88-53209b0906c8', 5, 'Abby Plays the Letter ''P'' Game', 'Elmo wants to play tag, but Zoe wants to play checkers. Alan notices them arguing, and suggests they play the "letter P game." In order to play, they need to look around the store for things that start with the letter P, such as pickles. While Elmo and Zoe have difficulty looking for P words, a penguin (who pronounces his p''s hard) comes in and orders a peanut butter sandwich on pumpernickel bread, with a slice of pineapple, and a potato.', '2007-08-17', NULL, '/e0kcpXRHV9K3gavXwmbTvNiCnQl.jpg', '2026-04-03T17:36:45Z', '2026-04-03T17:36:45Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('f1ca2f55-f9ce-4176-b7da-04128fb39e54', '332249fa-796b-4f92-b7f8-421d523b0bdc', 14, 'Montego Baes', 'As Sanya continues to host the group trip in Jamaica, Kenya is not impressed with Sanya’s hosting skills. Kandi has a hard time moving past her conflict with Marlo. Everyone is over the drama when Drew races herself into another injury.', '2022-08-14', NULL, '/w1w8rmPQaxKNUQCed7QVoiQh4iM.jpg', '2026-04-03T16:34:49Z', '2026-04-03T16:34:49Z');
