INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('f2c34cad-3e13-4e25-a7f7-0377e5b6c17e', '91c151d9-8497-4056-a4ee-753cdcb08cea', 4, 'Episode 1459', 'Mister Rogers arrives with a plastic pail which he takes to the garage. On the way, he picks up a bottle of glue from the kitchen and fills the pail with sand from the backyard sand table. In the garage, he spreads the glue on a large piece of construction paper and sprinkles it with sand. Chef Brockett calls to let Mister Rogers know he will be coming over to bring back the film of Mari Gardner from the previous day. While he waits, Mister Rogers makes another piece of artwork with glue and glitter.', '1976-02-19', NULL, NULL, '2026-04-03T17:35:41Z', '2026-04-03T17:35:41Z');
