INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('f35dd001-2a08-4418-8c57-763f879910e8', '1415ef1c-411a-4c26-814a-7c79c3628bc2', 12, 'Regency Reunion', 'Sonja’s love triangle gets more complicated as things heat up with "Frenchie." Meanwhile, Tinsley goes apartment hunting. Carole and Adam bicker over items he left behind in her apartment. Fredrik and Bethenny look over her apartment as they plan to put it on the market. Carole and Dorinda go to Washington DC for the Women’s March. Ramona throws a party at her apartment with a surprising guest list.', '2017-06-21', 60, '/zBPCzqxxf9ByL8oLpkiE67F17Ws.jpg', '2026-04-03T16:35:24Z', '2026-04-03T16:35:24Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('f3670d22-8ae0-4a6f-9f45-b0fda6b30d3f', 'c21dbd22-5e2e-4414-bb67-750399aaf6f0', 16, 'Cash Cash Bang Bang', 'The Pawn Stars are amazed when a first issue Spider-Man comic book swings into the shop. Potentially worth hundreds of thousands of dollars, will the guys have the spidey-sense to buy this super rare book or will they tangle up the negotiation? Then, a guy moseys in with an antique 1860 Colt Army Pistol. Considered the assault weapon of it''s day, will Rick have the firepower to draw up a deal? And later, Old Man checks out a gold mining stock certificate issued to author Mark Twain. Issued in 1876, will the deal pan out, or will the guys end up in a deep hole?', '2012-01-16', 21, NULL, '2026-04-03T16:34:17Z', '2026-04-03T16:34:17Z');
