INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('f368169f-3667-4335-8ca4-5c552c451a47', 'f4c40307-9b5e-4263-a4e0-dfa138131e7f', 71, 'Elmo''s World: Pets', 'Having pets teaches kids about responsibility and caring - and ELMO''S WORLD: PETS! helps them understand more about what having a pet means. This compilation of episodes shows how to keep pets healthy and happy, and features both adults and kids caring for their own pets - including Elmo and his pet goldfish, Dorothy. Features the charming animation and fun live-action footage of the "Elmo''s World" series.', '2011-04-11', NULL, NULL, '2026-04-03T17:36:27Z', '2026-04-03T17:36:27Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('f36c7499-14f4-4ca7-bbfe-618c4fcf7c6f', '3269a890-bba9-4e6c-9278-f7eb38eb1720', 19, 'Populations', 'Populations need a couple of basic things to survive – food and a place to live. When two or more populations of living things are crowded into a small area, there is competition for food and space. A population of birds and a population of squirrels compete for seed and bread crumbs in a park. Competition is a natural part of life, but problems can arise if populations get out of balance.', '1995-10-20', 26, '/akr8Ox85ARRwXHsGftqzjhfkHsc.jpg', '2026-04-03T17:37:21Z', '2026-04-03T17:37:21Z');
