INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('f4097d8c-0990-42d8-8160-656c8e6231dc', '6c71887a-d6e3-41f1-aa7c-f482abc104d2', 2, 'The Silver Chair (2)', 'Jill and Eustace are introduced to Puddleglum who agrees to be their guide to the ruined city of the giants, but will their new found Marshwiggle friend meet his fate before they manage to get there?', '1990-11-25', 30, '/kLVTjJwdQEakEU3jwceGf2o0eB8.jpg', '2026-04-03T17:17:41Z', '2026-04-03T17:17:41Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('f40a787b-9d2c-4f44-84eb-ea19ebeb0285', '45e64a15-8fc0-4e4b-a1ca-9e3f42f3634d', 12, 'Sound', 'Listen up, scientists. Bill Nye is here to make some noise in the ""Sound"" episode.   Your vocal cords do it. Speakers playing rock music do it. Even a school bell does it. They all vibrate; and   that''s how sound is made. Plucking a stretched rubber band makes the rubber band vibrate. Air molecules   around the rubber band move, pushing other air molecules. As the rubber band continues to vibrate, it   sends waves of sound through the air. It''s a lot like the ripples you see when you drop a rock into a pond.   You hear sound when rippling air pushes on tiny bones in your ears. Nerves in your ears send a message   to your brain about the sound you''re hearing.   Different sounds make different patterns of waves with different distances between them. Plucking,   banging, whispering, and yelling are all vibrations in air, yet they all sound very different. Sound vibrations   can be thought of as waves moving through molecules. Low-pitched sounds have big gaps between   waves, while high-pi', '1993-11-26', 26, '/kqezzxipxNonCR1nXWfUyMElgXR.jpg', '2026-04-03T17:37:20Z', '2026-04-03T17:37:20Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('f4159cf9-67f8-42f8-9e81-dd71ccff6fc7', '83d1c2fb-7cd9-4977-9a5d-98d36cfb59d3', 47, 'Eipsode 2598', 'Loud talker Guy Smiley goes on safari and scares off the animals.  A classic skit staring Ernie as "Old King Cole".  The Two-Headed Monster sings a lullaby to itself.  Snuffy writes a love letter to his grandmother.  Mumford''s magic trick accidentally shrinks David.  Ernie hosts an arboreal fashion show.', '1989-04-26', NULL, '/uc0vsmQKgZzDLHGAJQTukScdvvc.jpg', '2026-04-03T17:36:37Z', '2026-04-03T17:36:37Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('f4159d39-b269-4393-af4e-385380932efe', '7c542833-ed0a-4272-9c53-e822408ab434', 19, 'Moose Versus the Mole', 'A ''pesky'' mole causes trouble for Moose when the mole decides that Moose''s Wild Man Golf course is the perfect place to build a few molehills.', '2024-11-04', 10, '/hoezU6bcpPw0yY5vVBvTCh4IUsu.jpg', '2026-04-03T17:14:42Z', '2026-04-03T17:14:42Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('f41dbee2-3b50-464c-8aed-ac795c6e9ab6', '0bbd380c-5cb8-46a6-8838-b5d60223c073', 21, 'Bruce Forsyth', 'Fozzie Bear has a plan to get back at Statler and Waldorf when he does his act, but is crushed when he''s replaced by Bruce Forsyth. Fozzie throws some nasty jokes and, for the first (and last) time, leaves the two old codgers speechless. Then Fozzie and Bruce end up performing together, and sing "Side by Side." A duck appears frequently in the sketches and skits.', '1977-01-30', 26, '/yVVPr4poG1ONKMbkkogPpG2Y6Js.jpg', '2026-04-03T17:35:24Z', '2026-04-03T17:35:24Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('f41f477a-9c14-40ea-8d2a-3976a4734dfe', '7da1b693-04d1-4168-a0a0-9715407c04c6', 15, 'Wicker Bear', 'Tom and Moose try to build the world''s largest wicker bear, but inadvertently cause chaos when it falls onto a campfire.', '2016-06-25', 10, '/3XDgVBJxhj5oHIpMH4xSJywRWt.jpg', '2026-04-03T17:14:40Z', '2026-04-03T17:14:40Z');
