INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('f4fc17c9-c60b-45da-8607-6cbfcec4c211', '3fc7c152-e4f6-426a-a899-36ec454c4403', 36, 'Wheezie''s Hairball', 'Wheezie gets a new pet Hairball named Slurpy and learns how to take care of him. However, after getting carried away with too many dragon berries swallowed whole, Slurpy ends up with a bad stomachache. Luckily, Quetzal advises them that hairballs like their dragon berries mashed.', '1999-10-20', 30, NULL, '2026-04-03T15:26:03Z', '2026-04-03T15:26:03Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('f4ffcf31-6010-4242-81b7-41c2f2f5fb9d', 'a6efe883-0113-4477-bf06-57b42a3770ee', 1, 'The Butter Shave', 'Kramer uses butter for shaving--and more; George''s cane is an advantage at his new job; Jerry feels used by his comedy nemesis, Bania; Elaine breaks up with her boyfriend before their flight back from Europe.', '1997-09-25', 22, '/uw27jspfnJw6DlHa6xC4elIl905.jpg', '2026-04-03T16:34:12Z', '2026-04-03T16:34:12Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('f506fc00-e65f-45cc-b138-d201d8a880bc', '6fd9fd9d-e378-411b-94b1-76ba4bd518fe', 6, 'Episode 6', 'with Christopher Trace and Valerie Singleton.', '1965-10-07', NULL, NULL, '2026-04-03T17:21:48Z', '2026-04-03T17:21:48Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('f509e26c-8b78-4570-ae04-a3f5b7085953', 'e291df42-d44f-49e5-bf81-2df32ee4a30f', 8, 'Woodland House Wonderful', 'Despite something of a mess in the living room of the Big Blue House, Bear is prepared for a relaxing day. He settles down for some relaxing music listening, but then receives a phone call. It''s Ms. Henrietta Vanderpeen, informing him that the Big Blue House has been selected as the House of the Month for Woodland House Wonderful. Bear is excited, but worries about the state of the house. He tells the kids the exciting news, but finds out from them that there''s even more cleaning to do than he thought. Everybody pitches in to get ready by cleaning the house, taking a bath, and brushing their teeth.  Songs  Clean Up the House  Everybody in the Tub  Brush Brush Bree', NULL, 25, NULL, '2026-04-03T17:35:32Z', '2026-04-03T17:35:32Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('f50a9da7-1a17-4c24-b089-e89e99e138b4', '301fb913-4e76-408f-b84b-05bf979766fe', 14, 'The Cadillac (1)', 'George becomes obsessed with Marisa Tomei after he''s told he''s her type; Jerry gives his father a Cadillac.', '1996-02-08', 22, '/yqWbODXf9sLJs6yhgXuv8snrUlx.jpg', '2026-04-03T16:34:11Z', '2026-04-03T16:34:11Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('f510dbdc-45f9-43e8-9051-836f67e06ef5', 'dc6ef505-d194-4259-b256-5711d25aca6b', 1, 'Dragonstone', 'Jon Snow organizes the defense of the North. Cersei tries to even the odds. Daenerys comes home.', '2017-07-16', 59, '/3SB4PUzZAnY6HnZbVbktIZoopGs.jpg', '2026-04-03T15:40:37Z', '2026-04-03T15:40:37Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('f5194d52-4f5e-4bf1-9017-bdc257b09749', '1a534647-384b-4c00-bb6c-a3371ad962eb', 15, 'Live Long and Prosper', 'Get fired up with the Pawn Stars when an Eli Whitney Civil War revolver drops into the shop. Will Rick go forth and win this firearm, or will he blow his shot? Then, Corey boldly goes where no man has gone before when checking out a signed picture of the original Star Trek cast. Will he engage and beam this item into the shop permanently, or will things get highly illogical? And later, when Corey un-friends Chumlee on social media, Chumlee decides to un-friend Corey in real life. Is this the end of them as pals or will it lead to the beginning of another beautiful friendship?', '2015-03-05', 21, '/s8BfDMaVH6UpZ264qLhxWifDsfu.jpg', '2026-04-03T16:34:19Z', '2026-04-03T16:34:19Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('f51f44be-8b1d-496f-8c08-bfbc09bf842e', 'a7421c26-c9a2-437a-be12-2cabed2b5a96', 12, 'Orbie and the Bullfrog / Two Brothers / The Loon', '', '2001-11-21', NULL, NULL, '2026-04-03T17:11:22Z', '2026-04-03T17:11:22Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('f5209b58-71a8-421d-a08d-f204dc99e759', '0b9d7ae7-218e-45a0-8c3a-e69912f5a6ed', 16, 'Franklin Camps Out', 'Franklin becomes too dependent on his friends when they were on a camp out. Eventually they get sick of it and stop. At night, the wind wakes Franklin up who sees the tent in danger, and with Bear asleep, he learns to be self sufficient in tying it down securely by himself.', '1999-12-06', 12, NULL, '2026-04-03T17:40:15Z', '2026-04-03T17:40:15Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('f52822ac-7d30-41e1-ba18-fe32e68d5f66', '943b0c94-0cc5-40e8-a0e1-bd5660772cc3', 1, 'A New New York', 'Season 5 begins with Sonja hosting a party to introduce three new cast members—Aviva Drescher, Carole Radziwill and Heather Thomson. But the successful bash takes a dramatically downward turn when Ramona arrives and revelations come to light.', '2012-06-04', 60, NULL, '2026-04-03T16:35:23Z', '2026-04-03T16:35:23Z');
