INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('f53a0bcb-0ed2-4807-9efd-8175bde4ca79', '0e419615-4c96-4dde-8ed2-715770ba77bb', 16, 'Grandma Flutter''s 100th Birthday', 'It''s Grandma Flutter''s 100th birthday. Bear and the kids of the Big Blue House take some time to reflect on aging and all of the experiences that life has to offer. Ojo, Treelo, Pip and Pop work to decorate the house and prepare for the party, but Tutter still needs to pick out a gift for her. Bear takes him to the General Store, but he''s not sure exactly what to buy her. While at the General Store, Tutter learns about some of the wonderful things that his Grandma has done in her life. As he hears more and more, he becomes overwhelmed, until Bear helps him to see how he can work it all into a perfect gift. Bear also plays a game of chess with Doc Hogg. He''s not very good, but Doc Hogg helps him to see that he has a lot of time to learn. Shadow also pays a visit and tells a story about about the life of a hammer.', '2006-04-24', 25, '/c1N3c2vZO7qTsEnaNOmFYXwL5Ku.jpg', '2026-04-03T17:35:32Z', '2026-04-03T17:35:32Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('f548a944-3a4f-41d5-a9fc-180d28bba3bf', 'd1d267dd-e27f-4543-acb8-0d28f676512a', 72, 'Episode 72', 'with Valerie Singleton, John Noakes, Peter Purves.', '1968-05-16', NULL, NULL, '2026-04-03T17:21:49Z', '2026-04-03T17:21:49Z');
