INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('f5aae226-7b46-4d4d-8269-4f2dadb0f33a', '70c8cb46-2494-4dd4-98f6-6bfb9b3faf73', 26, 'Aw Shucks!', 'The Pawn Stars meet a man hoping to sell a mysterious coin from the 1800''s believed to be from George Washington''s funeral. Will this piece be linked to one of our most revered Presidents or will it get stamped with a Presidential veto? Then the boys head out to the farm to see an early 1900s hand-crank corn shucker. Can they count the kernels and make a deal or will this husk prove too thick? And later Rick has a chance to buy an antique gaming wheel commonly used in speakeasies. Can he turn a profit, or will this deal spin out of control?', '2010-06-21', 21, '/kumcDRjwqYzJDEStL9ybCJqcki3.jpg', '2026-04-03T16:34:16Z', '2026-04-03T16:34:16Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('f5acc33b-a764-4e20-95c6-38248a52cab8', '4eb9b495-7962-41d9-ba8a-3bed48d9bcc6', 4, 'Too Cool', 'Lionel thinks the new kid at school, Derek Cheetah, is too cool to be on his baseball team. But what does Derek think? Guest Starring Mo Lewis of the New York Jets.', '2002-10-07', 30, NULL, '2026-04-03T17:12:28Z', '2026-04-03T17:12:28Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('f5ad82ab-928a-4df2-9127-eaa9df1cf112', '0b9d7ae7-218e-45a0-8c3a-e69912f5a6ed', 4, 'Franklin''s Starring Role', 'Franklin feels sad when he doesn''t get a big part in the school''s production of Sleeping Beauty, thinking he won''t get the same attention as a stage manager, not until he realizes how important his role is.', '1999-10-18', 12, NULL, '2026-04-03T17:40:15Z', '2026-04-03T17:40:15Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('f5af98a2-02ac-4a54-b377-a33f93c281aa', '3fc7c152-e4f6-426a-a899-36ec454c4403', 40, 'No Hitter', 'Max''s anger is out of control when he punches Emmy''s arm and later kicks Ord''s tail during a game of Dragon Ball when things don''t go his way. Quetzal teaches him to redirect his fury, first by not hitting others, next using words, then action, to let it out.', '1999-10-22', 30, NULL, '2026-04-03T15:26:03Z', '2026-04-03T15:26:03Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('f5b27e20-8597-4ff3-a2bf-aa0e963e28c6', '7b19039a-31ac-425c-8fb1-b51cf2447821', 16, 'Reunion (2)', 'In part two of the reunion, Braunwyn struggles to come to terms with her past behavior involving Shannon’s daughter. Gina shares an update on her relationship with Travis. Andy questions Kelly about her social media posts, while the ladies confront Braunwyn about her authenticity. Elizabeth opens up about growing up in a cult. Sean joins the ladies to discuss Braunwyn, their modern marriage and their future. The ladies close out the season with a toast and share what they learned from the most challenging year that tested their friendships and relationships.', '2021-01-27', 44, '/rexq4jxNoWNNx5Fe46InczLv4pa.jpg', '2026-04-03T16:35:34Z', '2026-04-03T16:35:34Z');
