INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('f66c20fb-8c48-4adf-8741-16cfa8536892', '98d80972-e53a-43dd-a03a-7703465e6f87', 32, 'Corey, I Am Your Father', 'The Pawn Stars prepare for battle when a guy brings in a Smith carbine from the Civil War. A problematic weapon known for blowing up in battle, can they keep this rare gun in their sights? Then, a campaign poster and convention hat from JFK''s 1960 Presidential campaign drops by the shop. Will Rick vote to keep it, or will it not poll well? And later, the guys are horrified that Corey has never seen the movie "Star Wars," and force him to watch it on company time.', '2013-03-04', 21, NULL, '2026-04-03T16:34:18Z', '2026-04-03T16:34:18Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('f66c6f3f-08fb-4767-bd3d-bc3b90781b5b', '5a4e38a1-8e54-4974-8097-d7a7b48630a2', 16, 'Episode 16', 'with Valerie Singleton, John Noakes, Peter Purves', '1970-11-10', NULL, NULL, '2026-04-03T17:21:50Z', '2026-04-03T17:21:50Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('f66f6ae3-79a8-41fb-9974-e490b5d33ed4', 'bb919aec-0d5c-4c58-9a5a-fa2a0a5de2b6', 80, 'Episode 485', '', '1973-03-16', NULL, NULL, '2026-04-03T17:36:30Z', '2026-04-03T17:36:30Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('f6713638-d09f-4168-acec-0b2935cf95a8', '9b144910-398a-47d4-9ccd-823d25cc8b0a', 2, 'Poker Face', 'Ashley has a hard time leaving the nest; Teresa''s attempt at an apology turns into a violent brawl; Melissa has a musical surprise for Joe.', '2012-04-29', 43, '/kp5WqR4rPWLAgU0OuKpmPUpYwiZ.jpg', '2026-04-03T16:35:15Z', '2026-04-03T16:35:15Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('f671a7e1-2928-434f-8cc0-aedf0b2dc8ab', '5a824218-5831-4c6d-aef3-8b5ba9147532', 6, 'Episode 1581', '', NULL, NULL, NULL, '2026-04-03T17:36:34Z', '2026-04-03T17:36:34Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('f673ceff-2c9a-4ad2-b61f-7a98527cccc6', 'f812042d-eb85-432e-8047-3675886e0b1b', 15, 'Golden Retrieved', 'Wishbone is distressed with his owner Joe''s infatuation with his new mountain bike, which causes Joe to pay less attention to Wishbone, and to act less caring and patient towards him.  Then when Wishbone goes missing for a day, Joe realizes how much Wishbone means to him, and how his dog''s company is so much more important than his new bike.  Meanwhile, as Silas Marner, Wishbone learns the value of human warmth and companionship as opposed to acquired wealth.', '1995-10-27', 28, '/uIU67cpkKYDnjT7Lavkxi4fIgJJ.jpg', '2026-04-03T17:10:42Z', '2026-04-03T17:10:42Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('f6877e78-6fd0-4f7d-92be-ab6176bf0038', '6a2d2839-7106-4c3b-8906-c9b3e4bfcc8b', 15, 'Valentines and Birthday Whines', 'Heather and Tamra decide to take a trip to Bali; Lizzie has a terrible birthday; Heather throws a Valentine''s Day dinner party.', '2014-07-28', 44, NULL, '2026-04-03T16:35:32Z', '2026-04-03T16:35:32Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('f68afd0d-a65c-4d9a-b00f-5506dd3c3ec3', '101549f4-6ed1-45fa-b543-d08723f65306', 28, 'Episode 747', '', NULL, NULL, NULL, '2026-04-03T17:36:39Z', '2026-04-03T17:36:39Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('f68b8dca-cbc4-4d91-bb77-d206f585c336', 'f4c40307-9b5e-4263-a4e0-dfa138131e7f', 28, 'Bert and Ernie''s Word Play', 'The Muppets are putting on a play on words (get it?), a convenient framing device for a Sesame Street-style reading lesson. Get ready for some sticky, slippery fun when Prairie Dawn directs the G-rated vaudevillian act, complete with Bert and Ernie in straw hats telling corny jokes and a pie-throwing machine in fine working order. There are behind-the-scenes prop emergencies and a finale no-show, prompting rhyming lessons ("Oh, no, Hoho is a no-show!") and plenty of TV clips, including "I Am Chicken," the fowl take on the feminist anthem "I Am Woman." Elmo joins singing partners Mo and Flo in the stirring (substitute) finale, "We Got the Need to Read." Kindergarteners who think they''re too old for Sesame Street might still get drawn in by challenges aimed at beginning readers. Ages 2 to 6.', NULL, NULL, NULL, '2026-04-03T17:36:27Z', '2026-04-03T17:36:27Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('f68cd30c-840d-45e3-862b-a856e6fa05b0', 'f1959b84-1930-4f85-b2fd-9000b3abf48a', 13, 'Episode 792', '', NULL, NULL, NULL, '2026-04-03T17:36:40Z', '2026-04-03T17:36:40Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('f6924f41-3b99-45c6-9526-71cf5361bf47', '432a6abd-dcca-44cc-82ce-fb39e33b8949', 46, 'Jealousy Pt 1', 'Grand-père receives a picture from his granddaughter Collette. This hurts Henrietta, who feels she is not as fancy.

Note: This is the first episode ever to be filmed in color.', '1971-04-19', NULL, NULL, '2026-04-03T17:35:39Z', '2026-04-03T17:35:39Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('f6a02ce5-478e-448f-b9ab-170c4b630631', 'f63c3f61-0970-4e37-81cc-2b9045a9952c', 10, 'Baby Bear Learns To Whistle (3925)', '', '2001-01-12', NULL, NULL, '2026-04-03T17:36:42Z', '2026-04-03T17:36:42Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('f6a23703-e602-4cd9-bac5-d27814be8b7e', '9193e795-da7c-40ec-b68f-f63aa7d5174f', 99, 'Histories & Lore: Old Ghis & Slaver''s Bay', 'Jorah Mormont charts the rise and fall of the Ghiscari Empire, including its battles with the Valyrian Freehold and the slaver cities that carry on in the wake of its destruction.', '2014-02-18', 3, '/vIGxRXPls9hVI5zRyZjQZpcZeuR.jpg', '2026-04-03T15:40:35Z', '2026-04-03T15:40:35Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('f6a2bee9-7b9c-489c-9862-8cce6c79a086', '526bd779-909a-480d-a38d-1fa625a7c21f', 3, 'How They Got Here 2021', 'A half-hour special spilling the tea on all the juicy gossip, disagreements and love affairs; Karen’s struggle to make her marriage work; Gizelle’s rekindled love story.', '2021-06-27', 42, NULL, '2026-04-03T16:35:38Z', '2026-04-03T16:35:38Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('f6a4ae7f-b304-4b4c-be8e-92baac98e726', 'a84aa42d-e738-4081-8da9-1faec0209ee9', 20, 'TV or Not TV', 'After failing to pay the electric bill on time, the electric company shuts off the Heck''s power. This leads Frankie and Mike to cut down on their unnecessary expenses, including their cable TV. The kids take up other activities to fill the void, but Frankie and Mike have a hard time figuring out what to do. Meanwhile, Brick and his other socially-challenged friends have to go outside for recess when the school library shuts down.', '2010-04-14', 22, '/xe04CWO6Ra5kw9DqZSOXFVng5xD.jpg', '2026-04-03T15:40:28Z', '2026-04-03T15:40:28Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('f6aeeee5-2a71-4992-8407-15d1926ee9de', '0ebba123-871d-4d2b-a054-eb85d2ad9450', 104, 'Larryboy The Cartoon Adventures: The Yodelnapper!', 'not a part of this series; shouldn''t be here', NULL, 30, '/wrGkeLux89glqF4Bo0JYMXwm3bG.jpg', '2026-04-03T17:39:39Z', '2026-04-03T17:39:39Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('f6bb32d1-aba5-400b-a4ee-f22eb43206f1', '42e591e2-2a88-4434-ae9f-3d4b1d685613', 44, 'Lost in Spacelander', 'Serve time with the Pawn Stars when they check out a lap desk made by Dr. Samuel Mudd. Made when Mudd was imprisoned for his role in Lincoln''s assassination, can Rick snag it for the shop, or will it make a clean getaway? Then, a 1959 Bowden Spacelander bicycle pedals into the shop. Rarely seen outside a museum, can the guys keep both wheels on the ground? And later, a good deal earns Chumlee a bonus, but will he spend it wisely?', '2013-12-26', 21, '/8hcUDLPZvTTuu1Ng2mUJpYHlHut.jpg', '2026-04-03T16:34:18Z', '2026-04-03T16:34:18Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('f6bce589-6585-4226-bdf2-eb129980c60b', '1bb53927-76f6-4ed3-9c41-5414ad0865ce', 8, 'Feathered Friends and Foes', 'Matthias''s raft drifts towards the rats on shore, watched in horror by Mattimeo and friends. In the roof of Redwall Abbey Baby Rollo, Mrs. Churchmouse, and Cornflower wait to be thrown down unless the abbey surrenders. Triumphant, Slagar drags the miserable slaves onwards as Warbeak desperately and unsuccessfully still seeks Matthias.

At Redwall, little Sister May comes up with a potion to drug the birds with food. Cheek saves Matthias and the other by eating the nibbling fish and drift them to shore.

As Abbot Mordalfus prepares to exchange hostages at Redwall, Warbeak joins Matthias at the river to defeat Stonefleck''s rats. She delivers the deciphered message which will help to locate the young ones but is killed in battle trying to save the other Sparras.

Matthias heads south, deeply saddened by the death of his old Redwall ally. Slagar will pay dearly for his evil.', '2000-12-17', NULL, '/sx6jx0zYUUXG52skjoOoP5DZ0jF.jpg', '2026-04-03T17:12:08Z', '2026-04-03T17:12:08Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('f6bfcc17-d149-42d8-ad08-05a576890432', 'e6254ae4-7d72-493b-8b37-b677d8b76c46', 9, 'Episode 674', '', NULL, NULL, NULL, '2026-04-03T17:36:30Z', '2026-04-03T17:36:30Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('f6c4829b-84ad-4037-b29b-6e5e65a08ea0', '6053b5c1-ce86-425c-8166-e0fcc3466061', 53, 'Episode 53', 'with Valerie Singleton, John Noakes, Peter Purves', '1970-03-19', NULL, NULL, '2026-04-03T17:21:50Z', '2026-04-03T17:21:50Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('f6c53cab-f99a-4f01-b617-0270b9c36ef1', '3fc7c152-e4f6-426a-a899-36ec454c4403', 49, 'Wheezie''s Last Laugh', 'The kids and dragons encounter Mr. Pop, only to mistakenly steal Wheezie''s laugh and all the sounds around. During a merry chase, they learn that everything has its own special sound.', '2000-01-21', NULL, NULL, '2026-04-03T15:26:03Z', '2026-04-03T15:26:03Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('f6ca4c10-0242-4fa6-8484-22a61df8d8f8', '01916834-25ec-43d6-9a1b-8ea5d9630adc', 14, 'Sleep on It', 'After Bitzer and the Farmer stay up all night, Shaun takes advantage of their sleepiness.', '2025-06-12', 7, '/g7QO7nak2Ut9wZDHcE2ocmxlPHj.jpg', '2026-04-03T17:39:33Z', '2026-04-03T17:39:33Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('f6d438f3-90d4-4d36-9cee-975509022c5f', 'b5ab3a72-bc79-4e9b-a531-96739afd7aea', 1, 'Ship in a Bottle', 'Emily Brings home a bottle with some bits of wood in it.  Professor Yaffle tells them it is a ship-in-a-bottle.  Bagpuss finds this puzzling, wondering where it would sail to.  With the help of a nursery rhyme and a poem about Mermaids, the ship is magically reassembled.', '1974-02-12', 15, NULL, '2026-04-03T17:23:58Z', '2026-04-03T17:23:58Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('f6d4e07c-b534-4fc2-b361-25f895bb8d5e', '2dcbd122-86d8-46e8-bbe5-9143875abd34', 19, 'My Music Rules', 'Cellist Yo-Yo Ma and Saxophonist Joshua Redman were invited by Grandma Thora and D.W. They battle over what kind of music is better than the rest-Classical or Jazz.', '1999-10-18', 13, NULL, '2026-04-03T17:37:56Z', '2026-04-03T17:37:56Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('f6e37cbf-b827-4489-931f-d45eed39a89a', '0987f081-b3b7-4e3c-abb7-795e56c279d5', 16, 'Winners and Losers', 'Frankie is worried when Brick decides to go on a three-day school trip to Chicago; Sue wants to know if Darrin, one of Axl''s friends, has feelings for her.', '2013-02-20', 22, '/yvbhNZvzdoahsoTdZ95AyA1KkSQ.jpg', '2026-04-03T15:40:30Z', '2026-04-03T15:40:30Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('f6e8d775-ef15-4e20-a5a3-959d2565f897', 'fb4ecc73-cb92-4c5c-821f-92179058b37b', 102, 'Alice''s first day at day care (3757)', '', '1998-04-07', NULL, NULL, '2026-04-03T17:36:41Z', '2026-04-03T17:36:41Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('f6e9d64e-8e10-4670-84a2-1cb4b1725895', '1e085f65-4b69-4500-8ffc-654d2f638dbb', 17, 'The Kitty Sisters', 'Chris and Elmo put up signs to try to find a lost kitten''s owner, and Grover and Cookie Monster learn all about how to take care of a kitten.', '2024-02-29', 26, '/n1EKlCxEDN0es1Jh6y6eJCo20mk.jpg', '2026-04-03T17:36:51Z', '2026-04-03T17:36:51Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('f6f0388b-1a0a-473a-bddc-f9a3612950cd', '941b8c65-4454-4336-be7c-1d0591c12f90', 21, 'Pingu and the Snowball', 'Pingu is enjoying himself by playing and juggling snowballs. Pingo comes along and starts a snowball fight. As the fight tails off, Pingu makes a larger snowball that he can’t lift. Pingo makes an even bigger one! Not to be outdone, Pingu makes his even bigger, so that it’s now larger than Pingo’s. Then they spot the ski hill and, with a lot of effort, push Pingu’s ball up to the top. As they push, the ball is getting bigger all the time, so that when they reach the top it’s quite large. At the top they take a rest. Unfortunately, the ball then starts to roll down the hill and they can’t stop it. Pingu manages to get out of the way, but the ball catches up Pingo as it rolls down the hill. The ball is rolling fast when it reaches the bottom of the hill and continues on, collecting a line full of washing (with Punki beside it and not in the snowball.) and a cactus (After Grandfather threw it after he sees the giant snowball.) before crashing through a public toilet (with a penguin in it.). It then rolls into an ice overhang and reverses direction, making Pingu, who has been chasing after the ball, hastily reverse and run hard to keep in front of it. On reaching the post office Pingu quickly makes a makeshift ramp from some parcels, which lifts the snowball up, and it breaks apart on landing. Pingo is very cold after his experience, so Pingu and Father take him to their house and sit him in front of the fire with a hot water bottle. Pingu then wraps Pingo in a blanket and rolls him around, to their amusement.', '2004-01-30', 5, '/q1okgMUOIAcA9Bl2vniPC70QGEP.jpg', '2026-04-03T17:22:20Z', '2026-04-03T17:22:20Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('f6f0d76a-2001-4a52-b236-e0ad2dd924be', '6053b5c1-ce86-425c-8166-e0fcc3466061', 59, 'Episode 59', 'with Valerie Singleton, John Noakes, Peter Purves', '1970-04-13', NULL, NULL, '2026-04-03T17:21:50Z', '2026-04-03T17:21:50Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('f6f65bc8-c68b-459f-8a87-f28ad664cfda', '432a6abd-dcca-44cc-82ce-fb39e33b8949', 24, 'Episode 24', 'Rogers draws a song, using paint brushes to visualize the Japanese records he plays. Later Mr. McFeely brings in a big St. Bernard dog. In between, Yoshi Ito enters the Neighborhood of Make-Believe.', '1971-03-18', NULL, NULL, '2026-04-03T17:35:39Z', '2026-04-03T17:35:39Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('f6fcc5bf-0b4b-4bec-90ad-8905d3310506', '432a6abd-dcca-44cc-82ce-fb39e33b8949', 21, 'Episode 21', 'Bob Dog wants to wear shoes so Queen Sara will like him as much as she likes Prince Tuesday.', '1971-03-15', NULL, NULL, '2026-04-03T17:35:39Z', '2026-04-03T17:35:39Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('f702150c-22cf-43de-b32d-f2c264c87ff7', 'abfe14ee-db42-4dde-a96a-601ff3c53ecc', 9, 'The Visitor', 'Cluny captures a traveling spice salesmouse an holds his wife ransom against the mouse entering Redwall and capturing Cornflower. Torn between love and honor, he does as Cluny demands. But with Matthias'' help the two outwit Cluny with expansive flair and rescue the mousemaids, riding back to safety in a spectacular underground waterborne escape.', '1999-09-26', NULL, '/gia72fBxAVMw8Hkf3GzxIppk1kg.jpg', '2026-04-03T17:12:08Z', '2026-04-03T17:12:08Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('f705e5f0-af7f-4cd1-9c74-767a6aa9d39a', '42e591e2-2a88-4434-ae9f-3d4b1d685613', 27, 'Say It, Don''t Spray It', 'Strum along with the Pawn Stars when a Gibson Super Jumbo guitar once owned by Peggy Eames comes in the shop. A former star of the "Our Gang" series, can the guys negotiate an "oh-tay" price? Then, Corey and the Old Man check out a Buck Rogers tin rocket. Made in the 1930''s, will they pay 25th Century prices? And later, Chumlee decides to put some graffiti art on the shop''s exterior. Can he pull it off, or will the only tag be on his toe?', '2013-10-17', 21, NULL, '2026-04-03T16:34:18Z', '2026-04-03T16:34:18Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('f70d827f-07a1-4472-899f-70df9a1eb918', '96dd06ee-d44a-47f3-9372-e29e8eaa77f5', 7, 'Safe With Sam', 'There is a fireworks display being held to celebrate the anniverary of Pontypandy fire station opening. But there are many valuable lessons to be learned about safety.', '1988-12-19', 10, '/6MVtzrT0a7mneWoab8TPZ1Nb5oj.jpg', '2026-04-03T17:14:37Z', '2026-04-03T17:14:37Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('f70ebae0-0094-4b76-a3d8-5567ca59f5cc', '8c3cfac1-d882-4904-b38c-d1981628d00e', 40, 'Episode 40', 'Pussies Galore!  Silver Tabbies Jack and Jill share their third birthday celebrations with Britain''s newest breed of cat, Fearless Tipper.', '1979-01-29', NULL, NULL, '2026-04-03T17:21:54Z', '2026-04-03T17:21:54Z');
