INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('f72bb71e-d809-4c27-ad6b-353674f0f732', 'c373abed-50ef-417e-9f34-4e9050611a1b', 12, 'Chicks and Salsa', 'Heather and Alexis meet at the coffee house to fix their friendship. Briana prepares emotionally for Ryan''s upcoming deployment. All the ladies, and husbands, come together for Lydia''s salsa dance party but Lydia brings her claws out once Slade starts to make rude remarks. Brooks surprises Vicki at the party with flowers and the room begins to fill with rumors regarding her love life. Gretchen is told that Alexis will be at Tamra''s wedding dress shopping trip and questions whether she will attend or not.', '2013-06-17', 44, NULL, '2026-04-03T16:35:32Z', '2026-04-03T16:35:32Z');
