INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('f748168e-3bfa-438f-b25d-4f79c3370d0a', 'f593d90c-5339-42f5-9c88-5bfd48d04075', 23, 'Cock-A-Doodle Shaun', 'The cockerel is missing and there''s no one to wake up the farm. When Shaun discovers the cockerel has been snatched by the greedy fox, he sets off with Bitzer on a daring rescue mission. Will they get the cockerel back in time to wake up the rest of the farm?', '2010-05-02', NULL, '/3rW6eyNTlC2gjxr3misGihM4NkX.jpg', '2026-04-03T17:39:31Z', '2026-04-03T17:39:31Z');
