INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('f76f2baa-1be1-4f99-bb54-a56101bf32a3', 'd0e5568d-939d-4d89-ab4e-c291a90691cf', 10, 'The Missing Tape Mystery', 'It''s Arnold''s birthday and he''s got some great presents. Pig has given him a cassette player - but the tape is missing. They want to play musical chairs - who has the tape? Everyone thinks everyone else has it until Tiger asks some searching questions. And the tape is in Tiger''s.... well, that would be telling wouldn''t it?', '2000-11-30', 30, NULL, '2026-04-03T17:10:49Z', '2026-04-03T17:10:49Z');
