INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('f7798330-f7a6-4826-877e-4a741b2e209a', '3d4d8f6a-9708-47e8-9c99-26ebafdb2609', 24, 'Episode 833', '', NULL, NULL, NULL, '2026-04-03T17:36:41Z', '2026-04-03T17:36:41Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('f77a7389-e732-4753-8fa4-d7729a6ba2bb', '7c756336-29db-4634-b976-e993e8f51da2', 7, 'Over the River and Thru The Woods', 'While Charrisse struggles to break the news of her marriage troubles to her daughter, Monique and her husband Chris try to reconnect as a married couple by returning to where they started. Karen shocks the world of Potomac by revealing her most guarded secret, leaving the rest of the ladies speechless. Armed with Gizelle by her side, Robyn decides to pay Ashley a visit to her restaurant. The pleasantries quickly go out the window as Ashley and Robyn get into it over spreading rumors, gossip, and emu!', '2017-05-21', 42, '/xM4KWd6mSl0FpkapMWvY5V3tMk3.jpg', '2026-04-03T16:35:38Z', '2026-04-03T16:35:38Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('f77b651c-4d4f-450d-ae70-ed609bcc606f', 'e6254ae4-7d72-493b-8b37-b677d8b76c46', 48, 'Episode 713', '', '1975-01-08', NULL, NULL, '2026-04-03T17:36:31Z', '2026-04-03T17:36:31Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('f77da83c-d17c-4bc7-af4d-66c63aa8bc26', '913f846d-85df-4694-8dd4-0d5909f78887', 4, 'Courage', 'Zach promises to drop off his father’s film at the lab before going on a hike with Annie, but decides to do the hike first.  When he and Annie get stranded on a steep trail, Sock goes for a rope while Ari tells a story to boast Zach’s courage.  They get off the trail safely, but Zach doesn’t make it to the lab before it closes.  Now he must have the courage to tell his father of his mistake.', '2000-10-15', 30, NULL, '2026-04-03T17:38:35Z', '2026-04-03T17:38:35Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('f780cd4c-fcef-404f-8f98-cde8ed869386', '4d2cac0f-38fd-438b-8afa-acf43952e535', 286, 'Episode 286', 'Christopher Trace and Valerie Singleton introduce a magazine programme for younger viewers.', '1964-07-06', NULL, NULL, '2026-04-03T17:21:47Z', '2026-04-03T17:21:47Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('f7933924-f2d9-4bb7-8fde-107712a068cd', 'f1325b56-44e0-4b6e-89bc-82cac30afea6', 14, 'Ice Cold In Pontypandy', 'When Trevor is driving his bus to Newtown he skids off the road and lands in a nearby lake. Moose Roberts decides to look for help and leaves but when Trevor starts a fire to keep the group warm the ice on the lake cracks and Fireman Sam comes to help', '2012-10-13', 10, '/5OyeCWKZ3E41pTkfpZVqJmQAdJ2.jpg', '2026-04-03T17:14:39Z', '2026-04-03T17:14:39Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('f7990013-df0c-4bed-8665-483d8d0c9951', '6fedba82-52f3-4184-be77-6b26e556cd0e', 21, 'Paddington and the Cold Snap', 'Paddington tries to help Mr. Curry by fixing his frozen pipes.', '1976-05-07', NULL, NULL, '2026-04-03T17:22:52Z', '2026-04-03T17:22:52Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('f7a20a8f-80a1-44ee-a5dd-045a94ef2886', '21745b85-d269-42fa-b4dd-701b2da5c085', 10, 'Episode 10', 'with John Noakes, Peter Purves, Lesley Judd', '1973-10-11', NULL, NULL, '2026-04-03T17:21:51Z', '2026-04-03T17:21:51Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('f7adaa26-6d65-4d9a-a08b-994156ed088e', '68138de2-0900-460a-b58e-480688f1e081', 3, 'The Big Sleep', 'It''s nighttime at the Big Blue House and Bear is all set to sit on his swing and read a good book. Then, Ojo shows up --- it turns out that there''s a sleepover scheduled tonight that Bear completely forgot about. Before he knows it, Tutter, Ojo, Treelo, Pip and Pop are all there and ready for the big sleepover, despite his protests that they''re not ready. He tries to settle back down to his book, but there''s a lot to do during a sleepover. He prepares the kids a snack, reads them a story and supervises as they all brush their teeth. Finally, everyone is ready to go to bed, after some final, special good-night touches. Ojo has difficulty getting to sleep, but eventually dozes, only to be awakened by a bad dream. Bear soothes her back to sleep and then finds Shadow. Shadow sings her own special version of the lullaby "Hush, Little Baby." 

Songs 

■Under Your Blanket 

■Brush Brush Bree 

■Go to Bed, Sleepy Head 

Notes 

■The title of this episode is a reference to Raymond Chandler''s 1939 novel The Big Sleep. In the novel, the phrase refers to death, not sleep itself. 

■Tutter holds a sleepover of his own in the fourth season episode "Tutter''s First Big Sleepover Bash."', NULL, 25, NULL, '2026-04-03T17:35:31Z', '2026-04-03T17:35:31Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('f7b257a4-0688-4c59-a143-717c1223b353', '7bc54df3-f32a-454e-aef6-a9436c35d53b', 26, 'Episode 26', 'Rogers shows models of a bicycle and a tricycle. Along the way, he introduces the prefixes "bi" and "tri" to compare what each one means. In the Neighborhood of Make-Believe, Bob Dog fears moving wheels.', '1970-03-09', NULL, NULL, '2026-04-03T17:35:39Z', '2026-04-03T17:35:39Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('f7b718f9-c146-45ca-861c-db5797a2f73f', 'acac417e-2aa3-42e7-9e08-ed0d6071a3ee', 17, 'Ship Happens', 'Tensions arise at breakfast as Luann and Dorinda continue their argument from the night before, as do Carole and Bethenny; the ladies ditch the city for a private island and some fun in the sun, despite the strained relations; and the day ends abruptly with a traumatic boat ride after the ladies are rushed off the island due to high seas.', '2018-08-01', 60, '/zt7ABW5m1NI7rqyN6hDGyq6s27A.jpg', '2026-04-03T16:35:25Z', '2026-04-03T16:35:25Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('f7cfc84f-9340-4cf3-a795-a4652dd60bf5', 'cb8a0322-be77-485b-b339-bdd572bca349', 22, 'Arthur''s Almost Live Not Real Music Festival', 'Arthur and Buster show D.W. that you don''t need cameras, lights, etc. to make a music video.', '1998-12-28', 13, NULL, '2026-04-03T17:37:56Z', '2026-04-03T17:37:56Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('f7d26337-424b-49c6-ac5f-6c5c5a9b33d9', '02849655-bd95-4d8d-af3b-03321918eeee', 1, 'Madeline''s Halloween', 'The girls return to New York City to visit their pen pals, and they get to dress up for a PROPER American Halloween Night out in the city.', '2000-09-08', 30, NULL, '2026-04-03T16:34:02Z', '2026-04-03T16:34:02Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('f7d4449f-04ff-42b4-9510-87652611e2b9', 'c382366d-b65c-4f2a-9e91-200f0d973ae9', 18, 'What''s Cooking?', '', '2006-05-26', 13, NULL, '2026-04-03T17:37:58Z', '2026-04-03T17:37:58Z');
