INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('f8a50ec6-55c8-4470-af20-8322913f9318', '227b8429-0dfd-47e4-b874-c37da20c403f', 1, 'Boom or Bust', 'Rick considers buying an 18th Century cannon that could be worth up to $40,000. But, before he makes an offer, he''ll need to verify that it''s the real deal by test firing it first. Then, a local woodworker needs cash to keep his business afloat and looks to pawn his 1.5 ton table saw. The Pawn Stars might lose the deal if they can''t figure out a way to move it back to the pawn shop. Finally, a guy trying to sell his replica Roman armor strikes out with Corey but gets a second chance as Chumlee tries to negotiate what could be his first and last deal at the shop.', '2009-07-19', 21, '/dqyXqh4kH2Tw97DiwXCkTpkE0MO.jpg', '2026-04-03T16:34:15Z', '2026-04-03T16:34:15Z');
