INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('f9160100-fbf4-46d6-91b6-568d11fd4b88', '487fdbcd-ec5a-454e-8268-b50566eb8546', 6, 'Deserted Friendships', 'Sara prepares for Akin''s departure and the couple defines their relationship; Caroline Stanbury struggles to balance her kids'' needs with Sergio''s; Caroline Brooks hosts her son''s birthday, but some of the ladies are absent.', '2024-07-09', 43, '/ksXyNvvgUSQmc2HvUnKZDkQqElt.jpg', '2026-04-03T16:35:07Z', '2026-04-03T16:35:07Z');
