INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('f917b9f1-e463-47cb-b1c3-4dcaf2cd3f82', '5b2c9365-7bd9-4ca1-a3fb-15f1a024a56e', 3, 'Fashion Week', 'Shopping and fashion come to the fore when Jill squires her daughter on an expensive shopping trip, and Bethenny later hits the stores with Jill. Meanwhile, Ramona attends a Fashion Week show, but catty problems arise when she scores a choice seat at the event; and Ramona''s daughter struts her stuff at an elite modeling agency.', '2008-03-18', 60, '/xoaOikVZ9rt611IFO8wyeUjurmF.jpg', '2026-04-03T16:35:21Z', '2026-04-03T16:35:21Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('f918b69e-279a-412e-b3a1-fee29e6ba856', '98d80972-e53a-43dd-a03a-7703465e6f87', 7, 'On Guard', 'All hail the Pawn Stars when they check out a uniform from the King of England''s royal guard. Used by those guarding the royal palace in England since the 1700s, can the guys get the seller to crack a smile, or is he strictly business? Then, Rick checks out a guitar made from a tortoise shell. Does a slow and steady negotiation win this rare piece, or will the price leave Rick shell shocked? And later, when a seller brings in an antique BBQ built in the shape of a pig, the Old Man reminisces about the good old days smoking pork in the South.', '2012-11-19', 21, NULL, '2026-04-03T16:34:18Z', '2026-04-03T16:34:18Z');
