INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('f944e031-e7ca-4647-b87d-24d54427352d', '3087a3ed-e94e-4276-9d02-a78183dea1d3', 23, 'Reunion (3)', 'During Part 3 of the reunion, the husbands and significant others join to give their take on the season. Kandi talks about her new life with Todd and their recent engagement, and the men chime in on Kenya and Walter’s breakup drama. Tune in for other must-see moments, including which Housewife is accused of allegedly “sexting” one of the husbands!', '2013-04-21', 43, NULL, '2026-04-03T16:34:46Z', '2026-04-03T16:34:46Z');
