INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('f95e3aba-fbd9-4ad6-ad2e-44c8bff092f5', '6e0be2a3-a234-453b-abb7-0ba535a93601', 26, 'Franklin''s Mom', 'Bear, Franklin and his family prepare to go out for a camping trip. While packing up, Mr. Turtle accidentally drops a frying pan and it lands on his foot which gives him serious injuries, forcing him to stay out of the vacation. Mrs. Turtle takes care of the rest of the work, which has some differences than what Mr. Turtle does.', '2000-07-30', 12, NULL, '2026-04-03T17:40:15Z', '2026-04-03T17:40:15Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('f960d746-60b7-4458-a021-9d85ce782258', 'da06465b-9154-4feb-a455-374df7dab02f', 23, 'Super Chicken on Sesame Street (4105)', 'Super Chicken helps Luis and Maria replenish their supply of packing tape at the Mail It Shop, helps Miles untie shoelaces, and fixes Gabi’s broken popcorn machine.  As Super Chicken quickly comes to the rescue and solves everyone’s problems, Super Grover begins to feel sad and useless as a superhero. He thinks that perhaps his friends on Sesame Street don’t need him anymore.  However, Luis, Maria, Gabi, Miles, and Big Bird all convince Super Grover that the only real superhero for Sesame Street is him, especially since there’s no other superhero in the world who can give a super hug like he does!', '2005-09-30', NULL, NULL, '2026-04-03T17:36:44Z', '2026-04-03T17:36:44Z');
