INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('f97eb7a8-33f3-4b0e-b48d-96c4db41ca51', '319bd5d6-ff58-426f-b9da-a0bb2cb87b02', 16, 'Storms', 'Storms are big, loud, and often accompanied by rain, snow, sleet, or hail. Where do these wild, dangerous, and necessary tornadoes, hurricanes, and thunderstorms come from? Storms happen when huge different air masses collide. Along the border of these air masses, water vapor condenses into clouds, strong winds form, and the clouds rub against each other with the ground often becoming electrically charged waiting to send lightning bolts across the sky. What starts out as a placid summer day turns into two air masses boxing it out 10,000 meters up.', '1998-05-23', 26, '/azd7TDs0GDVtBeMUBH1OmSkQbz3.jpg', '2026-04-03T17:37:22Z', '2026-04-03T17:37:22Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('f981384b-2ec6-43be-908b-f27b5a113194', '51c41996-c452-4a28-b174-3765855be794', 15, 'Kindness and Unkindness', '"Sir Thomas T. Tune" convinces King Friday to allow the new schooling method.', '1988-05-06', NULL, NULL, '2026-04-03T17:35:44Z', '2026-04-03T17:35:44Z');
