INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('f99641b0-9d1e-493f-8c1c-1e5cba220368', '0bbd380c-5cb8-46a6-8838-b5d60223c073', 3, 'Sandy Duncan', 'Fozzie performs Gags Beasley''s famous "banana sketch," which everyone has heard of except Kermit. When Kermit asks Sandy and Fozzie to tell him what it is, they laugh too hard to explain it.', '1976-09-19', 26, '/4HLcpeVt5OGubDgV2Ftt3f0yKOi.jpg', '2026-04-03T17:35:24Z', '2026-04-03T17:35:24Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('f996dd6e-74ce-4fa9-9608-cc4bf4542c2b', '1d713ca6-4e17-4f84-949c-8cfd98514127', 33, 'Reach for Raphael', 'Be in awe with the Pawn Stars when a print believed to be from Renaissance master Raphael comes into the shop. With it possibly being one of the rarest items to ever walk through the doors, will Rick be drawn to it or will he be unable to etch out a deal? Then, Corey gets rocked when a 1970s Ibanez guitar is brought in. Can he take the lead in the negotiation or will he get played? And later, Corey and Chum try to find out the contents of Rick’s will. Will it be to die for or will they be wishing they passed?', '2014-11-20', 21, '/x61pYhHejWb5Cx9XZUbCUx5qyUy.jpg', '2026-04-03T16:34:19Z', '2026-04-03T16:34:19Z');
