INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('f9b09156-001e-491b-a339-d681ec0d6957', '3269a890-bba9-4e6c-9278-f7eb38eb1720', 5, 'Energy', 'Energy can change forms. Your body changes the energy in food into energy you can use to do things. Dams turn the energy in falling water into electrical energy to bring power to your house. Sound energy changes into moving energy (like when the bass is so high you can feel the floor move).', '1995-02-10', 26, '/zCPLaW9XsZXoE0etzibwK0M7sCo.jpg', '2026-04-03T17:37:21Z', '2026-04-03T17:37:21Z');
