INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('fa54d807-6240-4e7b-88a9-5aad42947907', '56fc6204-8c9d-4ba3-a4e7-0d0a7de40dc3', 13, 'Unforgivable', 'Taylor''s birthday is coming up and everyone is excited. Kim and Kyle finally go to blows after years of pent up family frustration. Meanwhile, another bond is breaking as Camille gets word from her husband that he wants to end their marriage.', '2011-01-20', 43, '/kjxAU3D0SJwqIdxxyvvsAk40FqH.jpg', '2026-04-03T16:34:54Z', '2026-04-03T16:34:54Z');
