INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('fa5d0af9-08b5-4d81-b5a9-b5a517ac7bb2', '937ee587-e2eb-46aa-9a69-3d6bab04398f', 2, 'Keep the Lights Burning, Abbie', 'Sada Thompson reads the story of Abbie, the eldest daughter of a family that tends a lighthouse, and how she had to keep the lamps working during a storm while her father was in the city getting supplies. LeVar visits a family that runs their own sailboat tourism business and actually live on their small craft.', '1987-06-23', 30, NULL, '2026-04-03T17:36:16Z', '2026-04-03T17:36:16Z');
