INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('fa67b89d-b3c0-4667-ac3a-2f36220a0ecc', '5b2c9365-7bd9-4ca1-a3fb-15f1a024a56e', 7, 'Second Chances', 'In the Season 1 finale, the de Lesseps family visits the Statue of Liberty. Meanwhile, Bobby showers Jill with various gifts---but he fails to win points with an offering of lingerie. And Jill throws a holiday bash for the housewives.', '2008-04-15', 60, '/ikExTFFhaYrkJg2lOd4B3vVxuGn.jpg', '2026-04-03T16:35:21Z', '2026-04-03T16:35:21Z');
