INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('fa692430-7d4e-4dbf-9f52-0507e60f5790', 'e40e6b63-9f84-449f-8e88-53209b0906c8', 24, 'Elmo Is Jealous of Marco', 'Gina welcomes the viewer to Sesame Street. Elmo is looking forward to playing checkers with her today, but it becomes difficult because Marco needs his mommy''s attention. Gina thinks he needs to eat, so she leaves with Marco to get his baby food, leaving Elmo all alone.', '2007-10-10', NULL, '/jtz4TJKt0iZRvIlO51jSzqK4CFX.jpg', '2026-04-03T17:36:45Z', '2026-04-03T17:36:45Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('fa6bf0d6-a77e-4300-b8fc-6dc193f85bff', '70d9e397-6813-4785-887d-27d034928bae', 21, 'Pingu Draws a Winner', 'On his way home from school Pingu passes a lottery ticket seller, and watches a man as he has a go. The man doesn’t win, and goes off angrily. Pingu is about to leave when the ticket seller points out the prizes; a car, an igloo and first prize, a box of fish. Pingu is now keen to have a go, but has only a small fish, so he tries to pay with it. The ticket seller angrily refuses and Pingu trudges off. The ticket seller, who is very poor, then relents and calls Pingu back, and gives him a ticket in exchange for the fish. To his delight, he wins a prize and rushes home to tell Mother. She realises that Pingu has won the fish, and phones up to have it delivered. When it arrives Pingu and Mother are very pleased, but then Pingu thinks that rather than keep it themselves it would be better to give it to the ticket seller. Pingu takes the fish to the ticket seller, who is very happy to accept. As Pingu is leaving the ticket seller calls Pingu back and gives him a talisman as a thank-you. Pingu is delighted, and goes excitedly home.', '1996-08-01', 5, '/weaPhBnECgmHPPWZbuY8VLd3NhT.jpg', '2026-04-03T17:22:19Z', '2026-04-03T17:22:19Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('fa6fbcc0-435a-46bf-9789-d8b41bcaafc7', 'c13cac45-2554-4775-bb86-c6aa65c1ca2e', 7, 'Hidden River', 'Steve attempts to rescue a turtle in a river despite the presence of crocodiles.', '1997-05-17', 44, NULL, '2026-04-03T17:39:10Z', '2026-04-03T17:39:10Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('fa71be4c-bcdf-4b14-919c-32b1a4481e5e', '33e647e7-a3e8-4c3a-93e6-74e08399a790', 1, 'Next Time Around', 'Linda has hyptonized Pete to act like a chicken for 10 seconds when someone says ""now"". But how does she undo it?', '1992-04-04', 24, '/3uoHeQU1cW3gTeR3dHHVqY6mJcE.jpg', '2026-04-03T17:40:41Z', '2026-04-03T17:40:41Z');
