INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('fa8ae21a-3325-4e94-9149-ad3663e57641', '4d2cac0f-38fd-438b-8afa-acf43952e535', 31, 'Episode 31', 'A weekly programme for younger viewers.  Introduced by Christopher Trace and Leila Williams.  Owen Williams tells you about working with wood.  Jean and Frank: 5: Frank tends the Garden, stories of some American children.  Spot the Tune, results of the competition.', '1959-05-21', NULL, NULL, '2026-04-03T17:21:47Z', '2026-04-03T17:21:47Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('fa8bd19c-3ead-46a7-a3c2-a95b9468016b', '2dcbd122-86d8-46e8-bbe5-9143875abd34', 4, 'Muffy''s New Best Friend', 'Tired of playing with Muffy because she never played soccer, Francine starts to hang out with Jenna. So Muffy searches for a new friend.', '1999-10-05', 13, NULL, '2026-04-03T17:37:56Z', '2026-04-03T17:37:56Z');
