INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('fa949b02-76c5-42ce-85b8-3c57dd8c56cb', '54900370-8988-46b8-b7aa-61d2b88d7056', 6, 'Out of Gas', 'Friendships are challenged as Heather confronts Lisa. Angie and Mary have a heart-to-heart talk. Britani struggles to reconnect with her daughter. Lisa and John''s communication issues come to a head. Bronwyn''s marriage is tested following major accusations.', '2025-10-21', 42, '/xffLw0dSdJViU9FRFa0iR6w1pd5.jpg', '2026-04-03T16:35:46Z', '2026-04-03T16:35:46Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('fa949e84-e047-416b-8d67-135662220796', 'f4c40307-9b5e-4263-a4e0-dfa138131e7f', 78, 'Learning to Share', 'Like most kids, Elmo sometimes has trouble taking turns and sharing his toys. Even with his best friends Zoe. With a little help from Sesame Street favorites Big Bird, Cookie Monster, and Oscar, and special guest Katie Couric, Elmo discovers that sharing with friends makes playtime twice as much fun. Filled with songs and silliness, Learning To Share is a very special introduction to the Sesame Street Kids’ Guide To Life - a new home video series that helps make growing up a lot more fun. Plus Katie Koric gives parents some helpful TIPS for guiding kids through learning how to share.', NULL, NULL, NULL, '2026-04-03T17:36:27Z', '2026-04-03T17:36:27Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('fa9f9642-3125-484b-a9a6-b3d2c2fa8ce6', '63850e1d-d8ed-4fe4-a068-83cb879c170a', 5, 'The Bris', 'Godparenting is a chore for Jerry and Elaine; tragedy befalls George''s car; Kramer decries a genetic experiment.', '1993-10-14', 22, '/kqThZybfqQvgxu5QGUd772JFeID.jpg', '2026-04-03T16:34:10Z', '2026-04-03T16:34:10Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('faa50e10-c6c8-4bca-8f5d-350e3a64d88c', 'cefd1496-b649-4c62-aef9-35a22558ac08', 6, 'Don''t Cry Over Spilled Tea', 'LeeAnne gets a stunning surprise from Rich at the Texas State Fair. D’Andra decides to call an "Honestea" at her house where she’ll use a teapot, some notes, and a gavel to coerce her beloved back-talking b* to get their issues out on the table and move on. But a little too much honesty threatens to send the teacakes flying.', '2017-09-18', NULL, '/hRh3xMarj91SmnN3PyfGGMNbmle.jpg', '2026-04-03T16:35:04Z', '2026-04-03T16:35:04Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('faaef9c8-6d2a-4fb7-94b1-607701380e3d', '2005d71d-54eb-49f8-ae9c-039eae4089b3', 6, 'Disappearing Trousers', 'Neil goes to buy some new trousers with Rosie and Jim secretly joining in.', '2000-02-08', 10, NULL, '2026-04-03T17:19:39Z', '2026-04-03T17:19:39Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('fab1d722-c0dc-4cd4-9b9b-6ce178ecd9ab', '69b3befe-579a-43ad-a7d6-ec30ffe3adf7', 47, 'Episode 1102', '', '1978-01-31', NULL, NULL, '2026-04-03T17:36:32Z', '2026-04-03T17:36:32Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('fab4a968-1a83-4721-872e-05c1c02a6283', 'df77dba2-bbda-4f38-9713-8d5c856f852e', 9, 'Little Bear''s Big Race', 'Little Bear finds Bramwell Brown examining a piece of tinfoil. Together they make some silver cups, and this gives Rabbit an idea. He suggests they have a sports day and use the cups as trophies for the winners of each race. They have a sock race, a potato and spoon race and a six-legged race. Little Bear begins to feel rather sad because he is sure he won’t win a prize; he is just too small to beat the others. However, his friends find a way to cheer him up and in the end, he has a surprising bit of luck.', '1993-11-28', 10, NULL, '2026-04-03T17:18:55Z', '2026-04-03T17:18:55Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('fab71890-3af1-4bc1-a8a6-db0ff9b9b5f2', '99a96781-44cb-4a5c-9100-71e2a55b6b1a', 2, 'My Baby is All Grown Up', 'Vicki and Jeana have made a pact to get in shape, but getting up at 5:30 a.m. every morning may prove to be the bigger challenge.

Recent empty-nesters Vicki and Donn, seek to reduce the stress in their lives by downsizing and buying a smaller home in Coto. Unfortunately, Vicki is having buyer''s remorse. Vicki likes her big home in Coto and struggles with the notion that downsizing equals failure.

Having just graduated from high school, Kara has been accepted to UC Berkeley. Eager to check out the campus, the Keoughs leave for Northern California, but forget to tell Colton, leaving him home alone.

Since the death of Lou Knickerbocker, Tammy has tried to be a supportive mother to her daughters. Lindsey is keeping busy with the Lou''s Legacy, the OC Angels, but a recent car accident in the Hummer sends the "Angels" to the California Speedway for some much needed driving lessons.

Meanwhile, as Lauri and George begin to build a life together, Lauri decides to put her townhouse up for sale. Unfortunately for Ashley, that means having to find another place to live – but not before a visit to the Playboy Mansion.

Tamra is rapidly approaching 40, but she''s not ready to age gracefully. Conscious of the fact that she''s been raising children for the last 21 years, Tamra is up for anything that will keep her youthful, including riding on the back of a Harley Davidson and hanging out with biker dudes.', '2007-11-13', 44, '/eavlUgJu8joKmHXiEy13zkOrG3.jpg', '2026-04-03T16:35:30Z', '2026-04-03T16:35:30Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('faba788a-fc55-4b32-8f77-4da26d747ee0', '54900370-8988-46b8-b7aa-61d2b88d7056', 17, 'Reunion (1)', 'The women of Salt Lake City come together in NYC to discuss the past season and celebrate hitting a milestone 100 episodes. Lisa answers questions about her self-described very different lifestyle. Tensions flare when Bronwyn and Lisa go toe-to-toe about their truce. Heather and Angie are accused of teaming up against Lisa. Britani joins the stage and gives an update on her relationship with her daughter. Angie brings a scroll of evidence to prove who is behind the alleged leak.', '2026-01-13', 42, '/hl401Q117sCPAUZYaLHMmfdJhA7.jpg', '2026-04-03T16:35:46Z', '2026-04-03T16:35:46Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('fac1f521-b08b-4b4f-9222-e81ce06df48b', '63f9bf6d-39b3-44f4-b885-a56807277a80', 22, 'Studio DC: Almost Live! - The Second Show', 'Hosted by Demi Lovato, Selena Gomez, and Sabrina Bryan. With songs, dancing, and backstage antics, The Muppets and Disney Channel''s biggest stars team up for another fun variety show.', '2008-10-05', 26, NULL, '2026-04-03T17:35:23Z', '2026-04-03T17:35:23Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('fac333ae-1656-4946-99b0-867ca8da9edd', '34674c90-410e-427c-be4d-2a6f6f865a80', 4, 'To the Moon', 'Ride in style with the Pawn Stars when a limousine formerly owned by Jackie Gleason pulls up to the shop. Will this luxury ride really be "The Great One" or is the seller stretching the truth? Then, a football spirals into the shop signed by the winners of Super Bowl I. Including Vince Lombardi himself, can Rick push this deal into the end zone or will he get stymied by a tough defense? And later, Rick and the Old Man are presented with a commemorative plaque of Mount Rushmore. Made of pure silver, will they silver tongues to get a good deal or will the seller’s price be set in stone?', '2012-04-16', 21, NULL, '2026-04-03T16:34:17Z', '2026-04-03T16:34:17Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('face2d39-17ad-470a-81f7-ba703fe4f915', '9e30a416-edbd-490b-bb0f-18d5c45f0bdf', 11, 'Luaus and Lies', 'Brandi and Carlton pole-dance, while Kim throws a going away luau for her daughter.', '2014-01-13', 42, '/47sedTh88f5w2iMoYNn5L45WxsU.jpg', '2026-04-03T16:34:55Z', '2026-04-03T16:34:55Z');
