INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('faf308fe-0e0a-463d-a56d-67f73a4725a1', 'a8c6182e-05e1-4b68-91a5-5126cf6c94f0', 14, 'New York, New York', 'Sarah does a report on the loyalists opinion on the revolution in New York. Meanwhile James escapes to Manhattan with the Continental Army.', '2002-09-19', 30, '/jqSjC4CFqbkIRrTX1X4Sqk5kIPA.jpg', '2026-04-03T17:38:28Z', '2026-04-03T17:38:28Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('faf365c3-f0a7-4ec6-b321-69d7c403daee', '5ba20443-d99f-4820-81f6-6832d3f2bc4f', 7, 'Pollution Solutions', 'Dirty water, land, and air are a result of pollution. People are the only animals on Earth that make pollution. Garbage, burning fuel, chemicals, sewage, oil, and pesticides are all human-made things that make the Earth’s atmosphere, water, and soil unclean. Humans are even leaving trash in space, such as broken satellites, pieces of metal, paint from rocket skin, and even cameras and toothbrushes. Much of the junk people make and leave behind hurts plants, animals, you and me.', '1996-01-12', 26, '/7VasFnXlXP0XYZVRnxR6k5sCa52.jpg', '2026-04-03T17:37:21Z', '2026-04-03T17:37:21Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('faf8b3c1-e160-4bf2-93df-bf4f93911266', '1bb53927-76f6-4ed3-9c41-5414ad0865ce', 6, 'Ironbeak', 'From Redwall Abbey, Warbeak and her sparra squadrons fly South bearing the riddle. They hope to find Matthias to help him for his quest. But they are unaware that their departure is observed by Ironbeak, an evil raven general who invades Redwall as soon as Warbeak is gone. They drive the citizens of Redwall into the cavern hole and make them prisoners in their own abbey. Slagar and his slaves ascend the huge Great South Cliffs and cut off the means of pursuit leaving Matthias unable to follow. They pass along through the Dark Forest and are attacked by the fearsome and terrifying Painted Ones. They survive to find that Slagar is about to cross a huge river beyond which a huge rat army awaits him and his slaves.

Mattimeo is beyond help, Matthias is halted, and Redwall is under siege.', '2000-12-03', NULL, '/d1xY7Bs1rFU4b9uICXUb3wgI81F.jpg', '2026-04-03T17:12:08Z', '2026-04-03T17:12:08Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('faf8d9b9-731c-41f7-b8b6-ed0279535930', 'b1d55597-d9d2-4eee-ab95-46dbb163291a', 15, 'Pingu Builds an Igloo', 'Pingu is going on a camping trip of sorts with Pingo. When Pingu said goodbye to his parents, Father offers Pingu a hat. He does not want to wear it, but father insists. When he leaves he gleefully takes the hat off and puts it in the box. When they meet, they head up at the spot how they will use blocks of ice to build an igloo, however, they cannot agree on where to build one, get into a fight, and go off to build their own separate igloos. Due to them only having half the blocks each, however, they can only build hopeless half-built structures which promptly collapse after some fighting over the last remaining block (Pingu''s collapses, much to Pingo''s amusement, then Pingo''s collapses, much to Pingu''s amusement). They then make up, build a proper igloo, and start up by happily eating fish at night on a blanket inside.', '1990-01-21', 5, '/z5f5pllXxdY14WmS9adPE2seqlK.jpg', '2026-04-03T17:22:18Z', '2026-04-03T17:22:18Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('fb02d634-d27b-479d-a906-0abe3c052dd1', '4d2cac0f-38fd-438b-8afa-acf43952e535', 292, 'Episode 292', 'Christopher Trace and Valerie Singleton introduce a magazine programme for younger viewers.', '1964-08-24', NULL, NULL, '2026-04-03T17:21:47Z', '2026-04-03T17:21:47Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('fb129095-3d91-4d01-8524-8d63fcf89229', '1d556682-d9bb-47e1-993f-0b648a8daacd', 35, 'Episode 1220', '', '1979-01-12', NULL, NULL, '2026-04-03T17:36:33Z', '2026-04-03T17:36:33Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('fb17bbd6-1190-49db-b0aa-a883e6dd6bd7', '68138de2-0900-460a-b58e-480688f1e081', 17, 'If At First You Don''t Succeed...', 'Bear is expecting Doc Hogg to show up for lunch, but busy ol'' Doc keeps changing the plan. Bear and his friends learn to "roll with it" in a day of all kinds of change.', '2010-01-01', 25, NULL, '2026-04-03T17:35:31Z', '2026-04-03T17:35:31Z');
