INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('fb43883e-464f-4708-b39b-324b541af221', '447296c1-2426-4e98-827a-13f4a36afcdd', 9, 'The Chronicles of Buster', 'Buster is enthralled by the new Collector''s Edition of The Chronicles of Amayzzia, so much so that it seems like it''s all that he can talk about.', '2008-11-03', 13, NULL, '2026-04-03T17:37:59Z', '2026-04-03T17:37:59Z');
