INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('fb451f8c-172c-4b67-ba33-5c7d18107a29', '8012f05a-66a3-4254-885f-0a679393f3dd', 4, 'A Crime of Two Cities (4)', 'The team tracks down where the author is reading a Sophie Madison book, and where the kidnapping is held.  The kidnapper is Danny Winkler''s brother.', '1994-10-23', NULL, NULL, '2026-04-03T17:40:28Z', '2026-04-03T17:40:28Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('fb4cb314-cff4-4260-92d2-39c58ee55543', '991e78f1-03a5-4d26-8f75-75e11db4243c', 1, 'Noisy and Quiet: Different Sounds Bells Can Make', 'Rogers witnesses the Westminster Choir College Bell Choir. Mr. McFeely shows a video on how bells are made. In the Neighborhood of Make-Believe, Mayor Maggie presents a loud bell to Henrietta. That bell quickly becomes a big irritant to the others.', '1999-02-15', NULL, NULL, '2026-04-03T17:35:48Z', '2026-04-03T17:35:48Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('fb4df443-8e91-4e14-a7d6-6b3cc970bbe8', '54c29014-2dbd-49ff-a23f-cf4c546e0b3a', 19, 'There''s Something About Harry', 'Carole hosts a lavish party to celebrate her birthday. Sonja is presented with a present from Aviva''s ex-husband Harry.', '2014-07-15', 60, NULL, '2026-04-03T16:35:23Z', '2026-04-03T16:35:23Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('fb562650-33e2-44ef-93a3-0d6d6fd70d94', 'da06465b-9154-4feb-a455-374df7dab02f', 14, 'Mexico on Sesame Street (4096)', 'Rosita is feeling homesick for her abuela and for Mexico. Seeing how much Rosita misses Mexico and her abuela, Big Bird and friends decide to bring Mexico to her by decorating Sesame Street to look just like Mexico! They also bring in authentic Mexican food and Luis sings a traditional Mexican song. Rosita is truly surprised and grateful when she realizes what everyone has done. To everyone’s surprise, Rosita’s abuela shows up too! She missed Rosita so much that she had to fly in to see her. Rosita couldn’t be happier! They all continue the fiesta together.', '2005-09-08', NULL, NULL, '2026-04-03T17:36:44Z', '2026-04-03T17:36:44Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('fb611e60-c26a-4884-bb46-58b9144273e8', 'efdf1e4f-8476-4382-a9d7-2b9da4188be0', 8, 'Transformations', 'Rogers demonstrates that he doesn''t change when he wears dark glasses or a black wig. Lady Aberlin tries the same tactic in the Neighborhood of Make-Believe. Mr. McFeely shows a time-lapse videotape of how the television house is set up in the studios of WQED in Pittsburgh.', '1996-08-16', NULL, NULL, '2026-04-03T17:35:47Z', '2026-04-03T17:35:47Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('fb636802-77ad-4201-aa82-e5c061809697', '4892e2af-46c1-4b4e-ac81-eac161b5a347', 68, 'Episode 68', '', '1978-05-15', NULL, NULL, '2026-04-03T17:21:53Z', '2026-04-03T17:21:53Z');
