INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('fb6fd1b6-37e2-4287-8b9e-4cc0e577b48c', '150d1480-f3f1-43f9-9a22-d2527756fba2', 12, 'Reasonable or Shady?', 'Karen is ready to reveal her new candle line to the rest of the ladies, while Wendy struggles to get on equal footing; Mia''s family and her mum sit down for some much needed time together, but there is still a lot of work to be done.', '2021-09-26', 42, '/up4jXTAG13l1mXea1g0p9NAK618.jpg', '2026-04-03T16:35:40Z', '2026-04-03T16:35:40Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('fb721334-c5c2-4130-88ef-5fb6f86d2705', '4f8c16f6-9b92-4be9-9b6b-837f26ad3720', 7, 'Time Tables', 'Bernard gets into trouble with his music teacher when Mr Beasley accidentally drives off with Bernard''s instrument. At first, Bernard is inclined to seek revenge on his teacher, but ends up learning a lot about the true value of time.', '1998-11-13', 15, NULL, '2026-04-03T17:20:04Z', '2026-04-03T17:20:04Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('fb73dc3d-6c0f-4e10-8613-df0e21b428b5', '21384b9c-43fa-410c-b89d-102e7cf9129b', 15, 'Browns in Crisis', 'Truely becomes seriously ill and requires immediate hospitalization, which puts Mariah''s farewell party on the back burner.', '2014-01-26', NULL, NULL, '2026-04-03T16:34:28Z', '2026-04-03T16:34:28Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('fb75edf9-f4e3-450f-b027-48a1b549deb4', 'c9d2b3fb-7845-4f3c-9847-ce1f7717257a', 18, 'Corey''s House of Blues', 'A signed B.B. King guitar takes center stage at the shop. Then, Chum and Rick check out a house full of pop art inspired by the legendary Andy Warhol. Later, a Japanese sword mount has Corey on edge. Will Corey be able to get to the point and make this deal?

English', '2019-07-29', 42, NULL, '2026-04-03T16:34:22Z', '2026-04-03T16:34:22Z');
