INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('fb8dd84a-4f7d-4fe6-aaed-5436d370056d', 'bbfee3b4-9c95-48a6-beaa-791fa08b1f43', 19, 'Episode 19', 'Today SIMON, PETER and JANET make their most important announcement of the year - so have a pencil and paper handy for details of the 1983 Appeal and find out what it is Blue Peter is collecting and how you can help.', '1983-11-14', NULL, NULL, '2026-04-03T17:21:56Z', '2026-04-03T17:21:56Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('fb92cbf7-80fd-4b0d-8705-64348d8642ae', '4a8e3db0-8068-4ff3-942f-91f45f665f20', 10, 'Lionel''s Antlers', 'Lionel wakes up one morning, much like he does every day, to find that overnight, he''s grown a pair of antlers on his head! To help him feel better, Cleo reads him the book ""Imogene''s Antlers"" - also about a kid who woke up one morning to find she had grown antlers. When Lionel is still feeling low, his parents try to come up with helpful ""uses"" for his antlers.', '2000-04-14', 30, NULL, '2026-04-03T17:12:27Z', '2026-04-03T17:12:27Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('fb943568-e569-43a7-b540-c3c13e753a35', '01b3a1e3-d0e8-4f2b-a56d-9d55669ab5f2', 4, 'Cistern Wives', 'Meri and Janelle talk through old wounds after the family spins off in four directions; Christine takes Ysabel to have surgery in New Jersey; Janelle helps out while Evie gets foot surgery in North Carolina; Meri is in Utah.', '2021-12-12', NULL, '/4eHPGh0u3oysFgOzOBpYQOhf86f.jpg', '2026-04-03T16:34:32Z', '2026-04-03T16:34:32Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('fb99f353-ad34-4c65-85ef-dc7af2eddb8e', '4861ce46-9045-43c7-963f-27b4ea539804', 82, 'Episode 212', '', '1971-03-02', NULL, NULL, '2026-04-03T17:36:28Z', '2026-04-03T17:36:28Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('fb9effdb-4d8d-4ecb-8cb4-393406459344', '9e4790f4-3aab-459c-a5ed-7100b4e39a75', 5, 'Fashionably Absent', 'Sai shares her content creation journey, and Jenna cleans out her multiple closets of fashion artifacts. Escalating tension between Erin and Jessel makes for a frosty café confrontation that Brynn and Sai hear about over a game of chess. Jessel hosts a charity event attended by the who''s who of the fashion elite, except for Jenna Lyons.', '2023-08-13', NULL, '/zPNWvsuj22FU8JTpjyIk4GNokpa.jpg', '2026-04-03T16:35:26Z', '2026-04-03T16:35:26Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('fba0ac5b-dd72-4dad-a7c5-da3be79fd2d5', '6be74684-83e6-4d00-bd69-3e4fca97cabb', 2, 'Mad as a Hatter', 'LeeAnne enlists the help of a Dallas designer to create an extravagant hat for Mad Hatter’s Tea Party, one of the most coveted events on the Dallas social calendar. Brandi struggles with her husband Bryan’s constant business travel as she hosts a birthday party for her mother. Elsewhere, Tiffany and Aaron go house hunting, despite Aaron’s reservations about setting down roots in Dallas. Later, Stephanie and Cary are dragged deeper into Brandi’s conflict with LeeAnne when Brandi arrives to the Mad Hatter’s Tea Party donning a hat decorated with a special surprise.', '2016-04-18', NULL, '/gfu4w0CsLQ4LmQT9w23wZYoPEqD.jpg', '2026-04-03T16:35:03Z', '2026-04-03T16:35:03Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('fba45521-d81e-475a-92a1-127f7cc6670f', '4060ad7f-4b8f-4393-8eb1-66a150b928b6', 33, 'Turtle Tunes', '', '2021-06-17', 26, '/jVGwD3qOpmB0LpepkZcA7Lie4HL.jpg', '2026-04-03T17:36:50Z', '2026-04-03T17:36:50Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('fbb4c71e-9cdd-40fb-bd15-1706b32ed926', '1be79a20-de33-41d1-af17-079035b18d5c', 65, 'It''s Nice to Have Friends You Can Play With', '', '1970-02-06', NULL, NULL, '2026-04-03T17:36:28Z', '2026-04-03T17:36:28Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('fbb61f69-aa79-43e4-8632-bd97d7a2efdd', 'd1d267dd-e27f-4543-acb8-0d28f676512a', 7, 'Episode 7', 'with Valerie Singleton and John Noakes', '1967-10-19', NULL, NULL, '2026-04-03T17:21:49Z', '2026-04-03T17:21:49Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('fbb9cdec-0293-4df4-86db-207c9ff815d2', 'ac068b8e-80f6-46bf-afb2-dcebcf76dc36', 5, 'Fiesta Follies', 'The gang wants to throw Kiki a birthday party, but they learn that she likes different things than they do. Meanwhile, Sizzle becomes a Mexican heartthrob''s biggest fan.', '1998-10-27', 29, NULL, '2026-04-03T17:12:21Z', '2026-04-03T17:12:21Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('fbc456db-dab1-4b10-b0d0-13b8b70db47a', 'f13cb622-84e3-4654-a8f1-0ceab09a9ca6', 13, 'Franklin in Two Places', 'Franklin finds himself caught in a difficult situation when he promises to support Bear during his big-kid baseball game and attend Beaver''s art-show, both of which are happening at the same time. Bear is best friend and he did promise him first, but he wants to honor his commitment to Beaver because he''s always dodged attending her events in the past. Not wanting to hurt either''s feelings, he tries to make himself visible at both events without Bear or Beavers'' knowing, but quickly finds the juggling act harder to maintain than he thought it would be.', '2002-06-10', 12, NULL, '2026-04-03T17:40:16Z', '2026-04-03T17:40:16Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('fbd47120-cb2d-4e37-9cf6-8d5ec0103596', 'c1df0e9b-e03e-48e5-a930-61ee5ef85840', 18, 'The Big Dig', 'Arthur and D.W. don''t want to go to Grandpa Dave because he only want to sleep and play checkers. One day Grandpa Dave shares a secret map, and Arthur and D.W. hunt for the buried treasure.', '2000-10-30', 13, NULL, '2026-04-03T17:37:56Z', '2026-04-03T17:37:56Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('fbd5245a-cade-456d-b2ad-e27e55506208', '9193e795-da7c-40ec-b68f-f63aa7d5174f', 307, 'From Renderings to Reality: The Visual Effects of Season 8', 'Insights and techniques from the visual effects team on creating the show''s final season effects, offering an in-depth look at the process behind the complex visuals.', '2019-07-30', 26, '/7GeFLVPHDbp3jPtBCWXQNeIzKxz.jpg', '2026-04-03T15:40:35Z', '2026-04-03T15:40:35Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('fbd6f151-384f-499b-b362-e896ba2fc49a', 'a8c6182e-05e1-4b68-91a5-5126cf6c94f0', 2, 'The Intolerable Acts', 'Moses, James, Sarah and Henri hide at poet Phillis Wheatley''s house in Boston, where some of His Majesty''s soldiers are being quartered. Hearing Phillis Wheatley''s story, Sarah is confronted with the horror of slavery for the first time. Later, though Sarah does not agree with her new friends'' thoughts about Mother England, she helps them in a time of trouble.', '2002-09-03', 30, '/qSrurbSporAA4uO1w39imXo3Vlb.jpg', '2026-04-03T17:38:28Z', '2026-04-03T17:38:28Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('fbd7cc71-73d4-46c4-a4e4-9043e96791a7', 'efd2082e-32f5-4edd-9a7b-a4326d6992c9', 34, 'Slimey at the Car Race', 'Slimey participates in the Squirmadega car race.', '2019-07-06', NULL, '/h1AeFt3nySdtUNxD6UeudQKNOWS.jpg', '2026-04-03T17:36:49Z', '2026-04-03T17:36:49Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('fbdb71c3-6e5b-4170-b529-76f146d2b638', '40700e8a-1dce-4895-bede-522a13a8bcad', 14, 'Fearfest', 'A big thunderstorm hits Animal Junction and Zoboo sees something frightening in the dark. But the scary creatures are just grizzly bear cubs! Martin and Chris tell their lemur friend all about grizzlies and other animals that seem scary - but really aren''t.', '2001-03-23', 27, NULL, '2026-04-03T17:10:55Z', '2026-04-03T17:10:55Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('fbdfc9e2-0bdd-46d4-a64b-3d23ade61abc', 'a8c6182e-05e1-4b68-91a5-5126cf6c94f0', 26, 'Honor and Compromise', 'Henri befriends Abraham Nimham; Sarah and Moses watch Congress debate over the Articles of Confederation.', '2002-11-04', 30, '/z7WLOwDy9ijVhn2v5QyYeLucZ7m.jpg', '2026-04-03T17:38:28Z', '2026-04-03T17:38:28Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('fbe21d04-4e47-47fc-983b-2c677fdd7836', '5c4e51c6-e207-46ad-875c-72988eb1e13e', 19, 'Making Cents', 'The Pawn Stars consider sending a search party out for Chumlee when he takes off to look at a 1950''s Bally''s coin operated kiddie ride. Will he step up and make a rocking buy or will he drop too much change on a shaky deal? Then, Rick and Corey meet a woman hoping to sell a script from the legendary classic film The Godfather. Signed by Al Pacino, will the guys make an offer she can''t refuse or will the seller look to skim a little off the top? And later, the guys get ready to polka when a vintage Excelsior accordion chimes its way into the shop. Will the guys look to play a happy tune or will negotiations hit a sour note?', '2011-07-18', 21, NULL, '2026-04-03T16:34:16Z', '2026-04-03T16:34:16Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('fbef908e-de40-4544-83fa-3c6398cf7c40', '3fc7c152-e4f6-426a-a899-36ec454c4403', 46, 'Sounds Like Trouble', 'Max and Ord make a goo ball and the friends play catch with it, but it goes on the loose, and then rolls into a dark cave. However, Ord is still scared of the dark, so it''s up to the rest of the gang to help Ord brave his fear of the dark once more to find it.', '2000-01-19', NULL, NULL, '2026-04-03T15:26:03Z', '2026-04-03T15:26:03Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('fbf07d6a-9e83-4a47-b055-7f04d3a74363', '332249fa-796b-4f92-b7f8-421d523b0bdc', 16, 'It’s Expensive to Be She', 'Drew and Shereé attempt to broker peace between Marlo and Kenya by throwing them a joint surprise birthday party. Marlo’s nephews return to her home with new house rules. Shereé reaches out to an old friend for advice about Tyrone.', '2022-08-28', NULL, '/nywtFJrPknTr6ErW7qCXgX9JjlO.jpg', '2026-04-03T16:34:49Z', '2026-04-03T16:34:49Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('fbf29b88-d531-456b-bef7-c4aa2d271200', 'ea73e13c-6962-4804-8305-c303df65f89f', 34, 'Permission for the carnival', 'King Friday puts a damper on the carnival plans because he had not been asked for permission to hold it at the Castle.', '1969-03-27', NULL, NULL, '2026-04-03T17:35:38Z', '2026-04-03T17:35:38Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('fc052fd9-7f44-4dec-9fce-af9842460c5f', '432a6abd-dcca-44cc-82ce-fb39e33b8949', 3, 'Episode 3 (#1133)', 'Rogers and Bob Trow make some popsicle-stick crafts.', '1971-02-17', NULL, NULL, '2026-04-03T17:35:39Z', '2026-04-03T17:35:39Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('fc0922b8-8a5f-4971-a6ac-33ea8bb266d1', '03485b5e-a5b7-423e-b21e-c00e62216a35', 7, 'The Big Red Kite', 'The cubs & Papa build a big red kite.', '2004-09-10', NULL, NULL, '2026-04-03T17:40:22Z', '2026-04-03T17:40:22Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('fc0a5433-223d-4b84-b1cd-583b5c43d242', 'f593d90c-5339-42f5-9c88-5bfd48d04075', 2, 'Draw the Line', 'The flock hijack a road line-painting machine and cause chaos while creating giant works of art in the field. However, will farmer appreciate their art?', '2009-10-20', NULL, '/5wc2gFFkKvNdsj5TMiEDnX60XyJ.jpg', '2026-04-03T17:39:31Z', '2026-04-03T17:39:31Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('fc0b1d72-13ab-47d1-99cf-4437f24e3e26', '190c6e49-8849-4404-87d4-eaef943a6024', 4, 'Oakie Doke And The Birthday Cake', 'Mrs Tickle has a cold this morning, which Lizzie is not pleased about, as it''s her birthday today. To cheer up, Doke gets some help to make a cake for Lizzie''s Birthday Party, but Mrs Tickle already has a surprise for Lizzie.', '1995-10-02', 10, NULL, '2026-04-03T17:19:24Z', '2026-04-03T17:19:24Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('fc0c250f-34c5-4a5e-aeb2-2f01e5a57442', '7ccd5605-fe0b-4e00-ae7f-3e3daa252f8b', 15, 'Is This All There Is?', 'Season 5 finale. The housewives prepare to attend the season finale party. Vicki, still hurt by the San Francisco trip, vows to stay clear of drama. Gretchen and Slade color-coordinate outfits, looking (according to Vicki) as the plastic toppers of a wedding cake. Lynn''s daughters arrive at the party obviously under the influence, and Lynn excuses herself for knowing stating that the limo was big and she didn''t know what her daughter''s were up to. Tamra and Simon have a heated argument in the limo on the way to the party, with Tamra stating that she wants a divorce. The show ends with a recap of each housewife as is the tradition, and the last summary is that Tamra and Simon are divorcing.', '2010-03-04', 44, '/iaQd9a1q7ow1bq2QCwBi0MNqbhD.jpg', '2026-04-03T16:35:31Z', '2026-04-03T16:35:31Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('fc0cc68e-1f79-4fe5-ad95-dd53fd63b016', '7b8e3988-fbf3-4cfc-aeb2-782ae5a64e2d', 6, 'The Furry Four', 'Telly, Abby, and Elmo are reading Telly’s favorite comic book “The Furry Four!” They decide to pretend to be The Furry Four and quickly change into their furry, super costumes. Elmo is the Furry Flash, Abby is the Furry Tornado, and Telly is Mr. Furry! But that only makes three. They need one more member to be Furry Muscles so they can become The Furry Four. Telly, Elmo, and Abby go on a mission to find one more member! First, the superheroes run into Rosita and Zoe. They could be the The Furry Five, but Rosita and Zoe have planned to plant flowers in the garden with Maria. The mission continues. Abby, Telly, and Elmo think they found their fourth member when they come across a chicken, but he flies away in his cape. Next, they come across a squirrel who agrees to become the fourth member but he hurts his back trying to lift a mailbox while activating his super, furry power. Just then they see Chris sweeping outside Mr. Hooper’s Store. It turns out that he would love to pretend to be Furry Muscles and join the group. At last they found one more! Their first mission as The Furry Four is complete!', '2010-10-04', NULL, '/cZbu39ON06kX2BDA9CyRBklyLKD.jpg', '2026-04-03T17:36:46Z', '2026-04-03T17:36:46Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('fc11596f-445e-41d0-beaf-87cd3a2d7cbb', '1d556682-d9bb-47e1-993f-0b648a8daacd', 86, 'Episode 1271', '', '1979-03-26', NULL, NULL, '2026-04-03T17:36:33Z', '2026-04-03T17:36:33Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('fc16f6ec-7b41-466f-8f5b-4d5b8d85ad61', '8d0a597a-2adc-4192-80db-5d2e1fa55068', 8, 'Nomortland', 'That funemployed life, broh. Jerry makes a friend just as jobless as he is.', '2025-07-13', 23, '/8hVPCPuYVRTkG5DV3buLVTRhePU.jpg', '2026-04-03T15:40:44Z', '2026-04-03T15:40:44Z');
