INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('fc196028-b0d1-4c04-a545-a61028f61ff5', '740a96a0-a075-4be2-be92-a178d0939384', 10, 'Last Straw', 'Bert searches for a quiet place to nap after Ernie makes too much noise; after spending time apart, Bert and Ernie apologize to each other and learn that even though they had a fight, they can still be friends.', '2018-01-20', NULL, '/3g2gzVI0884tAWsejEYve5bpZ5H.jpg', '2026-04-03T17:36:49Z', '2026-04-03T17:36:49Z');
