INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('fc249a47-c9a0-48d5-b5d6-d0fdecf36812', '787dfa0b-c827-4dad-a82d-0548a6534d88', 24, 'Secrets Revealed', 'The Orange County vault is opened with never-before-seen footage from season ten including Shannon''s unique ladies lunch, Vicki''s night out and Heather''s teachable moment to Meghan about the finer points of Botox. In Tahiti, the women experience a wild ride, and back in Orange County, Heather proves the devil is in the details when building a mega home. Plus, secrets are revealed with more reunion footage addressing Vicki''s scandalous history with Brooks.', '2015-11-12', 44, '/Aus113dnBfFm9q48hBS9RyQ6nya.jpg', '2026-04-03T16:35:32Z', '2026-04-03T16:35:32Z');
