INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('fc465e7b-17c7-4db3-a922-c54de5197d24', 'c67a8787-4971-4961-b536-1ff01924e2a9', 9, 'Baby Kate and the Imaginary Mystery', 'When Nadine misses an appointment for tea with Vicita''s imaginary friend, Tweenie, Baby Kate and Pal grow concerned. They launch an investigation, worried that she may have been kidnapped by the Tibbles. Along the way, Francine''s cat Nemo is pulled into the investigation.', '2007-06-29', 13, NULL, '2026-04-03T17:37:58Z', '2026-04-03T17:37:58Z');
