INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('fcab3ff0-ba5f-426e-958c-fb5953c5140b', '4d0fd8a5-5200-4dfc-b96c-ae436dc8803c', 5, 'Sophie and Lou', 'LeVar takes a spirited leap into the world of dance. He gets a mambo lesson from Latin dancer, Jackie Rios, and has a hop while learning some fresh hip-hop moves. LeVar shows that there are different kinds of dancing done all over the world. Lola Falana narrates Sophie and Lou, a story of a young lady who is very shy and lives all alone. Sophie learns to dance by herself until she meets her match.', '1992-10-09', 30, NULL, '2026-04-03T17:36:18Z', '2026-04-03T17:36:18Z');
