INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('fd19e149-8558-48f5-b06d-32a372c04468', 'b054aff3-548c-4f56-b372-b1ea26613abb', 10, 'Mister Rogers Talks About GAMES', 'Rogers shows a new board game some friends based on the Neighborhood of Make-Believe. Ella Jenkins shares some childhood stories and songs. In the Neighborhood of Make-Believe, the children collectively figure out a way to stop the snowfall and permit the Make-Believe Olympic Games to begin.', '1983-02-11', NULL, NULL, '2026-04-03T17:35:43Z', '2026-04-03T17:35:43Z');
