INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('fd43cf05-5d69-4d11-83bc-faa8f1d68788', 'f9a8d8b3-d72e-437e-a9d5-7477f6d64df8', 17, 'Just Right', 'When James says Mia can’t play Goldilocks because she doesn’t look like her, Mia stands up for herself and James learns that the best part of acting out a story is that you can be anyone you want to be.', '2023-02-23', 25, '/ngWoXBXEHVk8gq8bLeucapDQAnS.jpg', '2026-04-03T17:36:51Z', '2026-04-03T17:36:51Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('fd46ff31-9d5a-4bbd-ba6b-93ef7b07818f', '698a60df-8ed4-4ca9-bcb1-ebab343dacdd', 6, 'The Watch', 'The network president doesn''t play George''s game; Jerry deals for his "broken" watch; Elaine is a hot topic in the office of her psychiatrist boyfriend.', '1992-09-30', 23, '/elXpqZ6g60TtApoJAlViE5X1Aas.jpg', '2026-04-03T16:34:10Z', '2026-04-03T16:34:10Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('fd5263b9-d9ac-4664-a89b-4aa8ceb4e5e3', '7acb58c5-320f-419d-a96f-26ad3cfe2e82', 5, 'The Art of the Illusion', 'Yennefer and Geralt step out arm in arm and dressed to kill at a lavish ball, but all is not as it seems during a night of revelry and revelations.', '2023-06-29', 51, '/ePpQeSYtWPZdyIOPCUTFQQqtsXU.jpg', '2026-04-03T15:40:45Z', '2026-04-03T15:40:45Z');
