INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('fdec3e61-6407-4f83-a433-6a1cdee3c8c5', 'e40e6b63-9f84-449f-8e88-53209b0906c8', 16, 'Telly Helps Gordon Play Golf', 'Gordon welcomes the viewer to Sesame Street. He has set up a miniature golf course, to prepare for the golf game he''ll have with Alan later on. Telly stops by, and is impressed with the setup. Gordon shows Telly how the game is played, and explains that the game isn''t always easy, because the grass often has hills, which make it harder for the ball to make it into the hole. Telly gets a sudden burst of inspiration, and rushes off.', '2007-09-18', NULL, '/1S1FyFJFmBYxeF6fWuSSClBepLT.jpg', '2026-04-03T17:36:45Z', '2026-04-03T17:36:45Z');
