INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('fe030e51-2070-4f92-839e-4d04abc1b145', '4b2a19e0-2fae-492e-bc31-f78e63d88ebc', 7, 'Death and Taxidermy', 'Get spooked out with the Pawn Stars when a 1547 edition of "The Dance of Death" haunts the shop. Will Rick take the book to his grave or will the negotiation have a bitter end? Next, things get whimsical when two sculptures from Dr. Seuss'' unorthodox taxidermy collection are brought in. Will Rick''s heart grow two sizes or will he say, "Green eggs and scram"? And later, a tear-gas baton forces its way into the shop. Will Corey think it''s a riot or will he be blinded by the price?', '2016-08-31', 21, '/6FTDmL64u2TBruleKUnTVJ7Jv8A.jpg', '2026-04-03T16:34:20Z', '2026-04-03T16:34:20Z');
