INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('fec165f5-611a-4472-abbe-babc94ad6a4f', '5c1b881f-ac58-4d72-b63f-209952d4f902', 73, 'Episode 73', 'Portable Pavement: A replica of the largest Romano-British pavement north of the Alps fills the Blue Peter studio today-all 115,052 pieces of it! Simon, Chris and Tina help to fit the giant jigsaw together and meet Bob and John Woodward, who''ve painstakingly re-created the famous Wood-Chester pavement.', '1980-05-29', NULL, NULL, '2026-04-03T17:21:54Z', '2026-04-03T17:21:54Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('fec20f28-24dd-477b-a3f1-6f52445b3c53', '23c93536-610c-41c5-ac6b-a6b243423258', 19, 'Reunion (2)', 'The reunion continues with Mia spiraling backstage after her confrontation. Keiarna and Stacey face tough criticism about their relationships with Greg and TJ, but when new revelations are made, the women are left speechless. When the ladies take her to task for her actions throughout the season, Mia finally reaches her breaking point.', '2025-02-23', 43, NULL, '2026-04-03T16:35:41Z', '2026-04-03T16:35:41Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('fec39ced-9601-438b-805d-356ace1eed24', '4fe93658-c463-4329-8e64-9d523869c2cb', 15, 'Monkey Business', 'Mount up and ride with the Pawn Stars as they take aim at a hat believed to have been worn by Western movie legend John Wayne. Will the gang decide to rustle up some quick cash or will they be forced to put up their dukes? Then, Rick and Chumlee are presented with an etching allegedly from one of the greatest artists in history - Rembrandt. Uncovered at a yard sale, will this artwork turn out to be a hidden masterpiece or a case of mistaken identity? And later, a woman hopes to sell her classic 1950s clapping chimp toy. Will the Old Man and Chumlee offer to play nice or will there be too much monkeying around?', '2010-12-06', 21, '/55oAV9yZpUOxZ6KhITPOSE9yyJ3.jpg', '2026-04-03T16:34:16Z', '2026-04-03T16:34:16Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('fec636c9-80e5-451e-b57e-1c463723a265', '15b8dcae-871d-41ca-a88e-beb4ec6530f7', 3, 'Mrs. Parette''s Necklace / Orbie and the Pumpkin Seed / Bryn''s New Bracelet', '', '2001-04-18', NULL, NULL, '2026-04-03T17:11:22Z', '2026-04-03T17:11:22Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('fece944c-7058-400b-a330-cc69c84e3780', 'ebc99729-ccb7-4d64-82c1-42708cd7ba85', 43, 'Episode 43', 'Peter helps build the course for canoeing''s most hazardous race - the White Water World Championships and tests the run.', '1981-02-05', NULL, NULL, '2026-04-03T17:21:55Z', '2026-04-03T17:21:55Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('fecfa2c4-7b56-43ba-ba07-546913aaa44b', '447296c1-2426-4e98-827a-13f4a36afcdd', 7, 'For the Birds', 'Brain is delighted when he learns that the green-tailed grebe, a bird previously believed to be extinct, has been sighted in the forests of Elwood City. He''s determined to be the first to take photographic evidence of it, but becomes worried when Mr. Ratburn starts a bird-watching club.', '2008-10-27', 13, NULL, '2026-04-03T17:37:59Z', '2026-04-03T17:37:59Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('fed3d9d3-738b-4f80-9bbd-382b38ed3555', '8dd9292d-bcb1-4864-8297-4f6c3313f8c6', 13, 'You Are Cordially Not Invited', 'Tamra reveals more surprising information about Ryan, leaving Jenn to question her friendship with Tamra once again; Emily and Heather discuss body image; Shannon hosts a tea party to reveal she''s taking almost everyone on a trip to London.', '2024-10-03', NULL, '/mibVR6N1IYnndEhXXx1DoxCxUSR.jpg', '2026-04-03T16:35:35Z', '2026-04-03T16:35:35Z');
