INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('fee29b1b-e98b-48f6-9cf5-8c39e676fb89', 'f12380a9-93e5-47bb-9e2f-cf1eed11eee4', 5, 'Kissing Another Man''s Wife', 'With the changing family dynamics, the Browns celebrate the holidays with new traditions.', '2025-10-26', NULL, '/aW7p26dS3G9YlyvnZsPy9s9EOV1.jpg', '2026-04-03T16:34:33Z', '2026-04-03T16:34:33Z');
