INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('feee4502-41a8-4407-a47f-03927d92e304', '4da606e7-9d23-4682-8bd5-f535e1da706f', 19, 'Franklin Says Sorry', 'Bear had a surprise for their tree fort and Franklin spoiled it by telling Fox.  Bear was really upset with Franklin and wouldn''t speak to him for day.  Franklin was also upset about what happened and apologized.  Fox and Beaver also confessed they were to blame as well for they had insisted Franklin tell them and that it wasn''t all his fault.', '1998-11-09', 12, NULL, '2026-04-03T17:40:15Z', '2026-04-03T17:40:15Z');
