INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('fef2c6e8-4f03-49ad-b848-f2d38f9b32d1', '487fdbcd-ec5a-454e-8268-b50566eb8546', 12, 'Serving the Tee', 'Lesa launches her new skincare line, but it leaves some of the ladies feeling uneasy; Taleen hosts a golf getaway with the ladies and their husbands; Lesa confronts Caroline Brooks about comments she made; Taleen adds fuel to the fire.', '2024-08-27', 43, '/aRY5zXTLvulitJFWDOicSO3ssjs.jpg', '2026-04-03T16:35:07Z', '2026-04-03T16:35:07Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('fef9f39d-ba83-4ea1-afd6-ceda312969f1', '36e5c604-fea9-4bcf-8343-71bfaf60ecd2', 26, 'The Tugboat Pledge', 'The Dispatcher has assigned Emily to lead the tugboat parade. Hank suggests to her that she should recite ''The Tugboat Pledge'' as well, except he has tricked Emily and there is no such thing!', NULL, NULL, NULL, '2026-04-03T17:10:11Z', '2026-04-03T17:10:11Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('ff023f2c-bf80-4aa7-988a-7fb19d5dea7c', '33825a15-37dc-4ff9-82bd-cc720498149a', 3, 'Donde Esta Margarita', 'D’Andra blows off a big business meeting with Travis because of a “hair emergency.” LeeAnne gets creative in order to afford her uber expensive couture wedding gown. The women all travel to Careyes, Mexico for some fun in the sun at Kary’s resort-like villa but things quickly take a turn when tensions rise between Kary and LeeAnne.', '2019-09-18', NULL, '/50RFIax0sZ1WkxFsAoVKDV5svA4.jpg', '2026-04-03T16:35:04Z', '2026-04-03T16:35:04Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('ff03a718-cac3-4cc5-8f88-7e62cf93c186', '6ef86c27-33e7-47e5-a053-483059dfd16d', 66, 'Episode 66', 'Operation Pipeline Auction: "Blue Peter" viewers created a record with the auction for the Operation Pipeline Appeal held at Phillips last week. The collectors items, from the stamps and coins donated to provide pure piped water systems and health care services for the people of Java, formed the biggest "Blue Peter" sale ever held!

See the lots go under the hammer wielded by top auctioneer Christopher Hawkings - aided by porters-for-the-day Simon, Sarah and Peter. And discover how much the biggest lot raises - the unique Merlin sports car complete with the "Blue Peter" ship on its doors!', '1982-05-10', NULL, NULL, '2026-04-03T17:21:55Z', '2026-04-03T17:21:55Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('ff03f76b-af12-4cdf-b47d-9a4434235db8', '8c3cfac1-d882-4904-b38c-d1981628d00e', 26, 'Episode 26', 'Don''t miss today''s stop-press news about the Medi-Bike Appeal and see the latest figures on the Totaliser.', '1978-12-07', NULL, NULL, '2026-04-03T17:21:54Z', '2026-04-03T17:21:54Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('ff04d41c-b3b4-4e6f-9ab3-b993d2099ccf', '495d4222-b33a-46fa-8351-3265798e558b', 3, 'A Good Tip for Ghosts', 'Pete is being made to feel uncomfortable by Gribbs, Jr. and his gang - Tiger and Rabbit. However in a ""duty"" of collecting a skull, Pete gets his own back on the three.', '1990-04-20', 24, '/3hKvRERrTJpeZuAUkDQtd7IOONq.jpg', '2026-04-03T17:40:40Z', '2026-04-03T17:40:40Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('ff0ec303-0ddb-4de6-85eb-152822b8b909', 'd46f25ad-9612-4516-91df-d1ace11fec38', 5, 'The Next Step Takeover and Wildlife Adventure', 'The stars of The Next Step take on a dance battle in the studio and surprise a class of young fans for the ultimate dance lesson on how to attempt some moves at home. Meanwhile, Abby sets off on a sea kayaking adventure to spot some incredible wildlife!', '2025-10-03', 25, NULL, '2026-04-03T17:22:12Z', '2026-04-03T17:22:12Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('ff10ea9b-3db1-40bf-8bd2-0cc4acb91364', '4d2cac0f-38fd-438b-8afa-acf43952e535', 316, 'Episode 316', 'with Christopher Trace and Valerie Singleton.', '1964-12-03', NULL, NULL, '2026-04-03T17:21:47Z', '2026-04-03T17:21:47Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('ff113a21-d53e-4199-b69c-52e6d6112533', '21745b85-d269-42fa-b4dd-701b2da5c085', 39, 'Episode 39', 'Paco Pena and his Flamenco Puro Paco, with dancers Margarita and Faiquillo De Cordoba, teach Lesley the basic flamenco steps to rhythm provided by John and Pete with Barrilito, El Sordera and Basilisco.', '1974-01-24', NULL, NULL, '2026-04-03T17:21:51Z', '2026-04-03T17:21:51Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('ff129bf5-15ed-40e5-9a85-c262110bac31', 'f4c40307-9b5e-4263-a4e0-dfa138131e7f', 116, 'Elmo''s World: Head to Toe with Elmo', 'One, two, buckle your shoe...Elmo gets dressed, and you can, too! Come along and learn all about jackets, hats, and shoes with Elmo. With a dancing shade, a mischievous drawer, a frisky television and a playful computer, Elmo''s World is the perfect place for preschoolers to learn all about the world around them. Elmo and his friends take a trip to the shoe store, learn how to make a magical hat, and chat with a fuzzy pink jacket. Getting dressed and learning are fun in Elmo''s World!', '2003-01-14', NULL, NULL, '2026-04-03T17:36:27Z', '2026-04-03T17:36:27Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('ff19eb0f-03e9-40fb-bcc5-d392cf5ab210', '9193e795-da7c-40ec-b68f-f63aa7d5174f', 73, 'Histories & Lore: The Sack of King''s Landing (Maester Luwin)', 'Maester Luwin details the downfall of the Mad King and the death of the royal family, as well as how it impacted those who won the war.', '2012-03-05', 3, '/8j5GrhHn2wbOm60xyIM7qRL4cJu.jpg', '2026-04-03T15:40:35Z', '2026-04-03T15:40:35Z');
