INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('ff22c565-c273-406c-9834-085d7da94f2f', '119c16d5-1047-45ec-8242-c72a8eed423b', 20, 'Francine Frensky, Superstar', 'Francine has always gotten the worst roles in school plays, so everyone in the Ratburn class asks Mr. Ratburn to give her a good part in the next one. The play is about Thomas Edison, and Francine is given the role of Edison himself. She takes her role very seriously, to the point where she starts to trying to run everything her way and insults her friends. After the hurt and the anger, they set out to show her that she can''t just forget their needs', '1996-10-18', 13, NULL, '2026-04-03T17:37:55Z', '2026-04-03T17:37:55Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('ff24c296-7045-4472-8edd-9d6d9eb29070', 'b598da2e-89fd-4e98-8d0d-4bce6bbd4ac9', 1, 'Raquel Welch', 'Fozzie heard that Roy Clark was going to bring Country to the show and sent all of the stagehands out to the country. Matters are complicated even more when a fire breaks out backstage and Fozzie tries to keep it a secret from Kermit.', '1978-11-17', 26, '/xx5Qr4Ci9LiGxLoG7ikXlGbgBGi.jpg', '2026-04-03T17:35:24Z', '2026-04-03T17:35:24Z');
