INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('ff366c9c-02ab-430f-be69-745061a90de2', '3087a3ed-e94e-4276-9d02-a78183dea1d3', 12, 'Battle of the Booty', 'Phaedra and Kenya feud after a fitness-video deal sours and Kenya decides to produce her own video. Meanwhile, NeNe returns to Atlanta; and Cynthia casts a charity runway event, culminating in a wicked showdown between Phaedra and Kenya.', '2013-01-20', 43, NULL, '2026-04-03T16:34:46Z', '2026-04-03T16:34:46Z');
