INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('ff442004-720f-4840-ac06-6cb4804c9b98', 'bcab920a-51a5-4cbb-aa59-41578a0eb005', 17, 'From Dogs to Diamonds', 'Still in Hong Kong, Lisa Rinna defends her scandalous accusations about Dorit. The ladies’ hearts are warmed when they visit the SPCA to see the dogs that Lisa Vanderpump has helped rescue. Later, back in Beverly Hills, Erika shoots her scenes for The Young &amp; the Restless before everybody heads to Villa Rosa for a spectacular Diamonds and Rosé party.', '2017-03-28', 43, '/1xWYLHnwoTjYROlI8D4cNmiSOvV.jpg', '2026-04-03T16:34:56Z', '2026-04-03T16:34:56Z');
