INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('ff6c69df-a419-4ed4-b07c-2497fd482e15', '42991e93-ef88-413f-b7e3-0333f9e7ab36', 3, 'Spiders', '', '1994-10-06', NULL, NULL, '2026-04-03T17:19:30Z', '2026-04-03T17:19:30Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('ff73cba9-b4a2-4afe-8380-09f0fcf73965', 'e38e9d87-1432-4a1a-a7d0-64a559bf7570', 6, 'Who Shall Wear The Crown', 'After the incident crossing the river, Badger is spotted still alive but caught in some reeds. Toad, Hare and weasel swim over to help Badger get untangled before they all swim back to land. Fox is nowhere to be found so Kestrel files downstream to see if she can find him. She sees him lying on the log heading under a bridge but as the log appears on the other side Fox is no longer there. Badger is assigned as the new leader and to add to matters Toad forgets which way to go. Owl suggests this is because his homing instincts have come into play. Hare and Vole inform Badger that Mrs. Fieldmouse has given birth to her young. Badger suggests that the animals should stop to rest for the time being.', '1993-02-07', 24, '/qHNe6yjB3bZECOlAjVB4EclW3S6.jpg', '2026-04-03T17:18:49Z', '2026-04-03T17:18:49Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('ff7873bc-5dfa-4031-b75b-c96ce9a4ce6d', '4d2cac0f-38fd-438b-8afa-acf43952e535', 54, 'Episode 54', 'A magazine programme for younger viewers.  Introduced by Christopher Trace and Leila Williams.', '1959-10-30', NULL, NULL, '2026-04-03T17:21:47Z', '2026-04-03T17:21:47Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('ff787e6b-b0e5-4d96-8e81-7b214e3146d6', 'ecb64ef3-4f80-45a7-b4a9-c04434b02e35', 17, 'Magic Bus', 'Head back in time with the Pawn Stars when Rick checks out a fully restored 1960s VW Samba. Featuring a rare 23-window design, will this iconic bus cause him to get bit by the bug? Then, Chum gets scrambled when a piece of egg art from Sergio Bustamante rolls into the shop. Will he be able to cook up an offer or will this deal not go over easy? And later, when Rick announces a bonus for the employee of the month, Chum tries to prove his worth. Will he show the guys he''s top dog, or end up at the bottom of the barrel?', '2014-02-27', 21, '/5o3dQPtd57zzZosgFg92AKHug9y.jpg', '2026-04-03T16:34:19Z', '2026-04-03T16:34:19Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('ff7bd197-7af7-49e6-bbb7-4d13bdd0cf00', '3415030f-f54d-42b9-a290-aaa05e246d86', 8, 'Another Catfishing', 'Meri meets another woman catfished by Sam, and her new details lead to a reckoning with Kody; Mariah makes a huge announcement.', '2017-01-01', NULL, NULL, '2026-04-03T16:34:30Z', '2026-04-03T16:34:30Z');
