INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('ff89b369-c8df-4b28-b3b0-d4265214de17', '1d39506b-06b8-4f93-9136-0208069bd7e4', 12, 'Sun, Sand and Psychosis', 'A Virgin Island getaway turns nasty when an argument breaks out between Kelly and Bethenny, ruining a peaceful breakfast and precipitating a meltdown for Kelly. Later, Bethenny cooks up dinner, but it''s hard to swallow when there are yet more blowups. Cut to the Big Apple, where Jill mulls over going to the Virgin Islands to see all the drama in person.', '2010-05-20', 43, '/8cS3SIvwR1zR7Pg6MYNESVw4YbK.jpg', '2026-04-03T16:35:22Z', '2026-04-03T16:35:22Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('ff8c4f17-9180-4554-9930-5558fe37badf', 'c4d795ae-6afa-47d6-9819-4dd057030a3c', 12, 'The Peaches of Tokyo', 'While in Tokyo to celebrate her bachelorette party, Eva receives devastating news that threatens to derail the trip; Porsha shares a secret with the rest of the ladies; NeNe and Tanya get into a heated confrontation that leaves everyone confused.', '2019-01-19', 43, NULL, '2026-04-03T16:34:48Z', '2026-04-03T16:34:48Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('ff90349d-0db4-4221-85e5-d0bfc3409f81', '8e5ed8a4-08e5-4006-9f36-c68c91ddfee4', 25, 'Episode 774', '', NULL, NULL, NULL, '2026-04-03T17:36:40Z', '2026-04-03T17:36:40Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('ff914f06-7e5c-4ce3-976e-5df84b5c6464', 'bf874be3-7e2f-4a0e-b205-c76ac1ad69fc', 30, 'Inside Looks (on The Subway)', 'Inside look from the season 3 episode "The Subway."', NULL, 3, NULL, '2026-04-03T16:34:08Z', '2026-04-03T16:34:08Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('ff921422-abd4-4da3-ad50-5095e226327f', 'a8f3a681-7abc-41e0-9988-9b8804d74611', 17, 'Confronting Failure', 'With the Sister Wives living separately for over a year now, the Brown family structure is falling apart. After stressing out over finances, the wives try hard to start a web business, and Christine makes another attempt to pass her real estate exam.', '2012-12-16', NULL, NULL, '2026-04-03T16:34:28Z', '2026-04-03T16:34:28Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('ff97b672-7455-4a68-810a-aa7054ed3b21', '319bd5d6-ff58-426f-b9da-a0bb2cb87b02', 3, 'Genes', 'The color of your eyes, the shape of your nose, and the straightness (or curliness) of your hair depend on your genes. Not jeans the pants, but genes, the long strands of chemicals in your cells. Genes are like a blueprint for your body, and your cells follow the blueprint to build you. All living things have genes in their cells. You get your genes from your parents – half from your mom and half from your dad. Your parents got their genes from their parents, your grandparents. Living things pass down their genes from generation to generation. Genes from a mother’s egg cell mix with genes from a father’s sperm cell to make a complete set of plans for a baby. Baby humans, baby dogs, and baby plants all grow up to look like their parents because of genes.', '1997-10-17', 26, '/b49yJmD2UqvR3O33PGvxKEXt8yM.jpg', '2026-04-03T17:37:22Z', '2026-04-03T17:37:22Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('ff9ea39c-9a77-41be-ac39-8d11ab77751f', '9193e795-da7c-40ec-b68f-f63aa7d5174f', 122, 'Histories & Lore: Robert''s Rebellion (Oberyn Martell)', 'Oberyn Martell reveals the Dornish perspective of Robert''s Rebellion - or the War of the Usurper as they call it - including the murder of his sister, Elia Martell, during the sack of King''s Landing.', '2015-02-17', 5, '/y8AdtzUGoctsnq4fQtTQrvdKOsx.jpg', '2026-04-03T15:40:35Z', '2026-04-03T15:40:35Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('ffa91c6b-c27f-4727-990a-a14faf33ee4e', '4861ce46-9045-43c7-963f-27b4ea539804', 124, 'Episode 254', '', '1971-04-29', NULL, NULL, '2026-04-03T17:36:29Z', '2026-04-03T17:36:29Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('ffaf9d62-f4bf-4ae7-b1ff-409e0fd17630', '119c16d5-1047-45ec-8242-c72a8eed423b', 5, 'D.W. All Wet', 'Whew, boy is it HOT today. The Reads decide to head to the beach in order to cool off, but D.W. refuses to go along (she thinks there is an octopus in the water).', '1996-10-09', 13, '/jC6IQoq2nwqZUDzR4PLOwmrHTvp.jpg', '2026-04-03T17:37:55Z', '2026-04-03T17:37:55Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('ffb09e53-c0f4-4367-86da-4c7ec28bad0a', '05044f49-5f9c-4e7f-a74d-b2ff19475d0e', 10, 'The Day of Jacqueline', 'Dina, Melissa and the twins travel to Florida; Dina has a secret about the twins that threatens to ruin the trip; Amber awaits news about the possible recurrence of her cancer; Jacqueline returns and confronts Teresa about her past.', '2014-09-21', 43, '/hfnHr09eoO46cBR0pSTjEcXoXtz.jpg', '2026-04-03T16:35:16Z', '2026-04-03T16:35:16Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('ffb27cc4-644a-479d-8ab4-b530ca2822af', '6e0be2a3-a234-453b-abb7-0ba535a93601', 3, 'Mr. Fix-It Franklin', 'Franklin gets to help out around the house on small fix-it jobs. He then tries to apply it to helping his friends, which seem to work at first, until he finds out that his fixes caused bigger messes. However, his friends forgive him and his parents tell him that learning from one''s mistakes is experience, too. And with his father''s help, he does it again the right way.', '2000-05-15', 12, NULL, '2026-04-03T17:40:15Z', '2026-04-03T17:40:15Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('ffb313ca-621c-4fc6-9e84-c0be416aee5a', '225b0f03-984b-47f3-a1a3-d3e92175e39d', 56, 'Episode 56', 'with Christopher Trace, Valerie Singleton and John Noakes.', '1967-04-13', NULL, NULL, '2026-04-03T17:21:48Z', '2026-04-03T17:21:48Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('ffb615a3-dfb8-4275-a32f-95a848f304cb', '5b72e664-d3d7-435d-bdc3-a23d29d1178e', 1, 'Ruff', 'The toys meet a new friend; a bouncy dog called Ruff. When they discover that he has never had a birthday party they quickly set about putting things right. They decide to hold an all-week birthday to celebrate all the birthdays Ruff has missed. Each day brings different birthday fun; parties, presents, games and birthday cakes. And on the seventh birthday they give Ruff the present he has always wanted.', '1994-09-06', 10, NULL, '2026-04-03T17:18:55Z', '2026-04-03T17:18:55Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('ffb73660-fe61-46b7-8df4-0a2da3d25d1d', 'c9d2b3fb-7845-4f3c-9847-ce1f7717257a', 14, 'Pawning Picasso', 'Corey snipes an early 1800s prototype rifle made by the man who invented the Baker Rifle; one of Marlon Brando''s most prized possessions shows up; an original work made by the one and only Pablo Picasso shapes up to be a great addition to the shop.', '2019-06-24', 42, NULL, '2026-04-03T16:34:21Z', '2026-04-03T16:34:21Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('ffbf44b3-e180-4887-a3bf-2f9ee825f2ae', '0fa92002-82ae-4609-85e3-3982baa99ae1', 9, 'Postman Pat and the Runaway Train', 'The reverend Timms inadvertently starts the Greendale Rocket. Pat and PC Selby give chase in the patrol car, while Ajay and Mr. Pringle are in hot pursuit on the railway pump-truck...', '2005-03-08', 15, '/3cWYD7FEyMFH3B0g42ghx8jr1D8.jpg', '2026-04-03T17:14:30Z', '2026-04-03T17:14:30Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('ffc3d439-9827-459b-ac32-d33c4443767b', '3430d881-14a2-497d-9cf4-351b78b6aa6a', 11, 'Postman Pat Takes Flight', 'The Major Forbes prepares for a film show about his balloon flights across the world. When Pat arrives at Garner Hall, the Major asks Pat to climb onto the roof, untangle the string and cast him off into the sky. Unfortunately it sets off with Pat still clinging to the basket!', '1997-09-01', 15, '/ewJBnejZ2QM1flnkPvOH4GM0TdT.jpg', '2026-04-03T17:14:30Z', '2026-04-03T17:14:30Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('ffc8d09a-f819-48ff-8537-890b52348759', '9f448cb8-07f8-4040-840b-c8690371ec41', 15, 'The Susie', 'Kramer becomes the spokesman for a woman George wants to avoid; Jerry''s bookie welches; a co-worker mistakes Elaine for someone else, who''s reported as a problem worker.', '1997-02-13', 22, '/5FykP2CXAnuoai7i0cfhUdkIb41.jpg', '2026-04-03T16:34:12Z', '2026-04-03T16:34:12Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('ffc936dd-751e-4830-bf94-fa4356514790', '2aebfad4-3145-4bc1-9def-5f1d5bdfcfc8', 7, 'The Cafe', 'While Jerry tries to help a cafe owner, Elaine tries to help George with an IQ test, and Kramer...well, nobody can help Kramer.', '1991-11-06', 23, '/w2ITewmpbxPPjkM1CkE4IiLI9IV.jpg', '2026-04-03T16:34:10Z', '2026-04-03T16:34:10Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('ffc9a01a-3d4c-4934-9b44-063486cdabfb', '4f18ac4c-8757-456c-a49a-224f00e6a9f7', 15, 'Slimey Adopts a Pet Bug', 'Gina meets up with Oscar, who’s trying to start up the Sloppy Jalopy, and Slimey, who eagerly bounces up and down in his booster seat. She learns that Oscar is taking Slimey to get his own pet bug, which Gina finds funny. They drive off, leaving Gina in the car exhaust.', '2008-10-07', NULL, '/p72AhIc5K5xfkhGC5JwrwjWPwrr.jpg', '2026-04-03T17:36:45Z', '2026-04-03T17:36:45Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('ffcd974b-f62d-4cc0-bd3c-c3abc46da0c0', '831e3a6b-c1a7-48b7-a5ac-b18ed67beb10', 4, 'Desperately Seeking Marriage', 'Katie renovates the house behind Andrew''s back; Charrisse tells her friends the shocking truth about her 18-year marriage; Karen learns how to fly a plane; Ashley gossips online, incurring the wrath of her close-knit community.', '2016-02-14', 42, '/ar7FULl7l41p1mRz1Uu2Aq01wqe.jpg', '2026-04-03T16:35:38Z', '2026-04-03T16:35:38Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('ffce7200-9335-4ee1-9d8e-87d11b48d0e5', '58adb9ab-3f1b-4a11-87b6-9b0b2dbb6aaf', 22, 'Mini Miles', 'Schedule a playdate with the Pawn Stars after Rick stumbles upon what could be one of the first Barbie dolls ever made while visiting his good friend, Marie Osmond backstage at her long running Vegas show. Will it turn out to be the real deal or is the seller just playing make believe? Then, Corey can''t believe how well Chumlee can drive a tiny amusement park car - he also can''t believe how much the seller wants for it. Later on, a "Citizen Kane" production still signed by Orson Welles comes into the shop and it''s anyone''s guess if a rare $10,000 certificate from 1900 meets the shop''s gold standard.', '2017-07-24', 21, '/sljZhhTkV6PmcrF6NyW1cTcdr3G.jpg', '2026-04-03T16:34:21Z', '2026-04-03T16:34:21Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('ffcf643b-3b6c-4e1c-8909-26a0815e7801', '5a4e38a1-8e54-4974-8097-d7a7b48630a2', 13, 'Episode 13', 'with Valerie Singleton, John Noakes, Peter Purves', '1970-10-30', NULL, NULL, '2026-04-03T17:21:50Z', '2026-04-03T17:21:50Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('ffcfc781-a67d-4bb0-9e43-4b35e2d575c0', '1c9ea7d3-e254-4e7b-8a9f-33eea9c6c341', 6, 'Where There''s a Wig, There''s a Way', 'Kandi and Todd continue to deal with their parenting differences. Kenya puts all her energy into her business. NeNe invites Kandi to lunch and reveals disturbing information about Cynthia. Marlo throws a party to launch her new wig line.', '2019-12-08', 43, NULL, '2026-04-03T16:34:49Z', '2026-04-03T16:34:49Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('ffcfe8c3-e1c4-496e-84dc-4fcc54b632af', 'd7ff9136-a833-4c43-a37c-a985a34f45a9', 16, 'One on One: Part 2', 'As the sit-downs continue, the Browns reveal difficulties that go back decades, including a short time where Janelle left the family. The family discusses Kody''s meltdown, and Robyn shares anger over the lack of support from her sister wives.', '2023-12-03', NULL, '/3kMqYnBJ1KWAtl4Q4V1qCg9SSED.jpg', '2026-04-03T16:34:32Z', '2026-04-03T16:34:32Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('ffd32888-1d42-4fd1-a619-6b0dc94661f4', '4d2cac0f-38fd-438b-8afa-acf43952e535', 321, 'Episode 321', 'with Christopher Trace, Valerie Singleton, Petra and Jason. The Christmas of the White Rhinoceros, written and directed by Dorothea Brooking and The Story of the Crib.', '1964-12-21', NULL, NULL, '2026-04-03T17:21:47Z', '2026-04-03T17:21:47Z');
