INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('ffddd738-c5a4-4add-b920-a8325dc27db9', 'cc472916-0b8b-4498-8a9a-c5c1e7e66097', 6, 'She''s Gone Too Far', 'Brandi spills a secret about Adrienne''s personal life, leading to a massive confrontation.', '2012-12-10', 43, '/ipS5T3Ogy03Fp256NupM7a5nyq.jpg', '2026-04-03T16:34:55Z', '2026-04-03T16:34:55Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('ffe5bc51-bfab-40f2-9527-063affbd7331', '50ee8f6c-645c-4d48-bab9-53b9f8f7ff2f', 10, 'Big Bad Wolf Huffs and Puffs Slimey', 'Oscar''s getting ready to take Slimey to the mud hole, but what''s this? It''s the Three Little Pigs being chased by the Big Bad Wolf! The wolf huffs and puffs at Slimey too, who goes flying through the air and lands in Snuffy''s lunch.', '2011-10-18', NULL, '/npdNaj60z3Etdpdagxw9WL1wbUQ.jpg', '2026-04-03T17:36:46Z', '2026-04-03T17:36:46Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('ffe88253-0920-42db-9a6f-6a5befd16fd4', '4861ce46-9045-43c7-963f-27b4ea539804', 81, 'Episode 211', '', '1971-03-01', NULL, NULL, '2026-04-03T17:36:28Z', '2026-04-03T17:36:28Z');
