INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('fff1d819-f1a1-469d-b755-d2bb0433de2c', 'e2aa3158-68e5-494f-951a-498ca0518dbb', 5, 'Let''s Spray', 'Graffitti is appearing around the farm, and The Farmer has given Bitzer the job of removing the painted artwork.', '2012-12-08', 7, '/qYN3ipxo9Ucv5yiRyvK375S9Fjk.jpg', '2026-04-03T17:39:32Z', '2026-04-03T17:39:32Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('fff3f32c-e8bd-4a6c-939d-5c4df0d146ef', '95ca8b6f-ccbc-431a-9d95-9b23367bbfed', 15, 'The Dinner Party From Hell: Part Two', 'Kyle assesses the progress at Sutton’s new home, while Dorit hopes her new business venture is the right fit for her family. Crystal invites Erika, Garcelle and Kathy over for a dinner where duck is served, but beef is on the menu. Kathy puts her staff to work arranging an evening to remember, but when Erika and Sutton face off, it quickly becomes a night the ladies would rather forget.', '2021-09-01', 43, '/jTor70cCh0xdFuMuMlsc9NWE8un.jpg', '2026-04-03T16:34:58Z', '2026-04-03T16:34:58Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('fff452e0-e96d-4e49-b2c8-1c5f8cb9995f', 'c13cac45-2554-4775-bb86-c6aa65c1ca2e', 12, 'Graham''s Revenge', '', NULL, 44, NULL, '2026-04-03T17:39:10Z', '2026-04-03T17:39:10Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('fff5b920-d2b7-4a3a-a78e-6d52cb8d0b50', '050d8ae1-6cc1-4018-933d-b3c3d13de856', 50, 'Episode 50', '', '1985-03-04', NULL, NULL, '2026-04-03T17:21:57Z', '2026-04-03T17:21:57Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('fff6e522-87c7-45a7-b0bb-48e1ca7c90f0', '20d7138e-eea8-46a8-8ada-2b0f0ee1f674', 65, 'Episode 65', 'Hard, Very Severe: That''s the grading of Wintaur''s Leap - an escarpment of sheer limestone with a terrifying 210 ft drop that can defeat even the most experienced climber. In the expert hands of Stuart Thompson and John James, Peter had a go, and no one was more surprised than him to find their particular route had never been climbed successfully before!

Join Peter at the summit and think of a name for his amazing climb - your suggestion could be the one registered in the official log.', '1983-05-05', NULL, NULL, '2026-04-03T17:21:56Z', '2026-04-03T17:21:56Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('fff771a5-8efb-429f-bf9f-2f71d5536fb8', '8b35accc-64c5-42b9-bd91-7dbc7f28ce38', 7, 'Lost Cat', 'Saturdays are busy enough for Bella, without having to deal with chip pan fires and lost cats.', '1987-12-08', 10, '/fmeAUZv8XZG1LTLO1RfCIAFvrcG.jpg', '2026-04-03T17:14:37Z', '2026-04-03T17:14:37Z');
INSERT OR REPLACE INTO tv_episodes (id, tv_season_id, episode_number, title, overview, air_date, runtime, still_key, created_at, updated_at) VALUES ('fff891bf-8b9d-4ddb-8e52-2a6310cb1fef', 'e48599f8-66ff-4c0f-9274-65b9ae1cda9e', 26, 'Episode 26', 'Blue Peter film cameras bring a stop press report from the Appeal Depot to show how the Lifeline Lebanon stamps and postcards are being sorted.', '1976-12-09', NULL, NULL, '2026-04-03T17:21:53Z', '2026-04-03T17:21:53Z');
